$script:SelfUpdateVerifyTimeout = 6

New-Item -ItemType Directory -Path $script:AppDataRoot -Force | Out-Null
New-Item -ItemType Directory -Path $script:ShotFolder -Force | Out-Null
New-Item -ItemType Directory -Path $script:BinFolder -Force | Out-Null

# ----------------------------------------------------------------------------
# UPDATE-STATUS VERARBEITEN (Version 3.7)
# Der Starter schreibt neben das Skript eine Datei update-status.json mit den
# Details (Version, Neuigkeiten, Fehlermeldung). Der Status-Parameter
# entscheidet, was die Oberflaeche zeigt.
# ----------------------------------------------------------------------------
$script:AppFolder = Split-Path -Parent $script:ScriptPath
if ([string]::IsNullOrWhiteSpace($script:AppFolder)) { $script:AppFolder = $script:AppDataRoot }
$script:UpdateDetails = $null
try {
    $updateStatusFile = Join-Path $script:AppFolder 'update-status.json'
    if (Test-Path -LiteralPath $updateStatusFile) {
        $script:UpdateDetails = (Get-Content -LiteralPath $updateStatusFile -Raw -Encoding UTF8 | ConvertFrom-Json)
    }
} catch { $script:UpdateDetails = $null }

function Get-UpdateStatusText {
    # Klarer deutscher Text zum Status-Parameter (fuer Hinweisfenster/Einstellungen)
    switch ($UpdateStatus) {
        'update-erfolgreich'   { return 'Update installiert' }
        'erster-start'         { return 'Erster Start' }
        'kein-update'          { return 'Kein neues Update' }
        'keine-verbindung'     { return 'Keine Verbindung zum Update-Server' }
        'update-fehler'        { return 'Update konnte nicht installiert werden' }
        'update-suche-fehler'  { return 'Update-Suche fehlgeschlagen' }
        default                { return '' }
    }
}

function Test-UpdateError {
    # Wahr, wenn der Starter einen Fehler melden wollte (rote "1" am Zahnrad)
    return (@('keine-verbindung', 'update-fehler', 'update-suche-fehler') -contains $UpdateStatus)
}

# ----------------------------------------------------------------------------
# SELBST-AKTUALISIERUNG BEIM AUTOSTART (Version 3.9.8)
# ----------------------------------------------------------------------------
# Wird die Bridge ueber den Windows-Autostart gestartet, laeuft der Starter
# (Arena Roblox Bridge.cmd) nicht mit - das Programm bekommt dann KEINEN
# -UpdateStatus. Genau dann uebernimmt es die Update-Suche selbst:
#   1) version.json von raw.githubusercontent.com laden (Branch-Kette)
#   2) Ist die Version dort neuer, ArenaBridge.ps1 herunterladen
#   3) Datei sauber austauschen (erst .new schreiben, dann umbenennen)
#   4) Alte Instanzen beenden und neu starten (-UpdateStatus update-erfolgreich)
# WICHTIG: Kein Netz, langsames Netz, GitHub down, kaputtes JSON - nichts
# davon darf den Start blockieren. Jeder Schritt hat ein kurzes Zeitlimit und
# faellt im Zweifel stillschweigend auf die lokal vorhandene Fassung zurueck.
# ----------------------------------------------------------------------------

function Get-LocalBridgeVersion {
    # Liest die Version aus dem Changelog-Kopf der eigenen Datei.
    try {
        if ($script:ScriptPath -and (Test-Path -LiteralPath $script:ScriptPath)) {
            $head = Get-Content -LiteralPath $script:ScriptPath -TotalCount 5 -Encoding UTF8
            foreach ($line in $head) {
                $m = [regex]::Match([string]$line, 'Version\s+([0-9]+(?:\.[0-9]+)+)')
                if ($m.Success) { return $m.Groups[1].Value }
            }
        }
    } catch {}
    return [string]$script:Shared.DocsVersion
}

function Get-UpdateBranchChain {
    # Reihenfolge: konfigurierter Branch zuerst, dann main, dann master.
    $chain = New-Object System.Collections.Generic.List[string]
    $configured = ''
    try {
        # Optional: update-config.json neben dem Skript ({ "branch": "..." })
        $cfgFile = Join-Path $script:AppFolder 'update-config.json'
        if (Test-Path -LiteralPath $cfgFile) {
            $cfg = Get-Content -LiteralPath $cfgFile -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($cfg -and $cfg.branch) { $configured = [string]$cfg.branch }
        }
    } catch {}
    if ([string]::IsNullOrWhiteSpace($configured)) { $configured = [string]$script:RepoBranch }
    if (-not [string]::IsNullOrWhiteSpace($configured)) { [void]$chain.Add($configured.Trim()) }
    foreach ($fallback in $script:RepoBranchFallbacks) {
        if ($chain -notcontains $fallback) { [void]$chain.Add($fallback) }
    }
    # Version 7.2.4: NIE @() um eine Generic.List - Windows PowerShell 5.1
    # wirft dafuer den Binderfehler "Die Argumenttypen stimmen nicht
    # ueberein." (Hausregel aus 7.1.1, seit 7.2.4 durch ein Parse-Gate
    # gesichert). .ToArray() ergibt auch leer ein Array, nie $null.
    return ,$chain.ToArray()
}

function Compare-BridgeVersion {
    # Gibt 1 zurueck, wenn $Remote neuer ist als $Local (sonst 0 / -1).
    param([string]$Remote, [string]$Local)
    try {
        $r = [version]([string]$Remote).Trim()
        $l = [version]([string]$Local).Trim()
        if ($r -gt $l) { return 1 }
        if ($r -lt $l) { return -1 }
        return 0
    } catch { return 0 }
}

function Get-RawGitHubText {
    # 6.0.2: -TimeoutSec erlaubt dem Sicherheits-Check nach einem Starter-
    # Start ein knapperes Zeitlimit als der normale Autostart-Update-Pfad
    # (12 s) - sonst wuerde ein totes Netz den Programmstart spuerbar
    # verzoegern.
    param([string]$Branch, [string]$File, [int]$TimeoutSec = 0)
    if ($TimeoutSec -le 0) { $TimeoutSec = [int]$script:SelfUpdateTimeout }
    $url = "https://raw.githubusercontent.com/$($script:RepoOwner)/$($script:RepoName)/$Branch/$File"
    $text = $null
    try {
        $response = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec $TimeoutSec -ErrorAction Stop
        if ([int]$response.StatusCode -eq 200) {
            $content = $response.Content
            if ($content -is [byte[]]) {
                # Binaer-Rueckgabe: selbst als UTF-8 dekodieren.
                $text = [System.Text.Encoding]::UTF8.GetString($content)
            } else {
                # FIX 3.9.8: raw.githubusercontent.com liefert text/plain mit
                # utf-8-Charset - Invoke-WebRequest hat .Content dann BEREITS
                # als String dekodiert. Der fruehere UTF8.GetString()-Aufruf
                # darauf warf (GetString nimmt nur Bytes), landete im catch
                # und der Selbst-Update-Pfad lieferte seit 3.9 IMMER $null.
                $text = [string]$content
            }
        }
    } catch {
        return $null
    }
    if ($null -eq $text) { return $null }
    # Mitdekodiertes BOM-Zeichen (U+FEFF) entfernen: WriteAllText schreibt
    # ueber UTF8Encoding($true) selbst ein BOM - sonst stuende ein
    # doppeltes BOM am Dateianfang von ArenaBridge.ps1.
    if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
    return $text
}

function Invoke-AutostartSelfUpdate {
    # Rueckgabe: $true, wenn ein Update installiert wurde und dieser Prozess
    # sich gleich beendet (der Neustart laeuft dann schon).
    #
    # 6.0.2: -VerifyMode = kurzer Sicherheits-Check auch nach einem Starter-
    # Start. Der Starter hat dann zwar ein -UpdateStatus uebergeben, aber
    # keines, das ein frisch installiertes Update BEWEIST ('kein-update',
    # 'keine-verbindung', 'update-fehler', 'update-suche-fehler'). In dem
    # Fall vergleicht die Bridge selbst kurz mit version.json im Repository
    # und zieht ein Update notfalls direkt - ein haengender/defekter Starter
    # konnte vorher beliebig lange dieselbe lokale Fassung starten lassen.
    # Zeitlimit knapp halten und nach dem ersten unerreichbaren Branch
    # aufhoeren: Der normale Programmstart darf nie spuerbar warten.
    param([switch]$VerifyMode)
    if ($script:IsExeMode) { return $false }           # EXE aktualisiert der Starter
    if (-not $script:ScriptPath) { return $false }
    if (-not (Test-Path -LiteralPath $script:ScriptPath)) { return $false }

    $localVersion = Get-LocalBridgeVersion
    if ($VerifyMode) {
        Write-RuntimeLog "Sicherheits-Check: Starter meldete kein frisches Update - pruefe selbst nach (lokal $localVersion) ..."
    } else {
        Write-RuntimeLog "Autostart-Update: Suche nach einer neueren Fassung (lokal $localVersion) ..."
    }

    foreach ($branch in (Get-UpdateBranchChain)) {
        $jsonTimeout = [int]$script:SelfUpdateTimeout
        if ($VerifyMode) { $jsonTimeout = [int]$script:SelfUpdateVerifyTimeout }
        $versionText = Get-RawGitHubText -Branch $branch -File 'version.json' -TimeoutSec $jsonTimeout
        if (-not $versionText) {
            Write-RuntimeLog "Update-Suche: Branch '$branch' nicht erreichbar - naechster Versuch."
            if ($VerifyMode) { break }
            continue
        }

        $remoteVersion = ''
        $remoteNotes = ''
        try {
            $info = $versionText | ConvertFrom-Json
            $remoteVersion = [string]$info.version
            if ($info.PSObject.Properties['notes']) { $remoteNotes = [string]$info.notes }
        } catch {
            Write-RuntimeLog "Update-Suche: version.json auf Branch '$branch' ist unlesbar."
            continue
        }
        if ([string]::IsNullOrWhiteSpace($remoteVersion)) { continue }

        if ((Compare-BridgeVersion -Remote $remoteVersion -Local $localVersion) -ne 1) {
            if ($VerifyMode) {
                Write-RuntimeLog "Sicherheits-Check: Version $remoteVersion online, $localVersion lokal - lokaler Stand ist aktuell."
            } else {
                Write-RuntimeLog "Autostart-Update: Version $remoteVersion online, $localVersion lokal - kein Update noetig."
            }
            return $false
        }

        Write-RuntimeLog "Update-Suche: Neue Version $remoteVersion gefunden - wird geladen ..."
        $newScript = Get-RawGitHubText -Branch $branch -File 'ArenaBridge.ps1'
        if ([string]::IsNullOrWhiteSpace($newScript) -or $newScript.Length -lt 50000) {
            Write-RuntimeLog 'Update-Suche: Download unvollstaendig - es bleibt bei der lokalen Fassung.'
            return $false
        }

        try {
            # 1) Erst in eine .new-Datei schreiben (UTF-8 MIT BOM, sonst
            #    liest PowerShell 5.1 die Umlaute als ANSI).
            $newPath = $script:ScriptPath + '.new'
            $utf8Bom = New-Object System.Text.UTF8Encoding($true)
            [System.IO.File]::WriteAllText($newPath, $newScript, $utf8Bom)

            # 2) Details fuer das Hinweisfenster hinterlegen.
            try {
                $statusFile = Join-Path $script:AppFolder 'update-status.json'
                $payload = @{ version = $remoteVersion; notes = $remoteNotes; error = $null } | ConvertTo-Json -Depth 5
                [System.IO.File]::WriteAllText($statusFile, $payload, $utf8Bom)
            } catch {}

            # 3) Austauschen: alte Datei als .old sichern, dann umbenennen.
            $oldPath = $script:ScriptPath + '.old'
            if (Test-Path -LiteralPath $oldPath) { Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue }
            Move-Item -LiteralPath $script:ScriptPath -Destination $oldPath -Force
            try {
                Move-Item -LiteralPath $newPath -Destination $script:ScriptPath -Force
            } catch {
                # Umbenennen fehlgeschlagen: alten Stand zurueckholen.
                Move-Item -LiteralPath $oldPath -Destination $script:ScriptPath -Force
                throw
            }
            Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue

            # 4) Andere Bridge-Instanzen beenden (wie der Starter es tut).
            try {
                foreach ($ghostPid in (Get-BridgeGhostProcesses)) {
                    [void](Stop-ProcessSafe -TargetPid $ghostPid -Reason 'Autostart-Update: alte Instanz')
                }
            } catch {}

            # 5) Neu starten - mit Update-Hinweis.
            $psExe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
            if (-not (Test-Path -LiteralPath $psExe)) { $psExe = 'powershell.exe' }
            # Version 7.3.0 (STARTGARANTIE): Neustart wird geprueft statt blind
            # gestartet. Stirbt er sofort (z. B. weil eine Sperre/AV den Aufruf
            # abwuergt), wird genau EIN weiterer Versuch gemacht und danach eine
            # Spur geschrieben - kein stilles Ende ohne Fenster.
            $restartArgs = @(
                '-NoProfile', '-ExecutionPolicy', 'Bypass',
                '-WindowStyle', 'Hidden',
                '-File', $script:ScriptPath,
                '-UpdateStatus', 'update-erfolgreich'
            )
            for ($restartTry = 1; $restartTry -le 2; $restartTry++) {
                $restartProc = Start-Process -FilePath $psExe -ArgumentList $restartArgs -WorkingDirectory $script:AppFolder -PassThru
                Start-Sleep -Milliseconds 700
                if (-not $restartProc.HasExited) { break }
                $restartCode = [string]$restartProc.ExitCode
                Write-RuntimeLog "Update-Suche: Neustart-Versuch $restartTry sofort beendet (ExitCode $restartCode)."
                if ($restartTry -ge 2) {
                    try {
                        [System.IO.File]::WriteAllText((Join-Path $script:BinFolder 'startup-trace.txt'),
                            'Update installiert, aber der Neustart brach zweimal sofort ab (ExitCode ' + $restartCode + '). Bitte ArenaBridge.exe erneut starten.',
                            [System.Text.Encoding]::UTF8)
                    } catch {}
                }
            }

            Write-RuntimeLog "Update-Suche: Version $remoteVersion installiert - Neustart laeuft."
            return $true
        } catch {
            Write-RuntimeLog "Update-Suche fehlgeschlagen: $($_.Exception.Message) - es wird die lokale Fassung gestartet."
            return $false
        }
    }

    if ($VerifyMode) {
        Write-RuntimeLog 'Sicherheits-Check: Repository nicht erreichbar - es wird die lokale Fassung gestartet.'
    } else {
        Write-RuntimeLog 'Autostart-Update: Kein Branch erreichbar - es wird die lokale Fassung gestartet.'
    }
    return $false
}

# ----------------------------------------------------------------------------
# EINSTELLUNGEN DAUERHAFT SPEICHERN (Version 3.8)
# Dauerhafte Einstellungen (Autostart, Selbst-Tests der KI und Fertig-Meldung)
# liegen in %LOCALAPPDATA%\ArenaRobloxBridge\settings.json. Der Zugriff je
# Place wird absichtlich nicht gespeichert und beginnt bei jeder Anmeldung
# wieder mit Lese- und Schreibzugriff.
# ----------------------------------------------------------------------------
$script:SettingsFile = Join-Path $script:AppDataRoot 'settings.json'

function Get-BridgeSettingsFile {
    $settings = @{
        autoStart       = $false
        # sim_start is intentionally disabled until supported true Edit-mode
        # physics/script execution exists. Ignore legacy simAllowed opt-ins.
        simAllowed      = $false
        notifyOnDone    = $false    # Fertig-Meldung als Windows-Notification (Standard: aus)
        editorIconsEnabled = $true # Live-Vorschau-Icons im Editor (Standard: an)
        progressInPlaceList = $true # Fortschrittsanzeige in der Place-Liste (Standard: an)
        perfDiagnostics = $false    # Laufzeitdiagnostik Leistung (Standard: AUS)
        # accessModes aus älteren Versionen werden absichtlich NICHT mehr geladen:
        # Lesezugriff gilt nur für die aktuelle Verbindung und startet immer aus.
    }
    try {
        if (Test-Path -LiteralPath $script:SettingsFile) {
            $loaded = Get-Content -LiteralPath $script:SettingsFile -Raw -Encoding UTF8 | ConvertFrom-Json
            if ($loaded.PSObject.Properties.Name -contains 'autoStart') { $settings.autoStart = [bool]$loaded.autoStart }
            if ($loaded.PSObject.Properties.Name -contains 'progressInPlaceList') { $settings.progressInPlaceList = [bool]$loaded.progressInPlaceList }
            if ($loaded.PSObject.Properties.Name -contains 'notifyOnDone') { $settings.notifyOnDone = [bool]$loaded.notifyOnDone }
            if ($loaded.PSObject.Properties.Name -contains 'editorIconsEnabled') { $settings.editorIconsEnabled = [bool]$loaded.editorIconsEnabled }
            # Version 7.2.2: Der Diagnosebereich ist entfernt; alte opt-ins werden ignoriert.
            # Legacy accessModes are deliberately ignored (Version 5): the
            # per-place read-only switch is temporary and never survives a registration.
        }
    } catch {}
    return $settings
}

function Save-BridgeSettingsFile {
    try {
        $out = @{
            autoStart       = [bool]$script:SettingsCache.autoStart
            simAllowed      = $false
            notifyOnDone    = [bool]$script:SettingsCache.notifyOnDone
            editorIconsEnabled = [bool]$script:SettingsCache.editorIconsEnabled
            progressInPlaceList = [bool]$script:SettingsCache.progressInPlaceList
            perfDiagnostics = [bool]$script:SettingsCache.perfDiagnostics
        }
        $json = $out | ConvertTo-Json -Depth 6
        [System.IO.File]::WriteAllText($script:SettingsFile, $json, [System.Text.UTF8Encoding]::new($true))
    } catch {
        try { Write-RuntimeLog "Einstellungen konnten nicht gespeichert werden: $($_.Exception.Message)" } catch {}
    }
}

$script:SettingsCache = Get-BridgeSettingsFile

# Version 7.1.3: HARTE OBERGRENZE fuer das Sessionstart-Paket (Bytes, JSON).
# Die erste Antwort einer Sitzung trug bis 7.1.2 die vollstaendige Doku aller
# 129 Werkzeuge mit - zusammen mit den Regelbloecken weit ueber 120 KB in EINEM
# Paket. Genau solche Riesenpakete sind ein bekannter Ausloeser fuer abgelehnte
# KI-Anfragen ("The AI service rejected this request"), und nach so einer
# Ablehnung war die Sitzung mitten in der Arbeit zu Ende. Get-SessionStartPackage
# liefert daher nur noch die Kernwerkzeuge vollstaendig, alles andere als Index
# (Name/Kategorie/Kurztext) und reduziert im Notfall auch den Kern auf den
# Index. Gemessen wird das echte serialisierte Paket; die Antwort nennt
# packageBytes, budgetBytes und docsPolicy. Der Wert liegt bewusst in $Shared:
# der HTTP-Handler laeuft in einem EIGENEN Runspace und sieht $script:-Variablen
# des Hauptskripts nicht (dieselbe Falle wie bei $script:PreviewCaptureMode).

# ----------------------------------------------------------------------------
# GEMEINSAMER ZUSTAND
# Alle Threads (HTTP-Server, Oberfläche) arbeiten auf diesen Sammlungen.
# Sie stecken in EINER Tabelle, damit der Server nur ein Argument braucht.
# ----------------------------------------------------------------------------
$script:Shared = [hashtable]::Synchronized(@{
    # sessionId -> JSON eines Studio-Fensters
    Sessions        = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    SessionTokens   = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    TokenSessions   = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    AccessModes     = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # sessionId -> Warteschlange mit Befehlen (JSON); queue rewrites are guarded
    # because dequeue, reset, watchdog removal and enqueue must remain atomic.
    CommandQueues   = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    CommandQueueLock = [System.Object]::new()
    # sessionId -> Signal: weckt den wartenden Long-Poll sofort auf
    CommandSignals  = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # Version 7.1.0: commandId -> JSON-Payload des Befehls fuer Re-Delivery,
    # solange das Plugin den Empfang noch nicht bestaetigt hat.
    CommandPayloads = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # commandId -> Ergebnis (JSON-Text)
    CommandResults  = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # commandId -> owning session; a result can only complete its original command.
    CommandOwners   = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    CommandStates   = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    CompletedCommandIds = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # Version 7.0.6: sessionId -> die letzten abgeschlossenen Befehle (kompakt).
    # Erst damit zeigt GET /api/queue die vollstaendige Zustell-Timeline
    # (queuedAt -> deliveredAt -> receivedAt -> startedAt -> heartbeatAt ->
    # finishedAt + Code), auch nachdem der offene Eintrag entfernt wurde.
    CommandHistory = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # sessionId:commandId -> cancel timestamp; sessionId -> executor reset timestamp.
    CancelRequests  = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    ExecutorResetRequests = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    ExecutorStates  = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    ToolSchemaIndex = $null
    ToolSchemaLock  = [System.Object]::new()
    ResultSignals   = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    CommandResultLock = [System.Object]::new()
    # commandId -> Teilstücke einer großen Antwort
    ResultChunks    = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    ResultChunkAt   = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # sessionId -> Zeitpunkt des letzten offenen Long-Polls
    Presence        = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # sessionId -> Anzahl gerade offener Long-Polls (echte Lebendigkeit)
    Pollers         = [System.Collections.Concurrent.ConcurrentDictionary[string,int]]::new()
    # blobId -> große Antwort, die in Stücken abgeholt wird
    Blobs           = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    BlobInfo        = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # uploadId -> großer Text, den die KI hochgeladen hat
    Uploads         = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # sessionId -> Ereignisse (Benutzer hat Play gestartet usw.)
    Events          = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    Counters        = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # sessionId -> ausstehende Befehle samt Queue-/Executor-Status
    PendingCommands = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # sessionId -> completed results whose HTTP caller had already timed out.
    LateResults     = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # Version 7.0.5: commandId -> session that CALLED the tool (owns the token and
    # the lateResults queue). CommandOwners keeps the session that currently has to
    # deliver/execute the command; after a plugin restart both can differ, so a
    # result still reaches the caller that is waiting for that commandId.
    CommandOrigins  = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Version 7.0.5: commandId -> plugin instanceGuid. A result is accepted from the
    # same physical plugin instance even after it registered a new session.
    CommandInstanceGuids = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Version 7.0.5: sessionId -> successor session (same plugin window after a
    # reconnect). Deliveries follow this chain so commands are not stranded in a
    # session the plugin no longer polls. The caller keeps its own token/session.
    SessionSuccessors = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Version 7.0.5: proof that the independent server-side watchdog really runs.
    SweepState = [hashtable]::Synchronized(@{
        LastSweepAt = 0L
        Sweeps = 0L
        Abandoned = 0L
        StartedAt = 0L
    })
    # sessionId -> { tool -> @{ fingerprint, at, resultJson } }; retries of
    # play_start/play_stop within 3s reuse the original result.
    PlayRetryDedupe = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # sessionId -> true, wenn die Start-Doku bereits an die KI ging
    DocsSent        = [System.Collections.Concurrent.ConcurrentDictionary[string,bool]]::new()
    # ================================================================
    # Version 7.4.0: BLENDER-/MESH-BAU (Schritt 4 vor dem Tunnel).
    # Alle Strukturen sind thread-sicher: Handler-, Sweep- und UI-Threads
    # lesen und schreiben sie parallel.
    #   BlenderState -> Zustand von Pruefung/Installation (Splash-Schritt 4)
    #   MeshJobs     -> jobId  -> JSON {id, modelName, state, slots[], ...}
    #   MeshRegistry -> slotKey -> JSON {slotKey, state, objPath, assetId, ...}
    #   MeshInternal -> tag -> JSON-Ergebnis eines INTERNEN Studio-Aufrufs
    # ================================================================
    BlenderState    = [hashtable]::Synchronized(@{
        state = 'unknown'
        path = ''
        version = ''
        probe = ''
        detail = ''
        percent = 0
        message = 'Blender wird geprueft ...'
        source = ''
        updatedAt = 0L
        installStartedAt = 0L
        checkedAt = 0L
        gateResolved = $false
        enabled = $false
    })
    MeshJobs        = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    MeshRegistry    = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    MeshInternal    = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    MeshRunnerText  = ''
    # Pfad des lokalen Asset-Caches (Suche/Details, damit pro Session nichts neu geladen wird)
    AssetCachePath  = Join-Path $script:AppDataRoot 'asset_cache.json'
    # Version 7.1.2: TOOLBOX-DROSSEL je Place. Ohne sie lief jeder Katalog-/
    # Asset-Aufruf unbegrenzt parallel im HTTP-Runspace, schrieb dieselbe
    # Cache-Datei und konnte den Cloudflare-524 erreichen.
    #   ToolboxSlots         sessionId -> Anzahl gerade laufender Katalogaufrufe
    #   ToolboxImportLocks   sessionId -> JSON des EINEN aktiven Asset-Imports
    #   ToolboxInsertResults requestKey -> fertiges Ergebnis (Idempotenz)
    ToolboxSlots         = [System.Collections.Concurrent.ConcurrentDictionary[string,int]]::new()
    ToolboxSlotLock      = [System.Object]::new()
    ToolboxImportLocks   = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    ToolboxInsertResults = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    ToolboxInsertAt      = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    AssetCacheLock       = [System.Object]::new()
    # Harte Obergrenzen (bewusst klein - ein Mini-Fix, kein neues Subsystem).
    ToolboxLimits = [hashtable]::Synchronized(@{
        MaxPendingPerPlace   = 2     # gleichzeitige Katalogaufrufe je Place
        CatalogTimeoutSec    = 12    # hartes Zeitlimit je HTTP-Aufruf
        CatalogBudgetSec     = 25    # hartes Gesamtbudget je Werkzeugaufruf
        MaxDetailIdsPerCall  = 24    # Obergrenze fuer Einzelabfragen (404-Faelle)
        ImportWedgedAfterSec = 45    # danach gilt ein Import als haengend
        IdempotencyWindowSec = 120   # gleiche Einfuegung in diesem Fenster = Wiederholung
        MaxCacheEntries      = 400   # Asset-Cache haert begrenzt (RAM/Disk)
        MaxCacheBytes        = 2097152
    })
    AppDataRoot     = $script:AppDataRoot
    LogFile         = $script:RuntimeLog
    ShotFolder      = $script:ShotFolder
    Port            = $script:Port
    DocsVersion     = '7.4.1'
    # Version 7.0.6: SELBSTAUSKUNFT, die das Deployment BEWEIST. Diese Zaehler
    # laufen IMMER mit - unabhaengig von der Leistungsdiagnose. GET /api/version
    # liefert sie zusammen mit Datei-Pfad und SHA-256 der laufenden Datei, damit
    # in EINER Antwort sichtbar ist, ob 7.0.6 ueberhaupt laeuft und ob das
    # Studio-Plugin pollt. Ohne diese Zahlen war jede Fehlersuche geraten.
    Telemetry = [hashtable]::Synchronized(@{
        StartedAt = 0L
        Hello = 0L
        Poll = 0L
        Result = 0L
        ToolCalls = 0L
        NewSessions = 0L
        ReusedSessions = 0L
        RevivedSessions = 0L
        UnknownSessionPolls = 0L
        StormWarnings = 0L
        FastFailWedged = 0L
        FastFailBusy = 0L
        RowCancels = 0L
        LastHelloAt = 0L
        LastPollAt = 0L
        LastResultAt = 0L
    })
    # Version 7.0.6: Zeitpunkte der Sitzungs-Neuanlagen (Sturm-Beweis ohne Log).
    SessionCreations = [System.Collections.Concurrent.ConcurrentQueue[long]]::new()
    # Version 7.0.6: DIESELBE Plugin-Instanz bekommt IMMER dieselbe Sitzung und
    # denselben Token - auch nach Cleanup, Reconnect oder einem Zustand, der von
    # aussen "tot" aussieht. Erst das beendet den "Bridge connected"-Sturm alle
    # 2 Sekunden und verhindert, dass Befehle in einer Sitzung landen, die das
    # Plugin nicht mehr pollt.
    InstanceSessions = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    InstanceLastSeen = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # Version 7.0.6: Laufzeit-Identitaet der LAUFENDEN Datei (Version, Pfad,
    # SHA-256, Sprachmodus, Startzeit) fuer GET /api/version.
    RuntimeInfo = [hashtable]::Synchronized(@{
        Version = '7.4.1'
        File = ''
        Sha256 = ''
        LanguageMode = ''
        AppDataRoot = ''
        LogFile = ''
        PerfFile = ''
        StartedAt = 0L
    })
    # Einstellungen (Version 3.8): UI und Server-Threads teilen sich diese Werte.
    BridgeSettings  = [hashtable]::Synchronized(@{
        simAllowed      = $false    # sim_start bleibt bis zu echter Edit-Modus-Simulation gesperrt
        notifyOnDone    = $false    # report_done -> Windows-Benachrichtigung
        progressInPlaceList = $true # Fortschrittsanzeige in der Place-Liste
        # Version 7.0.3: Laufzeitdiagnostik fuer die Leistungsmessung.
        # Standard AUS: ohne diese Zustimmung wird nichts gemessen/geloggt.
        perfDiagnostics = $false
        # Read-only is session-local only. It is intentionally not persisted.
    })
    # report_done-Meldungen: der Server legt sie ab, die Oberflaeche zeigt sie an
    NotifyQueue     = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()

    # ==================================================================
    # Version 7.2.0: NUTZER-KANAL, FRAGEN, BUILD-REGISTER, KANAL-ZAEHLER.
    # Alles liegt in $Shared (nicht als $script:-Variable), weil der
    # HTTP-Handler in EIGENEN Runspaces laeuft und $script: dort nicht kennt
    # (dieselbe Regel wie bei SessionPayloadHardBudgetBytes seit 7.1.3).
    # ==================================================================
    # NUTZER-KANAL ("Zwischen-Prompt"): sessionId -> JSON
    #   { messages = [ { id, text, kind, createdAt, state, attempts,
    #                    deliveredAt, deliveredWith, ackAt, withdrawnAt } ],
    #     updatedAt }
    # Die Oberflaeche stellt ein, der Umschlag JEDER HTTP-Antwort liefert aus
    # (at-least-once, maximal 3 Versuche). state: queued -> delivered ->
    # acked | delivered_unacked | withdrawn.
    UserMessages    = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    UserMessageLock = [System.Object]::new()
    # sessionId -> ManualResetEvent: weckt wait_for_user, sobald der Nutzer
    # schreibt (sonst wuerde die KI bis zum Ende ihrer Wartezeit schlafen).
    UserSignals     = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # FRAGEN AN DEN NUTZER (ask_user/confirm_action): askId -> JSON
    #   { askId, sessionId, kind, title, questions = [ { id, text, options,
    #     allowCustomResponse, required, multi, when } ], state, createdAt,
    #     expiresAt, answeredAt, answers, path, notShown, deliveredTo }
    AskRequests     = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    AskLock         = [System.Object]::new()
    AskSignals      = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # sessionId -> JSON-Liste mit Antworten, die erst NACH dem Ende der
    # wartenden Anfrage ankamen. Sie gehen nie verloren: der naechste Umschlag
    # liefert sie als _bridge.userAnswers nach.
    LateAskAnswers  = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # BUILD-REGISTER: sessionId -> JSON { models = [ { id, path, name, kind,
    #   declaredGrade, firstWriteAtTicks, lastWriteAtTicks, auditAtTicks,
    #   auditGrade, auditFinishScore, auditVerdict } ] }
    SessionBuilds    = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    SessionBuildLock = [System.Object]::new()
    # STATIONEN-Puffer (Ring) fuer die kleinen Diagnose-Dateien der
    # Oberflaeche (progress-diagnose.txt / notify-diagnose.txt).
    FlowTrace       = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
    FlowTraceCap    = 500
    # Version 7.2.0 (D4): Das von der Oberflaeche GEMESSENE Plattform-Urteil als
    # JSON. Der Handler-Runspace kann keine UI-Funktionen aufrufen, braucht das
    # Urteil aber, damit report_done ehrlich antwortet (NOTIFICATION_UNVERIFIED).
    NotifyPlatformJson = ''
    NotifyLastJson     = ''
    # Version 7.2.0 (AP7): Ergebnis der Code-Struktur-Messung je Sitzung
    # (UI_ENGINE.codeLayoutReport beim Schreiben eines Skripts).
    CodeLayouts        = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Zuletzt geschriebene Station je Schluessel (Drosselung gegen vollaufende
    # runtime.log: Fortschritt kaeme sonst bei JEDEM Werkzeugaufruf).
    ProgressLogAt   = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # KANAL-ZAEHLER: laufen IMMER mit (wie Telemetry seit 7.0.6). Sie
    # verwandeln "die Meldung kam nicht an" und "der Balken blieb bei 0 %"
    # in Zahlen, die man zwischen zwei Laeufen vergleichen kann.
    Channel = [hashtable]::Synchronized(@{
        ProgressCalls            = 0L
        ProgressWithPercent      = 0L
        ProgressMissingPercent   = 0L
        ProgressPaintedPercent   = 0L
        ProgressPaintedNoPercent = 0L
        ProgressNotDisplaced     = 0L
        NotifyFlowSeq            = 0L
        NotifyEnqueued           = 0L
        NotifyShown              = 0L
        NotifyUnverified         = 0L
        NotifyLastSeen           = ''
        NotifySuppressed         = 0L
        NotifyFailed             = 0L
        NotifyLastVerdict        = ''
        NotifyLastReason         = ''
        NotifyLastAt             = 0L
        UserMessagesQueued       = 0L
        UserMessagesDelivered    = 0L
        UserMessagesAcked        = 0L
        UserMessagesUnacked      = 0L
        UserMessagesWithdrawn    = 0L
        AskOpened                = 0L
        AskAnswered              = 0L
        AskExpired               = 0L
        AskAgentGone             = 0L
        AskLateAnswers           = 0L
        BuildsRegistered         = 0L
        CodeLayoutChecked        = 0L
        BuildAuditDemands        = 0L
        QualityDraftFlags        = 0L
        QualityAuditDemands      = 0L
        UiMonolithFlags          = 0L
        UiStructureDemands       = 0L
    })
    # Version 7.1.3: harte Obergrenze des Sessionstart-Pakets (Bytes, JSON).
    # Liegt hier - und nicht als $script:-Variable - damit der HTTP-Handler in
    # seinem eigenen Runspace denselben Wert liest (siehe Kommentar oben).
    SessionPayloadHardBudgetBytes = 300000
    # sessionId -> @{ action='start'/'stop'; at=<unix> } - Play-Absicht der KI
    AiPlayIntents   = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # sessionId -> @{ kind='play_started'/'play_stopped'; at=<unix> } - Dedupe
    LastPlayEvents  = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    # sessionId -> 'assistant'/'user' - wer hat den LAUFENDEN Test gestartet
    RunOwners       = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # sessionId -> unix-Zeit der letzten Nutzer-Aktivitaet im Studio
    UserActiveAt    = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # 3.9.8 Session-Agent: short-lived authenticated local channel from the
    # isolated Play DataModel back to its edit-plugin session.
    AgentKeys       = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    AgentQueues     = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    AgentResults    = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    AgentStates     = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    AgentLastSeen   = [System.Collections.Concurrent.ConcurrentDictionary[string,long]]::new()
    # Version 5: sessionId -> activityId -> JSON log entry. The UI reads this
    # live collection; entries stay only for the running bridge process.
    ActivityLogs       = [System.Collections.Concurrent.ConcurrentDictionary[string,object]]::new()
    ActivityCommandMap = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Version 7.0.0: Fortschrittsvertrag. sessionId -> JSON
    # { percent, message, state, updatedAt, lastCallAt, calls, callsWithProgress,
    #   autoSet, history[] }. Jeder Aufruf traegt ihn; fehlt er, gilt 0 %.
    ProgressStates  = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Version 7.0.0: Uebergaben (Handoff) je Sitzung + zuletzt geschriebener Pfad.
    Handoffs        = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Version 7.0.0: Audit-Kennzahlen (Platzhalter/Blockout) fuer HANDOFF_REQUIRED.
    AuditFlags      = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # sessionId -> getrennte Datensaetze aller registrierten organischen Modelle.
    # report_done verlangt frische, bestandene per-model Audits fuer jedes Modell.
    OrganicBuilds   = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
    # Version 7.0.3: LAUFZEITDIAGNOSTIK (Leistung). Zaehler fuer die Bereiche,
    # die im Leerlauf Arbeit verursachen koennen: HTTP-Anfragen der Plugins,
    # UI-Abgleich (DispatcherTimer) und die vom Plugin gemeldeten Poll-Zahlen.
    # Alle Werte sind Summen/Intervalle; geschrieben wird nur, wenn die
    # Diagnose in den Einstellungen aktiv ist (Standard: aus) und dann
    # hoechstens alle 30 Sekunden - kein Logging pro Tick.
    Perf            = [hashtable]::Synchronized(@{
        HttpRequests   = 0L
        HttpMsTotal    = 0.0
        HttpMsMax      = 0.0
        HttpDone       = 0L
        PollRequests   = 0L
        HelloRequests  = 0L
        Heartbeats     = 0L
        UiTicks        = 0L
        UiMsTotal      = 0.0
        UiMsMax        = 0.0
    })
    # One aggregate token per program start, never derived from the place list.
    MultiPlaceToken    = $null
})

# Gespeicherte Einstellungen in den gemeinsamen Zustand uebernehmen (3.8)
try {
    if ($script:SettingsCache.simAllowed -is [bool]) { $script:Shared.BridgeSettings.simAllowed = [bool]$script:SettingsCache.simAllowed }
    if ($script:SettingsCache.notifyOnDone -is [bool]) { $script:Shared.BridgeSettings.notifyOnDone = [bool]$script:SettingsCache.notifyOnDone }
    if ($script:SettingsCache.progressInPlaceList -is [bool]) { $script:Shared.BridgeSettings.progressInPlaceList = [bool]$script:SettingsCache.progressInPlaceList }
    if ($script:SettingsCache.perfDiagnostics -is [bool]) { $script:Shared.BridgeSettings.perfDiagnostics = [bool]$script:SettingsCache.perfDiagnostics }
    # Version 5: legacy per-place accessModes are ignored on purpose.
} catch {}

function Write-RuntimeLog {
    param([string]$Message)
    try {
        $line = '{0:u} {1}' -f (Get-Date), $Message
        Add-Content -LiteralPath $script:RuntimeLog -Value $line -Encoding UTF8
    } catch {}
}

# ----------------------------------------------------------------------------
# Version 5.0.2: Harte, sichtbare Fehlerausgabe fuer Oberflaechen-Fehler.
# Bis 5.0.1 stand in runtime.log nur die nackte .Message eines Fehlers -
# Exception-Typ, Skriptzeile und Stacktrace fehlten. Ein Fehler beim Bau
# einer Place-Zeile war damit praktisch verschluckt und die Ursache nicht
# mehr zurueckverfolgbar (Lehre aus 5.0.1: raten bringt nichts, messen).
# ----------------------------------------------------------------------------
function Write-UiErrorLog {
    param([string]$Context, $ErrorRecord)
    $typeName   = ''
    $message    = ''
    $lineNumber = ''
    $trace      = ''
    try { if ($ErrorRecord -and $ErrorRecord.Exception) { $typeName = [string]$ErrorRecord.Exception.GetType().FullName } } catch {}
    try { if ($ErrorRecord -and $ErrorRecord.Exception) { $message = [string]$ErrorRecord.Exception.Message } } catch {}
    try { if ($ErrorRecord -and $ErrorRecord.InvocationInfo) { $lineNumber = [string]$ErrorRecord.InvocationInfo.ScriptLineNumber } } catch {}
    try { if ($ErrorRecord) { $trace = [string]$ErrorRecord.ScriptStackTrace } } catch {}
    Write-RuntimeLog ('{0}: {1}: {2} | Skriptzeile: {3} | Stacktrace: {4}' -f $Context, $typeName, $message, $lineNumber, $trace)
}

function Write-StartupFailureDiagnose {
    param($ErrorRecord)
    # Version 7.2.6 (START-NETZ KOMPLETT): Ein Fehler im Startabschnitt darf die
    # Bridge nicht lautlos beenden. Die Ausnahme wird in runtime.log UND in
    # startup-diagnose.txt gesichert (mit der letzten Startstufe). Wurde das
    # Hauptfenster noch nicht sichtbar, erscheint ZUSAETZLICH eine sichtbare
    # Windows-Meldung - kein stummes Prozessende mehr.
    try {
        $message = ''
        try { $message = [string]$ErrorRecord.Exception.Message } catch {}
        if ([string]::IsNullOrWhiteSpace($message)) { $message = [string]$ErrorRecord }
        try { Write-RuntimeLog ('START-ABSCHNITT FEHLGESCHLAGEN: ' + $message) } catch {}
        $stage = ''
        try { $stage = [string]$script:StartupStage } catch {}
        $trace = ''
        try { $trace = [string]$ErrorRecord.ScriptStackTrace } catch {}
        if ($trace.Length -gt 2000) { $trace = $trace.Substring(0, 2000) }
        $report = New-Object System.Text.StringBuilder
        [void]$report.AppendLine('Arena Roblox Bridge - Start-Diagnose (Version 7.4.1)')
        [void]$report.AppendLine('Zeitstempel: ' + (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'))
        [void]$report.AppendLine('Letzte Startstufe: ' + $stage)
        [void]$report.AppendLine('PowerShell: ' + [string]$PSVersionTable.PSVersion)
        [void]$report.AppendLine('CLR: ' + [string][Environment]::Version)
        [void]$report.AppendLine('Fehler: ' + $message)
        [void]$report.AppendLine('Stapel: ' + $trace)
        $diagnosePath = ''
        try {
            $diagnosePath = Join-Path $script:BinFolder 'startup-diagnose.txt'
            [System.IO.File]::WriteAllText($diagnosePath, $report.ToString(), [System.Text.Encoding]::UTF8)
        } catch {}
        # Nie mehr lautlos: solange kein Fenster sichtbar wurde, sichtbar melden.
        $shown = $false
        try { $shown = [bool]$script:WindowShown } catch {}
        if (-not $shown) {
            # Version 7.3.0 (STARTGARANTIE): Es gibt IMMER einen sichtbaren
            # Hinweis. Klappt die Windows-Meldung nicht (WPF nicht verfuegbar),
            # wird die Diagnosedatei in Notepad geoeffnet - der letzte Weg, der
            # ohne WPF auskommt. Erst danach endet der Prozess.
            $boxShown = $false
            try {
                try { Add-Type -AssemblyName PresentationFramework -ErrorAction SilentlyContinue } catch {}
                $nl = [Environment]::NewLine
                $boxText = 'Die Bridge konnte nicht vollstaendig starten.' + $nl + $nl +
                           'Stufe: ' + $stage + $nl +
                           'Fehler: ' + $message + $nl + $nl +
                           'Details: ' + $diagnosePath
                [void][System.Windows.MessageBox]::Show($boxText, 'Arena Roblox Bridge - Startfehler')
                $boxShown = $true
            } catch {}
            if (-not $boxShown) {
                try {
                    if ($diagnosePath -and (Test-Path -LiteralPath $diagnosePath)) {
                        Start-Process -FilePath 'notepad.exe' -ArgumentList ('"' + $diagnosePath + '"')
                    }
                } catch {}
            }
        } else {
            # Nach dem ersten Rendern bleibt der Fehler direkt im sichtbaren
            # Startbildschirm stehen; der Nutzer muss nicht erst Logs suchen.
            try {
                $main = $script:MainWindow
                if ($null -ne $main) {
                    $splash = $main.FindName('SplashScreen')
                    $headline = $main.FindName('SplashHeadline')
                    $subline = $main.FindName('SplashSub')
                    if ($splash) { $splash.Visibility = 'Visible' }
                    if ($headline) { $headline.Text = 'Start fehlgeschlagen' }
                    if ($subline) {
                        $shortMessage = [string]$message
                        if ($shortMessage.Length -gt 240) { $shortMessage = $shortMessage.Substring(0, 240) + '…' }
                        $subline.Text = 'Stufe: ' + $stage + [Environment]::NewLine +
                                        'Fehler: ' + $shortMessage + [Environment]::NewLine +
                                        'Details: ' + $diagnosePath
                    }
                    [void]$main.Activate()
                }
            } catch {}
        }
    } catch {}
}

# Version 7.2.6: Startstufen-Trace. Jede Stufe wird sofort in startup-trace.txt
# festgehalten. Bricht der Start trotzdem ab, steht die letzte erreichte Stufe
# in startup-trace.txt, in startup-diagnose.txt und in der sichtbaren Meldung -
# damit ist die Ursache ohne Raten belegbar.
$script:StartupStage = 'Skriptbeginn'
$script:WindowShown = $false
function Set-StartupStage {
    param([string]$Stage)
    $script:StartupStage = [string]$Stage
    try {
        $line = ((Get-Date -Format 'yyyy-MM-dd HH:mm:ss') + ' | ' + $script:StartupStage + ' | PowerShell ' + [string]$PSVersionTable.PSVersion)
        [System.IO.File]::WriteAllText((Join-Path $script:BinFolder 'startup-trace.txt'), $line, [System.Text.Encoding]::UTF8)
    } catch {}
    # Version 7.3.0 (STARTGARANTIE): Dieselbe Stufe zusaetzlich als leicht
    # auffindbare Datei in %LOCALAPPDATA%\START-CHECK.txt. Sie ist der Beweis,
    # wie weit der Start wirklich gekommen ist, und die EINE Datei, die der
    # Nutzer zurueckgeben kann. Nur Text, kein Fenster, keine Ausnahme.
    try {
        $stamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
        $checkText = 'Arena Roblox Bridge - Startkontrolle' + [Environment]::NewLine +
                     'Version: 7.4.1' + [Environment]::NewLine +
                     'Zeit: ' + $stamp + [Environment]::NewLine +
                     'PowerShell: ' + [string]$PSVersionTable.PSVersion + ' | CLR ' + [string][Environment]::Version + [Environment]::NewLine +
                     'Skript: ' + [string]$script:ScriptPath + [Environment]::NewLine +
                     'Letzte erreichte Startstufe: ' + [string]$script:StartupStage + [Environment]::NewLine +
                     'Fenster sichtbar: ' + [string]$script:WindowShown + [Environment]::NewLine +
                     [Environment]::NewLine +
                     'Wenn kein Fenster erscheint: genau diese Datei weitergeben.'
        [System.IO.File]::WriteAllText((Join-Path $env:LOCALAPPDATA 'START-CHECK.txt'), $checkText, [System.Text.Encoding]::UTF8)
    } catch {}
}

function Write-PlaceRowFailure {
    param([string]$Context, [string]$SessionId, $ErrorRecord)
    $sid = if ([string]::IsNullOrWhiteSpace($SessionId)) { '(unknown)' } else { $SessionId }
    # Version 7.0.7: Grund IMMER merken (auch wenn das Log gedrosselt ist).
    try {
        $message = if ($ErrorRecord) { [string]$ErrorRecord.Exception.Message } else { '' }
        $script:LastPlaceRowError = ($Context + ' (sid=' + $sid + ')' + $(if ($message) { ': ' + $message } else { '' }))
    } catch {}
    $key = $sid + '|' + $Context
    $now = Get-Date
    if ($script:PlaceRowFailureLogAt.ContainsKey($key)) {
        if (($now - [DateTime]$script:PlaceRowFailureLogAt[$key]).TotalSeconds -lt 15) { return }
    }
    $script:PlaceRowFailureLogAt[$key] = $now
    Write-UiErrorLog ("$Context (sid=$sid)") $ErrorRecord
}

$script:PreviewFailureLogAt = @{}
function Write-PreviewCaptureError {
    param([string]$SessionId, $ErrorRecord)
    $sid = if ([string]::IsNullOrWhiteSpace($SessionId)) { '(unknown)' } else { $SessionId }
    $msg = ''
    try { if ($ErrorRecord -and $ErrorRecord.Exception) { $msg = [string]$ErrorRecord.Exception.Message } } catch {}
    $key = $sid + '|' + $msg
    $now = Get-Date
    if ($script:PreviewFailureLogAt.ContainsKey($key)) {
        if (($now - [DateTime]$script:PreviewFailureLogAt[$key]).TotalSeconds -lt 30) { return }
    }
    $script:PreviewFailureLogAt[$key] = $now
    Write-UiErrorLog ("Vorschau-Aufnahme fehlgeschlagen (sid=$sid)") $ErrorRecord
}

$runModeText = if ($script:IsExeMode) { "EXE-Modus ($script:ExePath)" } else { "Skript-Modus ($script:ScriptPath)" }
Write-RuntimeLog "=== Programmstart (PID $PID, PowerShell $($PSVersionTable.PSVersion), $runModeText) ==="
Write-RuntimeLog "Codierung: Umlaute korrekt gelesen = $script:EncodingOk (Marker-Laenge $($script:EncodingMarker.Length))"

# Version 6.0.4: Laufzeit-Identitaet. Beweist im Log, welche Datei WIRKLICH
# laeuft (Version, absoluter Pfad, SHA-256) - damit ist sofort sichtbar, ob
# der Starter tatsaechlich 6.0.4 installiert hat oder noch eine alte Kopie
# startet. Der Sprachmodus steht dabei, weil Add-Type (C#-Helfer) unter
# ConstrainedLanguage scheitert und dann der ps-fallback-Pfad greift.
try {
    $runFile = [string]$script:ScriptPath
    if ([string]::IsNullOrWhiteSpace($runFile)) {
        try { $runFile = [string][System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch {}
    }
    $runHash = '-'
    try {
        if ($runFile -and (Test-Path -LiteralPath $runFile)) {
            $runHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $runFile).Hash
        }
    } catch {}
    $langMode = '-'
    try { $langMode = [string]$ExecutionContext.SessionState.LanguageMode } catch {}
$script:PreviewDiagIdentity = ("Bridge-Version=7.4.1, Datei='{0}', SHA-256={1}, LanguageMode={2}, CLR={3}" -f $runFile, $runHash, $langMode, [Environment]::Version)
    Write-RuntimeLog ("Laufzeit-Identitaet: Bridge-Version=7.4.1, Datei='{0}', SHA-256={1}, LanguageMode={2}, CLR={3}" -f $runFile, $runHash, $langMode, [Environment]::Version)
    # Version 7.0.6: dieselbe Identitaet auch fuer GET /api/version bereitstellen.
    # Sie ist der einzige Beweis, dass die 7.0.6-Datei wirklich laeuft (H1).
    try {
$script:Shared.RuntimeInfo.Version = '7.4.1'
        $script:Shared.RuntimeInfo.File = [string]$runFile
        $script:Shared.RuntimeInfo.Sha256 = [string]$runHash
        $script:Shared.RuntimeInfo.LanguageMode = [string]$langMode
        $script:Shared.RuntimeInfo.AppDataRoot = [string]$script:AppDataRoot
        $script:Shared.RuntimeInfo.LogFile = [string]$script:RuntimeLog
        $script:Shared.RuntimeInfo.PerfFile = (Join-Path $script:AppDataRoot 'performance.txt')
        $script:Shared.RuntimeInfo.StartedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        $script:Shared.Telemetry.StartedAt = [long]$script:Shared.RuntimeInfo.StartedAt
    } catch {}
    # Version 6.0.5: Hinweis auf den kleinen Kurzbericht - er enthaelt alles,
    # was zur Beurteilung der Fenster-Vorschau noetig ist.
    Write-RuntimeLog ("Vorschau-Kurzbericht: " + (Join-Path $script:AppDataRoot 'preview-diagnose.txt'))
} catch {}

try {
    [System.AppDomain]::CurrentDomain.add_UnhandledException({
        param($sender, $eventArgs)
        try { Write-RuntimeLog "SCHWERER FEHLER: $($eventArgs.ExceptionObject)" } catch {}
    })
} catch {}

function New-Token {
    $bytes = New-Object byte[] 24
    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($bytes)
    [Convert]::ToBase64String($bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_')
}

# Version 5: this aggregate token deliberately exists independently of the
# visible "Alle Places" row. It changes only on process restart or when the
# user explicitly clicks "Token zurücksetzen" in the "..." menu of that row
# (Version 5.2: the button lives in the menu; the row itself matches all
# other rows now).
$script:AllPlacesToken = New-Token
$script:Shared.MultiPlaceToken = $script:AllPlacesToken

# ----------------------------------------------------------------------------
# Kaputte Umlaute reparieren (falls doch einmal ANSI-Text ankommt).
# Aus "BÃ¶seElla" wird wieder "BöseElla".
# ----------------------------------------------------------------------------
function Repair-Mojibake {
    param([string]$Text)
    if ([string]::IsNullOrEmpty($Text)) { return $Text }
    if ($Text -notmatch '[ÃÂ]') { return $Text }
    try {
        $bytes = [System.Text.Encoding]::GetEncoding(1252).GetBytes($Text)
        $repaired = [System.Text.UTF8Encoding]::new($false, $true).GetString($bytes)
        if (-not [string]::IsNullOrWhiteSpace($repaired)) { return $repaired }
    } catch {}
    return $Text
}

function Find-RobloxStudio {
    $roots = @(
        (Join-Path $env:LOCALAPPDATA 'Roblox\Versions'),
        (Join-Path ${env:ProgramFiles(x86)} 'Roblox\Versions'),
        (Join-Path $env:ProgramFiles 'Roblox\Versions')
    ) | Where-Object { $_ -and (Test-Path $_) }

    $found = @()
    foreach ($root in $roots) {
        $found += Get-ChildItem -Path $root -Directory -ErrorAction SilentlyContinue |
            ForEach-Object { Join-Path $_.FullName 'RobloxStudioBeta.exe' } |
            Where-Object { Test-Path $_ } |
            ForEach-Object { Get-Item $_ }
    }

    $uninstallRoots = @(
        'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )
    foreach ($key in $uninstallRoots) {
        Get-ItemProperty -Path $key -ErrorAction SilentlyContinue |
            Where-Object {
                $displayName = $_.PSObject.Properties['DisplayName']
                $displayName -and $displayName.Value -like '*Roblox Studio*'
            } |
            ForEach-Object {
                $candidate = $null
                $installLocation = $_.PSObject.Properties['InstallLocation']
                $displayIcon = $_.PSObject.Properties['DisplayIcon']
                if ($installLocation -and $installLocation.Value) {
                    $candidate = Join-Path $installLocation.Value 'RobloxStudioBeta.exe'
                } elseif ($displayIcon -and $displayIcon.Value) {
                    $candidate = ([string]$displayIcon.Value -replace '^"|"$', '') -replace ',\d+$', ''
                }
                if ($candidate -and (Test-Path $candidate)) {
                    $found += Get-Item $candidate
                }
            }
    }

    $found | Sort-Object LastWriteTime -Descending | Select-Object -First 1
}


# ----------------------------------------------------------------------------
# STUDIO-PLUGIN (Lua)
# Wird bei jedem Start neu nach %LOCALAPPDATA%\Roblox\Plugins geschrieben.
# ----------------------------------------------------------------------------
function Get-PluginSource {
@'
--[[============================================================================
  Arena Studio Bridge - Studio Plugin  (Version 7.4.1)

  Dieses Plugin verbindet ein Roblox-Studio-Fenster mit dem Programm
  "Arena Roblox Bridge" auf dem PC. Jedes Studio-Fenster bekommt eine eigene
  Sitzung und damit einen eigenen Token.

  Wichtige Neuerungen:
    * Jedes Objekt bekommt eine eigene Id (#12). Damit sind 55 gleich
      benannte "Part" eindeutig ansprechbar.
    * Scripte koennen punktgenau geaendert werden (patch_script), ohne den
      ganzen Text neu zu schreiben.
    * Vollstaendiger Zugriff auf das Ausgabefenster (Output) inklusive
      Client-Ausgaben im Testmodus.
    * sim_start ist deaktiviert: Die fruehere offizielle Studio-Run-Simulation
      (ExecuteRunModeAsync) verliess Edit Mode (EditModeActive=false). Die
      dokumentierte API bietet keinen echten Edit-Modus-Pfad fuer Physik/Skripte;
      sim_status bleibt lesbar und sim_stop fuer bestehende Sessions verfuegbar.
    * Schutz: dauerhafte Aenderungen werden im Play-Modus blockiert, weil sie
      beim Stoppen verloren gehen.
    * Unions: zusammenfuegen, abziehen, schneiden, trennen - mit Warnungen.
    * Klonen, Massenoperationen (60 Teile auf einmal) und Bauhilfen.
    * Grosse Ergebnisse werden in Stuecken uebertragen statt abgeschnitten.

  Wichtige Neuerungen 3.1:
    * Persistenter Lua-Worker: run_lua und Jobs teilen sich EINE Umgebung -
      Helper, Variablen und Caches ueberleben einzelne Rufe.
    * Job-System: lange Operationen laufen nach Timeouts weiter
      (job_status/job_result), kooperative Abbrechung, kein Doppellauf.
    * Neue Geometrie wird automatisch so lange gewartet, bis sie per Raycast
      messbar ist (create/clone/bulk_create, fill_region).
    * Orientierung wird GEMESSEN: measureShape, point_at, describe_orientation,
      coordinate_guide - keine ratenden Drehwerte mehr.
    * Raeumliches Verstehen: parts_in_box, nearest_parts, what_is_in_the_way,
      ground_height, measure_height, scene_stats.
    * Weltprofil: probe_world + fill_region nach Messwert-Regel
      (Wasser y1-2, sonst y1 oder y1+2, kein Raten, keine Tiefen-Ueberschreibung).
    * Union mit Vorpruefung: anchored, Eltern, Groessen, Dreiecks-Budget,
      "einer statt vierzig"-Vorschlag, saubere SOLID_REFUSED-Fehler.
    * Studio-Run-Simulation: sim_status/sim_stop koennen bestehende Sessions
      lesen/beenden; neue Starts ueber sim_start sind gesperrt, weil Studio Run
      EditModeActive=false setzt. BENUTZER-Aktionen werden gemeldet; ein vom
      Nutzer gestarteter Play/F5-Test blockiert weiterhin.
    * Fehler als Klassen (codes) statt Freitext: BAD_ARGS, REF_NOT_FOUND,
      BUDGET_EXCEEDED, SIM_DISABLED, SIM_STOP_NEEDS_USER, SOLID_REFUSED, REGION_LIMIT, ...
    * Dokumentationen auf Abruf (get_docs) und automatisch am Sitzungsstart.
============================================================================]]

local HttpService        = game:GetService("HttpService")
local Selection          = game:GetService("Selection")
local RunService         = game:GetService("RunService")
