    lastTick = os.time(),
    runningCommandId = nil,
    runningTool = nil,
    startedAt = 0,
    dispatcherBusy = false,
    queueDepth = 0,
    resultOutbox = {},
    ackOutbox = {},
    lastAckAt = 0,
}
local cancelRequests = {}
local seenCommandIds = {}
-- Version 7.0.5: Ergebnisse der zuletzt ausgeführten Befehle. Wird derselbe
-- commandId nach einem Reconnect/Plugin-Neuladen erneut zugestellt, schickt das
-- Plugin das GESPEICHERTE Ergebnis noch einmal -statt den Befehl ein zweites Mal
-- auszuführen (weder doppelt ausführen noch verlieren).
local completedResults = {}
local completedOrder = {}
local completedResultLimit = 48
local function rememberCompletedResult(commandId, result)
    local id = tostring(commandId)
    if completedResults[id] == nil then table.insert(completedOrder, id) end
    completedResults[id] = result
    while #completedOrder > completedResultLimit do
        local oldest = table.remove(completedOrder, 1)
        if oldest then completedResults[oldest] = nil end
    end
end
local function getCompletedResult(commandId)
    return completedResults[tostring(commandId)]
end
local connectedEventSessionId = nil
local defaultContext = "server"   -- fuer Laufzeit-Befehle im Play-Modus
local userPlaytestActive = false       -- vom Nutzer gestarteter/aktiv gespielter Test
-- Version 3.8: Zuverlaessige Play-Erkennung + Nutzer-Aktivitaet im Editor
local bridgeCommandActive = false      -- laeuft gerade ein Bridge-Befehl? (unterdrueckt Nutzer-Meldungen)
local lastEditCamCFrame = nil          -- Kamera-Position im Edit-Modus (Play-Here-Erkennung + Start)
local lastEditCamPos = nil             -- zur Bewegungserkennung (Nutzer navigiert im Editor)
local lastUserActiveNotice = 0         -- os.clock() der letzten Nutzer-Aktivitaets-Meldung

-- Version 7.0.3: LAUFZEITDIAGNOSTIK (Leistung), standardmaessig AUS.
-- Sie wird nur aktiv, wenn die Bridge sie in den Einstellungen einschaltet;
-- dann fordert die Bridge sie im Poll-Ergebnis an ("perf": true) und bekommt
-- die Zaehler mit der NAECHSTEN Poll-Anfrage zurueck - ohne eine einzige
-- zusaetzliche HTTP-Anfrage und ohne Logging pro Tick. Die Zaehler sind
-- Interval-Werte: perfReport() liest sie und setzt sie zurueck.
local perfWanted = false
local perfStats = {
    since = os.clock(), requests = 0, polls = 0, waitMs = 0, pollMs = 0,
    gapMs = 0, cmds = 0, hbFallback = 0, quiet = false,
}

local function perfReport()
    local now = os.clock()
    local periodMs = math.floor((now - perfStats.since) * 1000)
    if periodMs < 1 then periodMs = 1 end
    local out = {
        periodMs  = periodMs,
        requests  = perfStats.requests,
        polls     = perfStats.polls,
        waitMs    = perfStats.waitMs,
        pollMs    = perfStats.pollMs,
        gapMs     = perfStats.gapMs,
        cmds      = perfStats.cmds,
        hbFallback = perfStats.hbFallback,
        quiet     = perfStats.quiet and 1 or 0,
    }
    perfStats.since = now
    perfStats.requests = 0
    perfStats.polls = 0
    perfStats.waitMs = 0
    perfStats.pollMs = 0
    perfStats.gapMs = 0
    perfStats.cmds = 0
    perfStats.hbFallback = 0
    return out
end

-- Der Plugin-Code bleibt in aktuellen Studio-Versionen im Edit-DataModel.
-- Der Session-Agent unten ist deshalb die verbindliche Sicht auf den echten Test.
