-- ---------------------------------------------------------------------------
-- HTTP
-- ---------------------------------------------------------------------------
local function post(path, payload)
    -- A transient empty/failed local response must not kill the session
    -- reporter. The live 4.0.3 run showed postFailCount climbing although
    -- the reporter itself was still alive. Retry once before reporting nil.
    for attempt = 1, 2 do
        perfStats.requests = perfStats.requests + 1
        local ok, response = pcall(function()
            return HttpService:RequestAsync({
                Url = BASE_URL .. path,
                Method = "POST",
                Headers = {
                    ["Content-Type"] = "application/json; charset=utf-8",
                    ["X-Arena-Plugin"] = ARENA_VERSION,
                },
                Body = HttpService:JSONEncode(payload),
            })
        end)
        if ok and response and response.Success and response.Body ~= "" then
            local decodedOk, decoded = pcall(function()
                return HttpService:JSONDecode(response.Body)
            end)
            if decodedOk then return decoded end
            lastPollError = "JSON-Dekodierfehler (" .. tostring(path) .. ")"
            pluginOutputError("Antwort von " .. tostring(path) .. " war kein gueltiges JSON: " .. tostring(decoded))
        elseif ok and response and not response.Success then
            lastPollError = "HTTP " .. tostring(response.StatusCode) .. " (" .. tostring(path) .. ")"
        end
        if attempt == 1 then task.wait(0.08) end
    end
    return nil
end

-- ---------------------------------------------------------------------------
-- Laufzeit-Zustand (Play / Run / Edit)
-- ---------------------------------------------------------------------------
local function currentContext()
    if RunService:IsRunning() then
        if RunService:IsServer() then
            return "server"
        end
        return "client"
    end
    return "edit"
end

local function currentMode()
    local runningNow = false
    pcall(function() runningNow = RunService:IsRunning() end)
    if not runningNow then
        local editNow = false
        pcall(function() editNow = RunService:IsEdit() end)
        if editNow then return "edit" end
        return "paused"
    end

    -- IsRunMode distinguishes the server-only Studio Run from a player Play/F5
    -- test. If this API is unavailable, report "unknown" instead of conflating
    -- the two modes.
    local isRunMode = nil
    pcall(function() isRunMode = RunService:IsRunMode() end)
    if isRunMode == true then return "run" end
    if isRunMode == false then return "play" end
    return "unknown"
end

local function currentPlayerCount()
    local count = 0
    pcall(function() count = #Players:GetPlayers() end)
    return count
end

local function playState()
    -- StudioTestService.EditModeActive is the oracle for leaving Edit mode;
    -- currentMode separately distinguishes Studio Run from player Play/F5.
    local editModeActive = nil
    if StudioTestService ~= nil then
        pcall(function() editModeActive = StudioTestService.EditModeActive end)
    end
    local sessionActive = testSessionActive()
    local mode = currentMode()
    if sessionActive and (mode == "edit" or mode == "paused") then mode = "unknown" end
    local context = currentContext()
    if sessionActive and context == "edit" then context = "session" end
    local isEdit = false
    local isServer = false
    local isClient = false
    pcall(function() isEdit = RunService:IsEdit() end)
    pcall(function() isServer = RunService:IsServer() end)
    pcall(function() isClient = RunService:IsClient() end)
    if sessionActive then isEdit = false end
    local playerCount = currentPlayerCount()
    return {
        running    = sessionActive,
        mode       = mode,
        context    = context,
        isEdit     = isEdit,
        isServer   = isServer,
        isClient   = isClient,
        playerCount = playerCount,
        sessionPlayers = playerCount,
        agentConnected = false,
        reporterActive = false,
        httpEnabled = readHttpEnabled(),
        userPlaytestActive = userPlaytestActive,
        startedByBridge = simStartedByBridge,
        simRunning = (sessionActive and simStartedByBridge == true) or false,
        simMode = sessionActive and mode or nil,
        editModeActive = editModeActive,
        sessionSnapshot = nil,
    }
end

-- ---------------------------------------------------------------------------
-- MITTEILUNGEN AN DIE KI (z.B. "der Benutzer hat den Test gestartet").
-- Frueh deklariert, damit sie auch in spaeter definierten, aber fruher
-- erzeugten Callbacks greift.
-- ---------------------------------------------------------------------------
local notices = {}
local noticeSeq = 0

local function addNotice(kind, message, data)
    noticeSeq = noticeSeq + 1
    local notice = { seq = noticeSeq, kind = kind, message = message, time = os.time(), data = data }
    table.insert(notices, notice)
    while #notices > 40 do table.remove(notices, 1) end
    -- Sofort an das Programm melden, damit die Bridge Bescheid weiss
    task.spawn(function()
        if sessionId then
            post("/plugin/event", { sessionId = sessionId, event = notice, state = playState() })
        end
    end)
    return notice
end

-- Frueh deklariert (Zuweisung kommt unten in "AUSFUEHRUNG").
local executeTool

-- ---------------------------------------------------------------------------
-- Ausgabefenster (Output) mitschreiben
-- ---------------------------------------------------------------------------
local outputBuffer = {}
local outputSeq = 0
local outputStart = 1     -- Index des ersten Eintrags im Ring
local errorCount = 0
local warningCount = 0

local function pushOutput(message, messageType, source)
    outputSeq = outputSeq + 1
    local entry = {
        seq     = outputSeq,
        time    = os.time(),
        message = tostring(message),
        type    = tostring(messageType or "Output"),
        source  = source or currentContext(),
    }
    if entry.type == "MessageError" or entry.type == "Error" then
        errorCount = errorCount + 1
    elseif entry.type == "MessageWarning" or entry.type == "Warning" then
        warningCount = warningCount + 1
    end
    outputBuffer[outputSeq] = entry
    if outputSeq - outputStart + 1 > ARENA_CFG.MAX_OUTPUT then
        local removeUntil = outputSeq - ARENA_CFG.MAX_OUTPUT
        for i = outputStart, removeUntil do
            outputBuffer[i] = nil
        end
        outputStart = removeUntil + 1
    end
end

local function shortType(messageType)
    local name = tostring(messageType)
    name = string.gsub(name, "^Enum%.MessageType%.", "")
    return name
end

pcall(function()
    for _, item in ipairs(LogService:GetLogHistory()) do
        pushOutput(item.message, shortType(item.messageType), "history")
    end
end)


LogService.MessageOut:Connect(function(message, messageType)
    pushOutput(message, shortType(messageType), currentContext())
end)

local function readOutput(options)
    options = options or {}
    local limit = tonumber(options.limit) or 200
    if limit > 2000 then limit = 2000 end
    local since = tonumber(options.since) or 0
    local filter = options.filter
    local wanted = nil
    if type(options.types) == "table" and #options.types > 0 then
        wanted = {}
        for _, name in ipairs(options.types) do
            wanted[string.lower(tostring(name))] = true
        end
    end
    local onlyErrors = options.onlyErrors == true

    local matches = {}
    for i = outputStart, outputSeq do
        local entry = outputBuffer[i]
        if entry and entry.seq > since then
            local keep = true
            if onlyErrors and entry.type ~= "MessageError" then keep = false end
            if keep and wanted and not wanted[string.lower(entry.type)] then keep = false end
            if keep and filter and filter ~= "" then
                local ok, found = pcall(function()
                    if options.regex == true then
                        return string.find(entry.message, filter) ~= nil
                    end
                    return string.find(string.lower(entry.message), string.lower(filter), 1, true) ~= nil
                end)
                if not ok or not found then keep = false end
            end
            if keep then
                table.insert(matches, entry)
            end
        end
    end

    local total = #matches
    local result = {}
    local startIndex = 1
    if total > limit then
        startIndex = total - limit + 1
    end
    for i = startIndex, total do
        table.insert(result, matches[i])
    end
    return {
        lines        = result,
        returned     = #result,
        matched      = total,
        cursor       = outputSeq,
        oldestStored = outputStart,
        errorCount   = errorCount,
        warningCount = warningCount,
        hint         = "Use cursor as 'since' on the next call to read only new lines.",
    }
end

-- ---------------------------------------------------------------------------
-- IDs UND REFERENZEN
-- Jedes Objekt bekommt beim ersten Kontakt eine stabile Id ("#42").
-- Damit sind 55 gleichnamige Parts eindeutig ansprechbar.
-- ---------------------------------------------------------------------------
local nextId = 0
local idToInstance = setmetatable({}, { __mode = "v" })
local instanceToId = setmetatable({}, { __mode = "k" })

local function idOf(inst)
    if inst == nil then return nil end
    local existing = instanceToId[inst]
    if existing then return existing end
    nextId = nextId + 1
    local id = "#" .. tostring(nextId)
    instanceToId[inst] = id
    idToInstance[id] = inst
    return id
end

local function pathOf(inst)
    if inst == nil then return nil end
    if inst == game then return "game" end
    local parts = {}
    local current = inst
    local guard = 0
    while current and current ~= game and guard < 200 do
        guard = guard + 1
        local name = current.Name
        local parent = current.Parent
        if parent then
            local sameName = 0
            local index = 0
            for _, child in ipairs(parent:GetChildren()) do
                if child.Name == name then
                    sameName = sameName + 1
                    if child == current then
                        index = sameName
                    end
                end
            end
            if sameName > 1 then
                name = name .. "[" .. tostring(index) .. "]"
            end
        end
        table.insert(parts, 1, name)
        current = parent
    end
    return "game." .. table.concat(parts, ".")
end

local function isAlive(inst)
    if inst == nil then return false end
    if inst == game then return true end
    local ok, result = pcall(function()
        return inst.Parent ~= nil or inst:IsDescendantOf(game)
    end)
    return ok and result == true
end

local function splitPathSegments(path)
    local segments = {}
    for segment in string.gmatch(path, "[^%.]+") do
        table.insert(segments, segment)
    end
    return segments
end

local function childByToken(parent, token)
    -- Erlaubt: Name, Name[2], Name#3 (3. Kind mit diesem Namen)
    local name, index = string.match(token, "^(.-)%[(%d+)%]$")
    if not name then
        name, index = string.match(token, "^(.-)#(%d+)$")
    end
    if name then
        local wanted = tonumber(index)
        local seen = 0
        for _, child in ipairs(parent:GetChildren()) do
            if child.Name == name then
                seen = seen + 1
                if seen == wanted then return child end
            end
        end
        return nil
    end
    return parent:FindFirstChild(token)
end

-- FIX 7.0.8: findByPath fehlte im 7.0.x-Plugin KOMPLETT - nur der Aufruf war
-- da. Dadurch lief JEDE Referenz, die kein "#id"/"id:"/"selection" und keine
-- Tabelle ist, in "attempt to call a nil value" und der Befehl endete als
-- RUNTIME_ERROR: get_tree, get_properties, get_bounds und viele andere waren
-- fuer immer kaputt. splitPathSegments/childByToken standen direkt daneben
-- bereit und werden hier endlich benutzt.
local function findByPath(path)
    if type(path) ~= "string" or path == "" then return nil end
    local segments = splitPathSegments(path)
    if #segments == 0 then return nil end
    local head = segments[1]
    local headLower = string.lower(head)
    local current = nil
    if headLower == "game" then
        current = game
    elseif headLower == "workspace" then
        current = Workspace
    else
        current = childByToken(game, head)
        if current == nil then
            -- Dienste (Workspace, Lighting, ReplicatedStorage, ...) sind Kinder
            -- von game, aber nicht immer schon angelegt - GetService erzwingt sie.
            local okService, service = pcall(function() return game:GetService(head) end)
            if okService then current = service end
        end
    end
    for index = 2, #segments do
        if current == nil then return nil end
        local nextInst = childByToken(current, segments[index])
        if nextInst == nil and current == game then
            -- Dienste koennen fehlen, solange sie niemand angefordert hat -
            -- GetService legt sie an (echtes Roblox liefert sie sonst als Kind).
            local okService, service = pcall(function() return game:GetService(segments[index]) end)
            if okService then nextInst = service end
        end
        current = nextInst
    end
    return current
end

-- FIX 3.2: Vorwaerts-Deklarationen (findMatches/resolveSelector stehen weiter
-- unten, MUSSSEN aber hier im Scope sein, damit resolveRef/resolveMany sie
-- als Upvalue und nicht als nil-Global sehen).
local findMatches
local resolveSelector

-- FIX 7.0.8: firstNonEmpty wurde in tools.get_properties/get_bounds schon
-- benutzt, BEVOR die Deklaration weiter unten kam. In Lua ist so ein Name
-- dann ein GLOBAL-Zugriff -> nil -> "attempt to call a nil value". Darum hier
-- die Vorwaerts-Deklaration (die Definition unten weist jetzt diesem Local zu).
local firstNonEmpty

-- Loest eine Referenz auf. Erlaubt sind:
--   "#42"                      -> Id
--   "game.Workspace.Part[3]"   -> Pfad mit Index
--   { id = "#42" }             -> Tabelle
--   { path = "game.Workspace" }
--   { query|tag|className }    -> Selektor (siehe resolveSelector)
--   "selection"                -> aktuelle Auswahl (erstes Objekt)
local function resolveRef(ref)
    if ref == nil then return nil, "Reference missing." end
    if typeof(ref) == "Instance" then return ref end

    if type(ref) == "table" then
        if ref.id then return resolveRef(ref.id) end
        if ref.path then return resolveRef(ref.path) end
        if ref.ref then return resolveRef(ref.ref) end
        -- FIX 3.2: Selektor-Referenzen (in der Doku angekündigt, jetzt funktionsfähig):
        --   { query = "door" }, { tag = "Door" }, { className = "Part", rootRef = "#50" }
        if ref.query or ref.tag or ref.className then
            local matches, selErr = resolveSelector(ref, 1)
            if matches then
                return matches[1]
            end
            return nil, selErr
        end
        return nil, "Reference table needs 'id', 'path' or a selector ({ query = ... }, { tag = ... }, { className = ..., rootRef = ... })."
    end

    local text = tostring(ref)
    if text == "" then return nil, "Reference is empty." end

    if string.sub(text, 1, 1) == "#" then
        local inst = idToInstance[text]
        if inst == nil then
            return nil, "Unknown id " .. text .. " (object was deleted or the plugin was reloaded). Use search/get_tree to get fresh ids."
        end
        if not isAlive(inst) then
            return inst, nil, true
        end
        return inst
    end
    if string.sub(text, 1, 3) == "id:" then
        return resolveRef("#" .. string.sub(text, 4))
    end
    if text == "selection" then
        local selected = Selection:Get()
        if #selected == 0 then return nil, "Selection is empty." end
        return selected[1]
    end

    local inst = findByPath(text)
    if inst == nil then
        return nil, "Path not found: " .. text
    end
    return inst
end

local function resolveMany(refs)
    local list = {}
    local errors = {}
    if refs == nil then return list, errors end
    if type(refs) ~= "table" or refs.id or refs.path or refs.query or refs.tag or refs.className then
        refs = { refs }
    end
    for _, ref in ipairs(refs) do
        if type(ref) == "table" and (ref.query or ref.tag or ref.className) then
            -- FIX 3.2: Selektor expandiert auf ALLE Treffer (max. 500).
            local matches, totalOrErr = resolveSelector(ref, 500)
            if matches then
                for _, inst in ipairs(matches) do
                    table.insert(list, inst)
                end
                if type(totalOrErr) == "number" and totalOrErr > 500 then
                    table.insert(errors, "Selector matched " .. tostring(totalOrErr) .. " objects - only the first 500 were used.")
                end
            else
                table.insert(errors, totalOrErr or "Selector matched nothing.")
            end
        else
            local inst, err = resolveRef(ref)
            if inst then
                table.insert(list, inst)
            else
                table.insert(errors, err or ("Could not resolve " .. tostring(ref)))
            end
        end
    end
    return list, errors
end

local function describeRef(inst)
    if inst == nil then return nil end
    return {
        id        = idOf(inst),
        name      = inst.Name,
        className = inst.ClassName,
        path      = pathOf(inst),
    }
end

-- ---------------------------------------------------------------------------
-- Werte kodieren / dekodieren
-- ---------------------------------------------------------------------------
local function encodeValue(value)
    local t = typeof(value)
    if t == "nil" or t == "string" or t == "number" or t == "boolean" then
        return value
    elseif t == "Vector3" then
        return { type = "Vector3", x = value.X, y = value.Y, z = value.Z }
    elseif t == "Vector2" then
        return { type = "Vector2", x = value.X, y = value.Y }
    elseif t == "Color3" then
        return { type = "Color3", r = value.R, g = value.G, b = value.B,
                 rgb = { math.floor(value.R * 255 + 0.5), math.floor(value.G * 255 + 0.5), math.floor(value.B * 255 + 0.5) } }
    elseif t == "CFrame" then
        local p = value.Position
        local rx, ry, rz = value:ToOrientation()
        return {
            type = "CFrame",
            position = { x = p.X, y = p.Y, z = p.Z },
            orientation = { x = math.deg(rx), y = math.deg(ry), z = math.deg(rz) },
            orientationRadians = { x = rx, y = ry, z = rz },
        }
    elseif t == "UDim2" then
        return { type = "UDim2", xScale = value.X.Scale, xOffset = value.X.Offset, yScale = value.Y.Scale, yOffset = value.Y.Offset }
    elseif t == "UDim" then
        return { type = "UDim", scale = value.Scale, offset = value.Offset }
    elseif t == "BrickColor" then
        return { type = "BrickColor", name = value.Name, number = value.Number }
    elseif t == "EnumItem" then
        return { type = "EnumItem", enum = tostring(value.EnumType), name = value.Name, value = tostring(value) }
    elseif t == "NumberRange" then
        return { type = "NumberRange", min = value.Min, max = value.Max }
    elseif t == "Rect" then
        return { type = "Rect", minX = value.Min.X, minY = value.Min.Y, maxX = value.Max.X, maxY = value.Max.Y }
    elseif t == "Instance" then
        return { type = "Instance", id = idOf(value), path = pathOf(value), className = value.ClassName, name = value.Name }
    elseif t == "ColorSequence" then
        local points = {}
        for _, keypoint in ipairs(value.Keypoints) do
            table.insert(points, { time = keypoint.Time, r = keypoint.Value.R, g = keypoint.Value.G, b = keypoint.Value.B })
        end
        return { type = "ColorSequence", keypoints = points }
    elseif t == "NumberSequence" then
        local points = {}
        for _, keypoint in ipairs(value.Keypoints) do
            table.insert(points, { time = keypoint.Time, value = keypoint.Value, envelope = keypoint.Envelope })
        end
        return { type = "NumberSequence", keypoints = points }
    elseif t == "table" then
        local copy = {}
        for key, item in pairs(value) do
            copy[key] = encodeValue(item)
        end
        return copy
    end
    return tostring(value)
end

local function decodeValue(value)
    if type(value) ~= "table" then
        return value
    end
    if value.type == nil then
        -- Kurzform fuer Vektoren: {x=,y=,z=}
        if value.x ~= nil and value.y ~= nil and value.z ~= nil then
            return Vector3.new(value.x, value.y, value.z)
        end
        if value.r ~= nil and value.g ~= nil and value.b ~= nil then
            if value.r > 1 or value.g > 1 or value.b > 1 then
                return Color3.fromRGB(value.r, value.g, value.b)
            end
            return Color3.new(value.r, value.g, value.b)
        end
        return value
    end
    if value.type == "Vector3" then
        return Vector3.new(value.x or 0, value.y or 0, value.z or 0)
    elseif value.type == "Vector2" then
        return Vector2.new(value.x or 0, value.y or 0)
    elseif value.type == "Color3" then
        if value.rgb then
            return Color3.fromRGB(value.rgb[1] or 0, value.rgb[2] or 0, value.rgb[3] or 0)
        end
        if (value.r or 0) > 1 or (value.g or 0) > 1 or (value.b or 0) > 1 then
            return Color3.fromRGB(value.r or 0, value.g or 0, value.b or 0)
        end
        return Color3.new(value.r or 0, value.g or 0, value.b or 0)
    elseif value.type == "CFrame" then
        local p = value.position or {}
        local o = value.orientation or {}
        local base = CFrame.new(p.x or 0, p.y or 0, p.z or 0)
        if value.orientationRadians then
            local r = value.orientationRadians
            return base * CFrame.fromOrientation(r.x or 0, r.y or 0, r.z or 0)
        end
        return base * CFrame.fromOrientation(math.rad(o.x or 0), math.rad(o.y or 0), math.rad(o.z or 0))
    elseif value.type == "UDim2" then
        return UDim2.new(value.xScale or 0, value.xOffset or 0, value.yScale or 0, value.yOffset or 0)
    elseif value.type == "UDim" then
        return UDim.new(value.scale or 0, value.offset or 0)
    elseif value.type == "BrickColor" then
        return BrickColor.new(value.name or "Medium stone grey")
    elseif value.type == "NumberRange" then
        return NumberRange.new(value.min or 0, value.max or value.min or 0)
    elseif value.type == "Rect" then
        return Rect.new(value.minX or 0, value.minY or 0, value.maxX or 0, value.maxY or 0)
    elseif value.type == "EnumItem" then
        local enumName = string.gsub(tostring(value.enum or ""), "^Enum%.", "")
        local ok, result = pcall(function()
            return Enum[enumName][value.name]
        end)
        if ok then return result end
        return nil
    elseif value.type == "Instance" then
        local inst = resolveRef(value.id or value.path)
        return inst
    elseif value.type == "ColorSequence" then
        local points = {}
        for _, keypoint in ipairs(value.keypoints or {}) do
            table.insert(points, ColorSequenceKeypoint.new(keypoint.time or 0, Color3.new(keypoint.r or 0, keypoint.g or 0, keypoint.b or 0)))
        end
        if #points >= 2 then return ColorSequence.new(points) end
        return nil
    elseif value.type == "NumberSequence" then
        local points = {}
        for _, keypoint in ipairs(value.keypoints or {}) do
            table.insert(points, NumberSequenceKeypoint.new(keypoint.time or 0, keypoint.value or 0, keypoint.envelope or 0))
        end
        if #points >= 2 then return NumberSequence.new(points) end
        return nil
    end
    return value.value
end

-- Setzt eine Eigenschaft und uebersetzt bequeme Kurzformen
-- (z.B. Material = "Neon", Color = {255,0,0}).
local function setProperty(inst, property, rawValue)
    local value = rawValue
    if type(rawValue) == "table" then
        if #rawValue == 3 and property ~= "Size" and (property == "Color" or property == "Color3" or string.find(property, "Color")) then
            value = Color3.fromRGB(rawValue[1], rawValue[2], rawValue[3])
        elseif #rawValue == 3 then
            value = Vector3.new(rawValue[1], rawValue[2], rawValue[3])
        else
            value = decodeValue(rawValue)
        end
    elseif type(rawValue) == "string" then
        local current = nil
        local okCurrent = pcall(function() current = inst[property] end)
        if okCurrent and typeof(current) == "EnumItem" then
            local enumType = tostring(current.EnumType)
            enumType = string.gsub(enumType, "^Enum%.", "")
            local okEnum, enumValue = pcall(function() return Enum[enumType][rawValue] end)
            if okEnum then value = enumValue end
        elseif okCurrent and typeof(current) == "BrickColor" then
            value = BrickColor.new(rawValue)
        elseif okCurrent and typeof(current) == "Color3" and string.sub(rawValue, 1, 1) == "#" then
            local hex = string.sub(rawValue, 2)
            local r = tonumber(string.sub(hex, 1, 2), 16) or 0
            local g = tonumber(string.sub(hex, 3, 4), 16) or 0
            local b = tonumber(string.sub(hex, 5, 6), 16) or 0
            value = Color3.fromRGB(r, g, b)
        end
    end

    local ok, err = pcall(function()
        inst[property] = value
    end)
    if not ok then
        return false, tostring(err)
    end
    return true
end

local commonProps = {
    "Name", "ClassName", "Archivable", "Parent",
    "Position", "Size", "Orientation", "CFrame", "Color", "BrickColor", "Material", "Transparency",
    "Reflectance", "Anchored", "CanCollide", "CanTouch", "CanQuery", "Massless", "Shape", "CastShadow",
    "Text", "TextColor3", "TextSize", "TextScaled", "Font", "BackgroundColor3", "BackgroundTransparency",
    "BorderSizePixel", "Visible", "Image", "ImageColor3", "ScaleType", "ZIndex", "AnchorPoint",
    "Enabled", "Value", "Volume", "SoundId", "Looped", "Playing", "PlaybackSpeed", "TimePosition",
    "Texture", "MeshId", "TextureID", "Scale", "Face", "Adornee", "Attachment0", "Attachment1",
    "Brightness", "Range", "Angle", "Health", "MaxHealth", "WalkSpeed", "JumpPower", "HipHeight",
    "PrimaryPart", "WorldPivot", "Disabled", "RunContext", "CollisionFidelity", "RenderFidelity",
}

local function readProps(inst, includeSource, includeAll)
    local props = {}
    local list = commonProps
    for _, prop in ipairs(list) do
        local ok, value = pcall(function() return inst[prop] end)
        if ok and value ~= nil then
            props[prop] = encodeValue(value)
        end
    end
    if includeSource and inst:IsA("LuaSourceContainer") then
        local ok, source = pcall(function() return inst.Source end)
        if ok then
            props.Source = source
            props.SourceLineCount = select(2, string.gsub(source, "\n", "\n")) + 1
        end
    elseif inst:IsA("LuaSourceContainer") then
        local ok, source = pcall(function() return inst.Source end)
        if ok then
            props.SourceBytes = #source
            props.SourceLineCount = select(2, string.gsub(source, "\n", "\n")) + 1
        end
    end
    local attrsOk, attrs = pcall(function() return inst:GetAttributes() end)
    if attrsOk then
        local safeAttrs = {}
        local hasAny = false
        for key, value in pairs(attrs) do
            safeAttrs[key] = encodeValue(value)
            hasAny = true
        end
        if hasAny then props.Attributes = safeAttrs end
    end
    local tagsOk, tags = pcall(function() return CollectionService:GetTags(inst) end)
    if tagsOk and #tags > 0 then
        props.Tags = tags
    end
    if includeAll then
        props._note = "Only common properties are listed. Use run_lua for exotic properties."
    end
    return props
end

-- ---------------------------------------------------------------------------
-- BAUM UND SUCHE
-- ---------------------------------------------------------------------------
local function treeNode(inst, depth, maxDepth, state, includeProperties, includeSource)
    if state.count >= state.maxNodes then
        state.truncated = true
        return nil
    end
    state.count = state.count + 1
    local item = {
        id         = idOf(inst),
        name       = inst.Name,
        className  = inst.ClassName,
        path       = pathOf(inst),
        childCount = #inst:GetChildren(),
    }
    if inst:IsA("BasePart") then
        item.position = { x = inst.Position.X, y = inst.Position.Y, z = inst.Position.Z }
        item.size = { x = inst.Size.X, y = inst.Size.Y, z = inst.Size.Z }
    end
    if inst:IsA("LuaSourceContainer") then
        local ok, source = pcall(function() return inst.Source end)
        if ok then
            item.sourceBytes = #source
            item.sourceLines = select(2, string.gsub(source, "\n", "\n")) + 1
        end
    end
    if includeProperties then
        item.properties = readProps(inst, includeSource, false)
    end
    if depth < maxDepth then
        item.children = {}
        for _, child in ipairs(inst:GetChildren()) do
            local childNode = treeNode(child, depth + 1, maxDepth, state, includeProperties, includeSource)
            if childNode then
                table.insert(item.children, childNode)
            end
            if state.truncated then break end
        end
    end
    return item
end

local function nameCollisions(parent, name)
    local count = 0
    for _, child in ipairs(parent:GetChildren()) do
        if child.Name == name then count = count + 1 end
    end
    return count
end

-- ---------------------------------------------------------------------------
-- SCRIPTE: LESEN, SUCHEN, PUNKTGENAU AENDERN
-- ---------------------------------------------------------------------------
local function hashString(text)
    -- kleiner, stabiler Hash (djb2) - dient nur zum Abgleich
    local hash = 5381
    for i = 1, #text do
        hash = (hash * 33 + string.byte(text, i)) % 4294967296
    end
    return string.format("%08x", hash) .. "-" .. tostring(#text)
end

local function splitLines(text)
    local lines = {}
    local position = 1
    while true do
        local newlineAt = string.find(text, "\n", position, true)
        if not newlineAt then
            table.insert(lines, string.sub(text, position))
            break
        end
        table.insert(lines, string.sub(text, position, newlineAt - 1))
        position = newlineAt + 1
    end
    return lines
end

local function joinLines(lines)
    return table.concat(lines, "\n")
end

local function lineOfOffset(text, offset)
    local line = 1
    for i = 1, math.min(offset, #text) do
        if string.byte(text, i) == 10 then line = line + 1 end
    end
    return line
end

local function findOccurrences(text, needle, plain)
    local hits = {}
    local position = 1
    local guard = 0
    while guard < 100000 do
        guard = guard + 1
        local from, to = string.find(text, needle, position, plain)
        if not from then break end
        table.insert(hits, { from = from, to = to, line = lineOfOffset(text, from) })
        position = to + 1
        if to < from then position = from + 1 end
    end
    return hits
end

-- Fuehrt eine einzelne Aenderung an einem Skripttext aus.
local function applyEdit(text, edit, report)
    local op = string.lower(tostring(edit.op or edit.mode or "replace"))

    if op == "replace" or op == "replaceall" or op == "regex" or op == "pattern" then
        local plain = not (op == "regex" or op == "pattern" or edit.regex == true or edit.pattern == true)
        local needle = edit.find or edit.old or edit.pattern or edit.search
        if needle == nil or needle == "" then
            return nil, "Edit needs 'find' (the text to replace)."
        end
        local replacement = edit.replace
        if replacement == nil then replacement = edit.new end
        if replacement == nil then replacement = "" end

        local hits = findOccurrences(text, needle, plain)
        if #hits == 0 then
            return nil, "Text not found: " .. string.sub(tostring(needle), 1, 120)
        end

        local wantAll = (op == "replaceall") or edit.all == true
        local occurrence = tonumber(edit.occurrence)
        if not wantAll and occurrence == nil and #hits > 1 then
            local lines = {}
            for _, hit in ipairs(hits) do table.insert(lines, hit.line) end
            return nil, "Ambiguous edit: '" .. string.sub(tostring(needle), 1, 60) .. "' occurs " .. tostring(#hits)
                .. " times (lines " .. table.concat(lines, ", ") .. "). Pass occurrence=<n> or all=true, or use a longer unique snippet."
        end

        if wantAll then
            local newText
            if plain then
                -- Zeichenweise ersetzen, damit Sonderzeichen keine Rolle spielen
                local pieces = {}
                local position = 1
                for _, hit in ipairs(hits) do
                    table.insert(pieces, string.sub(text, position, hit.from - 1))
                    table.insert(pieces, replacement)
                    position = hit.to + 1
                end
                table.insert(pieces, string.sub(text, position))
                newText = table.concat(pieces)
            else
                newText = string.gsub(text, needle, replacement)
            end
            table.insert(report, { op = "replaceAll", count = #hits, firstLine = hits[1].line })
            return newText
        end

        local index = occurrence or 1
        local hit = hits[index]
        if hit == nil then
            return nil, "Occurrence " .. tostring(index) .. " does not exist (found " .. tostring(#hits) .. ")."
        end
        local newText
        if plain then
            newText = string.sub(text, 1, hit.from - 1) .. replacement .. string.sub(text, hit.to + 1)
        else
            local replaced = string.gsub(string.sub(text, hit.from), needle, replacement, 1)
            newText = string.sub(text, 1, hit.from - 1) .. replaced
        end
        table.insert(report, { op = "replace", occurrence = index, line = hit.line })
        return newText
    end

    if op == "insertbefore" or op == "insertafter" then
        local needle = edit.find or edit.anchor
        if needle == nil or needle == "" then
            return nil, "Edit needs 'find' as anchor."
        end
        local hits = findOccurrences(text, needle, not (edit.regex == true))
        if #hits == 0 then
            return nil, "Anchor not found: " .. string.sub(tostring(needle), 1, 120)
        end
        local index = tonumber(edit.occurrence) or 1
        local hit = hits[index]
        if hit == nil then
            return nil, "Anchor occurrence " .. tostring(index) .. " does not exist."
        end
        local addition = tostring(edit.text or edit.insert or "")
        local newText
        if edit.inline == true then
            -- Genau an der Fundstelle einfuegen, ohne neue Zeile.
            if op == "insertbefore" then
                newText = string.sub(text, 1, hit.from - 1) .. addition .. string.sub(text, hit.from)
            else
                newText = string.sub(text, 1, hit.to) .. addition .. string.sub(text, hit.to + 1)
            end
        else
            -- Standard: zeilenweise einfuegen. Der neue Text kommt als eigene
            -- Zeile ueber bzw. unter die Zeile mit der Fundstelle - genau das
            -- erwartet man beim Einfuegen von Code.
            local lines = splitLines(text)
            local target = (op == "insertafter") and lineOfOffset(text, hit.to) or hit.line
            local additionLines = splitLines(addition)
            -- Einrueckung der Ankerzeile uebernehmen, wenn der neue Text keine hat.
            local indent = string.match(lines[target] or "", "^[ \t]*") or ""
            if indent ~= "" and string.match(additionLines[1] or "", "^[ \t]") == nil then
                for i = 1, #additionLines do
                    if additionLines[i] ~= "" then
                        additionLines[i] = indent .. additionLines[i]
                    end
                end
            end
            local out = {}
            for i = 1, #lines do
                if op == "insertbefore" and i == target then
                    for _, l in ipairs(additionLines) do table.insert(out, l) end
                end
                table.insert(out, lines[i])
                if op == "insertafter" and i == target then
                    for _, l in ipairs(additionLines) do table.insert(out, l) end
                end
            end
            newText = joinLines(out)
        end
        table.insert(report, {
            op = op,
            line = hit.line,
            mode = (edit.inline == true) and "inline" or "line",
        })
        return newText
    end

    if op == "replacelines" or op == "deletelines" or op == "insertafterline" or op == "insertbeforeline" then
        local lines = splitLines(text)
        local startLine = tonumber(edit.startLine or edit.line) or 1
        local endLine = tonumber(edit.endLine) or startLine
        if startLine < 1 then startLine = 1 end
        if endLine > #lines then endLine = #lines end
        if startLine > #lines + 1 then
            return nil, "startLine " .. tostring(startLine) .. " is beyond the end of the script (" .. tostring(#lines) .. " lines)."
        end

        if op == "replacelines" then
            local replacementLines = splitLines(tostring(edit.text or ""))
            local out = {}
            for i = 1, startLine - 1 do table.insert(out, lines[i]) end
            for _, line in ipairs(replacementLines) do table.insert(out, line) end
            for i = endLine + 1, #lines do table.insert(out, lines[i]) end
            table.insert(report, { op = "replaceLines", startLine = startLine, endLine = endLine, newLines = #replacementLines })
            return joinLines(out)
        elseif op == "deletelines" then
            local out = {}
            for i = 1, #lines do
                if i < startLine or i > endLine then table.insert(out, lines[i]) end
            end
            table.insert(report, { op = "deleteLines", startLine = startLine, endLine = endLine })
            return joinLines(out)
        else
            local additionLines = splitLines(tostring(edit.text or ""))
            local out = {}
            local anchor = startLine
            if op == "insertbeforeline" then anchor = startLine - 1 end
            for i = 1, math.min(anchor, #lines) do table.insert(out, lines[i]) end
            for _, line in ipairs(additionLines) do table.insert(out, line) end
            for i = math.min(anchor, #lines) + 1, #lines do table.insert(out, lines[i]) end
            table.insert(report, { op = op, atLine = anchor })
            return joinLines(out)
        end
    end

    if op == "append" then
        local addition = tostring(edit.text or "")
        table.insert(report, { op = "append", bytes = #addition })
        if #text > 0 and string.sub(text, -1) ~= "\n" then
            return text .. "\n" .. addition
        end
        return text .. addition
    end

    if op == "prepend" then
        local addition = tostring(edit.text or "")
        table.insert(report, { op = "prepend", bytes = #addition })
        if #addition > 0 and string.sub(addition, -1) ~= "\n" then
            return addition .. "\n" .. text
        end
        return addition .. text
    end

    if op == "replacefunction" then
        local name = tostring(edit.name or "")
        if name == "" then return nil, "replaceFunction needs 'name'." end
        local lines = splitLines(text)
        local startLine, indent = nil, ""
        for index, line in ipairs(lines) do
            local pattern = "^(%s*)[%w%s%.:_]-function%s+" .. string.gsub(name, "([%.%-%(%)%[%]%+%*%?%^%$%%])", "%%%1") .. "%s*%("
            local found = string.match(line, pattern)
            if found ~= nil then
                startLine = index
                indent = found
                break
            end
            local localPattern = "^(%s*)local%s+" .. string.gsub(name, "([%.%-%(%)%[%]%+%*%?%^%$%%])", "%%%1") .. "%s*=%s*function%s*%("
            found = string.match(line, localPattern)
            if found ~= nil then
                startLine = index
                indent = found
                break
            end
        end
        if startLine == nil then
            return nil, "Function '" .. name .. "' not found."
        end
        local endLine = nil
        for index = startLine + 1, #lines do
            if string.match(lines[index], "^" .. indent .. "end%f[%W]") then
                endLine = index
                break
            end
        end
        if endLine == nil then
            return nil, "Could not find the matching 'end' of function '" .. name .. "'. Use replaceLines instead."
        end
        local replacementLines = splitLines(tostring(edit.text or ""))
        local out = {}
        for i = 1, startLine - 1 do table.insert(out, lines[i]) end
        for _, line in ipairs(replacementLines) do table.insert(out, line) end
        for i = endLine + 1, #lines do table.insert(out, lines[i]) end
        table.insert(report, { op = "replaceFunction", name = name, startLine = startLine, endLine = endLine })
        return joinLines(out)
    end

    return nil, "Unknown edit op: " .. tostring(op)
end

local function previewAround(text, lineNumber, radius)
    local lines = splitLines(text)
    local from = math.max(1, lineNumber - radius)
    local to = math.min(#lines, lineNumber + radius)
    local out = {}
    for i = from, to do
        table.insert(out, string.format("%5d| %s", i, lines[i]))
    end
    return table.concat(out, "\n")
end

-- ---------------------------------------------------------------------------
-- BAUHILFE: Groessen, Ecken, Ausrichtung
-- ---------------------------------------------------------------------------
local function boundsOf(inst)
    if inst:IsA("BasePart") then
        return inst.CFrame, inst.Size
    end
    if inst:IsA("Model") then
        local ok, cframe, size = pcall(function()
            local c, s = inst:GetBoundingBox()
            return c, s
        end)
        if ok and cframe then
            return cframe, size
        end
    end
    local ok, cframe = pcall(function() return inst:GetPivot() end)
    if ok and cframe then
        return cframe, Vector3.new(0, 0, 0)
    end
    return nil, nil
end

local function setPivotOf(inst, cframe)
    if inst:IsA("BasePart") then
        inst.CFrame = cframe
        return true
    end
    local ok = pcall(function() inst:PivotTo(cframe) end)
    return ok
end

local function getPivotOf(inst)
    if inst:IsA("BasePart") then return inst.CFrame end
    local ok, cframe = pcall(function() return inst:GetPivot() end)
    if ok then return cframe end
    return nil
end

local function boundsInfo(inst)
    local cframe, size = boundsOf(inst)
    if cframe == nil then
        return { id = idOf(inst), path = pathOf(inst), note = "This instance has no geometry." }
    end
    local position = cframe.Position
    local half = size / 2
    return {
        id       = idOf(inst),
        name     = inst.Name,
        className = inst.ClassName,
        path     = pathOf(inst),
        center   = { x = position.X, y = position.Y, z = position.Z },
        size     = { x = size.X, y = size.Y, z = size.Z },
        min      = { x = position.X - half.X, y = position.Y - half.Y, z = position.Z - half.Z },
        max      = { x = position.X + half.X, y = position.Y + half.Y, z = position.Z + half.Z },
        top      = position.Y + half.Y,
        bottom   = position.Y - half.Y,
        cframe   = encodeValue(cframe),
    }
end

local FACE_VECTORS = {
    top    = Vector3.new(0, 1, 0),
    bottom = Vector3.new(0, -1, 0),
    front  = Vector3.new(0, 0, -1),
    back   = Vector3.new(0, 0, 1),
    left   = Vector3.new(-1, 0, 0),
    right  = Vector3.new(1, 0, 0),
}

-- Legt A auf/an eine Flaeche von B, mit Versatz von der Mitte aus.
local function placeOnFace(mover, target, face, offsetA, offsetB, gap, inside, matchRotation)
    local targetCFrame, targetSize = boundsOf(target)
    local moverCFrame, moverSize = boundsOf(mover)
    if targetCFrame == nil or moverCFrame == nil then
        return nil, "Both instances need geometry (BasePart or Model)."
    end
    face = string.lower(tostring(face or "top"))
    local normal = FACE_VECTORS[face]
    if normal == nil then
        return nil, "Unknown face '" .. face .. "'. Use top, bottom, front, back, left or right."
    end

    local targetHalf = (targetSize * normal).Magnitude / 2
    local moverHalf = (moverSize * normal).Magnitude / 2
    local distance = targetHalf + gap
    if inside then
        distance = targetHalf - moverHalf - gap
    else
        distance = distance + moverHalf
    end

    -- Achsen der Flaeche fuer den seitlichen Versatz
    local up = Vector3.new(0, 1, 0)
    if math.abs(normal.Y) > 0.9 then up = Vector3.new(0, 0, -1) end
    local right = normal:Cross(up).Unit
    local realUp = right:Cross(normal).Unit

    local worldNormal = targetCFrame:VectorToWorldSpace(normal)
    local worldRight = targetCFrame:VectorToWorldSpace(right)
    local worldUp = targetCFrame:VectorToWorldSpace(realUp)

    local position = targetCFrame.Position + worldNormal * distance + worldRight * (offsetA or 0) + worldUp * (offsetB or 0)

    local newCFrame
    if matchRotation then
        newCFrame = CFrame.fromMatrix(position, targetCFrame.RightVector, targetCFrame.UpVector)
    else
        local rotation = moverCFrame - moverCFrame.Position
        newCFrame = CFrame.new(position) * rotation
    end
    setPivotOf(mover, newCFrame)
    return {
        moved = describeRef(mover),
        target = describeRef(target),
        face = face,
        newPosition = { x = position.X, y = position.Y, z = position.Z },
        gap = gap,
    }
end

-- ---------------------------------------------------------------------------
-- CLIENT-AGENT
-- Im Play-Modus laeuft dieses Plugin im Server-Kontext. Fuer alles, was nur
-- der Client kennt (GUIs, Kamera, lokale Ausgaben), wird ein kleiner
-- LocalScript in den Spieler eingesetzt. Er wird nie mitgespeichert
-- (Archivable = false) und verschwindet mit dem Testlauf.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- SIMULATION (Run, ab 7.0.0)
-- Kein Reporter, kein Session-Agent, kein Client-Agent. Verbindliches Orakel
-- fuer "laeuft eine Simulation" ist allein StudioTestService.EditModeActive;
-- RunService:IsRunning wird nur als zweite, schwaechere Quelle gemeldet.
-- ---------------------------------------------------------------------------

local function waitForEditMode(wanted, seconds)
    local waited = 0
    while waited < (seconds or 20) do
        local value = nil
        if StudioTestService ~= nil then pcall(function() value = StudioTestService.EditModeActive end) end
        if value == wanted then return true, value end
        task.wait(0.15)
        waited = waited + 0.15
    end
    local value = nil
    if StudioTestService ~= nil then pcall(function() value = StudioTestService.EditModeActive end) end
    return value == wanted, value
end

local function collisionFidelityFrom(name)
    local ok, value = pcall(function() return Enum.CollisionFidelity[name or "Default"] end)
    if ok and value then return value end
    return Enum.CollisionFidelity.Default
end

local function renderFidelityFrom(name)
    local ok, value = pcall(function() return Enum.RenderFidelity[name or "Automatic"] end)
    if ok and value then return value end
    return Enum.RenderFidelity.Automatic
end

local function estimateTriangles(parts)
    local total = 0
    for _, part in ipairs(parts) do
        if part:IsA("PartOperation") then
            total = total + 4000
        elseif part:IsA("MeshPart") then
            total = total + 1500
        elseif part:IsA("BasePart") then
            local s = part.Size
            local biggest = math.max(s.X, s.Y, s.Z)
            total = total + 24 + math.floor(biggest / 8)
        end
    end
    return total
end

-- Wenn die Teile zu EINEM Block zusammenpassen: der guenstigere Weg ist
-- ein einzelner Part (kein Solid Modeling, kein Verlust der Einzelteile).
local function singleBlockSuggestion(parts)
    local minX, minY, minZ = math.huge, math.huge, math.huge
    local maxX, maxY, maxZ = -math.huge, -math.huge, -math.huge
    local volume = 0
    for _, part in ipairs(parts) do
        if not part:IsA("BasePart") or part:IsA("PartOperation") or part:IsA("MeshPart") then
            return nil
        end
        local s = part.Size
        volume = volume + s.X * s.Y * s.Z
        local c = part.CFrame.Position
        local half = s / 2
        if c.X - half.X < minX then minX = c.X - half.X end
        if c.Y - half.Y < minY then minY = c.Y - half.Y end
        if c.Z - half.Z < minZ then minZ = c.Z - half.Z end
        if c.X + half.X > maxX then maxX = c.X + half.X end
        if c.Y + half.Y > maxY then maxY = c.Y + half.Y end
        if c.Z + half.Z > maxZ then maxZ = c.Z + half.Z end
    end
    local boxVolume = (maxX - minX) * (maxY - minY) * (maxZ - minZ)
    if boxVolume > 0 and math.abs(volume - boxVolume) <= boxVolume * 0.05 then
        return {
            size = { x = maxX - minX, y = maxY - minY, z = maxZ - minZ },
            center = { x = (minX + maxX) / 2, y = (minY + maxY) / 2, z = (minZ + maxZ) / 2 },
            suggestion = "These parts tile into ONE solid block. A single Part of that size does the same job - no solid modeling cost, no one-way merge.",
        }
    end
    return nil
end

local function unionWarnings(parts, kind)
    local warnings = {
        "Solid modeling is one-way: after " .. kind .. " the individual parts are gone. You can no longer read or move them separately - use 'separate' to get them back (properties like colour per part may be lost).",
    }
    if #parts > ARENA_CFG.UNION_SOFT_LIMIT then
        table.insert(warnings, "You are combining " .. tostring(#parts) .. " parts. Large unions are hard to inspect and slow to render. Prefer several small unions grouped in a Model.")
    end
    local totalVolume = 0
    for _, part in ipairs(parts) do
        if part:IsA("BasePart") then
            totalVolume = totalVolume + (part.Size.X * part.Size.Y * part.Size.Z)
        end
    end
    if totalVolume > 200000 then
        table.insert(warnings, "The combined volume is very large. Consider building with plain parts instead - unions of huge geometry hurt performance.")
    end
    return warnings
end

-- Vorpruefung: liefert warnings (Tabelle) oder einen Fehler (code, message, extra).
local function precheckSolid(parts, minimum, args)
    if #parts < minimum then
        return nil, "BAD_ARGS", "Need at least " .. tostring(minimum) .. " parts.", nil
    end
    for _, part in ipairs(parts) do
        if not part:IsA("BasePart") then
            return nil, "BAD_ARGS", "'" .. part.Name .. "' (" .. part.ClassName .. ") is not a BasePart.", nil
        end
    end
    local warnings = {}
    if #parts > ARENA_CFG.UNION_HARD_LIMIT and args.force ~= true then
        return nil, "UNION_BUDGET",
            "Refusing to combine " .. tostring(#parts) .. " parts at once (limit " .. tostring(ARENA_CFG.UNION_HARD_LIMIT)
            .. "). Build in smaller groups so the result stays editable, or pass force=true if you really want this.",
            nil
    end

    -- Anchored: Solid Modeling braucht stehende Teile
    local unanchored = {}
    for _, part in ipairs(parts) do
        if not part.Anchored then table.insert(unanchored, part.Name) end
    end
    if #unanchored > 0 then
        if args.fixAnchored == true then
            for _, part in ipairs(parts) do part.Anchored = true end
            table.insert(warnings, "Anchored " .. tostring(#unanchored) .. " unanchored part(s) (fixAnchored=true): " .. table.concat(unanchored, ", "))
        else
            return nil, "UNION_PRECHECK",
                "These parts are NOT anchored and will fall before/during the solid operation: " .. table.concat(unanchored, ", ")
                .. ". Pass fixAnchored=true to anchor them first (recommended) or anchor them yourself.",
                { parts = unanchored }
        end
    end

    -- Gleicher Parent (Warnung - das Ergebnis kommt in den Parent des ersten Teils)
    local parents = {}
    for _, part in ipairs(parts) do
        if part.Parent then parents[tostring(part.Parent:GetFullName())] = true end
    end
    local parentCount = 0
    for _ in pairs(parents) do parentCount = parentCount + 1 end
    if parentCount > 1 then
        table.insert(warnings, "The parts live in DIFFERENT parents. The result will be placed in the parent of the first part - move the others first if that is not intended.")
    end

    -- Groessen
    local sizeIssues = {}
    for _, part in ipairs(parts) do
        local s = part.Size
        local biggest = math.max(s.X, s.Y, s.Z)
        local smallest = math.min(s.X, s.Y, s.Z)
        if biggest > 500 then table.insert(sizeIssues, part.Name .. " is very large (" .. tostring(biggest) .. " studs)") end
        if smallest < 0.05 then table.insert(sizeIssues, part.Name .. " is extremely thin") end
    end
    if #sizeIssues > 0 then
        table.insert(warnings, "Size warnings: " .. table.concat(sizeIssues, "; ") .. ".")
    end

    -- Dreiecks-Budget
    local triangles = estimateTriangles(parts)
    if triangles > ARENA_CFG.UNION_TRIANGLE_REFUSE and args.force ~= true then
        return nil, "UNION_BUDGET",
            "Estimated " .. tostring(triangles) .. " triangles - above the refusal limit of " .. tostring(ARENA_CFG.UNION_TRIANGLE_REFUSE)
            .. " (the result would be slow to render and nearly impossible to edit). Build in smaller groups, or pass force=true.",
            { estimatedTriangles = triangles, limit = ARENA_CFG.UNION_TRIANGLE_REFUSE }
    end
    if triangles > ARENA_CFG.UNION_TRIANGLE_WARN then
        table.insert(warnings, "Estimated " .. tostring(triangles) .. " triangles (warning limit " .. tostring(ARENA_CFG.UNION_TRIANGLE_WARN)
            .. ") - expect slow rendering. Fewer parts per union is much cheaper.")
    end

    -- Guenstigere Alternative?
    local cheaper = singleBlockSuggestion(parts)
    if cheaper then
        table.insert(warnings, cheaper.suggestion)
    end

    local extra = {}
    extra.estimatedTriangles = triangles
    if cheaper then extra.cheaperAlternative = cheaper end
    return warnings, nil, nil, extra
end


-- ---------------------------------------------------------------------------
-- JOBS UND PERSISTENTER LUA-WORKER
-- Lange Arbeit laeuft als Job im Hintergrund weiter (Timeout koennen nichts
-- toeten). run_lua und Jobs teilen sich EINE persistente Lua-Umgebung:
-- Helfer aus einem frueheren Call (ohne "local") sind spaeter sichtbar.
-- ---------------------------------------------------------------------------
local jobs = {}
local jobSeq = 0

local function jobSnapshot(job)
    return {
        id         = job.id,
        name       = job.name,
        status     = job.status,
        progress   = job.progress,
        message    = job.message,
        startedAt  = job.startedAt,
        finishedAt = job.finishedAt,
        ageSeconds = job.finishedAt and (os.time() - job.startedAt) or (os.time() - job.startedAt),
    }
end

local function jobsCount()
    local n = 0
    for _ in pairs(jobs) do n = n + 1 end
    return n
end

local function newJob(name, fn)
    jobSeq = jobSeq + 1
    local jobId = "job_" .. tostring(jobSeq)
    local job = {
        id = jobId,
        name = name or "job",
        status = "running",
        progress = 0,
        message = "gestartet",
        startedAt = os.time(),
        finishedAt = nil,
        cancelled = false,
        result = nil,
        error = nil,
        errorCode = nil,
    }
    jobs[jobId] = job
    -- Alte, fertige Jobs raumen (laufende bleiben immer erhalten).
    while true do
        local oldest = nil
        local oldestTime = 0
        for id, j in pairs(jobs) do
            if j.status ~= "running" then
                local t = j.finishedAt or 0
                if oldest == nil or t < oldestTime then
                    oldest = id
                    oldestTime = t
                end
            end
        end
        if oldest and jobsCount() > ARENA_CFG.MAX_JOBS then
            jobs[oldest] = nil
        else
            break
        end
    end

    local function jobProgress(percent, message)
        job.progress = tonumber(percent) or job.progress
        if message then job.message = tostring(message) end
    end
    local function jobCancelled()
        return job.cancelled
    end
    local jobApi = { id = jobId, progress = jobProgress, cancelled = jobCancelled }

    task.spawn(function()
        local okRun, result = pcall(fn, jobApi)
        job.finishedAt = os.time()
        if job.cancelled then
            job.status = "cancelled"
        elseif okRun then
            job.status = "done"
            job.result = result
        else
            job.status = "error"
            job.error = tostring(result)
        end
    end)
    return jobId
end

local function jobsList()
    local list = {}
    for id, job in pairs(jobs) do
        table.insert(list, jobSnapshot(job))
    end
    table.sort(list, function(a, b) return (a.startedAt or 0) > (b.startedAt or 0) end)
    return list
end

-- ---------------------------------------------------------------------------
-- Persistente Lua-Umgebung (run_lua + Jobs teilen sich diese)
-- ---------------------------------------------------------------------------
local function makeLuaEnv()
    return setmetatable({}, { __index = _G })
end
local luaEnv = makeLuaEnv()

local function luaEnvKeys()
    local keys = {}
    for key, _ in pairs(luaEnv) do
        table.insert(keys, tostring(key))
    end
    table.sort(keys)
    return keys
end

-- Fuer lange Arbeit, die als Job laeuft: der Job meldet Fortschritt und
-- prueft job:cancelled() in Schleifen (Lua-Threads lassen sich nicht hart toeten).
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- WELT-MESSWERKZEUGE
-- Hoehe kommt AUSSCHLIESSLICH per Raycast (ReadVoxels-Indexmathematik ist
-- in diesem Place falsch). Neue Geometrie wird erst zurueckgegeben, wenn
-- sie messbar ist (FillRegion/Create sind nicht in derselben Frame sichtbar).
-- ---------------------------------------------------------------------------
-- FIX 3.2: CanCollide/CanQuery/CanTouch sind Properties von BasePart, KEINE
-- Members von RaycastParams. Die Zuweisung warf in aktuellen Studio-Versionen
-- "X is not a valid member of RaycastParams" und crashte damit JEDE BasePart-
-- Erstellung (create_instance, bulk_create, clone_instance, fill_region).
local function measureRayParams(excludeRefs)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = excludeRefs or {}
    return params
end

local function overlapParamsNew(excludeRefs)
    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = excludeRefs or {}
    return params
end

local function isWaterLike(inst)
    if inst == nil then return false end
    local okM, material = pcall(function() return inst.Material end)
    if okM and material == Enum.Material.Water then return true end
    local okT, transp = pcall(function() return inst.Transparency end)
    local okS, size = pcall(function() return inst.Size end)
    if okT and okS and transp >= 0.4 and (size.X >= 50 or size.Z >= 50) then
        return true
    end
    return false
end

-- Warten, bis (neue) Geometrie auf Raycasts antwortet.
local function waitMeasurableCore(insts, maxSeconds)
    maxSeconds = tonumber(maxSeconds) or 2
    local startAt = os.clock()
    local frames = 0
    while true do
        frames = frames + 1
        local allReady = true
        for _, inst in ipairs(insts) do
            local okAlive, alive = pcall(function() return inst and inst.Parent ~= nil end)
            if not (okAlive and alive) then
                allReady = false
                break
            end
            local cframe, size = boundsOf(inst)
            local ready = false
            if cframe then
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Include
                params.FilterDescendantsInstances = { inst }
                local hit = Workspace:Raycast(cframe.Position + Vector3.new(0, size.Y / 2 + 5, 0), Vector3.new(0, -size.Y - 10, 0), params)
                if hit and (hit.Instance == inst or hit.Instance:IsDescendantOf(inst)) then ready = true end
            end
            if not ready then
                allReady = false
                break
            end
        end
        if allReady then
            return { ready = true, frames = frames, waitedMs = math.floor((os.clock() - startAt) * 1000) }
        end
        if os.clock() - startAt >= maxSeconds then
            return {
                ready = false,
                frames = frames,
                waitedMs = math.floor((os.clock() - startAt) * 1000),
                note = "New geometry did not answer raycasts immediately. Call verify_measurable on these ids before measuring again.",
            }
        end
        task.wait(0.05)
    end
end

-- FIX 3.2: Messfehler duerfen niemals die Create/Bulk-Ergebnisse zerstoeren.
-- Zuvor crashte ein einziger kaputter Raycast-Weg den ganzen Tool-Call,
-- obwohl die Instanzen längst erstellt waren (die Ids gingen verloren).
local function waitMeasurable(insts, maxSeconds)
    local okRun, result = pcall(waitMeasurableCore, insts or {}, maxSeconds)
    if okRun and type(result) == "table" then
        return result
    end
    return { ready = false, frames = 0, waitedMs = 0, note = "Geometry verification unavailable: " .. tostring(result) }
end

-- ---------------------------------------------------------------------------
-- FORMEN MESSEN (kein Raten): senkrechte Raycasts ueber die Oberflaeche,
-- 5x5-Raster, nur Treffer auf den Teil selbst. Ergebnis pro Instanz gecacht
-- (automatisch neu gemessen bei geaenderter Position/Groesse/Form).
-- ---------------------------------------------------------------------------
local shapeCache = setmetatable({}, { __mode = "k" })

local function shapeKeyOf(inst)
    local cframe, size = boundsOf(inst)
    if not cframe or size == nil then return nil end
    return cframe.Position.X .. "," .. cframe.Position.Y .. "," .. cframe.Position.Z .. "|"
        .. size.X .. "," .. size.Y .. "," .. size.Z .. "|" .. tostring(inst.Shape)
end

local function measureShape(inst)
    if inst == nil or not inst:IsA("BasePart") then return nil end
    local key = shapeKeyOf(inst)
    if key == nil then return nil end
    local cached = shapeCache[inst]
    if cached and cached.key == key then return cached.value end

    local cframe, size = boundsOf(inst)
    local top = cframe.Position.Y + size.Y / 2
    local samples = {}
    for ix = -2, 2 do
        for iz = -2, 2 do
            local x = cframe.Position.X + (ix / 2) * (size.X / 2)
            local z = cframe.Position.Z + (iz / 2) * (size.Z / 2)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Include
            params.FilterDescendantsInstances = { inst }
            local hit = Workspace:Raycast(Vector3.new(x, top + 2000, z), Vector3.new(0, -4000, 0), params)
            if hit then
                table.insert(samples, { x = x, z = z, y = hit.Position.Y, ix = ix, iz = iz })
            end
        end
    end

    local value
    if #samples == 0 then
        value = { shape = tostring(inst.Shape), note = "No surface hit from above - could not measure this shape." }
    else
        local minY, maxY = math.huge, -math.huge
        for _, s in ipairs(samples) do
            if s.y < minY then minY = s.y end
            if s.y > maxY then maxY = s.y end
        end
        local flatTol = math.max(0.15, size.Y * 0.01)
        local shapeName = tostring(inst.Shape)
        if (maxY - minY) < flatTol then
            local cornerHit = false
            for _, s in ipairs(samples) do
                if math.abs(s.ix) == 2 and math.abs(s.iz) == 2 then cornerHit = true end
            end
            if shapeName == "Cylinder" and not cornerHit then
                value = {
                    shape = "Cylinder", flatTop = true, axis = "vertical", topY = maxY,
                    note = "Cylinder with a VERTICAL length axis: the flat caps point up and down, the length direction is the part's local Y axis (top/bottom).",
                }
            elseif shapeName == "Ball" then
                value = { shape = "Ball", flatTop = false, note = "Sphere: no faces, no length axis. 'point_at' steuert die -Z-Richtung (front)." }
            else
                value = { shape = shapeName, flatTop = true, topY = maxY, note = "Flat top - an axis-aligned block, no hidden orientation." }
            end
        else
            local high = {}
            for _, s in ipairs(samples) do
                if maxY - s.y <= flatTol + 0.01 then table.insert(high, s) end
            end
            if #high >= 2 then
                local ax, az = high[1].x, high[1].z
                local bx, bz = high[#high].x, high[#high].z
                local axisVec = Vector3.new(bx - ax, 0, bz - az)
                if axisVec.Magnitude < 0.01 then
                    value = {
                        shape = shapeName, highPoint = { x = ax, z = az }, topY = maxY, bottomY = minY,
                        note = "Single highest point - if this is a Cylinder it lies horizontally (length axis is horizontal).",
                    }
                else
                    local highEdge = { a = { x = ax, z = az }, b = { x = bx, z = bz } }
                    if shapeName == "Wedge" then
                        local midX, midZ, n = 0, 0, 0
                        for _, s in ipairs(samples) do
                            if maxY - s.y > flatTol + 0.01 then midX = midX + s.x; midZ = midZ + s.z; n = n + 1 end
                        end
                        if n > 0 then
                            midX, midZ = midX / n, midZ / n
                            local toLow = Vector3.new(midX - (ax + bx) / 2, 0, midZ - (az + bz) / 2)
                            if toLow.Magnitude > 0.01 then
                                local slopeDir = toLow.Unit
                                value = {
                                    shape = "Wedge", highEdge = highEdge, slopeDir = { x = slopeDir.X, z = slopeDir.Z },
                                    topY = maxY, bottomY = minY,
                                    note = "Wedge (ramp): HIGH edge from (" .. string.format("%.1f", ax) .. ", " .. string.format("%.1f", az)
                                        .. ") to (" .. string.format("%.1f", bx) .. ", " .. string.format("%.1f", bz)
                                        .. "). The slope goes DOWN toward (" .. string.format("%.2f", slopeDir.X) .. ", " .. string.format("%.2f", slopeDir.Z) .. ").",
                                }
                            else
                                value = {
                                    shape = "Wedge", highEdge = highEdge, topY = maxY, bottomY = minY,
                                    note = "Wedge (ramp): HIGH edge from (" .. string.format("%.1f", ax) .. ", " .. string.format("%.1f", az)
                                        .. ") to (" .. string.format("%.1f", bx) .. ", " .. string.format("%.1f", bz) .. ").",
                                }
                            end
                        else
                            value = {
                                shape = "Wedge", highEdge = highEdge, topY = maxY, bottomY = minY,
                                note = "Wedge (ramp): HIGH edge from (" .. string.format("%.1f", ax) .. ", " .. string.format("%.1f", az)
                                    .. ") to (" .. string.format("%.1f", bx) .. ", " .. string.format("%.1f", bz) .. ").",
                            }
                        end
                    else
                        value = {
                            shape = shapeName, highEdge = highEdge, topY = maxY, bottomY = minY,
                            note = shapeName .. ": the highest points form a line from (" .. string.format("%.1f", ax) .. ", " .. string.format("%.1f", az)
                                .. ") to (" .. string.format("%.1f", bx) .. ", " .. string.format("%.1f", bz)
                                .. ") - that line is the LENGTH axis of the shape (e.g. a horizontal Cylinder).",
                        }
                    end
                end
            else
                value = {
                    shape = shapeName, topY = maxY, bottomY = minY,
                    note = "The top surface is not flat and no clear high edge was measured. Use describe_orientation for the exact face directions.",
                }
            end
        end
    end
    shapeCache[inst] = { key = key, value = value }
    return value
end

-- Klartext fuer eine Welt-Richtung (0° = -Z = weg von der Standardkamera).
local function dirHeading(v)
    local h = Vector3.new(v.X, 0, v.Z)
    if h.Magnitude < 0.05 then
        if v.Y > 0.5 then return "straight UP"
        elseif v.Y < -0.5 then return "straight DOWN"
        else return "flat (no clear direction)" end
    end
    local angle = math.atan2(h.X, -h.Z) * 180 / math.pi
    if angle < 0 then angle = angle + 360 end
    local names = {
        "north (away from the default camera)",
        "north-east",
        "east (toward +X)",
        "south-east",
        "south (toward the default camera)",
        "south-west",
        "west (toward -X)",
        "north-west",
    }
    local index = math.floor(angle / 45 + 0.5)
    if index > 8 then index = 8 end
    return string.format("%s (heading %.0f degrees from north)", names[index], angle)
end

local function facesOf(cframe)
    return {
        front  = dirHeading(cframe:VectorToWorldSpace(Vector3.new(0, 0, -1))),
        back   = dirHeading(cframe:VectorToWorldSpace(Vector3.new(0, 0, 1))),
        left   = dirHeading(cframe:VectorToWorldSpace(Vector3.new(-1, 0, 0))),
        right  = dirHeading(cframe:VectorToWorldSpace(Vector3.new(1, 0, 0))),
        top    = dirHeading(cframe:VectorToWorldSpace(Vector3.new(0, 1, 0))),
        bottom = dirHeading(cframe:VectorToWorldSpace(Vector3.new(0, -1, 0))),
    }
end

-- ---------------------------------------------------------------------------
-- WERKZEUGE
-- ---------------------------------------------------------------------------
local tools = {}

local function ok(result, warnings)
    return { ok = true, result = result, warnings = warnings }
end

local function fail(message, extra)
    local response = { ok = false, error = message }
    if extra then
        for key, value in pairs(extra) do response[key] = value end
    end
    return response
end

-- Fehler mit Code: die KI reagiert auf den code, nicht auf den Text.
local function failCode(code, message, extra)
    local response = { ok = false, code = code, error = message }
    if extra then
        for key, value in pairs(extra) do response[key] = value end
    end
    return response
end

local function waypoint(name)
    if ChangeHistoryService == nil then return end
    pcall(function() ChangeHistoryService:SetWaypoint("Arena: " .. tostring(name)) end)
end

-- ------------------------- Informationen -----------------------------------
tools.get_place_info = function()
    local state = playState()
    state.modeInfo = {
        edit      = "permanent building and one-off edit-mode script checks (compile_check/run_lua)",
        run       = "sim_start is disabled. Its former Studio Run implementation ran physics/server scripts without a player/client but exited Edit mode (EditModeActive=false); no Play/F5 test",
    }
    return ok({
        name       = game.Name,
        placeId    = game.PlaceId,
        gameId     = game.GameId,
        creatorId  = game.CreatorId,
        rootPath   = "game",
        pluginVersion = ARENA_VERSION,
        state      = state,
        capabilities = capabilities,
    })
end

tools.bridge_info = tools.get_place_info

tools.get_tree = function(args)
    local root, err = resolveRef(args.rootRef or args.rootPath or args.ref or "game")
    if not root then return fail(err) end
    local state = { count = 0, maxNodes = tonumber(args.maxNodes) or 3000, truncated = false }
    local node = treeNode(root, 0, tonumber(args.maxDepth) or 6, state, args.includeProperties == true, args.includeSource == true)
    local warnings = nil
    if state.truncated then
        warnings = { "Tree was cut off at " .. tostring(state.maxNodes) .. " nodes. Read smaller sub-trees (rootRef) or raise maxNodes." }
    end
    return ok({ tree = node, nodeCount = state.count, truncated = state.truncated }, warnings)
end

-- FIX 3.2: Gemeinsamer Suchkern - wird von tools.search UND von den
-- Selektor-Referenzen { query= } / { tag= } / { className=, rootRef= } benutzt.
-- (Zuweisung an die Vorwaerts-Deklaration ueben, damit alle Funktionen im
-- Chunk dasselbe Upvalue sehen.)
findMatches = function(root, query, className, tag, limit, exact)
    local matches = {}
    local total = 0
    local q = string.lower(tostring(query or ""))
    local list = root:GetDescendants()
    for _, inst in ipairs(list) do
        local nameMatch = true
        if q ~= "" then
            local lowerName = string.lower(inst.Name)
            if exact then
                nameMatch = (lowerName == q)
            else
                nameMatch = string.find(lowerName, q, 1, true) ~= nil
            end
        end
        local classMatch = true
        if className then
            local isOk, isType = pcall(function() return inst:IsA(className) end)
            classMatch = (inst.ClassName == className) or (isOk and isType)
        end
        local tagMatch = true
        if tag then
            local tagOk, hasTag = pcall(function() return CollectionService:HasTag(inst, tag) end)
            tagMatch = tagOk and hasTag
        end
        if nameMatch and classMatch and tagMatch then
            total = total + 1
            if #matches < limit then
                table.insert(matches, inst)
            end
        end
    end
    return matches, total
end

-- Loest eine Selektor-Referenz auf eine Liste von Instanzen auf.
-- Erfolg: (InstanzListe, Gesamtzahl). Fehler: (nil, Fehlermeldung).
resolveSelector = function(ref, limit)
    limit = limit or 500
    local root = game
    if ref.rootRef or ref.rootPath then
        local r, err = resolveRef(ref.rootRef or ref.rootPath)
        if r then
            root = r
        else
            return nil, "Selector rootRef not found: " .. tostring(err)
        end
    end
    local matches, total = findMatches(root, ref.query, ref.className, ref.tag, limit, ref.exact == true)
    if #matches == 0 then
        return nil, "Selector matched nothing."
    end
    return matches, total
end

tools.search = function(args)
    local root, err = resolveRef(args.rootRef or args.rootPath or "game")
    if not root then return fail(err) end
    local query = string.lower(tostring(args.query or ""))
    local limit = tonumber(args.limit) or 200
    local found, total = findMatches(root, query, args.className, args.tag, limit, args.exact == true)
    local matches = {}
    for _, inst in ipairs(found) do
        local entry = describeRef(inst)
        if inst:IsA("BasePart") then
            entry.position = { x = inst.Position.X, y = inst.Position.Y, z = inst.Position.Z }
            entry.size = { x = inst.Size.X, y = inst.Size.Y, z = inst.Size.Z }
        end
        if inst:IsA("LuaSourceContainer") then
            local sourceOk, source = pcall(function() return inst.Source end)
            if sourceOk then entry.sourceLines = select(2, string.gsub(source, "\n", "\n")) + 1 end
        end
        table.insert(matches, entry)
    end

    local warnings = nil
    if total > #matches then
        warnings = { "Found " .. tostring(total) .. " matches, returning the first " .. tostring(#matches) .. ". Raise 'limit' to get more." }
    end
    if total > 1 and query ~= "" then
        local sameName = 0
        for _, entry in ipairs(matches) do
            if string.lower(entry.name) == query then sameName = sameName + 1 end
        end
        if sameName > 1 then
            warnings = warnings or {}
            table.insert(warnings, "Several objects share the name '" .. tostring(args.query) .. "'. Always address them by their id (e.g. \"#42\") - the path alone is ambiguous.")
        end
    end
    return ok({ matches = matches, totalMatches = total, returned = #matches }, warnings)
end

tools.get_instance = function(args)
    local inst, err = resolveRef(args.ref or args.path)
    if not inst then return fail(err) end
    local children = {}
    for _, child in ipairs(inst:GetChildren()) do
        local entry = describeRef(child)
        entry.childCount = #child:GetChildren()
        table.insert(children, entry)
    end
    local warnings = nil
    if inst.Parent and nameCollisions(inst.Parent, inst.Name) > 1 then
        warnings = { "There are several siblings named '" .. inst.Name .. "'. Use the id " .. idOf(inst) .. " to address exactly this one." }
    end
    return ok({
        id = idOf(inst),
        name = inst.Name,
        className = inst.ClassName,
        path = pathOf(inst),
        parent = inst.Parent and describeRef(inst.Parent) or nil,
        properties = readProps(inst, args.includeSource == true, args.includeAllProperties == true),
        children = children,
        childCount = #children,
    }, warnings)
end

tools.get_children = function(args)
    local inst, err = resolveRef(args.ref or args.path or "game")
    if not inst then return fail(err) end
    local offset = tonumber(args.offset) or 0
    local limit = tonumber(args.limit) or 500
    local all = inst:GetChildren()
    local items = {}
    for index = offset + 1, math.min(#all, offset + limit) do
        local entry = describeRef(all[index])
        entry.childCount = #all[index]:GetChildren()
        table.insert(items, entry)
    end
    return ok({ children = items, total = #all, offset = offset, returned = #items })
end

tools.get_properties = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    local wanted = args.properties
    local results = {}
    for _, inst in ipairs(list) do
        local entry = describeRef(inst)
        entry.properties = {}
        if type(wanted) == "table" and #wanted > 0 then
            for _, property in ipairs(wanted) do
                local okRead, value = pcall(function() return inst[property] end)
                if okRead then
                    entry.properties[property] = encodeValue(value)
                else
                    entry.properties[property] = nil
                end
            end
        else
            entry.properties = readProps(inst, args.includeSource == true, false)
        end
        table.insert(results, entry)
    end
    return ok({ items = results, errors = errors })
end

tools.get_selection = function()
    local items = {}
    for _, inst in ipairs(Selection:Get()) do
        table.insert(items, describeRef(inst))
    end
    return ok({ selection = items, count = #items })
end

tools.select_instance = function(args)
    local list, errors = resolveMany(args.refs or args.ref or args.path)
    if #list == 0 then return fail("Nothing to select. " .. table.concat(errors, " ")) end
    if args.add == true then
        local current = Selection:Get()
        for _, inst in ipairs(list) do table.insert(current, inst) end
        Selection:Set(current)
    else
        Selection:Set(list)
    end
    local items = {}
    for _, inst in ipairs(list) do table.insert(items, describeRef(inst)) end
    return ok({ selected = items, errors = errors })
end

tools.resolve_ref = function(args)
    local inst, err = resolveRef(args.ref or args.path or args.id)
    if not inst then return fail(err) end
    return ok(describeRef(inst))
end

-- Textbeschreibung der Szene: die bessere Alternative zu Screenshots.
tools.describe_scene = function(args)
    local root, err = resolveRef(args.rootRef or "game.Workspace")
    if not root then return fail(err) end
    local maxItems = tonumber(args.maxItems) or 120
    local lines = {}
    local items = {}
    local counts = {}

    local function record(inst, depth)
        local className = inst.ClassName
        counts[className] = (counts[className] or 0) + 1
        if #items >= maxItems then return end
        local entry = describeRef(inst)
        local text = string.rep("  ", depth) .. inst.Name .. " [" .. className .. "] " .. idOf(inst)
        if inst:IsA("BasePart") then
            entry.position = { x = inst.Position.X, y = inst.Position.Y, z = inst.Position.Z }
            entry.size = { x = inst.Size.X, y = inst.Size.Y, z = inst.Size.Z }
            text = text .. string.format(" pos(%.1f, %.1f, %.1f) size(%.1f, %.1f, %.1f) %s %s",
                inst.Position.X, inst.Position.Y, inst.Position.Z,
                inst.Size.X, inst.Size.Y, inst.Size.Z,
                tostring(inst.Material.Name),
                tostring(inst.BrickColor.Name))
            if inst.Transparency > 0 then
                text = text .. string.format(" transparency %.2f", inst.Transparency)
            end
            if not inst.Anchored then text = text .. " NOT-ANCHORED" end
        elseif inst:IsA("Model") then
            local cframe, size = boundsOf(inst)
            if cframe then
                text = text .. string.format(" center(%.1f, %.1f, %.1f) extent(%.1f, %.1f, %.1f) parts=%d",
                    cframe.Position.X, cframe.Position.Y, cframe.Position.Z, size.X, size.Y, size.Z, #inst:GetDescendants())
            end
        elseif inst:IsA("LuaSourceContainer") then
            local sourceOk, source = pcall(function() return inst.Source end)
            if sourceOk then
                text = text .. " lines=" .. tostring(select(2, string.gsub(source, "\n", "\n")) + 1)
            end
        end
        table.insert(items, entry)
        table.insert(lines, text)
    end

    local maxDepth = tonumber(args.maxDepth) or 2
    local function walk(inst, depth)
        for _, child in ipairs(inst:GetChildren()) do
            record(child, depth)
            if depth < maxDepth then
                walk(child, depth + 1)
            end
        end
    end
    record(root, 0)
    walk(root, 1)

    local camera = Workspace.CurrentCamera
    local cameraText = "unknown"
    if camera then
        local position = camera.CFrame.Position
        local look = camera.CFrame.LookVector
        cameraText = string.format("camera at (%.1f, %.1f, %.1f) looking (%.2f, %.2f, %.2f)",
            position.X, position.Y, position.Z, look.X, look.Y, look.Z)
    end

    local summary = {}
    for className, count in pairs(counts) do
        table.insert(summary, className .. " x" .. tostring(count))
    end
    table.sort(summary)

    return ok({
        text = cameraText .. "\n" .. table.concat(lines, "\n"),
        items = items,
        classSummary = summary,
        truncated = (#items >= maxItems),
        hint = "This textual description replaces screenshots. It is far more reliable for an AI than an image.",
    })
end

tools.scene_stats = function(args)
    local root, err = resolveRef(args.rootRef or "game.Workspace")
    if not root then return failCode("REF_NOT_FOUND", err) end
    local counts = {}
    local total = 0
    local totalParts = 0
    local operations = 0
    for _, inst in ipairs(root:GetDescendants()) do
        total = total + 1
        counts[inst.ClassName] = (counts[inst.ClassName] or 0) + 1
        if inst:IsA("BasePart") then
            totalParts = totalParts + 1
            if inst:IsA("PartOperation") then operations = operations + 1 end
        end
    end
    local modelList = {}
    for _, inst in ipairs(root:GetDescendants()) do
        if inst:IsA("Model") and (inst.Parent == nil or not inst.Parent:IsA("Model")) then
            local n = 0
            for _, d in ipairs(inst:GetDescendants()) do
                if d:IsA("BasePart") then n = n + 1 end
            end
            table.insert(modelList, { model = describeRef(inst), parts = n })
        end
    end
    table.sort(modelList, function(a, b) return a.parts > b.parts end)
    local topModels = {}
    for i = 1, math.min(10, #modelList) do table.insert(topModels, modelList[i]) end
    local classSummary = {}
    for className, count in pairs(counts) do
        table.insert(classSummary, { className = className, count = count })
    end
    table.sort(classSummary, function(a, b) return a.count > b.count end)
    local summaryTop = {}
    for i = 1, math.min(25, #classSummary) do table.insert(summaryTop, classSummary[i]) end
    return ok({
        totalDescendants = total,
        totalParts = totalParts,
        partOperations = operations,
        models = #modelList,
        topModels = topModels,
        classes = summaryTop,
        note = "For very big places (15.000+ parts) prefer targeted queries (search with tag/className, get_tree with rootRef+maxDepth) over full dumps.",
    })
end

tools.viewport_info = function()
    local camera = Workspace.CurrentCamera
    if camera == nil then return fail("No camera found.") end
    local looking = {}
    local origin = camera.CFrame.Position
    local direction = camera.CFrame.LookVector * 500
    local params = RaycastParams.new()
    local hit = Workspace:Raycast(origin, direction, params)
    if hit then
        looking = {
            instance = describeRef(hit.Instance),
            position = { x = hit.Position.X, y = hit.Position.Y, z = hit.Position.Z },
            distance = (hit.Position - origin).Magnitude,
            material = tostring(hit.Material),
        }
    end
    return ok({
        camera = encodeValue(camera.CFrame),
        fieldOfView = camera.FieldOfView,
        viewportSize = { x = camera.ViewportSize.X, y = camera.ViewportSize.Y },
        lookingAt = looking,
    })
end

tools.get_bounds = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    if #list == 0 then return fail("No instance resolved. " .. table.concat(errors, " ")) end
    local items = {}
    for _, inst in ipairs(list) do
        table.insert(items, boundsInfo(inst))
    end
    if #items == 1 then
        return ok(items[1])
    end
    return ok({ items = items, errors = errors })
end

tools.measure = function(args)
    local a, errA = resolveRef(args.refA or args.ref)
    local b, errB = resolveRef(args.refB or args.targetRef)
    if not a then return fail(errA) end
    if not b then return fail(errB) end
    local ca = getPivotOf(a)
    local cb = getPivotOf(b)
    if ca == nil or cb == nil then return fail("Both instances need a position.") end
    local delta = cb.Position - ca.Position
    return ok({
        distance = delta.Magnitude,
        delta = { x = delta.X, y = delta.Y, z = delta.Z },
        from = describeRef(a),
        to = describeRef(b),
    })
end

tools.raycast = function(args)
    local origin = decodeValue(args.origin)
    local direction = decodeValue(args.direction)
    if typeof(origin) ~= "Vector3" or typeof(direction) ~= "Vector3" then
        return fail("origin and direction must be {x,y,z}.")
    end
    local params = RaycastParams.new()
    local ignoreList, _ = resolveMany(args.ignore)
    if #ignoreList > 0 then
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = ignoreList
    end
    local hit = Workspace:Raycast(origin, direction, params)
    if hit == nil then
        return ok({ hit = false })
    end
    return ok({
        hit = true,
        instance = describeRef(hit.Instance),
        position = { x = hit.Position.X, y = hit.Position.Y, z = hit.Position.Z },
        normal = { x = hit.Normal.X, y = hit.Normal.Y, z = hit.Normal.Z },
        distance = (hit.Position - origin).Magnitude,
        material = tostring(hit.Material),
    })
end


-- ------------------------- Raumabfragen (Batch/Filter/Toleranz) ----------
local function filterMatches(inst, filter)
    if filter == nil then return true end
    if filter.className then
        local wanted = tostring(filter.className)
        local okIs, isType = pcall(function() return inst:IsA(wanted) end)
        if not (inst.ClassName == wanted or (okIs and isType)) then return false end
    end
    if filter.tag then
        local okTag, hasTag = pcall(function() return CollectionService:HasTag(inst, tostring(filter.tag)) end)
        if not (okTag and hasTag) then return false end
    end
    if filter.tags then
        for _, tag in ipairs(filter.tags) do
            local okTag, hasTag = pcall(function() return CollectionService:HasTag(inst, tostring(tag)) end)
            if not (okTag and hasTag) then return false end
        end
    end
    return true
end

-- FIX 7.0.8: Zuweisung an die Vorwaerts-Deklaration oben (sonst sehen die
-- bereits definierten Werkzeuge weiterhin ein nil-Global).
firstNonEmpty = function(...)
    for index = 1, select("#", ...) do
        local value = select(index, ...)
        if value ~= nil and not (type(value) == "string" and value == "")
            and not (type(value) == "table" and next(value) == nil) then
            return value
        end
    end
    return nil
end

local function resolveExcluded(exclude)
    local list = {}
    local exList, _ = resolveMany(exclude)
    for _, inst in ipairs(exList) do table.insert(list, inst) end
    return list
end

local function spatialFilter(args)
    local filter = {}
    if type(args.filter) == "table" then
        for key, value in pairs(args.filter) do filter[key] = value end
    end
    if args.className ~= nil then filter.className = args.className end
    if args.tag ~= nil then filter.tag = args.tag end
    if next(filter) == nil then return nil end
    return filter
end

local function spatialExclude(args)
    return firstNonEmpty(args.excludeRefs, args.exclude, args.ignore)
end

local function collectInBox(minVec, maxVec, filter, exclude, limit)
    limit = tonumber(limit) or 200
    local params = overlapParamsNew(resolveExcluded(exclude))
    local found = {}
    local total = 0
    local parts = Workspace:GetPartBoundsInBox((minVec + maxVec) / 2, (maxVec - minVec), params)
    for _, inst in ipairs(parts) do
        if filterMatches(inst, filter) then
            total = total + 1
            if #found < limit then
                local entry = describeRef(inst)
                local cf, size = boundsOf(inst)
                if cf and size then
                    entry.position = { x = cf.Position.X, y = cf.Position.Y, z = cf.Position.Z }
                    entry.size = { x = size.X, y = size.Y, z = size.Z }
                end
                table.insert(found, entry)
            end
        end
    end
    return found, total
end

tools.parts_in_box = function(args)
    local minVec = decodeValue(args.min)
    local maxVec = decodeValue(args.max)
    local center = nil
    if typeof(minVec) == "Vector3" and typeof(maxVec) == "Vector3" then
        -- min/max supplied directly
    else
        local centerValue = decodeValue(args.center)
        local sizeValue = decodeValue(args.size)
        if typeof(centerValue) == "Vector3" and typeof(sizeValue) == "Vector3" then
            center = centerValue
            local half = Vector3.new(math.abs(sizeValue.X), math.abs(sizeValue.Y), math.abs(sizeValue.Z)) / 2
            minVec, maxVec = center - half, center + half
        elseif args.refA and args.refB then
            local a, errA = resolveRef(args.refA)
            local b, errB = resolveRef(args.refB)
            if not a then return failCode("REF_NOT_FOUND", errA) end
            if not b then return failCode("REF_NOT_FOUND", errB) end
            local cfA = getPivotOf(a)
            local cfB = getPivotOf(b)
            if not cfA or not cfB then return failCode("BAD_ARGS", "refA/refB must have measurable positions.") end
            minVec, maxVec = cfA.Position, cfB.Position
        else
            return failCode("BAD_ARGS", "Use min+max, center+size, or refA+refB.")
        end
    end
    local low = Vector3.new(math.min(minVec.X, maxVec.X), math.min(minVec.Y, maxVec.Y), math.min(minVec.Z, maxVec.Z))
    local high = Vector3.new(math.max(minVec.X, maxVec.X), math.max(minVec.Y, maxVec.Y), math.max(minVec.Z, maxVec.Z))
    local tolerance = math.max(0, tonumber(args.tolerance) or 0)
    local expand = Vector3.new(tolerance, tolerance, tolerance)
    low, high = low - expand, high + expand
    if center == nil then center = (low + high) / 2 end
    local filter = spatialFilter(args)
    local exclude = spatialExclude(args)
    local limit = math.max(0, math.min(tonumber(args.limit) or 200, 500))
    local found, total = collectInBox(low, high, filter, exclude, limit)
    for _, entry in ipairs(found) do
        if entry.position then
            local delta = Vector3.new(entry.position.x - center.X, entry.position.y - center.Y, entry.position.z - center.Z)
            entry.distanceFromCenter = delta.Magnitude
        end
    end
    local empty = total == 0
    return ok({
        items = found, count = #found, totalMatches = total,
        empty = empty, clear = empty,
        hint = empty and "No matching BaseParts in this box. Check the bounds, className and tag filters." or nil,
    })
end

tools.parts_in_sphere = function(args)
    local center = decodeValue(args.center)
    if typeof(center) ~= "Vector3" and args.ref then
        local inst, err = resolveRef(args.ref)
        if not inst then return failCode("REF_NOT_FOUND", err) end
        local cf = getPivotOf(inst)
        if cf then center = cf.Position end
    end
    if typeof(center) ~= "Vector3" then return failCode("BAD_ARGS", "Need center={x,y,z} or ref.") end
    local radius = tonumber(args.radius) or 10
    if radius ~= radius or radius < 0 then return failCode("BAD_ARGS", "radius must be >= 0.") end
    local tolerance = math.max(0, tonumber(args.tolerance) or 0)
    local limit = math.max(0, math.min(tonumber(args.limit) or 200, 500))
    local extent = radius + tolerance
    local half = Vector3.new(extent, extent, extent)
    local candidates, total = collectInBox(center - half, center + half, spatialFilter(args), spatialExclude(args), 500)
    local inside = {}
    for _, entry in ipairs(candidates) do
        if entry.position then
            local delta = Vector3.new(entry.position.x - center.X, entry.position.y - center.Y, entry.position.z - center.Z)
            local partExtent = 0
            if entry.size then partExtent = (entry.size.x + entry.size.y + entry.size.z) / 6 end
            if delta.Magnitude <= radius + tolerance + partExtent and #inside < limit then
                table.insert(inside, entry)
            end
        end
    end
    return ok({ items = inside, count = #inside, totalCandidates = total, empty = (#inside == 0),
        note = "Sphere test includes part extent approximately; very large scenes are capped at 500 candidate parts." })
end

tools.nearest_parts = function(args)
    local from = decodeValue(args.position or args.origin)
    if typeof(from) ~= "Vector3" and (args.ref or args.fromRef) then
        local inst, err = resolveRef(args.ref or args.fromRef)
        if not inst then return failCode("REF_NOT_FOUND", err) end
        local cf = getPivotOf(inst)
        if cf then from = cf.Position end
    end
    if typeof(from) ~= "Vector3" then return failCode("BAD_ARGS", "Need origin/position {x,y,z} or ref/fromRef.") end
    local radius = tonumber(args.radius) or 50
    if radius ~= radius or radius < 0 then return failCode("BAD_ARGS", "radius must be >= 0.") end
    local limit = math.max(0, math.min(tonumber(args.limit) or 20, 500))
    local half = Vector3.new(radius, radius, radius)
    local candidates, total = collectInBox(from - half, from + half, spatialFilter(args), spatialExclude(args), 500)
    local scored = {}
    for _, entry in ipairs(candidates) do
        if entry.position then
            local delta = Vector3.new(entry.position.x - from.X, entry.position.y - from.Y, entry.position.z - from.Z)
            entry.distance = math.floor(delta.Magnitude * 100) / 100
            table.insert(scored, entry)
        end
    end
    table.sort(scored, function(a, b) return a.distance < b.distance end)
    local out = {}
    for i = 1, math.min(limit, #scored) do table.insert(out, scored[i]) end
    return ok({ items = out, count = #out, totalCandidates = total, empty = (#out == 0), nearest = out[1],
        from = { x = from.X, y = from.Y, z = from.Z } })
end

tools.what_is_in_the_way = function(args)
    local pointA = decodeValue(args.from or args.origin)
    if typeof(pointA) ~= "Vector3" and args.fromRef then
        local inst, err = resolveRef(args.fromRef)
        if not inst then return failCode("REF_NOT_FOUND", err) end
        local cf = getPivotOf(inst)
        if cf then pointA = cf.Position end
    end
    local pointB = decodeValue(args.to or args.target)
    if typeof(pointB) ~= "Vector3" and args.toRef then
        local inst, err = resolveRef(args.toRef)
        if not inst then return failCode("REF_NOT_FOUND", err) end
        local cf = getPivotOf(inst)
        if cf then pointB = cf.Position end
    end
    if typeof(pointA) ~= "Vector3" or typeof(pointB) ~= "Vector3" then
        return failCode("BAD_ARGS", "Need from/to as {x,y,z} or fromRef/toRef.")
    end
    local dir = pointB - pointA
    local length = dir.Magnitude
    if length < 0.01 then return failCode("BAD_ARGS", "from and to are the same point.") end
    local width = tonumber(args.width) or 2
    local exList = resolveExcluded(spatialExclude(args))
    if args.fromRef then
        local instA = resolveRef(args.fromRef)
        if instA then table.insert(exList, instA) end
    end
    if args.toRef then
        local instB = resolveRef(args.toRef)
        if instB then table.insert(exList, instB) end
    end
    local lo = Vector3.new(math.min(pointA.X, pointB.X), math.min(pointA.Y, pointB.Y), math.min(pointA.Z, pointB.Z))
        - Vector3.new(width / 2, width / 2, width / 2)
    local hi = Vector3.new(math.max(pointA.X, pointB.X), math.max(pointA.Y, pointB.Y), math.max(pointA.Z, pointB.Z))
        + Vector3.new(width / 2, width / 2, width / 2)
    local params = overlapParamsNew(exList)
    local limit = math.max(0, math.min(tonumber(args.limit) or 50, 500))
    local found = {}
    local parts = Workspace:GetPartBoundsInBox((lo + hi) / 2, (hi - lo), params)
    for _, inst in ipairs(parts) do
        if filterMatches(inst, spatialFilter(args)) then
            local cf = getPivotOf(inst)
            if cf then
                local rel = cf.Position - pointA
                local t = rel:Dot(dir) / (length * length)
                if t >= -0.05 and t <= 1.05 then
                    local tc = math.max(0, math.min(1, t))
                    local closest = pointA + dir * tc
                    local dist = (cf.Position - closest).Magnitude
                    local entry = describeRef(inst)
                    entry.position = { x = cf.Position.X, y = cf.Position.Y, z = cf.Position.Z }
                    entry.distanceFromLine = math.floor(dist * 100) / 100
                    table.insert(found, entry)
                end
            end
        end
        if #found >= limit then break end
    end
    return ok({
        items = found,
        count = #found,
        clear = (#found == 0),
        note = "Axis-aligned box around the line (width on every axis); A and B are excluded.",
    })
end

tools.raycast_many = function(args)
    local casts = firstNonEmpty(args.rays, args.casts) or {}
    if type(casts) ~= "table" or #casts == 0 then
        return failCode("BAD_ARGS", "rays/casts must be a list of { origin = {x,y,z}, direction = {x,y,z}, length? }.")
    end
    if #casts > 500 then
        return failCode("REGION_LIMIT", "Too many casts (" .. tostring(#casts) .. ", max 500 per call). Split the batch.", { sampleLimit = 500 })
    end
    local params = measureRayParams(resolveExcluded(firstNonEmpty(args.exclude, args.ignore)))
    local hits = {}
    local hitCount = 0
    local job = args._job
    for index, cast in ipairs(casts) do
        if type(cast) ~= "table" then
            table.insert(hits, { index = index, error = "ray must be an object with origin and direction" })
        else
            local origin = decodeValue(cast.origin)
            local direction = decodeValue(cast.direction)
            if typeof(origin) ~= "Vector3" or typeof(direction) ~= "Vector3" then
                table.insert(hits, { index = index, error = "origin/direction must be {x,y,z}" })
            else
                local length = tonumber(cast.length) or 1000
                if length < 0 then
                    table.insert(hits, { index = index, error = "length must be >= 0" })
                else
                    if direction.Magnitude > 0 then
                        direction = direction.Unit * length
                    else
                        direction = Vector3.new(0, 0, 0)
                    end
                    local hit = Workspace:Raycast(origin, direction, params)
                    if hit then
                        hitCount = hitCount + 1
                        table.insert(hits, {
                            index = index, hit = true,
                            instance = describeRef(hit.Instance),
                            position = { x = hit.Position.X, y = hit.Position.Y, z = hit.Position.Z },
                            normal = { x = hit.Normal.X, y = hit.Normal.Y, z = hit.Normal.Z },
                            distance = (hit.Position - origin).Magnitude,
                            material = tostring(hit.Material),
                            waterLike = isWaterLike(hit.Instance),
                        })
                    else
                        table.insert(hits, { index = index, hit = false })
                    end
                end
            end
        end
        if index % 64 == 0 then
            if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                return failCode("COMMAND_CANCELLED", "Raycast batch job was cancelled.", { measured = index, total = #casts })
            end
            if type(job) == "table" and type(job.progress) == "function" then
                job.progress(index / #casts * 100, tostring(index) .. "/" .. tostring(#casts) .. " rays cast")
            end
            task.wait()
        end
    end
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, "raycast batch complete") end
    return ok({ results = hits, count = #hits, hitCount = hitCount })
end

tools.ground_height = function(args)
    local positions = firstNonEmpty(args.positions, args.points) or {}
    if type(positions) ~= "table" then
        return failCode("BAD_ARGS", "points/positions must be an array of {x,y,z} or use min+max+step for a grid.")
    end
    if positions.x ~= nil or positions.X ~= nil then positions = { positions } end
    if #positions == 0 and args.min and args.max then
        local minVec = decodeValue(args.min)
        local maxVec = decodeValue(args.max)
        if typeof(minVec) ~= "Vector3" or typeof(maxVec) ~= "Vector3" then
            return failCode("BAD_ARGS", "Need points (a list of {x,y,z}) or min+max {x,y,z} with step.")
        end
        local step = tonumber(args.step) or 4
        if step < 0.5 then step = 0.5 end
        local minX, maxX = math.min(minVec.X, maxVec.X), math.max(minVec.X, maxVec.X)
        local minZ, maxZ = math.min(minVec.Z, maxVec.Z), math.max(minVec.Z, maxVec.Z)
        local countX = math.floor((maxX - minX + 0.001) / step) + 1
        local countZ = math.floor((maxZ - minZ + 0.001) / step) + 1
        local estimate = countX * countZ
        if estimate > 4000 then
            return failCode("REGION_LIMIT", "Ground grid would contain " .. tostring(estimate) .. " sample points (max 4000). Increase step or split the area before measuring.", {
                sampleLimit = 4000, estimatedSamples = estimate, step = step,
            })
        end
        positions = {}
        for ix = 0, countX - 1 do
            local x = minX + ix * step
            for iz = 0, countZ - 1 do
                local z = minZ + iz * step
                table.insert(positions, { x = x, y = minVec.Y + 400, z = z })
            end
        end
    end
    if #positions == 0 then
        return failCode("BAD_ARGS", "Need points/positions (a list of {x,y,z}; each ray starts there and goes straight down) or min/max+step for a grid.")
    end
    if #positions > 4000 then
        return failCode("REGION_LIMIT", "Too many sample points (" .. tostring(#positions) .. ", max 4000). Raise the step or split the area.", { sampleLimit = 4000 })
    end
    local params = measureRayParams(resolveExcluded(firstNonEmpty(args.exclude, args.ignore)))
    local results = {}
    local job = args._job
    for index, p in ipairs(positions) do
        local vec = decodeValue(p)
        if typeof(vec) == "Vector3" then
            local hit = Workspace:Raycast(vec, Vector3.new(0, -4000, 0), params)
            if hit then
                table.insert(results, {
                    position = { x = vec.X, y = vec.Y, z = vec.Z },
                    groundY = hit.Position.Y,
                    ground = describeRef(hit.Instance),
                    material = tostring(hit.Material),
                    waterLike = isWaterLike(hit.Instance),
                })
            else
                table.insert(results, { position = { x = vec.X, y = vec.Y, z = vec.Z }, groundY = nil, note = "no surface below" })
            end
        end
        if index % 128 == 0 then
            if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                return failCode("COMMAND_CANCELLED", "Ground measurement job was cancelled.", { measured = index, total = #positions })
            end
            if type(job) == "table" and type(job.progress) == "function" then
                job.progress(index / #positions * 100, tostring(index) .. "/" .. tostring(#positions) .. " sample points measured")
            end
            task.wait()
        end
    end
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, "ground measurement complete") end
    return ok({
        heights = results,
        results = results,
        count = #results,
        hint = "Heights are RAYCAST results - the only allowed way to get world Y in this place.",
    })
end

tools.measure_height = function(args)
    local inst = nil
    local cframe = nil
    local size = nil
    local origin = nil
    local err = nil
    if args.ref ~= nil then
        inst, err = resolveRef(args.ref)
        if not inst then return failCode("REF_NOT_FOUND", err) end
        cframe, size = boundsOf(inst)
        if not cframe or size == nil then return failCode("BAD_ARGS", "Instance has no measurable geometry.") end
    else
        origin = decodeValue(args.point)
        if typeof(origin) ~= "Vector3" then
            return failCode("BAD_ARGS", "Pass either ref or point={x,y,z}.")
        end
    end
    local directionName = string.lower(tostring(args.direction or "down"))
    if directionName ~= "down" and directionName ~= "up" then
        return failCode("BAD_ARGS", "direction must be 'down' or 'up'.")
    end
    local rayDirection
    if directionName == "up" then
        if inst then origin = cframe.Position + Vector3.new(0, size.Y / 2 + 1, 0) end
        rayDirection = Vector3.new(0, 4000, 0)
    else
        if inst then origin = cframe.Position + Vector3.new(0, -size.Y / 2 - 1, 0) end
        rayDirection = Vector3.new(0, -4000, 0)
    end
    local exclusions = resolveExcluded(firstNonEmpty(args.exclude, args.ignore))
    if inst then table.insert(exclusions, inst) end
    local hit = Workspace:Raycast(origin, rayDirection, measureRayParams(exclusions))
    local result = {
        instance = inst and describeRef(inst) or nil,
        direction = directionName,
        origin = { x = origin.X, y = origin.Y, z = origin.Z },
        hit = (hit ~= nil),
    }
    if inst then
        result.top = cframe.Position.Y + size.Y / 2
        result.bottom = cframe.Position.Y - size.Y / 2
        result.height = size.Y
    end
    if hit then
        result.y = hit.Position.Y
        result.distance = hit.Distance
        result.hitInstance = describeRef(hit.Instance)
        result.waterLike = isWaterLike(hit.Instance)
        if directionName == "down" then
            result.groundY = hit.Position.Y
            if inst then result.heightAboveGround = result.bottom - hit.Position.Y end
        else
            result.skyY = hit.Position.Y
        end
    else
        result.note = directionName == "down" and "No surface found below." or "No surface found above."
    end
    return ok(result)
end

tools.verify_measurable = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    if #list == 0 then return failCode("REF_NOT_FOUND", "Nothing resolved. " .. table.concat(errors, " ")) end
    local check = {}
    for i = 1, math.min(10, #list) do table.insert(check, list[i]) end
    local maxSeconds = math.max(0, math.min(tonumber(args.maxSeconds or args.seconds) or 5, 30))
    local info = waitMeasurable(check, maxSeconds)
    return ok({ checked = #list, geometry = info, maxSeconds = maxSeconds })
end

-- ------------------------- Erstellen / Aendern ------------------------------
local function applyProperties(inst, properties)
    local problems = {}
    if type(properties) ~= "table" then return problems end
    for key, value in pairs(properties) do
        if key ~= "ClassName" and key ~= "Parent" then
            local okSet, err = setProperty(inst, key, value)
            if not okSet then
                table.insert(problems, key .. ": " .. tostring(err))
            end
        end
    end
    return problems
end

local function createOne(spec)
    local parent, err = resolveRef(spec.parentRef or spec.parentPath or "game.Workspace")
    if not parent then return nil, err end
    local className = spec.className or "Part"
    local created = nil
    local createOk, createErr = pcall(function()
        created = Instance.new(className)
    end)
    if not createOk or created == nil then
        return nil, "Cannot create '" .. tostring(className) .. "': " .. tostring(createErr)
    end
    created.Name = spec.name or className
    local problems = applyProperties(created, spec.properties)
    created.Parent = parent
    local entry = describeRef(created)
    entry.propertyProblems = (#problems > 0) and problems or nil
    return entry
end

tools.create_instance = function(args)
    local count = math.floor(tonumber(args.count) or 1)
    if count < 1 then count = 1 end
    if count > 400 then return failCode("BUDGET_EXCEEDED", "create_instance supports at most 400 copies per call. Split the request.", { sampleLimit = 400 }) end
    local job = args._job
    if count == 1 then
        local entry, err = createOne(args)
        if not entry then return fail(err) end
        waypoint("create " .. tostring(args.className))
        local geometry = nil
        if args.waitForMeasurable ~= false then
            local createdInst = resolveRef(entry.id)
            geometry = waitMeasurable({ createdInst }, 2)
            entry.geometry = geometry
        end
        return ok(entry)
    end
    local created = {}
    local createdInsts = {}
    local offset = decodeValue(args.offset) or Vector3.new(0, 0, 0)
    for index = 1, count do
        local spec = {
            parentRef = args.parentRef or args.parentPath,
            className = args.className,
            name = (args.name or args.className or "Part") .. tostring(index),
            properties = args.properties,
        }
        local entry, err = createOne(spec)
        if entry then
            local inst = resolveRef(entry.id)
            if inst and inst:IsA("BasePart") then
                if typeof(offset) == "Vector3" and offset.Magnitude > 0 then
                    inst.Position = inst.Position + offset * (index - 1)
                end
                if #createdInsts < 8 then table.insert(createdInsts, inst) end
            end
            table.insert(created, entry)
        end
        if index % 32 == 0 then
            if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                return failCode("COMMAND_CANCELLED", "create_instance job was cancelled after partial creation.", { created = created, count = #created, requested = count })
            end
            if type(job) == "table" and type(job.progress) == "function" then
                job.progress(index / count * 95, tostring(index) .. "/" .. tostring(count) .. " instances created")
            end
            task.wait()
        end
    end
    waypoint("create " .. tostring(count) .. "x " .. tostring(args.className))
    local geometry = nil
    if args.waitForMeasurable ~= false then geometry = waitMeasurable(createdInsts, 2) end
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, "create complete") end
    return ok({ created = created, count = #created, geometry = geometry })
end

tools.bulk_create = function(args)
    local items = args.items or args.instances or {}

    -- FIX 3.2: Doku-Vertrag endlich umgesetzt:
    --   * template als SPEZ-Tabelle { className, properties, parentRef } + count
    --   * grid mit { rows, columns, spacingX, spacingZ } (frueher nur rows/cols,
    --     obwohl die Doku "columns" sagte -> Grids lieferten still 1 Teil)
    --   * nameTemplate "{n}" (frueher wurde nur "$" ersetzt)
    local templateSpec = (type(args.template) == "table") and args.template or {}
    local grid = args.grid
    local wantCount = tonumber(args.count)
    if #items == 0 and (type(grid) == "table" or (wantCount and wantCount > 0)) then
        local origin = decodeValue(args.origin)
        local className = args.className or templateSpec.className or "Part"
        local baseProps = args.properties or templateSpec.properties
        local nameTemplate = tostring(args.nameTemplate or "Part")
        local cells = {}
        if type(grid) == "table" then
            if typeof(origin) ~= "Vector3" then
                return failCode("BAD_ARGS", "grid needs origin {x,y,z} and grid { rows, columns, spacingX, spacingZ }.")
            end
            local rows = math.max(1, math.floor(tonumber(grid.rows) or 1))
            local cols = math.max(1, math.floor(tonumber(grid.cols or grid.columns) or 1))
            if rows * cols > 400 then
                return failCode("BUDGET_EXCEEDED", "This grid would create " .. tostring(rows * cols) .. " instances - max 400 per call. Reduce rows/columns before generating it.", { sampleLimit = 400 })
            end
            local sx = tonumber(grid.spacingX) or 4
            local sz = tonumber(grid.spacingZ) or 4
            for r = 0, rows - 1 do
                for c = 0, cols - 1 do
                    table.insert(cells, origin + Vector3.new(c * sx, 0, r * sz))
                end
            end
        else
            if typeof(origin) ~= "Vector3" then
                return failCode("BAD_ARGS", "count needs origin {x,y,z} (plus optional offset {x,y,z} between copies).")
            end
            if wantCount > 400 then
                return failCode("BUDGET_EXCEEDED", "This would create " .. tostring(wantCount) .. " instances - max 400 per call. Reduce count before generating it.", { sampleLimit = 400 })
            end
            local off = decodeValue(args.offset) or Vector3.new(0, 0, 0)
            for i = 0, wantCount - 1 do
                table.insert(cells, origin + off * i)
            end
        end
        if #cells > 400 then
            return failCode("BUDGET_EXCEEDED", "This would create " .. tostring(#cells) .. " instances - max 400 per call. Split into smaller calls.")
        end
        local counter = 0
        for _, pos in ipairs(cells) do
            counter = counter + 1
            local props = {}
            if type(baseProps) == "table" then
                for key, value in pairs(baseProps) do props[key] = value end
            end
            props.Position = pos
            local name = nameTemplate:gsub("{n}", tostring(counter)):gsub("%$", tostring(counter))
            table.insert(items, {
                className = className,
                name = name,
                properties = props,
                parentRef = args.parentRef or args.parentPath or templateSpec.parentRef,
            })
        end
    end

    -- Vorlage: stattdessen ein fertiges Teil/Modell klonen
    local templateInst = nil
    if args.templateRef then
        local t, errT = resolveRef(args.templateRef)
        if t == nil then return failCode("REF_NOT_FOUND", errT) end
        templateInst = t
    end

    if #items > 400 then
        return failCode("BUDGET_EXCEEDED", "bulk_create got " .. tostring(#items) .. " items - max 400 per call. Split the list into smaller calls.")
    end

    local created = {}
    local createdInsts = {}
    local errors = {}
    local job = args._job
    for index, spec in ipairs(items) do
        local entry = nil
        local err = nil
        if templateInst then
            local parentT, errP = resolveRef(spec.parentRef or spec.parentPath or "game.Workspace")
            if parentT == nil then
                err = errP
            else
                local cloneInst = templateInst:Clone()
                if spec.name then cloneInst.Name = spec.name end
                local props = (type(spec.properties) == "table") and spec.properties or {}
                local pos = props.Position
                if typeof(pos) == "Vector3" then
                    cloneInst.CFrame = CFrame.new(pos)
                end
                for key, value in pairs(props) do
                    if key ~= "Position" then
                        pcall(function() cloneInst[key] = value end)
                    end
                end
                cloneInst.Parent = parentT
                entry = describeRef(cloneInst)
            end
        else
            entry, err = createOne(spec)
        end
        if entry then
            local inst = resolveRef(entry.id)
            if inst and inst:IsA("BasePart") and #createdInsts < 8 then
                table.insert(createdInsts, inst)
            end
            table.insert(created, entry)
        else
            table.insert(errors, "item " .. tostring(index) .. ": " .. tostring(err))
        end
        if index % 32 == 0 then
            if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                return failCode("COMMAND_CANCELLED", "bulk_create job was cancelled after partial creation.", { created = created, count = #created, requested = #items, errors = errors })
            end
            if type(job) == "table" and type(job.progress) == "function" then
                job.progress(index / #items * 95, tostring(index) .. "/" .. tostring(#items) .. " instances created")
            end
            task.wait()
        end
    end
    waypoint("bulk create " .. tostring(#created))
    local geometry = waitMeasurable(createdInsts, 2)
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, "bulk create complete") end
    return ok({ created = created, count = #created, errors = errors, geometry = geometry })
end

tools.clone_instance = function(args)
    local source, err = resolveRef(args.ref or args.path)
    if not source then return fail(err) end
    if source == game then return fail("Cannot clone the DataModel.") end

    local parent = source.Parent
    if args.parentRef or args.parentPath then
        local resolved, parentErr = resolveRef(args.parentRef or args.parentPath)
        if not resolved then return fail(parentErr) end
        parent = resolved
    end

    local count = math.floor(tonumber(args.count) or 1)
    if count < 1 then count = 1 end
    if count > 500 then return failCode("BUDGET_EXCEEDED", "Refusing to clone more than 500 copies at once.", { sampleLimit = 500 }) end

    local offset = decodeValue(args.offset)
    if typeof(offset) ~= "Vector3" then offset = Vector3.new(0, 0, 0) end
    local rotationStep = tonumber(args.rotateStep) or 0
    local nameTemplate = args.nameTemplate
    local job = args._job

    local copies = {}
    local wasArchivable = source.Archivable
    if not wasArchivable then source.Archivable = true end
    for index = 1, count do
        local copy = source:Clone()
        if copy == nil then
            source.Archivable = wasArchivable
            return fail("Clone failed (Archivable is false or the instance cannot be copied).")
        end
        if nameTemplate then
            copy.Name = string.gsub(tostring(nameTemplate), "{n}", tostring(index))
        end
        copy.Parent = parent
        if offset.Magnitude > 0 or rotationStep ~= 0 then
            local pivot = getPivotOf(copy)
            if pivot then
                local moved = pivot + (offset * index)
                if rotationStep ~= 0 then
                    moved = moved * CFrame.Angles(0, math.rad(rotationStep * index), 0)
                end
                setPivotOf(copy, moved)
            end
        end
        table.insert(copies, describeRef(copy))
        if index % 16 == 0 then
            if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                source.Archivable = wasArchivable
                return failCode("COMMAND_CANCELLED", "clone_instance job was cancelled after partial cloning.", { clones = copies, count = #copies, requested = count })
            end
            if type(job) == "table" and type(job.progress) == "function" then
                job.progress(index / count * 95, tostring(index) .. "/" .. tostring(count) .. " copies created")
            end
            task.wait()
        end
    end
    source.Archivable = wasArchivable
    waypoint("clone " .. tostring(count) .. "x " .. source.Name)
    local copiedInsts = {}
    for _, c in ipairs(copies) do
        local inst = resolveRef(c.id)
        if inst and inst:IsA("BasePart") and #copiedInsts < 8 then table.insert(copiedInsts, inst) end
    end
    local geometry = waitMeasurable(copiedInsts, 2)
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, "clone complete") end
    return ok({ clones = copies, count = #copies, source = describeRef(source), geometry = geometry })
end

tools.delete_instance = function(args)
    local inst, err = resolveRef(args.ref or args.path)
    if not inst then return fail(err) end
    if inst == game then return fail("Cannot delete the DataModel.") end
    local info = describeRef(inst)
    inst:Destroy()
    waypoint("delete " .. tostring(info.name))
    return ok({ deleted = info })
end

tools.bulk_delete = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    local deleted = {}
    for _, inst in ipairs(list) do
        if inst ~= game then
            local info = describeRef(inst)
            local okDelete = pcall(function() inst:Destroy() end)
            if okDelete then
                table.insert(deleted, info)
            else
                table.insert(errors, "Could not delete " .. tostring(info.path))
            end
        end
    end
    waypoint("bulk delete " .. tostring(#deleted))
    return ok({ deleted = deleted, count = #deleted, errors = errors })
end

tools.rename_instance = function(args)
    local inst, err = resolveRef(args.ref or args.path)
    if not inst then return fail(err) end
    inst.Name = tostring(args.name or inst.Name)
    waypoint("rename")
    return ok(describeRef(inst))
end

tools.move_instance = function(args)
    local list, errors = resolveMany(args.refs or args.ref or args.path)
    local parent, parentErr = resolveRef(args.parentRef or args.parentPath)
    if not parent then return fail(parentErr) end
    local moved = {}
    for _, inst in ipairs(list) do
        if inst ~= game then
            local okMove = pcall(function() inst.Parent = parent end)
            if okMove then
                table.insert(moved, describeRef(inst))
            else
                table.insert(errors, "Could not move " .. inst.Name)
            end
        end
    end
    waypoint("move")
    return ok({ moved = moved, parent = describeRef(parent), errors = errors })
end

tools.set_property = function(args)
    local list, errors = resolveMany(args.refs or args.ref or args.path)
    if #list == 0 then return fail("No instance resolved. " .. table.concat(errors, " ")) end
    local property = tostring(args.property or "")
    if property == "" then return fail("property missing.") end
    local changed = {}
    for _, inst in ipairs(list) do
        local okSet, err = setProperty(inst, property, args.value)
        if okSet then
            table.insert(changed, describeRef(inst))
        else
            table.insert(errors, inst.Name .. ": " .. tostring(err))
        end
    end
    waypoint("set " .. property)
    return ok({ changed = changed, count = #changed, property = property, errors = errors })
end

tools.set_properties = function(args)
    local list, errors = resolveMany(args.refs or args.ref or args.path)
    if #list == 0 then return fail("No instance resolved. " .. table.concat(errors, " ")) end
    local changed = {}
    for _, inst in ipairs(list) do
        local problems = applyProperties(inst, args.properties)
        for _, problem in ipairs(problems) do
            table.insert(errors, inst.Name .. ": " .. problem)
        end
        table.insert(changed, describeRef(inst))
    end
    waypoint("set properties")
    return ok({ changed = changed, count = #changed, errors = errors })
end

tools.bulk_set_properties = function(args)
    local items = args.items or {}
    local changed = {}
    local errors = {}
    for index, item in ipairs(items) do
        local inst, err = resolveRef(item.ref or item.path)
        if inst then
            local problems = applyProperties(inst, item.properties)
            for _, problem in ipairs(problems) do
                table.insert(errors, "item " .. tostring(index) .. " " .. problem)
            end
            table.insert(changed, describeRef(inst))
        else
            table.insert(errors, "item " .. tostring(index) .. ": " .. tostring(err))
        end
    end
    waypoint("bulk set properties")
    return ok({ changed = changed, count = #changed, errors = errors })
end

tools.set_attribute = function(args)
    local list, errors = resolveMany(args.refs or args.ref or args.path)
    if #list == 0 then return fail("No instance resolved.") end
    for _, inst in ipairs(list) do
        local okSet, err = pcall(function()
            inst:SetAttribute(tostring(args.name), decodeValue(args.value))
        end)
        if not okSet then table.insert(errors, tostring(err)) end
    end
    waypoint("set attribute")
    return ok({ count = #list, attribute = args.name, errors = errors })
end

tools.add_tag = function(args)
    local list = resolveMany(firstNonEmpty(args.refs, args.ref))
    for _, inst in ipairs(list) do
        pcall(function() CollectionService:AddTag(inst, tostring(args.tag)) end)
    end
    return ok({ count = #list, tag = args.tag })
end

tools.remove_tag = function(args)
    local list = resolveMany(firstNonEmpty(args.refs, args.ref))
    for _, inst in ipairs(list) do
        pcall(function() CollectionService:RemoveTag(inst, tostring(args.tag)) end)
    end
    return ok({ count = #list, tag = args.tag })
end

tools.group_instances = function(args)
    local list, errors = resolveMany(args.refs)
    if #list < 1 then return fail("Need at least one instance. " .. table.concat(errors, " ")) end
    local parent = list[1].Parent
    if args.parentRef then
        local resolved = resolveRef(args.parentRef)
        if resolved then parent = resolved end
    end
    local model = Instance.new(args.className or "Model")
    model.Name = args.name or "Group"
    model.Parent = parent
    for _, inst in ipairs(list) do
        pcall(function() inst.Parent = model end)
    end
    if model:IsA("Model") then
        local firstPart = nil
        for _, inst in ipairs(list) do
            if inst:IsA("BasePart") then firstPart = inst break end
        end
        if firstPart then
            pcall(function() model.PrimaryPart = firstPart end)
        end
    end
    waypoint("group")
    return ok({ group = describeRef(model), count = #list })
end

tools.ungroup = function(args)
    local model, err = resolveRef(args.ref)
    if not model then return fail(err) end
    local parent = model.Parent
    local moved = {}
    for _, child in ipairs(model:GetChildren()) do
        local okMove = pcall(function() child.Parent = parent end)
        if okMove then table.insert(moved, describeRef(child)) end
    end
    model:Destroy()
    waypoint("ungroup")
    return ok({ moved = moved, count = #moved })
end

-- ------------------------- Skripte ------------------------------------------
tools.get_script = function(args)
    local inst, err = resolveRef(args.ref or args.path)
    if not inst then return fail(err) end
    if not inst:IsA("LuaSourceContainer") then
        return fail("'" .. inst.Name .. "' is a " .. inst.ClassName .. ", not a script.")
    end
    local source = inst.Source
    local lines = splitLines(source)
    local startLine = tonumber(args.startLine) or 1
    local endLine = tonumber(args.endLine) or #lines
    if startLine < 1 then startLine = 1 end
    if endLine > #lines then endLine = #lines end

    local selected = {}
    for index = startLine, endLine do
        if args.withLineNumbers == false then
            table.insert(selected, lines[index])
        else
            table.insert(selected, string.format("%5d| %s", index, lines[index]))
        end
    end
    local text = table.concat(selected, "\n")

    return ok({
        id         = idOf(inst),
        path       = pathOf(inst),
        className  = inst.ClassName,
        totalLines = #lines,
        totalBytes = #source,
        startLine  = startLine,
        endLine    = endLine,
        hash       = hashString(source),
        source     = text,
        hint       = "Use patch_script with small unique snippets instead of rewriting the whole file. Pass the hash as expectHash to make sure nobody changed the script in between.",
    })
end

tools.find_in_script = function(args)
    local inst, err = resolveRef(args.ref or args.path)
    if not inst then return fail(err) end
    if not inst:IsA("LuaSourceContainer") then return fail("Not a script.") end
    local source = inst.Source
    local needle = tostring(args.query or args.find or "")
    if needle == "" then return fail("query missing.") end
    local plain = not (args.regex == true)
    local hits = findOccurrences(source, needle, plain)
    local contextLines = tonumber(args.contextLines) or 2
    local results = {}
    for _, hit in ipairs(hits) do
        table.insert(results, {
            line = hit.line,
            offset = hit.from,
            preview = previewAround(source, hit.line, contextLines),
        })
        if #results >= (tonumber(args.limit) or 40) then break end
    end
    return ok({ matches = results, count = #hits, totalLines = select(2, string.gsub(source, "\n", "\n")) + 1, hash = hashString(source) })
end

tools.set_script_source = function(args)
    local inst, err = resolveRef(args.ref or args.path)
    if not inst then return fail(err) end
    if not inst:IsA("LuaSourceContainer") then return fail("Not a script.") end
    local newSource = tostring(args.source or "")
    local oldSource = inst.Source
    if args.expectHash and args.expectHash ~= hashString(oldSource) then
        return fail("The script changed since you read it (hash mismatch). Read it again with get_script before writing.", { currentHash = hashString(oldSource) })
    end
    inst.Source = newSource
    waypoint("script " .. inst.Name)
    local warnings = nil
    if #oldSource > 4000 and #newSource < #oldSource * 0.6 then
        warnings = { "The new source is much shorter than the old one (" .. tostring(#oldSource) .. " -> " .. tostring(#newSource) .. " bytes). If that was not intended, use undo and switch to patch_script." }
    end
    -- Version 7.2.0: Code-Struktur messen statt nur Bytes zaehlen.
    local codeLayout = nil
    if UI_ENGINE and UI_ENGINE.codeLayoutReport then codeLayout = UI_ENGINE.codeLayoutReport(newSource) end
    local layoutWarning = nil
    if UI_ENGINE and UI_ENGINE.describeCodeLayout then layoutWarning = UI_ENGINE.describeCodeLayout(codeLayout) end
    if layoutWarning then
        if warnings then table.insert(warnings, layoutWarning) else warnings = { layoutWarning } end
    end
    return ok({
        id = idOf(inst),
        path = pathOf(inst),
        codeLayout = codeLayout,
        bytes = #newSource,
        lines = select(2, string.gsub(newSource, "\n", "\n")) + 1,
        previousLines = select(2, string.gsub(oldSource, "\n", "\n")) + 1,
        previousBytes = #oldSource,
        hash = hashString(newSource),
    }, warnings)
end

-- Punktgenaue Aenderungen: nur die betroffene Stelle wird ersetzt.
tools.patch_script = function(args)
    local inst, err = resolveRef(args.ref or args.path)
    if not inst then return fail(err) end
    if not inst:IsA("LuaSourceContainer") then return fail("Not a script.") end

    local source = inst.Source
    if args.expectHash and args.expectHash ~= hashString(source) then
        return fail("The script changed since you read it (hash mismatch). Read it again with get_script.", { currentHash = hashString(source) })
    end

    local edits = args.edits
    if edits == nil and args.edit then edits = { args.edit } end
    if type(edits) ~= "table" or #edits == 0 then
        return fail("patch_script needs 'edits': a list like [{op='replace', find='...', replace='...'}].")
    end

    local report = {}
    local working = source
    for index, edit in ipairs(edits) do
        local newText, editError = applyEdit(working, edit, report)
        if newText == nil then
            return fail("Edit " .. tostring(index) .. " failed: " .. tostring(editError), {
                appliedBefore = report,
                unchanged = true,
                hash = hashString(source),
            })
        end
        working = newText
    end

    local oldLines = select(2, string.gsub(source, "\n", "\n")) + 1
    local newLines = select(2, string.gsub(working, "\n", "\n")) + 1

    if args.dryRun == true then
        return ok({
            dryRun = true,
            wouldChange = (working ~= source),
            operations = report,
            oldLines = oldLines,
            newLines = newLines,
            preview = string.sub(working, 1, 2000),
        })
    end

    inst.Source = working
    waypoint("patch " .. inst.Name)

    local firstLine = nil
    for _, entry in ipairs(report) do
        firstLine = entry.line or entry.startLine or entry.firstLine or entry.atLine
        if firstLine then break end
    end

    -- Version 7.2.0: Auch nach einer punktgenauen Aenderung die Struktur messen -
    -- so waechst kein Skript unbemerkt zum Monolithen.
    local codeLayout = nil
    local layoutWarnings = nil
    if UI_ENGINE and UI_ENGINE.codeLayoutReport then
        codeLayout = UI_ENGINE.codeLayoutReport(working)
        if UI_ENGINE.describeCodeLayout then
            local layoutWarning = UI_ENGINE.describeCodeLayout(codeLayout)
            if layoutWarning then layoutWarnings = { layoutWarning } end
        end
    end

    return ok({
        id = idOf(inst),
        path = pathOf(inst),
        codeLayout = codeLayout,
        operations = report,
        oldLines = oldLines,
        newLines = newLines,
        lineDelta = newLines - oldLines,
        bytes = #working,
        hash = hashString(working),
        preview = firstLine and previewAround(working, firstLine, 4) or nil,
    }, layoutWarnings)
end

tools.insert_script = function(args)
    local parent, err = resolveRef(args.parentRef or args.parentPath or "game.ServerScriptService")
    if not parent then return fail(err) end
    local className = args.className or "Script"
    local created = Instance.new(className)
    created.Name = args.name or className
    local okSource = pcall(function() created.Source = tostring(args.source or "") end)
    if not okSource then
        created:Destroy()
        return fail("'" .. className .. "' has no Source property. Use Script, LocalScript or ModuleScript.")
    end
    if args.properties then applyProperties(created, args.properties) end
    created.Parent = parent
    waypoint("insert script")
    -- Version 7.2.0: Code-Struktur messen (siehe UI_ENGINE.codeLayoutReport).
    local codeLayout = nil
    local layoutWarnings = nil
    if UI_ENGINE and UI_ENGINE.codeLayoutReport then
        codeLayout = UI_ENGINE.codeLayoutReport(tostring(args.source or ""))
        if UI_ENGINE.describeCodeLayout then
            local layoutWarning = UI_ENGINE.describeCodeLayout(codeLayout)
            if layoutWarning then layoutWarnings = { layoutWarning } end
        end
    end
    return ok({
        id = idOf(created),
        path = pathOf(created),
        codeLayout = codeLayout,
        className = created.ClassName,
        lines = select(2, string.gsub(created.Source, "\n", "\n")) + 1,
        hash = hashString(created.Source),
    }, layoutWarnings)
end

tools.bulk_insert_scripts = function(args)
    local items = args.items or {}
    local created = {}
    local errors = {}
    for index, item in ipairs(items) do
        local result = tools.insert_script(item)
        if result.ok then
            table.insert(created, result.result)
            -- Version 7.2.0: Code-Struktur-Warnungen auch im Sammelaufruf melden.
            if result.warnings ~= nil then
                for _, warning in ipairs(result.warnings) do
                    table.insert(errors, "item " .. tostring(index) .. " (Hinweis): " .. tostring(warning))
                end
            end
        else
            table.insert(errors, "item " .. tostring(index) .. ": " .. tostring(result.error))
        end
    end
    return ok({ created = created, count = #created, errors = errors })
end

-- ------------------------- Bauhilfe -----------------------------------------
tools.place_on = function(args)
    local mover, errA = resolveRef(args.ref)
    local target, errB = resolveRef(args.targetRef)
    if not mover then return fail(errA) end
    if not target then return fail(errB) end
    local result, err = placeOnFace(
        mover, target,
        args.face or "top",
        tonumber(args.offsetX) or tonumber(args.offsetU) or 0,
        tonumber(args.offsetZ) or tonumber(args.offsetV) or 0,
        tonumber(args.gap) or 0,
        args.inside == true,
        args.matchRotation == true
    )
    if not result then return fail(err) end
    waypoint("place on")
    return ok(result)
end

tools.align = tools.place_on

-- "align" ist derselbe Befehl wie place_on (nur ein anderer Name dafuer).
tools.align = function(args)
    return tools.place_on(args)
end

tools.stack = function(args)
    local list, errors = resolveMany(args.refs)
    if #list < 1 then return fail("Need at least one instance. " .. table.concat(errors, " ")) end
    local axis = string.lower(tostring(args.axis or "y"))
    local gap = tonumber(args.gap) or 0
    local base = nil
    if args.baseRef then
        base = resolveRef(args.baseRef)
    end

    local results = {}
    local cursor = nil
    if base then
        local cframe, size = boundsOf(base)
        if cframe then
            if axis == "y" then cursor = cframe.Position.Y + size.Y / 2
            elseif axis == "x" then cursor = cframe.Position.X + size.X / 2
            else cursor = cframe.Position.Z + size.Z / 2 end
        end
    end

    for _, inst in ipairs(list) do
        local cframe, size = boundsOf(inst)
        if cframe then
            local half
            if axis == "y" then half = size.Y / 2 elseif axis == "x" then half = size.X / 2 else half = size.Z / 2 end
            if cursor == nil then
                if axis == "y" then cursor = cframe.Position.Y - half
                elseif axis == "x" then cursor = cframe.Position.X - half
                else cursor = cframe.Position.Z - half end
            end
            local position = cframe.Position
            local newPosition
            if axis == "y" then
                newPosition = Vector3.new(position.X, cursor + gap + half, position.Z)
            elseif axis == "x" then
                newPosition = Vector3.new(cursor + gap + half, position.Y, position.Z)
            else
                newPosition = Vector3.new(position.X, position.Y, cursor + gap + half)
            end
            if args.alignToBase == true and base then
                local baseCFrame = boundsOf(base)
                if baseCFrame then
                    if axis == "y" then
                        newPosition = Vector3.new(baseCFrame.Position.X, newPosition.Y, baseCFrame.Position.Z)
                    end
                end
            end
            setPivotOf(inst, CFrame.new(newPosition) * (cframe - cframe.Position))
            cursor = cursor + gap + half * 2
            table.insert(results, { instance = describeRef(inst), position = { x = newPosition.X, y = newPosition.Y, z = newPosition.Z } })
        end
    end
    waypoint("stack")
    return ok({ stacked = results, count = #results, axis = axis })
end

tools.grid_arrange = function(args)
    local list, errors = resolveMany(args.refs)
    if #list == 0 then return fail("Need instances. " .. table.concat(errors, " ")) end
    local columns = tonumber(args.columns) or math.ceil(math.sqrt(#list))
    local spacingX = tonumber(args.spacingX) or tonumber(args.spacing) or 10
    local spacingZ = tonumber(args.spacingZ) or tonumber(args.spacing) or 10
    local origin = decodeValue(args.origin)
    if typeof(origin) ~= "Vector3" then
        local firstCFrame = getPivotOf(list[1])
        origin = firstCFrame and firstCFrame.Position or Vector3.new(0, 0, 0)
    end
    local placed = {}
    for index, inst in ipairs(list) do
        local column = (index - 1) % columns
        local row = math.floor((index - 1) / columns)
        local position = origin + Vector3.new(column * spacingX, 0, row * spacingZ)
        local pivot = getPivotOf(inst)
        local rotation = pivot and (pivot - pivot.Position) or CFrame.new()
        setPivotOf(inst, CFrame.new(position) * rotation)
        table.insert(placed, { instance = describeRef(inst), position = { x = position.X, y = position.Y, z = position.Z } })
    end
    waypoint("grid")
    return ok({ placed = placed, count = #placed, columns = columns })
end

tools.distribute = function(args)
    local list, errors = resolveMany(args.refs)
    if #list < 2 then return fail("Need at least two instances.") end
    local axis = string.lower(tostring(args.axis or "x"))
    local spacing = tonumber(args.spacing)
    local pivots = {}
    for _, inst in ipairs(list) do
        table.insert(pivots, getPivotOf(inst))
    end
    local startPosition = pivots[1].Position
    local endPosition = pivots[#pivots].Position
    local placed = {}
    for index, inst in ipairs(list) do
        local factor = (index - 1) / (#list - 1)
        local position
        if spacing then
            local step = Vector3.new(axis == "x" and spacing or 0, axis == "y" and spacing or 0, axis == "z" and spacing or 0)
            position = startPosition + step * (index - 1)
        else
            position = startPosition:Lerp(endPosition, factor)
        end
        local rotation = pivots[index] - pivots[index].Position
        setPivotOf(inst, CFrame.new(position) * rotation)
        table.insert(placed, { instance = describeRef(inst), position = { x = position.X, y = position.Y, z = position.Z } })
    end
    waypoint("distribute")
    return ok({ placed = placed, count = #placed })
end

tools.snap_to_ground = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    if #list == 0 then return failCode("REF_NOT_FOUND", "No instance resolved. " .. table.concat(errors, " ")) end
    if #list > 500 then return failCode("REGION_LIMIT", "Too many objects to snap (" .. tostring(#list) .. ", max 500). Split the selection.") end
    local offset = tonumber(args.offset) or 0
    local maxDrop = tonumber(args.maxDrop or args.maxFall) or 2000
    local extraExclusions = resolveExcluded(firstNonEmpty(args.ignore, args.exclude))
    local results = {}
    local movedInstances = {}
    local job = args._job
    for index, inst in ipairs(list) do
        local cframe, size = boundsOf(inst)
        if cframe and size then
            local exclusions = { inst }
            for _, ignored in ipairs(extraExclusions) do table.insert(exclusions, ignored) end
            local origin = cframe.Position
            local hit = Workspace:Raycast(origin, Vector3.new(0, -4000, 0), measureRayParams(exclusions))
            if hit then
                local newY = hit.Position.Y + size.Y / 2 + offset
                local drop = origin.Y - newY
                if maxDrop and drop > maxDrop then
                    table.insert(results, {
                        instance = describeRef(inst),
                        note = "Ground is " .. string.format("%.1f", drop) .. " studs below (maxDrop " .. tostring(maxDrop)
                            .. ") - NOT moved. Pass a bigger maxDrop if that is intended.",
                        ground = describeRef(hit.Instance),
                    })
                else
                    setPivotOf(inst, CFrame.new(origin.X, newY, origin.Z) * (cframe - cframe.Position))
                    table.insert(movedInstances, inst)
                    table.insert(results, { instance = describeRef(inst), y = newY, ground = describeRef(hit.Instance) })
                end
            else
                table.insert(results, { instance = describeRef(inst), note = "Nothing below - not moved." })
            end
        end
        if index % 64 == 0 then
            if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                return failCode("COMMAND_CANCELLED", "Snap-to-ground job was cancelled.", { moved = #results, total = #list })
            end
            if type(job) == "table" and type(job.progress) == "function" then
                job.progress(index / #list * 100, tostring(index) .. "/" .. tostring(#list) .. " objects checked")
            end
            task.wait()
        end
    end
    local measurable = nil
    if args.waitForMeasurable ~= false and #movedInstances > 0 then
        local check = {}
        for index = 1, math.min(10, #movedInstances) do table.insert(check, movedInstances[index]) end
        measurable = waitMeasurable(check, math.max(0, math.min(tonumber(args.waitSeconds) or 2, 10)))
    end
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, "snap to ground complete") end
    waypoint("snap to ground")
    return ok({ results = results, count = #results, measurable = measurable })
end

tools.look_at = function(args)
    local inst, err = resolveRef(args.ref)
    if not inst then return fail(err) end
    local targetPosition = nil
    if args.targetRef then
        local target = resolveRef(args.targetRef)
        if target then
            local cframe = getPivotOf(target)
            if cframe then targetPosition = cframe.Position end
        end
    end
    if targetPosition == nil then
        local decoded = decodeValue(args.position)
        if typeof(decoded) == "Vector3" then targetPosition = decoded end
    end
    if targetPosition == nil then return fail("Need targetRef or position.") end
    local pivot = getPivotOf(inst)
    if pivot == nil then return fail("Instance has no position.") end
    local newCFrame = CFrame.lookAt(pivot.Position, targetPosition)
    if args.keepUpright == true then
        newCFrame = CFrame.lookAt(pivot.Position, Vector3.new(targetPosition.X, pivot.Position.Y, targetPosition.Z))
    end
    setPivotOf(inst, newCFrame)
    waypoint("look at")
    return ok({ instance = describeRef(inst), cframe = encodeValue(newCFrame) })
end

tools.coordinate_guide = function(args)
    local system = {
        axes = "+X = right (east), +Y = up, +Z = toward the default camera (south). The default Studio camera looks toward -Z, so the front face of a fresh part (-Z) points AWAY from the default camera (north).",
        yaw = "Rotation around +Y in degrees, positive = counter-clockwise seen from above. A yaw of d degrees turns the front face to world direction (-sin d, 0, -cos d) - so positive yaw turns the front toward -X (west/left).",
        cframe = "CFrame values come back in degrees (orientation) and radians (orientationRadians). pitch = around X, yaw = around Y, roll = around Z.",
        shapeDefaults = {
            block = "Axis aligned - no hidden orientation.",
            ball = "Sphere - no faces.",
            cylinder = "Length axis is VERTICAL (local Y) by default, flat caps on top and bottom.",
            wedge = "A ramp - the high edge and slope direction are MEASURED per part (see the measured section below).",
        },
        workflow = "1) coordinate_guide (once per session) 2) describe_orientation on the part 3) point_at (axis='top' for a cylinder's length) or rotate_around with the measured axis 4) describe_orientation again to verify.",
    }
    local measured = {}
    local refs = args.refs or args.ref
    if refs then
        local list, _ = resolveMany(refs)
        for _, inst in ipairs(list) do
            local shape = measureShape(inst)
            if shape then table.insert(measured, { instance = describeRef(inst), shape = shape }) end
        end
    else
        local limit = tonumber(args.limit) or 12
        local root, err = resolveRef(args.rootRef or "game.Workspace")
        if not root then return failCode("REF_NOT_FOUND", err) end
        for _, inst in ipairs(root:GetDescendants()) do
            if #measured >= limit then break end
            if inst:IsA("BasePart") and (inst.Shape == Enum.PartType.Cylinder
                or inst.Shape == Enum.PartType.Wedge or inst.Shape == Enum.PartType.Ball) then
                local shape = measureShape(inst)
                if shape then table.insert(measured, { instance = describeRef(inst), shape = shape }) end
            end
        end
    end
    return ok({
        system = system,
        measured = measured,
        note = "The measured values are raycast results from right now - not guesses. They are cached per part and re-measured automatically when position/size/shape change.",
    })
end

tools.describe_orientation = function(args)
    local inst, err = resolveRef(args.ref)
    if not inst then return failCode("REF_NOT_FOUND", err) end
    local cframe = getPivotOf(inst)
    if cframe == nil then return failCode("BAD_ARGS", "Instance has no CFrame.") end
    local rx, ry, rz = cframe:ToOrientation()
    local result = {
        instance = describeRef(inst),
        faces = facesOf(cframe),
        rotation = { pitch = math.deg(rx), yaw = math.deg(ry), roll = math.deg(rz) },
        note = "front = the part's -Z face (the face a model would look out of). Positive yaw turns the front toward -X.",
    }
    local shape = measureShape(inst)
    if shape then result.shape = shape end
    return ok(result)
end

tools.point_at = function(args)
    local inst, errA = resolveRef(args.ref)
    if not inst then return failCode("REF_NOT_FOUND", errA) end
    local targetPosition = nil
    if args.targetRef then
        local target, errT = resolveRef(args.targetRef)
        if not target then return failCode("REF_NOT_FOUND", errT) end
        local cframe = getPivotOf(target)
        if cframe then targetPosition = cframe.Position end
    end
    if targetPosition == nil then
        local decoded = decodeValue(args.position)
        if typeof(decoded) == "Vector3" then targetPosition = decoded end
    end
    if targetPosition == nil then return failCode("BAD_ARGS", "Need targetRef or position {x,y,z}.") end
    local pivot = getPivotOf(inst)
    if pivot == nil then return failCode("BAD_ARGS", "Instance has no CFrame.") end
    local axis = string.lower(tostring(args.axis or "front"))
    if axis ~= "front" and axis ~= "back" and axis ~= "top" and axis ~= "bottom"
        and axis ~= "left" and axis ~= "right" then
        return failCode("BAD_ARGS", "axis must be front, back, top, bottom, left or right.")
    end
    local dir = targetPosition - pivot.Position
    if dir.Magnitude < 0.001 then return failCode("BAD_ARGS", "Target is at the same position.") end
    dir = dir.Unit
    local newCFrame
    if axis == "front" then
        newCFrame = CFrame.lookAt(pivot.Position, targetPosition)
    elseif axis == "back" then
        newCFrame = CFrame.lookAt(pivot.Position, pivot.Position - dir)
    elseif axis == "left" then
        newCFrame = CFrame.lookAt(pivot.Position, targetPosition) * CFrame.Angles(0, math.rad(-90), 0)
    elseif axis == "right" then
        newCFrame = CFrame.lookAt(pivot.Position, targetPosition) * CFrame.Angles(0, math.rad(90), 0)
    elseif axis == "top" then
        -- Längenachse (lokal Y, z.B. Zylinder) zeigt zum Ziel
        local ref = math.abs(dir.Y) > 0.9 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
        local right = ref:Cross(dir).Unit
        local look = right:Cross(dir)
        newCFrame = CFrame.fromMatrix(pivot.Position, right, dir, look)
    else
        local up = -dir
        local ref = math.abs(up.Y) > 0.9 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
        local right = ref:Cross(up).Unit
        local look = right:Cross(up)
        newCFrame = CFrame.fromMatrix(pivot.Position, right, up, look)
    end
    setPivotOf(inst, newCFrame)
    waypoint("point at")
    return ok({
        instance = describeRef(inst),
        axis = axis,
        target = encodeValue(targetPosition),
        cframe = encodeValue(newCFrame),
        facesNow = {
            front = dirHeading(newCFrame:VectorToWorldSpace(Vector3.new(0, 0, -1))),
            back  = dirHeading(newCFrame:VectorToWorldSpace(Vector3.new(0, 0, 1))),
            top   = dirHeading(newCFrame:VectorToWorldSpace(Vector3.new(0, 1, 0))),
        },
        hint = "Verify with describe_orientation - it includes the measured shape facts (wedge high edge, cylinder axis).",
    })
end

tools.rotate_around = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    if #list == 0 then return fail("No instance resolved.") end
    local degrees = tonumber(args.degrees) or 0
    local axisName = string.lower(tostring(args.axis or "y"))
    local axis = Vector3.new(0, 1, 0)
    if axisName == "x" then axis = Vector3.new(1, 0, 0) end
    if axisName == "z" then axis = Vector3.new(0, 0, 1) end

    local pivotPosition = decodeValue(args.pivot)
    if typeof(pivotPosition) ~= "Vector3" then
        if args.pivotRef then
            local target = resolveRef(args.pivotRef)
            local cframe = target and getPivotOf(target)
            if cframe then pivotPosition = cframe.Position end
        end
    end
    if typeof(pivotPosition) ~= "Vector3" then
        local cframe = getPivotOf(list[1])
        pivotPosition = cframe and cframe.Position or Vector3.new(0, 0, 0)
    end

    local rotation = CFrame.fromAxisAngle(axis, math.rad(degrees))
    local results = {}
    for _, inst in ipairs(list) do
        local pivot = getPivotOf(inst)
        if pivot then
            local relative = pivot.Position - pivotPosition
            local rotated = rotation * relative
            local newCFrame = CFrame.new(pivotPosition + rotated) * rotation * (pivot - pivot.Position)
            setPivotOf(inst, newCFrame)
            table.insert(results, describeRef(inst))
        end
    end
    waypoint("rotate around")
    return ok({ rotated = results, count = #results, degrees = degrees, axis = axisName })
end

tools.move_relative = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    if #list == 0 then return fail("No instance resolved. " .. table.concat(errors, " ")) end
    local right = tonumber(args.right) or tonumber(args.x) or 0
    local up = tonumber(args.up) or tonumber(args.y) or 0
    local forward = tonumber(args.forward) or tonumber(args.z) or 0
    local space = string.lower(tostring(args.space or "world"))
    local results = {}
    for _, inst in ipairs(list) do
        local pivot = getPivotOf(inst)
        if pivot then
            local newCFrame
            if space == "local" or space == "object" then
                newCFrame = pivot * CFrame.new(right, up, -forward)
            else
                newCFrame = pivot + Vector3.new(right, up, forward)
            end
            setPivotOf(inst, newCFrame)
            table.insert(results, { instance = describeRef(inst), position = encodeValue(newCFrame.Position) })
        end
    end
    waypoint("move relative")
    return ok({ moved = results, count = #results })
end

tools.resize_part = function(args)
    local inst, err = resolveRef(args.ref)
    if not inst then return fail(err) end
    if not inst:IsA("BasePart") then return fail("resize_part works on BaseParts. For models scale each part or use a Model:ScaleTo call via run_lua.") end
    local newSize = decodeValue(args.size)
    if typeof(newSize) ~= "Vector3" then return fail("size must be {x,y,z}.") end
    local anchor = string.lower(tostring(args.anchor or "center"))
    local oldSize = inst.Size
    local oldCFrame = inst.CFrame
    inst.Size = newSize
    if anchor == "bottom" then
        inst.CFrame = oldCFrame * CFrame.new(0, (newSize.Y - oldSize.Y) / 2, 0)
    elseif anchor == "top" then
        inst.CFrame = oldCFrame * CFrame.new(0, -(newSize.Y - oldSize.Y) / 2, 0)
    end
    waypoint("resize")
    return ok({ instance = describeRef(inst), size = encodeValue(inst.Size), position = encodeValue(inst.Position) })
end

tools.fit_between = function(args)
    local inst, err = resolveRef(args.ref)
    if not inst then return fail(err) end
    if not inst:IsA("BasePart") then return fail("fit_between needs a BasePart.") end
    local pointA = decodeValue(args.from)
    local pointB = decodeValue(args.to)
    if typeof(pointA) ~= "Vector3" and args.fromRef then
        local target = resolveRef(args.fromRef)
        local cframe = target and getPivotOf(target)
        if cframe then pointA = cframe.Position end
    end
    if typeof(pointB) ~= "Vector3" and args.toRef then
        local target = resolveRef(args.toRef)
        local cframe = target and getPivotOf(target)
        if cframe then pointB = cframe.Position end
    end
    if typeof(pointA) ~= "Vector3" or typeof(pointB) ~= "Vector3" then
        return fail("Need from/to as {x,y,z} or fromRef/toRef.")
    end
    local thickness = tonumber(args.thickness) or 1
    local distance = (pointB - pointA).Magnitude
    inst.Size = Vector3.new(thickness, thickness, distance)
    inst.CFrame = CFrame.lookAt((pointA + pointB) / 2, pointB)
    waypoint("fit between")
    return ok({ instance = describeRef(inst), length = distance })
end

tools.overlap_check = function(args)
    local list, errors = resolveMany(firstNonEmpty(args.refs, args.ref))
    if #list == 0 then return failCode("REF_NOT_FOUND", "No instance resolved. " .. table.concat(errors, " ")) end
    if #list > 500 then return failCode("REGION_LIMIT", "Too many objects to check (max 500). Split the selection.") end
    local tolerance = math.max(0, tonumber(args.tolerance) or 0)
    local limit = math.max(0, math.min(tonumber(args.limit) or 50, 500))
    local exList = resolveExcluded(args.excludeRefs or args.ignore)
    for _, inst in ipairs(list) do table.insert(exList, inst) end
    local params = overlapParamsNew(exList)
    local items = {}
    local job = args._job
    for index, inst in ipairs(list) do
        local cframe, size = boundsOf(inst)
        if cframe and size then
            local boxSize = size + Vector3.new(tolerance * 2, tolerance * 2, tolerance * 2)
            local parts = Workspace:GetPartBoundsInBox(cframe.Position, boxSize, params)
            local overlapping = {}
            local matched = 0
            for _, part in ipairs(parts) do
                local classMatches = (not args.className) or part.ClassName == tostring(args.className)
                if classMatches and not part:IsDescendantOf(inst) then
                    matched = matched + 1
                    if #overlapping < limit then table.insert(overlapping, describeRef(part)) end
                end
            end
            table.insert(items, {
                instance = describeRef(inst),
                overlapping = overlapping,
                count = matched,
                clear = (matched == 0),
            })
        end
        if index % 16 == 0 then
            if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                return failCode("COMMAND_CANCELLED", "Overlap check job was cancelled.", { checked = index, total = #list })
            end
            if type(job) == "table" and type(job.progress) == "function" then
                job.progress(index / #list * 100, tostring(index) .. "/" .. tostring(#list) .. " objects checked")
            end
            task.wait()
        end
    end
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, "overlap check complete") end
    if #items == 1 then return ok(items[1]) end
    return ok({ items = items, count = #items })
end

-- ---------------------------------------------------------------------------
-- SOLID MODELING: GRUPPEN + GEMEINSAME AUSFUEHRUNG (FIX 7.0.8)
-- resolveGroups und runSolidOperation fehlten im 7.0.x-Plugin KOMPLETT:
-- tools.union/subtract/negate/intersect riefen globale Namen auf, die es
-- nirgends gab. Die Vorpruefung (precheckSolid), die Dreiecks-Schaetzung und
-- die Fidelity-Helfer standen daneben unbenutzt bereit; hier laufen sie
-- wieder zusammen.
-- ---------------------------------------------------------------------------
local function resolveGroups(kind, args)
    local groups = args.groups
    if type(groups) ~= "table" or #groups == 0 then return nil end
    local resolved = {}
    for index, group in ipairs(groups) do
        local entry = { group = index }
        if type(group) ~= "table" then
            entry.error = "Group " .. tostring(index) .. " must be a table like { refs = { ... }, name = '...' }."
        else
            entry.name = group.name
            local list, errors = resolveMany(group.refs or group.ref or group.parts)
            if #list < 2 then
                local detail = table.concat(errors or {}, " ")
                entry.error = "Group " .. tostring(index) .. " needs at least 2 resolvable parts."
                if detail ~= "" then entry.error = entry.error .. " " .. detail end
            else
                entry.base = list[1]
                entry.others = {}
                for position = 2, #list do
                    table.insert(entry.others, list[position])
                end
            end
        end
        table.insert(resolved, entry)
    end
    return resolved
end

local function runSolidOperation(kind, base, others, args)
    args = args or {}
    local parts = { base }
    for _, part in ipairs(others or {}) do table.insert(parts, part) end
    local warnings, code, message, extra = precheckSolid(parts, 2, args)
    if code then return failCode(code, message, extra) end
    warnings = warnings or {}

    local defaults = ARENA_CFG.SOLID[kind] or ARENA_CFG.SOLID.union
    local name = tostring(args.name or defaults.name)
    local triangles = estimateTriangles(parts)

    -- Undo-Punkt VOR der Aenderung: 1x Rueckgaengig macht genau diese
    -- Solid-Operation rueckgaengig (eigener Schritt, nichts anderes).
    local undoPoint = nil
    if args.undoPoint ~= false then
        undoPoint = "vor " .. defaults.title .. " " .. name
        waypoint(undoPoint)
    end

    -- keepOriginals: Klone, die unsichtbar IM Ergebnis liegen (nur zur
    -- Nachvollziehbarkeit) - die echten Teile verbraucht Solid Modeling.
    local kept = {}
    if args.keepOriginals == true then
        for _, part in ipairs(parts) do
            local okClone, copy = pcall(function() return part:Clone() end)
            if okClone and copy then table.insert(kept, copy) end
        end
    end

    local created = nil
    local okRun, runErr = pcall(function()
        if kind == "subtract" then
            created = base:SubtractAsync(others)
        elseif kind == "intersect" then
            created = base:IntersectAsync(others)
        else
            created = base:UnionAsync(others)
        end
    end)
    if not okRun then
        return failCode("SOLID_REFUSED",
            "Roblox refused the " .. kind .. ": " .. tostring(runErr)
            .. " Solid modeling needs anchored BaseParts that are not razor-thin or degenerate, inside the same DataModel.",
            { partsUsed = #parts, estimatedTriangles = triangles })
    end
    if created == nil then
        return failCode("SOLID_REFUSED",
            "Roblox returned no result for the " .. kind .. ". Check that all parts are anchored, not razor-thin and still in the place.",
            { partsUsed = #parts, estimatedTriangles = triangles })
    end

    pcall(function() created.Name = name end)
    local parent = nil
    if args.parentRef or args.parentPath then
        local wantedParent = resolveRef(args.parentRef or args.parentPath)
        if wantedParent then parent = wantedParent end
    end
    if parent == nil then parent = base.Parent end
    pcall(function() created.Parent = parent end)
    pcall(function() created.Anchored = true end)
    pcall(function() created.CollisionFidelity = collisionFidelityFrom(args.collisionFidelity) end)
    pcall(function() created.RenderFidelity = renderFidelityFrom(args.renderFidelity) end)
    for _, copy in ipairs(kept) do
        pcall(function()
            copy.Transparency = 1
            copy.CanCollide = false
            copy.CanQuery = false
            copy.CanTouch = false
            copy.Anchored = true
            copy.Parent = created
        end)
    end
    if #kept > 0 then
        table.insert(warnings, tostring(#kept) .. " original part(s) were kept as INVISIBLE clones inside the result (keepOriginals=true).")
    end
    local geometry = waitMeasurable({ created }, 2)
    return ok({
        result = describeRef(created),
        partsUsed = #parts,
        bounds = boundsInfo(created),
        triangleEstimate = triangles,
        geometry = geometry,
        undoPoint = undoPoint,
        canBeUndone = (ChangeHistoryService ~= nil),
        keptOriginals = (#kept > 0) and #kept or nil,
    }, warnings)
end

tools.union = function(args)
    local groups = resolveGroups("union", args)
    if groups then
        local results = {}
        for _, g in ipairs(groups) do
            if g.base then
                local gArgs = {}
                for key, value in pairs(args) do gArgs[key] = value end
                gArgs.name = g.name or ("Union" .. tostring(g.group))
                table.insert(results, runSolidOperation("union", g.base, g.others, gArgs))
            else
                table.insert(results, { ok = false, code = "REF_NOT_FOUND", error = g.error })
            end
        end
        return ok({ groups = results, count = #results })
    end
    local parts, errors = resolveMany(args.refs)
    local others = {}
    for ii = 2, #parts do table.insert(others, parts[ii]) end
    local result = runSolidOperation("union", parts[1], others, args)
    if type(errors) == "table" and #errors > 0 then
        if type(result) == "table" then result.resolveErrors = errors end
    end
    return result
end

tools.subtract = function(args)
    local base, err = resolveRef(args.baseRef or args.ref)
    if not base then return failCode("REF_NOT_FOUND", err) end
    local negatives, negErrors = resolveMany(args.negativeRefs or args.refs)
    local result = runSolidOperation("subtract", base, negatives, args)
    if type(negErrors) == "table" and #negErrors > 0 then
        if type(result) == "table" then result.resolveErrors = negErrors end
    end
    return result
end

tools.negate = tools.subtract

tools.intersect = function(args)
    local groups = resolveGroups("intersect", args)
    if groups then
        local results = {}
        for _, g in ipairs(groups) do
            if g.base then
                local gArgs = {}
                for key, value in pairs(args) do gArgs[key] = value end
                gArgs.name = g.name or ("Intersection" .. tostring(g.group))
                table.insert(results, runSolidOperation("intersect", g.base, g.others, gArgs))
            else
                table.insert(results, { ok = false, code = "REF_NOT_FOUND", error = g.error })
            end
        end
        return ok({ groups = results, count = #results })
    end
    local parts, errors = resolveMany(args.refs)
    local others = {}
    for ii = 2, #parts do table.insert(others, parts[ii]) end
    local result = runSolidOperation("intersect", parts[1], others, args)
    if type(errors) == "table" and #errors > 0 then
        if type(result) == "table" then result.resolveErrors = errors end
    end
    return result
end

tools.separate = function(args)
    local inst, err = resolveRef(args.ref)
    if not inst then return fail(err) end
    if not inst:IsA("PartOperation") then
        return fail("'" .. inst.Name .. "' is a " .. inst.ClassName .. ", not a union.")
    end
    local parent = inst.Parent
    local pieces = nil
    local okRun, runErr = pcall(function()
        pieces = inst:SeparateAsync()
    end)
    if not okRun then return fail("SeparateAsync failed: " .. tostring(runErr)) end
    local items = {}
    for _, piece in ipairs(pieces or {}) do
        piece.Parent = parent
        table.insert(items, describeRef(piece))
    end
    pcall(function() inst:Destroy() end)
    waypoint("separate")
    return ok({ pieces = items, count = #items }, { "The pieces are plain parts again. Colours or materials of the original union may not be restored exactly." })
end

tools.union_info = function(args)
    local inst, err = resolveRef(args.ref)
    if not inst then return fail(err) end
    local isUnion = inst:IsA("PartOperation")
    return ok({
        instance = describeRef(inst),
        isUnion = isUnion,
        collisionFidelity = isUnion and tostring(inst.CollisionFidelity) or nil,
        renderFidelity = isUnion and tostring(inst.RenderFidelity) or nil,
        bounds = boundsInfo(inst),
        advice = isUnion and "You cannot inspect the original parts of a union. Call separate to edit them." or "Not a union.",
    })
end

-- ------------------------- FUELLEN (nach GEMESSENER Regel) ------------------
local worldProfile = nil

tools.probe_world = function(args)
    local center = decodeValue(args.center)
    if typeof(center) ~= "Vector3" then center = Vector3.new(0, 0, 0) end
    local radius = tonumber(args.radius) or 40
    local step = tonumber(args.step) or 10
    if radius ~= radius or step ~= step or radius < 0 or step <= 0 then
        return failCode("BAD_ARGS", "radius must be >= 0 and step must be > 0.")
    end
    if step < 1 then step = 1 end
    local axisCount = math.floor((2 * radius + 0.001) / step) + 1
    local estimatedSquare = axisCount * axisCount
    if estimatedSquare > 4000 then
        return failCode("REGION_LIMIT", "probe_world would inspect a grid of " .. tostring(estimatedSquare) .. " points (max 4000). Increase step or reduce radius before measuring.", {
            sampleLimit = 4000, estimatedSquare = estimatedSquare, radius = radius, step = step,
        })
    end
    local params = measureRayParams({})
    local heights = {}
    local waterY = nil
    local total = 0
    local measuredRays = 0
    local job = args._job
    local x = center.X - radius
    while x <= center.X + radius + 0.001 do
        local z = center.Z - radius
        while z <= center.Z + radius + 0.001 do
            local dx = x - center.X
            local dz = z - center.Z
            if dx * dx + dz * dz <= radius * radius then
                total = total + 1
                local hit = Workspace:Raycast(Vector3.new(x, center.Y + 400, z), Vector3.new(0, -800, 0), params)
                if hit then
                    local y = hit.Position.Y
                    table.insert(heights, y)
                    if isWaterLike(hit.Instance) and (waterY == nil or y > waterY) then
                        waterY = y
                    end
                end
                measuredRays = measuredRays + 1
                if measuredRays % 128 == 0 then
                    if type(job) == "table" and type(job.cancelled) == "function" and job.cancelled() then
                        return failCode("COMMAND_CANCELLED", "World probe job was cancelled.", { measured = measuredRays, total = estimatedSquare })
                    end
                    if type(job) == "table" and type(job.progress) == "function" then
                        job.progress(measuredRays / estimatedSquare * 100, tostring(measuredRays) .. " surface points measured")
                    end
                    task.wait()
                end
            end
            z = z + step
        end
        x = x + step
    end
    if #heights < 8 then
        return failCode("BAD_ARGS", "Too few surface samples (" .. tostring(#heights) .. " of " .. tostring(total)
            .. "). Is this place empty here? Try a bigger radius or a center that sits on the ground.")
    end
    -- Gitter-Schritt: haeufigste kleine Differenz zwischen den Flaechen
    table.sort(heights)
    local distinct = {}
    for i = 1, #heights do
        if i == 1 or heights[i] - heights[i - 1] > 0.1 then
            table.insert(distinct, heights[i])
        end
    end
    local diffs = {}
    for i = 2, #distinct do
        table.insert(diffs, distinct[i] - distinct[i - 1])
    end
    local gridStep = nil
    local candidates = { 0.5, 1, 2, 4, 8, 16, 32, 64 }
    for _, cand in ipairs(candidates) do
        local matches = 0
        for _, d in ipairs(diffs) do
            if d > 0.01 then
                local k = math.floor(d / cand + 0.5)
                if k >= 1 and math.abs(d - k * cand) < 0.06 * cand + 0.01 then
                    matches = matches + 1
                end
            end
        end
        if #diffs > 0 and matches / #diffs >= 0.6 then
            gridStep = cand
            break
        end
    end
    local sample = {}
    for i = 1, math.min(40, #heights) do sample[i] = heights[i] end
    local profile = {
        measuredAt = os.time(),
        center = { x = center.X, y = center.Y, z = center.Z },
        radius = radius,
        sampleCount = total,
        surfaceSamples = sample,
        gridStep = gridStep,
        waterY = waterY,
        fillRule = {
            formula = "fresh column: y1 if y1 is divisible by gridStep, else ceil(y1/gridStep)*gridStep + 2. water column: y1 - 2.",
            gridStep = gridStep,
            waterY = waterY,
            note = "Heights are ALWAYS measured per column at fill time (raycast). This profile only fixes the grid step and the water level.",
        },
    }
    worldProfile = profile
    if type(job) == "table" and type(job.progress) == "function" then job.progress(100, tostring(total) .. " surface points measured; profile stored") end
    return ok(profile, { "Stored: fill_region now uses this profile. Re-run probe_world after big terrain changes." })
end

tools.fill_region = function(args)
    local minVec = decodeValue(args.min)
    local maxVec = decodeValue(args.max)
    if typeof(minVec) ~= "Vector3" or typeof(maxVec) ~= "Vector3" then
        return failCode("BAD_ARGS", "min and max must be {x,y,z}.")
    end
    local gridStep = tonumber(args.gridStep)
    if gridStep == nil then
        if worldProfile == nil then
            return failCode("WORLD_NOT_PROBED", "fill_region needs a measured world profile - call probe_world first (or pass an explicit gridStep). Fill heights are never guessed.")
        end
        gridStep = worldProfile.gridStep
        if gridStep == nil then
            return failCode("WORLD_NOT_PROBED", "The measured profile has no reliable grid step - pass gridStep explicitly (e.g. 4).")
        end
    end
    if gridStep <= 0.1 then return failCode("BAD_ARGS", "gridStep must be > 0.1 studs.") end

    local minX, maxX = math.min(minVec.X, maxVec.X), math.max(minVec.X, maxVec.X)
    local minZ, maxZ = math.min(minVec.Z, maxVec.Z), math.max(minVec.Z, maxVec.Z)
    local bottomY = math.min(minVec.Y, maxVec.Y)
    local topY = math.max(minVec.Y, maxVec.Y)
    if topY <= bottomY then return failCode("BAD_ARGS", "max.Y must be above min.Y.") end

    local cols = math.floor((maxX - minX) / gridStep + 0.999) + 1
    local rows = math.floor((maxZ - minZ) / gridStep + 0.999) + 1
    local totalColumns = cols * rows
    if totalColumns > 4000 then
        return failCode("REGION_LIMIT",
            "Region is " .. tostring(totalColumns) .. " grid columns (" .. string.format("%.0f x %.0f", maxX - minX, maxZ - minZ)
            .. " studs at step " .. tostring(gridStep) .. "), max is 4000. Split the region into smaller boxes - every call returns a resumeToken, so the next box continues instead of restarting.",
            { measuredLimit = 4000, regionColumns = totalColumns })
    end
    if (maxX - minX) > 400 or (maxZ - minZ) > 400 then
        return failCode("REGION_LIMIT", "One side of the region is over 400 studs - split it up.", { measuredLimit = 400 })
    end

    local with = args.with or "Air"
    local isAir = (tostring(with) == "Air")
    local fillTo = args.fillTo or "rule"
    local clearBelowFirst = (args.clearBelowFirst ~= false)
    local confirmClear = (args.confirmClear == true)
    local chunkBudget = tonumber(args.chunkBudget) or 200
    local stopOnError = (args.stopOnError == true)

    local created = 0
    local cleared = 0
    local alreadyDone = 0
    local skippedNeedClear = {}
    local skippedNoSurface = 0
    local failedCells = {}
    local createdParts = {}
    local startedAt = os.clock()

    local startIndex = 1
    if type(args.resumeToken) == "table" and tonumber(args.resumeToken.index) then
        startIndex = tonumber(args.resumeToken.index) + 1
        if startIndex > totalColumns then startIndex = totalColumns + 1 end
    end

    local function columnAt(n)
        local col = (n - 1) % cols
        local row = math.floor((n - 1) / cols)
        return minX + col * gridStep, minZ + row * gridStep
    end

    local rayTopY = topY + 500
    local params = measureRayParams({})
    local lastProgressAt = os.clock()

    local function reportProgress(n, force)
        local now = os.clock()
        if force or now - lastProgressAt > 0.2 then
            lastProgressAt = now
            local pct = math.floor((n / totalColumns) * 100)
            local doneCount = n - startIndex + 1
            local rate = doneCount / math.max(0.01, os.clock() - startedAt)
            if args._job then
                args._job.progress(pct, doneCount .. "/" .. tostring(totalColumns) .. " columns, " .. string.format("%.0f", rate) .. " columns/s")
            end
            task.wait(0.01)
        end
    end

    for n = startIndex, totalColumns do
        if args._job and args._job.cancelled() then
            return ok({
                aborted = "cancelled",
                created = created, cleared = cleared, alreadyDone = alreadyDone,
                skippedNeedClear = #skippedNeedClear, skippedNoSurface = skippedNoSurface,
                failedCells = failedCells, totalColumns = totalColumns,
                resumeToken = { index = n - 1 },
                note = "Job cancelled - repeat the call with this resumeToken to continue here.",
            })
        end
        local x, z = columnAt(n)
        local okCell, err = pcall(function()
            if isAir then
                -- Air: in dieser Spalte den Box-Bereich von ArenaFill-Teilen befreien.
                local lo3 = Vector3.new(x - gridStep / 2, bottomY, z - gridStep / 2)
                local hi3 = Vector3.new(x + gridStep / 2, topY + 0.1, z + gridStep / 2)
                local boxParts = Workspace:GetPartBoundsInBox((lo3 + hi3) / 2, (hi3 - lo3), overlapParamsNew({}))
                local foreign = false
                for _, part in ipairs(boxParts) do
                    local cfP, sizeP = boundsOf(part)
                    if cfP and sizeP then
                        local okTag, hasTag = pcall(function() return CollectionService:HasTag(part, "ArenaFill") end)
                        local partTop = cfP.Position.Y + sizeP.Y / 2
                        local partBottom = cfP.Position.Y - sizeP.Y / 2
                        if okTag and hasTag and partTop <= topY + 0.05 and partBottom >= bottomY - 0.05 then
                            pcall(function() part:Destroy() end)
                            cleared = cleared + 1
                        else
                            foreign = true
                        end
                    end
                end
                if foreign and #skippedNeedClear < 30 then
                    table.insert(skippedNeedClear, {
                        column = { x = x, z = z },
                        note = "Contains non-ArenaFill parts (or parts extending below the box) - NOT cleared. Your parts are never touched.",
                    })
                end
                return
            end

            local hit = Workspace:Raycast(Vector3.new(x, rayTopY, z), Vector3.new(0, -800, 0), params)
            if hit == nil then
                skippedNoSurface = skippedNoSurface + 1
                return
            end
            local y1 = hit.Position.Y
            local waterTop = isWaterLike(hit.Instance)
            -- FIX 7.0.8: tplName gehoert in DIESEN Block. Vorher stand die
            -- Deklaration im if-Zweig darunter, der else-Zweig las deshalb ein
            -- nil-Global - der Vorlagen-Name aus with.name ging verloren.
            local tplName = (type(with) == "table" and with.name) or nil

            local target
            if type(fillTo) == "number" then
                target = fillTo
            elseif tostring(fillTo) == "top" then
                target = topY
            else
                if waterTop then
                    target = y1 - 2
                else
                    local rounded = math.floor(y1 / gridStep + 0.5) * gridStep
                    if math.abs(y1 - rounded) < 0.01 then
                        target = y1
                    else
                        target = math.ceil(y1 / gridStep) * gridStep + 2
                    end
                end
            end

            if target <= y1 + 0.05 then
                alreadyDone = alreadyDone + 1
                return
            end

            if target > y1 + 0.05 then
                local bottom = math.max(y1, bottomY)
                if target > bottom + 0.05 then
                    local part = Instance.new("Part")
                    part.Name = tplName or "Fill"
                    part.Size = Vector3.new(gridStep, target - bottom, gridStep)
                    part.Position = Vector3.new(x, bottom + (target - bottom) / 2, z)
                    part.Anchored = true
                    if type(with) == "table" and type(with.properties) == "table" then
                        applyProperties(part, with.properties)
                    end
                    part.Parent = Workspace
                    CollectionService:AddTag(part, "ArenaFill")
                    created = created + 1
                    if #createdParts < 5 then table.insert(createdParts, part) end
                else
                    alreadyDone = alreadyDone + 1
                end
                return
            end

            -- Tiefer als die Oberflaeche: [target, y1] muss frei sein.
            -- Nur ArenaFill-Teile werden gelöscht, und nur wenn sie komplett
            -- im Bereich liegen. Fremde/teilverdeckende Teile bleiben unangetastet.
            local lo4 = Vector3.new(x - gridStep / 2, target, z - gridStep / 2)
            local hi4 = Vector3.new(x + gridStep / 2, y1 + 0.1, z + gridStep / 2)
            local boxParts = Workspace:GetPartBoundsInBox((lo4 + hi4) / 2, (hi4 - lo4), overlapParamsNew({}))
            local foreign = false
            for _, part in ipairs(boxParts) do
                local cfP, sizeP = boundsOf(part)
                if cfP and sizeP then
                    local okTag, hasTag = pcall(function() return CollectionService:HasTag(part, "ArenaFill") end)
                    local partBottom = cfP.Position.Y - sizeP.Y / 2
                    if okTag and hasTag and partBottom >= target - 0.05 then
                        if clearBelowFirst or confirmClear then
                            pcall(function() part:Destroy() end)
                            cleared = cleared + 1
                        else
                            foreign = true
                        end
                    else
                        foreign = true
                    end
                end
            end
            if foreign and #skippedNeedClear < 30 then
                table.insert(skippedNeedClear, {
                    column = { x = x, z = z },
                    note = "Existing parts block the depth (not ArenaFill, or they extend below target) - column NOT changed. Only 'ArenaFill'-tagged parts are ever cleared.",
                })
            else
                -- Bereich ist jetzt frei: von target bis zur Oberflaeche y1 auffuellen.
                if y1 - target > 0.05 then
                    local part = Instance.new("Part")
                    part.Name = tplName or "Fill"
                    part.Size = Vector3.new(gridStep, y1 - target, gridStep)
                    part.Position = Vector3.new(x, target + (y1 - target) / 2, z)
                    part.Anchored = true
                    if type(with) == "table" and type(with.properties) == "table" then
                        applyProperties(part, with.properties)
                    end
                    part.Parent = Workspace
                    CollectionService:AddTag(part, "ArenaFill")
                    created = created + 1
                    if #createdParts < 5 then table.insert(createdParts, part) end
                else
                    alreadyDone = alreadyDone + 1
                end
            end
        end)
        if not okCell then
            table.insert(failedCells, { x = x, z = z, error = tostring(err) })
            if stopOnError then
                return ok({
                    created = created, cleared = cleared, alreadyDone = alreadyDone,
                    skippedNeedClear = #skippedNeedClear, skippedNoSurface = skippedNoSurface,
                    failedCells = failedCells, totalColumns = totalColumns,
                    stoppedAt = n, resumeToken = { index = n - 1 },
                    note = "Stopped on the first cell error - continue with the same resumeToken.",
                })
            end
        end
        if (n - startIndex + 1) % chunkBudget == 0 or n == totalColumns then
            reportProgress(n, (n == totalColumns))
        end
    end

    local elapsed = os.clock() - startedAt
    local rate = (totalColumns - startIndex + 1) / math.max(0.01, elapsed)
    local geometry = { ready = true, frames = 0 }
    if created > 0 then
        geometry = waitMeasurable(createdParts, 2)
    end
    return ok({
        created = created,
        cleared = cleared,
        alreadyDone = alreadyDone,
        skippedNeedClear = skippedNeedClear,
        skippedNoSurface = skippedNoSurface,
        failedCells = failedCells,
        totalColumns = totalColumns,
        partsPerSecond = math.floor(rate * 10) / 10,
        geometry = geometry,
        resumeToken = nil,
        usedProfile = {
            gridStep = gridStep,
            waterY = (worldProfile and worldProfile.waterY) or nil,
            fillRule = "rule",
        },
        note = "All created parts carry the tag 'ArenaFill' - fill_region only ever clears those. Your own parts are never touched.",
    })
end

-- ------------------------- Assets -------------------------------------------
-- ---------------------------------------------------------------------------
-- MEISTER-BAUWERKZEUGE (6.1): Polygon-Triangulation und komplette Baugruppen
-- Die KI liefert nur Absicht + Punkte/Styles. Projektion, Ear-Clipping,
-- Dreieckszerlegung, Wedge-CFrames und Gruppierung rechnet die Bridge.
-- ---------------------------------------------------------------------------
MASTER_BUILD = {}
function MASTER_BUILD.vec3(value)
    local decoded = decodeValue(value)
    if typeof(decoded) == "Vector3" then return decoded end
    if type(value) == "table" then
        return Vector3.new(tonumber(value.x or value.X or value[1]) or 0, tonumber(value.y or value.Y or value[2]) or 0, tonumber(value.z or value.Z or value[3]) or 0)
    end
    return nil
end

function MASTER_BUILD.parseScript(source)
    local polygons, current = {}, nil
    for raw in tostring(source or ""):gmatch("[^\r\n]+") do
        local line = raw:match("^%s*(.-)%s*$")
        if line ~= "" and not line:match("^#") and not line:match("^%-%-") then
            local command, rest = line:match("^(%S+)%s*(.*)$")
            command = string.upper(command or "")
            if command == "POLYGON" then
                current = { points = {} }
                for key, value in rest:gmatch("([%w_]+)=([^%s]+)") do
                    if value == "true" then current[key] = true
                    elseif value == "false" then current[key] = false
                    elseif tonumber(value) ~= nil then current[key] = tonumber(value)
                    else current[key] = value end
                end
                table.insert(polygons, current)
            elseif command == "END" then
                current = nil
            elseif current then
                local x, y, z = line:match("^([%+%-]?[%d%.eE]+)%s*[,;%s]%s*([%+%-]?[%d%.eE]+)%s*[,;%s]%s*([%+%-]?[%d%.eE]+)$")
                if x then table.insert(current.points, { x = tonumber(x), y = tonumber(y), z = tonumber(z) }) end
            end
        end
    end
    return polygons
end

function MASTER_BUILD.normal(points)
    local n = Vector3.zero
    for i = 1, #points do
        local a, b = points[i], points[(i % #points) + 1]
        n = n + Vector3.new((a.Y-b.Y)*(a.Z+b.Z), (a.Z-b.Z)*(a.X+b.X), (a.X-b.X)*(a.Y+b.Y))
    end
    return n.Magnitude > 1e-8 and n.Unit or nil
end

function MASTER_BUILD.project(points, normal)
    local ax, ay, az = math.abs(normal.X), math.abs(normal.Y), math.abs(normal.Z)
    local drop = (ax >= ay and ax >= az) and "x" or ((ay >= az) and "y" or "z")
    local out = {}
    for i, p in ipairs(points) do
        if drop == "x" then out[i] = { x=p.Y, y=p.Z }
        elseif drop == "y" then out[i] = { x=p.X, y=p.Z }
        else out[i] = { x=p.X, y=p.Y } end
    end
    return out, drop
end

function MASTER_BUILD.area2(poly)
    local sum = 0
    for i = 1, #poly do local a,b=poly[i],poly[(i%#poly)+1]; sum=sum+a.x*b.y-b.x*a.y end
    return sum
end

function MASTER_BUILD.pointInTri2(p,a,b,c,orientation,eps)
    local function cross(u,v,w) return (v.x-u.x)*(w.y-u.y)-(v.y-u.y)*(w.x-u.x) end
    local e=eps or 1e-8
    return cross(a,b,p)*orientation >= -e and cross(b,c,p)*orientation >= -e and cross(c,a,p)*orientation >= -e
end

-- Removes consecutive near-duplicate vertices and vertices that sit exactly
-- on the line between their neighbours (zero-area contribution). Both are
-- extremely common in exported organic meshes (trees, rocks, animals) and
-- are the leading real-world cause of "no valid ear found" / self-
-- intersection false positives further down the pipeline.
function MASTER_BUILD.cleanPolygonPoints(points)
    local n=#points
    if n==0 then return points, 1e-5 end
    local minP,maxP=points[1],points[1]
    for _,p in ipairs(points) do
        minP=Vector3.new(math.min(minP.X,p.X),math.min(minP.Y,p.Y),math.min(minP.Z,p.Z))
        maxP=Vector3.new(math.max(maxP.X,p.X),math.max(maxP.Y,p.Y),math.max(maxP.Z,p.Z))
    end
    local diag=(maxP-minP).Magnitude
    local eps=math.max(1e-5,diag*1e-5)
    local deduped={}
    for i=1,n do
        local p=points[i]
        local last=deduped[#deduped]
        if not last or (p-last).Magnitude>eps then table.insert(deduped,p) end
    end
    if #deduped>3 and (deduped[1]-deduped[#deduped]).Magnitude<=eps then table.remove(deduped,#deduped) end
    if #deduped>3 then
        local cleaned={}
        local m=#deduped
        for i=1,m do
            local prev=deduped[((i-2)%m)+1]
            local cur=deduped[i]
            local nxt=deduped[(i%m)+1]
            local v1,v2=cur-prev,nxt-cur
            local keep=true
            if v1.Magnitude>eps and v2.Magnitude>eps then
                local d=v1.Unit:Dot(v2.Unit)
                if d>0.999999 then keep=false end
            end
            if keep then table.insert(cleaned,cur) end
        end
        if #cleaned>=3 then deduped=cleaned end
    end
    return deduped,eps
end

-- Standalone ear-clipping pass with a caller-supplied tolerance. Kept
-- separate from MASTER_BUILD.triangulate so the wrapper can retry it with a
-- looser tolerance / different winding before giving up on a face.
function MASTER_BUILD.earClip(projected,orientation,eps)
    local n=#projected
    local indices={}; for i=1,n do indices[i]=i end
    local triangles,guard={},0
    while #indices>3 do
        guard=guard+1
        if guard>n*n+32 then return nil,"Polygon is self-intersecting or numerically invalid; split it into simple polygons." end
        local clipped=false
        for pos=1,#indices do
            local ia,ib,ic=indices[((pos-2)%#indices)+1],indices[pos],indices[(pos%#indices)+1]
            local a,b,c=projected[ia],projected[ib],projected[ic]
            local cross=(b.x-a.x)*(c.y-b.y)-(b.y-a.y)*(c.x-b.x)
            if cross*orientation>eps then
                local contains=false
                for _,idx in ipairs(indices) do
                    if idx~=ia and idx~=ib and idx~=ic and MASTER_BUILD.pointInTri2(projected[idx],a,b,c,orientation,eps) then contains=true; break end
                end
                if not contains then table.insert(triangles,{ia,ib,ic}); table.remove(indices,pos); clipped=true; break end
            end
        end
        if not clipped then return nil,"No valid ear found. Remove duplicate/collinear points or split a self-intersecting polygon." end
    end
    table.insert(triangles,{indices[1],indices[2],indices[3]})
    return triangles
end

-- Triangulates one polygon face. Returns triangles (index triples into the
-- returned, possibly-cleaned point list), an error string on total failure,
-- the face normal, the dropped projection axis, the cleaned point list, and
-- an optional diagnostic note ("relaxed-tolerance" / "reordered" /
-- "fan-fallback") when a fallback strategy had to be used so a valid face
-- could still be produced instead of silently leaving a hole.
function MASTER_BUILD.triangulate(points)
    if #points < 3 then return nil, "A polygon needs at least 3 points." end
    local cleaned,weldEps = MASTER_BUILD.cleanPolygonPoints(points)
    if #cleaned < 3 then return nil, "Polygon points collapse to fewer than 3 distinct points after cleanup." end
    local normal = MASTER_BUILD.normal(cleaned)
    if not normal then return nil, "Polygon points are collinear or duplicated." end
    local projected, drop = MASTER_BUILD.project(cleaned, normal)
    local minx,maxx,miny,maxy=projected[1].x,projected[1].x,projected[1].y,projected[1].y
    for _,p in ipairs(projected) do
        minx=math.min(minx,p.x); maxx=math.max(maxx,p.x); miny=math.min(miny,p.y); maxy=math.max(maxy,p.y)
    end
    local areaScale=math.max((maxx-minx)*(maxy-miny), weldEps*weldEps, 1e-6)
    local signed = MASTER_BUILD.area2(projected)
    if math.abs(signed) < areaScale*1e-8 then return nil, "Polygon area is zero after projection." end
    local orientation = signed > 0 and 1 or -1

    -- Attempt 1: standard ear-clipping with a tight tolerance.
    local triangles,why = MASTER_BUILD.earClip(projected, orientation, areaScale*1e-9)
    local note=nil
    if not triangles then
        -- Attempt 2: relax the tolerance. Slightly non-planar or rounded
        -- input coordinates can make an otherwise-valid ear look borderline
        -- self-intersecting; a looser epsilon recovers it without changing
        -- the resulting shape in any perceptible way.
        triangles,why = MASTER_BUILD.earClip(projected, orientation, areaScale*1e-4)
        if triangles then note="relaxed-tolerance" end
    end
    if not triangles then
        -- Attempt 3: try the opposite winding/orientation. Some organic
        -- meshes list points in an order that is only marginally consistent;
        -- walking them the other way changes the numeric path of the ear
        -- test and frequently succeeds where the original order failed.
        local reversed={}
        for i=#cleaned,1,-1 do table.insert(reversed,cleaned[i]) end
        local rNormal=MASTER_BUILD.normal(reversed)
        if rNormal then
            local rProjected,rDrop=MASTER_BUILD.project(reversed,rNormal)
            local rSigned=MASTER_BUILD.area2(rProjected)
            if math.abs(rSigned)>=areaScale*1e-8 then
                local rOrientation=rSigned>0 and 1 or -1
                local rTriangles=MASTER_BUILD.earClip(rProjected,rOrientation,areaScale*1e-4)
                if rTriangles then
                    local remapped={}
                    for _,t in ipairs(rTriangles) do
                        table.insert(remapped,{#cleaned-t[1]+1,#cleaned-t[2]+1,#cleaned-t[3]+1})
                    end
                    return remapped,nil,rNormal,rDrop,cleaned,"reordered"
                end
            end
        end
    end
    if not triangles then
        -- Last resort: fan triangulation from the first vertex. This keeps
        -- the face present (no hole in the model) instead of dropping it
        -- outright; the caller is told about the fallback via the returned
        -- note so the build result stays honest about it.
        local fan={}
        for i=2,#cleaned-1 do table.insert(fan,{1,i,i+1}) end
        if #fan>0 then return fan,nil,normal,drop,cleaned,"fan-fallback" end
        return nil, why or "No valid ear found."
    end
    return triangles, nil, normal, drop, cleaned, note
end

function MASTER_BUILD.color(value, fallback)
    local decoded=decodeValue(value)
    if typeof(decoded)=="Color3" then return decoded end
    return fallback or Color3.fromRGB(163,162,165)
end

function MASTER_BUILD.copyTable(source)
    local out={}
    for k,v in pairs(source or {}) do out[k]=v end
    return out
end

function MASTER_BUILD.mergeStyle(base, override)
    local out=MASTER_BUILD.copyTable(base)
    for k,v in pairs(override or {}) do out[k]=v end
    return out
end

-- A loft is a REAL three-dimensional organic volume, not one side-view face.
-- Each station contributes an elliptical ring; adjacent rings are joined by
-- quads and both ends are capped. The existing polygon engine then triangulates
-- this closed skin into WedgeParts. Cross-section radii are deliberately
-- explicit so the bridge can prove that a creature body/head has depth.
function MASTER_BUILD.loftVolume(volume)
    if type(volume)~="table" then return nil,nil,"volume entry must be a table" end
    local sections=volume.sections or volume.stations or {}
    if type(sections)~="table" or #sections<3 then return nil,nil,"at least 3 sections are required" end
    local sides=math.floor(tonumber(volume.sides) or 8)
    if sides<6 or sides>16 then return nil,nil,"sides must be between 6 and 16" end
    local centers,radiusUp,radiusSide={},{},{}
    for i,section in ipairs(sections) do
        if type(section)~="table" then return nil,nil,"section "..tostring(i).." must be a table" end
        local center=MASTER_BUILD.vec3(section.center or section.position)
        local rUp=tonumber(section.heightRadius or section.upRadius or section.radiusY)
        local rSide=tonumber(section.depthRadius or section.sideRadius or section.radiusZ)
        if not center then return nil,nil,"section "..tostring(i).." needs center={x,y,z}" end
        if not rUp or not rSide or rUp<0.025 or rSide<0.025 then
            return nil,nil,"section "..tostring(i).." needs heightRadius and depthRadius >= 0.025"
        end
        centers[i]=center; radiusUp[i]=rUp; radiusSide[i]=rSide
        if i>1 and (center-centers[i-1]).Magnitude<0.01 then
            return nil,nil,"adjacent section centers must be at least 0.01 studs apart"
        end
    end
    local rings,previousSide={},nil
    local minCrossSectionRatio=1
    local axisLength=0
    for i,center in ipairs(centers) do
        if i>1 then axisLength=axisLength+(center-centers[i-1]).Magnitude end
        local before=centers[math.max(1,i-1)]
        local after=centers[math.min(#centers,i+1)]
        local delta=after-before
        if delta.Magnitude<0.01 then return nil,nil,"section path has no measurable direction" end
        local tangent=delta.Unit
        local upReference=Vector3.new(0,1,0)
        local up=upReference-tangent*upReference:Dot(tangent)
        if up.Magnitude<0.001 then
            upReference=Vector3.new(0,0,1)
            up=upReference-tangent*upReference:Dot(tangent)
        end
        if up.Magnitude<0.001 then return nil,nil,"could not construct a stable cross-section frame" end
        up=up.Unit
        local side=tangent:Cross(up).Unit
        -- Keep the ring frame from flipping when the centerline bends.
        if previousSide and side:Dot(previousSide)<0 then side=-side; up=-up end
        previousSide=side
        local ring={}
        for j=1,sides do
            local angle=(2*math.pi*(j-1))/sides
            ring[j]=center+up*(radiusUp[i]*math.cos(angle))+side*(radiusSide[i]*math.sin(angle))
        end
        rings[i]=ring
        local larger=math.max(radiusUp[i],radiusSide[i])
        minCrossSectionRatio=math.min(minCrossSectionRatio,math.min(radiusUp[i],radiusSide[i])/larger)
    end
    local polygons={}
    table.insert(polygons,{name=tostring(volume.name or "Loft").."_CapA",points=rings[1]})
    local lastCap={}
    for j=sides,1,-1 do table.insert(lastCap,rings[#rings][j]) end
    table.insert(polygons,{name=tostring(volume.name or "Loft").."_CapB",points=lastCap})
    for i=1,#rings-1 do
        for j=1,sides do
            local nextJ=(j%sides)+1
            table.insert(polygons,{name=tostring(volume.name or "Loft").."_R"..tostring(i).."_S"..tostring(j),points={
                rings[i][j],rings[i][nextJ],rings[i+1][nextJ],rings[i+1][j]
            }})
        end
    end
    return polygons,{sections=#sections,sides=sides,faces=#polygons,axisLength=axisLength,minCrossSectionRatio=minCrossSectionRatio,closedEnds=true}
end

function MASTER_BUILD.pointKey(v)
    -- Shared mesh vertices often arrive as separate JSON objects. Quantising
    -- makes boundary detection stable without moving the actual geometry.
    -- Rounding also normalises "negative zero" (e.g. sin(2*pi) evaluates to
    -- a tiny negative float instead of exactly 0): without this, a value
    -- that rounds to "-0.00000" produced a DIFFERENT string than the exact
    -- "0.00000" it geometrically equals, so a circular cross-section (round
    -- trunks, tree crowns, animal bodies built from sin/cos) could fail to
    -- weld its own start/end seam and leave a visible gap there.
    local function q(n)
        local r = math.floor(n*100000 + 0.5) / 100000
        if r == 0 then r = 0 end
        return r
    end
    return string.format("%.5f,%.5f,%.5f", q(v.X), q(v.Y), q(v.Z))
end

-- Snaps vertices that are within quantisation distance of each other to the
-- exact same Vector3 instance across every polygon of a submodel. Adjacent
-- faces are usually authored with matching-but-not-bit-identical coordinates
-- (separate JSON points, float rounding); welding them here is what lets the
-- independently-built WedgeParts of neighbouring triangles meet edge-to-edge
-- instead of leaving hairline gaps, and it also makes closeBoundaryLoops'
-- edge matching far more reliable.
function MASTER_BUILD.weldEntryVertices(entries)
    local canon={}
    for _,entry in ipairs(entries) do
        for i,p in ipairs(entry.points) do
            local k=MASTER_BUILD.pointKey(p)
            local existing=canon[k]
            if existing then entry.points[i]=existing else canon[k]=p end
        end
    end
end

function MASTER_BUILD.closeBoundaryLoops(entries)
    local edges={}
    for _,entry in ipairs(entries) do
        local pts=entry.points
        for i=1,#pts do
            local a,b=pts[i],pts[(i%#pts)+1]
            local ka,kb=MASTER_BUILD.pointKey(a),MASTER_BUILD.pointKey(b)
            local key=(ka<kb) and (ka.."|"..kb) or (kb.."|"..ka)
            local hit=edges[key]
            if hit then hit.count=hit.count+1 else edges[key]={count=1,a=a,b=b,ka=ka,kb=kb,style=entry.style} end
        end
    end
    local outgoing={}
    for _,edge in pairs(edges) do
        if edge.count==1 then
            outgoing[edge.ka]=outgoing[edge.ka] or {}
            table.insert(outgoing[edge.ka],edge)
        end
    end
    local caps,used={},{}
    for _,first in pairs(edges) do
        if first.count==1 and not used[first] then
            local loop={first.a}; local edge=first; local startKey=first.ka; local guard=0
            while edge and not used[edge] and guard<10000 do
                guard=guard+1; used[edge]=true; table.insert(loop,edge.b)
                if edge.kb==startKey then break end
                local nextEdge=nil
                for _,candidate in ipairs(outgoing[edge.kb] or {}) do if not used[candidate] then nextEdge=candidate; break end end
                -- Adjacent faces can expose the reverse direction. Follow it
                -- as well; cap triangulation determines its own orientation.
                if not nextEdge then
                    for _,candidate in pairs(edges) do
                        if candidate.count==1 and not used[candidate] and candidate.kb==edge.kb then
                            candidate.a,candidate.b=candidate.b,candidate.a; candidate.ka,candidate.kb=candidate.kb,candidate.ka
                            nextEdge=candidate; break
                        end
                    end
                end
                edge=nextEdge
            end
            if #loop>=4 and (loop[1]-loop[#loop]).Magnitude<1e-4 then
                table.remove(loop,#loop)
                table.insert(caps,{points=loop,name="AutoCap"..tostring(#caps+1),style=MASTER_BUILD.copyTable(first.style),autoCap=true})
            end
        end
    end
    return caps
end

function MASTER_BUILD.triangleWedges(a,b,c,parent,style,name,faceNormal,solidCenter)
    local ab,ac,bc=b-a,c-a,c-b
    local abd,acd,bcd=ab:Dot(ab),ac:Dot(ac),bc:Dot(bc)
    -- Re-label the vertices so BC is always the triangle's longest edge and A
    -- is the opposite vertex: the perpendicular foot dropped from A then
    -- always lands inside segment BC, whatever order the caller supplied the
    -- points in. The previous version only reassigned two of the three local
    -- variables on these swaps ("c,a=b,c" / "a,b=b,c"), which silently made
    -- B and C alias the very same point (a fake zero-length edge) whenever
    -- the longest edge happened to be AB or AC. That bug rejected perfectly
    -- valid triangles as "degenerate" purely based on point order.
    if abd > acd and abd > bcd then
        a,b,c = c,a,b
    elseif acd > bcd then
        a,b,c = b,a,c
    end
    ab,ac,bc=b-a,c-a,c-b
    local longestSq = math.max(ab:Dot(ab), ac:Dot(ac), bc:Dot(bc), 1e-12)
    -- Tolerances now scale with the triangle's own size instead of one fixed
    -- absolute number, so a hair-thin sliver on a huge terrain piece and a
    -- genuinely collapsed micro-triangle on a tiny prop are both judged
    -- correctly instead of a single epsilon being wrong for either scale.
    local areaTolerance = math.max(1e-7, longestSq*1e-6)
    local lengthTolerance = math.max(1e-6, math.sqrt(longestSq)*1e-5)
    local right=ac:Cross(ab)
    if right.Magnitude < areaTolerance or bc.Magnitude < lengthTolerance then return {}, "degenerate triangle" end
    right=right.Unit
    local back=bc.Unit
    local up=bc:Cross(right).Unit
    local height=math.abs(ab:Dot(up))
    local z1=math.abs(ab:Dot(back)); local z2=math.abs(ac:Dot(back))
    local thickness=math.max(0.01,tonumber(style.thickness) or 0.03)

    -- A WedgePart has thickness on BOTH sides of its CFrame X plane. On a
    -- bent shell that old centre-line placement produces the familiar dark
    -- grooves: the visible skins no longer meet as the angle grows. The input
    -- polygon is now treated as the requested skin. By default the complete
    -- wedge thickness is moved towards the submodel centre, so the outside
    -- remains exactly on the supplied points and the inside overlaps cleanly.
    -- `thicknessPlacement="center"` keeps legacy behaviour; positive/negative
    -- use point winding when an open sheet has no meaningful solid centre.
    local normal=(faceNormal and faceNormal.Magnitude>1e-8) and faceNormal.Unit or right
    local placement=string.lower(tostring(style.thicknessPlacement or style.surfaceSide or "inside"))
    local shift=Vector3.zero
    if placement~="center" then
        local inward=-normal
        if placement=="positive" or placement=="outsidepositive" then inward=normal
        elseif placement=="negative" or placement=="outsidenegative" then inward=-normal
        elseif solidCenter then
            local centroid=(a+b+c)/3
            if normal:Dot(solidCenter-centroid)<0 then inward=-normal else inward=normal end
        end
        shift=inward*(thickness/2)
    end

    local made={}
    local geometryOwned={cframe=true,position=true,orientation=true,rotation=true,size=true,pivotoffset=true}
    local function one(index,size,cf)
        local w=Instance.new("WedgePart")
        w.Name=name.."_W"..tostring(index)
        w.Anchored=style.anchored ~= false
        w.CanCollide=style.canCollide == true
        w.CanQuery=style.canQuery ~= false
        w.CanTouch=style.canTouch == true
        w.CastShadow=style.castShadow ~= false
        w.Transparency=math.clamp(tonumber(style.transparency) or 0,0,1)
        w.Color=MASTER_BUILD.color(style.color,Color3.fromRGB(163,162,165))
        if style.material then pcall(function() w.Material=Enum.Material[tostring(style.material)] end) end
        if style.materialVariant then pcall(function() w.MaterialVariant=tostring(style.materialVariant) end) end
        if style.collisionGroup then pcall(function() w.CollisionGroup=tostring(style.collisionGroup) end) end
        if style.reflectance then w.Reflectance=math.clamp(tonumber(style.reflectance) or 0,0,1) end
        if type(style.properties)=="table" then
            local safeProperties={}
            for key,value in pairs(style.properties) do
                if not geometryOwned[string.lower(tostring(key))] then safeProperties[key]=value end
            end
            applyProperties(w,safeProperties)
        end
        -- Size and CFrame are geometry invariants. Set them LAST so generic
        -- style properties can never move, resize or rotate a triangle away
        -- from the supplied vertices.
        w.Size=Vector3.new(thickness,math.max(0.01,size.Y),math.max(0.01,size.Z))
        w.CFrame=cf+shift
        w:SetAttribute("ArenaPolygonTriangle",name)
        w:SetAttribute("ThicknessPlacement",placement)
        w.Parent=parent; table.insert(made,w)
    end
    one(1,Vector3.new(thickness,height,z1),CFrame.fromMatrix((a+b)/2,right,up,back))
    one(2,Vector3.new(thickness,height,z2),CFrame.fromMatrix((a+c)/2,-right,up,-back))
    return made
end

function MASTER_BUILD.weldContainer(container,weldName)
    local parts={}
    for _,d in ipairs(container:GetDescendants()) do if d:IsA("BasePart") then table.insert(parts,d) end end
    local root=parts[1]
    if not root then return nil,0 end
    for i=2,#parts do
        local weld=Instance.new("WeldConstraint"); weld.Name=(weldName or "ArenaAutoWeld")..tostring(i-1)
        weld.Part0=root; weld.Part1=parts[i]; weld.Parent=root
    end
    return root,math.max(0,#parts-1)
end

function MASTER_BUILD.findSubmodel(root,name)
    for _,child in ipairs(root:GetChildren()) do if child.Name==name and (child:IsA("Model") or child:IsA("Folder")) then return child end end
    return nil
end

tools.build_polygon_model = function(args)
    local parent,err=resolveRef(args.parentRef or "game.Workspace")
    if not parent then return failCode("REF_NOT_FOUND",err) end
    local rawPolygons=args.polygons or {}
    local subSpecs=args.submodels or args.groups or {}
    local rawVolumes=args.volumes or {}
    if type(rawPolygons)~="table" or type(subSpecs)~="table" or type(rawVolumes)~="table" then
        return failCode("BAD_ARGS","polygons, submodels and volumes must be arrays/tables.")
    end
    for _,spec in ipairs(subSpecs) do
        if type(spec)~="table" then return failCode("BAD_ARGS","Every submodel entry must be a table.") end
    end
    for _,volume in ipairs(rawVolumes) do
        if type(volume)~="table" then return failCode("BAD_ARGS","Every loft volume entry must be a table.") end
    end
    local polygonScript=args.script or args.source
    if polygonScript then for _,p in ipairs(MASTER_BUILD.parseScript(polygonScript)) do table.insert(rawPolygons,p) end end
    if args.points then table.insert(rawPolygons,{points=args.points,name=args.polygonName}) end
    local organicBuild=args.organic==true
    local organicKind=string.lower(tostring(args.organicKind or ""))
    local allowedOrganicKinds={creature=true,plant=true,tree=true,prop=true,custom=true}
    if organicBuild and organicKind=="" then
        return failCode("ORGANIC_KIND_REQUIRED","organic=true now requires organicKind=creature|plant|tree|prop|custom so the correct measured geometry contract is applied.")
    end
    if organicBuild and not allowedOrganicKinds[organicKind] then
        return failCode("ORGANIC_KIND_INVALID","organicKind must be creature, plant, tree, prop or custom.")
    end
    if organicKind=="creature" and not organicBuild then
        return failCode("ORGANIC_KIND_REQUIRED","organicKind=creature also requires organic=true so the creature is registered for its strict audit.")
    end
    local function hasTrait(traits,wanted)
        if type(traits)=="string" then return string.find(string.lower(traits),wanted,1,true)~=nil end
        for _,trait in ipairs(type(traits)=="table" and traits or {}) do
            if string.lower(tostring(trait))==wanted then return true end
        end
        return false
    end
    local hasWings=hasTrait(args.organicTraits,"wings")
    for _,volume in ipairs(rawVolumes) do
        local role=string.lower(tostring(volume.role or ""))
        if role=="wing_left" or role=="wing_right" then hasWings=true end
    end
    for _,spec in ipairs(subSpecs) do
        local role=string.lower(tostring(spec.role or ""))
        if role=="wing_left" or role=="wing_right" then hasWings=true end
    end
    if #rawPolygons==0 and #subSpecs==0 and #rawVolumes==0 then
        return failCode("BAD_ARGS","Provide polygons/points/script, submodels, or loft volumes.")
    end
    if organicKind=="creature" then
        local roleSpecs,volumeRoles={},{}
        for _,volume in ipairs(rawVolumes) do
            local role=string.lower(tostring(volume.role or ""))
            if role~="" then roleSpecs[role]=volume; volumeRoles[role]=volume end
        end
        for _,spec in ipairs(subSpecs) do
            local role=string.lower(tostring(spec.role or ""))
            if role~="" and not roleSpecs[role] then roleSpecs[role]=spec end
        end
        local body,head=volumeRoles.body,volumeRoles.head
        local bodySections=body and (body.sections or body.stations) or {}
        local headSections=head and (head.sections or head.stations) or {}
        if type(bodySections)~="table" then bodySections={} end
        if type(headSections)~="table" then headSections={} end
        if not body or not head or #bodySections<4 or #headSections<3
            or (tonumber(body.sides) or 8)<8 or (tonumber(head.sides) or 8)<8 then
            return failCode("CREATURE_VOLUME_REQUIRED","A creature's first build needs closed loft volumes with role=body (at least 4 cross-section sections) and role=head (at least 3), each with sides >= 8. A side-profile polygon is not a creature body.")
        end
        if hasWings and (not roleSpecs.wing_left or not roleSpecs.wing_right) then
            return failCode("CREATURE_WINGS_REQUIRED","organicTraits=[\"wings\"] requires separate role=wing_left (+Z flank) and role=wing_right (-Z flank) geometry attached to the body.")
        end
    end
    local generatedVolumeSpecs,volumeSummary={},{}
    for i,volume in ipairs(rawVolumes) do
        if volume.style~=nil and type(volume.style)~="table" then
            return failCode("BAD_ARGS","Loft volume style must be a table.")
        end
        local polygons,meta,volumeError=MASTER_BUILD.loftVolume(volume)
        if not polygons then
            return failCode("BAD_ARGS","Invalid loft volume "..tostring(volume.name or i)..": "..tostring(volumeError))
        end
        local role=string.lower(tostring(volume.role or ""))
        local name=tostring(volume.name or (role~="" and role or ("LoftVolume"..i)))
        local volumeSpec={name=name,role=role,polygons=polygons,style=volume.style or {},containerClass="Folder",isLoftVolume=true,loftMeta=meta,autoWeld=volume.autoWeld}
        table.insert(generatedVolumeSpecs,volumeSpec)
        table.insert(volumeSummary,{name=name,role=role,sections=meta.sections,sides=meta.sides,expectedFaces=meta.faces,axisLength=meta.axisLength,minCrossSectionRatio=meta.minCrossSectionRatio,closedEnds=meta.closedEnds})
    end

    local model=Instance.new("Model"); model.Name=tostring(args.modelName or args.name or "ArenaPolygonModel"); model.Parent=parent
    model:SetAttribute("ArenaMasterBuild",true)
    -- Version 7.2.0: Wenn der Aufrufer die Einfachheit AUSDRUECKLICH erklaert
    -- (grade = simple/lowpoly/blockout), wird sie als Attribut gespeichert.
    -- model_audit liest sie und nennt das Ergebnis dann nicht mehr Entwurf.
    if args.grade == "simple" or args.grade == "lowpoly" or args.grade == "blockout" or args.grade == "detailed" then
        model:SetAttribute("ArenaDeclaredGrade", tostring(args.grade))
    end
    if organicBuild then
        model:SetAttribute("ArenaOrganicBuild",true)
        model:SetAttribute("ArenaOrganicBuildVersion",3)
        model:SetAttribute("ArenaOrganicKind",organicKind)
        model:SetAttribute("ArenaOrganicHasWings",hasWings)
    end
    local defaults=args.style or {}
    local origin=MASTER_BUILD.vec3(args.origin) or Vector3.zero
    local scale=tonumber(args.scale) or 1
    local rotation=MASTER_BUILD.vec3(args.rotation) or Vector3.zero
    local transform=CFrame.new(origin)*CFrame.Angles(math.rad(rotation.X),math.rad(rotation.Y),math.rad(rotation.Z))
    if organicBuild then
        model:SetAttribute("ArenaOrganicForward",transform.RightVector)
        model:SetAttribute("ArenaOrganicUp",transform.UpVector)
        model:SetAttribute("ArenaOrganicSide",transform:VectorToWorldSpace(Vector3.new(0,0,1)))
    end
    local specs={}
    if #rawPolygons>0 then table.insert(specs,{name=args.defaultSubmodelName or "Surfaces",polygons=rawPolygons,style=defaults,containerClass=args.containerClass}) end
    for _,spec in ipairs(generatedVolumeSpecs) do table.insert(specs,spec) end
    for _,spec in ipairs(subSpecs) do table.insert(specs,spec) end

    local wedgeCount,triCount,weldCount,capCount,skipped=0,0,0,0,{}
    local facesTotal,facesSkipped,fallbackFaces=0,0,{}
    local ignoredGeometryProperties={}
    local ignoredGeometrySeen={}
    local geometryOwned={cframe=true,position=true,orientation=true,rotation=true,size=true,pivotoffset=true}
    local maxWedges=math.min(10000,math.max(2,tonumber(args.maxWedges) or 4000))
    local roots={}
    local weldedSubmodels=0
    for si,spec in ipairs(specs) do
        local className=(string.lower(tostring(spec.containerClass or spec.className or "folder"))=="model") and "Model" or "Folder"
        local container=Instance.new(className); container.Name=tostring(spec.name or ("Submodel"..si)); container.Parent=model
        container:SetAttribute("ArenaPolygonSubmodel",true)
        if type(spec.role)=="string" and spec.role~="" then container:SetAttribute("ArenaOrganicRole",string.lower(spec.role)) end
        if spec.isLoftVolume==true then
            container:SetAttribute("ArenaLoftVolume",true)
            container:SetAttribute("ArenaLoftSectionCount",tonumber((spec.loftMeta or {}).sections) or 0)
            container:SetAttribute("ArenaLoftSideCount",tonumber((spec.loftMeta or {}).sides) or 0)
            container:SetAttribute("ArenaLoftExpectedFaceCount",tonumber((spec.loftMeta or {}).faces) or 0)
            container:SetAttribute("ArenaLoftClosedEnds",(spec.loftMeta or {}).closedEnds==true)
        end
        local subStyle=MASTER_BUILD.mergeStyle(defaults,spec.style)
        local entries={}; local centerSum=Vector3.zero; local centerCount=0
        for pi,poly in ipairs(spec.polygons or {}) do
            local style=MASTER_BUILD.mergeStyle(subStyle,poly.style)
            for _,k in ipairs({"color","material","materialVariant","collisionGroup","thickness","thicknessPlacement","surfaceSide","anchored","canCollide","canQuery","canTouch","castShadow","transparency","reflectance","properties"}) do if poly[k]~=nil then style[k]=poly[k] end end
            if type(style.properties)=="table" then
                for key,_ in pairs(style.properties) do
                    local lower=string.lower(tostring(key))
                    if geometryOwned[lower] and not ignoredGeometrySeen[lower] then
                        ignoredGeometrySeen[lower]=true
                        table.insert(ignoredGeometryProperties,tostring(key))
                    end
                end
            end
            local pts={}
            for _,raw in ipairs(poly.points or {}) do local v=MASTER_BUILD.vec3(raw); if v then local tv=transform*(v*scale); table.insert(pts,tv); centerSum=centerSum+tv; centerCount=centerCount+1 end end
            if #pts>3 and (pts[1]-pts[#pts]).Magnitude<1e-6 then table.remove(pts,#pts) end
            table.insert(entries,{points=pts,name=poly.name or ("Polygon"..pi),style=style,index=pi})
        end
        -- Weld matching vertices across this submodel's polygons before
        -- anything else touches them: closeOpenings' loop-matching and every
        -- triangle's WedgePart placement then work off exactly the same
        -- Vector3 for a shared edge instead of near-identical-but-different
        -- floats, which is what makes neighbouring faces meet without gaps.
        MASTER_BUILD.weldEntryVertices(entries)
        if (spec.closeOpenings==true or args.closeOpenings==true) then
            local caps=MASTER_BUILD.closeBoundaryLoops(entries)
            for _,cap in ipairs(caps) do cap.style=MASTER_BUILD.mergeStyle(subStyle,spec.capStyle or args.capStyle); table.insert(entries,cap); capCount=capCount+1 end
        end
        local solidCenter=centerCount>0 and centerSum/centerCount or nil
        local subTriangles,subFaceCount,subFacesSkipped=0,0,0
        for _,entry in ipairs(entries) do
            facesTotal=facesTotal+1
            subFaceCount=subFaceCount+1
            local triangles,why,normal,drop,cleanedPoints,note=MASTER_BUILD.triangulate(entry.points)
            if not triangles or #triangles==0 then
                facesSkipped=facesSkipped+1
                subFacesSkipped=subFacesSkipped+1
                table.insert(skipped,{submodel=container.Name,polygon=entry.name,name=entry.name,index=entry.index,autoCap=entry.autoCap==true,error=why or "triangulation produced no triangles"})
            elseif wedgeCount+#triangles*2>maxWedges then model:Destroy(); return failCode("BUDGET_EXCEEDED","Polygon build needs more than "..tostring(maxWedges).." wedges. Raise maxWedges up to 10000 or split the model.")
            else
                local group=Instance.new("Model"); group.Name=tostring(entry.name); group.Parent=container
                group:SetAttribute("TriangleCount",#triangles); group:SetAttribute("ProjectionAxis",drop); group:SetAttribute("Normal",normal); group:SetAttribute("AutoCap",entry.autoCap==true)
                if note then
                    group:SetAttribute("TriangulationFallback",note)
                    table.insert(fallbackFaces,{submodel=container.Name,polygon=entry.name,index=entry.index,note=note})
                end
                local usePoints=cleanedPoints or entry.points
                for ti,t in ipairs(triangles) do
                    local made,werr=MASTER_BUILD.triangleWedges(usePoints[t[1]],usePoints[t[2]],usePoints[t[3]],group,entry.style,group.Name.."_T"..ti,normal,solidCenter)
                    if werr then
                        subFacesSkipped=math.max(subFacesSkipped,1)
                        table.insert(skipped,{submodel=container.Name,polygon=entry.name,index=entry.index,triangle=ti,error=werr})
                    else
                        wedgeCount=wedgeCount+#made; triCount=triCount+1; subTriangles=subTriangles+1
                    end
                end
            end
        end
        container:SetAttribute("TriangleCount",subTriangles)
        container:SetAttribute("ArenaLoftFaceCount",subFaceCount)
        container:SetAttribute("ArenaLoftFacesSkipped",subFacesSkipped)
        -- Polygon surfaces are one object by default. Without WeldConstraints,
        -- unanchored Wedges become independent physics bodies and immediately
        -- scatter/rotate in play mode. Only explicit false opts out.
        local shouldWeld=args.autoWeld~=false
        if spec.autoWeld~=nil then shouldWeld=spec.autoWeld~=false end
        if shouldWeld then
            local root,count=MASTER_BUILD.weldContainer(container,"ArenaSurfaceWeld")
            roots[container.Name]=root; weldCount=weldCount+count
            if root then weldedSubmodels=weldedSubmodels+1 end
        else
            for _,d in ipairs(container:GetDescendants()) do if d:IsA("BasePart") then roots[container.Name]=d; break end end
        end
    end

    -- Animatable joins deliberately use classic Welds (C0/C1), not rigid
    -- WeldConstraints. Scripts can sway a crown around the trunk by animating
    -- the named main weld without dismantling either welded submodel.
    local mainWelds=args.mainWelds or {}
    if args.mainWeld==true and #specs>1 then
        for i=2,#specs do table.insert(mainWelds,{name="MainWeld_"..tostring(i-1),from=specs[1].name or "Surfaces",to=specs[i].name or ("Submodel"..i)}) end
    end
    local mainWeldCount=0
    for wi,join in ipairs(mainWelds) do
        local p0=roots[tostring(join.from or join.part0 or "")]; local p1=roots[tostring(join.to or join.part1 or "")]
        if p0 and p1 then
            local weld=Instance.new("Weld"); weld.Name=tostring(join.name or ("MainWeld"..wi)); weld.Part0=p0; weld.Part1=p1
            weld.C0=p0.CFrame:ToObjectSpace(p1.CFrame); weld.C1=CFrame.new(); weld.Parent=model; mainWeldCount=mainWeldCount+1
        else table.insert(skipped,{mainWeld=wi,error="Could not resolve from/to submodel roots."}) end
    end
    if wedgeCount==0 then
        model:Destroy()
        return failCode("POLYGON_INVALID","No polygon could be triangulated. "..tostring(#skipped).." face(s) failed; see result.skipped for polygon/submodel/reason per failure.",{skipped=skipped,facesTotal=facesTotal,facesSkipped=facesSkipped})
    end
    model:SetAttribute("PolygonCount",#rawPolygons); model:SetAttribute("SubmodelCount",#specs)
    model:SetAttribute("FacesBuilt",facesTotal-facesSkipped); model:SetAttribute("FacesSkipped",facesSkipped)
    waypoint("build polygon model "..model.Name)
    local sample={}; for _,d in ipairs(model:GetDescendants()) do if d:IsA("BasePart") and #sample<8 then table.insert(sample,d) end end
    -- A build that skipped faces (or had to fall back to a less-strict
    -- triangulation) is never reported as a silent full success: `incomplete`
    -- and the human-readable `warnings` text make partial results impossible
    -- to miss, while `skipped`/`fallbackFaces` keep the exact polygon name,
    -- submodel name and error reason for each affected face.
    local incomplete=#skipped>0
    local warningsText=nil
    if incomplete then
        warningsText=tostring(#skipped).." of "..tostring(facesTotal).." face(s) were skipped and are MISSING from the model - see result.skipped for {submodel, polygon, error} per failure. Consider fixing the source points (duplicate/self-intersecting) or re-running with different point order."
    elseif #fallbackFaces>0 then
        warningsText=tostring(#fallbackFaces).." face(s) needed a fallback triangulation strategy (still built, see result.fallbackFaces)."
    end
    if #ignoredGeometryProperties>0 then
        local note="Ignored geometry-owned style.properties ("..table.concat(ignoredGeometryProperties,", ")..") so polygon Size/CFrame cannot be overwritten."
        warningsText=warningsText and (warningsText.." "..note) or note
    end
    return ok({model=describeRef(model),organic=organicBuild,organicKind=organicKind,submodels=#specs,polygons=#rawPolygons,volumesBuilt=#generatedVolumeSpecs,volumeSummary=volumeSummary,triangles=triCount,wedges=wedgeCount,autoCaps=capCount,welds=weldCount,weldedSubmodels=weldedSubmodels,autoWeldDefault=true,mainWelds=mainWeldCount,facesTotal=facesTotal,facesBuilt=facesTotal-facesSkipped,facesSkipped=facesSkipped,incomplete=incomplete,skipped=skipped,fallbackFaces=fallbackFaces,ignoredGeometryProperties=ignoredGeometryProperties,geometryInvariant="Size/CFrame applied after safe style properties",geometry=waitMeasurable(sample,2),method="side-corrected skin placement + ear-clipping + two WedgeParts per triangle (closed loft volumes included; auto-welded by default)",editable=true},warningsText)
end

tools.build_assembly = function(args)
    local parent,err=resolveRef(args.parentRef or "game.Workspace"); if not parent then return failCode("REF_NOT_FOUND",err) end
    local model=Instance.new("Model"); model.Name=tostring(args.modelName or args.name or "ArenaAssembly"); model.Parent=parent; model:SetAttribute("ArenaMasterBuild",true)
    if args.grade == "simple" or args.grade == "lowpoly" or args.grade == "blockout" or args.grade == "detailed" then model:SetAttribute("ArenaDeclaredGrade", tostring(args.grade)) end
    local items=args.items or args.parts or {}; local expanded={}
    for _,spec in ipairs(items) do
        local repeatSpec=spec.repeatSpec or spec["repeat"] or {}; local count=math.max(1,math.floor(tonumber(repeatSpec.count) or 1))
        if #expanded+count>2000 then model:Destroy(); return failCode("BUDGET_EXCEEDED","build_assembly creates at most 2000 parts per call.") end
        local basePos=MASTER_BUILD.vec3((spec.properties or {}).Position or spec.position) or Vector3.zero
        local offset=MASTER_BUILD.vec3(repeatSpec.offset) or Vector3.zero
        local radius=tonumber(repeatSpec.radius); local angleStep=tonumber(repeatSpec.angleStep) or (radius and 360/count or 0)
        for i=1,count do
            local copy={}; for k,v in pairs(spec) do copy[k]=v end
            local props={}; for k,v in pairs(spec.properties or {}) do props[k]=v end
            local pos=basePos+offset*(i-1)
            if radius then local a=math.rad((tonumber(repeatSpec.startAngle) or 0)+angleStep*(i-1)); pos=basePos+Vector3.new(math.cos(a)*radius,tonumber(repeatSpec.heightStep or 0)*(i-1),math.sin(a)*radius); props.Orientation=Vector3.new(0,-math.deg(a)+90,0) end
            props.Position=pos; copy.properties=props; copy.name=tostring(spec.name or spec.className or "Part"):gsub("{n}",tostring(i)); copy.parentRef=nil
            table.insert(expanded,copy)
        end
    end
    local created,errors,sample={},{},{}
    for i,spec in ipairs(expanded) do
        local className=tostring(spec.className or "Part")
        local okNew,inst=pcall(Instance.new,className)
        if not okNew or not inst then table.insert(errors,{index=i,error="Cannot create "..className})
        else
            inst.Name=spec.name or className
            local problems=applyProperties(inst,spec.properties)
            local attributeProblems={}
            for attributeName,attributeValue in pairs(spec.attributes or {}) do
                local okAttribute,attributeError=pcall(function()
                    inst:SetAttribute(tostring(attributeName),decodeValue(attributeValue))
                end)
                if not okAttribute then table.insert(attributeProblems,{name=tostring(attributeName),error=tostring(attributeError)}) end
            end
            inst.Parent=model
            local d=describeRef(inst)
            d.propertyProblems=(#problems>0) and problems or nil
            d.attributeProblems=(#attributeProblems>0) and attributeProblems or nil
            table.insert(created,d)
            if inst:IsA("BasePart") and #sample<8 then table.insert(sample,inst) end
        end
    end
    if #created==0 then model:Destroy(); return failCode("BAD_ARGS","No assembly items could be created.",errors) end
    if args.pivot then local pivot=decodeValue(args.pivot); if typeof(pivot)=="CFrame" then model:PivotTo(pivot) elseif typeof(pivot)=="Vector3" then model:PivotTo(CFrame.new(pivot)) end end
    waypoint("build assembly "..model.Name)
    return ok({model=describeRef(model),created=created,count=#created,errors=errors,geometry=waitMeasurable(sample,2),note="All parts were created, repeated and grouped in one atomic build call; use the returned model id for moving/cloning."})
end


-- ---------------------------------------------------------------------------
-- UI ENGINE 1.0 (6.2): KOMPOSITE OBERFLAECHEN STATT NACKTER FRAMES
-- Die KI liefert nur Absicht (Rolle, Rechteck im Design-Raum, Skin). Die
-- Bridge rechnet AnchorPoint, Scale-UDim2, Seitenverhaeltnis, Eckenradius,
-- Innenabstand, Schattenstapel, Konturstapel, Farbharmonie und Kontrast.
-- MASTER_BUILD ist das Vorbild: eine globale Tabelle, damit das Plugin kein
-- weiteres Top-Level-local verbraucht (Luau-Grenze 200).
-- ---------------------------------------------------------------------------
UI_ENGINE = {}
-- Version 7.0.0: Engine 2.0 - Glow, echte Texturen (textureImage statt
-- nur prozeduraler Muster) und Radialmenues aus einer Bild-Id.
UI_ENGINE.ENGINE_VERSION = "2.0"

-- Version 7.2.0: CODE-STRUKTUR MESSEN (Thema 2: GUI wirklich in StarterGui,
-- viele kleine Skripte statt eines Monolithen).
-- Ein Skript, das die ganze Oberflaeche zur Laufzeit mit Instance.new
-- aufbaut, ist in Studio nicht editierbar, kostet beim Beitritt Leistung und
-- kann von niemandem gelesen werden. Gemessen wird beim Schreiben.
UI_ENGINE.codeLayoutReport = function(source)
    local text = tostring(source or "")
    local lines = select(2, string.gsub(text, "\n", "\n")) + 1
    local function countOccurrences(needle)
        local total, position = 0, 1
        while true do
            local found = string.find(text, needle, position, true)
            if not found then break end
            total = total + 1
            position = found + #needle
        end
        return total
    end
    local instanceNew = countOccurrences("Instance.new(")
    local clones = countOccurrences(":Clone()")
    local parentWrites = countOccurrences(".Parent =")
    local level = "ok"
    if lines > 400 then level = "monolith"
    elseif lines > 250 then level = "large"
    elseif instanceNew >= 15 then level = "runtime_built" end
    local report = {
        lines = lines,
        instanceNewCalls = instanceNew,
        cloneCalls = clones,
        parentAssignments = parentWrites,
        monolithRisk = (level ~= "ok"),
        level = level,
    }
    if level == "ok" then
        report.advice = ""
    elseif level == "runtime_built" then
        report.advice = "RUNTIME_BUILT_UI: die Oberflaeche wird zur Laufzeit mit Instance.new erzeugt, statt in StarterGui zu liegen. Baue Frames und Knoepfe als ECHTE gespeicherte Instanzen (build_interface/ui_engine) und lass jedes kleine Skript nur das aendern, was ihm gehoert. Eine zur Laufzeit gebaute Oberflaeche ist in Studio nicht editierbar, kostet beim Beitritt Zeit und ist nicht lesbar."
    elseif level == "large" then
        report.advice = "LARGE_SCRIPT: dieses Skript hat ueber 250 Zeilen. Teile es nach Verantwortung auf (Eingabe, Zustand, Aktualisierung, Effekte, Daten) - mehrere kleine ModuleScripts/LocalScripts unter derselben ScreenGui, jedes in einem Zug lesbar."
    else
        report.advice = "MONOLITH_SCRIPT: dieses Skript hat ueber 400 Zeilen. Genau so entsteht ein unlesbarer Monolith; teile es in kleine Skripte mit je EINER Verantwortung (siehe uiStructureRules und scaffold_ui_scripts)."
    end
    return report
end

UI_ENGINE.describeCodeLayout = function(layout)
    if layout == nil then return nil end
    if layout.monolithRisk ~= true then return nil end
    return "MONOLITH_RISK (" .. tostring(layout.level) .. ", " .. tostring(layout.lines) .. " Zeilen, "
        .. tostring(layout.instanceNewCalls) .. "x Instance.new): " .. tostring(layout.advice)
end

-- AnchorPoint wird NIE geraten: er folgt immer aus der Ausrichtung. Das ist
-- die Wurzel des haeufigsten Fehlers (AnchorPoint 0,0 + Skalierungs-
-- animation => das Element waechst nach unten rechts statt aus der Mitte).
UI_ENGINE.ALIGN = {
    center = {0.5, 0.5}, top = {0.5, 0}, bottom = {0.5, 1}, left = {0, 0.5}, right = {1, 0.5},
    topleft = {0, 0}, topright = {1, 0}, bottomleft = {0, 1}, bottomright = {1, 1},
}
-- Eckenprofile statt roher Pixelzahlen; Skalenwerte sind aufloesungsunabhaengig.
UI_ENGINE.CORNER = { sharp = 0, crisp = 0.02, soft = 0.055, round = 0.13, chunky = 0.22, pill = 0.5 }
-- Reale Roblox-Viewports fuer die rechnerische Geraetematrix (keine Screenshots noetig).
UI_ENGINE.DEVICES = { phone = {896, 414}, tablet = {1112, 834}, desktop = {1920, 1080}, ultrawide = {2560, 1080} }
UI_ENGINE.FONTFAMILY = {
    Gotham = "rbxasset://fonts/families/GothamSSm.json",
    Montserrat = "rbxasset://fonts/families/Montserrat.json",
    SourceSans = "rbxasset://fonts/families/SourceSansPro.json",
    Fredoka = "rbxasset://fonts/families/FredokaOne.json",
    Bangers = "rbxasset://fonts/families/Bangers.json",
    Luckiest = "rbxasset://fonts/families/LuckiestGuy.json",
    Marker = "rbxasset://fonts/families/PermanentMarker.json",
    Merriweather = "rbxasset://fonts/families/Merriweather.json",
    Arimo = "rbxasset://fonts/families/Arimo.json",
    Mono = "rbxasset://fonts/families/Inconsolata.json",
    Creepster = "rbxasset://fonts/families/Creepster.json",
    Kalam = "rbxasset://fonts/families/Kalam.json",
}

-- ---------------------------------------------------------------------------
-- FAEHIGKEITSPROBE: nie wieder Code aus altem Wissen schreiben.
-- Jede moderne Instanz/Eigenschaft wird zur Laufzeit GEMESSEN, nicht geraten.
-- ---------------------------------------------------------------------------
function UI_ENGINE.probeClass(className)
    local made, inst = pcall(Instance.new, className)
    if made and inst then pcall(function() inst:Destroy() end); return true end
    return false
end

function UI_ENGINE.caps(force)
    if UI_ENGINE._caps ~= nil and force ~= true then return UI_ENGINE._caps end
    local c = {}
    c.uiShadow = UI_ENGINE.probeClass("UIShadow")
    c.uiFlexItem = UI_ENGINE.probeClass("UIFlexItem")
    c.uiDragDetector = UI_ENGINE.probeClass("UIDragDetector")
    c.path2D = UI_ENGINE.probeClass("Path2D")
    c.styleSheet = UI_ENGINE.probeClass("StyleSheet")
    c.canvasGroup = UI_ENGINE.probeClass("CanvasGroup")
    c.individualCorners = false
    local madeC, corner = pcall(Instance.new, "UICorner")
    if madeC and corner then
        c.individualCorners = pcall(function() corner.TopRightRadius = UDim.new(0, 4) end)
        pcall(function() corner:Destroy() end)
    end
    c.strokeScaledSize, c.strokeBorderOffset, c.strokeMulti = false, false, false
    local madeS, stroke = pcall(Instance.new, "UIStroke")
    if madeS and stroke then
        c.strokeScaledSize = pcall(function() stroke.StrokeSizingMode = Enum.StrokeSizingMode.ScaledSize end)
        c.strokeBorderOffset = pcall(function() stroke.BorderOffset = UDim.new(0, 0) end)
        pcall(function() stroke:Destroy() end)
    end
    local madeF, probe = pcall(Instance.new, "Frame")
    if madeF and probe then
        local a, b = Instance.new("UIStroke"), Instance.new("UIStroke")
        local both = pcall(function() a.Parent = probe; b.Parent = probe end)
        c.strokeMulti = both and (#probe:GetChildren() >= 2)
        pcall(function() probe:Destroy() end)
    end
    c.fontFace = pcall(function() return Font.new(UI_ENGINE.FONTFAMILY.Gotham, Enum.FontWeight.Bold) end)
    UI_ENGINE._caps = c
    return c
end

function UI_ENGINE.capNotes()
    local c, notes = UI_ENGINE.caps(), {}
    if not c.uiShadow then table.insert(notes, "UIShadow missing: the engine falls back to a stacked halo-frame shadow. Ask the user to update Roblox Studio for native drop shadows.") end
    if not c.strokeScaledSize then table.insert(notes, "UIStroke.StrokeSizingMode missing: stroke thickness falls back to pixel offset and is rescaled by the runtime script instead.") end
    if not c.individualCorners then table.insert(notes, "Individual UICorner radii missing: all four corners share one radius.") end
    if not c.strokeMulti then table.insert(notes, "Only one UIStroke per object: the inner bevel stroke is skipped.") end
    return notes
end

-- ---------------------------------------------------------------------------
-- FARBE: Ableitung statt Erfindung. Eine Markenfarbe erzeugt die Palette.
-- ---------------------------------------------------------------------------
function UI_ENGINE.col(value, fallback)
    if typeof(value) == "Color3" then return value end
    if type(value) == "string" then
        local hex = value:gsub("#", "")
        if #hex == 6 then
            local r = tonumber(hex:sub(1, 2), 16); local g = tonumber(hex:sub(3, 4), 16); local b = tonumber(hex:sub(5, 6), 16)
            if r and g and b then return Color3.fromRGB(r, g, b) end
        end
    end
    if type(value) == "table" then
        local r = tonumber(value.r or value.R or value[1])
        local g = tonumber(value.g or value.G or value[2])
        local b = tonumber(value.b or value.B or value[3])
        if r and g and b then
            if r <= 1 and g <= 1 and b <= 1 and (r + g + b) <= 3 then return Color3.new(r, g, b) end
            return Color3.fromRGB(r, g, b)
        end
    end
    return fallback or Color3.fromRGB(255, 255, 255)
end

function UI_ENGINE.shift(c, dh, ds, dv)
    local h, s, v = c:ToHSV()
    h = (h + (dh or 0)) % 1
    s = math.clamp(s + (ds or 0), 0, 1)
    v = math.clamp(v + (dv or 0), 0, 1)
    return Color3.fromHSV(h, s, v)
end

function UI_ENGINE.mix(a, b, t)
    t = math.clamp(t or 0.5, 0, 1)
    return Color3.new(a.R + (b.R - a.R) * t, a.G + (b.G - a.G) * t, a.B + (b.B - a.B) * t)
end

-- WCAG-artige relative Leuchtdichte -> echter, messbarer Textkontrast.
function UI_ENGINE.lum(c)
    local function ch(u) if u <= 0.03928 then return u / 12.92 end return ((u + 0.055) / 1.055) ^ 2.4 end
    return 0.2126 * ch(c.R) + 0.7152 * ch(c.G) + 0.0722 * ch(c.B)
end

function UI_ENGINE.contrast(a, b)
    local la, lb = UI_ENGINE.lum(a), UI_ENGINE.lum(b)
    if la < lb then la, lb = lb, la end
    return (la + 0.05) / (lb + 0.05)
end

function UI_ENGINE.readable(bg, light, dark)
    light = light or Color3.fromRGB(255, 255, 255)
    dark = dark or Color3.fromRGB(18, 14, 20)
    if UI_ENGINE.contrast(bg, light) >= UI_ENGINE.contrast(bg, dark) then return light end
    return dark
end

-- Generik-Erkennung: das entsaettigte Blaugrau der immergleichen
-- "Dark-Website"-GUI wird als Signatur erkannt und abgelehnt.
function UI_ENGINE.isGeneric(c)
    local h, s, v = c:ToHSV()
    local deg = h * 360
    if s < 0.07 and v < 0.42 then return true end
    if s < 0.26 and v < 0.32 and deg > 192 and deg < 272 then return true end
    return false
end

-- Die Palette ist hue-gebunden: auch ein dunkler Skin bleibt farbig
-- (tiefes Pflaume/Teal/Moos), nie das neutrale Dashboard-Anthrazit.
function UI_ENGINE.palette(brand, mood, overrides)
    local a = UI_ENGINE.col(brand, Color3.fromRGB(255, 77, 109))
    local h, s, v = a:ToHSV()
    s = math.max(s, 0.45)
    local p = {}
    p.accent = Color3.fromHSV(h, s, math.max(v, 0.62))
    p.accentHi = UI_ENGINE.shift(p.accent, 0.015, -0.14, 0.18)
    p.accentLo = UI_ENGINE.shift(p.accent, -0.015, 0.08, -0.26)
    p.comp = Color3.fromHSV((h + 0.5) % 1, s * 0.85, math.max(v, 0.6))
    p.warm = Color3.fromHSV((h + 0.07) % 1, s, math.max(v, 0.7))
    if mood == "light" then
        p.surface = Color3.fromHSV(h, math.min(0.11, s * 0.22), 0.97)
        p.surfaceHi = Color3.fromHSV(h, math.min(0.05, s * 0.10), 1.00)
        p.surfaceLo = Color3.fromHSV(h, math.min(0.19, s * 0.38), 0.87)
        p.text = Color3.fromHSV(h, math.min(0.42, s * 0.55), 0.14)
    elseif mood == "pastel" then
        p.surface = Color3.fromHSV(h, math.min(0.28, s * 0.45), 0.94)
        p.surfaceHi = Color3.fromHSV(h, math.min(0.16, s * 0.28), 0.99)
        p.surfaceLo = Color3.fromHSV(h, math.min(0.38, s * 0.62), 0.82)
        p.text = Color3.fromHSV(h, math.min(0.48, s * 0.7), 0.22)
    elseif mood == "ink" then
        p.surface = Color3.fromHSV(h, 0.05, 0.99)
        p.surfaceHi = Color3.fromRGB(255, 255, 255)
        p.surfaceLo = Color3.fromHSV(h, 0.10, 0.90)
        p.text = Color3.fromRGB(16, 14, 18)
    else
        -- "deep": bewusst stark eingefaerbt, Mindestsaettigung verhindert Anthrazit.
        p.surface = Color3.fromHSV(h, math.max(0.38, s * 0.74), 0.235)
        p.surfaceHi = Color3.fromHSV(h, math.max(0.34, s * 0.66), 0.34)
        p.surfaceLo = Color3.fromHSV(h, math.max(0.46, s * 0.86), 0.145)
        p.text = Color3.fromHSV(h, 0.10, 0.98)
    end
    p.textMuted = UI_ENGINE.mix(p.text, p.surface, 0.44)
    p.stroke = UI_ENGINE.mix(p.surfaceLo, p.accent, 0.35)
    p.strokeHi = UI_ENGINE.mix(p.surfaceHi, Color3.fromRGB(255, 255, 255), 0.55)
    p.shadow = Color3.fromHSV(h, math.min(0.75, s * 1.1), 0.08)
    p.glow = p.accent
    if type(overrides) == "table" then
        for key, value in pairs(overrides) do p[key] = UI_ENGINE.col(value, p[key]) end
    end
    return p
end

