-- ===========================================================================
-- WELT-ENGINE 1.0 (Version 7.0.0)
-- VERTRAG: Die Welt ist ein Ort mit Regeln, nicht eine Sammlung von Teilen.
--   * Erst messen (site_survey), dann Stil festlegen (world_style), dann
--     bauen - und am Ende model_audit/world_audit statt Behauptungen.
--   * Jede Variation ist deterministisch: derselbe Seed liefert dieselbe
--     Welt. Kein math.random, kein Raten, keine zwei gleichen Nachbarn.
--   * Platzhalter und Blockouts werden GEZAEHLT und gemeldet; die KI darf
--     ohne Uebergabe (handoff) nicht "fertig" behaupten, solange sie existieren.
--   * Der billige Weg ist schlechter als der richtige: ohne Stil/Lock sinkt
--     die Bewertung von model_audit und world_audit sichtbar.
-- ===========================================================================
local WORLD_ENGINE = {}
WORLD_ENGINE.VERSION = "1.0"
WORLD_ENGINE.ROOT = "ArenaWelt"
WORLD_ENGINE.PROPS = "ArenaProps"
WORLD_ENGINE.DETAIL = "ArenaDetail"

local worldStyle = nil

WORLD_ENGINE.PRESETS = {
    coastal = { label = "Coastal", palette = { "#E9DFC8", "#8FB8B0", "#3E6B63", "#D9A15B", "#5B6B78" },
        materials = { "Wood", "Sand", "Slate", "Fabric", "Metal", "Glass" }, density = 0.55, weathering = 0.35 },
    forest  = { label = "Forest",  palette = { "#DDE3C4", "#6E8B52", "#2F4A33", "#B98A54", "#4A5D53" },
        materials = { "Wood", "Grass", "LeafyGrass", "Slate", "Fabric" }, density = 0.65, weathering = 0.30 },
    desert  = { label = "Desert",  palette = { "#F0DFC0", "#D9B173", "#9C6B3F", "#5A4632", "#C97F4A" },
        materials = { "Sand", "Sandstone", "Slate", "Wood", "Fabric" }, density = 0.40, weathering = 0.55 },
    snow    = { label = "Snow",    palette = { "#F2F6FA", "#B9CFE0", "#5D7C9B", "#3A4A5C", "#C4A484" },
        materials = { "Snow", "Ice", "Slate", "Wood", "Metal", "Glass" }, density = 0.45, weathering = 0.25 },
    urban   = { label = "Urban",   palette = { "#E4E0DA", "#9A9C9E", "#4A4E52", "#C2A15A", "#7A4A3A" },
        materials = { "Concrete", "Metal", "Glass", "Brick", "Asphalt", "Wood" }, density = 0.75, weathering = 0.40 },
    volcanic = { label = "Volcanic", palette = { "#E8D5C0", "#8C4A3A", "#3A2B2B", "#D96A2B", "#6B3A54" },
        materials = { "Basalt", "Slate", "Rock", "Metal", "CrackedLava" }, density = 0.50, weathering = 0.70 },
}

local function styleCopy(source, overrides)
    local copy = {}
    for key, value in pairs(source or {}) do
        if type(value) == "table" then
            local inner = {}
            for k2, v2 in pairs(value) do inner[k2] = v2 end
            copy[key] = inner
        else
            copy[key] = value
        end
    end
    for key, value in pairs(overrides or {}) do copy[key] = value end
    return copy
end

local function stylePaletteList(style)
    local list = {}
    for _, value in ipairs((style or {}).palette or {}) do
        local col = UI_ENGINE and UI_ENGINE.col(value, nil) or nil
        if col then table.insert(list, col) end
    end
    return list
end

local function nearestPalette(style, color)
    local list = stylePaletteList(style)
    if #list == 0 then return nil, 999 end
    local best, bestDist = nil, 9e9
    for _, entry in ipairs(list) do
        local dr = (entry.R - color.R) * 255
        local dg = (entry.G - color.G) * 255
        local db = (entry.B - color.B) * 255
        local dist = math.sqrt(dr * dr + dg * dg + db * db)
        if dist < bestDist then best, bestDist = entry, dist end
    end
    return best, bestDist
end

local function hexOf(color)
    return string.format("#%02X%02X%02X", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
end

-- deterministic variation: same seed -> same world, always.
local function lcg(seed)
    local state = math.floor(math.abs(tonumber(seed) or 1)) % 2147483647
    if state == 0 then state = 1 end
    return function()
        state = (state * 48271) % 2147483647
        return state / 2147483647
    end
end

local function variationValue(seed, index, low, high, decimals)
    local rng = lcg((tonumber(seed) or 1) + (tonumber(index) or 0) * 7919)
    local value = low + (high - low) * rng()
    if decimals then
        local factor = 10 ^ decimals
        value = math.floor(value * factor + 0.5) / factor
    end
    return value
end

local function groundHit(x, z)
    local params = RaycastParams.new()
    pcall(function() params.FilterType = Enum.RaycastFilterType.Exclude end)
    params.FilterDescendantsInstances = { workspace:FindFirstChild(WORLD_ENGINE.ROOT) }
    local result = workspace:Raycast(Vector3.new(x, 4000, z), Vector3.new(0, -6000, 0), params)
    if result then return result end
    return nil
end

local function partsInBox(center, size)
    local params = OverlapParams.new()
    pcall(function() params.FilterType = Enum.RaycastFilterType.Exclude end)
    local okBox, list = pcall(function() return workspace:GetPartBoundsInBox(CFrame.new(center), size, params) end)
    if okBox and list then return list end
    return {}
end

local function isPlaceholderName(name)
    return string.match(string.lower(tostring(name or "")), "placehold") ~= nil
        or string.match(string.lower(tostring(name or "")), "blockout") ~= nil
        or string.match(string.lower(tostring(name or "")), "provisor") ~= nil
        or string.match(string.lower(tostring(name or "")), "todo") ~= nil
end

local function isPlaceholderPart(part)
    if part:GetAttribute("ArenaPlaceholder") == true then return true, "attribute ArenaPlaceholder" end
    if isPlaceholderName(part.Name) then return true, "name looks like a placeholder" end
    return false, nil
end

local function isBlockoutPart(part)
    if not part:IsA("BasePart") then return false end
    if part:IsA("MeshPart") then return false end
    local ok = pcall(function()
        if part.Material ~= Enum.Material.Plastic then error("material") end
    end)
    if not ok then return false end
    local color = part.Color
    local dr = math.abs(color.R * 255 - 163)
    local dg = math.abs(color.G * 255 - 162)
    local db = math.abs(color.B * 255 - 165)
    return (dr < 12 and dg < 12 and db < 12), hexOf(color)
end

local function targetFrom(args, allowSelection)
    if args.ref ~= nil then
        local root, err = resolveRef(args.ref)
        if not root then return nil, err end
        return root, nil
    end
    if allowSelection == true or args.useSelection == true then
        local selected = Selection:Get()
        if #selected == 0 then return nil, "Selection is empty - select something in Studio or pass ref." end
        return selected[1], nil
    end
    return nil, nil
end

local function collectParts(root, out, limit)
    out = out or {}
    limit = limit or 8000
    local stack = { root }
    while #stack > 0 and #out < limit do
        local current = table.remove(stack)
        if current:IsA("BasePart") then table.insert(out, current) end
        for _, child in ipairs(current:GetChildren()) do
            if not child:IsA("BasePart") then table.insert(stack, child)
            elseif #out < limit then table.insert(out, child) end
        end
    end
    return out
end

local function buildProceduralProp(kind, style, index, seed)
    local model = Instance.new("Model")
    model.Name = "ArenaProp"
    local palette = stylePaletteList(style)
    local base = palette[1 + (#palette > 0 and (index % #palette) or 0)] or Color3.fromRGB(180, 180, 180)
    local accent = palette[1 + ((index + 1) % math.max(#palette, 1))] or base
    local parts = {}
    local function add(class, size, cf, color, material)
        local part = Instance.new(class)
        part.Size = size
        part.CFrame = cf
        part.Color = color
        pcall(function() part.Material = Enum.Material[material] end)
        part.Anchored = true
        part.Parent = model
        table.insert(parts, part)
        return part
    end
    if kind == "rock" then
        local n = 3
        for i = 1, n do
            local s = variationValue(seed, index * 31 + i, 1.6, 3.4, 2)
            local rot = variationValue(seed, index * 37 + i, 0, math.pi * 2, 3)
            add("Part", Vector3.new(s, s * 0.8, s * variationValue(seed, index * 41 + i, 0.8, 1.3, 2)),
                CFrame.new(variationValue(seed, index * 43 + i, -1.2, 1.2, 2), s * 0.35, variationValue(seed, index * 47 + i, -1.2, 1.2, 2))
                    * CFrame.Angles(variationValue(seed, index * 53 + i, -0.4, 0.4, 3), rot, 0),
                i == 1 and base or accent, i == 1 and "Slate" or "Rock")
        end
    elseif kind == "bush" then
        for i = 1, 3 do
            local s = variationValue(seed, index * 59 + i, 1.2, 2.2, 2)
            add("Part", Vector3.new(s, s, s),
                CFrame.new(variationValue(seed, index * 61 + i, -0.8, 0.8, 2), 0.8 + i * 0.5, variationValue(seed, index * 67 + i, -0.8, 0.8, 2)),
                i == 1 and accent or base, "LeafyGrass")
        end
    else -- crate
        add("Part", Vector3.new(2, 2, 2), CFrame.new(0, 1, 0), base, "Wood")
        for i = 1, 4 do
            local angle = (i - 1) * math.pi / 2
            add("Part", Vector3.new(0.16, 2.06, 0.16), CFrame.new(math.cos(angle) * 1.0, 1, math.sin(angle) * 1.0), accent, "Wood")
        end
    end
    model.PrimaryPart = parts[1]
    for _, part in ipairs(parts) do
        if part ~= parts[1] then
            local weld = Instance.new("WeldConstraint")
            weld.Part0 = parts[1]
            weld.Part1 = part
            weld.Parent = parts[1]
        end
    end
    model:SetAttribute("ArenaPropKind", kind)
    return model
end

tools.world_style = function(args)
    local overrides = {}
    local presetKey = args.preset and string.lower(tostring(args.preset)) or nil
    local source = presetKey and WORLD_ENGINE.PRESETS[presetKey] or ((worldStyle and worldStyle.preset and WORLD_ENGINE.PRESETS[worldStyle.preset]) or {})
    if presetKey and not WORLD_ENGINE.PRESETS[presetKey] then
        return failCode("BAD_ARGS", "Unknown preset '" .. tostring(args.preset) .. "'. Known: coastal, forest, desert, snow, urban, volcanic.", { known = { "coastal", "forest", "desert", "snow", "urban", "volcanic" } })
    end
    if type(args.palette) == "table" then overrides.palette = args.palette end
    if type(args.materials) == "table" then overrides.materials = args.materials end
    if args.density ~= nil then overrides.density = math.clamp(tonumber(args.density) or 0.5, 0, 1) end
    if args.weathering ~= nil then overrides.weathering = math.clamp(tonumber(args.weathering) or 0.3, 0, 1) end
    if args.seed ~= nil then overrides.seed = math.floor(tonumber(args.seed) or 1) end
    if args.label ~= nil then overrides.label = tostring(args.label) end
    local style = styleCopy(source, overrides)
    style.preset = presetKey or style.preset
    style.seed = style.seed or math.floor(os.time() % 100000)
    style.locked = false
    worldStyle = style
    local paletteHex = {}
    for _, value in ipairs(stylePaletteList(style)) do table.insert(paletteHex, hexOf(value)) end
    return ok({
        style = { preset = style.preset, label = style.label, seed = style.seed, density = style.density, weathering = style.weathering },
        palette = paletteHex,
        materials = (style.materials or {}),
        locked = false,
        rules = {
            "site_survey first: measure ground, clearance and existing parts before placing anything.",
            "Every variation uses this seed - the same seed rebuilds the same world.",
            "style_lock before a large build; model_audit/world_audit afterwards. Placeholders must be zero before 'done'.",
        },
        nextStep = "Call style_lock to bind this style to the place, then build with prop_place / refine.",
    })
end

tools.style_lock = function(args)
    if not worldStyle then
        return failCode("NO_WORLD_STYLE", "No style is active. Call world_style first (one call: preset=\"coastal\" or your own palette).", {
            howToFix = "world_style { preset = \"forest\" } then style_lock.",
        })
    end
    worldStyle.locked = true
    if args.seed ~= nil then worldStyle.seed = math.floor(tonumber(args.seed) or worldStyle.seed) end
    local root = workspace:FindFirstChild(WORLD_ENGINE.ROOT)
    if not root then
        root = Instance.new("Folder")
        root.Name = WORLD_ENGINE.ROOT
        root.Parent = workspace
    end
    local styleFolder = root:FindFirstChild("Style")
    if not styleFolder then
        styleFolder = Instance.new("Folder")
        styleFolder.Name = "Style"
        styleFolder.Parent = root
    end
    styleFolder:SetAttribute("ArenaWorldStylePreset", tostring(worldStyle.preset or "custom"))
    styleFolder:SetAttribute("ArenaWorldStyleLabel", tostring(worldStyle.label or "custom"))
    styleFolder:SetAttribute("ArenaWorldStyleSeed", tonumber(worldStyle.seed) or 0)
    styleFolder:SetAttribute("ArenaWorldStyleLocked", true)
    waypoint("style lock")
    return ok({
        locked = true,
        preset = worldStyle.preset,
        label = worldStyle.label,
        seed = worldStyle.seed,
        folder = WORLD_ENGINE.ROOT .. ".Style",
        note = "world_style/model_audit/world_audit read this lock; off-style parts are reported with measured distance.",
    })
end

tools.site_survey = function(args)
    local center = args.center or { x = 0, y = 0, z = 0 }
    local size = args.size or { x = 200, y = 120, z = 200 }
    local cx, cy, cz = tonumber(center.x) or 0, tonumber(center.y) or 0, tonumber(center.z) or 0
    local sx, sy, sz = tonumber(size.x) or 200, tonumber(size.y) or 120, tonumber(size.z) or 200
    local samples = math.clamp(math.floor(tonumber(args.samples) or 5), 2, 9)
    local heights, materials, water = {}, {}, 0
    local minH, maxH, sumH = nil, nil, 0
    local clearance = {}
    local total = 0
    for ix = 0, samples - 1 do
        for iz = 0, samples - 1 do
            local x = cx - sx / 2 + sx * (ix + 0.5) / samples
            local z = cz - sz / 2 + sz * (iz + 0.5) / samples
            local hit = groundHit(x, z)
            total = total + 1
            if hit then
                local h = hit.Position.Y
                if minH == nil or h < minH then minH = h end
                if maxH == nil or h > maxH then maxH = h end
                sumH = sumH + h
                table.insert(heights, math.floor(h * 100 + 0.5) / 100)
                local mat = "Unknown"
                pcall(function() mat = hit.Material.Name end)
                materials[mat] = (materials[mat] or 0) + 1
                if mat == "Water" then water = water + 1 end
                local params = RaycastParams.new()
                pcall(function() params.FilterType = Enum.RaycastFilterType.Exclude end)
                local up = workspace:Raycast(Vector3.new(x, h + 2, z), Vector3.new(0, sy, 0), params)
                table.insert(clearance, up and math.floor((up.Position.Y - h) * 10) / 10 or sy)
            end
        end
    end
    local parts = partsInBox(Vector3.new(cx, cy, cz), Vector3.new(sx, sy, sz))
    table.sort(clearance)
    local medianClearance = #clearance > 0 and clearance[math.max(1, math.floor(#clearance / 2))] or nil
    local span = (maxH and minH) and math.floor((maxH - minH) * 100) / 100 or 0
    return ok({
        area = { center = { x = cx, y = cy, z = cz }, size = { x = sx, y = sy, z = sz } },
        samples = total,
        ground = {
            minHeight = minH and math.floor(minH * 100) / 100 or nil,
            maxHeight = maxH and math.floor(maxH * 100) / 100 or nil,
            averageHeight = total > 0 and math.floor((sumH / total) * 100) / 100 or nil,
            span = span,
            slope = (sx > 0 and samples > 1) and math.floor((span / (sx * (samples - 1) / samples)) * 1000) / 1000 or 0,
            materials = materials,
            waterSamples = water,
        },
        freeSpace = { medianClearanceStuds = medianClearance, samples = #clearance },
        existingParts = #parts,
        suggestedOrigin = { x = cx, y = (minH or cy), z = cz },
        honest = "measured by raycast and overlap query - nothing here is estimated from training data",
    })
end

tools.variation = function(args)
    local seed = math.floor(tonumber(args.seed) or 1)
    local count = math.clamp(math.floor(tonumber(args.count) or 8), 1, 512)
    local low = tonumber(args.min) or 0
    local high = tonumber(args.max) or 1
    local decimals = args.decimals and math.clamp(math.floor(tonumber(args.decimals) or 0), 0, 6) or 4
    local list = {}
    for i = 1, count do table.insert(list, variationValue(seed, i, low, high, decimals)) end
    return ok({ seed = seed, count = count, min = low, max = high, values = list,
        formula = "state = (state * 48271) % 2147483647 - deterministic for a given seed",
        nextSeed = (seed * 48271) % 2147483647 })
end

tools.prop_place = function(args)
    local kinds = { rock = true, bush = true, crate = true }
    local kind = string.lower(tostring(args.kind or "rock"))
    local saved = nil
    if args.propName then
        local folder = workspace:FindFirstChild(WORLD_ENGINE.PROPS)
        saved = folder and folder:FindFirstChild(tostring(args.propName)) or nil
        if not saved then
            return failCode("PROP_NOT_FOUND", "No saved prop named '" .. tostring(args.propName) .. "' under workspace." .. WORLD_ENGINE.PROPS .. ".", {
                hint = "prop_list shows what exists; prop_save stores a selection.",
            })
        end
    elseif not kinds[kind] then
        return failCode("BAD_ARGS", "Unknown kind '" .. tostring(kind) .. "'. Use rock, bush, crate or propName=<saved prop>.", { known = { "rock", "bush", "crate" } })
    end
    local count = math.clamp(math.floor(tonumber(args.count) or 6), 1, 200)
    local seed = math.floor(tonumber(args.seed) or (worldStyle and worldStyle.seed) or 1)
    local center = args.center or { x = 0, y = 0, z = 0 }
    local size = args.size or { x = 60, y = 0, z = 60 }
    local cx, cz = tonumber(center.x) or 0, tonumber(center.z) or 0
    local sx, sz = tonumber(size.x) or 60, tonumber(size.z) or 60
    local root = workspace:FindFirstChild(WORLD_ENGINE.ROOT)
    if not root then
        root = Instance.new("Folder")
        root.Name = WORLD_ENGINE.ROOT
        root.Parent = workspace
    end
    local holder = args.group and root:FindFirstChild(tostring(args.group)) or nil
    if not holder then
        holder = Instance.new("Folder")
        holder.Name = tostring(args.group or (kind .. "s"))
        holder.Parent = root
    end
    local style = worldStyle or WORLD_ENGINE.PRESETS.coastal
    local placed, skipped, parts = 0, 0, 0
    for i = 1, count do
        local x = cx + variationValue(seed, i * 11, -sx / 2, sx / 2, 3)
        local z = cz + variationValue(seed, i * 13, -sz / 2, sz / 2, 3)
        local hit = groundHit(x, z)
        if hit and hit.Material ~= Enum.Material.Water then
            local y = hit.Position.Y
            local yaw = variationValue(seed, i * 17, 0, math.pi * 2, 4)
            local scale = variationValue(seed, i * 19, 0.85, 1.15, 3)
            local prop
            if saved then
                prop = saved:Clone()
                prop.Name = string.format("%s_%03d", tostring(saved.Name), i)
            else
                prop = buildProceduralProp(kind, style, i, seed)
                prop.Name = string.format("%s_%03d", kind, i)
            end
            prop:PivotTo(CFrame.new(x, y, z) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(0, 0, 0))
            if scale ~= 1 then
                pcall(function() prop:ScaleTo(scale) end)
            end
            prop:SetAttribute("ArenaVariationSeed", seed)
            prop:SetAttribute("ArenaVariationIndex", i)
            prop.Parent = holder
            placed = placed + 1
            parts = parts + #collectParts(prop, {}, 500)
        else
            skipped = skipped + 1
        end
    end
    waypoint("place props " .. kind)
    return ok({
        kind = saved and "saved" or kind,
        propName = saved and saved.Name or nil,
        group = holder:GetFullName(),
        requested = count,
        placed = placed,
        skipped = skipped,
        skippedBecause = skipped > 0 and "no ground or water under the sampled point" or nil,
        variationSeed = seed,
        partsCreated = parts,
        stylePreset = (worldStyle and worldStyle.preset) or nil,
        styleLocked = (worldStyle and worldStyle.locked) or false,
        note = "Deterministic: same seed + same area = same result. Run model_audit afterwards.",
    })
end

tools.prop_save = function(args)
    if not args.name or tostring(args.name) == "" then
        return failCode("BAD_ARGS", "name is missing - saved props are looked up by name in prop_place.")
    end
    local source, err = targetFrom(args, true)
    if not source then
        return failCode(args.ref == nil and "BAD_ARGS" or "REF_NOT_FOUND",
            err or "prop_save needs ref (a Model/Folder or part) or useSelection=true.",
            { hint = "Select the prop in Studio and call prop_save { name=\"tree_a\", useSelection=true }." })
    end
    local root = workspace:FindFirstChild(WORLD_ENGINE.PROPS)
    if not root then
        root = Instance.new("Folder")
        root.Name = WORLD_ENGINE.PROPS
        root.Parent = workspace
    end
    local name = tostring(args.name)
    local existing = root:FindFirstChild(name)
    if existing and args.overwrite ~= true then
        return failCode("PROP_EXISTS", "A prop named '" .. name .. "' already exists.", { howToFix = "Pass overwrite=true or choose another name." })
    end
    if existing then existing:Destroy() end
    local copy = source:Clone()
    copy.Name = name
    copy.Parent = root
    local partList = collectParts(copy, {}, 5000)
    copy:SetAttribute("ArenaPropParts", #partList)
    copy:SetAttribute("ArenaPropSavedAt", os.time())
    copy:SetAttribute("ArenaPropSource", source:GetFullName())
    return ok({ name = name, parts = #partList, folder = WORLD_ENGINE.PROPS,
        source = source:GetFullName(), note = "prop_place { propName=\"" .. name .. "\" } clones this with deterministic variation." })
end

tools.prop_list = function(args)
    local root = workspace:FindFirstChild(WORLD_ENGINE.PROPS)
    local list = {}
    if root then
        for _, child in ipairs(root:GetChildren()) do
            local parts = tonumber(child:GetAttribute("ArenaPropParts")) or #collectParts(child, {}, 5000)
            table.insert(list, { name = child.Name, className = child.ClassName, parts = parts,
                kind = child:GetAttribute("ArenaPropKind"), savedAt = child:GetAttribute("ArenaPropSavedAt") })
        end
    end
    table.sort(list, function(a, b) return a.name < b.name end)
    return ok({ props = list, count = #list, folder = WORLD_ENGINE.PROPS })
end

-- Version 7.3.2: echte Volumen statt Seitenprofil-/Sticker-Tiere.
-- Creature builds declare closed lofts (body/head), bilateral physical eyes,
-- and optional mirrored wing roles. These checks are per-model and use measured
-- part bounds; part count or a single polygon triangle is not volume evidence.
WORLD_ENGINE.auditOrganicCreature = function(organicModel)
    local issues,roleNodes,loftNodes={},{},{}
    local descendants=organicModel:GetDescendants()
    for _,node in ipairs(descendants) do
        local role=nil
        pcall(function() role=node:GetAttribute("ArenaOrganicRole") end)
        if type(role)=="string" and role~="" then
            role=string.lower(role)
            roleNodes[role]=roleNodes[role] or {}
            table.insert(roleNodes[role],node)
        end
        local isLoft=false
        pcall(function() isLoft=node:GetAttribute("ArenaLoftVolume")==true end)
        if isLoft and type(role)=="string" and role~="" then
            loftNodes[role]=loftNodes[role] or {}
            table.insert(loftNodes[role],node)
        end
    end
    local function roleParts(role)
        local found,seen={},{}
        for _,node in ipairs(roleNodes[role] or {}) do
            if node:IsA("BasePart") then
                if not seen[node] then seen[node]=true; table.insert(found,node) end
            else
                for _,part in ipairs(collectParts(node,{},8000)) do
                    if not seen[part] then seen[part]=true; table.insert(found,part) end
                end
            end
        end
        return found
    end
    local forward,up,side=Vector3.new(1,0,0),Vector3.new(0,1,0),Vector3.new(0,0,1)
    pcall(function()
        local value=organicModel:GetAttribute("ArenaOrganicForward")
        if typeof(value)=="Vector3" and value.Magnitude>0.001 then forward=value.Unit end
    end)
    pcall(function()
        local value=organicModel:GetAttribute("ArenaOrganicUp")
        if typeof(value)=="Vector3" and value.Magnitude>0.001 then up=value.Unit end
    end)
    pcall(function()
        local value=organicModel:GetAttribute("ArenaOrganicSide")
        if typeof(value)=="Vector3" and value.Magnitude>0.001 then side=value.Unit end
    end)
    local function measureBounds(list)
        if #list==0 then return nil end
        local minX,minY,minZ=math.huge,math.huge,math.huge
        local maxX,maxY,maxZ=-math.huge,-math.huge,-math.huge
        for _,part in ipairs(list) do
            local size=part.Size
            local cf=part.CFrame
            local position=part.Position
            local x=position:Dot(forward)
            local y=position:Dot(up)
            local z=position:Dot(side)
            local hx=(math.abs(cf.RightVector:Dot(forward))*size.X+math.abs(cf.UpVector:Dot(forward))*size.Y+math.abs(cf.LookVector:Dot(forward))*size.Z)*0.5
            local hy=(math.abs(cf.RightVector:Dot(up))*size.X+math.abs(cf.UpVector:Dot(up))*size.Y+math.abs(cf.LookVector:Dot(up))*size.Z)*0.5
            local hz=(math.abs(cf.RightVector:Dot(side))*size.X+math.abs(cf.UpVector:Dot(side))*size.Y+math.abs(cf.LookVector:Dot(side))*size.Z)*0.5
            minX=math.min(minX,x-hx); maxX=math.max(maxX,x+hx)
            minY=math.min(minY,y-hy); maxY=math.max(maxY,y+hy)
            minZ=math.min(minZ,z-hz); maxZ=math.max(maxZ,z+hz)
        end
        return {
            min=Vector3.new(minX,minY,minZ),max=Vector3.new(maxX,maxY,maxZ),
            center=Vector3.new((minX+maxX)*0.5,(minY+maxY)*0.5,(minZ+maxZ)*0.5),
            size=Vector3.new(maxX-minX,maxY-minY,maxZ-minZ),
        }
    end
    local function roleBounds(role) return measureBounds(roleParts(role)) end
    local function validateLoft(role,minimumSections)
        local candidates=loftNodes[role] or {}
        if #candidates==0 then
            table.insert(issues,string.upper(role).."_VOLUME_REQUIRED: use build_polygon_model.volumes with a closed loft; one side-profile polygon/wedge is not a volume.")
            return nil,0,0
        end
        if #candidates>1 then table.insert(issues,"DUPLICATE_VOLUME_ROLE: keep exactly one loft volume for role="..role..".") end
        local node=candidates[1]
        local sectionCount=tonumber(node:GetAttribute("ArenaLoftSectionCount")) or 0
        local sideCount=tonumber(node:GetAttribute("ArenaLoftSideCount")) or 0
        local expectedFaceCount=tonumber(node:GetAttribute("ArenaLoftExpectedFaceCount")) or 0
        local builtFaceCount=tonumber(node:GetAttribute("ArenaLoftFaceCount")) or 0
        local skippedFaceCount=tonumber(node:GetAttribute("ArenaLoftFacesSkipped")) or 0
        local closedEnds=node:GetAttribute("ArenaLoftClosedEnds")==true
        local topologyFaceCount=2+math.max(0,sectionCount-1)*sideCount
        if sectionCount<minimumSections or sideCount<8 or not closedEnds
            or expectedFaceCount~=topologyFaceCount or builtFaceCount~=expectedFaceCount or skippedFaceCount>0 then
            table.insert(issues,string.upper(role).."_LOFT_INCOMPLETE: sections="..tostring(sectionCount)..", sides="..tostring(sideCount)..", expectedFaces="..tostring(expectedFaceCount)..", builtFaces="..tostring(builtFaceCount)..", skippedFaces="..tostring(skippedFaceCount)..", closedEnds="..tostring(closedEnds).."; rebuild every loft surface and both end caps.")
        end
        local triangleCount=0
        for _,part in ipairs(collectParts(node,{},8000)) do
            if part:GetAttribute("ArenaPolygonTriangle")~=nil then triangleCount=triangleCount+1 end
        end
        if triangleCount<=0 then table.insert(issues,string.upper(role).."_LOFT_EMPTY: the tagged loft contains no generated polygon triangles.") end
        return node,sectionCount,sideCount
    end
    local bodyNode,bodySections,bodySides=validateLoft("body",4)
    local headNode,headSections,headSides=validateLoft("head",3)
    local bodyBounds=roleBounds("body")
    local headBounds=roleBounds("head")
    local function crossSectionRatio(bounds)
        if not bounds then return 0 end
        local largest=math.max(bounds.size.Y,bounds.size.Z)
        if largest<0.001 then return 0 end
        return math.min(bounds.size.Y,bounds.size.Z)/largest
    end
    local bodyDepthRatio=crossSectionRatio(bodyBounds)
    local headDepthRatio=crossSectionRatio(headBounds)
    if bodyBounds and bodyDepthRatio<0.16 then
        table.insert(issues,"BODY_THIN_PROFILE: measured body cross-section Y/Z ratio="..string.format("%.3f",bodyDepthRatio).."; add real depth on both sides instead of a flat side silhouette.")
    end
    if headBounds and headDepthRatio<0.16 then
        table.insert(issues,"HEAD_THIN_PROFILE: measured head cross-section Y/Z ratio="..string.format("%.3f",headDepthRatio).."; the head must have front/back depth.")
    end
    local function taggedPart(role)
        for _,part in ipairs(roleParts(role)) do if part:IsA("BasePart") then return part end end
        return nil
    end
    local function isRound(part)
        if not part then return false end
        local shapeName=nil
        pcall(function() shapeName=part.Shape.Name end)
        local largest=math.max(part.Size.X,part.Size.Y,part.Size.Z)
        local smallest=math.min(part.Size.X,part.Size.Y,part.Size.Z)
        if largest<0.04 or smallest/largest<0.62 then return false end
        -- A cube Part has a perfect aspect ratio too; only accept an unambiguous
        -- Roblox Ball primitive here. Mesh/union eyes may use measured bounds.
        if part:IsA("Part") then return shapeName=="Ball" end
        return part:IsA("MeshPart") or part:IsA("UnionOperation")
    end
    local eyeLeft,eyeRight=taggedPart("eye_left"),taggedPart("eye_right")
    local pupilLeft,pupilRight=taggedPart("pupil_left"),taggedPart("pupil_right")
    local eyePair=false
    local function eyeOnHeadFlank(part,positiveSide)
        if not part or not headBounds then return false end
        local position=part.Position
        local x,y,z=position:Dot(forward),position:Dot(up),position:Dot(side)
        local margin=math.max(0.08,math.max(headBounds.size.X,headBounds.size.Y,headBounds.size.Z)*0.12)
        local withinSkull=x>=headBounds.min.X-margin and x<=headBounds.max.X+margin
            and y>=headBounds.min.Y-margin and y<=headBounds.max.Y+margin
        if positiveSide then return withinSkull and z>headBounds.center.Z+math.max(0.025,headBounds.size.Z*0.06) and z<=headBounds.max.Z+margin end
        return withinSkull and z<headBounds.center.Z-math.max(0.025,headBounds.size.Z*0.06) and z>=headBounds.min.Z-margin
    end
    if not eyeLeft or not eyeRight or not isRound(eyeLeft) or not isRound(eyeRight) then
        table.insert(issues,"EYES_NOT_3D: add separate round eye_left and eye_right BaseParts (ArenaOrganicRole attributes), not a painted face.")
    elseif headBounds then
        if not eyeOnHeadFlank(eyeLeft,true) or not eyeOnHeadFlank(eyeRight,false) then
            table.insert(issues,"EYES_NOT_BILATERAL: measured eye_left must sit on the +Z head flank and eye_right on the -Z flank, both spatially attached to the skull.")
        else
            eyePair=true
        end
    end
    local function physicalPupilNearEye(pupil,eye)
        if not pupil or not eye or not pupil:IsA("BasePart") then return false end
        local largest=math.max(pupil.Size.X,pupil.Size.Y,pupil.Size.Z)
        local smallest=math.min(pupil.Size.X,pupil.Size.Y,pupil.Size.Z)
        if smallest<0.01 or largest<0.01 or smallest/largest<0.06 then return false end
        local offset=pupil.Position-eye.Position
        local eyeScale=math.max(eye.Size.X,eye.Size.Y,eye.Size.Z)
        return offset.Magnitude<=math.max(0.12,eyeScale*1.75)
            and offset:Dot(forward)>=math.max(0.01,eyeScale*0.05)
            and math.abs(offset:Dot(side))<=eyeScale*0.8
            and math.abs(offset:Dot(up))<=eyeScale*0.8
    end
    local pupils3D=physicalPupilNearEye(pupilLeft,eyeLeft) and physicalPupilNearEye(pupilRight,eyeRight)
    if not pupils3D then
        table.insert(issues,"PUPILS_NOT_3D: add two non-flat physical pupil_left/pupil_right BaseParts near the forward surface of their matching eyes; do not draw pupils with a decal/texture.")
    end
    local faceOverlays,overlaySeen={},{}
    local faceOverlayCount=0
    local faceRoots={}
    if headNode then table.insert(faceRoots,headNode) end
    for _,role in ipairs({"face","muzzle","nose","mouth","eye_left","eye_right","pupil_left","pupil_right"}) do
        for _,node in ipairs(roleNodes[role] or {}) do table.insert(faceRoots,node) end
    end
    local function isFaceOverlay(node)
        if node:IsA("Decal") or node:IsA("Texture") or node:IsA("SurfaceGui") or node:IsA("BillboardGui") then return true end
        if node:IsA("SpecialMesh") then
            local textureId=""
            pcall(function() textureId=tostring(node.TextureId or "") end)
            return textureId~="" and textureId~="0"
        end
        if node:IsA("MeshPart") then
            local textureId=""
            pcall(function() textureId=tostring(node.TextureID or "") end)
            return textureId~="" and textureId~="0"
        end
        if node:IsA("SurfaceAppearance") then
            for _,property in ipairs({"ColorMap","NormalMap","RoughnessMap","MetalnessMap"}) do
                local textureId=""
                pcall(function() textureId=tostring(node[property] or "") end)
                if textureId~="" and textureId~="0" then return true end
            end
        end
        return false
    end
    local function recordFaceOverlay(node)
        if node and not overlaySeen[node] and isFaceOverlay(node) then
            overlaySeen[node]=true
            faceOverlayCount=faceOverlayCount+1
            if #faceOverlays<5 then table.insert(faceOverlays,node:GetFullName()) end
        end
    end
    for _,faceRoot in ipairs(faceRoots) do
        recordFaceOverlay(faceRoot)
        for _,node in ipairs(faceRoot:GetDescendants()) do recordFaceOverlay(node) end
    end
    -- Also catch SurfaceGui/BillboardGui instances kept at model root but
    -- explicitly adorned to the skull or one of its physical eye parts.
    for _,node in ipairs(descendants) do
        if not overlaySeen[node] and (node:IsA("SurfaceGui") or node:IsA("BillboardGui")) then
            local adornee=nil
            pcall(function() adornee=node.Adornee end)
            local targetsHead=false
            if adornee and headNode then
                pcall(function() targetsHead=adornee==headNode or adornee:IsDescendantOf(headNode) end)
            end
            if adornee==eyeLeft or adornee==eyeRight or targetsHead then recordFaceOverlay(node) end
        end
    end
    if faceOverlayCount>0 then
        table.insert(issues,"FACE_IMAGE_OVERLAY: creature faces must be physical 3D eye/pupil/muzzle/nose geometry; remove Decal/Texture/SurfaceGui/BillboardGui/MeshPart/PBR texture overlay(s) (count="..tostring(faceOverlayCount)..", sample: "..table.concat(faceOverlays,"; ")..")")
    end
    local wingPair=false
    local hasWings=organicModel:GetAttribute("ArenaOrganicHasWings")==true
        or #(roleNodes.wing_left or {})>0 or #(roleNodes.wing_right or {})>0
    if hasWings then
        local leftWing,rightWing=roleBounds("wing_left"),roleBounds("wing_right")
        if not leftWing or not rightWing or not bodyBounds then
            table.insert(issues,"WING_PAIR_REQUIRED: add role=wing_left (+Z) and role=wing_right (-Z), each attached to the body.")
        else
            local margin=math.max(0.04,bodyBounds.size.Z*0.12)
            local spansOppositeSides=leftWing.center.Z>bodyBounds.center.Z+margin
                and rightWing.center.Z<bodyBounds.center.Z-margin
                and leftWing.max.Z>bodyBounds.max.Z+margin
                and rightWing.min.Z<bodyBounds.min.Z-margin
            local overlapsBody=math.min(leftWing.max.X,bodyBounds.max.X)-math.max(leftWing.min.X,bodyBounds.min.X)>0.02
                and math.min(leftWing.max.Y,bodyBounds.max.Y)-math.max(leftWing.min.Y,bodyBounds.min.Y)>0.02
                and math.min(leftWing.max.Z,bodyBounds.max.Z)-math.max(leftWing.min.Z,bodyBounds.min.Z)>0.02
                and math.min(rightWing.max.X,bodyBounds.max.X)-math.max(rightWing.min.X,bodyBounds.min.X)>0.02
                and math.min(rightWing.max.Y,bodyBounds.max.Y)-math.max(rightWing.min.Y,bodyBounds.min.Y)>0.02
                and math.min(rightWing.max.Z,bodyBounds.max.Z)-math.max(rightWing.min.Z,bodyBounds.min.Z)>0.02
            if not spansOppositeSides then
                table.insert(issues,"WINGS_NOT_BILATERAL: measured wings must extend from the body on opposite +Z/-Z flanks, not sit behind it as one hidden sheet.")
            elseif not overlapsBody then
                table.insert(issues,"WINGS_NOT_ATTACHED: wing bounds must overlap the torso in forward/up axes at the shoulder attachment.")
            else
                wingPair=true
            end
        end
    end
    local function plainBounds(bounds)
        if not bounds then return nil end
        return {center={x=bounds.center.X,y=bounds.center.Y,z=bounds.center.Z},size={x=bounds.size.X,y=bounds.size.Y,z=bounds.size.Z}}
    end
    return {
        bodyLoft={present=bodyNode~=nil,sections=bodySections,sides=bodySides,bounds=plainBounds(bodyBounds),crossSectionRatio=bodyDepthRatio},
        headLoft={present=headNode~=nil,sections=headSections,sides=headSides,bounds=plainBounds(headBounds),crossSectionRatio=headDepthRatio},
        eyePairBilateral=eyePair,pupils3D=pupils3D,
        faceOverlayCount=faceOverlayCount,wingPairBilateral=wingPair,
    },issues
end

-- Version 7.1.3: BAUQUALITAET MESSEN STATT BEHAUPTEN.
-- Ein Tier aus sieben Kugeln und ein Baum aus einem Zylinder plus einer Kugel
-- sind keine Modelle, sondern Entwuerfe. Diese Messung nennt sie beim Namen -
-- und prueft jeden Zylinder auf den klassischen 90-Grad-Drehfehler: die Achse
-- eines CylinderPart ist LOKAL X, Size.X ist also die Laenge.
WORLD_ENGINE.auditBuildQuality = function(parts, root)
    local counts = { parts = #parts, balls = 0, sphereMeshes = 0, blocks = 0, cylinders = 0, wedges = 0,
        meshes = 0, unions = 0, polygonParts = 0, polygonTriangles = 0, detailParts = 0 }
    local shapes = {}
    local kindOf = {}
    local solidOf = {}
    local colorCounts = {}
    local nearWhiteParts = 0
    local cylinderProblems, tiltedCylinders = {}, {}
    local cylinderProblemCount, tiltedCylinderCount = 0, 0
    local function isSolid(part, shapeName)
        if shapeName == "WedgePart" then return true end
        if part:IsA("MeshPart") or part:IsA("UnionOperation") or part:IsA("IntersectOperation") then return true end
        if part:GetAttribute("ArenaDetail") == true then return true end
        -- ArenaMasterBuild is a broad model marker, not proof of polygon geometry.
        -- Only the builder's per-wedge tag proves that real polygon triangles exist.
        if part:GetAttribute("ArenaPolygonTriangle") ~= nil then return true end
        if part:GetAttribute("ArenaPolygonSubmodel") == true or part:GetAttribute("ArenaAssembly") ~= nil then return true end
        if shapeName == "Wedge" then return true end
        return false
    end
    for _, part in ipairs(parts) do
        if part:IsA("MeshPart") then counts.meshes = counts.meshes + 1 end
        if part:IsA("UnionOperation") or part:IsA("IntersectOperation") then counts.unions = counts.unions + 1 end
        if part:IsA("WedgePart") then counts.wedges = counts.wedges + 1 end
        if part:GetAttribute("ArenaDetail") == true then counts.detailParts = counts.detailParts + 1 end
        if part:GetAttribute("ArenaMasterBuild") == true or part:GetAttribute("ArenaPolygonTriangle") ~= nil
            or part:GetAttribute("ArenaPolygonSubmodel") == true or part:GetAttribute("ArenaAssembly") ~= nil then
            counts.polygonParts = counts.polygonParts + 1
        end
        if part:GetAttribute("ArenaPolygonTriangle") ~= nil then counts.polygonTriangles = counts.polygonTriangles + 1 end
        local sphereMesh = false
        if part:IsA("Part") then
            local special = part:FindFirstChildOfClass("SpecialMesh")
            if special then
                pcall(function() sphereMesh = special.MeshType == Enum.MeshType.Sphere end)
                if sphereMesh then counts.sphereMeshes = counts.sphereMeshes + 1 end
            end
        end
        local color = part.Color
        local r = math.floor(color.R * 255 + 0.5)
        local g = math.floor(color.G * 255 + 0.5)
        local b = math.floor(color.B * 255 + 0.5)
        local colorKey = tostring(r) .. "," .. tostring(g) .. "," .. tostring(b)
        colorCounts[colorKey] = (colorCounts[colorKey] or 0) + 1
        local hi = math.max(color.R, color.G, color.B)
        local lo = math.min(color.R, color.G, color.B)
        if color.R >= 0.90 and color.G >= 0.90 and color.B >= 0.90 and (hi - lo) <= 0.08 then
            nearWhiteParts = nearWhiteParts + 1
        end
        local shapeName = nil
        pcall(function() shapeName = part.Shape.Name end)
        if shapeName then
            shapes[shapeName] = true
            if shapeName == "Ball" then counts.balls = counts.balls + 1 end
            if shapeName == "Block" then counts.blocks = counts.blocks + 1 end
        end
        if sphereMesh then kindOf[part] = "SphereMesh" else kindOf[part] = shapeName or part.ClassName end
        solidOf[part] = isSolid(part, shapeName)
        if shapeName == "Cylinder" then
            counts.cylinders = counts.cylinders + 1
            local size = part.Size
            local xAxis, yAxis = part.CFrame.RightVector, part.CFrame.UpVector
            local align = math.max(math.abs(xAxis.X), math.abs(xAxis.Y), math.abs(xAxis.Z))
            local axisSkewDeg = math.deg(math.acos(math.clamp(align, 0, 1)))
            local round = math.floor(axisSkewDeg * 10 + 0.5) / 10
            if math.abs(xAxis.Y) < 0.3 and math.max(size.Y, size.Z) >= 1.5 * size.X then
                cylinderProblemCount = cylinderProblemCount + 1
                if #cylinderProblems < 8 then
                    table.insert(cylinderProblems, {
                        id = idOf(part), path = part:GetFullName(), issue = "discLikeCylinder",
                        axisHorizontal = true, axisSkewDeg = round, size = { size.X, size.Y, size.Z },
                        hint = "A CylinderPart runs along its LOCAL X axis, so Size.X is the length. This one is wide across its round axis and its axis lies horizontally: it renders as a disc standing on its edge. If it should be a trunk, column, leg, tube or bone, build CFrame.Angles(0, 0, math.rad(90)) with Size = Vector3.new(length, diameter, diameter), or use cylinderBetween from organicBuildRules.",
                    })
                end
            elseif round > 5 then
                tiltedCylinderCount = tiltedCylinderCount + 1
                if #tiltedCylinders < 8 then
                    table.insert(tiltedCylinders, { id = idOf(part), path = part:GetFullName(),
                        axisSkewDeg = round, size = { size.X, size.Y, size.Z },
                        note = "The tube axis is not parallel to any world axis. Correct for a diagonal branch or strut, wrong for a trunk, column or upright leg." })
                end
            end
        end
    end
    local uniqueColors, dominantColorCount = 0, 0
    for _, amount in pairs(colorCounts) do
        uniqueColors = uniqueColors + 1
        if amount > dominantColorCount then dominantColorCount = amount end
    end
    local dominantColorShare = #parts > 0 and dominantColorCount / #parts or 0
    local nearWhiteShare = #parts > 0 and nearWhiteParts / #parts or 0

    -- Recognize and measure each organic model independently. Auditing the
    -- whole Workspace must never let an unrelated polygon, colour palette or
    -- animator make a primitive animal look complete.
    local function isOrganicModel(node)
        if not node or not node:IsA("Model") then return false end
        if node:GetAttribute("ArenaOrganicBuild") == true or node:GetAttribute("ArenaAnimal") == true then return true end
        local species = nil
        pcall(function() species = node:GetAttribute("Species") end)
        if species ~= nil and tostring(species) ~= "" then return true end
        local name = string.lower(node.Name)
        local words = { "wildlife", "animal", "animals", "creature", "creatures", "pet", "pets", "tier", "tiere", "kreatur", "katze", "hund", "fuchs", "wolf", "baer", "hirsch", "kaninchen", "eule", "schmetterling", "vogel", "pferd", "fisch", "schlange", "drache", "baum", "pflanze", "rabbit", "hare", "owl", "butterfly", "butterflies", "deer", "fox", "wolf", "cat", "dog", "bear", "horse", "bird", "fish", "snake", "dragon", "lion", "tiger", "otter", "squirrel", "frog", "turtle", "eagle", "hawk", "raven", "crow", "parrot", "penguin", "goat", "cow", "sheep", "pig", "duck", "chicken", "elephant", "giraffe", "zebra", "monkey", "ape", "gorilla", "dolphin", "whale", "shark", "seal", "panda", "koala", "badger", "mole", "beaver", "moose", "elk", "boar", "camel", "llama", "alpaca", "bison", "buffalo", "crab", "lobster", "octopus", "jellyfish", "spider", "snail", "bee", "wasp", "ant", "moth", "insect", "phoenix", "griffin", "unicorn", "monster", "dinosaur", "reptile", "amphibian", "tree", "plant" }
        for _, word in ipairs(words) do
            local atStart = string.sub(name, 1, #word) == word
            local atEnd = string.sub(name, -#word) == word
            local token = string.find(name, "%f[%w]" .. word .. "%f[^%w]") ~= nil
            if token or atStart or atEnd then return true end
        end
        return false
    end
    local candidates = {}
    local function addOrganicCandidate(node)
        if not isOrganicModel(node) then return end
        local ancestor = node.Parent
        while ancestor and ancestor ~= root.Parent do
            if isOrganicModel(ancestor) then return end
            ancestor = ancestor.Parent
        end
        table.insert(candidates, node)
    end
    addOrganicCandidate(root)
    local descendants = root:GetDescendants()
    for _, node in ipairs(descendants) do addOrganicCandidate(node) end

    local organicModels, organicIssues = {}, {}
    local organicPolygonTriangles, organicSphereMeshes, organicMotionScripts = 0, 0, 0
    local organicUniqueColors, organicDominantShare, organicNearWhiteShare = 0, 0, 0
    local organicScriptsScanned = 0
    for _, organicModel in ipairs(candidates) do
        local modelParts = collectParts(organicModel, {}, 8000)
        local modelColors, modelNearWhite = {}, 0
        local modelPolygonTriangles, modelSphereMeshes = 0, 0
        for _, part in ipairs(modelParts) do
            if part:GetAttribute("ArenaPolygonTriangle") ~= nil then modelPolygonTriangles = modelPolygonTriangles + 1 end
            local isSphereMesh = false
            if part:IsA("Part") then
                local special = part:FindFirstChildOfClass("SpecialMesh")
                if special then pcall(function() isSphereMesh = special.MeshType == Enum.MeshType.Sphere end) end
            end
            if isSphereMesh then modelSphereMeshes = modelSphereMeshes + 1 end
            local color = part.Color
            local r = math.floor(color.R * 255 + 0.5)
            local g = math.floor(color.G * 255 + 0.5)
            local b = math.floor(color.B * 255 + 0.5)
            local colorKey = tostring(r) .. "," .. tostring(g) .. "," .. tostring(b)
            modelColors[colorKey] = (modelColors[colorKey] or 0) + 1
            local hi = math.max(color.R, color.G, color.B)
            local lo = math.min(color.R, color.G, color.B)
            if color.R >= 0.90 and color.G >= 0.90 and color.B >= 0.90 and (hi - lo) <= 0.08 then
                modelNearWhite = modelNearWhite + 1
            end
        end
        local modelUniqueColors, modelDominantCount = 0, 0
        for _, amount in pairs(modelColors) do
            modelUniqueColors = modelUniqueColors + 1
            if amount > modelDominantCount then modelDominantCount = amount end
        end
        local modelDominantShare = #modelParts > 0 and modelDominantCount / #modelParts or 0
        local modelNearWhiteShare = #modelParts > 0 and modelNearWhite / #modelParts or 0

        local modelMotionScripts, modelScriptsScanned = 0, 0
        local function inspectMotionScript(node)
            if modelScriptsScanned >= 200 then return end
            if not (node:IsA("Script") or node:IsA("LocalScript")) then return end
            modelScriptsScanned = modelScriptsScanned + 1
            local disabled = false
            pcall(function() disabled = node.Disabled end)
            if disabled then return end
            local source = ""
            pcall(function() source = string.lower(node.Source) end)
            if source == "" then return end
            local loopEvidence = string.find(source, "heartbeat", 1, true) or string.find(source, "stepped", 1, true)
                or string.find(source, "tweenservice", 1, true) or string.find(source, "animationtrack", 1, true)
                or string.find(source, "motor6d", 1, true) or string.find(source, "renderstepped", 1, true)
            local motionEvidence = string.find(source, "cframe", 1, true) or string.find(source, "transform", 1, true)
                or string.find(source, "motor6d", 1, true) or string.find(source, "animationtrack", 1, true)
                or string.find(source, ":play(", 1, true) or string.find(source, "tween", 1, true)
            if loopEvidence and motionEvidence then modelMotionScripts = modelMotionScripts + 1 end
        end
        for _, node in ipairs(organicModel:GetDescendants()) do inspectMotionScript(node) end

        local modelIssues = {}
        local organicKind=""
        pcall(function() organicKind=string.lower(tostring(organicModel:GetAttribute("ArenaOrganicKind") or "")) end)
        local creatureMetrics=nil
        if organicKind=="" then
            table.insert(modelIssues,"ORGANIC_KIND_REQUIRED: declare organicKind=creature|plant|tree|prop|custom on the first organic build; model names do not substitute for the geometry contract.")
        elseif organicKind~="creature" and organicKind~="plant" and organicKind~="tree" and organicKind~="prop" and organicKind~="custom" then
            table.insert(modelIssues,"ORGANIC_KIND_INVALID: use creature, plant, tree, prop or custom.")
        elseif organicKind=="creature" then
            local creatureIssues=nil
            creatureMetrics,creatureIssues=WORLD_ENGINE.auditOrganicCreature(organicModel)
            for _,issue in ipairs(creatureIssues or {}) do table.insert(modelIssues,issue) end
        end
        if modelPolygonTriangles <= 0 then
            table.insert(modelIssues, "NO_POLYGON_GEOMETRY: build the silhouette with build_polygon_model { organic=true }; primitive parts or SpecialMesh spheres are not polygon modelling.")
        end
        if modelUniqueColors < 3 or modelDominantShare > 0.90 or modelNearWhiteShare > 0.90 then
            table.insert(modelIssues, "PALETTE_TOO_FLAT: assign explicit contrasting colours to the polygon submodels (back/body, belly, muzzle/paws and details); this model is uniform or at least 90% near-white.")
        end
        if modelMotionScripts <= 0 then
            table.insert(modelIssues, "ANIMATION_NOT_INSTALLED: add an enabled Script/LocalScript inside this model with real motion loops (breathing, head/limb/tail/wing); a generated source file outside Studio is not installed animation.")
        end
        for _, issue in ipairs(modelIssues) do
            table.insert(organicIssues, organicModel:GetFullName() .. ": " .. issue)
        end
        organicPolygonTriangles = organicPolygonTriangles + modelPolygonTriangles
        organicSphereMeshes = organicSphereMeshes + modelSphereMeshes
        organicMotionScripts = organicMotionScripts + modelMotionScripts
        organicScriptsScanned = organicScriptsScanned + modelScriptsScanned
        organicUniqueColors = organicUniqueColors + modelUniqueColors
        if modelDominantShare > organicDominantShare then organicDominantShare = modelDominantShare end
        if modelNearWhiteShare > organicNearWhiteShare then organicNearWhiteShare = modelNearWhiteShare end
        if #organicModels < 20 then
            table.insert(organicModels, {
                id = idOf(organicModel), name = organicModel.Name, path = organicModel:GetFullName(),
                organicKind = organicKind, creatureMetrics = creatureMetrics,
                parts = #modelParts, polygonTriangles = modelPolygonTriangles, sphereMeshes = modelSphereMeshes,
                uniqueColors = modelUniqueColors,
                dominantColorShare = math.floor(modelDominantShare * 100 + 0.5) / 100,
                nearWhiteShare = math.floor(modelNearWhiteShare * 100 + 0.5) / 100,
                motionScripts = modelMotionScripts, scriptsScanned = modelScriptsScanned,
                issues = modelIssues,
            })
        end
    end
    local organicQuality = {
        detected = (#candidates > 0),
        modelCount = #candidates,
        polygonTriangles = organicPolygonTriangles,
        sphereMeshes = organicSphereMeshes,
        uniqueColors = organicUniqueColors,
        dominantColorShare = math.floor(organicDominantShare * 100 + 0.5) / 100,
        nearWhiteShare = math.floor(organicNearWhiteShare * 100 + 0.5) / 100,
        motionScripts = organicMotionScripts,
        scriptsScanned = organicScriptsScanned,
        models = organicModels,
        issues = organicIssues,
    }

    local function topGroup(part)
        local node, parent = part, part.Parent
        while parent and parent ~= root do
            node = parent
            parent = node.Parent
        end
        if node == part then return nil end
        if node:IsA("Model") or node:IsA("Folder") then return node end
        return nil
    end
    local groups = {}
    local loose = { parts = 0, balls = 0, sphereMeshes = 0, solid = 0 }
    for _, part in ipairs(parts) do
        local group = topGroup(part)
        local entry = nil
        if group then
            entry = groups[group]
            if not entry then entry = { parts = 0, balls = 0, sphereMeshes = 0, solid = 0 }; groups[group] = entry end
        else
            entry = loose
        end
        entry.parts = entry.parts + 1
        if kindOf[part] == "Ball" then entry.balls = entry.balls + 1 end
        if kindOf[part] == "SphereMesh" then entry.sphereMeshes = entry.sphereMeshes + 1 end
        if solidOf[part] then entry.solid = entry.solid + 1 end
    end
    local primitiveGroups = {}
    local function judge(entry, name, path)
        local sphereCount = entry.balls + entry.sphereMeshes
        if entry.parts >= 6 and sphereCount >= 6 and sphereCount >= 0.5 * entry.parts and entry.solid == 0 then
            if #primitiveGroups < 5 then
                table.insert(primitiveGroups, { name = name, path = path, parts = entry.parts, balls = entry.balls,
                    sphereMeshes = entry.sphereMeshes, sphereShare = math.floor((sphereCount / entry.parts) * 100 + 0.5) / 100,
                    detailParts = 0 })
            end
            return true
        end
        return false
    end
    local groupOrder = {}
    for group in pairs(groups) do table.insert(groupOrder, group) end
    table.sort(groupOrder, function(a, b) return a:GetFullName() < b:GetFullName() end)
    for _, group in ipairs(groupOrder) do judge(groups[group], group.Name, group:GetFullName()) end
    if loose.parts >= 6 then judge(loose, "loose parts", root:GetFullName() .. " (directly)") end
    local variety = 0
    for _ in pairs(shapes) do variety = variety + 1 end
    local ballShare = 0
    -- Version 7.2.0: FERTIG-GRAD STATT NUR "KEIN FEHLER GEFUNDEN".
    -- Ein Baum aus zwei Zylindern und drei Kugeln war bis 7.1.5 "clean", weil
    -- die Pruefung nur extreme Faelle kannte (mindestens 6 Teile, davon
    -- mindestens 6 Kugeln). Jetzt wird gezaehlt und benotet: Teilzahl, echte
    -- Gestaltung (Polygon/Mesh/Union/Detail), Formenvielfalt, Farbvielfalt -
    -- abzueglich der gemessenen Fehler. Note 'draft' faengt genau den Fall des
    -- Owners ab: wenige Teile, keine Gestaltung, fast alles primitive.
    local declaredGrade = nil
    pcall(function() declaredGrade = root:GetAttribute("ArenaDeclaredGrade") end)
    if declaredGrade == nil then
        for _, part in ipairs(parts) do
            local value = nil
            pcall(function() value = part:GetAttribute("ArenaDeclaredGrade") end)
            if value ~= nil then declaredGrade = value break end
        end
    end
    if declaredGrade ~= nil then declaredGrade = string.lower(tostring(declaredGrade)) end
    if declaredGrade ~= "simple" and declaredGrade ~= "lowpoly" and declaredGrade ~= "blockout" and declaredGrade ~= "detailed" then
        declaredGrade = nil
    end
    local colorVariety = 0
    for _ in pairs(colorCounts) do colorVariety = colorVariety + 1 end
    local intentional = counts.meshes + counts.unions + counts.polygonParts + counts.detailParts
    local primitiveShare = 0
    if #parts > 0 then primitiveShare = math.floor(((#parts - math.min(intentional, #parts)) / #parts) * 100 + 0.5) / 100 end
    local finishScore = 0
    if #parts >= 4 then finishScore = finishScore + 10 end
    if #parts >= 12 then finishScore = finishScore + 10 end
    if #parts >= 30 then finishScore = finishScore + 10 end
    if counts.polygonParts > 0 then finishScore = finishScore + 20 end
    if counts.meshes > 0 then finishScore = finishScore + 10 end
    if counts.unions > 0 then finishScore = finishScore + 5 end
    if counts.detailParts > 0 then finishScore = finishScore + 15 end
    if counts.wedges > 0 then finishScore = finishScore + 5 end
    finishScore = finishScore + math.min(10, 5 * math.max(0, variety - 1))
    finishScore = finishScore + math.min(10, 5 * math.max(0, colorVariety - 1))
    finishScore = finishScore - math.min(12, 3 * #primitiveGroups)
    finishScore = finishScore - math.min(9, 3 * cylinderProblemCount)
    if finishScore < 0 then finishScore = 0 end
    if finishScore > 100 then finishScore = 100 end
    local grade = "simple"
    if finishScore >= 85 then grade = "sculpted"
    elseif finishScore >= 60 then grade = "detailed"
    elseif finishScore >= 35 then grade = "simple" end
    local draftRisk = false
    if #parts >= 4 and intentional == 0 and primitiveShare > 0.6 then
        grade = "draft"
        draftRisk = true
    end
    if declaredGrade ~= nil then
        grade = declaredGrade
        draftRisk = false
    end
    if #parts > 0 then ballShare = math.floor((counts.balls / #parts) * 100 + 0.5) / 100 end
    local verdict = "clean"
    if #primitiveGroups > 0 and cylinderProblemCount > 0 then verdict = "primitive_abuse_and_cylinder_rotation"
    elseif #primitiveGroups > 0 then verdict = "primitive_abuse"
    elseif cylinderProblemCount > 0 then verdict = "cylinder_rotation"
    elseif #organicIssues > 0 then verdict = "organic_build_incomplete" end
    local advice = "Clean: the geometry is varied and no cylinder looks rotated wrong."
    if verdict == "primitive_abuse" then
        advice = "Rebuild the flagged group as a silhouette with build_polygon_model (tapering volumes, limb segments, joints, detail) - see organicBuildRules. Primitive-only groups are drafts, not models."
    elseif verdict == "cylinder_rotation" then
        advice = "The flagged cylinders stand as discs because their tube axis lies horizontally and the length sits in Size.Y or Size.Z. Rebuild them with CFrame.Angles(0, 0, math.rad(90)) and Size = Vector3.new(length, diameter, diameter), or use cylinderBetween from organicBuildRules."
    elseif verdict == "primitive_abuse_and_cylinder_rotation" then
        advice = "Two independent defects: primitive-only groups AND wrongly rotated cylinders. Fix both (organicBuildRules has the anatomy contract and the cylinder helpers), then run model_audit again."
    elseif #organicIssues > 0 then
        advice = table.concat(organicIssues, " ")
    end
    return {
        counts = counts,
        shapeVariety = variety,
        ballShare = ballShare,
        -- Version 7.2.0: dieselbe Messung, aber als Note statt nur als Urteil.
        finishScore = finishScore,
        grade = grade,
        declaredGrade = declaredGrade,
        draftRisk = draftRisk,
        primitiveShare = primitiveShare,
        intentionalParts = intentional,
        colorVariety = colorVariety,
        primitiveOnly = (#primitiveGroups > 0),
        primitiveGroups = primitiveGroups,
        cylinderProblems = cylinderProblems,
        cylinderProblemCount = cylinderProblemCount,
        tiltedCylinders = tiltedCylinders,
        tiltedCylinderCount = tiltedCylinderCount,
        organicQuality = organicQuality,
        verdict = verdict,
        advice = advice,
    }
end


tools.model_audit = function(args)
    local root, err = targetFrom(args, false)
    if not root then
        if args.ref ~= nil then return failCode("REF_NOT_FOUND", err) end
        root = workspace
    end
    local parts = collectParts(root, {}, 8000)
    local placeholders, blockouts, meshes, unions, untextured, named = {}, {}, 0, 0, 0, 0
    local meshSlots = {}
    local materials = {}
    for _, part in ipairs(parts) do
        if part:IsA("MeshPart") then meshes = meshes + 1 end
        if part:IsA("UnionOperation") or part:IsA("IntersectOperation") then unions = unions + 1 end
        -- Version 7.4.0: Mesh-Platzhalter des Blender-Wegs sind EIGENE Klasse.
        -- Sie warten auf den Upload des Nutzers (ArenaMeshSlot) und werden
        -- darum nicht als vergessene Platzhalter gezaehlt - report_done
        -- antwortet fuer sie mit MESH_UPLOAD_PENDING.
        local meshKey = part:GetAttribute("ArenaMeshSlot")
        if meshKey ~= nil then
            table.insert(meshSlots, {
                id = idOf(part),
                path = part:GetFullName(),
                name = part.Name,
                key = tostring(meshKey),
                state = tostring(part:GetAttribute("ArenaMeshState") or ""),
                assetId = tostring(part:GetAttribute("ArenaMeshAssetId") or ""),
            })
        end
        local isPlaceholder, why = isPlaceholderPart(part)
        if isPlaceholder and meshKey == nil then
            table.insert(placeholders, { id = idOf(part), path = part:GetFullName(), name = part.Name, why = why })
        elseif meshKey == nil then
            local blockout, colorHex = isBlockoutPart(part)
            if blockout then table.insert(blockouts, { id = idOf(part), path = part:GetFullName(), color = colorHex }) end
        end
        if part.Name ~= string.gsub(part.ClassName, "^", "") and not isPlaceholderName(part.Name) then named = named + 1 end
        local matName = "Unknown"
        pcall(function() matName = part.Material.Name end)
        materials[matName] = (materials[matName] or 0) + 1
        if part:IsA("BasePart") and part:FindFirstChildOfClass("Decal") == nil and part:IsA("Part") then untextured = untextured + 1 end
    end
    -- Version 7.1.3: Bauqualitaet messen (Kugel-Gruppen, Zylinder-Achsen).
    local quality = WORLD_ENGINE.auditBuildQuality(parts, root)
    local qualityWarnings = {}
    if quality.primitiveOnly then
        table.insert(qualityWarnings, "PRIMITIVE_ONLY_BUILD: " .. tostring(#quality.primitiveGroups)
            .. " group(s) consist only of Ball parts (no polygon, assembly, mesh, union or ArenaDetail part). That is a draft, not a model - rebuild the silhouette with build_polygon_model and follow organicBuildRules. report_done answers DETAIL_REQUIRED until this is fixed or honestly handed off.")
    end
    if quality.cylinderProblemCount > 0 then
        table.insert(qualityWarnings, "CYLINDER_ROTATION: " .. tostring(quality.cylinderProblemCount)
            .. " cylinder(s) have a horizontal axis while being far wider across their round axis than long - they stand as discs on their edge instead of forming a tube. That is the classic 90-degree error: the length was typed into Size.Y or Size.Z. A CylinderPart runs along its LOCAL X axis (Size.X = length): use CFrame.Angles(0, 0, math.rad(90)) with Size = Vector3.new(length, diameter, diameter), or cylinderBetween from organicBuildRules.")
    end
    if quality.tiltedCylinderCount > 0 then
        table.insert(qualityWarnings, "CYLINDER_TILT (info): " .. tostring(quality.tiltedCylinderCount)
            .. " cylinder(s) are not parallel to any world axis. Fine for diagonal branches and struts, wrong for trunks, columns and upright legs.")
    end
    if quality.organicQuality and #quality.organicQuality.issues > 0 then
        table.insert(qualityWarnings, "ORGANIC_BUILD_INCOMPLETE: " .. table.concat(quality.organicQuality.issues, " "))
    end
    if quality.draftRisk then
        table.insert(qualityWarnings, "DRAFT_GRADE_RISK (grade '" .. tostring(quality.grade) .. "', " .. tostring(quality.finishScore)
            .. "/100): " .. tostring(#parts) .. " part(s), davon " .. tostring(quality.intentionalParts)
            .. " gestaltete(s) (Polygon/Mesh/Union/ArenaDetail), Primitive-Anteil " .. tostring(math.floor(quality.primitiveShare * 100 + 0.5))
            .. "%. Das ist ein Entwurf, kein Modell. Baue die Silhouette mit build_polygon_model und echten Details nach (organicBuildRules/modelBuildRules) - oder erklaere die Einfachheit AUSDRUECKLICH beim Bauen (grade = \"simple\"/\"lowpoly\"/\"blockout\"), wenn sie so gewollt ist. report_done antwortet bis dahin DRAFT_GRADE_RISK.")
    end
    local phase, verdict
    if #placeholders > 0 then
        phase, verdict = "blockout", "NOT done: " .. tostring(#placeholders) .. " placeholder(s) are still in the place."
    elseif #blockouts > 0 then
        phase, verdict = "blockout", "Blockout: " .. tostring(#blockouts) .. " part(s) still carry the default grey plastic look."
    elseif quality.primitiveOnly then
        phase, verdict = "modelled", "NOT done: the build is primitive-only (" .. tostring(#quality.primitiveGroups) .. " ball-only group(s), no polygon/assembly/mesh/detail part)."
    elseif quality.cylinderProblemCount > 0 then
        phase, verdict = "modelled", "NOT done: " .. tostring(quality.cylinderProblemCount) .. " cylinder(s) stand as discs on their edge - the axis lies horizontally because the length was typed into Size.Y or Size.Z instead of Size.X."
    elseif quality.organicQuality and #quality.organicQuality.issues > 0 then
        phase, verdict = "modelled", "NOT done: organic build quality is incomplete - " .. table.concat(quality.organicQuality.issues, " ")
    elseif quality.draftRisk then
        phase, verdict = "modelled", "Draft (grade '" .. tostring(quality.grade) .. "', " .. tostring(quality.finishScore) .. "/100): " .. tostring(#parts) .. " part(s) without polygon, mesh, union or detail geometry. Rebuild it with real structure or declare the intended simplicity with the grade argument."

    elseif meshes + unions + quality.counts.polygonParts == 0 then
        phase, verdict = "modelled", "Modelled, but nothing is a mesh, union or polygon model - check whether detail is missing."
    elseif quality.counts.detailParts > 0 then
        phase, verdict = "refined", "Clean: detailed geometry (ArenaDetail parts) and no placeholders, blockouts or measured build defects."
    else
        phase, verdict = "modelled", "Clean: no placeholders, blockouts or measured build defects found in the checked scope."
    end
    local nextStep = "Run world_audit for style/lighting, then continue."
    if #meshSlots > 0 then
        nextStep = tostring(#meshSlots) .. " mesh placeholder(s) wait for the user: he uploads the OBJ file(s) to Roblox and enters the mesh id(s) in the bridge window \"Mesh-Uploads\" (or tells you the id so you call mesh_apply_asset). report_done answers MESH_UPLOAD_PENDING until then - be honest about that."
    elseif (#placeholders + #blockouts) > 0 then
        nextStep = "refine the flagged parts or replace them, then run model_audit again."
    elseif quality.primitiveOnly or quality.cylinderProblemCount > 0 or quality.draftRisk or (quality.organicQuality and #quality.organicQuality.issues > 0) then
        nextStep = quality.advice
    end
    return ok({
        scope = root:GetFullName(),
        parts = #parts,
        placeholderCount = #placeholders,
        placeholders = placeholders,
        meshSlotCount = #meshSlots,
        meshSlots = meshSlots,
        blockoutCount = #blockouts,
        blockoutExamples = { blockouts[1], blockouts[2], blockouts[3] },
        meshes = meshes,
        unions = unions,
        namedParts = named,
        materials = materials,
        phase = phase,
        verdict = verdict,
        buildQuality = quality,
        primitiveAbuse = quality.primitiveOnly,
        cylinderProblemCount = quality.cylinderProblemCount,
        nextStep = nextStep,
    }, qualityWarnings)
end

tools.world_audit = function(args)
    local parts = collectParts(workspace, {}, 8000)
    local lights, lightKinds = 0, {}
    local hasAtmosphere, hasSky, hasClouds = false, false, false
    local collections = {}
    pcall(function() collections = game:GetService("CollectionService"):GetAllTags() end)
    for _, child in ipairs(workspace:GetDescendants()) do
        if child:IsA("Light") then
            lights = lights + 1
            lightKinds[child.ClassName] = (lightKinds[child.ClassName] or 0) + 1
        elseif child:IsA("Atmosphere") then hasAtmosphere = true
        elseif child:IsA("Sky") then hasSky = true
        elseif child:IsA("Clouds") then hasClouds = true end
    end
    local offStyle, details = {}, 0
    local styleLocked = (worldStyle and worldStyle.locked) or false
    for _, part in ipairs(parts) do
        if part:GetAttribute("ArenaDetail") == true then details = details + 1 end
        if styleLocked then
            local _, dist = nearestPalette(worldStyle, part.Color)
            local matName = "Unknown"
            pcall(function() matName = part.Material.Name end)
            local allowed = false
            for _, mat in ipairs((worldStyle or {}).materials or {}) do
                if mat == matName then allowed = true break end
            end
            if (not allowed) and dist and dist > 60 then
                if #offStyle < 20 then table.insert(offStyle, { id = idOf(part), path = part:GetFullName(), color = hexOf(part.Color), material = matName, paletteDistance = math.floor(dist) }) end
            end
        end
    end
    local styleCompliance = 1
    if styleLocked and #parts > 0 then styleCompliance = math.floor((1 - #offStyle / #parts) * 1000) / 1000 end
    local phase = "modelled"
    if details > 0 then phase = "refined" end
    if details > 0 and lights > 0 and (hasAtmosphere or hasSky) then phase = "polished" end
    local issues = {}
    if not styleLocked then table.insert(issues, "No style lock: call world_style + style_lock so audits can measure compliance.") end
    if lights == 0 then table.insert(issues, "No Light in the place: geometry alone cannot carry a mood.") end
    if not hasAtmosphere and not hasSky then table.insert(issues, "Neither Atmosphere nor Sky exists - the sky is the default blue.") end
    if #offStyle > 0 then table.insert(issues, tostring(#offStyle) .. " part(s) are outside the locked style (colour distance > 60 or material not in the list).") end
    return ok({
        scope = "game.Workspace",
        parts = #parts,
        lights = lights,
        lightKinds = lightKinds,
        atmosphere = hasAtmosphere,
        sky = hasSky,
        clouds = hasClouds,
        tags = collections,
        styleLocked = styleLocked,
        stylePreset = (worldStyle and worldStyle.preset) or nil,
        styleCompliance = styleCompliance,
        offStyleParts = offStyle,
        detailParts = details,
        phase = phase,
        verdict = (#issues == 0) and "Polished: style, light and detail are consistent." or ("Open points: " .. table.concat(issues, " ")),
        issues = issues,
    })
end

tools.refine = function(args)
    local root, err = targetFrom(args, true)
    if not root then
        return failCode(args.ref == nil and "BAD_ARGS" or "REF_NOT_FOUND",
            err or "refine needs ref or useSelection=true.",
            { hint = "refine { useSelection=true } works on the Studio selection." })
    end
    local seed = math.floor(tonumber(args.seed) or (worldStyle and worldStyle.seed) or 1)
    local maxParts = math.clamp(math.floor(tonumber(args.maxParts) or 24), 1, 200)
    local parts = collectParts(root, {}, 2000)
    table.sort(parts, function(a, b)
        local av = a.Size.X * a.Size.Y * a.Size.Z
        local bv = b.Size.X * b.Size.Y * b.Size.Z
        return av > bv
    end)
    local style = worldStyle or WORLD_ENGINE.PRESETS.coastal
    local palette = stylePaletteList(style)
    local trimColor = palette[#palette] or Color3.fromRGB(120, 120, 120)
    local added, touched = 0, 0
    for index, part in ipairs(parts) do
        if added >= maxParts then break end
        if part:IsA("BasePart") and not part:GetAttribute("ArenaDetail") then
            local top = part.CFrame * CFrame.new(0, part.Size.Y / 2, 0)
            local thickness = math.clamp(part.Size.Y * 0.06, 0.05, 0.35)
            local along = "X"
            local length = part.Size.X
            if part.Size.Z > part.Size.X then along = "Z" length = part.Size.Z end
            local trim = Instance.new("Part")
            trim.Name = "ArenaDetail_Trim"
            trim.Size = along == "X" and Vector3.new(length * 0.92, thickness, thickness) or Vector3.new(thickness, thickness, length * 0.92)
            trim.CFrame = top
            trim.Color = trimColor
            pcall(function() trim.Material = Enum.Material[(style.materials or {})[1] or "Wood"] end)
            trim.Anchored = part.Anchored
            trim:SetAttribute("ArenaDetail", true)
            trim:SetAttribute("ArenaRefineSeed", seed)
            trim.Parent = part.Parent
            if not part.Anchored then
                local weld = Instance.new("WeldConstraint")
                weld.Part0 = part
                weld.Part1 = trim
                weld.Parent = trim
            end
            added = added + 1
            touched = touched + 1
        end
    end
    waypoint("refine " .. root.Name)
    return ok({
        scope = root:GetFullName(),
        seed = seed,
        partsChecked = #parts,
        partsTouched = touched,
        detailsAdded = added,
        maxParts = maxParts,
        stoppedBecause = added >= maxParts and "maxParts reached - call refine again with a higher maxParts if the model needs more." or nil,
        stylePreset = (worldStyle and worldStyle.preset) or nil,
        nextStep = "model_audit now counts ArenaDetail parts; world_audit rates the phase.",
    })
end

tools.world_glow = function(args)
    -- Glow gehoert der Engine: EINE Lampe + optional Neon, nie eine
    -- handgebaute Kette aus Ball-Teilen mit Transparency-Stufen.
    local target, err = targetFrom(args, true)
    if not target then
        return failCode(args.ref == nil and "BAD_ARGS" or "REF_NOT_FOUND",
            err or "world_glow needs ref or useSelection=true.",
            { hint = "world_glow { ref=\"game.Workspace.Lampe\" } or select the part and use useSelection=true." })
    end
    if not target:IsA("BasePart") then
        return failCode("BAD_ARGS", "world_glow works on a BasePart (the light is parented to it), not on " .. target.ClassName .. ".")
    end
    local style = worldStyle or WORLD_ENGINE.PRESETS.coastal
    local palette = stylePaletteList(style)
    local color = UI_ENGINE and UI_ENGINE.col(args.color, palette[#palette] or Color3.fromRGB(255, 214, 140)) or Color3.fromRGB(255, 214, 140)
    local lightClass = tostring(args.lightClass or "PointLight")
    if lightClass ~= "PointLight" and lightClass ~= "SpotLight" and lightClass ~= "SurfaceLight" then
        return failCode("BAD_ARGS", "lightClass must be PointLight, SpotLight or SurfaceLight.")
    end
    local light = target:FindFirstChildOfClass(lightClass)
    if not light then
        light = Instance.new(lightClass)
        light.Parent = target
    end
    light.Color = color
    light.Brightness = math.clamp(tonumber(args.brightness) or 2, 0, 10)
    if lightClass == "PointLight" or lightClass == "SurfaceLight" then
        pcall(function() light.Range = math.clamp(tonumber(args.range) or 18, 1, 60) end)
    end
    if args.neon == true then
        pcall(function() target.Material = Enum.Material.Neon end)
    end
    target:SetAttribute("ArenaGlow", true)
    target:SetAttribute("ArenaGlowColor", "#" .. color:ToHex())
    waypoint("world glow")
    return ok({
        engine = WORLD_ENGINE.VERSION,
        target = target:GetFullName(),
        lightClass = lightClass,
        color = color:ToHex(),
        brightness = light.Brightness,
        material = (function() local name = "unknown"; pcall(function() name = target.Material.Name end) return name end)(),
        stylePreset = (worldStyle and worldStyle.preset) or nil,
        note = "one engine-built light per part; tone down with brightness instead of stacking more lights",
    })
end

local function toolNames()
    local names = {}
    for name, _ in pairs(tools) do table.insert(names, name) end
    table.sort(names)
    return names
end

tools.list_tools = function()
    return ok({ tools = toolNames(), count = #toolNames(), pluginVersion = ARENA_VERSION })
end

tools.batch = function(args)
    local commands = args.commands or args.items or {}
    local parallel = args.parallel == true
    local stopOnError = args.stopOnError == true
    local results = {}

    if parallel then
        local finished = 0
        local total = #commands
        for index, item in ipairs(commands) do
            task.spawn(function()
                local okRun, result = pcall(function()
                    return executeTool(item.tool, item.args or {}, true)
                end)
                if okRun then
                    results[index] = result
                else
                    results[index] = { ok = false, error = tostring(result) }
                end
                finished = finished + 1
            end)
        end
        local waited = 0
        local limit = tonumber(args.timeoutSeconds) or 90
        while finished < total and waited < limit do
            task.wait(0.05)
            waited = waited + 0.05
        end
        local list = {}
        for index = 1, total do
            list[index] = results[index] or { ok = false, error = "Timed out inside the batch." }
        end
        local failures = 0
        for _, item in ipairs(list) do
            if item.ok ~= true then failures = failures + 1 end
        end
        return ok({ results = list, count = #list, failed = failures, mode = "parallel" })
    end

    local failures = 0
    for index, item in ipairs(commands) do
        local okRun, result = pcall(function()
            return executeTool(item.tool, item.args or {}, true)
        end)
        if not okRun then
            result = { ok = false, error = tostring(result) }
        end
        results[index] = result
        if result.ok ~= true then
            failures = failures + 1
            if stopOnError then
                return ok({ results = results, count = #results, failed = failures, stoppedAt = index, mode = "sequential" })
            end
        end
    end
    return ok({ results = results, count = #results, failed = failures, mode = "sequential" })
end

tools.parallel = function(args)
    local copy = {}
    for key, value in pairs(args) do copy[key] = value end
    copy.parallel = true
    return tools.batch(copy)
end

executeTool = function(tool, args, insideBatch)
    args = args or {}
    -- Enforce the limitation here as well as at the desktop HTTP boundary so
    -- batch, parallel and start_job cannot bypass the disabled sim_start.
    if tool == "sim_start" then
        return simDisabledResult()
    end
    local handler = tools[tool]
    if handler == nil then
        return failCode("UNKNOWN_TOOL", "Unknown tool: " .. tostring(tool), {
            hint = "Call list_tools to see everything this bridge can do.",
        })
    end

    if accessMode == "readonly" and WRITE_TOOLS[tool] then
        return failCode("READONLY_TOKEN", "This place is in read-only mode (switched in the Arena Roblox Bridge app).")
    end

    local warnings = nil
    -- 3.9.7: the persistent-edit block uses the same session oracle as every
    -- play tool (editModeActive=false IS a running test, B4 of the live test).
    if testSessionActive() and PERSISTENT_WRITE_TOOLS[tool] then
        if userPlaytestActive then
            return failCode("USER_PLAYTEST_ACTIVE",
                "IMPORTANT: The user started and is using a playtest right now. STOP your current response and do not edit anything: changes during a test would be temporary and could disrupt the user.", {
                assistantAction = "STOP_OR_YIELD",
                howToFix = "The playtest is the user's, and the bridge cannot stop it for you. Either end your response and ask the user to stop the test (or to let you work in peace), or keep working with read-only tools. NEVER claim the changes were saved.",
                userMessage = "Ich sehe, dass du Roblox Studio gerade selbst testest. Parallel kann ich nicht sicher bauen. Beende den Test bitte selbst (Shift+F5) oder sag mir Bescheid, wenn ich in Ruhe weiterarbeiten darf.",
                state = playState(),
            })
        elseif args.allowInSimMode ~= true then
            return failCode("SIM_RUNNING",
                "A Studio Run session is active. '" .. tostring(tool)
                .. "' would change the place, but every change made during the simulation is thrown away when it stops.", {
                howToFix = "Call sim_stop to leave an existing bridge-owned session, then do the real work in Edit mode. sim_start is disabled; test live behavior manually in Studio.",
                state = playState(),
            })
        end
        warnings = { "allowInSimMode was used: this change only exists during the running simulation and disappears when it stops." }
    end

    local okRun, result = xpcall(function()
        return handler(args)
    end, debug.traceback)
    if not okRun then
        local trace = tostring(result)
        result = failCode("RUNTIME_ERROR", "Tool crashed: " .. trace, {
            traceback = trace,
            tool = tostring(tool),
        })
    end
    if type(result) ~= "table" then
        result = { ok = true, result = result }
    end
    -- SCHWEIGENDER FEHLER WIRD ZUM FEHLER: eine Antwort ohne ok, ohne Ergebnis
    -- und ohne Fehler ist kein gueltiges Antwort - die KI muss es merken.
    if result.ok == nil and result.error == nil then
        local isEmpty = true
        for _ in pairs(result) do isEmpty = false break end
        if isEmpty then
            result = failCode("RUNTIME_ERROR",
                "Tool '" .. tostring(tool) .. "' returned an empty answer (no result, no error). Check get_errors / get_output for what happened.")
        else
            result.ok = true
        end
    end
    if warnings then
        result.warnings = result.warnings or {}
        for _, warning in ipairs(warnings) do table.insert(result.warnings, warning) end
    end

    if not insideBatch then
        result.studio = playState()
        local pending = takeNotices()
        if #pending > 0 then
            result.notices = pending
        end
    end
    return result
end

-- ---------------------------------------------------------------------------
-- ERGEBNISSE ZURUECKSCHICKEN (grosse Daten in Stuecken)
-- ---------------------------------------------------------------------------
local function postResult(commandId, payload)
    local okEncode, json = pcall(function()
        return HttpService:JSONEncode(payload)
    end)
    if not okEncode then
        json = HttpService:JSONEncode({
            ok = false,
            code = "RUNTIME_ERROR",
            error = "Result could not be encoded: " .. tostring(json),
            commandId = tostring(commandId),
        })
    end

    local function sendResultPart(partPayload)
        for attempt = 1, 3 do
            local response = post("/plugin/result", partPayload)
            if response and response.ok == true then return true end
            if attempt < 3 then task.wait(0.2 * attempt) end
        end
        return false
    end

    if #json <= ARENA_CFG.CHUNK_SIZE then
        return sendResultPart({ sessionId = sessionId, commandId = commandId, json = json })
    end

    local total = math.ceil(#json / ARENA_CFG.CHUNK_SIZE)
    for index = 1, total do
        local from = (index - 1) * ARENA_CFG.CHUNK_SIZE + 1
        local piece = string.sub(json, from, from + ARENA_CFG.CHUNK_SIZE - 1)
        local sent = sendResultPart({
            sessionId = sessionId,
            commandId = commandId,
            chunkIndex = index,
            chunkCount = total,
            chunk = piece,
            totalBytes = #json,
        })
        if not sent then return false end
    end
    return true
end

local function handleCommand(command)
    if command == nil or command.id == nil then
        return failCode("RUNTIME_ERROR", "The bridge delivered a command without commandId.")
    end
    local startedAt = os.clock()
    local result
    local args = command.args
    if type(args) ~= "table" then args = {} end
    -- Waehrend eines Bridge-Befehls keine user_active-Meldungen ausloesen.
    bridgeCommandActive = true
    if args.asJob == true and command.tool ~= "start_job" then
        local okJob, jobId = xpcall(function()
            return newJob(command.tool, function(job)
                local jobArgs = {}
                for key, value in pairs(args) do jobArgs[key] = value end
                jobArgs._job = { progress = job.progress, cancelled = job.cancelled }
                return executeTool(command.tool, jobArgs, true)
            end)
        end, debug.traceback)
        if not okJob then
            local trace = tostring(jobId)
            result = failCode("RUNTIME_ERROR", "Could not start job: " .. trace, { traceback = trace })
        else
            result = ok({
                jobId = jobId,
                status = "running",
                note = "This command runs in the background - it survives any timeout. Poll with job_status { jobId: '" .. tostring(jobId) .. "' } and fetch the result later with job_result.",
            })
        end
    else
        local okRun, value = xpcall(function()
            return executeTool(command.tool, args, false)
        end, debug.traceback)
        if not okRun then
            local trace = tostring(value)
            value = failCode("RUNTIME_ERROR", "Command crashed: " .. trace, {
                traceback = trace,
                tool = tostring(command.tool),
                commandId = tostring(command.id),
            })
        end
        result = value
    end
    if type(result) ~= "table" then result = { ok = true, result = result } end
    result.commandId = tostring(command.id)
    result.durationSeconds = math.floor((os.clock() - startedAt) * 1000) / 1000
    bridgeCommandActive = false
    return result
end

local function commandStateRequest(command, phase)
    local resp = post("/plugin/command_state", {
        sessionId = sessionId,
        commandId = command and command.id or nil,
        tool = command and command.tool or nil,
        phase = phase,
    })
    if type(resp) == "table" and resp.ok == true then
        executorState.lastAckAt = os.time()
    end
    return resp
end

-- Version 7.1.0: Einheitliche Zustellung fuer Empfangsbestaetigungen (Ack-Outbox)
-- und Befehls-Ergebnisse (Result-Outbox). Beide liegen als Methoden auf
-- executorState, damit im Haupt-Chunk keine weiteren top-level Locals verbraucht
-- werden (Luau-Grenze: 200 Register).
executorState.sendOrQueueAckBatch = function(commandIds)
    if type(commandIds) ~= "table" or #commandIds == 0 then return true end
    local batch = {}
    for _, rawId in ipairs(commandIds) do
        local cid = tostring(rawId or "")
        if cid ~= "" then
            table.insert(batch, cid)
            if executorState.ackOutbox[cid] == nil then
                executorState.ackOutbox[cid] = {
                    commandId = cid,
                    phase = "received_batch",
                    nextTry = os.clock() + 1,
                    backoff = 1,
                    attempts = 0,
                }
            end
        end
    end
    if #batch == 0 then return true end
    if not sessionId then return false end
    local okSend, ackResp = pcall(post, "/plugin/command_state", {
        sessionId = sessionId,
        phase = "received_batch",
        commandIds = batch,
    })
    if okSend and type(ackResp) == "table" and ackResp.ok == true and ackResp.accepted ~= false then
        executorState.lastAckAt = os.time()
        for _, cid in ipairs(batch) do
            executorState.ackOutbox[cid] = nil
        end
        return true
    end
    local nowClock = os.clock()
    for _, cid in ipairs(batch) do
        local entry = executorState.ackOutbox[cid]
        if entry then
            entry.attempts = (tonumber(entry.attempts) or 0) + 1
            local backoff = math.min(tonumber(entry.backoff) or 1, 15)
            entry.nextTry = nowClock + backoff
            entry.backoff = math.min(backoff * 2, 15)
        end
    end
    return false
end

executorState.deliverOrQueueResult = function(commandId, resultPayload)
    local cid = tostring(commandId or "")
    if cid == "" then return false end
    if type(resultPayload) ~= "table" then
        resultPayload = failCode("RUNTIME_ERROR", tostring(resultPayload), { commandId = cid })
    end
    resultPayload.commandId = cid
    rememberCompletedResult(cid, resultPayload)
    executorState.ackOutbox[cid] = nil
    local sendOk, delivered = pcall(postResult, cid, resultPayload)
    if sendOk and delivered == true then
        executorState.lastAckAt = os.time()
        executorState.resultOutbox[cid] = nil
        return true
    end
    executorState.resultOutbox[cid] = {
        payload = resultPayload,
        nextTry = os.clock() + 2,
        backoff = 2,
    }
    return false
end

local function pumpCommandQueue()
    if executorState.dispatcherBusy or not running then return end
    executorState.dispatcherBusy = true
    task.spawn(function()
        local loopOk, loopError = xpcall(function()
            while running and #commandQueue > 0 do
                local nextCommand = table.remove(commandQueue, 1)
                executorState.queueDepth = #commandQueue
                if nextCommand and nextCommand.id then
                    local commandId = tostring(nextCommand.id)
                    local budget = tonumber(nextCommand.budgetSeconds) or 90
                    budget = math.clamp(budget, 5, 300)
                    -- Publish the command as locally dispatched before the
                    -- start acknowledgement; if that POST is lost, the server
                    -- can reconcile from its next independent executor snapshot.
                    executorState.runningCommandId = commandId
                    executorState.runningTool = tostring(nextCommand.tool or "unknown")
                    executorState.startedAt = os.time()
                    local startAck = commandStateRequest(nextCommand, "started")
                    if startAck and type(startAck) == "table" then
                        executorState.ackOutbox[commandId] = nil
                    end
                    if startAck and startAck.accepted == false and startAck.cancelled == true then
                        cancelRequests[commandId] = nil
                        if startAck.state ~= "finished" then
                            local cancelledEarly = failCode("COMMAND_CANCELLED", "The command was cancelled or already closed on the bridge before execution started.", { commandId = commandId })
                            executorState.deliverOrQueueResult(commandId, cancelledEarly)
                        end
                        executorState.runningCommandId = nil
                        executorState.runningTool = nil
                        executorState.startedAt = 0
                    elseif cancelRequests[commandId] then
                        cancelRequests[commandId] = nil
                        local cancelled = failCode("COMMAND_CANCELLED", "The command was cancelled before execution.", { commandId = commandId })
                        executorState.deliverOrQueueResult(commandId, cancelled)
                        executorState.runningCommandId = nil
                        executorState.runningTool = nil
                        executorState.startedAt = 0
                    else
                        local commandFinished = false
                        local commandResult = nil
                        local commandThread = task.spawn(function()
                            local okRun, value = xpcall(function()
                                return handleCommand(nextCommand)
                            end, debug.traceback)
                            if okRun then
                                commandResult = value
                            else
                                local trace = tostring(value)
                                commandResult = failCode("RUNTIME_ERROR", "Executor caught an unhandled command error: " .. trace, {
                                    traceback = trace,
                                    tool = tostring(nextCommand.tool),
                                    commandId = commandId,
                                })
                            end
                            commandFinished = true
                        end)
                        executorState.commandThread = commandThread
                        local heartbeatActive = true
                        local heartbeatThread = task.spawn(function()
                            while heartbeatActive and not commandFinished and running do
                                task.wait(5)
                                if not heartbeatActive or commandFinished or not running then break end
                                local beat = commandStateRequest(nextCommand, "heartbeat")
                                if beat and beat.cancelled == true then cancelRequests[commandId] = true end
                            end
                        end)
                        executorState.heartbeatThread = heartbeatThread
                        local startedClock = os.clock()
                        local timedOut = false
                        while not commandFinished and running do
                            executorState.lastTick = os.time()
                            local elapsed = os.clock() - startedClock
                            if cancelRequests[commandId] == true then
                                timedOut = true
                                pcall(task.cancel, commandThread)
                                pcall(commandStateRequest, nextCommand, "cancel_ack")
                                commandResult = failCode("COMMAND_CANCELLED", "The running command was cancelled by the bridge.", {
                                    commandId = commandId,
                                    tool = tostring(nextCommand.tool),
                                })
                                break
                            elseif elapsed >= budget then
                                timedOut = true
                                pcall(task.cancel, commandThread)
                                commandResult = failCode("STUDIO_ABANDONED", "The command exceeded its safety budget and was stopped so the Studio queue can continue. Inspect the Place before retrying; partial changes may have occurred.", {
                                    commandId = commandId,
                                    tool = tostring(nextCommand.tool),
                                    budgetSeconds = budget,
                                    ranFor = math.floor(elapsed * 10) / 10,
                                })
                                break
                            end
                            task.wait(0.2)
                        end
                        heartbeatActive = false
                        pcall(task.cancel, heartbeatThread)
                        executorState.commandThread = nil
                        executorState.heartbeatThread = nil
                        bridgeCommandActive = false
                        cancelRequests[commandId] = nil
                        if timedOut then commandFinished = true end
                        commandResult = commandResult or failCode("RUNTIME_ERROR", "Executor ended without a result.", { commandId = commandId })
                        commandResult.commandId = commandId
                        rememberCompletedResult(commandId, commandResult)
                        executorState.deliverOrQueueResult(commandId, commandResult)
                        executorState.runningCommandId = nil
                        executorState.runningTool = nil
                        executorState.startedAt = 0
                        executorState.lastTick = os.time()
                        setWidgetStatus()
                    end
                end
            end
        end, debug.traceback)

        if not loopOk then
            bridgeCommandActive = false
            local failedId = executorState.runningCommandId
            if failedId then
                pcall(task.cancel, executorState.commandThread)
                pcall(task.cancel, executorState.heartbeatThread)
                local trace = tostring(loopError)
                local failure = failCode("RUNTIME_ERROR", "Executor loop recovered from an error: " .. trace, {
                    traceback = trace,
                    commandId = failedId,
                    tool = executorState.runningTool,
                    partialChangesPossible = true,
                })
                executorState.deliverOrQueueResult(failedId, failure)
            end
            executorState.commandThread = nil
            executorState.heartbeatThread = nil
            executorState.runningCommandId = nil
            executorState.runningTool = nil
            executorState.startedAt = 0
        end
        executorState.dispatcherBusy = false
        executorState.queueDepth = #commandQueue
        executorState.lastTick = os.time()
        if running and #commandQueue > 0 then task.defer(pumpCommandQueue) end
    end)
end

local function enqueueCommand(command)
    if type(command) ~= "table" or command.id == nil or tostring(command.id) == "" then
        pluginOutputError("Ungueltiger Befehl ohne commandId empfangen.")
        return false
    end
    local commandId = tostring(command.id)
    -- Version 7.1.0: Empfang sicherstellen, falls enqueueCommand einzeln gerufen wird.
    if executorState.ackOutbox[commandId] ~= nil then
        executorState.sendOrQueueAckBatch({ commandId })
    end
    if command.tool == nil or tostring(command.tool) == "" then
        local invalidRes = failCode("INVALID_COMMAND", "Der empfangene Befehl enthaelt keinen gueltigen Tool-Namen (tool fehlt).", {
            commandId = commandId,
        })
        executorState.deliverOrQueueResult(commandId, invalidRes)
        return false
    end
    local cached = completedResults[commandId]
    if cached ~= nil then
        seenCommandIds[commandId] = os.time()
        task.spawn(function()
            local okSend, delivered = pcall(postResult, commandId, cached)
            if not okSend or delivered ~= true then
                executorState.deliverOrQueueResult(commandId, cached)
            end
        end)
        return true
    end
    if seenCommandIds[commandId] then
        -- Bereits gesehen, aber noch kein fertiges Ergebnis: pruefen, ob der
        -- Befehl gerade laeuft oder noch in der lokalen Warteschlange liegt.
        if executorState.runningCommandId == commandId then
            task.spawn(function()
                pcall(commandStateRequest, command, "heartbeat")
            end)
            return true
        end
        for _, queuedCmd in ipairs(commandQueue) do
            if type(queuedCmd) == "table" and tostring(queuedCmd.id or "") == commandId then
                return true
            end
        end
        -- Weder fertig noch laufend noch in der Queue -> erneut einreihen,
        -- damit kein Befehl jemals stillschweigend ohne Antwort bleibt!
    end
    seenCommandIds[commandId] = os.time()
    local seenCount = 0
    local oldestId = nil
    local oldestAt = math.huge
    for id, at in pairs(seenCommandIds) do
        seenCount = seenCount + 1
        if at < oldestAt then oldestAt = at; oldestId = id end
    end
    if seenCount > 256 and oldestId then seenCommandIds[oldestId] = nil end
    table.insert(commandQueue, command)
    executorState.queueDepth = #commandQueue
    pumpCommandQueue()
    return true
end

-- Executor liveness is deliberately independent from the connection/poll loop.
task.spawn(function()
    while running do
        executorState.lastTick = os.time()
        executorState.queueDepth = #commandQueue
        task.wait(1)
    end
end)

-- Version 7.1.0: Sowohl Empfangsbestaetigungen (ackOutbox) als auch fertige
-- Ergebnisse (resultOutbox) werden im Hintergrund mit exponentiellem Backoff
-- nachgeliefert, bis die Bridge den Erhalt bestaetigt.
task.spawn(function()
    while running do
        if sessionId then
            local dueAckIds = {}
            local nowClock = os.clock()
            for cid, ackItem in pairs(executorState.ackOutbox) do
                if nowClock >= (tonumber(ackItem.nextTry) or 0) then
                    table.insert(dueAckIds, cid)
                end
            end
            if #dueAckIds > 0 then
                executorState.sendOrQueueAckBatch(dueAckIds)
            end
        end
        for commandId, item in pairs(executorState.resultOutbox) do
            if os.clock() >= (tonumber(item.nextTry) or 0) and sessionId then
                local okSend, delivered = pcall(postResult, commandId, item.payload)
                if okSend and delivered == true then
                    executorState.lastAckAt = os.time()
                    executorState.resultOutbox[commandId] = nil
                else
                    local backoff = math.min(tonumber(item.backoff) or 2, 30)
                    item.nextTry = os.clock() + backoff
                    item.backoff = math.min(backoff * 2, 30)
                end
                break
            end
        end
        task.wait(1)
    end
end)

-- ---------------------------------------------------------------------------
-- VERBINDUNG
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 4.0.1 SESSION-REPORTER (Plugin-Instanz IM Test-DataModel)
-- Diese Instanz registriert sich NICHT als Place. Sie meldet stattdessen
-- Spieler/Charakter an die bestehende Sitzung und fuehrt Befehle aus, die
-- ausschliesslich hier funktionieren - allen voran EndTest (automatischer
-- Stop) und LeaveTest.
-- ---------------------------------------------------------------------------

local function statePayload()
    -- Version 7.1.1: sessionId (seit 7.0.0 verloren) und gameId wieder im
    -- Poll-/Heartbeat-Payload. Ohne sessionId kannte Update-Session die
    -- Sitzung nie: jeder Poll lief als "Reconnect" (reconnects+1, Lesemodus
    -- zurueckgesetzt), der Ersatz-Heartbeat meldete "Sitzung unbekannt".
    local payload = {
        instanceGuid = instanceGuid,
        sessionId = sessionId,
        placeId = tostring(game.PlaceId),
        placeName = tostring(game.Name),
        mode = currentMode(),
        context = currentContext(),
        capabilities = capabilities,
        pluginVersion = ARENA_VERSION,
    }
    pcall(function() payload.gameId = tostring(game.GameId) end)
    local okState, stateValue = pcall(playState)
    if okState then payload.state = stateValue end
    local queuedCommandIds = {}
    for _, queuedCommand in ipairs(commandQueue) do
        if queuedCommand and queuedCommand.id then table.insert(queuedCommandIds, tostring(queuedCommand.id)) end
    end
    local outboxCount = 0
    for _ in pairs(executorState.resultOutbox) do outboxCount = outboxCount + 1 end
    local ackOutboxCount = 0
    for _ in pairs(executorState.ackOutbox) do ackOutboxCount = ackOutboxCount + 1 end
    local completedCount = 0
    for _ in pairs(completedResults) do completedCount = completedCount + 1 end
    payload.executor = {
        lastTick = executorState.lastTick,
        runningCommandId = executorState.runningCommandId,
        runningTool = executorState.runningTool,
        startedAt = executorState.startedAt,
        queueDepth = #commandQueue,
        queuedCommandIds = queuedCommandIds,
        dispatcherBusy = executorState.dispatcherBusy,
        resultOutbox = outboxCount,
        ackOutbox = ackOutboxCount,
        cachedResults = completedCount,
        lastAckAt = executorState.lastAckAt,
        lastPollError = lastPollError,
        lastPluginError = lastPluginErrorText,
    }
    return payload
end

local function handshake()
    local payload = statePayload()
    payload.capabilities = capabilities
    local response = post("/plugin/hello", payload)
    if response and response.sessionId then
        sessionId = response.sessionId
        accessMode = response.accessMode or "readwrite"
        -- 7.0.0: keine Reporter mehr - die Sitzung gehoert nur noch dieser
        -- Plugin-Instanz. Kein SetSetting ueber DataModel-Grenzen.
        if response.pluginOutdated then
            pluginOutdated = true
            title.Text = "Arena Bridge: Studio neu starten"
            pluginOutputError('Plugin-Version ' .. tostring(ARENA_VERSION) .. ' passt nicht zur Bridge (erwartet ' .. tostring(response.docsVersion) .. '). Roblox Studio einmal KOMPLETT schliessen und neu oeffnen - ein laufendes Studio behaelt das alte Plugin im Speicher.')
        end
        setWidgetStatus('verbunden')
        connected = true
        -- Version 7.1.0: Nach einem Reconnect sofort offene Empfangsbestaetigungen
        -- und Ergebnisse aus den Ausgangskoerben nachliefern.
        task.spawn(function()
            local pendingAckIds = {}
            for cid in pairs(executorState.ackOutbox) do
                table.insert(pendingAckIds, cid)
            end
            if #pendingAckIds > 0 then
                executorState.sendOrQueueAckBatch(pendingAckIds)
            end
            for commandId, item in pairs(executorState.resultOutbox) do
                local okSend, delivered = pcall(postResult, commandId, item.payload)
                if okSend and delivered == true then
                    executorState.lastAckAt = os.time()
                    executorState.resultOutbox[commandId] = nil
                end
            end
        end)
        return true
    end
    connected = false
    return false
end

-- Zustandswaechter: unterscheidet Studio Run von player Play/F5 anhand des
-- RunService-Modus. Nur Play/F5 ist USER_PLAYTEST_ACTIVE; ein user-gestartetes
-- Studio Run wird separat als SIM_RUNNING behandelt. Es gibt keine Start- oder
-- Stop-Steuerung fuer user-eigene Tests.
task.spawn(function()
    local lastActive = testSessionActive()
    while running do
        -- Version 7.0.2: idle state/camera polling is a background fallback;
        -- selection changes still report immediately through their event.
        task.wait(1.5)
        local activeNow = testSessionActive()
        if not activeNow then
            local cam = Workspace.CurrentCamera
            if cam ~= nil then
                local camPos = cam.CFrame.Position
                if lastEditCamPos ~= nil and os.clock() - lastUserActiveNotice >= 25 and bridgeCommandActive == false then
                    local moved = (camPos - lastEditCamPos).Magnitude
                    if moved > 6 then
                        lastUserActiveNotice = os.clock()
                        addNotice("user_active",
                            "The USER is currently moving around in Roblox Studio themselves (edit camera moved). This is NOT you and NOT a bug. Expect changes you did not make - re-read objects before overwriting them and coordinate in chat.",
                            { kind = "camera", movedStuds = math.floor(moved * 10) / 10 })
                    end
                end
                lastEditCamPos = camPos
                lastEditCamCFrame = cam.CFrame
            end
        end
        if activeNow ~= lastActive then
            local byAi = (os.time() - (aiPlayIntent.at or 0)) <= 25
            local who = byAi and "assistant" or "user"
            if activeNow then
                local mode = currentMode()
                if mode == "edit" or mode == "paused" then mode = "unknown" end
                userPlaytestActive = (mode == "play" and not byAi)
                if byAi then simStartedByBridge = true end
                addNotice("sim_started",
                    "A Studio test session is active in " .. mode .. " mode - started by the " .. who .. ". mode='run' is official Studio Run without a player/client; mode='play' is a separate player Play/F5 test. Studio has left Edit mode, so persistent changes are temporary.",
                    { mode = mode, startedBy = who, playerCount = currentPlayerCount() })
            else
                userPlaytestActive = false
                simStartedByBridge = false
                simStartedAt = 0
                addNotice("sim_stopped",
                    "The Studio Run simulation was stopped by the " .. who .. ". Studio is back in edit mode - this is NOT a crash and nothing went wrong.",
                    { stoppedBy = who })
            end
            aiPlayIntent = { action = nil, at = 0 }
            lastActive = activeNow
        end
    end
end)

-- Version 3.8: Der Nutzer klickt etwas im Studio an (Auswahl geaendert)?
-- Im Edit-Modus ist das ein sicheres Zeichen, dass der Nutzer SELBST gerade
-- am Place arbeitet - die KI soll das wissen, statt unsanft uebereinander
-- zu arbeiten. Eigene Bridge-Befehle (select_instance usw.) zaehlen nicht.
Selection.SelectionChanged:Connect(function()
    if running ~= true then return end
    if RunService:IsRunning() then return end
    if bridgeCommandActive then return end
    if os.clock() - lastUserActiveNotice < 20 then return end
    lastUserActiveNotice = os.clock()
    task.spawn(function()
        addNotice("user_active",
            "The USER is actively working in Roblox Studio right now (they changed the selection). This is NOT you and NOT a bug. Expect changes you did not make - re-read objects before overwriting and coordinate in chat.",
            { kind = "selection" })
    end)
end)

-- Version 7.0.3: KEIN eigener 5-Sekunden-Heartbeat mehr.
-- Der Poll unten frischt die Sitzung bei JEDER Anfrage selbst auf
-- (Update-Session auf der Bridge-Seite), also war der zweite Dauerkanal
-- doppelte Last. Der Heartbeat existiert nur noch als Rueckfall im Poll:
-- nur wenn laenger als HEARTBEAT_FALLBACK Sekunden kein Poll durchkam.
task.spawn(function()
    if isSessionDataModel then return end
    while running do
        if sessionId ~= nil and os.clock() - lastHeartbeat > ARENA_CFG.HEARTBEAT_FALLBACK then
            lastHeartbeat = os.clock()
            perfStats.hbFallback = perfStats.hbFallback + 1
            local response = post("/plugin/heartbeat", statePayload())
            if response then
                if response.unknownSession == true then
                    -- Version 7.1.1: Kennt die Bridge die Instanz noch, kommt die
                    -- gueltige sessionId mit - uebernehmen statt neu anmelden.
                    if type(response.sessionId) == "string" and response.sessionId ~= "" then
                        sessionId = response.sessionId
                    else
                        sessionId = nil
                    end
                elseif response.accessMode then
                    accessMode = response.accessMode
                end
            end
        end
        task.wait(2)
    end
end)

-- Befehls- und Lebenszeichen-Kanal (Long-Poll).
-- Version 7.0.0: Im Test-DataModel laeuft KEIN Reporter mehr; die Instanz
-- meldet sich dort gar nicht erst an (kein zweites Place, kein Zombie).
-- Version 7.0.3: Der Poll ist jetzt KURZ und laesst nach jeder Anfrage eine
-- Pause, damit Studio seinen HTTP-Platz zurueckbekommt (siehe ARENA_CFG).
-- Im Ruhezustand waechst die Pause; kommt ein Befehl, geht es sofort wieder
-- auf "aktiv", damit Arena-Aufrufe schnell bleiben.
task.spawn(function()
    local sessionDm = isSessionDataModel
    if sessionDm ~= true then
        local isEdit = true
        pcall(function() isEdit = RunService:IsEdit() end)
        if isEdit == false then sessionDm = true end
    end
    if sessionDm then
        widget.Enabled = false
        return
    end
    local backoff = 0.5
    local emptyPolls = 0
    local quiet = false
    while running do
        -- FIX 7.0.8: Der Poll ist der einzige Kanal, der Befehle ausliefert UND
        -- die Sitzung auf der Bridge frisch haelt. Ein einziger unerwarteter
        -- Fehler beendete diese Aufgabe frueher STILL: danach kam nie wieder
        -- ein Poll, die Sitzung alterte auf der Bridge, die Place-Zeile
        -- verschwand - und Arena wartete endlos auf eine Antwort. Jetzt wird
        -- der Fehler sichtbar gemacht und die Schleife laeuft weiter.
        local loopOk, loopErr = xpcall(function()
        if sessionId == nil then
            if handshake() then
                backoff = 0.5
                lastHeartbeat = os.clock()
                if connectedEventSessionId ~= sessionId then
                    connectedEventSessionId = sessionId
                    addNotice("connected", "Bridge connected. Place '" .. tostring(game.Name) .. "' is ready.", { placeId = game.PlaceId })
                end
            else
                task.wait(backoff)
                backoff = math.min(backoff * 1.6, 5)
            end
        else
            local waitSeconds = ARENA_CFG.POLL_WAIT_ACTIVE
            local gapSeconds = ARENA_CFG.POLL_GAP_ACTIVE
            if quiet then
                waitSeconds = ARENA_CFG.POLL_WAIT_QUIET
                gapSeconds = ARENA_CFG.POLL_GAP_QUIET
            end
            local payload = statePayload()
            payload.wait = waitSeconds
            if perfWanted then payload.perf = perfReport() end
            local started = os.clock()
            local response = post("/plugin/poll", payload)
            if response ~= nil then
                lastPollOkAt = os.clock()
                lastPollError = ''
            else
                lastPollError = 'keine Antwort'
                pluginOutputError('Poll-Anfrage an die Bridge ohne Antwort. Laeuft die Bridge und ist der Tunnel erreichbar?')
            end
            local pollMs = math.floor((os.clock() - started) * 1000)
            perfStats.polls = perfStats.polls + 1
            perfStats.waitMs = perfStats.waitMs + math.floor(waitSeconds * 1000)
            perfStats.pollMs = perfStats.pollMs + pollMs
            local delivered = 0
            if response == nil then
                task.wait(0.5)
            elseif response.unknownSession == true then
                -- Version 7.0.6: Die Bridge ist die Autoritaet fuer Identitaet.
                -- Kennt sie diese Instanz noch, schickt sie die gueltige
                -- sessionId mit - das Plugin uebernimmt sie, statt seine
                -- Sitzung zu verwerfen. Genau das beendet den
                -- "Bridge connected"-Sturm alle 2 Sekunden.
                if response.sessionId ~= nil and tostring(response.sessionId) ~= "" then
                    sessionId = tostring(response.sessionId)
                    lastPollOkAt = os.clock()
                    lastPollError = ''
                    quiet = false
                    emptyPolls = 0
                    backoff = 0.5
                    setWidgetStatus('gleiche Sitzung uebernommen')
                else
                    sessionId = nil
                    lastPollError = 'Sitzung unbekannt'
                    quiet = false
                    emptyPolls = 0
                    pluginOutputError('Die Bridge kennt diese Sitzung nicht mehr. Studio neu oeffnen; die Bridge vergibt fuer dieselbe Instanz wieder dieselbe Sitzung.')
                    task.wait(backoff)
                    backoff = math.min(backoff * 1.6, 5)
                end
            else
                backoff = 0.5
                lastHeartbeat = os.clock()
                -- Version 7.1.1: Die Bridge nennt in jeder Poll-Antwort die
                -- gueltige sessionId der Instanz; eine abweichende eigene
                -- Kennung wird still uebernommen (Ergebnisse landen richtig).
                if type(response.sessionId) == "string" and response.sessionId ~= "" and response.sessionId ~= sessionId then
                    sessionId = response.sessionId
                end
                if response.accessMode then accessMode = response.accessMode end
                perfWanted = (response.perf == true)
                if response.cancelledCommands ~= nil then
                    local cancelList = type(response.cancelledCommands) == "table" and response.cancelledCommands
                        or (type(response.cancelledCommands) == "string" and response.cancelledCommands ~= "" and { response.cancelledCommands } or {})
                    for _, commandId in ipairs(cancelList) do
                        local cancelledId = tostring(commandId)
                        cancelRequests[cancelledId] = true
                        executorState.ackOutbox[cancelledId] = nil
                        pcall(post, "/plugin/command_state", {
                            sessionId = sessionId,
                            commandId = cancelledId,
                            phase = "cancel_ack",
                        })
                    end
                end
                if response.resetExecutor == true then
                    commandQueue = {}
                    executorState.ackOutbox = {}
                    if executorState.runningCommandId then
                        cancelRequests[tostring(executorState.runningCommandId)] = true
                    end
                    pcall(post, "/plugin/command_state", { sessionId = sessionId, phase = "reset_ack" })
                end
                if response.commands ~= nil and response.resetExecutor ~= true then
                    local cmdList = type(response.commands) == "table" and response.commands or {}
                    local receivedIds = {}
                    for _, command in ipairs(cmdList) do
                        if type(command) == "table" and command.id ~= nil and tostring(command.id) ~= "" then
                            table.insert(receivedIds, tostring(command.id))
                        end
                    end
                    -- Version 7.1.0: Empfang VOR dem Einreihen bestaetigen (und bei
                    -- Fehlern ueber die Ack-Outbox nachliefern), damit kein Befehl
                    -- nach 30 s als COMMAND_DELIVERY_UNCONFIRMED stirbt.
                    if #receivedIds > 0 then
                        executorState.sendOrQueueAckBatch(receivedIds)
                    end
                    for _, command in ipairs(cmdList) do
                        delivered = delivered + 1
                        lastToolName = tostring(type(command) == "table" and command.tool or '?')
                        enqueueCommand(command)
                    end
                elseif response.command ~= nil and response.resetExecutor ~= true then
                    delivered = 1
                    if type(response.command) == "table" and response.command.id ~= nil then
                        executorState.sendOrQueueAckBatch({ tostring(response.command.id) })
                    end
                    enqueueCommand(response.command)
                end
            end
            if delivered > 0 then
                perfStats.cmds = perfStats.cmds + delivered
                pluginCmdCount = pluginCmdCount + delivered
                emptyPolls = 0
                quiet = false
            else
                emptyPolls = emptyPolls + 1
                if emptyPolls >= ARENA_CFG.QUIET_AFTER_POLLS then quiet = true end
            end
            perfStats.quiet = quiet
            setWidgetStatus()
            -- PFLICHT-PAUSE: zwischen zwei Anfragen ist der HTTP-Platz frei.
            task.wait(gapSeconds)
            perfStats.gapMs = perfStats.gapMs + math.floor(gapSeconds * 1000)
        end
        end, debug.traceback)
        if not loopOk then
            local loopDetail = tostring(loopErr)
            lastPollError = 'Poll-Fehler: ' .. loopDetail
            pluginOutputError('Die Poll-Schleife hat einen Fehler abgefangen und laeuft weiter: ' .. loopDetail)
            pcall(setWidgetStatus)
            task.wait(1)
        end
    end
end)

game:GetPropertyChangedSignal("Name"):Connect(function()
    lastHeartbeat = 0
end)

plugin.Unloading:Connect(function()
    running = false
    if sessionId then
        post("/plugin/disconnect", { sessionId = sessionId, reason = "unloading" })
    end
end)

'@
}


function Install-RobloxPlugin {
    $pluginDir = Join-Path $env:LOCALAPPDATA 'Roblox\Plugins'
    New-Item -ItemType Directory -Path $pluginDir -Force | Out-Null
    $pluginPath = Join-Path $pluginDir 'ArenaStudioBridge.lua'
    $source = (Get-PluginSource).Replace('__BASE_URL__', $script:LocalBaseUrl)
    [System.IO.File]::WriteAllText($pluginPath, $source, [System.Text.UTF8Encoding]::new($false))
    $script:PluginInstalled = Test-Path $pluginPath
    return $pluginPath
}

function Test-PortAvailable {
    param([int]$Port)
    try {
        $listener = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Parse('127.0.0.1'), $Port)
        $listener.Start()
        $listener.Stop()
        return $true
    } catch {
        return $false
    }
}

function Test-PortListening {
    param([int]$Port)
    $client = $null
    try {
        $client = [System.Net.Sockets.TcpClient]::new()
        $client.Connect('127.0.0.1', $Port)
        return $client.Connected
    } catch {
        return $false
    } finally {
        if ($client) {
            try { $client.Close() } catch {}
        }
    }
}

# ----------------------------------------------------------------------------
# PORT AUTOMATISCH FREIGEBEN (Version 3.4, repariert in 3.5)
# Ist der lokale Port schon belegt (z.B. eine alte Bridge-Instanz, die noch
# im Hintergrund laeuft), wird der Verursacher gesucht und automatisch
# beendet. Systemkritische Prozesse werden nie angeruehrt.
#
# WICHTIG (Grund fuer den 3.5-Bugfix): Der HTTP-Server der Bridge nutzt
# http.sys - Windows zeigt dafuer im Port-Table PID 4 (System) an, NICHT den
# echten Verursacher. Und auf deutschen Windows heisst der netstat-Status
# "ABHOEREN" statt "LISTENING". Deshalb werden andere Arena-Bridge-Prozesse
# ZUSAETZLICH ueber den Prozessnamen erkannt:
#   1) EXE-Modus: andere Prozesse mit dem gleichen Namen wie dieser Prozess
#      (z.B. weitere ArenaBridge.exe)
#   2) Skript-Modus: PowerShell-Prozesse, die ArenaBridge.ps1 ausfuehren
# Das findet die Geister-Instanz auch dann, wenn der Port-Table nur
# "System" verraet.
# ----------------------------------------------------------------------------
function Get-PortOwnerPids {
    param([int]$Port)
    $owners = New-Object 'System.Collections.Generic.HashSet[int]'
    try {
        $connections = @(Get-NetTCPConnection -LocalPort $Port -ErrorAction SilentlyContinue)
        foreach ($connection in $connections) {
            if ($connection.OwningProcess) { [void]$owners.Add([int]$connection.OwningProcess) }
        }
    } catch {}
    if ($owners.Count -eq 0) {
        # Fallback ohne NetTCPIP-Modul: netstat-Ausgabe auswerten.
        # Der Status wird BEWUSST nicht gefiltert: netstat ist lokalisiert
        # (deutsch: "ABHOEREN" statt "LISTENING").
        try {
            $netstatLines = @(netstat.exe -ano -p tcp 2>$null)
            foreach ($netstatLine in $netstatLines) {
                $text = ([string]$netstatLine).Trim()
                if ($text -match ('^TCP\s+\S+:' + $Port + '\s+\S+\s+\S+\s+(\d+)$')) {
                    [void]$owners.Add([int]$matches[1])
                }
            }
        } catch {}
    }
    return @($owners)
}

function Get-BridgeGhostProcesses {
    # Findet ANDERE Arena-Bridge-Instanzen (nie den eigenen Prozess):
    #  1) Prozesse mit gleichem Namen wie dieser Prozess (EXE-Modus) -
    #     ausser der Name ist ein generischer wie powershell/pwsh.
    #  2) PowerShell-Prozesse mit ArenaBridge.ps1 in der Befehlszeile.
    $ghosts = New-Object 'System.Collections.Generic.HashSet[int]'
    try {
        $myName = (Get-Process -Id $PID -ErrorAction Stop).Name
        if ($myName -and $myName -notmatch '^(powershell|pwsh|cmd|conhost|wscript|cscript)') {
            foreach ($p in @(Get-Process -Name $myName -ErrorAction SilentlyContinue)) {
                if ($p.Id -ne $PID) { [void]$ghosts.Add([int]$p.Id) }
            }
        }
    } catch {}
    try {
        $candidates = @()
        try {
            $candidates = @(Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" -ErrorAction SilentlyContinue)
        } catch {}
        if ($candidates.Count -eq 0) {
            try { $candidates = @(Get-WmiObject Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" -ErrorAction SilentlyContinue) } catch {}
        }
        foreach ($candidate in $candidates) {
            if ([int]$candidate.ProcessId -eq $PID) { continue }
            if ([string]$candidate.CommandLine -match 'ArenaBridge\.ps1') {
                [void]$ghosts.Add([int]$candidate.ProcessId)
            }
        }
    } catch {}
    return @($ghosts)
}

function Stop-ProcessSafe {
    param([int]$TargetPid, [string]$Reason)
    if ($TargetPid -eq $PID -or $TargetPid -le 4) { return $false }
    try {
        $proc = Get-Process -Id $TargetPid -ErrorAction Stop
        $procName = [string]$proc.Name
        $protected = @('system','idle','registry','smss','csrss','wininit','winlogon','services','lsass','svchost','fontdrvhost','dwm','explorer','conhost','dllhost','sihost','taskhostw','ctfmon')
        if ($protected -contains $procName.ToLowerInvariant()) {
            Write-RuntimeLog "Free-Port: '$procName' (PID $TargetPid) ist systemkritisch und wird NICHT beendet ($Reason)."
            return $false
        }
        Write-RuntimeLog "Free-Port: Beende Prozess '$procName' (PID $TargetPid) - $Reason."
        Stop-Process -Id $TargetPid -Force -ErrorAction Stop
        return $true
    } catch {
        Write-RuntimeLog "Free-Port: Prozess $TargetPid konnte nicht beendet werden: $($_.Exception.Message)"
        return $false
    }
}

function Free-Port {
    param([int]$Port)
    Write-RuntimeLog "Free-Port: Port $Port ist belegt - Verursacher werden gesucht ..."

    # Welle 1: Port-Besitzer (ausser System) + andere Bridge-Instanzen beenden
    $ownerPids = Get-PortOwnerPids -Port $Port
    $ghostPids = Get-BridgeGhostProcesses
    foreach ($ownerPid in $ownerPids) {
        if ($ownerPid -le 4) {
            Write-RuntimeLog "Free-Port: Port $Port wird von PID $ownerPid (System/http.sys) gehalten - der echte Verursacher wird ueber den Prozessnamen gesucht."
            continue
        }
        [void](Stop-ProcessSafe -TargetPid $ownerPid -Reason "haelt Port $Port")
    }
    foreach ($ghostPid in $ghostPids) {
        [void](Stop-ProcessSafe -TargetPid $ghostPid -Reason 'andere Arena-Bridge-Instanz')
    }

    $deadline = (Get-Date).AddSeconds(8)
    while ((Get-Date) -lt $deadline) {
        if (Test-PortAvailable -Port $Port) {
            Write-RuntimeLog "Free-Port: Port $Port ist jetzt frei."
            return $true
        }
        Start-Sleep -Milliseconds 250
    }

    # Welle 2: nochmals scannen (Prozesse koennen dazwischen neu gestartet sein)
    Write-RuntimeLog "Free-Port: Port $Port immer noch belegt - zweite Runde."
    foreach ($ownerPid in (Get-PortOwnerPids -Port $Port)) {
        if ($ownerPid -gt 4) { [void](Stop-ProcessSafe -TargetPid $ownerPid -Reason "haelt Port $Port (2. Versuch)") }
    }
    foreach ($ghostPid in (Get-BridgeGhostProcesses)) {
        [void](Stop-ProcessSafe -TargetPid $ghostPid -Reason 'andere Arena-Bridge-Instanz (2. Versuch)')
    }

    $deadline2 = (Get-Date).AddSeconds(5)
    while ((Get-Date) -lt $deadline2) {
        if (Test-PortAvailable -Port $Port) {
            Write-RuntimeLog "Free-Port: Port $Port ist nach der zweiten Runde frei."
            return $true
        }
        Start-Sleep -Milliseconds 250
    }

    # Immer noch belegt: genaue Diagnose ins Protokoll schreiben
    $finalOwners = Get-PortOwnerPids -Port $Port
    foreach ($finalOwner in $finalOwners) {
        $procName = '(unbekannt)'
        try { $procName = (Get-Process -Id $finalOwner -ErrorAction Stop).Name } catch {}
        Write-RuntimeLog "Free-Port: Port $Port wird weiterhin von '$procName' (PID $finalOwner) gehalten."
    }
    if ($finalOwners.Count -eq 0) {
        Write-RuntimeLog "Free-Port: Kein Besitzer ermittelbar (moeglicherweise http.sys/System)."
    }
    return $false
}

# ----------------------------------------------------------------------------
# Hilfstyp für Screenshots (wird nur im Notfall benutzt - siehe Manifest).
# Add-Type gilt für den ganzen Prozess, also auch in den Server-Runspaces.
# ----------------------------------------------------------------------------
try {
    if (-not ('Arena.ScreenHelper' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace Arena {
    [StructLayout(LayoutKind.Sequential)]
    public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
    public static class ScreenHelper {
        [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
        [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hWnd);
        [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr hWnd, IntPtr hdcBlt, uint nFlags);
        [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
        [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
    }
}
'@ -ErrorAction Stop
    }
} catch {
    Write-RuntimeLog "Screenshot-Hilfstyp konnte nicht geladen werden: $($_.Exception.Message)"
}

# ----------------------------------------------------------------------------
# Version 7.2.0 (D4): Helfer fuer die Benachrichtigungs-Messung und fuer die
# Registrierung der App-Id (AUMID).
#
# Warum: Windows zeigt einen Toast nur fuer eine REGISTRIERTE App-Id. Die
# Bridge benutzte bis 7.1.5 die feste PowerShell-Id
# '{1AC14E77-...}\WindowsPowerShell\v1.0\powershell.exe'. Ohne dazu gehoerigen
# Startmenue-Eintrag verwirft Windows die Meldung still oder zeigt sie ohne
# Zuordnung - CreateToastNotifier().Show() kehrt dabei OHNE Ausnahme zurueck.
# Genau das steht im 7.1.4-Protokoll zweimal als "Arena-Fertig-Meldung
# angezeigt", waehrend der Nutzer nichts gesehen hat.
#
# Add-Type gilt fuer den ganzen Prozess, also auch fuer die Server-Runspaces.
# Scheitert das Kompilieren (z. B. Sprachmodus ConstrainedLanguage), faellt die
# Bridge auf das bisherige Verhalten zurueck und sagt das ehrlich.
# ----------------------------------------------------------------------------
try {
    if (-not ('Arena.NotifyLink' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
using System.Text;

namespace Arena {
    [ComImport]
    [Guid("000214F9-0000-0000-C000-000000000046")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    internal interface IShellLinkW {
        void GetPath([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszFile, int cchMaxPath, IntPtr pfd, uint fFlags);
        void GetIDList(out IntPtr ppidl);
        void SetIDList(IntPtr pidl);
        void GetDescription([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszName, int cchMaxName);
        void SetDescription([MarshalAs(UnmanagedType.LPWStr)] string pszName);
        void GetWorkingDirectory([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszDir, int cchMaxPath);
        void SetWorkingDirectory([MarshalAs(UnmanagedType.LPWStr)] string pszDir);
        void GetArguments([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszArgs, int cchMaxPath);
        void SetArguments([MarshalAs(UnmanagedType.LPWStr)] string pszArgs);
        void GetHotkey(out short pwHotkey);
        void SetHotkey(short wHotkey);
        void GetShowCmd(out int piShowCmd);
        void SetShowCmd(int iShowCmd);
        void GetIconLocation([Out, MarshalAs(UnmanagedType.LPWStr)] StringBuilder pszIconPath, int cchMaxPath, out int piIcon);
        void SetIconLocation([MarshalAs(UnmanagedType.LPWStr)] string pszIconPath, int iIcon);
        void SetRelativePath([MarshalAs(UnmanagedType.LPWStr)] string pszPathRel, uint dwReserved);
        void Resolve(IntPtr hwnd, uint fFlags);
        void SetPath([MarshalAs(UnmanagedType.LPWStr)] string pszFile);
    }

    [StructLayout(LayoutKind.Sequential, Pack = 4)]
    internal struct NOTIFYPROPERTYKEY { public Guid fmtid; public int pid; }

    [ComImport]
    [Guid("886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    internal interface INotifyPropertyStore {
        [PreserveSig] int GetCount(out uint cProps);
        [PreserveSig] int GetAt(uint iProp, out NOTIFYPROPERTYKEY pkey);
        [PreserveSig] int GetValue(ref NOTIFYPROPERTYKEY key, [Out, MarshalAs(UnmanagedType.Struct)] out object pv);
        [PreserveSig] int SetValue(ref NOTIFYPROPERTYKEY key, [In, MarshalAs(UnmanagedType.Struct)] ref object pv);
        [PreserveSig] int Commit();
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct NOTIFYRECT { public int Left; public int Top; public int Right; public int Bottom; }

    public static class NotifyLink {
        [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
        [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out NOTIFYRECT lpRect);
        [DllImport("user32.dll")] public static extern int GetSystemMetrics(int nIndex);

        // Legt eine Startmenue-Verknuepfung mit System.AppUserModel.ID an.
        // Rueckgabe: "ok" oder der Grund - die Bridge zeigt beides ehrlich an.
        public static string Register(string lnkPath, string targetPath, string arguments, string workingDir, string aumid, string description, string iconPath, int iconIndex) {
            object shellLink = null;
            try {
                Type shellLinkType = Type.GetTypeFromCLSID(new Guid("00021401-0000-0000-C000-000000000046"));
                if (shellLinkType == null) { return "failed: CLSID_ShellLink nicht verfuegbar" }
                shellLink = Activator.CreateInstance(shellLinkType);
                IShellLinkW link = (IShellLinkW)shellLink;
                link.SetPath(targetPath);
                if (!string.IsNullOrEmpty(arguments)) { link.SetArguments(arguments); }
                if (!string.IsNullOrEmpty(workingDir)) { link.SetWorkingDirectory(workingDir); }
                if (!string.IsNullOrEmpty(description)) { link.SetDescription(description); }
                if (!string.IsNullOrEmpty(iconPath)) { link.SetIconLocation(iconPath, iconIndex); }
                link.SetShowCmd(1);
                INotifyPropertyStore store = (INotifyPropertyStore)shellLink;
                NOTIFYPROPERTYKEY key = new NOTIFYPROPERTYKEY();
                key.fmtid = new Guid("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3");
                key.pid = 5;
                object value = aumid;
                int setHr = store.SetValue(ref key, ref value);
                store.Commit();
                IPersistFile file = (IPersistFile)shellLink;
                file.Save(lnkPath, false);
                Marshal.ReleaseComObject(file);
                Marshal.ReleaseComObject(store);
                if (setHr != 0) { return "saved_but_aumid_hr_" + setHr.ToString(); }
                return "ok";
            } catch (Exception ex) {
                return "failed: " + ex.Message;
            } finally {
                if (shellLink != null) { try { Marshal.ReleaseComObject(shellLink); } catch {} }
            }
        }

        // Misst, ob eine Vollbild-Anwendung den Vordergrund hat (Windows
        // unterdrueckt Toasts dann von sich aus). "unknown" statt Raten.
        public static string ForegroundFullscreen() {
            try {
                IntPtr hwnd = GetForegroundWindow();
                if (hwnd == IntPtr.Zero) { return "no_foreground_window"; }
                NOTIFYRECT rect;
                if (!GetWindowRect(hwnd, out rect)) { return "unknown"; }
                int screenW = GetSystemMetrics(0);
                int screenH = GetSystemMetrics(1);
                if (screenW <= 0 || screenH <= 0) { return "unknown"; }
                int width = rect.Right - rect.Left;
                int height = rect.Bottom - rect.Top;
                if (width >= screenW && height >= screenH && rect.Left <= 0 && rect.Top <= 0) { return "fullscreen"; }
                return "windowed";
            } catch (Exception ex) {
                return "unknown: " + ex.Message;
            }
        }
    }
}
'@ -ErrorAction Stop
    }
} catch {
    Write-RuntimeLog "Benachrichtigungs-Helfertyp konnte nicht geladen werden (Fallback auf bisheriges Verhalten): $($_.Exception.Message)"
}

# ----------------------------------------------------------------------------
# Version 6.0.4: Kompilierter Aufnahme-Helfer fuer die Fenster-Vorschau.
# Laueft IM Hauptprozess: Das Ergebnis ist ein CLR-Objekt mit echtem,
# unveraenderlichem byte[] und durchquert keine PowerShell-Runspace-Grenze
# (dort konnten Bilddaten als PSObject/Object[] verpackt oder beschaedigt
# werden). Scheitert bereits das Kompilieren (z. B. Sprachmodus
# ConstrainedLanguage), steht der Grund im runtime.log und die Bridge faellt
# auf den 6.0.3-Hintergrund-Runspace-Worker zurueck (ps-runspace-fallback).
# Aufnahme-Leiter fuer GPU-/verdeckte Fenster: PrintWindow(PW_RENDERFULLCONTENT)
# -> PrintWindow(0) -> WindowDcBitBlt (DWM-Umleitflaeche) -> CopyFromScreen.
# ----------------------------------------------------------------------------
$script:PreviewCaptureMode = 'ps-fallback'
$script:PreviewCaptureModeReason = 'C#-Helfer noch nicht kompiliert'
try {
    if (-not ('Arena.PreviewCapture' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading.Tasks;

namespace Arena {
    [StructLayout(LayoutKind.Sequential)]
    public struct PreviewWindowRect { public int Left; public int Top; public int Right; public int Bottom; }

    public sealed class PreviewCaptureResult {
        public bool Ok;
        public bool Minimized;
        public string Method = "";
        public string Error = "";
        public string AttemptLog = "";
        public byte[] Png;
        public int Width;
        public int Height;
        public long ElapsedMs;
    }

    public static class PreviewCapture {
        private const uint PW_RENDERFULLCONTENT = 2;
        private const int SRCCOPY = 0x00CC0020;

        [DllImport("user32.dll")] private static extern bool IsIconic(IntPtr hWnd);
        [DllImport("user32.dll")] private static extern bool GetWindowRect(IntPtr hWnd, out PreviewWindowRect lpRect);
        [DllImport("user32.dll")] private static extern bool PrintWindow(IntPtr hWnd, IntPtr hdcBlt, uint nFlags);
        [DllImport("user32.dll")] private static extern IntPtr GetWindowDC(IntPtr hWnd);
        [DllImport("user32.dll")] private static extern int ReleaseDC(IntPtr hWnd, IntPtr hDC);
        [DllImport("gdi32.dll")] private static extern IntPtr CreateCompatibleDC(IntPtr hdc);
        [DllImport("gdi32.dll")] private static extern IntPtr CreateCompatibleBitmap(IntPtr hdc, int nWidth, int nHeight);
        [DllImport("gdi32.dll")] private static extern IntPtr SelectObject(IntPtr hdc, IntPtr hgdiobj);
        [DllImport("gdi32.dll")] private static extern bool DeleteDC(IntPtr hdc);
        [DllImport("gdi32.dll")] private static extern bool DeleteObject(IntPtr hObject);
        [DllImport("gdi32.dll")] private static extern bool BitBlt(IntPtr hdcDest, int nXDest, int nYDest, int nWidth, int nHeight, IntPtr hdcSrc, int nXSrc, int nYSrc, int dwRop);

        public static Task<PreviewCaptureResult> CaptureAsync(long hwndValue, int targetHeight) {
            return Task.Run<PreviewCaptureResult>(delegate { return Capture(hwndValue, targetHeight); });
        }

        public static PreviewCaptureResult Capture(long hwndValue, int targetHeight) {
            PreviewCaptureResult result = new PreviewCaptureResult();
            Stopwatch watch = Stopwatch.StartNew();
            StringBuilder attempts = new StringBuilder();
            IntPtr hwnd = new IntPtr(hwndValue);
            try {
                if (hwnd == IntPtr.Zero) { result.Error = "HWND ist 0"; return Finish(result, watch, attempts); }
                PreviewWindowRect rect;
                if (!GetWindowRect(hwnd, out rect)) { result.Error = "GetWindowRect fehlgeschlagen"; return Finish(result, watch, attempts); }
                int width = rect.Right - rect.Left;
                int height = rect.Bottom - rect.Top;
                if (width <= 40 || height <= 40) { result.Error = "Fenstergroesse ungueltig (" + width + "x" + height + ")"; return Finish(result, watch, attempts); }

                Bitmap captured = TryPrintWindow(hwnd, width, height, PW_RENDERFULLCONTENT, "pwRenderFullContent", attempts);
                if (captured != null) { result.Method = "PrintWindow(PW_RENDERFULLCONTENT)"; }
                if (captured == null) {
                    captured = TryPrintWindow(hwnd, width, height, 0, "pwOhneFlag", attempts);
                    if (captured != null) { result.Method = "PrintWindow"; }
                }
                if (captured == null) {
                    captured = TryWindowDcBitBlt(hwnd, width, height, attempts);
                    if (captured != null) { result.Method = "WindowDcBitBlt"; }
                }
                if (captured == null) {
                    captured = TryCopyFromScreen(rect, width, height, attempts);
                    if (captured != null) { result.Method = "CopyFromScreen"; }
                }
                if (captured == null) {
                    result.Error = "alle vier Aufnahmewege ohne nutzbare Pixel (schwarz/transparent oder API-Fehler)";
                    return Finish(result, watch, attempts);
                }

                int targetH = targetHeight > 16 ? targetHeight : 88;
                double scale = (double)targetH / (double)height;
                int smallWidth = Math.Max(1, (int)(width * scale));
                using (Bitmap small = new Bitmap(smallWidth, targetH)) {
                    using (Graphics g2 = Graphics.FromImage(small)) {
                        g2.InterpolationMode = InterpolationMode.HighQualityBilinear;
                        g2.DrawImage(captured, 0, 0, smallWidth, targetH);
                    }
                    captured.Dispose();
                    using (MemoryStream ms = new MemoryStream()) {
                        small.Save(ms, ImageFormat.Png);
                        result.Png = ms.ToArray();
                    }
                }
                if (result.Png == null || result.Png.Length < 100) {
                    result.Error = "PNG-Kodierung fehlgeschlagen oder leer";
                    result.Png = null;
                    return Finish(result, watch, attempts);
                }
                result.Ok = true;
                result.Width = smallWidth;
                result.Height = targetH;
                return Finish(result, watch, attempts);
            } catch (Exception ex) {
                result.Ok = false;
                result.Error = ex.GetType().Name + ": " + ex.Message;
                return Finish(result, watch, attempts);
            }
        }

        private static PreviewCaptureResult Finish(PreviewCaptureResult result, Stopwatch watch, StringBuilder attempts) {
            watch.Stop();
            result.ElapsedMs = watch.ElapsedMilliseconds;
            result.AttemptLog = attempts.ToString();
            return result;
        }

        private static void DisposeQuiet(IDisposable value) {
            try { if (value != null) { value.Dispose(); } } catch { }
        }

        // PrintWindow: true heisst bei GPU-Fenstern leider manchmal "fertig,
        // aber komplett schwarz/transparent" - deshalb die Sichtbarkeitsprobe.
        private static Bitmap TryPrintWindow(IntPtr hwnd, int width, int height, uint flags, string tag, StringBuilder attempts) {
            Bitmap bmp = null;
            try {
                bmp = new Bitmap(width, height, PixelFormat.Format32bppArgb);
                using (Graphics g = Graphics.FromImage(bmp)) {
                    IntPtr hdc = g.GetHdc();
                    bool printed = false;
                    string innerError = "";
                    try { printed = PrintWindow(hwnd, hdc, flags); }
                    catch (Exception ex) { innerError = ex.Message; }
                    finally { g.ReleaseHdc(hdc); }
                    if (!printed) {
                        attempts.Append(tag).Append("=api-false");
                        if (innerError.Length > 0) { attempts.Append("(").Append(innerError).Append(")"); }
                        attempts.Append(" ");
                        DisposeQuiet(bmp);
                        return null;
                    }
                }
                string sample;
                if (!HasVisibleContent(bmp, out sample)) {
                    attempts.Append(tag).Append("=true-aber-nichts-sichtbar[").Append(sample).Append("] ");
                    DisposeQuiet(bmp);
                    return null;
                }
                attempts.Append(tag).Append("=ok ");
                return bmp;
            } catch (Exception ex) {
                attempts.Append(tag).Append("=ex(").Append(ex.Message).Append(") ");
                DisposeQuiet(bmp);
                return null;
            }
        }

        // DWM-/Windows-Capture-Alternative: BitBlt aus der Umleitflaeche des
        // Fenster-DC. Funktioniert bei manchen GPU-Fenstern, bei denen
        // PrintWindow nur Schwarz liefert.
        private static Bitmap TryWindowDcBitBlt(IntPtr hwnd, int width, int height, StringBuilder attempts) {
            IntPtr windowDc = IntPtr.Zero;
            IntPtr memDc = IntPtr.Zero;
            IntPtr hBmp = IntPtr.Zero;
            Bitmap bmp = null;
            try {
                windowDc = GetWindowDC(hwnd);
                if (windowDc == IntPtr.Zero) { attempts.Append("windowDcBitBlt=dc-null "); return null; }
                memDc = CreateCompatibleDC(windowDc);
                hBmp = CreateCompatibleBitmap(windowDc, width, height);
                if (memDc == IntPtr.Zero || hBmp == IntPtr.Zero) {
                    attempts.Append("windowDcBitBlt=ressource-fehlt ");
                    return null;
                }
                IntPtr oldObj = SelectObject(memDc, hBmp);
                bool blitted = BitBlt(memDc, 0, 0, width, height, windowDc, 0, 0, SRCCOPY);
                if (oldObj != IntPtr.Zero) { SelectObject(memDc, oldObj); }
                if (!blitted) { attempts.Append("windowDcBitBlt=api-false "); return null; }
                bmp = Image.FromHbitmap(hBmp);
                string sample;
                if (!HasVisibleContent(bmp, out sample)) {
                    attempts.Append("windowDcBitBlt=ok-aber-nichts-sichtbar[").Append(sample).Append("] ");
                    DisposeQuiet(bmp);
                    bmp = null;
                    return null;
                }
                attempts.Append("windowDcBitBlt=ok ");
                return bmp;
            } catch (Exception ex) {
                attempts.Append("windowDcBitBlt=ex(").Append(ex.Message).Append(") ");
                DisposeQuiet(bmp);
                return null;
            } finally {
                if (hBmp != IntPtr.Zero) { DeleteObject(hBmp); }
                if (memDc != IntPtr.Zero) { DeleteDC(memDc); }
                if (windowDc != IntPtr.Zero) { ReleaseDC(hwnd, windowDc); }
            }
        }

        // Letzter Fallback: CopyFromScreen (fotografiert ggf. Ueberlagerungen mit).
        private static Bitmap TryCopyFromScreen(PreviewWindowRect rect, int width, int height, StringBuilder attempts) {
            Bitmap bmp = null;
            try {
                bmp = new Bitmap(width, height, PixelFormat.Format32bppArgb);
                using (Graphics g = Graphics.FromImage(bmp)) {
                    g.CopyFromScreen(rect.Left, rect.Top, 0, 0, new Size(width, height));
                }
                string sample;
                if (!HasVisibleContent(bmp, out sample)) {
                    attempts.Append("copyFromScreen=nichts-sichtbar[").Append(sample).Append("] ");
                    DisposeQuiet(bmp);
                    return null;
                }
                attempts.Append("copyFromScreen=ok ");
                return bmp;
            } catch (Exception ex) {
                attempts.Append("copyFromScreen=ex(").Append(ex.Message).Append(") ");
                DisposeQuiet(bmp);
                return null;
            }
        }

        // Sichtbarkeitsprobe: mehrere Punkte ueber die Flaeche. Liefert die
        // Messwerte mit, damit das Log zeigt, WARUM ein Weg verworfen wurde.
        private static bool HasVisibleContent(Bitmap bmp, out string info) {
            int maxAlpha = 0;
            int maxLum = 0;
            long lumSum = 0;
            int samples = 0;
            int steps = 6;
            for (int ix = 0; ix < steps; ix++) {
                int x = Math.Min(bmp.Width - 1, Math.Max(0, (int)(((double)ix + 0.5) * bmp.Width / steps)));
                for (int iy = 0; iy < steps; iy++) {
                    int y = Math.Min(bmp.Height - 1, Math.Max(0, (int)(((double)iy + 0.5) * bmp.Height / steps)));
                    Color c = bmp.GetPixel(x, y);
                    samples++;
                    if (c.A > maxAlpha) { maxAlpha = c.A; }
                    int lum = c.R + c.G + c.B;
                    lumSum += lum;
                    if (lum > maxLum) { maxLum = lum; }
                }
            }
            info = "maxA=" + maxAlpha + ",maxLum=" + maxLum + ",avgLum=" + (lumSum / (long)Math.Max(1, samples));
            return maxAlpha > 8 && maxLum > 24;
        }
    }
}
'@ -ReferencedAssemblies 'System.Drawing' -ErrorAction Stop
    }
    $script:PreviewCaptureMode = 'csharp'
    $script:PreviewCaptureModeReason = ''
    Write-RuntimeLog ("Vorschau-Aufnahme: kompilierter C#-Helfer geladen (PreviewCaptureMode=csharp). PNG-Ablage: " + (Join-Path $script:AppDataRoot 'preview-cache'))
} catch {
    $script:PreviewCaptureMode = 'ps-fallback'
    $script:PreviewCaptureModeReason = [string]$_.Exception.Message
    Write-RuntimeLog ("Vorschau-Aufnahme: C#-Helfer konnte NICHT kompiliert werden (PreviewCaptureMode=ps-fallback) - Grund: " + [string]$_.Exception.Message)
}

# ============================================================================
# HTTP-SERVER
# Eine Anfrage = ein Runspace aus einem Pool. Der Pool begrenzt die Last,
# auch wenn mehrere Studio-Fenster gleichzeitig verbunden sind.
# ============================================================================
$script:BridgeHandlerScript = {
    param($Context, $Shared)

    $LogFile   = $Shared.LogFile
    $MaxInline = 180000     # Bytes, die direkt in einer Antwort stehen dürfen
    $ChunkSize = 90000      # Größe eines abholbaren Teilstücks

    function Write-BridgeLog {
        param([string]$Text)
        try {
            Add-Content -LiteralPath $LogFile -Value ('{0:u} {1}' -f (Get-Date), $Text) -Encoding UTF8
        } catch {}
    }

    # ------------------------------------------------------------------
    # Version 7.0.3: LAUFZEITDIAGNOSTIK (Leistung) - abschaltbar.
    # Ohne die Zustimmung in den Einstellungen (Standard: aus) zaehlt und
    # schreibt hier nichts. Es gibt KEIN Logging pro Anfrage/Tick; die
    # Zaehler werden in $Shared.Perf gesammelt und von der Oberflaeche
    # hoechstens alle 30 Sekunden als eine Zeile ausgegeben.
    # ------------------------------------------------------------------
    function Test-PerfEnabled {
        try { return ($Shared.BridgeSettings.perfDiagnostics -eq $true) } catch { return $false }
    }

    function Add-PerfCount {
        param([string]$Name, [long]$Delta = 1)
        try {
            if (-not (Test-PerfEnabled)) { return }
            $perf = $Shared.Perf
            if ($null -eq $perf) { return }
            $current = [long]0
            if ($perf.ContainsKey($Name)) { $current = [long]$perf[$Name] }
            $perf[$Name] = $current + $Delta
        } catch {}
    }

    # Die vom Plugin gemeldeten Interval-Zaehler (Poll-Kanal) ablegen.
    function Record-PluginPerf([string]$SessionId, $PerfPayload) {
        try {
            if (-not (Test-PerfEnabled)) { return }
            $perf = $Shared.Perf
            if ($null -eq $perf) { return }
            $perf['Plugin:' + $SessionId] = (To-Json $PerfPayload 6)
            $perf['PluginAt:' + $SessionId] = (Get-UnixSeconds)
        } catch {}
    }

    # ==================================================================
    # Version 7.2.0 (D3): ask_user mit ENTSCHEIDUNGSBAUM.
    # Der ganze Baum kommt in EINER Anfrage. Bedingungen sind erlaubt
    # (when auf eine FRUEHERE Frage), deshalb darf eine Frage von der Antwort
    # einer anderen abhaengen - auch mehrere Ebenen tief und mit mehreren
    # Zweigen. Das Fenster beim Nutzer verzweigt mit; die Antwort enthaelt
    # answers, path (wirklich gestellte Fragen) und notShown (uebersprungene).
    #
    # Wartezeit: Der harte HTTP-Deckel liegt bei 55 s (max. 85 s). ask_user
    # blockiert deshalb hoechstens 50 s und ist WIEDERAUFNEHMBAR: kommt keine
    # Antwort, liefert es { state='waiting', askId, nextCall } zurueck, und die
    # KI ruft spaeter mit resume=true erneut auf. Antworten gehen nie verloren:
    # sie liegen im gemeinsamen Zustand und kommen notfalls als
    # _bridge.userAnswers mit der naechsten Antwort.
    # ==================================================================
    function Get-AskOptionList {
        param($Question)
        $options = New-Object System.Collections.Generic.List[object]
        try {
            if ($null -ne $Question -and $Question.PSObject.Properties['options']) {
                foreach ($option in $Question.options) { $options.Add($option) }
            }
        } catch {}
        # List[object] muss als ein Rueckgabewert erhalten bleiben: PowerShell
        # entpackt sonst 0/1/n Elemente in die Pipeline.
        return ,$options
    }

    function Test-AskTree {
        # Prueft den Baum VOR dem ersten Fenster. Ein ungueltiger Baum darf
        # niemals eine halbe Frage beim Nutzer zeigen.
        param($ToolArgs)
        $maxQuestions = 12
        $maxOptions = 6
        $maxChars = 400
        $rawQuestions = $null
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['questions']) { $rawQuestions = @($ToolArgs.questions) } } catch {}
        if ($null -eq $rawQuestions -or $rawQuestions.Count -eq 0) {
            return @{ ok = $false; code = 'BAD_ARGS'; error = 'questions is required and must contain 1..12 questions.'; hint = 'Each question: { id, text, options: [ { id, label } ], allowCustomResponse, required, multi, when: [ { questionId, anyOf: [..] } ] }.' }
        }
        if ($rawQuestions.Count -gt $maxQuestions) {
            return @{ ok = $false; code = 'ASK_TOO_MANY_QUESTIONS'; error = ('Too many questions: ' + [string]$rawQuestions.Count + ' (max ' + [string]$maxQuestions + ').'); max = $maxQuestions; actual = $rawQuestions.Count; hint = 'Split the request or ask only what you really need to continue.' }
        }
        $questions = New-Object System.Collections.Generic.List[object]
        $seen = New-Object System.Collections.Generic.HashSet[string]
        $optionMap = @{}
        $index = 0
        foreach ($raw in $rawQuestions) {
            $qid = ''
            $qtext = ''
            try { $qid = ([string]$raw.id).Trim() } catch {}
            try { $qtext = ([string]$raw.text).Trim() } catch {}
            if ([string]::IsNullOrWhiteSpace($qid)) {
                return @{ ok = $false; code = 'BAD_ARGS'; error = ('Question ' + [string]($index + 1) + ' has no id.'); hint = 'Give every question a short unique id (for example "style"), so the answer can be matched.' }
            }
            if ($seen.Contains($qid)) {
                return @{ ok = $false; code = 'ASK_GRAPH_INVALID'; error = ('Duplicate question id "' + $qid + '".'); duplicateId = $qid; hint = 'Question ids must be unique.' }
            }
            if ([string]::IsNullOrWhiteSpace($qtext)) {
                return @{ ok = $false; code = 'BAD_ARGS'; error = ('Question "' + $qid + '" has no text.'); hint = 'Write the question as the user should read it.' }
            }
            if ($qtext.Length -gt $maxChars) {
                return @{ ok = $false; code = 'ASK_TOO_LONG'; error = ('Question "' + $qid + '" is too long (' + [string]$qtext.Length + ' characters, max ' + [string]$maxChars + ').'); max = $maxChars; actual = $qtext.Length }
            }
            $options = Get-AskOptionList $raw
            if ($options.Count -lt 2) {
                return @{ ok = $false; code = 'ASK_GRAPH_INVALID'; error = ('Question "' + $qid + '" needs at least 2 options.'); questionId = $qid; hint = 'Give the user real choices (labels, not numbers). Use confirm_action for a plain yes/no.' }
            }
            if ($options.Count -gt $maxOptions) {
                return @{ ok = $false; code = 'ASK_TOO_MANY_QUESTIONS'; error = ('Question "' + $qid + '" has ' + [string]$options.Count + ' options (max ' + [string]$maxOptions + ').'); max = $maxOptions; actual = $options.Count; questionId = $qid }
            }
            $optionIds = New-Object System.Collections.Generic.List[string]
            $optionViews = New-Object System.Collections.Generic.List[object]
            foreach ($option in $options) {
                $oid = ''
                $olabel = ''
                try { $oid = ([string]$option.id).Trim() } catch {}
                try { $olabel = ([string]$option.label).Trim() } catch {}
                if ([string]::IsNullOrWhiteSpace($oid) -or [string]::IsNullOrWhiteSpace($olabel)) {
                    return @{ ok = $false; code = 'ASK_GRAPH_INVALID'; error = ('Question "' + $qid + '" has an option without id or label.'); questionId = $qid }
                }
                if ($optionIds.Contains($oid)) {
                    return @{ ok = $false; code = 'ASK_GRAPH_INVALID'; error = ('Question "' + $qid + '" uses the option id "' + $oid + '" twice.'); questionId = $qid; duplicateId = $oid }
                }
                if ($olabel.Length -gt $maxChars) {
                    return @{ ok = $false; code = 'ASK_TOO_LONG'; error = ('Option "' + $oid + '" is too long (max ' + [string]$maxChars + ' characters).'); max = $maxChars; actual = $olabel.Length }
                }
                $optionIds.Add($oid)
                $optionView = @{ id = $oid; label = $olabel }
                try { if ($option.PSObject.Properties['description'] -and -not [string]::IsNullOrWhiteSpace([string]$option.description)) { $optionView.description = [string]$option.description } } catch {}
                $optionViews.Add($optionView)
            }
            $whenViews = New-Object System.Collections.Generic.List[object]
            $whenRaw = $null
            try { if ($raw.PSObject.Properties['when']) { $whenRaw = @($raw.when) } } catch {}
            if ($null -ne $whenRaw) {
                foreach ($condition in $whenRaw) {
                    $refId = ''
                    try { $refId = ([string]$condition.questionId).Trim() } catch {}
                    if ([string]::IsNullOrWhiteSpace($refId)) {
                        return @{ ok = $false; code = 'ASK_GRAPH_INVALID'; error = ('Question "' + $qid + '" has a when entry without questionId.'); questionId = $qid; hint = 'when entries reference an EARLIER question id.' }
                    }
                    if ($refId -eq $qid) {
                        return @{ ok = $false; code = 'ASK_CYCLE'; error = ('Question "' + $qid + '" depends on itself.'); questionId = $qid; cycleWith = $refId; hint = 'A question may only depend on a question that comes BEFORE it in the payload.' }
                    }
                    if (-not $seen.Contains($refId)) {
                        if ($optionMap.ContainsKey($refId)) {
                            return @{ ok = $false; code = 'ASK_CYCLE'; error = ('Question "' + $qid + '" depends on the LATER question "' + $refId + '".'); questionId = $qid; cycleWith = $refId; hint = 'Order matters: a question may only depend on earlier questions. Reorder the payload.' }
                        }
                        return @{ ok = $false; code = 'ASK_GRAPH_INVALID'; error = ('Question "' + $qid + '" depends on the unknown question "' + $refId + '".'); questionId = $qid; unknownQuestionId = $refId; knownQuestionIds = @($seen | Sort-Object) }
                    }
                    $conditionView = @{ questionId = $refId }
                    foreach ($key in @('anyOf', 'allOf')) {
                        $values = New-Object System.Collections.Generic.List[string]
                        try {
                            if ($condition.PSObject.Properties[$key]) { foreach ($value in @($condition.$key)) { $values.Add([string]$value) } }
                        } catch {}
                        if ($values.Count -gt 0) { $conditionView[$key] = @($values.ToArray()) }
                    }
                    try { if ($condition.PSObject.Properties['custom'] -and $condition.custom -eq $true) { $conditionView.custom = $true } } catch {}
                    $whenViews.Add($conditionView)
                }
            }
            $questionView = @{
                id = $qid
                text = $qtext
                index = $index
                options = @($optionViews.ToArray())
                allowCustomResponse = $false
                required = $true
                multi = $false
                when = @($whenViews.ToArray())
            }
            try { if ($raw.PSObject.Properties['allowCustomResponse'] -and $raw.allowCustomResponse -eq $true) { $questionView.allowCustomResponse = $true } } catch {}
            try { if ($raw.PSObject.Properties['required'] -and $raw.required -eq $false) { $questionView.required = $false } } catch {}
            try { if ($raw.PSObject.Properties['multi'] -and $raw.multi -eq $true) { $questionView.multi = $true } } catch {}
            $questions.Add($questionView)
            [void]$seen.Add($qid)
            $optionMap[$qid] = $optionIds
            $index = $index + 1
        }
        # Warnungen: eine Bedingung, die auf eine Option zeigt, die es nicht
        # gibt, macht die Frage unerreichbar - das ist erlaubt, wird aber
        # gesagt (ASK_UNREACHABLE), damit die KI es korrigieren kann.
        $unreachable = New-Object System.Collections.Generic.List[string]
        foreach ($question in $questions) {
            foreach ($condition in @($question.when)) {
                $refId = [string]$condition.questionId
                $validIds = $null
                if ($optionMap.ContainsKey($refId)) { $validIds = $optionMap[$refId] }
                if ($null -eq $validIds) { continue }
                foreach ($key in @('anyOf', 'allOf')) {
                    if ($null -eq $condition[$key]) { continue }
                    foreach ($value in @($condition[$key])) {
                        if (-not $validIds.Contains([string]$value)) {
                            $unreachable.Add(('Frage "' + [string]$question.id + '" wartet auf die Option "' + [string]$value + '", die es in "' + $refId + '" nicht gibt.'))
                        }
                    }
                }
            }
        }
        return @{ ok = $true; questions = $questions; warnings = $unreachable }
    }

    function Read-AskState {
        param([string]$AskId)
        $json = ''
        if (-not $Shared.AskRequests.TryGetValue([string]$AskId, [ref]$json)) { return $null }
        if ([string]::IsNullOrWhiteSpace($json)) { return $null }
        try { return ($json | ConvertFrom-Json) } catch { return $null }
    }

    function Save-AskState {
        param([string]$AskId, $State)
        try { $Shared.AskRequests[[string]$AskId] = (To-Json $State 14) } catch {}
    }

    function Ensure-AskSignal {
        param([string]$AskId)
        $existing = $null
        try {
            if ($Shared.AskSignals.TryGetValue([string]$AskId, [ref]$existing) -and $null -ne $existing) { return $existing }
        } catch {}
        $created = [System.Threading.ManualResetEvent]::new($false)
        try { $existing = $Shared.AskSignals.GetOrAdd([string]$AskId, $created) } catch { $existing = $created }
        if ($null -eq $existing) { $existing = $created }
        if (-not [object]::ReferenceEquals($existing, $created)) { try { $created.Dispose() } catch {} }
        return $existing
    }

    function Get-AskView {
        # Nur das, was der Nutzer sehen soll - ohne Server-Interna.
        param($State)
        $view = $null
        try {
            $view = @{
                askId = [string]$State.askId
                kind = [string]$State.kind
                title = [string]$State.title
                message = [string]$State.message
                questions = $State.questions
                createdAt = [int64]$State.createdAt
                expiresAt = [int64]$State.expiresAt
                state = [string]$State.state
                secondsLeft = [int][Math]::Max(0, ([int64]$State.expiresAt - (Get-UnixSeconds)))
            }
        } catch {}
        return $view
    }

    function Get-AskSummary {
        param($State)
        $parts = New-Object System.Collections.Generic.List[string]
        try {
            foreach ($question in @($State.questions)) {
                $qid = [string]$question.id
                $answer = $null
                try { if ($null -ne $State.answers -and $State.answers.PSObject.Properties[$qid]) { $answer = $State.answers.$qid } } catch {}
                if ($null -eq $answer) { continue }
                $labels = New-Object System.Collections.Generic.List[string]
                try { foreach ($label in @($answer.labels)) { $labels.Add([string]$label) } } catch {}
                $text = [string]$question.text
                if ($text.Length -gt 80) { $text = $text.Substring(0, 79) + '...' }
                $value = ''
                if ($labels.Count -gt 0) { $value = ($labels.ToArray() -join ', ') }
                $custom = ''
                try { $custom = [string]$answer.custom } catch {}
                if (-not [string]::IsNullOrWhiteSpace($custom)) {
                    if ($value) { $value = $value + ' (eigene Antwort: ' + $custom + ')' } else { $value = $custom }
                }
                if ([string]::IsNullOrWhiteSpace($value)) { $value = '(keine Angabe)' }
                $parts.Add($text + ' -> ' + $value)
            }
        } catch {}
        return ($parts.ToArray() -join ' | ')
    }

    function Get-AskResult {
        param([string]$AskId, $State)
        $answers = @{}
        try { if ($null -ne $State.answers) { $answers = $State.answers } } catch {}
        return @{
            ok = $true
            result = @{
                state = [string]$State.state
                askId = [string]$AskId
                kind = [string]$State.kind
                answeredAt = [int64]$State.answeredAt
                answers = $answers
                path = @($State.path)
                notShown = @($State.notShown)
                summary = (Get-AskSummary $State)
                note = 'path lists the questions the user actually saw; notShown lists the questions that were skipped because their condition did not match. Act on the answers exactly as given.'
            }
        }
    }

    function Get-AskCancelledResponse {
        # Ein Abbruch ist eine echte Nutzerentscheidung, keine fehlende Antwort.
        # Die KI darf die gleiche Frage nicht erneut stellen und muss die
        # Annahme, mit der sie weiterarbeitet, offen benennen.
        param([string]$AskId, $State = $null)
        return @{
            ok = $false
            code = 'ASK_CANCELLED'
            error = 'The user cancelled this question.'
            hint = 'Der Nutzer hat abgebrochen. Frage nicht erneut. Arbeite mit einer vernünftigen Annahme weiter und sage welche — oder stoppe und berichte.'
            askId = $AskId
            cancelled = $true
            cancelledAt = $(try { [int64]$State.cancelledAt } catch { [int64]0 })
            summary = 'Der Nutzer hat abgebrochen.'
        }
    }

    function Get-AskExpirySeconds {
        param($ToolArgs, [int]$Default = 180)
        $seconds = $Default
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['expiresInSeconds']) { $seconds = [int]$ToolArgs.expiresInSeconds } } catch {}
        if ($seconds -lt 30) { $seconds = 30 }
        if ($seconds -gt 1800) { $seconds = 1800 }
        return $seconds
    }

    function Get-AskWaitSeconds {
        param($ToolArgs, [int]$Default = 0)
        $seconds = $Default
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['waitSeconds']) { $seconds = [int]$ToolArgs.waitSeconds } } catch {}
        if ($seconds -lt 0) { $seconds = 0 }
        if ($seconds -gt 50) { $seconds = 50 }
        return $seconds
    }

    function New-AskRequest {
        param([string]$SessionId, $ToolArgs, [string]$Kind = 'ask')
        $tree = Test-AskTree $ToolArgs
        if (-not $tree.ok) { return $tree }
        $title = ''
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['title']) { $title = ([string]$ToolArgs.title).Trim() } } catch {}
        if ([string]::IsNullOrWhiteSpace($title)) { $title = 'Arena braucht eine Entscheidung' }
        if ($title.Length -gt 90) { $title = $title.Substring(0, 89) + '...' }
        $message = ''
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['message']) { $message = ([string]$ToolArgs.message).Trim() } } catch {}
        if ($message.Length -gt 600) { $message = $message.Substring(0, 599) + '...' }
        $askId = 'ask_' + ([guid]::NewGuid().ToString('N').Substring(0, 12))
        $now = Get-UnixSeconds
        $expiresIn = Get-AskExpirySeconds $ToolArgs
        $entry = $SessionId
        $place = ''
        try {
            $entryInfo = Get-SessionEntry $SessionId
            if ($entryInfo) { $place = [string]$entryInfo.placeName }
        } catch {}
        $state = [pscustomobject]@{
            askId = $askId
            sessionId = [string]$SessionId
            kind = [string]$Kind
            title = $title
            message = $message
            place = $place
            questions = @($tree.questions.ToArray())
            state = 'waiting'
            createdAt = $now
            expiresAt = ($now + $expiresIn)
            answeredAt = 0
            cancelledAt = 0
            answers = $null
            path = @()
            notShown = @()
            deliveredAt = 0
            lastCallAt = $now
        }
        Save-AskState $askId $state
        [void](Ensure-AskSignal $askId)
        Add-ChannelCount 'AskOpened' 1
        Write-FlowStation 'ASK' $askId 'OPENED' @{ sid = $SessionId; kind = $Kind; questions = $tree.questions.Count; expiresInSeconds = $expiresIn; title = $title }
        foreach ($warning in @($tree.warnings)) { Write-FlowStation 'ASK' $askId 'UNREACHABLE' @{ detail = [string]$warning } }
        Add-BridgeEvent $SessionId 'ask_opened' ('Arena fragt: ' + $title) @{ askId = $askId; questions = $tree.questions.Count }
        $result = @{
            ok = $true
            result = (Get-AskView $state)
        }
        $result.result.nextCall = 'ask_user { askId: "' + $askId + '", resume: true, waitSeconds: 45 }'
        $result.result.hint = 'The question window is open at the user''s mouse cursor. It stays open for ' + [string]$expiresIn + ' seconds. Do NOT guess: call ask_user again with askId and resume=true to wait for the answers (max 50 seconds per call), or continue with other work and resume later. Answers also arrive automatically as _bridge.userAnswers.'
        if ($tree.warnings.Count -gt 0) { $result.result.askWarning = 'ASK_UNREACHABLE'; $result.result.warnings = @($tree.warnings) }
        return $result
    }

    function Wait-AskAnswer {
        param([string]$AskId, [int]$MaxSeconds)
        $signal = Ensure-AskSignal $AskId
        $started = [System.Diagnostics.Stopwatch]::StartNew()
        $reason = 'timeout'
        $state = Read-AskState $AskId
        if ($null -ne $state -and ([string]$state.state -eq 'answered' -or [string]$state.state -eq 'cancelled')) { return $state }
        if ($MaxSeconds -lt 1) { return $state }
        while ($started.Elapsed.TotalSeconds -lt $MaxSeconds) {
            $remaining = [int][Math]::Ceiling($MaxSeconds - $started.Elapsed.TotalSeconds)
            $slice = 250
            if (($remaining * 1000) -lt $slice) { $slice = [Math]::Max(20, ($remaining * 1000)) }
            try { [void]$signal.WaitOne($slice) } catch { break }
            $state = Read-AskState $AskId
            if ($null -eq $state) { break }
            if ([string]$state.state -eq 'answered') { $reason = 'answered'; break }
            if ([string]$state.state -eq 'cancelled') { $reason = 'cancelled'; break }
            if ([string]$state.state -eq 'expired') { $reason = 'expired'; break }
            if ((Get-UnixSeconds) -gt [int64]$state.expiresAt) { $reason = 'expired'; break }
        }
        try { [void]$signal.Reset() } catch {}
        $state = Read-AskState $AskId
        if ($null -eq $state) { return $null }
        if ([string]$state.state -eq 'waiting' -and (Get-UnixSeconds) -gt [int64]$state.expiresAt) {
            $state.state = 'expired'
            Save-AskState $AskId $state
            Add-ChannelCount 'AskExpired' 1
            Write-FlowStation 'ASK' $AskId 'EXPIRED' @{ sid = [string]$state.sessionId; waitedSeconds = [int][Math]::Round($started.Elapsed.TotalSeconds, 1) }
        }
        Write-FlowStation 'ASK' $AskId 'WAIT_END' @{ reason = $reason; waitedSeconds = [int][Math]::Round($started.Elapsed.TotalSeconds, 1); state = [string]$state.state }
        return $state
    }

    function Invoke-AskUser {
        param([string]$SessionId, $ToolArgs)
        $resumeId = ''
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['askId']) { $resumeId = ([string]$ToolArgs.askId).Trim() } } catch {}
        $resume = $false
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['resume']) { $resume = ($ToolArgs.resume -eq $true) } } catch {}
        if ([string]::IsNullOrWhiteSpace($resumeId)) {
            $created = New-AskRequest $SessionId $ToolArgs 'ask'
            if ($null -eq $created -or -not $created.ok) { return $created }
            $askId = [string]$created.result.askId
            $waitSeconds = Get-AskWaitSeconds $ToolArgs 0
            if ($waitSeconds -le 0) { return $created }
            $state = Wait-AskAnswer $askId $waitSeconds
            if ($null -ne $state -and [string]$state.state -eq 'answered') { return (Get-AskResult $askId $state) }
            if ($null -ne $state -and [string]$state.state -eq 'cancelled') { return (Get-AskCancelledResponse $askId $state) }
            if ($null -ne $state -and [string]$state.state -eq 'expired') {
                return @{ ok = $false; code = 'ASK_EXPIRED'; error = 'The question window expired before the user answered.'; hint = 'Ask again only if you really need it, or continue with your best assumption and say so in your answer.'; askId = $askId }
            }
            $waiting = Get-AskView $state
            if ($null -eq $waiting) {
                return @{ ok = $false; code = 'ASK_UNKNOWN'; error = 'The question request disappeared while waiting.'; hint = 'Ask again with the same question text.'; askId = $askId }
            }
            $waiting.nextCall = 'ask_user { askId: "' + $askId + '", resume: true, waitSeconds: 45 }'
            return @{ ok = $true; result = $waiting }
        }
        $state = Read-AskState $resumeId
        if ($null -eq $state) {
            return @{ ok = $false; code = 'ASK_UNKNOWN'; error = ('No question request with id "' + $resumeId + '".'); hint = 'Use the askId from the previous ask_user answer.' }
        }
        if ([string]$state.state -eq 'answered') { return (Get-AskResult $resumeId $state) }
        if ([string]$state.state -eq 'cancelled') { return (Get-AskCancelledResponse $resumeId $state) }
        if ([string]$state.state -eq 'expired' -or (Get-UnixSeconds) -gt [int64]$state.expiresAt) {
            if ([string]$state.state -ne 'expired') {
                $state.state = 'expired'
                Save-AskState $resumeId $state
                Add-ChannelCount 'AskExpired' 1
            }
            return @{ ok = $false; code = 'ASK_EXPIRED'; error = 'The question window expired before the user answered.'; hint = 'Continue with your best assumption, say clearly what you assumed, and let the user correct you with a message.'; askId = $resumeId }
        }
        if (-not $resume) {
            $view = Get-AskView $state
            if ($null -eq $view) {
                return @{ ok = $false; code = 'ASK_UNKNOWN'; error = 'The question request could not be read.'; hint = 'Ask again with the same question text.'; askId = $resumeId }
            }
            $view.nextCall = 'ask_user { askId: "' + $resumeId + '", resume: true, waitSeconds: 45 }'
            return @{ ok = $true; result = $view }
        }
        $waitSeconds = Get-AskWaitSeconds $ToolArgs 45
        if ($waitSeconds -le 0) { $waitSeconds = 45 }
        $waited = Wait-AskAnswer $resumeId $waitSeconds
        if ($null -ne $waited -and [string]$waited.state -eq 'answered') { return (Get-AskResult $resumeId $waited) }
        if ($null -ne $waited -and [string]$waited.state -eq 'cancelled') { return (Get-AskCancelledResponse $resumeId $waited) }
        if ($null -ne $waited -and [string]$waited.state -eq 'expired') {
            return @{ ok = $false; code = 'ASK_EXPIRED'; error = 'The question window expired before the user answered.'; hint = 'Continue with your best assumption and say so.'; askId = $resumeId }
        }
        $view = Get-AskView $waited
        if ($null -eq $view) {
            return @{ ok = $false; code = 'ASK_UNKNOWN'; error = 'The question request disappeared while waiting.'; hint = 'Ask again with the same question text.'; askId = $resumeId }
        }
        $view.nextCall = 'ask_user { askId: "' + $resumeId + '", resume: true, waitSeconds: 45 }'
        $view.hint = 'Still no answer. The window is still open. Do useful work you can do without the answer, then resume.'
        return @{ ok = $true; result = $view }
    }

    function Invoke-ConfirmAction {
        param([string]$SessionId, $ToolArgs)
        $title = ''
        $message = ''
        $confirmLabel = 'Ja, mach das'
        $cancelLabel = 'Nein, nicht'
        try {
            if ($null -ne $ToolArgs) {
                if ($ToolArgs.PSObject.Properties['title']) { $title = ([string]$ToolArgs.title).Trim() }
                if ($ToolArgs.PSObject.Properties['message']) { $message = ([string]$ToolArgs.message).Trim() }
                if ($ToolArgs.PSObject.Properties['confirmLabel'] -and -not [string]::IsNullOrWhiteSpace([string]$ToolArgs.confirmLabel)) { $confirmLabel = ([string]$ToolArgs.confirmLabel).Trim() }
                if ($ToolArgs.PSObject.Properties['cancelLabel'] -and -not [string]::IsNullOrWhiteSpace([string]$ToolArgs.cancelLabel)) { $cancelLabel = ([string]$ToolArgs.cancelLabel).Trim() }
            }
        } catch {}
        if ([string]::IsNullOrWhiteSpace($title)) { $title = 'Soll Arena das wirklich tun?' }
        $question = [pscustomobject]@{
            id = 'confirm'
            text = $(if ([string]::IsNullOrWhiteSpace($message)) { $title } else { $message })
            options = @(
                @{ id = 'yes'; label = $confirmLabel; description = 'Arena macht so weiter, wie beschrieben.' },
                @{ id = 'no'; label = $cancelLabel; description = 'Arena laesst es und fragt nach einer anderen Loesung.' }
            )
            allowCustomResponse = $true
            required = $true
            multi = $false
            when = @()
        }
        $payload = [pscustomobject]@{
            title = $title
            message = $message
            questions = @($question)
            expiresInSeconds = $(if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['expiresInSeconds']) { [int]$ToolArgs.expiresInSeconds } else { 120 })
            waitSeconds = $(if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['waitSeconds']) { [int]$ToolArgs.waitSeconds } else { 0 })
        }
        $answer = Invoke-AskUser $SessionId $payload
        $answer.kind = 'confirm'
        if ($answer.ContainsKey('result')) {
            $answer.result.kind = 'confirm'
            $confirmed = $false
            $custom = ''
            try {
                $yes = $answer.result.answers.confirm
                if ($null -ne $yes) {
                    foreach ($optionId in @($yes.optionIds)) { if ([string]$optionId -eq 'yes') { $confirmed = $true } }
                    $custom = [string]$yes.custom
                }
            } catch {}
            $answer.result.confirmed = $confirmed
            $answer.result.customResponse = $custom
            if ([string]$answer.result.state -eq 'answered') {
                Write-FlowStation 'ASK' ([string]$answer.result.askId) 'CONFIRMED' @{ confirmed = $confirmed; sid = $SessionId }
            }
        } elseif ($answer.ContainsKey('code') -and [string]$answer.code -eq 'ASK_CANCELLED') {
            # confirm_action bleibt bei einem Abbruch eindeutig Nein; der
            # ASK_CANCELLED-Code sagt der KI zugleich, dass sie nicht erneut
            # fragen darf.
            $answer.confirmed = $false
            $answer.cancelled = $true
            $answer.summary = 'Der Nutzer hat abgebrochen.'
        }
        return $answer
    }

    function Get-LateAskAnswers {
        # Antworten, die der KI noch NICHT gezeigt wurden. Sie gehen als
        # _bridge.userAnswers mit der naechsten Antwort - eine Antwort darf
        # niemals verloren gehen, nur weil die KI gerade nicht gewartet hat.
        param([string]$SessionId, [int]$Max = 4)
        $items = New-Object System.Collections.Generic.List[object]
        try {
            foreach ($pair in $Shared.AskRequests.GetEnumerator()) {
                if ($items.Count -ge $Max) { break }
                $state = $null
                try { $state = ($pair.Value | ConvertFrom-Json) } catch { $state = $null }
                if ($null -eq $state) { continue }
                if ([string]$state.sessionId -ne [string]$SessionId) { continue }
                $answerState = [string]$state.state
                if ($answerState -ne 'answered' -and $answerState -ne 'cancelled') { continue }
                if ([int64]$state.deliveredAt -gt 0) { continue }
                $state.deliveredAt = Get-UnixSeconds
                Save-AskState ([string]$state.askId) $state
                $wasCancelled = ($answerState -eq 'cancelled')
                $items.Add([pscustomobject]@{
                    askId = [string]$state.askId
                    kind = [string]$state.kind
                    title = [string]$state.title
                    answers = $(if ($wasCancelled) { @{} } else { $state.answers })
                    path = $(if ($wasCancelled) { @() } else { @($state.path) })
                    notShown = $(if ($wasCancelled) { @() } else { @($state.notShown) })
                    cancelled = $wasCancelled
                    cancelledAt = $(if ($wasCancelled) { [int64]$state.cancelledAt } else { [int64]0 })
                    summary = $(if ($wasCancelled) { 'Der Nutzer hat abgebrochen.' } else { Get-AskSummary $state })
                    answeredAt = [int64]$state.answeredAt
                })
                Add-ChannelCount 'AskLateAnswers' 1
                Write-FlowStation 'ASK' ([string]$state.askId) $(if ($wasCancelled) { 'CANCELLED_DELIVERED' } else { 'LATE_DELIVERED' }) @{ sid = $SessionId }
            }
        } catch {}
        return ,$items
    }

    function Get-PendingAskViews {
        # Offene Fragen einer Sitzung fuer die Oberflaeche (neueste zuerst).
        param([string]$SessionId, [int]$Max = 3)
        $items = New-Object System.Collections.Generic.List[object]
        try {
            foreach ($pair in $Shared.AskRequests.GetEnumerator()) {
                $state = $null
                try { $state = ($pair.Value | ConvertFrom-Json) } catch { $state = $null }
                if ($null -eq $state) { continue }
                if ([string]$state.sessionId -ne [string]$SessionId) { continue }
                if ([string]$state.state -ne 'waiting') { continue }
                if ((Get-UnixSeconds) -gt [int64]$state.expiresAt) { continue }
                $items.Add((Get-AskView $state))
                if ($items.Count -ge $Max) { break }
            }
        } catch {}
        return ,$items
    }

    # ------------------------------------------------------------------
    # Version 7.2.0 (AP6): BAU-REGISTER.
    # Bis 7.1.5 fuehrte die Bridge nur fuer ORGANISCHE Modelle Buch. Alles
    # andere konnte unbemerkt und ungeprueft entstehen - genau so wurde aus
    # einem Baum ein Zylinder mit zwei Kugeln. Jetzt wird jeder Modell-Bau
    # registriert; report_done nennt, was gebaut und was davon geprueft wurde.
    # ------------------------------------------------------------------
    function Read-SessionBuilds {
        param([string]$SessionId)
        $json = ''
        if (-not $Shared.SessionBuilds.TryGetValue([string]$SessionId, [ref]$json)) { return $null }
        if ([string]::IsNullOrWhiteSpace($json)) { return $null }
        try { return ($json | ConvertFrom-Json) } catch { return $null }
    }

    function Save-SessionBuilds {
        param([string]$SessionId, $State)
        try { $Shared.SessionBuilds[[string]$SessionId] = (To-Json $State 12) } catch {}
    }

    function Get-SessionBuildRecords {
        param($State)
        $items = New-Object System.Collections.Generic.List[object]
        try {
            if ($null -ne $State -and $State.PSObject.Properties['models']) {
                foreach ($entry in $State.models) { $items.Add($entry) }
            }
        } catch {}
        return ,$items
    }

    function Register-SessionBuild {
        param([string]$SessionId, [string]$Tool, $ToolArgs, $Payload, [int64]$AtTicks = 0)
        try {
            $eligible = $Tool -in @('build_polygon_model', 'build_assembly', 'mesh_slots', 'mesh_apply', 'build_surface', 'build_interface',
                'union', 'subtract', 'negate', 'intersect', 'insert_asset', 'apply_asset', 'clone_instance', 'group_instances')
            if (-not $eligible -and $Tool -in @('create_instance', 'bulk_create')) {
                $className = ''
                try { $className = [string]$ToolArgs.className } catch {}
                if ($className -eq 'Model') { $eligible = $true }
            }
            if (-not $eligible) { return }
            if ($null -eq $Payload) { return }
            if ($AtTicks -le 0) { $AtTicks = [DateTime]::UtcNow.Ticks }
            $modelId = ''
            $modelPath = ''
            $modelName = ''
            try { if ($Payload.PSObject.Properties['model'] -and $null -ne $Payload.model) { $modelId = [string]$Payload.model.id; $modelPath = [string]$Payload.model.path; $modelName = [string]$Payload.model.name } } catch {}
            if ([string]::IsNullOrWhiteSpace($modelId)) { try { if ($Payload.PSObject.Properties['id']) { $modelId = [string]$Payload.id } } catch {} }
            if ([string]::IsNullOrWhiteSpace($modelPath)) { try { if ($Payload.PSObject.Properties['path']) { $modelPath = [string]$Payload.path } } catch {} }
            if ([string]::IsNullOrWhiteSpace($modelName)) { try { if ($Payload.PSObject.Properties['name']) { $modelName = [string]$Payload.name } } catch {} }
            if ([string]::IsNullOrWhiteSpace($modelId) -and [string]::IsNullOrWhiteSpace($modelPath)) { return }
            $declaredGrade = ''
            try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['grade']) { $declaredGrade = ([string]$ToolArgs.grade).ToLowerInvariant() } } catch {}
            if ($declaredGrade -notin @('simple', 'lowpoly', 'blockout', 'detailed')) { $declaredGrade = '' }
            $state = Read-SessionBuilds $SessionId
            if ($null -eq $state) { $state = [pscustomobject]@{ models = @(); updatedAt = 0 } }
            $records = Get-SessionBuildRecords $state
            $existing = $null
            foreach ($record in $records) {
                $recordId = ''
                $recordPath = ''
                try { $recordId = [string]$record.id } catch {}
                try { $recordPath = [string]$record.path } catch {}
                if (-not [string]::IsNullOrWhiteSpace($modelId) -and $recordId -eq $modelId) { $existing = $record; break }
                if ([string]::IsNullOrWhiteSpace($modelId) -and -not [string]::IsNullOrWhiteSpace($modelPath) -and $recordPath -eq $modelPath) { $existing = $record; break }
            }
            if ($null -eq $existing) {
                $record = [pscustomobject]@{
                    tool = [string]$Tool
                    id = $modelId
                    path = $modelPath
                    name = $modelName
                    declaredGrade = $declaredGrade
                    firstWriteAtTicks = $AtTicks
                    lastWriteAtTicks = $AtTicks
                    writes = 1
                    auditAtTicks = [int64]0
                    auditGrade = ''
                    auditFinishScore = -1
                    auditVerdict = ''
                    auditDraftRisk = $false
                }
                $records.Add($record)
                Write-FlowStation 'BUILD' ([string]$Tool) 'REGISTERED' @{ sid = $SessionId; path = $modelPath; name = $modelName; declaredGrade = $declaredGrade }
            } else {
                Set-FlowField $existing 'lastWriteAtTicks' $AtTicks
                $writes = 0
                try { $writes = [int]$existing.writes } catch {}
                Set-FlowField $existing 'writes' ($writes + 1)
                if (-not [string]::IsNullOrWhiteSpace($declaredGrade)) { Set-FlowField $existing 'declaredGrade' $declaredGrade }
                if (-not [string]::IsNullOrWhiteSpace($modelPath)) { Set-FlowField $existing 'path' $modelPath }
                if (-not [string]::IsNullOrWhiteSpace($modelName)) { Set-FlowField $existing 'name' $modelName }
                # Ein neuer Schreibvorgang macht den alten Audit ungueltig.
                Set-FlowField $existing 'auditAtTicks' ([int64]0)
                Set-FlowField $existing 'auditGrade' ''
                Set-FlowField $existing 'auditFinishScore' (-1)
                Set-FlowField $existing 'auditVerdict' ''
                Set-FlowField $existing 'auditDraftRisk' $false
            }
            while ($records.Count -gt 40) { $records.RemoveAt(0) }
            Set-FlowField $state 'models' @($records.ToArray())
            Set-FlowField $state 'updatedAt' (Get-UnixSeconds)
            Save-SessionBuilds $SessionId $state
            Add-ChannelCount 'BuildsRegistered' 1
        } catch {}
    }

    function Update-SessionBuildAudit {
        param([string]$SessionId, $AuditPayload, [int64]$AtTicks = 0)
        try {
            if ($null -eq $AuditPayload) { return }
            if ($AtTicks -le 0) { $AtTicks = [DateTime]::UtcNow.Ticks }
            $quality = $null
            try { if ($AuditPayload.PSObject.Properties['buildQuality']) { $quality = $AuditPayload.buildQuality } } catch {}
            if ($null -eq $quality) { return }
            $grade = ''
            try { if ($quality.PSObject.Properties['grade']) { $grade = [string]$quality.grade } } catch {}
            $finishScore = -1
            try { if ($quality.PSObject.Properties['finishScore']) { $finishScore = [int]$quality.finishScore } } catch {}
            $draftRisk = $false
            try { if ($quality.PSObject.Properties['draftRisk']) { $draftRisk = [bool]$quality.draftRisk } } catch {}
            $verdict = ''
            try { if ($quality.PSObject.Properties['verdict']) { $verdict = [string]$quality.verdict } } catch {}
            $scope = ''
            try { if ($AuditPayload.PSObject.Properties['scope']) { $scope = [string]$AuditPayload.scope } } catch {}
            $modelIds = New-Object System.Collections.Generic.List[string]
            try {
                if ($quality.PSObject.Properties['organicQuality'] -and $null -ne $quality.organicQuality) {
                    foreach ($evidence in @($quality.organicQuality.models)) {
                        $evidenceId = ''
                        try { $evidenceId = [string]$evidence.id } catch {}
                        if (-not [string]::IsNullOrWhiteSpace($evidenceId)) { $modelIds.Add($evidenceId) }
                    }
                }
            } catch {}
            $state = Read-SessionBuilds $SessionId
            if ($null -eq $state) { return }
            $records = Get-SessionBuildRecords $state
            $touched = 0
            foreach ($record in $records) {
                $recordId = ''
                $recordPath = ''
                try { $recordId = [string]$record.id } catch {}
                try { $recordPath = [string]$record.path } catch {}
                $matches = $false
                if (-not [string]::IsNullOrWhiteSpace($recordId) -and $modelIds.Contains($recordId)) { $matches = $true }
                if (-not $matches -and -not [string]::IsNullOrWhiteSpace($recordPath) -and -not [string]::IsNullOrWhiteSpace($scope)) {
                    if ($recordPath -eq $scope -or $recordPath.StartsWith($scope + '.')) { $matches = $true }
                }
                if (-not $matches) { continue }
                Set-FlowField $record 'auditAtTicks' $AtTicks
                Set-FlowField $record 'auditGrade' $grade
                Set-FlowField $record 'auditFinishScore' $finishScore
                Set-FlowField $record 'auditVerdict' $verdict
                Set-FlowField $record 'auditDraftRisk' $draftRisk
                $touched = $touched + 1
            }
            if ($touched -gt 0) {
                Set-FlowField $state 'models' @($records.ToArray())
                Set-FlowField $state 'updatedAt' (Get-UnixSeconds)
                Save-SessionBuilds $SessionId $state
                Write-FlowStation 'BUILD' ([string]$SessionId) 'AUDITED' @{ models = $touched; grade = $grade; finishScore = $finishScore; draftRisk = $draftRisk }
            }
        } catch {}
    }

    function Get-SessionBuildSummary {
        # Was wurde gebaut, was davon ist geprueft, was ist ein Entwurf?
        param([string]$SessionId)
        $summary = [pscustomobject]@{
            models = 0
            audited = 0
            unaudited = @()
            drafts = @()
            declared = @()
            averageFinishScore = -1
        }
        try {
            $state = Read-SessionBuilds $SessionId
            $records = Get-SessionBuildRecords $state
            if ($records.Count -eq 0) { return $summary }
            $unaudited = New-Object System.Collections.Generic.List[object]
            $drafts = New-Object System.Collections.Generic.List[object]
            $declared = New-Object System.Collections.Generic.List[string]
            $audited = 0
            $scoreSum = 0
            $scoreCount = 0
            $now = Get-UnixSeconds
            foreach ($record in $records) {
                $auditAt = [int64]0
                try { $auditAt = [int64]$record.auditAtTicks } catch {}
                $lastWrite = [int64]0
                try { $lastWrite = [int64]$record.lastWriteAtTicks } catch {}
                $name = ''
                $path = ''
                $tool = ''
                $declaredGrade = ''
                try { $name = [string]$record.name } catch {}
                try { $path = [string]$record.path } catch {}
                try { $tool = [string]$record.tool } catch {}
                try { $declaredGrade = [string]$record.declaredGrade } catch {}
                if (-not [string]::IsNullOrWhiteSpace($declaredGrade)) { $declared.Add($name + ' (' + $declaredGrade + ')') }
                if ($auditAt -gt 0 -and $auditAt -ge $lastWrite) {
                    $audited = $audited + 1
                    $score = -1
                    try { $score = [int]$record.auditFinishScore } catch {}
                    if ($score -ge 0) { $scoreSum = $scoreSum + $score; $scoreCount = $scoreCount + 1 }
                    $draft = $false
                    try { $draft = [bool]$record.auditDraftRisk } catch {}
                    if ($draft) {
                        $drafts.Add([pscustomobject]@{ name = $name; path = $path; tool = $tool; grade = $(try { [string]$record.auditGrade } catch { '' }); finishScore = $score })
                    }
                } else {
                    $age = 0
                    try { if ($lastWrite -gt 0) { $age = [int][Math]::Max(0, ($now - [int64](($lastWrite - 621355968000000000) / 10000000))) } } catch {}
                    $unaudited.Add([pscustomobject]@{ name = $name; path = $path; tool = $tool; declaredGrade = $declaredGrade; ageSeconds = $age })
                }
            }
            $summary.models = $records.Count
            $summary.audited = $audited
            $summary.unaudited = @($unaudited.ToArray())
            $summary.drafts = @($drafts.ToArray())
            $summary.declared = @($declared.ToArray())
            if ($scoreCount -gt 0) { $summary.averageFinishScore = [int][Math]::Round($scoreSum / $scoreCount) }
        } catch {}
        return $summary
    }

    # ------------------------------------------------------------------
    # Version 7.2.0: STATIONEN + KANAL-ZAEHLER.
    # Format wie die bewaehrten PREVIEW-Stationen aus 6.0.4:
    #   <BEREICH> [<flowId>] <STATION> feld=wert feld=wert
    # Ohne diese Zeilen war "der Balken blieb bei 0 %" und "die Meldung kam
    # nicht an" nicht beweisbar - beides wurde in 7.1.x nur vermutet.
    # ------------------------------------------------------------------
    function Format-FlowFields {
        param($Fields)
        $parts = New-Object System.Collections.Generic.List[string]
        try {
            if ($Fields -is [System.Collections.IDictionary]) {
                foreach ($key in $Fields.Keys) {
                    $value = $Fields[$key]
                    if ($null -eq $value) { $value = '-' }
                    $text = ([string]$value) -replace '[\r\n\t]+', ' '
                    if ($text.Length -gt 200) { $text = $text.Substring(0, 199) + '...' }
                    $parts.Add(([string]$key + '=' + $text))
                }
            }
        } catch {}
        if ($parts.Count -eq 0) { return '' }
        return (' ' + ($parts.ToArray() -join ' '))
    }

    function Add-FlowTraceLine {
        param([string]$Line)
        try {
            if ([string]::IsNullOrWhiteSpace($Line)) { return }
            $cap = 500
            try { $cap = [int]$Shared.FlowTraceCap } catch {}
            if ($cap -lt 20) { $cap = 20 }
            $Shared.FlowTrace.Enqueue(('{0:u} ' -f (Get-Date)) + $Line)
            $discard = $null
            while ($Shared.FlowTrace.Count -gt $cap) {
                if (-not $Shared.FlowTrace.TryDequeue([ref]$discard)) { break }
            }
        } catch {}
    }

    function Write-FlowStation {
        param([string]$Area, [string]$FlowId, [string]$Station, $Fields = $null)
        $line = ''
        try {
            $line = ([string]$Area).ToUpperInvariant() + ' [' + [string]$FlowId + '] ' + ([string]$Station).ToUpperInvariant() + (Format-FlowFields $Fields)
            Write-BridgeLog $line
            Add-FlowTraceLine $line
        } catch {}
        # Bewusst KEIN return: eine Ausgabe hier wuerde den Rueckgabewert jedes
        # Aufrufers verschmutzen (Invoke-AckUserMessage, Update-ArenaProgressState).
    }

    function Add-ChannelCount {
        param([string]$Name, [long]$Delta = 1)
        try {
            $channel = $Shared.Channel
            if ($null -eq $channel) { return }
            if ([string]::IsNullOrWhiteSpace($Name)) { return }
            $existing = $null
            if ($channel.ContainsKey($Name)) { $existing = $channel[$Name] }
            if ($existing -is [long] -or $existing -is [int]) { $channel[$Name] = ([long]$existing + [long]$Delta) }
            else { $channel[$Name] = [long]$Delta }
        } catch {}
    }

    function Set-ChannelText {
        param([string]$Name, [string]$Value)
        try {
            $channel = $Shared.Channel
            if ($null -eq $channel) { return }
            $channel[$Name] = [string]$Value
        } catch {}
    }

    # Ein Feld an einem aus JSON gelesenen Objekt schreiben, ohne in die
    # PowerShell-5.1-Falle "The property cannot be found" zu laufen.
    function Set-FlowField {
        param($Object, [string]$Name, $Value)
        try {
            if ($null -eq $Object) { return }
            if ($Object.PSObject.Properties[$Name]) { $Object.$Name = $Value }
            else { $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force }
        } catch {}
    }

    # ------------------------------------------------------------------
    # Version 7.2.0: NUTZER-KANAL ("Zwischen-Prompt").
    # Die Bridge kann NICHT in den Arena-Chat schreiben - es gibt keinen
    # Push-Kanal zur KI. Deshalb traegt JEDER Umschlag wartende
    # Nutzernachrichten mit (at-least-once), und wait_for_user erlaubt der KI,
    # an einer Entscheidungsstelle aktiv auf den Nutzer zu warten.
    # ------------------------------------------------------------------
    function Read-UserMessageState {
        param([string]$SessionId)
        $json = ''
        if (-not $Shared.UserMessages.TryGetValue([string]$SessionId, [ref]$json)) { return $null }
        if ([string]::IsNullOrWhiteSpace($json)) { return $null }
        try { return ($json | ConvertFrom-Json) } catch { return $null }
    }

    function Save-UserMessageState {
        param([string]$SessionId, $State)
        try { $Shared.UserMessages[[string]$SessionId] = (To-Json $State 12) } catch {}
    }

    # Gibt IMMER eine echte List[object] zurueck. Kein ", $array" und kein
    # @() am Aufrufer - genau die Kombination hat in 7.1.0 jede
    # Befehlszustellung blockiert.
    function Get-UserMessageList {
        param($State)
        $items = New-Object System.Collections.Generic.List[object]
        try {
            if ($null -ne $State -and $State.PSObject.Properties['messages']) {
                foreach ($entry in $State.messages) { $items.Add($entry) }
            }
        } catch {}
        return ,$items
    }

    function Get-PendingUserMessageViews {
        param([string]$SessionId, [int]$Max = 3)
        $views = New-Object System.Collections.Generic.List[object]
        $now = Get-UnixSeconds
        try {
            [System.Threading.Monitor]::Enter($Shared.UserMessageLock)
            $list = Get-UserMessageList (Read-UserMessageState $SessionId)
            foreach ($message in $list) {
                if ($views.Count -ge $Max) { break }
                $messageState = ''
                try { $messageState = [string]$message.state } catch {}
                $attempts = 0
                try { $attempts = [int]$message.attempts } catch {}
                $deliveredAt = [int64]0
                try { $deliveredAt = [int64]$message.deliveredAt } catch {}
                $repeatable = ($messageState -eq 'delivered' -and $attempts -lt 3 -and ($now - $deliveredAt) -ge 20)
                if ($messageState -ne 'queued' -and -not $repeatable) { continue }
                $text = ''
                try { $text = [string]$message.text } catch {}
                if ($text.Length -gt 2000) { $text = $text.Substring(0, 1999) + '...' }
                $sentAt = [int64]0
                try { $sentAt = [int64]$message.createdAt } catch {}
                $age = 0
                if ($sentAt -gt 0 -and $now -ge $sentAt) { $age = [int]($now - $sentAt) }
                $views.Add([pscustomobject]@{
                    id           = $(try { [string]$message.id } catch { '' })
                    text         = $text
                    kind         = $(try { [string]$message.kind } catch { 'note' })
                    sentAt       = $sentAt
                    ageSeconds   = $age
                    attempt      = ($attempts + 1)
                })
            }
        } catch {}
        finally { try { [System.Threading.Monitor]::Exit($Shared.UserMessageLock) } catch {} }
        return ,$views
    }

    function Mark-UserMessagesDelivered {
        param([string]$SessionId, $Ids, [string]$ToolName)
        $marked = 0
        $now = Get-UnixSeconds
        try {
            [System.Threading.Monitor]::Enter($Shared.UserMessageLock)
            $state = Read-UserMessageState $SessionId
            if ($null -ne $state) {
                $list = Get-UserMessageList $state
                foreach ($message in $list) {
                    $id = ''
                    try { $id = [string]$message.id } catch {}
                    if ([string]::IsNullOrWhiteSpace($id)) { continue }
                    $hit = $false
                    foreach ($wanted in $Ids) { if ([string]$wanted -eq $id) { $hit = $true; break } }
                    if (-not $hit) { continue }
                    $attempts = 0
                    try { $attempts = [int]$message.attempts } catch {}
                    Set-FlowField $message 'attempts' ($attempts + 1)
                    Set-FlowField $message 'state' 'delivered'
                    Set-FlowField $message 'deliveredAt' $now
                    Set-FlowField $message 'deliveredWith' ([string]$ToolName)
                    $marked = $marked + 1
                    Write-FlowStation 'USERMSG' $id 'DELIVERED' @{ sid = $SessionId; attempt = ($attempts + 1); tool = $ToolName }
                }
                if ($marked -gt 0) {
                    Set-FlowField $state 'updatedAt' $now
                    Save-UserMessageState $SessionId $state
                    Add-ChannelCount 'UserMessagesDelivered' ([long]$marked)
                }
            }
        } catch {}
        finally { try { [System.Threading.Monitor]::Exit($Shared.UserMessageLock) } catch {} }
        return $marked
    }

    function Invoke-AckUserMessage {
        param([string]$SessionId, $ToolArgs)
        $wanted = New-Object System.Collections.Generic.List[string]
        try {
            if ($null -ne $ToolArgs) {
                if ($ToolArgs.PSObject.Properties['ids']) {
                    foreach ($entry in $ToolArgs.ids) {
                        $value = ([string]$entry).Trim()
                        if (-not [string]::IsNullOrWhiteSpace($value)) { $wanted.Add($value) }
                    }
                }
                if ($wanted.Count -eq 0 -and $ToolArgs.PSObject.Properties['id']) {
                    $value = ([string]$ToolArgs.id).Trim()
                    if (-not [string]::IsNullOrWhiteSpace($value)) { $wanted.Add($value) }
                }
                if ($wanted.Count -eq 0 -and $ToolArgs.PSObject.Properties['all'] -and $ToolArgs.all -eq $true) {
                    $list = Get-UserMessageList (Read-UserMessageState $SessionId)
                    foreach ($message in $list) {
                        $state = ''
                        try { $state = [string]$message.state } catch {}
                        if ($state -eq 'queued' -or $state -eq 'delivered') {
                            try { $wanted.Add([string]$message.id) } catch {}
                        }
                    }
                }
            }
        } catch {}
        if ($wanted.Count -eq 0) {
            return @{
                ok = $false
                code = 'BAD_ARGS'
                error = 'ack_user_message needs id, ids or all=true.'
                hint = 'The message ids are in _bridge.userMessages of every response.'
            }
        }
        $acked = 0
        $reply = ''
        $now = Get-UnixSeconds
        $knownIds = New-Object System.Collections.Generic.List[string]
        try {
            [System.Threading.Monitor]::Enter($Shared.UserMessageLock)
            $state = Read-UserMessageState $SessionId
            $list = Get-UserMessageList $state
            foreach ($message in $list) {
                $id = ''
                try { $id = [string]$message.id } catch {}
                if (-not [string]::IsNullOrWhiteSpace($id)) { $knownIds.Add($id) }
            }
            if ($null -ne $state) {
                foreach ($message in $list) {
                    $id = ''
                    try { $id = [string]$message.id } catch {}
                    $hit = $false
                    foreach ($entry in $wanted) { if ([string]$entry -eq $id) { $hit = $true; break } }
                    if (-not $hit) { continue }
                    $messageState = ''
                    try { $messageState = [string]$message.state } catch {}
                    if ($messageState -eq 'acked' -or $messageState -eq 'withdrawn') { continue }
                    Set-FlowField $message 'state' 'acked'
                    Set-FlowField $message 'ackAt' $now
                    $acked = $acked + 1
                    Write-FlowStation 'USERMSG' $id 'ACKED' @{ sid = $SessionId }
                }
                if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['reply']) {
                    $reply = ([string]$ToolArgs.reply).Trim()
                    if ($reply.Length -gt 300) { $reply = $reply.Substring(0, 299) + '...' }
                }
                if ($acked -gt 0 -or -not [string]::IsNullOrWhiteSpace($reply)) {
                    Set-FlowField $state 'updatedAt' $now
                    if (-not [string]::IsNullOrWhiteSpace($reply)) { Set-FlowField $state 'lastAckReply' $reply }
                    Save-UserMessageState $SessionId $state
                    Add-ChannelCount 'UserMessagesAcked' ([long]$acked)
                }
            }
        } catch {}
        finally { try { [System.Threading.Monitor]::Exit($Shared.UserMessageLock) } catch {} }
        if ($acked -eq 0) {
            return @{
                ok = $false
                code = 'ACK_UNKNOWN_MESSAGE'
                error = 'No open user message matched that id.'
                knownMessageIds = @($knownIds.ToArray())
                hint = 'Only messages listed in _bridge.userMessages can be acknowledged.'
            }
        }
        return @{
            ok = $true
            result = @{
                acked = $acked
                replyShownToUser = $reply
                note = 'The bridge shows the user that their message arrived and was read. Now act on it.'
            }
        }
    }

    function Ensure-UserSignal {
        param([string]$SessionId)
        $existing = $null
        try {
            if ($Shared.UserSignals.TryGetValue([string]$SessionId, [ref]$existing) -and $null -ne $existing) { return $existing }
        } catch {}
        $created = [System.Threading.ManualResetEvent]::new($false)
        try { $existing = $Shared.UserSignals.GetOrAdd([string]$SessionId, $created) } catch { $existing = $created }
        if ($null -eq $existing) { $existing = $created }
        if (-not [object]::ReferenceEquals($existing, $created)) { try { $created.Dispose() } catch {} }
        return $existing
    }

    function Invoke-WaitForUser {
        param([string]$SessionId, $ToolArgs)
        $maxSeconds = 30
        try { if ($null -ne $ToolArgs -and $ToolArgs.PSObject.Properties['maxSeconds']) { $maxSeconds = [int]$ToolArgs.maxSeconds } } catch {}
        if ($maxSeconds -lt 1) { $maxSeconds = 1 }
        if ($maxSeconds -gt 50) { $maxSeconds = 50 }
        $flowId = 'wait_' + ([guid]::NewGuid().ToString('N').Substring(0, 8))
        $signal = Ensure-UserSignal $SessionId
        $started = [System.Diagnostics.Stopwatch]::StartNew()
        $reason = 'timeout'
        $views = Get-PendingUserMessageViews $SessionId 3
        if ($views.Count -eq 0) {
            Write-FlowStation 'USERMSG' $flowId 'WAIT_START' @{ sid = $SessionId; maxSeconds = $maxSeconds }
            while ($started.Elapsed.TotalSeconds -lt $maxSeconds) {
                $remaining = [int][Math]::Ceiling($maxSeconds - $started.Elapsed.TotalSeconds)
                $slice = 250
                if (($remaining * 1000) -lt $slice) { $slice = [Math]::Max(20, ($remaining * 1000)) }
                try { [void]$signal.WaitOne($slice) } catch { break }
                $views = Get-PendingUserMessageViews $SessionId 3
                if ($views.Count -gt 0) { $reason = 'user_message'; break }
            }
            try { [void]$signal.Reset() } catch {}
        } else {
            $reason = 'user_message'
        }
        $waited = [int][Math]::Round($started.Elapsed.TotalSeconds, 1)
        Write-FlowStation 'USERMSG' $flowId 'WAIT_END' @{ sid = $SessionId; reason = $reason; waitedSeconds = $waited; messages = $views.Count }
        if ($views.Count -gt 0) {
            $ids = New-Object System.Collections.Generic.List[string]
            foreach ($view in $views) { $ids.Add([string]$view.id) }
            [void](Mark-UserMessagesDelivered $SessionId $ids 'wait_for_user')
        }
        return @{
            ok = $true
            result = @{
                state = $(if ($views.Count -gt 0) { 'messages_waiting' } else { 'timeout' })
                reason = $reason
                waitedSeconds = $waited
                messageCount = $views.Count
                maxSeconds = $maxSeconds
                note = $(if ($views.Count -gt 0) { 'The user messages themselves are in _bridge.userMessages of THIS response. Read them, act on them and acknowledge with ack_user_message.' } else { 'No user message arrived. Continue your work; do not call wait_for_user in a loop.' })
            }
        }
    }

    # Beweis statt Vermutung: Ein Plugin, das deutlich haeufiger pollt als
    # seine eigene Richtlinie erlaubt (> 30 Anfragen je 60 s), wird EINMAL
    # pro 5 Minuten protokolliert. Das kostet pro Anfrage nur wenige
    # Hashtable-Zugriffe und laeuft immer mit.
    function Test-PollRateSane([string]$SessionId) {
        try {
            $perf = $Shared.Perf
            if ($null -eq $perf -or [string]::IsNullOrWhiteSpace($SessionId)) { return }
            $key = 'PollRate:' + $SessionId
            $state = $null
            if ($perf.ContainsKey($key)) { $state = $perf[$key] }
            $nowSeconds = Get-UnixSeconds
            if ($null -eq $state) {
                $state = @{ windowStart = $nowSeconds; count = 0; lastWarn = 0 }
                $perf[$key] = $state
            }
            $state.count = [int]$state.count + 1
            if (($nowSeconds - [int]$state.windowStart) -ge 60) {
                if ([int]$state.count -gt 30 -and ($nowSeconds - [int]$state.lastWarn) -ge 300) {
                    $state.lastWarn = $nowSeconds
                    Write-BridgeLog ('Leistungswarnung: Sitzung ' + $SessionId + ' hat in 60 s ' + [int]$state.count + ' Poll-Anfragen geschickt (Richtlinie: etwa 10-16).')
                }
                $state.windowStart = $nowSeconds
                $state.count = 0
            }
        } catch {}
    }

    function To-Json($obj, [int]$Depth = 30) {
        if ($null -eq $obj) { return 'null' }
        if (($obj -is [System.Array]) -or ($obj -is [System.Collections.IList])) {
            if ($obj.Count -eq 0) { return '[]' }
            if ($obj.Count -eq 1) {
                return ('[' + (To-Json $obj[0] ([Math]::Max(1, $Depth - 1))) + ']')
            }
        }
        $json = $obj | ConvertTo-Json -Depth $Depth -Compress
        if ([string]::IsNullOrEmpty($json)) { return 'null' }
        return [string]$json
    }

    function Update-PollerCount([string]$SessionId, [int]$Delta) {
        if ([string]::IsNullOrWhiteSpace($SessionId)) { return }
        for ($spin = 0; $spin -lt 16; $spin++) {
            $oldVal = [int]0
            if ($Shared.Pollers.TryGetValue($SessionId, [ref]$oldVal)) {
                $newVal = [Math]::Max(0, ([int]$oldVal + $Delta))
                if ($Shared.Pollers.TryUpdate($SessionId, [int]$newVal, [int]$oldVal)) { return }
            } else {
                $initVal = [Math]::Max(0, $Delta)
                if ($Shared.Pollers.TryAdd($SessionId, [int]$initVal)) { return }
            }
        }
    }

    function Get-UnixSeconds {
        [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    }

    # --- WICHTIG: Anfragen IMMER als UTF-8 lesen. -------------------------
    # Vorher wurde $request.ContentEncoding benutzt. Ohne "charset" im
    # Content-Type liefert das unter Windows ANSI (CP1252) - genau dadurch
    # wurde aus "BöseElla" ein "BÃ¶seElla".
    function Read-Body($request) {
        $memory = New-Object System.IO.MemoryStream
        try {
            $request.InputStream.CopyTo($memory)
            $bytes = $memory.ToArray()
        } finally {
            $memory.Dispose()
        }
        if ($bytes.Length -eq 0) { return $null }
        $text = [System.Text.Encoding]::UTF8.GetString($bytes)
        $text = $text.TrimStart([char]0xFEFF)
        if ([string]::IsNullOrWhiteSpace($text)) { return $null }
        try {
            return $text | ConvertFrom-Json
        } catch {
            return $null
        }
    }

    function Send-RawJson($context, [int]$status, [string]$json) {
        $safeJson = if ([string]::IsNullOrEmpty($json)) { 'null' } else { [string]$json }
        $response = $context.Response
        $response.StatusCode = $status
        $response.ContentType = 'application/json; charset=utf-8'
        $response.Headers['Access-Control-Allow-Origin'] = '*'
        $response.Headers['Access-Control-Allow-Headers'] = 'content-type, authorization, x-arena-token'
        $response.Headers['Access-Control-Allow-Methods'] = 'GET, POST, OPTIONS'
        $response.Headers['Cache-Control'] = 'no-store'
        $buffer = [System.Text.Encoding]::UTF8.GetBytes($safeJson)
        $response.ContentLength64 = $buffer.Length
        try {
            if ($context.Request.HttpMethod -ne 'HEAD' -and $buffer.Length -gt 0) {
                $response.OutputStream.Write($buffer, 0, $buffer.Length)
            }
        } catch {}
        try { $response.OutputStream.Close() } catch {}
    }

    function Send-Json($context, [int]$status, $obj) {
        Send-RawJson $context $status (To-Json $obj 40)
    }

    # Hängt Zusatzinformationen an eine fertige JSON-Antwort an, ohne sie
    # neu zu serialisieren (kein Datenverlust bei großen Ergebnissen).
    function Merge-Envelope([string]$json, $envelope) {
        $envJson = To-Json $envelope 20
        $trimmed = $json.TrimStart()
        if ($trimmed.StartsWith('{')) {
            $rest = $trimmed.Substring(1)
            if ($rest.TrimStart().StartsWith('}')) {
                return '{"_bridge":' + $envJson + $rest
            }
            return '{"_bridge":' + $envJson + ',' + $rest
        }
        return '{"_bridge":' + $envJson + ',"ok":true,"result":' + $json + '}'
    }

    # Hängt ein fertiges JSON-Objekt unter einem Namen in eine JSON-Antwort
    # ein, ohne sie neu zu serialisieren (für die Start-Doku).
    function Merge-ExtraJson([string]$json, [string]$key, [string]$valueJson) {
        if ([string]::IsNullOrWhiteSpace($valueJson)) { return $json }
        $extra = '"' + $key + '":' + $valueJson
        $trimmed = $json.TrimStart()
        if ($trimmed.StartsWith('{')) {
            $rest = $trimmed.Substring(1)
            if ($rest.TrimStart().StartsWith('}')) {
                return '{' + $extra + $rest
            }
            return '{' + $extra + ',' + $rest
        }
        return $json
    }

    function Get-Token($request, $body) {
        $auth = $request.Headers['Authorization']
        if ($auth -and $auth -match '^Bearer\s+(.+)$') {
            return $matches[1].Trim()
        }
        $header = $request.Headers['X-Arena-Token']
        if ($header) { return $header.Trim() }
        if ($body -and ($body.PSObject.Properties.Name -contains 'token')) { return [string]$body.token }
        $queryToken = $request.QueryString['token']
        if ($queryToken) { return $queryToken }
        return $null
    }

    function Get-SessionForToken($token) {
        if (-not $token) { return $null }
        # Version 5: the stable aggregate token is intentionally independent
        # from the currently visible number of places.
        if ($Shared.MultiPlaceToken -and [string]$token -eq [string]$Shared.MultiPlaceToken) {
            return '__arena_all_places__'
        }
        $sessionId = $null
        if ($Shared.TokenSessions.TryGetValue($token, [ref]$sessionId)) {
            return $sessionId
        }
        return $null
    }

    function Get-ActiveMultiPlaces {
        $now = Get-UnixSeconds
        $places = New-Object System.Collections.Generic.List[object]
        foreach ($pair in $Shared.Sessions.GetEnumerator()) {
            try {
                $entry = $pair.Value | ConvertFrom-Json
                # Version 5.2: gleich wie die Oberflaeche - Lebenszeichen aus
                # Presence (Edit-Plugin), orphans sofort ausblenden, Limit 30 s.
                $aliveAt = [int64]$entry.lastSeen
                $presence = [int64]0
                $presenceKnown = $false
                if ($Shared.Presence.TryGetValue([string]$entry.sessionId, [ref]$presence)) { $presenceKnown = $true; $aliveAt = $presence }
                if ($entry.orphan -eq $true -and -not $presenceKnown) { continue }
                if ($entry -and ($now - $aliveAt) -lt 30) {
                    $places.Add(@{
                        targetPlace = [string]$entry.sessionId
                        placeName = [string]$entry.placeName
                        placeId = [string]$entry.placeId
                        gameId = [string]$entry.gameId
                        accessMode = [string]$entry.accessMode
                        studio = $entry.state
                        pluginVersion = [string]$entry.pluginVersion
                    })
                }
            } catch {}
        }
        return , @($places | Sort-Object -Property @('placeName','targetPlace'))
    }

    function Resolve-MultiPlaceTarget($body) {
        $wanted = $null
        try { if ($body -and $body.PSObject.Properties['targetPlace']) { $wanted = [string]$body.targetPlace } } catch {}
        try { if ([string]::IsNullOrWhiteSpace($wanted) -and $body -and $body.args -and $body.args.PSObject.Properties['targetPlace']) { $wanted = [string]$body.args.targetPlace } } catch {}
        $places = Get-ActiveMultiPlaces
        if ([string]::IsNullOrWhiteSpace($wanted)) {
            return @{ ok=$false; code='MULTI_PLACE_SELECTION_REQUIRED'; places=$places; error='This is the Alle-Places token of the bridge and no Place was chosen yet - completely normal for a first request (nothing is broken). Call GET /api/places, pick one places[].targetPlace and repeat this request with "targetPlace" set - do this for every /api/tool request afterwards.' }
        }
        $matches = @($places | Where-Object {
            [string]$_.targetPlace -eq $wanted -or [string]$_.placeId -eq $wanted -or [string]$_.placeName -ieq $wanted
        })
        if ($matches.Count -ne 1) {
            return @{ ok=$false; code='MULTI_PLACE_TARGET_NOT_FOUND'; places=$places; error=("targetPlace '" + $wanted + "' is unknown or ambiguous. Use the exact targetPlace value from GET /api/places.") }
        }
        $entry = Get-SessionEntry ([string]$matches[0].targetPlace)
        if (-not $entry) { return @{ ok=$false; code='MULTI_PLACE_TARGET_NOT_FOUND'; places=$places; error='The selected Place disconnected. Refresh GET /api/places and choose again.' } }
        return @{ ok=$true; entry=$entry; places=$places }
    }

    function Get-ArenaActivityBag([string]$sessionId) {
        $bag = $null
        if (-not $Shared.ActivityLogs.TryGetValue($sessionId, [ref]$bag)) {
            $bag = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
            [void]$Shared.ActivityLogs.TryAdd($sessionId, $bag)
            [void]$Shared.ActivityLogs.TryGetValue($sessionId, [ref]$bag)
        }
        return $bag
    }

    function Get-ActivityArgument($args, [string[]]$names, [string]$fallback = '') {
        if ($null -eq $args) { return $fallback }
        foreach ($name in $names) {
            try {
                if ($args -is [System.Collections.IDictionary] -and $args.Contains($name) -and $null -ne $args[$name]) { return [string]$args[$name] }
                if ($args.PSObject.Properties[$name] -and $null -ne $args.$name) { return [string]$args.$name }
            } catch {}
        }
        return $fallback
    }

    function Get-SourceLineCount($args) {
        $source = Get-ActivityArgument $args @('source','text') ''
        if ([string]::IsNullOrEmpty($source)) { return '?' }
        return [string]([Math]::Max(1, (($source -split "`r?`n").Count)))
    }

    function Get-ResultField($result, [string[]]$names) {
        if ($null -eq $result) { return $null }
        foreach ($name in $names) {
            try {
                if ($result -is [System.Collections.IDictionary]) { if ($result.Contains($name) -and $null -ne $result[$name]) { return $result[$name] } }
                elseif ($result.PSObject.Properties[$name] -and $null -ne $result.$name) { return $result.$name }
            } catch {}
        }
        return $null
    }

    function Get-ResultNumber($result, [string[]]$names) {
        $value = Get-ResultField $result $names
        if ($null -eq $value) { return $null }
        try { return [int64]$value } catch { return $null }
    }

    # Version 5.2: vollstaendige Werkzeuglisten (jedes vorhandene Werkzeug).
    # ------------------------------------------------------------------
    # Version 7.0.0: FORTSCHRITTSVERTRAG (progress)
    # Jeder Aufruf traegt progress = { percent = 43, message = "..." } auf
    # derselben Ebene wie token/targetPlace/tool ODER innerhalb von args.
    # Liegt er in args, zieht die Bridge ihn heraus - das Plugin sieht ihn nie.
    # Fehlt er, gilt 0 % (Normalfall beim ersten Aufruf) und es ist NIE ein
    # Fehler. Die Bridge fuehrt je Sitzung Buch und zeigt das ehrlich an.
    # ------------------------------------------------------------------
    function Clamp-ProgressPercent($value) {
        # Version 7.2.0: INVARIANT parsen. Unter deutscher Kultur wurde aus dem
        # String "45.5" die Zahl 455 (Punkt = Tausendertrennzeichen) und der
        # Balken sprang auf 100 %. Zahlen aus JSON bleiben unveraendert sicher.
        $number = 0.0
        try {
            if ($value -is [string]) {
                $text = ([string]$value).Trim().Replace(',', '.')
                if ($text.Length -gt 0) {
                    $parsed = 0.0
                    if ([double]::TryParse($text, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed)) { $number = $parsed }
                }
            } else {
                $number = [double]$value
            }
        } catch { $number = 0.0 }
        if ($number -ne $number) { $number = 0.0 }
        if ($number -lt 0) { $number = 0 }
        if ($number -gt 100) { $number = 100 }
        return [math]::Round($number, 1)
    }

    function Get-ProgressPercentProvided($node) {
        # Version 7.2.0: "Die KI hat eine Zahl geschickt" ist etwas ANDERES als
        # "die Zahl ist 0". Nur eine wirklich mitgeschickte Zahl darf den Balken
        # erscheinen lassen - sonst zeigt die Zeile Klartext ohne erfundene 0 %.
        try {
            if ($null -eq $node) { return $false }
            if ($node -is [string]) {
                $text = ([string]$node).Trim()
                if ($text.Length -eq 0) { return $false }
                $parsed = 0.0
                return [double]::TryParse($text.Replace(',', '.'), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed)
            }
            if ($node -is [ValueType]) { return $true }
            if ($node.PSObject.Properties['percent']) {
                $value = $node.percent
                if ($null -eq $value) { return $false }
                if ($value -is [string] -and [string]::IsNullOrWhiteSpace([string]$value)) { return $false }
                return $true
            }
        } catch {}
        return $false
    }

    function Get-ShortSid([string]$sessionId) {
        $text = ([string]$sessionId).Trim()
        if ($text.Length -le 8) { return $text }
        return $text.Substring(0, 8)
    }

    function Set-ProgressField {
        param($Object, [string]$Name, $Value)
        try {
            if ($null -eq $Object) { return }
            if ($Object.PSObject.Properties[$Name]) { $Object.$Name = $Value }
            else { $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force }
        } catch {}
    }

    function Write-ProgressStationThrottled {
        # Stationen fuer den Fortschritt, gedrosselt: eine Zeile je Sitzung und
        # 30 s fuer "keine Prozentzahl", damit runtime.log nicht vollaeuft
        # (PREVIEW schreibt pro Aufnahmeversuch - Fortschritt kaeme pro Call).
        param([string]$sessionId, [string]$Station, $Fields, [int]$EverySeconds = 30)
        try {
            $key = (Get-ShortSid $sessionId) + ':' + $Station
            $now = Get-UnixSeconds
            $last = [long]0
            if ($Shared.ProgressLogAt.TryGetValue($key, [ref]$last) -and ($now - $last) -lt $EverySeconds) { return }
            $Shared.ProgressLogAt[$key] = $now
            Write-FlowStation 'PROGRESS' (Get-ShortSid $sessionId) $Station $Fields
        } catch {}
    }

    function Read-ProgressState([string]$sessionId) {
        $json = ''
        if (-not $Shared.ProgressStates.TryGetValue([string]$sessionId, [ref]$json)) { return $null }
        if ([string]::IsNullOrWhiteSpace($json)) { return $null }
        try { return ($json | ConvertFrom-Json) } catch { return $null }
    }

    function Save-ProgressState([string]$sessionId, $state) {
        try { $Shared.ProgressStates[[string]$sessionId] = ($state | ConvertTo-Json -Depth 8 -Compress) } catch {}
    }

    function Update-ArenaProgressState {
        # Version 7.2.0: Die Ursache fuer "der Balken bleibt bei 0 %" war, dass
        # percent NUR bei expliziter Zahl gesetzt wurde, eine Nachricht OHNE
        # Zahl percent aber auf 0 ZURUECKgesetzt hat - ein einmal gemeldeter
        # Stand fiel damit bei der naechsten Nachricht wieder auf 0 %. Jetzt
        # wird percent ausschliesslich bei wirklich mitgeschickter Zahl
        # geschrieben ($percentProvided), und der Zustand merkt sich, ob
        # ueberhaupt schon eine Zahl kam (percentKnown). Ohne Zahl zeigt die
        # Oberflaeche keinen Balken und keine erfundene 0 %.
        param([string]$sessionId, [string]$tool, $percent, [string]$message, [bool]$reported, [bool]$isDone, [bool]$autoSet, [bool]$percentProvided = $false)
        $state = Read-ProgressState $sessionId
        if ($null -eq $state) {
            $state = [pscustomobject]@{
                percent = 0.0; message = ''; state = 'working'; updatedAt = 0; lastCallAt = 0
                calls = 0; callsWithProgress = 0; autoSet = $false; history = @(); lastTool = ''
                percentKnown = $false; callsWithPercent = 0; callsWithoutPercent = 0; lastPercentAt = 0
            }
        }
        $now = Get-UnixSeconds
        $state.calls = [int]$state.calls + 1
        $state.lastCallAt = $now
        $state.lastTool = [string]$tool
        Add-ChannelCount 'ProgressCalls' 1
        if (-not $isDone) {
            if ([string]$state.state -eq 'done') {
                $state.percent = 0.0
                $state.message = ''
                $state.autoSet = $false
                Set-ProgressField $state 'percentKnown' $false
            }
            $state.state = 'working'
        }
        if ($reported) {
            $state.callsWithProgress = [int]$state.callsWithProgress + 1
            if ($percentProvided) {
                $state.percent = Clamp-ProgressPercent $percent
                Set-ProgressField $state 'percentKnown' $true
                Set-ProgressField $state 'lastPercentAt' $now
                $withPercent = 0
                try { $withPercent = [int]$state.callsWithPercent } catch {}
                Set-ProgressField $state 'callsWithPercent' ($withPercent + 1)
                Add-ChannelCount 'ProgressWithPercent' 1
                Write-FlowStation 'PROGRESS' (Get-ShortSid $sessionId) 'REPORTED' @{ percent = $state.percent; tool = [string]$tool; message = ([string]$message); callsWithPercent = ($withPercent + 1) }
            } else {
                $withoutPercent = 0
                try { $withoutPercent = [int]$state.callsWithoutPercent } catch {}
                Set-ProgressField $state 'callsWithoutPercent' ($withoutPercent + 1)
                Add-ChannelCount 'ProgressMissingPercent' 1
                Write-ProgressStationThrottled $sessionId 'PERCENT_MISSING' @{ tool = [string]$tool; callsWithoutPercent = ($withoutPercent + 1); message = ([string]$message) } 30
            }
            if (-not [string]::IsNullOrWhiteSpace($message)) { $state.message = $message.Trim() }
            $state.updatedAt = $now
            $state.state = 'working'
            $state.autoSet = $false
        }
        if ($isDone) {
            if (-not $reported) {
                $state.percent = 100.0
                $state.autoSet = $true
                if ([string]::IsNullOrWhiteSpace([string]$state.message)) { $state.message = 'Automatisch gesetzt (report_done ohne Prozentangabe)' }
                $state.updatedAt = $now
                $state.callsWithProgress = [int]$state.callsWithProgress + 1
            }
            $state.percent = 100.0
            $state.state = 'done'
            Set-ProgressField $state 'percentKnown' $true
            Set-ProgressField $state 'lastPercentAt' $now
            Write-FlowStation 'PROGRESS' (Get-ShortSid $sessionId) 'DONE' @{ percent = 100.0; autoSet = [bool]$state.autoSet; tool = [string]$tool }
        }
        $state.updatedAt = $now
        $line = ('{0}% {1} {2}' -f [string]$state.percent, [string]$tool, [string]$state.message).Trim()
        $history = @()
        if ($state.history) { $history = @($state.history) }
        $history = @($line) + $history
        if ($history.Count -gt 12) { $history = $history[0..11] }
        $state.history = $history
        Save-ProgressState $sessionId $state
        return $state
    }


    # ==================================================================
    # Version 7.0.0: UEBERGABE (HANDOFF)
    # Nur fuer ein KOMPLETTES SPIEL oder einen Verbund mehrerer Systeme.
    # Alles andere MUSS in dieser Sitzung fertig werden - eine Uebergabe
    # dafuer wird als HANDOFF_NOT_ALLOWED abgelehnt.
    # Die Bruecke baut den Rahmen (Version, Place, Platzhalter, Audits,
    # offene Punkte aus frueheren Uebergaben, Simulations-/Playtest-Hinweise),
    # Arena fuellt den Inhalt.
    # ==================================================================
    function Format-HandoffList($value, [string]$fallback) {
        if ($null -eq $value) { return @($fallback) }
        $items = @()
        if ($value -is [string]) { $items = @([string]$value) }
        else { foreach ($entry in @($value)) { $items += [string]$entry } }
        $clean = @()
        foreach ($item in $items) { if (-not [string]::IsNullOrWhiteSpace($item)) { $clean += $item.Trim() } }
        if ($clean.Count -eq 0) { return @($fallback) }
        return $clean
    }

    function Invoke-HandoffWrite([string]$sessionId, $toolArgs) {
        $scope = ''
        try { $scope = [string]$toolArgs.scope } catch {}
        if ([string]::IsNullOrWhiteSpace($scope)) { $scope = 'unknown' }
        $scopeKey = $scope.ToLowerInvariant()
        if ($scopeKey -notin @('game', 'full_game', 'fullgame')) {
            return @{
                ok = $false
                code = 'HANDOFF_NOT_ALLOWED'
                error = 'A handoff is ONLY for a complete game or a combination of several systems. A single object, decoration, a scene, a single system or UI work MUST be finished completely in this session.'
                scopeReceived = $scope
                action = 'Finish the rest here. Do not hand off: "der Rest wird fertig, hier."'
            }
        }
        $entry = Get-SessionEntry $sessionId
        $placeName = ''
        $placeId = ''
        $pluginVersion = ''
        if ($entry) {
            $placeName = [string]$entry.placeName
            $placeId = [string]$entry.placeId
            $pluginVersion = [string]$entry.pluginVersion
        }
        if ([string]::IsNullOrWhiteSpace($placeName)) { $placeName = [string]$sessionId }
        $completed = ''
        foreach ($field in @('completed', 'summary', 'etappe1')) { try { if ($toolArgs.PSObject.Properties[$field]) { $completed = [string]$toolArgs.$field } } catch {} }
        $nextSteps = Format-HandoffList (Get-Property -Object $toolArgs -Name @('nextSteps','next_steps','naechsteSchritte')) '(nicht angegeben)'
        $decisions = Format-HandoffList (Get-Property -Object $toolArgs -Name @('decisions','entscheidungen')) '(nicht angegeben)'
        $pitfalls  = Format-HandoffList (Get-Property -Object $toolArgs -Name @('pitfalls','fallstricke')) '(keine)'
        $toolsWorked = Format-HandoffList (Get-Property -Object $toolArgs -Name @('toolsThatWorked','bewaehrteWerkzeuge','bewaehrt')) '(nicht angegeben)'
        $placeholders = Format-HandoffList (Get-Property -Object $toolArgs -Name @('placeholders','platzhalter')) ''
        $untested = Format-HandoffList (Get-Property -Object $toolArgs -Name @('untested','ungetestet')) ''
        $stageIndex = 0; $stageTotal = 0; $stageTitle = ''
        try { $stageIndex = [int](Get-Property -Object $toolArgs -Name @('stageIndex','stage')) } catch {}
        try { $stageTotal = [int](Get-Property -Object $toolArgs -Name @('stageTotal','stages')) } catch {}
        try { $stageTitle = [string](Get-Property -Object $toolArgs -Name @('stageTitle','etappe')) } catch {}
        if ([string]::IsNullOrWhiteSpace($completed)) {
            return @{
                ok = $false
                code = 'HANDOFF_INCOMPLETE'
                error = 'The handoff has no content. Describe what is finished (with proof), then the exact next steps, the binding decisions and the pitfalls.'
                required = @('completed (what is finished, with proof)', 'nextSteps (concrete enough that a chat without memory can follow them)', 'decisions (style, brand colour, skin, naming)', 'pitfalls + toolsThatWorked (honest)')
                note = 'The bridge already fills in version, place, plugin state, audits, placeholders and open points. You fill in the content - and honestly name placeholders, blockouts and untested spots.'
            }
        }
        if ($nextSteps.Count -eq 0 -or $nextSteps[0] -eq '(nicht angegeben)') {
            return @{ ok = $false; code = 'HANDOFF_INCOMPLETE'; error = 'nextSteps is missing: the next session must be able to continue without guessing. Give the following steps in order, each one concrete.' }
        }

        # Rahmen: Audit-Zahlen, Platzhalter, offene Punkte frueherer Uebergaben
        $audit = $null
        $auditJson = ''
        if ($Shared.AuditFlags.TryGetValue([string]$sessionId, [ref]$auditJson) -and -not [string]::IsNullOrWhiteSpace($auditJson)) {
            try { $audit = $auditJson | ConvertFrom-Json } catch { $audit = $null }
        }
        $previousJson = ''
        $previous = $null
        if ($Shared.Handoffs.TryGetValue([string]$sessionId, [ref]$previousJson) -and -not [string]::IsNullOrWhiteSpace($previousJson)) {
            try { $previous = $previousJson | ConvertFrom-Json } catch { $previous = $null }
        }
        $progress = $null
        $progressJson = ''
        if ($Shared.ProgressStates.TryGetValue([string]$sessionId, [ref]$progressJson) -and -not [string]::IsNullOrWhiteSpace($progressJson)) {
            try { $progress = $progressJson | ConvertFrom-Json } catch { $progress = $null }
        }
        $now = Get-Date
        $stamp = $now.ToString('yyyy-MM-dd_HH-mm-ss')
        $safePlace = ($placeName -replace '[^\w\-]+', '_')
        $folder = Join-Path ([string]$Shared.AppDataRoot) 'handoff'
        $path = Join-Path $folder ($safePlace + '-' + $stamp + '.md')
        try { if (-not (Test-Path -LiteralPath $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null } } catch {}

        $md = New-Object System.Text.StringBuilder
        [void]$md.AppendLine('# Uebergabe - ' + $placeName)
        [void]$md.AppendLine('')
        [void]$md.AppendLine('## Rahmen (von der Bruecke gefuellt - nicht raten)')
        [void]$md.AppendLine(('- Bridge/Plugin-Stand: 7.4.1 / ' + $(if ($pluginVersion) { $pluginVersion } else { 'unbekannt' })))
        [void]$md.AppendLine(('- Place: "' + $placeName + '", placeId ' + $(if ($placeId) { $placeId } else { '0' })))
        [void]$md.AppendLine(('- Zeitpunkt: ' + $now.ToString('yyyy-MM-dd HH:mm:ss')))
        [void]$md.AppendLine(('- Etappe: ' + $(if ($stageIndex -gt 0) { [string]$stageIndex + ' von ' + [string]$stageTotal + ' - ' + $stageTitle } else { 'nicht angegeben' })))
        if ($audit) {
            [void]$md.AppendLine(('- Audits: ' + $(if ($audit.summary) { [string]$audit.summary } else { 'keine Zahlen hinterlegt' })))
            [void]$md.AppendLine(('- Offene Platzhalter: ' + [string]$audit.placeholderCount))
            if ($audit.placeholders) { foreach ($p in @($audit.placeholders)) { [void]$md.AppendLine('    - ' + [string]$p) } }
        } else {
            [void]$md.AppendLine('- Audits: keine Messung in dieser Sitzung hinterlegt (ehrlich: nicht gemessen).')
        }
        if ($progress) { [void]$md.AppendLine(('- Fortschritt zuletzt: ' + [string]$progress.percent + ' % - "' + [string]$progress.message + '"')) }
        if ($previous) {
            [void]$md.AppendLine('- Offene Punkte aus frueheren Uebergaben:')
            foreach ($n in @($previous.nextSteps)) { [void]$md.AppendLine('    - ' + [string]$n) }
        }
        [void]$md.AppendLine('')
        [void]$md.AppendLine('## Inhalt (von Arena)')
        [void]$md.AppendLine('')
        [void]$md.AppendLine('### Fertig (mit Belegen)')
        [void]$md.AppendLine($completed)
        [void]$md.AppendLine('')
        [void]$md.AppendLine('### Naechste Schritte (in Reihenfolge)')
        $stepNo = 0
        foreach ($step in $nextSteps) { $stepNo++; [void]$md.AppendLine(('{0}. {1}' -f $stepNo, $step)) }
        [void]$md.AppendLine('')
        [void]$md.AppendLine('### Gueltige Entscheidungen')
        foreach ($d in $decisions) { [void]$md.AppendLine('- ' + $d) }
        [void]$md.AppendLine('')
        [void]$md.AppendLine('### Fallstricke')
        foreach ($p in $pitfalls) { [void]$md.AppendLine('- ' + $p) }
        [void]$md.AppendLine('')
        [void]$md.AppendLine('### Bewaehrte Werkzeugwege')
        foreach ($t in $toolsWorked) { [void]$md.AppendLine('- ' + $t) }
        if ($placeholders.Count -gt 0 -and $placeholders[0] -ne '') {
            [void]$md.AppendLine('')
            [void]$md.AppendLine('### Offene Platzhalter / Blockouts (ehrlich)')
            foreach ($p in $placeholders) { [void]$md.AppendLine('- ' + $p) }
        }
        if ($untested.Count -gt 0 -and $untested[0] -ne '') {
            [void]$md.AppendLine('')
            [void]$md.AppendLine('### Ungetestet')
            foreach ($u in $untested) { [void]$md.AppendLine('- ' + $u) }
        }
        [void]$md.AppendLine('')
        [void]$md.AppendLine('---')
        [void]$md.AppendLine('Dieser Block ist die vollstaendige Uebergabe. Neuen Chat mit Bridge-Zugriff oeffnen und den Block unveraendert senden.')
        $markdown = $md.ToString()
        try { [System.IO.File]::WriteAllText($path, $markdown, (New-Object System.Text.UTF8Encoding($false))) } catch {
            return @{ ok = $false; code = 'HANDOFF_WRITE_FAILED'; error = ('The handoff file could not be written: ' + $_.Exception.Message) }
        }

        $closing = @()
        $closing += ('Etappe ' + $(if ($stageIndex -gt 0) { [string]$stageIndex + ' von ' + [string]$stageTotal } else { '1' }) + ' ist vollstaendig fertig - kein halber Kuchen.')
        $closing += 'Das hier ist ein grosses Projekt, und das schafft niemand in einem Anlauf. Was oben steht, ist eine komplette, gepruefte Etappe: gebaut, gemessen, dokumentiert. Die restlichen Etappen stehen in der Uebergabe, Schritt fuer Schritt, in Reihenfolge.'
        $closing += 'Kein Problem - ich will sofort weiterbauen. Kopier den Block oben, oeffne einen neuen Chat mit Bridge-Zugriff und schick ihn ab. Dort weiss ich in der ersten Sekunde, wo wir stehen, welchen Stil wir benutzen und was als Naechstes drankommt - und lege direkt los.'
        $closing += 'Na los, worauf wartest du?'

        $record = [pscustomobject]@{
            ok = $true
            handoffId = ('ho_' + $stamp)
            place = $placeName
            placeId = $placeId
            path = $path
            stageIndex = $stageIndex
            stageTotal = $stageTotal
            stageTitle = $stageTitle
            markdown = $markdown
            block = $markdown
            closing = $closing
            headline = ('UEBERGABE - Etappe ' + $(if ($stageIndex -gt 0) { [string]$stageIndex } else { '1' }) + ' von ' + $(if ($stageTotal -gt 0) { [string]$stageTotal } else { '?' }) + ' vollstaendig')
            arenaUrl = 'https://arena.ai/agent/'
            chatInstruction = 'Show the biggest available heading with the headline, then the complete block unchanged, then the closing message. Exactly once per turn, never repeated after every tool call.'
            savedAt = $now.ToString('u')
        }
        try { $Shared.Handoffs[[string]$sessionId] = ($record | ConvertTo-Json -Depth 6 -Compress) } catch {}
        try { Add-BridgeEvent $sessionId 'handoff' ('Uebergabe gespeichert: ' + $path) @{ stageIndex = $stageIndex; stageTotal = $stageTotal } } catch {}
        return $record
    }

    function Get-Property($Object, [string[]]$Name) {
        if ($null -eq $Object) { return $null }
        foreach ($n in $Name) {
            try { if ($Object.PSObject.Properties[$n]) { return $Object.$n } } catch {}
        }
        return $null
    }

    function Get-ActivityToolSets {
        $read = @('get_place_info','get_tree','search','get_instance','get_children','get_properties','resolve_ref','get_selection','describe_scene','viewport_info','get_bounds','scene_stats','list_tools','bridge_status','get_script','find_in_script','compile_check','lua_state','raycast','raycast_many','ground_height','measure','measure_height','parts_in_box','parts_in_sphere','nearest_parts','what_is_in_the_way','overlap_check','verify_measurable','coordinate_guide','describe_orientation','union_info','search_assets','asset_details','validate_asset','catalog_status','get_output','wait_for_output','get_errors','sim_status','probe_world','job_status','job_result','list_jobs','get_pending','get_notices','get_events','get_chunk','get_docs','wait','ui_capabilities','ui_skin','ui_audit','ui_texture','world_style','site_survey','variation','model_audit','world_audit','prop_list','wait_for_user','ack_user_message','ask_user','confirm_action','scaffold_ui_scripts')
        $write = @('select_instance','create_instance','bulk_create','clone_instance','delete_instance','bulk_delete','rename_instance','move_instance','group_instances','ungroup','set_property','set_properties','bulk_set_properties','set_attribute','add_tag','remove_tag','patch_script','set_script_source','insert_script','bulk_insert_scripts','run_lua','clear_lua_state','fill_region','build_polygon_model','build_assembly','mesh_slots','mesh_apply','mesh_drop','union','subtract','intersect','separate','insert_asset','apply_asset','clear_output','sim_start','set_context','start_job','cancel_job','batch','parallel','undo','redo','set_waypoint','upload_text','capture_screenshot','report_done','snap_to_ground','point_at','look_at','rotate_around','move_relative','resize_part','fit_between','place_on','align','stack','grid_arrange','distribute','build_surface','build_interface','ui_glow','ui_radial','prop_place','prop_save','refine','style_lock','world_glow')
        return @{ read = $read; write = $write }
    }

    # Version 5.2: Jede abgeschlossene Aktion bekommt einen verstaendlichen
    # deutschen Satz mit den ECHTEN Werten aus dem Werkzeug-Ergebnis.
    # Kein [PLATZHALTER] mehr - schlaegt etwas fehl, steht die Ursache im Satz.
    function Get-ArenaActivityText([string]$tool, $args, [string]$phase, $result) {
        $ref = Get-ActivityArgument $args @('ref','rootRef','parentRef','targetRef','query') 'ein Objekt'
        $sets = Get-ActivityToolSets
        $read = $sets.read
        $writes = $sets.write
        if ($phase -eq 'running') {
            if ($tool -eq 'run_lua') { return 'Arena führt gerade Lua-Code in der Konsole aus.' }
            if ($tool -eq 'patch_script') { return 'Arena bearbeitet gerade das Skript „' + $ref + '“.' }
            if ($tool -eq 'set_script_source') { return 'Arena ersetzt gerade das Skript „' + $ref + '“.' }
            if ($tool -eq 'insert_script' -or $tool -eq 'bulk_insert_scripts') { return 'Arena erstellt gerade ein Skript.' }
            if ($tool -eq 'fill_region' -or $tool -eq 'probe_world') { return 'Arena arbeitet gerade an „' + $tool + '“ (kann etwas dauern).' }
            if ($read -contains $tool) { return 'Arena ruft gerade ' + $tool + ' ab.' }
            if ($writes -contains $tool) { return 'Arena führt gerade ' + $tool + ' aus.' }
            return 'Arena führt gerade „' + $tool + '“ aus.'
        }
        # ---- Aktionen mit echten Zahlen aus dem Ergebnis -------------------
        if ($tool -eq 'patch_script') {
            $oldLines = Get-ResultNumber $result @('oldLines')
            $newLines = Get-ResultNumber $result @('newLines')
            if ($null -ne $oldLines -and $null -ne $newLines) {
                $delta = $newLines - $oldLines
                $deltaText = if ($delta -gt 0) { '+' + [string]$delta } elseif ($delta -lt 0) { [string]$delta } else { '±0' }
                $opCount = $null
                try { $ops = Get-ResultField $result @('operations'); if ($ops) { $opCount = @($ops).Count } } catch {}
                $suffix = if ($null -ne $opCount) { $opCount } else { 1 }
                return 'Hat das Skript „' + $ref + '“ bearbeitet: ' + [string]$oldLines + ' → ' + [string]$newLines + ' Zeilen (' + $deltaText + ' in ' + [string]$suffix + ' Änderung(en)).'
            }
            return 'Hat das Skript „' + $ref + '“ bearbeitet.'
        }
        if ($tool -eq 'set_script_source') {
            $newLines = Get-ResultNumber $result @('lines')
            $oldLines = Get-ResultNumber $result @('previousLines')
            if ($null -ne $newLines -and $null -ne $oldLines) { return 'Hat das Skript „' + $ref + '“ ersetzt: +' + [string]$newLines + ' Zeilen (vorher -' + [string]$oldLines + ' Zeilen).' }
            if ($null -ne $newLines) { return 'Hat das Skript „' + $ref + '“ ersetzt (' + [string]$newLines + ' Zeilen).' }
            return 'Hat das Skript „' + $ref + '“ ersetzt (' + (Get-SourceLineCount $args) + ' Zeilen).'
        }
        if ($tool -eq 'insert_script') {
            $scriptName = Get-ActivityArgument $args @('name') 'Skript'
            $lines = Get-ResultNumber $result @('lines')
            if ($null -ne $lines) { return 'Hat das Skript „' + $scriptName + '“ erstellt (' + [string]$lines + ' Zeilen).' }
            return 'Hat das Skript „' + $scriptName + '“ erstellt (' + (Get-SourceLineCount $args) + ' Zeilen).'
        }
        if ($tool -eq 'bulk_insert_scripts') {
            $createdCount = Get-ResultNumber $result @('count')
            $totalLines = 0
            $hasLines = $false
            try {
                $createdList = Get-ResultField $result @('created')
                if ($createdList) {
                    foreach ($entry in @($createdList)) {
                        $lineCount = Get-ResultNumber $entry @('lines')
                        if ($null -ne $lineCount) { $totalLines += $lineCount; $hasLines = $true }
                    }
                }
            } catch {}
            if ($null -ne $createdCount) {
                if ($hasLines) { return 'Hat ' + [string]$createdCount + ' Skripte erstellt (insgesamt ' + [string]$totalLines + ' Zeilen).' }
                return 'Hat ' + [string]$createdCount + ' Skripte erstellt.'
            }
            return 'Hat mehrere Skripte erstellt.'
        }
        if ($tool -eq 'delete_instance') { return 'Hat „' + $ref + '“ gelöscht.' }
        if ($tool -eq 'bulk_delete') {
            $deletedCount = Get-ResultNumber $result @('count')
            if ($null -ne $deletedCount) { return 'Hat ' + [string]$deletedCount + ' Objekte gelöscht.' }
            return 'Hat mehrere Objekte gelöscht.'
        }
        if ($tool -eq 'clone_instance') {
            $copyCount = Get-ResultNumber $result @('count')
            if ($null -eq $copyCount) { try { $copyCount = [int64](Get-ActivityArgument $args @('count') '1') } catch { $copyCount = 1 } }
            if ([int64]$copyCount -gt 1) { return 'Hat „' + $ref + '“ geklont (' + [string]$copyCount + ' Kopien).' }
            return 'Hat „' + $ref + '“ geklont.'
        }
        if ($tool -eq 'create_instance') {
            $createdName = Get-ActivityArgument $args @('name','className') 'Objekt'
            $itemCount = $null
            try { $itemCount = [int64](Get-ActivityArgument $args @('count') '1') } catch { $itemCount = 1 }
            $resultCount = Get-ResultNumber $result @('count')
            if ($null -ne $resultCount) { $itemCount = $resultCount }
            if ($null -ne $itemCount -and [int64]$itemCount -gt 1) { return 'Hat ' + [string]$itemCount + 'x „' + $createdName + '“ erstellt.' }
            return 'Hat „' + $createdName + '“ erstellt.'
        }
        if ($tool -eq 'bulk_create') {
            $bulkCount = Get-ResultNumber $result @('count')
            if ($null -ne $bulkCount) { return 'Hat ' + [string]$bulkCount + ' Objekte erstellt.' }
            return 'Hat mehrere Objekte erstellt.'
        }
        if ($tool -eq 'run_lua') { return 'Hat ' + (Get-SourceLineCount $args) + ' Zeilen in der Konsole ausgeführt.' }
        if ($tool -eq 'rename_instance') { return 'Hat „' + $ref + '“ in „' + (Get-ActivityArgument $args @('name') '?') + '“ umbenannt.' }
        if ($tool -eq 'group_instances') { return 'Hat Objekte in „' + (Get-ActivityArgument $args @('name') 'einer Gruppe') + '“ gruppiert.' }
        if ($tool -eq 'batch' -or $tool -eq 'parallel') {
            $callCount = $null
            try { $calls = Get-ResultField $args @('commands'); if ($calls) { $callCount = @($calls).Count } } catch {}
            if ($null -ne $callCount) { return 'Hat ' + [string]$callCount + ' Werkzeuge gebündelt ausgeführt.' }
            return 'Hat mehrere Werkzeuge gebündelt ausgeführt.'
        }
        if ($tool -eq 'search') { return 'Hat nach „' + $ref + '“ im Explorer gesucht.' }
        if ($tool -eq 'get_instance') { return 'Hat sich die Instance „' + $ref + '“ angesehen.' }
        if ($tool -eq 'get_children') { return 'Hat die Children von „' + $ref + '“ abgerufen.' }
        if ($tool -eq 'resolve_ref') { return 'Hat den genauen Ablageort von „' + $ref + '“ abgerufen.' }
        if ($tool -eq 'get_script') { return 'Hat den Quelltext von „' + $ref + '“ gelesen.' }
        if ($tool -eq 'find_in_script') { return 'Hat im Skript „' + $ref + '“ gesucht.' }
        if ($tool -eq 'move_relative' -or $tool -eq 'move_instance') { return 'Hat „' + $ref + '“ verschoben.' }
        if ($tool -eq 'resize_part') { return 'Hat die Größe von „' + $ref + '“ geändert.' }
        if ($tool -eq 'snap_to_ground') { return 'Hat „' + $ref + '“ auf dem Boden abgesetzt.' }
        if ($tool -eq 'point_at' -or $tool -eq 'look_at' -or $tool -eq 'align') { return 'Hat „' + $ref + '“ ausgerichtet.' }
        if ($tool -eq 'rotate_around') { return 'Hat „' + $ref + '“ gedreht.' }
        if ($tool -eq 'fit_between') { return 'Hat „' + $ref + '“ zwischen zwei Punkte gespannt.' }
        if ($tool -eq 'place_on') { return 'Hat „' + $ref + '“ platziert.' }
        if ($tool -eq 'sim_start') { return 'Hat den deaktivierten Studio-Run-Start angefragt.' }
        if ($tool -eq 'sim_stop') { return 'Hat die Studio-Run-Simulation beendet.' }
        if ($tool -eq 'sim_status') { return 'Hat den Simulationsstatus gelesen.' }
        # ---- Jeder verbleibende Werkzeugtyp bekommt einen eigenen Satz -----
        $texts = @{
            get_place_info = 'Hat Informationen über den Place abgerufen.'
            get_tree = 'Hat den Explorer des Places abgerufen.'
            get_properties = 'Hat die Properties der ausgewählten Instances abgerufen.'
            get_selection = 'Hat sich die aktuell ausgewählte Instance angesehen.'
            select_instance = 'Hat die angegebenen Objekte ausgewählt.'
            describe_scene = 'Hat die Szene im Place beschrieben.'
            viewport_info = 'Hat Kamerarichtung und Kameraposition abgerufen.'
            get_bounds = 'Hat Größe und Begrenzungen der ausgewählten Objekte abgerufen.'
            scene_stats = 'Hat die Szenenstatistik und Performance-Hinweise abgerufen.'
            list_tools = 'Hat die verfügbaren Bridge-Werkzeuge abgerufen.'
            bridge_status = 'Hat den Status der Bridge abgerufen.'
            raycast = 'Hat einen Strahl geschossen (Raycast).'
            raycast_many = 'Hat mehrere Strahlen geschossen.'
            ground_height = 'Hat Bodenhöhen gemessen.'
            measure = 'Hat eine Distanz gemessen.'
            measure_height = 'Hat eine Höhe gemessen.'
            parts_in_box = 'Hat Teile in einem Bereich gesucht.'
            parts_in_sphere = 'Hat Teile in einem Umkreis gesucht.'
            nearest_parts = 'Hat die nächsten Objekte gesucht.'
            what_is_in_the_way = 'Hat geprüft, was zwischen zwei Punkten im Weg steht.'
            overlap_check = 'Hat eine Kollision geprüft.'
            verify_measurable = 'Hat gewartet, bis Objekte messbar waren.'
            coordinate_guide = 'Hat das Koordinatensystem abgefragt.'
            describe_orientation = 'Hat die Ausrichtung eines Objekts bestimmt.'
            stack = 'Hat Objekte gestapelt.'
            grid_arrange = 'Hat Objekte im Raster angeordnet.'
            distribute = 'Hat Objekte gleichmäßig verteilt.'
            ungroup = 'Hat eine Gruppe aufgelöst.'
            set_property = 'Hat eine Eigenschaft geändert.'
            set_properties = 'Hat Eigenschaften geändert.'
            bulk_set_properties = 'Hat Eigenschaften an vielen Objekten geändert.'
            set_attribute = 'Hat ein Attribut gesetzt.'
            add_tag = 'Hat ein Tag hinzugefügt.'
            remove_tag = 'Hat ein Tag entfernt.'
            compile_check = 'Hat Lua-Code auf Syntaxfehler geprüft.'
            lua_state = 'Hat den Lua-Status abgefragt.'
            clear_lua_state = 'Hat den Lua-Status zurückgesetzt.'
            probe_world = 'Hat die Welt vermessen (Raster-Probe).'
            fill_region = 'Hat einen Bereich gefüllt.'
            build_polygon_model = 'Hat ein Polygon professionell aus dünnen Wedges gebaut.'
            build_assembly = 'Hat ein komplettes Bauteil als Modell in einem Call gebaut.'
            ui_capabilities = 'Hat gemessen, welche modernen UI-Instanzen dieses Studio kann.'
            ui_skin = 'Hat eine GUI-Kunstrichtung gewählt oder den vorhandenen Stil ausgelesen.'
            build_surface = 'Hat eine komposite Oberfläche mit vollem Schichtstapel gebaut.'
            build_interface = 'Hat ein komplettes GUI samt Bewegung in einem Call gebaut.'
            ui_audit = 'Hat das GUI vermessen (Geräte, Kontrast, Anker, Generik-Score).'
            union = 'Hat Teile zu einem Teil verschmolzen.'
            subtract = 'Hat eine Form aus einem Teil herausgestanzt.'
            intersect = 'Hat nur den gemeinsamen Teil behalten.'
            separate = 'Hat eine Union wieder zerlegt.'
            union_info = 'Hat eine Union untersucht.'
            search_assets = 'Hat im Katalog gesucht.'
            asset_details = 'Hat Asset-Details abgerufen.'
            validate_asset = 'Hat ein Asset geprüft.'
            insert_asset = 'Hat ein Asset in den Place eingefügt.'
            apply_asset = 'Hat ein Asset auf ein Objekt gelegt.'
            mesh_slots = 'Hat Mesh-Platzhalter fuer den Blender-Bau angelegt.'
            mesh_apply = 'Hat hochgeladene Meshes in die Platzhalter gesetzt.'
            mesh_drop = 'Hat einen Mesh-Slot storniert (Platzhalter entfernt).'
            mesh_apply_asset = 'Hat hochgeladene Meshes in die Platzhalter gesetzt.'
            catalog_status = 'Hat geprüft, ob der Katalog erreichbar ist.'
            get_output = 'Hat die Ausgabe gelesen.'
            wait_for_output = 'Hat auf eine Ausgabezeile gewartet.'
            clear_output = 'Hat die Ausgabe geleert.'
            get_errors = 'Hat die Fehlerzeilen gelesen.'
            sim_status = 'Hat den Simulationsstatus abgefragt.'
            set_context = 'Hat die Seite (Server/Client) gewechselt.'
            wait = 'Hat im Place gewartet.'
            start_job = 'Hat einen Hintergrundjob gestartet.'
            job_status = 'Hat den Status eines Jobs abgefragt.'
            job_result = 'Hat das Ergebnis eines Jobs abgeholt.'
            list_jobs = 'Hat die Jobs aufgelistet.'
            cancel_job = 'Hat einen Job abgebrochen.'
            get_pending = 'Hat offene Befehle abgefragt.'
            undo = 'Hat die letzte Änderung rückgängig gemacht.'
            redo = 'Hat eine Änderung wiederholt.'
            set_waypoint = 'Hat einen Wiederherstellungspunkt gesetzt.'
            get_notices = 'Hat die Hinweise abgefragt.'
            get_events = 'Hat die Ereignisse abgefragt.'
            get_chunk = 'Hat einen Ergebnis-Teil abgeholt.'
            upload_text = 'Hat Text hochgeladen.'
            get_docs = 'Hat die Dokumentation gelesen.'
            capture_screenshot = 'Hat einen Screenshot gemacht.'
            report_done = 'Hat fertig gemeldet.'
        }
        if ($texts.ContainsKey($tool)) { return [string]$texts[$tool] }
        # Theoretisch unerreichbar - aber falls doch: nie mehr ein Platzhalter.
        if ($read -contains $tool) { return 'Hat „' + $tool + '“ abgerufen.' }
        return 'Hat „' + $tool + '“ ausgeführt.'
    }

    function Get-ArenaActivityKind([string]$tool, [string]$phase, $result) {
        if ($phase -eq 'running') { return 'running' }
        # Version 7.1.2: timed_out/cancelled sind ENDZUSTAENDE und duerfen in
        # der Oberflaeche nie als "Macht gerade" stehen bleiben.
        if ($phase -eq 'failed' -or $phase -eq 'timed_out' -or $phase -eq 'cancelled') { return 'failed' }
        if ($tool -eq 'run_lua') { return 'console' }
        $sets = Get-ActivityToolSets
        if ($sets.read -contains $tool) { return 'read' }
        return 'write'
    }

    function New-ArenaActivity([string]$sessionId, [string]$tool, $args) {
        $id = [guid]::NewGuid().ToString('N')
        $entry = @{ id=$id; tool=$tool; phase='running'; kind='running'; text=(Get-ArenaActivityText $tool $args 'running' $null); startedAt=(Get-UnixSeconds); updatedAt=(Get-UnixSeconds) }
        $bag = Get-ArenaActivityBag $sessionId
        $bag[$id] = (To-Json $entry 12)
        # Keep the in-memory per-process timeline compact.
        if ($bag.Count -gt 400) {
            $oldest = $null
            foreach ($pair in $bag.GetEnumerator()) { try { $candidate=$pair.Value|ConvertFrom-Json; if (-not $oldest -or [int64]$candidate.startedAt -lt [int64]$oldest.startedAt) { $oldest=$candidate } } catch {} }
            if ($oldest) { $discard=$null; [void]$bag.TryRemove([string]$oldest.id,[ref]$discard) }
        }
        return $id
    }

    function Complete-ArenaActivity([string]$sessionId, [string]$activityId, [string]$tool, $args, [string]$resultJson, [string]$terminalPhase = '') {
        if ([string]::IsNullOrWhiteSpace($activityId)) { return }
        $result = $null
        try { if ($resultJson) { $result = $resultJson | ConvertFrom-Json } } catch {}
        $ok = $true
        if ($result -and $result.PSObject.Properties['ok']) { $ok = ([bool]$result.ok) }
        $phase = if ($ok) { 'completed' } else { 'failed' }
        # Version 7.1.2: ein abgelaufener oder abgebrochener Aufruf bekommt
        # einen EIGENEN Endzustand - niemals weiter 'running'.
        if (-not [string]::IsNullOrWhiteSpace($terminalPhase)) { $phase = $terminalPhase; $ok = $false }
        $text = Get-ArenaActivityText $tool $args $phase $result
        if (-not $ok) {
            $code = ''
            $reason = ''
            try { $code = [string]$result.code } catch {}
            try { $reason = [string]$result.error } catch {}
            $germanReason = switch ($code) {
                'COMMAND_DELIVERY_UNCONFIRMED' { 'Das Studio-Plugin hat den Empfang des Befehls innerhalb von 30 s nicht bestätigt.' }
                'EXECUTOR_UNRESPONSIVE'        { 'Das Studio-Plugin sendet keine Lebenszeichen mehr während der Ausführung.' }
                'EXECUTOR_UNAVAILABLE'         { 'Das Studio-Plugin ist derzeit nicht erreichbar.' }
                'EXECUTOR_DROPPED_COMMAND'     { 'Der Befehl ging in der lokalen Plugin-Warteschlange verloren.' }
                'STUDIO_ABANDONED'             { 'Der Befehl hat das Sicherheits-Zeitbudget überschritten und wurde beendet.' }
                'COMMAND_CANCELLED'            { 'Der Befehl wurde abgebrochen.' }
                'INVALID_COMMAND'              { 'Ungültiger Befehl (Tool-Name fehlt oder ist leer).' }
                'STUDIO_TIMEOUT'               { 'Zeitüberschreitung: Studio hat vor Ablauf der HTTP-Frist nicht geantwortet.' }
                'CATALOG_TIMEOUT'              { 'Zeitüberschreitung: Der Roblox-Katalog hat nicht rechtzeitig geantwortet.' }
                'CATALOG_UNAVAILABLE'          { 'Der Roblox-Katalog ist nicht erreichbar.' }
                'TOOLBOX_BUSY'                 { 'Es laufen bereits so viele Katalog-/Asset-Aufrufe wie erlaubt.' }
                'TOOLBOX_IMPORT_IN_FLIGHT'     { 'Es läuft bereits ein Asset-Import für diesen Place.' }
                'TOOLBOX_IMPORT_WEDGED'        { 'Ein Asset-Import hängt in Roblox fest - weitere Importe sind gesperrt. Studio bitte einmal komplett neu starten.' }
                default                        { $reason }
            }
            if ([string]::IsNullOrWhiteSpace($germanReason)) { $germanReason = $code }
            if (-not [string]::IsNullOrWhiteSpace($germanReason)) { $text = '⚠ ' + $text + ' Fehler: ' + $germanReason }
            else { $text = '⚠ ' + $text + ' ist fehlgeschlagen.' }
        }
        $entry = @{ id=$activityId; tool=$tool; phase=$phase; kind=(Get-ArenaActivityKind $tool $phase $result); text=$text; updatedAt=(Get-UnixSeconds) }
        $bag = Get-ArenaActivityBag $sessionId
        $prior = $null
        if ($bag.TryGetValue($activityId,[ref]$prior)) { try { $priorObj=$prior|ConvertFrom-Json; $entry.startedAt=[int64]$priorObj.startedAt } catch { $entry.startedAt=(Get-UnixSeconds) } }
        else { $entry.startedAt=(Get-UnixSeconds) }
        $bag[$activityId] = (To-Json $entry 12)
    }

    function Ensure-Queue($sessionId) {
        $queue = $null
        if (-not $Shared.CommandQueues.TryGetValue($sessionId, [ref]$queue)) {
            $queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
            [void]$Shared.CommandQueues.TryAdd($sessionId, $queue)
            [void]$Shared.CommandQueues.TryGetValue($sessionId, [ref]$queue)
        }
        return , $queue
    }

    function Enqueue-Command($sessionId, $queue, [string]$commandJson) {
        [System.Threading.Monitor]::Enter($Shared.CommandQueueLock)
        try {
            if ($queue.Count -ge 64) { return @{ ok=$false; queueDepth=[int]$queue.Count } }
            $queue.Enqueue($commandJson)
            return @{ ok=$true; queueDepth=[int]$queue.Count }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.CommandQueueLock)
        }
    }

    function Ensure-AgentQueue($sessionId) {
        $queue = $null
        if (-not $Shared.AgentQueues.TryGetValue($sessionId, [ref]$queue)) {
            $queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
            [void]$Shared.AgentQueues.TryAdd($sessionId, $queue)
            [void]$Shared.AgentQueues.TryGetValue($sessionId, [ref]$queue)
        }
        return , $queue
    }

    function Ensure-Signal($sessionId) {
        $signal = $null
        if (-not $Shared.CommandSignals.TryGetValue($sessionId, [ref]$signal)) {
            $signal = New-Object System.Threading.ManualResetEventSlim($false)
            [void]$Shared.CommandSignals.TryAdd($sessionId, $signal)
            [void]$Shared.CommandSignals.TryGetValue($sessionId, [ref]$signal)
        }
        return $signal
    }

    function Ensure-EventQueue($sessionId) {
        $queue = $null
        if (-not $Shared.Events.TryGetValue($sessionId, [ref]$queue)) {
            $queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
            [void]$Shared.Events.TryAdd($sessionId, $queue)
            [void]$Shared.Events.TryGetValue($sessionId, [ref]$queue)
        }
        return , $queue
    }

    function Add-BridgeEvent($sessionId, $kind, $message, $data) {
        $queue = Ensure-EventQueue $sessionId
        $event = @{
            kind    = $kind
            message = $message
            time    = (Get-Date).ToString('u')
            data    = $data
        }
        $queue.Enqueue((To-Json $event 12))
        # Nur die letzten 60 Ereignisse behalten
        while ($queue.Count -gt 60) {
            $dropped = $null
            [void]$queue.TryDequeue([ref]$dropped)
        }
        Write-BridgeLog "Ereignis [$kind] $message"
    }

    function Take-Events($sessionId, [int]$max = 12) {
        $queue = Ensure-EventQueue $sessionId
        $items = New-Object System.Collections.Generic.List[object]
        $itemJson = $null
        while ($items.Count -lt $max -and $queue.TryDequeue([ref]$itemJson)) {
            try { $items.Add(($itemJson | ConvertFrom-Json)) } catch {}
        }
        return , $items
    }

    # ------------------------------------------------------------------
    # PLAY-TESTS ZUVERLAESSIG VERFOLGEN (Version 3.8)
    # ------------------------------------------------------------------
    # Version 5: per-place read-only is deliberately session-local.

    function Test-AiPlayActive($sessionId, [string]$action) {
        # Wahr, wenn die KI vor kurzem genau diese Play-Aktion ausgeloesst hat.
        $intent = $null
        if (-not $Shared.AiPlayIntents.TryGetValue([string]$sessionId, [ref]$intent)) { return $false }
        if ([string]$intent.action -ne $action) { return $false }
        return (((Get-UnixSeconds) - [int64]$intent.at) -le 45)
    }

    function Test-RecentPlayEvent($sessionId, [string]$kind, [long]$now) {
        $last = $null
        if (-not $Shared.LastPlayEvents.TryGetValue([string]$sessionId, [ref]$last)) { return $false }
        return ([string]$last.kind -eq $kind -and ($now - [int64]$last.at) -lt 8)
    }

    function Set-StateField($state, [string]$name, $value) {
        # 4.0.5 LIVE-FIX (Kernursache des haengenden play_stop):
        # $entry.state / Get-StateObject liefern eine Hashtable, der
        # Session-Reporter-Heartbeat dagegen ein PSCustomObject aus
        # ConvertFrom-Json. Bei einem PSCustomObject WIRFT die direkte
        # Zuweisung auf eine noch nicht vorhandene Eigenschaft
        # ("The property 'userPlaytestActive' cannot be found on this
        # object"). Genau das passierte in JEDEM Heartbeat -> 500 ->
        # der Reporter bekam nie seine Befehle. Dieser Setter beherrscht
        # beide Typen.
        if ($null -eq $state) { return }
        if ($state -is [System.Collections.IDictionary]) { $state[$name] = $value; return }
        $state | Add-Member -NotePropertyName $name -NotePropertyValue $value -Force
    }

    function Update-PlayStateTracking {
        # Erkennt Studio-Run- und Play/F5-Uebergaenge auch nach einem Plugin-
        # Neuladen. Nur mode=play gilt als userPlaytestActive; mode=run bleibt
        # ein eigener, serverseitiger Studio-Run-Test.
        param($sessionId, $oldState, $newState)
        if (-not $newState) { return $newState }
        $sid = [string]$sessionId
        $now = Get-UnixSeconds
        $wasRunning = $false
        if ($oldState) { $wasRunning = [bool]$oldState.running }
        $nowRunning = [bool]$newState.running
        if ($wasRunning -ne $nowRunning) {
            if ($nowRunning) {
                $byAi = Test-AiPlayActive $sid 'start'
                $bridgeOwned = ($byAi -or [bool]$newState.simRunning -or [bool]$newState.startedByBridge)
                $who = 'user'
                if ($bridgeOwned) { $who = 'assistant' }
                $Shared.RunOwners[$sid] = $who
                $modeText = [string]$newState.mode
                $isUserPlay = ($modeText -eq 'play' -and -not $bridgeOwned)
                Set-StateField $newState 'userPlaytestActive' $isUserPlay
                if (-not (Test-RecentPlayEvent $sid 'sim_started' $now)) {
                    $Shared.LastPlayEvents[$sid] = @{ kind = 'sim_started'; at = $now }
                    $modeNote = "mode='run' is official Studio Run without a player/client; mode='play' is the separate player Play/F5 test. EditModeActive is false in both, and changes are temporary."
                    Add-BridgeEvent $sid 'sim_started' ("Studio entered " + $modeText + " mode (started by: " + $who + "). " + $modeNote) @{ mode = $modeText; startedBy = $who; detectedBy = 'server' }
                }
            } else {
                $byAi = Test-AiPlayActive $sid 'stop'
                $who = 'user'
                if ($byAi) { $who = 'assistant' }
                $removedOwner = $null
                [void]$Shared.RunOwners.TryRemove($sid, [ref]$removedOwner)
                Set-StateField $newState 'userPlaytestActive' $false
                if (-not (Test-RecentPlayEvent $sid 'sim_stopped' $now)) {
                    $Shared.LastPlayEvents[$sid] = @{ kind = 'sim_stopped'; at = $now }
                    Add-BridgeEvent $sid 'sim_stopped' ("Studio returned to edit mode (stopped by: " + $who + "). Everything from the simulation is discarded - this is normal, not a crash.") @{ stoppedBy = $who; detectedBy = 'server' }
                }
            }
        } elseif ($nowRunning) {
            $owner = $null
            if (-not $Shared.RunOwners.TryGetValue($sid, [ref]$owner)) {
                # Kein Wechsel beobachtet (z. B. Desktop-/Plugin-Neustart):
                # bewahre bekannte Bridge-Eigentuemerschaft aus dem Pluginstatus;
                # sonst gilt die Session sicherheitshalber als nutzer-eigen.
                $owner = 'user'
                if ([bool]$newState.simRunning -or [bool]$newState.startedByBridge) { $owner = 'assistant' }
                $Shared.RunOwners[$sid] = $owner
            }
            if ([string]$owner -eq 'user') {
                Set-StateField $newState 'userPlaytestActive' ([string]$newState.mode -eq 'play')
            } else {
                Set-StateField $newState 'userPlaytestActive' $false
            }
        }
        return $newState
    }

    function New-SimBlockedResult([string]$tool) {
        return @{
            ok = $false
            code = 'SIM_DISABLED'
            reason = 'EDIT_MODE_SIMULATION_UNAVAILABLE'
            severity = 'notice'
            error = "The tool '$tool' is intentionally disabled. The former implementation started official Studio Run and exited Edit mode (EditModeActive=false); the documented Studio API has no supported true Edit-mode physics/script path."
            why = 'This is an intentional limitation, not a bridge failure. The available Studio Run simulation does not meet the requested true Edit-mode behavior.'
            whatStillWorks = 'compile_check, one-off run_lua in the edit place, sim_status, sim_stop for an existing bridge-owned session, all reading/building tools, GUIs, assets, jobs, progress and handoff.'
            howToFix = 'Do not retry sim_start. Continue building and auditing in Edit mode; test live physics/scripts manually in Studio until Roblox provides a supported true Edit-mode API.'
            userHint = 'sim_start ist deaktiviert, weil Studio Run den Edit-Modus verlaesst. Bauen, compile_check und run_lua bleiben verfuegbar.'
        }
    }

    # ------------------------------------------------------------------
    # STUDIO-COMMAND-LIFECYCLE: Ein HTTP-Timeout beendet Arbeit nicht sofort.
    # Plugin-Budget und Server-Watchdog geben die Queue jedoch frei, falls der
    # Executor hängt oder keine Heartbeats mehr sendet. Späte Resultate werden
    # per commandId dedupliziert und im _bridge-Envelope ausgeliefert.
    # ------------------------------------------------------------------
    function Ensure-PendingBag($sessionId) {
        $bag = $null
        if (-not $Shared.PendingCommands.TryGetValue([string]$sessionId, [ref]$bag)) {
            $bag = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
            [void]$Shared.PendingCommands.TryAdd([string]$sessionId, $bag)
            [void]$Shared.PendingCommands.TryGetValue([string]$sessionId, [ref]$bag)
        }
        return , $bag
    }

    function Ensure-LateResults($sessionId) {
        $queue = $null
        if (-not $Shared.LateResults.TryGetValue([string]$sessionId, [ref]$queue)) {
            $queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
            [void]$Shared.LateResults.TryAdd([string]$sessionId, $queue)
            [void]$Shared.LateResults.TryGetValue([string]$sessionId, [ref]$queue)
        }
        return , $queue
    }

    function Add-PendingCommand($sessionId, $commandId, $tool, [int]$budgetSeconds = 90, [long]$queuedAt = 0, [string]$originSessionId = '') {
        $sid = [string]$sessionId
        $id = [string]$commandId
        if ([string]::IsNullOrWhiteSpace($originSessionId)) { $originSessionId = $sid }
        $originSessionId = [string]$originSessionId
        $now = Get-UnixSeconds
        if ($queuedAt -le 0) { $queuedAt = $now }
        $budgetSeconds = [Math]::Max(5, [Math]::Min(300, $budgetSeconds))
        $record = @{
            sessionId = $sid
            commandId = $id
            tool = [string]$tool
            status = 'queued'
            createdAt = $now
            queuedAt = $queuedAt
            deliveredAt = 0
            lastDeliveryAt = 0
            receivedAt = 0
            startedAt = 0
            heartbeatAt = 0
            unackedCount = 0
            deliveryAttempts = 0
            budgetSeconds = $budgetSeconds
            executor = $null
        }
        $bag = Ensure-PendingBag $sid
        $bag[$id] = (To-Json $record 8)
        $Shared.CommandOwners[$id] = $sid
        $Shared.CommandOrigins[$id] = $originSessionId
        $guid = Get-SessionInstanceGuid $sid
        if (-not [string]::IsNullOrWhiteSpace($guid)) { $Shared.CommandInstanceGuids[$id] = $guid }
        $Shared.CommandStates[$id] = (To-Json $record 8)
        Write-BridgeLog ('Befehl eingereiht: tool=' + [string]$tool + ', commandId=' + $id + ', sid=' + $sid + ', budget=' + $budgetSeconds + 's')
    }

    function Remove-PendingCommand($sessionId, $commandId) {
        $bag = Ensure-PendingBag $sessionId
        $removed = $null
        [void]$bag.TryRemove([string]$commandId, [ref]$removed)
        return $removed
    }

    function Get-PendingInfo($sessionId, $commandId) {
        $id = [string]$commandId
        $probe = [string]$sessionId
        for ($hop = 0; $hop -lt 8; $hop++) {
            $bag = Ensure-PendingBag $probe
            $raw = $null
            if ($bag.TryGetValue($id, [ref]$raw)) {
                try { return ($raw | ConvertFrom-Json) } catch {}
            }
            # Version 7.0.5: after a plugin reconnect the record lives in the new
            # session's bag; the caller's session reaches it through this chain.
            $next = $null
            if (-not $Shared.SessionSuccessors.TryGetValue($probe, [ref]$next)) { break }
            $probe = [string]$next
            if ([string]::IsNullOrWhiteSpace($probe) -or $probe -eq $sessionId) { break }
        }
        return $null
    }

    function Save-PendingInfo($sessionId, $commandId, $info) {
        if (-not $info) { return $false }
        $sid = [string]$sessionId
        $id = [string]$commandId
        $bag = Ensure-PendingBag $sid
        $json = To-Json $info 10
        $bag[$id] = $json
        $Shared.CommandStates[$id] = $json
        return $true
    }

    function Get-CommandControlKey($sessionId, $commandId) {
        return ([string]$sessionId + ':' + [string]$commandId)
    }

    function Get-CommandOwner([string]$commandId) {
        $owner = $null
        if ($Shared.CommandOwners.TryGetValue([string]$commandId, [ref]$owner)) { return [string]$owner }
        return $null
    }

    # Version 7.0.5: the session that CALLED the tool. It owns the token the AI
    # keeps using and therefore the lateResults queue; it survives a plugin
    # reconnect that issues a new sessionId.
    function Get-CommandOrigin([string]$commandId) {
        $origin = $null
        if ($Shared.CommandOrigins.TryGetValue([string]$commandId, [ref]$origin) -and
            -not [string]::IsNullOrWhiteSpace([string]$origin)) { return [string]$origin }
        return (Get-CommandOwner $commandId)
    }

    function Get-SessionInstanceGuid([string]$sessionId) {
        $entry = Get-SessionEntry $sessionId
        if ($entry) {
            try { return [string]$entry.instanceGuid } catch {}
        }
        return ''
    }

    # A result/ack may arrive from a session that is not the current owner when
    # the plugin re-registered (new sessionId, same physical window). Then the
    # commandId still points at the same plugin INSTANCE - that is the proof we
    # accept, never a bare "some session claims this id".
    function Test-CommandInstanceMatches([string]$sessionId, [string]$commandId) {
        $expected = $null
        if (-not $Shared.CommandInstanceGuids.TryGetValue([string]$commandId, [ref]$expected)) { return $false }
        $expected = [string]$expected
        if ([string]::IsNullOrWhiteSpace($expected)) { return $false }
        $reporting = Get-SessionInstanceGuid $sessionId
        if ([string]::IsNullOrWhiteSpace($reporting)) { return $false }
        return ($reporting -eq $expected)
    }

    # Deliveries follow the reconnect chain (old session -> new session) so a
    # command queued under the caller's token still reaches the plugin that now
    # polls under a different sessionId. Max 8 hops; a cycle simply stops.
    function Get-DeliverySession([string]$sessionId) {
        $current = [string]$sessionId
        for ($hop = 0; $hop -lt 8; $hop++) {
            $next = $null
            if (-not $Shared.SessionSuccessors.TryGetValue($current, [ref]$next)) { break }
            $next = [string]$next
            if ([string]::IsNullOrWhiteSpace($next) -or $next -eq $current) { break }
            $current = $next
        }
        return $current
    }

    function Register-SessionSuccessor([string]$oldSessionId, [string]$newSessionId) {
        $old = [string]$oldSessionId
        $new = [string]$newSessionId
        if ([string]::IsNullOrWhiteSpace($old) -or [string]::IsNullOrWhiteSpace($new) -or $old -eq $new) { return }
        $Shared.SessionSuccessors[$old] = $new
        # Re-point existing commands of the old session so their results and acks
        # are accepted from the new plugin instance as well.
        $oldBag = $null
        $newBag = Ensure-PendingBag $new
        if ($Shared.PendingCommands.TryGetValue($old, [ref]$oldBag)) {
            $oldGuid = Get-SessionInstanceGuid $old
            foreach ($pair in @($oldBag.GetEnumerator())) {
                $id = [string]$pair.Key
                if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace([string]$pair.Value)) { continue }
                try {
                    $info = $pair.Value | ConvertFrom-Json
                    $info.sessionId = $new
                    $newBag[$id] = (To-Json $info 10)
                    $Shared.CommandStates[$id] = (To-Json $info 10)
                } catch { continue }
                $discard = $null
                [void]$oldBag.TryRemove($id, [ref]$discard)
                if ((Get-CommandOwner $id) -eq $old) { $Shared.CommandOwners[$id] = $new }
                # The caller's own session stays the origin; late results must reach it.
                if (-not $Shared.CommandOrigins.ContainsKey($id)) { $Shared.CommandOrigins[$id] = $old }
                if (-not $Shared.CommandInstanceGuids.ContainsKey($id) -and -not [string]::IsNullOrWhiteSpace($oldGuid)) {
                    $Shared.CommandInstanceGuids[$id] = $oldGuid
                }
            }
        }
        # Move the not-yet-delivered FIFO of the old session to the new one. A
        # command that was never handed out cannot have run, so handing it to the
        # new session is safe and it is NOT replayed twice.
        $oldQueue = Ensure-Queue $old
        $newQueue = Ensure-Queue $new
        $raw = $null
        [System.Threading.Monitor]::Enter($Shared.CommandQueueLock)
        try {
            while ($oldQueue.TryDequeue([ref]$raw)) {
                if (-not [string]::IsNullOrWhiteSpace([string]$raw)) { $newQueue.Enqueue([string]$raw) }
            }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.CommandQueueLock)
        }
        $wake = Ensure-Signal $new
        [void]$wake.Set()
        Add-BridgeEvent $new 'queue_followed' 'Studio reconnected with a new session id; commands that were still waiting were handed over to the new session (nothing was executed twice).' @{ previousSessionId = $old }
    }

    function Save-SessionExecutorState($sessionId, $executor) {
        if (-not $executor) { return }
        try {
            $state = @{
                lastTick = [int64]$executor.lastTick
                runningCommandId = [string]$executor.runningCommandId
                runningTool = [string]$executor.runningTool
                startedAt = [int64]$executor.startedAt
                queueDepth = [int]$executor.queueDepth
                dispatcherBusy = [bool]$executor.dispatcherBusy
                queuedCommandIds = @($executor.queuedCommandIds)
                resultOutbox = if ($null -ne $executor.resultOutbox) { [int]$executor.resultOutbox } else { 0 }
                ackOutbox = if ($null -ne $executor.ackOutbox) { [int]$executor.ackOutbox } else { 0 }
                lastAckAt = if ($null -ne $executor.lastAckAt) { [int64]$executor.lastAckAt } else { 0 }
                lastPollError = if ($null -ne $executor.lastPollError) { [string]$executor.lastPollError } else { '' }
                lastPluginError = if ($null -ne $executor.lastPluginError) { [string]$executor.lastPluginError } else { '' }
                receivedAt = (Get-UnixSeconds)
            }
            $Shared.ExecutorStates[[string]$sessionId] = (To-Json $state 6)
        } catch {}
    }

    function Get-SessionExecutorSnapshot($sessionId) {
        $now = Get-UnixSeconds
        $state = $null
        $raw = $null
        if ($Shared.ExecutorStates.TryGetValue([string]$sessionId, [ref]$raw)) {
            try { $state = $raw | ConvertFrom-Json } catch {}
        }
        $entry = Get-SessionEntry $sessionId
        $lastSeen = 0
        if ($entry) { try { $lastSeen = [int64]$entry.lastSeen } catch {} }
        $lastTick = 0
        $receivedAt = 0
        if ($state) {
            try { $lastTick = [int64]$state.lastTick } catch {}
            try { $receivedAt = [int64]$state.receivedAt } catch {}
        }
        $sessionAlive = ($lastSeen -gt 0 -and ($now - $lastSeen) -le 30)
        $executorFresh = ($state -and $lastTick -gt 0 -and ($now - $lastTick) -le 12 -and ($now - $receivedAt) -le 30)
        return @{
            alive = [bool]($sessionAlive -and $executorFresh)
            sessionAlive = [bool]$sessionAlive
            lastSeen = $lastSeen
            lastTick = $lastTick
            stateReceivedAt = $receivedAt
            runningCommandId = if ($state) { [string]$state.runningCommandId } else { '' }
            runningTool = if ($state) { [string]$state.runningTool } else { '' }
            startedAt = if ($state) { [int64]$state.startedAt } else { 0 }
            queueDepth = if ($state) { [int]$state.queueDepth } else { 0 }
            dispatcherBusy = if ($state) { [bool]$state.dispatcherBusy } else { $false }
            queuedCommandIds = if ($state -and $state.queuedCommandIds) { @($state.queuedCommandIds) } else { @() }
            resultOutbox = if ($state -and $null -ne $state.resultOutbox) { [int]$state.resultOutbox } else { 0 }
            ackOutbox = if ($state -and $null -ne $state.ackOutbox) { [int]$state.ackOutbox } else { 0 }
            lastAckAt = if ($state -and $null -ne $state.lastAckAt) { [int64]$state.lastAckAt } else { 0 }
            lastPollError = if ($state -and $null -ne $state.lastPollError) { [string]$state.lastPollError } else { '' }
            lastPluginError = if ($state -and $null -ne $state.lastPluginError) { [string]$state.lastPluginError } else { '' }
        }
    }

    function Queue-LateResult($sessionId, $commandId, [string]$json, $pendingInfo) {
        $queue = Ensure-LateResults $sessionId
        $result = $null
        try { $result = $json | ConvertFrom-Json } catch { $result = @{ rawResult=$json } }
        $age = 0
        $tool = $null
        if ($pendingInfo) {
            try { $tool = [string]$pendingInfo.tool } catch {}
            try { if ($pendingInfo.createdAt) { $age = [int][Math]::Max(0, (Get-UnixSeconds) - [int64]$pendingInfo.createdAt) } elseif ($pendingInfo.startedAt) { $age = [int][Math]::Max(0, (Get-UnixSeconds) - [int64]$pendingInfo.startedAt) } } catch {}
        }
        $queue.Enqueue((To-Json @{ tool=$tool; commandId=[string]$commandId; seconds=$age; result=$result } 40))
        while ($queue.Count -gt 60) { $discard=$null; [void]$queue.TryDequeue([ref]$discard) }
    }

    function Take-LateResults($sessionId) {
        $queue = Ensure-LateResults $sessionId
        $items = New-Object System.Collections.Generic.List[object]
        $raw = $null
        while ($items.Count -lt 30 -and $queue.TryDequeue([ref]$raw)) {
            try { $items.Add(($raw | ConvertFrom-Json)) } catch {}
        }
        return , $items
    }

    function Remove-CommandFromQueue($sessionId, $commandId) {
        $queue = Ensure-Queue $sessionId
        $kept = New-Object System.Collections.Generic.List[string]
        [System.Threading.Monitor]::Enter($Shared.CommandQueueLock)
        try {
            $raw = $null
            while ($queue.TryDequeue([ref]$raw)) {
                $drop = $false
                try {
                    $item = $raw | ConvertFrom-Json
                    if ([string]$item.id -eq [string]$commandId) { $drop = $true }
                } catch {}
                if (-not $drop) { $kept.Add([string]$raw) }
            }
            foreach ($itemJson in $kept) { $queue.Enqueue($itemJson) }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.CommandQueueLock)
        }
    }

    function Complete-CommandResult($sessionId, $commandId, [string]$resultJson, [string]$source = 'plugin') {
        $sid = [string]$sessionId
        $id = [string]$commandId
        $owner = Get-CommandOwner $id
        if ([string]::IsNullOrWhiteSpace($owner) -or $owner -ne $sid) { return $false }
        $dedupeKey = Get-CommandControlKey $sid $id
        $completedAt = Get-UnixSeconds
        $pendingInfo = Get-PendingInfo $sid $id
        $discardPayload = $null
        [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
        try {
            $parsed = $resultJson | ConvertFrom-Json
            if ($parsed -and $parsed.PSObject.Properties['commandId'] -and [string]$parsed.commandId -ne $id) {
                return $false
            }
            if ($parsed -and -not $parsed.PSObject.Properties['commandId']) {
                $parsed | Add-Member -NotePropertyName 'commandId' -NotePropertyValue $id -Force
                $resultJson = To-Json $parsed 40
            }
        } catch {
            $parsed = @{ ok=$false; code='RUNTIME_ERROR'; error='The Studio result was not valid JSON.'; commandId=$id }
            $resultJson = To-Json $parsed 8
        }
        # Version 7.1.0: Selbstheilung bei Verlust von received_batch / started.
        # Wenn das Plugin ein Ergebnis liefert, ist der Empfang und die Ausfuehrung
        # damit bewiesen - fehlende Zwischen-Zeitstempel werden geheilt.
        if ($source -eq 'plugin' -and $pendingInfo) {
            try {
                if (-not $pendingInfo.deliveredAt -or [int64]$pendingInfo.deliveredAt -le 0) {
                    $pendingInfo | Add-Member -NotePropertyName 'deliveredAt' -NotePropertyValue $completedAt -Force
                }
                if (-not $pendingInfo.receivedAt -or [int64]$pendingInfo.receivedAt -le 0) {
                    $pendingInfo | Add-Member -NotePropertyName 'receivedAt' -NotePropertyValue $completedAt -Force
                }
                if (-not $pendingInfo.startedAt -or [int64]$pendingInfo.startedAt -le 0) {
                    $pendingInfo.startedAt = $completedAt
                }
                $pendingInfo | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
            } catch {}
        }
        if (-not $Shared.CompletedCommandIds.TryAdd($dedupeKey, $completedAt)) {
            # Falls der Befehl zuvor vom Waechter als COMMAND_DELIVERY_UNCONFIRMED
            # abgebrochen wurde und das echte Plugin-Ergebnis verspaetet eintrifft,
            # stellen wir es trotzdem als LateResult zu (Selbstheilung).
            if ($source -eq 'plugin') {
                $priorStateRaw = $null
                if ($Shared.CommandStates.TryGetValue($id, [ref]$priorStateRaw)) {
                    try {
                        $priorState = $priorStateRaw | ConvertFrom-Json
                        if ([string]$priorState.status -eq 'abandoned') {
                            Queue-LateResult (Get-CommandOrigin $id) $id $resultJson $priorState
                            Write-BridgeLog ('Befehl nachtraeglich vom Plugin beantwortet (Selbstheilung nach Abbruch): commandId=' + $id + ', tool=' + [string]$priorState.tool)
                            return $true
                        }
                    } catch {}
                }
            }
            return $false
        }

        $tool = ''
        if ($pendingInfo) { try { $tool = [string]$pendingInfo.tool } catch {} }
        if ([string]::IsNullOrWhiteSpace($tool) -and $parsed -and $parsed.PSObject.Properties['tool']) {
            $tool = [string]$parsed.tool
        }
        $deliveredStamp = if ($pendingInfo -and $pendingInfo.deliveredAt) { [int64]$pendingInfo.deliveredAt } elseif ($source -eq 'plugin') { $completedAt } else { 0 }
        $receivedStamp  = if ($pendingInfo -and $pendingInfo.receivedAt) { [int64]$pendingInfo.receivedAt } elseif ($source -eq 'plugin') { $completedAt } else { 0 }
        $startedStamp   = if ($pendingInfo -and $pendingInfo.startedAt) { [int64]$pendingInfo.startedAt } elseif ($source -eq 'plugin') { $completedAt } else { 0 }
        $finalState = @{
            sessionId = $sid
            commandId = $id
            tool = $tool
            status = if ($parsed -and $parsed.ok -eq $true) { 'completed' } elseif ($source -eq 'cancelled' -or ($parsed -and [string]$parsed.code -eq 'COMMAND_CANCELLED')) { 'cancelled' } elseif ($source -ne 'plugin' -or ($parsed -and [string]$parsed.code -in @('STUDIO_ABANDONED','EXECUTOR_UNRESPONSIVE','EXECUTOR_UNAVAILABLE','EXECUTOR_DROPPED_COMMAND','COMMAND_DELIVERY_UNCONFIRMED','QUEUE_EXPIRED'))) { 'abandoned' } else { 'failed' }
            createdAt = if ($pendingInfo -and $pendingInfo.createdAt) { [int64]$pendingInfo.createdAt } else { $completedAt }
            queuedAt = if ($pendingInfo -and $pendingInfo.queuedAt) { [int64]$pendingInfo.queuedAt } else { 0 }
            deliveredAt = $deliveredStamp
            receivedAt = $receivedStamp
            startedAt = $startedStamp
            finishedAt = $completedAt
            durationSeconds = if ($startedStamp -gt 0) { [Math]::Max(0, $completedAt - $startedStamp) } else { 0 }
            source = $source
            resultCode = if ($parsed -and $parsed.code) { [string]$parsed.code } else { '' }
        }
        $Shared.CommandStates[$id] = (To-Json $finalState 8)
        Write-BridgeLog ('Befehl abgeschlossen: tool=' + $tool + ', commandId=' + $id + ', status=' + [string]$finalState.status + ', code=' + [string]$finalState.resultCode + ', quelle=' + $source + ', dauer=' + [string]$finalState.durationSeconds + 's')
        # Version 7.0.6: Die Historie haelt das Endergebnis fest, damit
        # GET /api/queue auch nach dem Entfernen des offenen Eintrags zeigt,
        # wie der Befehl geendet hat (finishedAt/abandonedAt + Code).
        Add-CommandHistory $sid $id $tool ([string]$finalState.status) ("finished at " + [string]$completedAt + " (" + [string]$finalState.resultCode + ")")
        # Keep any outstanding cancellation request until the plugin acknowledges
        # it; removing it here would make queue cancel/reset a no-op in Studio.

        $activityMapJson = $null
        if ($Shared.ActivityCommandMap.TryRemove($id, [ref]$activityMapJson)) {
            try {
                $activityMap = $activityMapJson | ConvertFrom-Json
                Complete-ArenaActivity ([string]$activityMap.sessionId) ([string]$activityMap.activityId) ([string]$activityMap.tool) $activityMap.args $resultJson
            } catch {}
        }

        $signal = $null
        [System.Threading.Monitor]::Enter($Shared.CommandResultLock)
        try {
            $hasWaiter = $Shared.ResultSignals.TryGetValue($id, [ref]$signal)
            if ($hasWaiter) {
                $Shared.CommandResults[$id] = $resultJson
                try { [void]$signal.Set() } catch {}
            } else {
                # Version 7.0.5: late results always go to the CALLER session, so a
                # reconnect (which changes the executing session) cannot hide them.
                Queue-LateResult (Get-CommandOrigin $id) $id $resultJson $pendingInfo
            }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.CommandResultLock)
        }
        Remove-PendingCommand $sid $id | Out-Null
        Remove-CommandFromQueue $sid $id
        $removedGuid = $null
        [void]$Shared.CommandInstanceGuids.TryRemove($id, [ref]$removedGuid)
        return $true
    }

    function Mark-CommandAbandoned($sessionId, $commandId, [string]$reasonCode, [string]$reason) {
        $sid = [string]$sessionId
        $id = [string]$commandId
        $info = Get-PendingInfo $sid $id
        if (-not $info) { return $false }
        $discardPayload = $null
        [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
        # The command must not keep running in Studio either: request a cancel for
        # every session on the reconnect chain that may be executing it.
        $cancelSid = $sid
        while (-not [string]::IsNullOrWhiteSpace($cancelSid)) {
            $cancelKey = Get-CommandControlKey $cancelSid $id
            $Shared.CancelRequests[$cancelKey] = Get-UnixSeconds
            $nextSid = $null
            if (-not $Shared.SessionSuccessors.TryGetValue([string]$cancelSid, [ref]$nextSid)) { break }
            $cancelSid = [string]$nextSid
        }
        $info.status = 'abandoned'
        $info | Add-Member -NotePropertyName 'abandonedAt' -NotePropertyValue (Get-UnixSeconds) -Force
        $info | Add-Member -NotePropertyName 'abandonReason' -NotePropertyValue $reasonCode -Force
        $info | Add-Member -NotePropertyName 'lastError' -NotePropertyValue ($reasonCode + ': ' + $reason) -Force
        # Version 7.0.5: after a reconnect the record and the queue entry belong to
        # the successor session; the caller session reaches them through the chain.
        $ownerSid = Get-CommandOwner $id
        if ([string]::IsNullOrWhiteSpace($ownerSid)) { $ownerSid = $sid }
        Save-PendingInfo $ownerSid $id $info | Out-Null
        Remove-CommandFromQueue $ownerSid $id
        $seconds = 0
        try {
            $start = [int64]$info.startedAt
            if ($start -le 0) { $start = [int64]$info.queuedAt }
            if ($start -gt 0) { $seconds = [int][Math]::Max(0, (Get-UnixSeconds) - $start) }
        } catch {}
        $unackedCount = 0
        $deliveryAttempts = 0
        try { if ($null -ne $info.unackedCount) { $unackedCount = [int]$info.unackedCount } } catch {}
        try { if ($null -ne $info.deliveryAttempts) { $deliveryAttempts = [int]$info.deliveryAttempts } } catch {}
        $execSnap = Get-SessionExecutorSnapshot $ownerSid
        $pluginDiagnostics = @{
            lastPollError    = [string]$execSnap.lastPollError
            lastPluginError  = [string]$execSnap.lastPluginError
            lastAckAt        = [int64]$execSnap.lastAckAt
            ackOutbox        = [int]$execSnap.ackOutbox
            resultOutbox     = [int]$execSnap.resultOutbox
            unackedCount     = $unackedCount
            deliveryAttempts = $deliveryAttempts
        }
        Write-BridgeLog ('Befehl vom Waechter abgebrochen: tool=' + [string]$info.tool + ', commandId=' + $id + ', code=' + $reasonCode + ', unacked=' + $unackedCount + ', versuche=' + $deliveryAttempts + ', lastPollError=' + [string]$execSnap.lastPollError + ', lastPluginError=' + [string]$execSnap.lastPluginError + ', lastAckAt=' + [int64]$execSnap.lastAckAt + ' | ' + $reason)
        $failure = @{
            ok = $false
            code = $reasonCode
            commandId = $id
            tool = [string]$info.tool
            error = $reason
            workIsLost = $false
            partialChangesPossible = ($info.startedAt -gt 0)
            retrySafe = $false
            elapsedSeconds = $seconds
            budgetSeconds = [int]$info.budgetSeconds
            status = 'abandoned'
            pluginDiagnostics = $pluginDiagnostics
            hint = 'The executor was released so the Studio queue can continue. Inspect the Place before retrying because partial changes may have been applied.'
        }
        return (Complete-CommandResult $ownerSid $id (To-Json $failure 10) $reasonCode)
    }

    function Request-CommandCancel($sessionId, $commandId, [string]$reason = 'Cancelled by the client.') {
        $sid = [string]$sessionId
        $id = [string]$commandId
        $info = Get-PendingInfo $sid $id
        if (-not $info) { return $false }
        $discardPayload = $null
        [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
        $cancelKey = Get-CommandControlKey $sid $id
        $Shared.CancelRequests[$cancelKey] = Get-UnixSeconds
        Remove-CommandFromQueue $sid $id
        $wake = Ensure-Signal $sid
        [void]$wake.Set()
        $failure = @{
            ok = $false
            code = 'COMMAND_CANCELLED'
            commandId = $id
            tool = [string]$info.tool
            error = $reason
            workIsLost = $false
            partialChangesPossible = ($info.startedAt -gt 0)
            retrySafe = $false
            status = 'cancelled'
            hint = 'Cancellation is best-effort and may leave partial changes. Inspect the Place before retrying.'
        }
        return (Complete-CommandResult $sid $id (To-Json $failure 10) 'cancelled')
    }

    # Version 7.0.5: ADMIN-RESET. Marks every pending command of this Place as
    # failed/abandoned, delivers a real answer to every waiter (or as a
    # lateResult), empties the FIFO and asks the plugin to drop its local queue.
    # This is the escape hatch for a wedged queue - it needs no Studio restart.
    function Force-FailSessionQueue($sessionId, [string]$reason = 'The pending Studio queue was cleared through the admin control.', [string]$reasonCode = 'FORCE_CLEARED', [string]$source = 'force_fail') {
        $sid = [string]$sessionId
        $failed = 0
        # Version 7.1.1: Get-PendingCommands gibt ", $liste" zurueck. In
        # @( Get-PendingCommands ... ) wurde die GANZE Liste zu EINEM Element,
        # [string]$item.commandId zur leerzeichen-verbundenen ID-Liste und kein
        # einziger Befehl wurde getroffen (live: 5 Befehle ueberlebten
        # clear_pending). Erst zuweisen, dann die echte Liste iterieren.
        $pendingItems = Get-PendingCommands $sid
        foreach ($item in $pendingItems) {
            $id = [string]$item.commandId
            if ([string]::IsNullOrWhiteSpace($id)) { continue }
            if (Mark-CommandAbandoned $sid $id $reasonCode $reason) { $failed = $failed + 1 }
        }
        $queue = Ensure-Queue $sid
        $raw = $null
        [System.Threading.Monitor]::Enter($Shared.CommandQueueLock)
        try {
            while ($queue.TryDequeue([ref]$raw)) { $raw = $null }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.CommandQueueLock)
        }
        $Shared.ExecutorResetRequests[$sid] = Get-UnixSeconds
        $wake = Ensure-Signal $sid
        [void]$wake.Set()
        try { $Shared.SweepState.Abandoned = [int64]$Shared.SweepState.Abandoned + [int64]$failed } catch {}
        return @{
            ok = $true
            action = $source
            clearedCommands = $failed
            executor = (Get-SessionExecutorSnapshot $sid)
            note = 'Every waiting command was answered with ' + $reasonCode + '. Studio was asked to drop its local queue; a wedged Lua executor can still need a Studio restart.'
        }
    }

    function Reset-SessionQueue($sessionId, [string]$reason = 'The Studio executor queue was manually reset.', [string]$pendingCode = 'COMMAND_CANCELLED') {
        $sid = [string]$sessionId
        [System.Threading.Monitor]::Enter($Shared.CommandQueueLock)
        try {
            # Version 7.1.1: siehe Force-FailSessionQueue - kein @() um den
            # Aufruf, sonst ist $pending ein 1-elementiges Array mit der Liste.
            $pending = Get-PendingCommands $sid
            $resetCount = 0
            foreach ($item in $pending) {
                $resetId = [string]$item.commandId
                if ([string]::IsNullOrWhiteSpace($resetId)) { continue }
                $resetDone = $false
                if ($pendingCode -eq 'COMMAND_CANCELLED') {
                    $resetDone = [bool](Request-CommandCancel $sid $resetId $reason)
                } else {
                    $resetDone = [bool](Mark-CommandAbandoned $sid $resetId $pendingCode $reason)
                }
                if ($resetDone) { $resetCount = $resetCount + 1 }
            }
            $queue = Ensure-Queue $sid
            $raw = $null
            while ($queue.TryDequeue([ref]$raw)) { $raw = $null }
            $Shared.ExecutorResetRequests[$sid] = Get-UnixSeconds
            $wake = Ensure-Signal $sid
            [void]$wake.Set()
            return $resetCount
        } finally {
            [System.Threading.Monitor]::Exit($Shared.CommandQueueLock)
        }
    }

    function Mark-CommandDelivered($sessionId, $commandId) {
        $info = Get-PendingInfo $sessionId $commandId
        if (-not $info -or [string]$info.status -ne 'queued') { return $false }
        $now = Get-UnixSeconds
        $info.status = 'delivered'
        $info | Add-Member -NotePropertyName 'deliveredAt' -NotePropertyValue $now -Force
        $info | Add-Member -NotePropertyName 'lastDeliveryAt' -NotePropertyValue $now -Force
        $info | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
        $info | Add-Member -NotePropertyName 'deliveryAttempts' -NotePropertyValue 1 -Force
        Save-PendingInfo $sessionId $commandId $info | Out-Null
        Write-BridgeLog ('Befehl ans Plugin ausgeliefert (Versuch 1/3): tool=' + [string]$info.tool + ', commandId=' + [string]$commandId + ', sid=' + [string]$sessionId)
        return $true
    }

    function Invoke-SessionExecutorWatchdog($sessionId) {
        $sid = [string]$sessionId
        if ([string]::IsNullOrWhiteSpace($sid)) { return }
        $bag = Ensure-PendingBag $sid
        $now = Get-UnixSeconds
        foreach ($cancelPair in $Shared.CancelRequests.GetEnumerator()) {
            if (($now - [int64]$cancelPair.Value) -gt 1800) {
                $discardCancel = [long]0
                [void]$Shared.CancelRequests.TryRemove([string]$cancelPair.Key, [ref]$discardCancel)
            }
        }
        foreach ($chunkPair in $Shared.ResultChunkAt.GetEnumerator()) {
            if (($now - [int64]$chunkPair.Value) -gt 1800) {
                $discardChunkAt = [long]0
                $discardChunk = $null
                [void]$Shared.ResultChunkAt.TryRemove([string]$chunkPair.Key, [ref]$discardChunkAt)
                [void]$Shared.ResultChunks.TryRemove([string]$chunkPair.Key, [ref]$discardChunk)
            }
        }
        if ($Shared.CompletedCommandIds.Count -gt 1024) {
            foreach ($completedPair in $Shared.CompletedCommandIds.GetEnumerator()) {
                if (($now - [int64]$completedPair.Value) -gt 1800) {
                    $discardCompleted = [long]0
                    [void]$Shared.CompletedCommandIds.TryRemove([string]$completedPair.Key, [ref]$discardCompleted)
                    $separator = ([string]$completedPair.Key).LastIndexOf(':')
                    if ($separator -ge 0) {
                        $completedSid = ([string]$completedPair.Key).Substring(0, $separator)
                        $completedId = ([string]$completedPair.Key).Substring($separator + 1)
                        $discardState = $null
                        [void]$Shared.CommandStates.TryRemove($completedId, [ref]$discardState)
                        [void]$Shared.CommandPayloads.TryRemove($completedId, [ref]$discardState)
                        $ownerValue = $null
                        if ($Shared.CommandOwners.TryGetValue($completedId, [ref]$ownerValue) -and [string]$ownerValue -eq $completedSid) {
                            [void]$Shared.CommandOwners.TryRemove($completedId, [ref]$discardState)
                        }
                    }
                }
            }
        }
        $entry = Get-SessionEntry $sid
        $lastSeen = 0
        if ($entry) { try { $lastSeen = [int64]$entry.lastSeen } catch {} }
        $executorSnapshot = Get-SessionExecutorSnapshot $sid
        foreach ($pair in $bag.GetEnumerator()) {
            $info = $null
            try { $info = $pair.Value | ConvertFrom-Json } catch {}
            if (-not $info) { continue }
            $id = [string]$pair.Key
            $status = [string]$info.status
            if ([string]::IsNullOrWhiteSpace($status)) { $status = 'queued' }
            $queuedAt = 0; $startedAt = 0; $heartbeatAt = 0; $budget = 90
            try { $queuedAt = [int64]$info.queuedAt } catch {}
            try { $startedAt = [int64]$info.startedAt } catch {}
            try { $heartbeatAt = [int64]$info.heartbeatAt } catch {}
            try { $budget = [int]$info.budgetSeconds } catch {}
            if ($status -eq 'delivered') {
                $deliveredAt = 0
                try { $deliveredAt = [int64]$info.deliveredAt } catch {}
                if ($executorSnapshot.alive) {
                    if ([string]$executorSnapshot.runningCommandId -eq $id) {
                        # The batch-receipt or start POST may have been lost even
                        # though the independent executor snapshot proves work began.
                        $executorStartedAt = 0
                        try { $executorStartedAt = [int64]$executorSnapshot.startedAt } catch {}
                        if ($executorStartedAt -le 0) { $executorStartedAt = $now }
                        $info.status = 'started'
                        $info.startedAt = $executorStartedAt
                        $info.heartbeatAt = $now
                        if (-not $info.receivedAt -or [int64]$info.receivedAt -le 0) {
                            $info | Add-Member -NotePropertyName 'receivedAt' -NotePropertyValue $now -Force
                        }
                        $info | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
                        $discardPayload = $null
                        [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
                        Save-PendingInfo $sid $id $info | Out-Null
                        if (($now - $executorStartedAt) -gt ($budget + 15)) {
                            Mark-CommandAbandoned $sid $id 'STUDIO_ABANDONED' ("The Studio command exceeded its $budget-second execution budget. The queue watchdog released it; inspect for partial changes before retrying.") | Out-Null
                        }
                        continue
                    }
                    if (@($executorSnapshot.queuedCommandIds) -contains $id) {
                        # Reconcile the receipt from the plugin's local FIFO.
                        $info.status = 'received'
                        $info | Add-Member -NotePropertyName 'receivedAt' -NotePropertyValue $now -Force
                        $info | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
                        $discardPayload = $null
                        [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
                        Save-PendingInfo $sid $id $info | Out-Null
                        continue
                    }
                }
                if ($deliveredAt -gt 0 -and (($now - $deliveredAt) -gt 30)) {
                    Mark-CommandAbandoned $sid $id 'COMMAND_DELIVERY_UNCONFIRMED' 'The plugin did not acknowledge receiving this command within 30 seconds and its executor snapshot does not contain it. It was abandoned rather than left stuck or replayed.' | Out-Null
                    continue
                }
            } elseif ($status -eq 'received') {
                $receivedAt = 0
                try { $receivedAt = [int64]$info.receivedAt } catch {}
                if ($receivedAt -gt 0 -and $lastSeen -gt 0 -and (($now - $lastSeen) -gt 60) -and (($now - $receivedAt) -gt 60)) {
                    Mark-CommandAbandoned $sid $id 'EXECUTOR_UNAVAILABLE' 'The Studio plugin disconnected after receiving this command but before starting it. It was not replayed automatically.' | Out-Null
                    continue
                }
                $isRunning = ([string]$executorSnapshot.runningCommandId -eq $id)
                if ($isRunning -and $executorSnapshot.alive) {
                    # Reconcile from the independently reported local executor
                    # slot if the per-command started/heartbeat POST was lost.
                    $executorStartedAt = 0
                    try { $executorStartedAt = [int64]$executorSnapshot.startedAt } catch {}
                    if ($executorStartedAt -le 0) { $executorStartedAt = $now }
                    if ($startedAt -le 0) { $startedAt = $executorStartedAt; $info.startedAt = $startedAt }
                    $info.status = 'started'
                    $info.heartbeatAt = $now
                    Save-PendingInfo $sid $id $info | Out-Null
                    if (($now - $startedAt) -gt ($budget + 15)) {
                        Mark-CommandAbandoned $sid $id 'STUDIO_ABANDONED' ("The Studio command exceeded its $budget-second execution budget. The queue watchdog released it; inspect for partial changes before retrying.") | Out-Null
                        continue
                    }
                } elseif ($receivedAt -gt 0 -and (($now - $receivedAt) -gt 30) -and $executorSnapshot.sessionAlive) {
                    if (-not $executorSnapshot.alive) {
                        Mark-CommandAbandoned $sid $id 'EXECUTOR_UNRESPONSIVE' 'The Studio session is still connected, but its executor liveness snapshot stopped advancing after command receipt. The command was abandoned to release the queue.' | Out-Null
                        continue
                    }
                    $inLocalQueue = (@($executorSnapshot.queuedCommandIds) -contains $id)
                    $dispatcherStalled = ([string]::IsNullOrWhiteSpace([string]$executorSnapshot.runningCommandId) -and [int]$executorSnapshot.queueDepth -gt 0)
                    if (-not $inLocalQueue -or $dispatcherStalled) {
                        Mark-CommandAbandoned $sid $id 'EXECUTOR_DROPPED_COMMAND' 'The plugin acknowledged receiving this command, but it is no longer present in the local executor queue or running slot. It was abandoned to prevent a permanent queue blockage.' | Out-Null
                        continue
                    }
                }
            } elseif ($status -eq 'started' -or $status -eq 'running') {
                if ($startedAt -gt 0 -and (($now - $startedAt) -gt ($budget + 15))) {
                    Mark-CommandAbandoned $sid $id 'STUDIO_ABANDONED' ("The Studio command exceeded its $budget-second execution budget. The queue watchdog released it; inspect for partial changes before retrying.") | Out-Null
                    continue
                }
                if ($heartbeatAt -gt 0 -and (($now - $heartbeatAt) -gt 45)) {
                    Mark-CommandAbandoned $sid $id 'EXECUTOR_UNRESPONSIVE' 'Studio stopped sending executor heartbeats for more than 45 seconds. The command was abandoned so the queue can recover; inspect for partial changes before retrying.' | Out-Null
                    continue
                }
            } elseif ($status -eq 'queued' -and $queuedAt -gt 0 -and $lastSeen -gt 0) {
                if (($now - $lastSeen) -gt 60 -and ($now - $queuedAt) -gt 60) {
                    Mark-CommandAbandoned $sid $id 'EXECUTOR_UNAVAILABLE' 'The Studio plugin has not been seen for more than 60 seconds while this command was queued. The command was removed from the queue; reconnect Studio before retrying.' | Out-Null
                } elseif (($now - $lastSeen) -le 15 -and ($now - $queuedAt) -gt 120) {
                    # Version 7.1.1: Das Plugin pollt NACHWEISLICH (lastSeen frisch),
                    # hat den Befehl aber in 120 s nie abgeholt (deliveryAttempts=0).
                    # Das ist kein beschaeftigtes Studio, sondern ein Zustellfehler
                    # (7.1.0: Poll-Schleife brach vor dem Dequeue ab). Statt eines
                    # Zombies fuer 30 Minuten gibt es eine klare Antwort mit Diagnose.
                    $neverAttempts = 0
                    try { if ($null -ne $info.deliveryAttempts) { $neverAttempts = [int]$info.deliveryAttempts } } catch {}
                    if ($neverAttempts -le 0) {
                        Mark-CommandAbandoned $sid $id 'COMMAND_NEVER_DELIVERED' 'The Studio plugin kept polling for more than 120 seconds but never took this command out of the bridge queue (deliveryAttempts=0). The command was released instead of staying queued forever. Check GET /api/queue (timeline.deliveryAttempts) and restart the bridge if this repeats.' | Out-Null
                        continue
                    }
                }
            }
        }
    }

    function Get-PendingCommands($sessionId) {
        Invoke-SessionExecutorWatchdog $sessionId
        $now = Get-UnixSeconds
        $items = New-Object System.Collections.Generic.List[object]
        # Version 7.0.5: a caller session also sees the commands that were handed
        # over to its successor sessions after a Studio reconnect.
        $chain = New-Object System.Collections.Generic.List[string]
        $probe = [string]$sessionId
        for ($hop = 0; $hop -lt 8; $hop++) {
            if ([string]::IsNullOrWhiteSpace($probe)) { break }
            $chain.Add($probe)
            $next = $null
            if (-not $Shared.SessionSuccessors.TryGetValue($probe, [ref]$next)) { break }
            $nextProbe = [string]$next
            if ([string]::IsNullOrWhiteSpace($nextProbe) -or $nextProbe -eq $probe) { break }
            $probe = $nextProbe
        }
        $seenIds = New-Object System.Collections.Generic.HashSet[string]
        foreach ($chainSession in $chain) {
        $bag = Ensure-PendingBag $chainSession
        foreach ($pair in $bag.GetEnumerator()) {
            try {
                if (-not $seenIds.Add([string]$pair.Key)) { continue }
                $info = $pair.Value | ConvertFrom-Json
                $createdAt = [int64]$info.createdAt
                $queuedAt = [int64]$info.queuedAt
                $startedAt = [int64]$info.startedAt
                $heartbeatAt = [int64]$info.heartbeatAt
                $ageSeconds = [int][Math]::Max(0, $now - $createdAt)
                if ($ageSeconds -gt 1800) {
                    Mark-CommandAbandoned $sessionId ([string]$pair.Key) 'QUEUE_EXPIRED' 'The command exceeded the maximum queue-retention time and was removed.' | Out-Null
                    continue
                }
                $items.Add(@{
                    commandId = [string]$pair.Key
                    tool = [string]$info.tool
                    status = if ($info.status) { [string]$info.status } else { 'queued' }
                    seconds = $ageSeconds
                    queuedAt = $queuedAt
                    startedAt = $startedAt
                    heartbeatAt = $heartbeatAt
                    deliveredAt = if ($info.deliveredAt) { [int64]$info.deliveredAt } else { 0 }
                    receivedAt = if ($info.receivedAt) { [int64]$info.receivedAt } else { 0 }
                    unackedCount = if ($null -ne $info.unackedCount) { [int]$info.unackedCount } else { 0 }
                    deliveryAttempts = if ($null -ne $info.deliveryAttempts) { [int]$info.deliveryAttempts } else { 0 }
                    runningSeconds = if ($startedAt -gt 0) { [int][Math]::Max(0, $now - $startedAt) } else { 0 }
                    budgetSeconds = [int]$info.budgetSeconds
                    abandonReason = if ($info.abandonReason) { [string]$info.abandonReason } else { '' }
                    lastError = if ($info.lastError) { [string]$info.lastError } elseif ($info.abandonReason) { [string]$info.abandonReason } else { '' }
                })
            } catch {
                # A malformed legacy value cannot poison following requests.
                $removed = $null; [void]$bag.TryRemove([string]$pair.Key, [ref]$removed)
            }
        }
        }
        return , $items
    }

    function Invoke-PluginCommandState($body) {
        $sid = [string]$body.sessionId
        $id = [string]$body.commandId
        $phase = [string]$body.phase
        if ([string]::IsNullOrWhiteSpace($sid)) { return @{ ok=$false; accepted=$false; error='sessionId is required' } }

        if ($phase -eq 'reset_ack') {
            $resetStamp = [long]0
            [void]$Shared.ExecutorResetRequests.TryRemove($sid, [ref]$resetStamp)
            return @{ ok=$true; accepted=$true; resetPending=$false }
        }
        if ($phase -eq 'cancel_ack') {
            if ([string]::IsNullOrWhiteSpace($id)) { return @{ ok=$false; accepted=$false } }
            $cancelStamp = [long]0
            $cancelled = $Shared.CancelRequests.TryRemove((Get-CommandControlKey $sid $id), [ref]$cancelStamp)
            return @{ ok=$true; accepted=[bool]$cancelled; commandId=$id }
        }
        if ($phase -eq 'received_batch') {
            $received = 0
            $nowAck = Get-UnixSeconds
            foreach ($receivedIdValue in @($body.commandIds)) {
                $receivedId = [string]$receivedIdValue
                if ([string]::IsNullOrWhiteSpace($receivedId)) { continue }
                $discardPayload = $null
                [void]$Shared.CommandPayloads.TryRemove($receivedId, [ref]$discardPayload)
                $receivedOwner = Get-CommandOwner $receivedId
                $targetSid = $sid
                if ($receivedOwner -ne $targetSid) {
                    if (-not (Test-CommandInstanceMatches $targetSid $receivedId)) { continue }
                    $targetSid = $receivedOwner
                }
                $receivedInfo = Get-PendingInfo $targetSid $receivedId
                if (-not $receivedInfo) { continue }
                if ([string]$receivedInfo.status -eq 'delivered' -or [string]$receivedInfo.status -eq 'queued') {
                    $receivedInfo.status = 'received'
                    $receivedInfo | Add-Member -NotePropertyName 'receivedAt' -NotePropertyValue $nowAck -Force
                    $receivedInfo | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
                    Save-PendingInfo $targetSid $receivedId $receivedInfo | Out-Null
                    Write-BridgeLog ('Befehl vom Plugin bestaetigt (received_batch): tool=' + [string]$receivedInfo.tool + ', commandId=' + $receivedId + ', sid=' + $targetSid)
                    $received = $received + 1
                }
            }
            return @{ ok=$true; accepted=$true; received=$received }
        }
        if ([string]::IsNullOrWhiteSpace($id)) { return @{ ok=$false; accepted=$false; error='commandId is required' } }
        $ownerSession = Get-CommandOwner $id
        if ($ownerSession -ne $sid) {
            # Version 7.0.5: started/heartbeat/cancel acks from the same plugin
            # instance are valid after it re-registered with a new sessionId.
            if (-not (Test-CommandInstanceMatches $sid $id)) {
                return @{ ok=$false; accepted=$false; cancelled=$true; commandId=$id }
            }
            $sid = $ownerSession
        }

        $dedupeKey = Get-CommandControlKey $sid $id
        if ($Shared.CompletedCommandIds.ContainsKey($dedupeKey)) {
            return @{ ok=$true; accepted=$false; cancelled=$true; commandId=$id; state='finished' }
        }
        $info = Get-PendingInfo $sid $id
        if (-not $info) { return @{ ok=$true; accepted=$false; cancelled=$true; commandId=$id; state='not_pending' } }
        $cancelStamp = [long]0
        $cancelled = $Shared.CancelRequests.TryGetValue($dedupeKey, [ref]$cancelStamp)

        if ($phase -eq 'started') {
            if ($cancelled) { return @{ ok=$true; accepted=$false; cancelled=$true; commandId=$id; state='cancel_requested' } }
            $discardPayload = $null
            [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
            if ([string]$info.status -in @('queued','delivered','received')) {
                $now = Get-UnixSeconds
                $info.status = 'started'
                $info.startedAt = $now
                $info.heartbeatAt = $now
                if (-not $info.receivedAt -or [int64]$info.receivedAt -le 0) {
                    $info | Add-Member -NotePropertyName 'receivedAt' -NotePropertyValue $now -Force
                }
                $info | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
                $info | Add-Member -NotePropertyName 'startedTool' -NotePropertyValue ([string]$body.tool) -Force
                Save-PendingInfo $sid $id $info | Out-Null
                Write-BridgeLog ('Befehl im Plugin gestartet (started): tool=' + [string]$info.tool + ', commandId=' + $id + ', sid=' + $sid)
            }
            return @{ ok=$true; accepted=$true; cancelled=$false; commandId=$id; startedAt=[int64]$info.startedAt }
        }
        if ($phase -eq 'heartbeat') {
            if ($cancelled) { return @{ ok=$true; accepted=$true; cancelled=$true; commandId=$id } }
            $discardPayload = $null
            [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
            $nowHb = Get-UnixSeconds
            $info.heartbeatAt = $nowHb
            if ([string]$info.status -in @('queued','delivered','received')) {
                $info.status = 'started'
                if (-not $info.startedAt -or [int64]$info.startedAt -le 0) { $info.startedAt = $nowHb }
                if (-not $info.receivedAt -or [int64]$info.receivedAt -le 0) {
                    $info | Add-Member -NotePropertyName 'receivedAt' -NotePropertyValue $nowHb -Force
                }
                $info | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
            }
            Save-PendingInfo $sid $id $info | Out-Null
            return @{ ok=$true; accepted=$true; cancelled=$false; commandId=$id; heartbeatAt=[int64]$info.heartbeatAt }
        }
        return @{ ok=$false; accepted=$false; commandId=$id; error='Unknown command phase.' }
    }

    # Version 7.0.6: kurze, dauerhafte Befehls-Historie je Sitzung.
    function Add-CommandHistory($sessionId, $commandId, $tool, $status, [string]$detail) {
        try {
            $sid = [string]$sessionId
            if ([string]::IsNullOrWhiteSpace($sid)) { return }
            $historyQueue = $null
            if (-not $Shared.CommandHistory.TryGetValue($sid, [ref]$historyQueue)) {
                $historyQueue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
                [void]$Shared.CommandHistory.TryAdd($sid, $historyQueue)
                [void]$Shared.CommandHistory.TryGetValue($sid, [ref]$historyQueue)
            }
            $historyQueue.Enqueue((To-Json @{
                commandId = [string]$commandId
                tool      = [string]$tool
                status    = [string]$status
                at        = (Get-UnixSeconds)
                detail    = [string]$detail
            } 6))
            while ($historyQueue.Count -gt 40) { $dropHistory = $null; [void]$historyQueue.TryDequeue([ref]$dropHistory) }
        } catch {}
    }

    # Version 7.0.6: Kann dieser Place ueberhaupt noch Befehle ausfuehren?
    # Bewusst konservativ: ein offener Poll oder ein frisches Lebenszeichen
    # bedeutet IMMER "erreichbar". Erst wenn nachweislich nichts mehr antwortet
    # UND Arbeit wartet, gilt der Executor als stumm ("wedged") - dann antwortet
    # die Bridge sofort, statt 55 Sekunden in den Timeout zu laufen.
    function Get-StudioDeliveryHealth($sessionId) {
        $sid = [string]$sessionId
        $now = Get-UnixSeconds
        $delivery = Get-DeliverySession $sid
        $executor = Get-SessionExecutorSnapshot $delivery
        $openPolls = 0
        [void]$Shared.Pollers.TryGetValue($delivery, [ref]$openPolls)
        $presenceStamp = [int64]0
        $hasPresence = $Shared.Presence.TryGetValue($delivery, [ref]$presenceStamp)
        $lastSeen = 0
        try { $lastSeen = [int64]$executor.lastSeen } catch {}
        $lastSign = $(if ($hasPresence) { [int64]$presenceStamp } else { [int64]$lastSeen })
        $age = $(if ($lastSign -gt 0) { [int][Math]::Max(0, $now - $lastSign) } else { 999999 })
        $waiting = 0
        $oldestWaiting = 0
        $undelivered = 0
        $bag = $null
        if ($Shared.PendingCommands.TryGetValue($delivery, [ref]$bag)) {
            foreach ($pair in @($bag.GetEnumerator())) {
                try {
                    $info = $pair.Value | ConvertFrom-Json
                    $status = [string]$info.status
                    if ($status -eq 'queued' -or $status -eq 'delivered' -or $status -eq 'received' -or $status -eq 'started' -or $status -eq 'running') {
                        $waiting = $waiting + 1
                        $queuedAt = [int64]$info.queuedAt
                        if ($queuedAt -le 0) { try { $queuedAt = [int64]$info.createdAt } catch {} }
                        if ($queuedAt -gt 0) {
                            $waitAge = [int][Math]::Max(0, $now - $queuedAt)
                            if ($waitAge -gt $oldestWaiting) { $oldestWaiting = $waitAge }
                            # Version 7.1.1: 'queued' seit > 30 s ohne einen einzigen
                            # Zustellversuch, obwohl das Plugin pollt = Zustellfehler
                            # (nicht "Studio beschaeftigt"). Wird im Status sichtbar.
                            if ($status -eq 'queued' -and $waitAge -gt 30 -and $age -le 15) {
                                $attemptCount = 0
                                try { if ($null -ne $info.deliveryAttempts) { $attemptCount = [int]$info.deliveryAttempts } } catch {}
                                if ($attemptCount -le 0) { $undelivered = $undelivered + 1 }
                            }
                        }
                    }
                } catch {}
            }
        }
        # Version 7.1.2: executorAlive MUSS in den Zustand einfliessen.
        # Vorher stand $state auf 'ok', sobald IRGENDEIN HTTP-Kontakt juenger
        # als 15 s war (ein sich oeffnender Poll, ein Heartbeat, ein Ereignis,
        # eine Outbox-Nachlieferung) - und executorAlive wurde ueberhaupt erst
        # ab 45 s Funkstille geprueft. Genau diese Kombination stand im
        # Live-Befund: /api/status meldete delivery.state = ok, waehrend
        # executor.alive = false war. Die Bridge hat damit Gesundheit
        # vorgetaeuscht. Jetzt gibt es dafuer einen eigenen, ehrlichen
        # Zustand 'executor_down'.
        $executorAlive = [bool]$executor.alive
        $executorEverReported = $false
        try { $executorEverReported = ([int64]$executor.stateReceivedAt -gt 0) } catch {}
        $state = 'ok'
        $stateReason = 'open poll or fresh sign of life'
        if (-not $executorAlive -and $waiting -gt 0 -and $oldestWaiting -gt 25) {
            $state = 'wedged'
            $stateReason = 'executor liveness stopped while commands are waiting'
        } elseif (-not $executorAlive -and $age -gt 45) {
            $state = 'wedged'
            $stateReason = 'no sign of life and no executor liveness'
        } elseif (-not $executorAlive -and $executorEverReported) {
            $state = 'executor_down'
            $stateReason = 'the Studio session still talks to the bridge, but its executor liveness tick stopped - do NOT report this place as healthy'
        } elseif ($openPolls -gt 0 -or $age -le 15) {
            $state = 'ok'
        } elseif ($waiting -gt 0 -and $oldestWaiting -gt 25) {
            $state = 'wedged'
            $stateReason = 'no poll and waiting work'
        } elseif ($age -gt 45) {
            $state = 'quiet'
            $stateReason = 'simply no activity'
        }
        $runningTool = ''
        try { $runningTool = [string]$executor.runningTool } catch {}
        $runningSeconds = 0
        try { if ([int64]$executor.startedAt -gt 0) { $runningSeconds = [int][Math]::Max(0, $now - [int64]$executor.startedAt) } } catch {}
        return @{
            state = $state
            deliverySession = $delivery
            secondsSinceLastSign = $age
            openPolls = [int]$openPolls
            waitingCommands = $waiting
            oldestWaitingSeconds = $oldestWaiting
            undeliveredCommands = $undelivered
            runningTool = $runningTool
            runningSeconds = $runningSeconds
            busy = ($runningSeconds -gt 0 -and -not [string]::IsNullOrWhiteSpace($runningTool))
            executorAlive = [bool]$executor.alive
            stateReason = $stateReason
            rule = 'ok = fresh sign of life AND a living executor; executor_down = the session still answers HTTP but the executor liveness tick stopped (never report this as healthy); busy = a tool is running with fresh heartbeats; wedged = no executor liveness plus waiting work or long silence (a blocked Lua VM only a Studio restart frees); quiet = simply no activity.'
        }
    }

    # Version 7.0.6: EINE Antwort, die Deployment und Verbindung beweist.
    # Bewusst OHNE Token erreichbar (nur lokal bzw. ueber den Tunnel), damit sie
    # auch dann hilft, wenn der Token nicht mehr gueltig ist. Sie enthaelt KEINE
    # Tokens - nur gekuerzte Sitzungs-Ids.
    function Get-VersionReport {
        $now = Get-UnixSeconds
        $rt = $Shared.RuntimeInfo
        $tel = $Shared.Telemetry
        $recentCreations = 0
        try {
            foreach ($creationStamp in @($Shared.SessionCreations.ToArray())) {
                if ([int64]$creationStamp -ge ($now - 60)) { $recentCreations = $recentCreations + 1 }
            }
        } catch {}
        $sessions = New-Object System.Collections.Generic.List[object]
        foreach ($pair in $Shared.Sessions.GetEnumerator()) {
            try {
                $sid = [string]$pair.Key
                $entry = $pair.Value | ConvertFrom-Json
                $openPolls = 0
                [void]$Shared.Pollers.TryGetValue($sid, [ref]$openPolls)
                $lastSeen = [int64]$entry.lastSeen
                $executor = Get-SessionExecutorSnapshot $sid
                $pendingCount = 0
                $pendingBag = $null
                if ($Shared.PendingCommands.TryGetValue($sid, [ref]$pendingBag)) { $pendingCount = [int]$pendingBag.Count }
                $sessions.Add(@{
                    sessionIdShort = $(if ($sid.Length -gt 8) { $sid.Substring(0, 8) } else { $sid })
                    placeName = [string]$entry.placeName
                    placeId = [string]$entry.placeId
                    pluginVersion = [string]$entry.pluginVersion
                    pluginOutdated = ([string]$entry.pluginVersion -ne [string]$Shared.DocsVersion)
                    secondsSinceLastSeen = [int][Math]::Max(0, $now - $lastSeen)
                    openPolls = [int]$openPolls
                    pendingCommands = $pendingCount
                    executorAlive = [bool]$executor.alive
                    runningTool = [string]$executor.runningTool
                    executorQueueDepth = [int]$executor.queueDepth
                    orphan = [bool]$entry.orphan
                })
            } catch {}
        }
        $sweep = @{
            running = ([int64]$Shared.SweepState.LastSweepAt -gt 0 -and ($now - [int64]$Shared.SweepState.LastSweepAt) -le 10)
            startedAt = [int64]$Shared.SweepState.StartedAt
            lastSweepAt = [int64]$Shared.SweepState.LastSweepAt
            secondsSinceSweep = $(if ([int64]$Shared.SweepState.LastSweepAt -gt 0) { [int][Math]::Max(0, $now - [int64]$Shared.SweepState.LastSweepAt) } else { -1 })
            sweeps = [int64]$Shared.SweepState.Sweeps
            abandonedTotal = [int64]$Shared.SweepState.Abandoned
        }
        return @{
            ok = $true
            bridgeVersion = [string]$Shared.DocsVersion
            deployment = @{
                version = [string]$rt.Version
                file = [string]$rt.File
                sha256 = [string]$rt.Sha256
                sha256Short = $(if ([string]$rt.Sha256 -and ([string]$rt.Sha256).Length -ge 8) { ([string]$rt.Sha256).Substring(0, 8).ToLowerInvariant() } else { '' })
                languageMode = [string]$rt.LanguageMode
                startedAt = [int64]$rt.StartedAt
                runningSeconds = $(if ([int64]$rt.StartedAt -gt 0) { [int][Math]::Max(0, $now - [int64]$rt.StartedAt) } else { 0 })
                logFile = [string]$rt.LogFile
                runtimeLog = [string]$rt.LogFile
                rootFolder = [string]$rt.AppDataRoot
            }
            counters = @{
                hello = [int64]$tel.Hello
                poll = [int64]$tel.Poll
                result = [int64]$tel.Result
                toolCalls = [int64]$tel.ToolCalls
                newSessions = [int64]$tel.NewSessions
                reusedSessions = [int64]$tel.ReusedSessions
                revivedSessions = [int64]$tel.RevivedSessions
                unknownSessionPolls = [int64]$tel.UnknownSessionPolls
                stormWarnings = [int64]$tel.StormWarnings
                fastFailWedged = [int64]$tel.FastFailWedged
                fastFailBusy = [int64]$tel.FastFailBusy
                rowCancels = [int64]$tel.RowCancels
                newSessionsLast60s = [int]$recentCreations
                lastHelloAt = [int64]$tel.LastHelloAt
                lastPollAt = [int64]$tel.LastPollAt
                lastResultAt = [int64]$tel.LastResultAt
                secondsSinceLastPoll = $(if ([int64]$tel.LastPollAt -gt 0) { [int][Math]::Max(0, $now - [int64]$tel.LastPollAt) } else { -1 })
            }
            sweep = $sweep
            preview = @{
                mode = [string]$script:PreviewCaptureMode
                modeReason = [string]$script:PreviewCaptureModeReason
                selfTestVerdict = [string]$script:PreviewSelfTestVerdict
                lastOutcome = [string]$script:PreviewLastOutcome
                lastOutcomeSecondsAgo = $(try { if ($script:PreviewLastOutcomeAt -gt [DateTime]::MinValue) { [int][Math]::Max(0, ((Get-Date) - $script:PreviewLastOutcomeAt).TotalSeconds) } else { -1 } } catch { -1 })
                activeCaptures = @($script:PlacePreviewJobs.Keys).Count
                intervalSeconds = [double]$script:PlacePreviewIntervalSeconds
                targetHeight = [int]$script:PlacePreviewCaptureHeight
                diagnoseFile = $(try { $root = if ([string]$rt.AppDataRoot) { [string]$rt.AppDataRoot } else { [string]$Shared.AppDataRoot }; if ($root) { Join-Path $root 'preview-diagnose.txt' } else { '' } } catch { '' })
                cacheFolder = $(try { $root = if ([string]$rt.AppDataRoot) { [string]$rt.AppDataRoot } else { [string]$Shared.AppDataRoot }; if ($root) { Join-Path $root 'preview-cache' } else { '' } } catch { '' })
                note = 'The window preview never spins silently: the last outcome (ok with pixel size and method, or the exact reason) is reported here and in preview-diagnose.txt. If mode is ps-fallback, the C# helper could not be compiled - modeReason says why.'
            }
            connectedPlaces = $Shared.Sessions.Count
            sessions = $sessions
            verdict = @{
                versionLoaded = [string]$rt.Version
                ifThisIsNotTheVersionYouDeployed = 'The running file is listed under deployment.file with its SHA-256; compare it with the file in the repository (git show origin/main:ArenaBridge.ps1 | sha256sum). A different hash means an old copy is running.'
                pluginOutdated = (@($sessions | Where-Object { $_.pluginOutdated }).Count -gt 0)
                storm = ([int]$recentCreations -ge 6)
                watchdogRunning = [bool]$sweep.running
                hint = 'If sessions stay empty although Studio is open, the plugin never reached the bridge: check that Roblox Studio was restarted after the update (the plugin file is rewritten at every bridge start, but a running Studio keeps the old plugin in memory).'
            }
        }
    }

    # Version 7.1.1: Liefert 0..n Strings FLACH (kein Komma-Operator!). Jeder
    # Aufrufer schreibt @(Get-SessionCancellationIds $sid); mit ", $array"
    # (7.1.0) wurde daraus IMMER ein 1-elementiges Array mit dem (auch leeren)
    # Array als Element -> "$cancelledNow.Count -gt 0" war in /plugin/poll immer
    # wahr, die Schleife brach vor dem Dequeue ab und Studio bekam NIE einen
    # Befehl (live: deliveryAttempts=0, result=0, cancelledCommands=[[]]).
    function Get-SessionCancellationIds($sessionId) {
        $prefix = [string]$sessionId + ':'
        $items = New-Object System.Collections.Generic.List[string]
        foreach ($pair in $Shared.CancelRequests.GetEnumerator()) {
            if ([string]$pair.Key -like ($prefix + '*')) {
                $items.Add(([string]$pair.Key).Substring($prefix.Length))
            }
        }
        if ($items.Count -eq 0) { return @() }
        return $items.ToArray()
    }

    function Get-QueueSnapshot($sessionId) {
        $pending = Get-PendingCommands $sessionId
        $queue = Ensure-Queue $sessionId
        $executor = Get-SessionExecutorSnapshot $sessionId
        $queued = @($pending | Where-Object { $_.status -eq 'queued' })
        $delivered = @($pending | Where-Object { $_.status -eq 'delivered' -or $_.status -eq 'received' })
        $running = @($pending | Where-Object { $_.status -eq 'started' -or $_.status -eq 'running' -or $_.status -eq 'cancel_requested' })
        $sweep = $null
        try {
            $sweep = @{
                lastSweepAt = [int64]$Shared.SweepState.LastSweepAt
                secondsSinceSweep = if ([int64]$Shared.SweepState.LastSweepAt -gt 0) { [int][Math]::Max(0, (Get-UnixSeconds) - [int64]$Shared.SweepState.LastSweepAt) } else { -1 }
                abandonedTotal = [int64]$Shared.SweepState.Abandoned
                running = ([int64]$Shared.SweepState.LastSweepAt -gt 0 -and ((Get-UnixSeconds) - [int64]$Shared.SweepState.LastSweepAt) -le 10)
            }
        } catch {}
        $deliverySession = Get-DeliverySession ([string]$sessionId)
        # Version 7.0.6: Die Zustell-Timeline beantwortet in EINER Anfrage, WO
        # ein Befehl klemmt: queuedAt -> deliveredAt -> receivedAt -> startedAt
        # -> heartbeatAt -> finishedAt. Ohne diese Zeiten war jede Diagnose
        # geraten (H7: kommt der Befehl ueberhaupt an?).
        $timeline = New-Object System.Collections.Generic.List[object]
        # Version 7.1.1: NIE @($liste) um eine List[object] legen - Windows
        # PowerShell 5.1 wirft dafuer "Die Argumenttypen stimmen nicht
        # ueberein." (das war der 500 von /api/status und /api/queue).
        foreach ($item in $pending) {
            $timeline.Add(@{
                commandId = [string]$item.commandId
                tool = [string]$item.tool
                status = [string]$item.status
                seconds = [int]$item.seconds
                queuedAt = [int64]$item.queuedAt
                deliveredAt = [int64]$item.deliveredAt
                receivedAt = [int64]$item.receivedAt
                unackedCount = [int]$item.unackedCount
                deliveryAttempts = [int]$item.deliveryAttempts
                startedAt = [int64]$item.startedAt
                heartbeatAt = [int64]$item.heartbeatAt
                runningSeconds = [int]$item.runningSeconds
                budgetSeconds = [int]$item.budgetSeconds
                lastError = [string]$item.lastError
            })
        }
        $recentCommands = New-Object System.Collections.Generic.List[object]
        try {
            $historyQueue = $null
            if ($Shared.CommandHistory.TryGetValue([string]$sessionId, [ref]$historyQueue)) {
                foreach ($historyRaw in @($historyQueue.ToArray())) {
                    try { $recentCommands.Add(($historyRaw | ConvertFrom-Json)) } catch {}
                }
                while ($recentCommands.Count -gt 12) {
                    $recentCommands.RemoveAt(0)
                }
            }
        } catch {}
        return @{
            ok = $true
            sessionId = [string]$sessionId
            deliverySession = $deliverySession
            queueDepth = [int]$queue.Count
            queued = $queued
            delivered = $delivered
            running = $running
            pending = $pending
            timeline = $timeline
            recent = $recentCommands.ToArray()
            delivery = (Get-StudioDeliveryHealth $sessionId)
            executor = $executor
            sweep = $sweep
            cancelledCommandIds = @(Get-SessionCancellationIds $sessionId)
            resetRequested = $Shared.ExecutorResetRequests.ContainsKey([string]$sessionId)
            timelineRule = 'queuedAt -> deliveredAt -> receivedAt -> startedAt -> heartbeatAt -> finishedAt/abandonedAt. A missing deliveredAt means the plugin never polled the command away; a missing startedAt means it was never started in Studio; a stalled heartbeatAt means the executor stopped reporting.'
        }
    }

    function Get-SessionEntry($sessionId) {
        $json = $null
        if ($Shared.Sessions.TryGetValue($sessionId, [ref]$json)) {
            try { return $json | ConvertFrom-Json } catch { return $null }
        }
        return $null
    }

    function Save-SessionEntry($entry) {
        $Shared.Sessions[[string]$entry.sessionId] = (To-Json $entry 12)
    }

    function New-BridgeToken {
        $bytes = New-Object byte[] 24
        [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($bytes)
        [Convert]::ToBase64String($bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_')
    }

    function Get-StateObject($body) {
        $state = @{ running = $false; mode = 'edit'; context = 'edit' }
        if ($body -and $body.state) {
            $state = @{
                running = [bool]$body.state.running
                mode    = [string]$body.state.mode
                context = [string]$body.state.context
                playerCount = $body.state.playerCount
                sessionPlayers = $body.state.sessionPlayers
                reporterActive = [bool]$body.state.reporterActive
                agentMode = [string]$body.state.agentMode
                httpEnabled = [bool]$body.state.httpEnabled
                editModeActive = $body.state.editModeActive
                agentConnected = [bool]$body.state.agentConnected
                userPlaytestActive = [bool]$body.state.userPlaytestActive
            }
        }
        return $state
    }

    # ------------------------------------------------------------------
    # ANMELDUNG EINES STUDIO-FENSTERS
    # Jedes Fenster ist eine eigene Sitzung mit eigenem Token.
    # Startet Studio den Testmodus neu, meldet sich dasselbe Fenster mit
    # einer neuen instanceGuid - dann wird die alte, verwaiste Sitzung
    # wiederverwendet, damit der Token der KI gültig bleibt.
    # ------------------------------------------------------------------
    function Register-Session($body) {
        if (-not $body) { return $null }
        # 4.0.1: Die Plugin-Instanz im Test-DataModel ist KEIN eigenes Place.
        # Sie erzeugte bisher den zusaetzlichen "Game"-Eintrag in der Liste.
        if ($body.sessionDataModel -eq $true) { return $null }
        $guid    = [string]$body.instanceGuid
        $placeId = [string]$body.placeId
        $placeName = [string]$body.placeName
        $now = Get-UnixSeconds

        # Version 7.0.6: IDENTITAET ZUERST. Hat dieses Plugin-Fenster
        # (instanceGuid) schon eine Sitzung, dann ist DAS die Sitzung - ohne
        # Namensraten und ohne "sieht tot aus"-Heuristik. Genau hier entstand
        # der "Bridge connected"-Sturm alle 2 Sekunden, und genau deshalb
        # landeten Befehle in Sitzungen, die niemand mehr pollte.
        $instanceSessionId = ''
        if (-not [string]::IsNullOrWhiteSpace($guid)) {
            [void]$Shared.InstanceSessions.TryGetValue($guid, [ref]$instanceSessionId)
            $instanceSessionId = [string]$instanceSessionId
            $Shared.InstanceLastSeen[$guid] = $now
        }

        $reusable = $null
        $reuseReason = $null
        if (-not [string]::IsNullOrWhiteSpace($instanceSessionId)) {
            $instanceEntry = Get-SessionEntry $instanceSessionId
            if (-not $instanceEntry) {
                # Die Sitzung war schon aufgeraeumt (z. B. 120 s ohne
                # Lebenszeichen). Dieselbe Identitaet wird wiederbelebt, statt
                # eine neue sessionId zu erfinden - der Token bleibt gueltig,
                # wartende Befehle bleiben erreichbar.
                $instanceEntry = @{
                    sessionId     = $instanceSessionId
                    instanceGuid  = $guid
                    placeName     = $placeName
                    placeId       = $placeId
                    gameId        = [string]$body.gameId
                    token         = ''
                    accessMode    = 'readwrite'
                    lastSeen      = $now
                    connectedAt   = $now
                    state         = $null
                    pluginVersion = [string]$body.pluginVersion
                    capabilities  = $body.capabilities
                    reconnects    = 0
                    orphan        = $false
                    revived       = $true
                }
                try { $Shared.Telemetry.RevivedSessions = [long]$Shared.Telemetry.RevivedSessions + 1 } catch {}
                Write-BridgeLog ("Sitzung " + $instanceSessionId + " wurde fuer dieselbe Plugin-Instanz wiederbelebt (keine neue sessionId, kein neuer Token).")
            }
            if ($instanceEntry) {
                $reusable = $instanceEntry
                $reuseReason = 'same-instance'
            }
        }
        foreach ($pair in $Shared.Sessions.GetEnumerator()) {
            $entry = $null
            try { $entry = $pair.Value | ConvertFrom-Json } catch { $entry = $null }
            if (-not $entry) { continue }
            if ([string]$entry.instanceGuid -eq $guid -and $guid -ne '') {
                $reusable = $entry
                $reuseReason = 'same-instance'
                break
            }
        }
        # Version 7.0.0: Ein LEBENDES Fenster wird NIE uebernommen. Der alte
        # Reconnect-Zweig durfte ueber placeId=0 + gleichem Anzeigenamen eine
        # fremde, noch lebende Sitzung samt Token uebernehmen - dadurch teilten
        # sich zwei offene Places EINE Zeile (gleicher Name, gleiche Vorschau).
        # Uebernommen wird nur noch, was nachweislich tot ist UND dessen
        # Instanz nicht mehr heartbeatet. Bei placeId=0 zusaetzlich nur mit
        # identischer instanceGuid.
        $claimable = @()
        if ($reusable) {
            $claimable = @($reusable)
            $reusable = $null
            $reuseReason = $null
            foreach ($entry in $claimable) {
                if ([string]$entry.instanceGuid -eq $guid -and $guid -ne '') {
                    $reusable = $entry; $reuseReason = 'same-instance'; break
                }
            }
        }

        if (-not $reusable) {
            $best = $null
            foreach ($pair in $Shared.Sessions.GetEnumerator()) {
                $entry = $null
                try { $entry = $pair.Value | ConvertFrom-Json } catch { $entry = $null }
                if (-not $entry) { continue }
                # Version 7.0.0: Ohne echte placeId (0 = unveroeffentlicht/lokal)
                # ist ein Namensvergleich KEIN Identitaetsbeweis. Zwei Fenster
                # koennen beide "obby" heissen und trotzdem zwei verschiedene
                # Places sein. Dann wird nur bei identischer instanceGuid
                # uebernommen - sonst bleibt jedes Fenster eine eigene Zeile.
                if ([string]::IsNullOrWhiteSpace($placeId) -or $placeId -eq '0') { continue }
                $age = $now - [int64]$entry.lastSeen
                $samePlace = ([string]$entry.placeId -eq $placeId)
                # Wann darf eine alte Sitzung samt Token weiterbenutzt werden?
                #   a) Das Plugin hat sich sauber abgemeldet (Studio geschlossen, Neuladen,
                #      Studio geschlossen)  ->  sofort.
                #   b) Kein offener Long-Poll und seit 10 Sekunden nichts gehört
                #      (Absturz)  ->  ebenfalls.
                # Ein zweites, LEBENDES Fenster desselben Place wird dadurch
                # niemals übernommen - es behält seinen eigenen Token.
                $openPolls = 0
                [void]$Shared.Pollers.TryGetValue([string]$entry.sessionId, [ref]$openPolls)
                $isOrphan = ($entry.orphan -eq $true)
                # Version 7.0.0: Ein offener Long-Poll beweist ein LEBENDES
                # Fenster. So etwas wird niemals uebernommen - auch nicht mit
                # "orphan"-Flag (Plugin-Neuladen im selben Fenster).
                if ($openPolls -gt 0) { continue }
                $looksDead = ($age -ge 10)
                # Lebenszeichen aus Presence (Edit-Heartbeat) schuetzt ebenso.
                try {
                    $presence = [int64]0
                    $visibleSecs = if ($script:PlaceVisibleSeconds) { [int]$script:PlaceVisibleSeconds } else { 20 }
                    if ($Shared.Presence.TryGetValue([string]$entry.sessionId, [ref]$presence)) {
                        if (($now - [int64]$presence) -lt $visibleSecs) { continue }
                    }
                } catch {}
                if ($samePlace -and ($isOrphan -or $looksDead) -and $age -le 900) {
                    if (-not $best -or [int64]$entry.lastSeen -gt [int64]$best.lastSeen) { $best = $entry }
                }
            }
            if ($best) {
                $reusable = $best
                $reuseReason = 'reconnect'
            }
        }

        if ($reusable) {
            $sessionId = [string]$reusable.sessionId
            $token = $null
            if (-not $Shared.SessionTokens.TryGetValue($sessionId, [ref]$token)) {
                $token = New-BridgeToken
                $Shared.SessionTokens[$sessionId] = $token
                $Shared.TokenSessions[$token] = $sessionId
            }
            $mode = $null
            if (-not $Shared.AccessModes.TryGetValue($sessionId, [ref]$mode)) {
                $mode = 'readwrite'
                $Shared.AccessModes[$sessionId] = $mode
            }
            # Version 5: every fresh/re-registered Place starts with write
            # access. Read-only is never restored from disk.
            # Version 7.1.1: Ausnahme - dieselbe LEBENDE Instanz (zuletzt vor
            # <= 30 s gesehen) meldet sich erneut an (z. B. verlorene sessionId
            # im Plugin). Das ist kein neues Place; ein im Fenster gesetzter
            # Lesemodus bleibt erhalten statt still auf readwrite zu kippen.
            $reusableAge = 999999
            try { $reusableAge = [int][Math]::Max(0, $now - [int64]$reusable.lastSeen) } catch {}
            if (-not ($reuseReason -eq 'same-instance' -and $reusableAge -le 30 -and -not [string]::IsNullOrWhiteSpace([string]$mode))) {
                $mode = 'readwrite'
            }
            $Shared.AccessModes[$sessionId] = $mode
            # Version 3.8: Play-Wechsel erkennen - auch wenn das Plugin beim
            # Start/Stop des Tests neu geladen wurde und neu registriert.
            $registerState = Update-PlayStateTracking $sessionId $reusable.state (Get-StateObject $body)
            $entry = @{
                sessionId     = $sessionId
                instanceGuid  = $guid
                placeName     = $placeName
                placeId       = $placeId
                gameId        = [string]$body.gameId
                token         = $token
                accessMode    = $mode
                lastSeen      = $now
                connectedAt   = $reusable.connectedAt
                state         = $registerState
                pluginVersion = [string]$body.pluginVersion
                capabilities  = $body.capabilities
                reconnects    = ([int]$reusable.reconnects + 1)
                orphan        = $false
            }
            Save-SessionEntry $entry
            if ($reuseReason -eq 'reconnect') {
                # Version 7.0.5: a plugin restart must NOT throw away commands that
                # were never handed out. They stay in the queue and go to the fresh
                # executor; only work that the DEAD executor had already taken is
                # abandoned, and the watchdog decides that from the timestamps
                # (nothing is replayed blindly).
                Invoke-SessionExecutorWatchdog $sessionId
                Add-BridgeEvent $sessionId 'studio_reconnected' 'The Studio plugin reconnected. Waiting commands stay queued for the new executor; work that the previous executor had taken is abandoned after the watchdog timeout instead of being replayed.' @{ placeName = $placeName }
            }
            Save-SessionExecutorState $sessionId $body.executor
            $Shared.Presence[$sessionId] = $now
            if (-not [string]::IsNullOrWhiteSpace($guid)) {
                $Shared.InstanceSessions[$guid] = $sessionId
                $Shared.InstanceLastSeen[$guid] = $now
            }
            try { $Shared.Telemetry.ReusedSessions = [long]$Shared.Telemetry.ReusedSessions + 1 } catch {}
            return $entry
        }

        $sessionId = [guid]::NewGuid().ToString('N')
        $token = New-BridgeToken
        $Shared.SessionTokens[$sessionId] = $token
        $Shared.TokenSessions[$token] = $sessionId
        # Version 5: new registrations always start with full access.
        $startMode = 'readwrite'
        $Shared.AccessModes[$sessionId] = $startMode
        # Lief schon ein Test, als die Bridge das Fenster zum ersten Mal sah?
        # Dann gilt er sicherheitshalber als Nutzer-Test.
        $freshState = Update-PlayStateTracking $sessionId $null (Get-StateObject $body)
        $entry = @{
            sessionId     = $sessionId
            instanceGuid  = $guid
            placeName     = $placeName
            placeId       = $placeId
            gameId        = [string]$body.gameId
            token         = $token
            accessMode    = $startMode
            lastSeen      = $now
            connectedAt   = $now
            state         = $freshState
            pluginVersion = [string]$body.pluginVersion
            capabilities  = $body.capabilities
            reconnects    = 0
            orphan        = $false
        }
        Save-SessionEntry $entry
        Save-SessionExecutorState $sessionId $body.executor
        $Shared.Presence[$sessionId] = $now
        [void](Ensure-Queue $sessionId)
        [void](Ensure-Signal $sessionId)
        # Version 7.0.5: if the same Studio window comes back with a NEW plugin
        # instanceGuid (Roblox reloaded the plugin / the connection was reset), the
        # commands that were never delivered are handed over to the new session
        # instead of being lost. A live second window is never touched.
        try {
            $predecessor = $null
            foreach ($candidatePair in @($Shared.Sessions.GetEnumerator())) {
                if ([string]$candidatePair.Key -eq $sessionId) { continue }
                $candidate = $null
                try { $candidate = $candidatePair.Value | ConvertFrom-Json } catch { continue }
                if (-not $candidate) { continue }
                $candidateSid = [string]$candidate.sessionId
                if ([string]::IsNullOrWhiteSpace($candidateSid)) { continue }
                if ([string]$candidate.placeId -ne $placeId) { continue }
                $candidatePolls = 0
                [void]$Shared.Pollers.TryGetValue($candidateSid, [ref]$candidatePolls)
                $candidatePresence = [int64]0
                $candidateHasPresence = $Shared.Presence.TryGetValue($candidateSid, [ref]$candidatePresence)
                $candidateSeen = [int64]0
                try { $candidateSeen = [int64]$candidate.lastSeen } catch {}
                $candidateAliveAt = $(if ($candidateHasPresence) { [int64]$candidatePresence } else { [int64]$candidateSeen })
                $candidateAge = $(if ($candidateAliveAt -gt 0) { $now - $candidateAliveAt } else { 999999 })
                $candidateBag = $null
                $candidatePending = 0
                if ($Shared.PendingCommands.TryGetValue($candidateSid, [ref]$candidateBag)) { $candidatePending = [int]$candidateBag.Count }
                # Only a session that clearly stopped polling (dead executor) with
                # work still waiting qualifies - never a live second Studio window.
                if ($candidatePolls -le 0 -and $candidateAge -gt 20 -and $candidatePending -gt 0) {
                    $predecessor = $candidate
                    break
                }
            }
            if ($predecessor) {
                Register-SessionSuccessor ([string]$predecessor.sessionId) $sessionId
                Write-BridgeLog ('Befehle der vorherigen Sitzung ' + [string]$predecessor.sessionId + ' an ' + $sessionId + ' uebergeben (Reconnect).')
            }
        } catch {}
        # Version 7.0.6: Identitaet merken und Sitzungs-Neuanlagen zaehlen.
        # Mehr als sechs neue Sitzungen in 60 Sekunden sind kein normaler
        # Reconnect, sondern ein Sturm - er wird sichtbar gemacht, statt
        # stillschweigend weiterzulaufen.
        if (-not [string]::IsNullOrWhiteSpace($guid)) {
            $Shared.InstanceSessions[$guid] = $sessionId
            $Shared.InstanceLastSeen[$guid] = $now
        }
        try {
            $tel = $Shared.Telemetry
            $tel.NewSessions = [long]$tel.NewSessions + 1
            if ([long]$tel.StartedAt -le 0) { $tel.StartedAt = $now }
            $Shared.SessionCreations.Enqueue($now)
            $cutoff = $now - 300
            $stampProbe = [long]0
            while ($Shared.SessionCreations.TryPeek([ref]$stampProbe) -and [int64]$stampProbe -lt $cutoff) {
                $dropStamp = [long]0
                [void]$Shared.SessionCreations.TryDequeue([ref]$dropStamp)
            }
            $recentCreations = 0
            foreach ($creationStamp in @($Shared.SessionCreations.ToArray())) {
                if ([int64]$creationStamp -ge ($now - 60)) { $recentCreations = $recentCreations + 1 }
            }
            if ($recentCreations -ge 6) {
                $tel.StormWarnings = [long]$tel.StormWarnings + 1
                Write-BridgeLog ("WARNUNG: $recentCreations neue Studio-Sitzungen in 60 Sekunden. Dieselbe Plugin-Instanz muss dieselbe Sitzung behalten (instanceGuid). Pruefe /api/version (newSessionsLast60s) und die Plugin-Version im Studio.")
            }
        } catch {}
        Add-BridgeEvent $sessionId 'connected' "Place '$placeName' is connected." @{ placeId = $placeId }
        Write-BridgeLog "Neue Sitzung $sessionId fuer Place '$placeName' (placeId $placeId)."
        return $entry
    }

    # Version 7.0.6: Eine unbekannte Sitzung wird nur dann wiederbelebt, wenn
    # die INSTANZ bekannt ist (instanceGuid -> sessionId). Es wird nie eine neue
    # Sitzung erfunden: genau das war der Reconnect-Sturm.
    function Resolve-InstanceSession($body) {
        if (-not $body) { return $null }
        $guid = [string]$body.instanceGuid
        if ([string]::IsNullOrWhiteSpace($guid)) { return $null }
        $known = ''
        if (-not $Shared.InstanceSessions.TryGetValue($guid, [ref]$known)) { return $null }
        $known = [string]$known
        if ([string]::IsNullOrWhiteSpace($known)) { return $null }
        $entry = Register-Session $body
        if ($entry) {
            try { $Shared.Telemetry.RevivedSessions = [long]$Shared.Telemetry.RevivedSessions + 1 } catch {}
        }
        return $entry
    }

    # Aktualisiert eine bestehende Sitzung (Heartbeat / Poll).
    function Update-Session($body) {
        if (-not $body) { return $null }
        $sessionId = [string]$body.sessionId
        # Version 7.1.1: Poll/Heartbeat ohne sessionId (das 7.0.0-7.1.0-Plugin
        # schickte sie nie mit) oder mit veralteter sessionId -> die Identitaet
        # der Plugin-Instanz (instanceGuid) entscheidet. Vorher lief JEDER Poll
        # durch Register-Session (reconnects+1, Lesemodus zurueckgesetzt,
        # revivedSessions im Sekundentakt) und der Ersatz-Heartbeat meldete
        # "Sitzung unbekannt" -> Plugin verwarf die Sitzung, re-hello, Sturm.
        if ([string]::IsNullOrWhiteSpace($sessionId) -or -not $Shared.Sessions.ContainsKey($sessionId)) {
            $instanceGuidForUpdate = ''
            try { $instanceGuidForUpdate = [string]$body.instanceGuid } catch {}
            if (-not [string]::IsNullOrWhiteSpace($instanceGuidForUpdate)) {
                $mappedSessionId = ''
                if ($Shared.InstanceSessions.TryGetValue($instanceGuidForUpdate, [ref]$mappedSessionId)) {
                    $mappedSessionId = [string]$mappedSessionId
                    if (-not [string]::IsNullOrWhiteSpace($mappedSessionId) -and $Shared.Sessions.ContainsKey($mappedSessionId)) {
                        $sessionId = $mappedSessionId
                    }
                }
            }
        }
        if ([string]::IsNullOrWhiteSpace($sessionId)) { return $null }
        $entry = Get-SessionEntry $sessionId
        if (-not $entry) { return $null }

        $now = Get-UnixSeconds
        $mode = $null
        if (-not $Shared.AccessModes.TryGetValue($sessionId, [ref]$mode)) {
            $mode = 'readwrite'
            $Shared.AccessModes[$sessionId] = $mode
        }
        $token = $null
        if (-not $Shared.SessionTokens.TryGetValue($sessionId, [ref]$token)) {
            $token = New-BridgeToken
            $Shared.SessionTokens[$sessionId] = $token
            $Shared.TokenSessions[$token] = $sessionId
        }

        $oldState = $entry.state
        # The edit plugin continues to heartbeat with running=false while the
        # separate session DataModel is running. Prefer a fresh agent snapshot.
        $incomingState = Get-StateObject $body
        $agentSeen = 0
        $agentJson = $null
        if ($Shared.AgentLastSeen.TryGetValue($sessionId, [ref]$agentSeen) -and ((Get-UnixSeconds) - $agentSeen) -le 4 -and $Shared.AgentStates.TryGetValue($sessionId, [ref]$agentJson)) {
            try {
                $agentState = $agentJson | ConvertFrom-Json
                if ([bool]$agentState.running) { $incomingState = $agentState }
            } catch {}
        }
        $newName = [string]$body.placeName
        if ([string]::IsNullOrWhiteSpace($newName)) { $newName = [string]$entry.placeName }
        # Version 3.8: Play-Start/Stop ZUVERLAESSIG erkennen - inklusive
        # startedBy (der Server weiß es selbst, siehe AiPlayIntents) und
        # Nutzer-Test-Erkennung nach echten Plugin-Neuladevorgaengen.
        $newState = Update-PlayStateTracking $sessionId $oldState $incomingState
        if ($agentSeen -gt 0 -and ((Get-UnixSeconds) - $agentSeen) -le 4) {
            $newState | Add-Member -NotePropertyName 'agentConnected' -NotePropertyValue $true -Force
        }

        $newPlaceId = [string]$body.placeId
        if ([string]::IsNullOrWhiteSpace($newPlaceId)) { $newPlaceId = [string]$entry.placeId }
        $newGameId = [string]$body.gameId
        if ([string]::IsNullOrWhiteSpace($newGameId)) { $newGameId = [string]$entry.gameId }
        $updated = @{
            sessionId     = $sessionId
            instanceGuid  = [string]$entry.instanceGuid
            placeName     = $newName
            placeId       = $newPlaceId
            gameId        = $newGameId
            token         = $token
            accessMode    = $mode
            lastSeen      = $now
            connectedAt   = $entry.connectedAt
            state         = $newState
            agentConnected = ($agentSeen -gt 0 -and ((Get-UnixSeconds) - $agentSeen) -le 4)
            pluginVersion = [string]$entry.pluginVersion
            versionMismatch = ([string]$entry.pluginVersion -ne [string]$Shared.DocsVersion)
            capabilities  = $entry.capabilities
            reconnects    = $entry.reconnects
            orphan        = $false
        }
        Save-SessionEntry $updated
        Save-SessionExecutorState $sessionId $body.executor
        $Shared.Presence[$sessionId] = $now

        return $updated
    }


    # ------------------------------------------------------------------
    # GROSSE ANTWORTEN: als Blob ablegen und in Stücken herausgeben
    # ------------------------------------------------------------------
    function New-Blob([string]$json, [string]$tool) {
        $blobId = 'blob_' + [guid]::NewGuid().ToString('N').Substring(0, 12)
        $Shared.Blobs[$blobId] = $json
        $chunkCount = [Math]::Ceiling($json.Length / [double]$ChunkSize)
        $info = @{
            blobId     = $blobId
            tool       = $tool
            totalChars = $json.Length
            chunkSize  = $ChunkSize
            chunkCount = [int]$chunkCount
            created    = (Get-Date).ToString('u')
        }
        $Shared.BlobInfo[$blobId] = (To-Json $info 8)
        # Alte Blobs (älter als 30 Minuten) aufräumen
        foreach ($pair in $Shared.BlobInfo.GetEnumerator()) {
            try {
                $old = $pair.Value | ConvertFrom-Json
                if (((Get-Date) - [DateTime]::Parse($old.created)).TotalMinutes -gt 30) {
                    $removed = $null
                    [void]$Shared.Blobs.TryRemove($pair.Key, [ref]$removed)
                    [void]$Shared.BlobInfo.TryRemove($pair.Key, [ref]$removed)
                }
            } catch {}
        }
        return $info
    }

    function Get-BlobChunk([string]$blobId, [int]$index) {
        $json = $null
        if (-not $Shared.Blobs.TryGetValue($blobId, [ref]$json)) {
            return @{ ok = $false; error = "Unknown or expired blobId '$blobId'. Blobs live for 30 minutes - run the tool again." }
        }
        $infoJson = $null
        [void]$Shared.BlobInfo.TryGetValue($blobId, [ref]$infoJson)
        $info = $null
        if ($infoJson) { $info = $infoJson | ConvertFrom-Json }
        $chunkCount = [int][Math]::Ceiling($json.Length / [double]$ChunkSize)
        if ($index -lt 1) { $index = 1 }
        if ($index -gt $chunkCount) {
            return @{ ok = $false; error = "Chunk $index does not exist (chunkCount = $chunkCount)." }
        }
        $start = ($index - 1) * $ChunkSize
        $length = [Math]::Min($ChunkSize, $json.Length - $start)
        return @{
            ok         = $true
            blobId     = $blobId
            index      = $index
            chunkCount = $chunkCount
            totalChars = $json.Length
            isLast     = ($index -eq $chunkCount)
            data       = $json.Substring($start, $length)
            note       = 'Concatenate data of all chunks in order, then parse the result as JSON. Nothing is truncated.'
        }
    }

    # ------------------------------------------------------------------
    # ASSET-CACHE (lokale Datei): Suchergebnisse und Asset-Details werden
    # nicht jede Session neu von Roblox geladen, sondern aus dem Cache
    # bedient (Suche 7 Tage, Details 30 Tage). refresh=true erzwingt Neu.
    # ------------------------------------------------------------------
    function Read-AssetCache {
        try {
            $path = [string]$Shared.AssetCachePath
            if (Test-Path -LiteralPath $path) {
                $raw = Get-Content -LiteralPath $path -Raw
                if ($raw) { return ($raw | ConvertFrom-Json) }
            }
        } catch {
            Write-BridgeLog "Asset-Cache lesen fehlgeschlagen: $($_.Exception.Message)"
        }
        return $null
    }

    # Version 7.1.2: Der Asset-Cache war UNBEGRENZT. Jede Suche legte einen
    # Eintrag plus bis zu 50 Detail-Eintraege ab, nichts wurde je entfernt
    # (die 7/30-Tage-Pruefung galt nur beim Lesen). Jeder Add-CacheEntry las
    # die KOMPLETTE Datei nach PSObject, schrieb sie komplett neu - mit
    # wachsender Datei wurde jeder Toolbox-Aufruf langsamer und belegte mehr
    # Speicher im HTTP-Runspace. Jetzt: harte Obergrenze an Eintraegen und
    # Bytes, aelteste Eintraege fliegen zuerst raus.
    function Limit-AssetCache($cache) {
        if ($null -eq $cache) { return $null }
        try {
            $maxEntries = [int]$Shared.ToolboxLimits.MaxCacheEntries
            # Hausregel: KEIN @() um eine Sammlung legen (PowerShell-5.1-
            # Binderfehler "Die Argumenttypen stimmen nicht ueberein.").
            # Deshalb wird direkt aufgezaehlt statt verpackt.
            $names = New-Object System.Collections.Generic.List[string]
            foreach ($prop in $cache.PSObject.Properties) { $names.Add([string]$prop.Name) }
            if ($names.Count -le $maxEntries) { return $cache }
            $aged = New-Object System.Collections.Generic.List[object]
            foreach ($name in $names) {
                $stamp = [DateTime]::MinValue
                try { $stamp = [DateTime]::Parse([string]$cache.PSObject.Properties[$name].Value.fetchedAt) } catch {}
                $aged.Add([pscustomobject]@{ Name = [string]$name; At = $stamp })
            }
            $sorted = $aged.ToArray() | Sort-Object -Property At
            $removeCount = $names.Count - $maxEntries
            for ($i = 0; $i -lt $removeCount; $i++) {
                try { $cache.PSObject.Properties.Remove([string]$sorted[$i].Name) } catch {}
            }
        } catch {
            Write-BridgeLog "Asset-Cache begrenzen fehlgeschlagen: $($_.Exception.Message)"
        }
        return $cache
    }

    function Save-AssetCache($cache) {
        try {
            $path = [string]$Shared.AssetCachePath
            $cache = Limit-AssetCache $cache
            $json = $cache | ConvertTo-Json -Depth 14 -Compress
            if ($null -ne $json -and $json.Length -gt [int]$Shared.ToolboxLimits.MaxCacheBytes) {
                # Notbremse: lieber einen leeren Cache als eine Datei, die jeden
                # Aufruf teurer macht (sie wird bei jedem Zugriff komplett geparst).
                Write-BridgeLog ('Asset-Cache ueberschreitet ' + [string]$Shared.ToolboxLimits.MaxCacheBytes + ' Bytes und wird geleert.')
                $json = '{}'
            }
            [System.IO.File]::WriteAllText($path, $json, (New-Object System.Text.UTF8Encoding($false)))
        } catch {
            Write-BridgeLog "Asset-Cache speichern fehlgeschlagen: $($_.Exception.Message)"
        }
    }

    function Get-CacheEntry($cache, [string]$key, [double]$maxAgeDays) {
        if ($null -eq $cache) { return $null }
        # Version 7.1.2: Klammerung repariert - '-not $x -contains $y' wertet
        # '(-not $x) -contains $y' aus und war damit IMMER $false; der
        # Schnellausstieg lief nie und jeder Fehltreffer ging ueber eine
        # Ausnahme im try-Block.
        if (-not ($cache.PSObject.Properties.Name -contains $key)) { return $null }
        try {
            $cached = $cache.PSObject.Properties[$key].Value
            $age = (Get-Date) - [DateTime]::Parse([string]$cached.fetchedAt)
            if ($age.TotalDays -lt $maxAgeDays) { return $cached.result }
        } catch {}
        return $null
    }

    # Version 7.1.2: Schreibzugriffe laufen serialisiert (vorher konnten
    # mehrere HTTP-Runspaces dieselbe Datei gleichzeitig lesen und neu
    # schreiben) und MEHRERE Eintraege gehen in EINEM Lese-/Schreibvorgang
    # raus. Invoke-AssetDetails hat vorher je Asset-Id die ganze Datei neu
    # geschrieben - bei 20 Ids 20 volle Serialisierungen.
    function Add-CacheEntries($pairs) {
        if ($null -eq $pairs -or $pairs.Count -eq 0) { return }
        [System.Threading.Monitor]::Enter($Shared.AssetCacheLock)
        try {
            $cache = Read-AssetCache
            if ($null -eq $cache) { $cache = New-Object psobject }
            $stamp = (Get-Date).ToUniversalTime().ToString('o')
            foreach ($cacheKey in @($pairs.Keys)) {
                $cache | Add-Member -NotePropertyName ([string]$cacheKey) -NotePropertyValue (@{
                    fetchedAt = $stamp
                    result    = $pairs[$cacheKey]
                }) -Force
            }
            Save-AssetCache $cache
        } catch {
            Write-BridgeLog "Asset-Cache schreiben fehlgeschlagen: $($_.Exception.Message)"
        } finally {
            [System.Threading.Monitor]::Exit($Shared.AssetCacheLock)
        }
    }

    function Add-CacheEntry([string]$key, $value) {
        $single = @{}
        $single[$key] = $value
        Add-CacheEntries $single
    }

    # typeId -> wofuer man es verwenden kann (fuer die Tyvalidierung)
    function Get-AssetTypeUsage([int]$typeId) {
        switch ($typeId) {
            1  { return @{ typeName = 'Image';     usableAs = 'Texture / Image / Decal-Texture'; properties = @('Texture', 'Image') } }
            3  { return @{ typeName = 'Audio';     usableAs = 'Sound';                          properties = @('SoundId') } }
            4  { return @{ typeName = 'Mesh';      usableAs = 'SpecialMesh (MeshId)';           properties = @('MeshId') } }
            10 { return @{ typeName = 'Model';     usableAs = 'insert_asset (Model)';           properties = @() } }
            13 { return @{ typeName = 'Decal';     usableAs = 'Decal / Texture / Image';        properties = @('Texture', 'Image') } }
            24 { return @{ typeName = 'Animation'; usableAs = 'Animation';                      properties = @('AnimationId') } }
            38 { return @{ typeName = 'Plugin';    usableAs = 'Creator Store metadata / Studio plugin'; properties = @() } }
            40 { return @{ typeName = 'MeshPart';  usableAs = 'insert_asset (MeshPart)';        properties = @() } }
            62 { return @{ typeName = 'Video';     usableAs = 'VideoFrame';                     properties = @('VideoId') } }
            default { return @{ typeName = ('Unknown(' + [string]$typeId + ')'); usableAs = ''; properties = @() } }
        }
    }

    # ==================================================================
    # Version 7.1.2: EIN einziger, HART BEGRENZTER Weg in den Roblox-Katalog.
    # Vorher rief jede Asset-Funktion direkt Invoke-RestMethod auf:
    #   - Invoke-AssetSearch mit einer EIGENEN Wiederholungsschleife
    #     (2 x 20 s + 1,5 s Pause) und danach noch einem 20-s-Detailaufruf
    #     = bis zu 61,5 s fuer EINEN search_assets-Aufruf,
    #   - Invoke-AssetDetails im 404-Fall mit EINER Anfrage JE Asset-Id
    #     (20 s x N, voellig unbegrenzt),
    #   - Invoke-AssetValidation zusaetzlich VOR jedem insert_asset.
    # Zusammen mit den 55 s Studio-Wartezeit konnte ein einzelner
    # /api/tool-Aufruf die ~100-s-Grenze des Cloudflare-Tunnels reissen (524).
    # Jetzt gilt: ein Versuch, hartes Zeitlimit, KEINE automatische
    # Wiederholung, typisierter Fehler.
    # ==================================================================
    function Invoke-CatalogHttp([string]$url, [int]$timeoutSeconds = 0) {
        if ($timeoutSeconds -le 0) { $timeoutSeconds = [int]$Shared.ToolboxLimits.CatalogTimeoutSec }
        $timeoutSeconds = [Math]::Max(3, [Math]::Min(20, $timeoutSeconds))
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $data = Invoke-RestMethod -Uri $url -Method Get -TimeoutSec $timeoutSeconds -UseBasicParsing -ErrorAction Stop
            $sw.Stop()
            return @{ ok = $true; data = $data; elapsedMs = [int]$sw.ElapsedMilliseconds; timedOut = $false; notFound = $false; error = '' }
        } catch {
            $sw.Stop()
            $message = [string]$_.Exception.Message
            $notFound = ($message -match '404')
            $timedOut = $false
            if (-not $notFound) {
                $timedOut = (($sw.Elapsed.TotalSeconds * 1.0) -ge ($timeoutSeconds - 0.5)) -or ($message -match 'timed out|timeout|Zeitlimit|Vorgangstimeout')
            }
            return @{ ok = $false; data = $null; elapsedMs = [int]$sw.ElapsedMilliseconds; timedOut = $timedOut; notFound = $notFound; error = $message }
        }
    }

    function New-CatalogErrorResult($call, [string]$what) {
        # Typisierte, verstaendliche Fehler statt "haengt einfach".
        if ($call.timedOut) {
            return @{
                ok = $false
                code = 'CATALOG_TIMEOUT'
                catalogAvailable = $false
                timedOutAfterMs = [int]$call.elapsedMs
                error = ("The Roblox catalog did not answer within the hard time limit while " + $what + " (" + [string]$call.elapsedMs + " ms). The call was ABORTED - nothing is still running in the background.")
                protocol = 'Do NOT retry in a loop. Tell the user "Katalog antwortet nicht" and continue PROCEDURALLY (build_polygon_model / build_assembly / create_instance). Never guess asset ids.'
                checkAgain = 'catalog_status is a cheap single probe if you want to know whether the catalog is back.'
                retryAdvice = 'At most ONE manual retry, and only after catalog_status reports catalogAvailable=true.'
            }
        }
        return @{
            ok = $false
            code = 'CATALOG_UNAVAILABLE'
            catalogAvailable = $false
            error = ("The Roblox catalog is NOT available right now while " + $what + " (" + [string]$call.error + ").")
            protocol = 'Say this clearly to the user right away: "Katalog nicht verfuegbar". Then continue PROCEDURALLY: textures = colored parts / SurfaceGui, sounds = a short procedural beep in a script (or skip), models = build them with build_polygon_model / build_assembly / create_instance. Do NOT guess asset ids and do NOT stay silent.'
            checkAgain = 'Call the catalog_status tool whenever you want to know if the catalog is back.'
        }
    }

    # ------------------------------------------------------------------
    # Version 7.1.2: TOOLBOX-DROSSEL. Pro Place darf nur eine streng
    # begrenzte Zahl Katalogaufrufe GLEICHZEITIG laufen. Weitere Aufrufe
    # kommen SOFORT mit TOOLBOX_BUSY zurueck statt sich aufzustauen -
    # genau das liess die Bridge im Live-Befund immer traeger werden.
    # ------------------------------------------------------------------
    function Enter-ToolboxSlot([string]$sessionId, [string]$tool) {
        $sid = [string]$sessionId
        if ([string]::IsNullOrWhiteSpace($sid)) { $sid = '__anon__' }
        $maxPending = [int]$Shared.ToolboxLimits.MaxPendingPerPlace
        [System.Threading.Monitor]::Enter($Shared.ToolboxSlotLock)
        try {
            $current = 0
            [void]$Shared.ToolboxSlots.TryGetValue($sid, [ref]$current)
            if ($current -ge $maxPending) {
                return @{
                    ok = $false
                    sessionKey = $sid
                    result = @{
                        ok = $false
                        code = 'TOOLBOX_BUSY'
                        toolboxBusy = $true
                        error = ("This place already has " + [string]$current + " catalog/asset request(s) in flight (limit " + [string]$maxPending + "). '" + [string]$tool + "' was NOT started.")
                        activeRequests = [int]$current
                        limit = [int]$maxPending
                        howToFix = 'Run toolbox calls strictly one after another and WAIT for each answer. Do not start parallel asset searches and do not poll in a loop - every extra call makes Studio slower without delivering anything.'
                        workIsLost = $false
                    }
                }
            }
            $Shared.ToolboxSlots[$sid] = ($current + 1)
            return @{ ok = $true; sessionKey = $sid; result = $null }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.ToolboxSlotLock)
        }
    }

    function Exit-ToolboxSlot([string]$sessionKey) {
        if ([string]::IsNullOrWhiteSpace($sessionKey)) { return }
        [System.Threading.Monitor]::Enter($Shared.ToolboxSlotLock)
        try {
            $current = 0
            if ($Shared.ToolboxSlots.TryGetValue([string]$sessionKey, [ref]$current)) {
                $Shared.ToolboxSlots[[string]$sessionKey] = [Math]::Max(0, $current - 1)
            }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.ToolboxSlotLock)
        }
    }

    # ------------------------------------------------------------------
    # Version 7.1.2: GENAU EIN aktiver Asset-Import je Place.
    # InsertService:LoadAsset ist ein NATIVER, yieldender Roblox-Aufruf.
    # task.cancel beendet nur den Luau-Thread - der native Ladevorgang laeuft
    # im Hintergrund weiter und kann spaeter zurueckkommen. Ein zweiter
    # Import waehrend eines haengenden ersten belastet Studio zusaetzlich und
    # kann dasselbe Modell doppelt einfuegen. Deshalb: harte Einzelbelegung,
    # ehrliche Meldung statt vorgetaeuschtem Abbruch, Idempotenz gegen
    # Wiederholungen nach einem Client-Timeout.
    # ------------------------------------------------------------------
    function Get-ToolboxInsertKey([string]$sessionId, $toolArgs) {
        $explicit = ''
        try { if ($toolArgs -and $toolArgs.requestId) { $explicit = ([string]$toolArgs.requestId).Trim() } } catch {}
        if (-not [string]::IsNullOrWhiteSpace($explicit)) { return ([string]$sessionId + '|rid|' + $explicit) }
        $parent = 'game.Workspace'
        try { if ($toolArgs -and $toolArgs.parentRef) { $parent = [string]$toolArgs.parentRef } } catch {}
        $name = ''
        try { if ($toolArgs -and $toolArgs.name) { $name = [string]$toolArgs.name } } catch {}
        $assetId = ''
        try { if ($toolArgs -and $toolArgs.assetId) { $assetId = [string]$toolArgs.assetId } } catch {}
        return ([string]$sessionId + '|fp|' + $assetId + '|' + $parent + '|' + $name)
    }

    function Get-ToolboxInsertReplay([string]$insertKey, $toolArgs) {
        try { if ($toolArgs -and $toolArgs.allowDuplicate -eq $true) { return $null } } catch {}
        $stamp = [long]0
        if (-not $Shared.ToolboxInsertAt.TryGetValue($insertKey, [ref]$stamp)) { return $null }
        $age = (Get-UnixSeconds) - [long]$stamp
        if ($age -gt [int]$Shared.ToolboxLimits.IdempotencyWindowSec) {
            $discard = $null
            [void]$Shared.ToolboxInsertResults.TryRemove($insertKey, [ref]$discard)
            $discardAt = [long]0
            [void]$Shared.ToolboxInsertAt.TryRemove($insertKey, [ref]$discardAt)
            return $null
        }
        $stored = $null
        if (-not $Shared.ToolboxInsertResults.TryGetValue($insertKey, [ref]$stored)) { return $null }
        return [string]$stored
    }

    function Save-ToolboxInsertResult([string]$insertKey, [string]$resultJson) {
        if ([string]::IsNullOrWhiteSpace($insertKey) -or [string]::IsNullOrWhiteSpace($resultJson)) { return }
        $Shared.ToolboxInsertResults[$insertKey] = [string]$resultJson
        $Shared.ToolboxInsertAt[$insertKey] = (Get-UnixSeconds)
        # Obergrenze: der Idempotenz-Speicher darf nicht mitwachsen. Zuerst
        # alles ausserhalb des Fensters, danach - falls es IMMER NOCH zu viele
        # sind (viele verschiedene Assets in kurzer Zeit) - die aeltesten
        # Eintraege, bis die harte Grenze wieder eingehalten ist.
        if ($Shared.ToolboxInsertAt.Count -gt 64) {
            $cutoff = (Get-UnixSeconds) - [int]$Shared.ToolboxLimits.IdempotencyWindowSec
            foreach ($pair in $Shared.ToolboxInsertAt.GetEnumerator()) {
                if ([long]$pair.Value -lt $cutoff) {
                    $discard = $null
                    [void]$Shared.ToolboxInsertResults.TryRemove([string]$pair.Key, [ref]$discard)
                    $discardAt = [long]0
                    [void]$Shared.ToolboxInsertAt.TryRemove([string]$pair.Key, [ref]$discardAt)
                }
            }
            while ($Shared.ToolboxInsertAt.Count -gt 64) {
                $oldestKey = $null
                $oldestAt = [long]::MaxValue
                foreach ($pair in $Shared.ToolboxInsertAt.GetEnumerator()) {
                    if ([long]$pair.Value -lt $oldestAt) { $oldestAt = [long]$pair.Value; $oldestKey = [string]$pair.Key }
                }
                if ($null -eq $oldestKey) { break }
                $discard = $null
                [void]$Shared.ToolboxInsertResults.TryRemove($oldestKey, [ref]$discard)
                $discardAt = [long]0
                [void]$Shared.ToolboxInsertAt.TryRemove($oldestKey, [ref]$discardAt)
            }
        }
    }

    function Get-ToolboxImportLock([string]$sessionId) {
        $raw = $null
        if (-not $Shared.ToolboxImportLocks.TryGetValue([string]$sessionId, [ref]$raw)) { return $null }
        try { return ($raw | ConvertFrom-Json) } catch { return $null }
    }

    function Enter-ToolboxImport([string]$sessionId, [string]$insertKey, $toolArgs) {
        $sid = [string]$sessionId
        $now = Get-UnixSeconds
        $wedgedAfter = [int]$Shared.ToolboxLimits.ImportWedgedAfterSec
        $recovery = 'SAFE RECOVERY: tell the user (in German) to close Roblox Studio COMPLETELY (all Studio windows) and open the place again. A native InsertService:LoadAsset that never returns can only be freed by a Studio restart - Roblox offers no way to abort it. Do NOT retry the import and do NOT start a second one; check the place for a partially inserted model first. When Studio is back, build the model procedurally (build_polygon_model / build_assembly) instead of importing it.'
        [System.Threading.Monitor]::Enter($Shared.ToolboxSlotLock)
        try {
            $existing = Get-ToolboxImportLock $sid
            if ($null -ne $existing) {
                $startedAt = 0
                try { $startedAt = [long]$existing.startedAt } catch {}
                $runningFor = [int][Math]::Max(0, $now - $startedAt)
                $wedged = $false
                try { $wedged = [bool]$existing.wedged } catch {}
                if ($wedged -or $runningFor -ge $wedgedAfter) {
                    $existing | Add-Member -NotePropertyName 'wedged' -NotePropertyValue $true -Force
                    $Shared.ToolboxImportLocks[$sid] = (To-Json $existing 8)
                    return @{ ok = $false; result = @{
                        ok = $false
                        code = 'TOOLBOX_IMPORT_WEDGED'
                        importWedged = $true
                        error = ("A previous insert_asset (assetId " + [string]$existing.assetId + ") has been stuck inside the native InsertService:LoadAsset call for " + [string]$runningFor + " seconds. Further imports are BLOCKED for this place so Studio is not loaded up further.")
                        stuckAssetId = [string]$existing.assetId
                        stuckForSeconds = $runningFor
                        cancellable = $false
                        whyNotCancellable = 'Roblox cannot abort a running InsertService:LoadAsset. The bridge does not pretend to cancel it.'
                        howToFix = $recovery
                        workIsLost = $false
                    } }
                }
                return @{ ok = $false; result = @{
                    ok = $false
                    code = 'TOOLBOX_IMPORT_IN_FLIGHT'
                    toolboxBusy = $true
                    error = ("This place is already importing assetId " + [string]$existing.assetId + " (" + [string]$runningFor + " s). Only ONE asset import per place is allowed, so this call was NOT started.")
                    runningAssetId = [string]$existing.assetId
                    runningSeconds = $runningFor
                    howToFix = 'Wait for the running import to answer and then send this call again. Never run asset imports in parallel and never poll in a loop.'
                    workIsLost = $false
                } }
            }
            $lock = @{ assetId = [string]$toolArgs.assetId; insertKey = [string]$insertKey; startedAt = $now; wedged = $false }
            $Shared.ToolboxImportLocks[$sid] = (To-Json $lock 8)
            return @{ ok = $true; result = $null }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.ToolboxSlotLock)
        }
    }

    function Exit-ToolboxImport([string]$sessionId) {
        $discard = $null
        [void]$Shared.ToolboxImportLocks.TryRemove([string]$sessionId, [ref]$discard)
    }

    function Set-ToolboxImportUnconfirmed([string]$sessionId) {
        # Kein Ergebnis vor der HTTP-Frist: die Sperre bleibt ABSICHTLICH
        # stehen. Der native Ladevorgang kann noch laufen; ein zweiter Import
        # wuerde doppelt einfuegen und Studio zusaetzlich belasten.
        $existing = Get-ToolboxImportLock $sessionId
        if ($null -eq $existing) { return }
        $existing | Add-Member -NotePropertyName 'unconfirmed' -NotePropertyValue $true -Force
        $Shared.ToolboxImportLocks[[string]$sessionId] = (To-Json $existing 8)
    }

    function Invoke-AssetSearch($toolArgs) {
        # TYP-NORMALISIERUNG: Die Roblox-Marketplace-API kennt NICHT 'image'
        # und NICHT 'mesh' - genau deshalb liefen Texturen/Meshes vorher ins
        # Leere. Jetzt wird auf das gemappt, was wirklich da ist.
        $type = ([string]$toolArgs.type).ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($type)) { $type = 'audio' }
        $typeMap = @{
            'audio'     = 'audio'
            'sound'     = 'audio'
            'music'     = 'music'
            'model'     = 'model'
            'decal'     = 'decal'
            'video'     = 'video'
            'animation' = 'animation'
            'image'     = 'decal'
            'texture'   = 'decal'
            'mesh'      = 'mesh'
            'meshes'    = 'mesh'
            'meshpart'  = 'mesh'
            'plugin'    = 'plugin'
            'plugins'   = 'plugin'
            'font'      = 'font'
            'fonts'     = 'font'
        }
        if (-not $typeMap.ContainsKey($type)) {
            return @{
                ok = $false
                code = 'CATALOG_TYPE_NOT_SUPPORTED'
                error = "Asset type '$type' cannot be searched in the catalog."
                supportedTypes = @('audio', 'music', 'decal', 'image', 'texture', 'mesh', 'meshpart', 'model', 'plugin', 'font', 'video', 'animation')
            }
        }
        $apiType = $typeMap[$type]
        $typeNote = $null
        if ($apiType -ne $type) {
            if ($apiType -eq 'decal') {
                $typeNote = "The catalog API has no '$type' search - I searched DECALS instead. Decal assets are textures: use them on 'Texture' (Part/Decal) or 'Image' (ImageLabel/ImageButton)."
            } else {
                $typeNote = "The request uses the Creator Store's current MESH category. Mesh and MeshPart results can be inserted with insert_asset; bare mesh ids can also be applied to SpecialMesh.MeshId."
            }
        }
        # Toolbox-Modelle dürfen gesucht und als Metadaten abgerufen werden.
        # Das Sicherheits-Gate bleibt beim tatsächlichen Einfügen: Scripts in
        # einem Modell werden dort weiterhin erkannt und nicht blind platziert.

        $keyword = [string]$toolArgs.query
        if ([string]::IsNullOrWhiteSpace($keyword)) { $keyword = [string]$toolArgs.keyword }
        $limit = 20
        if ($toolArgs.limit) { $limit = [Math]::Min([int]$toolArgs.limit, 50) }
        $page = 0
        if ($toolArgs.page) { $page = [int]$toolArgs.page }
        $sortType = 0
        if ($toolArgs.sortType) { $sortType = [int]$toolArgs.sortType }
        $sortNames = @{ 0 = 'relevance'; 1 = 'favorited'; 3 = 'updated'; 4 = 'priceAsc'; 5 = 'priceDesc' }

        # ---------------- Cache (7 Tage) ----------------
        $cacheKey = "search|${apiType}|${keyword}|${page}|${sortType}"
        if ($toolArgs.refresh -ne $true) {
            $cached = Get-CacheEntry (Read-AssetCache) $cacheKey 7
            if ($null -ne $cached) {
                return @{
                    ok = $true
                    catalogAvailable = $true
                    cached = $true
                    cachedNote = 'Served from the local cache (fetched earlier - not reloaded from the catalog). Pass refresh=true to force a new catalog query.'
                    result = $cached
                }
            }
        }

        $searchUrl = 'https://apis.roblox.com/toolbox-service/v1/marketplace/' + $apiType +
            '?keyword=' + [uri]::EscapeDataString($keyword) +
            '&limit=' + $limit + '&pageNumber=' + $page + '&sortType=' + $sortType

        # Version 7.1.2: EIN Versuch mit hartem Zeitlimit. Die alte Schleife
        # wiederholte nach einem Timeout automatisch (2 x 20 s + 1,5 s Pause) -
        # genau das verbot sich, weil ein nicht antwortender Katalog dadurch
        # die HTTP-Anfrage ueber eine Minute festhielt.
        $budget = [System.Diagnostics.Stopwatch]::StartNew()
        $searchCall = Invoke-CatalogHttp $searchUrl
        if (-not $searchCall.ok) { return (New-CatalogErrorResult $searchCall 'searching the catalog') }
        $searchResult = $searchCall.data

        $ids = @()
        foreach ($item in @($searchResult.data)) {
            if ($item.id) { $ids += [string]$item.id }
        }

        $assets = @()
        $detailsFailed = $false
        $detailsTimedOut = $false
        # Version 7.1.2: Der Detailabruf bekommt nur noch das, was vom
        # Gesamtbudget uebrig ist - der Aufruf kann die 100-s-Tunnelgrenze
        # damit nicht mehr reissen.
        $remaining = [int]([int]$Shared.ToolboxLimits.CatalogBudgetSec - [int]$budget.Elapsed.TotalSeconds)
        if ($ids.Count -gt 0 -and $remaining -lt 3) {
            $detailsFailed = $true
            $detailsTimedOut = $true
            foreach ($id in $ids) {
                $assets += @{ assetId = $id; useAs = 'rbxassetid://' + $id; note = 'Details were skipped because the catalog budget for this call was already used up - verify with validate_asset before applying.' }
            }
        } elseif ($ids.Count -gt 0) {
            $detailUrl = 'https://apis.roblox.com/toolbox-service/v1/items/details?assetIds=' + ($ids -join ',')
            $detailCall = Invoke-CatalogHttp $detailUrl $remaining
            if ($detailCall.ok) {
                $details = $detailCall.data
                $freshDetails = @{}
                foreach ($entry in @($details.data)) {
                    $asset = $entry.asset
                    $creator = $entry.creator
                    $item = @{
                        assetId     = $asset.id
                        name        = $asset.name
                        typeId      = $asset.typeId
                        typeName    = (Get-AssetTypeUsage ([int]$asset.typeId)).typeName
                        description = $asset.description
                        duration    = $asset.duration
                        created     = $asset.createdUtc
                        updated     = $asset.updatedUtc
                        endorsed    = $asset.isEndorsed
                        hasScripts  = $asset.hasScripts
                        creator     = $creator.name
                        creatorVerified = $creator.isVerifiedCreator
                        useAs       = 'rbxassetid://' + [string]$asset.id
                    }
                    if ($asset.audioDetails) {
                        $item.audioType = $asset.audioDetails.audioType
                        $item.artist = $asset.audioDetails.artist
                    }
                    $assets += $item
                    $freshDetails[[string]$asset.id] = $entry
                }
                # Details in EINEM Zug cachen (eine Datei, kein Schreibsturm)
                $detailPairs = @{}
                foreach ($key in $freshDetails.Keys) { $detailPairs['detail|' + [string]$key] = $freshDetails[$key] }
                Add-CacheEntries $detailPairs
                $freshDetails = $null
                $detailPairs = $null
            } else {
                $detailsFailed = $true
                $detailsTimedOut = [bool]$detailCall.timedOut
                foreach ($id in $ids) {
                    $assets += @{ assetId = $id; useAs = 'rbxassetid://' + $id; note = 'Details could not be loaded - verify with validate_asset before applying.' }
                }
            }
            $detailCall = $null
            $details = $null
        }

        $note = 'Apply an asset with apply_asset (sets Texture/SoundId/Image/MeshId automatically and validates the type BEFORE applying) or set the property to the useAs value. Meshes/MeshParts/Models need insert_asset.'
        if ($type -eq 'model') {
            $note = 'Toolbox model: when only geometry is needed, STRONGLY prefer insert_asset sanitize=true. It removes every script plus Remote/Bindable events and functions before the asset enters the Place. Without sanitation, scripted models are blocked with ASSET_HAS_SCRIPTS unless explicitly trusted.'
        }
        $resultObject = @{
            assets      = $assets
            count       = $assets.Count
            type        = $type
            apiType     = $apiType
            keyword     = $keyword
            page        = $page
            sortType    = $sortType
            sortName    = $sortNames[[int]$sortType]
            totalResults = if ($searchResult -and $searchResult.totalResults) { [int]$searchResult.totalResults } else { $null }
            typeNote    = $typeNote
            note        = $note
        }
        if ($detailsFailed) {
            $resultObject.detailsWarning = 'The detail lookup failed, so names/types above are incomplete. Verify ids with validate_asset before applying them.'
            if ($detailsTimedOut) {
                $resultObject.detailsTimedOut = $true
                $resultObject.detailsWarning = 'The detail lookup hit the hard catalog time limit and was ABORTED (nothing is still running). The ids above are usable, the names/types are not. Do not retry in a loop.'
            }
        }
        if ($ids.Count -eq 0) {
            $resultObject.note = "No results for '$keyword'. Try a shorter or more common (English) keyword, or another sort type (sortType 3 = recently updated)."
        }

        Add-CacheEntry $cacheKey $resultObject
        # Version 7.1.2: grosse Zwischenantworten sofort freigeben, damit sie
        # nicht bis zum Ende des Runspace-Aufrufs im Speicher stehen.
        $searchResult = $null
        $searchCall = $null
        $budget.Stop()
        return @{
            ok = $true
            catalogAvailable = $true
            cached = $false
            result = $resultObject
            catalogMs = [int]$budget.ElapsedMilliseconds
        }
    }

    function Invoke-AssetDetails($toolArgs) {
        $ids = @()
        foreach ($id in @($toolArgs.assetIds)) { if ($id) { $ids += [string]$id } }
        if ($toolArgs.assetId) { $ids += [string]$toolArgs.assetId }
        if ($ids.Count -eq 0) { return @{ ok = $false; code = 'REF_NOT_FOUND'; error = 'assetIds missing.' } }
        $uniqueIds = @($ids | Select-Object -Unique)
        # Version 7.1.2: Obergrenze fuer eine einzelne Abfrage. Vorher konnte
        # eine Liste beliebiger Laenge im 404-Fall je Id eine eigene
        # 20-Sekunden-Anfrage ausloesen (unbegrenzte Gesamtlaufzeit).
        $maxIds = [int]$Shared.ToolboxLimits.MaxDetailIdsPerCall
        $idsTruncated = $false
        if ($uniqueIds.Count -gt $maxIds) {
            $uniqueIds = @($uniqueIds[0..($maxIds - 1)])
            $idsTruncated = $true
        }
        $results = @()
        $missing = @()
        # Den Cache EINMAL lesen - nicht je Id die ganze Datei neu parsen.
        $cacheSnapshot = Read-AssetCache
        foreach ($id in $uniqueIds) {
            $cached = Get-CacheEntry $cacheSnapshot ('detail|' + $id) 30
            if ($null -ne $cached) {
                $results += $cached
            } else {
                $missing += $id
            }
        }
        $cacheSnapshot = $null
        $budget = [System.Diagnostics.Stopwatch]::StartNew()
        if ($missing.Count -gt 0) {
            $detailUrl = 'https://apis.roblox.com/toolbox-service/v1/items/details?assetIds=' + ($missing -join ',')
            $batchCall = Invoke-CatalogHttp $detailUrl
            if ($batchCall.ok) {
                $freshPairs = @{}
                foreach ($entry in @($batchCall.data.data)) {
                    $results += $entry
                    $freshPairs['detail|' + [string]$entry.asset.id] = $entry
                }
                Add-CacheEntries $freshPairs
                $freshPairs = $null
            } elseif ($batchCall.notFound) {
                # Batch fehlgeschlagen, weil MINDESTENS eine Id unbekannt ist:
                # einzeln nachfragen - aber mit HARTEM Gesamtbudget, damit ein
                # langsamer Katalog die Anfrage nicht endlos festhaelt.
                $unknown = @()
                $skipped = @()
                $singlePairs = @{}
                foreach ($id in $missing) {
                    $left = [int]([int]$Shared.ToolboxLimits.CatalogBudgetSec - [int]$budget.Elapsed.TotalSeconds)
                    if ($left -lt 3) { $skipped += $id; continue }
                    $singleCall = Invoke-CatalogHttp ('https://apis.roblox.com/toolbox-service/v1/items/details?assetIds=' + $id) ([Math]::Min(6, $left))
                    if ($singleCall.ok) {
                        $singleData = @($singleCall.data.data)
                        if ($singleData.Count -gt 0) {
                            $results += $singleData
                            $singlePairs['detail|' + $id] = $singleData[0]
                        } else {
                            $unknown += $id
                        }
                    } elseif ($singleCall.notFound) {
                        $unknown += $id
                    } else {
                        $skipped += $id
                    }
                }
                Add-CacheEntries $singlePairs
                $singlePairs = $null
                $unknownNote = @()
                foreach ($id in $unknown) {
                    $unknownNote += "Asset $id does NOT exist or is not public (404) - do not use it."
                }
                foreach ($id in $skipped) {
                    $unknownNote += "Asset $id was NOT checked: the hard catalog time budget for this call ran out. Do not retry in a loop."
                }
                if ($idsTruncated) { $unknownNote += "Only the first $maxIds asset ids were looked up; ask for the rest in a SEPARATE call." }
                $budget.Stop()
                return @{
                    ok = $true
                    catalogAvailable = $true
                    result = @{ assets = $results; unknownAssets = $unknown; uncheckedAssets = $skipped; idsTruncated = $idsTruncated }
                    warnings = $unknownNote
                    catalogMs = [int]$budget.ElapsedMilliseconds
                }
            } else {
                $budget.Stop()
                return (New-CatalogErrorResult $batchCall 'loading asset details')
            }
            $batchCall = $null
        }
        $budget.Stop()
        $detailsResult = @{ ok = $true; catalogAvailable = $true; result = @{ assets = $results; idsTruncated = $idsTruncated }; catalogMs = [int]$budget.ElapsedMilliseconds }
        if ($idsTruncated) { $detailsResult.warnings = @("Only the first $maxIds asset ids were looked up; ask for the rest in a SEPARATE call.") }
        return $detailsResult
    }

    # ------------------------------------------------------------------
    # ASSET-TYpVALIDIERUNG: passt die Id wirklich zum Typ, BEVOR eingebaut?
    # ------------------------------------------------------------------
    function Invoke-AssetValidation($toolArgs) {
        $id = $null
        if ($toolArgs.assetId) { $id = [string]$toolArgs.assetId }
        if ([string]::IsNullOrWhiteSpace($id) -and $toolArgs.assetIds -and @($toolArgs.assetIds).Count -ge 1) {
            $id = [string](@($toolArgs.assetIds))[0]
        }
        if ([string]::IsNullOrWhiteSpace($id)) { return @{ ok = $false; code = 'REF_NOT_FOUND'; error = 'assetId missing.' } }
        $expect = ([string]$toolArgs.expectType).ToLowerInvariant()

        $entry = Get-CacheEntry (Read-AssetCache) ('detail|' + $id) 30
        if ($null -eq $entry) {
            # Version 7.1.2: ein Versuch, hartes Zeitlimit, keine Wiederholung.
            # Diese Pruefung laeuft VOR jedem insert_asset auf DERSELBEN
            # HTTP-Anfrage - sie darf das Tunnel-Zeitfenster nicht aufbrauchen.
            $validateCall = Invoke-CatalogHttp ('https://apis.roblox.com/toolbox-service/v1/items/details?assetIds=' + $id) 8
            if ($validateCall.ok) {
                $entry = @($validateCall.data.data)[0]
                if ($null -ne $entry) { Add-CacheEntry ('detail|' + $id) $entry }
            } elseif ($validateCall.notFound) {
                return @{
                    ok = $false
                    code = 'ASSET_NOT_FOUND'
                    verified = $false
                    assetId = $id
                    error = "Asset $id does not exist or is not public (catalog answered 404). This id MUST NOT be used - it would fail at runtime."
                }
            } else {
                return @{
                    ok = $true
                    verified = $false
                    assetId = $id
                    code = $(if ($validateCall.timedOut) { 'CATALOG_TIMEOUT' } else { 'CATALOG_UNAVAILABLE' })
                    catalogAvailable = $false
                    timedOutAfterMs = [int]$validateCall.elapsedMs
                    note = 'Could not verify the asset because the catalog did not answer inside the hard time limit. The check was ABORTED. Applying is still allowed, but it may fail at runtime - prefer verified ids or build procedurally. Do not retry in a loop.'
                }
            }
            $validateCall = $null
        }
        if ($null -eq $entry) {
            return @{ ok = $false; code = 'ASSET_NOT_FOUND'; verified = $false; assetId = $id; error = "Asset $id was not found in the catalog. This id MUST NOT be used." }
        }
        $asset = $entry.asset
        $typeId = [int]$asset.typeId
        $usage = Get-AssetTypeUsage $typeId
        $matchesExpect = $null
        if ($expect -ne '') {
            $expectedIds = @()
            switch ($expect) {
                'audio'     { $expectedIds = @(3) }
                'music'     { $expectedIds = @(3) }
                'sound'     { $expectedIds = @(3) }
                'image'     { $expectedIds = @(1, 13) }
                'texture'   { $expectedIds = @(1, 13) }
                'decal'     { $expectedIds = @(13, 1) }
                'mesh'      { $expectedIds = @(4, 40) }
                'model'     { $expectedIds = @(10) }
                'plugin'    { $expectedIds = @(38) }
                'font'      { $expectedIds = @(73) }
                'animation' { $expectedIds = @(24) }
                'video'     { $expectedIds = @(62) }
                default     { $expectedIds = @() }
            }
            $matchesExpect = ($expectedIds -contains $typeId)
        }
        $note = 'Verified: the id exists and matches the expected type.'
        if ($null -ne $matchesExpect -and -not $matchesExpect) {
            $note = "TYPE MISMATCH: asset $id is a $($usage.typeName) (typeId $typeId), but '$expect' was expected. Do not apply it - search_assets for the right type or pick another id."
        }
        return @{
            ok = $true
            verified = $true
            catalogAvailable = $true
            assetId = $id
            assetName = [string]$asset.name
            typeId = $typeId
            typeName = $usage.typeName
            usableAs = $usage.usableAs
            hasScripts = [bool]$asset.hasScripts
            creator = [string]$entry.creator.name
            matchesExpect = $matchesExpect
            note = $note
        }
    }

    # ------------------------------------------------------------------
    # KATALOG-ERREICHBARKEIT (Schnelltest)
    # ------------------------------------------------------------------
    function Invoke-CatalogStatus($toolArgs) {
        # Version 7.1.2: EIN kurzer Sondierungsaufruf mit hartem Zeitlimit.
        $probe = Invoke-CatalogHttp 'https://apis.roblox.com/toolbox-service/v1/items/details?assetIds=155016084' 8
        if ($probe.ok) {
            return @{ ok = $true; result = @{ catalogAvailable = $true; latencyMs = [int]$probe.elapsedMs } }
        }
        return @{
            ok = $true
            result = @{
                catalogAvailable = $false
                timedOut = [bool]$probe.timedOut
                latencyMs = [int]$probe.elapsedMs
                protocol = 'The catalog is NOT reachable. Say so clearly to the user ("Katalog nicht verfuegbar") and build assets procedurally instead of guessing ids. Retry later - this test is cheap.'
            }
        }
    }

    # ------------------------------------------------------------------
    # Version 7.1.2: ALLE Katalog-/Asset-Werkzeuge laufen durch EIN Tor.
    # Der Slot wird in finally IMMER freigegeben - auch bei Ausnahme,
    # Timeout oder abgebrochenem Client. Vorher konnte ein Fehler im
    # Katalogpfad den Place dauerhaft als "beschaeftigt" hinterlassen.
    # ------------------------------------------------------------------
    function Invoke-ToolboxServerTool($sessionId, [string]$tool, $toolArgs) {
        $slot = Enter-ToolboxSlot $sessionId $tool
        if (-not $slot.ok) { return $slot.result }
        try {
            switch ($tool) {
                'search_assets'  { return (Invoke-AssetSearch $toolArgs) }
                'asset_details'  { return (Invoke-AssetDetails $toolArgs) }
                'validate_asset' { return (Invoke-AssetValidation $toolArgs) }
                'catalog_status' { return (Invoke-CatalogStatus $toolArgs) }
            }
            return $null
        } catch {
            Write-BridgeLog ("Toolbox-Werkzeug '" + [string]$tool + "' ist mit einer Ausnahme beendet worden: " + $_.Exception.Message)
            return @{
                ok = $false
                code = 'TOOLBOX_FAILED'
                error = ("The catalog tool '" + [string]$tool + "' failed with an internal error: " + $_.Exception.Message)
                howToFix = 'This is a final answer, not a hang. Continue procedurally or try catalog_status once.'
                workIsLost = $false
            }
        } finally {
            Exit-ToolboxSlot $slot.sessionKey
        }
    }

    # ------------------------------------------------------------------
    # SCREENSHOT (bewusst unbeliebt gemacht - siehe Manifest)
    # ------------------------------------------------------------------
    function Invoke-Screenshot($toolArgs) {
        $advice = 'Screenshot captured. Textual scene tools are also available when exact object values are useful.'
        # Der eigentliche Code steckt in einem erst bei Bedarf erzeugten
        # Block. Grund: PowerShell löst Typangaben wie [System.Drawing...]
        # schon beim Übersetzen einer Funktion auf. Fehlt oder klemmt
        # System.Drawing, würden sonst ALLE Werkzeuge ausfallen - nur wegen
        # der Screenshot-Funktion, von der ohnehin abgeraten wird.
        $shotCode = [scriptblock]::Create(@'
param($toolArgs, $shotFolder, $advice)
Add-Type -AssemblyName System.Drawing -ErrorAction Stop
$process = Get-Process -Name 'RobloxStudioBeta', 'RobloxStudio' -ErrorAction SilentlyContinue |
    Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
if (-not $process) {
    return @{ ok = $false; error = 'No visible Roblox Studio window found.'; advice = $advice }
}
$rect = New-Object Arena.RECT
[void][Arena.ScreenHelper]::GetWindowRect($process.MainWindowHandle, [ref]$rect)
$width = $rect.Right - $rect.Left
$height = $rect.Bottom - $rect.Top
if ($width -le 0 -or $height -le 0) {
    return @{ ok = $false; error = 'The Studio window is minimised or hidden.'; advice = $advice }
}
$bitmap = New-Object System.Drawing.Bitmap $width, $height
$graphics = [System.Drawing.Graphics]::FromImage($bitmap)
$graphics.CopyFromScreen($rect.Left, $rect.Top, 0, 0, (New-Object System.Drawing.Size $width, $height))
$graphics.Dispose()

$maxWidth = 1100
if ($toolArgs.maxWidth) { $maxWidth = [int]$toolArgs.maxWidth }
$final = $bitmap
if ($width -gt $maxWidth) {
    $scale = $maxWidth / [double]$width
    $newWidth = [int]($width * $scale)
    $newHeight = [int]($height * $scale)
    $resized = New-Object System.Drawing.Bitmap $newWidth, $newHeight
    $resizeGraphics = [System.Drawing.Graphics]::FromImage($resized)
    $resizeGraphics.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
    $resizeGraphics.DrawImage($bitmap, 0, 0, $newWidth, $newHeight)
    $resizeGraphics.Dispose()
    $bitmap.Dispose()
    $final = $resized
}

$fileName = 'studio_' + (Get-Date).ToString('yyyyMMdd_HHmmss') + '.png'
$filePath = Join-Path $shotFolder $fileName
$final.Save($filePath, [System.Drawing.Imaging.ImageFormat]::Png)
$shotWidth = $final.Width
$shotHeight = $final.Height
$final.Dispose()
return @{ ok = $true; file = $filePath; width = $shotWidth; height = $shotHeight }
'@)

        try {
            $shot = & $shotCode $toolArgs $Shared.ShotFolder $advice
        } catch {
            return @{ ok = $false; error = "Screenshot failed: $($_.Exception.Message)"; advice = $advice }
        }
        if (-not $shot.ok) { return $shot }

        $result = @{
            ok = $true
            result = @{
                file = $shot.file
                width = $shot.width
                height = $shot.height
                advice = $advice
            }
        }
        if ($toolArgs.includeBase64 -eq $true) {
            try {
                $bytes = [System.IO.File]::ReadAllBytes([string]$shot.file)
                $blob = New-Blob ([Convert]::ToBase64String($bytes)) 'capture_screenshot'
                $result.result.base64Blob = $blob
                $result.result.base64Note = 'Fetch the picture with get_chunk and decode base64. Seriously: describe_scene is better.'
            } catch {
                $result.result.base64Error = $_.Exception.Message
            }
        }
        return $result
    }

    # ------------------------------------------------------------------
    # BEFEHL AN DAS STUDIO-PLUGIN SCHICKEN
    # Der wartende Long-Poll wird sofort geweckt -> keine Verzögerung.
    # ------------------------------------------------------------------
    function Get-PlayRetryFingerprint([string]$tool, $toolArgs) {
        return $tool + ':' + (To-Json $toolArgs 20)
    }

    function Get-DedupedPlayResult($sessionId, [string]$tool, $toolArgs) {
        if ($tool -ne 'sim_stop') { return $null }
        $key = [string]$sessionId + ':' + $tool
        $raw = $null
        if (-not $Shared.PlayRetryDedupe.TryGetValue($key, [ref]$raw)) { return $null }
        try {
            $item = $raw | ConvertFrom-Json
            if ((Get-UnixSeconds) - [int64]$item.at -le 3 -and [string]$item.fingerprint -eq (Get-PlayRetryFingerprint $tool $toolArgs)) { return [string]$item.resultJson }
        } catch {}
        return $null
    }

    function Save-DedupedPlayResult($sessionId, [string]$tool, $toolArgs, [string]$resultJson) {
        if ($tool -ne 'sim_stop' -or [string]::IsNullOrWhiteSpace($resultJson)) { return }
        $key = [string]$sessionId + ':' + $tool
        $Shared.PlayRetryDedupe[$key] = (To-Json @{ at=(Get-UnixSeconds); fingerprint=(Get-PlayRetryFingerprint $tool $toolArgs); resultJson=$resultJson } 30)
    }

    function Reserve-PlayRetry($sessionId, [string]$tool, $toolArgs) {
        if ($tool -ne 'sim_stop') { return $true }
        $key = [string]$sessionId + ':' + $tool
        $fingerprint = Get-PlayRetryFingerprint $tool $toolArgs
        $now = Get-UnixSeconds
        $existing = $null
        if ($Shared.PlayRetryDedupe.TryGetValue($key, [ref]$existing)) {
            try {
                $entry = $existing | ConvertFrom-Json
                if (($now - [int64]$entry.at) -le 3 -and [string]$entry.fingerprint -eq $fingerprint) { return $false }
            } catch {}
            $discard = $null
            [void]$Shared.PlayRetryDedupe.TryRemove($key, [ref]$discard)
        }
        # Reserve before the command is enqueued. A simultaneous retry sees this
        # small JSON answer and cannot start a second Play/Stop action.
        $pendingJson = '{"ok":true,"deduplicated":true,"pending":true,"note":"Identical play retry is already executing; use get_pending/lateResults instead of retrying."}'
        $reservation = (To-Json @{ at=$now; fingerprint=$fingerprint; resultJson=$pendingJson } 20)
        return $Shared.PlayRetryDedupe.TryAdd($key, $reservation)
    }

    function Get-CommandArgumentValue($arguments, [string]$name) {
        if ($null -eq $arguments) { return @{ found=$false; value=$null } }
        try {
            if ($arguments -is [System.Collections.IDictionary]) {
                if ($arguments.Contains($name)) { return @{ found=$true; value=$arguments[$name] } }
            } elseif ($arguments.PSObject.Properties[$name]) {
                return @{ found=$true; value=$arguments.PSObject.Properties[$name].Value }
            }
        } catch {}
        return @{ found=$false; value=$null }
    }

    function ConvertTo-CommandNumber($value, [double]$default = 0) {
        if ($null -eq $value) { return $default }
        if ($value -is [ValueType]) { try { return [double]$value } catch { return $default } }
        $parsed = 0.0
        $styles = [System.Globalization.NumberStyles]::Float
        $culture = [System.Globalization.CultureInfo]::InvariantCulture
        if ([double]::TryParse([string]$value, $styles, $culture, [ref]$parsed)) { return $parsed }
        return $default
    }

    function Get-CommandNumber($arguments, [string]$name, [double]$default = 0) {
        $candidate = Get-CommandArgumentValue $arguments $name
        if (-not $candidate.found) { return $default }
        return (ConvertTo-CommandNumber $candidate.value $default)
    }

    function Test-CommandArgumentPresent($arguments, [string]$name) {
        $candidate = Get-CommandArgumentValue $arguments $name
        if (-not $candidate.found -or $null -eq $candidate.value) { return $false }
        if ($candidate.value -is [string] -and [string]::IsNullOrWhiteSpace($candidate.value)) { return $false }
        if ($candidate.value -is [System.Array] -and $candidate.value.Count -eq 0) { return $false }
        return $true
    }

    function Get-CommandSchemaIndex {
        $index = $Shared.ToolSchemaIndex
        if ($null -ne $index) { return ,$index }
        $lock = $Shared.ToolSchemaLock
        [System.Threading.Monitor]::Enter($lock)
        try {
            $index = $Shared.ToolSchemaIndex
            if ($null -eq $index) {
                $index = @{}
                foreach ($doc in (Get-ToolDocs)) {
                    if ($doc -and $doc.name) { $index[[string]$doc.name] = $doc }
                }
                $Shared.ToolSchemaIndex = $index
            }
        } finally {
            [System.Threading.Monitor]::Exit($lock)
        }
        return ,$index
    }

    function Test-CommandArguments([string]$tool, $toolArgs) {
        if ([string]::IsNullOrWhiteSpace($tool)) {
            return @{ ok=$false; code='BAD_ARGS'; error='tool is required.' }
        }
        if ($null -eq $toolArgs) { $toolArgs = New-Object PSObject }
        if ($toolArgs -is [string] -or $toolArgs -is [System.Array] -or $toolArgs -is [ValueType]) {
            return @{ ok=$false; code='BAD_ARGS'; error='args must be a JSON object (for example {"ref":"game.Workspace"}), not a scalar or array.' }
        }
        $schemaIndex = Get-CommandSchemaIndex
        $schema = $null
        if ($schemaIndex.ContainsKey($tool)) { $schema = $schemaIndex[$tool] }
        if (-not $schema) {
            return @{ ok=$false; code='UNKNOWN_TOOL'; error="Unknown tool '$tool'."; hint='Call list_tools or GET /api/docs for the current tool list.' }
        }
        $params = $schema.params
        if ($null -eq $params -or -not ($params -is [System.Collections.IDictionary])) { return @{ ok=$true } }
        $missing = New-Object System.Collections.Generic.List[string]
        foreach ($name in $params.Keys) {
            $spec = $params[$name]
            if ($spec.required -ne $true) { continue }
            $found = Get-CommandArgumentValue $toolArgs ([string]$name)
            $value = $found.value
            $empty = (-not $found.found -or $null -eq $value)
            if (-not $empty -and $value -is [string] -and [string]::IsNullOrWhiteSpace($value)) { $empty = $true }
            if (-not $empty -and $value -is [System.Array] -and $value.Count -eq 0) { $empty = $true }
            # These source-taking tools also accept the uploaded-text handle.
            if ($empty -and [string]$name -eq 'source' -and $tool -in @('compile_check','run_lua')) {
                $sourceRef = Get-CommandArgumentValue $toolArgs 'sourceRef'
                if ($sourceRef.found -and -not [string]::IsNullOrWhiteSpace([string]$sourceRef.value)) { $empty = $false }
            }
            if ($empty) { $missing.Add([string]$name) }
        }
        if ($missing.Count -gt 0) {
            return @{
                ok=$false
                code='BAD_ARGS'
                error=('Missing required argument(s): ' + ($missing -join ', ') + '.')
                missing=$missing.ToArray()
                tool=$tool
                hint='Arguments were rejected before queueing; fix them and retry. No Studio command was sent.'
            }
        }
        $argumentError = $null
        switch ($tool) {
            'ground_height' {
                $hasPositions = (Test-CommandArgumentPresent $toolArgs 'points') -or (Test-CommandArgumentPresent $toolArgs 'positions')
                $hasGrid = (Test-CommandArgumentPresent $toolArgs 'min') -and (Test-CommandArgumentPresent $toolArgs 'max')
                if (-not $hasPositions -and -not $hasGrid) { $argumentError = 'ground_height needs points/positions or both min and max.' }
            }
            'raycast_many' {
                if (-not (Test-CommandArgumentPresent $toolArgs 'rays') -and -not (Test-CommandArgumentPresent $toolArgs 'casts')) { $argumentError = 'raycast_many needs rays (or the casts alias).' }
            }
            'measure' {
                $hasFrom = (Test-CommandArgumentPresent $toolArgs 'refA') -or (Test-CommandArgumentPresent $toolArgs 'ref')
                $hasTo = (Test-CommandArgumentPresent $toolArgs 'refB') -or (Test-CommandArgumentPresent $toolArgs 'targetRef')
                if (-not $hasFrom -or -not $hasTo) { $argumentError = 'measure needs refA/refB or the ref/targetRef aliases.' }
            }
            'measure_height' {
                if (-not (Test-CommandArgumentPresent $toolArgs 'ref') -and -not (Test-CommandArgumentPresent $toolArgs 'point')) { $argumentError = 'measure_height needs either ref or point={x,y,z}.' }
            }
            'snap_to_ground' {
                if (-not (Test-CommandArgumentPresent $toolArgs 'refs') -and -not (Test-CommandArgumentPresent $toolArgs 'ref')) { $argumentError = 'snap_to_ground needs refs or one ref.' }
            }
            'verify_measurable' {
                if (-not (Test-CommandArgumentPresent $toolArgs 'refs') -and -not (Test-CommandArgumentPresent $toolArgs 'ref')) { $argumentError = 'verify_measurable needs refs or one ref.' }
            }
            'parts_in_box' {
                $hasMinMax = (Test-CommandArgumentPresent $toolArgs 'min') -and (Test-CommandArgumentPresent $toolArgs 'max')
                $hasCenterSize = (Test-CommandArgumentPresent $toolArgs 'center') -and (Test-CommandArgumentPresent $toolArgs 'size')
                $hasRefs = (Test-CommandArgumentPresent $toolArgs 'refA') -and (Test-CommandArgumentPresent $toolArgs 'refB')
                if (-not $hasMinMax -and -not $hasCenterSize -and -not $hasRefs) { $argumentError = 'parts_in_box needs min+max, center+size, or refA+refB.' }
            }
            'parts_in_sphere' {
                if (-not (Test-CommandArgumentPresent $toolArgs 'center') -and -not (Test-CommandArgumentPresent $toolArgs 'ref')) { $argumentError = 'parts_in_sphere needs center or ref.' }
            }
            'overlap_check' {
                if (-not (Test-CommandArgumentPresent $toolArgs 'refs') -and -not (Test-CommandArgumentPresent $toolArgs 'ref')) { $argumentError = 'overlap_check needs refs or one ref.' }
            }
            'nearest_parts' {
                $hasOrigin = (Test-CommandArgumentPresent $toolArgs 'origin') -or (Test-CommandArgumentPresent $toolArgs 'position')
                $hasRef = (Test-CommandArgumentPresent $toolArgs 'ref') -or (Test-CommandArgumentPresent $toolArgs 'fromRef')
                if (-not $hasOrigin -and -not $hasRef) { $argumentError = 'nearest_parts needs origin/position or ref/fromRef.' }
            }
            'what_is_in_the_way' {
                $hasFrom = (Test-CommandArgumentPresent $toolArgs 'from') -or (Test-CommandArgumentPresent $toolArgs 'origin') -or (Test-CommandArgumentPresent $toolArgs 'fromRef')
                $hasTo = (Test-CommandArgumentPresent $toolArgs 'to') -or (Test-CommandArgumentPresent $toolArgs 'target') -or (Test-CommandArgumentPresent $toolArgs 'toRef')
                if (-not $hasFrom -or -not $hasTo) { $argumentError = 'what_is_in_the_way needs from/to, origin/target, or fromRef/toRef.' }
            }
        }
        if ($argumentError) {
            return @{ ok=$false; code='BAD_ARGS'; error=$argumentError; tool=$tool; hint='Arguments were rejected before queueing; no Studio command was sent.' }
        }
        if ($tool -eq 'probe_world') {
            $radius = Get-CommandNumber $toolArgs 'radius' 40
            $step = Get-CommandNumber $toolArgs 'step' 10
            if ($radius -lt 0 -or $step -le 0) {
                return @{ ok=$false; code='BAD_ARGS'; error='probe_world requires radius >= 0 and step > 0.'; tool=$tool; hint='Arguments were rejected before queueing; no Studio scan was started.' }
            }
            if ($step -lt 1) { $step = 1 }
            $axisCount = [Math]::Floor((2 * $radius + 0.001) / $step) + 1
            $estimatedSquare = $axisCount * $axisCount
            if ($estimatedSquare -gt 4000) {
                return @{ ok=$false; code='REGION_LIMIT'; error=('probe_world grid would contain about ' + $estimatedSquare + ' samples (max 4000); increase step or reduce radius.'); tool=$tool; sampleLimit=4000; estimatedSquare=$estimatedSquare; hint='Rejected before queueing; no Studio raycasts were started.' }
            }
        }
        if ($tool -eq 'ground_height') {
            $hasPositions = (Test-CommandArgumentPresent $toolArgs 'points') -or (Test-CommandArgumentPresent $toolArgs 'positions')
            if (-not $hasPositions -and (Test-CommandArgumentPresent $toolArgs 'min') -and (Test-CommandArgumentPresent $toolArgs 'max')) {
                $minArg = (Get-CommandArgumentValue $toolArgs 'min').value
                $maxArg = (Get-CommandArgumentValue $toolArgs 'max').value
                $minXArg = Get-CommandArgumentValue $minArg 'x'; $minZArg = Get-CommandArgumentValue $minArg 'z'
                $maxXArg = Get-CommandArgumentValue $maxArg 'x'; $maxZArg = Get-CommandArgumentValue $maxArg 'z'
                if ($minXArg.found -and $minZArg.found -and $maxXArg.found -and $maxZArg.found) {
                    $minX = ConvertTo-CommandNumber $minXArg.value [double]::NaN
                    $minZ = ConvertTo-CommandNumber $minZArg.value [double]::NaN
                    $maxX = ConvertTo-CommandNumber $maxXArg.value [double]::NaN
                    $maxZ = ConvertTo-CommandNumber $maxZArg.value [double]::NaN
                    if (-not [double]::IsNaN($minX) -and -not [double]::IsNaN($minZ) -and -not [double]::IsNaN($maxX) -and -not [double]::IsNaN($maxZ)) {
                        $step = [Math]::Max(0.5, (Get-CommandNumber $toolArgs 'step' 4))
                        $countX = [Math]::Floor(([Math]::Abs($maxX - $minX) + 0.001) / $step) + 1
                        $countZ = [Math]::Floor(([Math]::Abs($maxZ - $minZ) + 0.001) / $step) + 1
                        $estimatedSamples = $countX * $countZ
                        if ($estimatedSamples -gt 4000) {
                            return @{ ok=$false; code='REGION_LIMIT'; error=('ground_height grid would contain ' + $estimatedSamples + ' samples (max 4000); increase step or split the area.'); tool=$tool; sampleLimit=4000; estimatedSamples=$estimatedSamples; hint='Rejected before queueing; no Studio raycasts were started.' }
                        }
                    }
                }
            }
            foreach ($listName in @('points','positions')) {
                $listValue = Get-CommandArgumentValue $toolArgs $listName
                if ($listValue.found -and $listValue.value -is [System.Array] -and $listValue.value.Count -gt 4000) {
                    return @{ ok=$false; code='REGION_LIMIT'; error=($listName + ' contains ' + $listValue.value.Count + ' points (max 4000). Split the measurement.'); tool=$tool; argument=$listName; sampleLimit=4000; hint='Rejected before queueing; no Studio raycasts were started.' }
                }
            }
        }
        foreach ($name in $params.Keys) {
            $spec = $params[$name]
            $provided = Get-CommandArgumentValue $toolArgs ([string]$name)
            if (-not $provided.found -or $null -eq $provided.value) { continue }
            $typeName = [string]$spec.type
            if ($typeName -match '(^|\|)\s*array(\b|\[)' -or $typeName -match '\[\]') {
                $isSequence = ($provided.value -is [System.Collections.IEnumerable] -and $provided.value -isnot [string] -and $provided.value -isnot [System.Collections.IDictionary])
                # resolveMany intentionally accepts either ref[] or one ref /
                # selector table; do not reject that supported shorthand here.
                $isReferenceList = ($typeName -match '(?i)^\s*ref\[\]')
                $isSingleRef = ($isReferenceList -and ($provided.value -is [string] -or $provided.value -is [System.Collections.IDictionary] -or ($provided.value -isnot [ValueType] -and $provided.value -isnot [System.Collections.IEnumerable])))
                $isSinglePoint = $false
                if ($tool -eq 'ground_height' -and ([string]$name -eq 'points' -or [string]$name -eq 'positions')) {
                    $hasX = Test-CommandArgumentPresent $provided.value 'x'
                    $hasY = Test-CommandArgumentPresent $provided.value 'y'
                    $hasZ = Test-CommandArgumentPresent $provided.value 'z'
                    $isSinglePoint = ($hasX -and $hasY -and $hasZ)
                }
                if (-not $isSequence -and -not $isSingleRef -and -not $isSinglePoint) {
                    return @{ ok=$false; code='BAD_ARGS'; error=("Argument '$name' must be an array or a single ref/selector value."); tool=$tool; argument=[string]$name; expected=$typeName; hint='Arguments were rejected before queueing; no Studio command was sent.' }
                }
            }
        }
        return @{ ok=$true }
    }

    function Invoke-PluginTool($sessionId, $tool, $toolArgs, [int]$timeoutSeconds, [string]$activityId = '') {
        $argumentCheck = Test-CommandArguments ([string]$tool) $toolArgs
        if (-not $argumentCheck.ok) { return (To-Json $argumentCheck 12) }
        # Version 7.0.5: the caller keeps its session/token; the DELIVERY follows the
        # reconnect chain, so commands are not stranded in a session the plugin no
        # longer polls. Results are routed back by commandId (origin stays the caller).
        $callerSession = [string]$sessionId
        $deliverySession = Get-DeliverySession $callerSession
        $sessionId = $deliverySession
        $queue = Ensure-Queue $sessionId
        # Version 7.0.6: VOR dem Einreihen messen, ob der Executor ueberhaupt
        # antwortet. 7.0.5 liess jeden Befehl 55 Sekunden in den Timeout laufen,
        # wenn das Plugin stumm war - genau das war "Befehle haengen". Jetzt
        # gibt es sofort eine ehrliche, umsetzbare Antwort.
        $deliveryHealth = Get-StudioDeliveryHealth $sessionId
        if ($deliveryHealth.state -eq 'wedged') {
            try { $Shared.Telemetry.FastFailWedged = [long]$Shared.Telemetry.FastFailWedged + 1 } catch {}
            Add-CommandHistory $callerSession $null $tool 'not_queued' ('STUDIO_UNREACHABLE: no sign of life for ' + [string]$deliveryHealth.secondsSinceLastSign + ' s; command was not queued')
            $unreachableHint = 'Roblox Studio does not answer the bridge: no poll and no sign of life for ' + [string]$deliveryHealth.secondsSinceLastSign + ' seconds while ' + [string]$deliveryHealth.waitingCommands + ' command(s) are waiting. This is NOT an Arena bug and nothing is running in Studio any more. Tell the user, in German, to close Roblox Studio COMPLETELY (Alt+F4, all Studio windows) and then open the place again - a blocked Lua VM inside the Studio plugin can only be freed by a Studio restart. The place itself is not damaged.'
            return (To-Json @{
                ok = $false
                code = 'STUDIO_UNREACHABLE'
                studioUnreachable = $true
                error = ('Roblox Studio did not answer for ' + [string]$deliveryHealth.secondsSinceLastSign + ' seconds. The command was NOT queued - it could never be executed and would only block the queue.')
                measurement = $deliveryHealth
                userHint = $unreachableHint
                howToFix = 'Ask the user to restart Roblox Studio once (close Studio completely, open the place again). Afterwards the plugin reconnects with the SAME session and the SAME token and commands work again. Do not retry this call in a loop and do not call force_fail repeatedly - the bridge already knows the executor is gone.'
                commandSent = $false
                workIsLost = $false
            } 12)
        }
        if ($deliveryHealth.busy -and $queue.Count -gt 0) {
            try { $Shared.Telemetry.FastFailBusy = [long]$Shared.Telemetry.FastFailBusy + 1 } catch {}
            Add-CommandHistory $callerSession $null $tool 'not_queued' ('STUDIO_BUSY: ' + [string]$deliveryHealth.runningTool + ' running for ' + [string]$deliveryHealth.runningSeconds + ' s with ' + [string]$queue.Count + ' command(s) queued')
            return (To-Json @{
                ok = $false
                code = 'STUDIO_BUSY'
                studioBusy = $true
                error = ('Studio is still executing ' + [string]$deliveryHealth.runningTool + ' (' + [string]$deliveryHealth.runningSeconds + ' s) and ' + [string]$queue.Count + ' command(s) are already waiting in the queue. The command was NOT queued, so it cannot pile up behind the running work.')
                runningTool = [string]$deliveryHealth.runningTool
                runningSeconds = [int]$deliveryHealth.runningSeconds
                queueDepth = [int]$queue.Count
                measurement = $deliveryHealth
                howToFix = 'Studio executes commands strictly one after another. Either wait for the running command (GET /api/queue shows running + heartbeatAt) and repeat this call, or repeat it with args.asJob = true so it runs in the background without blocking.'
                commandSent = $false
                workIsLost = $false
            } 12)
        }
        if ($queue.Count -ge 64) {
            return (To-Json @{ ok=$false; code='QUEUE_FULL'; error='The Studio command queue is full (64 queued commands). Wait for the current work or reset the queue through /api/queue.'; queueDepth=[int]$queue.Count; commandSent=$false } 8)
        }

        $commandId = [guid]::NewGuid().ToString('N')
        $commandBudget = [Math]::Max(90, [Math]::Min(300, $timeoutSeconds + 30))
        $queuedAt = Get-UnixSeconds
        if (-not [string]::IsNullOrWhiteSpace($activityId)) {
            $Shared.ActivityCommandMap[$commandId] = (To-Json @{ sessionId=$sessionId; activityId=$activityId; tool=$tool; args=$toolArgs } 20)
        }
        $signal = New-Object System.Threading.ManualResetEventSlim($false)
        [void]$Shared.ResultSignals.TryAdd($commandId, $signal)

        $command = @{ id=$commandId; tool=$tool; args=$toolArgs; queuedAt=$queuedAt; budgetSeconds=$commandBudget }
        $commandJson = (To-Json $command 40)
        $Shared.CommandPayloads[$commandId] = $commandJson
        Add-PendingCommand $sessionId $commandId $tool $commandBudget $queuedAt $callerSession
        $enqueue = Enqueue-Command $sessionId $queue $commandJson
        if (-not $enqueue.ok) {
            Remove-PendingCommand $sessionId $commandId | Out-Null
            $discard = $null
            [void]$Shared.CommandPayloads.TryRemove($commandId, [ref]$discard)
            [void]$Shared.CommandOwners.TryRemove($commandId, [ref]$discard)
            [void]$Shared.CommandStates.TryRemove($commandId, [ref]$discard)
            [void]$Shared.ActivityCommandMap.TryRemove($commandId, [ref]$discard)
            [void]$Shared.ResultSignals.TryRemove($commandId, [ref]$discard)
            try { $signal.Dispose() } catch {}
            return (To-Json @{ ok=$false; code='QUEUE_FULL'; error='The Studio command queue is full (64 queued commands). The command was rejected before queueing.'; queueDepth=[int]$enqueue.queueDepth; commandSent=$false } 8)
        }
        $wake = Ensure-Signal $sessionId
        [void]$wake.Set()

        $deadline = [DateTime]::UtcNow.AddSeconds($timeoutSeconds)
        $resultJson = $null
        $got = $false
        while ([DateTime]::UtcNow -lt $deadline) {
            if ($Shared.CommandResults.TryRemove($commandId, [ref]$resultJson)) { $got = $true; break }
            [void]$signal.Wait(100)
            $signal.Reset()
        }

        $removed = $null
        [System.Threading.Monitor]::Enter($Shared.CommandResultLock)
        try {
            [void]$Shared.ResultSignals.TryRemove($commandId, [ref]$removed)
            if (-not $got -and $Shared.CommandResults.TryRemove($commandId, [ref]$resultJson)) { $got = $true }
        } finally {
            [System.Threading.Monitor]::Exit($Shared.CommandResultLock)
        }
        if ($got) { [void]$Shared.ResultChunks.TryRemove($commandId, [ref]$removed) }
        try { $signal.Dispose() } catch {}

        if (-not $got) { return $null }
        Remove-PendingCommand $sessionId $commandId | Out-Null
        return $resultJson
    }

    # ==================================================================
    # TOOL-DOKUMENTATION: vollstaendig pro Tool - Beschreibung, alle
    # Parameter (Typ + Default + Bedeutung), Rueckgabewert, lauffaehiges
    # Beispiel und Fehlerfaelle. Wird automatisch mit dem ersten Call der
    # Sitzung ausgeliefert und laesst sich ueber /api/docs + get_docs
    # pro Tool, pro Kategorie oder komplett abrufen.
    # ==================================================================
    function Get-ToolDocs {
        $t = New-Object System.Collections.Generic.List[object]

        # ---------------- INFO ----------------
        $t.Add(@{ name = 'get_bridge_log'; category = 'info'; summary = 'Letzte Zeilen von runtime.log / performance.txt (Selbstdiagnose).';
            description = 'Liest die Log-Dateien der Bridge selbst - ohne den Nutzer nach Dateien zu fragen. Immer enthalten: Laufzeit-Identitaet (Version + Datei + SHA-256 der LAUFENDEN Datei), Waechter-Status und der Zustell-Zustand dieses Places (ok/busy/wedged). Damit laesst sich jede Fehlersuche mit Belegen fuehren statt mit Vermutungen.';
            params = @{ lines = @{ type = 'number'; required = $false; default = 120; description = 'Zeilenzahl ab dem Ende (10-500).' }; file = @{ type = 'string'; required = $false; default = 'runtime'; description = 'runtime (Standard) oder performance.' } };
            returns = '{ file, path, exists, lines[], deployment { version, file, sha256, startedAt }, sweep { running, secondsSinceSweep, abandonedTotal }, delivery { state, secondsSinceLastSign, runningTool } }';
            example = @{ lines = 120; file = 'runtime' };
            errors = @('Die Datei existiert noch nicht (z. B. performance.txt ohne eingeschaltete Leistungsdiagnose).') })
        $t.Add(@{ name = 'get_place_info'; category = 'info'; summary = 'Place, Play-Zustand, Faehigkeiten.';
            description = 'Was fuer ein Place ist verbunden, welche Id hat er, laeuft gerade eine Simulation (edit/run), welche Faehigkeiten hat das Plugin. Immer der erste sinnvolle Call.';
            params = @{};
            returns = '{ name, placeId, gameId, creatorId, state: { running, mode (edit|run), context, playerCount, editModeActive, modeInfo }, capabilities, pluginVersion }';
            example = @{};
            errors = @('REF_NOT_FOUND: kein Studio-Fenster verbunden (Token ungültig oder Place geschlossen).') })
        $t.Add(@{ name = 'get_tree'; category = 'info'; summary = 'Instanz-Baum mit Ids.';
            description = 'Liest die Hierarchie ab der Wurzel mit allen Ids (#42), Klassennamen und (optional) Eigenschaften/Quellcode. Nutze rootRef, um grosse Baume in Stuecken zu lesen.';
            params = @{ rootRef = @{ type = 'ref'; required = $false; default = "'game'"; description = 'Wurzel: Id (#42) oder Pfad (game.Workspace).' }; maxDepth = @{ type = 'int'; required = $false; default = '6'; description = 'Ebenen tief.' }; maxNodes = @{ type = 'int'; required = $false; default = '3000'; description = 'Obergrenze der Knoten - bei Erreichung truncated=true.' }; includeProperties = @{ type = 'bool'; required = $false; default = 'false'; description = 'Eigenschaften mitliefern (teuer).' }; includeSource = @{ type = 'bool'; required = $false; default = 'false'; description = 'Quelltext von Skripten mitliefern.' } };
            returns = '{ tree: { id, name, className, path, children: [...] }, nodeCount, truncated }';
            example = @{ rootRef = 'game.Workspace'; maxDepth = 2 };
            errors = @('REF_NOT_FOUND: rootRef existiert nicht.') })
        $t.Add(@{ name = 'search'; category = 'info'; summary = 'Instanzen suchen (Name/Klasse/Tag).';
            description = 'Sucht in der Wurzel nach Namen (Teil-/Gleich), Class (IsA) oder CollectionService-Tag. Liefert Ids - nutze IMMER die Ids zurueck, Namen sind nicht eindeutig.';
            params = @{ query = @{ type = 'string'; required = $false; default = "''"; description = 'Namenssuche (lowercase, Teilstring).' }; className = @{ type = 'string'; required = $false; default = 'null'; description = 'z.B. BasePart, Script, Model (IsA).' }; tag = @{ type = 'string'; required = $false; default = 'null'; description = 'CollectionService-Tag.' }; rootRef = @{ type = 'ref'; required = $false; default = "'game'"; description = 'Suchbereich.' }; limit = @{ type = 'int'; required = $false; default = '200'; description = 'Maximale Treffer.' }; exact = @{ type = 'bool'; required = $false; default = 'false'; description = 'Nur exakte Namenstreffer.' } };
            returns = '{ matches: [ { id, name, className, path, position?, size?, sourceLines? } ], totalMatches, returned }';
            example = @{ query = 'wall'; className = 'BasePart'; rootRef = 'game.Workspace' };
            errors = @() })
        $t.Add(@{ name = 'get_instance'; category = 'info'; summary = 'Ein Objekt im Detail.';
            description = 'Eigenschaften, Attribute, Tags und Kinder eines Objekts. Bei Skripten nur Groesse (nutze get_script fuer den Text).';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = 'Id (#42) oder Pfad.' }; includeSource = @{ type = 'bool'; required = $false; default = 'false'; description = 'Skriptquelle mitliefern.' }; includeAllProperties = @{ type = 'bool'; required = $false; default = 'false'; description = 'Hinweis auf exotische Eigenschaften.' } };
            returns = '{ id, name, className, path, parent, properties, attributes (in properties.Attributes), children, childCount }';
            example = @{ ref = '#42'; includeSource = $true };
            errors = @('REF_NOT_FOUND: Id unbekannt (gelöscht oder Plugin neu geladen) - neu suchen mit search/get_tree.') })
        $t.Add(@{ name = 'get_children'; category = 'info'; summary = 'Kinder paginieren.';
            params = @{ ref = @{ type = 'ref'; required = $false; default = "'game'"; description = 'Vater-Objekt.' }; offset = @{ type = 'int'; required = $false; default = '0'; description = 'Erstes Kind.' }; limit = @{ type = 'int'; required = $false; default = '500'; description = 'Seite-Groesse.' } };
            returns = '{ children: [ { id, name, className, path, childCount } ], total, offset, returned }';
            example = @{ ref = '#50'; offset = 0; limit = 100 };
            errors = @() })
        $t.Add(@{ name = 'get_properties'; category = 'info'; summary = 'Dieselben Eigenschaften von vielen.';
            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = 'Liste von Ids/Selektoren.' }; properties = @{ type = 'string[]'; required = $false; default = 'all common'; description = 'z.B. ["Position","Size"].' }; includeSource = @{ type = 'bool'; required = $false; default = 'false'; description = '' } };
            returns = '{ items: [ { id, name, className, path, properties: {...} } ], errors }';
            example = @{ refs = @('#42','#43'); properties = @('Position','Size') };
            errors = @('REF_NOT_FOUND: einzelne Ids fehlen (siehe errors).') })
        $t.Add(@{ name = 'resolve_ref'; category = 'info'; summary = 'Pfad zu stabiler Id.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = 'Pfad oder Id.' } };
            returns = '{ id, name, className, path }';
            example = @{ ref = 'game.Workspace.Part[3]' };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'get_selection'; category = 'info'; summary = 'Wahl des Benutzers.';
            description = 'Was der BENUTZER gerade in Studio markiert hat - oft sein direkter Hinweis, worum es geht.';
            params = @{};
            returns = '{ selection: [ { id, name, className, path } ], count }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'select_instance'; category = 'info'; summary = 'Objekte im Studio markieren.';
            description = 'Markiert Objekte im Studio-Fenster, damit der Benutzer sieht, worauf du dich beziehst.';
            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = '' }; add = @{ type = 'bool'; required = $false; default = 'false'; description = 'Zur aktuellen Markierung hinzufuegen.' } };
            returns = '{ selected: [...], errors }';
            example = @{ refs = @('#42','#43') };
            errors = @() })
        $t.Add(@{ name = 'describe_scene'; category = 'info'; summary = 'TEXT-Beschreibung der Szene (statt Screenshot).';
            description = 'Kamera + Objekte mit Position/Groesse/Material/Transparenz als Text. DEUTLICH zuverlaessiger fuer dich als ein Bild. Das Standard-Werkzeug zum "Sehen".';
            params = @{ rootRef = @{ type = 'ref'; required = $false; default = "'game.Workspace'"; description = '' }; maxItems = @{ type = 'int'; required = $false; default = '120'; description = '' }; maxDepth = @{ type = 'int'; required = $false; default = '2'; description = '' } };
            returns = '{ text (menschenlesbar), items, classSummary, truncated, hint }';
            example = @{ rootRef = 'game.Workspace'; maxItems = 60 };
            errors = @() })
        $t.Add(@{ name = 'viewport_info'; category = 'info'; summary = 'Kamera + Blickziel.';
            params = @{};
            returns = '{ camera (CFrame), fieldOfView, viewportSize, lookingAt: { instance, position, distance } }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'get_bounds'; category = 'info'; summary = 'Zentrum/Groesse/Ecken.';
            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = '' } };
            returns = 'pro Objekt: { id, name, center, size, min, max, top, bottom, cframe }';
            example = @{ refs = @('#42') };
            errors = @() })
        $t.Add(@{ name = 'scene_stats'; category = 'info'; summary = 'Performance-ueberblick des Places.';
            description = 'Zaehlt Teile, Unions, MeshParts, Skripte, schätzt Dreiecke und gibt konkrete Tipps fuer grosse Places (z.B. 17.000+ Teile): CanCollide bei Deko aus, in Models gruppieren, Unions klein halten.';
            params = @{};
            returns = '{ partCount, unionCount, meshPartCount, scriptCount, topLevel: [...], triangleEstimate, tips: [...] }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'list_tools'; category = 'info'; summary = 'Alle Tools mit Kategorie + Kurzbeschreibung.';
            params = @{};
            returns = '{ tools: [ { name, category, summary } ], count, pluginVersion, docsVersion, docs }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'bridge_status'; category = 'info'; summary = 'Zustand der Bridge.';
            description = 'Version, Place, Warteschlange, was grade in Studio laeuft (ueberlebte Timeouts), Asset-Cache-Groesse.';
            params = @{};
            returns = '{ bridgeVersion, docsVersion, place, studio, queuedCommands, runningInStudio, executor: { alive, lastTick, runningCommandId, queueDepth }, connectedPlaces, assetCacheEntries }';
            example = @{};
            errors = @() })

        # ---------------- SPATIAL ----------------
        $t.Add(@{ name = 'raycast'; category = 'spatial'; summary = 'Einen Strahl schieessen.';
            description = 'Raycast ab origin in direction. Fuer HÖHEN IMMER raycast/ground_height benutzen - niemals Y aus Indizes berechnen.';
            params = @{ origin = @{ type = '{x,y,z}'; required = $true; default = '-'; description = 'Startpunkt.' }; direction = @{ type = '{x,y,z}'; required = $true; default = '-'; description = 'Richtung (Länge = max. Reichweite).' }; ignore = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Objekte ignorieren.' } };
            returns = '{ hit: bool, instance?, position?, normal?, distance?, material? } - bei kein Treffer NUR { hit: false }';
            example = @{ origin = @{ x = 0; y = 50; z = 0 }; direction = @{ x = 0; y = -100; z = 0 } };
            errors = @('REF_NOT_FOUND: ignore-Id unbekannt.') })
        $t.Add(@{ name = 'raycast_many'; category = 'spatial'; summary = 'Batch: viele Strahlen in einem Call.';
            description = 'Bis zu 500 Rays gleichzeitig; length ist optional und standardmaessig 1000 Studs. Bei langen Batches wird regelmaessig an Studio abgegeben. rays ist der dokumentierte Name; casts bleibt als Kompatibilitaetsalias erhalten.';
            params = @{ rays = @{ type = 'array of { origin, direction, length? }'; required = $false; default = 'null'; description = 'Bis zu 500 Rays; alternativ casts.' }; casts = @{ type = 'array of { origin, direction, length? }'; required = $false; default = 'null'; description = 'Alias fuer rays.' }; ignore = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Objekte ignorieren.' }; exclude = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Alias fuer ignore.' }; asJob = @{ type = 'bool'; required = $false; default = 'false'; description = 'Optional als Hintergrundjob ausfuehren.' } };
            returns = '{ results: [ { index, hit, instance?, position?, distance?, normal? } ], count, hitCount }';
            example = @{ rays = @(@{ origin = @{ x = 0; y = 20; z = 0 }; direction = @{ x = 0; y = -1; z = 0 }; length = 40 }, @{ origin = @{ x = 5; y = 20; z = 0 }; direction = @{ x = 0; y = -1; z = 0 }; length = 40 }) };
            errors = @('REGION_LIMIT: max. 500 Rays pro Call - in Runden aufteilen.', 'BAD_ARGS: rays/casts fehlt.') })
        $t.Add(@{ name = 'ground_height'; category = 'spatial'; summary = 'Höhen per Raycast (Batch).';
            description = 'Misst Bodenhoehen per Raycast. Nutze points/positions ODER min+max+step fuer ein Raster. Hoechstens 4000 Messpunkte pro Call; grosse Raster werden VOR den Raycasts abgewiesen, und die Schleife gibt Studio regelmaessig Zeit zum Atmen. Fuer lange Messungen asJob=true setzen und job_status/job_result verwenden.';
            params = @{ points = @{ type = 'array of {x,y,z}'; required = $false; default = 'null'; description = 'Liste von Ausgangspunkten (jeweils ueber dem Boden); alternativ positions.' }; positions = @{ type = 'array of {x,y,z}'; required = $false; default = 'null'; description = 'Alias fuer points.' }; min = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Untere Ecke fuer ein Raster (zusammen mit max).' }; max = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Obere Ecke fuer ein Raster.' }; step = @{ type = 'number'; required = $false; default = '4'; description = 'Rasterabstand, mindestens 0.5; das Raster darf hoechstens 4000 Punkte haben.' }; ignore = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Zu ignorierende Objekte.' }; exclude = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Alias fuer ignore.' }; asJob = @{ type = 'bool'; required = $false; default = 'false'; description = 'Bei groesseren Messungen true setzen; Jobfortschritt mit job_status abfragen.' } };
            returns = '{ heights/results: [ { position, groundY?, ground?, material?, waterLike? } ], count, hint }';
            example = @{ points = @(@{ x = 0; y = 30; z = 0 }, @{ x = 4; y = 30; z = 4 }) };
            errors = @('REGION_LIMIT: max. 4000 Messpunkte - step erhoehen oder Gebiet teilen.', 'BAD_ARGS: points oder min/max fehlen.') })
        $t.Add(@{ name = 'measure'; category = 'spatial'; summary = 'Distanz zwischen zwei Objekten.';
            params = @{ refA = @{ type = 'ref'; required = $false; default = 'null'; description = 'Erster Ref; alternativ ref.' }; refB = @{ type = 'ref'; required = $false; default = 'null'; description = 'Zweiter Ref; alternativ targetRef.' }; ref = @{ type = 'ref'; required = $false; default = 'null'; description = 'Alias fuer refA.' }; targetRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Alias fuer refB.' } };
            returns = '{ distance, delta: {x,y,z}, from, to }';
            example = @{ refA = '#42'; refB = '#43' };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'measure_height'; category = 'spatial'; summary = 'Distanz zu Boden/Himmel.';
            description = 'Raycast ab einem Punkt/Objekt nach unten (Boden) oder oben (Himmel) - die freie Hoehe.';
            params = @{ ref = @{ type = 'ref'; required = $false; default = 'null'; description = 'Optionales Objekt; die Messung startet an dessen Unter-/Oberkante.' }; point = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Oder ein expliziter Messpunkt.' }; direction = @{ type = "'down'|'up'"; required = $false; default = "'down'"; description = 'Boden oder freie Hoehe nach oben.' }; ignore = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Zu ignorierende Objekte.' }; exclude = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Alias fuer ignore.' } };
            returns = '{ instance?, direction, origin, hit, y?, groundY?, skyY?, distance?, hitInstance? }';
            example = @{ point = @{ x = 0; y = 10; z = 0 }; direction = 'down' };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'parts_in_box'; category = 'spatial'; summary = 'Alle Teile in einer Box.';
            description = 'Räumliche Abfrage: alle BaseParts, deren Bounds die Box beruehren. Box als min/max, center/size oder zwei Eck-Objekte. BaseParts (Parts, MeshParts, Unions) - andere Klassen mit search.';
            params = @{ min = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Untere Ecke. (alternativ center+size oder refA+refB)' }; max = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Obere Ecke.' }; center = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Mitte (mit size).' }; size = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Ausdehnung (mit center).' }; refA = @{ type = 'ref'; required = $false; default = 'null'; description = 'Ecke 1 (mit refB).' }; refB = @{ type = 'ref'; required = $false; default = 'null'; description = 'Ecke 2.' }; tolerance = @{ type = 'number'; required = $false; default = '0'; description = 'Box um so viel Studs aufwaechsen lassen.' }; className = @{ type = 'string'; required = $false; default = 'null'; description = 'z.B. Part, MeshPart.' }; tag = @{ type = 'string'; required = $false; default = 'null'; description = 'Nur Objekte mit Tag.' }; excludeRefs = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Ausschliessen.' }; limit = @{ type = 'int'; required = $false; default = '200'; description = '' } };
            returns = '{ items: [ { id, name, className, position, size, distanceFromCenter } ], count, empty, hint (wenn empty) }';
            example = @{ min = @{ x = -10; y = 0; z = -10 }; max = @{ x = 10; y = 20; z = 10 }; tolerance = 1 };
            errors = @('REF_NOT_FOUND: Box-Ecken nicht auflasbar.', 'BAD_ARGS: min/max, center/size oder refA/refB angeben.') })
        $t.Add(@{ name = 'parts_in_sphere'; category = 'spatial'; summary = 'Alle Teile in einem Kugelumfeld.';
            params = @{ center = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Oder ref.' }; ref = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder center.' }; radius = @{ type = 'number'; required = $true; default = '-'; description = 'Studs.' }; tolerance = @{ type = 'number'; required = $false; default = '0'; description = 'Radius aufwaechsen.' }; className = @{ type = 'string'; required = $false; default = 'null'; description = '' }; tag = @{ type = 'string'; required = $false; default = 'null'; description = '' }; excludeRefs = @{ type = 'ref[]'; required = $false; default = 'null'; description = '' }; limit = @{ type = 'int'; required = $false; default = '200'; description = '' } };
            returns = '{ items: [ { id, name, className, position, size, distance } ], count, empty }';
            example = @{ center = @{ x = 0; y = 5; z = 0 }; radius = 10 };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: center oder ref erforderlich.') })
        $t.Add(@{ name = 'nearest_parts'; category = 'spatial'; summary = 'Nächste Objekte (sortiert nach Distanz).';
            description = '"Was ist in 10 Studs?" - Kugel-Abfrage, aufsteigend nach Distanz sortiert.';
            params = @{ origin = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Oder position/ref.' }; position = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Alias fuer origin.' }; ref = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder origin.' }; radius = @{ type = 'number'; required = $true; default = '-'; description = '' }; limit = @{ type = 'int'; required = $false; default = '20'; description = '' }; className = @{ type = 'string'; required = $false; default = 'null'; description = '' }; tag = @{ type = 'string'; required = $false; default = 'null'; description = '' }; exclude = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Ausgeschlossene Objekte.' } };
            returns = '{ items: [ { id, name, className, position, distance, size } ], count, empty, nearest: (erstes Item oder null) }';
            example = @{ ref = '#42'; radius = 10; limit = 5 };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'what_is_in_the_way'; category = 'spatial'; summary = 'Was steht zwischen A und B?';
            description = 'Baut eine Box entlang der Strecke zwischen zwei Punkten/Objekten und listet alles, was drin liegt (A und B selbst werden ausgeschlossen). Akzeptiert from/to und die dokumentierten origin/target-Aliase.';
            params = @{ fromRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder origin/from.' }; toRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder target/to.' }; origin = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Startpunkt; Alias fuer from.' }; target = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Endpunkt; Alias fuer to.' }; from = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Startpunkt.' }; to = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Endpunkt.' }; width = @{ type = 'number'; required = $false; default = '2'; description = 'Box-Breite/Hoehe um die Linie.' }; className = @{ type = 'string'; required = $false; default = 'null'; description = 'Nur diese Klasse.' }; tag = @{ type = 'string'; required = $false; default = 'null'; description = 'Nur Objekte mit Tag.' }; exclude = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Ausgeschlossene Objekte.' }; limit = @{ type = 'int'; required = $false; default = '50'; description = 'Maximal 500 Treffer.' } };
            returns = '{ items: [ { id, name, className, position, distanceFromLine } ], count, clear (true = nichts im Weg) }';
            example = @{ fromRef = '#42'; toRef = '#43'; width = 2 };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: von+nach angeben.') })
        $t.Add(@{ name = 'overlap_check'; category = 'spatial'; summary = 'Stosst ein Objekt mit etwas zusammen?';
            description = 'Prueft Bounds mit optionaler Toleranz, Klassenfilter und Ausschlussliste. Akzeptiert ref oder refs; bei grossen Gruppen asJob=true.';
            params = @{ ref = @{ type = 'ref'; required = $false; default = 'null'; description = 'Ein Objekt; alternativ refs.' }; refs = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Liste von Objekten.' }; tolerance = @{ type = 'number'; required = $false; default = '0'; description = 'Box aufwaechsen (Studs).' }; excludeRefs = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Ausgeschlossene Objekte.' }; ignore = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Alias fuer excludeRefs.' }; className = @{ type = 'string'; required = $false; default = 'null'; description = 'Nur diese Klasse.' }; limit = @{ type = 'int'; required = $false; default = '50'; description = 'Maximal 500 Treffer pro Objekt.' }; asJob = @{ type = 'bool'; required = $false; default = 'false'; description = 'Optional als Hintergrundjob ausfuehren.' } };
            returns = '{ overlapping: [ { id, name, className, position } ], count, clear }';
            example = @{ ref = '#42'; tolerance = 0.5 };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'snap_to_ground'; category = 'spatial'; summary = 'Auf das legen, was darunter ist.';
            description = 'Raycast nach unten pro Objekt und setzt es auf die gemessene Flaeche. Ein Fall ueber maxDrop/maxFall wird zum Schutz vor unerwuenschten Verschiebungen abgelehnt; die Geometrie kann optional danach per Raycast verifiziert werden.';
            params = @{ refs = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Liste; alternativ ein einzelnes ref.' }; ref = @{ type = 'ref'; required = $false; default = 'null'; description = 'Einzelobjekt-Alias.' }; offset = @{ type = 'number'; required = $false; default = '0'; description = 'Zusaetzlicher Abstand ueber dem Boden.' }; maxFall = @{ type = 'number'; required = $false; default = '2000'; description = 'Alias fuer maxDrop: hoechstens so tief fallen; darueber = nicht bewegen + Hinweis.' }; maxDrop = @{ type = 'number'; required = $false; default = '2000'; description = 'Maximal erlaubte Fallhoehe.' }; ignore = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Zu ignorierende Objekte.' }; exclude = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Alias fuer ignore.' }; waitForMeasurable = @{ type = 'bool'; required = $false; default = 'true'; description = 'Nach dem Setzen per Raycast verifizieren.' }; waitSeconds = @{ type = 'number'; required = $false; default = '2'; description = 'Maximal 10 Sekunden auf Messbarkeit warten.' }; asJob = @{ type = 'bool'; required = $false; default = 'false'; description = 'Bei vielen Objekten im Hintergrund ausfuehren.' } };
            returns = '{ results: [ { instance, y?, ground?, note? } ], count, measurable? }';
            example = @{ refs = @('#42','#43'); offset = 0.1 };
            errors = @('REF_NOT_FOUND', 'GEOMETRY_NOT_READY (Warning): Welt nach dem Setzen nicht sofort messbar.') })
        $t.Add(@{ name = 'verify_measurable'; category = 'spatial'; summary = 'Warten, bis Geometrie raycastbar ist.';
            description = 'Nach create/fill ist neue Geometrie manchmal erst ab dem naechsten Frame messbar. Dieses Tool prueft bis zu 10 refs per Raycast; maxSeconds ist auf hoechstens 30 begrenzt.';
            params = @{ refs = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Liste von refs; alternativ ein einzelnes ref.' }; ref = @{ type = 'ref'; required = $false; default = 'null'; description = 'Alias fuer genau ein Objekt.' }; maxSeconds = @{ type = 'number'; required = $false; default = '5'; description = 'Maximale Wartezeit, hoechstens 30 Sekunden.' }; seconds = @{ type = 'number'; required = $false; default = 'null'; description = 'Kompatibilitaetsalias fuer maxSeconds.' } };
            returns = '{ checked, geometry: { ready, frames, waitedMs, note? }, maxSeconds }';
            example = @{ refs = @('#60','#61') };
            errors = @('REF_NOT_FOUND') })

        # ---------------- ORIENTATION / ROTATION ----------------
        $t.Add(@{ name = 'coordinate_guide'; category = 'orientation'; summary = 'Koordinatensystem + formbewusste Achsen (gemessen).';
            description = 'Die WICHTIGSTE Referenz fuer Rotation: welche Achse was heisst, wie Yaw/Pitch/Roll wirken (mit Formeln), UND wie Block/Ball/Cylinder/Wedge standardmaessig ausgerichtet sind - das wird live im Place gemessen (mit temporaren Probedeilen), NICHT geraten. Vor dem ersten Drehen eines Zylinders/Wedges IMMER hier nachschauen.';
            params = @{ reprobe = @{ type = 'bool'; required = $false; default = 'false'; description = 'Geometrie neu messen.' } };
            returns = '{ axes: {x,y,z}, yawRule, shapeDefaults: { block, ball, cylinder, wedge: { description, measured } }, howToRotate }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'describe_orientation'; category = 'orientation'; summary = 'Wohin zeigen die Seiten dieses Parts?';
            description = 'Gibt in Klartext und als Vektoren, wohin top/bottom/front/back/left/right des Objekts in Welt-Koordinaten zeigen. Damit "welche Seite zeigt nach vorne?" nie mehr geraten werden muss.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = '' } };
            returns = '{ top, bottom, front, back, left, right (je {x,y,z}), yawDegrees, pitchDegrees, rollDegrees, human: [ "front face points to the left (-X)", ... ] }';
            example = @{ ref = '#42' };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: Objekt hat keine Position.') })
        $t.Add(@{ name = 'point_at'; category = 'orientation'; summary = 'Part formbewusst auf Ziel ausrichten.';
            description = 'Dreht den Part SO, dass die gewählte lokale Achse exakt auf das Ziel zeigt - mit der moeglichst kleinen Rotation. Fuer Zylinder: axis="top" (die Lange-Achse). Fuer Wedges: coordinate_guide zuerst lesen. Ersetzt alle manuellen CFrame-Rechnungen.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = '' }; targetRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Ziel-Objekt. (alternativ targetPosition)' }; targetPosition = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Ziel-Punkt.' }; axis = @{ type = "'front'|'back'|'top'|'bottom'|'left'|'right'"; required = $false; default = "'front'"; description = 'Welche lokale Achse aufs Ziel zeigen soll (front = -Z).' }; keepUpright = @{ type = 'bool'; required = $false; default = 'true'; description = 'Objekt senkrecht lassen (kein Kippen).' } };
            returns = '{ instance, cframe (neu), target, axis, yawDegrees }';
            example = @{ ref = '#42'; targetRef = '#43'; axis = 'front' };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: targetRef oder targetPosition fehlt.') })
        $t.Add(@{ name = 'look_at'; category = 'orientation'; summary = 'Auf Ziel drehen (klassisch, -Z nach vorn).';
            description = 'Wie point_at mit axis="front" (die "Vorderseite" -Z zeigt aufs Ziel).';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = '' }; targetRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder position.' }; position = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Oder targetRef.' }; keepUpright = @{ type = 'bool'; required = $false; default = 'true'; description = '' }; axis = @{ type = 'string'; required = $false; default = "'front'"; description = 'Andere Achse -> gleich wie point_at.' } };
            returns = '{ instance, cframe }';
            example = @{ ref = '#42'; targetRef = '#43' };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'rotate_around'; category = 'orientation'; summary = 'Um einen Punkt drehen.';
            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = '' }; axis = @{ type = "'x'|'y'|'z'"; required = $false; default = "'y'"; description = '' }; degrees = @{ type = 'number'; required = $false; default = '0'; description = 'Drehwinkel (grad, + = gegen Uhrzeiger um die Achse).' }; pivot = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = 'Drehzentrum. (alternativ pivotRef)' }; pivotRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder pivot. Default: Position des ersten Objekts.' } };
            returns = '{ rotated: [...], count, degrees, axis }';
            example = @{ refs = @('#42'); pivotRef = '#43'; axis = 'y'; degrees = 90 };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'move_relative'; category = 'orientation'; summary = 'Lokal oder weltbezogen verschieben.';
            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = '' }; right = @{ type = 'number'; required = $false; default = '0'; description = '' }; up = @{ type = 'number'; required = $false; default = '0'; description = '' }; forward = @{ type = 'number'; required = $false; default = '0'; description = 'Positive forward = in die Blickrichtung des Objekts (lokal -Z).' }; space = @{ type = "'world'|'local'"; required = $false; default = "'world'"; description = '' } };
            returns = '{ moved: [ { instance, position } ], count }';
            example = @{ refs = @('#42'); right = 4; forward = 2; space = 'local' };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'resize_part'; category = 'orientation'; summary = 'Groesse aendern, Kante halten.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = 'BasePart.' }; size = @{ type = '{x,y,z}'; required = $true; default = '-'; description = 'Neue Groesse.' }; anchor = @{ type = "'center'|'bottom'|'top'"; required = $false; default = "'center'"; description = 'Welche Kante stehen bleibt.' } };
            returns = '{ instance, size, position }';
            example = @{ ref = '#42'; size = @{ x = 4; y = 8; z = 4 }; anchor = 'bottom' };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: kein BasePart.') })
        $t.Add(@{ name = 'fit_between'; category = 'orientation'; summary = 'Zwei Punkte verbinden (Tragwerk/Kabel/Schiene).';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = 'BasePart, das gestreckt wird.' }; fromRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder from {x,y,z}.' }; toRef = @{ type = 'ref'; required = $false; default = 'null'; description = 'Oder to.' }; from = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = '' }; to = @{ type = '{x,y,z}'; required = $false; default = 'null'; description = '' }; thickness = @{ type = 'number'; required = $false; default = '1'; description = 'Dicke quer zur Verbindung.' } };
            returns = '{ instance, length }';
            example = @{ ref = '#42'; fromRef = '#43'; toRef = '#44'; thickness = 0.5 };
