            params = @{ refs = @{ type = 'ref[] | Selektoren'; required = $true; default = '-'; description = '' }; properties = @{ type = 'table'; required = $true; default = '-'; description = '{ Material="Neon", Color={255,80,0}, Transparency=0.3 }' } };
