            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = '' }; tag = @{ type = 'string'; required = $true; default = '-'; description = '' } };
            returns = '{ count, tag }';
            example = @{ refs = @('#42'); tag = 'Door' };
            errors = @() })

        # ---------------- SCRIPTS ----------------
        $t.Add(@{ name = 'get_script'; category = 'scripts'; summary = 'Quelltext mit Zeilen + Hash.';
            description = 'Liest ein Skript mit Zeilennummern, Gesamthaenge und Hash. Den Hash als expectHash an patch/set_script_source rueckgeben, damit niemand dazwischen aendert.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = 'Script/LocalScript/ModuleScript.' }; startLine = @{ type = 'int'; required = $false; default = '1'; description = '' }; endLine = @{ type = 'int'; required = $false; default = 'Ende'; description = '' }; withLineNumbers = @{ type = 'bool'; required = $false; default = 'true'; description = '' } };
            returns = '{ id, path, className, totalLines, totalBytes, startLine, endLine, hash, source }';
            example = @{ ref = '#77'; startLine = 1; endLine = 200 };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: kein Skript.') })
        $t.Add(@{ name = 'find_in_script'; category = 'scripts'; summary = 'Ausschnitt im Skript finden.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = '' }; query = @{ type = 'string'; required = $true; default = '-'; description = 'Text oder (regex=true) Lua-Pattern.' }; regex = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; contextLines = @{ type = 'int'; required = $false; default = '2'; description = 'Zeilen drumherum.' }; limit = @{ type = 'int'; required = $false; default = '40'; description = '' } };
            returns = '{ matches: [ { line, offset, preview } ], count, totalLines, hash }';
            example = @{ ref = '#77'; query = 'WalkSpeed' };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'patch_script'; category = 'scripts'; summary = 'Punktgenaue Aenderungen (DAS Standardwerkzeug).';
            description = 'NUR die betroffene Stelle wird ersetzt - nie die ganze Datei. Mehrere Edits pro Call, in Reihenfolge angewendet. Zweideutige Snippets werden abgelehnt (mit allen Trefferzeilen). dryRun=true zeigt vorher, was passiert.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = '' }; edits = @{ type = 'array'; required = $true; default = '-'; description = 'Liste von Edit-Objekten (siehe ops).' }; expectHash = @{ type = 'string'; required = $false; default = 'null'; description = 'Hash aus get_script - Schutz vor Ueberschreiben.' }; dryRun = @{ type = 'bool'; required = $false; default = 'false'; description = 'Nur zeigen, nicht aendern.' } };
            returns = '{ id, path, operations: [ { op, line, ... } ], oldLines, newLines, bytes, hash, preview } - bei dryRun: { dryRun, wouldChange, operations, preview }';
            example = @{ ref = '#77'; edits = @(@{ op = 'replace'; find = 'WalkSpeed = 16'; replace = 'WalkSpeed = 24' }, @{ op = 'insertAfter'; find = 'local function onJoin()'; text = 'print("join")' }) };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: Text nicht gefunden / zweideutig (alle Trefferzeilen stehen im Fehler) / unbekannte op.') })
        $t.Add(@{ name = 'set_script_source'; category = 'scripts'; summary = 'GANZEN Quelltext ersetzen (fuer neue/kleine Dateien).';
            description = 'Existiert noch, aber fuer grosse Dateien ist patch_script ueberlegener. Fuer > 50 KB vorher upload_text + sourceRef.';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = '' }; source = @{ type = 'string'; required = $false; default = "''"; description = 'Volle neue Quelle (unverändert übernommen - kein String-Schneidwerk, keine %-Kollisionen).' }; sourceRef = @{ type = 'string'; required = $false; default = 'null'; description = 'uploadId aus upload_text.' }; expectHash = @{ type = 'string'; required = $false; default = 'null'; description = '' } };
            returns = '{ id, path, bytes, lines, previousBytes, hash }';
            example = @{ ref = '#77'; source = 'print("hi")' };
            errors = @('REF_NOT_FOUND', 'RUNTIME_ERROR: Hash-Mismatch (Skript wurde zwischendurch geaendert).') })
        $t.Add(@{ name = 'insert_script'; category = 'scripts'; summary = 'Neues Script/LocalScript/ModuleScript.';
            description = 'Erzeugt ein Skript mit Quelle. ModuleScripte einfach mit "return M" am Ende beenden - die Bridge greift in den Text NICHT ein.';
            params = @{ parentRef = @{ type = 'ref'; required = $false; default = "'game.ServerScriptService'"; description = '' }; className = @{ type = "'Script'|'LocalScript'|'ModuleScript'"; required = $false; default = "'Script'"; description = '' }; name = @{ type = 'string'; required = $false; default = 'className'; description = '' }; source = @{ type = 'string'; required = $false; default = "''"; description = 'Oder sourceRef.' }; sourceRef = @{ type = 'string'; required = $false; default = 'null'; description = 'uploadId.' }; properties = @{ type = 'table'; required = $false; default = '{}'; description = 'z.B. { Disabled=false }.' } };
            returns = '{ id, path, className, lines, hash }';
            example = @{ parentRef = 'game.ServerScriptService'; className = 'Script'; name = 'Main'; source = 'print("hi")' };
            errors = @('REF_NOT_FOUND', 'BAD_ARGS: className ohne Source-Eigenschaft.') })
        $t.Add(@{ name = 'bulk_insert_scripts'; category = 'scripts'; summary = 'Mehrere Skripte in einem Call.';
            params = @{ items = @{ type = 'array'; required = $true; default = '-'; description = 'Wie insert_script: [ { parentRef, className, name, source }, ... ].' } };
            returns = '{ created: [...], count, errors }';
            example = @{ items = @(@{ parentRef = 'game.ServerScriptService'; name = 'A'; source = '-- a' }, @{ parentRef = 'game.ServerScriptService'; name = 'B'; source = '-- b' }) };
            errors = @() })
        $t.Add(@{ name = 'compile_check'; category = 'scripts'; summary = 'Syntax pruefen, OHNE auszufuehren.';
            description = 'Lädt den Code nur zum Kompilieren. Damit ist COMPILE_ERROR bekannt, BEVOR das Skript laeuft - und es ist kein "Raten und Abwarten" mehr.';
            params = @{ source = @{ type = 'string'; required = $true; default = '-'; description = 'Oder sourceRef.' }; name = @{ type = 'string'; required = $false; default = "'@arena_check'"; description = 'Name im Fehler.' } };
            returns = '{ ok=true, compilable=true } oder { ok=false, code="COMPILE_ERROR", error, line }';
            example = @{ source = 'local x = 1 + ' };
            errors = @('COMPILE_ERROR: mit Zeilennummer.') })
        $t.Add(@{ name = 'run_lua'; category = 'scripts'; summary = 'Lua im Server-/Edit-Kontext ausfuehren (persistent!).';
            description = 'Fuehrt Lua aus und gibt Rueckgabe + alles, was gedruckt wurde, zurueck. WICHTIG: Die Umgebung ist PERSISTENT - ein Helfer aus einem frueheren Call (z.B. "M = {...}" ohne local) ist im naechsten Call weiter da (lua_state zeigt alle persiste Variablen). Fuer Laeufe ueber 60s: asJob=true oder start_job. Fuer jedes nichttriviale sichtbare 3D-Modell modelBuildRules.polygonWorkflow befolgen: build_polygon_model ist der erste Modellbau-Aufruf und baut die vollstaendige Hauptsilhouette; polygons=submodels fuer einzelne Flaechen/Bauteile, volumes fuer veraenderliche Querschnitte. build_assembly fuer Wiederholungen und native Parts fuer Standardstuetzen/Details kombinieren. Nach dem Build result.incomplete/facesSkipped/skipped pruefen und model_audit ausfuehren. run_lua ist kein Ersatz fuer die dedizierten Modellbauer; nutze es fuer Logik, Animation oder echte Sonderfaelle. Wenn eigenes Dreieck/WedgePart-Lua noetig ist, gilt polygonEngineRules (get_docs/Sessionstart): lokal X=Dicke/Normale, Y=Hoehe, Z=Basiskante. Fuer organische Modelle organic=true am Polygonbau setzen; danach model_audit auf jedes zurueckgegebene Modell nach dem letzten Schreibaufruf und alle organicQuality.issues beheben. report_done verlangt pro registriertem organischem Modell echte ArenaPolygonTriangle-Geometrie, eine bestandene Palette, ein aktiviertes Bewegungs-Script und einen frischen Audit. Externe Generator-Dateien oder ungemessene Qualitaetsbehauptungen sind kein Place-Build.';
            params = @{ source = @{ type = 'string'; required = $true; default = '-'; description = 'Oder sourceRef.' }; context = @{ type = "'server'|'auto'"; required = $false; default = "'auto'"; description = 'Client existiert seit 7.0.0 nicht mehr (kein Playtest, kein Client-Agent) - "client" antwortet CONTEXT_UNAVAILABLE.' }; asJob = @{ type = 'bool'; required = $false; default = 'false'; description = 'Im Hintergrund als Job laufen lassen (rueckgibt jobId).' } };
            returns = '{ returned, output: [ { seq, message, type } ], context, environment="persistent", persistentKeys } oder (asJob) { ok, jobId, status="running" }';
            example = @{ source = 'local p = workspace:FindFirstChild("Part"); return p and p.Position' };
            errors = @('COMPILE_ERROR: Syntax (Zeile im Fehler).', 'RUNTIME_ERROR: Laufzeit (Mitteilung + Output).', 'CONTEXT_UNAVAILABLE: "client" gibt es nicht mehr.') })
        $t.Add(@{ name = 'lua_state'; category = 'scripts'; summary = 'Was lebt in der persistenten Lua-Umgebung?';
            params = @{};
            returns = '{ keys: [ "M", "helpers", ... ], count, jobs: [ { id, name, status } ] }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'clear_lua_state'; category = 'scripts'; summary = 'Persistente Variablen + Jobs zuruecksetzen.';
            params = @{ confirm = @{ type = 'bool'; required = $true; default = '-'; description = 'Muss true sein.' } };
            returns = '{ cleared = true }';
            example = @{ confirm = $true };
            errors = @() })

        # ---------------- FILL (Voxel/Geometrie aufmassen + fuellen) ----------------
        $t.Add(@{ name = 'probe_world'; category = 'fill'; summary = 'WELT MESSEN: Raster-Schritt, Wasserhoehe, Füllhöhen-Regel.';
            description = 'Raycast-Raster ueber den Boden (nie Index-Rechnung!), bestimmt den Raster-Schritt (z.B. 4 Studs) und Wasserhoehe. Das Profil wird gespeichert und von fill_region verwandt. Maximal 4000 Rasterpunkte: groessere Raster werden sofort abgewiesen; radius verkleinern oder step erhoehen. Fuer lange Messungen asJob=true setzen und job_status/job_result verwenden.';
            params = @{ center = @{ type = '{x,y,z}'; required = $false; default = '{0,0,0}'; description = 'Mittelpunkt der Messung.' }; radius = @{ type = 'number'; required = $false; default = '40'; description = 'Messradius (Studs), mindestens 0.' }; step = @{ type = 'number'; required = $false; default = '10'; description = 'Rasterabstand (mindestens 1 Stud); maximal 4000 Rasterpunkte.' }; asJob = @{ type = 'bool'; required = $false; default = 'false'; description = 'Im Hintergrund ausfuehren und Jobfortschritt bereitstellen.' } };
            returns = '{ measuredAt, center, radius, sampleCount, gridStep, waterY, heights: [...], fillRule: { formula, matched, samples }, stored = true }';
            example = @{ center = @{ x = 0; y = 0; z = 0 }; radius = 40 };
            errors = @('BAD_ARGS: zu wenige Messpunkte gefunden (leerer Place?).') })
        $t.Add(@{ name = 'fill_region'; category = 'fill'; summary = 'Bereich fuellen - nach GEMESSENER Regel, in Chunks, resume-fähig.';
            description = 'Fuellt eine Box aus Gitterzellen (gridStep) mit Air oder einem Teil-Template. Zielhoehe: explizite Zahl, "rule" (Fuehlhoehe-Regel aus probe_world: frisch y1 wenn durch gridStep teilbar, sonst ceil(y1/gridStep)*gridStep+2; Wasser y1-2) oder "top" (bis max.Y). TIEFER ueberschreiben geht NICHT stillschweigend: wird erst mit Air geleert (clearBelowFirst, nur mit confirmClear=true, sonst Spalten = skippedNeedClear). Laeuft in kleinen Chunks mit Fortschritt; bei Abbruch: gleiches resumeToken zurueckgeben = WITTERMACHEN, nicht von vorn. Jeder Zellfehler betrifft nur diese Zelle (failedCells).';
            params = @{ min = @{ type = '{x,y,z}'; required = $true; default = '-'; description = 'Untere Ecke der Box.' }; max = @{ type = '{x,y,z}'; required = $true; default = '-'; description = 'Obere Ecke.' }; with = @{ type = "'Air' | { className, properties, name }"; required = $false; default = "'Air'"; description = "'Air' loescht Zellen (Raum freimachen). Template legt Teile." }; gridStep = @{ type = 'number'; required = $false; default = 'worldProfile.gridStep'; description = 'Zellgroesse. Ohne probe_world wird NICHT geraten (Fehler WORLD_NOT_PROBED).' }; fillTo = @{ type = 'number | "rule" | "top"'; required = $false; default = "'rule'"; description = 'Zielhoehe der Saeule.' }; fillFrom = @{ type = 'number'; required = $false; default = 'min.Y'; description = 'Untergrenze des Fuellens.' }; clearBelowFirst = @{ type = 'bool'; required = $false; default = 'true'; description = 'Saeulen, die tiefer fuellen muessen, erst mit Air leeren.' }; confirmClear = @{ type = 'bool'; required = $false; default = 'false'; description = 'OHNE true werden Saeulen mit existing parts nur als skippedNeedClear gemeldet, nichts wird gelöscht.' }; chunkBudget = @{ type = 'int'; required = $false; default = '200'; description = 'Zellen pro Chunk (konservativ; Job meldet partsPerSecond).' }; resumeToken = @{ type = 'table'; required = $false; default = 'null'; description = 'Aus dem letzten (abgebrochenen) Ergebnis - naemlicher Aufruf damit = weitermachen.' }; stopOnError = @{ type = 'bool'; required = $false; default = 'false'; description = 'Bei Zellfehler anhalten.' }; asJob = @{ type = 'bool'; required = $false; default = 'false'; description = 'EMPFOEHLEN bei > 150 Zellen: true.' } };
            returns = '{ created, cleared, skippedExisting, skippedNeedClear, failedCells: [ { x, y, z, error } ], totalColumns, chunks, partsPerSecond, geometry: { ready, frames }, resumeToken (null = fertig), usedProfile: { gridStep, fillRule } }';
            example = @{ min = @{ x = -20; y = -10; z = -20 }; max = @{ x = 20; y = 10; z = 20 }; with = @{ className = 'Part'; properties = @{ Anchored = $true }; name = 'Fill' }; fillTo = 'rule'; asJob = $true };
            errors = @('WORLD_NOT_PROBED: probe_world zuerst.', 'REGION_LIMIT: Box zu gross - kleiner aufteilen (empirische Obergrenze im Fehler).', 'BAD_ARGS: min/max fehlt.') })

        # ---------------- MASTER BUILD ----------------
        $t.Add(@{ name = 'build_assembly'; category = 'create'; summary = 'Modulare/wiederholte Baugruppe in EINEM Call; mit Polygon-Silhouetten kombinieren.';
            description = 'Erstellt bis zu 2000 Parts/Instanzen, wendet Properties an, erzeugt lineare oder radiale Wiederholungen und gruppiert alles direkt in ein Model. Ideal fuer Gebaeude-Rahmen, Treppen, Zaeune, Saeulenringe, Fassaden und wiederholte Module. Kombiniere die Baugruppe mit build_polygon_model fuer die praegende Hauptsilhouette oder individuelle Formen; build_assembly ersetzt bei einem nichttrivialen Hero-Modell nicht die polygonale Hauptform. Die Bridge berechnet Wiederholungen/Positionen; Arena muss weder Lua-Schleifen noch hunderte Einzelcalls schreiben.';
            params = @{ grade = @{ type='string'; required=$false; default='null'; description='Version 7.2.0: ''simple'' | ''lowpoly'' | ''blockout'' - Erklaert die Einfachheit AUSDRUECKLICH (Attribut ArenaDeclaredGrade). model_audit benotet das Ergebnis dann nicht mehr als Entwurf und report_done antwortet nicht mit DRAFT_GRADE_RISK.' }; modelName = @{ type='string'; required=$false; default="'ArenaAssembly'"; description='Name des fertigen Models.' }; parentRef=@{type='ref';required=$false;default="'game.Workspace'";description='Ziel.'}; items=@{type='array';required=$true;default='-';description='[{className,name,properties,attributes,repeat:{count,offset}|{count,radius,startAngle,angleStep,heightStep}}]. attributes wird per SetAttribute gesetzt (z.B. {ArenaOrganicRole="eye_left"}); {n} im Namen wird ersetzt.'}; pivot=@{type='Vector3|CFrame';required=$false;default='null';description='Optional das ganze Model am Ende versetzen.'} };
            returns = '{ model, created, count, errors, geometry }';
            example = @{ modelName='Saeulenring'; items=@(@{className='Part';name='Saeule{n}';properties=@{Size=@{x=2;y=12;z=2};Anchored=$true};repeat=@{count=12;radius=20}}) };
            errors = @('BUDGET_EXCEEDED: mehr als 2000 Teile.', 'BAD_ARGS: nichts erstellt.') })
        $t.Add(@{ name = 'build_polygon_model'; category = 'create'; summary = 'BEVORZUGT fuer nichttriviale Custom-3D-Modelle: Hauptsilhouette als Polygon direkt im Place bauen.';
            description = 'GLOBALER 3D-BAUSTANDARD fuer alle nichttrivialen sichtbaren 3D-Kategorien, nicht nur Kreaturen. modelBuildRules und das Beispiel LowPolyHouse sind die Arbeitsanleitung. Ablauf: erst Bounds/Koordinaten/Stil festlegen, dann eine vollstaendige Hauptsilhouette als benannte Submodels mit Polygonflaechen bauen, danach Wiederholungen mit build_assembly und Akzente/Details ergaenzen, Ergebnis pruefen und model_audit ausfuehren. Ein polygon={name,points=[{x,y,z},...]} ist genau eine planare Flaeche, KEIN ganzer Koerper: fuer ein geschlossenes Objekt alle Seiten/Enden als Flaechen verbinden oder closeOpenings=true fuer offene Rand-Loops setzen. Punkte muessen geordnet, planar, verschieden und nicht selbstschneidend sein. Benutze volumes fuer veraenderliche Querschnitte wie Rumpf, Griff, Saeule, Schaft oder Ast. Ein einzelner Frontumriss mit thickness bleibt eine duenne Platte. Punkte sind die Geometrie; origin/rotation-in-Grad/scale transformieren das ganze Modell, properties.Position/Size/CFrame/Orientation werden ignoriert. Der Builder trianguliert und erzeugt zwei WedgeParts pro Dreieck; AutoWeld ist je Submodel an. Nie nur ok ansehen: result.incomplete=false, facesSkipped=0 und skipped=[] verlangen; fallbackFaces/Warnungen lesen und Fehlerstellen neu bauen. Fuer organic=true bleibt organicKind Pflicht und der Spezialvertrag gilt zusaetzlich. Simple Standardteile und explizite Primitive-/Blockoutwuensche bleiben einfache Ausnahmen.';
            params = @{ grade=@{type='string';required=$false;default='null';description='Version 7.2.0: ''simple'' | ''lowpoly'' | ''blockout'' - Erklaert die Einfachheit AUSDRUECKLICH (Attribut ArenaDeclaredGrade). Ohne das gilt ein Bau mit wenigen Teilen ohne Polygon-/Mesh-/Union-/Detail-Geometrie als Entwurf (DRAFT_GRADE_RISK).'}; modelName=@{type='string';required=$false;default="'ArenaPolygonModel'";description='Oberstes fertiges Model.'}; organic=@{type='bool';required=$false;default='false';description='Fuer jedes bewusst organische Modell true setzen; zusammen mit organicKind erforderlich. Registriert das Modell fuer frischen per-model Audit und report_done-Gate.'}; organicKind=@{type='string';required=$false;default='null';description='Pflicht bei organic=true: creature|plant|tree|prop|custom. creature aktiviert Volumen-, Gesichts- und optionale Fluegelmessung.'}; organicTraits=@{type='array';required=$false;default='[]';description='Optionale Kreaturenmerkmale, derzeit ["wings"]: verlangt wing_left (+Z) und wing_right (-Z) mit gemessener Anbindung an den Torso.'}; volumes=@{type='array';required=$false;default='[]';description='Allgemeine geschlossene Loft-Volumen [{name,role,sides=6..16,sections:[{center={x,y,z},heightRadius,depthRadius},...],style}]. Fuer veraenderliche Querschnitte in Rumpf/Huelle, Griff, Saeule, Schaft oder Ast; mindestens 3 Stationen, Radien >=0.025 vor globalem scale und benachbarte Zentren >=0.01 Studs. Creature zusaetzlich: body >=4, head >=3 Stationen und beide >=8 Seiten.'}; submodels=@{type='array';required=$false;default='[]';description='EMPFOHLEN fuer jedes zusammengesetzte Modell: [{name,role,containerClass="Folder|Model",polygons:[{name,points:[{x,y,z},...],style?}],style,autoWeld,closeOpenings,capStyle}]. Jede Polygonliste enthaelt einzelne planare Flaechen; groupiere nach Bauteil/Farbe/Material. Alle Submodels liegen unter dem zurueckgegebenen Hauptmodel. role ist ein optionaler semantischer Marker; Spezialrollen nur verwenden, wenn ein Audit sie verlangt.'}; polygons=@{type='array';required=$false;default='[]';description='Planare Flaechen [{name,points:[{x,y,z},...],color,material,thickness,style}]. Jede Flaeche braucht >=3 geordnete, planare, eindeutige Punkte und wird fuer ein Solid mit Rueckseite/Seiten/Enden ergaenzt. Punkte ohne Selbstschnitt und ohne redundante kollineare Ecken; fuer grosse Modelle nach Submodel/Material gruppieren.'}; points=@{type='Vector3[]';required=$false;default='null';description='Kurzform fuer genau EINE planare Flaeche; Punkte sind echte Modellkoordinaten, nicht eine Bild-/Frontskizze.'}; script=@{type='string';required=$false;default='null';description='Textuelle Kurzform fuer mehrere POLYGON-Abschnitte. Fuer nachvollziehbare, mehrteilige Modelle bevorzugt die strukturierte submodels/polygons-Form und das LowPolyHouse-Beispiel verwenden.'}; style=@{type='table';required=$false;default='{}';description='Globale Part-Defaults: color, material, materialVariant, collisionGroup, thickness, thicknessPlacement (inside Standard|center|positive|negative), anchored, canCollide, canQuery, canTouch, castShadow, transparency, reflectance, properties. Geometrie bleibt Builder-eigen: Position/Orientation/Rotation/CFrame/Size/PivotOffset in properties werden ignoriert, damit keine Flaeche verdreht wird.'}; autoWeld=@{type='bool';required=$false;default='true';description='Standard AN: WeldConstraint-Kette innerhalb jedes Untermodells, damit Polygon-Wedges auch bei anchored=false als ein Objekt verbunden bleiben. Nur autoWeld=false erzeugt bewusst getrennte Teile.'}; mainWeld=@{type='bool';required=$false;default='false';description='Verbindet alle Untermodelle automatisch mit dem ersten.'}; mainWelds=@{type='array';required=$false;default='[]';description='Animierbare Verbindungen [{name,from,to}] zwischen benannten Untermodellen. Erzeugt klassische Welds mit C0/C1 fuer Script-Animation.'}; closeOpenings=@{type='bool';required=$false;default='false';description='Erkennt unmatched boundary loops pro Submodel und versucht sie mit triangulierten AutoCaps zu schliessen. Best effort: fuer kritische/geschlossene Objekte alle Flaechen selbst modellieren und facesSkipped/skipped pruefen.'}; capStyle=@{type='table';required=$false;default='{}';description='Eigener Style fuer automatisch geschlossene Oeffnungen.'}; origin=@{type='Vector3';required=$false;default='{0,0,0}';description='Gesamt-Offset.'}; rotation=@{type='Vector3 degrees';required=$false;default='{0,0,0}';description='Gesamtrotation.'}; scale=@{type='number';required=$false;default='1';description='Gesamtskalierung.'}; maxWedges=@{type='int';required=$false;default='4000';description='Budget, maximal 10000.'}; parentRef=@{type='ref';required=$false;default="'game.Workspace'";description='Ziel.'} };
            returns = '{ model, organicKind, submodels, polygons, volumesBuilt, volumeSummary, triangles, wedges, autoCaps, welds, weldedSubmodels, autoWeldDefault, mainWelds, facesTotal, facesBuilt, facesSkipped, incomplete, skipped, fallbackFaces, ignoredGeometryProperties, geometryInvariant, geometry, method, editable }, warnings';
            example = @{ modelName='LowPolyHouse'; grade='lowpoly'; origin=@{x=0;y=0;z=0}; rotation=@{x=0;y=0;z=0}; scale=1; style=@{thickness=0.04;anchored=$true;canCollide=$true}; submodels=@(
                @{name='Walls';style=@{color='#D7B77E';material='SmoothPlastic'};polygons=@(
                    @{name='FrontGable';points=@(@{x=-2;y=0;z=-1},@{x=2;y=0;z=-1},@{x=2;y=3;z=-1},@{x=0;y=5;z=-1},@{x=-2;y=3;z=-1})},
                    @{name='BackGable';points=@(@{x=2;y=0;z=1},@{x=-2;y=0;z=1},@{x=-2;y=3;z=1},@{x=0;y=5;z=1},@{x=2;y=3;z=1})},
                    @{name='LeftWall';points=@(@{x=-2;y=0;z=-1},@{x=-2;y=0;z=1},@{x=-2;y=3;z=1},@{x=-2;y=3;z=-1})},
                    @{name='RightWall';points=@(@{x=2;y=0;z=-1},@{x=2;y=3;z=-1},@{x=2;y=3;z=1},@{x=2;y=0;z=1})},
                    @{name='Floor';points=@(@{x=-2;y=0;z=-1},@{x=2;y=0;z=-1},@{x=2;y=0;z=1},@{x=-2;y=0;z=1})})},
                @{name='Roof';style=@{color='#A65F35';material='SmoothPlastic'};polygons=@(
                    @{name='LeftSlope';points=@(@{x=-2;y=3;z=-1},@{x=0;y=5;z=-1},@{x=0;y=5;z=1},@{x=-2;y=3;z=1})},
                    @{name='RightSlope';points=@(@{x=0;y=5;z=-1},@{x=2;y=3;z=-1},@{x=2;y=3;z=1},@{x=0;y=5;z=1})})},
                @{name='FrontDetails';style=@{thickness=0.025;thicknessPlacement='center';canCollide=$false};polygons=@(
                    @{name='Door';style=@{color='#59402F'};points=@(@{x=-0.45;y=0;z=-1.04},@{x=0.45;y=0;z=-1.04},@{x=0.45;y=1.8;z=-1.04},@{x=-0.45;y=1.8;z=-1.04})},
                    @{name='Window';style=@{color='#79C9D0'};points=@(@{x=0.75;y=2.0;z=-1.04},@{x=1.35;y=2.0;z=-1.04},@{x=1.35;y=2.6;z=-1.04},@{x=0.75;y=2.6;z=-1.04})})})};
            errors = @('ORGANIC_KIND_REQUIRED: organic=true needs organicKind.', 'ORGANIC_KIND_INVALID', 'ORGANIC_COLORS_REQUIRED: organic=true needs at least three explicit colour assignments.', 'CREATURE_VOLUME_REQUIRED: body/head need closed lofts.', 'CREATURE_WINGS_REQUIRED: declared wings need left/right geometry.', 'ORGANIC_POLYGON_REQUIRED: an explicitly organic build must use this polygon builder with organic=true.', 'POLYGON_INVALID: kein gueltiges Polygon.', 'BUDGET_EXCEEDED', 'BAD_ARGS', 'REF_NOT_FOUND') })

        # ---------------- UI ENGINE 1.0 (6.2) ----------------

$t.Add(@{ name = 'ui_capabilities'; category = 'ui'; summary = 'ZUERST AUFRUFEN: misst, welche modernen UI-Instanzen dieses Studio wirklich kann.';
            description = 'Probt mit Instance.new/pcall in GENAU dieser Studio-Version, ob UIShadow, einzelne UICorner-Radien, UIStroke.StrokeSizingMode.ScaledSize, UIStroke.BorderOffset, mehrere UIStrokes pro Objekt, UIFlexItem, UIDragDetector, Path2D, StyleSheet, CanvasGroup und FontFace vorhanden sind. Damit schreibt Arena nie wieder Code aus veraltetem Trainingswissen und nie wieder Code fuer Instanzen, die es nicht gibt. Fehlt etwas, nennt notes den Fallback, den die Engine automatisch verwendet (z.B. gestapelte Halo-Frames statt UIShadow). Liefert ausserdem die verfuegbaren Skins, Eckenprofile und Geraete.';
            params = @{ refresh = @{ type = 'bool'; required = $false; default = 'false'; description = 'Zwischenspeicher verwerfen und neu messen.' } };
            returns = '{ engineVersion, capabilities: { uiShadow, individualCorners, strokeScaledSize, strokeBorderOffset, strokeMulti, uiFlexItem, uiDragDetector, path2D, styleSheet, canvasGroup, fontFace }, notes, skins, corners, devices, measured }';
            example = @{ };
            errors = @() })
        $t.Add(@{ name = 'ui_skin'; category = 'ui'; summary = 'Kunstrichtung waehlen ODER den Stil vorhandener GUIs auslesen.';
            description = 'action=list nennt alle zwoelf Skins (glass, arcade, comic, sticker, clay, parchment, metal, paper, crt, holo, cozywood, chalk) - keiner davon ist ein dunkles Dashboard. action=get loest einen Skin plus Markenfarbe zur vollstaendigen Palette auf und meldet den gemessenen Textkontrast. action=extract liest ein BESTEHENDES GUI und meldet dominante Farben, wahrscheinliche Markenfarbe, Eckenradien, Schriften und ob dort ueberhaupt Strokes/Gradients/Schatten/Texturen benutzt werden. Genau damit wird der Wunsch den bisherigen Stil der anderen GUIs bitte messbar statt geraten: extract aufrufen, brand und suggestedMood uebernehmen, dann build_interface damit aufrufen.';
            params = @{ action = @{ type = "'list' | 'get' | 'extract'"; required = $false; default = "'list'"; description = 'Was getan werden soll.' }; skin = @{ type = 'string'; required = $false; default = "'glass'"; description = 'Skinname fuer get.' }; brand = @{ type = 'color'; required = $false; default = 'null'; description = 'EINE gesaettigte Markenfarbe; die ganze Palette wird daraus harmonisch abgeleitet.' }; colors = @{ type = 'table'; required = $false; default = '{}'; description = 'Einzelne Palettenwerte gezielt ueberschreiben.' }; ref = @{ type = 'ref'; required = $false; default = "'game.StarterGui'"; description = 'Wurzel fuer extract.' } };
            returns = 'list: { skins, count } | get: { skin, palette (hex), textContrast, fonts, generic } | extract: { brand, dominantColors, suggestedMood, corners, fonts, found, reuseThisStyle }';
            example = @{ action = 'extract'; ref = 'game.StarterGui' };
            errors = @('BAD_ARGS: action unbekannt.', 'REF_NOT_FOUND') })
        $t.Add(@{ name = 'build_surface'; category = 'ui'; summary = 'EINE komposite Oberflaeche - niemals nur ein Frame.';
            description = 'Das GUI-Gegenstueck zu build_polygon_model. Arena liefert nur Absicht (Rolle, Rechteck im Design-Raum 0..100, Skin); die Bridge kompiliert daraus den vollstaendigen Schichtstapel: Transform-Wrapper mit AnchorPoint aus align und UIScale, Basis (Frame oder CanvasGroup nach Regel), Schattenstapel mit BlurRadius in Scale, Fuellgradient, gekachelte Raster-Textur, Konturstapel mit ScaledSize plus UIGradient IM UIStroke, Glanzkante, Eckenprofil und ein Inhaltsschacht, dessen Innenabstand aus dem Radius folgt. Die Rueckgabe meldet offsetUsed=0 und jede gebaute Schicht. Arena kann die klassischen Fehler gar nicht mehr machen, weil sie die fehleranfaelligen Teile nie selbst anfasst.';
            params = @{ parentRef = @{ type = 'ref'; required = $false; default = "'game.StarterGui'"; description = 'Ziel. Ist es StarterGui, wird automatisch ein ScreenGui mit ZIndexBehavior=Sibling und DeviceSafeInsets erzeugt.' }; skin = @{ type = 'string|table'; required = $false; default = "'glass'"; description = 'Kunstrichtung. Einzelne Rezeptfelder koennen als Tabelle ueberschrieben werden.' }; brand = @{ type = 'color'; required = $false; default = "'#FF4D6D'"; description = 'EINE Markenfarbe -> ganze Palette.' }; role = @{ type = "'card'|'button'|'panel'|'modal'|'header'|'bar'|'chip'"; required = $false; default = "'card'"; description = 'button erzeugt zusaetzlich eine Trefferflaeche und Hover/Press-Attribute.' }; rect = @{ type = '{x,y,w,h}'; required = $false; default = '{50,50,40,20}'; description = 'DESIGN-RAUM 0..100 des Elternteils. x,y ist der Ankerpunkt. Es gibt bewusst kein Offset.' }; align = @{ type = 'string'; required = $false; default = "'center'"; description = 'center/top/bottom/left/right/topleft/... - bestimmt den AnchorPoint. Wird nie geraten.' }; corner = @{ type = "'sharp'|'crisp'|'soft'|'round'|'chunky'|'pill'"; required = $false; default = 'aus dem Skin'; description = 'Eckenprofil statt Pixelzahl.' }; cornerShape = @{ type = '{tl,tr,bl,br}'; required = $false; default = 'null'; description = 'Einzelne Eckenradien fuer Tabs, Kerben, Sprechblasen (nur wenn ui_capabilities.individualCorners true ist).' }; aspect = @{ type = 'number'; required = $false; default = 'null'; description = 'Seitenverhaeltnis festnageln (UIAspectRatioConstraint) - verhindert Verzerrung auf dem Handy.' }; groupFade = @{ type = 'bool'; required = $false; default = 'false'; description = 'NUR wenn der ganze Teilbaum als Einheit faden/toenen soll: erzeugt eine CanvasGroup und begruendet das in der Rueckgabe. Verschachtelung wird verweigert.' }; text = @{ type = 'table'; required = $false; default = 'null'; description = '{ value, display, weight, xAlign, minSize, maxSize, rich, wrap } - TextScaled plus UITextSizeConstraint, Farbe wird auf Kontrast geprueft und notfalls korrigiert.' }; padding = @{ type = 'number'; required = $false; default = 'aus dem Radius'; description = 'Zusaetzlicher Innenabstand als Scale. Die Untergrenze radius*0.3 gilt immer.' }; allowGeneric = @{ type = 'bool'; required = $false; default = 'false'; description = 'Die Sperre gegen entsaettigtes Dunkelblaugrau bewusst aufheben.' } };
            returns = '{ surface, content, screenGui, skin, layers, shadows, shadowKind, strokes, strokeGradients, strokesScaled, gradients, texture, textureParts, cornerRadius, padding, cornerSafe, canvasGroup, canvasGroupReason, offsetUsed, anchorPoint, invariants, capabilities }';
            example = @{ skin = 'holo'; brand = '#38F2C6'; role = 'button'; rect = @(50, 82, 26, 9); text = @{ value = 'JETZT SPIELEN'; display = $true } };
            errors = @('STYLE_TOO_GENERIC: die uebergebene Farbe ist das generische Dashboard-Blaugrau.', 'REF_NOT_FOUND', 'BAD_ARGS') })
        $t.Add(@{ name = 'build_interface'; category = 'ui'; summary = 'STARK EMPFOHLEN: ein KOMPLETTES GUI in EINEM Call, inklusive Bewegung.';
            description = 'FUER GUIS AUSDRUECKLICH STARK EMPFOHLEN - das Gegenstueck zu build_polygon_model fuer 2D. Ein Call erzeugt ScreenGui (ZIndexBehavior=Sibling, DeviceSafeInsets gegen Notch), einen beliebig tief verschachtelten Baum komposite Oberflaechen, Text, Bilder, Listen-/Grid-/Scroll-Layout inklusive Flex sowie einen mitgelieferten LocalScript fuer die Laufzeit-Choreografie. Jedes Rechteck liegt im DESIGN-RAUM 0..100 des jeweiligen Elternteils und wird zu reinem Scale-UDim2 kompiliert - Offset ist strukturell nicht erreichbar. Layout-Kinder bekommen automatisch einen aeusseren Slot, damit das Layout die Position steuert und die Skalierungsanimation trotzdem aus der Mitte waechst. Der Bewegungsscript ist rein attributgetrieben: gestaffelte Feder-Eingaenge, Hover/Press mit Schattenreaktion, und im Leerlauf driftende Stroke-Gradienten, wandernde Texturen und Glanzstreifen. Danach ui_audit aufrufen.';
            params = @{ name = @{ type = 'string'; required = $false; default = "'ArenaInterface'"; description = 'Name des ScreenGui.' }; parentRef = @{ type = 'ref'; required = $false; default = "'game.StarterGui'"; description = 'Ziel.' }; skin = @{ type = 'string|table'; required = $false; default = "'glass'"; description = 'Kunstrichtung fuer den ganzen Baum; einzelne Knoten duerfen abweichen.' }; brand = @{ type = 'color'; required = $false; default = "'#FF4D6D'"; description = 'EINE Markenfarbe -> ganze Palette mit garantiertem Textkontrast.' }; surfaces = @{ type = 'array'; required = $true; default = '-'; description = 'Baum aus Knoten: { id, role, rect:{x,y,w,h}, align, corner, cornerShape, aspect, groupFade, padding, text, image, flex, layout:{ kind:list|grid|none, dir, gap, cols, cellH, scroll, wrap, hFlex, vFlex, xAlign, yAlign }, children:[...], repeat:{ count, template } }. {n} im Text wird durch den Index ersetzt.' }; motion = @{ type = 'table'; required = $false; default = '{}'; description = '{ enabled, energy: soft|snappy|bouncy|heavy, stagger, idle } - steuert den mitgelieferten LocalScript.' }; ignoreGuiInset = @{ type = 'bool'; required = $false; default = 'false'; description = 'Topbar-Bereich mitbenutzen.' }; resetOnSpawn = @{ type = 'bool'; required = $false; default = 'true'; description = '' }; maxSurfaces = @{ type = 'int'; required = $false; default = '160'; description = 'Budget, maximal 400.' }; allowGeneric = @{ type = 'bool'; required = $false; default = 'false'; description = 'Generik-Sperre aufheben.' } };
            returns = '{ screenGui, roots, surfaces, layers, strokes, strokeGradients, shadows, gradients, textureParts, texts, canvasGroups, scrollers, thinSurfaces, motionScript, skin, energy, imageAssets, offsetUsed, invariants, capabilities, nextStep }';
            example = @{ name = 'ShopUI'; skin = 'sticker'; brand = '#FFB020'; surfaces = @(@{ id = 'Panel'; role = 'modal'; rect = @(50, 50, 62, 70); groupFade = $true; children = @(@{ id = 'Title'; role = 'header'; rect = @(50, 9, 86, 13); text = @{ value = 'SHOP'; display = $true } }, @{ id = 'Grid'; role = 'panel'; rect = @(50, 58, 90, 70); layout = @{ kind = 'grid'; cols = 3; gap = 4; cellH = 30; scroll = $true }; repeatSpec = @{ count = 9; template = @{ role = 'button'; rect = @(0, 0, 28, 28); text = @{ value = 'Item {n}' } } } }) }) };
            errors = @('STYLE_TOO_GENERIC', 'BAD_ARGS: surfaces fehlt oder leer.', 'REF_NOT_FOUND') })
        $t.Add(@{ name = 'ui_audit'; category = 'ui'; summary = 'GUI MESSEN statt hoffen: Geraetematrix, Kontrast, Anker, Ecken, Generik-Score.';
            description = 'Der Linter zur UI Engine - die ehrliche Rueckmeldung, die es bisher nur beim Polygon-Builder gab (facesSkipped). Prueft rein rechnerisch, ohne Screenshot und ohne Simulation: offsetRatio (wie viel Layout an Pixeln haengt), Elemente mit UIScale und AnchorPoint 0,0 (wachsen nach unten rechts), Eckenradius gegen Innenabstand (Inhalt laeuft ueber die runde Ecke), Textkontrast gegen den tatsaechlichen Hintergrund, verschachtelte CanvasGroups, nackte gefuellte Frames ohne Gradient/Stroke/Schatten, Stroke-Budget und einen blandnessScore, bei dem 1.0 exakt das generische dunkle Dashboard ist. Zusaetzlich rechnet die Geraetematrix die effektiven Pixelgroessen fuer phone/tablet/desktop/ultrawide aus der Scale-Kette aus und meldet zu kleinen Text (unter 11 px), zu kleine Touch-Ziele (unter 44 px) und Elemente ausserhalb des Sichtfelds. Jeder Befund nennt die Objekt-ID und den GEMESSENEN Wert.';
            params = @{ ref = @{ type = 'ref'; required = $false; default = "'game.StarterGui'"; description = 'Wurzel der Pruefung (ScreenGui oder ein beliebiger Teilbaum).' }; devices = @{ type = 'string[]'; required = $false; default = "@('phone','tablet','desktop')"; description = 'phone 896x414, tablet 1112x834, desktop 1920x1080, ultrawide 2560x1080.' } };
            returns = '{ scope, screenGuis, elements, offsetRatio, blandnessScore, verdict, failureCount, counts, problems: { anchorMismatches, cornerOverflow, contrastFailures, flatSurfaces, genericColors, offsetHeavy, nestedCanvasGroups, textTooSmall, tapTargetsTooSmall, outOfBounds }, deviceMatrix, strokeBudget, capabilities, howToRead }';
            example = @{ ref = 'game.StarterGui.ShopUI'; devices = @('phone', 'desktop') };
            errors = @('REF_NOT_FOUND') })

        # ---------------- UNION / CSG ----------------
        $t.Add(@{ name = 'union'; category = 'union'; summary = 'Teile zu EINEM Teil verschmelzen (mit Vorpruefung und Budget).';
            description = 'Mergt BaseParts zu einem PartOperation. VORPRUEFUNG: alle BaseParts, anchored, gleicher Parent, Größe; Komplexitaets-Budget (Dreiecke geschätzt) mit Warnung und konkretem Vorschlag (z.B. "einen Part statt 40"). Vorher wird automatisch ein Undo-Punkt gesetzt (undoPoint). Roblox-Verweigerung kommt als SOLID_REFUSED mit Roblox-Ursache und Tipps. groups=... verarbeitet mehrere Gruppen in einem Call.';
            params = @{ refs = @{ type = 'ref[]'; required = $false; default = 'null'; description = 'Die zu mergenden Teile (min. 2). (alternativ groups)' }; groups = @{ type = 'array of { refs, name?, keepOriginals?, ... }'; required = $false; default = 'null'; description = 'Batch: mehrere Unions in einem Call.' }; name = @{ type = 'string'; required = $false; default = "'Union'"; description = 'Name des Ergebnisses.' }; parentRef = @{ type = 'ref'; required = $false; default = 'Parent des ersten'; description = '' }; keepOriginals = @{ type = 'bool'; required = $false; default = 'false'; description = 'Originalteile behalten (liegen unsichtbar im Ergebnis).' }; collisionFidelity = @{ type = "'Default'|'Fast'|'Extreme'"; required = $false; default = "'Default'"; description = '' }; renderFidelity = @{ type = "'Automatic'|'Fast'|'Extreme'"; required = $false; default = "'Automatic'"; description = '' }; force = @{ type = 'bool'; required = $false; default = 'false'; description = 'Harte Obergrenzen (24 Teile / Dreiecksbudget) ueberschreiben.' }; fixAnchored = @{ type = 'bool'; required = $false; default = 'false'; description = 'Nicht anker Teile vorher ankeren.' }; undoPoint = @{ type = 'bool'; required = $false; default = 'true'; description = 'Undo-Punkt "vor Union <name>" setzen ( Rueckgaengig-Machen als eigener Schritt: 1x undo).' } };
            returns = '{ result: { id, name, ... }, partsUsed, bounds, triangleEstimate, undoPoint, canBeUndone } oder (groups) { results: [...], count }';
            example = @{ refs = @('#42','#43'); name = 'Wall'; collisionFidelity = 'Default' };
            errors = @('UNION_BUDGET: zu viele Teile/zugleich - kleiner gruppieren oder force=true.', 'UNION_COSTLY (Warning): Komplexitaet hoch - Vorschlag im Feld suggestion (z.B. ein einziger Part).', 'SOLID_REFUSED: Roblox hat abgelehnt (robloxMessage + hints), nichts wurde geaendert.', 'REF_NOT_FOUND', 'UNION_PRECHECK (Warning): nicht anker / verschiedene Parente - Liste im Fehlerfeld.') })
        $t.Add(@{ name = 'subtract'; category = 'union'; summary = 'Form aus einem Teil herausstechen.';
            description = 'baseRef minus negativeRefs. Die Negativteile MUSSSEN sich ueberschneiden, sonst lehnt Roblox ab (SOLID_REFUSED). Vorher mit overlap_check pruefen.';
            params = @{ baseRef = @{ type = 'ref'; required = $true; default = '-'; description = 'Das Teil, das behalten wird.' }; negativeRefs = @{ type = 'ref[]'; required = $true; default = '-'; description = 'Die Form(en), die herauskommen.' }; name = @{ type = 'string'; required = $false; default = "'SubtractResult'"; description = '' }; keepOriginals = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; force = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; undoPoint = @{ type = 'bool'; required = $false; default = 'true'; description = '' } };
            returns = '{ result, partsUsed, bounds, triangleEstimate, undoPoint }';
            example = @{ baseRef = '#42'; negativeRefs = @('#43'); name = 'WallWithDoor' };
            errors = @('SOLID_REFUSED: Negativteil ueberschneidet das Basis-Teil nicht (overlap_check pruefen!).', 'UNION_BUDGET', 'REF_NOT_FOUND') })
        $t.Add(@{ name = 'intersect'; category = 'union'; summary = 'Nur den gemeinsamen Teil behalten.';
            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = 'min. 2, muessen sich ueberschneiden.' }; name = @{ type = 'string'; required = $false; default = "'Intersection'"; description = '' }; keepOriginals = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; force = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; undoPoint = @{ type = 'bool'; required = $false; default = 'true'; description = '' } };
            returns = '{ result, partsUsed, bounds, triangleEstimate, undoPoint }';
            example = @{ refs = @('#42','#43') };
            errors = @('SOLID_REFUSED: keine Ueberschneidung.', 'REF_NOT_FOUND') })
        $t.Add(@{ name = 'separate'; category = 'union'; summary = 'Union wieder in Teile zerlegen.';
            description = 'Das "Rueckgaengig-machen" von union/subtract/intersect: das Ergebnis wird wieder zu normalen, editierbaren Teilen (Farben sind danach nicht mehr garantiet).';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = 'Das PartOperation.' } };
            returns = '{ pieces: [ { id, name, className, path } ], count }';
            example = @{ ref = '#50' };
            errors = @('BAD_ARGS: kein PartOperation.', 'SOLID_REFUSED: SeparateAsync fehlgeschlagen.') })
        $t.Add(@{ name = 'union_info'; category = 'union'; summary = 'Ist das eine Union? Wie komplex?';
            params = @{ ref = @{ type = 'ref'; required = $true; default = '-'; description = '' } };
            returns = '{ instance, isUnion, collisionFidelity, renderFidelity, triangleEstimate, bounds, performance, advice }';
            example = @{ ref = '#50' };
            errors = @('REF_NOT_FOUND') })

        # ---------------- ASSETS ----------------
        $t.Add(@{ name = 'search_assets'; category = 'assets'; summary = 'Katalogsuche (zouverlaessig, mit Cache).';
            description = 'Sucht im Roblox-Katalog. Typen: audio, music, decal, image, texture, mesh/meshpart, model, plugin, font, video und animation. Modelle, 3D-Modelle und Meshes sind direkt durchsuchbar; keine Kategorie braucht einen Freigabe-Schalter. WICHTIG: image/texture werden als DECALs durchgesucht (Katalog-API hat keine "image"-Suche), mesh ueber die aktuelle MESH-Kategorie - die Antwort nennt den verwendeten API-Typ (typeNote). Ergebnisse werden lokal gecacht (cached=true bei Treffer). Wenn der Katalog nicht erreichbar ist: code CATALOG_UNAVAILABLE mit klarem Protokoll ("Katalog nicht verfuegbar -> prozedual bauen") - NICHT schweigen.';
            params = @{ type = @{ type = 'string'; required = $false; default = "'audio'"; description = 'audio, music, decal, image, texture, mesh, meshpart, model, plugin, font, video, animation.' }; query = @{ type = 'string'; required = $true; default = '-'; description = 'Suchbegriff (englisch funktioniert am besten).' }; limit = @{ type = 'int'; required = $false; default = '20'; description = 'max 50.' }; page = @{ type = 'int'; required = $false; default = '0'; description = '' }; sortType = @{ type = 'int'; required = $false; default = '0'; description = '0 Relevanz, 1 Favoriten, 3 Neuere, 4/5 Preis.' }; refresh = @{ type = 'bool'; required = $false; default = 'false'; description = 'Cache umgehen.' } };
            returns = '{ assets: [ { assetId, name, typeId, typeName, useAs="rbxassetid://...", hasScripts, creator, ... } ], count, type, apiType, typeNote, note, cached, totalResults }';
            example = @{ type = 'audio'; query = 'door creak'; limit = 10 };
            errors = @('CATALOG_UNAVAILABLE: Katalog nicht erreichbar - sagen Sie dem Nutzer es klar und bauen Sie prozedual.', 'CATALOG_TYPE_NOT_SUPPORTED: unbekannter Typ.') })
        $t.Add(@{ name = 'asset_details'; category = 'assets'; summary = 'Details zu Asset-Ids (gecacht).';
            params = @{ assetIds = @{ type = 'number[]'; required = $true; default = '-'; description = 'Oder assetId.' } };
            returns = '{ assets: [ { asset: {...}, creator: {...} } ], unknownAssets? (404-Ids klar gemeldet) }';
            example = @{ assetIds = @(1234567) };
            errors = @('CATALOG_UNAVAILABLE', 'ASSET_NOT_FOUND (als unknownAssets mit Hinweis).') })
        $t.Add(@{ name = 'validate_asset'; category = 'assets'; summary = 'Passt die Id wirklich zum Typ? (BEVOR eingebaut.)';
            description = 'Prüft eine Asset-Id gegen den Katalog: existiert sie? Welcher Typ? Passt sie zum erwarteten Typ? Das ist der Schutz gegen rbxassetid://9046578614 als Audio - das waere sonst erst Laufzeitfehler geworden.';
            params = @{ assetId = @{ type = 'number'; required = $true; default = '-'; description = '' }; expectType = @{ type = 'string'; required = $false; default = "''"; description = 'audio, image, texture, decal, mesh, model, animation, video.' } };
            returns = '{ verified, assetId, assetName, typeId, typeName, usableAs, hasScripts, creator, matchesExpect, note }';
            example = @{ assetId = 1838833093; expectType = 'audio' };
            errors = @('ASSET_NOT_FOUND: Id existiert nicht / ist nicht oeffentlich - NICHT verwenden.', 'CATALOG_UNAVAILABLE: konnte nicht verifiziert werden (verified=false) - Anwenden erlaubt, aber mit Risiko.') })

        # ---------------- UI ENGINE 2.0 ----------------
        $t.Add(@{ name = 'ui_glow'; category = 'ui'; summary = 'Glow bauen - IMMER hier, nie selbst basteln.';
            description = 'Baut einen weichen Glow-Stapel (3 Schichten, Scale-only, UICorner) hinter/um das Ziel. Glow gehoert der Engine: handgebaute Transparenz-Ketten sind verboten, weil sie bei jeder Aufloesung anders brechen. color default = Skin-Glow/Akzent, strength 0..1, layers 1..5, spread skaliert die Ausdehnung.';
            params = @{ ref = @{ type = 'string'; required = $true; default = '-'; description = 'Ziel-GuiObject oder ScreenGui.' }; skin = @{ type = 'string'; required = $false; default = "'arcade'"; description = 'Skin fuer Glow-Farbe/Ecken.' }; color = @{ type = 'string'; required = $false; default = 'null'; description = 'Eigene Farbe (#RRGGBB).' }; strength = @{ type = 'number'; required = $false; default = '0.55'; description = '0.05..1.' }; layers = @{ type = 'number'; required = $false; default = '3'; description = '1..5 Schichten.' }; spread = @{ type = 'number'; required = $false; default = '1'; description = 'Ausdehnungs-Faktor.' } };
            returns = '{ ok, engine="2.0", glow { mode="layered-neon", layers, color, strength } }';
            example = @{ ref = '#42'; skin = 'arcade'; strength = 0.7 };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'ui_texture'; category = 'ui'; summary = 'Textur-Rezept: echte Textur-ID zuerst, sonst ehrlicher Gradienten-Fallback.';
            description = 'Echte Texturen schlagen prozedurale Muster. Mit textureId kommt mode="texture" und die Engine nutzt genau diese Id (Tile/Groesse aus tileX/tileY, Tint aus textureTint). Ohne Id kommt mode="gradient" plus Warnung TEXTURE_ASSET_MISSING - kein Fehler, aber ehrlich sichtbar. Reines Rezept (baut nichts), ideal vor build_surface/build_interface.';
            params = @{ skin = @{ type = 'string'; required = $false; default = "'glass'"; description = '' }; textureId = @{ type = 'string'; required = $false; default = 'null'; description = 'echte Roblox-Bild-Id (z.B. rbxassetid://...).' }; tileX = @{ type = 'number'; required = $false; default = '0.18'; description = '' }; tileY = @{ type = 'number'; required = $false; default = '0.18'; description = '' }; textureTint = @{ type = 'string'; required = $false; default = 'null'; description = '' } };
            returns = '{ ok, engine, recipe { mode="texture"|"gradient", textureId, tile, tint }, warnings=[TEXTURE_ASSET_MISSING?] }';
            example = @{ textureId = 'rbxassetid://123456789'; tileX = 0.25 };
            errors = @() })
        $t.Add(@{ name = 'ui_radial'; category = 'ui'; summary = 'Radialmenue aus EINER Bild-Id - beide Farben gehoeren der Engine.';
            description = 'Baut count (3..12) Eintraege auf einem Kreis. Der Ring kommt aus EINER imageId (Skalierung/Transparenz/Tint); fehlt sie, baut die Engine prozedural weiter und meldet RADIAL_ASSET_MISSING als Warnung. Ringfarbe UND Aktivfarbe leitet die Engine aus dem Skin ab - der Aufrufer uebergibt hoechstens eigene Farben, baut aber nie selbst einen Ring aus Teilen. activeIndex hebt genau einen Eintrag hervor. Alle Positionen sind Scale, kein Offset.';
            params = @{ ref = @{ type = 'string'; required = $true; default = '-'; description = 'Eltern-GuiObject.' }; skin = @{ type = 'string'; required = $false; default = "'glass'"; description = '' }; imageId = @{ type = 'string'; required = $false; default = 'null'; description = 'Eine Bild-Id fuer den Ring.' }; items = @{ type = 'number'; required = $false; default = '6'; description = '3..12.' }; radius = @{ type = 'number'; required = $false; default = '0.34'; description = '0.15..0.46 des Elternteils.' }; activeIndex = @{ type = 'number'; required = $false; default = 'null'; description = 'Hervorgehobener Eintrag.' } };
            returns = '{ ok, engine, radial { mode="texture-ring"|"procedural-ring", imageId, items, colors { ring, active } }, warnings }';
            example = @{ ref = 'game.StarterGui.Main'; items = 8; activeIndex = 3 };
            errors = @('REF_NOT_FOUND') })

        # ---------------- WORLD ENGINE 1.0 ----------------
        $t.Add(@{ name = 'world_style'; category = 'world'; summary = 'Welt-Stil festlegen: Palette, Materialien, Dichte, Wetter, Seed.';
            description = 'Setzt den aktiven Welt-Stil (Preset coastal/forest/desert/snow/urban/volcanic oder eigene Palette/Materialien). Der Seed steuert JEDE Variation deterministisch - derselbe Seed baut dieselbe Welt. Ohne Stil baut prop_place weiter, aber model_audit/world_audit koennen keine Stil-Treue messen (der billige Weg ist sichtbar schlechter).';
            params = @{ preset = @{ type = 'string'; required = $false; default = 'null'; description = 'coastal, forest, desert, snow, urban oder volcanic.' }; palette = @{ type = 'table'; required = $false; default = 'null'; description = 'Eigene Farben (#RRGGBB), 3..6 Stueck.' }; materials = @{ type = 'table'; required = $false; default = 'null'; description = 'Erlaubte Materialnamen.' }; density = @{ type = 'number'; required = $false; default = '0.55'; description = '0..1 - wie dicht die Welt gefuellt wird.' }; weathering = @{ type = 'number'; required = $false; default = '0.35'; description = '0..1 - wie gebraucht die Welt aussieht.' }; seed = @{ type = 'number'; required = $false; default = 'null'; description = 'Determinismus.' } };
            returns = '{ ok, style, palette, materials, rules, nextStep }';
            example = @{ preset = 'forest'; seed = 4711 };
            errors = @('BAD_ARGS: unbekanntes Preset (bekannte Liste liegt bei).') })
        $t.Add(@{ name = 'style_lock'; category = 'world'; summary = 'Welt-Stil an den Place binden (Grundlage fuer Stil-Audits).';
            description = 'Schreibt den aktiven Stil als Attribute in workspace.ArenaWelt.Style (Preset, Label, Seed, locked=true) und schaltet die Stil-Pruefung in world_audit/model_audit scharf. Ohne Lock gibt es keine Messung.';
            params = @{ seed = @{ type = 'number'; required = $false; default = 'null'; description = 'Ueberschreibt den Stil-Seed.' } };
            returns = '{ ok, locked, preset, label, seed, folder }';
            example = @{};
            errors = @('NO_WORLD_STYLE: erst world_style aufrufen.') })
        $t.Add(@{ name = 'site_survey'; category = 'world'; summary = 'Gelaende MESSEN: Hoehen, Materialien, Wasser, freier Raum, bestehende Teile.';
            description = 'Raycastet ein Raster (samples x samples) im Bereich, misst min/max/mittlere Hoehe, Span, Steigung, Bodenmaterialien, Wasser-Treffer und den freien Raum ueber dem Boden; dazu die Zahl der bereits vorhandenen Teile im Volumen. Alles gemessen, nichts geschaetzt. Immer VOR dem Bauen aufrufen.';
            params = @{ center = @{ type = '{x,y,z}'; required = $false; default = '{0,0,0}'; description = '' }; size = @{ type = '{x,y,z}'; required = $false; default = '{200,120,200}'; description = '' }; samples = @{ type = 'number'; required = $false; default = '5'; description = '2..9 pro Achse.' } };
            returns = '{ ok, area, samples, ground { minHeight, maxHeight, averageHeight, span, slope, materials, waterSamples }, freeSpace { medianClearanceStuds }, existingParts, suggestedOrigin }';
            example = @{ center = @{ x = 0; z = 0 }; size = @{ x = 120; y = 80; z = 120 }; samples = 6 };
            errors = @() })
        $t.Add(@{ name = 'variation'; category = 'world'; summary = 'Deterministische Variation aus einem Seed (statt math.random).';
            description = 'Liefert count Zahlen zwischen min und max aus einem LCG-Seed. Gleicher Seed + gleicher Index = gleicher Wert, immer. Fuer KI-eigenen Code, der einzelne Werte braucht, ohne die Welt neu zu bauen.';
            params = @{ seed = @{ type = 'number'; required = $false; default = '1'; description = '' }; count = @{ type = 'number'; required = $false; default = '8'; description = '1..512.' }; min = @{ type = 'number'; required = $false; default = '0'; description = '' }; max = @{ type = 'number'; required = $false; default = '1'; description = '' }; decimals = @{ type = 'number'; required = $false; default = '4'; description = '0..6.' } };
            returns = '{ ok, seed, count, values, formula, nextSeed }';
            example = @{ seed = 4711; count = 12; min = 0.85; max = 1.15; decimals = 3 };
            errors = @() })
        $t.Add(@{ name = 'prop_place'; category = 'world'; summary = 'Props deterministisch platzieren (Boden-Snap, Seed, Stil).';
            description = 'Platziert count Props (kind rock/bush/crate oder propName aus prop_save) im Bereich. Position/Rotation/Groesse kommen aus dem Seed, der Boden wird per Raycast gefunden (Wasser wird uebersprungen und gezaehlt), Stil-Palette und -Materialien gelten automatisch. Ergebnis nennt placed/skipped, Seed, Teilezahl und ob ein Stil-Lock aktiv ist.';
            params = @{ kind = @{ type = 'string'; required = $false; default = "'rock'"; description = 'rock, bush oder crate.' }; propName = @{ type = 'string'; required = $false; default = 'null'; description = 'Gespeicherter Prop (hat Vorrang vor kind).' }; count = @{ type = 'number'; required = $false; default = '6'; description = '1..200.' }; seed = @{ type = 'number'; required = $false; default = 'Stil-Seed'; description = '' }; center = @{ type = '{x,y,z}'; required = $false; default = '{0,0,0}'; description = '' }; size = @{ type = '{x,z}'; required = $false; default = '{60,60}'; description = 'Bereich, in dem gestreut wird.' }; group = @{ type = 'string'; required = $false; default = 'null'; description = 'Ordnername unter workspace.ArenaWelt.' } };
            returns = '{ ok, kind, group, requested, placed, skipped, variationSeed, partsCreated, stylePreset, styleLocked }';
            example = @{ kind = 'rock'; count = 14; size = @{ x = 90; z = 90 }; seed = 4711 };
            errors = @('PROP_NOT_FOUND', 'BAD_ARGS: unbekannte Art.') })
        $t.Add(@{ name = 'prop_save'; category = 'world'; summary = 'Auswahl als wiederverwendbaren Prop speichern.';
            description = 'Klont das Ziel (oder die Studio-Auswahl) nach workspace.ArenaProps/<name>, setzt Attribute (Teilezahl, Zeit, Quelle) und macht es fuer prop_place { propName=<name> } nutzbar. Vorhandene Namen werden nur mit overwrite=true ersetzt.';
            params = @{ name = @{ type = 'string'; required = $true; default = '-'; description = '' }; ref = @{ type = 'string'; required = $false; default = 'null'; description = 'Model/Ordner/Teil.' }; useSelection = @{ type = 'bool'; required = $false; default = 'false'; description = 'Studio-Auswahl nehmen.' }; overwrite = @{ type = 'bool'; required = $false; default = 'false'; description = '' } };
            returns = '{ ok, name, parts, folder, source }';
            example = @{ name = 'tree_a'; useSelection = $true };
            errors = @('BAD_ARGS: ref oder useSelection fehlt.', 'PROP_EXISTS') })
        $t.Add(@{ name = 'prop_list'; category = 'world'; summary = 'Gespeicherte Props auflisten.';
            description = 'Listet workspace.ArenaProps mit Name, Klasse, Teilezahl, Art und Speicherzeit.';
            params = @{};
            returns = '{ ok, props: [ { name, className, parts, kind, savedAt } ], count }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'model_audit'; category = 'world'; summary = 'Modell-Audit: Platzhalter, Blockouts, Phase, Urteil.';
            description = 'Auditiert jedes 3D-Build: Platzhalter, Blockouts, Modellphase, Meshes/Unions, Materialien, Polygon-/Primitive-Verhaeltnis, echte ArenaPolygonTriangle-Wedges, Zylinderachsen und ArenaDetail. Liefert konkrete Pfade/Messwerte statt einer unbelegten Qualitaetsbehauptung. Fuer organische Modelle (explizit markiert oder als organisch erkannt) wird organicQuality ZUSAETZLICH pro Modell berechnet, damit kein fremdes Polygon oder Script im Workspace die Metriken erfuellt: polygonTriangles, eindeutige Farben, dominanter Farbanteil, nearWhiteShare und enabled motionScripts mit issues je Modell. organicKind=creature misst ausserdem Koerper-/Kopf-Lofts mit realen Querachsen-Bounds, physische bilaterale Augen und Pupillen, Decal-/PBR-/GUI-Texturen am Kopf sowie deklarierte Fluegelrollen und deren Torso-Ueberlappung. Fuer mit organic=true gebaute Modelle muss der Audit jedes exakt zurueckgegebene Modell NACH dem letzten Schreibaufruf enthalten; report_done gibt bei fehlendem/stalem Beleg ORGANIC_AUDIT_REQUIRED und bei nicht bestandenen Metriken DETAIL_REQUIRED zurueck. Dieser Messpfad waehlt nicht anhand des Modellnamens das bevorzugte Build-Tool. Version 7.2.0: Das Ergebnis traegt zusaetzlich finishScore (0..100) und grade ("draft", "simple", "detailed", "sculpted" oder die beim Bauen erklaerte Note). grade "draft" heisst: mindestens 4 Teile, KEIN Polygon/Mesh/Union/ArenaDetail und ueber 60 % primitive - also ein Entwurf (genau der Fall "Baum = ein Zylinder plus drei Kugeln"). report_done antwortet dann DRAFT_GRADE_RISK. Ausweg: nachbauen ODER die Einfachheit beim Bauen ausdruecklich erklaeren - build_polygon_model/build_assembly { grade = "simple" | "lowpoly" | "blockout" } setzt das Attribut ArenaDeclaredGrade, und der Audit nennt das Ergebnis dann nicht mehr Entwurf. Regeln: modelBuildRules und organicBuildRules.';
            params = @{ ref = @{ type = 'string'; required = $false; default = 'game.Workspace'; description = '' } };
            returns = '{ ok, result: { scope, placeholderCount, phase, verdict, buildQuality: { verdict, organicQuality: { detected, models: [{ id, path, organicKind, creatureMetrics: { bodyLoft, headLoft, eyePairBilateral, pupils3D, faceOverlayCount, wingPairBilateral }, polygonTriangles, uniqueColors, dominantColorShare, nearWhiteShare, motionScripts, issues }] } }, nextStep }, warnings }';
            example = @{ ref = 'game.Workspace.Stadt' };
            errors = @('REF_NOT_FOUND') })
        $t.Add(@{ name = 'world_audit'; category = 'world'; summary = 'Welt-Audit: Stil-Treue, Licht, Atmosphaere, Phase.';
            description = 'Prueft Workspace gegen den gelockten Stil: zaehlt Lichter, Atmosphaere/Sky/Clouds, Detail-Teile, Farbabstand und Material-Abweichungen jedes Teils. styleCompliance sinkt messbar, wenn ohne Stil gebaut wurde - der billige Weg ist nachweisbar schlechter. Liefert offStyleParts mit gemessenem Abstand und issues als klare Arbeitsliste.';
            params = @{};
            returns = '{ ok, parts, lights, lightKinds, atmosphere, sky, clouds, styleLocked, stylePreset, styleCompliance, offStyleParts, detailParts, phase, verdict, issues }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'world_glow'; category = 'world'; summary = 'Licht/Glow fuer ein Teil - immer ueber die Engine.';
            description = 'Setzt EINE Lampe (PointLight/SpotLight/SurfaceLight) auf ein Teil, optional Material Neon, Farbe aus Stil-Palette oder explizit. Glow wird nie als handgebaute Kette aus Ball-Teilen gebaut; Helligkeit/Reichweite sind geklemmt.';
            params = @{ ref = @{ type = 'string'; required = $false; default = 'null'; description = '' }; useSelection = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; lightClass = @{ type = 'string'; required = $false; default = "'PointLight'"; description = '' }; color = @{ type = 'string'; required = $false; default = 'Stil-Palette'; description = '' }; brightness = @{ type = 'number'; required = $false; default = '2'; description = '0..10.' }; range = @{ type = 'number'; required = $false; default = '18'; description = '1..60 (Punkt/Flaeche).' }; neon = @{ type = 'bool'; required = $false; default = 'false'; description = 'Material Neon setzen.' } };
            returns = '{ ok, engine, target, lightClass, color, brightness, material }';
            example = @{ ref = 'game.Workspace.Laterne'; brightness = 3; color = '#FFD68C'; neon = $true };
            errors = @('BAD_ARGS: kein BasePart / falsche lightClass.', 'REF_NOT_FOUND') })
        $t.Add(@{ name = 'refine'; category = 'world'; summary = 'Feinschliff: messbare Details statt "sieht gut aus".';
            description = 'Geht die groessten Teile des Ziels durch und setzt entlang der laengsten Oberkante eine duenne Zierleiste (ArenaDetail, Stil-Material/Farbe), verankert wie das Original und per WeldConstraint verbunden. Bounded durch maxParts; das Ergebnis nennt partsTouched, detailsAdded und ob maxParts der Grund zum Stoppen war. model_audit zaehlt die Details danach als Phase refined.';
            params = @{ ref = @{ type = 'string'; required = $false; default = 'null'; description = '' }; useSelection = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; seed = @{ type = 'number'; required = $false; default = 'Stil-Seed'; description = '' }; maxParts = @{ type = 'number'; required = $false; default = '24'; description = '1..200.' } };
            returns = '{ ok, scope, seed, partsChecked, partsTouched, detailsAdded, maxParts, stoppedBecause }';
            example = @{ ref = 'game.Workspace.Haus'; maxParts = 40 };
            errors = @('BAD_ARGS: ref oder useSelection fehlt.', 'REF_NOT_FOUND') })

        $t.Add(@{ name = 'insert_asset'; category = 'assets'; summary = 'Mesh/Model/MeshPart in den Place einfuegen.';
            description = 'Lädt das Asset in den Place und validiert vorher den Typ. Wenn nur Geometrie gebraucht wird, sanitize=true verwenden: Noch bevor das geladene Asset dem Place untergeordnet wird, entfernt die Bridge automatisch ALLE Scripts/LocalScripts/ModuleScripts sowie RemoteEvents, RemoteFunctions, BindableEvents und BindableFunctions (typischer Virus-/Event-Muell). Damit kann Arena gezielt scriptfreie Toolbox-Modelle suchen und sicher als reine Bauteile einfuegen. unpack=true zerlegt das Model in seine Kinder.';
            params = @{ assetId = @{ type = 'number'; required = $true; default = '-'; description = '' }; parentRef = @{ type = 'ref'; required = $false; default = "'game.Workspace'"; description = '' }; unpack = @{ type = 'bool'; required = $false; default = 'true'; description = 'Model zerlegen.' }; name = @{ type = 'string'; required = $false; default = 'null'; description = 'Name (bei unpack).' }; sanitize = @{ type = 'bool'; required = $false; default = 'false'; description = 'EMPFOHLEN wenn nur das Modell gebraucht wird: vor Einfuegen alle Scripts, Remotes, Bindable-Events/-Functions und damit Virus-Muell entfernen.' }; removeScripts = @{ type = 'bool'; required = $false; default = 'false'; description = 'Nur alle LuaSourceContainer entfernen.' }; removeEvents = @{ type = 'bool'; required = $false; default = 'false'; description = 'Nur Remote-/Bindable-Events und Functions entfernen.' }; acceptScripts = @{ type = 'bool'; required = $false; default = 'false'; description = 'Skripte bewusst behalten (nur wenn wirklich erforderlich; sanitize ist sicherer).' }; skipValidation = @{ type = 'bool'; required = $false; default = 'false'; description = 'Tyvalidierung ueberspringen (nur im Notfall).' } };
            returns = '{ inserted, assetId, count, sanitized, removed, removedCount }';
            example = @{ assetId = 1234567; parentRef = 'game.Workspace' };
            errors = @('ASSET_TYPE_MISMATCH: Id passt nicht zu Model/Mesh (actual.typeName wird gemeldet).', 'ASSET_NOT_FOUND', 'ASSET_HAS_SCRIPTS: enthält Skripte - acceptScripts=true nur mit Vorsicht.', 'CATALOG_UNAVAILABLE.') })
        $t.Add(@{ name = 'apply_asset'; category = 'assets'; summary = 'Asset auf Objekt legen (eigenschaft automatisch).';
            description = 'Setzt Texture/SoundId/Image/MeshId automatisch passend zur Zielklasse - und validiert VORHER, dass die Id wirklich zum Typ passt (ASSET_TYPE_MISMATCH, sonst nie eingebaut).';
            params = @{ refs = @{ type = 'ref[]'; required = $true; default = '-'; description = 'Decal, Texture, Sound, ImageLabel, SpecialMesh, MeshPart, Animation.' }; assetId = @{ type = 'number'; required = $true; default = '-'; description = '' }; property = @{ type = 'string'; required = $false; default = 'auto'; description = 'Nur wenn Auto nicht geht: Texture/SoundId/Image/MeshId/AnimationId.' }; skipValidation = @{ type = 'bool'; required = $false; default = 'false'; description = '' } };
            returns = '{ applied: [ { instance, property, value } ], count, errors }';
            example = @{ refs = @('#42'); assetId = 1234567 };
            errors = @('ASSET_TYPE_MISMATCH: Id ist z.B. ein Decal, aber Sound erwartet - nichts wurde gesetzt.', 'ASSET_NOT_FOUND', 'REF_NOT_FOUND', 'CATALOG_UNAVAILABLE (Warning im Ergebnis: unverifiziert).') })
        $t.Add(@{ name = 'catalog_status'; category = 'assets'; summary = 'Ist der Katalog gerade erreichbar?';
            description = 'Billiger Test (eine bekannte Id abfragen). Vor Asset-Arbeit gut fragen - und wenn catalogAvailable=false: dem Nutzer klar sagen "Katalog nicht verfuegbar" und prozedual bauen.';
            params = @{};
            returns = '{ catalogAvailable, latencyMs }';
            example = @{};
            errors = @() })

        # ---------------- OUTPUT ----------------
        $t.Add(@{ name = 'get_output'; category = 'output'; summary = 'Ausgabefenster lesen (Edit+Server+Client).';
            description = 'Zeilen seit dem letzten Cursor, filterbar (Text/Regex/Typen). "since" = cursor aus dem letzten Call, dann kommen nur NEUE Zeilen.';
            params = @{ limit = @{ type = 'int'; required = $false; default = '200'; description = 'max 2000.' }; since = @{ type = 'int'; required = $false; default = '0'; description = 'Cursor (cursor aus vorigem Call).' }; filter = @{ type = 'string'; required = $false; default = "''"; description = 'Teilstring (lowercase) oder Pattern bei regex=true.' }; regex = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; types = @{ type = 'string[]'; required = $false; default = 'all'; description = 'z.B. ["MessageError","MessageWarning","Output"].' }; onlyErrors = @{ type = 'bool'; required = $false; default = 'false'; description = '' } };
            returns = '{ lines: [ { seq, time, message, type, source } ], returned, matched, cursor, errorCount, warningCount }';
            example = @{ since = 1234; limit = 100; filter = 'error' };
            errors = @() })
        $t.Add(@{ name = 'wait_for_output'; category = 'output'; summary = 'Bis eine Zeile erscheint warten.';
            description = 'Nach run_lua oder einer bestehenden Studio-Aktion: wartet im Studio auf ein Muster (oder bis die Zeit abgelaufen ist). sim_start ist deaktiviert.';
            params = @{ pattern = @{ type = 'string'; required = $true; default = '-'; description = 'Suchtext.' }; timeoutSeconds = @{ type = 'number'; required = $false; default = '15'; description = 'max 110.' }; since = @{ type = 'int'; required = $false; default = 'jetzt'; description = 'Ab welchem Cursor.' }; regex = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; types = @{ type = 'string[]'; required = $false; default = 'all'; description = '' } };
            returns = '{ found, lines?, cursor, waited? }';
            example = @{ pattern = 'loaded'; timeoutSeconds = 20 };
            errors = @() })
        $t.Add(@{ name = 'clear_output'; category = 'output'; summary = 'Ausgabefenster leeren.';
            params = @{};
            returns = '{ cleared, cursor }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'get_errors'; category = 'output'; summary = 'Nur Fehlerzeilen + Zaehler.';
            params = @{ limit = @{ type = 'int'; required = $false; default = '100'; description = '' }; since = @{ type = 'int'; required = $false; default = '0'; description = '' }; filter = @{ type = 'string'; required = $false; default = "''"; description = '' } };
            returns = '{ lines, returned, cursor, errorCount, warningCount, note (wenn leer) }';
            example = @{ limit = 50 };
            errors = @() })

        # ---------------- PLAY / TEST ----------------
                                        $t.Add(@{ name = 'report_done'; category = 'session'; summary = 'Eine kurze, lebendige Windows-11-Mitteilung senden.';
            description = 'Als letzten Call verwenden, wenn die Arbeit fertig ist. Arena schreibt SELBST einen aussagekraeftigen Titel und einen natuerlichen, einladenden Inhalt – keine trockene Liste. Verlaessliches Windows-11-Anzeigebudget: Titel maximal 70 Zeichen, Inhalt maximal 140 Zeichen. Microsoft definiert fuer ToastGeneric keine feste Zeichenobergrenze pro Feld; die sichtbare Menge haengt von Breite, Skalierung und Layout ab. Deshalb erzwingt die Bridge diese konservativen Vollanzeige-Grenzen. Gute Form: Titel="✅ Arena hat den Lauf-Bug behoben!", message="Der Lauf-Bug ist weg – komm ins Spiel und probiere es aus!".';
            params = @{ title = @{ type = 'string'; required = $true; default = '-'; description = 'Von Arena formulierter lebendiger Titel, maximal 70 Zeichen.' }; message = @{ type = 'string'; required = $true; default = '-'; description = 'Ein natuerlicher, einladender Satz, maximal 140 Zeichen; keine Auflistung.' } };
            returns = '{ delivered, title, message, limits: { titleCharacters=70, messageCharacters=140 } }';
            example = @{ title = '✅ Arena hat den Lauf-Bug behoben!'; message = 'Der Lauf-Bug ist weg – komm ins Spiel und probiere es aus!' };
            errors = @('NOTIFICATIONS_DISABLED', 'DRAFT_GRADE_RISK: model_audit hat die Arbeit als Entwurf benotet (wenige Teile, keine Polygon-/Mesh-/Union-/Detail-Geometrie) - nachbauen oder die Einfachheit mit grade erklaeren.', 'BAD_ARGS: title/message fehlen oder ueberschreiten 70/140 Zeichen.');
            notes = @('Version 7.2.0: Die Antwort enthaelt notification { flowId, platformVerdict, platformReason, verified }. Steht dort NOTIFICATION_UNVERIFIED, hat Windows die Meldung vermutlich unterdrueckt (Grund im Feld platformReason) - behaupte dann NICHT, der Nutzer sei benachrichtigt, sondern sage im Antworttext, was fertig ist und dass die Windows-Meldung moeglicherweise nicht erscheint.', 'Version 7.2.0: Die Antwort enthaelt buildRegister { models, audited, unaudited, drafts, declared, averageFinishScore } und buildRegisterNote: was wurde gebaut, was davon ist mit model_audit gemessen, was ist noch Entwurf. Steht dort ein ungeprueftes Modell, hat model_audit diese Geometrie nie gemessen - hole das nach oder sage ehrlich, was ungeprueft ist.') })
                        $t.Add(@{ name = 'set_context'; category = 'session'; summary = 'Seite wechseln: server oder client.';
            description = 'Bestimmt, welche Seite Laufzeit-Werkzeuge (run_lua) treffen. run_lua selbst laeuft IMMER nur auf der Server/Seite - fuer den Client die client_-Werkzeuge.';
            params = @{ context = @{ type = "'server'|'client'"; required = $true; default = '-'; description = '' } };
            returns = '{ context, note }';
            example = @{ context = 'client' };
            errors = @('BAD_ARGS: context muss server oder client sein.') })
                                        $t.Add(@{ name = 'wait'; category = 'session'; summary = 'Im Place warten + Output mitlesen.';
            params = @{ seconds = @{ type = 'number'; required = $false; default = '1'; description = 'max 60.' } };
            returns = '{ waited, output: [...] }';
            example = @{ seconds = 2 };
            errors = @() })

        # ---------------- GUI / CLIENT ----------------
                                                        

        # ---------------- SIMULATION (sim_start bewusst gesperrt) ----------------
        $t.Add(@{ name = 'sim_start'; category = 'sim'; summary = 'Deaktiviert: keine unterstuetzte Physik-/Skript-Simulation im echten Edit-Modus.';
            description = 'Dieser Aufruf ist dauerhaft gesperrt, solange die dokumentierte Roblox-Studio-API keinen unterstuetzten Weg fuer Physik/Skripte bei EditModeActive=true bietet. Die fruehere Implementierung nutzte StudioTestService:ExecuteRunModeAsync (offizieller Studio Run) und verliess den Edit-Modus. Nicht erneut versuchen; compile_check und run_lua bleiben verfuegbar, Live-Verhalten muss der Nutzer in Studio pruefen.';
            params = @{};
            returns = '{ ok=false, code="SIM_DISABLED", reason="EDIT_MODE_SIMULATION_UNAVAILABLE" }';
            example = @{};
            errors = @('SIM_DISABLED: sim_start ist bis zu einer unterstuetzten echten Edit-Modus-Simulation deaktiviert.') })
        $t.Add(@{ name = 'sim_stop'; category = 'sim'; summary = 'Nur eine bestaetigt bridge-eigene Studio-Run-Session stoppen.';
            description = 'Stoppt ausschliesslich eine bereits laufende, der Bridge gehoerende Session mit RunService:Stop() und wartet auf EditModeActive=true (12s). Der Start neuer Studio-Run-Simulationen ist deaktiviert; ein vom Nutzer gestarteter Test wird nicht fernbeendet. Fallback: Shift+F5; nicht in einer Schleife wiederholen.';
            params = @{};
            returns = '{ ok, state { running=false, editModeActive=true, stoppedByBridge } }';
            example = @{};
            errors = @('SIM_NOT_BRIDGE_OWNED: aktive Session ist nicht als bridge-eigen bestaetigt.', 'SIM_STOP_NEEDS_USER: Nutzer muss selbst stoppen.') })
        $t.Add(@{ name = 'sim_status'; category = 'sim'; summary = 'Studio-Teststatus lesen; sim_start ist deaktiviert (read-only).';
            description = 'Liest EditModeActive, RunService-Modus (Studio Run vs Play/F5, sonst unknown), startedByBridge/simStartedAt und die verfuegbare Player-Zahl. simAllowed ist immer false: Die fruehere Studio-Run-Implementierung verliess den Edit-Modus (EditModeActive=false); die dokumentierte API bietet keinen unterstuetzten true Edit-Modus-Pfad fuer Physik/Skripte.';
            params = @{};
            returns = '{ running, mode, editModeActive, runServiceRunning, startedByBridge, simStartedAt, simAllowed=false, playerCount, note }';
            example = @{};
            errors = @() })

        # ---------------- MESH / BLENDER (Version 7.4.0) ----------------
        $t.Add(@{ name = 'blender_status'; category = 'mesh'; summary = 'Ist Blender bereit? Zustand, Version, Pfad, Probe.';
            description = 'Liest den Schritt-4-Zustand der Bridge: Blender wird gesucht (vorhandene Installationen zuerst), die Version gemessen und eine ECHTE Faehigkeitsprobe gefahren (Blender baut im Hintergrund wirklich ein OBJ). Nur wenn die Probe bestanden ist, wird state ready und der Mesh-Bau frei. Mit action="check" wird die ganze Pruefung erneut angestossen (Hintergrund, sofortige Antwort - danach kurz erneut lesen). Solange state nicht ready ist, ist der Mesh-Bau deaktiviert - build_mesh_model antwortet dann BLENDER_NOT_READY. Der Polygon-Weg (build_polygon_model) funktioniert unabhaengig davon.';
            params = @{ action = @{ type = 'string'; required = $false; default = '-'; description = 'Leer oder "check" (Suche + Version + echte Faehigkeitsprobe erneut starten).' } };
            returns = '{ ok, result { started, blender { state, ready, version, path, source, percent, message, detail, probe, enabled, meshFolder, installLog }, note } }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'build_mesh_model'; category = 'mesh'; summary = 'Blender baut im Hintergrund ein OBJ (ein Slot = ein MeshPart).';
            description = 'Startet den Blender-Bau als HINTERGRUND-Job und antwortet sofort mit jobId - niemals synchron warten. Je Slot liefert der Aufruf ein Blender-Python-Skript (nur Geometrie: bpy, bmesh, math, mathutils, random; Datei-/Netzwerk-/Prozesszugriff, bpy.ops.wm.* und Exportfunktionen werden vor dem Start abgelehnt). 1 Blender-Einheit = 1 Stud, Y ist oben, die bbox-Mitte am Ursprung setzt der Runner der Bridge automatisch, Modifier werden beim Export angewandt. Danach MISST die Bridge die OBJ-Datei (Dreiecke, Groesse in Studs) und legt die viereckigen MeshPart-Platzhalter selbst in den Place. Der NUTZER laedt die Datei(en) in Roblox hoch und traegt die Mesh-Id(s) im Bridge-Fenster "Mesh-Uploads" ein; mesh_apply_asset setzt die Geometrie ein. Fortschritt und Zahlen mit mesh_status lesen (kurz pollen, nicht in einer engen Schleife). Siehe meshBuildRules in den Guides.';
            params = @{ modelName = @{ type = 'string'; required = $true; default = '-'; description = 'Name des Modells (auch fuer die Platzhalter-Namen).' }; slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { name, script, offset {x,y,z}, targetTriangles, color, material, canCollide } - ein Eintrag je MeshPart (max. 12).' }; parentRef = @{ type = 'string'; required = $false; default = 'game.Workspace'; description = 'Wohin die Platzhalter kommen.' }; origin = @{ type = 'table'; required = $false; default = '{x=0,y=0,z=0}'; description = 'Weltposition des Modell-Ursprungs; Slot-Offsets kommen darauf.' }; rotationY = @{ type = 'number'; required = $false; default = '0'; description = 'Drehung um Y in Grad.' }; anchored = @{ type = 'boolean'; required = $false; default = 'true'; description = 'Anchored der Platzhalter.' }; timeoutSeconds = @{ type = 'number'; required = $false; default = '300'; description = 'Zeitlimit je Slot (max. 900).' } };
            returns = '{ ok, result { jobId, state="queued", slotCount, blender, meshFolder, note, files } }';
            example = @{ modelName = 'Turret'; origin = @{ x = 12; y = 4; z = -18 }; slots = @( @{ name = 'base'; script = 'bpy.ops.mesh.primitive_cylinder_add(vertices=24, radius=1.4, depth=0.6)'; color = '#8A8F99' } ) };
            errors = @('BLENDER_NOT_READY: Blender fehlt/installiert noch - nichts wurde gebaut.', 'SCRIPT_REJECTED: mindestens ein Skript ist gesperrt (problems nennt den Grund).', 'BUDGET_EXCEEDED: mehr als 12 Slots.', 'BAD_ARGS: slots fehlt oder ist leer.') })
        $t.Add(@{ name = 'mesh_status'; category = 'mesh'; summary = 'Zustand der Mesh-Jobs, gemessene Dreiecke/Groesse, Platzhalter, Ids.';
            description = 'Liest alle Mesh-Jobs dieser Sitzung aus dem Register der Bridge: Zustand, Ordner, je Slot die GEMESSENEN Dreiecke und die Groesse in Studs, die Platzhalter, die eingetragene Asset-Id und die zurueckgelesene MeshId. readyForUpload nennt genau die Dateien, die der Nutzer noch hochladen muss. Mit action="placeholders" werden die Platzhalter neu angefordert (z.B. nachdem sie im Studio geloescht wurden).';
            params = @{ jobId = @{ type = 'string'; required = $false; default = '-'; description = 'Nur diesen Job lesen.' }; action = @{ type = 'string'; required = $false; default = '-'; description = 'Leer oder "placeholders" (Platzhalter neu anfordern).' } };
            returns = '{ ok, result { blender, jobs [ { jobId, modelName, state, folder, placeholdersCreated, placeholderState, slots [ { key, name, state, triangles, size, fileName, objPath, assetId, meshIdReadBack, placeholderPath, error } ] } ], readyForUpload, appliedCount, failedCount, summary, note } }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'mesh_cancel'; category = 'mesh'; summary = 'Laufenden Blender-Job abbrechen.';
            description = 'Beendet den laufenden Blender-Job (ohne jobId den neuesten dieser Sitzung). Eine halbfertige OBJ-Datei wird verworfen; bereits gemessene Slots bleiben unveraendert. Nicht in einer Schleife aufrufen.';
            params = @{ jobId = @{ type = 'string'; required = $false; default = '-'; description = 'Job aus build_mesh_model/mesh_status.' } };
            returns = '{ ok, result { jobId, cancelled, note } }';
            example = @{ jobId = 'mesh_1a2b3c4d5e' };
            errors = @('NO_JOB: es laeuft kein Job.') })
        $t.Add(@{ name = 'mesh_apply_asset'; category = 'mesh'; summary = 'Hochgeladene Mesh-Ids in die vorhandenen Platzhalter setzen.';
            description = 'Setzt die Geometrie in die BESTEHENDEN MeshPart-Platzhalter (Slot-keys aus mesh_status). Groesse, Position, Welds, Attribute und Animationen bleiben erhalten. MeshPart.MeshId ist schreibgeschuetzt - die Bridge benutzt deshalb InsertService:CreateMeshPartAsync + MeshPart:ApplyMesh ueber das Plugin. Die Asset-Ids muessen zum Konto des Nutzers gehoeren (er hat die Dateien selbst hochgeladen). Nach dem Einsetzen meldet die Antwort je Slot die zurueckgelesene MeshId - erst dann ist der Slot wirklich fertig.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key, assetId } - keys aus mesh_status, assetId ist die Zahl aus Roblox (rbxassetid:// optional).' } };
            returns = '{ ok, result { applied [ { key, state, assetId, meshIdReadBack, path, error } ], pluginResult, note } }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base'; assetId = 1234567890 } ) };
            errors = @('BAD_ARGS: slots fehlt oder enthaelt keine gueltige key/assetId.', 'STUDIO_UNREACHABLE_OR_TIMEOUT: Studio hat nicht geantwortet - nichts wurde eingesetzt.') })
        $t.Add(@{ name = 'mesh_slots'; category = 'mesh'; summary = 'Viereckige MeshPart-Platzhalter anlegen (interner Baustein des Mesh-Wegs).';
            description = 'Legt die viereckigen MeshPart-Platzhalter mit den GEMESSENEN Maßen an und markiert sie mit ArenaMeshSlot/ArenaMeshState/ArenaPlaceholder. Normalerweise macht das die Bridge nach dem Blender-Bau selbst - dieser Aufruf ist fuer Sonderfaelle (z.B. Platzhalter an anderer Stelle neu anlegen). Die Groesse muss von mesh_status kommen; sie darf nicht geschaetzt werden.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key, name, size {x,y,z}, position {x,y,z}, rotationY, color, material, canCollide, fileName } (max. 40).' }; parentRef = @{ type = 'string'; required = $false; default = 'game.Workspace'; description = 'Elternobjekt.' }; modelName = @{ type = 'string'; required = $false; default = 'ArenaMesh'; description = 'Namensbestandteil.' }; buildId = @{ type = 'string'; required = $false; default = '-'; description = 'Job-Id aus mesh_status.' } };
            returns = '{ ok, created, failed, createdCount, failedCount, note }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base'; name = 'base'; size = @{ x = 2.8; y = 0.6; z = 2.8 } } ) };
            errors = @('BAD_ARGS: slots fehlt.', 'BUDGET_EXCEEDED: mehr als 40 Platzhalter.') })
        $t.Add(@{ name = 'mesh_apply'; category = 'mesh'; summary = 'Interner Befehl der Bridge: Geometrie einsetzen (nicht direkt aufrufen).';
            description = 'Wird von der Bridge (mesh_apply_asset) an das Plugin geschickt. Der Aufruf setzt je Slot { key, assetId } die Geometrie in den bestehenden MeshPart mit dem Attribut ArenaMeshSlot. Nicht direkt benutzen - die Dokumentation steht bei mesh_apply_asset.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key, assetId }.' } };
            returns = '{ ok, applied, failed, appliedCount, failedCount, note }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base'; assetId = '1234567890' } ) };
            errors = @('BAD_ARGS: slots fehlt.') })
        $t.Add(@{ name = 'mesh_drop'; category = 'mesh'; summary = 'Interner Befehl der Bridge: Mesh-Slot stornieren (nicht direkt aufrufen).';
            description = 'Wird von der Bridge geschickt, wenn der Nutzer im automatischen Mesh-Fenster "Stornieren" bestaetigt. Loescht jedes MeshPart mit dem Attribut ArenaMeshSlot = key aus dem Place - den Platzhalter UND ein schon eingesetztes Mesh. Ehrlich: ein eingesetztes Mesh wird NICHT wiederhergestellt (es kommt kein Platzhalter zurueck). Danach raeumt die Oberflaeche Slot und Dateien auf. Wie jeder schreibende Befehl ist er im laufenden Playtest (Testmodus) blockiert.';
            params = @{ slots = @{ type = 'array'; required = $true; default = '-'; description = 'Array von { key } (keys aus mesh_status).' } };
            returns = '{ ok, dropped, failed, droppedCount, failedCount, note }';
            example = @{ slots = @( @{ key = 'mesh_1a2b3c4d5e:base' } ) };
            errors = @('BAD_ARGS: slots fehlt.', 'SIM_RUNNING/USER_PLAYTEST_ACTIVE: im laufenden Playtest sind schreibende Befehle gesperrt.') })

        # ---------------- JOBS ----------------
        $t.Add(@{ name = 'start_job'; category = 'jobs'; summary = 'Arbeit im Hintergrund starten (keine 60s-Grenze).';
            description = 'Startet Lua-Code ODER einen Tool-Call als Job im Studio. Laeuft unabhaengig weiter, auch wenn der HTTP-Call timet-out. Fortschritt: job kann job.progress(percent, message) rufen (im Code als job-Parameter: job:progress(...)). Ergebnis: job_result. Abbruch: cancel_job (kooperativ).';
            params = @{ name = @{ type = 'string'; required = $false; default = "'job'"; description = 'Merkname.' }; source = @{ type = 'string'; required = $false; default = 'null'; description = 'Lua-Code (in der persistenten Umgebung). (alternativ tool+args)' }; tool = @{ type = 'string'; required = $false; default = 'null'; description = 'Tool-Name, der im Job laufen soll.' }; args = @{ type = 'table'; required = $false; default = '{}'; description = 'Argumente fuer tool.' } };
            returns = '{ ok, jobId, status="running", poll = "job_status / job_result" }';
            example = @{ name = 'build wall'; source = 'for i=1,500 do ... end; return "done"' };
            errors = @('BAD_ARGS: source oder tool+args angeben.', 'COMPILE_ERROR: bei source.') })
        $t.Add(@{ name = 'job_status'; category = 'jobs'; summary = 'Läuft der Job? Wie weit?';
            params = @{ jobId = @{ type = 'string'; required = $true; default = '-'; description = '' } };
            returns = '{ status: "running"|"done"|"error", progress (0..1), progressMessage, secondsElapsed, hasResult }';
            example = @{ jobId = 'job_3' };
            errors = @('JOB_NOT_FOUND') })
        $t.Add(@{ name = 'job_result'; category = 'jobs'; summary = 'Ergebnis eines fertigen Jobs holen.';
            params = @{ jobId = @{ type = 'string'; required = $true; default = '-'; description = '' }; keep = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = Ergebnis behalten, sonst wird es nach dem Hohlen entfernt.' } };
            returns = '{ ok, result (Rueckgabewert), output (gedrucktes waehrend des Jobs), durationSeconds, error? { code, message } }';
            example = @{ jobId = 'job_3' };
            errors = @('JOB_NOT_FOUND', 'JOB_RUNNING: noch nicht fertig - job_status warten.') })
        $t.Add(@{ name = 'list_jobs'; category = 'jobs'; summary = 'Alle Jobs (aktiv + erledigt).';
            params = @{};
            returns = '{ jobs: [ { id, name, status, progress, secondsElapsed } ], activeCount }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'cancel_job'; category = 'jobs'; summary = 'Job abbrechen (kooperativ).';
            description = 'Setzt ein Flag, das der Job-Code ueber job:cancelled() pruefen kann. Lua-Threads lassen sich nicht hart toeten - der Code sollte in Schlingen job:cancelled() pruefen.';
            params = @{ jobId = @{ type = 'string'; required = $true; default = '-'; description = '' } };
            returns = '{ cancelled = true, note }';
            example = @{ jobId = 'job_3' };
            errors = @('JOB_NOT_FOUND') })
        $t.Add(@{ name = 'force_fail'; category = 'jobs'; summary = 'Haengende Studio-Queue sofort leeren (Admin-Reset, ohne Studio-Neustart).';
            description = 'Rettungsanker, wenn Befehle in pendingInStudio haengen: JEDER noch offene Befehl dieses Places wird sofort mit einem endgueltigen Fehler beantwortet (Code FORCE_CLEARED), die serielle Warteschlange wird geleert und Studio wird gebeten, seine lokale Queue zu verwerfen. Kein Befehl wird wiederholt. Ein haengendes Lua im Plugin kann trotzdem einen Studio-Neustart brauchen - dann zeigt die Antwort executor.alive=false.';
            params = @{ reason = @{ type = 'string'; required = $false; default = 'cleared by admin control'; description = 'Grund, der in jeder Fehlerantwort steht.' }; code = @{ type = 'string'; required = $false; default = 'FORCE_CLEARED'; description = 'Fehlercode der Antworten (z. B. FORCE_CLEARED).' } };
            returns = '{ ok, action, clearedCommands, executor: { alive, runningCommandId, queueDepth }, queue, note }';
            example = @{ reason = 'bridge wedged after a 15 minute list_jobs block' };
            errors = @() })
        $t.Add(@{ name = 'clear_pending'; category = 'jobs'; summary = 'Alias fuer force_fail (Queue leeren).';
            description = 'Exakt dasselbe wie force_fail: alle offenen Befehle sofort mit FORCE_CLEARED beantworten und die Warteschlange leeren. Fuer Notfaelle gedacht, wenn die KI sonst nur noch Timeouts sieht.';
            params = @{ reason = @{ type = 'string'; required = $false; default = 'cleared by admin control'; description = 'Grund in der Fehlerantwort.' }; code = @{ type = 'string'; required = $false; default = 'FORCE_CLEARED'; description = 'Antwortcode.' } };
            returns = '{ ok, action, clearedCommands, executor, queue, note }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'get_pending'; category = 'jobs'; summary = 'Was laeuft noch in Studio? (ueberlebte Timeouts).';
            description = 'Listet pro commandId ausstehende Befehle (queued/delivered/received/started), Executor-Heartbeats, Zeitbudget und späte Ergebnisse. Ein Folgeaufruf kann auf serialisierte Studio-Arbeit warten; bei Executor-Ausfall gibt der Watchdog die Queue frei und meldet, ob Teiländerungen möglich sind. Vor einem Retry Zustand prüfen.';
            params = @{};
            returns = '{ runningInStudio: [ { commandId, tool, status, seconds, queuedAt, deliveredAt, receivedAt, startedAt, heartbeatAt, budgetSeconds } ], lateResults: [ { tool, commandId, result } ] }';
            example = @{};
            errors = @() })

        # ---------------- SYSTEM ----------------
        $t.Add(@{ name = 'batch'; category = 'system'; summary = 'Viele Tools in einer Anfrage.';
            description = 'sequenziell (Standard) oder parallel=true. stopOnError=true bricht beim ersten Fehler ab. ACHTUNG: parallel=true fuehrt die Calls GLEICHZEITIG im Studio aus - nur fuer echte Unabhaengigkeiten.';
            params = @{ commands = @{ type = 'array'; required = $true; default = '-'; description = '[ { tool, args }, ... ].' }; parallel = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; stopOnError = @{ type = 'bool'; required = $false; default = 'false'; description = '' }; timeoutSeconds = @{ type = 'number'; required = $false; default = '90'; description = 'parallel-Modus.' } };
            returns = '{ results: [ ...je Call... ], count, failed, mode }';
            example = @{ commands = @(@{ tool = 'create_instance'; args = @{ className = 'Part'; name = 'A' } }, @{ tool = 'create_instance'; args = @{ className = 'Part'; name = 'B' } }) };
            errors = @() })
        $t.Add(@{ name = 'parallel'; category = 'system'; summary = 'Kurzform: batch mit parallel=true.';
            params = @{ commands = @{ type = 'array'; required = $true; default = '-'; description = '' } };
            returns = 'wie batch';
            example = @{ commands = @(@{ tool = 'clone_instance'; args = @{ ref = '#42'; count = 10 } }) };
            errors = @() })
        $t.Add(@{ name = 'undo'; category = 'system'; summary = 'Letzte Aenderung rueckgaengig (Studio-History).';
            description = 'Nimmt den letzten Schritt in der Studio-History zurueck (wie Strg+Z). Unions setzen vorher automatisch einen Punkt.';
            params = @{};
            example = @{};
            returns = '{ undone }';
            errors = @('RUNTIME_ERROR: Undo nicht moeglich.') })
        $t.Add(@{ name = 'redo'; category = 'system'; summary = 'Wiederholen.';
            description = 'Macht den letzten undo wieder gueltig (wie Strg+Y).';
            params = @{};
            example = @{};
            returns = '{ redone }';
            errors = @() })
        $t.Add(@{ name = 'set_waypoint'; category = 'system'; summary = 'Undo-Punkt setzen.';
            description = 'Setzt einen sichtbaren Punkt in der Studio-History, damit der Benutzer deine Arbeit in EINEM Schritt rueckgaengig machen kann. Die Bridge setzt vor union, create, delete & Co. automatisch welche.';
            params = @{ name = @{ type = 'string'; required = $false; default = "'manual'"; description = '' } };
            returns = '{ waypoint }';
            example = @{ name = 'Before the wall' };
            errors = @() })
        $t.Add(@{ name = 'get_notices'; category = 'system'; summary = 'Was ist passiert, ohne dass du es getan hast?';
            description = 'Meldungen wie "Benutzer hat den Test gestartet/stoppt", "Plugin neu verbunden" etc. Kommen auch automatisch als notices in fast jeder Antwort.';
            params = @{ all = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = auch schon gelieferte.' } };
            returns = '{ notices: [ { seq, kind, message, time, data } ] }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'get_events'; category = 'system'; summary = 'Ereignisse von der Bridge-Seite.';
            description = 'Dasselbe wie get_notices, aber uebersteht Plugin-Reloads (wird im Programm gespeichert).';
            params = @{};
            returns = '{ events: [...], count }';
            example = @{};
            errors = @() })
        $t.Add(@{ name = 'scaffold_ui_scripts'; category = 'session'; summary = 'Aufbau-Vorschlag fuer eine Oberflaeche: welche KLEINEN Skripte, wer macht was.';
            description = 'Server-Werkzeug ohne Studio-Umlauf. Es liefert die Aufteilung (Config, State, je Bildschirm ein View, Input, Update, Effects, Data), die Reihenfolge und die Leitplanken - damit eine GUI in StarterGui als echte, editierbare Instanzen entsteht und die Logik in mehreren kleinen Skripten liegt, nicht in einem 10.000-Zeilen-LocalScript. Die Strukturmessung (codeLayout) meldet MONOLITH_RISK, wenn ein Skript ueber 400 Zeilen hat oder ueber 15 Instance.new enthaelt. Regeln: uiStructureRules.';
            params = @{ ui = @{ type = 'string'; required = $true; default = '-'; description = 'Name der Oberflaeche, z.B. "Shop".' }; screens = @{ type = 'string[]'; required = $false; default = 'null'; description = 'Bildschirmseiten, je eine bekommt ein eigenes View-Skript.' }; mode = @{ type = 'string'; required = $false; default = 'new'; description = '"new" oder "extend" (bestehende, vom Nutzer gebaute GUI erweitern).' } };
            returns = '{ ui, mode, structure, scripts: [ { name, className, responsibility, why, order } ], buildOrder, limits, note }';
            example = @{ ui = 'Shop'; screens = @( 'Shop', 'Inventory' ); mode = 'extend' };
            errors = @('BAD_ARGS: ui fehlt.') })
        $t.Add(@{ name = 'ask_user'; category = 'session'; summary = 'Den Nutzer etwas fragen - mit Entscheidungsbaum, Fenster am Mauszeiger.';
            description = 'Statt im Chat zu fragen (der Nutzer ist oft weg und uebersieht es): ein Fenster erscheint in der Naehe des Mauszeigers mit Haekchen/Knopf-Optionen und eigener Antwort. Der ganze Baum kommt in EINER Anfrage. Bedingungen erlaubt: when = [ { questionId = "fruehererId", anyOf = ["optionA"], allOf = [...], custom = true } ] auf eine FRUEHERE Frage (mehrere Ebenen tief). Der gesamte Baum zaehlt: max 12 Fragen, max 6 Optionen je Frage, max 400 Zeichen je Text, Ids eindeutig. Du kannst dabei schlafen: waitSeconds (max 50) blockiert; kommt keine Antwort, liefert der Aufruf { state: "waiting", askId, nextCall } und du rufst spaeter mit resume=true erneut auf. Antworten kommen notfalls als _bridge.userAnswers mit.';
            params = @{ title = @{ type = 'string'; required = $true; default = '-'; description = 'Kurze Ueberschrift (max 90 Zeichen).' }; message = @{ type = 'string'; required = $false; default = 'null'; description = 'Einleitungssatz (max 600 Zeichen).' }; questions = @{ type = 'object[]'; required = $true; default = '-'; description = 'Je Frage: { id, text, options: [ { id, label, description? } ], allowCustomResponse?, required?, multi?, when? }.' }; expiresInSeconds = @{ type = 'int'; required = $false; default = '180'; description = '30..1800: so lange bleibt das Fenster offen.' }; waitSeconds = @{ type = 'int'; required = $false; default = '0'; description = '0..50: aktiv auf die Antwort warten (0 = sofort zurueck und spaeter mit resume=true fortsetzen).' }; askId = @{ type = 'string'; required = $false; default = 'null'; description = 'Zum Fortsetzen einer offenen Frage.' }; resume = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = erneut auf diese Frage warten.' } };
            returns = '{ state: waiting|answered, askId, answers: { frageId: { optionIds, labels, custom } }, path, notShown, summary, secondsLeft, nextCall }';
            example = @{ title = 'Welcher Baumstil?'; waitSeconds = 45; questions = @( @{ id = 'style'; text = 'Welchen Stil willst du?'; options = @( @{ id = 'organic'; label = 'Organisch' }, @{ id = 'lowpoly'; label = 'Low-Poly' } ) }, @{ id = 'detail'; text = 'Welche Details?'; multi = $true; when = @( @{ questionId = 'style'; anyOf = @('organic') } ); options = @( @{ id = 'leaves'; label = 'Laub' }, @{ id = 'branches'; label = 'Zweige' } ) } ) };
            errors = @('ASK_TOO_MANY_QUESTIONS: mehr als 12 Fragen oder mehr als 6 Optionen je Frage.', 'ASK_GRAPH_INVALID: doppelte/fehlende Ids, unbekannte Bedingung, weniger als 2 Optionen.', 'ASK_CYCLE: eine Frage haengt von sich selbst oder einer SPAETEREN Frage ab.', 'ASK_EXPIRED: das Fenster lief ab, ohne dass geantwortet wurde.', 'ASK_UNKNOWN: unbekannte askId.') })
        $t.Add(@{ name = 'confirm_action'; category = 'session'; summary = 'Kurz nachfragen: soll Arena das wirklich tun? (Ja/Nein)';
            description = 'Abkuerzung fuer ask_user mit genau einer Frage und zwei Optionen. Fuer Loeschungen, Umbauten, Ueberschreiben von Nutzerarbeit oder teure Schritte. Der Nutzer kann auch eine eigene Antwort schreiben.';
            params = @{ title = @{ type = 'string'; required = $true; default = '-'; description = 'Was bestaetigt werden soll.' }; message = @{ type = 'string'; required = $false; default = 'null'; description = 'Was passiert, wenn der Nutzer zustimmt.' }; confirmLabel = @{ type = 'string'; required = $false; default = 'Ja, mach das'; description = '' }; cancelLabel = @{ type = 'string'; required = $false; default = 'Nein, nicht'; description = '' }; expiresInSeconds = @{ type = 'int'; required = $false; default = '120'; description = '' }; waitSeconds = @{ type = 'int'; required = $false; default = '0'; description = '0..50, wie ask_user.' } };
            returns = '{ state, askId, confirmed: true/false, customResponse, answers, path, notShown, summary }';
            example = @{ title = 'Darf ich das bestehende Gebaeude ersetzen?'; message = 'Alle Teile des alten Hauses werden geloescht und neu gebaut.'; waitSeconds = 45 };
            errors = @('ASK_EXPIRED: keine Antwort im Zeitfenster.', 'ASK_UNKNOWN: unbekannte askId.') })
        $t.Add(@{ name = 'wait_for_user'; category = 'session'; summary = 'Aktiv auf eine Nachricht des Nutzers warten (max. 50 s).';
            description = 'Blockiert, bis der Nutzer ueber die Bridge schreibt ("Nachricht an Arena senden" im Menue der Place-Zeile) oder die Zeit ablaeuft. Die Nachrichten selbst stehen im Umschlag DERSELBEN Antwort unter _bridge.userMessages. Nur an einer echten Entscheidungsstelle benutzen, nie als Dauer-Polling. Der harte HTTP-Deckel liegt bei 55/85 s, deshalb ist maxSeconds auf 50 begrenzt.';
            params = @{ maxSeconds = @{ type = 'int'; required = $false; default = '30'; description = '1..50.' } };
            returns = '{ state: messages_waiting|timeout, reason, waitedSeconds, messageCount, maxSeconds, note }';
            example = @{ maxSeconds = 25 };
            errors = @() })
        $t.Add(@{ name = 'ack_user_message'; category = 'session'; summary = 'Nachricht des Nutzers als gelesen bestaetigen (Pflicht).';
            description = 'Beendet die Wiederholung einer Nutzernachricht und zeigt dem Nutzer im Fenster "von Arena bestaetigt" plus deine optionale Kurzantwort. Ohne Bestaetigung wird dieselbe Nachricht in bis zu drei Antworten wiederholt und die Oberflaeche meldet ehrlich "angekommen, nicht bestaetigt".';
            params = @{ id = @{ type = 'string'; required = $false; default = 'null'; description = 'Eine Nachrichten-Id aus _bridge.userMessages.' }; ids = @{ type = 'string[]'; required = $false; default = 'null'; description = 'Mehrere Ids.' }; all = @{ type = 'bool'; required = $false; default = 'false'; description = 'true = alle offenen Nachrichten.' }; reply = @{ type = 'string'; required = $false; default = 'null'; description = 'Kurze Antwort an den Nutzer (max. 300 Zeichen).' } };
            returns = '{ acked, replyShownToUser, note }';
            example = @{ id = 'msg_ab12cd34ef56'; reply = 'Verstanden - ich baue den Baum neu.' };
            errors = @('BAD_ARGS: weder id, ids noch all=true.', 'ACK_UNKNOWN_MESSAGE: keine offene Nachricht mit dieser Id (knownMessageIds nennt die gueltigen).') })
        $t.Add(@{ name = 'get_chunk'; category = 'system'; summary = 'Stueck eines grossen Ergebnisses holen.';
            description = 'Wenn eine Antwort zu gross ist, liegt sie im Programm: blobId + chunkCount. Alle Chunks in Reihe holen und zusammenfuegen = komplettes Ergebnis (nie abgeschnitten).';
            params = @{ blobId = @{ type = 'string'; required = $true; default = '-'; description = '' }; index = @{ type = 'int'; required = $true; default = '-'; description = '1..chunkCount.' } };
            returns = '{ data, index, chunkCount, isLast, totalChars }';
            example = @{ blobId = 'blob_abc'; index = 1 };
            errors = @('REF_NOT_FOUND: unbekanntes/abgelaufenes blobId (30 Min).') })
        $t.Add(@{ name = 'upload_text'; category = 'system'; summary = 'Grossen Text in Stuecken hochladen.';
            description = 'Fuer Skriptquellen > 50 KB: in Chunks hierher, danach sourceRef=<uploadId> an set_script_source/insert_script. Der Text wird unverändert übernommen (kein String-Schneidwerk, keine %-Kollisionen).';
            params = @{ text = @{ type = 'string'; required = $true; default = '-'; description = 'Stueck (oder alles).' }; uploadId = @{ type = 'string'; required = $false; default = 'neu'; description = 'Fuer mehrere Chunks: gleicher Wert.' }; chunkIndex = @{ type = 'int'; required = $false; default = '1'; description = '' }; chunkCount = @{ type = 'int'; required = $false; default = '1'; description = '' } };
            returns = '{ uploadId, chars, complete, useAs }';
            example = @{ text = 'local M = {}'; chunkIndex = 1; chunkCount = 3; uploadId = 'myScript' };
            errors = @() })
        $t.Add(@{ name = 'get_docs'; category = 'system'; summary = 'Doku holen: pro Tool, pro Kategorie oder komplett.';
            description = 'Dasselbe wie GET /api/docs - als Tool. Ohne Argumente: komplett. Version 7.1.4: Der Sessionstart liefert nur noch die Kernwerkzeuge vollstaendig (Bauen, Audit, Lesen, Sitzung) und alle uebrigen als Index mit Name/Kategorie/Kurztext. Vor dem ersten Einsatz eines Index-Werkzeugs hier die Parameter holen - die Doku ist hier IMMER vollstaendig.';
            params = @{ tool = @{ type = 'string'; required = $false; default = 'null'; description = 'Einzelnes Tool (z.B. "union").' }; category = @{ type = 'string'; required = $false; default = 'null'; description = 'info, spatial, orientation, create, properties, scripts, fill, union, assets, output, play, gui, jobs, system.' }; full = @{ type = 'bool'; required = $false; default = 'false'; description = 'Komplette Doku.' } };
            returns = 'Doku-JSON (siehe /api/docs)';
            example = @{ tool = 'fill_region' };
            errors = @('REF_NOT_FOUND: unbekanntes Tool/Kategorie (Liste im Fehler).') })
        $t.Add(@{ name = 'capture_screenshot'; category = 'system'; summary = 'Roblox-Studio-Fenster als Screenshot erfassen.';
            description = 'Erfasst das Studio-Fenster. Arena kann frei zwischen Screenshot und den textuellen Szenenwerkzeugen mit exakten Objektwerten wählen.';
            params = @{ confirm = @{ type = 'bool'; required = $false; default = 'false'; description = 'Aus Kompatibilitaetsgruenden akzeptiert; nicht mehr erforderlich.' }; includeBase64 = @{ type = 'bool'; required = $false; default = 'false'; description = 'Bild als Base64-Blob.' }; maxWidth = @{ type = 'int'; required = $false; default = '1100'; description = '' } };
            returns = '{ file, width, height, advice }';
            example = @{ confirm = $true };
            errors = @('RUNTIME_ERROR: Studio-Fenster nicht sichtbar.') })

        return ,$t
    }


    # ------------------------------------------------------------------
    # MANIFEST: die Bedienungsanleitung für die KI
    # ------------------------------------------------------------------
    # ==================================================================
    # GELEITINFORMATIONEN: Regeln, Koordinaten, Play-Modi, Jobs, Fehler-
    # Codes, Workflows. Stecken in Manifest, /api/docs und _sessionStart.
    # ==================================================================
    function Get-BridgeGuides {
        return @{
            importantRules = @(
                'Choose the tools and workflow that best fit the task. The bridge exposes precise read, build, script, asset, playtest and batch tools; these are capabilities, not a mandatory checklist.',
                'For ANY nontrivial custom 3D model, prefer build_polygon_model for the main silhouette and major freeform/curved/tapered surfaces - across characters, props, architecture, vehicles, landmarks, terrain and set pieces, not only organic examples. It works much like polygon modelling while the bridge handles triangulation, seamless Wedges, named submodels, per-submodel style, hole caps and default-on WeldConstraints. Use build_assembly as a complement for repeated or modular structure, and native Parts for truly simple, repeated, functional or explicitly primitive/low-poly geometry; do not reduce a hero/custom model to primitive blocks. NEVER set autoWeld=false unless physically independent polygon pieces are requested. See modelBuildRules for the universal complexity and finish bar.',
                'NONTRIVIAL 3D BUILD METHOD (ALL CATEGORIES): follow modelBuildRules.polygonWorkflow. The first model-building call for every nontrivial custom object is build_polygon_model, and that call must contain the complete distinguishing silhouette as multiple named planar faces/submodels or a measured loft—not only one front polygon. One polygon is one thin skin. Use polygons for authored faces, volumes for tapered/curved cross-sections, and build_assembly for repeats. Afterward verify incomplete=false, facesSkipped=0, skipped=[]; inspect fallbackFaces/warnings, run model_audit and fix the findings. This applies equally to architecture, vehicles, furniture, machines, props, terrain, characters and creatures; only truly simple standard shapes or explicit primitive/blockout requests are exceptions.',
                'For any visual/3D deliverable, make the result intentionally layered and finished: clear primary silhouette, secondary functional forms, tertiary trim/details, coherent palette/materials, and correct joins/placement. Complexity must be purposeful, not random part count. A simple object may remain simple; an unrequested blockout/primitive-only first draft is not a finished build. This standard is global and does not depend on model names or animal/tree examples.',
                'For ANY visual/GUI work, ALWAYS use build_interface (whole screen in one call) or build_surface unless the user explicitly asks for raw GuiObjects: the bridge owns AnchorPoint, Scale-only UDim2, aspect locking, corner-safe padding, layered shadows, scaled strokes, gradients on strokes, REAL raster textures, CanvasGroup discipline and the runtime motion script. Call ui_capabilities first (it probes this Studio build instead of trusting training data), ui_skin to pick or extract an art direction, ui_glow for glow (never hand-build it), ui_texture for the real-texture-first recipe, ui_radial for radial menus (one image id, both colours engine-owned), and ui_audit afterwards - it measures offsetRatio, contrast, per-device pixel sizes, glow/texture/radial usage and a blandness score. See uiEngineRules below for the hard rules.',
                'Object ids such as #42 are stable within the current plugin session and avoid ambiguity when names repeat. Paths and selectors are also accepted where documented.',
                'Several Places can be connected. With the Alle-Places token, GET /api/places returns targetPlace values; selecting one target keeps edits unambiguous.',
                'Queue recovery is explicit and diagnosable: GET /api/queue shows queued/delivered/running commandIds, delivery/start timestamps and executor liveness; POST /api/queue with action=cancel and commandId cancels one command, while action=reset abandons pending work and asks the plugin to reset its local queue. A reset/cancel can leave partial edits; inspect before retrying.',
                'Normal GET and POST tool calls use the same bridge code path. Queue cancellation/reset are mutating controls and require POST.',
                'After an HTTP timeout, a Studio command remains tracked by commandId and may return through _bridge.lateResults. A plugin execution budget and an INDEPENDENT server-side watchdog (queue.sweep) abandon stalled commands so they cannot block the serial queue forever; inspect the Place before retrying because partial changes may exist. Use asJob=true when a long task should deliberately continue in the background. HTTP answers are capped at 55 seconds by default (85 seconds maximum) so a Cloudflare 524 can never cut the connection before the bridge replies.',
                'Asset search covers the Creator Store categories including 3D models, models, meshes/MeshParts, plugins, fonts, audio, images/decals, video and animation. Insertion still reports Roblox permission/privacy errors and warns before inserting scripts.',
                'sim_start is disabled because the former official Studio Run simulation exits Edit mode (EditModeActive=false), and the documented Studio API has no supported true Edit-mode physics/script path. A USER-started Play/F5 test is separate, blocks building (USER_PLAYTEST_ACTIVE), and can only be ended by the user.',
                'Windows finish notifications use report_done { title, message }. Arena writes a lively title (max 70 characters) and an inviting body (max 140); avoid dry changelog lists.',
                'Responses include typed error codes and concrete diagnostics. Use those details to decide the next step.',
                'HARD CONSTRAINT for any hand-written WedgePart/triangle geometry (build_polygon_model already does this correctly - this rule is for genuinely custom run_lua geometry code only): see polygonEngineRules below for the mandatory WedgePart axis convention and the canonical seamless-triangle formula. Getting the axis order wrong is the single most common cause of 90-degree rotation errors and gaping seams in procedural low-poly builds.',
                'ASK THE USER (7.2.0): when you need a real decision, use ask_user (decision tree, window appears at the user''s mouse cursor) or confirm_action (plain yes/no) instead of only asking in chat - the user is often away and misses chat questions. The WHOLE tree goes into ONE ask_user call; conditions use when = [ { questionId = "<earlier question id>", anyOf = ["optionId"] } ] and may nest several levels. Pass waitSeconds (max 50) to wait actively; if nothing arrives you get { state = "waiting", askId, nextCall } - resume later with ask_user { askId, resume: true }. Late answers arrive as _bridge.userAnswers. Never guess while an openQuestions field is present.',
                'FINISH GRADE (7.2.0): model_audit now grades every build (finishScore 0..100, grade draft/simple/detailed/sculpted). grade "draft" means at least 4 parts, no polygon/mesh/union/detail geometry and more than 60 % primitives - report_done answers DRAFT_GRADE_RISK until you rebuild the silhouette with real structure. If the simplicity IS what the user asked for, declare it while building: build_polygon_model/build_assembly { grade = "simple" | "lowpoly" | "blockout" } writes the attribute ArenaDeclaredGrade and the audit stops calling it a draft. report_done also returns buildRegister: it lists what you built and what model_audit has not measured yet.',
                'USER CHANNEL (7.2.0): the user can message you WHILE you work ("Nachricht an Arena senden" in the bridge place row). Every response then carries _bridge.userMessages plus _bridge.userMessageContract. Read it first, apply it, tell the user what you changed, and acknowledge with ack_user_message { id } - an unacknowledged message repeats in up to three responses. wait_for_user { maxSeconds <= 50 } blocks until a message arrives; use it only at a real decision point, never as polling. The user can also switch the place to read-only from the same menu, which is reported as WRITE_LOCKED_BY_USER.'
                'HARD ORGANIC EVIDENCE CONTRACT (separate from the global builder preference): when an organic model is explicitly built with organic=true or is registered from per-model model_audit evidence, build and audit the real model in Studio, use a deliberate palette, install motion under that model, and fix its organicQuality issues. report_done requires fresh passing evidence for every registered organic model, even after a handoff. This is not selected or enforced from animal/tree names; see organicBuildRules for the stricter per-organic-model evidence contract.'
                'BLENDER-MESH-BAU (7.4.0, freiwilliger zweiter Weg fuer anspruchsvolle Modelle): build_mesh_model laesst Blender im Hintergrund ein OBJ bauen, die Bridge MISST es (Dreiecke, Groesse in Studs) und legt viereckige MeshPart-Platzhalter in den Place. Danach laedt der NUTZER die Datei in Roblox hoch und traegt die Mesh-Id im Bridge-Fenster "Mesh-Uploads" ein; mesh_apply_asset setzt die Geometrie automatisch ein. Roblox bietet keinen automatischen Mesh-Upload - dieser Zwischenschritt ist keine Unfertigkeit, sondern der offizielle Weg. Solange Platzhalter stehen, ist es KEIN fertiges Modell: report_done antwortet MESH_UPLOAD_PENDING. Der Polygon-Weg (build_polygon_model) bleibt der Standard fuer Entwurf, Iteration und einfache Formen; Mesh lohnt sich fuer glatte/organische Formen, viele Details und Teilzahl. Siehe meshBuildRules.'
            )
            worldEngineRules = @{
                title = 'World Engine 1.0 - the world is a place with rules, not a pile of parts'
                workflow = 'site_survey (measure ground, water, clearance, existing parts) -> world_style (palette, materials, density, weathering, seed) -> style_lock -> build with prop_place / build_assembly / build_polygon_model / refine -> model_audit + world_audit. Never place a large build without the survey, never call it finished while model_audit reports placeholders.'
                determinism = 'EVERY variation comes from the style seed (prop_place, refine, variation). The same seed must rebuild the same world - math.random is forbidden for anything a user could see twice.'
                styleLock = 'A style lock turns measurement on: world_audit then reports styleCompliance, colour distance and off-style parts. Building without a style is allowed but measurably worse - that is the honest contract, not a hidden penalty.'
                light = 'Light comes from world_glow (one engine-built light per part, clamped brightness/range). Never fake glow with stacked transparent spheres or dozens of flickering lights, and never leave a night scene without Atmosphere/Sky.'
                phases = 'model_audit phases: blockout (placeholders/blockouts exist) -> modelled (clean geometry, no mesh/union yet) -> refined (ArenaDetail parts exist) -> polished (details + light + atmosphere). report_done is only honest in refined/polished; blockout means handoff or keep working.'
                props = 'prop_save stores a selection under workspace.ArenaProps; prop_place clones it with deterministic variation and ground snap. Prefer saved props over rebuilding the same tree ten times by hand.'
            }
            toolboxRules = @{
                title = 'Toolbox Engine 1.0 (Version 7.1.4) - procedural first, catalog last, never in parallel'
                default = 'BUILD PROCEDURALLY BY DEFAULT. For every nontrivial user-visible 3D build, prefer build_polygon_model for the distinctive main silhouette in any category, and use build_assembly/native Parts for repeated or supporting geometry. Deliver secondary structure, purposeful details and a coherent palette; do not start with a primitive-only placeholder or search_assets/insert_asset unless the user requests an asset or approves a fallback. Keep simple tasks simple. For any organic model, explicitly set organic=true and install enabled motion under that model; fresh per-model geometry, palette and motion evidence is required before report_done.'
                beforeUsingTheCatalog = 'If a procedural shape is genuinely not realistic enough or technically out of reach, say so and OFFER a limited, transparent fallback FIRST. Let the user decide. Do not start catalog calls on your own initiative.'
                hardLimits = 'Per place the bridge allows at most 2 catalog requests at a time and EXACTLY ONE active asset import. Anything beyond that answers immediately with TOOLBOX_BUSY or TOOLBOX_IMPORT_IN_FLIGHT. Never run asset searches in parallel, never poll in a loop, and never retry automatically after a timeout.'
                timeouts = 'Every catalog request has a hard time limit (12 s, 8 s for the pre-insert validation) and a 25 s budget per tool call. A failure is FINAL and typed: CATALOG_TIMEOUT or CATALOG_UNAVAILABLE. Say "Katalog nicht verfuegbar" to the user and continue procedurally instead of retrying.'
                insertIsNotCancellable = 'InsertService:LoadAsset is a native yielding Roblox call that CANNOT be aborted. If an import hangs you get TOOLBOX_IMPORT_UNCONFIRMED and then TOOLBOX_IMPORT_WEDGED; imports stay locked for that place. Do NOT retry - ask the user to close Roblox Studio completely and reopen the place, check for a half-inserted model, then build procedurally.'
                idempotency = 'Repeating the same insert_asset (same assetId/parentRef/name) inside 120 s returns the stored result with idempotentReplay=true and inserts NOTHING a second time. Pass a fresh requestId or allowDuplicate=true when a second copy is really wanted.'
            }
            polygonEngineRules = @{
                title = 'Polygon Engine 2.0 - canonical WedgePart rule (prevents 90-degree rotation errors and seam gaps forever)'
                whenThisApplies = 'build_polygon_model already implements this correctly (longest-edge base, side-corrected inward skin offset, retry/fallback triangulation, vertex welding) - always STRONGLY prefer it for modelling. Only read on if you are writing bespoke geometry directly with run_lua/Instance.new("WedgePart") because the task needs logic the tool does not cover.'
                axisRule = 'The slanted face of a WedgePart is NEVER in its local X plane. Local X = thickness / face normal. Local Y = height / the axis orthogonal to the base edge. Local Z = the base-edge direction (dir, or -dir for the mirrored half). Build every WedgePart CFrame as CFrame.fromMatrix(position, normal, up, dir) - swapping which vector goes into which slot is exactly what produces 90-degree rotation errors.'
                seamRule = 'Seam gaps come from placing the wedge thickness symmetrically around the supplied skin points. Instead, treat the given triangle points as the exact outer skin and shift the whole wedge inward by half the thickness along -normal (skinOffset = -normal * thickness * 0.5) before building the CFrame, so neighbouring faces overlap cleanly on the inside instead of leaving visible grooves.'
                referenceLua = @'
-- Canonical zero-error formula for hand-written run_lua triangle/wedge builders.
-- applyProps(part, props, parent) is your own helper that sets Color/Material/
-- Anchored/CanCollide/Parent etc. - keep using whatever the rest of your script uses.
local function drawSeamlessTriangle(p1, p2, p3, parent, props)
    -- 1. Re-label so the LONGEST edge becomes the base (p2 -> p3); this
    --    guarantees the altitude foot from p1 lands inside that edge.
    local ab, ac, bc = (p2-p1).Magnitude, (p3-p1).Magnitude, (p3-p2).Magnitude
    if ab >= ac and ab >= bc then p1, p2, p3 = p3, p1, p2
    elseif ac >= ab and ac >= bc then p1, p2, p3 = p2, p3, p1 end

    local baseVec = p3 - p2
    local baseLen = baseVec.Magnitude
    if baseLen < 0.001 then return end
    local dir = baseVec.Unit

    -- 2. Face normal and the altitude foot point (pMid) on the base edge.
    local normal = (p2 - p1):Cross(p3 - p1).Unit
    local proj = (p1 - p2):Dot(dir)
    local pMid = p2 + dir * proj
    local height = (p1 - pMid).Magnitude
    local up = (p1 - pMid).Unit

    local len1 = proj
    local len2 = baseLen - proj
    local thickness = props.Thickness or 0.2

    -- 3. Side-corrected skin placement: shift the wedge thickness INWARD so
    --    the given points stay the exact outer skin and neighbours seal.
    local skinOffset = -normal * (thickness * 0.5)

    -- Wedge 1 (pMid -> p2): local X=normal (thickness), Y=up (height), Z=-dir (base).
    if len1 > 0.01 and height > 0.01 then
        local w1 = Instance.new("WedgePart")
        w1.Size = Vector3.new(thickness, height, len1)
        w1.CFrame = CFrame.fromMatrix((pMid + p2)/2 + up * (height/2) + skinOffset, normal, up, -dir)
        applyProps(w1, props, parent)
    end

    -- Wedge 2 (pMid -> p3): mirrored, Z=dir.
    if len2 > 0.01 and height > 0.01 then
        local w2 = Instance.new("WedgePart")
        w2.Size = Vector3.new(thickness, height, len2)
        w2.CFrame = CFrame.fromMatrix((pMid + p3)/2 + up * (height/2) + skinOffset, -normal, up, dir)
        applyProps(w2, props, parent)
    end
end
'@
            }
            modelBuildRules = @{
                title = 'Model Build Engine 1.1 - universal polygon workflow for every nontrivial 3D category'
                whenThisApplies = 'Every task that creates or materially remodels visible 3D geometry, regardless of subject, model name or whether it is organic. This is a global build preference, not an animal/tree-only rule.'
                default = 'For every nontrivial custom model, aim materially beyond a first-pass primitive sketch. Design a readable primary silhouette, add secondary forms that explain function and proportion, then add restrained tertiary details, trim, joints and surface structure. Use explicit, coherent color/material roles and correct attachment/placement. More parts without design purpose is not more quality.'
                polygonPreference = 'For EVERY nontrivial custom visible 3D model in ANY category—not only creatures—the first model-creation/build call MUST be build_polygon_model and must include its complete distinctive main silhouette, not merely one front plate. Prefer it for any freeform, tapered, curved, angled, irregular or hero surface: characters, props, furniture, architecture, vehicles, weapons, machinery, landmarks, terrain and set pieces. Organize the call into named submodels and polygons with per-submodel color/material roles; use volumes for changing cross-sections. Use autoWeld by default and mainWelds only for intended joins/animation. This is not a requirement for truly simple standard Parts or an explicit primitive/blockout request. The builder is preferred, not mandatory for every simple Part.'
                polygonDecision = 'Choose the geometry representation by shape, not by subject: polygons = individual planar faces/panels; submodels = named components and material/color groups containing faces; volumes = closed lofts for a shape whose cross-section changes along a centerline; build_assembly = repeated modules; native Parts = genuinely standard supports, pivots and accents. A polygon is one skin, not a solid: construct front/back/sides/ends or use closeOpenings for unmatched loops. A single front silhouette plus thickness is still a plate.'
                polygonInputContract = 'Structured form: build_polygon_model { modelName, origin={x,y,z}, rotation={x,y,z in degrees}, scale, style={...}, submodels=[{name,style,polygons=[{name,points=[{x,y,z},...],style?}]}], volumes=[{name,role,sides=6..16,sections=[{center,heightRadius,depthRadius},...]}], closeOpenings, autoWeld, mainWelds, maxWedges }. Points are actual local geometry. Each face must have >=3 ordered distinct coplanar vertices, no self-crossing/duplicate/collinear runs. origin/rotation/scale transform the model; Position/Size/CFrame/Orientation inside polygon properties are ignored.'
                polygonWorkflow = '1 inspect Place/selection and choose a stable frame, dimensions, palette/materials. 2 Plan the full silhouette as named large forms and surfaces before writing. 3 Make one structured build_polygon_model call for the principal model; share exact coordinates on adjacent face edges. 4 Add repeated modules via build_assembly and deliberate details/refine; do not replace the hero silhouette with blocks. 5 Read the returned model id, result.incomplete, facesSkipped, skipped, fallbackFaces, triangles, wedges, warnings and geometry. Do NOT accept ok=true as proof when faces are skipped. Fix bad named faces/point loops and rebuild. 6 Run model_audit on the returned model, plus world_audit for scenes; fix findings before report_done. The core build_polygon_model docs include a complete closed LowPolyHouse example.'
                polygonPatterns = 'Facade/roof/shield/panel = explicit planar polygons; closed box/building/housing = all outer faces sharing exact edge coordinates; tapered curved hull/handle/shaft/column/branch = volume stations with heightRadius+depthRadius; arches/frames can be assembled from individually valid faces plus repeated supports; rails/windows/spokes/ribs = build_assembly. Use closeOpenings=true only as an auto-cap safety net, not as a substitute for planning the shell. For cross-submodel motion, set parts unanchored and use mainWelds; inside each submodel AutoWeld is already on.'
                polygonBudget = 'Each n-vertex face usually produces n-2 triangles and two WedgeParts per triangle. Budget about 2*(n-2) wedges per polygon plus volume/cap faces. The default maxWedges is 4000 and the hard maximum is 10000; simplify/split into coherent submodels if necessary. A normal OK response may carry incomplete=true or warnings: require facesSkipped=0 and skipped=[] and inspect fallbackFaces.'
                polygonTemplate = 'build_polygon_model { modelName="<name>", grade="lowpoly|detailed|simple|blockout", origin={x=0,y=0,z=0}, rotation={x=0,y=0,z=0}, scale=1, style={thickness=0.04,anchored=true,canCollide=false}, submodels=[{name="Shell",style={color="#...",material="SmoothPlastic"},polygons=[{name="Front",points=[...]},{name="Back",points=[...]},{name="SideA",points=[...]},{name="SideB",points=[...]},{name="Top",points=[...]},{name="Bottom",points=[...]}]}], autoWeld=true, maxWedges=4000 }. This is a closed-shell skeleton: replace each placeholder with valid ordered planar coordinates and expand to the complete silhouette; the LowPolyHouse tool example is a fully specified call.'
                complementaryTools = 'Use build_assembly for repeated structural or modular pieces (frames, stairs, rails, facades, ribs, supports) and combine it with a polygon-built hero silhouette when both are useful. Use native Parts for genuinely simple standard shapes, structural supports, joints, pivots and small accents; bulk_create/grid/clone are for repetition, not for replacing the distinctive centerpiece with blocks.'
                finishBar = 'A nontrivial standalone asset is not complete as one box/cylinder or a primitive-only placeholder: complete the main form, its supporting components, visual details, coherent palette/materials, welds/collision and grounding as relevant. For scenes, add purposeful variation, depth, readable pathways and consistent style. Low-poly is a style, not permission to stop at a primitive blockout.'
                exceptions = 'Keep inherently simple tasks simple and follow explicit user requests for primitives, blockouts, low part counts or a deliberately plain style. Scale scope to time/tool/part limits; reduce how many assets are built instead of degrading the finish of each delivered asset.'
                workflow = 'inspect/select/measure -> choose art direction or world_style -> follow polygonWorkflow and build the complete main custom silhouette with build_polygon_model (first model-build call for nontrivial custom 3D) -> assembly/native support geometry -> detail/refine -> verify the returned face/wedge diagnostics -> model_audit (and world_audit for scenes) -> fix measured issues -> report_done. Build directly in the target Place; a generated source file or later unsupported quality claim is not a model.'
                motion = 'Add animation only when the task requests motion or the object is inherently living/moving. For organic models, explicitly use organic=true so per-model geometry, palette, enabled-motion and fresh-audit evidence is enforced; see organicBuildRules.'
            }
            meshBuildRules = @{
                title = 'Mesh-Build Engine 1.0 (Version 7.4.1) - Blender im Hintergrund, Nutzer laedt hoch, Bridge setzt ein'
                whenThisApplies = 'Freiwilliger ZWEITER Weg neben build_polygon_model. Sinnvoll, wenn eine Form mit Dreiecken/Wedges nicht gut wird (glatte oder organische Oberflaechen, viele Details, hohe Teilzahl) oder wenn das Modell im Place nur EIN Bauteil statt tausender Wedges sein soll. Fuer Entwurf, Iteration und fuer alles, was im Studio per Teil editierbar bleiben muss, bleibt build_polygon_model die erste Wahl.'
                workflow = '1 blender_status lesen (Bereitschaft + Zustand). 2 build_mesh_model mit einem Blender-Skript je Slot aufrufen -> sofort jobId (Blender laeuft im Hintergrund, KEIN synchrones Warten). 3 mesh_status pollen, bis state measured ist; die Antwort nennt je Slot Dreiecke + Groesse in Studs. 4 Die Bridge legt die viereckigen MeshPart-Platzhalter selbst an. 5 Der NUTZER laedt die OBJ-Datei(en) hoch und traegt die Mesh-Id(s) im Bridge-Fenster "Mesh-Uploads" ein (oder nennt sie im Chat, dann mesh_apply_asset aufrufen). 6 mesh_status zeigt applied. 7 Erst dann model_audit + report_done.'
                scriptContract = 'Ein Slot = ein Blender-Skript = EIN MeshPart. Das Skript ist normaler Code mit bpy (bmesh, math, mathutils, random erlaubt) und baut NUR Geometrie: 1 Blender-Einheit = 1 Stud, Y ist oben, die bbox-Mitte am Ursprung setzt der Runner automatisch, Modifier werden beim Export angewandt. Der Runner der Bridge macht Szene, Export, Zentrierung und Messung - bpy.ops.wm.*, Export, Datei-, Netzwerk- und Systemzugriff sind im Skript gesperrt (die Bridge lehnt solche Skripte vor dem Start ab).'
                slots = 'Mehrere Slots statt eines Riesenmeshes: ein MeshPart traegt EINE Farbe/Material (Roblox uebernimmt keine Blender-Materialien), und ein einzelnes Mesh laesst sich nicht animieren. Fuer Kreaturen, Fahrzeuge und Maschinen also je bewegliches Glied ein Slot und die Gelenke wie gewohnt mit Welds/Motor6D verbinden. Farbe und Material setzt Roblox ueber die Slot-Angaben color/material.'
                budget = 'Roblox nimmt pro Mesh hoechstens rund 10.000 Dreiecke an (Datei max. 20 MB). Die Bridge MISST die OBJ-Datei selbst und lehnt einen Slot ueber der Grenze mit state rejected ab - dann weniger Unterteilungen, Decimate/Remesh oder kleinere Slots bauen. Ziel: unter 8.000 Dreiecken je Slot.'
                userStep = 'Der Upload ist ein MENSCHEN-Schritt und nicht automatisierbar (keine Roblox-API fuer Mesh-Uploads). Immer ehrlich sagen: Datei im Bridge-Ordner oeffnen, in Studio per 3D-Importer/Drag-und-Drop oder im Creator Dashboard hochladen, Mesh-Id im Bridge-Fenster eintragen. NICHT behaupten, das Modell sei fertig, solange Platzhalter stehen.'
                evidence = 'Beweis statt Behauptung: Dreieckszahl, Groesse und Dateigroesse kommen aus der Messung der Bridge und stehen in mesh_status und im Bau-Register. Nach dem Einsetzen meldet mesh_apply_asset je Slot die zurueckgelesene MeshId. Ein Mesh ist im Place messtechnisch eine Blackbox - die OBJ-Messung plus der Sichttest des Nutzers sind der Beleg.'
                failure = 'Schlaegt Blender fehl (nicht installiert, Faehigkeitsprobe rot, Exit ungleich 0, Zeitlimit), sagt die Bridge das mit Code und Protokollzeile; dann bleibt der Polygon-Weg. Nie ein leeres oder unbemessenes Modell als fertig melden.'
            }
            organicBuildRules = @{
                title = 'Organic Build Engine 1.1 (Version 7.4.1) - typed creature volumes, physical face, bilateral anatomy, measured before done'
                whenThisApplies = 'For any model intentionally built as organic (character, creature, plant, tree, prop or other organic free-form shape), this is a hard sequence independent of its name: the FIRST write targeting that model is build_polygon_model { organic=true, organicKind=... } with an explicit contrasting palette. For organicKind=creature the same first build must create closed role=body and role=head loft volumes; a long flat side-profile wedge is not a body or head volume. Use organicTraits=["wings"] when wings are intended and build role=wing_left/wing_right. Face features are physical 3D geometry, never Decal/Texture/GUI substitutes. Do not start with run_lua, build_assembly, loose primitives, or an external generator file. Then install an enabled motion Script under that same model, run model_audit on every returned organic model after the final edit, and fix every organicQuality issue. report_done is rejected with ORGANIC_AUDIT_REQUIRED/DETAIL_REQUIRED until every registered model passes.'
                theOneIdea = 'For an organic model, the first write is build_polygon_model { organic=true, organicKind=... }. A creature gets real closed lofts for body and head (at least 4/3 stations, at least 8 sides) plus physical eyes and pupils; winged creatures get a mirrored, torso-attached wing pair. No side-view wedge, face sticker, or unmeasured claim can pass. Then add joints/details, install the enabled motion Script beneath the model, and audit the exact model.'
                forbidden = @(
                    'FORBIDDEN - BYPASSING THE POLYGON BUILDER: the first write targeting any explicitly organic model must be build_polygon_model { organic=true, organicKind=... }. A build_assembly/run_lua/create_instance organic model first, a local generator script, or an unmarked polygon call is rejected with ORGANIC_POLYGON_REQUIRED; this gate is controlled by organic=true, not by the model name.',
                    'FORBIDDEN - FLAT CREATURE SILHOUETTE: a body/head made from one long side-view wedge or an unclosed sheet is not a volume. Use body/head loft roles with multiple cross-sections, end caps, and measurable depth.',
                    'FORBIDDEN - FACE STICKER: Decal, Texture, SurfaceGui or BillboardGui on the head/face cannot replace physical bilateral eye and pupil geometry; model_audit reports FACE_IMAGE_OVERLAY/EYES_NOT_3D/PUPILS_NOT_3D.',
                    'FORBIDDEN - ONE-SIDED OR HIDDEN WINGS: if wings are intended, declare organicTraits=["wings"] and provide role=wing_left / role=wing_right on opposite sides with bounds overlapping the torso.',
                    'FORBIDDEN - BALL ANIMAL: an animal assembled only from Ball parts (body ball + head ball + four leg balls + tail ball). That is the first-minute draft the user can build himself. model_audit reports it as primitiveOnly with primitiveGroups and report_done refuses to accept it.',
                    'FORBIDDEN - CYLINDER TREE: one CylinderPart as trunk plus one Ball as crown. A real trunk is a tapered polygon column with a root flare and 3-6 real branches; a real crown is 3+ irregular polygon clumps with different sizes, colours and rotation, never a single sphere.',
                    'FORBIDDEN - UNTAPERED LIMBS: one stretched block per leg. Every limb has an upper and a lower segment that taper toward the paw/hoof, plus a shoulder/hip connection that overlaps the torso so no gap and no floating part remains.',
                    'FORBIDDEN - ONE SINGLE ROTATION AS ANIMATION: a model that spins or a limb that swings on one constant loop is not animated, it is a turntable.',
                    'FORBIDDEN - FORGOTTEN COLOUR OR MOTION: every organic model has an explicit contrasting palette and an enabled motion Script under its model; a generated file elsewhere or source-only animation does not count.',
