                ASSET_NOT_FOUND = 'The id does not exist or is not public (404). Do not use it.'
                CATALOG_UNAVAILABLE = 'The Roblox catalog is not reachable right now. Say clearly to the user: "Katalog nicht verfügbar" - then build procedurally. Do not guess ids, do not stay silent. Retry later with catalog_status.'
                CATALOG_TIMEOUT = 'The catalog did not answer inside the bridge hard time limit and the request was ABORTED (nothing keeps running). Do NOT retry in a loop - say so and build procedurally.'
                TOOLBOX_BUSY = 'This place already has the maximum number of catalog requests in flight. Run toolbox calls strictly one after another; never start parallel asset searches.'
                TOOLBOX_IMPORT_IN_FLIGHT = 'An asset import is already running for this place. Only ONE import at a time. Wait for its answer instead of retrying.'
                TOOLBOX_IMPORT_WEDGED = 'A native InsertService:LoadAsset is stuck. Roblox cannot abort it, so imports are LOCKED for this place. Ask the user to restart Roblox Studio completely, do not retry, and build the model procedurally instead.'
                TOOLBOX_IMPORT_UNCONFIRMED = 'The import did not answer before the HTTP deadline and cannot be cancelled. Further imports are blocked. Never retry - a retry can insert the model twice.'
                CATALOG_TYPE_NOT_SUPPORTED = 'That asset type cannot be searched in the catalog (list of supported types included).'
                JOB_NOT_FOUND = 'Unknown jobId (it may have been removed after job_result).'
                JOB_RUNNING = 'The job is not finished yet - poll job_status and fetch the result later.'
                PROP_NOT_FOUND = 'No saved prop with that name - prop_list shows what exists, prop_save stores the selection.'
                PROP_EXISTS = 'A saved prop with that name exists. Pass overwrite=true or choose another name.'
                NO_WORLD_STYLE = 'No world style is active - call world_style first, then style_lock. Building without a style is allowed but world_audit cannot measure compliance.'
                CONTEXT_UNAVAILABLE = 'The client context is gone since 7.0.0 (no playtest, no client agent). run_lua always runs on the server side.'
                TEXTURE_ASSET_MISSING = 'Warning, not an error: no real texture id was given, so the engine uses its gradient fallback and says so.'
                RADIAL_ASSET_MISSING = 'Warning, not an error: no image id for the ring was given, so the engine builds the ring procedurally and says so.'
                GEOMETRY_NOT_READY = 'Warning: new geometry was not immediately raycastable; verify_measurable waited for it (see geometry in the result).'
            }
            typedValues = 'Complex values are typed JSON: {"type":"Vector3","x":0,"y":5,"z":0}, {"type":"Color3","rgb":[255,0,0]}, {"type":"CFrame","position":{...},"orientation":{...}}, {"type":"EnumItem","enum":"Material","name":"Neon"}. Short forms work too: [0,5,0] for a Vector3, "Neon" for an enum, "#FF0000" for a colour, [255,0,0] for a Color3.'
            workflows = @{
                buildSomething = @('Understand as much context as the task needs', 'Choose build_assembly / build_polygon_model / bulk_create / unions / regular tools', 'Optionally verify or select the result')
                editAScript = @('search className=Script', 'get_script (note the hash)', 'patch_script with a unique snippet', 'compile_check the result', 'set/patch with expectHash', 'get_output / get_errors')
                testASimulation = @('sim_start is disabled; do not call it (the former Studio Run path exits Edit mode)', 'Use compile_check for syntax, run_lua for one-off edit-place logic, and read tools for state', 'sim_status can inspect an existing session; sim_stop only ends an existing bridge-owned session', 'For live physics/server-script behavior, the user must test manually in Roblox Studio until a supported true Edit-mode API exists')
                manyObjects = @('build_assembly for grouped linear/radial repetition', 'bulk_create or clone_instance for simple arrays', 'batch when combining independent operations')
                longBuild = @('fill_region with asJob=true (or start_job)', 'job_status (progress + partsPerSecond)', 'job_result when done (geometry.ready included)', 'verify_measurable on a sample if in doubt')
                rotationCorrect = @('coordinate_guide (once per session)', 'describe_orientation on the part', 'point_at (axis="top" for cylinder length) or rotate_around with measured axes', 'describe_orientation again to verify')
                assets = @('catalog_status (is it up?)', 'search_assets (type, keyword) - cached locally', 'validate_asset if unsure', 'apply_asset (auto-validated) / insert_asset', 'if CATALOG_UNAVAILABLE: say so and build procedurally')
            }
        }
    }

    # ==================================================================
    # /api/docs: Doku pro Tool, pro Kategorie oder komplett.
    # ==================================================================
    function Get-DocsResponse([string]$tool, [string]$category, [string]$full) {
        $all = Get-ToolDocs
        if (-not [string]::IsNullOrWhiteSpace($tool)) {
            $found = @()
            foreach ($d in $all) { if ($d.name -eq $tool.ToLowerInvariant()) { $found += $d } }
            if ($found.Count -eq 1) {
                return @{ ok = $true; docsVersion = [string]$Shared.DocsVersion; tool = $found[0] }
            }
            $names = @()
            foreach ($d in $all) { $names += $d.name }
            return @{ ok = $false; code = 'REF_NOT_FOUND'; error = "Unknown tool '$tool'."; knownTools = $names }
        }
        if (-not [string]::IsNullOrWhiteSpace($category)) {
            $found = @()
            foreach ($d in $all) { if ($d.category -eq $category.ToLowerInvariant()) { $found += $d } }
            if ($found.Count -eq 0) {
                $cats = @{}
                foreach ($d in $all) { $cats[[string]$d.category] = 1 }
                return @{ ok = $false; code = 'REF_NOT_FOUND'; error = "Unknown category '$category'."; knownCategories = @($cats.Keys) }
            }
            return @{ ok = $true; docsVersion = [string]$Shared.DocsVersion; category = $category; count = $found.Count; tools = $found }
        }
        $categories = @{}
        foreach ($d in $all) { $categories[[string]$d.category] = [int]$categories[[string]$d.category] + 1 }
        $result = @{
            ok = $true
            docsVersion = [string]$Shared.DocsVersion
            toolCount = $all.Count
            categories = $categories
            tools = $all
        }
        $guides = Get-BridgeGuides
        foreach ($key in $guides.Keys) { $result[[string]$key] = $guides[$key] }
        return $result
    }

    # ==================================================================
    # START-DOKU: wird automatisch mit der ERSTEN Tool-Antwort der Sitzung
    # ausgeliefert (_sessionStart) - die KI bekommt also ohne Extra-Call
    # ALLE Informationen (Doku pro Tool, Regeln, Fehlercodes, Workflows).
    # ==================================================================
    function Get-SessionStartPackage {
        $out = @{
            docsVersion = [string]$Shared.DocsVersion
            welcome = 'Welcome. This first response includes the available capabilities and reference documentation. Use whatever subset helps the current task; details remain available through GET /api/docs or get_docs.'
            quickStart = @(
                'Inspect the Place when context is needed.',
                'For nontrivial custom 3D, follow modelBuildRules.polygonWorkflow and its build_polygon_model example; that workflow applies to all categories, not only creatures.',
                'Choose dedicated tools, master build tools, assets, script editing or run_lua according to the task.',
                'Use get_docs { tool: "..." } whenever a parameter needs clarification.'
            )
        }
        $guides = Get-BridgeGuides
        foreach ($key in $guides.Keys) { $out[[string]$key] = $guides[$key] }
        # Version 3.8: Bridge-Einstellungen prominent unterbringen
        $startSim = $false
        $startNotify = $false
        try { $startSim = [bool]$Shared.BridgeSettings.simAllowed } catch {}
        try { $startNotify = [bool]$Shared.BridgeSettings.notifyOnDone } catch {}
        $out.simAllowed = $startSim
        $out.notifyWhenDone = $startNotify
        # Version 7.0.0: Fortschrittsvertrag + Qualitaetsvertrag gehoeren in
        # JEDE Sitzung - kurz, hart, maschinenlesbar.
        $out.progressContract = @{
            field = 'Every API call carries progress = { percent = 43, message = "kurze, konkrete Nachricht" } on the same level as token/targetPlace/tool. Inside args works too: the bridge pulls it out and NEVER forwards it to the plugin.'
            missing = 'Missing percent is NEVER an error and never blocks building - but since 7.2.0 the user then sees NO bar and NO percentage at all (only a text line with your message and your last tool), and every response carries progressWarning PERCENT_MISSING until you send a real number. Send percent: it is the only thing that makes your progress visible.'
            neverReset = 'A call with only a message no longer resets the bar to 0. percent is written exclusively when you actually send a number, so reported progress survives message-only calls.'
            last = 'The last call of a completed task is report_done; it fills in 100 itself and marks "Automatisch gesetzt".'
            display = 'The bridge shows percent + your message in the place row (blue = working, green = done only after report_done, grey = waiting/no feedback for 60 s, red = error). An open Studio command no longer replaces the bar - it is additional tooltip information. Everything is logged in the Arena history, in progress-diagnose.txt and as PROGRESS stations in runtime.log.'
            rewind = 'Rewinds are allowed and stay visible; the bridge never invents a higher percentage than you reported.'
        }
        $out.qualityContract = @(
            'No turn has to end with "done". It ends with report_done OR with a handoff - both are complete finishes.',
            'Classify first: single object, scene, or full game. The class decides the minimum scope, never an excuse for primitive-only first drafts.',
            'GLOBAL 3D BUILD BAR, independent of names/examples: first follow modelBuildRules.polygonDecision, polygonInputContract and polygonWorkflow. For every nontrivial custom 3D model, the first model-building call is build_polygon_model and it builds the complete distinctive main silhouette, in ANY category, not just a creature. Then add secondary structure, tertiary details, purposeful color/material design and correct joins/placement; pair with build_assembly for repeated modules and Parts for simple supports/details. Read the worked LowPolyHouse example in build_polygon_model docs and inspect facesSkipped/skipped before claiming completion.',
            'Do not force polygons onto a truly simple object, repeated standard geometry or an explicit primitive/low-poly request. Low-poly still means intentional silhouette and finish. Do not call a blockout, placeholder or one-box/one-cylinder stand-in complete unless that is what the user asked for.',
            'Single objects and scenes must be completed in this session: inspect/measure, build with the best-fit Bridge tools, refine, model_audit and world_audit where applicable, then fix the reported issues.',
            'Only a full game gets stages: deliver stage 1 completely, then hand off; never hand off in the middle of a stage.',
            'Never claim "done" while placeholders, blockouts or open audit points exist.',
            'Good is the standard, not a luxury. If time/tool budget is short, reduce scope or number of assets - not the geometry quality of what is delivered.'
        )
        $handoffJson = ''
        if ($Shared.Handoffs.TryGetValue([string]$sessionId, [ref]$handoffJson) -and -not [string]::IsNullOrWhiteSpace($handoffJson)) {
            $out.previousHandoff = $handoffJson | ConvertFrom-Json
            $out.previousHandoffNote = 'A handoff from an earlier session exists for this place. Continue from it instead of starting over - it is already included here, nothing needs to be copied.'
        }
        if (-not $startSim) {
            $out.simNotice = 'IMPORTANT: sim_start is intentionally disabled because the former Studio Run path exits Edit mode (EditModeActive=false), and the documented Studio API has no supported true Edit-mode physics/script path. Do not retry it; continue building and auditing in edit mode.'
        }
        if ($startNotify) {
            $out.finishNotification = 'FINISH NOTIFICATION IS ON: when ALL your changes are complete and you are about to end your answer, call report_done { title, message } as your VERY LAST tool call - the user receives a Windows notification with your German message (e.g. title="✅ Arena hat den Bug behoben!", message="Der Fehler ist weg – komm und teste das Spiel!"). After that call: no more tools, no more changes - end your answer immediately.'
        }
        # Version 7.1.3: NUTZLAST-BUDGET DES SESSIONSTARTS.
        # Bis 7.1.2 lieferte die ERSTE Antwort die vollstaendige Doku ALLER
        # Werkzeuge mit (129 Eintraege mit Parametern, Beispielen und
        # Fehlerfaellen) - zusammen mit den Regelbloecken weit ueber 120 KB in
        # einem einzigen Paket. Solche Riesenpakete sind ein bekannter Ausloeser
        # fuer abgelehnte KI-Anfragen ("The AI service rejected this request").
        # Jetzt: Kernwerkzeuge voll, alle uebrigen als Index (Name, Kategorie,
        # Kurztext) mit dem ausdruecklichen Hinweis, die Parameter mit
        # get_docs { tool = "..." } zu holen. Zusaetzlich eine harte Obergrenze:
        # waechst das Paket trotzdem darueber, wird auch der Kern nur noch als
        # Index verschickt - der Sessionstart kann also nie wieder unbegrenzt
        # wachsen. Die Antwort nennt packageBytes, budgetBytes und docsPolicy.
        $coreToolNames = @(
            'get_place_info','get_tree','get_instance','get_properties','get_selection','describe_scene','resolve_ref','probe_world',
            'raycast','ground_height','create_instance','bulk_create','set_property','set_properties','move_instance','clone_instance',
            'delete_instance','build_polygon_model','build_assembly','build_interface','build_surface','ui_capabilities','ui_skin','ui_audit',
            'run_lua','insert_script','set_script_source','compile_check','model_audit','world_audit','site_survey','world_style','style_lock',
            'refine','prop_place','prop_save','report_done','get_docs','get_chunk','list_tools','bridge_status','start_job','job_status',
            'job_result','get_output','get_errors','wait'
        )
        $coreDocs = New-Object System.Collections.Generic.List[object]
        $indexDocs = New-Object System.Collections.Generic.List[object]
        foreach ($doc in (Get-ToolDocs)) {
            if ($coreToolNames -contains [string]$doc.name) {
                $coreDocs.Add($doc)
            } else {
                $indexDocs.Add(@{ name = [string]$doc.name; category = [string]$doc.category; summary = [string]$doc.summary })
            }
        }
        $out.tools = $coreDocs.ToArray()
        $out.toolsIndex = $indexDocs.ToArray()
        $out.toolsIndexNote = ('The tool index lists ' + [string]$indexDocs.Count + ' further tools with name, category and summary only. Before using one of them, fetch its exact parameters, defaults, return value and examples with get_docs { tool = "<name>" } (or GET /api/docs?tool=<name>) - the full documentation is always complete there. The core building, audit, read and session tools above are already documented in full.')
        $packageBudget = 300000
        try { $packageBudget = [int]$Shared.SessionPayloadHardBudgetBytes } catch {}
        if ($packageBudget -le 0) { $packageBudget = 300000 }
        $out.budgetBytes = $packageBudget
        $out.packageBytes = 0
        $out.docsPolicy = 'core-full'
        $measuredBytes = 0
        try { $measuredBytes = ($out | ConvertTo-Json -Depth 12 -Compress).Length } catch { $measuredBytes = 0 }
        if ($measuredBytes -gt $packageBudget) {
            # Notbremse: selbst der Kern passt nicht mehr ins Budget. Dann
            # bleibt nur der Index - nie ein unbegrenztes Paket.
            $allIndex = New-Object System.Collections.Generic.List[object]
            foreach ($doc in (Get-ToolDocs)) {
                $allIndex.Add(@{ name = [string]$doc.name; category = [string]$doc.category; summary = [string]$doc.summary })
            }
            $out.tools = @()
            $out.toolsIndex = $allIndex.ToArray()
            $out.docsPolicy = 'index-only'
            $out.toolsIndexNote = ('Payload budget exceeded - the full per-tool documentation was left out completely (' + [string]$measuredBytes + ' bytes before this cut). Fetch what you need with get_docs { tool = "<name>" } or GET /api/docs?tool=<name>.')
            $measuredBytes = 0
            try { $measuredBytes = ($out | ConvertTo-Json -Depth 12 -Compress).Length } catch { $measuredBytes = 0 }
        }
        $out.packageBytes = [int]$measuredBytes
        return $out
    }

    # ------------------------------------------------------------------
    # MANIFEST: die Bedienungsanleitung für die KI
    # ------------------------------------------------------------------
    function Get-Manifest {
        $docs = Get-ToolDocs
        $toolIndex = New-Object System.Collections.Generic.List[object]
        foreach ($d in $docs) {
            $toolIndex.Add(@{ name = $d.name; category = $d.category; description = $d.summary })
        }
        $guides = Get-BridgeGuides
        $manifestSim = $false
        $manifestNotify = $false
        try { $manifestSim = [bool]$Shared.BridgeSettings.simAllowed } catch {}
        try { $manifestNotify = [bool]$Shared.BridgeSettings.notifyOnDone } catch {}
        $manifest = @{
            name = 'Arena Roblox Studio Bridge'
            version = '7.4.1'
            progress = 'Every call carries progress = { percent, message } on the same level as token/targetPlace/tool (or in args; the bridge strips it there). Missing percent = 0, never an error. The last call of a finished task is report_done (100, filled in automatically).'
            simulation = 'sim_start is intentionally disabled: the former implementation used official Studio Run and exited Edit mode (EditModeActive=false). The documented Studio API has no supported true Edit-mode physics/script path. sim_status stays available; sim_stop remains for an existing bridge-owned session. This is distinct from a user Play/F5 test.'
            handoff = 'handoff { scope = "game", ... } is ONLY for a complete game or a combination of systems. Everything else must be finished in this session (HANDOFF_NOT_ALLOWED). One completely delivered stage precedes every handoff; the bridge stores it under %LOCALAPPDATA%\ArenaRobloxBridge\handoff and injects it into the _sessionStart of the next session for the same place.'
            docsVersion = [string]$Shared.DocsVersion
            role = 'A normal token controls exactly one live Roblox Studio place. The special aggregate token copied from Alle Places controls several places: call GET /api/places first and pass one exact targetPlace in every request; the bridge refuses to guess. This makes switching safe and explicit. Send every request as POST /api/tool with JSON body { "token": "...", "targetPlace": "...", "tool": "...", "args": { ... } }.'
            firstCallBehavior = 'The FIRST tool response of this session automatically carries _sessionStart: the complete rules (including modelBuildRules and organicBuildRules), the progress/quality contracts and the full documentation of the core building, audit, read and session tools. The remaining tools are listed there as an index (name, category, summary) because a payload with every single tool documentation would be unnecessarily huge - fetch the exact parameters, defaults, examples and error cases with get_docs { tool = "<name>" } or GET /api/docs?tool=<name> (GET /api/docs with no parameter still returns everything). The session start names the measured size as packageBytes, the limit as budgetBytes and the policy as docsPolicy.'
            authentication = @{
                headers = @('Authorization: Bearer <token>', 'X-Arena-Token: <token>')
                query = '?token=<token>'
            }
            endpoints = @{
                manifest    = 'GET /api/manifest'
                docs        = 'GET /api/docs  (no param = everything; ?tool=<name>; ?category=<name>; ?full=true)'
                place       = 'GET /api/place'
                callTool    = 'POST /api/tool  { token, tool, args }  (args.asJob=true = run in background, get jobId)'
                callToolGet = 'GET /api/tool?token=<token>&tool=<name>&args=<URL-encoded JSON>&timeoutSeconds=<n>  - IDENTICAL to POST /api/tool (same code path, same envelope, same _sessionStart, same chunking/blobs). Use this if your environment can only do GET requests.'
                callMany    = 'POST /api/tools/parallel  { token, calls: [ { tool, args } ] }  - runs several tools at the same time'
                callManyGet = 'GET /api/tools/parallel?token=<token>&calls=<URL-encoded JSON array>  - same as the POST version'
                queue       = 'GET /api/queue?token=... - queue, pending commandIds and executor liveness; POST /api/queue { token, action="cancel", commandId } or { token, action="reset" } for controlled recovery'
                places      = 'GET /api/places?token=... - list targetPlace values for an aggregate Alle-Places token';
                events      = 'GET /api/events?token=...  - what the user did (started/stopped a playtest, plays in the game, ...)'
                blob        = 'GET /api/blob?token=...&id=<blobId>&index=<n>  - fetch one chunk of a huge answer'
                upload      = 'POST /api/upload  { token, text, uploadId?, chunkIndex?, chunkCount? }  - send a huge script in pieces, then use args.sourceRef = uploadId'
                uploadGet   = 'GET /api/upload?token=<token>&uploadId=<id>&chunkIndex=<n>&chunkCount=<m>&text=<URL-encoded text>  - same as the POST version'
                status      = 'GET /api/status'
                getOnlyNote = 'Normal tool and read endpoints work with plain HTTP GET (Version 3.9); POST /api/queue is intentionally required for cancel/reset because those controls mutate executor state. For GET tool calls, JSON fields args / calls / extra are URL-encoded query parameters.'
            }
            toolCount = $docs.Count
            toolsIndex = $toolIndex
            tools = $docs
            settings = @{
                simAllowed = $manifestSim
                notifyOnDone = $manifestNotify
                settingsNote = 'simAllowed=false: sim_start is disabled by design because the former Studio Run path exits Edit mode (EditModeActive=false); the documented Studio API has no supported true Edit-mode physics/script path. Building, GUIs, assets, jobs, compile_check, run_lua and sim_status remain available. notifyOnDone=true: call report_done { title, message } as your very last action when everything is done.'
            }
        }
        foreach ($key in $guides.Keys) { $manifest[[string]$key] = $guides[$key] }
        return $manifest
    }


    # ------------------------------------------------------------------
    # Mehrere Befehle gleichzeitig an das Plugin schicken
    # ------------------------------------------------------------------
    function Invoke-PluginToolsParallel($sessionId, $calls, [int]$timeoutSeconds, $progressPayload = $null) {
        $pending = New-Object System.Collections.Generic.List[object]
        # Version 7.0.5: deliveries follow the reconnect chain; the caller keeps its
        # own session/token and receives the results by commandId.
        $callerSession = [string]$sessionId
        $sessionId = Get-DeliverySession $callerSession
        $queue = Ensure-Queue $sessionId
        $commandBudget = [Math]::Max(90, [Math]::Min(300, $timeoutSeconds + 30))
        $progressStarted = $false
        foreach ($call in $calls) {
            $callTool = [string]$call.tool
            $callArgs = $call.args
            if ($null -eq $callArgs) { $callArgs = New-Object PSObject }
            $callProgress = $null
            try {
                if ($callArgs.PSObject.Properties['progress']) {
                    $callProgress = $callArgs.progress
                    $callArgs.PSObject.Properties.Remove('progress')
                }
            } catch {}
            $sourceRefArg = Get-CommandArgumentValue $callArgs 'sourceRef'
            if ($sourceRefArg.found -and -not [string]::IsNullOrWhiteSpace([string]$sourceRefArg.value)) {
                $uploadedSource = $null
                if ($Shared.Uploads.TryGetValue([string]$sourceRefArg.value, [ref]$uploadedSource)) {
                    $callArgs | Add-Member -NotePropertyName 'source' -NotePropertyValue $uploadedSource -Force
                } else {
                    $missingUpload = To-Json @{ ok=$false; code='REF_NOT_FOUND'; tool=$callTool; error=("Unknown sourceRef '" + [string]$sourceRefArg.value + "'. Upload the text again with upload_text."); commandSent=$false } 8
                    $activityId = New-ArenaActivity $sessionId $callTool $callArgs
                    Complete-ArenaActivity $sessionId $activityId $callTool $callArgs $missingUpload
                    $pending.Add(@{ id=$null; tool=$callTool; args=$callArgs; signal=$null; result=$missingUpload; deduplicated=$false; activityId=$activityId })
                    continue
                }
            }
            $activityId = New-ArenaActivity $sessionId $callTool $callArgs
            $argumentCheck = Test-CommandArguments $callTool $callArgs
            if (-not $argumentCheck.ok) {
                $invalidJson = To-Json $argumentCheck 12
                Complete-ArenaActivity $sessionId $activityId $callTool $callArgs $invalidJson
                $pending.Add(@{ id=$null; tool=$callTool; args=$callArgs; signal=$null; result=$invalidJson; deduplicated=$false; activityId=$activityId })
                continue
            }
            if ($queue.Count -ge 64) {
                $fullJson = To-Json @{ ok=$false; code='QUEUE_FULL'; tool=$callTool; error='The Studio command queue is full (64 queued commands). This command was rejected before queueing.'; commandSent=$false; queueDepth=[int]$queue.Count } 8
                Complete-ArenaActivity $sessionId $activityId $callTool $callArgs $fullJson
                $pending.Add(@{ id=$null; tool=$callTool; args=$callArgs; signal=$null; result=$fullJson; deduplicated=$false; activityId=$activityId })
                continue
            }

            $cached = Get-DedupedPlayResult $sessionId $callTool $callArgs
            $reserved = $false
            if ($null -eq $cached) { $reserved = Reserve-PlayRetry $sessionId $callTool $callArgs }
            if ($null -ne $cached -or -not $reserved) {
                if ($null -eq $cached) { $cached = Get-DedupedPlayResult $sessionId $callTool $callArgs }
                if ($cached) { Complete-ArenaActivity $sessionId $activityId $callTool $callArgs $cached }
                $pending.Add(@{ id=$null; tool=$callTool; args=$callArgs; signal=$null; result=$cached; deduplicated=$true; activityId=$activityId })
            } else {
                $commandId = [guid]::NewGuid().ToString('N')
                $queuedAt = Get-UnixSeconds
                $signal = New-Object System.Threading.ManualResetEventSlim($false)
                [void]$Shared.ResultSignals.TryAdd($commandId, $signal)
                $command = @{ id=$commandId; tool=$callTool; args=$callArgs; queuedAt=$queuedAt; budgetSeconds=$commandBudget }
                $commandJson = (To-Json $command 40)
                $Shared.CommandPayloads[$commandId] = $commandJson
                $Shared.ActivityCommandMap[$commandId] = (To-Json @{ sessionId=$sessionId; activityId=$activityId; tool=$callTool; args=$callArgs } 20)
                Add-PendingCommand $sessionId $commandId $callTool $commandBudget $queuedAt $callerSession
                $enqueue = Enqueue-Command $sessionId $queue $commandJson
                if (-not $enqueue.ok) {
                    Remove-PendingCommand $sessionId $commandId | Out-Null
                    $discard = $null
                    [void]$Shared.CommandPayloads.TryRemove($commandId, [ref]$discard)
                    [void]$Shared.CommandOwners.TryRemove($commandId, [ref]$discard)
                    [void]$Shared.CommandStates.TryRemove($commandId, [ref]$discard)
                    [void]$Shared.ActivityCommandMap.TryRemove($commandId, [ref]$discard)
                    [void]$Shared.ResultSignals.TryRemove($commandId, [ref]$discard)
                    try { $signal.Dispose() } catch {}
                    if ($callTool -eq 'sim_stop') {
                        $retryKey = [string]$sessionId + ':' + $callTool
                        $retryRaw = $null
                        if ($Shared.PlayRetryDedupe.TryGetValue($retryKey, [ref]$retryRaw)) {
                            try {
                                $retryEntry = $retryRaw | ConvertFrom-Json
                                if ([string]$retryEntry.fingerprint -eq (Get-PlayRetryFingerprint $callTool $callArgs) -and [string]$retryEntry.resultJson -like '*"pending":true*') {
                                    [void]$Shared.PlayRetryDedupe.TryRemove($retryKey, [ref]$discard)
                                }
                            } catch {}
                        }
                    }
                    $fullJson = To-Json @{ ok=$false; code='QUEUE_FULL'; tool=$callTool; error='The Studio command queue is full (64 queued commands). This command was rejected before queueing.'; commandSent=$false; queueDepth=[int]$enqueue.queueDepth } 8
                    Complete-ArenaActivity $sessionId $activityId $callTool $callArgs $fullJson
                    $pending.Add(@{ id=$null; tool=$callTool; args=$callArgs; signal=$null; result=$fullJson; deduplicated=$false; activityId=$activityId })
                } else {
                    if (-not $progressStarted) {
                        $progressNode = $progressPayload
                        if ($null -eq $progressNode) { $progressNode = $callProgress }
                        $progressReported = ($null -ne $progressNode)
                        $progressPercent = 0.0
                        $progressMessage = ''
                        $progressPercentProvided = (Get-ProgressPercentProvided $progressNode)
                        if ($progressReported) {
                            if ($progressNode -is [ValueType] -or $progressNode -is [string]) {
                                $progressPercent = Clamp-ProgressPercent $progressNode
                            } else {
                                try { if ($progressNode.PSObject.Properties['percent']) { $progressPercent = Clamp-ProgressPercent $progressNode.percent } } catch {}
                                try { if ($progressNode.PSObject.Properties['message']) { $progressMessage = [string]$progressNode.message } } catch {}
                            }
                        }
                        Update-ArenaProgressState $sessionId $callTool $progressPercent $progressMessage $progressReported $false $false $progressPercentProvided | Out-Null
                        $progressStarted = $true
                    }
                    $pending.Add(@{ id=$commandId; tool=$callTool; args=$callArgs; signal=$signal; result=$null; deduplicated=$false; activityId=$activityId })
                }
            }
        }
        $wake = Ensure-Signal $sessionId
        [void]$wake.Set()

        $deadline = [DateTime]::UtcNow.AddSeconds($timeoutSeconds)
        $open = $pending.Count
        while ($open -gt 0 -and [DateTime]::UtcNow -lt $deadline) {
            $open = 0
            foreach ($item in $pending) {
                if ($item.result -eq $null -and $item.id) {
                    $resultJson = $null
                    if ($Shared.CommandResults.TryRemove($item.id, [ref]$resultJson)) {
                        $item.result = $resultJson
                        Remove-PendingCommand $sessionId $item.id | Out-Null
                        Save-DedupedPlayResult $sessionId $item.tool $item.args $resultJson
                    } else {
                        $open = $open + 1
                    }
                }
            }
            if ($open -gt 0) { Start-Sleep -Milliseconds 40 }
        }

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($item in $pending) {
            if ($item.id) {
                $removed = $null
                $finalResultJson = $null
                [System.Threading.Monitor]::Enter($Shared.CommandResultLock)
                try {
                    [void]$Shared.ResultSignals.TryRemove($item.id, [ref]$removed)
                    if ($item.result -eq $null -and $Shared.CommandResults.TryRemove($item.id, [ref]$finalResultJson)) {
                        $item.result = $finalResultJson
                    }
                } finally {
                    [System.Threading.Monitor]::Exit($Shared.CommandResultLock)
                }
                if ($item.result -and $item.id -and $item.result -eq $finalResultJson) {
                    Remove-PendingCommand $sessionId $item.id | Out-Null
                    Save-DedupedPlayResult $sessionId $item.tool $item.args $item.result
                }
                if ($item.result) { [void]$Shared.ResultChunks.TryRemove($item.id, [ref]$removed) }
                try { $item.signal.Dispose() } catch {}
            }
            if ($item.result) {
                $suffix = if ($item.deduplicated) { ',"deduplicated":true' } else { '' }
                $parts.Add('{"tool":' + (To-Json $item.tool 3) + ',"response":' + $item.result + $suffix + '}')
            } else {
                $pendingState = $null
                if ($item.id) { $pendingState = Get-PendingInfo $sessionId $item.id }
                $stateJson = if ($pendingState) { To-Json @{ commandId=$item.id; status=$pendingState.status; queuedAt=$pendingState.queuedAt; startedAt=$pendingState.startedAt } 6 } else { 'null' }
                $parts.Add('{"tool":' + (To-Json $item.tool 3) + ',"response":{"ok":false,"code":"STUDIO_TIMEOUT","commandId":' + (To-Json $item.id 3) + ',"error":"Roblox Studio did not answer before the HTTP deadline. The command remains tracked by commandId and the watchdog will abandon it if executor heartbeats stop.","pending":' + $stateJson + '}}')
            }
        }
        return '[' + ($parts -join ',') + ']'
    }

    function New-Envelope($sessionId) {
        $entry = Get-SessionEntry $sessionId
        $events = Take-Events $sessionId 12
        # Version 3.8: Bridge-Einstellungen (Selbst-Tests / Fertig-Meldung)
        $simAllowed = $false
        $notifyOnDone = $false
        try { $simAllowed = [bool]$Shared.BridgeSettings.simAllowed } catch {}
        try { $notifyOnDone = [bool]$Shared.BridgeSettings.notifyOnDone } catch {}
        $progressJson = ''
        $progressView = $null
        if ($Shared.ProgressStates.TryGetValue([string]$sessionId, [ref]$progressJson) -and -not [string]::IsNullOrWhiteSpace($progressJson)) {
            try { $progressView = $progressJson | ConvertFrom-Json } catch {}
        }
        # Version 7.0.5: describe the session that currently EXECUTES (a reconnect
        # may have moved delivery to a successor while the caller keeps its token).
        $executorSnapshot = Get-SessionExecutorSnapshot (Get-DeliverySession ([string]$sessionId))
        $envelope = @{
            bridgeVersion = '7.4.1'
            executor = $executorSnapshot
            progressContract = @{
                rule = 'Every call carries progress = { percent, message } on the same level as token/targetPlace/tool (or inside args - the bridge removes it before the plugin sees it). Missing percent is never an error, but the user then sees NO bar and NO percentage at all - only your message as text. Send a real number every few calls. The last call of a finished task carries report_done (100, automatically filled in if omitted).'
                lastPercent = $(if ($progressView) { [double]$progressView.percent } else { 0 })
                lastMessage = $(if ($progressView) { [string]$progressView.message } else { '' })
                state = $(if ($progressView) { [string]$progressView.state } else { 'idle' })
                callsWithProgress = $(if ($progressView) { [int]$progressView.callsWithProgress } else { 0 })
                callsTotal = $(if ($progressView) { [int]$progressView.calls } else { 0 })
            }
            place         = if ($entry) { $entry.placeName } else { $null }
            sessionId     = $sessionId
            studio        = if ($entry) { $entry.state } else { $null }
            serverTime    = (Get-Date).ToString('u')
            docsVersion   = [string]$Shared.DocsVersion
            bridgeSettings = @{
                simAllowed = $simAllowed
                notifyOnDone    = $notifyOnDone
            }
            docs          = 'Full tool documentation (parameters, types, defaults, returns, examples, error codes): GET /api/docs, or ?tool=<name>, or ?category=<name>. The first tool call of this session (_sessionStart) already carried the rules, the contracts and the full documentation of the core building/audit/read/session tools; every other tool is listed there as an index - fetch its parameters with get_docs or GET /api/docs?tool=<name>.'
        }
        if ($Shared.Sessions.Count -ge 2) {
            $envelope.multiPlace = @{
                available = $true
                note = 'Several Places are connected. The All-Places token uses GET /api/places plus an explicit targetPlace per request; it never guesses which game to edit.'
                endpoint = 'GET /api/places?token=<all-places-token>'
            }
        }
        if ($entry -and [string]$entry.pluginVersion -ne [string]$Shared.DocsVersion) {
            $envelope.pluginOutdated = @{
                code = 'PLUGIN_OUTDATED'
                pluginVersion = [string]$entry.pluginVersion
                bridgeVersion = [string]$Shared.DocsVersion
                message = 'plugin outdated - simulations and version checks wait. Tell the user to restart Roblox Studio so the matching plugin loads; do not diagnose a simulation failure until the versions match.'
                userHint = 'Studio neu starten: Das Studio-Plugin ist aelter als die Bridge. Playtests warten bis zum Neustart.'
            }
            if ($envelope.attention) { $envelope.attention += ' plugin outdated - Simulationen warten; Studio neu starten.' } else { $envelope.attention = 'plugin outdated - Simulationen warten; Studio neu starten.' }
        }
        # sim_start is blocked because the available simulation leaves Edit mode.
        if (-not $simAllowed) {
            $envelope.simDisabled = @{
                code = 'SIM_DISABLED'
                reason = 'EDIT_MODE_SIMULATION_UNAVAILABLE'
                message = 'sim_start is intentionally unavailable: the former Studio Run implementation exits Edit mode (EditModeActive=false), and the documented Studio API has no supported true Edit-mode physics/script path.'
                whatThisMeans = 'This is an intentional compatibility/safety decision, not a bridge failure. The requested simulation while EditModeActive=true is not supported by the documented Studio API.'
                whatStillWorks = 'compile_check, one-off run_lua in the edit place, sim_status, sim_stop for an existing bridge-owned session, get_output / get_errors, all reading/building tools, GUIs, assets, jobs, progress and handoff.'
            }
            $envelope.attention = 'sim_start is disabled. Do not retry it; continue building/auditing in edit mode and test live physics/scripts manually in Studio.'
        }
        # Version 3.8: Fertig-Meldung aktiv? In JEDER Antwort deutlich daran
        # erinnern, report_done als ALLERLETZTE Aktion zu rufen.
        if ($notifyOnDone) {
            $envelope.notifyWhenDone = @{
                code = 'REPORT_DONE_EXPECTED'
                instruction = 'FINISH NOTIFICATION IS ON: when ALL your changes are complete and you are about to end your answer, call report_done { title, message } as your VERY LAST tool call.'
                messageRule = 'title = lively German headline (max 70 chars), message = inviting German sentence (max 140 chars), e.g. title="✅ Arena hat den Bug behoben!", message="Der Fehler ist weg – komm und teste das Spiel!".'
                strictRule = 'Call it ONLY when you are truly done: no further tool calls and no further changes afterwards - end your answer right after it. Never call it mid-work.'
            }
            $notifyNote = 'FINISH NOTIFICATION: when everything is done, call report_done { title, message } as your LAST action, then end your answer.'
            if ($envelope.attention) { $envelope.attention = $envelope.attention + ' ' + $notifyNote } else { $envelope.attention = $notifyNote }
        }
        # Version 3.8: Laufender Test - IMMER sichtbar machen (bei jedem Call,
        # auch beim Lesen), nicht nur wenn der Nutzer ihn gestartet hat.
        if ($entry -and $entry.state -and [bool]$entry.state.running) {
            $testMode = [string]$entry.state.mode
            if ([bool]$entry.state.userPlaytestActive) {
                $envelope.simulationWarning = @{
                    severity = 'critical'
                    code = 'USER_PLAYTEST_ACTIVE'
                    assistantAction = 'STOP_OR_YIELD'
                    mode = $testMode
                    message = "Roblox Studio is in $testMode mode and the USER started this playtest. Do not make persistent edits."
                    options = @(
                        'There is no play_stop tool any more: the bridge cannot and must not stop the user playtest for you.'
                        'End your response and ask the user to stop the test (Shift+F5) or to tell you when Studio is free again.'
                        'Reading tools and sim_status stay available; building waits.'
                    )
                    userRequest = 'Tell the user you can see their active playtest, that you cannot build while it runs, and ask them to stop it or to message you when Studio is free.'
                }
                $envelope.simulation = $envelope.simulationWarning
                $critNote = 'CRITICAL PLAYTEST NOTICE: the USER is testing/playing right now. You cannot stop it (no play_stop since 7.0.0): end your response and ask the user to stop the test or to tell you when Studio is free. Do not make persistent edits while the test runs.'
                if ($envelope.attention) { $envelope.attention = $envelope.attention + ' ' + $critNote } else { $envelope.attention = $critNote }
            } else {
                $envelope.simulation = @{
                    mode = $testMode
                    startedBy = 'assistant (you)'
                    message = "Your own $testMode simulation is running. Persistent edits stay blocked until sim_stop. Audit the result with get_output / get_errors, then call sim_stop before building again."
                }
            }
        }
        # Version 3.8: Arbeitet der Nutzer gerade selbst im Editor?
        $activeAt = [long]0
        if ($Shared.UserActiveAt.TryGetValue([string]$sessionId, [ref]$activeAt)) {
            $ageActive = (Get-UnixSeconds) - $activeAt
            if ($ageActive -ge 0 -and $ageActive -le 180) {
                $envelope.userWorking = @{
                    lastActivitySecondsAgo = $ageActive
                    message = 'The user is working in Roblox Studio themselves right now (selection/camera activity in the editor). Expect changes you did not make: re-read before overwriting, never undo their changes, coordinate in chat.'
                }
            }
        }
        # In Studio läuft noch etwas (z.B. nach einem Timeout). Studio arbeitet
        # Befehle strikt nacheinander ab - der nächste Call wartet automatisch.
        $pending = Get-PendingCommands $sessionId
        if ($pending.Count -gt 0) {
            $envelope.studioBusy = $pending
            $busyNote = 'One or more commands are still tracked in Roblox Studio (a client HTTP timeout does not immediately kill work). The executor runs serially and sends liveness heartbeats; if a command exceeds its safety budget or heartbeats stop, the watchdog marks it STUDIO_ABANDONED / EXECUTOR_UNRESPONSIVE so the queue can recover. Inspect _bridge.studioBusy and _bridge.lateResults before retrying; partial changes may have occurred.'
            if ($envelope.attention) {
                $envelope.attention = $envelope.attention + ' ' + $busyNote
            } else {
                $envelope.attention = $busyNote
            }
        }
        # Version 7.1.3: Der zuletzt GEMESSENE Bauzustand gehoert in jede
        # Antwort. Ein Kugel-Modell oder ein falsch gedrehter Zylinder darf
        # nicht erst bei report_done auffallen, sondern muss waehrend der
        # Arbeit sichtbar sein (model_audit -> buildQuality).
        $qualityJson = ''
        if ($Shared.AuditFlags.TryGetValue([string]$sessionId, [ref]$qualityJson) -and -not [string]::IsNullOrWhiteSpace($qualityJson)) {
            try {
                $qualityView = $qualityJson | ConvertFrom-Json
                $qualityAbuse = $false
                $qualityCylinders = 0
                try { if ($qualityView.PSObject.Properties['primitiveAbuse']) { $qualityAbuse = [bool]$qualityView.primitiveAbuse } } catch {}
                try { if ($qualityView.PSObject.Properties['cylinderProblemCount']) { $qualityCylinders = [int]$qualityView.cylinderProblemCount } } catch {}
                if ($qualityAbuse -or $qualityCylinders -gt 0) {
                    $envelope.buildQuality = @{
                        verdict = $(try { [string]$qualityView.buildQualityVerdict } catch { '' })
                        primitiveAbuse = $qualityAbuse
                        primitiveGroups = $(if ($qualityView.PSObject.Properties['primitiveGroups']) { $qualityView.primitiveGroups } else { @() })
                        cylinderProblemCount = $qualityCylinders
                        source = 'model_audit buildQuality (measured in Studio, not an estimate)'
                    }
                    $qualityNote = 'BUILD QUALITY: the last model_audit still reports '
                    if ($qualityAbuse) { $qualityNote = $qualityNote + 'a primitive-only (Ball-only) group ' }
                    if ($qualityAbuse -and $qualityCylinders -gt 0) { $qualityNote = $qualityNote + 'and ' }
                    if ($qualityCylinders -gt 0) { $qualityNote = $qualityNote + ([string]$qualityCylinders + ' cylinder(s) standing as discs on their edge (90-degree error) ') }
                    $qualityNote = $qualityNote + '- see organicBuildRules, rebuild with build_polygon_model and the cylinder helper, then run model_audit again. report_done answers DETAIL_REQUIRED until this is fixed or handed off.'
                    $draftRiskView = $false
                    $draftGradeView = ''
                    $draftScoreView = -1
                    try { if ($qualityView.PSObject.Properties['draftRisk']) { $draftRiskView = [bool]$qualityView.draftRisk } } catch {}
                    try { if ($qualityView.PSObject.Properties['buildGrade']) { $draftGradeView = [string]$qualityView.buildGrade } } catch {}
                    try { if ($qualityView.PSObject.Properties['finishScore']) { $draftScoreView = [int]$qualityView.finishScore } } catch {}
                    if ($draftRiskView) {
                        $envelope.qualityWarning = 'DRAFT_GRADE_RISK'
                        $draftNote = ('DRAFT_GRADE_RISK: the last model_audit graded this build "' + $draftGradeView + '" (' + [string]$draftScoreView + '/100) - few parts, no polygon/mesh/union/detail geometry. report_done answers DRAFT_GRADE_RISK. Rebuild it with real structure, or declare the intended simplicity while building (grade = "simple"/"lowpoly"/"blockout") and audit again.')
                        if ($envelope.attention) { $envelope.attention = $envelope.attention + ' ' + $draftNote } else { $envelope.attention = $draftNote }
                    }
                    if ($envelope.attention) { $envelope.attention = $envelope.attention + ' ' + $qualityNote } else { $envelope.attention = $qualityNote }
                }
            } catch {}
        }
        # Version 7.2.0: NUTZER-KANAL. JEDER Umschlag traegt wartende
        # Nutzernachrichten mit - das ist die einzige Stelle, an der eine
        # Korrektur des Nutzers die KI ueberhaupt erreichen kann (die Bridge
        # kann nicht in den Arena-Chat schreiben, es gibt keinen Push-Kanal).
        # Version 7.2.0: PERCENT_MISSING als Nudge in JEDER Antwort, solange die
        # KI keine Zahl schickt. Ohne Zahl zeigt die Oberflaeche bewusst keinen
        # Balken (D5/D6) - die KI muss also erfahren, warum der Nutzer nichts
        # sieht, statt es zu raten.
        try {
            $progressWarnJson = ''
            if ($Shared.ProgressStates.TryGetValue([string]$sessionId, [ref]$progressWarnJson) -and -not [string]::IsNullOrWhiteSpace($progressWarnJson)) {
                $progressWarnState = $progressWarnJson | ConvertFrom-Json
                $warnCalls = 0
                $warnWithPercent = 0
                $warnKnown = $false
                try { $warnCalls = [int]$progressWarnState.calls } catch {}
                try { if ($progressWarnState.PSObject.Properties['callsWithPercent']) { $warnWithPercent = [int]$progressWarnState.callsWithPercent } } catch {}
                try { if ($progressWarnState.PSObject.Properties['percentKnown']) { $warnKnown = [bool]$progressWarnState.percentKnown } } catch {}
                if ($warnCalls -ge 2 -and -not $warnKnown -and [string]$progressWarnState.state -ne 'done') {
                    $envelope.progressWarning = @{
                        code = 'PERCENT_MISSING'
                        callsWithoutPercent = $warnCalls
                        effect = 'The user sees NO progress bar and NO percentage for this place - only a text line with your message and your last tool. They cannot tell how far you are.'
                        fix = 'Add progress = { percent = <0-100>, message = "<what you are doing>" } to your next call. A rough honest number is worth more than no number.'
                    }
                    $percentNote = 'PERCENT_MISSING: send progress.percent - the user currently sees no bar at all.'
                    if ($envelope.attention) { $envelope.attention = $percentNote + ' ' + $envelope.attention } else { $envelope.attention = $percentNote }
                }
            }
        } catch {}
        # Version 7.2.0 (D3): Antworten aus dem Fragenfenster, die noch nicht
        # gezeigt wurden. Eine Antwort darf nie verloren gehen, nur weil die KI
        # gerade nicht gewartet hat.
        # Version 7.2.4 (P0): Get-LateAskAnswers liefert eine echte
        # List[object] (return ,$items). NIE @() darum legen - Windows
        # PowerShell 5.1 wirft fuer @( List[object] ) den Binderfehler
        # "Die Argumenttypen stimmen nicht ueberein." Dieser Fehler toetete
        # in 7.2.3 JEDEN Werkzeugaufruf, sobald eine Frage offen war.
        # .ToArray() ist erlaubt und ergibt auch leer ein Array, nie $null.
        # Jeder Umschlagblock liegt zusaetzlich in try/catch: Der Umschlag
        # ist Zierde und darf niemals die Werkzeugantwort kosten.
        try {
            $lateAnswers = Get-LateAskAnswers $sessionId 4
            if ($lateAnswers.Count -gt 0) {
                $envelope.userAnswers = $lateAnswers.ToArray()
                $answerNote = 'USER ANSWERS (ask_user/confirm_action): the user answered or cancelled. Read _bridge.userAnswers, honor cancelled: true without asking again, and mention the decision in your reply.'
                if ($envelope.attention) { $envelope.attention = $answerNote + ' ' + $envelope.attention } else { $envelope.attention = $answerNote }
            }
        } catch {
            Write-FlowStation 'ENVELOPE' ([string]$sessionId) 'USER_ANSWERS_SKIPPED' @{ reason = 'envelope_field_failed' }
        }
        # Version 7.2.0 (AP7): Die Code-Struktur-Messung wiederholt sich in
        # jeder Antwort, bis das Skript aufgeteilt ist - einmal lesen und
        # ignorieren hilft nicht.
        try {
            $layoutJson = ''
            if ($Shared.CodeLayouts.TryGetValue([string]$sessionId, [ref]$layoutJson) -and -not [string]::IsNullOrWhiteSpace($layoutJson)) {
                $layoutView = $layoutJson | ConvertFrom-Json
                $layoutRisk = $false
                try { $layoutRisk = [bool]$layoutView.monolithRisk } catch {}
                if ($layoutRisk) {
                    $envelope.codeLayout = $layoutView
                    $envelope.uiStructureWarning = 'MONOLITH_RISK'
                    $layoutNote = ('MONOLITH_RISK (' + [string]$layoutView.level + ', ' + [string]$layoutView.lines + ' lines, ' + [string]$layoutView.instanceNewCalls + 'x Instance.new): ' + [string]$layoutView.advice)
                    if ($envelope.attention) { $envelope.attention = $layoutNote + ' ' + $envelope.attention } else { $envelope.attention = $layoutNote }
                }
            }
        } catch {}
        # Version 7.2.4 (P0): .ToArray() statt @( List[object] ) - siehe oben.
        try {
            $openAsks = Get-PendingAskViews $sessionId 1
            if ($openAsks.Count -gt 0) {
                $envelope.openQuestions = $openAsks.ToArray()
                $askNote = 'OPEN QUESTION: the user still sees a question window (' + [string]$openAsks[0].askId + ': ' + [string]$openAsks[0].title + '). Do not guess - wait with ask_user { askId, resume: true } or continue with work that does not depend on the answer.'
                if ($envelope.attention) { $envelope.attention = $askNote + ' ' + $envelope.attention } else { $envelope.attention = $askNote }
            }
        } catch {
            Write-FlowStation 'ENVELOPE' ([string]$sessionId) 'OPEN_QUESTIONS_SKIPPED' @{ reason = 'envelope_field_failed' }
        }
        # Version 7.2.4 (P0): .ToArray() statt @( List[object] ) - siehe oben.
        try {
        $pendingUserMessages = Get-PendingUserMessageViews $sessionId 3
        if ($pendingUserMessages.Count -gt 0) {
            $deliveredIds = New-Object System.Collections.Generic.List[string]
            foreach ($messageView in $pendingUserMessages) { $deliveredIds.Add([string]$messageView.id) }
            [void](Mark-UserMessagesDelivered $sessionId $deliveredIds 'envelope')
            $envelope.userMessages = $pendingUserMessages.ToArray()
            $envelope.userMessageContract = @{
                code = 'USER_MESSAGE_PENDING'
                priority = 'highest'
                instruction = 'The user sent this WHILE you were working. Stop executing your previous plan, apply the instruction, and tell the user in your reply what you changed. Then acknowledge with ack_user_message { id }.'
                doNotIgnore = 'These messages outrank your own assumptions and any earlier plan. Never tell the user you received nothing while this field is present.'
                repeatRule = 'An unacknowledged message is repeated in up to three responses, so ignoring it does not make it disappear - it only makes the bridge show the user "angekommen, nicht bestaetigt".'
            }
            $userNote = 'USER MESSAGE PENDING: the user interrupted your work - read _bridge.userMessages FIRST, act on it, then ack_user_message.'
            if ($envelope.attention) { $envelope.attention = $userNote + ' ' + $envelope.attention } else { $envelope.attention = $userNote }
        }
        } catch {
            Write-FlowStation 'ENVELOPE' ([string]$sessionId) 'USER_MESSAGES_SKIPPED' @{ reason = 'envelope_field_failed' }
        }
        $late = Take-LateResults $sessionId
        if ($late.Count -gt 0) {
            $envelope.lateResults = $late
            $envelope.lateResultsNote = 'These results finished in Studio AFTER their HTTP call had timed out. They are final - do not rerun the work.'
        }
        if ($events.Count -gt 0) {
            $envelope.events = $events
            $eventNote = 'Something happened outside of your control (see events) - for example the user started or stopped the playtest, or the user is playing in the game right now. This is normal, nothing crashed, and it is NOT a bug in your scripts.'
            if ($envelope.attention) {
                $envelope.attention = $envelope.attention + ' ' + $eventNote
            } else {
                $envelope.attention = $eventNote
            }
        }
        return $envelope
    }

    # ------------------------------------------------------------------
    # Werkzeuge, die das Programm selbst beantwortet (ohne Roblox)
    # ------------------------------------------------------------------
    # ------------------------------------------------------------------
    # Version 7.4.0: MESH-SERVERWERKZEUGE
    # blender_status / build_mesh_model / mesh_status / mesh_cancel /
    # mesh_apply_asset laufen im Handler (Bridge-Prozess): Blender, OBJ-Messung
    # und Register liegen ausserhalb von Roblox Studio. Nur mesh_apply_asset
    # spricht mit dem Plugin (interner Befehl mesh_apply).
    # ------------------------------------------------------------------
    function Invoke-MeshServerTool($sessionId, [string]$tool, $toolArgs) {
        # Der Toolkit-Text ist die EINZIGE Quelle fuer Queue-Anmeldung,
        # Registerpflege und Messung. Er wird in DIESER Funktion geladen, damit
        # alle Mesh-Helfer hier sichtbar sind (kein Zustand zwischen Aufrufen).
        try { . ([scriptblock]::Create([string]$Shared.MeshToolkitText)) } catch {
            Write-BridgeLog ('Mesh-Toolkit konnte im Handler nicht geladen werden: ' + $_.Exception.Message)
        }
        # Version 7.4.1: GENAU die eine Blender-Hilfs-Quelle - dieselben
        # Funktionen wie im Hauptprogramm und in jedem Runspace.
        try { . ([scriptblock]::Create([string]$Shared.BlenderToolsText)) } catch {
            Write-BridgeLog ('Blender-Helfer konnten im Handler nicht geladen werden: ' + $_.Exception.Message)
        }
        $sid = [string]$sessionId
        $blender = $Shared.BlenderState
        $meshRoot = [string]$Shared.MeshRoot
        $blenderState = ''
        $blenderReady = $false
        if ($null -ne $blender) {
            try { $blenderState = [string]$blender.state } catch {}
            try { $blenderReady = ($blenderState -eq 'ready' -and [bool]$blender.enabled) } catch {}
        }
        $blenderReport = @{}
        try { $blenderReport = Get-BlenderReport -Shared $Shared } catch {}
        $blenderReport.ready = [bool]$blenderReady
        $blenderReport.enabled = [bool]$blenderReady
        $blenderReport.installLog = (Join-Path $meshRoot 'blender-install.log')
        $blenderReport.gatePending = $false
        try { $blenderReport.gatePending = (-not [bool]$blender.gateResolved) } catch {}

        if ($tool -eq 'blender_status') {
            $action = ''
            if ($toolArgs -and -not [string]::IsNullOrWhiteSpace([string]$toolArgs.action)) { $action = ([string]$toolArgs.action).Trim().ToLowerInvariant() }
            if ($action -eq 'check') {
                # Wiederholt die ECHTE Faehigkeitsprobe (nicht nur die Version)
                # im Hintergrund - die Antwort kommt sofort, kein Warten.
                $started = $false
                try { $started = [bool](Start-BlenderRecheck -Shared $Shared) } catch {
                    Write-BridgeLog ('Blender-Pruefung konnte im Handler nicht gestartet werden: ' + $_.Exception.Message)
                }
                $blenderReport = @{}
                try { $blenderReport = Get-BlenderReport -Shared $Shared } catch {}
                $blenderReport.ready = ([string]$blenderReport.state -eq 'ready' -and [bool]$blenderReport.enabled)
                $blenderReport.installLog = (Join-Path $meshRoot 'blender-install.log')
                return @{ ok = $true; result = @{ started = [bool]$started; blender = $blenderReport; note = $(if ($started) { 'Suche, Version und echte Faehigkeitsprobe laufen jetzt im Hintergrund - in ein paar Sekunden blender_status erneut lesen (nicht in einer engen Schleife).' } else { 'Es laeuft schon eine Blender-Pruefung (Zustand ' + [string]$blenderReport.state + ').' }) } }
            }
            $note = 'Blender ist bereit. Mesh-Dateien und Ids: siehe mesh_status.'
            if (-not $blenderReady) {
                $note = 'Der Mesh-Bau ist deaktiviert, solange Blender nicht bereit ist (state=' + $blenderState + ', probe=' + [string]$blenderReport.probe + '). Der Polygon-Weg (build_polygon_model) funktioniert unabhaengig davon. Der Nutzer kann die Pruefung mit blender_status { action = "check" } oder per Klick auf Zeile 4 im Startbildschirm wiederholen - dort laeuft immer die ECHTE Faehigkeitsprobe.'
            }
            return @{ ok = $true; result = @{ blender = $blenderReport; note = $note } }
        }

        if ($tool -eq 'build_mesh_model') {
            if (-not $blenderReady) {
                return (To-Json @{
                    ok = $false
                    code = 'BLENDER_NOT_READY'
                    error = ('Blender ist nicht bereit (Zustand: ' + $blenderState + '). Es wurde NICHTS gebaut.')
                    blender = $blenderReport
                    howToFix = 'Dem Nutzer ehrlich sagen, dass Blender nicht bereit ist (der Zustand und die Proben-Meldung stehen oben), und dass er die Pruefung mit blender_status { action = "check" } oder per Klick auf Zeile 4 im Startbildschirm wiederholen kann - dort laeuft immer die ECHTE Faehigkeitsprobe. Alternativ mit build_polygon_model weiterbauen. Nicht in einer Schleife wiederholen.'
                } 20)
            }
            $modelName = 'Mesh'
            if ($toolArgs -and -not [string]::IsNullOrWhiteSpace([string]$toolArgs.modelName)) { $modelName = ([string]$toolArgs.modelName).Trim() }
            $modelName = ([regex]::Replace($modelName, '[^A-Za-z0-9_\- ]', '')).Trim()
            if ([string]::IsNullOrWhiteSpace($modelName)) { $modelName = 'Mesh' }
            if ($modelName.Length -gt 32) { $modelName = $modelName.Substring(0, 32) }
            $slotsRaw = @()
            if ($toolArgs -and $null -ne $toolArgs.slots) { $slotsRaw = @($toolArgs.slots) }
            if ($slotsRaw.Count -lt 1) {
                return (To-Json @{ ok = $false; code = 'BAD_ARGS'; error = 'build_mesh_model braucht mindestens einen Slot mit name und script.' } 12)
            }
            if ($slotsRaw.Count -gt 12) {
                return (To-Json @{ ok = $false; code = 'BUDGET_EXCEEDED'; error = ('Hochstens 12 Slots je Aufruf (angefragt: ' + [string]$slotsRaw.Count + '). Mehr Slots = mehr Meshes = mehr Handarbeit beim Upload.'); maximumSlots = 12 } 12)
            }
            $specSlots = New-Object System.Collections.Generic.List[object]
            $problems = New-Object System.Collections.Generic.List[string]
            $index = 0
            foreach ($slotRaw in $slotsRaw) {
                $index = $index + 1
                if ($null -eq $slotRaw) { $problems.Add('Slot ' + [string]$index + ' ist leer.'); continue }
                $slotName = [string]$slotRaw.name
                $slotName = ([regex]::Replace($slotName, '[^A-Za-z0-9_\-]', '_')).Trim('_')
                if ([string]::IsNullOrWhiteSpace($slotName)) { $slotName = ('slot' + [string]$index) }
                if ($slotName.Length -gt 32) { $slotName = $slotName.Substring(0, 32) }
                $scriptText = [string]$slotRaw.script
                $safety = Test-MeshScriptSafety $scriptText
                if (-not $safety.ok) { $problems.Add($slotName + ': ' + [string]$safety.reason); continue }
                $targetTriangles = 0
                try { if ($null -ne $slotRaw.targetTriangles) { $targetTriangles = [int]$slotRaw.targetTriangles } } catch {}
                if ($targetTriangles -lt 0) { $targetTriangles = 0 }
                if ($targetTriangles -gt 10000) { $targetTriangles = 10000 }
                $color = '#A0A4AD'
                if (-not [string]::IsNullOrWhiteSpace([string]$slotRaw.color)) { $color = ([string]$slotRaw.color).Trim() }
                if ($color -notmatch '^#[0-9A-Fa-f]{6}$') { $color = '#A0A4AD' }
                $material = 'SmoothPlastic'
                if (-not [string]::IsNullOrWhiteSpace([string]$slotRaw.material)) { $material = ([string]$slotRaw.material).Trim() }
                $canCollide = $false
                try { $canCollide = ([bool]$slotRaw.canCollide -eq $true) } catch {}
                $offset = @{ x = 0.0; y = 0.0; z = 0.0 }
                if ($null -ne $slotRaw.offset) {
                    try {
                        $offset = @{
                            x = [double]$slotRaw.offset.x
                            y = [double]$slotRaw.offset.y
                            z = [double]$slotRaw.offset.z
                        }
                    } catch { $offset = @{ x = 0.0; y = 0.0; z = 0.0 } }
                }
                $specSlots.Add(@{
                    name = $slotName
                    script = $scriptText
                    targetTriangles = $targetTriangles
                    color = $color
                    material = $material
                    canCollide = $canCollide
                    offset = $offset
                })
            }
            if ($problems.Count -gt 0) {
                return (To-Json @{
                    ok = $false
                    code = 'SCRIPT_REJECTED'
                    error = 'Mindestens ein Blender-Skript wurde abgelehnt - es wurde NICHTS gebaut.'
                    problems = $problems.ToArray()
                    scriptRules = 'Erlaubt: bpy, bmesh, math, mathutils, random und normale Rechen-/Mesh-Befehle. Gesperrt: Datei-, Netzwerk-, Prozess- und Systemzugriff (os, sys, subprocess, shutil, socket, urllib, requests, ctypes, winreg, __import__, importlib, eval, exec), bpy.ops.wm.* und alle Exportfunktionen - Szene, Export und Messung macht der Runner der Bridge.'
                } 20)
            }
            $origin = @{ x = 0.0; y = 0.0; z = 0.0 }
            if ($toolArgs -and $null -ne $toolArgs.origin) {
                try { $origin = @{ x = [double]$toolArgs.origin.x; y = [double]$toolArgs.origin.y; z = [double]$toolArgs.origin.z } } catch { $origin = @{ x = 0.0; y = 0.0; z = 0.0 } }
            }
            $rotationY = 0.0
            try { if ($toolArgs -and $null -ne $toolArgs.rotationY) { $rotationY = [double]$toolArgs.rotationY } } catch {}
            $anchored = $true
            try { if ($toolArgs -and $toolArgs.anchored -eq $false) { $anchored = $false } } catch {}
            $parentRef = 'game.Workspace'
            if ($toolArgs -and -not [string]::IsNullOrWhiteSpace([string]$toolArgs.parentRef)) { $parentRef = ([string]$toolArgs.parentRef).Trim() }
            $timeoutSeconds = 300
            try { if ($toolArgs -and $null -ne $toolArgs.timeoutSeconds) { $timeoutSeconds = [int]$toolArgs.timeoutSeconds } } catch {}
            if ($timeoutSeconds -lt 30) { $timeoutSeconds = 30 }
            if ($timeoutSeconds -gt 900) { $timeoutSeconds = 900 }
            $spec = @{
                modelName = $modelName
                sessionId = $sid
                parentRef = $parentRef
                origin = $origin
                rotationY = $rotationY
                anchored = $anchored
                timeoutSeconds = $timeoutSeconds
                slots = $specSlots.ToArray()
            }
            $jobId = Start-MeshJobWork $Shared ([string]$blender.path) $spec
            Write-BridgeLog ('Mesh-Job gestartet: ' + [string]$jobId + ' (' + [string]$specSlots.Count + ' Slot(s), ' + $modelName + ')')
            return @{
                ok = $true
                result = @{
                    jobId = $jobId
                    state = 'queued'
                    slotCount = [int]$specSlots.Count
                    blender = $blenderReport
                    meshFolder = $meshRoot
                    note = 'Blender laeuft im HINTERGRUND - sofort weiterarbeiten und NICHT synchron warten. mesh_status zeigt Dreiecke und Groesse je Slot, sobald die Datei gemessen ist (meist in unter einer Minute). Die Bridge legt die viereckigen MeshPart-Platzhalter danach selbst an. Danach laedt der NUTZER die OBJ-Datei(en) in Roblox hoch und traegt die Mesh-Id(s) im Bridge-Fenster "Mesh-Uploads" ein; mesh_apply_asset setzt die Geometrie ein. Solange Platzhalter stehen, ist das Modell NICHT fertig (report_done: MESH_UPLOAD_PENDING).'
                    files = $(foreach ($s in $specSlots) { @{ name = [string]$s.name; file = ([string]$s.name + '.obj') } })
                }
            }
        }

        if ($tool -eq 'mesh_status') {
            $wantedJob = ''
            if ($toolArgs -and -not [string]::IsNullOrWhiteSpace([string]$toolArgs.jobId)) { $wantedJob = ([string]$toolArgs.jobId).Trim() }
            $action = ''
            if ($toolArgs -and -not [string]::IsNullOrWhiteSpace([string]$toolArgs.action)) { $action = ([string]$toolArgs.action).Trim().ToLowerInvariant() }
            $jobsOut = New-Object System.Collections.Generic.List[object]
            foreach ($pair in @($Shared.MeshJobs.GetEnumerator())) {
                $job = Get-MeshJobData $Shared ([string]$pair.Key)
                if ($null -eq $job) { continue }
                if (-not [string]::IsNullOrWhiteSpace($wantedJob) -and [string]$job.id -ne $wantedJob) { continue }
                if (-not [string]::IsNullOrWhiteSpace($sid) -and [string]$job.sessionId -ne $sid) { continue }
                $slotRows = New-Object System.Collections.Generic.List[object]
                foreach ($slot in (Get-MeshSlotsBySession $Shared ([string]$job.sessionId) ([string]$job.id))) {
                    $slotRows.Add(@{
                        key = [string]$slot.slotKey
                        name = [string]$slot.slotName
                        state = [string]$slot.state
                        triangles = [int]$slot.triangles
                        size = $slot.size
                        bytes = $(try { [int64]$slot.bytes } catch { 0 })
                        fileName = [string]$slot.fileName
                        objPath = [string]$slot.objPath
                        fileExists = $(try { [bool](Test-Path -LiteralPath ([string]$slot.objPath)) } catch { $false })
                        assetId = [string]$slot.assetId
                        meshIdReadBack = $(try { [string]$slot.meshIdReadBack } catch { '' })
                        placeholderPath = [string]$slot.placeholderPath
                        error = [string]$slot.error
                    })
                }
                $jobsOut.Add(@{
                    jobId = [string]$job.id
                    modelName = [string]$job.modelName
                    state = [string]$job.state
                    folder = [string]$job.folder
                    createdAt = [int64]$job.createdAt
                    finishedAt = [int64]$job.finishedAt
                    placeholdersCreated = [bool]$job.placeholdersCreated
                    placeholderState = $(try { [string]$job.placeholderState } catch { '' })
                    parentRef = [string]$job.parentRef
                    origin = $job.origin
                    rotationY = [double]$job.rotationY
                    error = [string]$job.error
                    slots = $slotRows.ToArray()
                })
            }
            if ($action -eq 'placeholders') {
                # Platzhalter erneut anfordern (z.B. nachdem sie im Studio
                # geloescht wurden). Der UI-Takt schickt den Befehl.
                $reset = 0
                foreach ($pair in @($Shared.MeshJobs.GetEnumerator())) {
                    $job = Get-MeshJobData $Shared ([string]$pair.Key)
                    if ($null -eq $job) { continue }
                    if (-not [string]::IsNullOrWhiteSpace($wantedJob) -and [string]$job.id -ne $wantedJob) { continue }
                    if (-not [string]::IsNullOrWhiteSpace($sid) -and [string]$job.sessionId -ne $sid) { continue }
                    $job.placeholdersCreated = $false
                    $job.placeholderCommandId = ''
                    $job.placeholderState = 'requested'
                    Save-MeshJobData $Shared $job
                    $reset = $reset + 1
                }
                return @{ ok = $true; result = @{ requested = $reset; note = 'Die Platzhalter werden neu angefordert (der UI-Takt schickt den Befehl an Studio). Kurz darauf mesh_status erneut lesen.'; blender = $blenderReport } }
            }
            $needUpload = New-Object System.Collections.Generic.List[object]
            $applied = 0
            $failed = 0
            foreach ($job in $jobsOut) {
                foreach ($slot in $job.slots) {
                    $slotState = [string]$slot.state
                    if ($slotState -eq 'obj') {
                        # Version 7.4.1: Nur ECHT offene Dateien zaehlen. Eingesetzte
                        # Slots sind fertig - ihre OBJ ist nach dem Aufraeumen weg.
                        $needUpload.Add(@{
                            key = [string]$slot.key
                            name = [string]$slot.name
                            state = $slotState
                            triangles = [int]$slot.triangles
                            file = [string]$slot.objPath
                            fileExists = $(try { [bool](Test-Path -LiteralPath ([string]$slot.objPath)) } catch { $false })
                            assetId = [string]$slot.assetId
                        })
                    }
                    if ($slotState -eq 'applied') { $applied = $applied + 1 }
                    if ($slotState -in @('failed', 'rejected', 'apply_failed')) { $failed = $failed + 1 }
                }
            }
            $summary = 'Kein Mesh-Job in dieser Sitzung.'
            if ($jobsOut.Count -gt 0) {
                $summary = [string]$jobsOut.Count + ' Job(s): ' + [string]$applied + ' Slot(s) eingesetzt, ' + [string]$failed + ' Slot(s) mit Fehler.'
                if ($needUpload.Count -gt 0) {
                    $summary = $summary + ' Der Nutzer muss noch ' + [string]$needUpload.Count + ' Datei(en) hochladen und die Mesh-Id(s) im Bridge-Fenster "Mesh-Uploads" eintragen.'
                }
            }
            return @{
                ok = $true
                result = @{
                    blender = $blenderReport
                    jobs = $jobsOut.ToArray()
                    readyForUpload = $needUpload.ToArray()
                    appliedCount = [int]$applied
                    failedCount = [int]$failed
                    summary = $summary
                    note = 'Dateien liegen im Ordner meshFolder (je Job ein Unterordner). Roblox nimmt pro Mesh rund 10.000 Dreiecke an - mesh_status nennt die GEMESSENEN Zahlen. Ein Slot ueber der Grenze wird abgelehnt und muss einfacher gebaut werden.'
                }
            }
        }

        if ($tool -eq 'mesh_cancel') {
            $wantedJob = ''
            if ($toolArgs -and -not [string]::IsNullOrWhiteSpace([string]$toolArgs.jobId)) { $wantedJob = ([string]$toolArgs.jobId).Trim() }
            if ([string]::IsNullOrWhiteSpace($wantedJob)) {
                $newest = [int64]0
                foreach ($pair in @($Shared.MeshJobs.GetEnumerator())) {
                    $job = Get-MeshJobData $Shared ([string]$pair.Key)
                    if ($null -eq $job) { continue }
                    if (-not [string]::IsNullOrWhiteSpace($sid) -and [string]$job.sessionId -ne $sid) { continue }
                    if ([string]$job.state -in @('measured', 'failed', 'cancelled')) { continue }
                    $created = 0
                    try { $created = [int64]$job.createdAt } catch {}
                    if ($created -ge $newest) { $newest = $created; $wantedJob = [string]$job.id }
                }
            }
            if ([string]::IsNullOrWhiteSpace($wantedJob)) {
                return (To-Json @{ ok = $false; code = 'NO_JOB'; error = 'Es laeuft kein Mesh-Job, der abgebrochen werden koennte.' } 12)
            }
            $stopped = Stop-MeshJob $Shared $wantedJob
            return @{ ok = [bool]$stopped; result = @{ jobId = $wantedJob; cancelled = [bool]$stopped; note = $(if ($stopped) { 'Der Job wird beendet; die OBJ-Datei kann unvollstaendig sein und wird verworfen.' } else { 'Der Job war schon fertig oder unbekannt - nichts wurde abgebrochen.' }) } }
        }

        if ($tool -eq 'mesh_apply_asset') {
            $entries = New-Object System.Collections.Generic.List[object]
            $problems = New-Object System.Collections.Generic.List[string]
            $slotsRaw = @()
            if ($toolArgs -and $null -ne $toolArgs.slots) { $slotsRaw = @($toolArgs.slots) }
            foreach ($raw in $slotsRaw) {
                if ($null -eq $raw) { continue }
                $key = ([string]$raw.key).Trim()
                $digits = ''
                try { $digits = ([regex]::Match([string]$raw.assetId, '(\d+)')).Groups[1].Value } catch {}
                if ([string]::IsNullOrWhiteSpace($key)) { $problems.Add('Ein Eintrag ohne key wurde uebersprungen.'); continue }
                if ([string]::IsNullOrWhiteSpace($digits)) { $problems.Add($key + ': keine numerische assetId.'); continue }
                $slot = Get-MeshSlotData $Shared $key
                if ($null -eq $slot) { $problems.Add($key + ': unbekannter Slot (mesh_status zeigt die gueltigen keys).'); continue }
                Set-MeshSlotField $Shared $key 'assetId' $digits
                Set-MeshSlotField $Shared $key 'state' 'applying'
                Set-MeshSlotField $Shared $key 'error' ''
                $entries.Add(@{ key = $key; assetId = $digits })
            }
            if ($entries.Count -eq 0) {
                return (To-Json @{
                    ok = $false
                    code = 'BAD_ARGS'
                    error = 'Kein gueltiger Eintrag: mesh_apply_asset braucht slots = [ { key, assetId } ] mit den keys aus mesh_status.'
                    problems = $problems.ToArray()
                } 20)
            }
            $pluginArgs = @{ slots = $entries.ToArray() }
            $rawResult = Invoke-PluginTool $sid 'mesh_apply' $pluginArgs 180 ''
            if ([string]::IsNullOrWhiteSpace([string]$rawResult)) {
                foreach ($entry in $entries) {
                    Set-MeshSlotField $Shared ([string]$entry.key) 'state' 'apply_failed'
                    Set-MeshSlotField $Shared ([string]$entry.key) 'error' 'Studio hat nicht geantwortet (Zeitlimit).'
                }
                return (To-Json @{
                    ok = $false
                    code = 'STUDIO_UNREACHABLE_OR_TIMEOUT'
                    error = 'Roblox Studio hat nicht rechtzeitig geantwortet - es wurde NICHTS eingesetzt. Den Zustand mit mesh_status pruefen und erst dann erneut versuchen (nicht in einer Schleife).'
                    applied = @()
                    problems = $problems.ToArray()
                } 20)
            }
            $appliedOk = $false
            try { $appliedOk = [bool](Update-MeshRegistryFromApplyResult $Shared ([string]$rawResult)) } catch {}
            $pluginView = $null
            try { $pluginView = ([string]$rawResult | ConvertFrom-Json) } catch {}
            $rows = New-Object System.Collections.Generic.List[object]
            foreach ($entry in $entries) {
                $slot = Get-MeshSlotData $Shared ([string]$entry.key)
                $rows.Add(@{
                    key = [string]$entry.key
                    state = $(try { [string]$slot.state } catch { 'unknown' })
                    assetId = $(try { [string]$slot.assetId } catch { '' })
                    meshIdReadBack = $(try { [string]$slot.meshIdReadBack } catch { '' })
                    path = $(try { [string]$slot.placeholderPath } catch { '' })
                    error = $(try { [string]$slot.error } catch { '' })
                })
            }
            return @{
                ok = [bool]$appliedOk
                result = @{
                    applied = $rows.ToArray()
                    pluginResult = $(if ($null -ne $pluginView) { $pluginView } else { [string]$rawResult })
                    problems = $problems.ToArray()
                    note = $(if ($appliedOk) { 'Die Geometrie sitzt in den BESTEHENDEN MeshParts: Groesse, Position, Welds, Attribute und Animationen bleiben erhalten. meshIdReadBack ist der Wert, den der Place wirklich liest.' } else { 'Es wurde nichts eingesetzt. Die Fehlermeldung je Slot steht oben - meistens ist die Platzhalter-Instanz weg (verschoben/geloescht) oder die Asset-Id gehoert nicht zum eigenen Konto.' })
                }
            }
        }

        return $null
    }

    function Invoke-ServerTool($sessionId, [string]$tool, $toolArgs) {
        switch ($tool) {
            # Version 7.1.2: nicht mehr direkt - immer ueber das Toolbox-Tor
            # (Begrenzung gleichzeitiger Aufrufe, garantierte Freigabe).
            'search_assets'      { return (Invoke-ToolboxServerTool $sessionId $tool $toolArgs) }
            'asset_details'      { return (Invoke-ToolboxServerTool $sessionId $tool $toolArgs) }
            'validate_asset'     { return (Invoke-ToolboxServerTool $sessionId $tool $toolArgs) }
            'catalog_status'     { return (Invoke-ToolboxServerTool $sessionId $tool $toolArgs) }
            # Version 7.4.0: Blender + Mesh-Bau. Laeuft im Bridge-Prozess, weil
            # Blender und die OBJ-Messung nicht in Studio stattfinden.
            'blender_status'     { return (Invoke-MeshServerTool $sessionId $tool $toolArgs) }
            'build_mesh_model'   { return (Invoke-MeshServerTool $sessionId $tool $toolArgs) }
            'mesh_status'        { return (Invoke-MeshServerTool $sessionId $tool $toolArgs) }
            'mesh_cancel'        { return (Invoke-MeshServerTool $sessionId $tool $toolArgs) }
            'mesh_apply_asset'   { return (Invoke-MeshServerTool $sessionId $tool $toolArgs) }
            'get_docs' {
                $qTool = if ($toolArgs.tool) { [string]$toolArgs.tool } else { $null }
                $qCategory = if ($toolArgs.category) { [string]$toolArgs.category } else { $null }
                $qFull = if ($toolArgs.full -eq $true) { 'true' } else { $null }
                return (Get-DocsResponse $qTool $qCategory $qFull)
            }
            'get_bridge_log' {
                # Version 7.0.6: die KI liest die Logs SELBST, statt den Nutzer
                # nach Dateien zu fragen. Immer mit Waechter- und
                # Zustell-Zustand, damit die Zeilen einordbar sind.
                $logLines = 120
                if ($toolArgs -and $toolArgs.lines) { $logLines = [int]$toolArgs.lines }
                if ($logLines -lt 10) { $logLines = 10 }
                if ($logLines -gt 500) { $logLines = 500 }
                $whichFile = 'runtime'
                if ($toolArgs -and $toolArgs.file) { $whichFile = ([string]$toolArgs.file).Trim().ToLowerInvariant() }
                $logPath = ''
                if ($whichFile -eq 'performance' -or $whichFile -eq 'perf') {
                    $logPath = [string]$Shared.RuntimeInfo.PerfFile
                    $whichFile = 'performance'
                } else {
                    $logPath = [string]$Shared.RuntimeInfo.LogFile
                    $whichFile = 'runtime'
                }
                $linesOut = New-Object System.Collections.Generic.List[string]
                $fileExists = $false
                $fileError = ''
                try {
                    if (-not [string]::IsNullOrWhiteSpace($logPath) -and (Test-Path -LiteralPath $logPath)) {
                        $fileExists = $true
                        $all = [System.IO.File]::ReadAllLines($logPath)
                        $start = [Math]::Max(0, $all.Length - $logLines)
                        for ($i = $start; $i -lt $all.Length; $i++) { $linesOut.Add([string]$all[$i]) }
                    } else {
                        $fileError = 'Die Datei existiert noch nicht.'
                    }
                } catch { $fileError = $_.Exception.Message }
                return @{
                    ok = $true
                    result = @{
                        file = $whichFile
                        path = $logPath
                        exists = $fileExists
                        error = $fileError
                        requestedLines = $logLines
                        returnedLines = $linesOut.Count
                        lines = $linesOut.ToArray()
                        deployment = @{
                            version = [string]$Shared.RuntimeInfo.Version
                            file = [string]$Shared.RuntimeInfo.File
                            sha256 = [string]$Shared.RuntimeInfo.Sha256
                            startedAt = [int64]$Shared.RuntimeInfo.StartedAt
                        }
                        sweep = @{
                            running = ([int64]$Shared.SweepState.LastSweepAt -gt 0 -and ((Get-UnixSeconds) - [int64]$Shared.SweepState.LastSweepAt) -le 10)
                            secondsSinceSweep = $(if ([int64]$Shared.SweepState.LastSweepAt -gt 0) { [int][Math]::Max(0, (Get-UnixSeconds) - [int64]$Shared.SweepState.LastSweepAt) } else { -1 })
                            abandonedTotal = [int64]$Shared.SweepState.Abandoned
                        }
                        delivery = (Get-StudioDeliveryHealth $sessionId)
                        note = 'runtime.log enthaelt die Laufzeit-Identitaet (Version, Datei, SHA-256), jede Sitzungs-Anmeldung, jede Zustellung und jeden Waechter-Abbruch. performance.txt erscheint nur, wenn der Nutzer die Leistungsdiagnose eingeschaltet hat.'
                    }
                }
            }
            'get_pending' {
                $pending = Get-PendingCommands $sessionId
                $late = Take-LateResults $sessionId
                return @{
                    ok = $true
                    result = @{
                        runningInStudio = $pending
                        lateResults     = $late
                        count           = $pending.Count
                        note = 'Commands in runningInStudio are tracked by commandId and execute serially. HTTP timeouts do not immediately discard them; an executor heartbeat/budget watchdog eventually abandons a dead or hung command and reports whether partial changes may have occurred.'
                    }
                }
            }
            'capture_screenshot' { return (Invoke-Screenshot $toolArgs) }
            'handoff'            { return (Invoke-HandoffWrite $sessionId $toolArgs) }
            'get_chunk' {
                $index = 1
                if ($toolArgs.index) { $index = [int]$toolArgs.index }
                return (Get-BlobChunk ([string]$toolArgs.blobId) $index)
            }
            'upload_text' {
                $uploadId = [string]$toolArgs.uploadId
                if ([string]::IsNullOrWhiteSpace($uploadId)) {
                    $uploadId = 'up_' + [guid]::NewGuid().ToString('N').Substring(0, 12)
                }
                $existing = ''
                [void]$Shared.Uploads.TryGetValue($uploadId, [ref]$existing)
                $chunkIndex = 1
                if ($toolArgs.chunkIndex) { $chunkIndex = [int]$toolArgs.chunkIndex }
                if ($chunkIndex -le 1) { $existing = '' }
                $Shared.Uploads[$uploadId] = $existing + [string]$toolArgs.text
                $chunkCount = 1
                if ($toolArgs.chunkCount) { $chunkCount = [int]$toolArgs.chunkCount }
                $complete = ($chunkIndex -ge $chunkCount)
                return @{
                    ok = $true
                    result = @{
                        uploadId = $uploadId
                        chars = $Shared.Uploads[$uploadId].Length
                        complete = $complete
                        useAs = 'Pass sourceRef = "' + $uploadId + '" instead of source in set_script_source / insert_script.'
                    }
                }
            }
            'report_done' {
                # Version 7.0.0: report_done setzt fehlende 100 selbst und
                # vermerkt "Automatisch gesetzt". Platzhalter/Blockouts im Place
                # verwandeln ein "fertig" in HANDOFF_REQUIRED.
                try {
                    $auditJson = ''
                    if ($Shared.AuditFlags.TryGetValue([string]$sessionId, [ref]$auditJson) -and -not [string]::IsNullOrWhiteSpace($auditJson)) {
                        $audit = $auditJson | ConvertFrom-Json
                        $handoffState = ''
                        [void]$Shared.Handoffs.TryGetValue([string]$sessionId, [ref]$handoffState)
                        # Version 7.4.0: Offene Mesh-Platzhalter sind KEIN
                        # vergessener Platzhalter, sondern warten auf den Upload
                        # des Nutzers. "Fertig" waere hier eine Luege - der
                        # ehrliche Code ist MESH_UPLOAD_PENDING.
                        $meshSlotCount = 0
                        $meshSlots = @()
                        try { if ($audit.PSObject.Properties['meshSlotCount']) { $meshSlotCount = [int]$audit.meshSlotCount } } catch {}
                        try { if ($audit.PSObject.Properties['meshSlots']) { $meshSlots = @($audit.meshSlots) } } catch {}
                        if ($meshSlotCount -gt 0 -and [string]::IsNullOrWhiteSpace($handoffState)) {
                            $waitingKeys = New-Object System.Collections.Generic.List[string]
                            foreach ($slot in $meshSlots) {
                                try {
                                    if ([string]$slot.state -eq 'applied') { continue }
                                    $label = [string]$slot.name
                                    if ([string]::IsNullOrWhiteSpace($label)) { $label = [string]$slot.key }
                                    if (-not [string]::IsNullOrWhiteSpace($label)) { $waitingKeys.Add($label) }
                                } catch {}
                            }
                            $waitCount = $waitingKeys.Count
                            if ($waitCount -gt 0) {
                                return @{
                                    ok = $false
                                    code = 'MESH_UPLOAD_PENDING'
                                    error = ('This place contains ' + [string]$waitCount + ' mesh placeholder(s) that still wait for the mesh upload: ' + ($waitingKeys.ToArray() -join ', ') + '. A placeholder is a box, not the model. Roblox has no automatic mesh upload - the USER must upload the OBJ file(s) and enter the mesh id(s) in the bridge window "Mesh-Uploads" (or tell you the id, then call mesh_apply_asset). Tell him that honestly instead of reporting done.')
                                    meshPlaceholders = $waitingKeys.ToArray()
                                    meshFolder = [string]$Shared.MeshRoot
                                    howToFix = 'Read mesh_status: it names the exact file per slot. Tell the user, in German, where the files are (bridge window "Mesh-Uploads" has an "Ordner öffnen" button), that he must upload them in Roblox Studio (3D Importer / drag and drop) or the Creator Dashboard, and that he enters the id in that window - then the bridge inserts the geometry automatically. After that run model_audit again and report done. If the work is genuinely handed over, call handoff { scope="game", ... } instead.'
                                }
                            }
                        }
                        if ([int]$audit.placeholderCount -gt 0 -and [string]::IsNullOrWhiteSpace($handoffState)) {
                            return @{
                                ok = $false
                                code = 'HANDOFF_REQUIRED'
                                error = ('This place still contains ' + [string]$audit.placeholderCount + ' marked placeholder(s). Do not report "done" yet - write the handoff now: call handoff { scope="game", ... } with the completed stage, the exact next steps and the open placeholders.')
                                placeholders = $audit.placeholders
                                howToFix = 'Finish the current stage completely, then call handoff. That is an invitation, not a punishment.'
                            }
                        }
                        # Version 7.1.3: Bauqualitaet. Ein Kugel-Tier oder ein
                        # falsch gedrehter Zylinder ist kein fertiges Modell -
                        # die Bridge sagt das jetzt selbst, statt es
                        # durchzuwinken. Ausweg: nachbauen ODER ehrlich
                        # uebergeben (handoff).
                        $primitiveAbuseNow = $false
                        $cylinderProblemsNow = 0
                        try { if ($audit.PSObject.Properties['primitiveAbuse']) { $primitiveAbuseNow = [bool]$audit.primitiveAbuse } } catch {}
                        try { if ($audit.PSObject.Properties['cylinderProblemCount']) { $cylinderProblemsNow = [int]$audit.cylinderProblemCount } } catch {}
                        if (($primitiveAbuseNow -or $cylinderProblemsNow -gt 0) -and [string]::IsNullOrWhiteSpace($handoffState)) {
                            $groupNames = New-Object System.Collections.Generic.List[string]
                            try {
                                foreach ($group in $audit.primitiveGroups) {
                                    $label = [string]$group.name
                                    if ([string]::IsNullOrWhiteSpace($label)) { $label = [string]$group.path }
                                    if (-not [string]::IsNullOrWhiteSpace($label)) { $groupNames.Add(('"' + $label + '" (' + [string]$group.balls + ' balls)')) }
                                }
                            } catch {}
                            $qualityReason = ''
                            if ($primitiveAbuseNow) {
                                $qualityReason = 'model_audit measured a PRIMITIVE-ONLY build: ' + [string]$groupNames.Count + ' group(s) consist only of Ball parts'
                                if ($groupNames.Count -gt 0) { $qualityReason = $qualityReason + ' - ' + ($groupNames.ToArray() -join ', ') }
                                $qualityReason = $qualityReason + '.'
                            }
                            if ($cylinderProblemsNow -gt 0) {
                                if ($qualityReason) { $qualityReason = $qualityReason + ' ' }
                                $qualityReason = $qualityReason + ('model_audit measured ' + [string]$cylinderProblemsNow + ' cylinder(s) whose tube axis lies horizontally while the part is far wider than long - they stand as discs on their edge, the classic 90-degree error. A Roblox CylinderPart runs along its LOCAL X axis, so Size.X must be the length (CFrame.Angles(0, 0, math.rad(90)) for upright, or cylinderBetween from organicBuildRules).')
                            }
                            return @{
                                ok = $false
                                code = 'DETAIL_REQUIRED'
                                error = ($qualityReason + ' report_done does not accept this as finished work - a ball-only animal or a sideways cylinder is a draft, not a model.')
                                buildQuality = @{
                                    verdict = [string]$audit.buildQualityVerdict
                                    primitiveAbuse = $primitiveAbuseNow
                                    primitiveGroups = $audit.primitiveGroups
                                    cylinderProblemCount = $cylinderProblemsNow
                                }
                                howToFix = 'Either rebuild it (build the silhouette with build_polygon_model, use the cylinder rule and the reference helpers from organicBuildRules, then run model_audit again) OR - if this really is a deliberate blockout or the user asked for primitives - call handoff { scope="object"/"scene"/"game", ... } saying exactly that. That is an invitation, not a punishment.'
                            }
                        }
                    }
                    # Version 7.2.0 (AP6): ENTWURFS-SPERRE. Der Audit nennt seit
                    # 7.2.0 eine Note. Ist sie 'draft' (wenige Teile, kein Polygon/
                    # Mesh/Union/Detail, ueber 60 % primitive), ist das kein
                    # fertiges Modell - genau der Fall "Baum = Zylinder + Kugeln".
                    # Ausweg: nachbauen ODER die Einfachheit beim Bauen erklaeren
                    # (grade = simple/lowpoly/blockout) und erneut auditieren.
                    if ($audit) {
                        $draftRiskNow = $false
                        $draftGradeNow = ''
                        $draftScoreNow = -1
                        try { if ($audit.PSObject.Properties['draftRisk']) { $draftRiskNow = [bool]$audit.draftRisk } } catch {}
                        try { if ($audit.PSObject.Properties['buildGrade']) { $draftGradeNow = [string]$audit.buildGrade } } catch {}
                        try { if ($audit.PSObject.Properties['finishScore']) { $draftScoreNow = [int]$audit.finishScore } } catch {}
                        if ($draftRiskNow -and [string]::IsNullOrWhiteSpace($handoffState)) {
                            Add-ChannelCount 'BuildAuditDemands' 1
                            Add-ChannelCount 'QualityDraftFlags' 1
                            Write-FlowStation 'BUILD' $sessionId 'DRAFT_BLOCKED' @{ grade = $draftGradeNow; finishScore = $draftScoreNow }
                            return @{
                                ok = $false
                                code = 'DRAFT_GRADE_RISK'
                                error = ('model_audit graded this build as a DRAFT (grade "' + $draftGradeNow + '", ' + [string]$draftScoreNow + '/100): few parts, no polygon/mesh/union/detail geometry, almost everything primitive. That is not finished work.')
                                buildQuality = @{
                                    verdict = [string]$audit.buildQualityVerdict
                                    grade = $draftGradeNow
                                    finishScore = $draftScoreNow
                                    draftRisk = $true
                                }
                                howToFix = 'Either rebuild it (real silhouette with build_polygon_model, details, palette - see modelBuildRules/organicBuildRules, then model_audit again) OR - if the simplicity is what the user asked for - declare it while building (build_polygon_model/build_assembly { grade = "simple" | "lowpoly" | "blockout" }) and run model_audit again. Or hand off honestly with handoff {...}.'
                            }
                        }
                    }
                    # Organic quality is a separate, per-model proof. It is
                    # required even when AuditFlags is empty, and any later
                    # successful write invalidates the proof until re-audited.
                    $organicJson = ''
                    $hasOrganicState = $false
                    try { $hasOrganicState = $Shared.OrganicBuilds.TryGetValue([string]$sessionId, [ref]$organicJson) } catch {
                        return @{
                            ok = $false
                            code = 'ORGANIC_AUDIT_REQUIRED'
                            error = 'Organic completion state could not be read safely; report_done fails closed.'
                            howToFix = 'Keep working and rerun model_audit for every registered organic model before trying report_done again.'
                        }
                    }
                    if ($hasOrganicState) {
                        if ([string]::IsNullOrWhiteSpace($organicJson)) {
                            return @{
                                ok = $false
                                code = 'ORGANIC_AUDIT_REQUIRED'
                                error = 'Organic completion state exists but is empty; report_done fails closed.'
                                howToFix = 'Rerun model_audit for every registered organic model before trying report_done again.'
                            }
                        }
                        $organicState = $null
                        try { $organicState = $organicJson | ConvertFrom-Json } catch {
                            return @{
                                ok = $false
                                code = 'ORGANIC_AUDIT_REQUIRED'
                                error = 'Organic completion state could not be decoded; report_done fails closed.'
                                howToFix = 'Rerun model_audit for every registered organic model before trying report_done again.'
                            }
                        }
                        if ($null -eq $organicState -or $organicState.required -ne $true) {
                            return @{
                                ok = $false
                                code = 'ORGANIC_AUDIT_REQUIRED'
                                error = 'Organic work is registered but its required per-model state is incomplete; report_done fails closed.'
                                howToFix = 'Rerun model_audit for every registered organic model before trying report_done again.'
                            }
                        }
                            $organicRecords = @()
                            try { $organicRecords = @($organicState.models) } catch {}
                            if ($organicRecords.Count -eq 0 -and $organicState.PSObject.Properties['modelId']) { $organicRecords = @($organicState) }
                            if ($organicRecords.Count -eq 0) {
                                return @{
                                    ok = $false; code = 'ORGANIC_AUDIT_REQUIRED'
                                    error = 'Organic work is registered for this Place, but no per-model audit record is available.'
                                    howToFix = 'Run model_audit by itself on each returned organic model id after its final edit.'
                                }
                            }
                            foreach ($organicRecord in $organicRecords) {
                                $lastWriteAtTicks = 0L
                                $auditAtTicks = 0L
                                try { $lastWriteAtTicks = [int64]$organicRecord.lastWriteAtTicks } catch {}
                                try { $auditAtTicks = [int64]$organicRecord.auditAtTicks } catch {}
                                if ($auditAtTicks -le 0 -or $auditAtTicks -lt $lastWriteAtTicks) {
                                    return @{
                                        ok = $false
                                        code = 'ORGANIC_AUDIT_REQUIRED'
                                        error = 'At least one organic model has no fresh model_audit after the latest successful Place write. report_done cannot verify all organic geometry, palettes or installed animations.'
                                        expectedModel = @{ id = [string]$organicRecord.modelId; path = [string]$organicRecord.modelPath; name = [string]$organicRecord.modelName }
                                        howToFix = 'Run model_audit { ref = <this model id> } after the final Place write for every returned organic model. If any later Place write succeeds, audit every registered organic model again.'
                                        lastWriteAtTicks = $lastWriteAtTicks
                                        auditAtTicks = $auditAtTicks
                                    }
                                }
                                $organicQuality = $organicRecord.auditQuality
                                if ($null -eq $organicQuality -or $organicQuality.detected -ne $true) {
                                    return @{
                                        ok = $false
                                        code = 'ORGANIC_AUDIT_REQUIRED'
                                        error = 'A fresh audit did not find a required organic model. A generated source file, unrelated model or audit without per-model evidence is not proof.'
                                        expectedModel = @{ id = [string]$organicRecord.modelId; path = [string]$organicRecord.modelPath; name = [string]$organicRecord.modelName }
                                        auditedScope = [string]$organicRecord.auditScope
                                        howToFix = 'Audit the exact returned model id and confirm organicQuality.detected=true with a matching model entry.'
                                    }
                                }
                                $expectedModelId = [string]$organicRecord.modelId
                                $expectedModelPath = [string]$organicRecord.modelPath
                                $matchingOrganicModel = $null
                                foreach ($candidate in @($organicRecord.auditModels)) {
                                    if (-not [string]::IsNullOrWhiteSpace($expectedModelId) -and [string]$candidate.id -eq $expectedModelId) { $matchingOrganicModel = $candidate; break }
                                    if ([string]::IsNullOrWhiteSpace($expectedModelId) -and -not [string]::IsNullOrWhiteSpace($expectedModelPath) -and [string]$candidate.path -eq $expectedModelPath) { $matchingOrganicModel = $candidate; break }
                                }
                                if ($null -eq $matchingOrganicModel) {
                                    return @{
                                        ok = $false
                                        code = 'ORGANIC_AUDIT_REQUIRED'
                                        error = 'The fresh audit does not contain per-model evidence for the exact organic model.'
                                        expectedModel = @{ id = $expectedModelId; path = $expectedModelPath; name = [string]$organicRecord.modelName }
                                        howToFix = 'Run model_audit by itself with this exact model id; a workspace-level aggregate without a matching model entry is insufficient.'
                                    }
                                }
                                $organicIssues = @($organicQuality.issues)
                                $modelTriangles = 0
                                $modelUniqueColors = 0
                                $modelDominantShare = 0.0
                                $modelNearWhiteShare = 0.0
                                $modelMotionScripts = 0
                                try { $modelTriangles = [int]$matchingOrganicModel.polygonTriangles } catch {}
                                try { $modelUniqueColors = [int]$matchingOrganicModel.uniqueColors } catch {}
                                try { $modelDominantShare = [double]$matchingOrganicModel.dominantColorShare } catch {}
                                try { $modelNearWhiteShare = [double]$matchingOrganicModel.nearWhiteShare } catch {}
                                try { $modelMotionScripts = [int]$matchingOrganicModel.motionScripts } catch {}
                                $organicIssues += @($matchingOrganicModel.issues)
                                if ($modelTriangles -le 0) { $organicIssues += 'NO_POLYGON_GEOMETRY: the exact organic model has no actual ArenaPolygonTriangle wedges.' }
                                if ($modelUniqueColors -lt 3) { $organicIssues += 'PALETTE_TOO_FLAT: the exact organic model has fewer than three measured colours.' }
                                if ($modelDominantShare -gt 0.90) { $organicIssues += 'PALETTE_TOO_FLAT: one measured colour covers more than 90% of the exact organic model.' }
                                if ($modelNearWhiteShare -gt 0.90) { $organicIssues += 'PALETTE_TOO_FLAT: more than 90% of the exact organic model is near-white/default-looking.' }
                                if ($modelMotionScripts -le 0) { $organicIssues += 'ANIMATION_NOT_INSTALLED: the exact organic model has no enabled motion Script detected beneath it.' }
                                if ($organicIssues.Count -gt 0) {
                                    return @{
                                        ok = $false
                                        code = 'DETAIL_REQUIRED'
                                        error = ('Organic quality is not verified as complete: ' + (($organicIssues | Select-Object -Unique) -join ' '))
                                        organicQuality = $organicQuality
                                        expectedModel = @{ id = $expectedModelId; path = $expectedModelPath; name = [string]$organicRecord.modelName }
                                        measuredModel = @{ polygonTriangles = $modelTriangles; uniqueColors = $modelUniqueColors; dominantColorShare = $modelDominantShare; nearWhiteShare = $modelNearWhiteShare; motionScripts = $modelMotionScripts; creatureMetrics = $matchingOrganicModel.creatureMetrics }
                                        howToFix = 'Build with build_polygon_model { organic=true, organicKind=creature } and closed body/head loft volumes, role-tag physical bilateral eyes/pupils and any wings, assign three contrasting colours, install an enabled motion Script under the model, fix every organicQuality issue, then model_audit again.'
                                    }
                                }
                            }
                        }
                } catch {
                    # Fail closed if any completion-proof validation failed while
                    # this Place has registered organic work. The old catch was
                    # intentionally quiet for legacy checks, but must never turn
                    # a malformed organic record into an unsupported done claim.
                    $validationError = [string]$_.Exception.Message
                    $registeredOrganicJson = ''
                    $registeredOrganic = $false
                    try { $registeredOrganic = $Shared.OrganicBuilds.TryGetValue([string]$sessionId, [ref]$registeredOrganicJson) } catch {}
                    if ($registeredOrganic) {
                        return @{
                            ok = $false
                            code = 'ORGANIC_AUDIT_REQUIRED'
                            error = 'Organic completion validation failed; report_done fails closed and does not accept an unsupported completion claim.'
                            validationError = $validationError
                            howToFix = 'Inspect the reported validation error, then run model_audit by itself for every registered organic model after the final Place write.'
                        }
                    }
                }
                $doneProgress = Read-ProgressState $sessionId
                if ($null -eq $doneProgress -or [double]$doneProgress.percent -lt 100) {
                    Update-ArenaProgressState $sessionId 'report_done' 100.0 'Automatisch gesetzt (report_done)' $false $true $true | Out-Null
                } else {
                    Update-ArenaProgressState $sessionId 'report_done' 100.0 ([string]$doneProgress.message) $true $true $false | Out-Null
                }
                # Version 3.8: Arena meldet "fertig" - der Nutzer bekommt eine
                # Windows-Benachrichtigung (nur wenn er das aktiviert hat).
                # Version 7.2.0 (AP6): Das Bau-Register gehoert in JEDE
                # report_done-Antwort - auch wenn die Fertig-Meldung aus ist.
                # Es sagt ehrlich, was gebaut und was davon geprueft wurde.
                $buildRegister = Get-SessionBuildSummary $sessionId
                $buildRegisterNote = ''
                if ($buildRegister.models -gt 0) {
                    $buildRegisterNote = ('Build register: ' + [string]$buildRegister.models + ' model(s) built in this session, ' + [string]$buildRegister.audited + ' audited.')
                    if (@($buildRegister.unaudited).Count -gt 0) {
                        $names = New-Object System.Collections.Generic.List[string]
                        foreach ($entry in @($buildRegister.unaudited)) {
                            $label = [string]$entry.name
                            if ([string]::IsNullOrWhiteSpace($label)) { $label = [string]$entry.path }
                            if (-not [string]::IsNullOrWhiteSpace($label)) { $names.Add('"' + $label + '"') }
                        }
                        $buildRegisterNote = $buildRegisterNote + ' NOT verified by model_audit: ' + ($names.ToArray() -join ', ') + '. Nothing measured this geometry - run model_audit on it.'
                        Add-ChannelCount 'BuildAuditDemands' 1
                        Write-FlowStation 'BUILD' $sessionId 'UNAUDITED' @{ models = $buildRegister.models; unaudited = @($buildRegister.unaudited).Count }
                    }
                    if (@($buildRegister.drafts).Count -gt 0) {
                        Add-ChannelCount 'QualityDraftFlags' 1
                    }
                }
                $notifyOn = $false
                try { $notifyOn = [bool]$Shared.BridgeSettings.notifyOnDone } catch {}
                if (-not $notifyOn) {
                    return @{
                        ok = $false
                        code = 'NOTIFICATIONS_DISABLED'
                        buildRegister = $buildRegister
                        buildRegisterNote = $buildRegisterNote
                        error = 'report_done is not active: the user has NOT enabled finish notifications in the Arena Roblox Bridge settings.'
                        hint = 'Nothing is wrong - simply finish your answer normally. Do not call report_done again in this session.'
                    }
                }
                $doneTitle = ''
                $doneMessage = ''
                if ($toolArgs -and $toolArgs.title) { $doneTitle = ([string]$toolArgs.title).Trim() }
                if ($toolArgs -and $toolArgs.message) { $doneMessage = ([string]$toolArgs.message).Trim() }
                if ([string]::IsNullOrWhiteSpace($doneTitle) -or [string]::IsNullOrWhiteSpace($doneMessage)) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'title and message are required. Write a lively German notification, for example title="✅ Arena hat den Lauf-Bug behoben!", message="Der Lauf-Bug ist weg – komm ins Spiel und probiere es aus!".'; limits = @{ titleCharacters = 70; messageCharacters = 140 } }
                }
                if ($doneTitle.Length -gt 70) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'title is too long for the Windows 11 display budget (max 70 characters). Rewrite it instead of letting Windows truncate it.'; actual = $doneTitle.Length; max = 70 }
                }
                if ($doneMessage.Length -gt 140) {
                    return @{ ok = $false; code = 'BAD_ARGS'; error = 'message is too long for the Windows 11 display budget (max 140 characters). Rewrite it as one inviting sentence.'; actual = $doneMessage.Length; max = 140 }
                }
                $doneEntry = Get-SessionEntry $sessionId
                $donePlace = 'Place'
                if ($doneEntry) { $donePlace = [string]$doneEntry.placeName }
                # Version 7.2.0 (D4): Jede Meldung bekommt eine Flow-Id, die
                # ENQUEUED -> PLATFORM -> CALL -> SWEEP verbindet. Vorher stand
                # im Protokoll "Arena-Fertig-Meldung angezeigt", ohne dass
                # irgendjemand wusste, ob Windows sie wirklich gezeichnet hat.
                $notifyFlowSeq = [long]0
                try {
                    $notifyFlowSeq = [long]$Shared.Channel['NotifyFlowSeq'] + 1
                    $Shared.Channel['NotifyFlowSeq'] = $notifyFlowSeq
                } catch {}
                $notifyFlowId = 'n-' + [string]$notifyFlowSeq
                $platformVerdict = 'UNKNOWN'
                $platformReason = 'Die Oberflaeche hat die Plattform noch nicht gemessen.'
                $platformAppId = $false
                try {
                    $platformJson = [string]$Shared.NotifyPlatformJson
                    if (-not [string]::IsNullOrWhiteSpace($platformJson)) {
                        $platformView = $platformJson | ConvertFrom-Json
                        $platformVerdict = [string]$platformView.verdict
                        $platformReason = [string]$platformView.reason
                        $platformAppId = [bool]$platformView.appUserModelIdRegistered
                    }
                } catch {}
                $donePayload = @{
                    flowId = $notifyFlowId
                    place = $donePlace
                    title = $doneTitle
                    message = $doneMessage
                    time = (Get-Date).ToString('u')
                    queuedAt = (Get-UnixSeconds)
                }
                $Shared.NotifyQueue.Enqueue((To-Json $donePayload 8))
                Add-ChannelCount 'NotifyEnqueued' 1
                Write-FlowStation 'NOTIFY' $notifyFlowId 'ENQUEUED' @{ place = $donePlace; platform = $platformVerdict; aumidRegistered = $platformAppId; title = $doneTitle }
                Add-BridgeEvent $sessionId 'arena_done' ("The assistant reported it is done: " + $doneMessage) @{ place = $donePlace }
                $notifyVerified = ($platformVerdict -eq 'READY')
                $notifyResult = @{
                    queued = $true
                    delivered = $notifyVerified
                    buildRegister = $buildRegister
                    buildRegisterNote = $buildRegisterNote
                    flowId = $notifyFlowId
                    title = $doneTitle
                    message = $doneMessage
                    limits = @{ titleCharacters = 70; messageCharacters = 140 }
                    notification = @{
                        flowId = $notifyFlowId
                        state = 'QUEUED'
                        settingEnabled = $true
                        platformVerdict = $platformVerdict
                        platformReason = $platformReason
                        appUserModelIdRegistered = $platformAppId
                        verified = $false
                        verification = 'notify.sweep re-measures the platform a few seconds after the call and writes the verdict (SHOWN or SHOWN_UNVERIFIED plus reason) to notify-diagnose.txt. Windows has no API that confirms a toast was drawn, so "verified" here means: no suppression was measurable.'
                        diagnoseFile = '%LOCALAPPDATA%\ArenaRobloxBridge\notify-diagnose.txt'
                    }
                    note = 'The user is being notified on their PC right now. This was your LAST action: make no further changes and no further tool calls - end your response now with your final summary.'
                }
                if (-not $notifyVerified) {
                    $notifyResult.notificationWarning = 'NOTIFICATION_UNVERIFIED'
                    $notifyResult.honest = ('The finish notification was queued, but Windows may suppress it right now: ' + $platformVerdict + ' - ' + $platformReason + ' Do NOT claim the user was notified. Say in your reply what you finished and that the Windows notification may not appear.')
                    Write-FlowStation 'NOTIFY' $notifyFlowId 'UNVERIFIED' @{ verdict = $platformVerdict; reason = $platformReason }
                }
                return @{ ok = $true; result = $notifyResult }
            }
            'get_events' {
                $events = Take-Events $sessionId 40
                return @{ ok = $true; result = @{ events = $events; count = $events.Count } }
            }
            'bridge_status' {
                $entry = Get-SessionEntry $sessionId
                $queue = Ensure-Queue $sessionId
                $pending = Get-PendingCommands $sessionId
                $executorSnapshot = Get-SessionExecutorSnapshot $sessionId
                $assetCacheEntries = 0
                $bsSim = $true
                $bsNotify = $false
                try { $bsSim = [bool]$Shared.BridgeSettings.simAllowed } catch {}
                try { $bsNotify = [bool]$Shared.BridgeSettings.notifyOnDone } catch {}
                try {
                    if (Test-Path -LiteralPath [string]$Shared.AssetCachePath) {
                        $cache = Get-Content -LiteralPath [string]$Shared.AssetCachePath -Raw | ConvertFrom-Json
                        $assetCacheEntries = @($cache.PSObject.Properties).Count
                    }
                } catch {}
                return @{
                    ok = $true
                    result = @{
                        bridgeVersion = '7.4.1'
                        docsVersion = [string]$Shared.DocsVersion
                        place = if ($entry) { $entry.placeName } else { $null }
                        placeId = if ($entry) { $entry.placeId } else { $null }
                        studio = if ($entry) { $entry.state } else { $null }
                        pluginVersion = if ($entry) { $entry.pluginVersion } else { $null }
                        accessMode = if ($entry) { $entry.accessMode } else { $null }
                        queuedCommands = $queue.Count
                        runningInStudio = $pending
                        executor = $executorSnapshot
                        connectedPlaces = $Shared.Sessions.Count
                        storedBlobs = $Shared.Blobs.Count
                        assetCacheEntries = $assetCacheEntries
                        settings = @{
                            simAllowed = $bsSim
                            notifyOnDone = $bsNotify
                        }
                        docs = 'GET /api/docs for the complete tool documentation (or ?tool= / ?category=).'
                        note = 'Each Studio window has its own token. This token only ever reaches the place shown above.'
                    }
                }
            }
            # Version 7.2.0 (AP7): Der Aufbau der Oberflaeche als Server-Werkzeug
            # (kein Studio-Umlauf): Namen, Verantwortungen und Reihenfolge der
            # KLEINEN Skripte. Genau das fehlte, wenn die KI stattdessen ein
            # 10.000-Zeilen-LocalScript geschrieben hat.
            'scaffold_ui_scripts' {
                $uiName = ''
                try { if ($null -ne $toolArgs -and $toolArgs.PSObject.Properties['ui']) { $uiName = ([string]$toolArgs.ui).Trim() } } catch {}
                if ([string]::IsNullOrWhiteSpace($uiName)) {
                    return @{
                        ok = $false
                        code = 'BAD_ARGS'
                        error = 'ui is required (the name of the interface, for example "Shop").'
                        hint = 'Call scaffold_ui_scripts { ui = "Shop", screens = ["Shop","Inventory"] } - you get the split and the order to build it in.'
                    }
                }
                $screens = New-Object System.Collections.Generic.List[string]
                try {
                    if ($null -ne $toolArgs -and $toolArgs.PSObject.Properties['screens']) {
                        foreach ($screen in @($toolArgs.screens)) {
                            $value = ([string]$screen).Trim()
                            if (-not [string]::IsNullOrWhiteSpace($value)) { $screens.Add($value) }
                        }
                    }
                } catch {}
                $modeValue = 'new'
                try { if ($null -ne $toolArgs -and $toolArgs.PSObject.Properties['mode'] -and -not [string]::IsNullOrWhiteSpace([string]$toolArgs.mode)) { $modeValue = ([string]$toolArgs.mode).Trim().ToLowerInvariant() } } catch {}
                if ($modeValue -ne 'extend') { $modeValue = 'new' }
                $scripts = New-Object System.Collections.Generic.List[object]
                $scripts.Add([pscustomobject]@{
                    name = $uiName + 'Config'
                    className = 'ModuleScript'
                    responsibility = 'Zahlen, Farben, Texte und Grenzen an EINER Stelle. Kein Zeichencode hier.'
                    why = 'Damit niemand Werte im Zeichencode sucht und zwei Skripte dieselbe Zahl anders belegen.'
                    order = 1
                })
                $scripts.Add([pscustomobject]@{
                    name = $uiName + 'State'
                    className = 'ModuleScript'
                    responsibility = 'Der Zustand (welche Seite, welche Auswahl, welche Werte) plus Getter/Setter und ein Signal (BindableEvent), wenn sich etwas aendert.'
                    why = 'Zustand getrennt von der Darstellung - genau das ist der Grund, warum die kleinen Skripte klein bleiben.'
                    order = 2
                })
                foreach ($screen in $screens) {
                    $scripts.Add([pscustomobject]@{
                        name = $uiName + ([string]$screen) + 'View'
                        className = 'LocalScript'
                        responsibility = ('Nur die Elemente von "' + [string]$screen + '": was wird angezeigt, was ist sichtbar. Schreibt in BESTEHENDE GuiObjects, erzeugt nichts neu.')
                        why = 'Eine Bildschirmseite, ein Skript - lesbar in einem Zug.'
                        order = 3
                    })
                }
                $scripts.Add([pscustomobject]@{
                    name = $uiName + 'Input'
                    className = 'LocalScript'
                    responsibility = 'Klicks, Hover, Tasten und Touch. Ruft NUR Setter des State auf, aendert selbst nichts am Aussehen.'
                    why = 'Eingabe und Darstellung zu trennen verhindert doppelte Wahrheiten.'
                    order = 4
                })
                $scripts.Add([pscustomobject]@{
                    name = $uiName + 'Update'
                    className = 'LocalScript'
                    responsibility = 'Hoert auf den State und aktualisiert die vorhandenen Elemente (Texte, Zahlen, Sichtbarkeit, Auswahl).'
                    why = 'Nur hier laeuft Aktualisierung - kein Skript schreibt an einem anderen vorbei.'
                    order = 5
                })
                $scripts.Add([pscustomobject]@{
                    name = $uiName + 'Effects'
                    className = 'LocalScript'
                    responsibility = 'Tweens und Animationen auf den Transform-Wrappern (UIScale), inklusive Oeffnen/Schliessen.'
                    why = 'Effekte sind der Teil, der am haeufigsten Laufzeitfehler erzeugt - klein und getrennt testbar.'
                    order = 6
                })
                $scripts.Add([pscustomobject]@{
                    name = $uiName + 'Data'
                    className = 'ModuleScript'
                    responsibility = 'Optional: RemoteEvents/Remotes, Profildaten, Preise. Alles, was mit dem Server spricht.'
                    why = 'Datenzugriff gehoert nicht in die Zeichenschleife.'
                    order = 7
                })
                return @{
                    ok = $true
                    result = @{
                        ui = $uiName
                        mode = $modeValue
                        structure = @{
                            instance = 'StarterGui.' + $uiName + 'Gui (ScreenGui)'
                            layout = 'Frames, Labels, Buttons und Bilder werden EINMAL gebaut (build_interface/build_surface) und bleiben in Studio editierbar.'
                            scriptsFolder = 'StarterGui.' + $uiName + 'Gui.' + $uiName + 'Scripts (Folder) - alle kleinen Skripte liegen sichtbar beieinander.'
                            forbidden = 'Kein LocalScript, das die ganze Oberflaeche zur Laufzeit mit Instance.new aufbaut. Das ist in Studio nicht editierbar, kostet beim Beitritt Leistung und ist nicht lesbar.'
                        }
                        scripts = @($scripts.ToArray())
                        buildOrder = @('1. Instanzen bauen (build_interface/build_surface ' + $(if ($modeValue -eq 'extend') { 'mode="extend" auf den BESTEHENDEN Elementen' } else { 'neu' }) + ')', '2. Config und State anlegen (insert_script, klein halten)', '3. je Bildschirm ein View-Skript', '4. Input, Update, Effects - je eine Verantwortung', '5. erst danach Details wie Bilder/Effekte ergaenzen')
                        limits = @{ maxLinesPerScript = 250; hardWarnLines = 400; instanceNewPerScript = 15 }
                        note = 'Jedes Skript bleibt unter etwa 250 Zeilen und erzeugt nichts, was es nicht besitzt. set_script_source/insert_script/patch_script messen das und melden MONOLITH_RISK mit Zahlen. Regeln: uiStructureRules.'
                    }
                }
            }
            # Version 7.2.0: NUTZER-KANAL. Beides sind reine Server-Werkzeuge
            # (kein Studio-Umlauf), damit eine Korrektur des Nutzers die KI auch
            # dann sofort erreicht, wenn die Studio-Queue gerade belegt ist.
            'ack_user_message' { return (Invoke-AckUserMessage $sessionId $toolArgs) }
            'wait_for_user'    { return (Invoke-WaitForUser $sessionId $toolArgs) }
            # Version 7.2.0 (D3): Fragen mit Entscheidungsbaum + Ja/Nein-Bestaetigung.
            'ask_user'         { return (Invoke-AskUser $sessionId $toolArgs) }
            'confirm_action'   { return (Invoke-ConfirmAction $sessionId $toolArgs) }
        }
        return $null
    }

    # Explicit organic-build contract at the HTTP boundary. It is activated by
    # organic=true, never by a species/model-name keyword: the global 3D build
    # preference lives in modelBuildRules for every category and remains a
    # preference rather than forcing every simple Part into polygon geometry.
    # Follow-up writes to registered organic models stay ordered until audited.
    function Get-OrganicBuildGuardResult([string]$tool, $toolArgs, [switch]$ParallelCall) {
        $organicGuardTools = @('set_property','set_properties','bulk_set_properties','set_attribute',
            'create_instance','bulk_create','clone_instance','delete_instance','bulk_delete','rename_instance','move_instance',
            'set_script_source','patch_script','insert_script','bulk_insert_scripts','run_lua','batch','parallel',
            'union','subtract','negate','intersect','separate','insert_asset','apply_asset','group_instances','ungroup',
            'add_tag','remove_tag','place_on','align','stack','grid_arrange','distribute','snap_to_ground','look_at',
            'rotate_around','move_relative','resize_part','fit_between','point_at','fill_region','build_polygon_model',
            'build_assembly','build_surface','build_interface','start_job','model_audit','prop_place','prop_save',
            'refine','world_style','style_lock','world_glow','ui_glow','ui_radial','ui_texture','undo','redo')
        if ($tool -notin $organicGuardTools) { return $null }
        if ($null -eq $toolArgs) { return $null }
        $argsJson = ''
        try { $argsJson = ConvertTo-Json -InputObject $toolArgs -Depth 24 -Compress } catch { return $null }
        $organicFlag = $false
        try { $organicFlag = ($toolArgs.organic -eq $true) } catch {}
        $isAsyncWrite = ($tool -eq 'start_job' -or $toolArgs.asJob -eq $true)

        $stateJson = ''
        $organicState = $null
        $hasOrganicState = $Shared.OrganicBuilds.TryGetValue([string]$sessionId, [ref]$stateJson)
        if ($hasOrganicState -and -not [string]::IsNullOrWhiteSpace($stateJson)) {
            try { $organicState = $stateJson | ConvertFrom-Json } catch { $organicState = $null }
        }

        # Parallel and background calls cannot establish a reliable last-write
        # order, and nested model_audit results are not persisted by the HTTP
        # boundary. Require one direct call per edit and one standalone audit.
        if ($tool -eq 'model_audit' -and ($ParallelCall -or $isAsyncWrite)) {
            return @{
                ok = $false; code = 'ORGANIC_SEQUENCE_REQUIRED'
                error = 'model_audit must be a standalone, foreground call so its exact per-model result can be stored as fresh evidence.'
                howToFix = 'Call model_audit by itself (without batch/parallel/asJob), after every final write. The bridge records the returned organicQuality result for report_done.'
            }
        }
        if ($organicState -and [bool]$organicState.required) {
            if ($ParallelCall -or $isAsyncWrite -or $tool -eq 'batch' -or $tool -eq 'parallel') {
                return @{
                    ok = $false; code = 'ORGANIC_SEQUENCE_REQUIRED'
                    error = 'This Place has a registered organic model. Parallel, batch or background writes cannot be ordered against its audit evidence; the write was NOT sent to Studio.'
                    howToFix = 'Make each edit as a direct foreground tool call. After the final edit, run model_audit by itself on the returned model id, then call report_done.'
                }
            }
            return $null
        }
        if (-not $organicFlag) { return $null }

        $isOrganicPolygonBuild = ($tool -eq 'build_polygon_model' -and $organicFlag)
        if ($tool -eq 'build_polygon_model' -and -not $organicFlag -and [string]$toolArgs.organicKind -eq 'creature') {
            return @{
                ok = $false; code = 'ORGANIC_KIND_REQUIRED'
                error = 'organicKind=creature requires organic=true so the model is registered for its per-creature geometry audit.'
                howToFix = 'Call build_polygon_model with organic=true, organicKind="creature", and closed body/head loft volumes.'
            }
        }
        if ($isOrganicPolygonBuild) {
            $organicKind = ''
            try { $organicKind = ([string]$toolArgs.organicKind).Trim().ToLowerInvariant() } catch {}
            if ([string]::IsNullOrWhiteSpace($organicKind)) {
                return @{
                    ok = $false; code = 'ORGANIC_KIND_REQUIRED'
                    error = 'organic=true now requires an explicit organicKind so the measured geometry contract is selected before Studio receives the build.'
                    howToFix = 'Pass organicKind="creature" for animals, or plant/tree/prop/custom for the matching organic category.'
                }
            }
            if ($organicKind -notin @('creature','plant','tree','prop','custom')) {
                return @{
                    ok = $false; code = 'ORGANIC_KIND_INVALID'
                    error = 'organicKind must be creature, plant, tree, prop or custom.'
                    howToFix = 'Use one of the supported organicKind values and rebuild.'
                }
            }
            if ($ParallelCall -or $isAsyncWrite) {
                return @{
                    ok = $false; code = 'ORGANIC_SEQUENCE_REQUIRED'
                    error = 'An organic model must be built, animated and audited in separate ordered foreground calls; parallel/background execution cannot prove that order.'
                    howToFix = 'Call build_polygon_model { organic=true } by itself first, use the returned model id, install the enabled motion Script, then run model_audit after the final edit.'
                }
            }
            $colorAssignments = ([regex]::Matches($argsJson, '(?i)"color"\s*:')).Count
            $colorAssignments += ([regex]::Matches($argsJson, '(?i)\bcolor\s*=')).Count
            if ($colorAssignments -lt 3) {
                return @{
                    ok = $false; code = 'ORGANIC_COLORS_REQUIRED'
                    error = 'organic=true requires at least three explicit, contrasting colour assignments across meaningful regions (for example body/back, belly and face/paws or trunk, foliage and accents). The build was NOT sent to Studio.'
                    howToFix = 'Pass at least three distinct style.color values across volumes/submodels (or at least three color= values in the polygon script), then build again. model_audit verifies the actual palette.'
                    colorAssignments = $colorAssignments
                }
            }
            return $null
        }
        return @{
            ok = $false; code = 'ORGANIC_POLYGON_REQUIRED'
            error = 'This write explicitly declares an organic build, but organic models must be created with build_polygon_model { organic=true }. The write was NOT sent to Studio; no model-name or species keyword is used to choose the builder.'
            howToFix = 'Call build_polygon_model { organic=true, modelName, submodels=[{name="Primary",style={color="#..."},polygons=[...]},{name="Secondary",style={color="#..."},polygons=[...]},{name="Accent",style={color="#..."},polygons=[...]}] } as one non-parallel foreground call. Then add an enabled motion Script under the returned model, run model_audit on that id after the last edit and fix every organicQuality issue.'
            blockedTool = $tool
        }
    }

    $context = $Context

    do {
        try {
            if ($context.Request.HttpMethod -eq 'OPTIONS') {
                Send-Json $context 200 @{ ok = $true }
                continue
            }

            $path = $context.Request.Url.AbsolutePath.TrimEnd('/')
            if ($path -eq '') { $path = '/' }
            $body = $null
            if ($context.Request.HttpMethod -in @('POST', 'PUT', 'PATCH')) {
                $body = Read-Body $context.Request
            }

            # ---------------- GET-Vollsteuerung (Version 3.9.8) --------------
            # Manche KI-Umgebungen duerfen NUR per HTTP GET nach draussen
            # (der Web-Abruf-Dienst schickt keine POST-Koerper). Damit die KI
            # die Bridge trotzdem komplett bedienen kann, bauen wir hier aus
            # den Abfrage-Parametern (?tool=...&args=...) genau denselben
            # Koerper zusammen, den ein POST geschickt haette. Ab dieser
            # Zeile ist der restliche Code voellig gleich - GET und POST
            # laufen also durch DIESELBE Verarbeitung.
            $getParamError = $null
            if ($null -eq $body -and $context.Request.HttpMethod -eq 'GET') {
                $q = $context.Request.QueryString
                $qNames = @()
                try { $qNames = @($q.AllKeys | Where-Object { $_ }) } catch {}
                if ($qNames.Count -gt 0) {
                    $getBody = New-Object psobject
                    # Decode GET data ourselves as UTF-8. HttpListener's QueryString
                    # can otherwise Latin-1-decode percent escapes (→ became â†').
                    $rawQuery = [string]$context.Request.Url.Query
                    function Get-Utf8QueryValue([string]$name) {
                        foreach ($piece in ($rawQuery.TrimStart('?') -split '&')) {
                            $split = $piece.IndexOf('=')
                            $rawName = if ($split -ge 0) { $piece.Substring(0,$split) } else { $piece }
                            $rawValue = if ($split -ge 0) { $piece.Substring($split+1) } else { '' }
                            $decodedName = [System.Web.HttpUtility]::UrlDecode($rawName, [System.Text.Encoding]::UTF8)
                            if ($decodedName -eq $name) { return [System.Web.HttpUtility]::UrlDecode($rawValue, [System.Text.Encoding]::UTF8) }
                        }
                        return $null
                    }
                    foreach ($plain in @('token','tool','uploadId','text','sessionId','id','category','message','status','targetPlace')) {
                        $raw = Get-Utf8QueryValue $plain
                        if ($null -ne $raw) { $getBody | Add-Member -MemberType NoteProperty -Name $plain -Value ([string]$raw) -Force }
                    }
                    # Zahlen-Felder sauber in Zahlen wandeln.
                    foreach ($num in @('timeoutSeconds','chunkIndex','chunkCount','limit')) {
                        $raw = Get-Utf8QueryValue $num
                        if (-not [string]::IsNullOrWhiteSpace([string]$raw)) {
                            $parsed = 0
                            if ([int]::TryParse(([string]$raw).Trim(), [ref]$parsed)) {
                                $getBody | Add-Member -MemberType NoteProperty -Name $num -Value $parsed -Force
                            }
                        }
                    }
                    # JSON-Felder: als URL-kodiertes JSON uebergeben.
                    foreach ($jsonField in @('args','calls','extra')) {
                        $raw = Get-Utf8QueryValue $jsonField
                        if (-not [string]::IsNullOrWhiteSpace([string]$raw)) {
                            try {
                                $getBody | Add-Member -MemberType NoteProperty -Name $jsonField -Value (ConvertFrom-Json ([string]$raw)) -Force
                            } catch {
                                if (-not $getParamError) {
                                    $getParamError = @{
                                        ok = $false
                                        error = ("Der Parameter '" + $jsonField + "' ist kein gueltiges JSON: " + $_.Exception.Message)
                                        hint = ("Send " + $jsonField + " as URL-encoded JSON, e.g. ?" + $jsonField + "=%7B%22key%22%3A%22value%22%7D")
                                    }
                                }
                            }
                        }
                    }
                    # Ein Werkzeug ohne Argumente ist erlaubt - dann ein
                    # leeres Objekt, damit der spaetere Code nicht stolpert.
                    if ($getBody.PSObject.Properties['tool'] -and -not $getBody.PSObject.Properties['args']) {
                        $getBody | Add-Member -MemberType NoteProperty -Name 'args' -Value (New-Object psobject) -Force
                    }
                    $body = $getBody
                }
            }
            if ($getParamError) {
                Send-Json $context 400 $getParamError
                continue
            }

            # ---------------- Manifest -------------------------------------
            if ($path -eq '/' -or $path -eq '/api/manifest' -or $path -eq '/api/tools') {
                Send-Json $context 200 (Get-Manifest)
                continue
            }

            # ---------------- Plugin ---------------------------------------
            if ($path -eq '/plugin/session') {
                # Session-Agent uses a per-play, plugin-generated key. This is
                # deliberately before token auth: the isolated test has no API
                # token, only localhost HTTP access and this ephemeral key.
                $sid = if ($body) { [string]$body.sessionId } else { '' }
                $action = if ($body) { [string]$body.action } else { '' }
                # Version 5: a new Studio test creates a fresh reporter key.
                # The edit plugin registers it before ExecutePlayModeAsync,
                # preventing a stale key from the preceding test from blocking
                # move_character and end_test. The session id is unguessable
                # and must already exist; this endpoint remains localhost-only.
                if ($action -eq 'register') {
                    $entryForKey = Get-SessionEntry $sid
                    if ($entryForKey -and $body.sessionKey) {
                        $Shared.AgentKeys[$sid] = [string]$body.sessionKey
                        Send-Json $context 200 @{ ok=$true; registered=$true }
                    } else {
                        Send-Json $context 403 @{ ok=$false; error='Unknown session for Session-Agent key registration.' }
                    }
                    continue
                }
                if ($action -eq 'stop_active_place') {
                    $sourceEntry = Get-SessionEntry $sid
                    $stopped = $false
                    if ($sourceEntry) {
                        foreach ($pair in $Shared.Sessions.GetEnumerator()) {
                            try {
                                $candidate = $pair.Value | ConvertFrom-Json
                                if ([string]$candidate.sessionId -ne $sid -and [string]$candidate.placeId -eq [string]$sourceEntry.placeId -and [bool]$candidate.state.running) {
                                    $r = Invoke-PluginTool ([string]$candidate.sessionId) 'sim_stop' @{} 18
                                    if ($r) { $stopped = $true; break }
                                }
                            } catch {}
                        }
                    }
                    Send-Json $context 200 @{ ok = $stopped }
                    continue
                }
                $knownKey = $null
                if (-not $sid -or -not $Shared.AgentKeys.TryGetValue($sid, [ref]$knownKey) -or [string]$knownKey -ne [string]$body.sessionKey) {
                    # 4.0.1: Der Session-Plugin-Reporter (Plugin-Instanz im
                    # Test-DataModel) und das Edit-Plugin einigen sich ueber
                    # plugin:SetSetting auf denselben Schluessel. Der erste
                    # Kontakt darf ihn registrieren - danach gilt er strikt.
                    if ($sid -and $body.sessionKey -and ($action -eq 'command' -or $action -eq 'heartbeat' -or $action -eq 'reporter_state')) {
                        $Shared.AgentKeys[$sid] = [string]$body.sessionKey; $knownKey = [string]$body.sessionKey
                    }
                    else { Send-Json $context 403 @{ ok=$false; error='Invalid Session-Agent key.' }; continue }
                }
                if ($action -eq 'reporter_state') {
                    # Das Edit-Plugin fragt den Zustand des Session-Reporters ab.
                    $stateJson = $null
                    $seen = [long]0
                    [void]$Shared.AgentLastSeen.TryGetValue($sid, [ref]$seen)
                    $fresh = ((Get-UnixSeconds) - $seen) -le 6
                    if ($fresh -and $Shared.AgentStates.TryGetValue($sid, [ref]$stateJson)) {
                        try { Send-Json $context 200 @{ ok=$true; state=($stateJson | ConvertFrom-Json); age=((Get-UnixSeconds) - $seen) } }
                        catch { Send-Json $context 200 @{ ok=$true } }
                    } else {
                        Send-Json $context 200 @{ ok=$true; state=$null }
                    }
                    continue
                }
                if ($action -eq 'command') {
                    if (-not $body.command -or -not $body.command.id) { Send-Json $context 400 @{ok=$false;error='Missing Session-Agent command.'}; continue }
                    $queue = Ensure-AgentQueue $sid
                    $queue.Enqueue((To-Json $body.command 20))
                    Send-Json $context 200 @{ok=$true}
                    continue
                }
                if ($action -eq 'result') {
                    if ($body.commandId) { $Shared.AgentResults[($sid + ':' + [string]$body.commandId)] = (To-Json $body.result 30) }
                    Send-Json $context 200 @{ok=$true}
                    continue
                }
                if ($action -eq 'heartbeat') {
                    $now = Get-UnixSeconds
                    $Shared.AgentLastSeen[$sid] = $now
                    # 4.0.5: Die Zustands-Uebernahme darf den Heartbeat NIE
                    # scheitern lassen. Vorher warf sie (PSCustomObject-
                    # Zuweisung, s. Set-StateField) und der ganze Request
                    # endete als 500 - der Reporter bekam dadurch NIE seine
                    # Befehle aus der Warteschlange und play_stop/
                    # move_character liefen in REPORTER_NOT_CONNECTED.
                    # Die Befehlsauslieferung unten laeuft jetzt IMMER.
                    try {
                        if ($body.state) {
                            $stateJson = To-Json $body.state 30
                            $Shared.AgentStates[$sid] = $stateJson
                            $entry = Get-SessionEntry $sid
                            if ($entry) {
                                $agentState = $body.state
                                $agentState | Add-Member -NotePropertyName 'agentConnected' -NotePropertyValue $true -Force
                                $entry.state = Update-PlayStateTracking $sid $entry.state $agentState
                                $entry.lastSeen = $now
                                $entry | Add-Member -NotePropertyName 'agentConnected' -NotePropertyValue $true -Force
                                Save-SessionEntry $entry
                            }
                        }
                    } catch {
                        Write-BridgeLog "Heartbeat-Zustand ignoriert (Befehle werden trotzdem zugestellt): $($_.Exception.Message)"
                    }
                    $queue = Ensure-AgentQueue $sid
                    $items = New-Object System.Collections.Generic.List[object]
                    $itemJson = $null
                    while ($items.Count -lt 6 -and $queue.TryDequeue([ref]$itemJson)) { try { $items.Add(($itemJson | ConvertFrom-Json)) } catch {} }
                    # Version 7.1.1: .ToArray() statt @( Liste ) - siehe Get-QueueSnapshot.
                    Send-Json $context 200 @{ok=$true;commands=$items.ToArray()}
                    continue
                }
                # Result polling uses action=query; all other authenticated
                # non-mutating calls below are treated as an empty query.
                $key = $sid + ':' + [string]$body.commandId
                $resultJson = $null
                if ($Shared.AgentResults.TryRemove($key, [ref]$resultJson)) { try { Send-Json $context 200 @{ok=$true;result=($resultJson | ConvertFrom-Json)} } catch { Send-Json $context 200 @{ok=$true} } }
                else { Send-Json $context 200 @{ok=$true} }
                continue
            }

            if ($path -eq '/plugin/hello') {
                Add-PerfCount 'HelloRequests'
                try {
                    $Shared.Telemetry.Hello = [long]$Shared.Telemetry.Hello + 1
                    $Shared.Telemetry.LastHelloAt = Get-UnixSeconds
                } catch {}
                $entry = Register-Session $body
                if (-not $entry) {
                    Send-Json $context 400 @{ ok = $false; error = 'Ungültige Anmeldung.' }
                } else {
                    $pluginVersion = [string]$entry.pluginVersion
                $outdated = ($pluginVersion -ne [string]$Shared.DocsVersion)
                $entry | Add-Member -NotePropertyName 'versionMismatch' -NotePropertyValue $outdated -Force
                Save-SessionEntry $entry
                Send-Json $context 200 @{
                        ok = $true
                        sessionId = $entry.sessionId
                        token = $entry.token
                        accessMode = $entry.accessMode
                        serverVersion = '7.4.1'
                        docsVersion = [string]$Shared.DocsVersion
                        pluginOutdated = $outdated
                        restartStudioHint = if ($outdated) { 'Studio neu starten: Plugin-Version stimmt nicht mit der Bridge ueberein. Simulationen warten.' } else { $null }
                    }
                }
                continue
            }

            if ($path -eq '/plugin/heartbeat') {
                Add-PerfCount 'Heartbeats'
                $entry = Update-Session $body
                if (-not $entry) {
                    # Version 7.1.1: wie /plugin/poll - kennt die Bridge die Instanz
                    # noch, bekommt das Plugin die gueltige sessionId statt seine
                    # Sitzung zu verwerfen (kein re-hello, kein connected-Sturm).
                    $knownHeartbeatSessionId = ''
                    try {
                        $heartbeatGuid = [string]$body.instanceGuid
                        if (-not [string]::IsNullOrWhiteSpace($heartbeatGuid)) {
                            $knownHeartbeatRaw = ''
                            if ($Shared.InstanceSessions.TryGetValue($heartbeatGuid, [ref]$knownHeartbeatRaw)) { $knownHeartbeatSessionId = [string]$knownHeartbeatRaw }
                        }
                    } catch {}
                    Send-Json $context 200 @{ ok = $false; unknownSession = $true; sessionId = $(if ([string]::IsNullOrWhiteSpace($knownHeartbeatSessionId)) { $null } else { $knownHeartbeatSessionId }) }
                } else {
                    Send-Json $context 200 @{ ok = $true; sessionId = [string]$entry.sessionId; token = $entry.token; accessMode = $entry.accessMode }
                }
                continue
            }

            if ($path -eq '/plugin/poll') {
                Add-PerfCount 'PollRequests'
                try {
                    $Shared.Telemetry.Poll = [long]$Shared.Telemetry.Poll + 1
                    $Shared.Telemetry.LastPollAt = Get-UnixSeconds
                } catch {}
                $entry = Update-Session $body
                if (-not $entry) {
                    # Version 7.0.6: Dieselbe Plugin-Instanz bekommt dieselbe
                    # Sitzung zurueck - auch wenn sie zwischendurch als tot
                    # aufgeraeumt wurde. Kein neuer Token, keine neue sessionId,
                    # keine Befehle in einer verwaisten Sitzung.
                    $entry = Resolve-InstanceSession $body
                }
                if (-not $entry) {
                    try { $Shared.Telemetry.UnknownSessionPolls = [long]$Shared.Telemetry.UnknownSessionPolls + 1 } catch {}
                    $knownSessionId = ''
                    try {
                        $pollGuid = [string]$body.instanceGuid
                        if (-not [string]::IsNullOrWhiteSpace($pollGuid)) {
                            $knownRaw = ''
                            if ($Shared.InstanceSessions.TryGetValue($pollGuid, [ref]$knownRaw)) { $knownSessionId = [string]$knownRaw }
                        }
                    } catch {}
                    Send-Json $context 200 @{ ok = $false; unknownSession = $true; sessionId = $(if ([string]::IsNullOrWhiteSpace($knownSessionId)) { $null } else { $knownSessionId }) }
                    continue
                }
                $sid = [string]$entry.sessionId
                Test-PollRateSane $sid
                Invoke-SessionExecutorWatchdog $sid
                if ($body.perf) { Record-PluginPerf $sid $body.perf }
                $queue = Ensure-Queue $sid
                $signal = Ensure-Signal $sid

                $waitSeconds = 8
                if ($body.wait) { $waitSeconds = [Math]::Min([double]$body.wait, 8) }
                $deadline = [DateTime]::UtcNow.AddSeconds($waitSeconds)
                $collected = New-Object System.Collections.Generic.List[string]
                $redeliveredIds = New-Object System.Collections.Generic.HashSet[string]
                Update-PollerCount $sid 1
                try {
                    while ($true) {
                        $resetStamp = [long]0
                        $resetRequested = $Shared.ExecutorResetRequests.TryGetValue($sid, [ref]$resetStamp)
                        $cancelledNow = @(Get-SessionCancellationIds $sid)
                        if ($resetRequested -or $cancelledNow.Count -gt 0) { break }
                        $itemJson = $null
                        [System.Threading.Monitor]::Enter($Shared.CommandQueueLock)
                        try {
                            # Version 7.1.0: Unbestaetigte 'delivered'-Befehle (fuer die noch
                            # kein received_batch / started / result ankam) bis zu 3-mal
                            # erneut ausliefern. Das Plugin dedupliziert per commandId.
                            $nowPoll = Get-UnixSeconds
                            $pendingBag = Ensure-PendingBag $sid
                            foreach ($pendingPair in @($pendingBag.GetEnumerator())) {
                                if ($collected.Count -ge 16) { break }
                                $pendingId = [string]$pendingPair.Key
                                if ([string]::IsNullOrWhiteSpace($pendingId) -or $redeliveredIds.Contains($pendingId)) { continue }
                                $pendingInfo = $null
                                try { $pendingInfo = $pendingPair.Value | ConvertFrom-Json } catch { continue }
                                if (-not $pendingInfo -or [string]$pendingInfo.status -ne 'delivered') { continue }
                                $lastDel = 0
                                try {
                                    if ($pendingInfo.lastDeliveryAt) { $lastDel = [int64]$pendingInfo.lastDeliveryAt }
                                    elseif ($pendingInfo.deliveredAt) { $lastDel = [int64]$pendingInfo.deliveredAt }
                                } catch {}
                                $unacked = 0
                                try { if ($null -ne $pendingInfo.unackedCount) { $unacked = [int]$pendingInfo.unackedCount } } catch {}
                                if (($nowPoll - $lastDel) -ge 1 -and $unacked -lt 3) {
                                    $payloadRaw = $null
                                    if ($Shared.CommandPayloads.TryGetValue($pendingId, [ref]$payloadRaw) -and -not [string]::IsNullOrWhiteSpace($payloadRaw)) {
                                        $unacked = $unacked + 1
                                        $attempts = 1
                                        try { if ($null -ne $pendingInfo.deliveryAttempts) { $attempts = [int]$pendingInfo.deliveryAttempts } } catch {}
                                        $attempts = $attempts + 1
                                        $pendingInfo | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue $unacked -Force
                                        $pendingInfo | Add-Member -NotePropertyName 'lastDeliveryAt' -NotePropertyValue $nowPoll -Force
                                        $pendingInfo | Add-Member -NotePropertyName 'deliveryAttempts' -NotePropertyValue $attempts -Force
                                        Save-PendingInfo $sid $pendingId $pendingInfo | Out-Null
                                        Write-BridgeLog ('Befehl erneut zugestellt (unbestaetigt ' + $unacked + '/3): tool=' + [string]$pendingInfo.tool + ', commandId=' + $pendingId + ', sid=' + $sid)
                                        [void]$redeliveredIds.Add($pendingId)
                                        $collected.Add([string]$payloadRaw)
                                    }
                                }
                            }
                            while ($collected.Count -lt 16 -and $queue.TryDequeue([ref]$itemJson)) {
                                try {
                                    $candidate = $itemJson | ConvertFrom-Json
                                    $pendingInfo = Get-PendingInfo $sid ([string]$candidate.id)
                                    if ($candidate.id -and $pendingInfo -and [string]$pendingInfo.status -eq 'queued') {
                                        $Shared.CommandPayloads[[string]$candidate.id] = [string]$itemJson
                                        $collected.Add([string]$itemJson)
                                    }
                                } catch {}
                            }
                        } finally {
                            [System.Threading.Monitor]::Exit($Shared.CommandQueueLock)
                        }
                        if ($collected.Count -gt 0) { break }
                        if ([DateTime]::UtcNow -ge $deadline) { break }
                        [void]$signal.Wait(250)
                        $signal.Reset()
                    }
                } finally {
                    Update-PollerCount $sid -1
                }

                $resetStamp = [long]0
                $resetRequested = $Shared.ExecutorResetRequests.TryGetValue($sid, [ref]$resetStamp)
                $cancelledIds = @(Get-SessionCancellationIds $sid)
                if ($resetRequested) { $collected.Clear() }
                if (-not $resetRequested) {
                    foreach ($commandJson in $collected) {
                        try {
                            $deliveredCommand = $commandJson | ConvertFrom-Json
                            $cid = [string]$deliveredCommand.id
                            if (-not $redeliveredIds.Contains($cid)) {
                                Mark-CommandDelivered $sid $cid | Out-Null
                            }
                        } catch {}
                    }
                }
                $mode = 'readwrite'
                [void]$Shared.AccessModes.TryGetValue($sid, [ref]$mode)
                $perfFlag = 'false'
                if (Test-PerfEnabled) { $perfFlag = 'true' }
                $commandJson = '[' + ($collected -join ',') + ']'
                # Version 7.1.1: sessionId in jeder Poll-Antwort - das Plugin
                # uebernimmt sie, falls seine eigene fehlt oder veraltet ist.
                $json = '{"ok":true,"sessionId":' + (To-Json $sid 3) + ',"accessMode":' + (To-Json $mode 3) + ',"perf":' + $perfFlag + ',"commands":' + $commandJson + ',"cancelledCommands":' + (To-Json $cancelledIds 6) + ',"resetExecutor":' + $(if ($resetRequested) { 'true' } else { 'false' }) + ',"queueDepth":' + [string]$queue.Count + '}'
                Send-RawJson $context 200 $json
                continue
            }

            if ($path -eq '/plugin/result') {
                try {
                    $Shared.Telemetry.Result = [long]$Shared.Telemetry.Result + 1
                    $Shared.Telemetry.LastResultAt = Get-UnixSeconds
                } catch {}
                if ($body -and $body.commandId -and $body.sessionId) {
                    $commandId = [string]$body.commandId
                    $sidForResult = [string]$body.sessionId
                    $ownerSession = Get-CommandOwner $commandId
                    if ($ownerSession -ne $sidForResult) {
                        # Version 7.0.5: after a plugin reconnect the result may arrive
                        # under a new sessionId of the SAME plugin instance. Accept it by
                        # commandId + instanceGuid instead of dropping it for good.
                        if (-not (Test-CommandInstanceMatches $sidForResult $commandId)) {
                            Send-Json $context 403 @{ ok=$false; code='COMMAND_OWNER_MISMATCH'; error='This commandId does not belong to the supplied Studio session.' }
                            continue
                        }
                        $sidForResult = $ownerSession
                    }
                    $dedupeKey = Get-CommandControlKey $sidForResult $commandId
                    $completeJson = $null
                    if ($body.chunkCount) {
                        $expected = 0; $index = 0
                        try { $expected = [int]$body.chunkCount; $index = [int]$body.chunkIndex } catch {}
                        if ($expected -lt 1 -or $expected -gt 256 -or $index -lt 1 -or $index -gt $expected -or [string]::IsNullOrEmpty([string]$body.chunk)) {
                            Send-Json $context 400 @{ ok=$false; code='BAD_ARGS'; error='Invalid result chunk coordinates.'; commandId=$commandId }
                            continue
                        }
                        # Version 7.1.0: Jeder Ergebnis-Chunk gilt als Lebenszeichen und
                        # Empfangsbeweis, damit grosse Antworten nicht waehrend der
                        # Uebertragung vom Watchdog abgebrochen werden.
                        try {
                            $chunkPending = Get-PendingInfo $sidForResult $commandId
                            if ($chunkPending) {
                                $nowChunk = Get-UnixSeconds
                                if ([string]$chunkPending.status -in @('queued','delivered','received')) {
                                    $chunkPending.status = 'started'
                                    if (-not $chunkPending.startedAt -or [int64]$chunkPending.startedAt -le 0) { $chunkPending.startedAt = $nowChunk }
                                }
                                if (-not $chunkPending.receivedAt -or [int64]$chunkPending.receivedAt -le 0) {
                                    $chunkPending | Add-Member -NotePropertyName 'receivedAt' -NotePropertyValue $nowChunk -Force
                                }
                                $chunkPending | Add-Member -NotePropertyName 'unackedCount' -NotePropertyValue 0 -Force
                                $chunkPending.heartbeatAt = $nowChunk
                                Save-PendingInfo $sidForResult $commandId $chunkPending | Out-Null
                            }
                        } catch {}
                        $bag = $null
                        if (-not $Shared.ResultChunks.TryGetValue($commandId, [ref]$bag)) {
                            $bag = [System.Collections.Concurrent.ConcurrentDictionary[int,string]]::new()
                            [void]$Shared.ResultChunks.TryAdd($commandId, $bag)
                            [void]$Shared.ResultChunks.TryGetValue($commandId, [ref]$bag)
                        }
                        $bag[$index] = [string]$body.chunk
                        $Shared.ResultChunkAt[$commandId] = Get-UnixSeconds
                        if ($bag.Count -ge $expected) {
                            $builder = New-Object System.Text.StringBuilder
                            $complete = $true
                            for ($i=1; $i -le $expected; $i++) {
                                $piece = $null
                                if ($bag.TryGetValue($i,[ref]$piece)) { [void]$builder.Append($piece) } else { $complete = $false; break }
                            }
                            if ($complete) { $completeJson = $builder.ToString() }
                        }
                    } elseif ($body.json) { $completeJson = [string]$body.json }
                    elseif ($body.result) { $completeJson = To-Json $body.result 40 }

                    if ($null -ne $completeJson) {
                        $accepted = Complete-CommandResult $sidForResult $commandId $completeJson 'plugin'
                        if ($accepted) {
                            $discardChunks = $null
                            $discardChunkAt = [long]0
                            [void]$Shared.ResultChunks.TryRemove($commandId, [ref]$discardChunks)
                            [void]$Shared.ResultChunkAt.TryRemove($commandId, [ref]$discardChunkAt)
                            Send-Json $context 200 @{ ok=$true; accepted=$true; commandId=$commandId }
                        } elseif ($Shared.CompletedCommandIds.ContainsKey($dedupeKey)) {
                            Send-Json $context 200 @{ ok=$true; duplicate=$true; commandId=$commandId }
                        } else {
                            Send-Json $context 409 @{ ok=$false; code='COMMAND_RESULT_REJECTED'; commandId=$commandId; error='The result payload did not match its commandId or command state.' }
                        }
                    } else {
                        Send-Json $context 200 @{ ok=$true; received=$true; complete=$false; commandId=$commandId }
                    }
                } else {
                    Send-Json $context 400 @{ ok=$false; code='BAD_ARGS'; error='sessionId and commandId are required for a Studio result.' }
                }
                continue
            }

            if ($path -eq '/plugin/command_state') {
                if (-not $body) {
                    Send-Json $context 400 @{ ok=$false; code='BAD_ARGS'; error='JSON body required.' }
                } else {
                    Send-Json $context 200 (Invoke-PluginCommandState $body)
                }
                continue
            }

            if ($path -eq '/plugin/event') {
                if ($body -and $body.sessionId -and $body.event) {
                    $eventKind = [string]$body.event.kind
                    $entry = Get-SessionEntry ([string]$body.sessionId)
                    if ($entry) {
                        # Version 3.8: Nutzer-Aktivitaet vermerken (Edition im
                        # Studio, Kamera, Avatar, GUI) - fuer userWorking-Hinweis.
                        if ($eventKind -eq 'user_active' -or $eventKind -eq 'user_moving_character' -or $eventKind -eq 'user_rotating_camera' -or $eventKind -eq 'user_clicked_gui') {
                            $Shared.UserActiveAt[[string]$body.sessionId] = (Get-UnixSeconds)
                        }
                        # Version 3.8: Play-Wechsel laufen immer durch die
                        # zentrale Verfolgung (klassifiziert startedBy zuver-
                        # laessig auf dem Server, dedupliziert Doppelte).
                        $entry.state = Update-PlayStateTracking ([string]$body.sessionId) $entry.state (Get-StateObject $body)
                        $entry.lastSeen = (Get-UnixSeconds)
                        Save-SessionEntry $entry
                        if ($eventKind -ne 'sim_started' -and $eventKind -ne 'sim_stopped') {
                            Add-BridgeEvent ([string]$body.sessionId) $eventKind ([string]$body.event.message) $body.event.data
                        }
                    } else {
                        Add-BridgeEvent ([string]$body.sessionId) $eventKind ([string]$body.event.message) $body.event.data
                    }
                }
                Send-Json $context 200 @{ ok = $true }
                continue
            }

            if ($path -eq '/plugin/disconnect') {
                if ($body -and $body.sessionId) {
                    $sid = [string]$body.sessionId
                    Add-BridgeEvent $sid 'studio_disconnected' 'The Studio plugin disconnected (Studio closed, place closed or plugins reloading).' @{ reason = [string]$body.reason }
                    $entry = Get-SessionEntry $sid
                    if ($entry) {
                        # Als "verwaist" markieren: meldet sich dasselbe Fenster
                        # wieder (Testmodus, Plugins neu geladen), bekommt es
                        # genau diese Sitzung und denselben Token zurück.
                        $entry | Add-Member -NotePropertyName 'orphan' -NotePropertyValue $true -Force
                        Save-SessionEntry $entry
                    }
                    $removed = $null
                    $removedPresence = [long]0
                    [void]$Shared.Presence.TryRemove($sid, [ref]$removedPresence)
                    $Shared.Pollers[$sid] = 0
                    # Version 7.1.2: Studio ist weg - damit ist auch ein
                    # haengender nativer InsertService:LoadAsset beendet. Die
                    # Import-Sperre und die Toolbox-Drossel werden freigegeben,
                    # damit der Place nach dem Neustart sofort wieder arbeitet.
                    $Shared.ToolboxSlots[$sid] = 0
                    $discardLock = ''
                    [void]$Shared.ToolboxImportLocks.TryRemove($sid, [ref]$discardLock)
                    # Studio is gone: finish pending callers with a diagnostic result;
                    # never strand them by silently deleting the tracking bag.
                    Reset-SessionQueue $sid 'Roblox Studio disconnected while this command was pending. It was abandoned because the old plugin executor is no longer available.' 'EXECUTOR_UNAVAILABLE' | Out-Null
                    [void]$Shared.PendingCommands.TryRemove($sid, [ref]$removed)
                }
                Send-Json $context 200 @{ ok = $true }
                continue
            }

            # Version 7.0.6: Selbstauskunft OHNE Token - sie muss auch dann
            # funktionieren, wenn der Token nicht mehr gueltig ist (genau der
            # Fall, in dem bisher nur geraten wurde). Nur lokal bzw. ueber den
            # eigenen Tunnel erreichbar, ohne Tokens im Inhalt.
            if ($path -eq '/api/version') {
                Send-Json $context 200 (Get-VersionReport)
                continue
            }

            # ---------------- Zugriff prüfen -------------------------------
            $token = Get-Token $context.Request $body
            $sessionId = Get-SessionForToken $token
            if (-not $sessionId) {
                Send-Json $context 401 @{
                    ok = $false
                    error = 'Token ungültig oder Place nicht verbunden.'
                    hint = 'Open the place in Roblox Studio and copy the prompt again from the Arena Roblox Bridge window. Every Studio window has its own token.'
                }
                continue
            }
            # Version 5 aggregate access: one stable token may see many
            # Studio windows, but never guesses a target. Arena must select a
            # listed targetPlace explicitly before sending a mutating/read tool.
            $usingAllPlacesToken = ($sessionId -eq '__arena_all_places__')
            if ($usingAllPlacesToken) {
                $allPlaces = Get-ActiveMultiPlaces
                if ($path -eq '/api/places') {
                    Send-Json $context 200 @{
                        ok=$true; multiPlace=$true; places=$allPlaces; count=$allPlaces.Count
                        instruction='Use one exact places[].targetPlace as targetPlace in every /api/tool or /api/tools/parallel request. Do not infer a target from a display name.'
                    }
                    continue
                }
                $hasRequestedTarget = $false
                try { $hasRequestedTarget = ($body -and $body.PSObject.Properties['targetPlace']) -or ($body -and $body.args -and $body.args.PSObject.Properties['targetPlace']) } catch {}
                if (($path -eq '/api/status' -or $path -eq '/api/place') -and -not $hasRequestedTarget) {
                    Send-Json $context 200 @{
                        ok=$true; multiPlace=$true; bridgeVersion='7.4.1'; docsVersion=[string]$Shared.DocsVersion
                        connectedPlaces=$allPlaces; count=$allPlaces.Count
                        instruction='This is an aggregate token. Call GET /api/places and pass targetPlace with every tool request to work in one selected Place.'
                    }
                    continue
                }
                if ($path -notin @('/api/docs')) {
                    $targetResolution = Resolve-MultiPlaceTarget $body
                    if (-not $targetResolution.ok) { Send-Json $context 409 $targetResolution; continue }
                    $sessionEntry = $targetResolution.entry
                    $sessionId = [string]$sessionEntry.sessionId
                }
            }
            if (-not $sessionEntry) { $sessionEntry = Get-SessionEntry $sessionId }
            $accessMode = 'readwrite'
            [void]$Shared.AccessModes.TryGetValue($sessionId, [ref]$accessMode)

            if ($path -eq '/api/place') {
                Send-Json $context 200 @{ ok = $true; place = $sessionEntry }
                continue
            }

            if ($path -eq '/api/places') {
                # Version 7.1.1: Die Root-Dokumentation nennt GET /api/places; mit
                # einem normalen Place-Token antwortete die Bridge bisher 404.
                # Jetzt: das eigene Place als einziger Eintrag (gleiche Form wie
                # beim Alle-Places-Token), damit Clients nicht raten muessen.
                $ownPlaces = @()
                if ($sessionEntry) {
                    $ownPlaces = @(@{
                        targetPlace = [string]$sessionEntry.sessionId
                        placeName = [string]$sessionEntry.placeName
                        placeId = [string]$sessionEntry.placeId
                        gameId = [string]$sessionEntry.gameId
                        accessMode = $accessMode
                        studio = $sessionEntry.state
                        pluginVersion = [string]$sessionEntry.pluginVersion
                    })
                }
                Send-Json $context 200 @{
                    ok=$true; multiPlace=$false; places=$ownPlaces; count=$ownPlaces.Count
                    instruction='This token controls exactly one Place; targetPlace is optional here. The aggregate Alle-Places token lists several places and requires targetPlace in every request.'
                }
                continue
            }

            if ($path -eq '/api/status') {
                $queueSnapshot = $null
                $queueError = $null
                try {
                    $queueSnapshot = Get-QueueSnapshot $sessionId
                } catch {
                    # Version 7.1.1: Ein Diagnosefehler darf den Status nie zu
                    # einem 500 machen - degradiert antworten und den Grund nennen.
                    $queueError = [string]$_.Exception.Message
                    try { Write-BridgeLog ('Status: Queue-Schnappschuss fehlgeschlagen (degradiert): ' + $queueError) } catch {}
                    $queueSnapshot = @{ ok = $false; error = $queueError; executor = $null; delivery = $null; timeline = @(); recent = @() }
                }
                $statusSim = $false
                $statusNotify = $false
                try { $statusSim = [bool]$Shared.BridgeSettings.simAllowed } catch {}
                try { $statusNotify = [bool]$Shared.BridgeSettings.notifyOnDone } catch {}
                $recentNewSessions = 0
                try {
                    $nowStat = Get-UnixSeconds
                    foreach ($cStamp in @($Shared.SessionCreations.ToArray())) {
                        if ([int64]$cStamp -ge ($nowStat - 60)) { $recentNewSessions = $recentNewSessions + 1 }
                    }
                } catch {}
                # Version 7.1.2: Der Toolbox-Zustand gehoert sichtbar in den
                # Status - bewusst VOR dem Hashtable-Literal berechnet
                # (PowerShell 5.1 ist bei Ausdruecken in Literalen empfindlich).
                $statusToolboxSlots = 0
                try { $slotCount = 0; if ($Shared.ToolboxSlots.TryGetValue([string]$sessionId, [ref]$slotCount)) { $statusToolboxSlots = [int]$slotCount } } catch {}
                $statusToolboxImport = $null
                try { $statusToolboxImport = Get-ToolboxImportLock ([string]$sessionId) } catch {}
                $statusToolbox = @{
                    activeCatalogRequests = [int]$statusToolboxSlots
                    maxCatalogRequests = [int]$Shared.ToolboxLimits.MaxPendingPerPlace
                    activeImport = $statusToolboxImport
                    rule = 'At most one asset import and a strictly limited number of catalog requests per place. Extra calls answer immediately with TOOLBOX_BUSY / TOOLBOX_IMPORT_IN_FLIGHT instead of queueing up.'
                }
                Send-Json $context 200 @{
                    ok = $true
                    bridgeVersion = '7.4.1'
                    serverVersion = '7.4.1'
                    toolbox = $statusToolbox
                    docsVersion = [string]$Shared.DocsVersion
                    place = $sessionEntry
                    connectedPlaces = $Shared.Sessions.Count
                    accessMode = $accessMode
                    pluginVersion = if ($sessionEntry) { [string]$sessionEntry.pluginVersion } else { $null }
                    pluginOutdated = if ($sessionEntry) { [bool]$sessionEntry.versionMismatch } else { $false }
                    restartStudioHint = if ($sessionEntry -and [bool]$sessionEntry.versionMismatch) { 'Studio neu starten: Plugin-Version ist veraltet; Simulationen warten.' } else { $null }
                    queue = $queueSnapshot
                    queueError = $queueError
                    executor = $queueSnapshot.executor
                    # Version 7.0.6: Zustell-Zustand und Sturm-Kennzahlen direkt
                    # im Status - damit ist "hängt es oder ist es tot?" in EINER
                    # Antwort entschieden (auch fuer die KI).
                    delivery = $queueSnapshot.delivery
                    timeline = $queueSnapshot.timeline
                    recentCommands = $queueSnapshot.recent
                    counters = @{
                        newSessionsLast60s = [int]$recentNewSessions
                        newSessionsTotal = [int64]$Shared.Telemetry.NewSessions
                        reusedSessions = [int64]$Shared.Telemetry.ReusedSessions
                        revivedSessions = [int64]$Shared.Telemetry.RevivedSessions
                        unknownSessionPolls = [int64]$Shared.Telemetry.UnknownSessionPolls
                        stormWarnings = [int64]$Shared.Telemetry.StormWarnings
                        fastFailWedged = [int64]$Shared.Telemetry.FastFailWedged
                        fastFailBusy = [int64]$Shared.Telemetry.FastFailBusy
                    }
                    heartbeatHint = 'pluginVersion, pluginOutdated and delivery decide what to do: pluginOutdated=true means Studio runs an old plugin (Studio restart); delivery.state=wedged means Studio stopped answering (Studio restart); delivery.state=ok/busy means normal work.'
                    settings = @{
                        simAllowed = $statusSim
                        notifyOnDone = $statusNotify
                    }
                }
                continue
            }

            if ($path -eq '/api/queue') {
                if ($context.Request.HttpMethod -eq 'GET') {
                    Send-Json $context 200 (Get-QueueSnapshot $sessionId)
                    continue
                }
                if ($context.Request.HttpMethod -ne 'POST' -or -not $body) {
                    Send-Json $context 405 @{ ok=$false; error='Use GET /api/queue for status or POST /api/queue with { action, commandId? }.' }
                    continue
                }
                $action = ([string]$body.action).Trim().ToLowerInvariant()
                if ($action -eq 'cancel') {
                    $commandId = [string]$body.commandId
                    if ([string]::IsNullOrWhiteSpace($commandId)) {
                        Send-Json $context 400 @{ ok=$false; code='BAD_ARGS'; error='commandId is required for action=cancel.' }
                        continue
                    }
                    $cancelled = Request-CommandCancel $sessionId $commandId 'The command was cancelled through the queue control endpoint.'
                    if (-not $cancelled) {
                        Send-Json $context 404 @{ ok=$false; code='PENDING_COMMAND_NOT_FOUND'; error='No pending command with this commandId belongs to the selected Place.'; commandId=$commandId }
                        continue
                    }
                    Add-BridgeEvent $sessionId 'command_cancelled' 'A Studio command was cancelled through queue controls.' @{ commandId=$commandId }
                    Send-Json $context 200 @{ ok=$true; action='cancel'; commandId=$commandId; queue=(Get-QueueSnapshot $sessionId) }
                    continue
                }
                if ($action -eq 'reset' -or $action -eq 'clear') {
                    $resetCount = Reset-SessionQueue $sessionId 'The Studio executor queue was manually reset through queue controls.'
                    Add-BridgeEvent $sessionId 'executor_reset' 'The Studio executor queue was reset; pending commands were marked cancelled.' @{ abandonedCount=$resetCount }
                    Send-Json $context 200 @{ ok=$true; action='reset'; cancelledCommands=$resetCount; queue=(Get-QueueSnapshot $sessionId) }
                    continue
                }
                if ($action -eq 'force_fail' -or $action -eq 'clear_pending' -or $action -eq 'fail_all') {
                    # Version 7.0.5: the admin escape hatch for a wedged queue. Unlike
                    # reset it FAILS every pending command with a real result, so no
                    # caller waits forever and nothing silently disappears.
                    $forced = Force-FailSessionQueue $sessionId 'The command was cleared by the admin queue control (force_fail/clear_pending). Nothing was replayed.' 'FORCE_CLEARED' $action
                    Add-BridgeEvent $sessionId 'executor_force_failed' 'The Studio queue was force-failed through the admin control; every pending command received a final failure result.' @{ clearedCommands=$forced.clearedCommands }
                    $forced.queue = (Get-QueueSnapshot $sessionId)
                    Send-Json $context 200 $forced
                    continue
                }
                Send-Json $context 400 @{ ok=$false; code='BAD_ARGS'; error="Unknown queue action '$action'. Use cancel, reset, clear_pending or force_fail." }
                continue
            }

            if ($path -eq '/api/events') {
                $events = Take-Events $sessionId 40
                Send-Json $context 200 @{ ok = $true; events = $events; count = $events.Count }
                continue
            }

            if ($path -eq '/api/blob') {
                $blobId = $context.Request.QueryString['id']
                $indexText = $context.Request.QueryString['index']
                $index = 1
                if ($indexText) { $index = [int]$indexText }
                Send-Json $context 200 (Get-BlobChunk $blobId $index)
                continue
            }

            if ($path -eq '/api/upload') {
                $result = Invoke-ServerTool $sessionId 'upload_text' $body
                Send-Json $context 200 $result
                continue
            }

            # ---------------- Doku (Tool / Kategorie / komplett) ----------------
            if ($path -eq '/api/docs') {
                $qTool = [string]$context.Request.QueryString['tool']
                $qCategory = [string]$context.Request.QueryString['category']
                $qFull = [string]$context.Request.QueryString['full']
                Send-Json $context 200 (Get-DocsResponse $qTool $qCategory $qFull)
                continue
            }

            # ---------------- Werkzeuge ------------------------------------
            if ($path -eq '/api/tools/parallel') {
                if (-not $body -or -not $body.calls) {
                    Send-Json $context 400 @{ ok = $false; error = 'calls fehlt: { "calls": [ { "tool": "...", "args": {} } ] }' }
                    continue
                }
                # Block sim_start at the desktop boundary too; the plugin has
                # a second guard for batch/parallel/start_job nested calls.
                $blockedTool = $null
                foreach ($call in @($body.calls)) {
                    if ([string]$call.tool -eq 'sim_start') {
                        $blockedTool = 'sim_start'
                        break
                    }
                }
                if ($blockedTool) {
                    $blockedSimPar = New-SimBlockedResult $blockedTool
                    $blockedSimPar._bridge = (New-Envelope $sessionId)
                    Send-Json $context 200 $blockedSimPar
                    continue
                }
                $organicParallelBlocked = $null
                foreach ($call in @($body.calls)) {
                    $candidateTool = [string]$call.tool
                    $candidateArgs = $call.args
                    if ($null -eq $candidateArgs) { $candidateArgs = New-Object PSObject }
                    $organicParallelBlocked = Get-OrganicBuildGuardResult $candidateTool $candidateArgs -ParallelCall
                    if ($null -ne $organicParallelBlocked) {
                        $organicParallelBlocked.tool = $candidateTool
                        $organicParallelBlocked._bridge = (New-Envelope $sessionId)
                        Send-Json $context 200 $organicParallelBlocked
                        break
                    }
                }
                if ($null -ne $organicParallelBlocked) { continue }
                foreach ($call in @($body.calls)) {
                    $callTool = [string]$call.tool
                    if ($callTool -eq 'sim_stop') {
                        $Shared.AiPlayIntents[$sessionId] = @{ action = 'stop'; at = (Get-UnixSeconds) }
                    }
                }
                # Version 7.0.5: stay clearly below Cloudflare's ~100 s 524 limit.
                $timeout = 55
                if ($body.timeoutSeconds) { $timeout = [Math]::Min([int]$body.timeoutSeconds, 85) }
                $parallelProgress = $null
                try { if ($body.PSObject.Properties['progress']) { $parallelProgress = $body.progress } } catch {}
                $resultsJson = Invoke-PluginToolsParallel $sessionId $body.calls $timeout $parallelProgress
                $envelope = New-Envelope $sessionId
                Send-RawJson $context 200 ('{"_bridge":' + (To-Json $envelope 20) + ',"ok":true,"results":' + $resultsJson + '}')
                continue
            }

            if ($path -eq '/api/tool') {
                try { $Shared.Telemetry.ToolCalls = [long]$Shared.Telemetry.ToolCalls + 1 } catch {}
                if (-not $body) {
                    Send-Json $context 400 @{ ok = $false; error = 'JSON Body fehlt.' }
                    continue
                }
                $tool = [string]$body.tool
                if ([string]::IsNullOrWhiteSpace($tool)) {
                    Send-Json $context 400 @{ ok = $false; error = 'Tool fehlt.' }
                    continue
                }
                $toolArgs = $null
                if ($body.PSObject.Properties.Name -contains 'args') { $toolArgs = $body.args }
                if ($null -eq $toolArgs) { $toolArgs = New-Object PSObject }

                # Große Texte, die vorher hochgeladen wurden, einsetzen
                if ($toolArgs.PSObject.Properties.Name -contains 'sourceRef') {
                    $uploaded = $null
                    if ($Shared.Uploads.TryGetValue([string]$toolArgs.sourceRef, [ref]$uploaded)) {
                        $toolArgs | Add-Member -NotePropertyName 'source' -NotePropertyValue $uploaded -Force
                    } else {
                        Send-Json $context 400 @{ ok = $false; error = "Unknown sourceRef '$($toolArgs.sourceRef)'. Upload the text again with upload_text." }
                        continue
                    }
                }

                # Version 7.0.0: FORTSCHRITT EINSAMMELN, BEVOR IRGENDETWAS
                # ans Plugin geht. Liegt progress in args, wird es entfernt -
                # Werkzeuge sehen die Zahl nie.
                $progressNode = $null
                $progressReported = $false
                $progressMessage = ''
                $progressPercent = 0.0
                try {
                    if ($body.PSObject.Properties['progress']) { $progressNode = $body.progress }
                } catch {}
                try {
                    if ($null -eq $progressNode -and $toolArgs.PSObject.Properties['progress']) {
                        $progressNode = $toolArgs.progress
                        try { $toolArgs.PSObject.Properties.Remove('progress') } catch {}
                    }
                } catch {}
                $progressPercentProvided = $false
                if ($null -ne $progressNode) {
                    $progressReported = $true
                    $progressPercentProvided = (Get-ProgressPercentProvided $progressNode)
                    if ($progressNode -is [ValueType] -or $progressNode -is [string]) {
                        $progressPercent = Clamp-ProgressPercent $progressNode
                    } else {
                        try { if ($progressNode.PSObject.Properties['percent']) { $progressPercent = Clamp-ProgressPercent $progressNode.percent } } catch {}
                        try { if ($progressNode.PSObject.Properties['message']) { $progressMessage = [string]$progressNode.message } } catch {}
                    }
                }
                $isDoneTool = ($tool -eq 'report_done')
                $progressState = Update-ArenaProgressState $sessionId $tool $progressPercent $progressMessage $progressReported $isDoneTool $false $progressPercentProvided
                if ($progressReported -and -not [string]::IsNullOrWhiteSpace($progressMessage)) {
                    try { Add-BridgeEvent $sessionId 'progress' $progressMessage @{ percent = $progressPercent; tool = [string]$tool } } catch {}
                }

                # Version 5: the visible Arena history starts as soon as the
                # request reaches the bridge. A Studio timeout deliberately
                # stays blue/running until its late result arrives.
                $activityId = New-ArenaActivity $sessionId $tool $toolArgs
                $argumentCheck = Test-CommandArguments $tool $toolArgs
                if (-not $argumentCheck.ok) {
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $argumentCheck 12)
                    $argumentCheck._bridge = (New-Envelope $sessionId)
                    Send-Json $context 400 $argumentCheck
                    continue
                }

                # ---------------- ASSET-VORPRUEFUNG ------------------------
                # Die Id muss zum Typ passen, BEVOR Studio angefasst wird.
                # (Vorher lief ein falsches rbxassetid erst als Laufzeitfehler auf.)
                if (($tool -eq 'apply_asset' -or $tool -eq 'insert_asset') -and $toolArgs.assetId -and $toolArgs.skipValidation -ne $true) {
                    $expectType = $null
                    if ($tool -eq 'insert_asset') {
                        $expectType = 'model'
                    } elseif ($toolArgs.property) {
                        $prop = ([string]$toolArgs.property).ToLowerInvariant()
                        if ($prop -eq 'soundid') { $expectType = 'audio' }
                        elseif ($prop -eq 'animationid') { $expectType = 'animation' }
                        elseif ($prop -eq 'texture' -or $prop -eq 'textureid') { $expectType = 'texture' }
                        elseif ($prop -eq 'image') { $expectType = 'image' }
                        elseif ($prop -eq 'meshid') { $expectType = 'mesh' }
                        elseif ($prop -eq 'videoid') { $expectType = 'video' }
                    }
                    if ($expectType) {
                        # Version 7.1.2: auch die Vorpruefung laeuft durch das
                        # Toolbox-Tor (Begrenzung + garantierte Freigabe) und hat
                        # ein hartes Zeitlimit - sie darf das Tunnel-Zeitfenster
                        # von insert_asset nicht aufbrauchen.
                        $validation = Invoke-ToolboxServerTool $sessionId 'validate_asset' @{ assetId = [string]$toolArgs.assetId; expectType = $expectType }
                        if ($validation.ok -eq $false) {
                            Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $validation 40)
                            $validation._bridge = (New-Envelope $sessionId)
                            Send-Json $context 200 $validation
                            continue
                        }
                        if ($validation.verified -eq $true -and $validation.matchesExpect -eq $false) {
                            $mismatch = @{
                                ok = $false
                                code = 'ASSET_TYPE_MISMATCH'
                                error = "Asset $($toolArgs.assetId) is a $($validation.typeName) (typeId $($validation.typeId)), but '$expectType' was expected. It was NOT applied."
                                actual = @{ typeId = $validation.typeId; typeName = $validation.typeName; usableAs = $validation.usableAs; assetName = [string]$validation.assetName }
                                howToFix = "Run search_assets with type='$expectType' and apply a matching id from the result. If the catalog is unavailable, say so and build procedurally - never guess ids."
                            }
                            Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $mismatch 40)
                            $mismatch._bridge = (New-Envelope $sessionId)
                            Send-Json $context 200 $mismatch
                            continue
                        }
                        if ($tool -eq 'insert_asset' -and $validation.verified -eq $true -and $validation.hasScripts -eq $true -and $toolArgs.acceptScripts -ne $true -and $toolArgs.sanitize -ne $true -and $toolArgs.removeScripts -ne $true) {
                            $hasScripts = @{
                                ok = $false
                                code = 'ASSET_HAS_SCRIPTS'
                                error = "Asset $($toolArgs.assetId) ('$($validation.assetName)') CONTAINS SCRIPTS. It was not inserted."
                                howToFix = 'Recommended for script-free searches: repeat with sanitize=true. The asset is cleaned while detached, before insertion; scripts, remote events/functions and bindable event plumbing are destroyed. Use acceptScripts=true only if the scripts are intentionally required.'
                            }
                            Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $hasScripts 40)
                            $hasScripts._bridge = (New-Envelope $sessionId)
                            Send-Json $context 200 $hasScripts
                            continue
                        }
                    }
                }

                # Version 7.0.5: ADMIN-RESET als Tool (nicht als Studio-Befehl). Der
                # Aufruf raeumt eine haengende Queue sofort auf, OHNE dass die KI
                # einen Studio-Neustart braucht; jeder wartende Befehl bekommt eine
                # endgueltige Fehlerantwort (Waiter oder lateResult).
                if ($tool -eq 'clear_pending' -or $tool -eq 'force_fail') {
                    $forcedCode = 'FORCE_CLEARED'
                    if ($toolArgs -and $toolArgs.code) { $forcedCode = ([string]$toolArgs.code).Trim().ToUpperInvariant() }
                    if ([string]::IsNullOrWhiteSpace($forcedCode)) { $forcedCode = 'FORCE_CLEARED' }
                    $forcedReason = 'The queued Studio work was cleared through the ' + $tool + ' control. Nothing was replayed; inspect the Place before retrying.'
                    if ($toolArgs -and $toolArgs.reason) { $forcedReason = [string]$toolArgs.reason }
                    $forcedResult = Force-FailSessionQueue $sessionId $forcedReason $forcedCode $tool
                    Add-BridgeEvent $sessionId 'executor_force_failed' 'The Studio queue was force-failed through a tool call; every pending command received a final failure result.' @{ clearedCommands=$forcedResult.clearedCommands; tool=$tool }
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $forcedResult 40)
                    $forcedResult._bridge = (New-Envelope $sessionId)
                    Send-Json $context 200 $forcedResult
                    continue
                }

                $serverResult = Invoke-ServerTool $sessionId $tool $toolArgs
                if ($null -ne $serverResult) {
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $serverResult 40)
                    $serverResult['_bridge'] = (New-Envelope $sessionId)
                    Send-Json $context 200 $serverResult
                    continue
                }

                $writeTools = @('set_property','set_properties','bulk_set_properties','set_attribute','create_instance','bulk_create',
                    'clone_instance','delete_instance','bulk_delete','rename_instance','move_instance','set_script_source','patch_script',
                    'insert_script','bulk_insert_scripts','select_instance','run_lua','batch','parallel','union','subtract','negate','intersect',
                    'separate','insert_asset','apply_asset','group_instances','ungroup','add_tag','remove_tag','place_on','align','stack',
                    'grid_arrange','distribute','snap_to_ground','look_at','rotate_around','move_relative','resize_part','fit_between','point_at',
                    'sim_start','undo','redo','clear_output','fill_region','probe_world','start_job',
                    'cancel_job','clear_lua_state','build_polygon_model','build_assembly','mesh_slots','mesh_apply','build_surface','build_interface')
                $persistentEditTools = @('set_property','set_properties','bulk_set_properties','set_attribute','create_instance','bulk_create',
                    'clone_instance','delete_instance','bulk_delete','rename_instance','move_instance','set_script_source','patch_script',
                    'insert_script','bulk_insert_scripts','run_lua','batch','parallel','union','subtract','negate','intersect','separate',
                    'insert_asset','apply_asset','group_instances','ungroup','add_tag','remove_tag','place_on','align','stack','grid_arrange',
                    'distribute','snap_to_ground','look_at','rotate_around','move_relative','resize_part','fit_between','point_at','fill_region','build_polygon_model','build_assembly','mesh_slots','mesh_apply','build_surface','build_interface','start_job','prop_place','prop_save','refine','world_style','style_lock','world_glow','ui_glow','ui_radial','ui_texture','undo','redo')
                $organicGuard = Get-OrganicBuildGuardResult $tool $toolArgs
                if ($null -ne $organicGuard) {
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $organicGuard 20)
                    $organicGuard._bridge = (New-Envelope $sessionId)
                    Send-Json $context 200 $organicGuard
                    continue
                }
                if ($sessionEntry -and $sessionEntry.state -and [bool]$sessionEntry.state.running -and [bool]$sessionEntry.state.userPlaytestActive -and $persistentEditTools -contains $tool) {
                    $blocked = @{
                        ok = $false
                        code = 'USER_PLAYTEST_ACTIVE'
                        severity = 'critical'
                        assistantAction = 'STOP_OR_YIELD'
                        error = "IMPORTANT: Roblox Studio is currently in $([string]$sessionEntry.state.mode) mode and the USER started it. The requested edit '$tool' was NOT sent to Studio."
                        why = 'The user is playing/testing the game. Editing now would interrupt them and persistent changes would be discarded when the test ends. Since 7.0.0 there is no play_stop any more - the bridge cannot stop the user test.'
                        requiredResponse = 'End your response and ask the user to stop the test themselves (Shift+F5) or to message you when Studio is free again. Reading tools stay available. Never claim the changes were saved.'
                        suggestedUserMessage = 'Ich sehe, dass du Roblox Studio gerade selbst testest. Parallel kann ich nicht sicher bauen. Beende den Test bitte selbst (Shift+F5) oder sag mir Bescheid, wenn ich in Ruhe weiterarbeiten darf.'
                    }
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $blocked 40)
                    $blocked._bridge = (New-Envelope $sessionId)
                    Send-Json $context 200 $blocked
                    continue
                }

                # sim_start is never dispatched to Studio. The remaining status
                # and cleanup calls receive an explicit false availability bit.
                if ($tool -eq 'sim_start') {
                    $blockedSim = New-SimBlockedResult $tool
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $blockedSim 40)
                    $blockedSim._bridge = (New-Envelope $sessionId)
                    Send-Json $context 200 $blockedSim
                    continue
                }
                if ($accessMode -eq 'readonly' -and $writeTools -contains $tool) {
                    $readOnlyResult = @{ ok=$false; code='READONLY_TOKEN'; error=("The tool '" + $tool + "' changes the place, but this token is set to read only.") }
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $readOnlyResult 12)
                    Send-Json $context 200 @{
                        ok = $false
                        code = 'READONLY_TOKEN'
                        error = "The tool '$tool' changes the place, but this token is set to read only."
                        hint = 'The user can switch this place to "Vollzugriff" in the Arena Roblox Bridge window. Until then only reading tools work.'
                    }
                    continue
                }

                # ---------------- TOOLBOX-IMPORT-TOR (Version 7.1.2) -------
                # Hoechstens EIN aktiver Asset-Import je Place, Idempotenz gegen
                # Wiederholungen nach einem Client-Timeout, und bei einem
                # haengenden nativen Import KEIN zweiter Versuch.
                $insertGateKey = $null
                if ($tool -eq 'insert_asset') {
                    $insertKey = Get-ToolboxInsertKey $sessionId $toolArgs
                    $replayJson = Get-ToolboxInsertReplay $insertKey $toolArgs
                    if ($null -ne $replayJson) {
                        $replay = $null
                        try { $replay = $replayJson | ConvertFrom-Json } catch {}
                        if ($null -eq $replay) { $replay = [pscustomobject]@{ ok = $true } }
                        $replay | Add-Member -NotePropertyName 'idempotentReplay' -NotePropertyValue $true -Force
                        $replay | Add-Member -NotePropertyName 'note' -NotePropertyValue ('This exact insert_asset already succeeded less than ' + [string]$Shared.ToolboxLimits.IdempotencyWindowSec + ' s ago. The stored result is returned AGAIN - nothing was inserted a second time. Pass allowDuplicate=true (or a new requestId) if you really want another copy.') -Force
                        Complete-ArenaActivity $sessionId $activityId $tool $toolArgs $replayJson
                        $replay | Add-Member -NotePropertyName '_bridge' -NotePropertyValue (New-Envelope $sessionId) -Force
                        Send-Json $context 200 $replay
                        continue
                    }
                    $importGate = Enter-ToolboxImport $sessionId $insertKey $toolArgs
                    if (-not $importGate.ok) {
                        $gateResult = $importGate.result
                        Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $gateResult 12)
                        $gateResult._bridge = (New-Envelope $sessionId)
                        Send-Json $context 200 $gateResult
                        continue
                    }
                    $insertGateKey = $insertKey
                }

                # Version 7.0.5: never hold a Cloudflare-proxied request long enough
                # for the ~100 s 524 to hit. A longer Studio job keeps running and is
                # picked up as a lateResult (or asJob=true from the start).
                $timeout = 55
                if ($toolArgs.timeoutSeconds) {
                    $timeout = [Math]::Min([int]$toolArgs.timeoutSeconds + 25, 85)
                }
                if ($body.timeoutSeconds) {
                    $timeout = [Math]::Min([int]$body.timeoutSeconds, 85)
                }

                # Langer Lauf? Als Job in den Hintergrund - läuft sicher über 60 s hinaus.
                $isJobCall = ($toolArgs.asJob -eq $true) -or ($tool -eq 'start_job')

                # Version 3.8: Play-Absicht der KI vermerken - der SERVER weiss
                # dann zuverlaessig, wer einen Test gestartet/gestoppt hat
                # (das ueberlebt auch ein echtes Neu-Laden des Plugins durch Studio).
                if ($tool -eq 'sim_stop') {
                    $Shared.AiPlayIntents[$sessionId] = @{ action = 'stop'; at = (Get-UnixSeconds) }
                }

                $resultJson = Get-DedupedPlayResult $sessionId $tool $toolArgs
                $reservedPlay = $false
                if ($null -eq $resultJson) { $reservedPlay = Reserve-PlayRetry $sessionId $tool $toolArgs }
                if ($null -eq $resultJson -and $reservedPlay) { $resultJson = Invoke-PluginTool $sessionId $tool $toolArgs $timeout $activityId }
                if ($null -eq $resultJson -and -not $reservedPlay) { $resultJson = Get-DedupedPlayResult $sessionId $tool $toolArgs }
                if ($null -ne $resultJson -and $insertGateKey) {
                    # Endzustand erreicht -> Sperre IMMER freigeben. Nur ein
                    # wirklich erfolgreicher Import wird fuer die Idempotenz
                    # gemerkt (ein BUSY/Fehler darf nicht wiedergespielt werden).
                    Exit-ToolboxImport $sessionId
                    $insertSucceeded = $false
                    try { $insertSucceeded = [bool](($resultJson | ConvertFrom-Json).ok) } catch {}
                    if ($insertSucceeded) { Save-ToolboxInsertResult $insertGateKey $resultJson }
                    $insertGateKey = $null
                }
                if ($null -ne $resultJson) {
                    Save-DedupedPlayResult $sessionId $tool $toolArgs $resultJson
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs $resultJson
                    $resultEnvelope = $null
                    $pluginPayload = $null
                    $resultSucceeded = $false
                    try {
                        $resultEnvelope = $resultJson | ConvertFrom-Json
                        if ($null -ne $resultEnvelope) {
                            $resultSucceeded = ([bool]$resultEnvelope.ok -eq $true)
                            $pluginPayload = $resultEnvelope
                            if ($resultEnvelope.PSObject.Properties['result'] -and $null -ne $resultEnvelope.result) {
                                $pluginPayload = $resultEnvelope.result
                            }
                        }
                    } catch {}
                    $resultAtTicks = [DateTime]::UtcNow.Ticks

                    # Remember the actual returned model so report_done can demand
                    # an audit of this precise organic build even when the build
                    # request timed out/reconnected before any later audit arrives.
                    # Version 7.2.0 (AP6): Jeder erfolgreiche Modell-Bau wird
                    # registriert (unabhaengig von organisch). Ein Audit traegt
                    # Note und Entwurfs-Kennzeichen nach.
                    if ($resultSucceeded -and $pluginPayload) {
                        try { Register-SessionBuild $sessionId $tool $toolArgs $pluginPayload $resultAtTicks } catch {}
                        if ($tool -eq 'model_audit') {
                            try { Update-SessionBuildAudit $sessionId $pluginPayload $resultAtTicks } catch {}
                        }
                        # Version 7.2.0 (AP7): Code-Struktur je Sitzung merken.
                        try {
                            if ($pluginPayload.PSObject.Properties['codeLayout'] -and $null -ne $pluginPayload.codeLayout) {
                                $layoutView = $pluginPayload.codeLayout
                                $layoutJson = ($layoutView | ConvertTo-Json -Depth 6 -Compress)
                                $Shared.CodeLayouts[[string]$sessionId] = [string]$layoutJson
                                Add-ChannelCount 'CodeLayoutChecked' 1
                                $layoutRisk = $false
                                try { $layoutRisk = [bool]$layoutView.monolithRisk } catch {}
                                if ($layoutRisk) {
                                    Add-ChannelCount 'UiMonolithFlags' 1
                                    Write-FlowStation 'UISTRUCTURE' (Get-ShortSid $sessionId) 'MONOLITH_RISK' @{ tool = $tool; level = ([string]$layoutView.level); lines = ([string]$layoutView.lines); instanceNew = ([string]$layoutView.instanceNewCalls) }
                                }
                            }
                        } catch {}
                    }
                    if ($resultSucceeded -and $tool -eq 'build_polygon_model' -and $pluginPayload.organic -eq $true) {
                        $builtModel = $null
                        try { $builtModel = $pluginPayload.model } catch {}
                        $organicJson = ''
                        $organicState = $null
                        if ($Shared.OrganicBuilds.TryGetValue([string]$sessionId, [ref]$organicJson) -and -not [string]::IsNullOrWhiteSpace($organicJson)) {
                            try { $organicState = $organicJson | ConvertFrom-Json } catch { $organicState = $null }
                        }
                        $organicRecords = @()
                        if ($organicState) {
                            try { $organicRecords = @($organicState.models) } catch {}
                            if ($organicRecords.Count -eq 0 -and $organicState.PSObject.Properties['modelId']) { $organicRecords = @($organicState) }
                        }
                        foreach ($priorOrganicRecord in $organicRecords) {
                            if (-not $priorOrganicRecord.PSObject.Properties['lastWriteAtTicks']) { $priorOrganicRecord | Add-Member -NotePropertyName lastWriteAtTicks -NotePropertyValue 0L }
                            if (-not $priorOrganicRecord.PSObject.Properties['auditAtTicks']) { $priorOrganicRecord | Add-Member -NotePropertyName auditAtTicks -NotePropertyValue 0L }
                            $priorOrganicRecord.lastWriteAtTicks = $resultAtTicks
                            $priorOrganicRecord.auditAtTicks = 0L
                            $priorOrganicRecord.auditScope = ''
                            $priorOrganicRecord.auditQuality = $null
                            $priorOrganicRecord.auditModels = @()
                            $priorOrganicRecord.detected = $false
                        }
                        $organicRecords += @(@{
                            required = $true
                            detected = $false
                            modelId = $(if ($builtModel) { [string]$builtModel.id } else { '' })
                            modelPath = $(if ($builtModel) { [string]$builtModel.path } else { '' })
                            modelName = $(if ($builtModel) { [string]$builtModel.name } else { [string]$toolArgs.modelName })
                            buildAtTicks = $resultAtTicks
                            lastWriteAtTicks = $resultAtTicks
                            auditAtTicks = 0L
                            auditScope = ''
                            auditQuality = $null
                            auditModels = @()
                        })
                        $organicState = [pscustomobject]@{ required = $true; models = $organicRecords }
                        $Shared.OrganicBuilds[[string]$sessionId] = ($organicState | ConvertTo-Json -Depth 12 -Compress)
                    } elseif ($resultSucceeded -and $persistentEditTools -contains $tool) {
                        $organicJson = ''
                        if ($Shared.OrganicBuilds.TryGetValue([string]$sessionId, [ref]$organicJson) -and -not [string]::IsNullOrWhiteSpace($organicJson)) {
                            try {
                                $organicState = $organicJson | ConvertFrom-Json
                                $organicRecords = @()
                                try { $organicRecords = @($organicState.models) } catch {}
                                if ($organicRecords.Count -eq 0 -and $organicState.PSObject.Properties['modelId']) { $organicRecords = @($organicState) }
                                foreach ($organicRecord in $organicRecords) {
                                    if (-not $organicRecord.PSObject.Properties['lastWriteAtTicks']) { $organicRecord | Add-Member -NotePropertyName lastWriteAtTicks -NotePropertyValue 0L }
                                    if (-not $organicRecord.PSObject.Properties['auditAtTicks']) { $organicRecord | Add-Member -NotePropertyName auditAtTicks -NotePropertyValue 0L }
                                    $organicRecord.lastWriteAtTicks = $resultAtTicks
                                    $organicRecord.auditAtTicks = 0L
                                    $organicRecord.auditScope = ''
                                    $organicRecord.auditQuality = $null
                                    $organicRecord.auditModels = @()
                                    $organicRecord.detected = $false
                                }
                                $organicState.required = $true
                                $organicState.models = $organicRecords
                                $Shared.OrganicBuilds[[string]$sessionId] = ($organicState | ConvertTo-Json -Depth 12 -Compress)
                            } catch {}
                        }
                    }

                    # Version 7.0.0: Audit-Kennzahlen mitschreiben. The plugin
                    # response is { ok, result, warnings }; unwrap it before
                    # reading fields so report_done never reasons from empty data.
                    if ($resultSucceeded -and ($tool -eq 'ui_audit' -or $tool -eq 'model_audit' -or $tool -eq 'world_audit' -or $tool -eq 'site_survey' -or $tool -eq 'lag_doctor')) {
                        try {
                            $auditResult = $pluginPayload
                            $placeholderCount = 0
                            $placeholders = @()
                            try { if ($auditResult.PSObject.Properties['placeholderCount']) { $placeholderCount = [int]$auditResult.placeholderCount } } catch {}
                            try { if ($auditResult.PSObject.Properties['placeholders']) { $placeholders = @($auditResult.placeholders) } } catch {}
                            if ($placeholderCount -le 0) {
                                # Also account for ui_audit/report-style nested counts.
                                try { if ($auditResult.PSObject.Properties['counts'] -and $auditResult.counts.PSObject.Properties['placeholders']) { $placeholderCount = [int]$auditResult.counts.placeholders } } catch {}
                            }
                            $primitiveAbuse = $false
                            $primitiveGroups = @()
                            $cylinderProblemCount = 0
                            $buildQuality = $null
                            $organicQuality = $null
                            try { if ($auditResult.PSObject.Properties['primitiveAbuse']) { $primitiveAbuse = [bool]$auditResult.primitiveAbuse } } catch {}
                            try { if ($auditResult.PSObject.Properties['buildQuality']) { $buildQuality = $auditResult.buildQuality } } catch {}
                            try { if ($buildQuality -and $buildQuality.PSObject.Properties['primitiveGroups']) { $primitiveGroups = @($buildQuality.primitiveGroups) } } catch {}
                            try { if ($auditResult.PSObject.Properties['cylinderProblemCount']) { $cylinderProblemCount = [int]$auditResult.cylinderProblemCount } } catch {}
                            try { if ($buildQuality -and $buildQuality.PSObject.Properties['organicQuality']) { $organicQuality = $buildQuality.organicQuality } } catch {}
                            $buildVerdict = ''
                            try { if ($buildQuality -and $buildQuality.PSObject.Properties['verdict']) { $buildVerdict = [string]$buildQuality.verdict } } catch {}
                            $organicDetected = $false
                            $organicIssues = @()
                            $organicPolygonTriangles = 0
                            $organicModelCount = 0
                            try { if ($organicQuality) { $organicDetected = [bool]$organicQuality.detected } } catch {}
                            try { if ($organicQuality) { $organicIssues = @($organicQuality.issues) } } catch {}
                            try { if ($organicQuality) { $organicPolygonTriangles = [int]$organicQuality.polygonTriangles } } catch {}
                            try { if ($organicQuality) { $organicModelCount = [int]$organicQuality.modelCount } } catch {}
                            $summary = ''
                            try {
                                if ($tool -eq 'ui_audit') { $summary = 'ui_audit: blandness ' + [string]$auditResult.blandnessScore + ', techniqueScore ' + [string]$auditResult.techniqueScore }
                                else { $summary = $tool + ': ' + [string]$auditResult.verdict + ' (' + [string]$auditResult.phase + ')' }
                            } catch {}
                            if ($primitiveAbuse -or $cylinderProblemCount -gt 0 -or $organicIssues.Count -gt 0) {
                                $summary = $summary + ' | buildQuality ' + $buildVerdict
                            }
                            # Version 7.2.0 (AP6): Note und Fertig-Punktzahl gehoeren
                            # in jede Antwort, damit ein Entwurf auffaellt, BEVOR die
                            # Arbeit als fertig gemeldet wird.
                            $buildGrade = ''
                            $buildFinishScore = -1
                            $buildDraftRisk = $false
                            try { if ($buildQuality -and $buildQuality.PSObject.Properties['grade']) { $buildGrade = [string]$buildQuality.grade } } catch {}
                            try { if ($buildQuality -and $buildQuality.PSObject.Properties['finishScore']) { $buildFinishScore = [int]$buildQuality.finishScore } } catch {}
                            try { if ($buildQuality -and $buildQuality.PSObject.Properties['draftRisk']) { $buildDraftRisk = [bool]$buildQuality.draftRisk } } catch {}
                            $meshSlotCount = 0
                            $meshSlots = @()
                            try { if ($auditResult.PSObject.Properties['meshSlotCount']) { $meshSlotCount = [int]$auditResult.meshSlotCount } } catch {}
                            try { if ($auditResult.PSObject.Properties['meshSlots']) { $meshSlots = @($auditResult.meshSlots) } } catch {}
                            $flag = [pscustomobject]@{
                                placeholderCount = $placeholderCount
                                placeholders = $placeholders
                                meshSlotCount = $meshSlotCount
                                meshSlots = $meshSlots
                                summary = $summary
                                phase = $(try { [string]$auditResult.phase } catch { '' })
                                primitiveAbuse = $primitiveAbuse
                                primitiveGroups = $primitiveGroups
                                cylinderProblemCount = $cylinderProblemCount
                                buildQualityVerdict = $buildVerdict
                                buildGrade = $buildGrade
                                finishScore = $buildFinishScore
                                draftRisk = $buildDraftRisk
                                organicDetected = $organicDetected
                                organicIssues = $organicIssues
                                organicPolygonTriangles = $organicPolygonTriangles
                                organicModelCount = $organicModelCount
                                organicQuality = $organicQuality
                                at = (Get-UnixSeconds)
                                atTicks = $resultAtTicks
                            }
                            $Shared.AuditFlags[[string]$sessionId] = ($flag | ConvertTo-Json -Depth 10 -Compress)

                            # Persist each organic model independently. A Workspace
                            # audit can refresh all returned candidates; an audit of
                            # one ref refreshes only that exact model.
                            if ($tool -eq 'model_audit') {
                                $organicJson = ''
                                $organicState = $null
                                if ($Shared.OrganicBuilds.TryGetValue([string]$sessionId, [ref]$organicJson) -and -not [string]::IsNullOrWhiteSpace($organicJson)) {
                                    try { $organicState = $organicJson | ConvertFrom-Json } catch { $organicState = $null }
                                }
                                $organicRecords = @()
                                if ($organicState) {
                                    try { $organicRecords = @($organicState.models) } catch {}
                                    if ($organicRecords.Count -eq 0 -and $organicState.PSObject.Properties['modelId']) { $organicRecords = @($organicState) }
                                }
                                $qualityModels = @()
                                try { if ($organicQuality) { $qualityModels = @($organicQuality.models) } } catch {}
                                foreach ($modelEvidence in $qualityModels) {
                                    $evidenceId = [string]$modelEvidence.id
                                    $evidencePath = [string]$modelEvidence.path
                                    $organicRecord = $null
                                    foreach ($candidateRecord in $organicRecords) {
                                        if (-not [string]::IsNullOrWhiteSpace($evidenceId) -and [string]$candidateRecord.modelId -eq $evidenceId) { $organicRecord = $candidateRecord; break }
                                        if ([string]::IsNullOrWhiteSpace([string]$candidateRecord.modelId) -and -not [string]::IsNullOrWhiteSpace($evidencePath) -and [string]$candidateRecord.modelPath -eq $evidencePath) { $organicRecord = $candidateRecord; break }
                                        if ([string]::IsNullOrWhiteSpace([string]$candidateRecord.modelId) -and [string]::IsNullOrWhiteSpace([string]$candidateRecord.modelPath) -and -not [string]::IsNullOrWhiteSpace([string]$candidateRecord.modelName) -and [string]$candidateRecord.modelName -eq [string]$modelEvidence.name) { $organicRecord = $candidateRecord; break }
                                    }
                                    if ($null -eq $organicRecord) {
                                        $organicRecord = [pscustomobject]@{
                                            required = $true; detected = $false; modelId = $evidenceId; modelPath = $evidencePath; modelName = [string]$modelEvidence.name
                                            buildAtTicks = 0L; lastWriteAtTicks = 0L; auditAtTicks = 0L; auditScope = ''
                                            auditQuality = $null; auditModels = @()
                                        }
                                        $organicRecords += @($organicRecord)
                                    }
                                    $modelIssues = @($modelEvidence.issues)
                                    $perModelQuality = [pscustomobject]@{
                                        detected = $true
                                        modelCount = 1
                                        polygonTriangles = [int]$modelEvidence.polygonTriangles
                                        uniqueColors = [int]$modelEvidence.uniqueColors
                                        dominantColorShare = [double]$modelEvidence.dominantColorShare
                                        nearWhiteShare = [double]$modelEvidence.nearWhiteShare
                                        motionScripts = [int]$modelEvidence.motionScripts
                                        issues = $modelIssues
                                        models = @($modelEvidence)
                                    }
                                    $organicRecord.required = $true
                                    $organicRecord.detected = $true
                                    $organicRecord.modelId = $evidenceId
                                    $organicRecord.modelPath = $evidencePath
                                    $organicRecord.modelName = [string]$modelEvidence.name
                                    $organicRecord.auditAtTicks = $resultAtTicks
                                    $organicRecord.auditScope = [string]$auditResult.scope
                                    $organicRecord.auditQuality = $perModelQuality
                                    $organicRecord.auditModels = @($modelEvidence)
                                }
                                if ($organicDetected -and $qualityModels.Count -eq 0 -and $organicRecords.Count -eq 0) {
                                    # Detection without the promised per-model detail
                                    # is an explicit incomplete record, never a pass.
                                    $organicRecords = @([pscustomobject]@{
                                        required = $true; detected = $false; modelId = ''; modelPath = ''; modelName = ''
                                        buildAtTicks = 0L; lastWriteAtTicks = 0L; auditAtTicks = 0L; auditScope = [string]$auditResult.scope
                                        auditQuality = $organicQuality; auditModels = @()
                                    })
                                }
                                $reportedOrganicCount = 0
                                try { if ($organicQuality) { $reportedOrganicCount = [int]$organicQuality.modelCount } } catch {}
                                if ($organicDetected -and $reportedOrganicCount -gt $qualityModels.Count) {
                                    $organicRecords += @([pscustomobject]@{
                                        required = $true; detected = $false; modelId = ''; modelPath = ''; modelName = 'unreported organic model(s)'
                                        buildAtTicks = 0L; lastWriteAtTicks = 0L; auditAtTicks = 0L; auditScope = [string]$auditResult.scope
                                        auditQuality = $null; auditModels = @()
                                    })
                                }
                                if ($organicRecords.Count -gt 0) {
                                    $organicState = [pscustomobject]@{ required = $true; models = $organicRecords }
                                    $Shared.OrganicBuilds[[string]$sessionId] = ($organicState | ConvertTo-Json -Depth 14 -Compress)
                                }
                            }
                        } catch {}
                    }
                }
                if ($null -eq $resultJson) {
                    $entryNow = Get-SessionEntry $sessionId
                    $stillRunning = Get-PendingCommands $sessionId
                    # Bewusst Status 200: die KI soll den Hinweistext lesen können.
                    $timeoutBody = @{
                        ok = $false
                        code = 'STUDIO_TIMEOUT'
                        error = "Roblox Studio did not answer within $timeout seconds."
                        workIsLost = $false
                        hint = 'The command remains tracked by commandId and may still be running; the executor enforces a hard budget and heartbeat watchdog so a hung command cannot block the queue forever. Check GET /api/queue and _bridge.studioBusy / _bridge.lateResults. If it is abandoned, inspect for partial changes before retrying.'
                        studio = if ($entryNow) { $entryNow.state } else { $null }
                        betterWay = 'For work that takes longer than 60 seconds: repeat this call with args.asJob=true (or use the start_job tool). You get a jobId back immediately and poll it with job_status / job_result - there is no timeout to hit.'
                    }
                    if ($stillRunning.Count -gt 0) {
                        $timeoutBody.pendingInStudio = $stillRunning
                    }
                    if ($isJobCall) {
                        $timeoutBody.note = 'This call was a job call. If it was accepted before the timeout the job is running - use list_jobs / job_status to find it.'
                    }
                    if ($insertGateKey) {
                        # Version 7.1.2: Die Import-Sperre bleibt ABSICHTLICH
                        # stehen. Der native InsertService:LoadAsset kann noch
                        # laufen - ein zweiter Import wuerde doppelt einfuegen
                        # und Studio weiter belasten. Hier wird NICHT so getan,
                        # als waere der Aufruf abgebrochen worden.
                        Set-ToolboxImportUnconfirmed $sessionId
                        $timeoutBody.code = 'TOOLBOX_IMPORT_UNCONFIRMED'
                        $timeoutBody.importLocked = $true
                        $timeoutBody.cancellable = $false
                        $timeoutBody.error = "Roblox Studio did not answer the asset import within $timeout seconds. Roblox cannot abort a running InsertService:LoadAsset, so the bridge does NOT pretend to cancel it."
                        $timeoutBody.hint = 'Further imports for this place are BLOCKED until the result arrives or Studio is restarted. Do NOT retry - a retry can insert the model twice.'
                        $timeoutBody.howToFix = 'Check GET /api/queue and _bridge.lateResults once. If nothing arrives, tell the user (in German) to close Roblox Studio COMPLETELY and reopen the place, then check the place for a half-inserted model. Build the model procedurally instead of importing it again.'
                        $insertGateKey = $null
                    }
                    # Version 7.1.2: Der Verlaufseintrag darf NICHT weiter auf
                    # "Macht gerade" stehen bleiben. Kommt spaeter doch ein
                    # echtes Ergebnis, ueberschreibt Complete-Command diesen
                    # Endzustand wieder mit dem tatsaechlichen Ausgang.
                    Complete-ArenaActivity $sessionId $activityId $tool $toolArgs (To-Json $timeoutBody 12) 'timed_out'
                    Send-Json $context 200 $timeoutBody
                    continue
                }

                $envelope = New-Envelope $sessionId

                # Start-Doku: nur bei der ersten Tool-Antwort dieser Sitzung,
                # damit die KI ohne Extra-Call ALLE Informationen hat.
                $docsSent = $false
                [void]$Shared.DocsSent.TryGetValue([string]$sessionId, [ref]$docsSent)
                if (-not $docsSent) {
                    $docsSent = $true
                    [void]$Shared.DocsSent.TryAdd([string]$sessionId, $true)
                }

                if ($resultJson.Length -gt $MaxInline) {
                    $blob = New-Blob $resultJson $tool
                    $summary = @{
                        ok = $true
                        delivery = 'chunked'
                        reason = "The answer is $($resultJson.Length) characters long - too big for one response, but nothing was cut off."
                        blobId = $blob.blobId
                        chunkCount = $blob.chunkCount
                        chunkSize = $blob.chunkSize
                        totalChars = $blob.totalChars
                        howTo = "Call the tool get_chunk with { blobId: '$($blob.blobId)', index: 1 } ... up to index $($blob.chunkCount) and concatenate the 'data' fields, then parse the JSON."
                        preview = $resultJson.Substring(0, [Math]::Min(1500, $resultJson.Length))
                        '_bridge' = $envelope
                    }
                    if (-not $docsSent) {
                        $summary._sessionStart = (Get-SessionStartPackage)
                    }
                    Send-Json $context 200 $summary
                    continue
                }

                $merged = Merge-Envelope $resultJson $envelope
                if (-not $docsSent) {
                    $merged = Merge-ExtraJson $merged '_sessionStart' (To-Json (Get-SessionStartPackage) 40)
                }
                Send-RawJson $context 200 $merged
                continue
            }

            Send-Json $context 404 @{ ok = $false; error = 'Route nicht gefunden.' }
        } catch {
            $errMsg = ''
            $errId = ''
            $errLine = ''
            $errTrace = ''
            $reqPath = ''
            try { $errMsg = [string]$_.Exception.Message } catch {}
            try { $errId = [string]$_.FullyQualifiedErrorId } catch {}
            try { if ($_.InvocationInfo) { $errLine = [string]$_.InvocationInfo.ScriptLineNumber } } catch {}
            try { $errTrace = ([string]$_.ScriptStackTrace -replace '\r?\n', ' <- ') } catch {}
            try { if ($context -and $context.Request -and $context.Request.Url) { $reqPath = [string]$context.Request.Url.AbsolutePath } } catch {}
            try {
                Send-Json $context 500 @{ ok = $false; error = $errMsg }
            } catch {}
            try {
                Add-Content -LiteralPath $LogFile -Value ('{0:u} Server Anfrage Fehler: {1} (Pfad={2}, ErrorId={3}, Zeile={4}, Trace={5})' -f (Get-Date), $errMsg, $reqPath, $errId, $errLine, $errTrace) -Encoding UTF8
            } catch {}
        }
    } while ($false)
}


# ----------------------------------------------------------------------------
# Listener-Schleife. Jede Anfrage läuft in einem Runspace aus einem Pool.
# Der Pool sorgt dafür, dass mehrere Studio-Fenster (jedes hält einen
# Long-Poll offen) das Programm nicht ausbremsen.
# ----------------------------------------------------------------------------

# ----------------------------------------------------------------------------
# UNABHAENGIGER SERVER-WAECHTER (Version 7.0.5) - DIE URSACHE DER EWIG HAENGENDEN
# BEFEHLE:
#
#   Bis 7.0.4 lief der Executor-Watchdog NUR in der /plugin/poll-Anfrage. Ein
#   Befehl wurde also genau dann als "haengt" erkannt, wenn das Plugin noch
#   pollte. Genau das ist im Fehlerfall nicht mehr der Fall: ein Befehl ohne
#   yield blockiert die komplette Lua-VM des Plugins (dann kommt kein Poll mehr),
#   oder die Verbindung bricht weg. Folge: pendingInStudio blieb FUER IMMER
#   stehen, lateResults kam nie an, und die serielle Queue blockierte alles
#   (real beobachtet: zwei list_jobs blockierten 15 Minuten).
#
#   Dieser Waechter laeuft in einem EIGENEN Runspace (zusammen mit dem Server
#   gestartet) und sieht nur den gemeinsamen Zustand. Er:
#     * erkennt einen toten/stummen Executor ohne jede Plugin-Anfrage,
#     * beendet das Kommando mit einem klaren Fehlercode (STUDIO_ABANDONED,
#       EXECUTOR_UNRESPONSIVE, EXECUTOR_UNAVAILABLE, EXECUTOR_DROPPED_COMMAND,
#       COMMAND_DELIVERY_UNCONFIRMED, QUEUE_EXPIRED),
#     * weckt einen noch wartenden HTTP-Aufrufer oder legt das Ergebnis als
#       lateResult der ANRUFER-Sitzung ab - es geht also nie verloren,
#     * laesst die serielle Queue danach weiterlaufen,
#     * verlangt vom Plugin, das laufende Kommando abzubrechen.
#
#   Er ist absichtlich selbststaendig (keine Handler-Funktionen), weil er in
#   einem frischen Runspace laeuft. Get-QueueSnapshot zeigt sweep.running=true
#   und sweep.secondsSinceSweep, damit die Funktion live belegbar ist.
# ----------------------------------------------------------------------------
$script:BridgeSweepScript = {
    param($Shared)

    function Get-SweepNow { return [DateTimeOffset]::UtcNow.ToUnixTimeSeconds() }
    function Get-SweepJsonOrNull { param($Raw) if ([string]::IsNullOrWhiteSpace([string]$Raw)) { return $null }; try { return ([string]$Raw | ConvertFrom-Json) } catch { return $null } }
    function Get-SweepIdList { param($Value) $list = @(); if ($null -eq $Value) { return $list }; foreach ($item in @($Value)) { $list += [string]$item }; return $list }

    try { $Shared.SweepState.StartedAt = Get-SweepNow } catch {}
    while ($true) {
        $now = Get-SweepNow
        try {
            foreach ($sessionPair in @($Shared.Sessions.GetEnumerator())) {
                $sid = [string]$sessionPair.Key
                if ([string]::IsNullOrWhiteSpace($sid)) { continue }

                # --- Lebenszeichen der Sitzung (Presence hat Vorrang) -----------
                $presence = [int64]0
                $hasPresence = $Shared.Presence.TryGetValue($sid, [ref]$presence)
                $entry = Get-SweepJsonOrNull $sessionPair.Value
                $lastSeen = [int64]0
                if ($entry) { try { $lastSeen = [int64]$entry.lastSeen } catch {} }
                $aliveAt = $(if ($hasPresence) { [int64]$presence } else { [int64]$lastSeen })
                $sessionAge = $(if ($aliveAt -gt 0) { $now - $aliveAt } else { 999999 })
                $openPolls = 0
                [void]$Shared.Pollers.TryGetValue($sid, [ref]$openPolls)
                $sessionAlive = (($sessionAge -le 30) -or ($openPolls -gt 0))

                # --- unabhaengige Executor-Sicht (Snapshot aus dem Poll) --------
                $snap = $null
                $snapRaw = $null
                if ($Shared.ExecutorStates.TryGetValue($sid, [ref]$snapRaw)) { $snap = Get-SweepJsonOrNull $snapRaw }
                $executorFresh = $false
                $executorRunningId = ''
                $executorStartedAt = [int64]0
                $executorQueuedIds = @()
                if ($snap) {
                    $snapReceived = [int64]0
                    try { $snapReceived = [int64]$snap.receivedAt } catch {}
                    $executorFresh = ($snapReceived -gt 0 -and ($now - $snapReceived) -le 30)
                    try { $executorRunningId = [string]$snap.runningCommandId } catch {}
                    try { $executorStartedAt = [int64]$snap.startedAt } catch {}
                    try { $executorQueuedIds = Get-SweepIdList $snap.queuedCommandIds } catch {}
                }

                $bag = $null
                if (-not $Shared.PendingCommands.TryGetValue($sid, [ref]$bag)) { continue }
                foreach ($pendingPair in @($bag.GetEnumerator())) {
                    try {
                        $id = [string]$pendingPair.Key
                        $info = Get-SweepJsonOrNull $pendingPair.Value
                        if ([string]::IsNullOrWhiteSpace($id) -or $null -eq $info) {
                            $discard = $null
                            [void]$bag.TryRemove($id, [ref]$discard)
                            continue
                        }
                        $status = [string]$info.status
                        if ([string]::IsNullOrWhiteSpace($status)) { $status = 'queued' }
                        $queuedAt = [int64]0; $startedAt = [int64]0; $heartbeatAt = [int64]0
                        $deliveredAt = [int64]0; $receivedAt = [int64]0
                        try { $queuedAt = [int64]$info.queuedAt } catch {}
                        if ($queuedAt -le 0) { try { $queuedAt = [int64]$info.createdAt } catch {} }
                        try { $startedAt = [int64]$info.startedAt } catch {}
                        try { $heartbeatAt = [int64]$info.heartbeatAt } catch {}
                        try { $deliveredAt = [int64]$info.deliveredAt } catch {}
                        try { $receivedAt = [int64]$info.receivedAt } catch {}
                        $budget = 90
                        try { $budget = [int]$info.budgetSeconds } catch {}
                        if ($budget -le 0) { $budget = 90 }
                        $age = [int][Math]::Max(0, $now - $queuedAt)

                        # Frischer Executor-Snapshot beweist, dass dieser Befehl
                        # laeuft - dann ist ein verlorener Heartbeat-POST harmlos.
                        if ($executorFresh -and $executorRunningId -eq $id) {
                            if ($startedAt -le 0) { $startedAt = $(if ($executorStartedAt -gt 0) { $executorStartedAt } else { $now }) }
                            $heartbeatAt = $now
                            if ($status -ne 'started' -and $status -ne 'running') { $status = 'started' }
                            try {
                                $info.status = 'started'; $info.startedAt = $startedAt; $info.heartbeatAt = $heartbeatAt
                                $bag[$id] = ($info | ConvertTo-Json -Depth 8 -Compress)
                                $Shared.CommandStates[$id] = $bag[$id]
                            } catch {}
                        }

                        $abandonCode = ''
                        $abandonReason = ''
                        if ($status -eq 'started' -or $status -eq 'running') {
                            if ($startedAt -gt 0 -and ($now - $startedAt) -gt ($budget + 15)) {
                                $abandonCode = 'STUDIO_ABANDONED'
                                $abandonReason = "The Studio command exceeded its $budget-second execution budget and was stopped by the bridge watchdog so the queue can continue. Inspect the Place for partial changes before retrying."
                            } elseif ($heartbeatAt -gt 0 -and ($now - $heartbeatAt) -gt 45) {
                                $abandonCode = 'EXECUTOR_UNRESPONSIVE'
                                $abandonReason = 'Studio stopped reporting executor heartbeats for more than 45 seconds. The command was aborted so the queue can recover; partial changes may exist.'
                            } elseif (-not $sessionAlive -and $startedAt -gt 0 -and ($now - $startedAt) -gt 60) {
                                $abandonCode = 'EXECUTOR_UNAVAILABLE'
                                $abandonReason = 'The Studio plugin stopped answering while this command was running. It was aborted so the queue can continue; partial changes may exist.'
                            }
                        } elseif ($status -eq 'delivered' -or $status -eq 'received') {
                            $inLocalQueue = ($executorQueuedIds -contains $id)
                            if (-not $sessionAlive -and $age -gt 60) {
                                $abandonCode = 'EXECUTOR_UNAVAILABLE'
                                $abandonReason = 'The Studio plugin stopped answering after this command was handed over. It was not replayed (it may have run) and is reported as abandoned instead.'
                            } elseif ($status -eq 'delivered' -and $age -gt 120) {
                                $abandonCode = 'COMMAND_DELIVERY_UNCONFIRMED'
                                $abandonReason = 'Studio never confirmed receiving this command. It was released so the queue can continue.'
                            } elseif ($status -eq 'received' -and $executorFresh -and -not $inLocalQueue -and $executorRunningId -ne $id -and $age -gt 60) {
                                $abandonCode = 'EXECUTOR_DROPPED_COMMAND'
                                $abandonReason = 'The plugin acknowledged this command but it is neither running nor present in its local queue any more. It was released so the queue can continue.'
                            } elseif ($status -eq 'received' -and -not $executorFresh -and $age -gt 120) {
                                $abandonCode = 'EXECUTOR_UNRESPONSIVE'
                                $abandonReason = 'The plugin executor stopped reporting liveness while this command was waiting to start. It was released so the queue can continue.'
                            }
                        } elseif ($status -eq 'queued') {
                            if (-not $sessionAlive -and $age -gt 60) {
                                $abandonCode = 'EXECUTOR_UNAVAILABLE'
                                $abandonReason = 'The Studio plugin has not polled for more than 60 seconds while this command was waiting. It was released so the queue cannot stay blocked forever.'
                            } elseif ($age -gt 1800) {
                                $abandonCode = 'QUEUE_EXPIRED'
                                $abandonReason = 'The command exceeded the maximum queue-retention time and was removed.'
                            }
                        }
                        if ([string]::IsNullOrWhiteSpace($abandonCode)) { continue }

                        $dedupeKey = $sid + ':' + $id
                        $discardPayload = $null
                        [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discardPayload)
                        if ($Shared.CompletedCommandIds.ContainsKey($dedupeKey)) {
                            $discard = $null
                            [void]$bag.TryRemove($id, [ref]$discard)
                            continue
                        }
                        [void]$Shared.CompletedCommandIds.TryAdd($dedupeKey, $now)
                        $unackedVal = 0
                        $attemptsVal = 0
                        try { if ($null -ne $info.unackedCount) { $unackedVal = [int]$info.unackedCount } } catch {}
                        try { if ($null -ne $info.deliveryAttempts) { $attemptsVal = [int]$info.deliveryAttempts } } catch {}
                        $pluginDiagnostics = @{
                            lastPollError    = if ($snap -and $null -ne $snap.lastPollError) { [string]$snap.lastPollError } else { '' }
                            lastPluginError  = if ($snap -and $null -ne $snap.lastPluginError) { [string]$snap.lastPluginError } else { '' }
                            lastAckAt        = if ($snap -and $null -ne $snap.lastAckAt) { [int64]$snap.lastAckAt } else { [int64]0 }
                            ackOutbox        = if ($snap -and $null -ne $snap.ackOutbox) { [int]$snap.ackOutbox } else { 0 }
                            resultOutbox     = if ($snap -and $null -ne $snap.resultOutbox) { [int]$snap.resultOutbox } else { 0 }
                            unackedCount     = $unackedVal
                            deliveryAttempts = $attemptsVal
                        }
                        try {
                            Add-Content -LiteralPath $Shared.LogFile -Value ('{0:u} Befehl vom Waechter abgebrochen: tool={1}, commandId={2}, code={3}, unacked={4}, versuche={5}, lastPollError={6}, lastPluginError={7}, lastAckAt={8} | {9}' -f (Get-Date), [string]$info.tool, $id, $abandonCode, $unackedVal, $attemptsVal, [string]$pluginDiagnostics.lastPollError, [string]$pluginDiagnostics.lastPluginError, [int64]$pluginDiagnostics.lastAckAt, $abandonReason) -Encoding UTF8
                        } catch {}
                        $failure = @{
                            ok = $false
                            code = $abandonCode
                            commandId = $id
                            tool = [string]$info.tool
                            error = $abandonReason
                            workIsLost = $false
                            partialChangesPossible = ($startedAt -gt 0)
                            retrySafe = $false
                            status = 'abandoned'
                            elapsedSeconds = $age
                            budgetSeconds = $budget
                            abandonedBy = 'server-watchdog'
                            pluginDiagnostics = $pluginDiagnostics
                            hint = 'The queue was released automatically. Check the Place for partial changes before retrying; the watchdog runs even when Studio stops answering.'
                        }
                        $failureJson = ($failure | ConvertTo-Json -Depth 10 -Compress)
                        $Shared.CommandStates[$id] = $failureJson
                        # Version 7.1.0: Auch die sichtbare Arena-Verlaufskarte aktualisieren,
                        # wenn der Hintergrund-Waechter einen Befehl abbricht.
                        try {
                            $actMapJson = $null
                            if ($Shared.ActivityCommandMap.TryRemove($id, [ref]$actMapJson) -and $actMapJson) {
                                $actMap = $actMapJson | ConvertFrom-Json
                                $actSid = [string]$actMap.sessionId
                                $actId = [string]$actMap.activityId
                                $actTool = [string]$actMap.tool
                                $actBag = $null
                                if ($Shared.ActivityLogs.TryGetValue($actSid, [ref]$actBag) -and $actBag) {
                                    $deReason = switch ($abandonCode) {
                                        'COMMAND_DELIVERY_UNCONFIRMED' { 'Das Studio-Plugin hat den Empfang des Befehls nicht bestätigt.' }
                                        'EXECUTOR_UNRESPONSIVE'        { 'Das Studio-Plugin sendet keine Lebenszeichen mehr während der Ausführung.' }
                                        'EXECUTOR_UNAVAILABLE'         { 'Das Studio-Plugin ist derzeit nicht erreichbar.' }
                                        'EXECUTOR_DROPPED_COMMAND'     { 'Der Befehl ging in der lokalen Plugin-Warteschlange verloren.' }
                                        'STUDIO_ABANDONED'             { 'Der Befehl hat das Sicherheits-Zeitbudget überschritten und wurde beendet.' }
                                        default                        { $abandonReason }
                                    }
                                    $priorActRaw = $null
                                    $actStartedAt = $now
                                    if ($actBag.TryGetValue($actId, [ref]$priorActRaw) -and $priorActRaw) {
                                        try { $actStartedAt = [int64](($priorActRaw | ConvertFrom-Json).startedAt) } catch {}
                                    }
                                    $actEntry = @{
                                        id = $actId
                                        tool = $actTool
                                        phase = 'failed'
                                        kind = 'failed'
                                        text = ('⚠ Befehl „' + $actTool + '“ abgebrochen: ' + $deReason)
                                        startedAt = $actStartedAt
                                        updatedAt = $now
                                    }
                                    $actBag[$actId] = ($actEntry | ConvertTo-Json -Depth 8 -Compress)
                                }
                            }
                        } catch {}
                        # Version 7.0.6: Der Waechter laeuft in einem EIGENEN
                        # Runspace ohne Handler-Funktionen - die Historie wird
                        # hier deshalb direkt geschrieben.
                        try {
                            $historyQueue = $null
                            if (-not $Shared.CommandHistory.TryGetValue($sid, [ref]$historyQueue)) {
                                $historyQueue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
                                [void]$Shared.CommandHistory.TryAdd($sid, $historyQueue)
                                [void]$Shared.CommandHistory.TryGetValue($sid, [ref]$historyQueue)
                            }
                            $historyQueue.Enqueue(([pscustomobject]@{
                                commandId = $id
                                tool = [string]$info.tool
                                status = 'abandoned'
                                at = $now
                                detail = ($abandonCode + ' by server-watchdog after ' + [string]$age + ' s')
                            } | ConvertTo-Json -Compress))
                            while ($historyQueue.Count -gt 40) { $dropHistory = $null; [void]$historyQueue.TryDequeue([ref]$dropHistory) }
                        } catch {}
                        $origin = $sid
                        $originRaw = $null
                        if ($Shared.CommandOrigins.TryGetValue($id, [ref]$originRaw)) {
                            if (-not [string]::IsNullOrWhiteSpace([string]$originRaw)) { $origin = [string]$originRaw }
                        }
                        $signal = $null
                        [System.Threading.Monitor]::Enter($Shared.CommandResultLock)
                        try {
                            if ($Shared.ResultSignals.TryGetValue($id, [ref]$signal)) {
                                $Shared.CommandResults[$id] = $failureJson
                                try { [void]$signal.Set() } catch {}
                            } else {
                                $lateQueue = $null
                                if (-not $Shared.LateResults.TryGetValue($origin, [ref]$lateQueue)) {
                                    $lateQueue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
                                    [void]$Shared.LateResults.TryAdd($origin, $lateQueue)
                                    [void]$Shared.LateResults.TryGetValue($origin, [ref]$lateQueue)
                                }
                                $lateQueue.Enqueue($failureJson)
                                while ($lateQueue.Count -gt 60) { $drop = $null; [void]$lateQueue.TryDequeue([ref]$drop) }
                            }
                        } finally {
                            [System.Threading.Monitor]::Exit($Shared.CommandResultLock)
                        }
                        $discardPending = $null
                        [void]$bag.TryRemove($id, [ref]$discardPending)
                        $Shared.CancelRequests[$dedupeKey] = $now
                        $Shared.SweepState.Abandoned = [int64]$Shared.SweepState.Abandoned + 1
                    } catch {}
                }
            }
        } catch {}
        try {
            $Shared.SweepState.LastSweepAt = $now
            $Shared.SweepState.Sweeps = [int64]$Shared.SweepState.Sweeps + 1
        } catch {}
        Start-Sleep -Seconds 2
    }
}

$script:BridgeListenerScript = {
    param($Port, $Shared, $HandlerScript)

    function Write-BridgeLog {
        param([string]$Text)
        try {
            Add-Content -LiteralPath $Shared.LogFile -Value ('{0:u} {1}' -f (Get-Date), $Text) -Encoding UTF8
        } catch {}
    }

    $listener = [System.Net.HttpListener]::new()
    $listener.Prefixes.Add("http://127.0.0.1:$Port/")
    try {
        $listener.Start()
    } catch {
        Write-BridgeLog "Server: Port $Port konnte nicht geöffnet werden: $($_.Exception.Message)"
        return
    }
    Write-BridgeLog "Server: lauscht auf http://127.0.0.1:$Port/"

    $pool = $null
    try {
        $initialState = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
        $pool = [runspacefactory]::CreateRunspacePool(2, 32, $initialState, $Host)
        $pool.ApartmentState = 'MTA'
        $pool.Open()
        Write-BridgeLog 'Server: Runspace-Pool bereit (2 bis 32 gleichzeitige Anfragen).'
    } catch {
        Write-BridgeLog "Server: Runspace-Pool konnte nicht geöffnet werden: $($_.Exception.Message)"
        $pool = $null
    }

    # ------------------------------------------------------------------
    # Version 7.0.3: Der 337-KB-Handler wird EINMAL geparst/kompiliert.
    # Vorher erzeugte jede einzelne HTTP-Anfrage ein neues PowerShell-Objekt
    # mit AddScript(<vollstaendiger Handler-Text>); damit wurde der komplette
    # Handler bei JEDER Anfrage neu geparst. Genau diese Anfragen beginnen
    # mit einem verbundenen Place (Heartbeat/Poll) - und waren damit
    # Dauerlast, obwohl im Leerlauf nichts zu tun ist.
    # Der Scriptblock ist ungebunden und daher in jedem Pool-Runspace
    # aufrufbar; die Worker bekommen nur noch einen Mini-Wrapper zu parsen.
    # ------------------------------------------------------------------
    $handlerBlock = $null
    try { $handlerBlock = [ScriptBlock]::Create($HandlerScript) } catch { $handlerBlock = $null }
    $fastWorkers = $false
    if ($null -ne $handlerBlock) {
        # Selbsttest: Der Handler muss als UNGEBUNDENER Scriptblock in einem
        # Pool-Runspace aufrufbar sein. Der Test benutzt denselben Weg wie
        # spaeter jede Anfrage, aber mit einem harmlosen Mini-Scriptblock -
        # so kann der echte Handler nie zweimal laufen.
        try {
            $probeBlock = [ScriptBlock]::Create('param($Value) return ("ok:" + [string]$Value)')
            $probe = [PowerShell]::Create()
            if ($pool) { $probe.RunspacePool = $pool }
            [void]$probe.AddScript('param($Handler, $Value) & $Handler $Value').AddArgument($probeBlock).AddArgument('probe')
            $probeResult = $probe.Invoke()
            $fastWorkers = ($null -ne $probeResult -and $probeResult.Count -gt 0 -and [string]$probeResult[0] -eq 'ok:probe')
            try { $probe.Dispose() } catch {}
        } catch { $fastWorkers = $false }
    }
    if ($fastWorkers) {
        $workerScript = 'param($Context, $Shared, $Handler, $HandlerText) & $Handler $Context $Shared'
        Write-BridgeLog 'Server: Handler wird einmal kompiliert und wiederverwendet (337 KB pro Anfrage gespart).'
    } else {
        $workerScript = 'param($Context, $Shared, $Handler, $HandlerText) & ([ScriptBlock]::Create($HandlerText)) $Context $Shared'
        $handlerBlock = $null
        Write-BridgeLog 'Server: Scriptblock-Wiederverwendung nicht verfuegbar - Handler wird wie bisher je Anfrage geparst.'
    }

    function Add-PerfHttpSample {
        param([double]$Milliseconds)
        try {
            $perf = $Shared.Perf
            if ($null -eq $perf) { return }
            $perf.HttpRequests = [long]$perf.HttpRequests + 1
            $perf.HttpDone = [long]$perf.HttpDone + 1
            $perf.HttpMsTotal = [double]$perf.HttpMsTotal + $Milliseconds
            if ($Milliseconds -gt [double]$perf.HttpMsMax) { $perf.HttpMsMax = $Milliseconds }
        } catch {}
    }

    $workers = [System.Collections.Generic.List[object]]::new()
    while ($listener.IsListening) {
        $context = $null
        try { $context = $listener.GetContext() } catch { break }

        # Fertige Anfragen sofort einsammeln. Nur dann wird (abschaltbar)
        # die Dauer je Anfrage gemessen - kein Logging pro Anfrage.
        $perfOn = $false
        try { $perfOn = ($Shared.BridgeSettings.perfDiagnostics -eq $true) } catch {}
        if ($workers.Count -gt 0) {
            $remaining = [System.Collections.Generic.List[object]]::new()
            foreach ($worker in $workers) {
                $done = $false
                try { $done = [bool]$worker.Handle.IsCompleted } catch { $done = $true }
                if ($done) {
                    try { $worker.Shell.EndInvoke($worker.Handle) } catch {}
                    try { $worker.Shell.Dispose() } catch {}
                    if ($perfOn) {
                        try { Add-PerfHttpSample ([double](([DateTime]::UtcNow - [DateTime]$worker.StartedAt).TotalMilliseconds)) } catch {}
                    }
                } else {
                    $remaining.Add($worker)
                }
            }
            $workers = $remaining
        }

        $ps = [PowerShell]::Create()
        if ($pool) { $ps.RunspacePool = $pool }
        [void]$ps.AddScript($workerScript).AddArgument($context).AddArgument($Shared).AddArgument($handlerBlock).AddArgument($HandlerScript)
        $handle = $ps.BeginInvoke()
        $workers.Add([pscustomobject]@{ Shell = $ps; Handle = $handle; StartedAt = [DateTime]::UtcNow })
    }
    foreach ($worker in $workers) {
        try { $worker.Shell.Dispose() } catch {}
    }
    if ($pool) {
        try { $pool.Close() } catch {}
        try { $pool.Dispose() } catch {}
    }
}

function Start-BridgeServer {
    param([int]$Port)

    $handlerText = [string]$script:BridgeHandlerScript
    $ps = [PowerShell]::Create()
    [void]$ps.AddScript([string]$script:BridgeListenerScript).AddArgument($Port).AddArgument($script:Shared).AddArgument($handlerText)
    [void]$ps.BeginInvoke()
    $script:ServerPowerShell = $ps
    # Version 7.0.5: Der unabhaengige Waechter laeuft in einem EIGENEN Runspace.
    # Er raeumt haengende Befehle auch dann ab, wenn das Plugin gar nicht mehr
    # pollt (das war bis 7.0.4 die Ursache der ewig haengenden Queue).
    try {
        $sweepPs = [PowerShell]::Create()
        [void]$sweepPs.AddScript([string]$script:BridgeSweepScript).AddArgument($script:Shared)
        [void]$sweepPs.BeginInvoke()
        $script:SweepPowerShell = $sweepPs
        Write-RuntimeLog 'Unabhaengiger Studio-Waechter gestartet (2-s-Sweep, unabhaengig von Plugin-Anfragen).'
    } catch {
        Write-RuntimeLog ('Warnung: unabhaengiger Studio-Waechter konnte nicht gestartet werden: ' + $_.Exception.Message)
    }
    Write-RuntimeLog "Lokaler Bridge Server wird auf Port $Port gestartet."
}

# ============================================================================
# Version 7.4.0: BLENDER (Schritt 4 des Starts) + MESH-BAU
# ============================================================================
# ----------------------------------------------------------------------------
# Version 7.4.1: BLENDER (Schritt 4 des Starts) - EINE Hilfs-Quelle.
#
# In 7.4.0 liefen Suche + Versionspruefung SYNCHRON im UI-Thread (das Fenster
# fror ein), die Faehigkeitsprobe lief in einem eigenen Runspace OHNE die
# Helferfunktionen (Phantom-Funktionen: ihre Protokollzeilen verschwanden
# lautlos) und "bereit" wurde schon nach dem Lesen der Version gesetzt -
# gemessen beim Nutzer: state=ready bei probe=failed.
#
# 7.4.1: Suche + Version + ECHTE Faehigkeitsprobe laufen in EINEM
# Hintergrund-Runspace ($script:BridgeBlenderStepScript). Das Hauptprogramm
# UND jeder Runspace laden GENAU EINE Hilfs-Quelle
# ($script:BridgeBlenderTools / $Shared.BlenderToolsText). ready setzt NUR die
# bestandene Probe; ein Fehlschlag wird ehrlich rot gemeldet, deaktiviert den
# Mesh-Bau und ist KEIN Start-Blocker (der Tunnel wartet nur auf den
# Endzustand: ready / failed / skipped).
# ----------------------------------------------------------------------------
$script:BridgeBlenderTools = {
    # ========================================================================
    # Alle Blender-Helfer in EINER Quelle. Keine $script:-Variablen: alles
    # kommt aus $Shared, damit dieselben Funktionen auch in Runspaces laufen.
    # ========================================================================

    function Write-BridgeBomFreeFile {
        # BOM-FREI schreiben. PowerShell 5.1 setzt bei Set-Content/Out-File
        # -Encoding UTF8 ein BOM vor die Datei - Python starb daran mit
        # "SyntaxError: invalid non-printable character U+FEFF" (Zeile 1).
        param([string]$Path, [string]$Text)
        try {
            $dir = [System.IO.Path]::GetDirectoryName($Path)
            if (-not [string]::IsNullOrWhiteSpace($dir) -and -not (Test-Path -LiteralPath $dir)) {
                [void](New-Item -ItemType Directory -Path $dir -Force)
            }
            [System.IO.File]::WriteAllText($Path, [string]$Text, (New-Object System.Text.UTF8Encoding($false)))
            return $true
        } catch { return $false }
    }

    function Write-BridgeLog {
        # Protokollzeile in die runtime.log der Bridge - AUCH aus Runspaces
        # (dort gibt es die Write-RuntimeLog des Hauptprogramms nicht).
        param($Shared, [string]$Text)
        try {
            $path = ''
            try { $path = [string]$Shared.LogFile } catch {}
            if ([string]::IsNullOrWhiteSpace($path)) { return }
            [System.IO.File]::AppendAllText($path, ((Get-Date).ToString('u') + ' ' + [string]$Text) + [Environment]::NewLine, (New-Object System.Text.UTF8Encoding($false)))
        } catch {}
    }

    function Set-BlenderState {
        # EINE Funktion schreibt blender-status.json - BOM-frei und auch aus
        # Runspaces. Sie behauptet nichts: 'ready' setzt ausschliesslich die
        # Faehigkeitsprobe nach einer BESTANDENEN Messung.
        param(
            $Shared,
            [string]$State = '',
            [string]$Path = '',
            [string]$Version = '',
            [string]$Detail = '',
            [string]$Message = '',
            [int]$Percent = -1,
            [string]$Source = '',
            [bool]$Enabled = $false,
            [long]$InstallStartedAt = [long]0,
            [bool]$GateResolved = $false,
            [string]$Probe = '',
            [switch]$ResetProbe
        )
        try {
            $map = $Shared.BlenderState
            if (-not [string]::IsNullOrWhiteSpace($State)) { $map.state = $State }
            if (-not [string]::IsNullOrWhiteSpace($Path)) { $map.path = $Path }
            if (-not [string]::IsNullOrWhiteSpace($Version)) { $map.version = $Version }
            if (-not [string]::IsNullOrWhiteSpace($Detail)) { $map.detail = $Detail }
            if (-not [string]::IsNullOrWhiteSpace($Message)) { $map.message = $Message }
            if ($Percent -ge 0) { $map.percent = [int]$Percent }
            if (-not [string]::IsNullOrWhiteSpace($Source)) { $map.source = $Source }
            if ($InstallStartedAt -gt 0) { $map.installStartedAt = $InstallStartedAt }
            if ($ResetProbe -or -not [string]::IsNullOrWhiteSpace($Probe)) { $map.probe = $Probe }
            $map.enabled = $Enabled
            $map.gateResolved = $GateResolved
            $map.updatedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            $map.checkedAt = $map.updatedAt
            $payload = @{
                state = [string]$map.state
                path = [string]$map.path
                version = [string]$map.version
                detail = [string]$map.detail
                message = [string]$map.message
                percent = [int]$map.percent
                source = [string]$map.source
                enabled = [bool]$map.enabled
                gateResolved = [bool]$map.gateResolved
                probe = [string]$map.probe
                updatedAt = $map.updatedAt
            }
            $jsonText = [string]($payload | ConvertTo-Json -Depth 4 -Compress)
            $statusFile = ''
            try { $statusFile = [string]$Shared.BlenderStatusFile } catch {}
            if (-not [string]::IsNullOrWhiteSpace($statusFile)) {
                [void](Write-BridgeBomFreeFile -Path $statusFile -Text $jsonText)
            }
        } catch {
            try { Write-BridgeLog -Shared $Shared -Text ('Blender-Zustand konnte nicht gespeichert werden: ' + $_.Exception.Message) } catch {}
        }
    }

    function Get-BlenderExeInFolder {
        param([string]$Folder)
        if ([string]::IsNullOrWhiteSpace($Folder)) { return $null }
        $direct = Join-Path $Folder 'blender.exe'
        if (Test-Path -LiteralPath $direct) { return $direct }
        try {
            $hit = Get-ChildItem -LiteralPath $Folder -Filter 'blender.exe' -Recurse -Depth 3 -File -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($hit) { return $hit.FullName }
        } catch {}
        return $null
    }

    function Get-BlenderPath {
        # Reihenfolge: eigener Ordner -> PATH -> Registry (echte Installationen)
        # -> klassische Ordner -> Steam -> Microsoft Store.
        param($Shared)
        $blenderFolder = ''
        try { $blenderFolder = [string]$Shared.BlenderFolder } catch {}
        try {
            if (-not [string]::IsNullOrWhiteSpace($blenderFolder) -and (Test-Path -LiteralPath $blenderFolder)) {
                $hit = Get-ChildItem -LiteralPath $blenderFolder -Filter 'blender.exe' -Recurse -Depth 2 -File -ErrorAction SilentlyContinue | Select-Object -First 1
                if ($hit) { return $hit.FullName }
            }
        } catch {}
        try {
            $cmd = Get-Command blender -ErrorAction SilentlyContinue
            if ($cmd -and $cmd.Source) { return [string]$cmd.Source }
            $cmdExe = Get-Command blender.exe -ErrorAction SilentlyContinue
            if ($cmdExe -and $cmdExe.Source) { return [string]$cmdExe.Source }
        } catch {}
        try {
            foreach ($root in @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*')) {
                $entries = Get-ItemProperty -Path $root -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like 'Blender*' }
                foreach ($entry in $entries) {
                    $loc = [string]$entry.InstallLocation
                    if (-not [string]::IsNullOrWhiteSpace($loc)) {
                        $exe = Get-BlenderExeInFolder $loc
                        if ($exe) { return $exe }
                    }
                }
            }
        } catch {}
        $patterns = New-Object System.Collections.Generic.List[string]
        $patterns.Add((Join-Path $env:LOCALAPPDATA 'Programs\Blender Foundation\Blender*'))
        $patterns.Add((Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps'))
        if (${env:ProgramFiles}) { $patterns.Add((Join-Path ${env:ProgramFiles} 'Blender Foundation\Blender*')) }
        if (${env:ProgramFiles(x86)}) { $patterns.Add((Join-Path ${env:ProgramFiles(x86)} 'Blender Foundation\Blender*')) }
        foreach ($steamRoot in @((Join-Path ${env:ProgramFiles} 'Steam\steamapps\common\Blender'), (Join-Path ${env:ProgramFiles(x86)} 'Steam\steamapps\common\Blender'))) {
            if ($steamRoot) { $patterns.Add($steamRoot) }
        }
        foreach ($pattern in $patterns) {
            try {
                $folders = Get-ChildItem -Path $pattern -Directory -ErrorAction SilentlyContinue
                foreach ($folder in $folders) {
                    $exe = Get-BlenderExeInFolder $folder.FullName
                    if ($exe) { return $exe }
                }
            } catch {}
        }
        return $null
    }

    function Invoke-BlenderProcess {
        # Startet blender.exe ohne Fenster und liest stdout/stderr mit hartem
        # Zeitlimit. Rueckgabe: exitCode, timedOut, output (beide Stroeme).
        param([string]$Path, [string]$Arguments, [int]$TimeoutSeconds = 60, [string]$WorkingDirectory = '')
        $result = @{ ok = $false; exitCode = -1; timedOut = $false; output = ''; error = '' }
        if ([string]::IsNullOrWhiteSpace($Path)) { $result.error = 'Kein Blender-Pfad.'; return $result }
        if (-not (Test-Path -LiteralPath $Path)) { $result.error = ('Blender nicht gefunden: ' + $Path); return $result }
        $process = $null
        try {
            $psi = [System.Diagnostics.ProcessStartInfo]::new()
            $psi.FileName = $Path
            $psi.Arguments = $Arguments
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            if (-not [string]::IsNullOrWhiteSpace($WorkingDirectory) -and (Test-Path -LiteralPath $WorkingDirectory)) {
                $psi.WorkingDirectory = $WorkingDirectory
            }
            $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
            $psi.StandardErrorEncoding = [System.Text.Encoding]::UTF8
            $process = [System.Diagnostics.Process]::new()
            $process.StartInfo = $psi
            [void]$process.Start()
            $outTask = $process.StandardOutput.ReadToEndAsync()
            $errTask = $process.StandardError.ReadToEndAsync()
            $exited = $process.WaitForExit([Math]::Max(5, $TimeoutSeconds) * 1000)
            if (-not $exited) {
                $result.timedOut = $true
                try { $process.Kill() } catch {}
                try { [void]$process.WaitForExit(4000) } catch {}
            }
            $outText = ''
            $errText = ''
            try { if ($outTask.Wait(4000)) { $outText = [string]$outTask.Result } } catch {}
            try { if ($errTask.Wait(4000)) { $errText = [string]$errTask.Result } } catch {}
            $result.output = (($outText + [Environment]::NewLine + $errText).Trim())
            try { $result.exitCode = [int]$process.ExitCode } catch {}
            $result.ok = ((-not $result.timedOut) -and $result.exitCode -eq 0)
            if ($result.timedOut) { $result.error = ('Blender hat nach ' + [string]$TimeoutSeconds + ' s nicht geantwortet und wurde beendet.') }
            elseif ($result.exitCode -ne 0) { $result.error = ('Blender endete mit Code ' + [string]$result.exitCode + '.') }
        } catch {
            $result.error = $_.Exception.Message
        } finally {
            try { if ($process) { $process.Dispose() } } catch {}
        }
        return $result
    }

    function Test-BlenderQuick {
        # SCHNELLE Messung: blender.exe --version -> "Blender 5.0.1". Sie sagt
        # NUR, dass die Datei startet und welche Version es ist - NICHT, dass
        # der Mesh-Bau funktioniert (das entscheidet allein die Probe).
        param([string]$Path)
        $out = @{ ok = $false; version = ''; error = '' }
        $run = Invoke-BlenderProcess -Path $Path -Arguments '--version' -TimeoutSeconds 25
        if ($run.timedOut) { $out.error = $run.error; return $out }
        $text = [string]$run.output
        if ([string]::IsNullOrWhiteSpace($text)) { $out.error = 'Blender lieferte keine Versionsausgabe.'; return $out }
        $match = [System.Text.RegularExpressions.Regex]::Match($text, 'Blender\s+([0-9]+(?:\.[0-9]+){1,2})')
        if (-not $match.Success) { $out.error = ('Versionsausgabe nicht lesbar: ' + $text.Substring(0, [Math]::Min(120, $text.Length))); return $out }
        $version = $match.Groups[1].Value
        $parts = $version.Split('.')
        $major = 0
        try { $major = [int]$parts[0] } catch { $major = 0 }
        $out.version = $version
        if ($major -lt 3) {
            $out.error = ('Blender ' + $version + ' ist zu alt (mindestens 3.3 wird gebraucht).')
            return $out
        }
        $out.ok = $true
        return $out
    }

    function Get-BlenderDownloadCandidates {
        # Gepinnte LTS-Kandidaten zuerst (4.5 LTS laeuft auch auf aelterer
        # Hardware), danach die Verzeichnisliste der offiziellen Quelle. Immer
        # portables ZIP - kein MSI, kein UAC, kein Admin.
        $list = New-Object System.Collections.Generic.List[string]
        foreach ($patch in @('4.5.12', '4.5.11', '4.5.10', '4.5.9', '4.5.8')) {
            $list.Add(('https://download.blender.org/release/Blender4.5/blender-' + $patch + '-windows-x64.zip'))
        }
        try {
            $listing = (Invoke-WebRequest -Uri 'https://download.blender.org/release/Blender4.5/' -UseBasicParsing -TimeoutSec 25).Content
            $found = [System.Text.RegularExpressions.Regex]::Matches([string]$listing, 'blender-(4\.5\.[0-9]+)-windows-x64\.zip')
            $rounds = New-Object System.Collections.Generic.List[string]
            foreach ($hit in $found) {
                $name = [string]$hit.Groups[1].Value
                if (-not $rounds.Contains($name)) { $rounds.Add($name) }
            }
            $sorted = $rounds.ToArray() | Sort-Object { [int]($_ -split '\.')[2] } -Descending
            foreach ($name in $sorted) {
                $url = ('https://download.blender.org/release/Blender4.5/blender-' + $name + '-windows-x64.zip')
                if (-not $list.Contains($url)) { $list.Add($url) }
            }
        } catch {}
        return ,$list
    }

    function Test-BlenderZipHash {
        # Wenn die offizielle .sha256-Datei erreichbar ist, wird der Download
        # wirklich geprueft; sonst wird das ehrlich im Protokoll vermerkt.
        param([string]$Url, [string]$File)
        try {
            $expected = ([string](Invoke-WebRequest -Uri ($Url + '.sha256') -UseBasicParsing -TimeoutSec 20).Content).Trim()
            $expectedHash = ($expected -split '\s+')[0]
            if ([string]::IsNullOrWhiteSpace($expectedHash)) { return @{ checked = $false; ok = $true; note = 'Keine Pruefsumme in der .sha256-Datei gefunden.' } }
            $actual = (Get-FileHash -LiteralPath $File -Algorithm SHA256).Hash
            if ($actual -eq $expectedHash.ToUpperInvariant()) { return @{ checked = $true; ok = $true; note = 'SHA-256 stimmt mit der offiziellen Pruefsumme ueberein.' } }
            return @{ checked = $true; ok = $false; note = 'SHA-256 stimmt NICHT mit der offiziellen Pruefsumme ueberein.' }
        } catch {
            return @{ checked = $false; ok = $true; note = ('Keine offizielle Pruefsumme erreichbar (' + $_.Exception.Message + ') - der Download wurde nur strukturell (ZIP) und danach mit der Faehigkeitsprobe geprueft.') }
        }
    }

    function Install-BlenderPortableZip {
        # Laedt das offizielle PORTABLE ZIP (kein Admin, kein UAC), prueft die
        # SHA-256 wenn erreichbar, entpackt und MISST die Version. Setzt
        # ausdruecklich KEIN ready - das entscheidet NUR die Faehigkeitsprobe.
        param($Shared)
        $result = @{ ok = $false; path = ''; version = ''; error = '' }
        $root = ''
        $folder = ''
        try { $root = [string]$Shared.MeshRoot } catch {}
        try { $folder = [string]$Shared.BlenderFolder } catch {}
        if ([string]::IsNullOrWhiteSpace($root) -or [string]::IsNullOrWhiteSpace($folder)) {
            $result.error = 'Mesh-/Blender-Ordner der Bridge ist unbekannt.'
            return $result
        }
        $logPath = Join-Path $root 'blender-install.log'
        $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
        try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12 } catch {}
        try {
            if (-not (Test-Path -LiteralPath $root)) { [void](New-Item -ItemType Directory -Path $root -Force) }
            if (-not (Test-Path -LiteralPath $folder)) { [void](New-Item -ItemType Directory -Path $folder -Force) }
        } catch {}
        Write-BridgeLog -Shared $Shared -Text 'Blender-Installation gestartet (portables ZIP von download.blender.org, kein Admin).'
        $urls = Get-BlenderDownloadCandidates
        $zipPath = Join-Path $folder 'blender-portable.zip'
        $downloaded = $false
        $usedUrl = ''
        foreach ($url in $urls) {
            Set-BlenderState -Shared $Shared -State 'installing' -Message ('Blender wird heruntergeladen … (' + [string]$url + ')') -Percent 0 -Source 'download' -InstallStartedAt ([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())
            try {
                try { [System.IO.File]::AppendAllText($logPath, ((Get-Date).ToString('u') + ' Download: ' + [string]$url) + [Environment]::NewLine, $utf8NoBom) } catch {}
                if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue }
                $client = [System.Net.WebClient]::new()
                $expected = [int64]0
                try {
                    $head = [System.Net.HttpWebRequest]::Create([string]$url)
                    $head.Method = 'HEAD'
                    $head.Timeout = 20000
                    $response = $head.GetResponse()
                    $expected = [int64]$response.ContentLength
                    $response.Close()
                } catch { $expected = 0 }
                $task = $client.DownloadFileTaskAsync([string]$url, $zipPath)
                while (-not $task.IsCompleted) {
                    [System.Threading.Thread]::Sleep(500)
                    $percent = -1
                    try {
                        $size = [int64]0
                        if (Test-Path -LiteralPath $zipPath) { $size = [int64](Get-Item -LiteralPath $zipPath).Length }
                        if ($expected -gt 0) { $percent = [int]([Math]::Min(99, [Math]::Floor($size * 100 / $expected))) } else { $percent = -1 }
                    } catch { $percent = -1 }
                    if ($percent -ge 0) {
                        Set-BlenderState -Shared $Shared -State 'installing' -Message ('Blender wird heruntergeladen … ' + [string]$percent + ' %') -Percent $percent -Source 'download'
                    }
                }
                if ($task.IsFaulted) { throw $task.Exception.GetBaseException() }
                try { $client.Dispose() } catch {}
                if (-not (Test-Path -LiteralPath $zipPath)) { throw 'Die Datei wurde nicht gespeichert.' }
                $zipBytes = [int64](Get-Item -LiteralPath $zipPath).Length
                if ($zipBytes -lt 50000000) { throw ('Die Datei ist zu klein fuer ein Blender-ZIP (' + [string]$zipBytes + ' Bytes).') }
                $zipOk = $true
                try {
                    $head = [System.IO.File]::OpenRead($zipPath)
                    $magic = New-Object byte[] 2
                    [void]$head.Read($magic, 0, 2)
                    $head.Close()
                    if (-not ($magic[0] -eq 80 -and $magic[1] -eq 75)) { $zipOk = $false }
                } catch {}
                if (-not $zipOk) { throw 'Die Datei ist kein ZIP-Archiv.' }
                Set-BlenderState -Shared $Shared -State 'installing' -Message 'Pruefsumme wird geprueft …' -Percent 99 -Source 'download'
                $hashNote = Test-BlenderZipHash -Url ([string]$url) -File $zipPath
                if ([bool]$hashNote.ok -ne $true) { throw 'Die Pruefsumme des Downloads stimmt nicht - der Download wird verworfen.' }
                try { [System.IO.File]::AppendAllText($logPath, ((Get-Date).ToString('u') + ' ' + [string]$hashNote.note) + [Environment]::NewLine, $utf8NoBom) } catch {}
                $downloaded = $true
                $usedUrl = [string]$url
                break
            } catch {
                try { [System.IO.File]::AppendAllText($logPath, ((Get-Date).ToString('u') + ' Download fehlgeschlagen (' + [string]$url + '): ' + $_.Exception.Message) + [Environment]::NewLine, $utf8NoBom) } catch {}
                Set-BlenderState -Shared $Shared -State 'installing' -Message 'Download fehlgeschlagen - naechste Quelle wird versucht …' -Percent 0 -Detail $_.Exception.Message -Source 'download'
            }
        }
        if (-not $downloaded) {
            # Letzter Weg: winget (braucht eine Bestaetigung von Windows).
            Set-BlenderState -Shared $Shared -State 'installing' -Message 'Download nicht moeglich - winget wird versucht …' -Percent 0 -Source 'winget'
            try {
                $winget = Get-Command winget -ErrorAction SilentlyContinue
                if ($winget) {
                    Write-BridgeLog -Shared $Shared -Text 'winget install BlenderFoundation.Blender.LTS'
                    $wingetOut = & $winget.Source install --id BlenderFoundation.Blender.LTS -e --silent --accept-source-agreements --accept-package-agreements 2>&1
                    Write-BridgeLog -Shared $Shared -Text ('winget: ' + ([string]($wingetOut -join ' ')))
                    $machinePath = [System.Environment]::GetEnvironmentVariable('Path', 'Machine')
                    $userPath = [System.Environment]::GetEnvironmentVariable('Path', 'User')
                    if (-not [string]::IsNullOrWhiteSpace($machinePath) -or -not [string]::IsNullOrWhiteSpace($userPath)) { $env:Path = ([string]$machinePath + ';' + [string]$userPath) }
                    $exe = $null
                    foreach ($pattern in @((Join-Path ${env:ProgramFiles} 'Blender Foundation\Blender*'), (Join-Path ${env:LOCALAPPDATA} 'Programs\Blender Foundation\Blender*'))) {
                        try {
                            foreach ($sub in (Get-ChildItem -Path $pattern -Directory -ErrorAction SilentlyContinue)) {
                                $hit = Join-Path $sub.FullName 'blender.exe'
                                if (Test-Path -LiteralPath $hit) { $exe = $hit; break }
                            }
                        } catch {}
                        if ($exe) { break }
                    }
                    if ($exe) {
                        $quick = Test-BlenderQuick -Path $exe
                        if ($quick.ok) {
                            $result.ok = $true
                            $result.path = [string]$exe
                            $result.version = [string]$quick.version
                            Set-BlenderState -Shared $Shared -State 'installing' -Message 'Blender ist per winget installiert - die echte Faehigkeitsprobe laeuft gleich.' -Percent 99 -Path ([string]$exe) -Version ([string]$quick.version) -Source 'winget' -Detail 'Ueber winget installiert.'
                            return $result
                        }
                    }
                } else {
                    Write-BridgeLog -Shared $Shared -Text 'winget ist nicht vorhanden.'
                }
            } catch {
                Write-BridgeLog -Shared $Shared -Text ('winget fehlgeschlagen: ' + $_.Exception.Message)
            }
            $result.error = 'Blender konnte nicht automatisch installiert werden (Download + winget). Siehe blender-install.log im Bridge-Ordner.'
            return $result
        }
        Set-BlenderState -Shared $Shared -State 'installing' -Message 'Blender wird entpackt … (das dauert 1-2 Minuten)' -Percent 99 -Source 'download'
        try {
            $extractOk = $false
            try {
                Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
                [System.IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $folder)
                $extractOk = $true
            } catch {
                Write-BridgeLog -Shared $Shared -Text ('Schnelles Entpacken nicht moeglich (' + $_.Exception.Message + ') - Expand-Archive wird benutzt.')
            }
            if (-not $extractOk) { Expand-Archive -LiteralPath $zipPath -DestinationPath $folder -Force }
        } catch {
            $result.error = ('Blender wurde heruntergeladen, konnte aber nicht entpackt werden: ' + $_.Exception.Message)
            return $result
        }
        $exe = Get-BlenderExeInFolder $folder
        if (-not $exe) {
            $result.error = 'Im entpackten Archiv wurde blender.exe nicht gefunden.'
            return $result
        }
        $quick = Test-BlenderQuick -Path $exe
        if (-not $quick.ok) {
            $result.error = ('Die entpackte blender.exe ist unbrauchbar: ' + [string]$quick.error)
            return $result
        }
        try { if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue } } catch {}
        Write-BridgeLog -Shared $Shared -Text ('Blender entpackt: ' + [string]$exe + ' (Version ' + [string]$quick.version + ', Quelle ' + [string]$usedUrl + ').')
        $result.ok = $true
        $result.path = [string]$exe
        $result.version = [string]$quick.version
        return $result
    }

    function Start-BlenderStepRunspace {
        # EIN Hintergrund-Runspace fuer Schritt 4: suchen -> Version -> (bei
        # Bedarf installieren) -> ECHTE Faehigkeitsprobe. Diese Funktion liegt
        # in der EINEN Hilfs-Quelle, damit auch der Handler-Runspace sie
        # benutzen kann (dort gibt es keine $script:-Funktionen des
        # Hauptprogramms - die 7.4.0-Phantom-Funktionen).
        param($Shared)
        try {
            $ps = [PowerShell]::Create()
            [void]$ps.AddScript([string]$Shared.BlenderStepScriptText).AddArgument($Shared)
            [void]$ps.BeginInvoke()
            return $true
        } catch {
            Write-BridgeLog -Shared $Shared -Text ('Blender-Schritt 4 konnte nicht gestartet werden: ' + $_.Exception.Message)
            Set-BlenderState -Shared $Shared -State 'failed' -Detail ('Der Pruef-Thread konnte nicht gestartet werden: ' + $_.Exception.Message) -Message 'Blender konnte nicht geprueft werden - der Mesh-Bau ist AUS, alles andere laeuft normal.' -Enabled $false -Percent 0 -Probe 'failed' -GateResolved $true
            return $false
        }
    }

    function Start-BlenderRecheck {
        # "Blender pruefen" (Zeile 4 im Startbildschirm, blender_status
        # action=check) wiederholt die ECHTE Faehigkeitsprobe - NICHT nur das
        # Lesen der Version. Antwortet sofort; die Arbeit laeuft im
        # Hintergrund-Runspace.
        param($Shared)
        $state = ''
        try { $state = [string]$Shared.BlenderState.state } catch {}
        if ($state -in @('searching', 'installing', 'probing')) { return $false }
        Set-BlenderState -Shared $Shared -State 'searching' -Message 'Blender wird erneut geprueft (echte Faehigkeitsprobe) ...' -Percent 0 -GateResolved $false -ResetProbe
        Write-BridgeLog -Shared $Shared -Text 'Blender-Pruefung angefordert - Suche, Version und Faehigkeitsprobe laufen im Hintergrund-Runspace.'
        return (Start-BlenderStepRunspace -Shared $Shared)
    }

    function Get-BlenderReport {
        # Kompakter Zustand fuer Werkzeuge und Fenster (ehrlich, ohne Behauptung).
        param($Shared)
        $map = $Shared.BlenderState
        $blenderFolder = ''
        $meshFolder = ''
        try { $blenderFolder = [string]$Shared.BlenderFolder } catch {}
        try { $meshFolder = [string]$Shared.MeshRoot } catch {}
        $report = @{
            state = [string]$map.state
            enabled = [bool]$map.enabled
            path = [string]$map.path
            version = [string]$map.version
            detail = [string]$map.detail
            message = [string]$map.message
            percent = [int]$map.percent
            source = [string]$map.source
            probe = [string]$map.probe
            gateResolved = [bool]$map.gateResolved
            updatedAt = [long]$map.updatedAt
            folder = $blenderFolder
            meshFolder = $meshFolder
            installing = ([string]$map.state -eq 'installing')
            probing = ([string]$map.state -eq 'probing')
        }
        if ($report.enabled -ne $true) {
            $report.hint = 'Mesh-Bau ist deaktiviert, solange Blender nicht bereit ist. Die Polygon-Wedge-Wege (build_polygon_model/build_assembly) funktionieren unabhaengig davon weiter.'
        }
        return $report
    }
}

# Version 7.4.1: EINE Hilfs-Quelle laden - das Hauptprogramm benutzt GENAU
# dieselben Blender-Helfer wie jeder Runspace (keine Phantom-Funktionen).
try { . ([scriptblock]::Create([string]$script:BridgeBlenderTools)) } catch {
    try { Write-RuntimeLog ('Blender-Helfer konnten nicht geladen werden: ' + $_.Exception.Message) } catch {}
}

function Start-BlenderStartupGate {
    # Schritt 4 des Starts. Suche + Version + ECHTE Faehigkeitsprobe laufen in
    # EINEM Hintergrund-Runspace (in 7.4.0 liefen sie im UI-Thread und froren
    # das Fenster ein). Der Tunnel startet erst nach dem Endzustand
    # (Complete-BlenderStartupGate im UI-Takt). Ein Fehlschlag macht die Zeile
    # rot, deaktiviert den Mesh-Bau und laesst alles andere weiterlaufen -
    # KEIN Start-Blocker.
    Set-StartupStage 'Blender-Pruefung (Schritt 4)'
    $script:BlenderGatePending = $true
    $script:BlenderSkippedByUser = $false
    $script:BlenderGateDeadline = (Get-Date).AddMinutes(12)
    $script:BlenderAttempts = [int]$script:BlenderAttempts + 1
    Set-BlenderState -Shared $script:Shared -State 'searching' -Message 'Blender wird gesucht und geprueft (echte Faehigkeitsprobe) ...' -Percent 0 -ResetProbe
    Write-RuntimeLog 'Schritt 4: Blender-Suche, Version und Faehigkeitsprobe laufen im Hintergrund (Zeitlimit Suchen/Pruefen 180 s, Gesamt-Gate 12 min).'
    [void](Start-BlenderStepRunspace -Shared $script:Shared)
    return $false
}

function Complete-BlenderStartupGate {
    # Wird vom UI-Takt aufgerufen. Sobald der Schritt 4 in einem Endzustand
    # ist (fertig / fehlgeschlagen / uebersprungen), startet der Tunnel.
    if (-not $script:BlenderGatePending) { return }
    $map = $script:Shared.BlenderState
    $state = [string]$map.state
    $terminal = ($state -eq 'ready' -or $state -eq 'failed' -or $state -eq 'skipped')
    $timedOut = ((Get-Date) -gt $script:BlenderGateDeadline)
    if (-not $terminal -and -not $timedOut) { return }
    if ($timedOut -and -not $terminal) {
        Set-BlenderState -Shared $script:Shared -State 'failed' -Detail 'Zeitlimit erreicht - der Blender-Schritt wurde beendet.' -Message 'Blender konnte nicht rechtzeitig bereitgestellt werden. Der Mesh-Bau ist vorerst AUS, alles andere laeuft normal.' -Enabled $false -Percent 0 -Probe 'failed' -GateResolved $true
        Write-RuntimeLog 'Blender-Schritt 4 im Zeitlimit beendet - Mesh-Bau vorerst deaktiviert, Start laeuft weiter.'
    }
    $script:BlenderGatePending = $false
    Start-CloudflareTunnel
}

function Update-BlenderSplashRow {
    # Zeile 4 im Startbildschirm: gruen = bereit (NUR nach der Probe), amber =
    # suchen/pruefen/installieren, rot = fehlgeschlagen (Mesh-Bau aus), grau =
    # uebersprungen. Ein Klick auf den Zustandstext wiederholt die ECHTE Probe.
    param($Row)
    $dot = $null
    $state = $null
    try { $dot = $script:SplashBlenderDot } catch {}
    try { $state = $script:SplashBlenderState } catch {}
    if ($null -eq $state) { return }
    $map = $script:Shared.BlenderState
    $mode = [string]$map.state
    if ($mode -eq 'ready') {
        if ($dot) { Set-Dot $dot $script:ColorGreen }
        $text = 'Bereit'
        if (-not [string]::IsNullOrWhiteSpace([string]$map.version)) { $text = ('Bereit (' + [string]$map.version + ')') }
        Set-Text $state $text
        $state.Foreground = Get-Brush '#9AD9AE'
        return
    }
    if ($mode -eq 'failed') {
        if ($dot) { Set-Dot $dot $script:ColorRed }
        Set-Text $state 'Nicht verfügbar'
        $state.Foreground = Get-Brush '#FF8AA0'
        return
    }
    if ($mode -eq 'skipped') {
        if ($dot) { Set-Dot $dot $script:ColorGray }
        Set-Text $state 'Übersprungen'
        $state.Foreground = Get-Brush '#9AA9CE'
        return
    }
    if ($mode -eq 'installing') {
        if ($dot) { Set-Dot $dot $script:ColorAmber }
        $percent = 0
        try { $percent = [int]$map.percent } catch {}
        if ($percent -gt 0) { Set-Text $state ('Wird installiert … ' + [string]$percent + ' %') } else { Set-Text $state 'Wird installiert …' }
        $state.Foreground = Get-Brush '#FFD9A0'
        return
    }
    if ($mode -eq 'searching' -or $mode -eq 'probing') {
        if ($dot) { Set-Dot $dot $script:ColorAmber }
        if ($mode -eq 'probing') { Set-Text $state 'Wird geprüft …' } else { Set-Text $state 'Wird gesucht …' }
        $state.Foreground = Get-Brush '#9AA9CE'
        return
    }
    if ($null -ne $Row) {
        if ($dot) { Set-Dot $dot $script:ColorAmber }
        Set-Text $state 'Wird geprüft …'
        $state.Foreground = Get-Brush '#9AA9CE'
        return
    }
    if ($dot) { Set-Dot $dot $script:ColorGray }
    Set-Text $state 'Wartet …'
    $state.Foreground = Get-Brush '#9AA9CE'
}


# ============================================================================
# Version 7.4.0: MESH-BAU - Blender headless, OBJ MESSEN, Platzhalter, IDs
# ============================================================================
# Ablauf (ehrlich, ohne Behauptung):
#   build_mesh_model  -> Bridge schreibt Blender-Skripte + Runner, startet
#                        Blender im Hintergrund (ein Prozess je Slot).
#   Worker            -> Blender erzeugt die OBJ-Datei; die Bridge MISST sie
#                        (Dreiecke, Bounds in Studs, Objekte, Materialien).
#   mesh_slots        -> viereckige MeshPart-Platzhalter im Place, mit
#                        Attributen (ArenaPlaceholder, ArenaMeshSlot, ...).
#   Nutzer            -> laedt die OBJ-Datei in Roblox hoch und traegt die
#                        Asset-Id im Fenster "Mesh-Uploads" ein.
#   mesh_apply_asset  -> Bridge setzt die Geometrie ueber
#                        InsertService:CreateMeshPartAsync + ApplyMesh in die
#                        Platzhalter (MeshId ist schreibgeschuetzt).
# ----------------------------------------------------------------------------

$script:BridgeMeshToolkit = {
    # ----------------------------------------------------------------
    # OBJ MESSEN - die Bridge glaubt keine Zahlen, sie liest sie selbst.
    # ----------------------------------------------------------------
    function Get-MeshObjStats {
        param($Shared, [string]$Path, [int]$Limit = 10000)
        $stats = @{
            ok = $false; error = ''; bytes = 0; vertices = 0; faces = 0; triangles = 0
            objects = 0; groups = 0; materials = 0; hasNaN = $false
            min = @{ x = 0.0; y = 0.0; z = 0.0 }; max = @{ x = 0.0; y = 0.0; z = 0.0 }
            size = @{ x = 0.0; y = 0.0; z = 0.0 }; limit = $Limit; overLimit = $false
        }
        try {
            if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) {
                $stats.error = 'Die OBJ-Datei wurde nicht gefunden.'
                return $stats
            }
            $stats.bytes = [int64](Get-Item -LiteralPath $Path).Length
            if ($stats.bytes -le 0) { $stats.error = 'Die OBJ-Datei ist leer.'; return $stats }
            $minX = [double]::MaxValue; $minY = [double]::MaxValue; $minZ = [double]::MaxValue
            $maxX = [double]::MinValue; $maxY = [double]::MinValue; $maxZ = [double]::MinValue
            $culture = [System.Globalization.CultureInfo]::InvariantCulture
            $reader = [System.IO.StreamReader]::new($Path, [System.Text.Encoding]::UTF8)
            try {
                while ($null -ne ($line = $reader.ReadLine())) {
                    if ($line.Length -lt 2) { continue }
                    $head = $line.Substring(0, 2)
                    if ($head -eq 'v ') {
                        $parts = $line.Split([char[]]@(' ', [char]9), [System.StringSplitOptions]::RemoveEmptyEntries)
                        if ($parts.Length -lt 4) { continue }
                        $x = 0.0; $y = 0.0; $z = 0.0
                        [void][double]::TryParse($parts[1], [System.Globalization.NumberStyles]::Float, $culture, [ref]$x)
                        [void][double]::TryParse($parts[2], [System.Globalization.NumberStyles]::Float, $culture, [ref]$y)
                        [void][double]::TryParse($parts[3], [System.Globalization.NumberStyles]::Float, $culture, [ref]$z)
                        if ([double]::IsNaN($x) -or [double]::IsNaN($y) -or [double]::IsNaN($z) -or [double]::IsInfinity($x) -or [double]::IsInfinity($y) -or [double]::IsInfinity($z)) { $stats.hasNaN = $true; continue }
                        $stats.vertices = [int]$stats.vertices + 1
                        if ($x -lt $minX) { $minX = $x }
                        if ($y -lt $minY) { $minY = $y }
                        if ($z -lt $minZ) { $minZ = $z }
                        if ($x -gt $maxX) { $maxX = $x }
                        if ($y -gt $maxY) { $maxY = $y }
                        if ($z -gt $maxZ) { $maxZ = $z }
                    } elseif ($head -eq 'f ') {
                        $parts = $line.Split([char[]]@(' ', [char]9), [System.StringSplitOptions]::RemoveEmptyEntries)
                        $count = $parts.Length - 1
                        if ($count -ge 3) {
                            $stats.faces = [int]$stats.faces + 1
                            $stats.triangles = [int]$stats.triangles + ($count - 2)
                        }
                    } elseif ($line.StartsWith('usemtl')) {
                        $stats.materials = [int]$stats.materials + 1
                    } elseif ($head -eq 'o ') {
                        $stats.objects = [int]$stats.objects + 1
                    } elseif ($head -eq 'g ') {
                        $stats.groups = [int]$stats.groups + 1
                    }
                }
            } finally {
                try { $reader.Dispose() } catch {}
            }
            if ($stats.vertices -le 0) { $stats.error = 'Die OBJ-Datei enthaelt keine Punkte.'; return $stats }
            if ($stats.triangles -le 0) { $stats.error = 'Die OBJ-Datei enthaelt keine Flaechen.'; return $stats }
            $stats.min = @{ x = $minX; y = $minY; z = $minZ }
            $stats.max = @{ x = $maxX; y = $maxY; z = $maxZ }
            $stats.size = @{ x = [Math]::Round(($maxX - $minX), 4); y = [Math]::Round(($maxY - $minY), 4); z = [Math]::Round(($maxZ - $minZ), 4) }
            if ([int]$stats.triangles -gt $Limit) { $stats.overLimit = $true }
            $stats.ok = $true
            return $stats
        } catch {
            $stats.error = $_.Exception.Message
            return $stats
        }
    }

    # ----------------------------------------------------------------
    # SKRIPT-PRUEFUNG. Ehrlich: das ist eine LEITPLANKE, kein Sandkasten.
    # Blender-Skripte bauen Geometrie - alles andere wird abgelehnt.
    # ----------------------------------------------------------------
    function Test-MeshScriptSafety {
        param([string]$Script)
        if ([string]::IsNullOrWhiteSpace($Script)) { return @{ ok = $false; reason = 'Das Blender-Skript ist leer.' } }
        if ($Script.Length -gt 200000) { return @{ ok = $false; reason = 'Das Blender-Skript ist zu gross (max. 200 KB).' } }
        $deny = @(
            @{ token = 'import os'; why = 'Modul os ist gesperrt' },
            @{ token = 'import sys'; why = 'Modul sys ist gesperrt' },
            @{ token = 'subprocess'; why = 'Prozessstart ist gesperrt' },
            @{ token = '__import__'; why = 'dynamischer Import ist gesperrt' },
            @{ token = 'importlib'; why = 'dynamischer Import ist gesperrt' },
            @{ token = 'socket'; why = 'Netzwerk ist gesperrt' },
            @{ token = 'urllib'; why = 'Netzwerk ist gesperrt' },
            @{ token = 'requests'; why = 'Netzwerk ist gesperrt' },
            @{ token = 'shutil'; why = 'Dateizugriff ist gesperrt' },
            @{ token = 'ctypes'; why = 'Systemaufrufe sind gesperrt' },
            @{ token = 'winreg'; why = 'Registry-Zugriff ist gesperrt' },
            @{ token = 'pickle'; why = 'Serialisierung ist gesperrt' },
            @{ token = 'eval('; why = 'eval ist gesperrt' },
            @{ token = 'exec('; why = 'exec ist gesperrt' },
            @{ token = 'compile('; why = 'compile ist gesperrt' },
            @{ token = 'open('; why = 'direkter Dateizugriff ist gesperrt' },
            @{ token = 'pathlib'; why = 'Dateizugriff ist gesperrt' },
            @{ token = 'glob'; why = 'Dateizugriff ist gesperrt' },
            @{ token = 'bpy.ops.wm.'; why = 'Datei-/Exportoperationen macht der Runner der Bridge' },
            @{ token = 'export_scene'; why = 'der Export wird von der Bridge gemacht' },
            @{ token = 'import_scene'; why = 'das Laden externer Dateien ist gesperrt' },
            @{ token = 'save_as_mainfile'; why = 'Dateizugriff ist gesperrt' },
            @{ token = 'open_mainfile'; why = 'Dateizugriff ist gesperrt' },
            @{ token = 'libraries'; why = 'Bibliothekszugriff ist gesperrt' },
            @{ token = 'bpy.utils.'; why = 'Erweiterungen/Skripte sind gesperrt' }
        )
        $lower = $Script.ToLowerInvariant()
        foreach ($rule in $deny) {
            if ($lower.Contains([string]$rule.token)) {
                return @{ ok = $false; reason = ('Nicht erlaubt: ' + [string]$rule.why + ' ("' + [string]$rule.token + '"). Blender-Skripte bauen NUR Geometrie ueber bpy - kein Datei-, Netzwerk- oder Systemzugriff.') }
            }
        }
        $allowed = @('bpy', 'bmesh', 'math', 'mathutils', 'random')
        foreach ($hit in [System.Text.RegularExpressions.Regex]::Matches($Script, '(?m)^\s*(?:from\s+([A-Za-z_][A-Za-z0-9_\.]*)\s+import|import\s+([A-Za-z_][A-Za-z0-9_\.]*))')) {
            $module = [string]$hit.Groups[1].Value
            if ([string]::IsNullOrWhiteSpace($module)) { $module = [string]$hit.Groups[2].Value }
            $module = $module.Split('.')[0]
            if ($allowed -notcontains $module) {
                return @{ ok = $false; reason = ('Modul "' + $module + '" ist nicht freigegeben. Erlaubt sind nur: bpy, bmesh, math, mathutils, random.') }
            }
        }
        return @{ ok = $true; reason = '' }
    }

    function Get-MeshJobData {
        param($Shared, [string]$JobId)
        $json = $null
        if ([string]::IsNullOrWhiteSpace($JobId)) { return $null }
        if (-not $Shared.MeshJobs.TryGetValue([string]$JobId, [ref]$json)) { return $null }
        if ([string]::IsNullOrWhiteSpace($json)) { return $null }
        try { return ($json | ConvertFrom-Json) } catch { return $null }
    }

    function Save-MeshJobData {
        param($Shared, $JobData)
        if ($null -eq $JobData) { return }
        try {
            $JobData.updatedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            $Shared.MeshJobs[[string]$JobData.id] = ($JobData | ConvertTo-Json -Depth 8 -Compress)
        } catch {}
    }

    function Get-MeshSlotData {
        param($Shared, [string]$SlotKey)
        $json = $null
        if ([string]::IsNullOrWhiteSpace($SlotKey)) { return $null }
        if (-not $Shared.MeshRegistry.TryGetValue([string]$SlotKey, [ref]$json)) { return $null }
        if ([string]::IsNullOrWhiteSpace($json)) { return $null }
        try { return ($json | ConvertFrom-Json) } catch { return $null }
    }

    function Set-MeshSlotField {
        param($Shared, [string]$SlotKey, [string]$Name, $Value)
        if ([string]::IsNullOrWhiteSpace($SlotKey)) { return }
        try {
            $data = Get-MeshSlotData $Shared $SlotKey
            if ($null -eq $data) { return }
            $existing = $data.PSObject.Properties[$Name]
            if ($existing) { $existing.Value = $Value } else { $data | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force }
            $data.updatedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            $Shared.MeshRegistry[[string]$SlotKey] = ($data | ConvertTo-Json -Depth 8 -Compress)
        } catch {}
    }

    function Save-MeshRegistryFile {
        param($Shared)
        $path = ''
        try { $path = [string]$Shared.MeshRegistryPath } catch {}
        if ([string]::IsNullOrWhiteSpace($path)) { return }
        try {
            $rows = New-Object System.Collections.Generic.List[object]
            foreach ($pair in $Shared.MeshRegistry.GetEnumerator()) {
                try { $rows.Add(($pair.Value | ConvertFrom-Json)) } catch {}
            }
            $payload = @{ registryVersion = '7.4.1'; updatedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds(); slots = $rows.ToArray() }
            # Version 7.4.1: BOM-FREI schreiben (WriteAllText statt Set-Content).
            [System.IO.File]::WriteAllText($path, [string]($payload | ConvertTo-Json -Depth 8), (New-Object System.Text.UTF8Encoding($false)))
        } catch {}
    }

    function Get-MeshSlotsBySession {
        param($Shared, [string]$SessionId, [string]$JobId = '')
        $rows = New-Object System.Collections.Generic.List[object]
        foreach ($pair in $Shared.MeshRegistry.GetEnumerator()) {
            $data = $null
            try { $data = ($pair.Value | ConvertFrom-Json) } catch { continue }
            if ($null -eq $data) { continue }
            if (-not [string]::IsNullOrWhiteSpace($SessionId) -and [string]$data.sessionId -ne [string]$SessionId) { continue }
            if (-not [string]::IsNullOrWhiteSpace($JobId) -and [string]$data.jobId -ne [string]$JobId) { continue }
            $rows.Add($data)
        }
        return ,$rows
    }

    function Start-MeshJobWork {
        param($Shared, [string]$BlenderPath, $Spec)
        # Spec kommt fertig geprueft vom Werkzeug: modelName, sessionId, root,
        # timeoutSeconds und slots[] (name, fileName, script, targetTriangles,
        # color, material, canCollide).
        $jobId = 'mesh_' + ([guid]::NewGuid().ToString('N').Substring(0, 10))
        $root = [string]$Shared.MeshRoot
        $jobFolder = Join-Path $root $jobId
        if (-not (Test-Path -LiteralPath $jobFolder)) { [void](New-Item -ItemType Directory -Path $jobFolder -Force) }
        $runnerPath = Join-Path $jobFolder 'runner.py'
        # Version 7.4.1: BOM-FREI schreiben! Set-Content -Encoding UTF8 setzt
        # im Windows PowerShell 5.1 ein BOM - genau das brach den Mesh-Bau
        # (SyntaxError: invalid non-printable character U+FEFF).
        [System.IO.File]::WriteAllText($runnerPath, [string]$Shared.MeshRunnerText, (New-Object System.Text.UTF8Encoding($false)))
        $slots = New-Object System.Collections.Generic.List[object]
        $index = 0
        foreach ($slot in $Spec.slots) {
            $index = $index + 1
            $name = [string]$slot.name
            if ([string]::IsNullOrWhiteSpace($name)) { $name = ('slot' + [string]$index) }
            $slotKey = ($jobId + ':' + $name)
            $scriptPath = Join-Path $jobFolder ($name + '.py')
            $objPath = Join-Path $jobFolder ($name + '.obj')
            [System.IO.File]::WriteAllText($scriptPath, [string]$slot.script, (New-Object System.Text.UTF8Encoding($false)))
            $slots.Add([pscustomobject]@{
                key = $slotKey
                name = $name
                scriptPath = $scriptPath
                objPath = $objPath
                runnerPath = $runnerPath
                state = 'pending'
                triangles = 0
                targetTriangles = [int]$slot.targetTriangles
                color = [string]$slot.color
                material = [string]$slot.material
                canCollide = [bool]$slot.canCollide
                size = $null
                error = ''
                startedAt = 0
                finishedAt = 0
            })
            $registry = [ordered]@{
                slotKey = $slotKey
                jobId = $jobId
                sessionId = [string]$Spec.sessionId
                modelName = [string]$Spec.modelName
                slotName = $name
                state = 'pending'
                fileName = [System.IO.Path]::GetFileName($objPath)
                objPath = $objPath
                scriptPath = $scriptPath
                triangles = 0
                size = $null
                color = [string]$slot.color
                material = [string]$slot.material
                assetId = ''
                placeholderPath = ''
                # Platzierung: die Bridge legt die Platzhalter genau dorthin.
                parentRef = [string]$Spec.parentRef
                origin = $Spec.origin
                offset = $slot.offset
                rotationY = [double]$Spec.rotationY
                anchored = [bool]$Spec.anchored
                canCollide = [bool]$slot.canCollide
                error = ''
                createdAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
                updatedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            }
            $Shared.MeshRegistry[$slotKey] = ($registry | ConvertTo-Json -Depth 6 -Compress)
        }
        $job = [ordered]@{
            id = $jobId
            modelName = [string]$Spec.modelName
            sessionId = [string]$Spec.sessionId
            parentRef = [string]$Spec.parentRef
            origin = $Spec.origin
            rotationY = [double]$Spec.rotationY
            anchored = [bool]$Spec.anchored
            placeholdersCreated = $false
            state = 'queued'
            folder = $jobFolder
            logFile = (Join-Path $jobFolder 'build-log.txt')
            blenderPath = [string]$BlenderPath
            timeoutSeconds = [int]$Spec.timeoutSeconds
            cancelRequested = $false
            currentPid = 0
            currentSlot = ''
            createdAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            updatedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
            finishedAt = 0
            slots = $slots
            error = ''
            note = 'Blender laeuft im Hintergrund. Der Nutzer muss die OBJ-Datei spaeter in Roblox hochladen und die Asset-Id im Bridge-Fenster "Mesh-Uploads" eintragen.'
        }
        $Shared.MeshJobs[$jobId] = ($job | ConvertTo-Json -Depth 8 -Compress)
        Save-MeshRegistryFile $Shared
        # Worker: eigener Runspace, damit die HTTP-Antwort sofort zurueckgeht.
        $ps = [PowerShell]::Create()
        [void]$ps.AddScript([string]$Shared.MeshJobScriptText).AddArgument($Shared).AddArgument($jobId).AddArgument([string]$Shared.MeshToolkitText)
        [void]$ps.BeginInvoke()
        return $jobId
    }

    function Stop-MeshJob {
        param($Shared, [string]$JobId)
        $job = Get-MeshJobData $Shared $JobId
        if ($null -eq $job) { return $false }
        if ([string]$job.state -in @('measured', 'failed', 'cancelled')) { return $false }
        try {
            $job.cancelRequested = $true
            Save-MeshJobData $Shared $job
        } catch {}
        $pidToKill = 0
        try { $pidToKill = [int]$job.currentPid } catch { $pidToKill = 0 }
        if ($pidToKill -gt 0) {
            try { Stop-Process -Id $pidToKill -Force -ErrorAction SilentlyContinue } catch {}
        }
        foreach ($slot in (Get-MeshSlotsBySession $Shared ([string]$job.sessionId) $JobId)) {
            if ([string]$slot.state -in @('pending', 'running', 'script')) {
                Set-MeshSlotField $Shared ([string]$slot.slotKey) 'state' 'cancelled'
                Set-MeshSlotField $Shared ([string]$slot.slotKey) 'error' 'Vom Nutzer abgebrochen.'
            }
        }
        return $true
    }

    # ------------------------------------------------------------------
    # Interne Mesh-Befehle (Version 7.4.0): Befehle, die die BRIDGE selbst an
    # Studio schickt - Platzhalter anlegen, Geometrie einsetzen. Sie benutzen
    # den normalen Befehlsweg, aber ohne wartenden HTTP-Aufruf: es gibt ein
    # wartendes Signal (damit das Ergebnis nicht als "late result" beim
    # Agenten landet) und die Oberflaeche erntet das Ergebnis im UI-Takt.
    # ------------------------------------------------------------------
    function New-MeshBridgeCommand {
        param($Shared, [string]$SessionId, [string]$Tool, $ToolArgs, [int]$BudgetSeconds = 120, [string]$Tag = '')
        $sid = [string]$SessionId
        if ([string]::IsNullOrWhiteSpace($sid)) { return '' }
        $commandId = [guid]::NewGuid().ToString('N')
        $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        $budget = [Math]::Max(30, [Math]::Min(300, [int]$BudgetSeconds))
        $payloadJson = (@{ id = $commandId; tool = [string]$Tool; args = $ToolArgs; queuedAt = $now; budgetSeconds = $budget } | ConvertTo-Json -Depth 12 -Compress)
        $record = @{
            sessionId = $sid
            commandId = $commandId
            tool = [string]$Tool
            status = 'queued'
            createdAt = $now
            queuedAt = $now
            deliveredAt = 0
            lastDeliveryAt = 0
            receivedAt = 0
            startedAt = 0
            heartbeatAt = 0
            unackedCount = 0
            deliveryAttempts = 0
            budgetSeconds = $budget
            executor = $null
        }
        $recordJson = ($record | ConvertTo-Json -Depth 6 -Compress)
        $signal = New-Object System.Threading.ManualResetEventSlim($false)
        [void]$Shared.ResultSignals.TryAdd($commandId, $signal)
        $Shared.CommandPayloads[$commandId] = $payloadJson
        $Shared.CommandOwners[$commandId] = $sid
        $Shared.CommandOrigins[$commandId] = $sid
        $Shared.CommandStates[$commandId] = $recordJson
        try {
            foreach ($pair in @($Shared.InstanceSessions.GetEnumerator())) {
                if ([string]$pair.Value -eq $sid) { $Shared.CommandInstanceGuids[$commandId] = [string]$pair.Key; break }
            }
        } catch {}
        try {
            $bag = $null
            if (-not $Shared.PendingCommands.TryGetValue($sid, [ref]$bag)) {
                $bag = [System.Collections.Concurrent.ConcurrentDictionary[string,string]]::new()
                [void]$Shared.PendingCommands.TryAdd($sid, $bag)
                [void]$Shared.PendingCommands.TryGetValue($sid, [ref]$bag)
            }
            $bag[$commandId] = $recordJson
        } catch {}
        try {
            $queue = $null
            if (-not $Shared.CommandQueues.TryGetValue($sid, [ref]$queue)) {
                $queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
                [void]$Shared.CommandQueues.TryAdd($sid, $queue)
                [void]$Shared.CommandQueues.TryGetValue($sid, [ref]$queue)
            }
            [System.Threading.Monitor]::Enter($Shared.CommandQueueLock)
            try {
                if ($queue.Count -lt 64) { $queue.Enqueue($payloadJson) }
            } finally {
                [System.Threading.Monitor]::Exit($Shared.CommandQueueLock)
            }
            $poke = $null
            if (-not $Shared.CommandSignals.TryGetValue($sid, [ref]$poke)) {
                $poke = New-Object System.Threading.ManualResetEventSlim($false)
                [void]$Shared.CommandSignals.TryAdd($sid, $poke)
                [void]$Shared.CommandSignals.TryGetValue($sid, [ref]$poke)
            }
            if ($poke) { [void]$poke.Set() }
        } catch {}
        try { $Shared.MeshInternal['cmd:' + $commandId] = ([string]$Tag + '|' + [string]$Tool) } catch {}
        return $commandId
    }

    function Get-MeshCommandOutcome {
        # Ergebnis eines internen Befehls abholen: pending / done / error.
        param($Shared, [string]$CommandId)
        $id = [string]$CommandId
        if ([string]::IsNullOrWhiteSpace($id)) { return @{ state = 'invalid'; message = 'Es wurde kein Befehl angegeben.' } }
        $json = $null
        if ($Shared.CommandResults.TryRemove($id, [ref]$json)) {
            $removedSignal = $null
            [void]$Shared.ResultSignals.TryRemove($id, [ref]$removedSignal)
            if ($removedSignal) { try { $removedSignal.Dispose() } catch {} }
            $discard = $null
            [void]$Shared.MeshInternal.TryRemove('cmd:' + $id, [ref]$discard)
            if ([string]::IsNullOrWhiteSpace($json)) { return @{ state = 'error'; message = 'Der Befehl kam ohne Ergebnis zurueck.' } }
            return @{ state = 'done'; json = $json }
        }
        $stateJson = $null
        if ($Shared.CommandStates.TryGetValue($id, [ref]$stateJson) -and -not [string]::IsNullOrWhiteSpace($stateJson)) {
            $status = ''
            $finishedAt = 0
            $code = ''
            try { $view = $stateJson | ConvertFrom-Json; $status = [string]$view.status; $finishedAt = [int64]$view.finishedAt; $code = [string]$view.resultCode } catch {}
            if ($status -in @('completed', 'failed', 'abandoned', 'cancelled')) {
                $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
                if (($now - $finishedAt) -ge 6) {
                    # Endgueltig: nur noch aufraeumen. Das Ergebnis ist verloren
                    # (z.B. Plugin-Neustart) - ehrlich melden, nichts erfinden.
                    $removedSignal = $null
                    [void]$Shared.ResultSignals.TryRemove($id, [ref]$removedSignal)
                    if ($removedSignal) { try { $removedSignal.Dispose() } catch {} }
                    $discard = $null
                    [void]$Shared.MeshInternal.TryRemove('cmd:' + $id, [ref]$discard)
                    [void]$Shared.CommandStates.TryRemove($id, [ref]$discard)
                    [void]$Shared.CommandPayloads.TryRemove($id, [ref]$discard)
                    $message = 'Der Befehl wurde nicht ausgefuehrt (' + $status + ')'
                    if (-not [string]::IsNullOrWhiteSpace($code)) { $message = $message + ' - Code ' + $code }
                    return @{ state = 'error'; message = ($message + '. Studio hat nicht geantwortet oder die Sitzung wurde beendet.') }
                }
            }
        }
        return @{ state = 'pending' }
    }

    function Send-MeshPlaceholders {
        # Nach der Messung: fuer jeden gemessenen Slot einen viereckigen
        # MeshPart-Platzhalter in den Place setzen lassen. Die Befehls-Id wird
        # im Job vermerkt, damit die Oberflaeche das Ergebnis zuordnen kann.
        param($Shared, [string]$JobId)
        $job = Get-MeshJobData $Shared $JobId
        if ($null -eq $job) { return '' }
        if ([bool]$job.placeholdersCreated) { return [string]$job.placeholderCommandId }
        $slots = New-Object System.Collections.Generic.List[object]
        foreach ($slot in (Get-MeshSlotsBySession $Shared ([string]$job.sessionId) $JobId)) {
            if ([string]$slot.state -ne 'obj' -and [string]$slot.state -ne 'applied') { continue }
            $size = $slot.size
            if ($null -eq $size) { continue }
            $offset = $slot.offset
            $position = @{ x = 0.0; y = 0.0; z = 0.0 }
            try {
                $position = @{
                    x = ([double]$job.origin.x + [double]$offset.x)
                    y = ([double]$job.origin.y + [double]$offset.y)
                    z = ([double]$job.origin.z + [double]$offset.z)
                }
            } catch { $position = @{ x = 0.0; y = 0.0; z = 0.0 } }
            $slots.Add(@{
                key = [string]$slot.slotKey
                name = [string]$slot.slotName
                size = @{ x = [double]$size.x; y = [double]$size.y; z = [double]$size.z }
                position = $position
                rotationY = [double]$job.rotationY
                anchored = [bool]$job.anchored
                canCollide = [bool]$slot.canCollide
                color = [string]$slot.color
                material = [string]$slot.material
                fileName = [string]$slot.fileName
            })
        }
        if ($slots.Count -eq 0) { return '' }
        $args = @{
            parentRef = [string]$job.parentRef
            buildId = [string]$job.id
            modelName = [string]$job.modelName
            slots = $slots.ToArray()
        }
        $commandId = New-MeshBridgeCommand -Shared $Shared -SessionId ([string]$job.sessionId) -Tool 'mesh_slots' -ToolArgs $args -BudgetSeconds 150 -Tag ('placeholders:' + [string]$job.id)
        if (-not [string]::IsNullOrWhiteSpace($commandId)) {
            $job.placeholderCommandId = $commandId
            $job.placeholderState = 'sent'
            Save-MeshJobData $Shared $job
        }
        return $commandId
    }

    function Update-MeshRegistryFromPlaceholderResult {
        # Ergebnis von mesh_slots verbuchen: Platzhalter-Pfade sichern und den
        # Job als "Platzhalter stehen" markieren.
        param($Shared, [string]$JobId, $ResultJson)
        $job = Get-MeshJobData $Shared $JobId
        if ($null -eq $job) { return }
        $parsed = $null
        try { if (-not [string]::IsNullOrWhiteSpace([string]$ResultJson)) { $parsed = [string]$ResultJson | ConvertFrom-Json } } catch {}
        if ($null -eq $parsed) {
            $job.placeholderState = 'failed'
            $job.error = 'Die Antwort fuer die Platzhalter war nicht lesbar.'
            Save-MeshJobData $Shared $job
            return
        }
        $createdCount = 0
        try { if ($null -ne $parsed.createdCount) { $createdCount = [int]$parsed.createdCount } } catch {}
        $createdPaths = @{}
        try {
            foreach ($entry in @($parsed.created)) {
                if ($null -eq $entry) { continue }
                $key = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($key)) { continue }
                $createdPaths[$key] = [string]$entry.path
            }
        } catch {}
        foreach ($entry in $createdPaths.GetEnumerator()) {
            Set-MeshSlotField $Shared ([string]$entry.Key) 'placeholderPath' ([string]$entry.Value)
        }
        $failedCount = 0
        try { if ($null -ne $parsed.failedCount) { $failedCount = [int]$parsed.failedCount } } catch {}
        $job.placeholdersCreated = [bool]($createdCount -gt 0)
        if ($createdCount -gt 0) {
            $job.placeholderState = 'ready'
            $job.error = ''
        } else {
            $job.placeholderState = 'failed'
            $job.error = 'Die Platzhalter konnten nicht angelegt werden.'
            try {
                foreach ($entry in @($parsed.failed)) {
                    if ($null -ne $entry -and -not [string]::IsNullOrWhiteSpace([string]$entry.error)) {
                        $job.error = 'Die Platzhalter konnten nicht angelegt werden: ' + [string]$entry.error
                        break
                    }
                }
            } catch {}
        }
        if ($failedCount -gt 0 -and $createdCount -gt 0) {
            $job.note = 'Ein Teil der Platzhalter fehlt (' + [string]$failedCount + ' von ' + [string]([int]$createdCount + [int]$failedCount) + ').'
        }
        Save-MeshJobData $Shared $job
        Save-MeshRegistryFile $Shared
    }

    function Update-MeshRegistryFromApplyResult {
        # Ergebnis von mesh_apply verbuchen: je Slot Zustand, Asset-Id und die
        # zurueckgelesene MeshId. Nichts wird erfunden - steht im Ergebnis kein
        # Erfolg, bleibt der Slot auf 'apply_failed' mit der echten Fehlermeldung.
        param($Shared, $ResultJson)
        $parsed = $null
        try { if (-not [string]::IsNullOrWhiteSpace([string]$ResultJson)) { $parsed = [string]$ResultJson | ConvertFrom-Json } } catch {}
        if ($null -eq $parsed) { return $false }
        $applied = 0
        $failed = 0
        try {
            foreach ($entry in @($parsed.applied)) {
                if ($null -eq $entry) { continue }
                $key = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($key)) { continue }
                Set-MeshSlotField $Shared $key 'state' 'applied'
                Set-MeshSlotField $Shared $key 'error' ''
                Set-MeshSlotField $Shared $key 'placeholderPath' ([string]$entry.path)
                if (-not [string]::IsNullOrWhiteSpace([string]$entry.meshIdReadBack)) {
                    Set-MeshSlotField $Shared $key 'meshIdReadBack' ([string]$entry.meshIdReadBack)
                }
                Set-MeshSlotField $Shared $key 'appliedAt' ([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())
                $applied = $applied + 1
            }
        } catch {}
        try {
            foreach ($entry in @($parsed.failed)) {
                if ($null -eq $entry) { continue }
                $key = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($key)) { continue }
                $existing = Get-MeshSlotData $Shared $key
                $wasApplied = $false
                if ($null -ne $existing) { try { $wasApplied = ([string]$existing.state -eq 'applied') } catch {} }
                if (-not $wasApplied) { Set-MeshSlotField $Shared $key 'state' 'apply_failed' }
                Set-MeshSlotField $Shared $key 'error' ([string]$entry.error)
                $failed = $failed + 1
            }
        } catch {}
        Save-MeshRegistryFile $Shared
        return ($applied -gt 0)
    }

    function Remove-MeshSlotFiles {
        # Weniger Datenmuell (Version 7.4.1): OBJ + MTL + Slot-Skript loeschen.
        # Den Job-Ordner nur, wenn danach NICHTS mehr auf den Upload wartet.
        param($Shared, [string]$SlotKey, [bool]$RemoveSlot = $false)
        $result = @{ ok = $false; filesRemoved = 0; folderRemoved = $false; slotRemoved = $false; jobId = ''; error = '' }
        try {
            $slot = Get-MeshSlotData $Shared $SlotKey
            if ($null -eq $slot) { $result.error = 'Slot unbekannt.'; return $result }
            $result.jobId = [string]$slot.jobId
            $paths = New-Object System.Collections.Generic.List[string]
            try {
                if (-not [string]::IsNullOrWhiteSpace([string]$slot.objPath)) {
                    $paths.Add([string]$slot.objPath)
                    $paths.Add([System.IO.Path]::ChangeExtension([string]$slot.objPath, '.mtl'))
                }
            } catch {}
            try { if (-not [string]::IsNullOrWhiteSpace([string]$slot.scriptPath)) { $paths.Add([string]$slot.scriptPath) } } catch {}
            foreach ($path in $paths) {
                try {
                    if (Test-Path -LiteralPath $path) {
                        Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
                        if (-not (Test-Path -LiteralPath $path)) { $result.filesRemoved = [int]$result.filesRemoved + 1 }
                    }
                } catch { $result.error = $_.Exception.Message }
            }
            if ($RemoveSlot) {
                $discard = $null
                if ($Shared.MeshRegistry.TryRemove([string]$SlotKey, [ref]$discard)) { $result.slotRemoved = $true }
            }
            # Job-Ordner: nur wenn kein Slot dieses Jobs mehr wartet.
            $job = Get-MeshJobData $Shared ([string]$result.jobId)
            if ($null -ne $job) {
                $openLeft = 0
                foreach ($other in (Get-MeshSlotsBySession $Shared ([string]$job.sessionId) ([string]$job.id))) {
                    $otherState = ''
                    try { $otherState = [string]$other.state } catch {}
                    if ($otherState -in @('obj', 'applying', 'dropping', 'pending', 'running', 'measured')) { $openLeft = $openLeft + 1 }
                }
                if ($RemoveSlot) {
                    # Stornierte Slots auch aus der Job-Kopie nehmen (mesh_status
                    # liest das Register, der Job bleibt sonst mit Altstand stehen).
                    $kept = New-Object System.Collections.Generic.List[object]
                    foreach ($entry in @($job.slots)) {
                        $entryKey = ''
                        try { $entryKey = [string]$entry.key } catch {}
                        if ($entryKey -ne [string]$SlotKey) { $kept.Add($entry) }
                    }
                    $job.slots = $kept.ToArray()
                    Save-MeshJobData $Shared $job
                }
                if ($openLeft -eq 0) {
                    $folder = ''
                    try { $folder = [string]$job.folder } catch {}
                    if (-not [string]::IsNullOrWhiteSpace($folder) -and (Test-Path -LiteralPath $folder)) {
                        try { Remove-Item -LiteralPath $folder -Recurse -Force -ErrorAction SilentlyContinue } catch {}
                        if (-not (Test-Path -LiteralPath $folder)) { $result.folderRemoved = $true }
                    }
                }
            }
            $result.ok = $true
            return $result
        } catch {
            $result.error = $_.Exception.Message
            return $result
        }
    }

    function Remove-MeshAppliedFileSets {
        # Nach erfolgreichem Einsetzen: je eingesetztem Slot des Jobs Datei +
        # Slot-Skript loeschen (der Job-Ordner faellt mit, wenn nichts mehr
        # wartet). Rueckgabe: Anzahl der aufgeraeumten Slots.
        param($Shared, [string]$JobId)
        $count = 0
        foreach ($slot in (Get-MeshSlotsBySession $Shared '' $JobId)) {
            $slotState = ''
            try { $slotState = [string]$slot.state } catch {}
            if ($slotState -ne 'applied') { continue }
            $cleanup = Remove-MeshSlotFiles $Shared ([string]$slot.slotKey) $false
            if ([bool]$cleanup.ok) { $count = $count + 1 }
        }
        Save-MeshRegistryFile $Shared
        return $count
    }

    function Update-MeshRegistryFromDropResult {
        # Ergebnis von mesh_drop verbuchen: stornierte Slots aus dem Register
        # nehmen und Dateien/Ordner aufraeumen. Steht kein Erfolg im Ergebnis,
        # bleibt der Slot ehrlich auf 'drop_failed' mit der ECHTEN Meldung.
        param($Shared, [string]$JobId, $ResultJson)
        $parsed = $null
        try { if (-not [string]::IsNullOrWhiteSpace([string]$ResultJson)) { $parsed = [string]$ResultJson | ConvertFrom-Json } } catch {}
        if ($null -eq $parsed) { return $false }
        $droppedKeys = New-Object System.Collections.Generic.List[string]
        try {
            foreach ($entry in @($parsed.dropped)) {
                if ($null -eq $entry) { continue }
                $key = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($key)) { continue }
                if (-not $droppedKeys.Contains($key)) { $droppedKeys.Add($key) }
            }
        } catch {}
        $failedMessage = ''
        try {
            foreach ($entry in @($parsed.failed)) {
                if ($null -eq $entry) { continue }
                if (-not [string]::IsNullOrWhiteSpace([string]$entry.error)) { $failedMessage = [string]$entry.error; break }
            }
        } catch {}
        foreach ($key in $droppedKeys) {
            [void](Remove-MeshSlotFiles $Shared $key $true)
        }
        if ($droppedKeys.Count -eq 0) {
            foreach ($slot in (Get-MeshSlotsBySession $Shared '' $JobId)) {
                $slotState = ''
                try { $slotState = [string]$slot.state } catch {}
                if ($slotState -ne 'dropping') { continue }
                Set-MeshSlotField $Shared ([string]$slot.slotKey) 'state' 'drop_failed'
                if (-not [string]::IsNullOrWhiteSpace($failedMessage)) { Set-MeshSlotField $Shared ([string]$slot.slotKey) 'error' $failedMessage }
            }
        }
        Save-MeshRegistryFile $Shared
        return ($droppedKeys.Count -gt 0)
    }
}

# ----------------------------------------------------------------------------
# Der Runner: EIN Python-Programm, das die Bridge schreibt und der Agent NICHT
# aendert. Er baut eine leere Szene, fuehrt den Modellteil aus, exportiert OBJ
# (Y up, trianguliert, Modifier angewandt) und zentriert exakt auf die
# Bounding-Box-Mitte - danach meldet er die gemessenen Zahlen.
# ----------------------------------------------------------------------------
$script:MeshRunnerTemplate = @'
# Arena Roblox Bridge - Mesh-Runner (Version 7.4.0)
# Dieses Programm gehoert der Bridge. Der Agent liefert nur den Modellteil
# (--script); der Runner macht Szene, Export, Zentrierung und Messung.
import json
import os
import sys

MARKER = "ARENA_MESH_STATS "

def arena_args():
    argv = list(sys.argv)
    if "--" in argv:
        argv = argv[argv.index("--") + 1:]
    else:
        argv = []
    parsed = {"script": "", "out": "", "slot": "mesh"}
    index = 0
    while index < len(argv):
        key = argv[index]
        if key in ("--script", "--out", "--slot") and index + 1 < len(argv):
            parsed[key[2:]] = argv[index + 1]
            index += 2
        else:
            index += 1
    return parsed

def arena_export(obj_path):
    errors = []
    try:
        bpy.ops.wm.obj_export(
            filepath=obj_path,
            export_selected_objects=False,
            apply_modifiers=True,
            export_materials=False,
            export_triangulated_mesh=True,
            export_uv=False,
            export_normals=True,
            forward_axis="NEGATIVE_Z",
            up_axis="Y",
        )
        return
    except TypeError as exc:
        errors.append("obj_export(TypeError): %s" % exc)
    except Exception as exc:
        errors.append("obj_export(%s): %s" % (type(exc).__name__, exc))
    try:
        bpy.ops.wm.obj_export(filepath=obj_path)
        return
    except Exception as exc:
        errors.append("obj_export(plain): %s" % exc)
    try:
        bpy.ops.export_scene.obj(filepath=obj_path, use_materials=False, axis_forward="-Z", axis_up="Y")
        return
    except Exception as exc:
        errors.append("export_scene.obj: %s" % exc)
    raise RuntimeError("Kein funktionierender OBJ-Exporter: " + " | ".join(errors))

def arena_measure_and_center(obj_path):
    vertices = []
    faces = []
    objects = 0
    with open(obj_path, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            if line.startswith("v "):
                parts = line.split()
                if len(parts) >= 4:
                    vertices.append((float(parts[1]), float(parts[2]), float(parts[3])))
            elif line.startswith("f "):
                parts = line.split()
                if len(parts) >= 4:
                    faces.append(len(parts) - 1)
            elif line.startswith("o "):
                objects += 1
    if not vertices:
        raise RuntimeError("Der Export enthielt keine Punkte.")
    min_x = min(v[0] for v in vertices)
    min_y = min(v[1] for v in vertices)
    min_z = min(v[2] for v in vertices)
    max_x = max(v[0] for v in vertices)
    max_y = max(v[1] for v in vertices)
    max_z = max(v[2] for v in vertices)
    center_x = (min_x + max_x) / 2.0
    center_y = (min_y + max_y) / 2.0
    center_z = (min_z + max_z) / 2.0
    if abs(center_x) > 1e-9 or abs(center_y) > 1e-9 or abs(center_z) > 1e-9:
        with open(obj_path, "r", encoding="utf-8", errors="replace") as handle:
            lines = handle.readlines()
        with open(obj_path, "w", encoding="utf-8", newline="\n") as handle:
            for line in lines:
                if line.startswith("v "):
                    parts = line.split()
                    if len(parts) >= 4:
                        x = float(parts[1]) - center_x
                        y = float(parts[2]) - center_y
                        z = float(parts[3]) - center_z
                        rest = " ".join(parts[4:])
                        if rest:
                            handle.write("v %.6f %.6f %.6f %s\n" % (x, y, z, rest))
                        else:
                            handle.write("v %.6f %.6f %.6f\n" % (x, y, z))
                        continue
                handle.write(line)
    triangles = sum(max(1, count - 2) for count in faces)
    return {
        "triangles": int(triangles),
        "faces": int(len(faces)),
        "vertices": int(len(vertices)),
        "objects": int(objects),
        "sizeStuds": {
            "x": round(max_x - min_x, 4),
            "y": round(max_y - min_y, 4),
            "z": round(max_z - min_z, 4),
        },
        "bytes": int(os.path.getsize(obj_path)),
    }

def main():
    options = arena_args()
    if not options["script"] or not options["out"]:
        raise RuntimeError("Runner braucht --script und --out.")
    import bpy  # erst hier laden: die Szene wird danach leer aufgebaut
    bpy.ops.wm.read_factory_settings(use_empty=True)
    source_path = options["script"]
    # Version 7.4.1: BOM-tolerant lesen. PowerShell 5.1 hatte die Datei in
    # 7.4.0 per Set-Content -Encoding UTF8 mit BOM geschrieben - Python
    # stoppte deshalb mit "SyntaxError: invalid non-printable character
    # U+FEFF" in Zeile 1. utf-8-sig UND der Strip unten fangen beides ab.
    with open(source_path, "r", encoding="utf-8-sig", errors="replace") as handle:
        source = handle.read()
    if source.startswith("\ufeff"):
        source = source[1:]
    namespace = {"__name__": "__arena_slot__", "__file__": source_path}
    exec(compile(source, source_path, "exec"), namespace)
    arena_export(options["out"])
    stats = arena_measure_and_center(options["out"])
    stats["slot"] = options["slot"]
    stats["ok"] = True
    print(MARKER + json.dumps(stats))
    print("ARENA_MESH_OK " + options["slot"])

main()
'@


# ----------------------------------------------------------------------------
# Schritt 4 in EINEM Hintergrund-Runspace (Version 7.4.1): suchen -> Version ->
# (bei Bedarf installieren) -> ECHTE Faehigkeitsprobe. Er laedt GENAU die eine
# Hilfs-Quelle ($Shared.BlenderToolsText) - in 7.4.0 fehlten den Runspaces die
# Helferfunktionen (Phantom-Funktionen), ihre Protokollzeilen verschwanden.
# NUR die Probe setzt ready; jeder Fehler endet ehrlich als failed.
# ----------------------------------------------------------------------------
$script:BridgeBlenderStepScript = {
    param($Shared)
    try { . ([scriptblock]::Create([string]$Shared.BlenderToolsText)) } catch {}
    try {
        # Zeitlimit Suchen/Pruefen: 180 s (das Gesamt-Gate im UI-Takt: 12 min).
        $searchStart = Get-Date
        Set-BlenderState -Shared $Shared -State 'searching' -Message 'Blender wird gesucht ...' -Percent 0
        $path = Get-BlenderPath -Shared $Shared
        $quick = $null
        if (-not [string]::IsNullOrWhiteSpace([string]$path)) { $quick = Test-BlenderQuick -Path $path }
        if (((Get-Date) - $searchStart).TotalSeconds -gt 180) {
            Set-BlenderState -Shared $Shared -State 'failed' -Detail 'Zeitlimit: Suchen/Pruefen brauchte laenger als 180 s.' -Message 'Blender konnte nicht rechtzeitig geprueft werden. Der Mesh-Bau ist AUS, alles andere laeuft normal.' -Enabled $false -Percent 0 -Probe 'failed' -GateResolved $true
            Write-BridgeLog -Shared $Shared -Text 'Blender-Schritt 4 im Zeitlimit (Suchen/Pruefen 180 s) beendet.'
            return
        }
        if (-not [string]::IsNullOrWhiteSpace([string]$path) -and $null -ne $quick -and [bool]$quick.ok) {
            Set-BlenderState -Shared $Shared -State 'probing' -Path ([string]$path) -Version ([string]$quick.version) -Source 'vorhanden' -Detail 'Vorhandene Blender-Installation gefunden - jetzt laeuft die echte Faehigkeitsprobe.' -Message ('Blender ' + [string]$quick.version + ' wird geprueft ...') -Percent 0
            Write-BridgeLog -Shared $Shared -Text ('Blender gefunden: ' + [string]$path + ' (Version ' + [string]$quick.version + ') - Faehigkeitsprobe startet.')
            & ([scriptblock]::Create([string]$Shared.BlenderProbeScriptText)) $Shared
            return
        }
        if (-not [string]::IsNullOrWhiteSpace([string]$path)) {
            $quickError = 'unbekannt'
            if ($null -ne $quick) { $quickError = [string]$quick.error }
            Set-BlenderState -Shared $Shared -State 'missing' -Path ([string]$path) -Detail ('Gefundene Datei ist unbrauchbar: ' + $quickError) -Message 'Die gefundene Blender-Datei ist unbrauchbar - es wird die offizielle portable Version geladen.' -Percent 0 -Source 'vorhanden'
            Write-BridgeLog -Shared $Shared -Text ('Blender gefunden, aber unbrauchbar: ' + $quickError)
        } else {
            Set-BlenderState -Shared $Shared -State 'missing' -Message 'Blender ist nicht installiert - die Bridge laedt die offizielle portable Version.' -Percent 0
            Write-BridgeLog -Shared $Shared -Text 'Blender wurde nicht gefunden - automatische Installation startet.'
        }
        $install = Install-BlenderPortableZip -Shared $Shared
        if (-not [bool]$install.ok) {
            Set-BlenderState -Shared $Shared -State 'failed' -Message 'Blender konnte nicht automatisch bereitgestellt werden. Der Mesh-Bau ist AUS - alles andere laeuft normal.' -Detail ([string]$install.error) -Enabled $false -Percent 0 -Probe 'failed' -GateResolved $true
            Write-BridgeLog -Shared $Shared -Text ('Blender-Schritt 4 gescheitert: ' + [string]$install.error)
            return
        }
        # WICHTIG (7.4.1): Der Installationsweg setzt KEIN ready - ready gibt es
        # nur nach der bestandenen Faehigkeitsprobe.
        Set-BlenderState -Shared $Shared -State 'probing' -Path ([string]$install.path) -Version ([string]$install.version) -Source 'download' -Message ('Blender ' + [string]$install.version + ' wird geprueft ...') -Percent 99
        & ([scriptblock]::Create([string]$Shared.BlenderProbeScriptText)) $Shared
    } catch {
        Set-BlenderState -Shared $Shared -State 'failed' -Detail ('Der Blender-Schritt 4 wurde abgebrochen: ' + $_.Exception.Message) -Message 'Blender ist nicht bereit - der Mesh-Bau bleibt AUS, alles andere laeuft normal.' -Enabled $false -Percent 0 -Probe 'failed' -GateResolved $true
        Write-BridgeLog -Shared $Shared -Text ('Blender-Schritt 4 abgebrochen: ' + $_.Exception.Message)
    }
}

# ----------------------------------------------------------------------------
# Die EINZIGE Faehigkeitsprobe (Version 7.4.1): beweist, dass Blender WIRKLICH
# ein OBJ erzeugen kann - mit demselben Runner wie der echte Bau, gemessen
# ueber die Markerzeile ARENA_MESH_STATS (Laenge EXAKT geprueft). Sie
# protokolliert SELBST in die runtime.log und faellt FAIL-CLOSED durch: ohne
# lesbare Messzeile wird sie NIE ready. Die zweite, tote Probe aus 7.4.0
# (Test-BlenderCapability) ist geloescht - es gab genau einen Aufrufer.
# ----------------------------------------------------------------------------
$script:BridgeBlenderProbeScript = {
    param($Shared)
    try { . ([scriptblock]::Create([string]$Shared.BlenderToolsText)) } catch {}
    try {
        $state = $Shared.BlenderState
        $path = ''
        try { $path = [string]$state.path } catch {}
        if ([string]::IsNullOrWhiteSpace($path)) {
            Write-BridgeLog -Shared $Shared -Text 'Blender-Faehigkeitsprobe ohne Pfad - sie wurde NICHT gestartet.'
            Set-BlenderState -Shared $Shared -State 'failed' -Detail 'Faehigkeitsprobe ohne Blender-Pfad gestartet.' -Message 'Blender ist nicht bereit - der Mesh-Bau bleibt AUS.' -Enabled $false -Probe 'failed' -GateResolved $true
            return
        }
        $probeRoot = Join-Path ([string]$Shared.MeshRoot) '_probe'
        $runnerPath = Join-Path $probeRoot 'runner.py'
        $slotPath = Join-Path $probeRoot 'probe.py'
        $objPath = Join-Path $probeRoot 'probe.obj'
        $slotCode = 'import bpy' + [Environment]::NewLine
        $slotCode = $slotCode + 'bpy.ops.mesh.primitive_cube_add(size=2.0)' + [Environment]::NewLine
        $slotCode = $slotCode + 'bpy.ops.mesh.primitive_uv_sphere_add(radius=0.6, location=(0.0, 0.0, 2.0))' + [Environment]::NewLine
        # BOM-FREI schreiben (sonst stirbt Python mit "SyntaxError: invalid
        # non-printable character U+FEFF" in Zeile 1 - der Live-Befund).
        $runnerWritten = Write-BridgeBomFreeFile -Path $runnerPath -Text ([string]$Shared.MeshRunnerText)
        $slotWritten = Write-BridgeBomFreeFile -Path $slotPath -Text $slotCode
        if (-not $runnerWritten -or -not $slotWritten) {
            Set-BlenderState -Shared $Shared -State 'failed' -Detail ('Probendateien konnten nicht geschrieben werden (' + $runnerPath + ').') -Message 'Blender ist nicht bereit - der Mesh-Bau bleibt AUS.' -Enabled $false -Probe 'failed' -GateResolved $true
            Write-BridgeLog -Shared $Shared -Text 'Blender-Faehigkeitsprobe: Probendateien konnten nicht BOM-frei geschrieben werden.'
            return
        }
        if (Test-Path -LiteralPath $objPath) { Remove-Item -LiteralPath $objPath -Force -ErrorAction SilentlyContinue }
        $arguments = '--background --factory-startup --python-exit-code 1 --python "' + $runnerPath + '" -- --script "' + $slotPath + '" --out "' + $objPath + '" --slot probe'
        $run = Invoke-BlenderProcess -Path $path -Arguments $arguments -TimeoutSeconds 120 -WorkingDirectory $probeRoot
        $combined = [string]$run.output
        $marker = 'ARENA_MESH_STATS '
        # Laenge EXAKT pruefen (der 7.4.0-Fehler war ein Zeichenversatz beim
        # Ausschneiden der Messzeile).
        if ($marker.Length -ne 17) {
            Set-BlenderState -Shared $Shared -State 'failed' -Detail ('Interner Fehler: Markerlaenge ' + [string]$marker.Length + ' statt 17.') -Message 'Blender ist nicht bereit - der Mesh-Bau bleibt AUS.' -Enabled $false -Probe 'failed' -GateResolved $true
            Write-BridgeLog -Shared $Shared -Text ('Blender-Faehigkeitsprobe: Markerlaenge ' + [string]$marker.Length + ' statt 17 - Abbruch.')
            return
        }
        $markerIndex = $combined.IndexOf($marker)
        if ($run.timedOut -or [int]$run.exitCode -ne 0 -or $markerIndex -lt 0 -or -not (Test-Path -LiteralPath $objPath)) {
            $tail = $combined.Trim()
            if ($tail.Length -gt 600) { $tail = $tail.Substring($tail.Length - 600) }
            Set-BlenderState -Shared $Shared -State 'failed' -Detail ('Faehigkeitsprobe fehlgeschlagen (Exit ' + [string]$run.exitCode + ', timeout=' + [string]$run.timedOut + '): ' + $tail) -Message 'Blender ist installiert, kann aber keine Meshes erzeugen - der Mesh-Bau bleibt AUS.' -Enabled $false -Probe 'failed' -Percent 0 -GateResolved $true
            Write-BridgeLog -Shared $Shared -Text ('Blender-Faehigkeitsprobe fehlgeschlagen (Exit ' + [string]$run.exitCode + ', timeout=' + [string]$run.timedOut + '): ' + $tail)
            return
        }
        $jsonText = $combined.Substring($markerIndex + $marker.Length)
        $lineEnd = $jsonText.IndexOfAny(@([char]10, [char]13))
        if ($lineEnd -ge 0) { $jsonText = $jsonText.Substring(0, $lineEnd) }
        $stats = $null
        try { $stats = $jsonText.Trim() | ConvertFrom-Json } catch {}
        # FAIL CLOSED: ohne lesbare Messzeile gilt die Probe als NICHT bestanden
        # (kein falscher Erfolg) - der Mesh-Bau bleibt aus.
        if ($null -eq $stats -or [string]::IsNullOrWhiteSpace([string]$jsonText) -or $null -eq $stats.triangles -or $null -eq $stats.bytes) {
            Set-BlenderState -Shared $Shared -State 'failed' -Detail ('Faehigkeitsprobe: Probenzeile nicht lesbar (' + [string]$jsonText + ')') -Message 'Blender ist installiert, kann aber keine Meshes erzeugen - der Mesh-Bau bleibt AUS.' -Enabled $false -Probe 'failed' -Percent 0 -GateResolved $true
            Write-BridgeLog -Shared $Shared -Text ('Blender-Faehigkeitsprobe lieferte keine lesbare Messzeile: ' + [string]$jsonText)
            return
        }
        Set-BlenderState -Shared $Shared -State 'ready' -Probe ('ok triangles=' + [string]$stats.triangles + ' bytes=' + [string]$stats.bytes) -Detail ('Faehigkeitsprobe bestanden: Blender hat im Hintergrund ein OBJ erzeugt (' + [string]$stats.triangles + ' Dreiecke, ' + [string]$stats.bytes + ' Bytes).') -Enabled $true -Percent 100 -Message ('Blender ' + [string]$state.version + ' ist bereit und geprueft.') -GateResolved $true
        Write-BridgeLog -Shared $Shared -Text ('Blender-Faehigkeitsprobe bestanden (' + [string]$stats.triangles + ' Dreiecke, ' + [string]$stats.bytes + ' Bytes).')
    } catch {
        try {
            $st = $Shared.BlenderState
            $st.probe = 'failed'
            $st.state = 'failed'
            $st.enabled = $false
            $st.gateResolved = $true
            $st.detail = ('Faehigkeitsprobe konnte nicht laufen: ' + $_.Exception.Message)
            $st.message = 'Blender ist nicht bereit - der Mesh-Bau bleibt AUS, alles andere laeuft normal.'
            $st.updatedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        } catch {}
        Write-BridgeLog -Shared $Shared -Text ('Blender-Faehigkeitsprobe abgebrochen: ' + $_.Exception.Message)
    }
}

# ----------------------------------------------------------------------------
# Der Mesh-Job-Worker: laeuft in einem eigenen Runspace, startet Blender je
# Slot, MISST die OBJ-Datei und aktualisiert Job + Register. Netzwerkzugriffe
# macht er nicht - Platzhalter und Asset-Ids macht die Oberflaeche.
# ----------------------------------------------------------------------------
$script:BridgeMeshJobScript = {
    param($Shared, [string]$JobId, [string]$ToolkitText)
    try { . ([scriptblock]::Create([string]$ToolkitText)) } catch {}
    function Write-JobLog {
        param([string]$Text)
        try {
            $jobNow = Get-MeshJobData $Shared $JobId
            if ($null -eq $jobNow) { return }
            [System.IO.File]::AppendAllText([string]$jobNow.logFile, ((Get-Date).ToString('u') + ' ' + $Text) + [Environment]::NewLine, (New-Object System.Text.UTF8Encoding($false)))
        } catch {}
    }
    $job = Get-MeshJobData $Shared $JobId
    if ($null -eq $job) { return }
    $job.state = 'running'
    Save-MeshJobData $Shared $job
    Write-JobLog ('Job ' + $JobId + ' gestartet: ' + [string]$job.modelName + ' (' + [string]$job.slots.Count + ' Slot(s))')
    Write-JobLog ('Blender: ' + [string]$job.blenderPath)
    $timeoutSeconds = 300
    try { if ([int]$job.timeoutSeconds -gt 0) { $timeoutSeconds = [int]$job.timeoutSeconds } } catch {}
    $anyMeasured = $false
    $anyFailed = $false
    $anyRejected = $false
    foreach ($slot in $job.slots) {
        $current = Get-MeshJobData $Shared $JobId
        if ($null -ne $current -and [bool]$current.cancelRequested) { break }
        try {
            Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'running'
            $current = Get-MeshJobData $Shared $JobId
            if ($null -ne $current) { $current.currentSlot = [string]$slot.name; Save-MeshJobData $Shared $current }
            $arguments = '--background --factory-startup --python-exit-code 1 --python "' + [string]$slot.runnerPath + '" -- --script "' + [string]$slot.scriptPath + '" --out "' + [string]$slot.objPath + '" --slot ' + [string]$slot.name
            Write-JobLog ('Slot ' + [string]$slot.name + ': Blender startet.')
            try { if (Test-Path -LiteralPath ([string]$slot.objPath)) { Remove-Item -LiteralPath ([string]$slot.objPath) -Force -ErrorAction SilentlyContinue } } catch {}
            $psi = [System.Diagnostics.ProcessStartInfo]::new()
            $psi.FileName = [string]$job.blenderPath
            $psi.Arguments = $arguments
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
            $psi.StandardErrorEncoding = [System.Text.Encoding]::UTF8
            $psi.WorkingDirectory = [string]$job.folder
            $process = [System.Diagnostics.Process]::new()
            $process.StartInfo = $psi
            [void]$process.Start()
            $current = Get-MeshJobData $Shared $JobId
            if ($null -ne $current) { $current.currentPid = [int]$process.Id; Save-MeshJobData $Shared $current }
            $outTask = $process.StandardOutput.ReadToEndAsync()
            $errTask = $process.StandardError.ReadToEndAsync()
            $timedOut = $false
            if (-not $process.WaitForExit($timeoutSeconds * 1000)) {
                $timedOut = $true
                try { $process.Kill() } catch {}
                try { [void]$process.WaitForExit(5000) } catch {}
            }
            $outText = ''
            try { if ($outTask.Wait(4000)) { $outText = [string]$outTask.Result } } catch {}
            $errText = ''
            try { if ($errTask.Wait(4000)) { $errText = [string]$errTask.Result } } catch {}
            $exitCode = -1
            try { $exitCode = [int]$process.ExitCode } catch {}
            try { $process.Dispose() } catch {}
            $combined = ($outText + [Environment]::NewLine + $errText).Trim()
            $current = Get-MeshJobData $Shared $JobId
            if ($null -ne $current) { $current.currentPid = 0; Save-MeshJobData $Shared $current }
            $logTail = $combined
            if ($logTail.Length -gt 1500) { $logTail = $logTail.Substring($logTail.Length - 1500) }
            Write-JobLog ('Slot ' + [string]$slot.name + ': Exit ' + [string]$exitCode + ' (timeout=' + [string]$timedOut + ')')
            if (-not [string]::IsNullOrWhiteSpace($logTail)) { Write-JobLog ('Slot ' + [string]$slot.name + ' Ausgabe: ' + $logTail) }
            $cancelledNow = $false
            $current = Get-MeshJobData $Shared $JobId
            if ($null -ne $current -and [bool]$current.cancelRequested) { $cancelledNow = $true }
            if ($cancelledNow) {
                Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'cancelled'
                Set-MeshSlotField $Shared ([string]$slot.key) 'error' 'Abgebrochen.'
                break
            }
            if ($timedOut) {
                Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'failed'
                Set-MeshSlotField $Shared ([string]$slot.key) 'error' ('Blender brauchte laenger als ' + [string]$timeoutSeconds + ' s und wurde beendet. Weniger Details oder ein groesseres timeoutSeconds benutzen.')
                $anyFailed = $true
                continue
            }
            if (-not (Test-Path -LiteralPath ([string]$slot.objPath))) {
                Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'failed'
                Set-MeshSlotField $Shared ([string]$slot.key) 'error' ('Blender hat keine OBJ-Datei erzeugt (Exit ' + [string]$exitCode + '). Siehe build-log.txt: ' + $logTail)
                $anyFailed = $true
                continue
            }
            $stats = Get-MeshObjStats $Shared ([string]$slot.objPath)
            if (-not $stats.ok) {
                Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'failed'
                Set-MeshSlotField $Shared ([string]$slot.key) 'error' ('Die OBJ-Datei ist unbrauchbar: ' + [string]$stats.error)
                $anyFailed = $true
                continue
            }
            foreach ($entry in $job.slots) {
                if ([string]$entry.key -eq [string]$slot.key) {
                    $entry.triangles = [int]$stats.triangles
                    $entry.size = $stats.size
                    $entry.state = 'measured'
                    $entry.finishedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
                }
            }
            Set-MeshSlotField $Shared ([string]$slot.key) 'triangles' ([int]$stats.triangles)
            Set-MeshSlotField $Shared ([string]$slot.key) 'size' $stats.size
            Set-MeshSlotField $Shared ([string]$slot.key) 'bytes' ([int64]$stats.bytes)
            Set-MeshSlotField $Shared ([string]$slot.key) 'vertices' ([int]$stats.vertices)
            Set-MeshSlotField $Shared ([string]$slot.key) 'faces' ([int]$stats.faces)
            if ([bool]$stats.overLimit) {
                Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'rejected'
                Set-MeshSlotField $Shared ([string]$slot.key) 'error' ('Roblox nimmt pro Mesh hoechstens ' + [string]$stats.limit + ' Dreiecke an - gemessen sind es ' + [string]$stats.triangles + '. Das Modell muss einfacher gebaut werden (Weniger Unterteilungen / Decimate / kleinere Slots).')
                $anyRejected = $true
            } else {
                Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'obj'
                Set-MeshSlotField $Shared ([string]$slot.key) 'error' ''
                $anyMeasured = $true
            }
            Write-JobLog ('Slot ' + [string]$slot.name + ': gemessen - ' + [string]$stats.triangles + ' Dreiecke, ' + [string]$stats.bytes + ' Bytes, Groesse ' + [string]$stats.size.x + ' x ' + [string]$stats.size.y + ' x ' + [string]$stats.size.z + ' Studs.')
            Save-MeshJobData $Shared $job
            Save-MeshRegistryFile $Shared
        } catch {
            Set-MeshSlotField $Shared ([string]$slot.key) 'state' 'failed'
            Set-MeshSlotField $Shared ([string]$slot.key) 'error' ('Bridge-Fehler beim Bau: ' + $_.Exception.Message)
            Write-JobLog ('Slot ' + [string]$slot.name + ' Fehler: ' + $_.Exception.Message)
            $anyFailed = $true
        }
    }
    $job = Get-MeshJobData $Shared $JobId
    if ($null -ne $job) {
        $cancelled = [bool]$job.cancelRequested
        if ($cancelled) { $job.state = 'cancelled' }
        elseif ($anyMeasured) { $job.state = 'measured' }
        else { $job.state = 'failed' }
        $job.currentPid = 0
        $job.currentSlot = ''
        $job.finishedAt = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        if ($job.state -eq 'failed') {
            if ($anyRejected) { $job.error = 'Alle Slots wurden von der Dreiecksgrenze abgelehnt.' }
            else { $job.error = 'Kein Slot hat eine brauchbare OBJ-Datei ergeben - siehe build-log.txt im Job-Ordner.' }
        }
        Save-MeshJobData $Shared $job
    }
    Save-MeshRegistryFile $Shared
    Write-JobLog ('Job ' + $JobId + ' beendet mit Zustand ' + [string]$job.state + '.')
}

# ----------------------------------------------------------------------------
# Alles, was Handler- und Worker-Runspaces brauchen, liegt in $Shared.
# ----------------------------------------------------------------------------
$script:Shared.MeshRoot = [string]$script:MeshRoot
$script:Shared.BlenderFolder = [string]$script:BlenderFolder
$script:Shared.BlenderStatusFile = [string]$script:BlenderStatusFile
$script:Shared.MeshRegistryPath = [string]$script:MeshRegistryFile
$script:Shared.MeshRunnerText = [string]$script:MeshRunnerTemplate
$script:Shared.MeshToolkitText = [string]$script:BridgeMeshToolkit
$script:Shared.MeshJobScriptText = [string]$script:BridgeMeshJobScript
$script:Shared.BlenderToolsText = [string]$script:BridgeBlenderTools
$script:Shared.BlenderStepScriptText = [string]$script:BridgeBlenderStepScript
$script:Shared.BlenderProbeScriptText = [string]$script:BridgeBlenderProbeScript
$script:Shared.LocalPort = [int]$script:Port
$script:Shared.LocalBaseUrl = [string]$script:LocalBaseUrl
$script:Shared.MeshRootFolder = [string]$script:AppDataRoot
try {
    if (-not (Test-Path -LiteralPath $script:MeshRoot)) { [void](New-Item -ItemType Directory -Path $script:MeshRoot -Force) }
    if (-not (Test-Path -LiteralPath $script:BlenderFolder)) { [void](New-Item -ItemType Directory -Path $script:BlenderFolder -Force) }
} catch { }

# ----------------------------------------------------------------------------
# Version 7.4.0: MESH-TAKT und MESH-FENSTER
# Der Toolkit-Text liegt in $Shared, damit auch der Handler-Runspace ihn
# benutzen kann. Fuer die Oberflaeche wird er hier EINMAL geladen - so gibt es
# genau eine Quelle fuer Queue-Anmeldung, Registerpflege und Messung.
# ----------------------------------------------------------------------------
try { . ([scriptblock]::Create([string]$script:BridgeMeshToolkit)) } catch { Write-RuntimeLog ('Mesh-Werkzeuge konnten nicht geladen werden: ' + $_.Exception.Message) }

$script:MeshWindow = $null
$script:MeshWindowRows = @{}
$script:MeshWindowNotice = ''
# Version 7.4.1: Wartemenge beim Schliessen (sortierte Slot-Keys) - das Fenster
# geht erst wieder auf, wenn sich diese Menge aendert (keine Schleife).
$script:MeshAutoClosedSignature = ''

function Update-MeshTick {
    # Laeuft im UI-Takt (kein zusaetzlicher Timer). Holt Ergebnisse interner
    # Mesh-Befehle ab, legt nach der Messung die Platzhalter an und pflegt das
    # Register. Kein Netzwerkzugriff, keine Annahmen: steht keine Antwort da,
    # passiert nichts.
    try {
        $map = $script:Shared.MeshInternal
        foreach ($pair in @($map.GetEnumerator())) {
            $key = [string]$pair.Key
            if (-not $key.StartsWith('cmd:')) { continue }
            $commandId = $key.Substring(4)
            $tag = [string]$pair.Value
            $outcome = Get-MeshCommandOutcome $script:Shared $commandId
            $state = [string]$outcome.state
            if ($state -eq 'pending' -or $state -eq 'invalid') { continue }
            $discard = $null
            [void]$map.TryRemove($key, [ref]$discard)
            if ($tag.StartsWith('placeholders:')) {
                $jobId = $tag.Substring(13)
                if ($state -eq 'done') {
                    Update-MeshRegistryFromPlaceholderResult $script:Shared $jobId ([string]$outcome.json)
                } else {
                    $job = Get-MeshJobData $script:Shared $jobId
                    if ($null -ne $job) {
                        $job.placeholderState = 'failed'
                        $job.error = [string]$outcome.message
                        Save-MeshJobData $script:Shared $job
                    }
                }
                continue
            }
            if ($tag.StartsWith('apply:')) {
                $jobId = $tag.Substring(6)
                if ($state -eq 'done') {
                    $appliedOk = $false
                    try { $appliedOk = [bool](Update-MeshRegistryFromApplyResult $script:Shared ([string]$outcome.json)) } catch {}
                    if ($appliedOk) {
                        # Version 7.4.1: Dateimuell vermeiden - OBJ + Slot-Skript
                        # loeschen, den Job-Ordner nur, wenn nichts mehr wartet.
                        $cleaned = 0
                        try { $cleaned = [int](Remove-MeshAppliedFileSets $script:Shared $jobId) } catch {}
                        Write-RuntimeLog ('Eingesetzte Mesh-Dateien geloescht (' + [string]$cleaned + ' Slot(s), Job ' + $jobId + ').')
                        $script:MeshWindowNotice = 'Eingesetzte Mesh-Dateien geloescht - der MeshPart ist jetzt das echte Mesh.'
                    } else {
                        $script:MeshWindowNotice = 'Das Einsetzen hat nicht geklappt - die Zeile zeigt den echten Fehler.'
                    }
                } else {
                    $failedNow = 0
                    foreach ($slot in (Get-MeshSlotsBySession $script:Shared '' $jobId)) {
                        if ([string]$slot.state -ne 'applying') { continue }
                        $pending = ''
                        try { $pending = [string]$slot.pendingCommandId } catch {}
                        if ($pending -eq $commandId -or [string]::IsNullOrWhiteSpace($pending)) {
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'state' 'apply_failed'
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'error' ([string]$outcome.message)
                            $failedNow = $failedNow + 1
                        }
                    }
                    if ($failedNow -gt 0) { $script:MeshWindowNotice = 'Einsetzen fehlgeschlagen: ' + [string]$outcome.message }
                    Save-MeshRegistryFile $script:Shared
                }
                continue
            }
            if ($tag.StartsWith('drop:')) {
                $jobId = $tag.Substring(5)
                if ($state -eq 'done') {
                    $droppedOk = $false
                    try { $droppedOk = [bool](Update-MeshRegistryFromDropResult $script:Shared $jobId ([string]$outcome.json)) } catch {}
                    if ($droppedOk) {
                        Write-RuntimeLog ('Mesh-Slot storniert (' + $jobId + '): Platzhalter und Dateien sind entfernt.')
                        $script:MeshWindowNotice = 'Mesh-Slot storniert - Platzhalter und Dateien sind weg.'
                    } else {
                        $script:MeshWindowNotice = 'Stornieren hat nicht geklappt - die Zeile zeigt den echten Fehler.'
                    }
                } else {
                    $failedNow = 0
                    foreach ($slot in (Get-MeshSlotsBySession $script:Shared '' $jobId)) {
                        if ([string]$slot.state -ne 'dropping') { continue }
                        $pending = ''
                        try { $pending = [string]$slot.pendingCommandId } catch {}
                        if ($pending -eq $commandId -or [string]::IsNullOrWhiteSpace($pending)) {
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'state' 'drop_failed'
                            Set-MeshSlotField $script:Shared ([string]$slot.slotKey) 'error' ([string]$outcome.message)
                            $failedNow = $failedNow + 1
                        }
                    }
                    if ($failedNow -gt 0) { $script:MeshWindowNotice = 'Stornieren fehlgeschlagen: ' + [string]$outcome.message }
                    Save-MeshRegistryFile $script:Shared
                }
                continue
            }
            Write-RuntimeLog ('Mesh-Befehl ohne Zuordnung beendet: ' + $tag)
        }

        # Nach der Messung: Platzhalter automatisch anlegen lassen.
        foreach ($jobPair in @($script:Shared.MeshJobs.GetEnumerator())) {
            $job = Get-MeshJobData $script:Shared ([string]$jobPair.Key)
            if ($null -eq $job) { continue }
            if ([string]$job.state -ne 'measured') { continue }
            if ([bool]$job.placeholdersCreated) { continue }
            if (-not [string]::IsNullOrWhiteSpace([string]$job.placeholderCommandId)) { continue }
            if ([string]::IsNullOrWhiteSpace([string]$job.sessionId)) { continue }
            $open = $false
            $ready = 0
            foreach ($slot in (Get-MeshSlotsBySession $script:Shared ([string]$job.sessionId) ([string]$job.id))) {
                $slotState = [string]$slot.state
                if ($slotState -in @('pending', 'running', 'script', 'measured')) { $open = $true }
                if ($slotState -eq 'obj' -or $slotState -eq 'applied') { $ready = $ready + 1 }
            }
            if ($open -or $ready -eq 0) { continue }
            $sent = Send-MeshPlaceholders $script:Shared ([string]$job.id)
            if (-not [string]::IsNullOrWhiteSpace($sent)) {
                Write-RuntimeLog ('Mesh-Platzhalter beauftragt: Job ' + [string]$job.id + ', ' + [string]$ready + ' Slot(s), commandId=' + $sent)
            }
        }
    } catch {
        try { Write-RuntimeLog ('Mesh-Takt Fehler: ' + $_.Exception.Message) } catch {}
    }
}

# ----------------------------------------------------------------------------
# Version 7.4.0: FENSTER "MESH-UPLOADS"
# Der Nutzer laedt die OBJ-Dateien selbst in Roblox hoch (Roblox hat keine
# API fuer Mesh-Uploads) und traegt die Mesh-Ids hier ein. Die Bridge setzt
# die Geometrie danach automatisch in die bestehenden Platzhalter.
# Aufbau und Design sind aus dem Nachrichtenfenster uebernommen (anthrazit,
# verschiebbare Titelleiste, X oben rechts); das Fenster ist modal wie die
# beiden anderen erlaubten Fenster und arbeitet ohne Toast.
# ----------------------------------------------------------------------------
function Get-MeshWindowXaml {
    # Version 7.4.1: EINFACHES, automatisches Mesh-Fenster. Es oeffnet sich von
    # selbst (modellos, Show()) sobald eine OBJ-Datei auf den Upload wartet -
    # es gibt KEINEN Menueeintrag mehr. Der Blender-Zustand steht im
    # Startbildschirm und in blender_status, nicht in diesem Fenster.
    $template = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Mesh-Uploads"
        Width="680" Height="540" MinWidth="580" MinHeight="420"
        ResizeMode="CanResize" WindowStyle="None" AllowsTransparency="True"
        Background="Transparent" WindowStartupLocation="CenterOwner"
        ShowInTaskbar="False" FontFamily="Segoe UI"
        UseLayoutRounding="True" SnapsToDevicePixels="True"
        TextOptions.TextFormattingMode="Display">
    <Window.Resources>
<!--ARENA_DIALOG_STYLES-->
    </Window.Resources>
    <Border CornerRadius="20" Background="{StaticResource SwAppBg}"
            BorderBrush="#33FFFFFF" BorderThickness="1" ClipToBounds="True">
        <Grid>
            <Grid IsHitTestVisible="False">
                <Ellipse Width="420" Height="420" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="-150,-190,0,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#407B5CFF" Offset="0"/>
                            <GradientStop Color="#007B5CFF" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                </Ellipse>
                <Ellipse Width="360" Height="360" HorizontalAlignment="Right" VerticalAlignment="Bottom" Margin="0,0,-120,-140">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#2EFF5C8A" Offset="0"/>
                            <GradientStop Color="#00FF5C8A" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                </Ellipse>
            </Grid>

            <Grid Margin="22">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- Titelzeile: ziehbar, Kreuz oben rechts, Place-Name darunter. -->
                <Grid x:Name="TitleBar" Grid.Row="0" Background="Transparent" Cursor="SizeAll">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="Mesh-Uploads" Foreground="{StaticResource SwTextMain}"
                                   FontSize="16" FontWeight="Bold"/>
                        <TextBlock x:Name="PlaceNameText" Text="Place" Foreground="{StaticResource SwTextFaint}"
                                   FontSize="10.5" Margin="0,2,0,0" TextTrimming="CharacterEllipsis"/>
                    </StackPanel>
                    <Button x:Name="CloseButton" Grid.Column="1" Style="{StaticResource ArenaCloseButton}"
                            Content="&#xE8BB;" FontFamily="Segoe MDL2 Assets" FontSize="11"
                            ToolTip="Schließen (Esc)"/>
                </Grid>

                <StackPanel Grid.Row="1" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,12,0,0">
                    <Button x:Name="FolderButton" Content="Ordner öffnen" MinWidth="130" MinHeight="28"
                            Padding="12,4" Style="{StaticResource ArenaQuietButton}"
                            ToolTip="Den Mesh-/Job-Ordner im Explorer öffnen"/>
                </StackPanel>

                <!-- EINE Liste: je Mesh eine Zeile. -->
                <Border Grid.Row="2" Margin="0,12,0,0" Background="{StaticResource SwCardBg}" BorderBrush="#2EFFFFFF"
                        BorderThickness="1" CornerRadius="10" Padding="10,8">
                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel x:Name="SlotList"/>
                    </ScrollViewer>
                </Border>

                <Border x:Name="StatusBorder" Grid.Row="3" Margin="0,12,0,0"
                        Background="{StaticResource SwCardBg}" BorderBrush="#2EFFFFFF"
                        BorderThickness="1" CornerRadius="10" Padding="11,8">
                    <TextBlock x:Name="StatusText" Text="Keine Mesh-Datei wartet auf den Upload."
                               Foreground="{StaticResource SwTextMuted}" FontSize="11" TextWrapping="Wrap"/>
                </Border>
            </Grid>
        </Grid>
    </Border>
</Window>
'@
    return $template.Replace('<!--ARENA_DIALOG_STYLES-->', [string]$script:ArenaDialogStyles)
}

function Get-MeshSlotStateText {
    param($Slot)
    $state = ''
    $errorText = ''
    $triangles = 0
    try { $state = [string]$Slot.state } catch {}
    try { $errorText = [string]$Slot.error } catch {}
    try { $triangles = [int]$Slot.triangles } catch {}
    $text = ''
    switch ($state) {
        'pending' { $text = 'Wartet auf Blender …' }
        'running' { $text = 'Blender baut …' }
        'script' { $text = 'Blender baut …' }
        'measured' { $text = 'Wird gemessen …' }
        'obj' { $text = 'Datei fertig - bitte in Roblox hochladen und die Mesh-Id eintragen' }
        'rejected' { $text = 'Zu viele Dreiecke (' + [string]$triangles + ') - einfacher bauen' }
        'applying' { $text = 'Wird in den Place gesetzt …' }
        'applied' { $text = 'Eingesetzt' }
        'apply_failed' { $text = 'Einsetzen fehlgeschlagen' }
        'dropping' { $text = 'Wird storniert …' }
        'drop_failed' { $text = 'Stornieren fehlgeschlagen' }
        'failed' { $text = 'Bau fehlgeschlagen' }
        'cancelled' { $text = 'Abgebrochen' }
        default { $text = $state }
    }
    if (-not [string]::IsNullOrWhiteSpace($errorText)) { $text = $text + ' - ' + $errorText }
    return $text
}

function Get-MeshWindowPlaceLabel {
    # Place-Name aus dem ersten wartenden Slot (die Zeile im Fenster soll
    # sagen, WO die Datei hochgeladen werden muss).
    $label = 'Verbundenes Place'
    try {
        foreach ($pair in @($script:Shared.MeshRegistry.GetEnumerator())) {
            $slot = $null
            try { $slot = ($pair.Value | ConvertFrom-Json) } catch { continue }
            if ($null -eq $slot) { continue }
            $slotState = ''
            try { $slotState = [string]$slot.state } catch {}
            if ($slotState -ne 'obj') { continue }
            $sid = ''
            try { $sid = [string]$slot.sessionId } catch {}
            if ([string]::IsNullOrWhiteSpace($sid)) { continue }
            $name = ''
            try { $name = [string]$script:PlaceNames[$sid] } catch {}
            if ([string]::IsNullOrWhiteSpace($name)) { $name = $sid }
            return ('Place · ' + $name)
        }
    } catch {}
    return $label
}

function New-MeshRow {
    # EINE Zeile je Mesh: Name (model · slot), Info (Datei/Dreiecke/Studs),
    # Zustand (farbig), Id-Feld, "Fertig", "Stornieren" - und die Rueckfrage
    # in der Zeile ("Wirklich stornieren?" mit "Ja, stornieren"/"Abbrechen").
    param($Slot)
    $win = $script:MeshWindow
    $shell = [System.Windows.Controls.Border]::new()
    $shell.Background = Get-Brush '#14FFFFFF'
    $shell.BorderBrush = Get-Brush '#1FFFFFFF'
    $shell.BorderThickness = [System.Windows.Thickness]::new(1)
    $shell.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $shell.Padding = [System.Windows.Thickness]::new(10, 8, 10, 8)
    $shell.Margin = [System.Windows.Thickness]::new(0, 0, 0, 8)
    $stack = [System.Windows.Controls.StackPanel]::new()
    $title = [System.Windows.Controls.TextBlock]::new()
    $title.Foreground = Get-Brush '#F4F8FF'
    $title.FontSize = 12
    $title.FontWeight = 'Bold'
    $file = [System.Windows.Controls.TextBlock]::new()
    $file.Foreground = Get-Brush '#9AA9CE'
    $file.FontSize = 10.5
    $file.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)
    $stateText = [System.Windows.Controls.TextBlock]::new()
    $stateText.Foreground = Get-Brush '#FFD9A0'
    $stateText.FontSize = 10.5
    $stateText.TextWrapping = 'Wrap'
    $stateText.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)

    $actionPanel = [System.Windows.Controls.Grid]::new()
    $actionPanel.Margin = [System.Windows.Thickness]::new(0, 7, 0, 0)
    $col1 = [System.Windows.Controls.ColumnDefinition]::new()
    $col1.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    $col2 = [System.Windows.Controls.ColumnDefinition]::new()
    $col2.Width = [System.Windows.GridLength]::new(0, [System.Windows.GridUnitType]::Auto)
    $col3 = [System.Windows.Controls.ColumnDefinition]::new()
    $col3.Width = [System.Windows.GridLength]::new(0, [System.Windows.GridUnitType]::Auto)
    [void]$actionPanel.ColumnDefinitions.Add($col1)
    [void]$actionPanel.ColumnDefinitions.Add($col2)
    [void]$actionPanel.ColumnDefinitions.Add($col3)
    $idBox = [System.Windows.Controls.TextBox]::new()
    $idBox.MinHeight = 28
    $idBox.MaxLength = 32
    $idBox.Foreground = Get-Brush '#F4F8FF'
    $idBox.ToolTip = 'Mesh-Id aus Roblox - nur die Ziffern'
    $idBox.Style = $win.FindResource('ArenaTextField')
    [System.Windows.Controls.Grid]::SetColumn($idBox, 0)
    $doneButton = [System.Windows.Controls.Button]::new()
    $doneButton.Content = 'Fertig'
    $doneButton.MinWidth = 92
    $doneButton.MinHeight = 28
    $doneButton.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
    $doneButton.Style = $win.FindResource('ArenaPrimaryButton')
    [System.Windows.Controls.Grid]::SetColumn($doneButton, 1)
    $cancelButton = [System.Windows.Controls.Button]::new()
    $cancelButton.Content = 'Stornieren'
    $cancelButton.MinWidth = 104
    $cancelButton.MinHeight = 28
    $cancelButton.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
    $cancelButton.Style = $win.FindResource('ArenaDangerButton')
    [System.Windows.Controls.Grid]::SetColumn($cancelButton, 2)
    [void]$actionPanel.Children.Add($idBox)
    [void]$actionPanel.Children.Add($doneButton)
    [void]$actionPanel.Children.Add($cancelButton)

    $askPanel = [System.Windows.Controls.StackPanel]::new()
    $askPanel.Margin = [System.Windows.Thickness]::new(0, 7, 0, 0)
    $askPanel.Visibility = 'Collapsed'
    $askText = [System.Windows.Controls.TextBlock]::new()
    $askText.Text = 'Wirklich stornieren? Der MeshPart wird aus dem Place entfernt; ein schon eingesetztes Mesh wird NICHT wiederhergestellt.'
    $askText.Foreground = Get-Brush '#FFD9A0'
    $askText.FontSize = 10.5
    $askText.TextWrapping = 'Wrap'
    $askButtons = [System.Windows.Controls.StackPanel]::new()
    $askButtons.Orientation = 'Horizontal'
    $askButtons.Margin = [System.Windows.Thickness]::new(0, 6, 0, 0)
    $yesButton = [System.Windows.Controls.Button]::new()
    $yesButton.Content = 'Ja, stornieren'
    $yesButton.MinWidth = 118
    $yesButton.MinHeight = 28
    $yesButton.Style = $win.FindResource('ArenaDangerButton')
    $noButton = [System.Windows.Controls.Button]::new()
    $noButton.Content = 'Abbrechen'
    $noButton.MinWidth = 104
    $noButton.MinHeight = 28
    $noButton.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
    $noButton.Style = $win.FindResource('ArenaQuietButton')
    [void]$askButtons.Children.Add($yesButton)
    [void]$askButtons.Children.Add($noButton)
    [void]$askPanel.Children.Add($askText)
    [void]$askPanel.Children.Add($askButtons)

    [void]$stack.Children.Add($title)
    [void]$stack.Children.Add($file)
    [void]$stack.Children.Add($stateText)
    [void]$stack.Children.Add($actionPanel)
    [void]$stack.Children.Add($askPanel)
    $shell.Child = $stack

    $rowTag = [pscustomobject]@{
        SlotKey      = [string]$Slot.slotKey
        Title        = $title
        FileText     = $file
        StateText    = $stateText
        IdBox        = $idBox
        DoneButton   = $doneButton
        CancelButton = $cancelButton
        ActionPanel  = $actionPanel
        AskPanel     = $askPanel
    }
    $shell.Tag = $rowTag
    $doneButton.Tag = $rowTag
    $cancelButton.Tag = $rowTag
    $yesButton.Tag = $rowTag
    $noButton.Tag = $rowTag
    $doneButton.Add_Click({
        param($s, $e)
        try { Invoke-MeshRowApply -Row $s.Tag } catch { try { Write-UiErrorLog 'Mesh-Zeile Fertig' $_ } catch {} }
    })
    $cancelButton.Add_Click({
        param($s, $e)
        try { Show-MeshRowAsk -Row $s.Tag } catch {}
    })
    $yesButton.Add_Click({
        param($s, $e)
        try { Invoke-MeshRowDrop -Row $s.Tag } catch { try { Write-UiErrorLog 'Mesh-Zeile Stornieren' $_ } catch {} }
    })
    $noButton.Add_Click({
        param($s, $e)
        try { Hide-MeshRowAsk -Row $s.Tag } catch {}
    })
    return $shell
}

function Show-MeshRowAsk {
    # Rueckfrage IN der Zeile (kein Fenster, kein Popup, kein Toast).
    param($Row)
    try { $Row.ActionPanel.Visibility = 'Collapsed' } catch {}
    try { $Row.AskPanel.Visibility = 'Visible' } catch {}
}

function Hide-MeshRowAsk {
    param($Row)
    try { $Row.AskPanel.Visibility = 'Collapsed' } catch {}
    try { $Row.ActionPanel.Visibility = 'Visible' } catch {}
}

function Invoke-MeshRowApply {
    # "Fertig": Id pruefen (NUR Ziffern) -> Zustand applying -> interner Befehl
    # mesh_apply an Studio. Das Ergebnis holt der UI-Takt ab; erst dann wird
    # aufgeraeumt und gemeldet - kein falscher Erfolg.
    param($Row)
    if ($null -eq $Row) { return }
    $slotKey = [string]$Row.SlotKey
    $raw = ''
    try { $raw = ([string]$Row.IdBox.Text).Trim() } catch {}
    if ($raw -notmatch '^\d+$') {
        $script:MeshWindowNotice = 'Bitte nur die Ziffern der Mesh-Id eintragen (keine Buchstaben, kein rbxassetid://).'
        return
    }
    $slot = Get-MeshSlotData $script:Shared $slotKey
    if ($null -eq $slot) {
        $script:MeshWindowNotice = 'Dieser Slot steht nicht mehr im Register - die Zeile verschwindet beim naechsten Takt.'
        return
    }
    try { $Row.IdBox.IsEnabled = $false } catch {}
    Set-MeshSlotField $script:Shared $slotKey 'assetId' $raw
    Set-MeshSlotField $script:Shared $slotKey 'state' 'applying'
    Set-MeshSlotField $script:Shared $slotKey 'error' ''
    $jobId = ''
    try { $jobId = [string]$slot.jobId } catch {}
    $sessionId = ''
    try { $sessionId = [string]$slot.sessionId } catch {}
    $commandId = New-MeshBridgeCommand -Shared $script:Shared -SessionId $sessionId -Tool 'mesh_apply' -ToolArgs @{ slots = @(@{ key = $slotKey; assetId = $raw }) } -BudgetSeconds 180 -Tag ('apply:' + $jobId)
    if ([string]::IsNullOrWhiteSpace($commandId)) {
        Set-MeshSlotField $script:Shared $slotKey 'state' 'apply_failed'
        Set-MeshSlotField $script:Shared $slotKey 'error' 'Die Bridge konnte den Befehl nicht einreihen - ist Roblox Studio mit diesem Place verbunden?'
        $script:MeshWindowNotice = 'Der Befehl konnte nicht an Studio geschickt werden.'
        try { $Row.IdBox.IsEnabled = $true } catch {}
        return
    }
    Set-MeshSlotField $script:Shared $slotKey 'pendingCommandId' $commandId
    $script:MeshWindowNotice = ('Mesh-Id ' + $raw + ' wird eingesetzt - Roblox laedt die Geometrie aus der Cloud.')
}

function Invoke-MeshRowDrop {
    # "Stornieren" (nach der Rueckfrage): internen Befehl mesh_drop senden. Er
    # loescht die MeshParts mit ArenaMeshSlot = key aus dem Place - ein schon
    # eingesetztes Mesh wird NICHT wiederhergestellt. Danach raeumt der
    # UI-Takt Slot + Dateien auf.
    param($Row)
    if ($null -eq $Row) { return }
    $slotKey = [string]$Row.SlotKey
    $slot = Get-MeshSlotData $script:Shared $slotKey
    if ($null -eq $slot) {
        $script:MeshWindowNotice = 'Dieser Slot steht nicht mehr im Register.'
        Hide-MeshRowAsk -Row $Row
        return
    }
    $jobId = ''
    try { $jobId = [string]$slot.jobId } catch {}
    $sessionId = ''
    try { $sessionId = [string]$slot.sessionId } catch {}
    Set-MeshSlotField $script:Shared $slotKey 'state' 'dropping'
    Set-MeshSlotField $script:Shared $slotKey 'error' ''
    $commandId = New-MeshBridgeCommand -Shared $script:Shared -SessionId $sessionId -Tool 'mesh_drop' -ToolArgs @{ slots = @(@{ key = $slotKey }) } -BudgetSeconds 150 -Tag ('drop:' + $jobId)
    if ([string]::IsNullOrWhiteSpace($commandId)) {
        Set-MeshSlotField $script:Shared $slotKey 'state' 'drop_failed'
        Set-MeshSlotField $script:Shared $slotKey 'error' 'Die Bridge konnte den Befehl nicht einreihen - ist Roblox Studio mit diesem Place verbunden?'
        $script:MeshWindowNotice = 'Stornieren konnte nicht an Studio geschickt werden.'
        Hide-MeshRowAsk -Row $Row
        return
    }
    Set-MeshSlotField $script:Shared $slotKey 'pendingCommandId' $commandId
    $script:MeshWindowNotice = 'Stornieren laeuft - der MeshPart wird entfernt; ein schon eingesetztes Mesh kommt NICHT zurueck.'
    Hide-MeshRowAsk -Row $Row
}

function Update-MeshWindow {
    # Aktualisiert das offene Fenster: je wartendem/gesetztem Mesh EINE Zeile,
    # EINE Statuszeile. Zeilen werden nur ergaenzt/entfernt - die Eingaben des
    # Nutzers (Id-Feld, Rueckfrage) werden nie ueberschrieben.
    if ($null -eq $script:MeshWindow) { return }
    $win = $script:MeshWindow
    try {
        $rows = New-Object System.Collections.Generic.List[object]
        foreach ($pair in @($script:Shared.MeshRegistry.GetEnumerator())) {
            $slot = $null
            try { $slot = ($pair.Value | ConvertFrom-Json) } catch { continue }
            if ($null -eq $slot) { continue }
            $slotState = ''
            try { $slotState = [string]$slot.state } catch {}
            if ($slotState -notin @('obj', 'applying', 'applied', 'apply_failed', 'dropping', 'drop_failed')) { continue }
            $rows.Add($slot)
        }

        $slotList = $win.FindName('SlotList')
        $keyed = @{}
        if ($null -ne $slotList) {
            foreach ($child in @($slotList.Children)) {
                $childKey = ''
                try { $childKey = [string]$child.Tag.SlotKey } catch {}
                if (-not [string]::IsNullOrWhiteSpace($childKey)) { $keyed[$childKey] = $child }
            }
        }
        $rowsByKey = @{}
        foreach ($slot in $rows) {
            $slotKey = ''
            try { $slotKey = [string]$slot.slotKey } catch {}
            if ([string]::IsNullOrWhiteSpace($slotKey)) { continue }
            $rowsByKey[$slotKey] = $slot
        }
        foreach ($knownKey in @($keyed.Keys)) {
            if (-not $rowsByKey.ContainsKey([string]$knownKey)) {
                try { [void]$slotList.Children.Remove($keyed[$knownKey]) } catch {}
                $keyed.Remove($knownKey)
            }
        }

        $openCount = 0
        $appliedCount = 0
        $failedCount = 0
        foreach ($slot in $rows) {
            $slotKey = ''
            try { $slotKey = [string]$slot.slotKey } catch {}
            if ([string]::IsNullOrWhiteSpace($slotKey)) { continue }
            if (-not $keyed.ContainsKey($slotKey)) {
                if ($null -eq $slotList) { continue }
                $keyed[$slotKey] = New-MeshRow -Slot $slot
                [void]$slotList.Children.Add($keyed[$slotKey])
            }
            $shell = $keyed[$slotKey]
            $slotState = ''
            try { $slotState = [string]$slot.state } catch {}
            try { $shell.Tag.Title.Text = ([string]$slot.modelName + ' · ' + [string]$slot.slotName) } catch {}
            $fileLine = 'Datei: ' + [string]$slot.fileName
            try {
                if ([int]$slot.triangles -gt 0) { $fileLine = $fileLine + '  |  ' + [string]$slot.triangles + ' Dreiecke' }
            } catch {}
            try {
                if ($null -ne $slot.size) {
                    $fileLine = $fileLine + '  |  ' + ([string]([Math]::Round([double]$slot.size.x, 2))) + ' x ' + ([string]([Math]::Round([double]$slot.size.y, 2))) + ' x ' + ([string]([Math]::Round([double]$slot.size.z, 2))) + ' Studs'
                }
            } catch {}
            try { $shell.Tag.FileText.Text = $fileLine } catch {}
            try { $shell.Tag.StateText.Text = (Get-MeshSlotStateText $slot) } catch {}
            $currentColor = '#FFD9A0'
            if ($slotState -eq 'applied') { $currentColor = '#9AD9AE' }
            elseif ($slotState -in @('failed', 'rejected', 'apply_failed', 'drop_failed')) { $currentColor = '#FF8AA0' }
            elseif ($slotState -eq 'obj') { $currentColor = '#FFD9A0' }
            elseif ($slotState -eq 'applying' -or $slotState -eq 'dropping') { $currentColor = '#9FDCFF' }
            try { $shell.Tag.StateText.Foreground = Get-Brush $currentColor } catch {}
            try {
                $existingId = [string]$slot.assetId
                if (-not [string]::IsNullOrWhiteSpace($existingId) -and [string]::IsNullOrWhiteSpace($shell.Tag.IdBox.Text)) {
                    $shell.Tag.IdBox.Text = $existingId
                }
            } catch {}
            $canSubmit = ($slotState -eq 'obj' -or $slotState -eq 'apply_failed')
            try { $shell.Tag.IdBox.IsEnabled = $canSubmit } catch {}
            try { $shell.Tag.DoneButton.IsEnabled = $canSubmit } catch {}
            try { $shell.Tag.CancelButton.IsEnabled = ($slotState -in @('obj', 'apply_failed', 'applied')) } catch {}
            if ($canSubmit) { $openCount = $openCount + 1 }
            if ($slotState -eq 'applied') { $appliedCount = $appliedCount + 1 }
            if ($slotState -in @('apply_failed', 'drop_failed')) { $failedCount = $failedCount + 1 }
        }

        $statusText = $win.FindName('StatusText')
        if ($null -ne $statusText) {
            if ($rows.Count -eq 0) {
                $statusText.Text = 'Keine Mesh-Datei wartet auf den Upload. Sobald Blender eine OBJ-Datei gebaut hat, oeffnet sich dieses Fenster von selbst.'
            } else {
                $status = [string]$rows.Count + ' Mesh(s): ' + [string]$openCount + ' warten auf die Mesh-Id, ' + [string]$appliedCount + ' eingesetzt'
                if ($failedCount -gt 0) { $status = $status + ', ' + [string]$failedCount + ' mit Fehler' }
                if (-not [string]::IsNullOrWhiteSpace([string]$script:MeshWindowNotice)) { $status = $status + '. ' + [string]$script:MeshWindowNotice }
                $statusText.Text = $status + '.'
            }
        }
        $placeLabel = $win.FindName('PlaceNameText')
        if ($null -ne $placeLabel) { $placeLabel.Text = Get-MeshWindowPlaceLabel }
    } catch {
        try { Write-UiErrorLog 'Mesh-Fenster Aktualisierung' $_ } catch {}
    }
}

function Get-MeshWaitingUploadKeys {
    # Slot-Keys aller Slots, deren OBJ-Datei auf den Upload wartet (state obj).
    $keys = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($pair in @($script:Shared.MeshRegistry.GetEnumerator())) {
            $slot = $null
            try { $slot = ($pair.Value | ConvertFrom-Json) } catch { continue }
            if ($null -eq $slot) { continue }
            $slotState = ''
            try { $slotState = [string]$slot.state } catch {}
            if ($slotState -ne 'obj') { continue }
            $keys.Add([string]$slot.slotKey)
        }
    } catch {}
    return ,$keys
}

function Get-MeshWaitingSignature {
    # Sortierte Wartemenge als eine Zeichenkette - damit das Fenster nicht in
    # Schleife aufgeht, merkt sich die Bridge diese Menge beim Schliessen.
    $keys = Get-MeshWaitingUploadKeys
    if ($null -eq $keys -or $keys.Count -eq 0) { return '' }
    return (($keys.ToArray() | Sort-Object) -join '|')
}

function Update-MeshAutoWindow {
    # Version 7.4.1: Das Fenster erscheint AUTOMATISCH und MODELLOS, sobald
    # mindestens eine OBJ auf den Upload wartet. Nach dem Schliessen geht es
    # erst wieder auf, wenn sich die Wartemenge (sortierte Slot-Keys) aendert.
    try {
        $signature = Get-MeshWaitingSignature
        if ([string]::IsNullOrWhiteSpace($signature)) {
            $script:MeshAutoClosedSignature = ''
            return
        }
        if ($null -ne $script:MeshWindow) { return }
        if ($signature -eq [string]$script:MeshAutoClosedSignature) { return }
        Open-MeshWindow
    } catch {
        try { Write-UiErrorLog 'Mesh-Fenster automatisch oeffnen' $_ } catch {}
    }
}

function Open-MeshWindow {
    # MODELLOS (Show(), KEIN ShowDialog): der Nutzer arbeitet im Studio weiter,
    # waehrend das Fenster offen ist. Es wird automatisch geoeffnet und kann
    # jederzeit geschlossen werden.
    if ($null -ne $script:MeshWindow) {
        try {
            $script:MeshWindow.Activate()
            Update-MeshWindow
            return
        } catch {}
    }
    $windowXaml = Get-MeshWindowXaml
    $reader = [System.Xml.XmlNodeReader]::new([xml]$windowXaml)
    $win = [Windows.Markup.XamlReader]::Load($reader)
    try { $win.Owner = $window } catch {}

    $titleBar = $win.FindName('TitleBar')
    $placeLabel = $win.FindName('PlaceNameText')
    $closeButton = $win.FindName('CloseButton')
    $folderButton = $win.FindName('FolderButton')

    $info = [pscustomobject]@{
        Window    = $win
        SessionId = [string]$script:MeshWindowSessionId
    }
    $win.Tag = $info
    $titleBar.Tag = $win
    $closeButton.Tag = $win
    $script:MeshWindow = $win
    $script:MeshWindowRows = @{}
    $script:MeshWindowNotice = ''

    $titleBar.Add_MouseLeftButtonDown({
        param($s, $e)
        if ($e.ButtonState -eq [System.Windows.Input.MouseButtonState]::Pressed) {
            try { $s.Tag.DragMove() } catch {}
        }
    })
    $closeButton.Add_Click({
        param($s, $e)
        try { $s.Tag.Close() } catch {}
    })
    $folderButton.Add_Click({
        param($s, $e)
        # "Ordner oeffnen": den Mesh-/Job-Ordner im Explorer zeigen; ohne
        # wartenden Job den Mesh-Ordner der Bridge.
        try {
            $folder = ''
            try {
                foreach ($pair in @($script:Shared.MeshRegistry.GetEnumerator())) {
                    $slot = $null
                    try { $slot = ($pair.Value | ConvertFrom-Json) } catch { continue }
                    if ($null -eq $slot) { continue }
                    $slotState = ''
                    try { $slotState = [string]$slot.state } catch {}
                    if ($slotState -ne 'obj') { continue }
                    $objPath = ''
                    try { $objPath = [string]$slot.objPath } catch {}
                    if ([string]::IsNullOrWhiteSpace($objPath)) { continue }
                    $folder = [System.IO.Path]::GetDirectoryName($objPath)
                    if (-not [string]::IsNullOrWhiteSpace($folder)) { break }
                }
            } catch {}
            if ([string]::IsNullOrWhiteSpace($folder) -or -not (Test-Path -LiteralPath $folder)) {
                $folder = [string]$script:MeshRoot
            }
            if (Test-Path -LiteralPath $folder) { Start-Process explorer.exe -ArgumentList ('"' + $folder + '"') | Out-Null }
        } catch {
            try { Write-UiErrorLog 'Mesh-Ordner oeffnen' $_ } catch {}
        }
    })
    $win.Add_Closed({
        param($s, $e)
        # Wartemenge merken - erst wenn sie sich aendert, oeffnet es wieder.
        try { $script:MeshAutoClosedSignature = Get-MeshWaitingSignature } catch {}
        try { $script:MeshWindow = $null } catch {}
    })
    $win.Add_PreviewKeyDown({
        param($s, $e)
        try {
            if ($e.Key -eq [System.Windows.Input.Key]::Escape) { $s.Close(); $e.Handled = $true }
        } catch {}
    })

    Update-MeshWindow
    try { $win.Show() | Out-Null } catch {
        try { Write-UiErrorLog 'Mesh-Fenster konnte nicht angezeigt werden' $_ } catch {}
    }
}

# ----------------------------------------------------------------------------
# Tunnel (cloudflared)
# ----------------------------------------------------------------------------
$script:TunnelStreamReaderScript = {
    param($Process, $StreamName, $Queue, $LogFile)
    try {
        $stream = if ($StreamName -eq 'Out') { $Process.StandardOutput } else { $Process.StandardError }
        while ($true) {
            $line = $stream.ReadLine()
            if ($null -eq $line) { break }
            # Alte Reader duerfen nach einem Neustart noch gepufferte Zeilen
            # schreiben. Die Prozess-ID macht sie im UI eindeutig filterbar,
            # damit eine alte Quick-Tunnel-URL keinen neuen Prozess uebermalt.
            $processId = 0
            try { $processId = [int]$Process.Id } catch {}
            $Queue.Enqueue(('[pid=' + [string]$processId + '] ' + $line))
            try {
                Add-Content -LiteralPath $LogFile -Value ('{0:u} cloudflared: {1}' -f (Get-Date), $line) -Encoding UTF8
            } catch {}
        }
    } catch {}
}

# ----------------------------------------------------------------------------
# CLOUDFLARED AUTOMATISCH INSTALLIEREN (Version 3.3)
# Fehlt cloudflared, wird es ohne Nachfrage installiert:
#   Weg 1: Download der neuesten offiziellen Version von GitHub (Cloudflare)
#          nach %LOCALAPPDATA%\ArenaRobloxBridge\bin\cloudflared.exe.
#          Braucht keine Admin-Rechte.
#   Weg 2: Klappt der Download nicht, wird winget versucht (falls vorhanden).
# Der Fortschritt wird in der Datei install.status festgehalten. Die
# Oberflaeche (Refresh-Ui) prueft sie regelmaessig, zeigt den Status an und
# startet den Tunnel automatisch, sobald cloudflared verfuegbar ist.
# ----------------------------------------------------------------------------
function Get-CloudflaredPath {
    # 1) Bereits im PATH?
    $command = Get-Command cloudflared -ErrorAction SilentlyContinue
    if ($command) { return $command.Source }
    # 2) Bereits automatisch heruntergeladen (fruehere Starts)?
    $localCopy = Join-Path $script:BinFolder 'cloudflared.exe'
    if (Test-Path -LiteralPath $localCopy) { return $localCopy }
    # 3) Klassische Installation (z.B. per winget/MSI in Program Files)?
    $installRoots = @(${env:ProgramFiles(x86)}, $env:ProgramFiles) | Where-Object { $_ }
    foreach ($root in $installRoots) {
        $candidate = Join-Path $root 'cloudflared\cloudflared.exe'
        if (Test-Path -LiteralPath $candidate) { return $candidate }
    }
    return $null
}

function Update-ProcessPath {
    # PATH aus der Registry neu einlesen. Installationen von aussen (z.B.
    # winget) aktualisieren den PATH eines bereits laufenden Programms nicht
    # von selbst.
    try {
        $machinePath = [System.Environment]::GetEnvironmentVariable('Path', 'Machine')
        $userPath = [System.Environment]::GetEnvironmentVariable('Path', 'User')
        $pathParts = @($machinePath, $userPath) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        if ($pathParts.Count -gt 0) { $env:Path = ($pathParts -join ';') }
    } catch {}
}

function Start-CloudflaredInstall {
    # Stoesst die vollautomatische Installation an (lauft im Hintergrund
    # weiter, das Fenster bleibt bedienbar). Refresh-Ui ueberwacht den
    # Fortschritt und startet den Tunnel, sobald die Installation fertig ist.
    if ($script:TunnelInstalling) { return }
    $script:TunnelInstalling = $true
    $script:TunnelInstallFailed = $false
    $script:TunnelInstallMessage = ''
    $script:TunnelInstallStartedAt = Get-Date
    try { New-Item -ItemType Directory -Path $script:BinFolder -Force | Out-Null } catch {}

    $targetPath = Join-Path $script:BinFolder 'cloudflared.exe'
    $statusPath = Join-Path $script:BinFolder 'install.status'

    Write-RuntimeLog 'Cloudflared fehlt - automatische Installation wird gestartet (Download von GitHub, Fallback winget).'
    try {
        if ($script:ToastHost) {
            Show-Toast -Message 'Cloudflared fehlt und wird jetzt automatisch installiert. Der Tunnel startet danach von selbst.' -Kind 'Info' -Seconds 8
        } else {
            Add-PendingToast 'Cloudflared fehlt und wird jetzt automatisch installiert. Der Tunnel startet danach von selbst.' 'Info' 8
        }
    } catch {}

    $installerScript = {
        param([string]$TargetPath, [string]$StatusPath)
        function Write-InstallStatus([string]$Text) {
            try { Set-Content -LiteralPath $StatusPath -Value $Text -Encoding UTF8 } catch {}
        }
        try {
            try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12 } catch {}
            $oldProgress = $ProgressPreference
            $ProgressPreference = 'SilentlyContinue'
            $tempPath = "$TargetPath.download"
            if (Test-Path -LiteralPath $tempPath) { Remove-Item -LiteralPath $tempPath -Force }
            Write-InstallStatus 'downloading'
            Invoke-WebRequest -Uri 'https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-windows-amd64.exe' -OutFile $tempPath -UseBasicParsing -TimeoutSec 600
            $downloaded = Get-Item -LiteralPath $tempPath
            $head = [byte[]]::new(2)
            $stream = [System.IO.File]::OpenRead($tempPath)
            try { [void]$stream.Read($head, 0, 2) } finally { $stream.Dispose() }
            if ($head[0] -ne 0x4D -or $head[1] -ne 0x5A -or $downloaded.Length -lt 5242880) {
                throw ("Heruntergeladene Datei ist keine gueltige cloudflared.exe ($($downloaded.Length) Bytes).")
            }
            if (Test-Path -LiteralPath $TargetPath) { Remove-Item -LiteralPath $TargetPath -Force }
            Move-Item -LiteralPath $tempPath -Destination $TargetPath -Force
            Write-InstallStatus 'ok'
        } catch {
            $downloadError = $_.Exception.Message
            # Fallback: winget, falls vorhanden
            $wingetCommand = Get-Command winget -ErrorAction SilentlyContinue
            if ($wingetCommand) {
                try {
                    Write-InstallStatus 'winget'
                    $wingetOutput = & $wingetCommand.Source install --id Cloudflare.cloudflared -e --silent --disable-interactivity --accept-source-agreements --accept-package-agreements 2>&1
                    if ($LASTEXITCODE -eq 0) {
                        Write-InstallStatus 'ok'
                    } else {
                        Write-InstallStatus ('error: winget: ' + (($wingetOutput | Out-String).Trim()) + ' / Download: ' + $downloadError)
                    }
                } catch {
                    Write-InstallStatus ('error: winget: ' + $_.Exception.Message + ' / Download: ' + $downloadError)
                }
            } else {
                Write-InstallStatus ('error: ' + $downloadError)
            }
        }
    }

    $installer = [PowerShell]::Create()
    [void]$installer.AddScript($installerScript).AddArgument($targetPath).AddArgument($statusPath)
    [void]$installer.BeginInvoke()
    $script:TunnelInstaller = $installer
}

function Start-CloudflareTunnel {
    param([string]$Protocol = 'auto')
    try {
        # Version 7.4.0: Schritt 4 hat Vorrang. Solange Blender geprueft oder
        # installiert wird, startet kein Tunnel - auch nicht aus der
        # Selbstheilung im UI-Takt heraus.
        if ($script:BlenderGatePending) {
            Write-RuntimeLog 'Der Tunnel wartet noch auf den Blender-Schritt 4.'
            return
        }
        $cloudflaredPath = Get-CloudflaredPath
        if (-not $cloudflaredPath) {
            # Nicht installiert: komplett automatische Installation anstossen.
            # Der Tunnel startet sich selbst, sobald der Download fertig ist
            # (siehe Refresh-Ui / Start-CloudflaredInstall).
            Start-CloudflaredInstall
            return
        }

        # Kein zweiter Prozess fuer dieselbe Bridge: sonst koennte eine alte
        # Quick-Tunnel-URL weiter im UI stehen, obwohl ein anderer Prozess die
        # neue Verbindung verwaltet.
        $alreadyRunning = $false
        try { $alreadyRunning = ($null -ne $script:TunnelProcess -and -not [bool]$script:TunnelProcess.HasExited) } catch {}
        if ($alreadyRunning) {
            Write-RuntimeLog 'Cloudflare-Tunnel ist bereits aktiv; kein zweiter Prozess wird gestartet.'
            return
        }

        $effectiveProtocol = if ([string]::IsNullOrWhiteSpace($Protocol)) { 'auto' } else { [string]$Protocol }
        $arguments = "tunnel --url $script:LocalBaseUrl --no-autoupdate"
        if ($effectiveProtocol -ne 'auto') { $arguments = "$arguments --protocol $effectiveProtocol" }

        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $cloudflaredPath
        $psi.Arguments = $arguments
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
        $psi.StandardErrorEncoding = [System.Text.Encoding]::UTF8
        $process = [System.Diagnostics.Process]::new()
        $process.StartInfo = $psi
        [void]$process.Start()

        foreach ($streamName in @('Out', 'Err')) {
            $reader = [PowerShell]::Create()
            [void]$reader.AddScript([string]$script:TunnelStreamReaderScript).AddArgument($process).AddArgument($streamName).AddArgument($script:TunnelLines).AddArgument($script:RuntimeLog)
            [void]$reader.BeginInvoke()
            $script:TunnelReaders += $reader
        }
        $script:TunnelProcess = $process
        $script:TunnelUrl = $null
        $script:TunnelLiveSince = [DateTime]::MinValue
        $script:TunnelProtocol = $effectiveProtocol
        $script:TunnelStartedAt = Get-Date
        $script:TunnelHttp2Tried = ($effectiveProtocol -eq 'http2')
        $script:TunnelSlowNotified = $false
        $script:TunnelFailed = $false
        Write-RuntimeLog "Cloudflare-Tunnel-Prozess gestartet (PID $($process.Id), Datei: $cloudflaredPath, Argumente: $arguments)."
    } catch {
        $script:TunnelFailed = $true
        $script:LastTunnelMessage = "Cloudflare-Tunnel-Fehler: $($_.Exception.Message)"
        Write-RuntimeLog $script:LastTunnelMessage
    }
}

function Restart-CloudflareTunnel {
    param([string]$Protocol = 'auto')
    try {
        if ($script:TunnelProcess -and -not $script:TunnelProcess.HasExited) {
            $script:TunnelProcess.Kill()
            Start-Sleep -Milliseconds 600
        }
    } catch {}
    $script:TunnelUrl = $null
    Start-CloudflareTunnel -Protocol $Protocol
}

function Get-StartupEnabled {
    $runKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    $props = Get-ItemProperty -Path $runKey -Name 'ArenaRobloxBridge' -ErrorAction SilentlyContinue
    if (-not $props) { return $false }
    $property = $props.PSObject.Properties['ArenaRobloxBridge']
    if (-not $property) { return $false }
    $value = [string]$property.Value
    return -not [string]::IsNullOrWhiteSpace($value)
}

function Set-StartupEnabled {
    param([bool]$Enabled)
    $runKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    if ($Enabled) {
        if ($script:IsExeMode -and $script:ExePath) {
            # EXE-Modus: die EXE selbst starten (kein PowerShell-Aufruf noetig).
            $value = "`"$($script:ExePath)`""
        } else {
            $value = "powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -STA -File `"$($script:AppRoot)\ArenaBridge.ps1`""
        }
        New-Item -Path $runKey -Force | Out-Null
        Set-ItemProperty -Path $runKey -Name 'ArenaRobloxBridge' -Value $value
    } else {
        Remove-ItemProperty -Path $runKey -Name 'ArenaRobloxBridge' -ErrorAction SilentlyContinue
    }
}

# ----------------------------------------------------------------------------
# SITZUNGEN (ein Studio-Fenster = eine Sitzung = ein Token)
# ----------------------------------------------------------------------------
# Version 5.2: verstorbene Sitzung restlos entsorgen (Token UND jeglicher
# Nebenzustand). Frueher blieb fast alles davon bis zum Programmende liegen.
function Remove-DeadSession {
    param([string]$SessionId)
    if ([string]::IsNullOrWhiteSpace($SessionId)) { return }
    $placeName = ''
    try {
        $rawEntry = $null
        if ($script:Shared.Sessions.TryGetValue($SessionId, [ref]$rawEntry)) { $placeName = [string](($rawEntry | ConvertFrom-Json).placeName) }
    } catch {}
    $removedJson = $null
    [void]$script:Shared.Sessions.TryRemove($SessionId, [ref]$removedJson)
    $token = $null
    if ($script:Shared.SessionTokens.TryRemove($SessionId, [ref]$token)) {
        $removedSession = $null
        [void]$script:Shared.TokenSessions.TryRemove($token, [ref]$removedSession)
    }
    $junk = $null
    $junkInt = [int]0
    $junkLong = [long]0
    $junkBool = $false
    foreach ($bagName in @('AccessModes','PendingCommands','LateResults','PlayRetryDedupe','AiPlayIntents','LastPlayEvents','RunOwners','AgentKeys','AgentQueues','AgentResults','AgentStates','CommandQueues','CommandSignals','ActivityLogs','ActivityCommandMap','ExecutorStates')) {
        try { [void]$script:Shared.$bagName.TryRemove($SessionId, [ref]$junk) } catch {}
    }
    try { [void]$script:Shared.Pollers.TryRemove($SessionId, [ref]$junkInt) } catch {}
    # Version 7.1.2: Toolbox-Drossel und Import-Sperre duerfen eine beendete
    # Sitzung NIE ueberleben - sonst bliebe der Place dauerhaft "beschaeftigt".
    try { [void]$script:Shared.ToolboxSlots.TryRemove($SessionId, [ref]$junkInt) } catch {}
    try { $junkString = ''; [void]$script:Shared.ToolboxImportLocks.TryRemove($SessionId, [ref]$junkString) } catch {}
    foreach ($longBag in @('Presence','UserActiveAt','AgentLastSeen','ExecutorResetRequests')) {
        try { [void]$script:Shared.$longBag.TryRemove($SessionId, [ref]$junkLong) } catch {}
    }
    try { [void]$script:Shared.DocsSent.TryRemove($SessionId, [ref]$junkBool) } catch {}
    # Command-level records use commandId keys, so remove them through the
    # explicit owner map rather than leaving result/signalling state behind.
    try {
        foreach ($ownerPair in @($script:Shared.CommandOwners.GetEnumerator())) {
            if ([string]$ownerPair.Value -ne $SessionId) { continue }
            $commandId = [string]$ownerPair.Key
            [void]$script:Shared.CommandOwners.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.CommandStates.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.CommandPayloads.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.CommandResults.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.ResultChunks.TryRemove($commandId, [ref]$junk)
            [void]$script:Shared.ResultChunkAt.TryRemove($commandId, [ref]$junkLong)
            $signal = $null
            if ($script:Shared.ResultSignals.TryRemove($commandId, [ref]$signal)) { try { $signal.Dispose() } catch {} }
        }
        $prefix = $SessionId + ':'
        foreach ($key in @($script:Shared.CancelRequests.Keys)) {
            if ([string]$key -like ($prefix + '*')) { [void]$script:Shared.CancelRequests.TryRemove([string]$key, [ref]$junkLong) }
        }
        foreach ($key in @($script:Shared.CompletedCommandIds.Keys)) {
            if ([string]$key -like ($prefix + '*')) { [void]$script:Shared.CompletedCommandIds.TryRemove([string]$key, [ref]$junkLong) }
        }
    } catch {}
    # Version 7.0.3: Auch die Diagnose-Eintraege dieser Sitzung entfernen,
    # damit wiederholtes Verbinden/Trennen nichts ansammelt.
    try {
        if ($null -ne $script:Shared.Perf) {
            foreach ($perfKey in @('PollRate:' + $SessionId, 'Plugin:' + $SessionId, 'PluginAt:' + $SessionId)) {
                [void]$script:Shared.Perf.Remove($perfKey)
            }
        }
    } catch {}
    try { $script:PlaceNames.Remove($SessionId) } catch {}
    try { $script:PlaceNameResolveErrorLogged.Remove($SessionId) } catch {}
    try {
        foreach ($failureKey in @($script:PlaceRowFailureLogAt.Keys)) {
            if ([string]$failureKey -like ($SessionId + '|*')) { [void]$script:PlaceRowFailureLogAt.Remove([string]$failureKey) }
        }
    } catch {}
    try { $script:PlaceNameSources.Remove($SessionId) } catch {}
    try {
        # Fenster-Besitz freigeben, damit ein neu geoeffnetes Studio-Fenster
        # den Handle uebernehmen kann (und keine Geister-Bindung bleibt).
        $identity = $null
        if ($script:PlaceIdentities.ContainsKey($SessionId)) { $identity = $script:PlaceIdentities[$SessionId] }
        if ($null -ne $identity) {
            foreach ($key in @($script:PreviewHandleClaims.Keys)) {
                if ([string]$script:PreviewHandleClaims[$key] -eq $SessionId) { [void]$script:PreviewHandleClaims.Remove($key) }
            }
        }
        [void]$script:PlaceIdentities.Remove($SessionId)
    } catch {}
    # Vorschau-Worker und Caches gehoeren zur Sitzung und duerfen nach dem
    # Schliessen eines Studio-Fensters weder weiterlaufen noch Handles halten.
    try {
        if ($script:PlacePreviewJobs.ContainsKey($SessionId)) {
            $previewJob = $script:PlacePreviewJobs[$SessionId]
            # Nur der PS-Fallback-Worker laesst sich stoppen; ein C#-Task-Job
            # wird schlicht fallengelassen (nichts blockiert den UI-Thread).
            if ($previewJob.Worker) {
                try { $previewJob.Worker.Stop() } catch {}
                try { $previewJob.Worker.Dispose() } catch {}
            }
            [void]$script:PlacePreviewJobs.Remove($SessionId)
        }
        [void]$script:PlacePreviewHandles.Remove($SessionId)
        try { [void]$script:PreviewHandleInfos.Remove($SessionId) } catch {}
        [void]$script:PlacePreviewLastCaptureAt.Remove($SessionId)
        [void]$script:PlacePreviewFailLogAt.Remove($SessionId)
    } catch {}
    Write-RuntimeLog ('Place-Sitzung ' + $SessionId + ' ("' + $placeName + '") nach ' + $script:PlaceCleanupSeconds + ' s ohne Lebenszeichen entfernt.')
}
function Get-ActiveStudios {
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($pair in $script:Shared.Sessions.GetEnumerator()) {
        try {
            $item = $pair.Value | ConvertFrom-Json
            $sessionId = [string]$item.sessionId
            # Version 5.2: Lebenszeichen PRIMAER aus Presence - Presence setzt
            # ausschliesslich das Edit-Plugin (Heartbeat/Long-Poll). Frueher
            # wurde das Maximum aus lastSeen UND Presence genommen; ein
            # verklemmter Session-Reporter (Agent-Heartbeat) frischt aber NUR
            # lastSeen weiter und hielt tote Places fuer immer sichtbar
            # ("Geister-Place"). Jetzt: nach spaetestens ~15 s ist er weg.
            $aliveAt = [int64]0
            $presenceKnown = $false
            if ($script:Shared.Presence.TryGetValue($sessionId, [ref]$aliveAt)) {
                $presenceKnown = $true
            } else {
                $aliveAt = [int64]$item.lastSeen
            }
            $age = $now - [int64]$aliveAt
            $limit = $script:PlaceVisibleSeconds
            # Sauber abgemeldete Fenster: kurze Gnadenfrist (Plugin-Neuladen),
            # danach sofort raus aus der Liste.
            if ($item.orphan -eq $true -and -not $presenceKnown) { $limit = $script:PlaceOrphanGraceSeconds }
            if ($age -lt $limit) {
                # Sicherheitsnetz gegen kaputte Umlaute in der Anzeige
                $item.placeName = Repair-Mojibake ([string]$item.placeName)
                $items.Add($item)
            } elseif ($age -gt $script:PlaceCleanupSeconds) {
                # Version 5.2: restlos aufraeumen (Token + jeglicher Nebenzustand).
                Remove-DeadSession $sessionId
            }
        } catch {}
    }
    # ------------------------------------------------------------------
    # 4.0.1 DEDUPLIZIERUNG (Live-Befund: waehrend eines Playtests erschienen
    # "Place1" UND "Game"). Ein physischer Studio-Platz darf genau EINE
    # sichtbare Zeile haben. Zwei wirklich getrennt geoeffnete Fenster
    # bleiben getrennt, weil sie unterschiedliche instanceGuids haben und
    # beide dauerhaft heartbeaten.
    #
    # Zusammengefasst wird nur, was nachweislich dieselbe physische
    # Verbindung ist:
    #   a) gleiche instanceGuid (identisches Plugin), oder
    #   b) eine Test-/Play-Session desselben Place, die parallel zu einer
    #      Edit-Sitzung desselben Place laeuft (Studio klont das Place fuer
    #      den Test und nennt es dann haeufig "Game").
    # Sichtbar bleibt die aeltere, echte Sitzung (connectedAt).
    # ------------------------------------------------------------------
    $deduped = New-Object System.Collections.Generic.List[object]
    foreach ($item in $items) {
        $hide = $false
        foreach ($other in $items) {
            if ([string]$other.sessionId -eq [string]$item.sessionId) { continue }
            # Nur die AELTERE Sitzung darf eine juengere verdecken.
            if ([int64]$other.connectedAt -ge [int64]$item.connectedAt) { continue }
            # Version 7.0.0: NUR dieselbe Plugin-Instanz darf sich selbst
            # verdecken. Der alte Zweig "gleiche placeId + laeuft" hat zwei
            # FENSTER mit placeId=0 (zwei lokale Places) zu EINER Zeile
            # verschmolzen, sobald eines davon einen Test laufen liess.
            $sameGuid = ((-not [string]::IsNullOrWhiteSpace([string]$item.instanceGuid)) -and
                         ([string]$other.instanceGuid -eq [string]$item.instanceGuid))
            if ($sameGuid) { $hide = $true; break }
        }
        if (-not $hide) { $deduped.Add($item) }
    }

    $deduped | Sort-Object placeName, sessionId
}

function Reset-SessionToken {
    param([string]$SessionId)
    if ($SessionId -eq '__arena_all_places__') {
        # Version 5: only an explicit click changes the aggregate token.
        $script:AllPlacesToken = New-Token
        $script:Shared.MultiPlaceToken = $script:AllPlacesToken
        Write-RuntimeLog 'Token für Alle Places wurde manuell zurückgesetzt.'
        Show-CopyConfirm -Message 'Token für alle Places wurde zurückgesetzt.' -Seconds 4
        return
    }
    $old = $null
    if ($script:Shared.SessionTokens.TryRemove($SessionId, [ref]$old)) {
        $removed = $null
        [void]$script:Shared.TokenSessions.TryRemove($old, [ref]$removed)
    }
    $new = New-Token
    $script:Shared.SessionTokens[$SessionId] = $new
    $script:Shared.TokenSessions[$new] = $SessionId
    Write-RuntimeLog "Token fuer Sitzung $SessionId neu vergeben."
    Show-CopyConfirm -Message 'Token wurde zurückgesetzt.' -Seconds 4
}

function Set-SessionMode {
    param([string]$SessionId, [string]$Mode)
    # Version 5: intentionally runtime-only. A newly registered Place must
    # always start with full access, therefore nothing is written to settings.json.
    if ($SessionId -eq '__arena_all_places__') { Set-AllSessionsMode $Mode; return }
    $script:Shared.AccessModes[$SessionId] = $Mode
}

function Set-AllSessionsMode {
    param([string]$Mode)
    # The aggregate switch affects only the Places connected right now. A Place
    # that connects later always receives its registration default (read/write).
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    foreach ($pair in $script:Shared.Sessions.GetEnumerator()) {
        try {
            $entry = $pair.Value | ConvertFrom-Json
            # Version 5.2: nur wirklich lebende Fenster umschalten (Presence).
            $aliveAt = [int64]0
            if (-not $script:Shared.Presence.TryGetValue([string]$pair.Key, [ref]$aliveAt)) { $aliveAt = [int64]$entry.lastSeen }
            if ($entry -and ($now - $aliveAt) -lt 30 -and $entry.orphan -ne $true) {
                $script:Shared.AccessModes[[string]$pair.Key] = $Mode
            }
        } catch {}
    }
}

# ----------------------------------------------------------------------------
# HILFSFUNKTIONEN FUER DIE OBERFLAECHE
# ----------------------------------------------------------------------------
$script:BrushCache = @{}
function Get-Brush {
    param([string]$Hex)
    $key = $Hex.ToUpperInvariant()
    if (-not $script:BrushCache.ContainsKey($key)) {
        $color = [System.Windows.Media.ColorConverter]::ConvertFromString($Hex)
        $brush = [System.Windows.Media.SolidColorBrush]::new($color)
        $brush.Freeze()
        $script:BrushCache[$key] = $brush
    }
    return $script:BrushCache[$key]
}

function New-Shadow {
    param([double]$Blur = 20, [double]$Opacity = 0.5, [string]$Color = '#000000')
    $shadow = [System.Windows.Media.Effects.DropShadowEffect]::new()
    $shadow.Color = [System.Windows.Media.ColorConverter]::ConvertFromString($Color)
    $shadow.BlurRadius = $Blur
    $shadow.ShadowDepth = 0
    $shadow.Opacity = $Opacity
    $shadow.Direction = 270
    return $shadow
}

function New-CheckPath {
    param([string]$Color = '#FFFFFF')
    $path = [System.Windows.Shapes.Path]::new()
    $path.Data = [System.Windows.Media.Geometry]::Parse('M 4,10.4 L 8,14.4 L 16,5.2')
    $path.Stroke = Get-Brush $Color
    $path.StrokeThickness = 2.2
    $path.StrokeStartLineCap = 'Round'
    $path.StrokeEndLineCap = 'Round'
    $path.HorizontalAlignment = 'Center'
    $path.VerticalAlignment = 'Center'
    return $path
}

function Set-Text {
    param($Element, [string]$Value)
    if ($null -eq $Element) { return }
    if ([string]$Element.Text -ne $Value) { $Element.Text = $Value }
}

function Set-Dot {
    param($Element, [string]$Hex)
    if ($null -eq $Element) { return }
    if ([string]$Element.Tag -ne $Hex) {
        $Element.Tag = $Hex
        $Element.Fill = Get-Brush $Hex
    }
}

$script:ColorGreen  = '#3DDC84'
$script:ColorAmber  = '#FFB020'
$script:ColorRed    = '#FF5C77'
$script:ColorBlue   = '#5B8CFF'
$script:ColorGray   = '#8FA3CC'


# ----------------------------------------------------------------------------
# OBERFLAECHE (XAML)
# ----------------------------------------------------------------------------
$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Arena Roblox Bridge"
        Width="920" Height="620"
        MinWidth="920" MinHeight="620" MaxWidth="920" MaxHeight="620"
        ResizeMode="NoResize"
        WindowStyle="None"
        AllowsTransparency="True"
        Background="Transparent"
        WindowStartupLocation="CenterScreen"
        FontFamily="Segoe UI">
    <Window.Resources>
        <!-- ============================================================ -->
        <!-- VERSION 6.0  -  LIQUID GLASS DESIGN                          -->
        <!-- Tiefblau-violetter Grund mit lebendigen Farblichtern         -->
        <!-- (Aurora), Teal-Glaskarten fuer die Places, gruene Glas-      -->
        <!-- Aktionsknoepfe, runde Fensterknoepfe in Crimson. Alle        -->
        <!-- Hover-/Druck-Zustaende laufen weich ueber Storyboards.       -->
        <!-- ============================================================ -->
        <SolidColorBrush x:Key="TextMain" Color="#F4F8FF"/>
        <SolidColorBrush x:Key="TextSoft" Color="#C9D6F2"/>
        <SolidColorBrush x:Key="TextMuted" Color="#9AA9CE"/>
        <SolidColorBrush x:Key="TextFaint" Color="#6E7FA8"/>

        <LinearGradientBrush x:Key="AppBg" StartPoint="0,0" EndPoint="1,1">
            <GradientStop Color="#060A1A" Offset="0"/>
            <GradientStop Color="#0A1128" Offset="0.55"/>
            <GradientStop Color="#0C1533" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="GlassFill" StartPoint="0,0" EndPoint="0.25,1">
            <GradientStop Color="#99121C44" Offset="0"/>
            <GradientStop Color="#5C0E1734" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="TitleGlass" StartPoint="0,0" EndPoint="0,1">
            <GradientStop Color="#2BFFFFFF" Offset="0"/>
            <GradientStop Color="#0DFFFFFF" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="LogoBrush" StartPoint="0,0" EndPoint="1,1">
            <GradientStop Color="#8B6BFF" Offset="0"/>
            <GradientStop Color="#00D0BE" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="SweepBrush" StartPoint="0,0" EndPoint="1,0">
            <GradientStop Color="#0000E5D0" Offset="0"/>
            <GradientStop Color="#B300E5D0" Offset="0.5"/>
            <GradientStop Color="#0000E5D0" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="GreenBtnBg" StartPoint="0,0" EndPoint="0,1">
            <GradientStop Color="#F238D16C" Offset="0"/>
            <GradientStop Color="#E61FA34A" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="NeutralBtnBg" StartPoint="0,0" EndPoint="0,1">
            <GradientStop Color="#47FFFFFF" Offset="0"/>
            <GradientStop Color="#21FFFFFF" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="CrimsonBtnBg" StartPoint="0,0" EndPoint="0,1">
            <GradientStop Color="#F2FF5C77" Offset="0"/>
            <GradientStop Color="#E6E11D48" Offset="1"/>
        </LinearGradientBrush>

        <!-- Glas-Knopf (implizit): Heller Schein oben, weicher Hover-Glanz, -->
        <!-- Druck zieht den Knopf sanft zusammen. Hintergrund/Rand kommen    -->
        <!-- per TemplateBinding vom einzelnen Knopf.                        -->
        <Style TargetType="Button">
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="Background" Value="{StaticResource NeutralBtnBg}"/>
            <Setter Property="BorderBrush" Value="#3DFFFFFF"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="14,9"/>
            <Setter Property="FontSize" Value="12.5"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Grid>
                            <Border x:Name="bd" CornerRadius="12"
                                    Background="{TemplateBinding Background}"
                                    BorderBrush="{TemplateBinding BorderBrush}"
                                    BorderThickness="{TemplateBinding BorderThickness}"
                                    RenderTransformOrigin="0.5,0.5">
                                <Border.RenderTransform>
                                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                                </Border.RenderTransform>
                                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/>
                            </Border>
                            <Border x:Name="sheen" CornerRadius="11,11,10,10" Margin="1,1,1,0" Height="18" VerticalAlignment="Top" IsHitTestVisible="False" Opacity="0.10">
                                <Border.Background>
                                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                                        <GradientStop Color="#59FFFFFF" Offset="0"/>
                                        <GradientStop Color="#00FFFFFF" Offset="1"/>
                                    </LinearGradientBrush>
                                </Border.Background>
                            </Border>
                            <Border x:Name="press" CornerRadius="11" Margin="1" Background="#29000000" Opacity="0" IsHitTestVisible="False"/>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#6BFFFFFF"/>
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.38" Duration="0:0:0.13">
                                                <DoubleAnimation.EasingFunction>
                                                    <CubicEase EasingMode="EaseOut"/>
                                                </DoubleAnimation.EasingFunction>
                                            </DoubleAnimation>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.10" Duration="0:0:0.20"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="press" Storyboard.TargetProperty="Opacity" To="0.22" Duration="0:0:0.08"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="0.965" Duration="0:0:0.08"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="0.965" Duration="0:0:0.08"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="press" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.15"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter Property="Opacity" Value="0.45"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Runde Glas-Knoepfe (Minimieren/Schliessen), gleiche Gleit-Effekte -->
        <Style x:Key="RoundGlassStyle" TargetType="Button">
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="Background" Value="{StaticResource NeutralBtnBg}"/>
            <Setter Property="BorderBrush" Value="#3DFFFFFF"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Grid>
                            <Border x:Name="bd" CornerRadius="17"
                                    Background="{TemplateBinding Background}"
                                    BorderBrush="{TemplateBinding BorderBrush}"
                                    BorderThickness="{TemplateBinding BorderThickness}"
                                    RenderTransformOrigin="0.5,0.5">
                                <Border.RenderTransform>
                                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                                </Border.RenderTransform>
                                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                            <Border x:Name="sheen" CornerRadius="16,16,14,14" Margin="1,1,1,0" Height="13" VerticalAlignment="Top" IsHitTestVisible="False" Opacity="0.12">
                                <Border.Background>
                                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                                        <GradientStop Color="#59FFFFFF" Offset="0"/>
                                        <GradientStop Color="#00FFFFFF" Offset="1"/>
                                    </LinearGradientBrush>
                                </Border.Background>
                            </Border>
                            <Border x:Name="press" CornerRadius="16" Margin="1" Background="#29000000" Opacity="0" IsHitTestVisible="False"/>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#6BFFFFFF"/>
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.42" Duration="0:0:0.13">
                                                <DoubleAnimation.EasingFunction>
                                                    <CubicEase EasingMode="EaseOut"/>
                                                </DoubleAnimation.EasingFunction>
                                            </DoubleAnimation>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.12" Duration="0:0:0.20"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="press" Storyboard.TargetProperty="Opacity" To="0.24" Duration="0:0:0.08"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="0.94" Duration="0:0:0.08"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="0.94" Duration="0:0:0.08"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="press" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.15"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="CloseButtonStyle" TargetType="Button" BasedOn="{StaticResource RoundGlassStyle}">
            <Setter Property="Background" Value="{StaticResource CrimsonBtnBg}"/>
            <Style.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Background" Value="#F2FF7A8C"/>
                    <Setter Property="Foreground" Value="#FFFFFF"/>
                </Trigger>
            </Style.Triggers>
        </Style>

        <Style x:Key="SettingsPillStyle" TargetType="Button">
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="Background" Value="{StaticResource GreenBtnBg}"/>
            <Setter Property="BorderBrush" Value="#4DFFFFFF"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Grid>
                            <Border x:Name="bd" CornerRadius="18"
                                    Background="{TemplateBinding Background}"
                                    BorderBrush="{TemplateBinding BorderBrush}"
                                    BorderThickness="{TemplateBinding BorderThickness}"
                                    RenderTransformOrigin="0.5,0.5">
                                <Border.RenderTransform>
                                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                                </Border.RenderTransform>
                                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                            <Border x:Name="sheen" CornerRadius="17,17,14,14" Margin="1,1,1,0" Height="15" VerticalAlignment="Top" IsHitTestVisible="False" Opacity="0.14">
                                <Border.Background>
                                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                                        <GradientStop Color="#59FFFFFF" Offset="0"/>
                                        <GradientStop Color="#00FFFFFF" Offset="1"/>
                                    </LinearGradientBrush>
                                </Border.Background>
                            </Border>
                            <Border x:Name="press" CornerRadius="17" Margin="1" Background="#29000000" Opacity="0" IsHitTestVisible="False"/>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#7FFFFFFF"/>
                                <Setter Property="Background" Value="#F24AE07E"/>
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.40" Duration="0:0:0.13">
                                                <DoubleAnimation.EasingFunction>
                                                    <CubicEase EasingMode="EaseOut"/>
                                                </DoubleAnimation.EasingFunction>
                                            </DoubleAnimation>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.14" Duration="0:0:0.20"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="press" Storyboard.TargetProperty="Opacity" To="0.22" Duration="0:0:0.08"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="0.96" Duration="0:0:0.08"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="0.96" Duration="0:0:0.08"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard>
                                        <Storyboard>
                                            <DoubleAnimation Storyboard.TargetName="press" Storyboard.TargetProperty="Opacity" To="0" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.15"/>
                                            <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.15"/>
                                        </Storyboard>
                                    </BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style TargetType="ScrollBar">
            <Setter Property="Width" Value="10"/>
            <Setter Property="MinWidth" Value="10"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="BorderBrush" Value="Transparent"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ScrollBar">
                        <Grid Margin="2,3,2,3">
                            <Border CornerRadius="5" Background="#14FFFFFF"/>
                            <Track x:Name="PART_Track" IsDirectionReversed="True" Focusable="False">
                                <Track.DecreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageUpCommand">
                                        <RepeatButton.Template>
                                            <ControlTemplate TargetType="RepeatButton">
                                                <Border Background="Transparent"/>
                                            </ControlTemplate>
                                        </RepeatButton.Template>
                                    </RepeatButton>
                                </Track.DecreaseRepeatButton>
                                <Track.IncreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageDownCommand">
                                        <RepeatButton.Template>
                                            <ControlTemplate TargetType="RepeatButton">
                                                <Border Background="Transparent"/>
                                            </ControlTemplate>
                                        </RepeatButton.Template>
                                    </RepeatButton>
                                </Track.IncreaseRepeatButton>
                                <Track.Thumb>
                                    <Thumb>
                                        <Thumb.Template>
                                            <ControlTemplate TargetType="Thumb">
                                                <Border x:Name="thumbBg" CornerRadius="4" Background="#38FFFFFF" Margin="1,0,1,0"/>
                                                <ControlTemplate.Triggers>
                                                    <Trigger Property="IsMouseOver" Value="True">
                                                        <Setter TargetName="thumbBg" Property="Background" Value="#5CFFFFFF"/>
                                                    </Trigger>
                                                    <Trigger Property="IsDragging" Value="True">
                                                        <Setter TargetName="thumbBg" Property="Background" Value="#8CFFFFFF"/>
                                                    </Trigger>
                                                </ControlTemplate.Triggers>
                                            </ControlTemplate>
                                        </Thumb.Template>
                                    </Thumb>
                                </Track.Thumb>
                            </Track>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
    </Window.Resources>

    <!-- Glas-Schale des Fensters: abgerundet, mit echtem Rundungs-Beschchnitt -->
    <!-- (ClipToBounds rundet nicht - die Aurora-Lichter duerfen niemals ueber -->
    <!-- die Fensterkanten hinausragen).                                      -->
    <Border x:Name="RootShell" CornerRadius="18" Background="{StaticResource AppBg}"
            BorderBrush="#33FFFFFF" BorderThickness="1" ClipToBounds="True"
            RenderTransformOrigin="0.5,0.5">
        <Border.Clip>
            <RectangleGeometry Rect="0,0,920,620" RadiusX="18" RadiusY="18"/>
        </Border.Clip>
        <Border.RenderTransform>
            <ScaleTransform ScaleX="1" ScaleY="1"/>
        </Border.RenderTransform>
        <Grid>
            <Grid.RowDefinitions>
                <RowDefinition Height="72"/>
                <RowDefinition Height="*"/>
            </Grid.RowDefinitions>

            <!-- ======================================================== -->
            <!-- AURORA: langsam driftende Farblichter hinter dem Glas     -->
            <!-- (Liquid Glass braucht ein lebendiges, farbiges Fundament) -->
            <!-- ======================================================== -->
            <Grid Grid.Row="0" Grid.RowSpan="2" IsHitTestVisible="False">
                <Ellipse Width="560" Height="560" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="-190,-230,0,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#547B5CFF" Offset="0"/>
                            <GradientStop Color="#007B5CFF" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse Width="500" Height="500" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-180,-170,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#4D2E4FFF" Offset="0"/>
                            <GradientStop Color="#002E4FFF" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse Width="440" Height="440" HorizontalAlignment="Right" VerticalAlignment="Bottom" Margin="0,0,-150,-180">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#4000CFC0" Offset="0"/>
                            <GradientStop Color="#0000CFC0" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse Width="320" Height="320" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="-110,210,0,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#47C13FF0" Offset="0"/>
                            <GradientStop Color="#00C13FF0" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse Width="280" Height="280" HorizontalAlignment="Left" VerticalAlignment="Bottom" Margin="90,0,0,-150">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#3D21C55D" Offset="0"/>
                            <GradientStop Color="#0021C55D" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                </Ellipse>
                <Ellipse Width="240" Height="240" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="400,-140,0,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#29FF4D6D" Offset="0"/>
                            <GradientStop Color="#00FF4D6D" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                </Ellipse>
                <!-- Sanfter Glas-Schein am oberen Fensterrand -->
                <Border Height="120" VerticalAlignment="Top" IsHitTestVisible="False">
                    <Border.Background>
                        <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                            <GradientStop Color="#0DFFFFFF" Offset="0"/>
                            <GradientStop Color="#00FFFFFF" Offset="1"/>
                        </LinearGradientBrush>
                    </Border.Background>
                </Border>
            </Grid>

            <!-- ======================== TITELLEISTE ======================== -->
            <Border x:Name="TitleBar" Grid.Row="0" Background="{StaticResource TitleGlass}" BorderBrush="#1FFFFFFF" BorderThickness="0,0,0,1" CornerRadius="17,17,0,0" ClipToBounds="True">
                <Grid Margin="24,0">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                        <Grid Width="38" Height="38" Margin="0,0,13,0">
                            <Border Width="38" Height="38" CornerRadius="13" Background="{StaticResource LogoBrush}" BorderBrush="#4DFFFFFF" BorderThickness="1"/>
                            <Ellipse Width="7" Height="7" Fill="#FFFFFF" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="6,0,0,0"/>
                            <Ellipse Width="7" Height="7" Fill="#FFFFFF" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,6,0"/>
                            <Ellipse x:Name="PulseDot" Width="9" Height="9" Fill="#2FE8D6" HorizontalAlignment="Center" VerticalAlignment="Center">
                                <Ellipse.Effect>
                                    <DropShadowEffect Color="#CC00E5D0" BlurRadius="12" ShadowDepth="0" Opacity="0.9"/>
                                </Ellipse.Effect>
                            </Ellipse>
                        </Grid>
                        <StackPanel VerticalAlignment="Center">
                            <TextBlock Text="Arena Roblox Bridge" Foreground="{StaticResource TextMain}" FontSize="18.5" FontWeight="Bold"/>
                            <TextBlock x:Name="SubtitleText" Text="bereit für verbundene Places" Foreground="{StaticResource TextMuted}" FontSize="11.5" Margin="0,3,0,0"/>
                        </StackPanel>
                    </StackPanel>
                    <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center">
                        <Border x:Name="LiveBadge" CornerRadius="11" Background="#331FA34A" BorderBrush="#662FCB6C" BorderThickness="1" Padding="11,6" Margin="0,0,12,0" VerticalAlignment="Center">
                            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                <Ellipse x:Name="LiveDot" Width="8" Height="8" Fill="#3DDC84" Margin="0,0,8,0" VerticalAlignment="Center"/>
                                <TextBlock x:Name="LiveText" Text="LIVE" Foreground="{StaticResource TextSoft}" FontSize="11.5" FontWeight="SemiBold" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Border>
                        <Grid Width="46" Height="36" Margin="0,0,10,0">
                            <Button x:Name="SettingsButton" Style="{StaticResource SettingsPillStyle}" Width="46" Height="36" FontFamily="Segoe MDL2 Assets" FontSize="15" Content="&#xE713;"/>
                            <!-- Rote "1" fuer Update-Fehler (Version 3.7) -->
                            <Border x:Name="UpdateBadge" Width="16" Height="16" CornerRadius="8"
                                    Background="#FF4D6C" BorderBrush="#070B1E" BorderThickness="2"
                                    HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,-4,-4,0"
                                    Visibility="Collapsed" Panel.ZIndex="90" IsHitTestVisible="False"
                                    ToolTip="Update-Problem - klicke auf die Einstellungen für Details">
                                <TextBlock Text="1" Foreground="#FFFFFF" FontSize="9.5" FontWeight="Bold"
                                           HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                        </Grid>
                        <Button x:Name="MinimizeButton" Style="{StaticResource RoundGlassStyle}" Width="34" Height="34" Margin="0,0,8,0" FontFamily="Segoe MDL2 Assets" FontSize="12" Content="&#xE921;"/>
                        <Button x:Name="CloseButton" Style="{StaticResource CloseButtonStyle}" Width="34" Height="34" FontFamily="Segoe MDL2 Assets" FontSize="12" Content="&#xE8BB;"/>
                    </StackPanel>

                    <Border Grid.ColumnSpan="2" VerticalAlignment="Bottom" Height="2" Margin="-24,0,-24,0" ClipToBounds="True">
                        <Rectangle x:Name="SweepRect" Width="300" Height="2" HorizontalAlignment="Left" Fill="{StaticResource SweepBrush}">
                            <Rectangle.RenderTransform>
                                <TranslateTransform X="-340"/>
                            </Rectangle.RenderTransform>
                        </Rectangle>
                    </Border>
                </Grid>
            </Border>

            <!-- ========================= INHALT ========================= -->
            <Grid Grid.Row="1" Margin="26,18,26,22">

                <Border CornerRadius="16" Background="{StaticResource GlassFill}" BorderBrush="#2EFFFFFF" BorderThickness="1" ClipToBounds="True">
                    <Grid>
                        <Grid.RowDefinitions>
                            <RowDefinition Height="Auto"/>
                            <RowDefinition Height="*"/>
                        </Grid.RowDefinitions>

                        <Border Grid.Row="0" Background="#14FFFFFF" BorderBrush="#1FFFFFFF" BorderThickness="0,0,0,1" Padding="18,13">
                            <Grid>
                                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                    <TextBlock Text="Verbundene Places" Foreground="{StaticResource TextMain}" FontSize="13.5" FontWeight="SemiBold"/>
                                    <Border x:Name="PlacesCountBadge" CornerRadius="9" Background="#3300D0BE" BorderBrush="#4D00E5D0" BorderThickness="1" Padding="9,3" Margin="10,0,0,0" VerticalAlignment="Center">
                                        <TextBlock x:Name="PlacesCountText" Text="0" Foreground="#8FF5E9" FontSize="11" FontWeight="Bold"/>
                                    </Border>
                                </StackPanel>
                                <TextBlock x:Name="PlaceListStatusText" HorizontalAlignment="Right" VerticalAlignment="Center" Text="Automatisch verbunden" Foreground="{StaticResource TextFaint}" FontSize="11"/>
                            </Grid>
                        </Border>

                        <Grid Grid.Row="1">
                            <Grid.RowDefinitions>
                                <RowDefinition Height="*"/>
                                <RowDefinition Height="Auto"/>
                            </Grid.RowDefinitions>
                            <Grid Grid.Row="0">
                                <StackPanel x:Name="EmptyState" HorizontalAlignment="Center" VerticalAlignment="Center" Width="430">
                                    <Border Width="76" Height="76" CornerRadius="22" HorizontalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                                        <Border.Background>
                                            <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                                                <GradientStop Color="#331B2C6E" Offset="0"/>
                                                <GradientStop Color="#1A0E1F44" Offset="1"/>
                                            </LinearGradientBrush>
                                        </Border.Background>
                                        <Border.BorderBrush>
                                            <SolidColorBrush Color="#40FFFFFF"/>
                                        </Border.BorderBrush>
                                        <Border.BorderThickness>1</Border.BorderThickness>
                                        <Border.RenderTransform>
                                            <TranslateTransform X="0" Y="0"/>
                                        </Border.RenderTransform>
                                        <Grid>
                                            <Ellipse Width="10" Height="10" Fill="#8FF5E9" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="15,0,0,0"/>
                                            <Ellipse Width="10" Height="10" Fill="#00E5D0" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,15,0"/>
                                            <Rectangle Height="3" Fill="#8B6BFF" Margin="30,0,30,0" RadiusX="1.5" RadiusY="1.5"/>
                                        </Grid>
                                    </Border>
                                    <TextBlock x:Name="EmptyTitle" Text="Öffne ein Place in Roblox Studio" Foreground="{StaticResource TextMain}" FontSize="21" FontWeight="Bold" TextAlignment="Center" Margin="0,22,0,0"/>
                                    <TextBlock x:Name="EmptyBody" Text="Sobald sich ein Studio-Fenster mit einem geladenen Place verbindet, erscheint es hier automatisch." Foreground="{StaticResource TextMuted}" FontSize="13.5" TextAlignment="Center" TextWrapping="Wrap" Margin="0,10,0,0"/>
                                </StackPanel>
                                <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="14" Margin="0,0,0,0">
                                    <StackPanel x:Name="PlaceList"/>
                                </ScrollViewer>
                            </Grid>
                            <Border Grid.Row="1" Background="#12FFFFFF" BorderBrush="#1FFFFFFF" BorderThickness="0,1,0,0" Padding="14,10,14,12">
                                <Button x:Name="ArenaAiButton" Width="178" Height="40" HorizontalAlignment="Right"
                                        Background="{StaticResource GreenBtnBg}" BorderBrush="#4DFFFFFF" BorderThickness="1"
                                        Foreground="#FFFFFF" ToolTip="Arena AI im Browser öffnen">
                                    <Button.Content>
                                        <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center">
                                            <TextBlock Text="&#xE71B;" FontFamily="Segoe MDL2 Assets" FontSize="13" Foreground="#FFFFFF" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                            <TextBlock Text="Arena AI öffnen" Foreground="#FFFFFF" VerticalAlignment="Center"/>
                                        </StackPanel>
                                    </Button.Content>
                                </Button>
                            </Border>
                        </Grid>
                    </Grid>
                </Border>

                <!-- ============================================================ -->
                <!-- KOPIER-BESTAETIGUNG (Version 3.9)                            -->
                <!-- Kein Popup, keine Windows-Sprechblase: nur ein kleiner       -->
                <!-- Hinweis unten im Fenster, der nach ein paar Sekunden von     -->
                <!-- allein ausblendet (Version 6.0: als Glas-Pille mit sanftem   -->
                <!-- Hochgleiten).                                                -->
                <!-- ============================================================ -->
                <Border x:Name="CopyConfirm" Panel.ZIndex="60" Visibility="Collapsed" Opacity="0"
                        HorizontalAlignment="Center" VerticalAlignment="Bottom" Margin="0,0,0,14"
                        Background="#E61B2B52" BorderBrush="#6600D0BE" BorderThickness="1" CornerRadius="14"
                        Padding="16,10,18,10">
                    <Border.RenderTransform>
                        <TranslateTransform X="0" Y="10"/>
                    </Border.RenderTransform>
                    <Border.Effect>
                        <DropShadowEffect Color="#6600A89C" BlurRadius="18" ShadowDepth="0" Opacity="0.55"/>
                    </Border.Effect>
                    <StackPanel Orientation="Horizontal">
                        <TextBlock Text="&#x2713;" Foreground="#5CFFEF" FontSize="15" FontWeight="Bold"
                                   VerticalAlignment="Center" Margin="0,0,10,0"/>
                        <TextBlock x:Name="CopyConfirmText" Text="Prompt wurde in die Zwischenablage kopiert"
                                   Foreground="#F0F6FF" FontSize="13" VerticalAlignment="Center"/>
                    </StackPanel>
                </Border>

                <!-- ============================================================ -->
                <!-- STARTBILDSCHIRM (Version 3.4): Ladekreisel mit Fortschritt.  -->
                <!-- Version 6.0: halbtransparentes Glas - die Aurora-Lichter     -->
                <!-- scheinen waehrend des Starts lebendig hindurch.              -->
                <!-- ============================================================ -->
                <Border x:Name="SplashScreen" Panel.ZIndex="70" Background="#EE0A1030" CornerRadius="16" ClipToBounds="True">
                    <Grid>
                        <StackPanel HorizontalAlignment="Center" VerticalAlignment="Center" Width="400" Margin="0,-10,0,0">
                            <Grid Width="86" Height="86" Margin="0,0,0,24" HorizontalAlignment="Center">
                                <Ellipse Stroke="#26FFFFFF" StrokeThickness="6"/>
                                <Ellipse x:Name="SplashSpinnerArc" Stroke="#00E5D0" StrokeThickness="6" StrokeDashArray="44 158" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5">
                                    <Ellipse.Effect>
                                        <DropShadowEffect Color="#9900E5D0" BlurRadius="14" ShadowDepth="0" Opacity="0.85"/>
                                    </Ellipse.Effect>
                                    <Ellipse.RenderTransform>
                                        <RotateTransform Angle="0"/>
                                    </Ellipse.RenderTransform>
                                </Ellipse>
                                <Grid Width="32" Height="30" HorizontalAlignment="Center" VerticalAlignment="Center">
                                    <Ellipse Width="7" Height="7" Fill="#AFF7EC" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="1,0,0,0"/>
                                    <Ellipse Width="7" Height="7" Fill="#E8FBFF" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,1,0"/>
                                    <Rectangle Height="2.6" Fill="#00E5D0" Margin="11,0,11,0" RadiusX="1.3" RadiusY="1.3"/>
                                </Grid>
                            </Grid>
                            <TextBlock x:Name="SplashHeadline" Text="Arena Roblox Bridge startet …" Foreground="{StaticResource TextMain}" FontSize="19" FontWeight="Bold" TextAlignment="Center"/>
                            <TextBlock x:Name="SplashSub" Text="Alles wird automatisch vorbereitet - du musst nichts tun." Foreground="{StaticResource TextMuted}" FontSize="12.5" TextAlignment="Center" TextWrapping="Wrap" Margin="0,9,0,24"/>
                            <Border CornerRadius="13" Background="#33101838" BorderBrush="#26FFFFFF" BorderThickness="1" Padding="18,14">
                                <StackPanel>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <Ellipse x:Name="SplashStudioDot" Grid.Column="0" Width="9" Height="9" Fill="#8FA3CC" Margin="0,0,12,0" VerticalAlignment="Center"/>
                                        <TextBlock Grid.Column="1" Text="Roblox Studio" Foreground="#DCE6FF" FontSize="13.5" VerticalAlignment="Center"/>
                                        <TextBlock x:Name="SplashStudioState" Grid.Column="2" Text="Wird geprüft …" Foreground="#9AA9CE" FontSize="12" VerticalAlignment="Center"/>
                                    </Grid>
                                    <Border Height="1" Background="#1FFFFFFF" Margin="0,11,0,11"/>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <Ellipse x:Name="SplashPluginDot" Grid.Column="0" Width="9" Height="9" Fill="#8FA3CC" Margin="0,0,12,0" VerticalAlignment="Center"/>
                                        <TextBlock Grid.Column="1" Text="Studio-Plugin" Foreground="#DCE6FF" FontSize="13.5" VerticalAlignment="Center"/>
                                        <TextBlock x:Name="SplashPluginState" Grid.Column="2" Text="Wartet …" Foreground="#9AA9CE" FontSize="12" VerticalAlignment="Center"/>
                                    </Grid>
                                    <Border Height="1" Background="#1FFFFFFF" Margin="0,11,0,11"/>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <Ellipse x:Name="SplashBlenderDot" Grid.Column="0" Width="9" Height="9" Fill="#8FA3CC" Margin="0,0,12,0" VerticalAlignment="Center"/>
                                        <TextBlock Grid.Column="1" Text="Blender (Mesh-Bau)" Foreground="#DCE6FF" FontSize="13.5" VerticalAlignment="Center"/>
                                        <TextBlock x:Name="SplashBlenderState" Grid.Column="2" Text="Wartet …" Foreground="#9AA9CE" FontSize="12" VerticalAlignment="Center" Cursor="Hand" ToolTip="Blender erneut pruefen (echte Faehigkeitsprobe)"/>
                                    </Grid>
                                    <Border Height="1" Background="#1FFFFFFF" Margin="0,11,0,11"/>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <Ellipse x:Name="SplashTunnelDot" Grid.Column="0" Width="9" Height="9" Fill="#8FA3CC" Margin="0,0,12,0" VerticalAlignment="Center"/>
                                        <TextBlock Grid.Column="1" Text="Cloudflare-Tunnel" Foreground="#DCE6FF" FontSize="13.5" VerticalAlignment="Center"/>
                                        <TextBlock x:Name="SplashTunnelState" Grid.Column="2" Text="Wartet …" Foreground="#9AA9CE" FontSize="12" VerticalAlignment="Center"/>
                                    </Grid>
                                </StackPanel>
                            </Border>
                        </StackPanel>
                    </Grid>
                </Border>
            </Grid>
        </Grid>
    </Border>
</Window>
'@

# Version 7.2.6 (START-NETZ KOMPLETT): Der Fensterbau liegt jetzt IM try/catch.
# Vorher konnte ein Fehler in XamlReader::Load, FindName oder der
# Ereignis-Verdrahtung den Prozess lautlos beenden - kein Fenster, kein Log.
Set-StartupStage 'Fensteraufbau: XAML wird geladen'
try {
$reader = [System.Xml.XmlNodeReader]::new([xml]$xaml)
$window = [Windows.Markup.XamlReader]::Load($reader)
$script:MainWindow = $window

$window.Dispatcher.add_UnhandledException({
    param($sender, $eventArgs)
    try {
        Write-RuntimeLog "UI Fehler: $($eventArgs.Exception.Message)"
    } catch {}
    $eventArgs.Handled = $true
})

$TitleBar        = $window.FindName('TitleBar')
$SplashScreen    = $window.FindName('SplashScreen')
$CopyConfirm     = $window.FindName('CopyConfirm')
$CopyConfirmText = $window.FindName('CopyConfirmText')
$SplashHeadline  = $window.FindName('SplashHeadline')
$SplashSub       = $window.FindName('SplashSub')
$SplashStudioDot    = $window.FindName('SplashStudioDot')
$SplashStudioState  = $window.FindName('SplashStudioState')
$SplashPluginDot    = $window.FindName('SplashPluginDot')
$SplashPluginState  = $window.FindName('SplashPluginState')
$SplashBlenderDot   = $window.FindName('SplashBlenderDot')
$SplashBlenderState = $window.FindName('SplashBlenderState')
# Version 7.4.1: "Blender pruefen" wiederholt die ECHTE Faehigkeitsprobe
# (nicht nur das Lesen der Version) - im Hintergrund, ohne Einfrieren.
try {
    $SplashBlenderState.Add_MouseLeftButtonUp({
        try {
            if (-not (Start-BlenderRecheck -Shared $script:Shared)) { Write-RuntimeLog 'Blender-Pruefung laeuft bereits - kein zweiter Lauf.' }
        } catch { try { Write-RuntimeLog ('Blender-Pruefung aus dem Startbildschirm fehlgeschlagen: ' + $_.Exception.Message) } catch {} }
    })
} catch { }
$SplashTunnelDot    = $window.FindName('SplashTunnelDot')
$SplashTunnelState  = $window.FindName('SplashTunnelState')
$PlaceList       = $window.FindName('PlaceList')
$EmptyState      = $window.FindName('EmptyState')
$EmptyTitle      = $window.FindName('EmptyTitle')
$EmptyBody       = $window.FindName('EmptyBody')
$PlacesCountText = $window.FindName('PlacesCountText')
$PlaceListStatusText = $window.FindName('PlaceListStatusText')
$LiveBadge       = $window.FindName('LiveBadge')
$LiveDot         = $window.FindName('LiveDot')
$LiveText        = $window.FindName('LiveText')
$SettingsButton  = $window.FindName('SettingsButton')
$ArenaAiButton   = $window.FindName('ArenaAiButton')
$UpdateBadge     = $window.FindName('UpdateBadge')
$MinimizeButton  = $window.FindName('MinimizeButton')
$CloseButton     = $window.FindName('CloseButton')
$PulseDot        = $window.FindName('PulseDot')
$RootShell       = $window.FindName('RootShell')
Set-StartupStage 'Fensteraufbau: fertig (FindName)'

# ----------------------------------------------------------------------------
# KLEINE MITTEILUNGEN (ersetzen die alte Fusszeile)
# Jede Mitteilung hat einen Balken, der zeigt, wann sie wieder verschwindet.
# ----------------------------------------------------------------------------
$script:ToastMax = 4

function Remove-Toast {
    param($Card)
    try {
        $state = $Card.Tag
        if ($state.Removing) { return }
        $state.Removing = $true
        $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(1, 0, [System.TimeSpan]::FromMilliseconds(240))
        $move = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 10, [System.TimeSpan]::FromMilliseconds(240))
        $Card.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fade)
        if ($Card.RenderTransform -is [System.Windows.Media.TranslateTransform]) {
            $Card.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $move)
        }
        $cleanup = [System.Windows.Threading.DispatcherTimer]::new()
        $cleanup.Interval = [System.TimeSpan]::FromMilliseconds(320)
        # WICHTIG: KeineClosure auf lokale Variablen - Event-Handler in
        # PowerShell sehen lokale Variablen einer Funktion nicht. Alles wird
        # ueber den Sender ($s) und dessen Tag uebergeben.
        $cleanup.Tag = $Card
        $cleanup.Add_Tick({
            param($s, $e)
            $s.Stop()
            try { $script:ToastHost.Children.Remove($s.Tag) } catch {}
        })
        $cleanup.Start()
    } catch {}
}

function Show-Toast {
    # Version 3.7: Popup-Nachrichten unten rechts sind ENTFERNT.
    # Die Funktion bleibt als leerer Stummel erhalten, damit alle alten
    # Aufrufstellen weiterlaufen, ohne etwas anzuzeigen.
    param(
        [string]$Message,
        [string]$Kind = 'Info',
        [double]$Seconds = 4.5
    )
    return
    try {
        if ($null -eq $script:ToastHost) { return }

        switch ($Kind) {
            'Success' { $accent = '#22C55E'; $edge = '#1F6B45' }
            'Warn'    { $accent = '#F59E0B'; $edge = '#7A5A16' }
            'Error'   { $accent = '#F87171'; $edge = '#475569' }
            default   { $accent = '#6366F1'; $edge = '#334155' }
        }

        while ($script:ToastHost.Children.Count -ge $script:ToastMax) {
            Remove-Toast $script:ToastHost.Children[0]
            $script:ToastHost.Children.RemoveAt(0)
        }

        $card = [System.Windows.Controls.Border]::new()
        $card.Width = 336
        $card.CornerRadius = [System.Windows.CornerRadius]::new(13)
        $card.Background = Get-Brush '#0E1C34'
        $card.BorderBrush = Get-Brush $edge
        $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.Padding = [System.Windows.Thickness]::new(14, 12, 14, 11)
        $card.Margin = [System.Windows.Thickness]::new(0, 9, 0, 0)
        $card.Effect = New-Shadow -Blur 18 -Opacity 0.45
        $card.Opacity = 0
        $transform = [System.Windows.Media.TranslateTransform]::new(0, 16)
        $card.RenderTransform = $transform
        $card.Tag = [pscustomobject]@{ Removing = $false }

        $grid = [System.Windows.Controls.Grid]::new()
        $r1 = [System.Windows.Controls.RowDefinition]::new(); $r1.Height = [System.Windows.GridLength]::Auto
        $r2 = [System.Windows.Controls.RowDefinition]::new(); $r2.Height = [System.Windows.GridLength]::Auto
        $grid.RowDefinitions.Add($r1)
        $grid.RowDefinitions.Add($r2)

        $top = [System.Windows.Controls.Grid]::new()
        $dotCol = [System.Windows.Controls.ColumnDefinition]::new(); $dotCol.Width = [System.Windows.GridLength]::Auto
        $textCol = [System.Windows.Controls.ColumnDefinition]::new()
        $top.ColumnDefinitions.Add($dotCol)
        $top.ColumnDefinitions.Add($textCol)

        $dot = [System.Windows.Shapes.Ellipse]::new()
        $dot.Width = 9
        $dot.Height = 9
        $dot.Fill = Get-Brush $accent
        $dot.VerticalAlignment = 'Top'
        $dot.Margin = [System.Windows.Thickness]::new(0, 4, 11, 0)
        [System.Windows.Controls.Grid]::SetColumn($dot, 0)

        $text = [System.Windows.Controls.TextBlock]::new()
        $text.Text = $Message
        $text.Foreground = Get-Brush '#CBD5E1'
        $text.FontSize = 12.5
        $text.TextWrapping = 'Wrap'
        $text.Width = 286
        [System.Windows.Controls.Grid]::SetColumn($text, 1)

        $top.Children.Add($dot) | Out-Null
        $top.Children.Add($text) | Out-Null
        [System.Windows.Controls.Grid]::SetRow($top, 0)
        $grid.Children.Add($top) | Out-Null

        $track = [System.Windows.Controls.Border]::new()
        $track.Height = 3
        $track.Width = 296
        $track.CornerRadius = [System.Windows.CornerRadius]::new(1.5)
        $track.Background = Get-Brush '#1E293B'
        $track.HorizontalAlignment = 'Left'
        $track.Margin = [System.Windows.Thickness]::new(0, 11, 0, 0)
        [System.Windows.Controls.Grid]::SetRow($track, 1)

        $fill = [System.Windows.Controls.Border]::new()
        $fill.Height = 3
        $fill.Width = 296
        $fill.CornerRadius = [System.Windows.CornerRadius]::new(1.5)
        $fill.Background = Get-Brush $accent
        $fill.HorizontalAlignment = 'Left'
        $scale = [System.Windows.Media.ScaleTransform]::new(1, 1)
        $fill.RenderTransform = $scale
        $fill.RenderTransformOrigin = [System.Windows.Point]::new(0, 0.5)
        $track.Child = $fill
        $grid.Children.Add($track) | Out-Null

        $card.Child = $grid
        $script:ToastHost.Children.Add($card) | Out-Null

        # Einblenden
        $ease = [System.Windows.Media.Animation.CubicEase]::new()
        $ease.EasingMode = 'EaseOut'
        $inOpacity = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(220))
        $inMove = [System.Windows.Media.Animation.DoubleAnimation]::new(16, 0, [System.TimeSpan]::FromMilliseconds(280))
        $inMove.EasingFunction = $ease
        $card.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $inOpacity)
        $transform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $inMove)

        # Balken leert sich - danach verschwindet die Mitteilung
        $bar = [System.Windows.Media.Animation.DoubleAnimation]::new(1, 0, [System.TimeSpan]::FromSeconds($Seconds))
        $scale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $bar)

        $timer = [System.Windows.Threading.DispatcherTimer]::new()
        $timer.Interval = [System.TimeSpan]::FromSeconds($Seconds)
        $timer.Tag = $card
        $timer.Add_Tick({
            param($s, $e)
            $s.Stop()
            Remove-Toast $s.Tag
        })
        $timer.Start()
    } catch {}
}

# Mitteilungen, die beim Start angezeigt werden sollen (Fenster ist dann sichtbar)
$script:PendingToasts = New-Object System.Collections.Generic.List[object]

function Add-PendingToast {
    # Version 3.7: Popup-Nachrichten sind entfernt - Stummel ohne Funktion.
    param([string]$Message, [string]$Kind = 'Info', [double]$Seconds = 5)
    # (bewusst leer)
}

# ----------------------------------------------------------------------------
# AUSWAHLMENUE ("..." Button)
# ----------------------------------------------------------------------------
function Set-MenuChecked {
    param($Item, [bool]$Checked)
    # Version 5.0.2: $null-fest - ohne Auswahlmenue gibt es keinen Toggle.
    if ($null -eq $Item -or -not $Item.Checkable) { return }
    # Version 5: this is deliberately a switch, never a checkbox. Read-only
    # is an immediate, temporary session state just like the settings switches.
    if ($Checked) {
        $Item.Track.Background = Get-Brush '#CC1FA34A'; $Item.Track.BorderBrush = Get-Brush '#662FCB6C'
        $Item.State.Text = 'AN'; $Item.State.Foreground = Get-Brush '#D9FFE9'; $Item.State.Margin = [System.Windows.Thickness]::new(0,0,12,0)
    } else {
        $Item.Track.Background = Get-Brush '#59E11D48'; $Item.Track.BorderBrush = Get-Brush '#73FF5C77'
        $Item.State.Text = 'AUS'; $Item.State.Foreground = Get-Brush '#FFC7D3'; $Item.State.Margin = [System.Windows.Thickness]::new(12,0,0,0)
    }
    # Version 6.0: Der Schalter-Daumen gleitet weich (TranslateTransform).
    # Der Daumen bleibt layout-statisch (links, Rand 3) - die Bewegung ist
    # reine Optik. Schlaegt die Animation fehl, bleibt alles voll bedienbar.
    try {
        if ($null -ne $Item.Thumb.RenderTransform -and $Item.Thumb.RenderTransform -is [System.Windows.Media.TranslateTransform]) {
            $toX = 0.0
            if ($Checked) { $toX = 22.0 }
            $slide = [System.Windows.Media.Animation.DoubleAnimation]::new($toX, [System.TimeSpan]::FromMilliseconds(150))
            $slideEase = [System.Windows.Media.Animation.CubicEase]::new()
            $slideEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $slide.EasingFunction = $slideEase
            $Item.Thumb.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $slide)
        }
    } catch {}
}

function New-MenuRow {
    param(
        [string]$Glyph,
        [string]$Title,
        [string]$Subtitle,
        [string]$Accent = '#5CFFEF',
        [bool]$Checkable = $false,
        [bool]$Checked = $false
    )

    $item = [pscustomobject]@{
        Checkable = $Checkable
        Track     = $null
        Thumb     = $null
        State     = $null
        Title     = $null
        Sub       = $null
    }

    $root = [System.Windows.Controls.Border]::new()
    $root.CornerRadius = [System.Windows.CornerRadius]::new(10)
    $root.Background = [System.Windows.Media.Brushes]::Transparent
    $root.Padding = [System.Windows.Thickness]::new(9, 8, 9, 8)
    $root.Cursor = [System.Windows.Input.Cursors]::Hand

    # Version 6.0: Der Hover-Zustand ist ein ueberlagertes Aufhell-Element,
    # dessen Opacity weich animiert wird (kein hartes Umschalten der Farbe).
    $layer = [System.Windows.Controls.Grid]::new()
    $hoverBg = [System.Windows.Controls.Border]::new()
    $hoverBg.CornerRadius = [System.Windows.CornerRadius]::new(10)
    $hoverBg.Background = Get-Brush '#47FFFFFF'
    $hoverBg.Opacity = 0
    $hoverBg.IsHitTestVisible = $false
    $null = $layer.Children.Add($hoverBg)

    $grid = [System.Windows.Controls.Grid]::new()
    $c0 = [System.Windows.Controls.ColumnDefinition]::new(); $c0.Width = [System.Windows.GridLength]::new(34)
    $c1 = [System.Windows.Controls.ColumnDefinition]::new()
    $c2 = [System.Windows.Controls.ColumnDefinition]::new(); $c2.Width = [System.Windows.GridLength]::Auto
    $grid.ColumnDefinitions.Add($c0)
    $grid.ColumnDefinitions.Add($c1)
    $grid.ColumnDefinitions.Add($c2)

    $iconBox = [System.Windows.Controls.Border]::new()
    $iconBox.Width = 34
    $iconBox.Height = 34
    $iconBox.CornerRadius = [System.Windows.CornerRadius]::new(10)
    $iconBox.Background = Get-Brush '#30FFFFFF'
    $iconBox.BorderBrush = Get-Brush '#26FFFFFF'
    $iconBox.BorderThickness = [System.Windows.Thickness]::new(1)
    $iconText = [System.Windows.Controls.TextBlock]::new()
    $iconText.Text = $Glyph
    $iconText.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe MDL2 Assets')
    $iconText.FontSize = 14
    $iconText.Foreground = Get-Brush $Accent
    $iconText.HorizontalAlignment = 'Center'
    $iconText.VerticalAlignment = 'Center'
    $iconBox.Child = $iconText

    $texts = [System.Windows.Controls.StackPanel]::new()
    $texts.VerticalAlignment = 'Center'
    $texts.Margin = [System.Windows.Thickness]::new(11, 0, 8, 0)
    $titleBlock = [System.Windows.Controls.TextBlock]::new()
    $titleBlock.Text = $Title
    $titleBlock.Foreground = Get-Brush '#FFFFFF'
    $titleBlock.FontSize = 13
    $titleBlock.FontWeight = 'SemiBold'
    $subBlock = [System.Windows.Controls.TextBlock]::new()
    $subBlock.Text = $Subtitle
    $subBlock.Foreground = Get-Brush '#D9D2F5'
    $subBlock.FontSize = 11
    $subBlock.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)
    $texts.Children.Add($titleBlock) | Out-Null
    $texts.Children.Add($subBlock) | Out-Null
    $item.Title = $titleBlock
    $item.Sub = $subBlock

    [System.Windows.Controls.Grid]::SetColumn($iconBox, 0)
    [System.Windows.Controls.Grid]::SetColumn($texts, 1)
    $grid.Children.Add($iconBox) | Out-Null
    $grid.Children.Add($texts) | Out-Null

    if ($Checkable) {
        $switch = [System.Windows.Controls.Grid]::new()
        $switch.Width = 46; $switch.Height = 24; $switch.VerticalAlignment = 'Center'
        $track = [System.Windows.Controls.Border]::new(); $track.Width=46; $track.Height=24; $track.CornerRadius=[System.Windows.CornerRadius]::new(12); $track.BorderThickness=[System.Windows.Thickness]::new(1)
        $thumb = [System.Windows.Shapes.Ellipse]::new(); $thumb.Width=18; $thumb.Height=18; $thumb.Fill=Get-Brush '#F2F7FF'; $thumb.VerticalAlignment='Center'
        $thumb.HorizontalAlignment = 'Left'
        $thumb.Margin = [System.Windows.Thickness]::new(3,0,0,0)
        $thumb.RenderTransform = [System.Windows.Media.TranslateTransform]::new(0, 0)
        try { $thumb.Effect = New-Shadow -Blur 6 -Opacity 0.45 } catch {}
        $state = [System.Windows.Controls.TextBlock]::new(); $state.FontSize=8.5; $state.FontWeight='Bold'; $state.HorizontalAlignment='Center'; $state.VerticalAlignment='Center'; $state.IsHitTestVisible=$false
        $switch.Children.Add($track)|Out-Null;$switch.Children.Add($thumb)|Out-Null;$switch.Children.Add($state)|Out-Null
        $item.Track=$track;$item.Thumb=$thumb;$item.State=$state
        Set-MenuChecked $item $Checked
        [System.Windows.Controls.Grid]::SetColumn($switch, 2)
        $grid.Children.Add($switch) | Out-Null
    }

    $null = $layer.Children.Add($grid)
    $root.Child = $layer
    $root.Add_MouseEnter({
        param($s, $e)
        try {
            $hover = $s.Child.Children[0]
            $show = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(120))
            $hover.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $show)
        } catch {}
    })
    $root.Add_MouseLeave({
        param($s, $e)
        try {
            $hover = $s.Child.Children[0]
            $hide = [System.Windows.Media.Animation.DoubleAnimation]::new(0, [System.TimeSpan]::FromMilliseconds(160))
            $hover.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $hide)
        } catch {}
    })

    $item | Add-Member -MemberType NoteProperty -Name 'Root' -Value $root -Force
    return $item
}

function New-Separator {
    $sep = [System.Windows.Controls.Border]::new()
    $sep.Height = 1
    $sep.Background = Get-Brush '#26FFFFFF'
    $sep.Margin = [System.Windows.Thickness]::new(9, 5, 9, 5)
    return $sep
}





# ----------------------------------------------------------------------------
# NAMEN DER PLACES
# Roblox Studio meldet direkt nach dem Start häufig nur den Standardnamen
# eines leeren Place ("place4", "Baseplate"), obwohl der Fenstertitel schon
# den echten Namen zeigt. Deshalb gilt:
#   1. Ein vom Plugin gemeldeter, vollständiger Name hat immer Vorrang.
#   2. Ist der gemeldete Name nur ein Standardname, wird der Titel eines
#      Roblox-Studio-Fensters benutzt - und dieser Titel gehört danach fest
#      zu dieser Sitzung (kein Hin- und Herspringen zwischen zwei Fenstern).
#   3. Die Fenstertitel werden nur alle 4 Sekunden gelesen (weniger Last).
# ----------------------------------------------------------------------------

# ----------------------------------------------------------------------------
# Version 7.0.0: PLACE-IDENTITAET STATT ANZEIGENAME
# Live-Bug: zwei Places (z. B. "Obby" und "Place1") waren offen, in der Liste
# standen aber zweimal "Obby" mit derselben Vorschau - egal wie oft man neu
# oeffnete. Ursache war eine Kette von Namens-Schluesseln: die Sitzungs-
# Wiederverwendung in Register-Session durfte ueber placeId=0 + gleichem Namen
# eine LEBENDE Fremdsitzung uebernehmen, die Vorschau-Zuordnung verglich nur
# Fenstertitel, und Get-PlaceName verlieh freie Titel aus EINER gemeinsamen
# Fensterliste an beliebige Zeilen. Ab 7.0.0 gilt: der Zeilen-Schluessel ist
# die Plugin-Session; die Fensterbindung ist PID + HWND und wird exklusiv
# beansprucht; der Anzeigename ist nur noch ein Etikett dieser Identitaet.
# ----------------------------------------------------------------------------
function Get-NormalizedPlaceName {
    # Fenstertitel sind KEIN Place-Name, sondern eine Behauptung. Hier werden
    # Studio-Suffixe, Skript-Segmente ("- local script"), ungespeichert-Marker
    # und Platzhalter entfernt. Rueckgabe: leerer String, wenn nichts Gutes
    # uebrig bleibt - dann wird NIE geraten.
    param([string]$Title)
    if ([string]::IsNullOrWhiteSpace($Title)) { return '' }
    $value = (Repair-Mojibake $Title).Trim()
    # Roblox-Studio-Suffixe (rechts) in beliebiger Reihenfolge abtragen
    for ($i = 0; $i -lt 6; $i++) {
        $before = $value
        $value = $value -replace '\s*[-–—|]\s*Roblox\s*Studio(\s*Beta)?\s*$', ''
        $value = $value -replace '\s*[-–—|]\s*Studio\s*$', ''
        $value = $value -replace '\s*[-–—|]\s*$', ''
        $value = $value.Trim()
        if ($value -eq $before) { break }
    }
    # Skript-Segmente: "- local script", "- Script", "- ModuleScript",
    # "- LocalScript", "Script: Foo", "(LocalScript)" ...
    $scriptWord = '(?:local\s*script|localscript|module\s*script|modulescript|script|luau|code)'
    for ($i = 0; $i -lt 4; $i++) {
        $before = $value
        $value = $value -replace ("(?i)^\s*" + $scriptWord + "\s*[-–—:]\s*"), ''
        $value = $value -replace ("(?i)\s*[-–—|:]\s*" + $scriptWord + "\s*$"), ''
        $value = $value -replace ("(?i)\s*[\(\[]\s*" + $scriptWord + "\s*[\)\]]\s*$"), ''
        $value = $value.Trim()
        if ($value -eq $before) { break }
    }
    # ungespeichert-Marker und Platzhalter
    $value = $value -replace '(?i)\s*[-–—|]\s*ungespeichert(es)?\s*(place|spiel)?\s*$', ''
    $value = $value -replace '(?i)\s*[\(\[]\s*(ungespeichert|unsaved)\s*[\)\]]\s*$', ''
    $value = $value -replace '(?i)^\s*(neues?\s+place|new\s+place|untitled(\s+place)?|unbenannt(es)?(\s+place)?|baseplate|place\s*\d*)\s*$', ''
    $value = $value.Trim()
    if ($value -match '(?i)Roblox\s*Studio') { return '' }
    if (Test-StandardPlaceName $value) { return '' }
    return $value
}

function Get-PlaceNameQuality {
    # Kleine, ehrliche Qualitaetsstufe - ein einmal erkannter GUTER Name darf
    # nie durch einen schlechteren ueberschrieben werden.
    # 0 = unbrauchbar, 1 = Fallback-Titel, 2 = sauberer Titel/Place-Name.
    param([string]$Name, [string]$Source)
    if ([string]::IsNullOrWhiteSpace($Name)) { return 0 }
    if (Test-StandardPlaceName $Name) { return 0 }
    if ($Source -eq 'plugin') { return 2 }
    if ($Source -eq 'windowTitle' -and $Name -match '\s') { return 1 }
    return 2
}

function Save-PlaceName {
    # Schreibt Name + Herkunft nur, wenn der neue Name nicht SCHLECHTER ist.
    param([string]$SessionId, [string]$Name, [string]$Source)
    if ([string]::IsNullOrWhiteSpace($SessionId) -or [string]::IsNullOrWhiteSpace($Name)) { return $false }
    $clean = $Name.Trim()
    $old = [string]''
    if ($script:PlaceNames.ContainsKey($SessionId)) { $old = [string]$script:PlaceNames[$SessionId] }
    $oldSource = [string]''
    if ($script:PlaceNameSources.ContainsKey($SessionId)) { $oldSource = [string]$script:PlaceNameSources[$SessionId] }
    $oldQuality = Get-PlaceNameQuality $old $oldSource
    $newQuality = Get-PlaceNameQuality $clean $Source
    if ($newQuality -le 0) { return $false }
    if ($oldQuality -gt $newQuality) { return $false }
    if ($oldQuality -eq $newQuality -and $old -eq $clean) { return $false }
    $script:PlaceNames[$SessionId] = $clean
    $script:PlaceNameSources[$SessionId] = $Source
    return $true
}

function Get-PlaceIdentity {
    # Stabile Identitaet einer Zeile: Plugin-Session + placeId + (falls
    # gebunden) PID/HWND. Der Anzeigename ist NUR ein Etikett.
    param([string]$SessionId)
    $identity = $null
    if ($script:PlaceIdentities.ContainsKey($SessionId)) { $identity = $script:PlaceIdentities[$SessionId] }
    if ($null -eq $identity) {
        $identity = [pscustomobject]@{
            SessionKey = [string]$SessionId
            PlaceId    = ''
            InstanceGuid = ''
            ProcessId  = 0
            WindowHandle = [IntPtr]::Zero
            WindowTitle = ''
            Name       = ''
            NameSource = ''
            BoundAt    = [DateTime]::MinValue
            BindReason = ''
        }
        $script:PlaceIdentities[$SessionId] = $identity
    }
    return $identity
}

function Save-PlaceIdentity {
    param([string]$SessionId, $Studio, $WindowInfo, [string]$Reason)
    $identity = Get-PlaceIdentity $SessionId
    if ($null -ne $Studio) {
        try { $identity.PlaceId = [string]$Studio.placeId } catch {}
        try { $identity.InstanceGuid = [string]$Studio.instanceGuid } catch {}
    }
    if ($null -ne $WindowInfo) {
        try { $identity.ProcessId = [int]$WindowInfo.ProcessId } catch { $identity.ProcessId = 0 }
        try { $identity.WindowHandle = [IntPtr]$WindowInfo.Handle } catch { $identity.WindowHandle = [IntPtr]::Zero }
        try { $identity.WindowTitle = [string]$WindowInfo.Title } catch { $identity.WindowTitle = '' }
        $identity.BoundAt = Get-Date
    }
    $identity.Name = [string]$script:PlaceNames[$SessionId]
    if ($script:PlaceNameSources.ContainsKey($SessionId)) { $identity.NameSource = [string]$script:PlaceNameSources[$SessionId] }
    if ($null -ne $identity.PSObject.Properties['BindReason']) {
        $identity.BindReason = [string]$Reason
    } else {
        $identity | Add-Member -NotePropertyName 'BindReason' -NotePropertyValue ([string]$Reason) -Force
    }
    return $identity
}

function Get-PlaceIdentityKey {
    # Der Schluessel, an dem eine Zeile in Diagnose und Logs haengt:
    # PID+HWND wenn gebunden, sonst die Plugin-Session (+placeId).
    param([string]$SessionId)
    $identity = Get-PlaceIdentity $SessionId
    if ($identity.ProcessId -gt 0 -and $identity.WindowHandle -ne [IntPtr]::Zero) {
        return ('pid{0}:hwnd{1}|{2}' -f $identity.ProcessId, $identity.WindowHandle.ToInt64(), $SessionId)
    }
    if (-not [string]::IsNullOrWhiteSpace($identity.PlaceId)) { return ('session:{0}|place:{1}' -f $SessionId, $identity.PlaceId) }
    return ('session:' + [string]$SessionId)
}

function Resolve-PlaceWindowIdentity {
    # Bindet eine Sitzung an GENAU EIN Studio-Fenster (PID + HWND) und
    # verhindert, dass zwei Zeilen dasselbe Fenster beanspruchen. Der
    # Anzeigename dient nur als Hinweis, nie als Schluessel.
    param($Studio, [string]$SessionId)
    $identity = Save-PlaceIdentity $SessionId $Studio $null 'lookup'
    $infos = @(Get-StudioWindowInfos)
    if ($infos.Count -eq 0) { return $identity }
    # 1) bereits gebunden und das Fenster existiert noch -> dabei bleiben.
    if ($identity.ProcessId -gt 0 -and $identity.WindowHandle -ne [IntPtr]::Zero) {
        foreach ($info in $infos) {
            if ([IntPtr]$info.Handle -eq [IntPtr]$identity.WindowHandle) {
                Save-PlaceIdentity $SessionId $Studio $info 'gebunden' | Out-Null
                return (Get-PlaceIdentity $SessionId)
            }
        }
    }
    # 2) Kandidat ueber den normalisierten Namen suchen - aber nur Fenster,
    #    die noch KEINE andere Sitzung beansprucht und nicht bereits vergeben.
    $wanted = ''
    if ($script:PlaceNames.ContainsKey($SessionId)) { $wanted = Get-NormalizedPlaceName ([string]$script:PlaceNames[$SessionId]) }
    if (-not [string]::IsNullOrWhiteSpace($wanted)) {
        foreach ($info in $infos) {
            $normalized = Get-NormalizedPlaceName ([string]$info.Title)
            if ([string]::IsNullOrWhiteSpace($normalized)) { continue }
            if ($normalized -ne $wanted) { continue }
            if (Test-PreviewHandleClaimed $info.Handle $SessionId) { continue }
            $script:PreviewHandleClaims[[int64]$info.Handle] = $SessionId
            Save-PlaceIdentity $SessionId $Studio $info 'titelExakt' | Out-Null
            return (Get-PlaceIdentity $SessionId)
        }
    }
    # 3) Einziges Fenster -> binden, unabhaengig vom Namen (Beweis: PID+HWND).
    if ($infos.Count -eq 1 -and -not (Test-PreviewHandleClaimed $infos[0].Handle $SessionId)) {
        $script:PreviewHandleClaims[[int64]$infos[0].Handle] = $SessionId
        Save-PlaceIdentity $SessionId $Studio $infos[0] 'einzelnesFenster' | Out-Null
        return (Get-PlaceIdentity $SessionId)
    }
    return $identity
}

function Test-PreviewHandleClaimed {
    param($Handle, [string]$ForSession)
    $key = [int64]$Handle
    if (-not $script:PreviewHandleClaims.ContainsKey($key)) { return $false }
    $owner = [string]$script:PreviewHandleClaims[$key]
    if ([string]::IsNullOrWhiteSpace($owner)) { return $false }
    if ($owner -eq [string]$ForSession) { return $false }
    # Besitzer tot? Dann freigeben (Fenster geschlossen / Session weg).
    if (-not $script:PlaceIdentities.ContainsKey($owner)) { return $false }
    $ownerIdentity = $script:PlaceIdentities[$owner]
    if ([IntPtr]$ownerIdentity.WindowHandle -eq [IntPtr]$Handle) { return $true }
    return $false
}

function Write-PlacesDiagnoseFile {
    # Beweis-Datei fuer den Mehrfach-Places-Bug: je erkanntem Studio-Fenster
    # PID, HWND, Fenstertitel, erkannter Place-Name und zugewiesener
    # Zeilen-Schluessel - plus die Namenquelle und die Handle-Besitzer.
    param([switch]$Force)
    if (-not $Force -and ((Get-Date) - $script:PlacesDiagLastWrite).TotalSeconds -lt 5) { return }
    $script:PlacesDiagLastWrite = Get-Date
    try {
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine('Arena Roblox Bridge - Place-Diagnose (Version 7.4.1)')
        [void]$sb.AppendLine(('Zeit: {0:yyyy-MM-dd HH:mm:ss}' -f (Get-Date)))
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine('STUDIO-FENSTER (PID + HWND = stabile Identitaet)')
        $infos = @(Get-StudioWindowInfos)
        if ($infos.Count -eq 0) { [void]$sb.AppendLine('  (keine Roblox-Studio-Fenster gefunden)') }
        foreach ($info in $infos) {
            $owner = ''
            $key = [int64]$info.Handle
            if ($script:PreviewHandleClaims.ContainsKey($key)) { $owner = [string]$script:PreviewHandleClaims[$key] }
            $normalized = Get-NormalizedPlaceName ([string]$info.Title)
            if ([string]::IsNullOrWhiteSpace($normalized)) { $normalized = '(kein brauchbarer Name)' }
            [void]$sb.AppendLine(('  PID={0} HWND={1} Titel="{2}" -> normalisiert="{3}" Besitzer={4}' -f $info.ProcessId, $key, [string]$info.Title, $normalized, $(if ($owner) { $owner } else { '(frei)' })))
        }
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine('ZEILEN (Plugin-Session = Schluessel; Name ist nur ein Etikett)')
        foreach ($pair in $script:Shared.Sessions.GetEnumerator()) {
            try {
                $item = $pair.Value | ConvertFrom-Json
                $sid = [string]$item.sessionId
                $identity = Get-PlaceIdentity $sid
                $name = ''
                if ($script:PlaceNames.ContainsKey($sid)) { $name = [string]$script:PlaceNames[$sid] }
                $source = ''
                if ($script:PlaceNameSources.ContainsKey($sid)) { $source = [string]$script:PlaceNameSources[$sid] }
                [void]$sb.AppendLine(('  Zeile={0} placeId={1} instance={2} PID={3} HWND={4} Name="{5}" Quelle={6} Plugin-Stand={7}' -f `
                    (Get-PlaceIdentityKey $sid), [string]$item.placeId, [string]$item.instanceGuid, $identity.ProcessId, $(if ($identity.WindowHandle -ne [IntPtr]::Zero) { $identity.WindowHandle.ToInt64() } else { 0 }), $name, $(if ($source) { $source } else { '(offen)' }), [string]$item.pluginVersion))
            } catch {}
        }
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine('FORTSCHRITT')
        foreach ($line in (Get-ProgressDiagnoseLines)) { [void]$sb.AppendLine([string]$line) }
        if ($script:HandoffDiagnoseLines.Count -gt 0) {
            [void]$sb.AppendLine('')
            [void]$sb.AppendLine('UEBERGABEN')
            foreach ($line in $script:HandoffDiagnoseLines.ToArray()) { [void]$sb.AppendLine('  ' + [string]$line) }
        }
        $path = Join-Path $script:AppDataRoot 'places-diagnose.txt'
        [System.IO.File]::WriteAllText($path, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
    } catch {
        Write-RuntimeLog ('places-diagnose.txt konnte nicht geschrieben werden: ' + $_.Exception.Message)
    }
}


# ----------------------------------------------------------------------------
# Version 7.0.0: FORTSCHRITT IN DER PLACE-ZEILE
# BLAU = laeuft (ausdruecklich gewuenscht, NICHT ins Pink-Schema umbiegen),
# GRUEN = fertig (nur nach report_done), GRAU = wartet/keine Rueckmeldung,
# ROT = Fehler. Alles nur in der Zeile - keine Toasts, keine Popups.
# ----------------------------------------------------------------------------
function Get-ProgressStateSnapshotForId {
    # Version 7.2.0: dieselbe Auswertung wie bisher, aber um die Felder
    # erweitert, die fuer "keine erfundene 0 %" noetig sind: PercentKnown
    # (hat die KI ueberhaupt schon eine Zahl geschickt?), CallsWithPercent und
    # LastTool.
    param([string]$SessionId)
    $json = ''
    if (-not $script:Shared.ProgressStates.TryGetValue([string]$SessionId, [ref]$json)) { return $null }
    if ([string]::IsNullOrWhiteSpace($json)) { return $null }
    $state = $null
    try { $state = $json | ConvertFrom-Json } catch { return $null }
    if ($null -eq $state) { return $null }
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    $lastCall = [int64]$state.lastCallAt
    if ($lastCall -le 0) { $lastCall = [int64]$state.updatedAt }
    $silent = ($now - $lastCall)
    $percentKnown = $false
    try { if ($state.PSObject.Properties['percentKnown']) { $percentKnown = [bool]$state.percentKnown } } catch {}
    if (-not $percentKnown) {
        try { if ([double]$state.percent -gt 0) { $percentKnown = $true } } catch {}
    }
    $callsWithPercent = 0
    try { if ($state.PSObject.Properties['callsWithPercent']) { $callsWithPercent = [int]$state.callsWithPercent } } catch {}
    $callsWithoutPercent = 0
    try { if ($state.PSObject.Properties['callsWithoutPercent']) { $callsWithoutPercent = [int]$state.callsWithoutPercent } } catch {}
    $lastTool = ''
    try { if ($state.PSObject.Properties['lastTool']) { $lastTool = [string]$state.lastTool } } catch {}
    $view = [pscustomobject]@{
        SessionId = [string]$SessionId
        Percent = [double]$state.percent
        PercentKnown = $percentKnown
        Message = [string]$state.message
        State   = [string]$state.state
        AutoSet = [bool]$state.autoSet
        UpdatedAt = [int64]$state.updatedAt
        LastCallAt = $lastCall
        SilentSeconds = $silent
        Calls = [int]$state.calls
        CallsWithProgress = [int]$state.callsWithProgress
        CallsWithPercent = $callsWithPercent
        CallsWithoutPercent = $callsWithoutPercent
        LastTool = $lastTool
    }
    # Nach einer Minute ohne Bridge-Aufruf: Fortschritt ehrlich einfrieren
    # und grau markieren. Eine abgeschlossene 100-%-Meldung bleibt separat
    # noch eine Minute gruen sichtbar und wird danach in der UI ausgeblendet.
    if ($silent -ge 60 -and $view.State -ne 'done') {
        $view.State = 'waiting'
        $view.Message = 'Seit über einer Minute kein Bridge Aufruf mehr'
    }
    return $view
}

function Get-ProgressStateSnapshot {
    # Version 7.2.0: Die Zeile traegt die Sitzung aus der Fensterliste, der
    # Fortschritt wird aber unter der Token-Sitzung geschrieben. Nach einer
    # Sitzungsuebergabe (Reconnect/Nachfolger) las die Zeile deshalb eine andere
    # Id als die, unter der die Arbeit laeuft - der Balken blieb leer, waehrend
    # Arena baute. Jetzt werden alle Kandidaten geprueft (eigene Id, Nachfolger
    # und jede Id, die auf diese Zeile zeigt) und der FRISCHESTE Zustand gewinnt.
    param([string]$SessionId)
    $sid = [string]$SessionId
    if ([string]::IsNullOrWhiteSpace($sid)) { return $null }
    $candidates = New-Object System.Collections.Generic.List[string]
    $candidates.Add($sid)
    try {
        $delivery = Get-UiDeliverySession $sid
        if (-not [string]::IsNullOrWhiteSpace($delivery) -and -not $candidates.Contains($delivery)) { $candidates.Add($delivery) }
    } catch {}
    try {
        foreach ($pair in $script:Shared.ProgressStates.GetEnumerator()) {
            $other = [string]$pair.Key
            if ([string]::IsNullOrWhiteSpace($other) -or $candidates.Contains($other)) { continue }
            $resolved = ''
            try { $resolved = Get-UiDeliverySession $other } catch {}
            if ($resolved -eq $sid) { $candidates.Add($other) }
        }
    } catch {}
    $best = $null
    $bestCall = [int64](-1)
    foreach ($candidate in $candidates) {
        $view = Get-ProgressStateSnapshotForId $candidate
        if ($null -eq $view) { continue }
        $callAt = [int64]$view.LastCallAt
        if ($null -eq $best -or $callAt -gt $bestCall) { $best = $view; $bestCall = $callAt }
    }
    return $best
}

function Format-ProgressMessage {
    param($Snapshot)
    if ($null -eq $Snapshot) { return '' }
    if ([string]$Snapshot.State -eq 'waiting') { return 'Seit über einer Minute kein Bridge Aufruf mehr' }
    $msg = [string]$Snapshot.Message
    if ([string]::IsNullOrWhiteSpace($msg)) { $msg = 'Arena arbeitet gerade...' }
    if ($Snapshot.State -eq 'waiting' -and $msg -notmatch '(?i)wartet') { $msg = 'wartet auf Arena / keine Rueckmeldung - ' + $msg }
    return $msg
}

function Get-UiDeliverySession {
    # Version 7.0.7: Die Oberflaeche hat KEINEN Zugriff auf die Funktionen des
    # Server-Runspaces (Get-DeliverySession liegt in $script:BridgeHandlerScript).
    # Der Nachfolger-Pfad steht aber im gemeinsamen Zustand - den liest die UI
    # hier direkt, genau mit derselben Regel (max. 8 Hops, kein Zyklus).
    param([string]$SessionId)
    $current = [string]$SessionId
    for ($hop = 0; $hop -lt 8; $hop++) {
        $next = $null
        try {
            if (-not $script:Shared.SessionSuccessors.TryGetValue($current, [ref]$next)) { break }
        } catch { break }
        $next = [string]$next
        if ([string]::IsNullOrWhiteSpace($next) -or $next -eq $current) { break }
        $current = $next
    }
    return $current
}

function Write-FlowTrace {
    # Version 7.2.0: dieselbe Stations-Schreibweise wie auf der Server-Seite
    # (Write-FlowStation im Handler-Runspace), aber fuer die Oberflaeche. Beide
    # Seiten schreiben bewusst dasselbe Zeilenformat:
    #   <BEREICH> [<flowId>] <STATION> feld=wert feld=wert
    # Vorbild sind die PREVIEW-Stationen aus 6.0.4, die das Raten beendet haben.
    param([string]$Area, [string]$FlowId, [string]$Station, $Fields = $null)
    $line = ''
    try {
        $parts = New-Object System.Collections.Generic.List[string]
        if ($Fields -is [System.Collections.IDictionary]) {
            foreach ($key in $Fields.Keys) {
                $value = $Fields[$key]
                if ($null -eq $value) { $value = '-' }
                $text = ([string]$value) -replace '[\r\n\t]+', ' '
                if ($text.Length -gt 200) { $text = $text.Substring(0, 199) + '...' }
                $parts.Add(([string]$key + '=' + $text))
            }
        }
        $line = ([string]$Area).ToUpperInvariant() + ' [' + [string]$FlowId + '] ' + ([string]$Station).ToUpperInvariant()
        if ($parts.Count -gt 0) { $line = $line + ' ' + ($parts.ToArray() -join ' ') }
        Write-RuntimeLog $line
        $cap = 500
        try { $cap = [int]$script:Shared.FlowTraceCap } catch {}
        if ($cap -lt 20) { $cap = 20 }
        try {
            $script:Shared.FlowTrace.Enqueue(('{0:u} ' -f (Get-Date)) + $line)
            $discard = $null
            while ($script:Shared.FlowTrace.Count -gt $cap) {
                if (-not $script:Shared.FlowTrace.TryDequeue([ref]$discard)) { break }
            }
        } catch {}
    } catch {}
    # Bewusst KEIN return: eine Ausgabe hier wuerde z. B. Add-UserMessage einen
    # Array statt der Nachrichten-Id zurueckgeben lassen.
}

function Add-UiChannelCount {
    # Version 7.2.0: Zaehler im gemeinsamen Zustand, von der Oberflaeche aus.
    param([string]$Name, [long]$Delta = 1)
    try {
        $channel = $script:Shared.Channel
        if ($null -eq $channel -or [string]::IsNullOrWhiteSpace($Name)) { return }
        $existing = $null
        if ($channel.ContainsKey($Name)) { $existing = $channel[$Name] }
        if ($existing -is [long] -or $existing -is [int]) { $channel[$Name] = ([long]$existing + [long]$Delta) }
        else { $channel[$Name] = [long]$Delta }
    } catch {}
}

function Set-UiChannelText {
    param([string]$Name, [string]$Value)
    try {
        $channel = $script:Shared.Channel
        if ($null -eq $channel) { return }
        $channel[$Name] = [string]$Value
    } catch {}
}

function Set-UiMessageField {
    # Feld an einem aus JSON gelesenen Objekt schreiben, ohne in die
    # PowerShell-5.1-Falle "The property cannot be found on this object" zu laufen.
    param($Object, [string]$Name, $Value)
    try {
        if ($null -eq $Object) { return }
        if ($Object.PSObject.Properties[$Name]) { $Object.$Name = $Value }
        else { $Object | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force }
    } catch {}
}

function Get-UiShortErrorReason {
    param($ErrorRecord, [string]$Fallback = 'Unbekannter Speicherfehler')
    $reason = ''
    try {
        if ($null -ne $ErrorRecord -and $null -ne $ErrorRecord.Exception) { $reason = [string]$ErrorRecord.Exception.Message }
        elseif ($ErrorRecord -is [System.Exception]) { $reason = [string]$ErrorRecord.Message }
        elseif ($null -ne $ErrorRecord) { $reason = [string]$ErrorRecord }
    } catch {}
    $reason = ($reason -replace '[\r\n\t]+', ' ').Trim()
    if ([string]::IsNullOrWhiteSpace($reason)) { $reason = $Fallback }
    if ($reason.Length -gt 180) { $reason = $reason.Substring(0, 177).TrimEnd() + '...' }
    return $reason
}

function Get-UserMessageStateForUi {
    # Version 7.2.0: liest denselben JSON-Zustand wie der Server
    # (Read-UserMessageState im Handler-Runspace). Die Oberflaeche hat keinen
    # Zugriff auf Server-Funktionen, deshalb dieselbe Regel hier noch einmal -
    # exakt wie bei Get-UiDeliverySession/Get-PlaceOpenCommand seit 7.0.6/7.0.7.
    param([string]$SessionId)
    $json = ''
    try {
        if (-not $script:Shared.UserMessages.TryGetValue([string]$SessionId, [ref]$json)) { return $null }
    } catch { return $null }
    if ([string]::IsNullOrWhiteSpace($json)) { return $null }
    try { return ($json | ConvertFrom-Json) } catch { return $null }
}

function Get-UserMessageUiList {
    param($State)
    $items = New-Object System.Collections.Generic.List[object]
    try {
        if ($null -ne $State -and $State.PSObject.Properties['messages']) {
            foreach ($entry in $State.messages) { $items.Add($entry) }
        }
    } catch {}
    return ,$items
}

function Add-UiBridgeEvent {
    # Version 7.2.0: dieselbe Ereignis-Queue wie Add-BridgeEvent im
    # Handler-Runspace ($Shared.Events), von der Oberflaeche aus befuellt - die
    # UI hat keinen Zugriff auf Server-Funktionen, wohl aber auf $Shared.
    param([string]$SessionId, [string]$Kind, [string]$Message, $Data = $null)
    try {
        if ([string]::IsNullOrWhiteSpace($SessionId)) { return }
        $queue = $null
        if (-not $script:Shared.Events.TryGetValue([string]$SessionId, [ref]$queue) -or $null -eq $queue) {
            $created = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
            [void]$script:Shared.Events.TryAdd([string]$SessionId, $created)
            $queue = $null
            [void]$script:Shared.Events.TryGetValue([string]$SessionId, [ref]$queue)
            if ($null -eq $queue) { $queue = $created }
        }
        $event = @{
            kind    = [string]$Kind
            message = [string]$Message
            time    = (Get-Date).ToString('u')
            data    = $Data
        }
        $queue.Enqueue(($event | ConvertTo-Json -Depth 12 -Compress))
        $dropped = $null
        while ($queue.Count -gt 60) {
            if (-not $queue.TryDequeue([ref]$dropped)) { break }
        }
    } catch {}
}

function Add-UserMessage {
    # Version 7.2.0: "Nachricht an Arena senden" (Menuepunkt in der Place-Zeile).
    # Legt die Nachricht in den gemeinsamen Zustand; ausgeliefert wird sie mit
    # dem Umschlag der NAECHSTEN Arena-Anfrage (at-least-once, max. 3 Versuche).
    # Rueckgabe: die Nachrichten-Id, oder $null bei Ablehnung.
    param([string]$SessionId, [string]$Text, [string]$Kind = 'note')
    $script:UserMessageUiLastError = ''
    if ([string]::IsNullOrWhiteSpace($SessionId)) {
        $script:UserMessageUiLastError = 'Die verbundene Sitzung fehlt.'
        return $null
    }
    $clean = ([string]$Text).Trim()
    if ([string]::IsNullOrWhiteSpace($clean)) {
        $script:UserMessageUiLastError = 'Die Nachricht ist leer.'
        return $null
    }
    if ($clean.Length -gt 4000) { $clean = $clean.Substring(0, 4000) }
    $kindValue = ([string]$Kind).Trim().ToLowerInvariant()
    if ($kindValue -notin @('note', 'correction', 'stop', 'question')) { $kindValue = 'note' }
    $messageId = 'msg_' + ([guid]::NewGuid().ToString('N').Substring(0, 12))
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    try {
        [System.Threading.Monitor]::Enter($script:Shared.UserMessageLock)
        $state = Get-UserMessageStateForUi $SessionId
        if ($null -eq $state) {
            $state = [pscustomobject]@{ messages = @(); updatedAt = $now }
        }
        $list = Get-UserMessageUiList $state
        # 7.2.4 (3d): fehlende Liste anlegen statt $list.Add() auf $null. Ein
        # $null hier wuerde die Nachricht still verschlucken und dem Nutzer nur
        # "konnte nicht gespeichert werden" sagen.
        if ($null -eq $list) { $list = New-Object System.Collections.Generic.List[object] }
        $entry = [pscustomobject]@{
            id            = $messageId
            text          = $clean
            kind          = $kindValue
            createdAt     = $now
            state         = 'queued'
            attempts      = 0
            deliveredAt   = 0
            deliveredWith = ''
            ackAt         = 0
            withdrawnAt   = 0
        }
        $list.Add($entry)
        # Begrenzen: die letzten 20 Nachrichten, erledigte aelter als 30 Minuten
        # fallen raus. Sonst waechst der Zustand unbegrenzt (Lehre aus 7.1.2).
        $kept = New-Object System.Collections.Generic.List[object]
        $cutoff = $now - 1800
        foreach ($message in $list) {
            $messageState = ''
            try { $messageState = [string]$message.state } catch {}
            $messageAt = [int64]0
            try { $messageAt = [int64]$message.createdAt } catch {}
            if (($messageState -eq 'acked' -or $messageState -eq 'withdrawn') -and $messageAt -lt $cutoff) { continue }
            $kept.Add($message)
        }
        while ($kept.Count -gt 20) { $kept.RemoveAt(0) }
        Set-UiMessageField $state 'messages' $kept.ToArray()
        Set-UiMessageField $state 'updatedAt' $now
        $script:Shared.UserMessages[[string]$SessionId] = ($state | ConvertTo-Json -Depth 12 -Compress)
    } catch {
        $script:UserMessageUiLastError = Get-UiShortErrorReason $_ 'Die Nachricht konnte nicht in der Bridge abgelegt werden.'
        Write-UiErrorLog 'Nachricht an Arena konnte nicht gespeichert werden' $_
        return $null
    }
    finally { try { [System.Threading.Monitor]::Exit($script:Shared.UserMessageLock) } catch {} }
    Add-UiChannelCount 'UserMessagesQueued' 1
    Write-FlowTrace 'USERMSG' $messageId 'QUEUED' @{ sid = $SessionId; kind = $kindValue; chars = $clean.Length }
    # wait_for_user wecken: wartet die KI gerade, kommt die Nachricht sofort an.
    try {
        $signal = $null
        if ($script:Shared.UserSignals.TryGetValue([string]$SessionId, [ref]$signal) -and $null -ne $signal) {
            try { [void]$signal.Set() } catch {}
        }
    } catch {}
    Add-UiBridgeEvent $SessionId 'user_message' ('The user sent a message during the session: ' + $clean) @{ kind = $kindValue; messageId = $messageId }
    return $messageId
}

function Withdraw-UserMessage {
    # "Abbrechen" im Nachricht-Fenster. Ehrlich: zurueckziehen geht NUR, solange
    # die Nachricht noch in der Queue liegt (state=queued). Hat eine
    # Arena-Anfrage sie bereits mitgenommen, ist sie technisch unterwegs - dann
    # liefert diese Funktion $false und das Fenster sagt das auch.
    param([string]$SessionId, [string]$MessageId)
    if ([string]::IsNullOrWhiteSpace($SessionId) -or [string]::IsNullOrWhiteSpace($MessageId)) { return $false }
    $withdrawn = $false
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    try {
        [System.Threading.Monitor]::Enter($script:Shared.UserMessageLock)
        $state = Get-UserMessageStateForUi $SessionId
        if ($null -ne $state) {
            $list = Get-UserMessageUiList $state
            foreach ($message in $list) {
                $id = ''
                try { $id = [string]$message.id } catch {}
                if ($id -ne [string]$MessageId) { continue }
                $messageState = ''
                try { $messageState = [string]$message.state } catch {}
                if ($messageState -ne 'queued') { break }
                Set-UiMessageField $message 'state' 'withdrawn'
                Set-UiMessageField $message 'withdrawnAt' $now
                $withdrawn = $true
                break
            }
            if ($withdrawn) {
                Set-UiMessageField $state 'updatedAt' $now
                $script:Shared.UserMessages[[string]$SessionId] = ($state | ConvertTo-Json -Depth 12 -Compress)
            }
        }
    } catch {
        Write-UiErrorLog 'Nachricht konnte nicht zurueckgezogen werden' $_
    }
    finally { try { [System.Threading.Monitor]::Exit($script:Shared.UserMessageLock) } catch {} }
    if ($withdrawn) {
        Add-UiChannelCount 'UserMessagesWithdrawn' 1
        Write-FlowTrace 'USERMSG' $MessageId 'WITHDRAWN' @{ sid = $SessionId }
    } else {
        Write-FlowTrace 'USERMSG' $MessageId 'WITHDRAW_TOO_LATE' @{ sid = $SessionId }
    }
    return $withdrawn
}

function Get-UserMessageUiViews {
    # Alle Nachrichten einer Sitzung fuer das Nachricht-Fenster und die Zeile.
    # Gibt eine echte List[object] zurueck (kein @() am Aufrufer noetig).
    param([string]$SessionId)
    $views = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrWhiteSpace($SessionId)) { return ,$views }
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    $list = Get-UserMessageUiList (Get-UserMessageStateForUi $SessionId)
    foreach ($message in $list) {
        $messageState = ''
        try { $messageState = [string]$message.state } catch {}
        if ($messageState -eq 'withdrawn') { continue }
        $createdAt = [int64]0
        try { $createdAt = [int64]$message.createdAt } catch {}
        $deliveredAt = [int64]0
        try { $deliveredAt = [int64]$message.deliveredAt } catch {}
        $attempts = 0
        try { $attempts = [int]$message.attempts } catch {}
        $deliveredWith = ''
        try { $deliveredWith = [string]$message.deliveredWith } catch {}
        $statusText = 'wird gesendet'
        $statusCode = 'queued'
        if ($messageState -eq 'acked') { $statusText = 'von Arena bestaetigt'; $statusCode = 'acked' }
        elseif ($messageState -eq 'delivered') {
            if ($attempts -ge 3) { $statusText = 'angekommen, nicht bestaetigt'; $statusCode = 'delivered_unacked' }
            else { $statusText = 'angekommen'; $statusCode = 'delivered' }
        }
        $ageSeconds = 0
        if ($createdAt -gt 0 -and $now -ge $createdAt) { $ageSeconds = [int]($now - $createdAt) }
        $views.Add([pscustomobject]@{
            id            = $(try { [string]$message.id } catch { '' })
            text          = $(try { [string]$message.text } catch { '' })
            kind          = $(try { [string]$message.kind } catch { 'note' })
            createdAt     = $createdAt
            ageSeconds    = $ageSeconds
            state         = $messageState
            statusCode    = $statusCode
            statusText    = $statusText
            attempts      = $attempts
            deliveredAt   = $deliveredAt
            deliveredWith = $deliveredWith
            canWithdraw   = ($messageState -eq 'queued')
        })
    }
    return ,$views
}

function Format-UserMessageAge {
    # Kleine, ehrliche Zeitangabe fuer das Nachricht-Fenster.
    param([int]$Seconds)
    if ($Seconds -lt 0) { $Seconds = 0 }
    if ($Seconds -lt 60) { return ([string]$Seconds + ' s') }
    $minutes = [int][Math]::Floor($Seconds / 60)
    if ($minutes -lt 60) { return ([string]$minutes + ' min') }
    return ([string][int][Math]::Floor($minutes / 60) + ' h')
}

function Get-UserMessageAckReply {
    # Die Kurzantwort, die Arena beim Bestaetigen mitgeschickt hat
    # (ack_user_message { reply = '...' }).
    param([string]$SessionId)
    try {
        $state = Get-UserMessageStateForUi $SessionId
        if ($null -ne $state -and $state.PSObject.Properties['lastAckReply']) { return [string]$state.lastAckReply }
    } catch {}
    return ''
}

function Get-UserMessageBadgeText {
    # Version 7.2.0: unauffaelliger Zaehler fuer die Place-Zeile (D8). Kein
    # neues Feld in der Zeile, keine Farbe, kein Blinken - die Zahl steht im
    # Tooltip des Fortschritts und im Menue.
    param([string]$SessionId)
    try {
        $views = Get-UserMessageUiViews $SessionId
        $waiting = 0
        $acked = 0
        foreach ($view in $views) {
            $code = [string]$view.statusCode
            if ($code -eq 'queued') { $waiting = $waiting + 1 }
            elseif ($code -eq 'delivered' -or $code -eq 'delivered_unacked') { $waiting = $waiting + 1 }
            elseif ($code -eq 'acked') { $acked = $acked + 1 }
        }
        if ($waiting -eq 0 -and $acked -eq 0) { return '' }
        if ($waiting -gt 0) {
            if ($waiting -eq 1) { return '1 Nachricht liegt fuer Arena bereit' }
            return ([string]$waiting + ' Nachrichten liegen fuer Arena bereit')
        }
        if ($acked -eq 1) { return '1 Nachricht von Arena bestaetigt' }
        return ([string]$acked + ' Nachrichten von Arena bestaetigt')
    } catch { return '' }
}

function Update-UserMessageWindow {
    # Zustand des Fensters aus dem gemeinsamen JSON ziehen (D8):
    #   wird gesendet -> angekommen -> von Arena bestaetigt
    # und ehrlich sagen, wann Arena gar nichts abholt.
    param($Info)
    try {
        if ($null -eq $Info) { return }
        $sessionId = [string]$Info.SessionId
        $messageId = [string]$Info.MessageId
        $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()

        # Verlauf der bisherigen Nachrichten dieser Sitzung.
        $historyLines = New-Object System.Collections.Generic.List[string]
        $views = Get-UserMessageUiViews $sessionId
        foreach ($view in $views) {
            $text = [string]$view.text
            if ($text.Length -gt 90) { $text = $text.Substring(0, 89) + '...' }
            $when = ''
            try { $when = ([DateTimeOffset]::FromUnixTimeSeconds([int64]$view.createdAt).LocalDateTime.ToString('HH:mm:ss')) } catch {}
            $historyLines.Add(([string]$view.statusCode + '  ' + $when + '  ' + $text))
        }
        if ($historyLines.Count -eq 0) { $Info.History.Text = 'Noch keine Nachricht in dieser Sitzung.' }
        else { $Info.History.Text = ($historyLines.ToArray() -join [Environment]::NewLine) }

        # Wie lange hat Arena ueberhaupt nichts mehr gefragt?
        $silentSeconds = 0
        try {
            $snapshot = Get-ProgressStateSnapshot $sessionId
            if ($null -ne $snapshot) { $silentSeconds = [int]$snapshot.SilentSeconds }
        } catch {}

        if ([string]::IsNullOrWhiteSpace($messageId)) {
            $Info.Status.Text = 'Noch nicht gesendet. Arena bekommt die Nachricht mit ihrer naechsten Anfrage - die Bridge kann nicht in den Arena-Chat schreiben.'
            $Info.Status.Foreground = Get-Brush '#9AA9CE'
            $Info.SendButton.IsEnabled = ($Info.TextBox.Text.Trim().Length -gt 0)
            $Info.CancelButton.IsEnabled = $false
            $Info.CancelButton.Content = 'Abbrechen'
            return
        }

        $current = $null
        foreach ($view in $views) { if ([string]$view.id -eq $messageId) { $current = $view } }
        # Zurueckgezogene Nachrichten erscheinen nicht mehr im Verlauf.
        if ($null -eq $current) {
            if ([string]$Info.LastState -eq 'withdrawn') {
                $Info.Status.Text = 'ZURUECKGEZOGEN - Arena hat die Nachricht nie bekommen.'
                $Info.Status.Foreground = Get-Brush '#FFB4C4'
                $Info.SendButton.IsEnabled = ($Info.TextBox.Text.Trim().Length -gt 0)
                $Info.CancelButton.IsEnabled = $false
                $Info.CancelButton.Content = 'Abbrechen'
            } else {
                $Info.Status.Text = 'Die Nachricht ist nicht mehr auffindbar (Sitzung zurueckgesetzt?).'
                $Info.Status.Foreground = Get-Brush '#9AA9CE'
            }
            return
        }

        $age = 0
        try { $age = [int]$current.ageSeconds } catch {}
        $code = [string]$current.statusCode
        $clock = ''
        try { $clock = ([DateTimeOffset]::FromUnixTimeSeconds([int64]$current.createdAt).LocalDateTime.ToString('HH:mm:ss')) } catch {}
        $text = ''
        if ($code -eq 'queued') {
            $text = ('wird gesendet - liegt seit ' + (Format-UserMessageAge $age) + ' bereit (gesendet ' + $clock + ').')
            if ($silentSeconds -ge 45) {
                $text = $text + ' Arena hat seit ' + (Format-UserMessageAge $silentSeconds) + ' keine Anfrage gestellt - die Nachricht kommt mit der naechsten.'
            }
            $Info.Status.Foreground = Get-Brush '#FFD9A0'
            $Info.SendButton.IsEnabled = $false
            $Info.CancelButton.IsEnabled = $true
            $Info.CancelButton.Content = 'Abbrechen'
        } elseif ($code -eq 'delivered') {
            $tool = [string]$current.deliveredWith
            if ([string]::IsNullOrWhiteSpace($tool)) { $tool = 'einer Arena-Anfrage' }
            $text = ('angekommen - mitgenommen von ' + $tool + '. Du kannst das Fenster jetzt schliessen.')
            $Info.Status.Foreground = Get-Brush '#9FDCFF'
            $Info.SendButton.IsEnabled = $false
            $Info.CancelButton.IsEnabled = $true
            $Info.CancelButton.Content = 'Schliessen'
        } elseif ($code -eq 'delivered_unacked') {
            $text = 'angekommen, aber von Arena nicht bestaetigt - sie wird noch bis zu drei Antworten wiederholt.'
            $Info.Status.Foreground = Get-Brush '#FFD9A0'
            $Info.SendButton.IsEnabled = $false
            $Info.CancelButton.IsEnabled = $true
            $Info.CancelButton.Content = 'Schliessen'
        } elseif ($code -eq 'acked') {
            $reply = Get-UserMessageAckReply $sessionId
            $text = 'von Arena bestaetigt.'
            if (-not [string]::IsNullOrWhiteSpace($reply)) { $text = $text + ' Antwort: ' + $reply }
            $Info.Status.Foreground = Get-Brush '#38D16C'
            $Info.SendButton.IsEnabled = ($Info.TextBox.Text.Trim().Length -gt 0)
            $Info.CancelButton.IsEnabled = $true
            $Info.CancelButton.Content = 'Schliessen'
        } else {
            $text = ('Zustand: ' + $code)
            $Info.Status.Foreground = Get-Brush '#9AA9CE'
        }
        $Info.LastState = $code
        $Info.Status.Text = $text
        if ($code -eq 'acked' -and $Info.TextBox.Text.Trim().Length -gt 0) {
            $Info.MessageId = ''
        }
    } catch {}
}

# ----------------------------------------------------------------------------
# Version 7.2.4: GEMEINSAME DIALOG-RESSOURCEN (EIN Block fuer alle Fenster)
# ----------------------------------------------------------------------------
# Anlass (Owner-Beobachtung 7.2.3): Das Fragen-Fenster und das Nachrichten-
# Fenster sahen nicht aus wie das Programm. Beide waren per Code aufgebaut
# (Border/StackPanel/Button einzeln zusammengesetzt) und nutzten eine eigene
# halbtransparente Shell (#F50B1030) sowie Mint-Toene (#5CFFEF), die es im
# Haupt- und Einstellungsfenster nirgends gibt.
#
# Referenz ist deshalb NICHT das alte Fragen-Fenster, sondern das Haupt- und
# das Einstellungsfenster: XAML-basiert, WindowStyle=None,
# AllowsTransparency=True, Background=Transparent, abgerundete Karte auf dem
# SwAppBg-Verlauf (#060A1A -> #0A1128 -> #0C1533), Karten aus SwCardBg, Text
# in SwTextMain/SwTextMuted/SwTextFaint, Trennlinien in SwLine, gefaehrliche
# Aktionen auf dem Crimson-Verlauf (#F2FF5C77 -> #E6E11D48).
#
# Dieser Block ist der EINSZIGE Ort, an dem die Dialog-Optik definiert wird.
# Das Fragen-Fenster (Open-AskWindow) und das Nachrichten-Fenster
# (Open-UserMessageWindow) fuegen ihn unveraendert in ihre
# <Window.Resources> ein (Platzhalter <!--ARENA_DIALOG_STYLES-->). Eine neue
# Farbe oder ein neuer Knopf wird hier geaendert - nicht in zwei Fenstern.
#
# Das grosse Einstellungsfenster bleibt davon bewusst unberuehrt: Es steht auf
# der Nicht-Anfassen-Liste des Owners (feste Regel 4). Seine Palette ist
# dieselbe und bleibt die Referenz.
# ----------------------------------------------------------------------------
$script:ArenaDialogStyles = @'
        <!-- ===== Arena Roblox Bridge: gemeinsame Dialog-Ressourcen (7.2.4) ===== -->
        <SolidColorBrush x:Key="SwTextMain" Color="#F4F8FF"/>
        <SolidColorBrush x:Key="SwTextMuted" Color="#9AA9CE"/>
        <SolidColorBrush x:Key="SwTextFaint" Color="#6E7FA8"/>
        <SolidColorBrush x:Key="SwLine" Color="#1FFFFFFF"/>
        <LinearGradientBrush x:Key="SwAppBg" StartPoint="0,0" EndPoint="1,1">
            <GradientStop Color="#060A1A" Offset="0"/>
            <GradientStop Color="#0A1128" Offset="0.55"/>
            <GradientStop Color="#0C1533" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="SwCardBg" StartPoint="0,0" EndPoint="0.25,1">
            <GradientStop Color="#66101838" Offset="0"/>
            <GradientStop Color="#3D0C1228" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="SwCrimsonBtnBg" StartPoint="0,0" EndPoint="0,1">
            <GradientStop Color="#F2FF5C77" Offset="0"/>
            <GradientStop Color="#E6E11D48" Offset="1"/>
        </LinearGradientBrush>
        <LinearGradientBrush x:Key="SwGreenBtnBg" StartPoint="0,0" EndPoint="0,1">
            <GradientStop Color="#F238D16C" Offset="0"/>
            <GradientStop Color="#E61F9A4C" Offset="1"/>
        </LinearGradientBrush>
        <SolidColorBrush x:Key="SwQuietBtnBg" Color="#0E1428"/>

        <!-- Grundknopf: abgerundet, mit Hover/Druck/Aus - wie im Hauptfenster. -->
        <Style x:Key="ArenaDialogButton" TargetType="Button">
            <Setter Property="Foreground" Value="{StaticResource SwTextMain}"/>
            <Setter Property="Background" Value="{StaticResource SwQuietBtnBg}"/>
            <Setter Property="BorderBrush" Value="#33FFFFFF"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Focusable" Value="True"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd" CornerRadius="9"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"
                                              Margin="{TemplateBinding Padding}" RecognizesAccessKey="True"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#66FFFFFF"/>
                                <Setter TargetName="bd" Property="Opacity" Value="0.92"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Opacity" Value="0.75"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#B3FFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="bd" Property="Opacity" Value="0.38"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <!-- Weiter / Fertig / Senden: gruen (#38D16C). -->
        <Style x:Key="ArenaPrimaryButton" TargetType="Button" BasedOn="{StaticResource ArenaDialogButton}">
            <Setter Property="Foreground" Value="#08131A"/>
            <Setter Property="Background" Value="{StaticResource SwGreenBtnBg}"/>
            <Setter Property="BorderBrush" Value="#662FCB6C"/>
        </Style>
        <!-- Abbrechen: Crimson-Verlauf (#FF5C77), dieselbe Sprache wie das X
             im Einstellungsfenster. -->
        <Style x:Key="ArenaDangerButton" TargetType="Button" BasedOn="{StaticResource ArenaDialogButton}">
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="Background" Value="{StaticResource SwCrimsonBtnBg}"/>
            <Setter Property="BorderBrush" Value="#4DFFFFFF"/>
        </Style>
        <!-- Zurueck / neutrale Aktionen: grau (#0E1428 / #9AA9CE). -->
        <Style x:Key="ArenaQuietButton" TargetType="Button" BasedOn="{StaticResource ArenaDialogButton}">
            <Setter Property="Foreground" Value="{StaticResource SwTextMuted}"/>
            <Setter Property="Background" Value="{StaticResource SwQuietBtnBg}"/>
        </Style>
        <!-- Kreuz oben rechts: rund, Crimson, mit Hover - wie im
             Einstellungsfenster, hier 32 x 32 px (gefordert: >= 28 x 28). -->
        <Style x:Key="ArenaCloseButton" TargetType="Button">
            <Setter Property="Width" Value="32"/>
            <Setter Property="Height" Value="32"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="Background" Value="{StaticResource SwCrimsonBtnBg}"/>
            <Setter Property="BorderBrush" Value="#4DFFFFFF"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Focusable" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="bd" CornerRadius="16"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#F2FF7A8C"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="#7FFFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#D9C0103A"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Textfelder: dunkle Karte, sichtbarer Caret, Fokusrahmen. -->
        <Style x:Key="ArenaTextField" TargetType="TextBox">
            <Setter Property="Foreground" Value="{StaticResource SwTextMain}"/>
            <Setter Property="Background" Value="#1A101838"/>
            <Setter Property="BorderBrush" Value="#33FFFFFF"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="10,8"/>
            <Setter Property="FontSize" Value="12.5"/>
            <Setter Property="CaretBrush" Value="#38D16C"/>
            <Setter Property="SelectionBrush" Value="#6638D16C"/>
            <Setter Property="SelectionOpacity" Value="0.5"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TextBox">
                        <Border x:Name="bd" CornerRadius="9"
                                Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}">
                            <ScrollViewer x:Name="PART_ContentHost" Margin="{TemplateBinding Padding}"
                                          VerticalScrollBarVisibility="Auto" Background="Transparent"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#4DFFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#B338D16C"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style x:Key="ArenaReadOnlyField" TargetType="TextBox" BasedOn="{StaticResource ArenaTextField}">
            <Setter Property="Foreground" Value="{StaticResource SwTextMuted}"/>
            <Setter Property="FontSize" Value="10.5"/>
            <Setter Property="IsReadOnly" Value="True"/>
            <Setter Property="CaretBrush" Value="Transparent"/>
        </Style>

        <!-- Optionen: ganze Zeile ist Treffflaeche, Auswahl ist sichtbar
             gefuellt (kein nacktes WPF-Radio auf dunklem Grund). -->
        <Style x:Key="ArenaOptionRadio" TargetType="RadioButton">
            <Setter Property="Foreground" Value="{StaticResource SwTextMain}"/>
            <Setter Property="FontSize" Value="12.5"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Margin" Value="0,3,0,3"/>
            <Setter Property="Focusable" Value="True"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RadioButton">
                        <Border x:Name="bd" CornerRadius="9" Background="#14FFFFFF"
                                BorderBrush="#1FFFFFFF" BorderThickness="1" Padding="10,8">
                            <Grid>
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto"/>
                                    <ColumnDefinition Width="*"/>
                                </Grid.ColumnDefinitions>
                                <Grid Width="18" Height="18" VerticalAlignment="Center">
                                    <Ellipse x:Name="ring" Width="18" Height="18" Fill="Transparent"
                                             Stroke="#6E7FA8" StrokeThickness="1.6"/>
                                    <Ellipse x:Name="dot" Width="9" Height="9" Fill="#38D16C" Opacity="0"/>
                                </Grid>
                                <ContentPresenter Grid.Column="1" Margin="10,0,0,0"
                                                  VerticalAlignment="Center" RecognizesAccessKey="True"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#1FFFFFFF"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="#33FFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#261FA34A"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="#662FCB6C"/>
                                <Setter TargetName="ring" Property="Stroke" Value="#38D16C"/>
                                <Setter TargetName="dot" Property="Opacity" Value="1"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#B3FFFFFF"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style x:Key="ArenaOptionCheck" TargetType="CheckBox">
            <Setter Property="Foreground" Value="{StaticResource SwTextMain}"/>
            <Setter Property="FontSize" Value="12.5"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Margin" Value="0,3,0,3"/>
            <Setter Property="Focusable" Value="True"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="CheckBox">
                        <Border x:Name="bd" CornerRadius="9" Background="#14FFFFFF"
                                BorderBrush="#1FFFFFFF" BorderThickness="1" Padding="10,8">
                            <Grid>
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto"/>
                                    <ColumnDefinition Width="*"/>
                                </Grid.ColumnDefinitions>
                                <Grid Width="18" Height="18" VerticalAlignment="Center">
                                    <Border x:Name="box" Width="18" Height="18" CornerRadius="5"
                                            Background="Transparent" BorderBrush="#6E7FA8" BorderThickness="1.6"/>
                                    <Path x:Name="check" Data="M 3.6,8.6 L 7,12 L 14,4.4" Stroke="#08131A"
                                          StrokeThickness="2.2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"
                                          HorizontalAlignment="Center" VerticalAlignment="Center" Visibility="Collapsed"/>
                                </Grid>
                                <ContentPresenter Grid.Column="1" Margin="10,0,0,0"
                                                  VerticalAlignment="Center" RecognizesAccessKey="True"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#1FFFFFFF"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="#33FFFFFF"/>
                            </Trigger>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="bd" Property="Background" Value="#261FA34A"/>
                                <Setter TargetName="bd" Property="BorderBrush" Value="#662FCB6C"/>
                                <Setter TargetName="box" Property="Background" Value="#38D16C"/>
                                <Setter TargetName="box" Property="BorderBrush" Value="#38D16C"/>
                                <Setter TargetName="check" Property="Visibility" Value="Visible"/>
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="bd" Property="BorderBrush" Value="#B3FFFFFF"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Schlanke Scrollbalken: exakt die Vorlage aus den Einstellungen,
             damit lange Frage-/Nachrichtentexte gleich aussehen. -->
        <Style TargetType="ScrollBar">
            <Setter Property="Width" Value="10"/>
            <Setter Property="MinWidth" Value="10"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="BorderBrush" Value="Transparent"/>
            <Setter Property="SnapsToDevicePixels" Value="True"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ScrollBar">
                        <Grid Margin="2,3,2,3">
                            <Border CornerRadius="5" Background="#14FFFFFF"/>
                            <Track x:Name="PART_Track" IsDirectionReversed="True" Focusable="False">
                                <Track.DecreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageUpCommand">
                                        <RepeatButton.Template>
                                            <ControlTemplate TargetType="RepeatButton">
                                                <Border Background="Transparent"/>
                                            </ControlTemplate>
                                        </RepeatButton.Template>
                                    </RepeatButton>
                                </Track.DecreaseRepeatButton>
                                <Track.IncreaseRepeatButton>
                                    <RepeatButton Command="ScrollBar.PageDownCommand">
                                        <RepeatButton.Template>
                                            <ControlTemplate TargetType="RepeatButton">
                                                <Border Background="Transparent"/>
                                            </ControlTemplate>
                                        </RepeatButton.Template>
                                    </RepeatButton>
                                </Track.IncreaseRepeatButton>
                                <Track.Thumb>
                                    <Thumb>
                                        <Thumb.Template>
                                            <ControlTemplate TargetType="Thumb">
                                                <Border x:Name="thumbBg" CornerRadius="4" Background="#38FFFFFF" Margin="1,0,1,0"/>
                                                <ControlTemplate.Triggers>
                                                    <Trigger Property="IsMouseOver" Value="True">
                                                        <Setter TargetName="thumbBg" Property="Background" Value="#5CFFFFFF"/>
                                                    </Trigger>
                                                    <Trigger Property="IsDragging" Value="True">
                                                        <Setter TargetName="thumbBg" Property="Background" Value="#8CFFFFFF"/>
                                                    </Trigger>
                                                </ControlTemplate.Triggers>
                                            </ControlTemplate>
                                        </Thumb.Template>
                                    </Thumb>
                                </Track.Thumb>
                            </Track>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
'@

function Get-UserMessageWindowXaml {
    # Version 7.2.4 (3a): Das Nachrichten-Fenster nutzt denselben gemeinsamen
    # XAML-Ressourcenblock wie das Fragen-Fenster ($script:ArenaDialogStyles).
    # Der Owner hatte ausdruecklich gemeldet, dieses Fenster habe "IMMER NOCH
    # NICHT das typische Design": Es sass auf einem halbtransparenten
    # #F50B1030-Shell statt auf dem SwAppBg-Verlauf des Programms.
    $template = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Nachricht an Arena"
        Width="480" Height="470" MinWidth="440" MinHeight="420"
        ResizeMode="NoResize" WindowStyle="None" AllowsTransparency="True"
        Background="Transparent" WindowStartupLocation="CenterOwner"
        ShowInTaskbar="False" FontFamily="Segoe UI"
        UseLayoutRounding="True" SnapsToDevicePixels="True"
        TextOptions.TextFormattingMode="Display">
    <Window.Resources>
<!--ARENA_DIALOG_STYLES-->
    </Window.Resources>
    <Border CornerRadius="20" Background="{StaticResource SwAppBg}"
            BorderBrush="#33FFFFFF" BorderThickness="1" ClipToBounds="True">
        <Grid>
            <Grid IsHitTestVisible="False">
                <Ellipse Width="420" Height="420" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="-150,-190,0,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#407B5CFF" Offset="0"/>
                            <GradientStop Color="#007B5CFF" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                </Ellipse>
                <Ellipse Width="360" Height="360" HorizontalAlignment="Right" VerticalAlignment="Bottom" Margin="0,0,-120,-140">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#2E00CFC0" Offset="0"/>
                            <GradientStop Color="#0000CFC0" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                </Ellipse>
            </Grid>

            <Grid Margin="22">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- Titelzeile: ziehbar, Kreuz oben rechts (32 x 32 px). -->
                <Grid x:Name="TitleBar" Grid.Row="0" Background="Transparent" Cursor="SizeAll">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="Nachricht an Arena" Foreground="{StaticResource SwTextMain}"
                                   FontSize="16" FontWeight="Bold"/>
                        <TextBlock x:Name="PlaceNameText" Text="Place" Foreground="{StaticResource SwTextFaint}"
                                   FontSize="10.5" Margin="0,2,0,0" TextTrimming="CharacterEllipsis"/>
                    </StackPanel>
                    <Button x:Name="CloseButton" Grid.Column="1" Style="{StaticResource ArenaCloseButton}"
                            Content="&#xE8BB;" FontFamily="Segoe MDL2 Assets" FontSize="11"
                            ToolTip="Schließen (Esc)"/>
                </Grid>

                <TextBlock Grid.Row="1" Margin="0,12,0,0"
                           Text="Deine Nachricht geht mit Arenas naechster Anfrage weiter und muss von Arena bestaetigt werden. Die Bridge schreibt nicht direkt in den Arena-Chat."
                           Foreground="{StaticResource SwTextMuted}" FontSize="10.5" TextWrapping="Wrap"/>

                <StackPanel Grid.Row="2" Margin="0,14,0,0">
                    <TextBlock Text="DEINE NACHRICHT" Foreground="{StaticResource SwTextMuted}" FontSize="9.5"
                               FontWeight="Bold" Margin="0,0,0,6"/>
                    <TextBox x:Name="MessageTextBox" Height="84" MinHeight="72" MaxLength="4000"
                             AcceptsReturn="True" TextWrapping="Wrap" TabIndex="1"
                             VerticalScrollBarVisibility="Auto" Style="{StaticResource ArenaTextField}"/>
                    <TextBlock Text="Strg+Enter sendet · Esc schließt" Foreground="{StaticResource SwTextFaint}"
                               FontSize="10" Margin="0,5,0,0"/>
                </StackPanel>

                <Grid Grid.Row="3" Margin="0,14,0,0">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>
                    <TextBlock Text="LETZTE NACHRICHTEN" Foreground="{StaticResource SwTextMuted}" FontSize="9.5"
                               FontWeight="Bold" Margin="0,0,0,6"/>
                    <TextBox x:Name="HistoryTextBox" Grid.Row="1" MinHeight="70" TabIndex="4"
                             IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto"
                             Text="Noch keine Nachricht in dieser Sitzung."
                             Style="{StaticResource ArenaReadOnlyField}"/>
                </Grid>

                <!-- 3c: ECHTER Fehlergrund im Fenster, nicht nur ein Verweis
                     auf runtime.log. Der volle Grund steht zusaetzlich im Log. -->
                <Border x:Name="StatusBorder" Grid.Row="4" Margin="0,12,0,0"
                        Background="{StaticResource SwCardBg}" BorderBrush="#2EFFFFFF"
                        BorderThickness="1" CornerRadius="10" Padding="11,8">
                    <TextBlock x:Name="StatusText" Text="Noch nicht gesendet."
                               Foreground="{StaticResource SwTextMuted}" FontSize="11" TextWrapping="Wrap"/>
                </Border>

                <StackPanel Grid.Row="5" Orientation="Horizontal" HorizontalAlignment="Right"
                            Margin="0,14,0,0">
                    <Button x:Name="SendButton" Content="Senden" MinWidth="92" MinHeight="32" TabIndex="2"
                            Padding="15,6" Margin="0,0,8,0" Style="{StaticResource ArenaPrimaryButton}"
                            IsEnabled="False"/>
                    <Button x:Name="CancelButton" Content="Abbrechen" MinWidth="98" MinHeight="32" TabIndex="3"
                            Padding="14,6" Style="{StaticResource ArenaQuietButton}" IsEnabled="False"/>
                </StackPanel>
            </Grid>
        </Grid>
    </Border>
</Window>
'@
    return $template.Replace('<!--ARENA_DIALOG_STYLES-->', [string]$script:ArenaDialogStyles)
}

function Open-UserMessageWindow {
    # Version 7.2.4: Nachrichtenfenster im echten Programm-Design (gemeinsamer
    # XAML-Ressourcenblock mit dem Fragen-Fenster). Das echte ShowDialog sperrt
    # die Hauptoberflaeche, bis der Nutzer das Fenster schliesst; die
    # Titelleiste bleibt frei verschiebbar.
    param([string]$SessionId, [string]$PlaceName = '')
    try {
        if ([string]::IsNullOrWhiteSpace($SessionId)) { return }
        if ($null -ne $script:UserMessageWindow) {
            try { $script:UserMessageWindow.Close() } catch {}
            $script:UserMessageWindow = $null
        }

        $windowXaml = Get-UserMessageWindowXaml
        $reader = [System.Xml.XmlNodeReader]::new([xml]$windowXaml)
        $win = [Windows.Markup.XamlReader]::Load($reader)
        try { $win.Owner = $window } catch {}

        $titleBar = $win.FindName('TitleBar')
        $placeLabel = $win.FindName('PlaceNameText')
        $textBox = $win.FindName('MessageTextBox')
        $historyBox = $win.FindName('HistoryTextBox')
        $statusText = $win.FindName('StatusText')
        $sendButton = $win.FindName('SendButton')
        $cancelButton = $win.FindName('CancelButton')
        $closeButton = $win.FindName('CloseButton')
        if ([string]::IsNullOrWhiteSpace($PlaceName)) { $placeLabel.Text = 'Verbundenes Place' }
        else { $placeLabel.Text = 'Place · ' + [string]$PlaceName }

        # Alle Daten haengen am Element selbst (Tag) - lokale Variablen einer
        # Funktion sind in Event-Handlern nicht zuverlaessig verfuegbar.
        $info = [pscustomobject]@{
            Window       = $win
            SessionId    = [string]$SessionId
            PlaceName    = [string]$PlaceName
            MessageId    = ''
            LastState    = ''
            FadeStarted  = $false
            TextBox      = $textBox
            History      = $historyBox
            Status       = $statusText
            SendButton   = $sendButton
            CancelButton = $cancelButton
            Timer        = $null
        }
        $win.Tag = $info
        $titleBar.Tag = $win
        $textBox.Tag = $info
        $sendButton.Tag = $info
        $cancelButton.Tag = $info
        $closeButton.Tag = $win

        # Ruhiges Einblenden (180 ms) wie im Rest des Programms - erst nachdem
        # der Inhalt einmal vollstaendig gerendert ist.
        try {
            $win.Opacity = 0
            $win.Add_ContentRendered({
                param($s, $e)
                try {
                    if ([bool]$s.Tag.FadeStarted) { return }
                    $s.Tag.FadeStarted = $true
                    $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [TimeSpan]::FromMilliseconds(180))
                    $ease = [System.Windows.Media.Animation.CubicEase]::new()
                    $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
                    $fade.EasingFunction = $ease
                    $s.BeginAnimation([System.Windows.Window]::OpacityProperty, $fade)
                } catch { try { $s.Opacity = 1 } catch {} }
                try { [void]$s.FindName('MessageTextBox').Focus() } catch {}
            })
        } catch { try { $win.Opacity = 1 } catch {} }

        $titleBar.Add_MouseLeftButtonDown({
            param($s, $e)
            if ($e.ButtonState -eq [System.Windows.Input.MouseButtonState]::Pressed) {
                try { $s.Tag.DragMove() } catch {}
            }
        })
        $closeButton.Add_Click({
            param($s, $e)
            try { $s.Tag.Close() } catch {}
        })
        # 3b: Strg+Enter sendet, Esc schliesst.
        $win.Add_PreviewKeyDown({
            param($s, $e)
            try {
                if ($e.Key -eq [System.Windows.Input.Key]::Escape) {
                    $s.Close()
                    $e.Handled = $true
                    return
                }
                $isCtrlEnter = ($e.Key -eq [System.Windows.Input.Key]::Enter -and
                    (([System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Control) -ne 0))
                if ($isCtrlEnter -and $s.Tag.SendButton.IsEnabled) {
                    $clickArgs = [System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)
                    $s.Tag.SendButton.RaiseEvent($clickArgs)
                    $e.Handled = $true
                }
            } catch {
                Write-UiErrorLog 'Tastatur im Nachricht-Fenster fehlgeschlagen' $_
            }
        })

        $textBox.Add_TextChanged({
            param($s, $e)
            $data = $s.Tag
            try { $data.SendButton.IsEnabled = ($s.Text.Trim().Length -gt 0 -and [string]$data.MessageId -eq '') } catch {}
        })
        $sendButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            try {
                $text = [string]$data.TextBox.Text
                if ([string]::IsNullOrWhiteSpace($text)) { return }
                $newId = Add-UserMessage $data.SessionId $text 'correction'
                if ([string]::IsNullOrWhiteSpace([string]$newId)) {
                    # 3c: kurzer echter Grund im Fenster, voller Grund im Log.
                    $reason = ''
                    try { $reason = [string]$script:UserMessageUiLastError } catch {}
                    if ([string]::IsNullOrWhiteSpace($reason)) { $reason = 'Die Bridge hat keine Nachrichten-ID zurueckgegeben.' }
                    $data.Status.Text = 'Die Nachricht konnte nicht gespeichert werden: ' + $reason
                    $data.Status.Foreground = Get-Brush '#FF5C77'
                    try { Write-RuntimeLog ('Nachricht-Fenster: Speichern abgelehnt - ' + $reason) } catch {}
                    return
                }
                $data.MessageId = [string]$newId
                $data.LastState = 'queued'
                $data.TextBox.Clear()
                $data.SendButton.IsEnabled = $false
                Update-UserMessageWindow $data
            } catch {
                $reason = Get-UiShortErrorReason $_ 'Unerwarteter Fehler beim Speichern.'
                try {
                    $data.Status.Text = 'Die Nachricht konnte nicht gesendet werden: ' + $reason
                    $data.Status.Foreground = Get-Brush '#FF5C77'
                } catch {}
                # 3c: Der VOLLE Grund (Typ, Meldung,StackTrace) geht ins Log.
                Write-UiErrorLog 'Nachricht konnte nicht gesendet werden' $_
            }
        })
        $cancelButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            try {
                $id = [string]$data.MessageId
                if ([string]::IsNullOrWhiteSpace($id)) {
                    try { $data.Window.Close() } catch {}
                    return
                }
                $state = [string]$data.LastState
                if ($state -eq 'queued') {
                    # Ehrliches Abbrechen: zurueckziehen geht nur, solange die
                    # Nachricht noch in der Queue liegt.
                    $withdrawn = Withdraw-UserMessage $data.SessionId $id
                    if ($withdrawn) {
                        $data.LastState = 'withdrawn'
                        $data.MessageId = ''
                        $data.Status.Text = 'ZURUECKGEZOGEN - Arena hat die Nachricht nie bekommen.'
                        $data.Status.Foreground = Get-Brush '#FFFF8296'
                        $data.SendButton.IsEnabled = ($data.TextBox.Text.Trim().Length -gt 0)
                        $data.CancelButton.IsEnabled = $false
                        $data.CancelButton.Content = 'Abbrechen'
                        Write-FlowTrace 'USERMSG' $id 'WITHDRAWN_BY_USER' @{ sid = $data.SessionId }
                    } else {
                        $data.Status.Text = 'Zu spaet zum Zurueckziehen: Eine Arena-Anfrage hat die Nachricht bereits mitgenommen. Sie ist jetzt unterwegs.'
                        $data.Status.Foreground = Get-Brush '#FFD36D7F'
                        $data.CancelButton.Content = 'Schliessen'
                        $data.LastState = 'delivered'
                    }
                    return
                }
                try { $data.Window.Close() } catch {}
            } catch {
                Write-UiErrorLog 'Abbrechen der Nachricht fehlgeschlagen' $_
            }
        })

        $timer = [System.Windows.Threading.DispatcherTimer]::new()
        $timer.Interval = [TimeSpan]::FromMilliseconds(500)
        $timer.Tag = $info
        $timer.Add_Tick({
            param($s, $e)
            try { Update-UserMessageWindow $s.Tag } catch {}
        })
        $info.Timer = $timer
        $win.Add_Closed({
            param($s, $e)
            try { $s.Tag.Timer.Stop() } catch {}
            try { $script:UserMessageWindow = $null } catch {}
        })
        $script:UserMessageWindow = $win
        Update-UserMessageWindow $info
        $timer.Start()
        # ShowDialog disables the owner window for the lifetime of this dialog.
        [void]$win.ShowDialog()
    } catch {
        Write-UiErrorLog 'Nachricht-Fenster konnte nicht geoeffnet werden' $_
    }
}

function Get-AskStateForUi {
    # Version 7.2.0 (D3): dieselbe Ablage wie auf der Server-Seite
    # ($Shared.AskRequests, askId -> JSON) - die Oberflaeche hat keinen Zugriff
    # auf Handler-Funktionen, wohl aber auf den gemeinsamen Zustand.
    param([string]$AskId)
    $json = ''
    try {
        if (-not $script:Shared.AskRequests.TryGetValue([string]$AskId, [ref]$json)) { return $null }
    } catch { return $null }
    if ([string]::IsNullOrWhiteSpace($json)) { return $null }
    try { return ($json | ConvertFrom-Json) } catch { return $null }
}

function Save-AskStateForUi {
    param([string]$AskId, $State)
    try { $script:Shared.AskRequests[[string]$AskId] = ($State | ConvertTo-Json -Depth 14 -Compress) } catch {}
}

function Get-AskPendingForUi {
    # Nur eine noch offene, nicht abgelaufene Frage darf ein Fenster oeffnen.
    # answered, expired und cancelled sind terminal; insbesondere darf ein
    # abgebrochenes Fenster nicht beim naechsten Anzeige-Takt wiederkommen.
    param([string]$SessionId)
    $best = $null
    $bestCreated = [int64](-1)
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    try {
        foreach ($pair in $script:Shared.AskRequests.GetEnumerator()) {
            $state = $null
            try { $state = ($pair.Value | ConvertFrom-Json) } catch { $state = $null }
            if ($null -eq $state) { continue }
            if ([string]$state.sessionId -ne [string]$SessionId) { continue }
            $askState = [string]$state.state
            if ($askState -eq 'cancelled') { continue }
            if ($askState -ne 'waiting') { continue }
            if ($now -ge [int64]$state.expiresAt) {
                # Der UI-Takt ist ein Notausgang: Eine nicht mehr wartende
                # Anfrage darf die Hauptoberflaeche nie dauerhaft blockieren.
                Set-UiMessageField $state 'state' 'expired'
                Save-AskStateForUi ([string]$state.askId) $state
                Add-UiChannelCount 'AskExpired' 1
                Write-FlowTrace 'ASK' ([string]$state.askId) 'EXPIRED' @{ sid = [string]$state.sessionId; source = 'ui_pending' }
                continue
            }
            $created = [int64]$state.createdAt
            if ($created -gt $bestCreated) { $bestCreated = $created; $best = $state }
        }
    } catch {}
    return $best
}

function Test-AskCondition {
    # Bedingungen: mehrere when-Eintraege muessen ALLE zutreffen; anyOf = eine
    # der Optionen, allOf = alle, custom = es muss eine eigene Antwort geben.
    param($Question, $Answers)
    try {
        if ($null -eq $Question) { return $false }
        $when = @()
        try { if ($Question.PSObject.Properties['when']) { $when = @($Question.when) } } catch {}
        if ($when.Count -eq 0) { return $true }
        foreach ($condition in $when) {
            $refId = ''
            try { $refId = [string]$condition.questionId } catch {}
            if ([string]::IsNullOrWhiteSpace($refId)) { return $false }
            $answer = $null
            try { if ($null -ne $Answers -and $Answers.ContainsKey($refId)) { $answer = $Answers[$refId] } } catch {}
            if ($null -eq $answer) { return $false }
            $selected = New-Object System.Collections.Generic.List[string]
            try { foreach ($id in @($answer.optionIds)) { $selected.Add([string]$id) } } catch {}
            $custom = ''
            try { $custom = [string]$answer.custom } catch {}
            foreach ($key in @('anyOf', 'allOf')) {
                $wanted = @()
                try { if ($condition.PSObject.Properties[$key]) { $wanted = @($condition.$key) } } catch {}
                if ($wanted.Count -eq 0) { continue }
                if ($key -eq 'anyOf') {
                    $hit = $false
                    foreach ($value in $wanted) { if ($selected.Contains([string]$value)) { $hit = $true; break } }
                    if (-not $hit) { return $false }
                } else {
                    foreach ($value in $wanted) { if (-not $selected.Contains([string]$value)) { return $false } }
                }
            }
            $wantsCustom = $false
            try { if ($condition.PSObject.Properties['custom'] -and $condition.custom -eq $true) { $wantsCustom = $true } } catch {}
            if ($wantsCustom -and [string]::IsNullOrWhiteSpace($custom)) { return $false }
        }
        return $true
    } catch {}
    return $false
}

function Get-AskVisibleQuestions {
    # Welche Fragen der Nutzer JETZT sieht - und fuer welche es schon eine
    # Antwort gibt. Genau diese Auswertung passiert auch beim Zurueckgehen neu.
    param($Questions, $Answers)
    $result = New-Object System.Collections.Generic.List[object]
    $live = @{}
    try {
        foreach ($question in @($Questions)) {
            $visible = $true
            try { $visible = (Test-AskCondition $question $live) } catch { $visible = $false }
            if (-not $visible) { continue }
            $has = $false
            try { $has = ($null -ne $Answers -and $Answers.ContainsKey([string]$question.id)) } catch {}
            $result.Add([pscustomobject]@{ Question = $question; Answered = $has })
            if ($has) { $live[[string]$question.id] = $Answers[[string]$question.id] }
        }
    } catch {}
    return ,$result
}

function Submit-AskAnswers {
    # Antworten des Nutzers ablegen. Das weckt einen wartenden Arena-Aufruf
    # (AskSignals) ODER liegt bereit und geht als _bridge.userAnswers mit der
    # naechsten Antwort - beides ist richtig, nichts geht verloren.
    param([string]$AskId, $Answers, $Path, $NotShown)
    try {
        $state = Get-AskStateForUi $AskId
        if ($null -eq $state) { return $false }
        Set-UiMessageField $state 'state' 'answered'
        Set-UiMessageField $state 'answers' $Answers
        Set-UiMessageField $state 'path' @($Path)
        Set-UiMessageField $state 'notShown' @($NotShown)
        Set-UiMessageField $state 'answeredAt' ([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())
        $stateJson = ''
        try { $stateJson = ($state | ConvertTo-Json -Depth 14 -Compress) } catch {}
        $script:Shared.AskRequests[[string]$AskId] = $stateJson
        Add-UiChannelCount 'AskAnswered' 1
        Write-FlowTrace 'ASK' $AskId 'ANSWERED' @{ sid = [string]$state.sessionId; questions = @($Path).Count; notShown = @($NotShown).Count }
        $signal = $null
        try {
            if ($script:Shared.AskSignals.TryGetValue([string]$AskId, [ref]$signal) -and $null -ne $signal) { [void]$signal.Set() }
        } catch {}
        Add-UiBridgeEvent ([string]$state.sessionId) 'ask_answered' ('Der Nutzer hat geantwortet: ' + [string]$state.title) @{ askId = $AskId }
        return $true
    } catch {
        Write-UiErrorLog 'Antworten konnten nicht gespeichert werden' $_
        return $false
    }
}

function Get-AskCopyPrompt {
    # Paste-fertiger Text fuer den Arena-Chat, wenn der Agent nicht mehr wartet
    # oder offline ist. Enthaelt Titel, alle Fragen mit ihren Bedingungen, die
    # Antworten und den Platz.
    param($Info)
    $lines = New-Object System.Collections.Generic.List[string]
    try {
        $state = Get-AskStateForUi ([string]$Info.AskId)
        if ($null -eq $state) { return '' }
        $lines.Add('Antworten auf deine Frage (Arena Roblox Bridge)')
        $place = ''
        try { $place = [string]$state.place } catch {}
        if (-not [string]::IsNullOrWhiteSpace($place)) { $lines.Add('Platz: ' + $place) }
        $lines.Add('Titel: ' + [string]$state.title)
        $message = ''
        try { $message = [string]$state.message } catch {}
        if (-not [string]::IsNullOrWhiteSpace($message)) { $lines.Add('Kontext: ' + $message) }
        $lines.Add('')
        foreach ($question in @($state.questions)) {
            $qid = [string]$question.id
            $conditionText = ''
            try {
                $when = @($question.when)
                if ($when.Count -gt 0) {
                    $parts = New-Object System.Collections.Generic.List[string]
                    foreach ($condition in $when) {
                        $bits = New-Object System.Collections.Generic.List[string]
                        foreach ($key in @('anyOf', 'allOf')) {
                            try {
                                if ($condition.PSObject.Properties[$key]) {
                                    $values = @($condition.$key)
                                    if ($values.Count -gt 0) { $bits.Add($key + '=' + ($values -join '/')) }
                                }
                            } catch {}
                        }
                        try { if ($condition.PSObject.Properties['custom'] -and $condition.custom -eq $true) { $bits.Add('custom') } } catch {}
                        $parts.Add([string]$condition.questionId + ' (' + ($bits.ToArray() -join ', ') + ')')
                    }
                    $conditionText = ' [nur wenn ' + ($parts.ToArray() -join ' und ') + ']'
                }
            } catch {}
            $answerText = '(nicht beantwortet)'
            try {
                if ($null -ne $Info.Answers -and $Info.Answers.ContainsKey($qid)) {
                    $entry = $Info.Answers[$qid]
                    $labels = @($entry.labels)
                    $custom = [string]$entry.custom
                    $combo = ''
                    if ($labels.Count -gt 0) { $combo = ($labels -join ', ') }
                    if (-not [string]::IsNullOrWhiteSpace($custom)) {
                        if ($combo) { $combo = $combo + ' | eigene Antwort: ' + $custom } else { $combo = 'eigene Antwort: ' + $custom }
                    }
                    if ($combo) { $answerText = $combo }
                }
            } catch {}
            $lines.Add('- ' + [string]$question.text + $conditionText)
            $lines.Add('  Antwort: ' + $answerText)
        }
        $lines.Add('')
        $lines.Add('Bitte arbeite mit diesen Antworten weiter.')
    } catch {}
    return ($lines.ToArray() -join [Environment]::NewLine)
}

function Start-AskModal {
    # Das Fragenfenster wird bewusst nicht per ShowDialog gestartet: Bei Ablauf
    # bleibt die Ausnahmeansicht (mit Kopierknopf) sichtbar, aber die
    # Hauptoberflaeche wird SOFORT wieder freigegeben. Solange state=waiting
    # ist, ist sie trotzdem genauso modal wie ein Dialog.
    param($Info)
    try {
        if ($null -eq $Info -or [bool]$Info.OwnerDisabled) { return }
        if ($null -ne $window) {
            $Info.OwnerWindow = $window
            $window.IsEnabled = $false
            $Info.OwnerDisabled = $true
        }
    } catch {
        Write-UiErrorLog 'Frage-Fenster konnte die Hauptoberflaeche nicht sperren' $_
    }
}

function Stop-AskModal {
    param($Info)
    try {
        if ($null -eq $Info -or -not [bool]$Info.OwnerDisabled) { return }
        $Info.OwnerDisabled = $false
        if ($null -ne $Info.OwnerWindow) { $Info.OwnerWindow.IsEnabled = $true }
    } catch {
        Write-UiErrorLog 'Frage-Fenster konnte die Hauptoberflaeche nicht freigeben' $_
    }
}

function Cancel-AskForUi {
    # X, Esc und Abbrechen teilen exakt dieselbe ehrliche Semantik. Ein
    # cancelled-Zustand ist terminal, wird an die KI ausgeliefert und kann von
    # Get-AskPendingForUi/Sync-AskWindows nie wieder geoeffnet werden.
    param($Info, [string]$Reason = 'user_cancelled')
    try {
        if ($null -eq $Info) { return $false }
        $askId = [string]$Info.AskId
        $state = Get-AskStateForUi $askId
        if ($null -eq $state -or [string]$state.state -ne 'waiting') { return $false }
        $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        Set-UiMessageField $state 'state' 'cancelled'
        Set-UiMessageField $state 'cancelledAt' $now
        Set-UiMessageField $state 'answers' $null
        Set-UiMessageField $state 'path' @()
        Set-UiMessageField $state 'notShown' @()
        Save-AskStateForUi $askId $state
        Add-UiChannelCount 'AskCancelled' 1
        Write-FlowTrace 'ASK' $askId 'CANCELLED' @{ sid = [string]$state.sessionId; reason = $Reason }
        Add-UiBridgeEvent ([string]$state.sessionId) 'ask_cancelled' 'Der Nutzer hat die Frage abgebrochen.' @{ askId = $askId; cancelled = $true }
        $signal = $null
        try {
            if ($script:Shared.AskSignals.TryGetValue($askId, [ref]$signal) -and $null -ne $signal) { [void]$signal.Set() }
        } catch {}
        return $true
    } catch {
        Write-UiErrorLog 'Frage konnte nicht abgebrochen werden' $_
        return $false
    }
}

function Get-AskWindowXaml {
    # Version 7.2.4 (2a): Das Fragen-Fenster ist jetzt XAML-basiert und teilt
    # sich EINEN Ressourcenblock mit dem Nachrichten-Fenster
    # ($script:ArenaDialogStyles). Referenz ist das Haupt-/Einstellungsfenster:
    # WindowStyle=None, AllowsTransparency=True, Background=Transparent,
    # abgerundete Karte auf dem SwAppBg-Verlauf, Karten aus SwCardBg, Text in
    # SwTextMain/SwTextMuted/SwTextFaint, Crimson fuer gefaehrliche Aktionen.
    # Kein halbtransparentes #F50B1030-Shell und kein Mint #5CFFEF mehr.
    $template = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Arena fragt"
        Width="480" Height="420" MinWidth="440" MinHeight="320"
        SizeToContent="Height" ResizeMode="NoResize"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        WindowStartupLocation="Manual" ShowInTaskbar="False" FontFamily="Segoe UI"
        UseLayoutRounding="True" SnapsToDevicePixels="True"
        TextOptions.TextFormattingMode="Display">
    <Window.Resources>
<!--ARENA_DIALOG_STYLES-->
    </Window.Resources>
    <Border CornerRadius="20" Background="{StaticResource SwAppBg}"
            BorderBrush="#33FFFFFF" BorderThickness="1" ClipToBounds="True">
        <Grid>
            <!-- Ruhiger Hintergrundglanz: dieselben Farben wie im Haupt- und
                 Einstellungsfenster, aber OHNE Daueranimation. Eine forever
                 laufende Storyboard-Animation war mit ein Grund fuer das
                 unruhige Bild des alten Fensters. -->
            <Grid IsHitTestVisible="False">
                <Ellipse Width="420" Height="420" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="-150,-190,0,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#407B5CFF" Offset="0"/>
                            <GradientStop Color="#007B5CFF" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                </Ellipse>
                <Ellipse Width="360" Height="360" HorizontalAlignment="Right" VerticalAlignment="Bottom" Margin="0,0,-120,-140">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#2E00CFC0" Offset="0"/>
                            <GradientStop Color="#0000CFC0" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                </Ellipse>
            </Grid>

            <Grid Margin="22">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- Titelzeile: ziehbar (DragMove), Kreuz oben rechts. -->
                <Grid x:Name="TitleBar" Grid.Row="0" Background="Transparent" Cursor="SizeAll">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="Arena fragt" Foreground="{StaticResource SwTextMain}"
                                   FontSize="16" FontWeight="Bold"/>
                        <TextBlock x:Name="AskPlaceText" Text="" Foreground="{StaticResource SwTextFaint}"
                                   FontSize="10.5" Margin="0,2,0,0" TextTrimming="CharacterEllipsis"/>
                    </StackPanel>
                    <!-- Kreuz = Abbrechen, 32 x 32 px (gefordert: >= 28 x 28),
                         mit Hover. Esc tut dasselbe. -->
                    <Button x:Name="CloseButton" Grid.Column="1" Style="{StaticResource ArenaCloseButton}"
                            Content="&#xE8BB;" FontFamily="Segoe MDL2 Assets" FontSize="11"
                            ToolTip="Abbrechen (Esc)"/>
                </Grid>

                <!-- Kopf: Titel, Einleitung, Frage x von y. -->
                <StackPanel Grid.Row="1" Margin="0,12,0,0">
                    <TextBlock x:Name="AskTitleText" Foreground="{StaticResource SwTextMain}"
                               FontSize="15" FontWeight="SemiBold" TextWrapping="Wrap"/>
                    <TextBlock x:Name="AskMessageText" Foreground="{StaticResource SwTextMuted}"
                               FontSize="11.5" TextWrapping="Wrap" Margin="0,5,0,0"/>
                    <TextBlock x:Name="AskProgressText" Foreground="{StaticResource SwTextFaint}"
                               FontSize="10.5" Margin="0,7,0,0"/>
                </StackPanel>

                <!-- Frage: lange Texte scrollen IN der Karte, nicht das Fenster. -->
                <ScrollViewer x:Name="QuestionScroll" Grid.Row="2" Margin="0,12,0,0"
                              VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                    <Border x:Name="QuestionCard" Background="{StaticResource SwCardBg}"
                            BorderBrush="#2EFFFFFF" BorderThickness="1" CornerRadius="14" Padding="14,12">
                        <StackPanel x:Name="QuestionStack"/>
                    </Border>
                </ScrollViewer>

                <!-- Statuszeile. -->
                <Border x:Name="StatusBorder" Grid.Row="3" Margin="0,10,0,0"
                        Background="{StaticResource SwCardBg}" BorderBrush="#2EFFFFFF"
                        BorderThickness="1" CornerRadius="10" Padding="11,8">
                    <TextBlock x:Name="StatusText" Foreground="{StaticResource SwTextMuted}"
                               FontSize="11" TextWrapping="Wrap"/>
                </Border>

                <!-- Kopier-Knopf NUR im Ausnahmezustand (Ablauf / Agent
                     offline). Im normalen Ablauf ist er unsichtbar. -->
                <StackPanel x:Name="CopyPanel" Grid.Row="4" Orientation="Horizontal"
                            HorizontalAlignment="Left" Margin="0,10,0,0" Visibility="Collapsed">
                    <Button x:Name="CopyButton" Content="Antwort als Text kopieren"
                            Style="{StaticResource ArenaQuietButton}" Padding="12,7" MinHeight="30"/>
                </StackPanel>

                <!-- Endzustand nach "Fertig": Das Fenster schliesst sich NICHT
                     von allein. Gruener Endzustand + ein Knopf "Schliessen". -->
                <Border x:Name="DonePanel" Grid.Row="5" Margin="0,10,0,0" Visibility="Collapsed"
                        Background="#261FA34A" BorderBrush="#662FCB6C" BorderThickness="1"
                        CornerRadius="12" Padding="14,12">
                    <StackPanel>
                        <TextBlock x:Name="DoneText" Foreground="#B9F5D2" FontSize="12.5"
                                   FontWeight="SemiBold" TextWrapping="Wrap"/>
                        <Button x:Name="DoneCloseButton" Content="Schließen" HorizontalAlignment="Right"
                                Margin="0,10,0,0" MinWidth="96" MinHeight="32" Padding="14,6"
                                Style="{StaticResource ArenaPrimaryButton}"/>
                    </StackPanel>
                </Border>

                <!-- Fusszeile: Restzeit links, genau drei Aktionen rechts. -->
                <Grid Grid.Row="6" Margin="0,12,0,0">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>
                    <TextBlock x:Name="AskCountdownText" Grid.Column="0" VerticalAlignment="Center"
                               Foreground="{StaticResource SwTextFaint}" FontSize="10.5"
                               TextWrapping="Wrap"/>
                    <StackPanel x:Name="ButtonRow" Grid.Column="1" Orientation="Horizontal"
                                HorizontalAlignment="Right">
                        <Button x:Name="BackButton" Content="Zurück" MinWidth="80" MinHeight="32"
                                Padding="13,6" Style="{StaticResource ArenaQuietButton}"/>
                        <Button x:Name="CancelButton" Content="Abbrechen" MinWidth="92" MinHeight="32"
                                Padding="13,6" Margin="8,0,0,0" Style="{StaticResource ArenaDangerButton}"/>
                        <Button x:Name="NextButton" Content="Weiter" MinWidth="86" MinHeight="32"
                                Padding="15,6" Margin="8,0,0,0" Style="{StaticResource ArenaPrimaryButton}"/>
                    </StackPanel>
                </Grid>
            </Grid>
        </Grid>
    </Border>
</Window>
'@
    return $template.Replace('<!--ARENA_DIALOG_STYLES-->', [string]$script:ArenaDialogStyles)
}

function New-AskWindowInfo {
    # Gemeinsamer Zustandsbehälter des Fragen-Fensters. Alle Event-Handler
    # haengen an $win.Tag: lokale Funktionsvariablen sind in WPF-Handlern
    # nicht zuverlaessig sichtbar.
    param($Win, [string]$AskId, [string]$SessionId)
    return [pscustomobject]@{
        Window             = $Win
        AskId              = $AskId
        SessionId          = $SessionId
        Answers            = @{}
        Visible            = (New-Object System.Collections.Generic.List[object])
        Step               = 0
        Dirty              = $false
        OwnerWindow        = $null
        OwnerDisabled      = $false
        TerminalClosing    = $false
        EmptyQuestionLogged = $false
        LastRenderedAt     = [int64]0
        RenderSignature    = ''
        FadeStarted        = $false
        DoneShown          = $false
        TitleText          = $Win.FindName('AskTitleText')
        MessageText        = $Win.FindName('AskMessageText')
        ProgressText       = $Win.FindName('AskProgressText')
        CountdownText      = $Win.FindName('AskCountdownText')
        PlaceText          = $Win.FindName('AskPlaceText')
        QuestionScroll     = $Win.FindName('QuestionScroll')
        QuestionCard       = $Win.FindName('QuestionCard')
        QuestionStack      = $Win.FindName('QuestionStack')
        StatusBorder       = $Win.FindName('StatusBorder')
        StatusText         = $Win.FindName('StatusText')
        ButtonRow          = $Win.FindName('ButtonRow')
        CopyPanel          = $Win.FindName('CopyPanel')
        DonePanel          = $Win.FindName('DonePanel')
        DoneText           = $Win.FindName('DoneText')
        DoneCloseButton    = $Win.FindName('DoneCloseButton')
        BackButton         = $Win.FindName('BackButton')
        CancelButton       = $Win.FindName('CancelButton')
        NextButton         = $Win.FindName('NextButton')
        CopyButton         = $Win.FindName('CopyButton')
        CloseButton        = $Win.FindName('CloseButton')
        Timer              = $null
    }
}

function Set-AskCountdownText {
    # Restzeit in der Fusszeile - der Nutzer muss sehen koennen, wie lange die
    # Frage noch offen bleibt (2d).
    param($Info, [int]$SecondsLeft, [string]$AskState)
    try {
        if ($null -eq $Info -or $null -eq $Info.CountdownText) { return }
        if ($AskState -ne 'waiting') {
            Set-Text $Info.CountdownText ''
            return
        }
        if ($SecondsLeft -le 0) {
            Set-Text $Info.CountdownText 'Antwortzeit abgelaufen'
            return
        }
        $minutes = [int][Math]::Floor($SecondsLeft / 60)
        $seconds = [int]($SecondsLeft % 60)
        if ($minutes -gt 0) {
            Set-Text $Info.CountdownText ('Noch ' + [string]$minutes + ' min ' + [string]$seconds + ' s Zeit')
        } else {
            Set-Text $Info.CountdownText ('Noch ' + [string]$seconds + ' s Zeit')
        }
    } catch {}
}

function Show-AskDoneState {
    # 2f: Nach "Fertig" verschwindet nichts still. Das Fenster bleibt offen und
    # zeigt einen gruenen Endzustand mit einem Knopf "Schliessen".
    param($Info, [int]$AnswerCount)
    try {
        if ($null -eq $Info) { return }
        if ($AnswerCount -lt 0) { $AnswerCount = 0 }
        $label = $(if ($AnswerCount -eq 1) { 'Antwort ist' } else { 'Antworten sind' })
        Set-Text $Info.DoneText ('Alle ' + [string]$AnswerCount + ' ' + $label + ' gespeichert - Arena holt sie ab.')
        $Info.DonePanel.Visibility = 'Visible'
        $Info.QuestionScroll.Visibility = 'Collapsed'
        $Info.QuestionCard.Visibility = 'Collapsed'
        $Info.ButtonRow.Visibility = 'Collapsed'
        $Info.CopyPanel.Visibility = 'Collapsed'
        $Info.StatusBorder.Visibility = 'Collapsed'
        $Info.NextButton.IsEnabled = $false
        $Info.BackButton.IsEnabled = $false
        $Info.CancelButton.IsEnabled = $false
        $Info.DoneShown = $true
        # Die Frage ist beantwortet: Die Hauptoberflaeche wird sofort frei,
        # waehrend die Bestaetigung sichtbar bleibt.
        Stop-AskModal $Info
        Set-AskCountdownText $Info 0 'answered'
        Set-Text $Info.ProgressText ''
        try { $Info.Timer.Stop() } catch {}
        Write-FlowTrace 'ASK' ([string]$Info.AskId) 'DONE_STATE_SHOWN' @{ answers = $AnswerCount }
    } catch {
        Write-UiErrorLog 'Endzustand des Frage-Fensters konnte nicht angezeigt werden' $_
    }
}

function Update-AskWindow {
    # Zeichnet Kopf, aktuelle Frage, Restzeit und die wenigen erlaubten
    # Ausnahmezustaende. Im Normalfall gibt es unten genau Zurueck, Abbrechen,
    # Weiter/Fertig - kein Kopier- und kein Schliessen-Knopf (2e).
    #
    # Version 7.2.4 (2c/2d): Der Fragenbereich wird NUR noch neu aufgebaut,
    # wenn sich wirklich etwas Strukturelles geaendert hat (Frage, sichtbarer
    # Satz, Antwortschluessel, Zustand). Bis 7.2.3 lief der Aufbau bei jedem
    # Takt und spaetestens alle 5 Sekunden komplett durch: Children.Clear()
    # liess das Fenster bei SizeToContent=Height sichtbar zusammensacken und
    # wieder aufploppen - genau das vom Owner gemeldete "schlecht animiert /
    # tauchte neu auf".
    param($Info)
    try {
        if ($null -eq $Info) { return }
        $state = Get-AskStateForUi ([string]$Info.AskId)
        if ($null -eq $state) {
            Stop-AskModal $Info
            try { $Info.Window.Close() } catch {}
            return
        }
        $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        $askState = [string]$state.state
        $secondsLeft = [int][Math]::Max(0, ([int64]$state.expiresAt - $now))
        if ($askState -eq 'waiting' -and $secondsLeft -le 0) {
            Set-UiMessageField $state 'state' 'expired'
            Save-AskStateForUi ([string]$Info.AskId) $state
            Add-UiChannelCount 'AskExpired' 1
            Write-FlowTrace 'ASK' ([string]$Info.AskId) 'EXPIRED' @{ sid = [string]$state.sessionId; source = 'ui_timer' }
            $signal = $null
            try {
                if ($script:Shared.AskSignals.TryGetValue([string]$Info.AskId, [ref]$signal) -and $null -ne $signal) { [void]$signal.Set() }
            } catch {}
            $askState = 'expired'
        }

        # Wie lebendig ist Arena? Fortschritt und Plugin-Heartbeat sind die
        # einzigen ehrlichen Sensoren; kein erfundener Online-Status.
        $lastCall = [int64]0
        try {
            $snapshot = Get-ProgressStateSnapshot ([string]$state.sessionId)
            if ($null -ne $snapshot) { $lastCall = [int64]$snapshot.LastCallAt }
        } catch {}
        $instanceSeen = [int64]0
        try { [void]$script:Shared.InstanceLastSeen.TryGetValue([string]$state.sessionId, [ref]$instanceSeen) } catch {}
        $aliveAt = [Math]::Max($lastCall, $instanceSeen)
        $agentSilent = 0
        if ($aliveAt -gt 0) { $agentSilent = [int][Math]::Max(0, ($now - $aliveAt)) }
        # Direkt nach dem Oeffnen kann noch kein Heartbeat im gemeinsamen
        # Zustand stehen. Diese kurze, klar begrenzte Schonfrist verhindert,
        # dass ein ganz normales frisches Fragenfenster faelschlich als offline
        # erscheint; nach 90 Sekunden ohne Sensor wird der Zustand wieder
        # ehrlich als offline gezeigt.
        $createdAt = [int64]0
        try { $createdAt = [int64]$state.createdAt } catch {}
        $freshWithoutSensor = ($aliveAt -le 0 -and $createdAt -gt 0 -and ($now - $createdAt) -le 90)
        $agentAlive = $freshWithoutSensor -or ($aliveAt -gt 0 -and $agentSilent -le 90)
        $Info.LastRenderedAt = $now

        Set-Text $Info.TitleText ([string]$state.title)
        $subtitle = ''
        try { $subtitle = [string]$state.message } catch {}
        Set-Text $Info.MessageText $subtitle
        if ([string]::IsNullOrWhiteSpace($subtitle)) { $Info.MessageText.Visibility = 'Collapsed' } else { $Info.MessageText.Visibility = 'Visible' }
        Set-AskCountdownText $Info $secondsLeft $askState

        # 2f: Beantwortet heisst NICHT "Fenster zu". Der grüne Endzustand
        # bleibt stehen, bis der Nutzer auf "Schliessen" klickt.
        if ($askState -eq 'answered') {
            if (-not [bool]$Info.DoneShown) {
                $answeredCount = 0
                try {
                    foreach ($pathEntry in @($state.path)) {
                        if (-not [string]::IsNullOrWhiteSpace([string]$pathEntry)) { $answeredCount = $answeredCount + 1 }
                    }
                } catch {}
                Show-AskDoneState $Info $answeredCount
            }
            return
        }
        if ($askState -eq 'cancelled') {
            # Abbrechen ist der einzige Zustand, in dem das Fenster wirklich
            # zugeht (2g). Es kommt fuer diese askId nie wieder.
            Stop-AskModal $Info
            if (-not [bool]$Info.TerminalClosing) {
                $Info.TerminalClosing = $true
                try { $Info.Timer.Stop() } catch {}
                try { $Info.Window.Close() } catch {}
            }
            return
        }
        if ($askState -eq 'expired') {
            Stop-AskModal $Info
            $Info.QuestionScroll.Visibility = 'Collapsed'
            $Info.QuestionCard.Visibility = 'Collapsed'
            $Info.ButtonRow.Visibility = 'Collapsed'
            $Info.CopyPanel.Visibility = 'Visible'
            Set-Text $Info.ProgressText 'Antwortzeit abgelaufen'
            if ($agentAlive) {
                $Info.StatusText.Text = 'Agent arbeitet weiter … Die Antwortzeit ist abgelaufen. Du kannst die Fragen und deine Auswahl als Text kopieren und im Arena-Chat senden.'
            } else {
                $Info.StatusText.Text = 'Agent ist offline … Die Antwortzeit ist abgelaufen. Du kannst die Fragen und deine Auswahl als Text kopieren und im Arena-Chat senden.'
            }
            $Info.StatusText.Foreground = Get-Brush '#FFB4C4'
            return
        }

        $Info.QuestionScroll.Visibility = 'Visible'
        $Info.QuestionCard.Visibility = 'Visible'
        $Info.ButtonRow.Visibility = 'Visible'
        $Info.DonePanel.Visibility = 'Collapsed'
        if ($agentAlive) {
            $Info.StatusText.Text = 'Arena wartet auf deine Antwort.'
            $Info.StatusText.Foreground = Get-Brush '#9AA9CE'
            $Info.CopyPanel.Visibility = 'Collapsed'
        } else {
            # Offline ist ein Ausnahmezustand: die Eingabe bleibt moeglich,
            # aber der dezente Kopierknopf hilft, wenn niemand mehr zuhoert.
            $Info.StatusText.Text = 'Agent ist offline … Deine Antwort wird gespeichert und mit der naechsten Anfrage uebergeben.'
            $Info.StatusText.Foreground = Get-Brush '#FFB4C4'
            $Info.CopyPanel.Visibility = 'Visible'
        }

        $visible = Get-AskVisibleQuestions $state.questions $Info.Answers
        $Info.Visible = $visible
        if ($Info.Step -ge $visible.Count) { $Info.Step = [Math]::Max(0, $visible.Count - 1) }
        if ($Info.Step -lt 0) { $Info.Step = 0 }
        Set-Text $Info.ProgressText ('Frage ' + [string]([Math]::Min($Info.Step + 1, [Math]::Max(1, $visible.Count))) + ' von ' + [string][Math]::Max(1, $visible.Count))

        # Antworten auf nicht mehr sichtbare Folgefragen koennen nach Zurueck
        # oder einer when-Verzweigung nicht heimlich weitergelten.
        $liveIds = @{}
        $visibleIds = New-Object System.Collections.Generic.List[string]
        foreach ($entry in $visible) {
            $liveIds[[string]$entry.Question.id] = $true
            $visibleIds.Add([string]$entry.Question.id)
        }
        $discarded = $false
        foreach ($key in @($Info.Answers.Keys)) {
            if (-not $liveIds.ContainsKey([string]$key)) {
                $Info.Answers.Remove([string]$key)
                $discarded = $true
                Write-FlowTrace 'ASK' ([string]$Info.AskId) 'ANSWER_DISCARDED' @{ questionId = [string]$key; reason = 'not_visible' }
            }
        }

        # 2c/2d: Nur bei echter Strukturänderung neu aufbauen. Sonst bleibt der
        # Baum stehen - kein Flackern, kein Springen, kein Fokusverlust beim
        # Tippen in "Eigene Antwort".
        $answeredKeys = New-Object System.Collections.Generic.List[string]
        foreach ($key in $Info.Answers.Keys) { $answeredKeys.Add([string]$key) }
        $signature = ([string]$Info.AskId + '|step=' + [string]$Info.Step +
            '|visible=' + ($visibleIds.ToArray() -join ',') +
            '|answered=' + (($answeredKeys.ToArray() | Sort-Object) -join ',') +
            '|state=' + $askState + '|alive=' + [string]$agentAlive +
            '|discarded=' + [string]$discarded)
        if ($signature -eq [string]$Info.RenderSignature) {
            $Info.BackButton.IsEnabled = ($Info.Step -gt 0)
            $Info.NextButton.IsEnabled = $true
            $Info.NextButton.Content = $(if ($Info.Step -ge ($visible.Count - 1)) { 'Fertig' } else { 'Weiter' })
            return
        }
        $Info.RenderSignature = $signature

        $questionStack = $Info.QuestionStack
        $questionStack.Children.Clear()
        $question = $null
        if ($visible.Count -gt 0) { $question = $visible[[Math]::Min($Info.Step, $visible.Count - 1)].Question }
        if ($null -eq $question) {
            $missing = [System.Windows.Controls.TextBlock]::new()
            $missing.Text = 'Diese Frage kam ohne Inhalt an - bitte abbrechen und Arena neu fragen lassen.'
            $missing.TextWrapping = 'Wrap'
            $missing.FontSize = 12
            $missing.FontWeight = 'SemiBold'
            $missing.Foreground = Get-Brush '#FF5C77'
            [void]$questionStack.Children.Add($missing)
            $Info.NextButton.IsEnabled = $false
            if (-not [bool]$Info.EmptyQuestionLogged) {
                $Info.EmptyQuestionLogged = $true
                try { throw [System.InvalidOperationException]::new('Frage ohne Inhalt gerendert') } catch {
                    Write-UiErrorLog ('ASK EMPTY_QUESTION askId=' + [string]$Info.AskId) $_
                }
                Write-FlowTrace 'ASK' ([string]$Info.AskId) 'EMPTY_QUESTION' @{ questionId = '-'; allowCustomResponse = $false }
            }
            return
        }

        $qid = [string]$question.id
        $answer = $null
        try { if ($Info.Answers.ContainsKey($qid)) { $answer = $Info.Answers[$qid] } } catch {}
        $selected = @()
        $custom = ''
        if ($null -ne $answer) {
            try { $selected = @($answer.optionIds) } catch {}
            try { $custom = [string]$answer.custom } catch {}
        }
        $questionText = [System.Windows.Controls.TextBlock]::new()
        $questionText.Text = [string]$question.text
        $questionText.TextWrapping = 'Wrap'
        $questionText.FontSize = 13.5
        $questionText.FontWeight = 'SemiBold'
        $questionText.Foreground = Get-Brush '#F4F8FF'
        $questionText.Margin = [System.Windows.Thickness]::new(0, 0, 0, 9)
        [void]$questionStack.Children.Add($questionText)

        $allowCustom = $false
        try { if ($question.PSObject.Properties['allowCustomResponse']) { $allowCustom = ([bool]$question.allowCustomResponse) } } catch {}
        $optionCount = 0
        try { foreach ($optionProbe in $question.options) { $optionCount = $optionCount + 1 } } catch {}

        $multi = $false
        try { if ($question.PSObject.Properties['multi']) { $multi = ([bool]$question.multi) } } catch {}
        if ($optionCount -gt 0) {
            if ($multi) {
                $hintRow = [System.Windows.Controls.TextBlock]::new()
                $hintRow.Text = 'Mehrfachauswahl möglich.'
                $hintRow.FontSize = 10.5
                $hintRow.Foreground = Get-Brush '#6E7FA8'
                $hintRow.Margin = [System.Windows.Thickness]::new(0, 0, 0, 7)
                [void]$questionStack.Children.Add($hintRow)
            }
            foreach ($option in @($question.options)) {
                $oid = [string]$option.id
                if ($multi) { $item = [System.Windows.Controls.CheckBox]::new() } else { $item = [System.Windows.Controls.RadioButton]::new() }
                if ($multi) { $item.Style = $Info.Window.FindResource('ArenaOptionCheck') }
                else { $item.Style = $Info.Window.FindResource('ArenaOptionRadio') }
                $item.Content = [string]$option.label
                $item.Margin = [System.Windows.Thickness]::new(0, 3, 0, 3)
                $item.Tag = [pscustomobject]@{ Info = $Info; QuestionId = $qid; OptionId = $oid; Label = [string]$option.label; Multi = $multi }
                $item.IsChecked = ($selected -contains $oid)
                if ($multi) {
                    $item.Add_Click({
                        param($s, $e)
                        $data = $s.Tag
                        try {
                            $entry = $data.Info.Answers[$data.QuestionId]
                            if ($null -eq $entry) { $entry = @{ optionIds = @(); custom = ''; labels = @() } }
                            $ids = New-Object System.Collections.Generic.List[string]
                            foreach ($value in @($entry.optionIds)) { $ids.Add([string]$value) }
                            $labels = New-Object System.Collections.Generic.List[string]
                            foreach ($value in @($entry.labels)) { $labels.Add([string]$value) }
                            if ([bool]$s.IsChecked) {
                                if (-not $ids.Contains([string]$data.OptionId)) { $ids.Add([string]$data.OptionId); $labels.Add([string]$data.Label) }
                            } else {
                                $ids.Remove([string]$data.OptionId) | Out-Null
                                $labels.Remove([string]$data.Label) | Out-Null
                            }
                            $entry.optionIds = @($ids.ToArray())
                            $entry.labels = @($labels.ToArray())
                            $data.Info.Answers[$data.QuestionId] = $entry
                            $data.Info.Dirty = $true
                        } catch {}
                    })
                } else {
                    $item.Add_Click({
                        param($s, $e)
                        $data = $s.Tag
                        try {
                            $entry = @{ optionIds = @([string]$data.OptionId); labels = @([string]$data.Label); custom = '' }
                            try { if ($data.Info.Answers.ContainsKey([string]$data.QuestionId)) { $entry.custom = [string]$data.Info.Answers[[string]$data.QuestionId].custom } } catch {}
                            $data.Info.Answers[$data.QuestionId] = $entry
                            $data.Info.Dirty = $true
                        } catch {}
                    })
                }
                if (-not [string]::IsNullOrWhiteSpace([string]$option.description)) {
                    $vbox = [System.Windows.Controls.StackPanel]::new()
                    [void]$vbox.Children.Add($item)
                    $desc = [System.Windows.Controls.TextBlock]::new()
                    $desc.Text = [string]$option.description
                    $desc.FontSize = 10.5
                    $desc.TextWrapping = 'Wrap'
                    $desc.Foreground = Get-Brush '#6E7FA8'
                    $desc.Margin = [System.Windows.Thickness]::new(30, 2, 0, 4)
                    [void]$vbox.Children.Add($desc)
                    [void]$questionStack.Children.Add($vbox)
                } else {
                    [void]$questionStack.Children.Add($item)
                }
            }
        } else {
            # 2b/7.2.2-Fund: Eine Frage ohne Optionen darf NIE leer rendern.
            # Sie bekommt eine sichtbare Fehlerzeile UND das immer vorhandene
            # Textfeld, damit der Nutzer trotzdem antworten kann.
            $emptyLine = [System.Windows.Controls.TextBlock]::new()
            $emptyLine.Text = 'Diese Frage kam ohne Optionen an - du kannst unten frei antworten.'
            $emptyLine.TextWrapping = 'Wrap'
            $emptyLine.FontSize = 12
            $emptyLine.FontWeight = 'SemiBold'
            $emptyLine.Foreground = Get-Brush '#FF5C77'
            $emptyLine.Margin = [System.Windows.Thickness]::new(0, 0, 0, 4)
            [void]$questionStack.Children.Add($emptyLine)
            if (-not [bool]$Info.EmptyQuestionLogged) {
                $Info.EmptyQuestionLogged = $true
                try { throw [System.InvalidOperationException]::new('Diese Frage kam ohne Optionen an') } catch {
                    Write-UiErrorLog ('ASK EMPTY_QUESTION askId=' + [string]$Info.AskId + ' questionId=' + $qid) $_
                }
                Write-FlowTrace 'ASK' ([string]$Info.AskId) 'EMPTY_QUESTION' @{ questionId = $qid; allowCustomResponse = $allowCustom }
            }
        }

        # 2b: "Eigene Antwort" ist IMMER sichtbar und immer tippbar - nicht nur
        # bei allowCustomResponse. Der Owner konnte in 7.2.3 ueberhaupt keine
        # eigene Antwort eingeben; ein Textfeld, das nur manchmal erscheint,
        # ist als Bedienweg unbrauchbar.
        $customLabel = [System.Windows.Controls.TextBlock]::new()
        if ($optionCount -gt 0 -and $allowCustom) { $customLabel.Text = 'Eigene Antwort (optional, ergänzt deine Auswahl):' }
        elseif ($optionCount -gt 0) { $customLabel.Text = 'Eigene Antwort (optional, ergänzt deine Auswahl):' }
        else { $customLabel.Text = 'Eigene Antwort:' }
        $customLabel.FontSize = 10.5
        $customLabel.Foreground = Get-Brush '#9AA9CE'
        $customLabel.TextWrapping = 'Wrap'
        $customLabel.Margin = [System.Windows.Thickness]::new(0, 11, 0, 5)
        [void]$questionStack.Children.Add($customLabel)

        $customBox = [System.Windows.Controls.TextBox]::new()
        $customBox.Style = $Info.Window.FindResource('ArenaTextField')
        $customBox.Text = $custom
        $customBox.MinHeight = 58
        $customBox.MaxLength = 4000
        $customBox.AcceptsReturn = $true
        $customBox.AcceptsTab = $false
        $customBox.TextWrapping = 'Wrap'
        $customBox.VerticalScrollBarVisibility = 'Auto'
        # Bewusst KEIN expliziter TabIndex: WPF vergibt sonst int.MaxValue an
        # alle uebrigen Elemente, und das Textfeld laege VOR den Optionen in
        # der Tab-Reihenfolge. Ohne Index gilt die visuelle Reihenfolge.
        $customBox.ToolTip = 'Eigene Antwort - tippen oder einfuegen (Strg+V). Wird zusaetzlich zu den angekreuzten Optionen uebergeben.'
        $customBox.Tag = [pscustomobject]@{ Info = $Info; QuestionId = $qid }
        $customBox.Add_TextChanged({
            param($s, $e)
            $data = $s.Tag
            try {
                $entry = $data.Info.Answers[$data.QuestionId]
                if ($null -eq $entry) { $entry = @{ optionIds = @(); labels = @(); custom = '' } }
                $entry.custom = [string]$s.Text
                $data.Info.Answers[$data.QuestionId] = $entry
                $data.Info.Dirty = $true
                # Wichtig: hier darf KEIN Neuzeichnen angestossen werden - das
                # Textfeld wuerde sonst beim Tippen neu gebaut und der Caret
                # waere weg.
            } catch {}
        })
        [void]$questionStack.Children.Add($customBox)

        $Info.BackButton.IsEnabled = ($Info.Step -gt 0)
        $Info.NextButton.IsEnabled = $true
        $Info.NextButton.Content = $(if ($Info.Step -ge ($visible.Count - 1)) { 'Fertig' } else { 'Weiter' })
    } catch {
        Write-UiErrorLog 'Frage-Fenster konnte nicht aktualisiert werden' $_
    }
}

function Retarget-AskWindow {
    # 2d: Ersetzt eine zweite Anfrage das Fenster, wird dasselbe Fenster
    # aktualisiert - NICHT geschlossen und neu aufgeploppt.
    param($Info, [string]$AskId, [string]$SessionId)
    try {
        if ($null -eq $Info -or [string]::IsNullOrWhiteSpace($AskId)) { return $false }
        if ([string]$Info.AskId -eq $AskId) { return $true }
        $previousAskId = [string]$Info.AskId
        $Info.AskId = $AskId
        if (-not [string]::IsNullOrWhiteSpace($SessionId)) { $Info.SessionId = $SessionId }
        $Info.Answers = @{}
        $Info.Step = 0
        $Info.Dirty = $false
        $Info.RenderSignature = ''
        $Info.EmptyQuestionLogged = $false
        $Info.DoneShown = $false
        $Info.TerminalClosing = $false
        $Info.DonePanel.Visibility = 'Collapsed'
        $Info.StatusBorder.Visibility = 'Visible'
        $Info.CancelButton.IsEnabled = $true
        Load-AskAnswersIntoInfo $Info
        Start-AskModal $Info
        [void](Update-AskWindow $Info)
        try { if ($null -ne $Info.Timer) { $Info.Timer.Start() } } catch {}
        Write-FlowTrace 'ASK' $AskId 'WINDOW_RETARGETED' @{ from = $previousAskId }
        return $true
    } catch {
        Write-UiErrorLog 'Frage-Fenster konnte nicht auf eine neue Frage umgestellt werden' $_
        return $false
    }
}

function Load-AskAnswersIntoInfo {
    # Bereits gespeicherte Antworten dieser askId uebernehmen, damit ein
    # wieder geoeffnetes/umgestelltes Fenster nicht leer wirkt.
    param($Info)
    try {
        if ($null -eq $Info) { return }
        $stateForRender = Get-AskStateForUi ([string]$Info.AskId)
        if ($null -eq $stateForRender) { return }
        if ($null -eq $stateForRender.answers) { return }
        foreach ($property in $stateForRender.answers.PSObject.Properties) {
            $saved = $stateForRender.answers.$($property.Name)
            $entry = @{ optionIds = @(); labels = @(); custom = '' }
            try { $entry.optionIds = @($saved.optionIds) } catch {}
            try { $entry.labels = @($saved.labels) } catch {}
            try { $entry.custom = [string]$saved.custom } catch {}
            $Info.Answers[$property.Name] = $entry
        }
    } catch {
        Write-UiErrorLog 'Vorherige Antworten konnten nicht geladen werden' $_
    }
}

function Open-AskWindow {
    # 7.2.4: XAML-Fenster im Programm-Design, ziehbar, sicher modal, mit
    # immer sichtbarer eigener Antwort, ruhigem Einblenden und ohne jedes
    # Auto-Schliessen. Es bleibt offen bis geantwortet, abgebrochen oder
    # abgelaufen - und fuer dieselbe askId wird es nie erneut geoeffnet.
    param($AskState)
    try {
        if ($null -eq $AskState) { return }
        $askId = [string]$AskState.askId
        if ([string]::IsNullOrWhiteSpace($askId)) { return }
        if ([string]$AskState.state -eq 'cancelled') { return }
        # 2d: Fuer eine askId, fuer die dieses Fenster schon einmal offen war,
        # wird es nie erneut geoeffnet - auch nicht nach dem Schliessen.
        try {
            if ($null -eq $script:AskWindowShownIds) { $script:AskWindowShownIds = [System.Collections.Generic.HashSet[string]]::new() }
            # Lehre aus 7.1.2: nichts darf unbegrenzt wachsen.
            if ($script:AskWindowShownIds.Count -gt 200) { $script:AskWindowShownIds.Clear() }
            if ($null -ne $script:AskWindow -and [string]$script:AskWindow.Tag.AskId -ne $askId) {
                [void](Retarget-AskWindow $script:AskWindow.Tag $askId ([string]$AskState.sessionId))
                return
            }
            if ($script:AskWindowShownIds.Contains($askId)) { return }
        } catch {}

        $askXaml = Get-AskWindowXaml
        $reader = [System.Xml.XmlNodeReader]::new([xml]$askXaml)
        $win = [Windows.Markup.XamlReader]::Load($reader)
        $win.Topmost = $true
        try { $win.Owner = $window } catch {}

        # Mit Versatz am Mauszeiger, auf dem jeweiligen Monitor. Hoehe max.
        # 70 % des Bildschirms; bei langem Inhalt scrollt nur die Karte.
        $screenHeight = 800
        $windowMaxHeight = 420
        try {
            $cursor = [System.Windows.Forms.Cursor]::Position
            $screen = [System.Windows.Forms.Screen]::FromPoint($cursor)
            $area = $screen.WorkingArea
            $screenHeight = [int]$area.Height
            $windowMaxHeight = [Math]::Min(560, [Math]::Floor($area.Height * 0.70))
            $win.MaxHeight = $windowMaxHeight
            $x = [int]$cursor.X + 24
            $y = [int]$cursor.Y + 20
            if (($x + 480) -gt ($area.X + $area.Width)) { $x = [int]$cursor.X - 24 - 480 }
            if (($y + 420) -gt ($area.Y + $area.Height)) { $y = [int]$cursor.Y - 20 - 420 }
            if ($x -lt $area.X) { $x = $area.X + 8 }
            if ($y -lt $area.Y) { $y = $area.Y + 8 }
            $win.WindowStartupLocation = 'Manual'
            $win.Left = $x
            $win.Top = $y
        } catch {
            $windowMaxHeight = [Math]::Min(560, [Math]::Floor($screenHeight * 0.70))
            $win.MaxHeight = $windowMaxHeight
            $win.WindowStartupLocation = 'CenterOwner'
        }

        $info = New-AskWindowInfo $win $askId ([string]$AskState.sessionId)
        $win.Tag = $info
        $titleBar = $win.FindName('TitleBar')
        $titleBar.Tag = $info
        foreach ($control in @($info.BackButton, $info.CancelButton, $info.NextButton, $info.CopyButton, $info.CloseButton, $info.DoneCloseButton)) {
            $control.Tag = $info
        }
        $placeName = ''
        try { $placeName = [string]$AskState.place } catch {}
        if (-not [string]::IsNullOrWhiteSpace($placeName)) { Set-Text $info.PlaceText ('Place · ' + $placeName) }
        else { $info.PlaceText.Visibility = 'Collapsed' }

        # 2c: ruhiges, kurzes Einblenden (180 ms, Opacity 0 -> 1) wie im Rest
        # des Programms - und zwar ERST nachdem der Inhalt einmal vollstaendig
        # gerendert ist. Dadurch erscheint das Fenster komplett, nicht halb.
        try {
            $win.Opacity = 0
            $win.Add_ContentRendered({
                param($s, $e)
                try {
                    if ([bool]$s.Tag.FadeStarted) { return }
                    $s.Tag.FadeStarted = $true
                    $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [TimeSpan]::FromMilliseconds(180))
                    $ease = [System.Windows.Media.Animation.CubicEase]::new()
                    $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
                    $fade.EasingFunction = $ease
                    $s.BeginAnimation([System.Windows.Window]::OpacityProperty, $fade)
                } catch { try { $s.Opacity = 1 } catch {} }
            })
        } catch { try { $win.Opacity = 1 } catch {} }

        # 2h: Titelzeile zieht das Fenster.
        $titleBar.Add_MouseLeftButtonDown({
            param($s, $e)
            if ($e.ButtonState -eq [System.Windows.Input.MouseButtonState]::Pressed) {
                try { $s.Tag.Window.DragMove() } catch {}
            }
        })
        # 2e: Kreuz oben rechts = Abbrechen (Notausgang, immer moeglich).
        $info.CloseButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            [void](Cancel-AskForUi $data 'close_button')
            Stop-AskModal $data
            try { $data.Window.Close() } catch {}
        })
        # Esc = Abbrechen, derselbe Weg wie das Kreuz.
        $win.Add_PreviewKeyDown({
            param($s, $e)
            if ($e.Key -eq [System.Windows.Input.Key]::Escape) {
                $data = $s.Tag
                [void](Cancel-AskForUi $data 'escape')
                Stop-AskModal $data
                try { $s.Close() } catch {}
                $e.Handled = $true
            }
        })

        $info.BackButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            try {
                $visible = $data.Visible
                if ($data.Step -le 0) { return }
                $target = $data.Step - 1
                # Alles NACH der Zielstufe ist eine Folgeantwort und wird beim
                # Zurueckgehen konsequent verworfen.
                for ($i = $target + 1; $i -lt $visible.Count; $i++) {
                    $discardId = [string]$visible[$i].Question.id
                    if ($data.Answers.ContainsKey($discardId)) {
                        $data.Answers.Remove($discardId)
                        Write-FlowTrace 'ASK' ([string]$data.AskId) 'ANSWER_DISCARDED' @{ questionId = $discardId; reason = 'back' }
                    }
                }
                $data.Step = $target
                $data.Dirty = $true
                Write-FlowTrace 'ASK' ([string]$data.AskId) 'BACK' @{ step = $data.Step }
                [void](Update-AskWindow $data)
            } catch {
                Write-UiErrorLog 'Zurueck im Frage-Fenster fehlgeschlagen' $_
            }
        })
        $info.CancelButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            [void](Cancel-AskForUi $data 'cancel_button')
            Stop-AskModal $data
            try { $data.Window.Close() } catch {}
        })
        $info.NextButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            try {
                $visible = $data.Visible
                if ($visible.Count -eq 0) { return }
                $index = [Math]::Min($data.Step, $visible.Count - 1)
                $question = $visible[$index].Question
                $qid = [string]$question.id
                $required = $true
                try { if ($question.PSObject.Properties['required']) { $required = [bool]$question.required } } catch {}
                $entry = $null
                try { if ($data.Answers.ContainsKey($qid)) { $entry = $data.Answers[$qid] } } catch {}
                $hasAnswer = $false
                if ($null -ne $entry) {
                    try { if (@($entry.optionIds).Count -gt 0) { $hasAnswer = $true } } catch {}
                    try { if (-not [string]::IsNullOrWhiteSpace([string]$entry.custom)) { $hasAnswer = $true } } catch {}
                }
                if ($required -and -not $hasAnswer) {
                    $data.StatusText.Text = 'Bitte waehle eine Antwort oder schreibe unten eine eigene, bevor es weitergeht.'
                    $data.StatusText.Foreground = Get-Brush '#FF5C77'
                    return
                }
                if (-not $data.Answers.ContainsKey($qid)) { $data.Answers[$qid] = @{ optionIds = @(); labels = @(); custom = '' } }
                if ($index -ge ($visible.Count - 1)) {
                    $path = New-Object System.Collections.Generic.List[string]
                    $allShown = New-Object System.Collections.Generic.List[string]
                    foreach ($entry2 in $visible) { $path.Add([string]$entry2.Question.id) }
                    foreach ($questionAll in @((Get-AskStateForUi ([string]$data.AskId)).questions)) { $allShown.Add([string]$questionAll.id) }
                    $notShown = New-Object System.Collections.Generic.List[string]
                    foreach ($candidate in $allShown) { if (-not $path.Contains($candidate)) { $notShown.Add($candidate) } }
                    $submitted = Submit-AskAnswers ([string]$data.AskId) $data.Answers $path.ToArray() $notShown.ToArray()
                    if ($submitted) {
                        # 2f: Fenster bleibt offen und zeigt den gruenen
                        # Endzustand - nichts verschwindet still.
                        Show-AskDoneState $data $path.Count
                    } else {
                        $data.StatusText.Text = 'Die Antworten konnten nicht gespeichert werden. Bitte versuche es erneut.'
                        $data.StatusText.Foreground = Get-Brush '#FF5C77'
                    }
                    return
                }
                $data.Step = $index + 1
                $data.Dirty = $true
                [void](Update-AskWindow $data)
            } catch {
                Write-UiErrorLog 'Antwort konnte nicht uebernommen werden' $_
                try {
                    $data.StatusText.Text = ('Antwort konnte nicht gespeichert werden: ' + [string]$_.Exception.Message)
                    $data.StatusText.Foreground = Get-Brush '#FF5C77'
                } catch {}
            }
        })
        $info.CopyButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            try {
                $text = Get-AskCopyPrompt $data
                if ([string]::IsNullOrWhiteSpace($text)) { return }
                [System.Windows.Clipboard]::SetText($text)
                $data.StatusText.Text = 'Text in der Zwischenablage - jetzt im Arena-Chat einfuegen (Strg+V).'
                $data.StatusText.Foreground = Get-Brush '#38D16C'
                Write-FlowTrace 'ASK' ([string]$data.AskId) 'COPY_PROMPT' @{ chars = $text.Length }
            } catch {
                Write-UiErrorLog 'Antworttext konnte nicht kopiert werden' $_
            }
        })
        # 2f: Der einzige Schliessen-Knopf im Ablauf - im gruenen Endzustand.
        $info.DoneCloseButton.Add_Click({
            param($s, $e)
            $data = $s.Tag
            Stop-AskModal $data
            try { $data.Window.Close() } catch {}
        })

        $timer = [System.Windows.Threading.DispatcherTimer]::new()
        $timer.Interval = [TimeSpan]::FromMilliseconds(500)
        $timer.Tag = $info
        $timer.Add_Tick({
            param($s, $e)
            try {
                $data = $s.Tag
                $state = Get-AskStateForUi ([string]$data.AskId)
                if ($null -eq $state -or [string]$state.state -ne 'waiting') {
                    # Pflicht-Notausgang: bei JEDEM terminalen Zustand endet die
                    # Modalitaet auch dann, wenn kein Button geklickt wurde.
                    [void](Update-AskWindow $data)
                    return
                }
                $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
                $left = [int][Math]::Max(0, ([int64]$state.expiresAt - $now))
                # Nur Restzeit und Status werden im Takt aktualisiert; der
                # Fragenbaum bleibt stehen, solange sich strukturell nichts
                # aendert (Update-AskWindow prueft die Signatur selbst).
                Set-AskCountdownText $data $left 'waiting'
                if ($left -le 0 -or [bool]$data.Dirty -or ($now - [int64]$data.LastRenderedAt) -ge 5) {
                    $data.Dirty = $false
                    [void](Update-AskWindow $data)
                }
            } catch {
                # Ein Timerfehler darf keine tote Modalitaet hinterlassen.
                try { Stop-AskModal $s.Tag } catch {}
                Write-UiErrorLog 'Frage-Fenster-Timer fehlgeschlagen' $_
            }
        })
        $info.Timer = $timer
        $win.Add_Closing({
            param($s, $e)
            try {
                $data = $s.Tag
                $state = Get-AskStateForUi ([string]$data.AskId)
                if ($null -ne $state -and [string]$state.state -eq 'waiting') { [void](Cancel-AskForUi $data 'window_closing') }
                Stop-AskModal $data
            } catch {}
        })
        $win.Add_Closed({
            param($s, $e)
            try { $s.Tag.Timer.Stop() } catch {}
            try { Stop-AskModal $s.Tag } catch {}
            try { $script:AskWindow = $null } catch {}
        })

        $script:AskWindow = $win
        try { [void]$script:AskWindowShownIds.Add($askId) } catch {}
        Load-AskAnswersIntoInfo $info
        Start-AskModal $info
        [void](Update-AskWindow $info)
        $timer.Start()
        [void]$win.Show()
        try { $win.Activate() } catch {}
    } catch {
        Write-UiErrorLog 'Frage-Fenster konnte nicht geoeffnet werden' $_
        try { if ($null -ne $window) { $window.IsEnabled = $true } } catch {}
    }
}

function Sync-AskWindows {
    # Der Anzeige-Takt oeffnet ausschliesslich aktuelle waiting-Requests.
    # cancelled ist explizit ausgeschlossen, damit ein Abbruch nie wieder
    # sichtbar wird.
    try {
        $currentAskId = ''
        if ($null -ne $script:AskWindow) {
            try { $currentAskId = [string]$script:AskWindow.Tag.AskId } catch {}
        }
        foreach ($studio in @(Get-ActiveStudios)) {
            $sid = [string]$studio.sessionId
            if ([string]::IsNullOrWhiteSpace($sid)) { continue }
            $pending = Get-AskPendingForUi $sid
            if ($null -eq $pending) { continue }
            if ([string]$pending.state -eq 'cancelled') { continue }
            $askId = [string]$pending.askId
            if ($askId -eq $currentAskId) { continue }
            Open-AskWindow $pending
            break
        }
    } catch {
        Write-UiErrorLog 'Frage-Fenster konnte nicht abgeglichen werden' $_
    }
}

function Get-PlaceOpenCommand {
    # Version 7.0.6: der aelteste noch offene Befehl dieser Sitzung - genau
    # der, der die strikt serielle Studio-Queue blockiert. Er wird in der
    # Place-Zeile sichtbar gemacht und kann dort abgebrochen werden.
    param([string]$sessionId)
    $best = $null
    try {
        if ([string]::IsNullOrWhiteSpace($sessionId)) { return $null }
        $bag = $null
        if (-not $script:Shared.PendingCommands.TryGetValue($sessionId, [ref]$bag)) { return $null }
        foreach ($pair in @($bag.GetEnumerator())) {
            $info = $null
            try { $info = $pair.Value | ConvertFrom-Json } catch { continue }
            $status = [string]$info.status
            if ($status -ne 'queued' -and $status -ne 'delivered' -and $status -ne 'received' -and $status -ne 'started' -and $status -ne 'running' -and $status -ne 'cancel_requested') { continue }
            if ($null -eq $best -or [int64]$info.queuedAt -lt [int64]$best.queuedAt) { $best = $info }
        }
    } catch {}
    return $best
}

function Invoke-PlaceRowCancel {
    # Version 7.0.7: Abbrechen laeuft OHNE Server-Funktionen (die UI sieht nur
    # den gemeinsamen Zustand). Dieselben Schritte wie Request-CommandCancel im
    # Handler-Runspace: Abbruchwunsch merken, FIFO bereinigen, Long-Poll wecken
    # und den wartenden Aufrufer sofort mit COMMAND_CANCELLED beantworten.
    param([string]$sessionId)
    try {
        if ([string]::IsNullOrWhiteSpace($sessionId)) { return }
        $sid = Get-UiDeliverySession $sessionId
        $cmd = Get-PlaceOpenCommand $sid
        if ($null -eq $cmd) { return }
        $commandId = [string]$cmd.commandId
        $toolName = [string]$cmd.tool
        $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        $cancelKey = ($sid + ':' + $commandId)
        $script:Shared.CancelRequests[$cancelKey] = $now
        # FIFO bereinigen, damit der Befehl nicht erneut zugestellt wird.
        try {
            $bag = $null
            if ($script:Shared.PendingCommands.TryGetValue($sid, [ref]$bag)) {
                $removedInfo = $null
                [void]$bag.TryRemove($commandId, [ref]$removedInfo)
            }
            $queue = $null
            if ($script:Shared.CommandQueues.TryGetValue($sid, [ref]$queue)) {
                $kept = New-Object System.Collections.Generic.List[string]
                $raw = $null
                while ($queue.TryDequeue([ref]$raw)) {
                    $drop = $false
                    try { $item = $raw | ConvertFrom-Json; if ([string]$item.id -eq $commandId) { $drop = $true } } catch {}
                    if (-not $drop) { $kept.Add([string]$raw) }
                }
                foreach ($itemJson in $kept) { $queue.Enqueue([string]$itemJson) }
            }
        } catch {}
        # Den wartenden Aufrufer sofort beantworten (kein 55-s-Warten mehr).
        try {
            $removedPayload = $null
            [void]$script:Shared.CommandPayloads.TryRemove($commandId, [ref]$removedPayload)
            $resultJson = (@{
                ok = $false
                code = 'COMMAND_CANCELLED'
                commandId = $commandId
                tool = $toolName
                error = 'Vom Nutzer in der Place-Zeile abgebrochen.'
                workIsLost = $false
                partialChangesPossible = ([int64]$cmd.startedAt -gt 0)
                retrySafe = $false
            } | ConvertTo-Json -Depth 8 -Compress)
            $script:Shared.CommandResults[$commandId] = $resultJson
            $script:Shared.CompletedCommandIds[$cancelKey] = $now
            $waiter = $null
            if ($script:Shared.ResultSignals.TryGetValue($commandId, [ref]$waiter)) {
                try { $waiter.Set() } catch {}
            }
        } catch {}
        # Long-Poll wecken: das Plugin sieht den Abbruch in der naechsten Antwort.
        try {
            $signal = $null
            if ($script:Shared.CommandSignals.TryGetValue($sid, [ref]$signal)) { try { $signal.Set() } catch {} }
        } catch {}
        try { $script:Shared.Telemetry.RowCancels = [long]$script:Shared.Telemetry.RowCancels + 1 } catch {}
        Write-RuntimeLog ("Place-Zeile: Befehl " + $toolName + " (" + $commandId + ") wurde vom Nutzer abgebrochen (COMMAND_CANCELLED, Queue frei).")
    } catch {
        Write-UiErrorLog 'Befehl aus der Place-Zeile konnte nicht abgebrochen werden' $_
    }
}

function Write-UiStationThrottled {
    # Version 7.2.0: Stationen der Oberflaeche, gedrosselt (eine Zeile je
    # Schluessel und Intervall). Der UI-Tick laeuft alle 250 ms - ohne Drosselung
    # wuerde runtime.log vollaufen (Lehre aus 6.0.4: Stationen ja, aber bezahlt).
    param([string]$Area, [string]$FlowId, [string]$Station, $Fields = $null, [int]$EverySeconds = 5)
    try {
        if ($null -eq $script:UiStationLogAt) { $script:UiStationLogAt = @{} }
        $key = $Area + ':' + $FlowId + ':' + $Station
        $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        $last = [int64]0
        try { if ($script:UiStationLogAt.ContainsKey($key)) { $last = [int64]$script:UiStationLogAt[$key] } } catch {}
        if (($now - $last) -lt $EverySeconds) { return }
        $script:UiStationLogAt[$key] = $now
        Write-FlowTrace $Area $FlowId $Station $Fields
    } catch {}
}

function Update-PlaceProgressVisual {
    param($Row, $Studio)
    if ($null -eq $Row -or $null -eq $Row.ProgressPanel) { return }
    $show = $true
    try { $show = [bool]$script:Shared.BridgeSettings.progressInPlaceList } catch {}
    $sessionId = [string]$Studio.sessionId
    $snapshot = Get-ProgressStateSnapshot $sessionId
    # Version 7.0.6: Die Bridge kennt den ECHTEN Befehlszustand. Version 7.2.0
    # (D7): er VERDRAENGT den Fortschritt aber nicht mehr - bis 7.1.5 wurde der
    # Balken ausgeblendet und durch "Befehl: <tool> - <status> seit X s" plus
    # einen Abbrechen-Knopf ersetzt. Genau das hat der Owner als Stoerung
    # gemeldet ("der schoene Balken wird durch irgendeine Abbrechen-Taste
    # ersetzt"). Der Befehl ist jetzt Zusatzinformation im Tooltip, und
    # abgebrochen wird ueber das Menue der Place-Zeile.
    $openCmd = Get-PlaceOpenCommand (Get-UiDeliverySession $sessionId)
    if (-not $show -or ($null -eq $snapshot -and $null -eq $openCmd)) {
        $Row.ProgressPanel.Visibility = 'Collapsed'
        $Row.ProgressState = 'idle'
        try { if ($Row.CommandCancelButton) { $Row.CommandCancelButton.Visibility = 'Collapsed' } } catch {}
        return
    }

    $state = 'working'
    $percent = 0
    $percentKnown = $false
    $silent = 0
    $lastTool = ''
    $message = ''
    $callsWithoutPercent = 0
    $sourceSid = ''
    if ($null -ne $snapshot) {
        $state = [string]$snapshot.State
        $percent = [int][math]::Round([double]$snapshot.Percent, 0)
        if ($percent -lt 0) { $percent = 0 }
        if ($percent -gt 100) { $percent = 100 }
        $percentKnown = [bool]$snapshot.PercentKnown
        $silent = [int]$snapshot.SilentSeconds
        $lastTool = [string]$snapshot.LastTool
        $message = [string]$snapshot.Message
        $callsWithoutPercent = [int]$snapshot.CallsWithoutPercent
        $sourceSid = [string]$snapshot.SessionId
    }

    # Offener Studio-Befehl: zusaetzliche Information, kein Ersatz.
    $commandText = ''
    if ($null -ne $openCmd) {
        $status = [string]$openCmd.status
        $ageBase = [int64]$openCmd.startedAt
        if ($ageBase -le 0) { $ageBase = [int64]$openCmd.queuedAt }
        $age = 0
        try { if ($ageBase -gt 0) { $age = [int][Math]::Max(0, ([DateTimeOffset]::UtcNow.ToUnixTimeSeconds() - $ageBase)) } } catch {}
        $commandText = ('Studio-Befehl: ' + [string]$openCmd.tool + ' - ' + $status + ' seit ' + [string]$age + ' s.')
        try {
            if ($Row.CommandCancelButton) {
                $Row.CommandCancelButton.Tag = $sessionId
                # Der Knopf bleibt unsichtbar: Er ersetzt seit 7.2.0 nicht mehr
                # die Fortschrittsanzeige (D7). Die Funktion liegt im Menue.
                $Row.CommandCancelButton.Visibility = 'Collapsed'
            }
        } catch {}
        Add-UiChannelCount 'ProgressNotDisplaced' 1
    }

    # Version 7.2.0 (D8): unauffaelliger Hinweis auf wartende Nutzernachrichten.
    # Kein neues Feld in der Zeile, keine Farbe, kein Blinken - die Zahl steht
    # im Tooltip und im Menue.
    $userBadgeText = ''
    try { $userBadgeText = Get-UserMessageBadgeText $sessionId } catch {}

    $color = '#FF4C9BFF'      # arbeitet = blau
    $label = 'Arena arbeitet gerade...'
    if ($state -eq 'done') { $color = '#FF38D16C'; $label = 'Fertig!' }
    elseif ($state -eq 'waiting') { $color = '#FF8A93A6'; $label = 'Seit über einer Minute kein Bridge Aufruf mehr' }
    elseif ($state -eq 'error') { $color = '#FFE11D48'; $label = 'Fehler' }
    # Version 7.2.0: Die Nachricht der KI wird SICHTBAR (sie stand bis hier nur
    # im Tooltip, deshalb sah die Zeile aus, als ob nichts passiert).
    if ($state -ne 'done' -and $state -ne 'waiting' -and -not [string]::IsNullOrWhiteSpace($message)) { $label = $message }

    # 100% bleibt nach report_done exakt 60 s sichtbar, danach verschwindet
    # nur die Zeilenanzeige; der Verlauf bleibt fuer Diagnose/Prompt erhalten.
    if ($state -eq 'done' -and $percent -ge 100 -and $snapshot.SilentSeconds -ge 60) {
        $Row.ProgressPanel.Visibility = 'Collapsed'
        $Row.ProgressState = 'idle'
        try { if ($Row.CommandCancelButton) { $Row.CommandCancelButton.Visibility = 'Collapsed' } } catch {}
        return
    }

    $Row.ProgressPanel.Visibility = 'Visible'
    $Row.ProgressState = $state
    $tooltip = Format-ProgressMessage $snapshot
    if (-not [string]::IsNullOrWhiteSpace($commandText)) { $tooltip = $tooltip + [Environment]::NewLine + $commandText }
    if (-not [string]::IsNullOrWhiteSpace($userBadgeText)) { $tooltip = $tooltip + [Environment]::NewLine + $userBadgeText + ' - Menue (...) der Place-Zeile: "Nachricht an Arena senden".' }

    if ($percentKnown -or $state -eq 'done') {
        # ECHTE Zahl gemeldet: Balken + Prozent wie gewohnt.
        Set-Text $Row.ProgressText $label
        $Row.ProgressText.Visibility = 'Collapsed'
        $Row.ProgressText.Foreground = Get-Brush $color
        $Row.ProgressBar.Visibility = 'Visible'
        $Row.ProgressPercent.Visibility = 'Visible'
        $Row.ProgressBar.Value = $percent
        $Row.ProgressBar.Foreground = Get-Brush $color
        $Row.ProgressPercent.Text = ($percent.ToString() + ' % • ' + $label)
        $Row.ProgressPercent.Foreground = Get-Brush $color
        Add-UiChannelCount 'ProgressPaintedPercent' 1
        Write-UiStationThrottled 'PROGRESS' ($sessionId.Substring(0, [Math]::Min(8, $sessionId.Length))) 'UI_PAINTED' @{ mode = 'percent'; percent = $percent; state = $state; tool = $lastTool; sidSource = $sourceSid; command = $(if ($null -ne $openCmd) { [string]$openCmd.tool + ':' + [string]$openCmd.status } else { '-' }) } 5
    } else {
        # KEINE Zahl gemeldet (D5/D6): kein Balken und keine erfundene 0 %,
        # sondern Klartext darueber, was messbar passiert.
        $textLine = $label
        if (-not [string]::IsNullOrWhiteSpace($lastTool)) { $textLine = $textLine + ' - ' + $lastTool }
        if ($silent -gt 0) { $textLine = $textLine + ' - vor ' + [string]$silent + ' s' }
        Set-Text $Row.ProgressText $textLine
        $Row.ProgressText.Visibility = 'Visible'
        $Row.ProgressText.Foreground = Get-Brush $color
        $Row.ProgressBar.Visibility = 'Collapsed'
        $Row.ProgressPercent.Visibility = 'Collapsed'
        if ($null -ne $snapshot) { $tooltip = $tooltip + [Environment]::NewLine + ('Kein Prozent gemeldet (' + [string]$callsWithoutPercent + ' Aufruf(e) ohne Zahl) - deshalb zeigt die Zeile keinen Balken und keine erfundene 0 %. Arena bekommt in jeder Antwort PERCENT_MISSING.') }
        Add-UiChannelCount 'ProgressPaintedNoPercent' 1
        Write-UiStationThrottled 'PROGRESS' ($sessionId.Substring(0, [Math]::Min(8, $sessionId.Length))) 'UI_PAINTED' @{ mode = 'text_no_percent'; percent = '-'; state = $state; tool = $lastTool; callsWithoutPercent = $callsWithoutPercent; sidSource = $sourceSid } 5
    }
    try { if ($Row.CommandCancelButton) { if ($null -eq $openCmd) { $Row.CommandCancelButton.Visibility = 'Collapsed' } } } catch {}
    $Row.ProgressText.ToolTip = $tooltip
    $Row.ProgressPanel.ToolTip = $tooltip
    try { $Row.ProgressBar.ToolTip = $tooltip } catch {}
    try { $Row.ProgressPercent.ToolTip = $tooltip } catch {}
}

function Get-ProgressDiagnoseLines {
    $lines = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($pair in $script:Shared.ProgressStates.GetEnumerator()) {
            $state = $null
            try { $state = ($pair.Value | ConvertFrom-Json) } catch { $state = $null }
            if ($null -eq $state) { continue }
            $name = ''
            try { $name = [string]$script:PlaceNames[[string]$pair.Key] } catch {}
            if ([string]::IsNullOrWhiteSpace($name)) { $name = [string]$pair.Key }
            $knownText = 'nein'
            try { if ($state.PSObject.Properties['percentKnown'] -and [bool]$state.percentKnown) { $knownText = 'ja' } } catch {}
            $withPercent = 0
            try { if ($state.PSObject.Properties['callsWithPercent']) { $withPercent = [int]$state.callsWithPercent } } catch {}
            $lastTool = ''
            try { if ($state.PSObject.Properties['lastTool']) { $lastTool = [string]$state.lastTool } } catch {}
            $lines.Add(('  {0}: {1} % / {2} - "{3}"' -f $name, [string]$state.percent, [string]$state.state, [string]$state.message))
            $lines.Add(('      Prozent von Arena gemeldet: {0} (Aufrufe mit Zahl: {1}, letztes Werkzeug: {2})' -f $knownText, [string]$withPercent, $(if ($lastTool) { $lastTool } else { '-' })))
            foreach ($h in @($state.history)) { $lines.Add('      ' + [string]$h) }
        }
    } catch {}
    return ,$lines
}



function Get-ChannelStations {
    # Stationen eines Bereichs aus dem Ringpuffer (neueste zuerst, begrenzt).
    param([string]$Area, [int]$Max = 40)
    $lines = New-Object System.Collections.Generic.List[string]
    try {
        $all = $script:Shared.FlowTrace.ToArray()
        for ($i = $all.Length - 1; $i -ge 0; $i--) {
            $line = [string]$all[$i]
            if ($line -notmatch (' ' + [regex]::Escape(([string]$Area).ToUpperInvariant()) + ' \[')) { continue }
            $lines.Add($line)
            if ($lines.Count -ge $Max) { break }
        }
    } catch {}
    return ,$lines
}

function Get-ChannelCountText {
    param([string]$Name)
    try {
        $channel = $script:Shared.Channel
        if ($null -ne $channel -and $channel.ContainsKey($Name)) { return [string]$channel[$Name] }
    } catch {}
    return '-'
}

function Write-ChannelDiagnoseFile {
    # Version 7.2.0: kleine, vollstaendig weitergebbare Kurzberichte fuer die
    # beiden Kanaele, die bis 7.1.5 nicht messbar waren (Vorbild:
    # preview-diagnose.txt aus 6.0.4). Ohne -Force hoechstens alle 10 Sekunden.
    param([switch]$Force)
    try {
        $now = Get-Date
        if (-not $Force -and ($now - $script:ChannelDiagLastWrite).TotalSeconds -lt 10) { return }
        $script:ChannelDiagLastWrite = $now
        $identity = ''
        try { $identity = [string]$script:PreviewDiagIdentity } catch {}
        $notifyOn = $false
        try { $notifyOn = [bool]$script:Shared.BridgeSettings.notifyOnDone } catch {}
        $progressOn = $true
        try { $progressOn = [bool]$script:Shared.BridgeSettings.progressInPlaceList } catch {}

        $progressPath = Join-Path $script:AppDataRoot 'progress-diagnose.txt'
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine('Arena Roblox Bridge - Kurzbericht Fortschrittsanzeige (Version 7.4.1)')
        [void]$sb.AppendLine('Diese Datei ist klein und kann komplett weitergegeben werden.')
        [void]$sb.AppendLine(('Erstellt: {0:yyyy-MM-dd HH:mm:ss}' -f $now))
        [void]$sb.AppendLine(('Laufzeit-Identitaet: {0}' -f $(if ($identity) { $identity } else { '(noch nicht ermittelt)' })))
        [void]$sb.AppendLine(('Schalter "Fortschritt in der Place-Liste anzeigen": {0}' -f $(if ($progressOn) { 'AN' } else { 'AUS' })))
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine('Zaehler (laufen immer mit):')
        [void]$sb.AppendLine(('  Arena-Aufrufe gesamt:            {0}' -f (Get-ChannelCountText 'ProgressCalls')))
        [void]$sb.AppendLine(('  Aufrufe MIT Prozentzahl:         {0}' -f (Get-ChannelCountText 'ProgressWithPercent')))
        [void]$sb.AppendLine(('  Aufrufe OHNE Prozentzahl:        {0}' -f (Get-ChannelCountText 'ProgressMissingPercent')))
        [void]$sb.AppendLine(('  Zeile mit Balken gezeichnet:     {0}' -f (Get-ChannelCountText 'ProgressPaintedPercent')))
        [void]$sb.AppendLine(('  Zeile als Text gezeichnet:       {0}' -f (Get-ChannelCountText 'ProgressPaintedNoPercent')))
        [void]$sb.AppendLine(('  Fortschritt nicht verdraengt:    {0}' -f (Get-ChannelCountText 'ProgressNotDisplaced')))
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine('Zustand je Sitzung:')
        $progressLines = Get-ProgressDiagnoseLines
        if ($progressLines.Count -gt 0) {
            foreach ($diagLine in $progressLines) { [void]$sb.AppendLine([string]$diagLine) }
        } else {
            [void]$sb.AppendLine('  (kein Fortschrittszustand gespeichert)')
        }
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine('Letzte PROGRESS-Stationen (neueste zuerst):')
        $stations = Get-ChannelStations 'PROGRESS' 40
        if ($stations.Count -gt 0) {
            foreach ($station in $stations) { [void]$sb.AppendLine('  ' + [string]$station) }
        } else {
            [void]$sb.AppendLine('  (noch keine PROGRESS-Station protokolliert)')
        }
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine(('Vollstaendiges Protokoll: {0}' -f [string]$script:RuntimeLog))
        [System.IO.File]::WriteAllText($progressPath, $sb.ToString(), (New-Object System.Text.UTF8Encoding($true)))

        $notifyPath = Join-Path $script:AppDataRoot 'notify-diagnose.txt'
        $sb2 = New-Object System.Text.StringBuilder
        [void]$sb2.AppendLine('Arena Roblox Bridge - Kurzbericht Fertig-Meldung (Version 7.4.1)')
        [void]$sb2.AppendLine('Diese Datei ist klein und kann komplett weitergegeben werden.')
        [void]$sb2.AppendLine(('Erstellt: {0:yyyy-MM-dd HH:mm:ss}' -f $now))
        [void]$sb2.AppendLine(('Laufzeit-Identitaet: {0}' -f $(if ($identity) { $identity } else { '(noch nicht ermittelt)' })))
        [void]$sb2.AppendLine(('Schalter "Benachrichtigung, wenn Arena fertig ist": {0}' -f $(if ($notifyOn) { 'AN' } else { 'AUS - report_done antwortet NOTIFICATIONS_DISABLED und es erscheint keine Meldung' })))
        [void]$sb2.AppendLine('')
        [void]$sb2.AppendLine('Zaehler (laufen immer mit):')
        [void]$sb2.AppendLine(('  Meldungen eingereiht:            {0}' -f (Get-ChannelCountText 'NotifyEnqueued')))
        [void]$sb2.AppendLine(('  Meldungen angezeigt:             {0}' -f (Get-ChannelCountText 'NotifyShown')))
        [void]$sb2.AppendLine(('  von Windows unterdrueckt:        {0}' -f (Get-ChannelCountText 'NotifySuppressed')))
        [void]$sb2.AppendLine(('  Aufruf fehlgeschlagen:           {0}' -f (Get-ChannelCountText 'NotifyFailed')))
        [void]$sb2.AppendLine(('  nach Aufruf nicht bestaetigt:    {0}' -f (Get-ChannelCountText 'NotifyUnverified')))
        [void]$sb2.AppendLine(('  letztes Urteil:                  {0}' -f (Get-ChannelCountText 'NotifyLastVerdict')))
        [void]$sb2.AppendLine(('  letzter Grund:                   {0}' -f (Get-ChannelCountText 'NotifyLastReason')))
        [void]$sb2.AppendLine('')
        [void]$sb2.AppendLine('Windows-Plattform (gemessen, nicht geraten):')
        try {
            $platformNow = Update-NotifyPlatformCache -Force
            if ($null -ne $platformNow) {
                [void]$sb2.AppendLine(('  Urteil:                          {0}' -f [string]$platformNow.verdict))
                [void]$sb2.AppendLine(('  Grund:                           {0}' -f [string]$platformNow.reason))
                [void]$sb2.AppendLine(('  Benachrichtigungen global:       {0}' -f $(if ($null -eq $platformNow.globalToastsEnabled) { 'unbekannt' } elseif ($platformNow.globalToastsEnabled) { 'an' } else { 'AUS' })))
                [void]$sb2.AppendLine(('  Benachrichtigungen fuer die App: {0}' -f $(if ($null -eq $platformNow.appNotificationsEnabled) { 'unbekannt' } elseif ($platformNow.appNotificationsEnabled) { 'an' } else { 'AUS' })))
                [void]$sb2.AppendLine(('  Fokus-Assistent:                 {0}' -f [string]$platformNow.focusAssist))
                [void]$sb2.AppendLine(('  Vordergrund:                     {0}' -f [string]$platformNow.foreground))
                [void]$sb2.AppendLine(('  App-Id registriert:              {0}' -f $(if ($platformNow.appUserModelIdRegistered) { 'ja' } else { 'nein' })))
                [void]$sb2.AppendLine(('  Startmenue-Verknuepfung:         {0}' -f $(if ($platformNow.startMenuShortcut) { 'ja' } else { 'nein' })))
                [void]$sb2.AppendLine(('  Windows-Build:                   {0}' -f [string]$platformNow.windowsBuild))
            } else {
                [void]$sb2.AppendLine('  (Plattform-Check nicht verfuegbar)')
            }
        } catch {}
        try {
            if ($null -ne $script:NotifyAumidState) {
                [void]$sb2.AppendLine(('  Registrierung:                   {0} - {1}' -f [string]$script:NotifyAumidState.verdict, [string]$script:NotifyAumidState.reason))
                [void]$sb2.AppendLine(('  Verknuepfung:                    {0}' -f [string]$script:NotifyAumidState.shortcutPath))
            }
        } catch {}
        [void]$sb2.AppendLine('')
        [void]$sb2.AppendLine('Letzte Meldungen:')
        $notifyRecords = Get-NotifyDiagnoseLines
        foreach ($recordLine in $notifyRecords) { [void]$sb2.AppendLine([string]$recordLine) }
        [void]$sb2.AppendLine('')
        [void]$sb2.AppendLine('Letzte NOTIFY-Stationen (neueste zuerst):')
        $notifyStations = Get-ChannelStations 'NOTIFY' 40
        if ($notifyStations.Count -gt 0) {
            foreach ($station in $notifyStations) { [void]$sb2.AppendLine('  ' + [string]$station) }
        } else {
            [void]$sb2.AppendLine('  (noch keine NOTIFY-Station protokolliert)')
        }
        [void]$sb2.AppendLine('')
        [void]$sb2.AppendLine(('Vollstaendiges Protokoll: {0}' -f [string]$script:RuntimeLog))
        [System.IO.File]::WriteAllText($notifyPath, $sb2.ToString(), (New-Object System.Text.UTF8Encoding($true)))
    } catch {}
}

# ----------------------------------------------------------------------------
# Version 7.0.0: UEBERGABE ALS KARTE IM BRIDGE-FENSTER
# Grosse Karte mit Kopier-Knopf und "Arena AI oeffnen" - genau wie gefordert.
# ----------------------------------------------------------------------------
$script:HandoffWindow = $null
$script:HandoffShownStamp = ''

function Open-HandoffWindow {
    param($Record)
    if ($null -eq $Record) { return }
    if ($script:HandoffWindow) {
        try { $script:HandoffWindow.Close() } catch {}
        $script:HandoffWindow = $null
    }
    $win = [System.Windows.Window]::new()
    $win.Title = 'Uebergabe'
    $win.Width = 720
    $win.Height = 640
    $win.MinWidth = 720; $win.MinHeight = 640; $win.MaxWidth = 720; $win.MaxHeight = 640
    $win.WindowStartupLocation = 'CenterOwner'
    $win.WindowStyle = 'None'
    $win.AllowsTransparency = $true
    $win.Background = [System.Windows.Media.Brushes]::Transparent
    $win.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe UI')
    try { $win.Owner = $window } catch {}
    $shell = [System.Windows.Controls.Border]::new()
    $shell.CornerRadius = [System.Windows.CornerRadius]::new(18)
    $shell.Background = Get-Brush '#F50B1030'
    $shell.BorderBrush = Get-Brush '#33FFFFFF'
    $shell.BorderThickness = [System.Windows.Thickness]::new(1)
    $shell.Padding = [System.Windows.Thickness]::new(20)
    $grid = [System.Windows.Controls.Grid]::new()
    foreach ($h in @('Auto', 'Auto', '*', 'Auto')) {
        $rd = [System.Windows.Controls.RowDefinition]::new()
        if ($h -ne 'Auto') { $rd.Height = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        [void]$grid.RowDefinitions.Add($rd)
    }
    $head = [System.Windows.Controls.TextBlock]::new()
    $head.Text = [string]$Record.headline
    $head.Foreground = Get-Brush '#F4F8FF'
    $head.FontSize = 24
    $head.FontWeight = 'Bold'
    $head.TextWrapping = 'Wrap'
    [System.Windows.Controls.Grid]::SetRow($head, 0)
    [void]$grid.Children.Add($head)
    $sub = [System.Windows.Controls.TextBlock]::new()
    $sub.Text = ('Gespeichert: ' + [string]$Record.path + "`n" + 'Diesen Block unveraendert in einen neuen Chat mit Bridge-Zugriff kopieren - er wird beim naechsten Start automatisch mitgeliefert.')
    $sub.Foreground = Get-Brush '#9AA9CE'
    $sub.FontSize = 11.5
    $sub.TextWrapping = 'Wrap'
    $sub.Margin = [System.Windows.Thickness]::new(0, 8, 0, 12)
    [System.Windows.Controls.Grid]::SetRow($sub, 1)
    [void]$grid.Children.Add($sub)
    $box = [System.Windows.Controls.TextBox]::new()
    $box.Text = [string]$Record.markdown
    $box.IsReadOnly = $true
    $box.TextWrapping = 'Wrap'
    $box.AcceptsReturn = $true
    $box.VerticalScrollBarVisibility = 'Auto'
    $box.Background = Get-Brush '#33101838'
    $box.Foreground = Get-Brush '#DCE6FF'
    $box.BorderBrush = Get-Brush '#26FFFFFF'
    $box.FontFamily = [System.Windows.Media.FontFamily]::new('Consolas')
    $box.FontSize = 12
    $box.Padding = [System.Windows.Thickness]::new(10)
    [System.Windows.Controls.Grid]::SetRow($box, 2)
    [void]$grid.Children.Add($box)
    $buttons = [System.Windows.Controls.StackPanel]::new()
    $buttons.Orientation = 'Horizontal'
    $buttons.HorizontalAlignment = 'Right'
    $buttons.Margin = [System.Windows.Thickness]::new(0, 14, 0, 0)
    $copy = [System.Windows.Controls.Button]::new()
    $copy.Content = 'Block kopieren'
    $copy.Width = 160; $copy.Height = 40
    $copy.Background = Get-Brush '#E61FA34A'
    $copy.Foreground = Get-Brush '#FFFFFF'
    $copy.BorderBrush = Get-Brush '#4DFFFFFF'
    $copy.Cursor = 'Hand'
    $copy.Add_Click({
        try {
            [System.Windows.Clipboard]::SetText([string]$s.Tag)
            Show-CopyConfirm 'Uebergabe kopiert - jetzt in einen neuen Chat einfuegen'
        } catch {}
    })
    $copy.Tag = [string]$Record.markdown
    $arena = [System.Windows.Controls.Button]::new()
    $arena.Content = 'Arena AI oeffnen'
    $arena.Width = 170; $arena.Height = 40
    $arena.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
    $arena.Background = Get-Brush '#E11D48'
    $arena.Foreground = Get-Brush '#FFFFFF'
    $arena.BorderBrush = Get-Brush '#66FF5C77'
    $arena.Cursor = 'Hand'
    $arena.Add_Click({ Open-ArenaAiPage })
    $close = [System.Windows.Controls.Button]::new()
    $close.Content = 'Schliessen'
    $close.Width = 120; $close.Height = 40
    $close.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
    $close.Background = Get-Brush '#3D3D5A80'
    $close.Foreground = Get-Brush '#F4F8FF'
    $close.BorderBrush = Get-Brush '#3DFFFFFF'
    $close.Cursor = 'Hand'
    $close.Add_Click({ try { $s.Tag.Close() } catch {} })
    $close.Tag = $win
    [void]$buttons.Children.Add($copy)
    [void]$buttons.Children.Add($arena)
    [void]$buttons.Children.Add($close)
    [System.Windows.Controls.Grid]::SetRow($buttons, 3)
    [void]$grid.Children.Add($buttons)
    $shell.Child = $grid
    $win.Content = $shell
    $win.Add_Closed({ $script:HandoffWindow = $null })
    $script:HandoffWindow = $win
    try { [void]$win.Show() } catch { try { [void]$win.ShowDialog() } catch {} }
}

function Update-HandoffCard {
    # Wird bei jedem UI-Tick aufgerufen: erscheint eine NEUE Uebergabe, oeffnet
    # sich die Karte GENAU EINMAL (kein Popup-Spam, keine Dauerschleife).
    try {
        foreach ($pair in $script:Shared.Handoffs.GetEnumerator()) {
            $record = $null
            try { $record = ($pair.Value | ConvertFrom-Json) } catch { $record = $null }
            if ($null -eq $record) { continue }
            $stamp = [string]$record.savedAt
            if ([string]::IsNullOrWhiteSpace($stamp)) { continue }
            if ($stamp -eq $script:HandoffShownStamp) { continue }
            $script:HandoffShownStamp = $stamp
            Open-HandoffWindow $record
            break
        }
    } catch {}
}

function Open-ArenaAiPage {
    try {
        Start-Process 'https://arena.ai/agent/' | Out-Null
    } catch {
        try { Write-RuntimeLog ('Arena-AI-Link konnte nicht geoeffnet werden: ' + $_.Exception.Message) } catch {}
    }
}

function Test-StandardPlaceName {
    param([string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return $true }
    $value = $Name.Trim()
    if ($value -match '^place\s*\d*$') { return $true }
    if ($value -match '^(baseplate|untitled.*|unbenannt.*|new place|neues place|my place|mein place)$') { return $true }
    if ($value -match '^\d+$') { return $true }
    return $false
}

function Get-StudioWindowName {
    # Version 7.0.0: Diese Liste liefert nur noch NORMALISIERTE Titel als
    # Hinweis. Sie ist ausdruecklich KEIN Namensvorrat: verliehen wird nichts.
    if (((Get-Date) - $script:WindowNameCacheAt).TotalSeconds -lt 4) {
        return $script:WindowNameCache
    }
    $names = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($info in @(Get-StudioWindowInfos)) {
            $clean = Get-NormalizedPlaceName ([string]$info.Title)
            if ([string]::IsNullOrWhiteSpace($clean)) { continue }
            if (-not $names.Contains($clean)) { $names.Add($clean) }
        }
    } catch {}
    $script:WindowNameCache = [string[]]$names.ToArray()
    $script:WindowNameCacheAt = Get-Date
    return $script:WindowNameCache
}

function Get-PlaceName {
    param($Studio, $WindowNames)

    $sessionId = [string]$Studio.sessionId
    $reported = Repair-Mojibake ([string]$Studio.placeName)
    Save-PlaceIdentity $sessionId $Studio $null 'name' | Out-Null

    # 1) AUTORITATIV: der vom Plugin gemeldete echte Place-Name (game.Name).
    #    Er wird nie durch einen Fenstertitel ersetzt - nur durch einen
    #    gleichwertigen, wenn das Plugin den Place umbenennt.
    $reportedName = Get-NormalizedPlaceName $reported
    if ([string]::IsNullOrWhiteSpace($reportedName) -and -not (Test-StandardPlaceName $reported) -and -not [string]::IsNullOrWhiteSpace($reported)) {
        # Der Plugin-Name ist bereits sauber (z. B. "obby"); Normalisierung
        # wuerde nur dann greifen, wenn er wie ein Fenstertitel aussieht.
        $reportedName = $reported.Trim()
    }
    if (-not [string]::IsNullOrWhiteSpace($reportedName)) {
        [void](Save-PlaceName $sessionId $reportedName 'plugin')
        Save-PlaceIdentity $sessionId $Studio $null 'pluginName' | Out-Null
        return [string]$script:PlaceNames[$sessionId]
    }

    # 2) Ein einmal erkannter guter Name bleibt - und wird nie durch einen
    #    schlechteren Titel ueberschrieben (Save-PlaceName prueft das).
    if ($script:PlaceNames.ContainsKey($sessionId)) { return [string]$script:PlaceNames[$sessionId] }

    # 3) FALLBACK: nur der Titel des EIGENEN, exklusiv gebundenen Fensters.
    #    Niemals ein freier Titel aus einer gemeinsamen Liste - genau das
    #    liess zwei Fenster denselben Namen "ausleihen".
    $identity = Resolve-PlaceWindowIdentity $Studio $sessionId
    if ($identity.ProcessId -gt 0 -and $identity.WindowHandle -ne [IntPtr]::Zero) {
        $candidate = Get-NormalizedPlaceName ([string]$identity.WindowTitle)
        if (-not [string]::IsNullOrWhiteSpace($candidate)) {
            [void](Save-PlaceName $sessionId $candidate 'windowTitle')
            Save-PlaceIdentity $sessionId $Studio $null 'windowTitle' | Out-Null
            return [string]$script:PlaceNames[$sessionId]
        }
    }

    # 4) Letzter Fallback: seiteneindeutiger Arbeitsname aus der Session-Id.
    #    KEIN Standardname und KEIN Ausleihen - so bleibt jede Zeile eindeutig.
    $fallback = 'Place ' + $sessionId.Substring([Math]::Max(0, $sessionId.Length - 4))
    [void](Save-PlaceName $sessionId $fallback 'sessionFallback')
    return [string]$script:PlaceNames[$sessionId]
}

function Get-PlaceDisplayName {
    param($Studio, $WindowNames)

    $sessionId = ''
    try { $sessionId = [string]$Studio.sessionId } catch {}
    try {
        $name = [string](Get-PlaceName $Studio $WindowNames)
        if (-not [string]::IsNullOrWhiteSpace($name)) { return $name }
    } catch {
        if (-not [string]::IsNullOrWhiteSpace($sessionId) -and -not $script:PlaceNameResolveErrorLogged.ContainsKey($sessionId)) {
            $script:PlaceNameResolveErrorLogged[$sessionId] = $true
            Write-UiErrorLog ("Place-Name konnte nicht aufgeloest werden (sid=$sessionId); verwende einen sichtbaren Fallback") $_
        }
    }

    $reported = ''
    try { $reported = Repair-Mojibake ([string]$Studio.placeName) } catch {}
    if (-not [string]::IsNullOrWhiteSpace($reported)) {
        $reported = $reported.Trim()
        if ($reported.Length -gt 80) { $reported = $reported.Substring(0, 77) + '…' }
        return $reported
    }
    if (-not [string]::IsNullOrWhiteSpace($sessionId)) {
        $suffixLength = [Math]::Min(6, $sessionId.Length)
        return 'Place ' + $sessionId.Substring($sessionId.Length - $suffixLength)
    }
    return 'Verbundenes Place'
}

# ----------------------------------------------------------------------------
# FENSTER-VORSCHAU DER STUDIO-FENSTER (LIVE)  -  AUFNAHME + LAUFZEIT-DIAGNOSE
# ----------------------------------------------------------------------------
# 6.0.1 ersetzte die nie ankommenden Roblox-Spiel-Icons durch eine echte
# Live-Vorschau des zugehoerigen Studio-Fensters, 6.0.2 machte Fehler
# sichtbar, 6.0.3 reparierte die Fensterlisten-Verschachtelung und nahm per
# PrintWindow(PW_RENDERFULLCONTENT) auf. Beim Nutzer blieb die Kachel
# trotzdem leer - alle bisherigen Fixes beruhten auf Quellcode-Mutmassungen,
# ohne dass ein einziger Aufnahmeversuch im runtime.log belegt war.
#
# 6.0.4 aendert das zweimal grundlegend:
#
# 1) MESSEN STATT RATEN: Jeder Aufnahmeversuch traegt eine kompakte Ablauf-ID
#    und protokolliert die Stationen CAPTURE_START -> WINDOWS_ENUMERATED ->
#    HANDLE_RESOLVED -> WORKER_STARTED -> WORKER_COMPLETED -> RESULT_RECEIVED
#    -> PNG_DECODED -> IMAGE_ASSIGNED -> IMAGE_VISIBLE. Jede Zeile fuehrt
#    sid, PID, HWND, Fenstertitel, Datentyp, Byte-Anzahl, Bildgroesse und
#    Fehlertext mit. Kein catch im Vorschaupfad bleibt mehr still.
#
# 2) ROBUSTE UEBERTRAGUNG: Die Aufnahme laeuft ueber den einmal kompilierten
#    C#-Helfer Arena.PreviewCapture im Hauptprozess. Das Ergebnis ist ein
#    CLR-Objekt mit echtem byte[] - es durchquert keine PowerShell-Runspace-
#    Grenze mehr (scheitert schon das Kompilieren, wird der 6.0.3-Runspace-
#    Worker begruendet als Fallback benutzt). Die UI-Zuweisung laeuft
#    ausschliesslich ueber den WPF-Dispatcher, und zusaetzlich wird jede
#    Aufnahme atomar als PNG-Datei pro Sitzung abgelegt (pruefbare Uebergabe).
#
# Fuer verdeckte/GPU-beschleunigte Studio-Fenster testet der Helfer der
# Reihe nach: PrintWindow(PW_RENDERFULLCONTENT), PrintWindow(0),
# WindowDcBitBlt (DWM-Umleitflaeche) und zuletzt CopyFromScreen. Ein Weg gilt
# nur als erfolgreich, wenn die Bitmap nicht schwarz/transparent ist.
# ----------------------------------------------------------------------------

# --- Ablauf-ID + Stations-Log (jede Zeile komplett, kompakt) ----------------
function New-PreviewFlowId {
    $script:PreviewFlowCounter = [long]$script:PreviewFlowCounter + 1
    return ('cap-{0}' -f [long]$script:PreviewFlowCounter)
}

function Clear-PreviewFlow {
    param([string]$FlowId)
    try { [void]$script:PreviewFlowContexts.Remove([string]$FlowId) } catch {}
}

# --- Version 6.0.5: Kurzbericht + ehrliche Sichtbarkeitsmessung -------------
function Add-PreviewDiagLine {
    # Haelt die letzten Vorschau-Zeilen fuer preview-diagnose.txt vor.
    param([string]$Line)
    try {
        if ($null -eq $script:PreviewDiagLines) { $script:PreviewDiagLines = New-Object System.Collections.Generic.List[string] }
        $script:PreviewDiagLines.Add(('{0:HH:mm:ss} {1}' -f (Get-Date), $Line))
        while ($script:PreviewDiagLines.Count -gt 60) { $script:PreviewDiagLines.RemoveAt(0) }
    } catch {}
}

function Write-PreviewDiagnoseFile {
    # Schreibt einen kleinen, vollstaendig weitergebbaren Kurzbericht:
    # Laufzeit-Identitaet, Aufnahme-Modus, Selbsttest-Urteil, PNG-Ablage und
    # die letzten Stationen. Ohne -Force hoechstens alle 10 Sekunden.
    param([switch]$Force)
    try {
        $now = Get-Date
        if (-not $Force -and ($now - $script:PreviewDiagLastWrite).TotalSeconds -lt 10) { return }
        $script:PreviewDiagLastWrite = $now
        $path = Join-Path $script:AppDataRoot 'preview-diagnose.txt'
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine('Arena Roblox Bridge - Kurzbericht Fenster-Vorschau (Version 7.4.1)')
        [void]$sb.AppendLine('Diese Datei ist klein und kann komplett weitergegeben werden.')
        [void]$sb.AppendLine(('Erstellt: {0:yyyy-MM-dd HH:mm:ss}' -f $now))
        [void]$sb.AppendLine(('Laufzeit-Identitaet: {0}' -f $(if ($script:PreviewDiagIdentity) { [string]$script:PreviewDiagIdentity } else { '(noch nicht ermittelt)' })))
        [void]$sb.AppendLine(('Aufnahme-Modus: {0}{1}' -f [string]$script:PreviewCaptureMode, $(if ($script:PreviewCaptureModeReason) { ' - Grund: ' + [string]$script:PreviewCaptureModeReason } else { '' })))
        [void]$sb.AppendLine(('UI-Selbsttest: {0}' -f $(if ($script:PreviewSelfTestVerdict) { [string]$script:PreviewSelfTestVerdict } else { '(noch kein Ergebnis)' })))
        [void]$sb.AppendLine(('Vollstaendiges Protokoll: {0}' -f [string]$script:RuntimeLog))
        $dir = Join-Path $script:AppDataRoot 'preview-cache'
        [void]$sb.AppendLine(('PNG-Ablage: {0}' -f $dir))
        try {
            if (Test-Path -LiteralPath $dir) {
                $files = @(Get-ChildItem -LiteralPath $dir -Filter '*.png' -ErrorAction SilentlyContinue)
                if ($files.Count -eq 0) { [void]$sb.AppendLine('  (keine PNG-Datei vorhanden)') }
                foreach ($f in $files) { [void]$sb.AppendLine(('  {0}  {1} Bytes  {2:yyyy-MM-dd HH:mm:ss}' -f $f.Name, $f.Length, $f.LastWriteTime)) }
            } else {
                [void]$sb.AppendLine('  (Ordner existiert nicht - es wurde noch keine Aufnahme gespeichert)')
            }
        } catch {}
        [void]$sb.AppendLine('')
        [void]$sb.AppendLine('Letzte Stationen der Fenster-Vorschau:')
        if ($script:PreviewDiagLines -and $script:PreviewDiagLines.Count -gt 0) {
            foreach ($diagLine in $script:PreviewDiagLines) { [void]$sb.AppendLine('  ' + [string]$diagLine) }
        } else {
            [void]$sb.AppendLine('  (noch keine Vorschau-Station protokolliert)')
        }
        [System.IO.File]::WriteAllText($path, $sb.ToString(), (New-Object System.Text.UTF8Encoding($true)))
    } catch {}
}

function Get-PlacePreviewVisualState {
    # Version 6.0.5: Misst die GANZE Sichtbarkeitskette der Kachel - Bild,
    # Rahmen und Zeile. "Zugewiesen" ist nicht "sichtbar": Ein Bild mit
    # Deckkraft 0 (haengende Einblend-Animation) meldet IsVisible=true und
    # sah in 6.0.4 wie ein Erfolg aus.
    param($Row)
    $state = @{
        isVisible = $false; visibility = '-'; opacity = '-'; actualW = 0; actualH = 0
        source = '-'; spinner = '-'; fallback = '-'
        frameVisibility = '-'; frameOpacity = '-'; frameActual = '0x0'
        rowVisibility = '-'; rowOpacity = '-'
        effOpacity = 0.0; inRows = $false; reallyVisible = $false; reason = ''
    }
    try {
        $img = $null
        try { $img = $Row.IconImage } catch {}
        if ($null -eq $img) { $state.reason = 'IconImage fehlt'; return $state }
        $imgOpacity = 1.0
        try { $state.isVisible = [bool]$img.IsVisible } catch {}
        try { $state.visibility = [string]$img.Visibility } catch {}
        try { $imgOpacity = [double]$img.Opacity; $state.opacity = [string]$img.Opacity } catch {}
        try { $state.actualW = [int]$img.ActualWidth; $state.actualH = [int]$img.ActualHeight } catch {}
        try { if ($img.Source) { $state.source = ([int]$img.Source.PixelWidth).ToString() + 'x' + ([int]$img.Source.PixelHeight).ToString() } } catch {}
        try { $state.spinner = [string]$Row.IconSpinner.Visibility } catch {}
        try { $state.fallback = [string]$Row.IconFallback.Visibility } catch {}
        $frameOpacity = 1.0
        try {
            if ($Row.IconFrame) {
                $state.frameVisibility = [string]$Row.IconFrame.Visibility
                $frameOpacity = [double]$Row.IconFrame.Opacity
                $state.frameOpacity = [string]$Row.IconFrame.Opacity
                $state.frameActual = ([int]$Row.IconFrame.ActualWidth).ToString() + 'x' + ([int]$Row.IconFrame.ActualHeight).ToString()
            }
        } catch {}
        $rowOpacity = 1.0
        try {
            if ($Row.Root) {
                $state.rowVisibility = [string]$Row.Root.Visibility
                $rowOpacity = [double]$Row.Root.Opacity
                $state.rowOpacity = [string]$Row.Root.Opacity
            }
        } catch {}
        try { $state.inRows = $script:UiRows.ContainsKey([string]$Row.sessionId) } catch {}
        try { $state.effOpacity = [math]::Round(($imgOpacity * $frameOpacity * $rowOpacity), 3) } catch {}
        $grounds = New-Object System.Collections.Generic.List[string]
        if (-not $state.isVisible) { $grounds.Add('nicht im sichtbaren Baum (IsVisible=false)') }
        if ([double]$state.effOpacity -le 0.05) { $grounds.Add('effektive Deckkraft ' + [string]$state.effOpacity + ' (Bild=' + [string]$imgOpacity + ', Rahmen=' + [string]$frameOpacity + ', Zeile=' + [string]$rowOpacity + ')') }
        if ([int]$state.actualW -le 0 -or [int]$state.actualH -le 0) { $grounds.Add('Flaeche 0x0 (kein Layout)') }
        try { if ($null -eq $img.Source) { $grounds.Add('keine Bildquelle gesetzt') } } catch {}
        if ($grounds.Count -eq 0) { $state.reallyVisible = $true } else { $state.reason = ($grounds -join '; ') }
    } catch {
        $state.reason = [string]$_.Exception.Message
    }
    return $state
}

function Format-PlacePreviewVisualState {
    param($State)
    return ('isVisible=' + [string]$State.isVisible + ' visibility=' + [string]$State.visibility +
        ' opacity=' + [string]$State.opacity + ' eff=' + [string]$State.effOpacity +
        ' actual=' + [string]$State.actualW + 'x' + [string]$State.actualH +
        ' source=' + [string]$State.source + ' spinner=' + [string]$State.spinner +
        ' fallback=' + [string]$State.fallback +
        ' frame=' + [string]$State.frameVisibility + '/' + [string]$State.frameOpacity + '/' + [string]$State.frameActual +
        ' row=' + [string]$State.rowVisibility + '/' + [string]$State.rowOpacity +
        ' rowInUiRows=' + [string]$State.inRows +
        ' grund=' + $(if ($State.reason) { [string]$State.reason } else { '-' }))
}

function Start-PlacePreviewVisibilityVerify {
    # Version 6.0.5: Das Urteil ueber "sichtbar" faellt NICHT direkt nach der
    # Zuweisung (da laeuft die Einblendung noch), sondern 1,5 s spaeter -
    # Animation (260 ms) und Einblend-Waechter (400 ms) sind dann durch.
    # Fehlt die Zeile PREVIEW_UI_VERIFY spaeter im Protokoll ganz, laufen in
    # diesem Prozess keine Dispatcher-Timer - auch das ist dann bewiesen.
    param($Row, [string]$FlowId, [bool]$IsSelfTest, [int]$DecodedW, [int]$DecodedH, [int]$ByteCount)
    try {
        if (-not $IsSelfTest) {
            # Je Zeile nur einmal nachmessen (der Selbsttest misst immer).
            $alreadyVerified = $false
            try { $alreadyVerified = [bool]$Row.PreviewVerifyDone } catch {}
            if ($alreadyVerified) { return }
            try { $Row.PreviewVerifyDone = $true } catch {
                try { $Row | Add-Member -NotePropertyName 'PreviewVerifyDone' -NotePropertyValue $true -Force } catch {}
            }
        }
        $verifyTimer = [System.Windows.Threading.DispatcherTimer]::new()
        $verifyTimer.Interval = [System.TimeSpan]::FromMilliseconds(1500)
        $verifyTimer.Tag = [pscustomobject]@{ Row = $Row; Flow = [string]$FlowId; SelfTest = [bool]$IsSelfTest; W = [int]$DecodedW; H = [int]$DecodedH; Bytes = [int]$ByteCount }
        $verifyTimer.Add_Tick({
            param($s, $e)
            $s.Stop()
            try {
                $info = $s.Tag
                $state = Get-PlacePreviewVisualState $info.Row
                $verifyLine = 'PREVIEW_UI_VERIFY sid=' + [string]$info.Row.sessionId + ' flow=' + [string]$info.Flow +
                    ' sichtbar=' + [string]$state.reallyVisible + ' ' + (Format-PlacePreviewVisualState $state) +
                    ' decoded=' + [string]$info.W + 'x' + [string]$info.H + ' bytes=' + [string]$info.Bytes
                Write-RuntimeLog $verifyLine
                Add-PreviewDiagLine $verifyLine
                if ($info.SelfTest) {
                    if ($state.reallyVisible) {
                        $verdict = 'PREVIEW_UI_SELFTEST_OK sid=' + [string]$info.Row.sessionId + ' flow=' + [string]$info.Flow +
                            ' decoded=' + [string]$info.W + 'x' + [string]$info.H + ' bytes=' + [string]$info.Bytes +
                            ' eff=' + [string]$state.effOpacity + ' actual=' + [string]$state.actualW + 'x' + [string]$state.actualH
                    } else {
                        $verdict = 'PREVIEW_UI_SELFTEST_FAILED sid=' + [string]$info.Row.sessionId + ' flow=' + [string]$info.Flow +
                            ' grund=' + [string]$state.reason + ' (' + (Format-PlacePreviewVisualState $state) + ')'
                    }
                    Write-RuntimeLog $verdict
                    Add-PreviewDiagLine $verdict
                    $script:PreviewSelfTestVerdict = $verdict
                    Write-PreviewDiagnoseFile -Force
                }
            } catch {
                try { Write-RuntimeLog ('PREVIEW_UI_VERIFY Messfehler: ' + [string]$_.Exception.Message) } catch {}
            }
        })
        $verifyTimer.Start()
    } catch {
        try { Write-RuntimeLog ('PREVIEW_UI_VERIFY konnte nicht geplant werden: ' + [string]$_.Exception.Message) } catch {}
    }
}

function Write-PreviewTrace {
    param([string]$FlowId, [string]$Station, [hashtable]$Set, [string]$Extra = '')
    if ([string]::IsNullOrWhiteSpace($FlowId)) { return }
    try {
        if ($script:PreviewFlowContexts.Count -gt 512) { $script:PreviewFlowContexts.Clear() }
        if (-not $script:PreviewFlowContexts.ContainsKey($FlowId)) {
            $script:PreviewFlowContexts[$FlowId] = @{ sid = '-'; pid = '-'; hwnd = '-'; title = '-'; type = '-'; bytes = '-'; w = '-'; h = '-'; error = '-' }
        }
        $ctx = $script:PreviewFlowContexts[$FlowId]
        if ($Set) { foreach ($key in $Set.Keys) { $ctx[$key] = [string]$Set[$key] } }
        $title = [string]$ctx.title
        if ($title.Length -gt 48) { $title = $title.Substring(0, 48) }
        $errText = ([string]$ctx.error) -replace '[\r\n]+', ' | '
        if ($errText.Length -gt 160) { $errText = $errText.Substring(0, 160) }
        $sizeText = ([string]$ctx.w) + 'x' + ([string]$ctx.h)
        $line = 'PREVIEW [{0}] {1} sid={2} pid={3} hwnd={4} title="{5}" type={6} bytes={7} size={8} error={9}' -f $FlowId, $Station, $ctx.sid, $ctx.pid, $ctx.hwnd, $title, $ctx.type, $ctx.bytes, $sizeText, $errText
        if (-not [string]::IsNullOrWhiteSpace($Extra)) { $line += ' ' + $Extra }
        Write-RuntimeLog $line
        Add-PreviewDiagLine $line
    } catch {}
}

function Save-PreviewHandleMeta {
    param([string]$SessionId, $Info, [string]$Reason, [string]$RowTitle = '')
    try {
        $procId = $null
        $titleValue = ''
        if ($null -ne $Info) {
            try { $procId = [int]$Info.ProcessId } catch { $procId = $null }
            try { $titleValue = [string]$Info.Title } catch { $titleValue = '' }
        }
        $script:PreviewHandleInfos[[string]$SessionId] = [pscustomobject]@{ ProcessId = $procId; Title = $titleValue; Reason = $Reason; RowTitle = $RowTitle; At = (Get-Date) }
    } catch {}
}

function Get-StudioWindowInfos {
    # Kurzer Cache (1.5 s): Fenster kommen/gehen selten, ein Neuenumerieren
    # bei jedem 900-ms-Tick waere unnoetiger Overhead.
    if (((Get-Date) - $script:PreviewWindowCacheAt).TotalSeconds -lt 1.5) {
        # Kein unitaeres Komma: Das wuerde object[] als EIN Pipeline-Objekt
        # zurueckgeben und beim Aufrufer erneut in object[] einpacken.
        return $script:PreviewWindowCache
    }
    $infos = New-Object System.Collections.Generic.List[object]
    try {
        foreach ($processName in @('RobloxStudioBeta', 'RobloxStudio')) {
            foreach ($proc in @(Get-Process -Name $processName -ErrorAction SilentlyContinue)) {
                if ($null -eq $proc -or $proc.MainWindowHandle -eq [IntPtr]::Zero) { continue }
                $title = [string]$proc.MainWindowTitle
                $clean = ($title -replace '\s*[-–]\s*Roblox Studio\s*$', '').Trim()
                $infos.Add([pscustomobject]@{ Handle = [IntPtr]$proc.MainWindowHandle; Title = $clean; ProcessId = [int]$proc.Id })
            }
        }
    } catch {}
    # Version 6.0.3: Eine Funktion schreibt Arrays ohnehin elementweise in
    # die PowerShell-Pipeline. `return , $array` unterdrueckt genau dieses
    # Entrollen und erzeugte beim Aufrufer `@(Get-...)` ein object[][].
    # Bei mehreren Fenstern wurde deshalb der Ein-Fenster-Zweig genommen und
    # ein komplettes Handle-Array nach IntPtr gecastet - die Aufnahme startete
    # nie. Hier deshalb bewusst KEIN unitaeres Komma.
    $script:PreviewWindowCache = [object[]]$infos.ToArray()
    $script:PreviewWindowCacheAt = Get-Date
    return $script:PreviewWindowCache
}

function Resolve-PlacePreviewHandle {
    param($Studio, $Row)
    $sessionId = [string]$Studio.sessionId
    $rowTitle = ''
    try { $rowTitle = ([string]$Row.Title.Text).Trim() } catch { $rowTitle = '' }
    $infos = @(Get-StudioWindowInfos)
    if ($infos.Count -eq 0) {
        Save-PreviewHandleMeta $sessionId $null 'keineStudioFensterGefunden' $rowTitle
        return [IntPtr]::Zero
    }
    # Version 7.0.0: ZUERST die gebundene Identitaet (PID + HWND). Nur wenn
    # sie fehlt, wird gesucht - und jede Bindung wird exklusiv beansprucht,
    # damit zwei Zeilen nie dasselbe Fenster zeigen.
    $identity = Resolve-PlaceWindowIdentity $Studio $sessionId
    if ($identity.ProcessId -gt 0 -and $identity.WindowHandle -ne [IntPtr]::Zero) {
        foreach ($info in $infos) {
            if ([IntPtr]$info.Handle -eq [IntPtr]$identity.WindowHandle) {
                Save-PreviewHandleMeta $sessionId $info ('identitaet:' + [string]$identity.BindReason) $rowTitle
                return [IntPtr]$info.Handle
            }
        }
    }
    # Nur EIN Studio-Fenster offen: keine Titel-Rateaktion noetig.
    if ($infos.Count -eq 1) {
        $script:PreviewHandleClaims[[int64]$infos[0].Handle] = $sessionId
        Save-PlaceIdentity $sessionId $Studio $infos[0] 'einzelnesFenster' | Out-Null
        Save-PreviewHandleMeta $sessionId $infos[0] 'einzelnesFenster' $rowTitle
        return [IntPtr]$infos[0].Handle
    }
    # Mehrere Fenster: demselben angezeigten Namen zuordnen, den Get-PlaceName
    # fuer diese Zeile bereits gewaehlt hat (dieselbe Kandidatenliste, die die
    # Namensanzeige seit Version 5 zur Unterscheidung mehrerer Fenster nutzt).
    # Version 6.0.2: robust gegen Leerraum an den Enden, Gross-/Klein-
    # schreibung und angehaengte Zusaetze (z. B. den versionMismatch-Hinweis
    # "Studio neu starten (Plugin veraltet)").
    $wanted = Get-NormalizedPlaceName $rowTitle
    foreach ($info in $infos) {
        if (Test-PreviewHandleClaimed $info.Handle $sessionId) { continue }
        $infoTitle = Get-NormalizedPlaceName ([string]$info.Title)
        if (-not [string]::IsNullOrWhiteSpace($infoTitle) -and $infoTitle -eq $wanted) {
            $script:PreviewHandleClaims[[int64]$info.Handle] = $sessionId
            Save-PlaceIdentity $sessionId $Studio $info 'titelExakt' | Out-Null
            Save-PreviewHandleMeta $sessionId $info 'titelExakt' $rowTitle
            return [IntPtr]$info.Handle
        }
    }
    $comparable = $wanted -replace '\s+-\s+Studio neu starten \(Plugin veraltet\)\s*$', ''
    $comparable = $comparable.Trim()
    if (-not [string]::IsNullOrWhiteSpace($comparable)) {
        foreach ($info in $infos) {
            if (Test-PreviewHandleClaimed $info.Handle $sessionId) { continue }
            $infoTitle = Get-NormalizedPlaceName ([string]$info.Title)
            if ([string]::IsNullOrWhiteSpace($infoTitle)) { continue }
            if ($infoTitle.StartsWith($comparable, [System.StringComparison]::OrdinalIgnoreCase) -or
                $comparable.StartsWith($infoTitle, [System.StringComparison]::OrdinalIgnoreCase)) {
                $script:PreviewHandleClaims[[int64]$info.Handle] = $sessionId
                Save-PlaceIdentity $sessionId $Studio $info 'titelTolerant' | Out-Null
                Save-PreviewHandleMeta $sessionId $info 'titelTolerant' $rowTitle
                return [IntPtr]$info.Handle
            }
        }
    }
    # Titel gerade uneindeutig/leer: den zuletzt zugeordneten Handle behalten,
    # solange das Fenster noch existiert (verhindert Flackern).
    if ($script:PlacePreviewHandles.ContainsKey($sessionId)) {
        $previousRaw = $script:PlacePreviewHandles[$sessionId]
        if ($null -ne $previousRaw) {
            $previous = [IntPtr]$previousRaw
            foreach ($info in $infos) {
                if ([IntPtr]$info.Handle -eq $previous) {
                    Save-PreviewHandleMeta $sessionId $info 'letzterHandle' $rowTitle
                    return $previous
                }
            }
        }
    }
    Save-PreviewHandleMeta $sessionId $null 'keinTrefferBeiMehrerenFenstern' $rowTitle
    return [IntPtr]::Zero
}

function Set-PlacePreviewImage {
    param($Row, [byte[]]$Bytes, [string]$FlowId)
    $flow = [string]$FlowId
    if ([string]::IsNullOrWhiteSpace($flow)) { $flow = 'ui-direct' }
    if ($null -eq $Row -or $null -eq $Row.IconImage) {
        Write-PreviewTrace $flow 'IMAGE_ASSIGN_SKIPPED' $null 'grund=Zeile/IconImage fehlt'
        Clear-PreviewFlow $flow
        return
    }
    if (-not $Bytes -or $Bytes.Length -eq 0) {
        Write-PreviewTrace $flow 'IMAGE_ASSIGN_SKIPPED' @{ sid = [string]$Row.sessionId; bytes = 0 } 'grund=leere Bytes'
        Clear-PreviewFlow $flow
        return
    }
    $isSelfTest = $flow.StartsWith('selftest')
    $apply = {
        $decodedW = 0
        $decodedH = 0
        try {
            $magicOk = ($Bytes.Length -ge 8 -and $Bytes[0] -eq 0x89 -and $Bytes[1] -eq 0x50 -and $Bytes[2] -eq 0x4E -and $Bytes[3] -eq 0x47)
            $stream = New-Object System.IO.MemoryStream (,$Bytes)
            $bitmap = [System.Windows.Media.Imaging.BitmapImage]::new()
            $bitmap.BeginInit()
            $bitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
            $bitmap.StreamSource = $stream
            $bitmap.EndInit()
            $bitmap.Freeze()
            $stream.Dispose()
            $decodedW = [int]$bitmap.PixelWidth
            $decodedH = [int]$bitmap.PixelHeight
            Write-PreviewTrace $flow 'PNG_DECODED' @{ sid = [string]$Row.sessionId; type = [string]$bitmap.GetType().FullName; bytes = $Bytes.Length; w = $decodedW; h = $decodedH } ('pngMagic=' + $(if ($magicOk) { 'ok' } else { 'FEHLER' }) + ' format=' + [string]$bitmap.Format)
            $Row.IconImage.Source = $bitmap
            try { Set-PlacePreviewSpinnerAnimation $Row.IconVisual $false } catch {}
            $Row.IconSpinner.Visibility = 'Collapsed'
            $Row.IconFallback.Visibility = 'Collapsed'
            $Row.IconImage.Visibility = 'Visible'
            # Version 6.0.5: Der Kachelrahmen muss sichtbar sein. Nur die
            # virtuelle "Alle Places"-Zeile blendet ihn absichtlich aus - die
            # bekommt hier ohnehin nie ein Bild.
            try {
                if ($Row.IconFrame -and ([string]$Row.sessionId) -ne '__arena_all_places__') { $Row.IconFrame.Visibility = 'Visible' }
            } catch {}
            $fadeNote = 'refresh'
            if (-not $Row.PreviewHasFrame) {
                # URSACHE DER LEEREN KACHEL (bis 6.0.4) UND IHR FIX:
                # Bis 6.0.4 stand hier Opacity = 0, und ob das Bild jemals
                # sichtbar wurde, hing ALLEIN an der Einblend-Animation.
                # Laeuft die nicht an, bleibt die Kachel dauerhaft leer,
                # obwohl Bildquelle, Visibility und Layout korrekt sind - und
                # das Protokoll meldete trotzdem Erfolg. Genau dieser Ausfall
                # ist in diesem Programm fuer die Place-Zeile bereits belegt
                # (5.0.2: "Einblend-Animation kam nie an", dort mit Waechter
                # aufgefangen; das Vorschaubild hatte keinen).
                # Jetzt gilt: sichtbar ZUERST (Opacity = 1), die Animation ist
                # nur noch Deko (FillBehavior = Stop gibt danach den lokalen
                # Wert 1 frei), und ein Waechter holt eine haengende
                # Einblendung nach 400 ms hart zurueck.
                $Row.PreviewHasFrame = $true
                $Row.IconImage.Opacity = 1
                try {
                    $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(260))
                    $fade.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
                    $Row.IconImage.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fade)
                    $fadeNote = 'fade-in'
                    $fadeGuard = [System.Windows.Threading.DispatcherTimer]::new()
                    $fadeGuard.Interval = [System.TimeSpan]::FromMilliseconds(400)
                    $fadeGuard.Tag = [pscustomobject]@{ Image = $Row.IconImage; Sid = [string]$Row.sessionId; Flow = $flow }
                    $fadeGuard.Add_Tick({
                        param($s, $e)
                        $s.Stop()
                        try {
                            $info = $s.Tag
                            $img = $info.Image
                            if ([double]$img.Opacity -lt 0.05) {
                                $img.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
                                $img.Opacity = 1
                                $rescueLine = 'PREVIEW_OPACITY_RESCUE sid=' + [string]$info.Sid + ' flow=' + [string]$info.Flow + ' grund=Einblend-Animation kam nie an - Vorschaubild hart auf sichtbar gestellt'
                                Write-RuntimeLog $rescueLine
                                Add-PreviewDiagLine $rescueLine
                            }
                        } catch {}
                    })
                    $fadeGuard.Start()
                } catch {
                    try { $Row.IconImage.Opacity = 1 } catch {}
                    $fadeNote = 'fade-in-fallback'
                }
            } else {
                $Row.IconImage.Opacity = 1
            }
            Write-PreviewTrace $flow 'IMAGE_ASSIGNED' @{ sid = [string]$Row.sessionId; type = 'System.Windows.Media.Imaging.BitmapImage'; bytes = $Bytes.Length; w = $decodedW; h = $decodedH } ('mode=' + $fadeNote)
            # Direkt nach dem Render-Durchlauf die Fakten messen (Clip,
            # Layout, Z-Index, ueberlagernder Spinner) - Version 6.0.5 faellt
            # hier bewusst KEIN Urteil mehr: Die Einblendung laeuft in diesem
            # Moment noch, eine Bewertung waere wertlos (genau daran hat sich
            # 6.0.4 selbst getaeuscht). Das Urteil kommt aus
            # Start-PlacePreviewVisibilityVerify nach 1,5 Sekunden.
            $measure = {
                try {
                    $state = Get-PlacePreviewVisualState $Row
                    Write-PreviewTrace $flow 'IMAGE_VISIBLE' @{ sid = [string]$Row.sessionId; w = $decodedW; h = $decodedH } (Format-PlacePreviewVisualState $state)
                } catch {
                    Write-PreviewTrace $flow 'IMAGE_VISIBLE' @{ error = [string]$_.Exception.Message }
                }
                try { Start-PlacePreviewVisibilityVerify $Row $flow $isSelfTest $decodedW $decodedH $Bytes.Length } catch {}
                Clear-PreviewFlow $flow
            }.GetNewClosure()
            try {
                [void]$Row.IconImage.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Render, [System.Action]$measure)
            } catch {
                # Das Messen ist nur Zusatzdiagnose - ein Fehler darf die
                # Anzeige selbst nicht stoppen, muss aber sichtbar bleiben.
                Write-PreviewTrace $flow 'IMAGE_VISIBLE' @{ error = [string]$_.Exception.Message } 'messdispatch=fehlgeschlagen'
                try { Start-PlacePreviewVisibilityVerify $Row $flow $isSelfTest $decodedW $decodedH $Bytes.Length } catch {}
                Clear-PreviewFlow $flow
            }
        } catch {
            Write-PreviewTrace $flow 'IMAGE_ASSIGN_FAILED' @{ sid = [string]$Row.sessionId; error = [string]$_.Exception.Message; bytes = $Bytes.Length; w = $decodedW; h = $decodedH }
            Write-UiErrorLog 'Place-Vorschau konnte nicht angezeigt werden' $_
            if ($isSelfTest) {
                $verdictFailed = 'PREVIEW_UI_SELFTEST_FAILED sid=' + [string]$Row.sessionId + ' flow=' + $flow + ' error=' + [string]$_.Exception.Message
                Write-RuntimeLog $verdictFailed
                Add-PreviewDiagLine $verdictFailed
                $script:PreviewSelfTestVerdict = $verdictFailed
                Write-PreviewDiagnoseFile -Force
            }
            Clear-PreviewFlow $flow
        }
    }.GetNewClosure()
    # UI-Zuweisung ausschliesslich ueber den Dispatcher des Fensters/Elements.
    try {
        if ($Row.IconImage.Dispatcher -and -not $Row.IconImage.Dispatcher.CheckAccess()) {
            [void]$Row.IconImage.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Normal, [System.Action]$apply)
        } else {
            & $apply
        }
    } catch {
        Write-PreviewTrace $flow 'IMAGE_ASSIGN_FAILED' @{ error = [string]$_.Exception.Message }
        Write-UiErrorLog 'Place-Vorschau konnte nicht angezeigt werden' $_
        Clear-PreviewFlow $flow
    }
}

function New-PlacePreviewSelfTestImage {
    # Unverwechselbar: Magenta/Neon-Limette-Schachbrett mit orangem Rand.
    # Wird komplett im Speicher gezeichnet - kein Fenster, kein Netzwerk.
    $bmp = New-Object System.Drawing.Bitmap 64, 44
    try {
        $colorA = [System.Drawing.Color]::FromArgb(255, 255, 0, 255)
        $colorB = [System.Drawing.Color]::FromArgb(255, 57, 255, 20)
        $colorEdge = [System.Drawing.Color]::FromArgb(255, 255, 128, 0)
        for ($y = 0; $y -lt 44; $y++) {
            for ($x = 0; $x -lt 64; $x++) {
                $color = $colorA
                if ($x -lt 3 -or $y -lt 3 -or $x -ge 61 -or $y -ge 41) { $color = $colorEdge }
                elseif (([int]($x / 8) + [int]($y / 8)) % 2 -eq 0) { $color = $colorB }
                $bmp.SetPixel($x, $y, $color)
            }
        }
        $memory = New-Object System.IO.MemoryStream
        try {
            $bmp.Save($memory, [System.Drawing.Imaging.ImageFormat]::Png)
            $result = $memory.ToArray()
        } finally { $memory.Dispose() }
        return , $result
    } finally { $bmp.Dispose() }
}

function Invoke-PlacePreviewUiSelfTest {
    param($Row, [string]$SessionId)
    # Derselbe Set-PlacePreviewImage-Pfad wie die echte Vorschau - aber mit
    # einem im Speicher gezeichneten, eindeutig farbigen Testbild. Erscheint
    # das Testbild nicht, liegt der Fehler in WPF/UI (nicht in der
    # Fensteraufnahme). Erscheint es, prueft ~2,5 s spaeter die echte
    # Aufnahme sichtbar dagegen. Ergebnis: PREVIEW_UI_SELFTEST_OK/FAILED.
    $flow = 'selftest-1'
    Write-PreviewTrace $flow 'CAPTURE_START' @{ sid = [string]$SessionId; pid = '-'; hwnd = '-'; title = '(in Speicher gezeichnetes Testbild)'; type = 'in-memory-png'; w = 64; h = 44 } 'origin=PREVIEW_UI_SELFTEST'
    try {
        Add-Type -AssemblyName System.Drawing -ErrorAction Stop
        $bytes = New-PlacePreviewSelfTestImage
        if (-not $bytes -or $bytes.Length -eq 0) { throw 'Testbild konnte nicht erzeugt werden (0 Bytes)' }
        Write-PreviewTrace $flow 'RESULT_RECEIVED' @{ sid = [string]$SessionId; type = [string]$bytes.GetType().FullName; bytes = $bytes.Length; w = 64; h = 44 } 'method=in-memory'
        Set-PlacePreviewImage $Row $bytes $flow
    } catch {
        Write-PreviewTrace $flow 'RESULT_RECEIVED' @{ sid = [string]$SessionId; error = [string]$_.Exception.Message }
        $verdictEarly = 'PREVIEW_UI_SELFTEST_FAILED sid=' + [string]$SessionId + ' error=' + [string]$_.Exception.Message
        Write-RuntimeLog $verdictEarly
        Add-PreviewDiagLine $verdictEarly
        $script:PreviewSelfTestVerdict = $verdictEarly
        Write-PreviewDiagnoseFile -Force
        Clear-PreviewFlow $flow
    }
}

function Set-PlacePreviewSpinnerAnimation {
    param($Visual, [bool]$Enabled)
    if ($null -eq $Visual -or $null -eq $Visual.Spinner -or $null -eq $Visual.SpinTransform) { return }
    $isRunning = ([string]$Visual.Spinner.Tag -eq 'ArenaPreviewSpinnerRunning')
    if ($Enabled) {
        if ($isRunning) { return }
        $animation = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 360, [TimeSpan]::FromSeconds(1.4))
        $animation.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $Visual.SpinTransform.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $animation)
        $Visual.Spinner.Tag = 'ArenaPreviewSpinnerRunning'
        return
    }
    if ($isRunning) {
        $Visual.SpinTransform.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null)
        $Visual.SpinTransform.Angle = 0
    }
    $Visual.Spinner.Tag = 'ArenaPreviewSpinnerStopped'
}

function New-PlacePreviewVisual {
    # Version 6.0.1: Live-Fenster-Vorschau statt Spiel-Icon. Etwas breiter als
    # das alte quadratische Icon (64x44 statt 46x46), damit ein Fenster-
    # Screenshot nicht unnoetig stark beschnitten wirkt.
    $frame = [System.Windows.Controls.Border]::new()
    $frame.Width = 64; $frame.Height = 44
    $frame.CornerRadius = [System.Windows.CornerRadius]::new(12)
    $frame.Background = Get-Brush '#E6FFFFFF'
    $frame.BorderBrush = Get-Brush '#59FFFFFF'
    $frame.BorderThickness = [System.Windows.Thickness]::new(1.2)
    $frame.Margin = [System.Windows.Thickness]::new(0, 0, 13, 0)
    $frame.ClipToBounds = $true
    $frame.ToolTip = 'Live-Vorschau des Roblox-Studio-Fensters'
    try { $frame.Effect = New-Shadow -Blur 10 -Opacity 0.30 } catch {}
    $iconHost = [System.Windows.Controls.Grid]::new()
    $image = [System.Windows.Controls.Image]::new()
    $image.Stretch = 'UniformToFill'
    $image.Clip = [System.Windows.Media.RectangleGeometry]::new([System.Windows.Rect]::new(0,0,64,44), 11, 11)
    $image.Visibility = 'Collapsed'
    $fallback = [System.Windows.Controls.TextBlock]::new()
    $fallback.Text = [char]0xE7F4
    $fallback.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe MDL2 Assets')
    $fallback.FontSize = 18
    $fallback.Foreground = Get-Brush '#5E7196'
    $fallback.HorizontalAlignment = 'Center'; $fallback.VerticalAlignment = 'Center'
    $fallback.Visibility = 'Collapsed'
    $spinner = [System.Windows.Shapes.Ellipse]::new()
    $spinner.Width = 24; $spinner.Height = 24
    $spinner.Stroke = Get-Brush '#00E5D0'; $spinner.StrokeThickness = 3
    # Version 6.1.3: Windows PowerShell 5.1 kann das object[] aus @(...)
    # nicht an den typisierten DoubleCollection-Konstruktor binden. Die Werte
    # deshalb ohne Ein-Argument-Konstruktor einzeln als double hinzufuegen.
    $strokeDashArray = [System.Windows.Media.DoubleCollection]::new()
    [void]$strokeDashArray.Add(4.0)
    [void]$strokeDashArray.Add(8.0)
    $spinner.StrokeDashArray = $strokeDashArray
    $spinner.StrokeDashCap = 'Round'
    $spinner.HorizontalAlignment = 'Center'; $spinner.VerticalAlignment = 'Center'
    $spinner.RenderTransformOrigin = [System.Windows.Point]::new(0.5, 0.5)
    $spinTransform = [System.Windows.Media.RotateTransform]::new(0)
    $spinner.RenderTransform = $spinTransform
    $iconHost.Children.Add($image) | Out-Null; $iconHost.Children.Add($fallback) | Out-Null; $iconHost.Children.Add($spinner) | Out-Null
    $frame.Child = $iconHost
    $visual = [pscustomobject]@{ Frame=$frame; Image=$image; Spinner=$spinner; Fallback=$fallback; SpinTransform=$spinTransform }
    if ($script:SettingsCache.editorIconsEnabled -ne $false) { Set-PlacePreviewSpinnerAnimation $visual $true }
    return $visual
}

function Start-PlacePreviewCapture {
    param($Studio, $Row)
    if ($null -eq $Row -or $null -eq $Row.IconFrame) { return }
    if ($script:SettingsCache.editorIconsEnabled -eq $false) {
        try { Set-PlacePreviewSpinnerAnimation $Row.IconVisual $false } catch {}
        try { $Row.IconFrame.Visibility = 'Collapsed' } catch {}
        return
    }
    try { $Row.IconFrame.Visibility = 'Visible' } catch {}
    if (-not $Row.PreviewHasFrame -and [int]$Row.PreviewFailCount -lt 3) {
        try { Set-PlacePreviewSpinnerAnimation $Row.IconVisual $true } catch {}
    }

    $sessionId = [string]$Studio.sessionId
    # Die virtuelle "Alle Places"-Zeile bekommt (erstmal) bewusst keine
    # Vorschau - siehe New-AllPlacesRow (Frame dort dauerhaft ausgeblendet).
    if ($sessionId -eq '__arena_all_places__') { return }
    # Performance-Bremse: Ist das Bridge-Fenster selbst minimiert, sieht
    # ohnehin niemand die Vorschau - dann auch keine neuen Aufnahmen starten.
    try { if ($window -and $window.WindowState -eq 'Minimized') { return } } catch {}

    # Bereits laufende Aufnahme: der naechste Tick rueckt erst nach, wenn sie
    # fertig ist - kein Log-Spam noetig (normale Skips sind keine Versuche).
    if ($script:PlacePreviewJobs.ContainsKey($sessionId)) { return }

    $handle = Resolve-PlacePreviewHandle $Studio $Row
    # Version 6.0.2: $null-fest. Ein nicht aufgeloester Handle darf nicht bis
    # zur Aufnahme durchreichen ($handle.ToInt64() warf sonst still).
    if ($null -eq $handle) { $handle = [IntPtr]::Zero }
    $Row.PreviewHandle = $handle
    if ($handle -eq [IntPtr]::Zero) {
        [void]$script:PlacePreviewHandles.Remove($sessionId)
        if (-not $Row.PreviewHasFrame) {
            # Erst nach 3 Ticks ohne Fenster auf das Platzhalter-Symbol fallen.
            $Row.PreviewFailCount = [int]$Row.PreviewFailCount + 1
            if ([int]$Row.PreviewFailCount -ge 3) {
                try { Set-PlacePreviewSpinnerAnimation $Row.IconVisual $false } catch {}
                try { $Row.IconSpinner.Visibility = 'Collapsed'; $Row.IconFallback.Visibility = 'Visible' } catch {}
            }
        }
        # Auch der Fehler VOR dem Worker bleibt sichtbar (gedrosselt).
        $now = Get-Date
        $lastLog = [DateTime]::MinValue
        if ($script:PlacePreviewFailLogAt.ContainsKey($sessionId)) { $lastLog = [DateTime]$script:PlacePreviewFailLogAt[$sessionId] }
        if (($now - $lastLog).TotalSeconds -ge 15) {
            $script:PlacePreviewFailLogAt[$sessionId] = $now
            $flow = New-PreviewFlowId
            $reason = '-'
            try {
                if ($script:PreviewHandleInfos.ContainsKey($sessionId)) { $reason = [string]$script:PreviewHandleInfos[$sessionId].Reason }
            } catch {}
            Write-PreviewTrace $flow 'HANDLE_RESOLVED' @{ sid = $sessionId; hwnd = '0x0'; error = 'kein passendes Fenster' } ('resolved=none reason=' + $reason)
            try { Write-RuntimeLog "Place-Vorschau ($sessionId): Aufnahme fehlgeschlagen - kein passendes Roblox-Studio-Fenster gefunden." } catch {}
            Clear-PreviewFlow $flow
        }
        return
    }
    $script:PlacePreviewHandles[$sessionId] = $handle

    # Gedrosselt: hoechstens alle $script:PlacePreviewIntervalSeconds je Sitzung.
    $lastAt = [DateTime]::MinValue
    if ($script:PlacePreviewLastCaptureAt.ContainsKey($sessionId)) { $lastAt = [DateTime]$script:PlacePreviewLastCaptureAt[$sessionId] }
    if (((Get-Date) - $lastAt).TotalSeconds -lt $script:PlacePreviewIntervalSeconds) { return }
    $script:PlacePreviewLastCaptureAt[$sessionId] = Get-Date

    # --- Ab hier: echter Aufnahmeversuch mit eigener Ablauf-ID. -------------
    $flow = New-PreviewFlowId
    $metaPid = '-'
    $metaTitle = '-'
    $metaReason = '-'
    $metaRowTitle = '-'
    try {
        if ($script:PreviewHandleInfos.ContainsKey($sessionId)) {
            $meta = $script:PreviewHandleInfos[$sessionId]
            if ($null -ne $meta.ProcessId) { $metaPid = [string]$meta.ProcessId }
            if ($meta.Title) { $metaTitle = (([string]$meta.Title) -replace '"', "'") }
            if ($meta.Reason) { $metaReason = [string]$meta.Reason }
            if ($meta.RowTitle) { $metaRowTitle = (([string]$meta.RowTitle) -replace '"', "'") }
        }
    } catch {}
    $handleValue = $handle.ToInt64()
    $hwndHex = '0x' + ('{0:X}' -f $handleValue)

    # WINDOWS_ENUMERATED + HANDLE_RESOLVED: die Fensterliste, die Resolve-
    # PlacePreviewHandle gerade benutzt hat (<=1,5 s alt), samt Zuordnungsgrund.
    $enumParts = New-Object System.Collections.Generic.List[string]
    foreach ($infoItem in @($script:PreviewWindowCache)) {
        try {
            $infoTitle = (([string]$infoItem.Title) -replace '"', "'")
            $enumParts.Add('pid=' + $infoItem.ProcessId + ';hwnd=0x' + ('{0:X}' -f [int64]$infoItem.Handle) + ';title="' + $infoTitle + '"')
        } catch {}
    }
    Write-PreviewTrace $flow 'WINDOWS_ENUMERATED' @{ sid = $sessionId } ('count=' + @($script:PreviewWindowCache).Count + ' [' + ($enumParts -join ' | ') + ']')
    Write-PreviewTrace $flow 'HANDLE_RESOLVED' @{ sid = $sessionId; pid = $metaPid; hwnd = $hwndHex; title = $metaTitle } ('reason=' + $metaReason + ' rowTitle="' + $metaRowTitle + '"')
    Write-PreviewTrace $flow 'CAPTURE_START' @{ sid = $sessionId; pid = $metaPid; hwnd = $hwndHex; title = $metaTitle } ('targetH=' + $script:PlacePreviewCaptureHeight)

    $targetHeight = $script:PlacePreviewCaptureHeight
    $job = [pscustomobject]@{ FlowId = $flow; SessionId = $sessionId; StartedAt = (Get-Date); Kind = ''; Task = $null; Worker = $null; Handle = $null }

    # Primaerweg 6.0.4: kompilierter C#-Helfer im Hauptprozess. Das Ergebnis
    # (unveraenderliches byte[]) durchquert keine Runspace-Grenze mehr.
    if ([string]$script:PreviewCaptureMode -eq 'csharp' -and ('Arena.PreviewCapture' -as [type])) {
        try {
            $job.Kind = 'csharp-helper'
            $job.Task = [Arena.PreviewCapture]::CaptureAsync($handleValue, [int]$targetHeight)
            $script:PlacePreviewJobs[$sessionId] = $job
            Write-PreviewTrace $flow 'WORKER_STARTED' $null 'kind=csharp-helper thread=threadpool'
            return
        } catch {
            Write-PreviewTrace $flow 'WORKER_START_FAILED' @{ error = [string]$_.Exception.Message } 'kind=csharp-helper'
            Write-UiErrorLog ('Place-Vorschau-Aufnahme ' + $sessionId + ' konnte nicht gestartet werden') $_
            Clear-PreviewFlow $flow
            return
        }
    }

    # Fallback (unveraendert aus 6.0.3): Hintergrund-Runspace-Worker - nur wenn
    # der C#-Helfer nicht kompiliert werden konnte. Grund steht im Start-Log
    # (PreviewCaptureMode=ps-fallback).
    $job.Kind = 'ps-runspace-fallback'
    $worker = $null
    $code = @'
param($handleValue, $targetHeight)
try {
    Add-Type -AssemblyName System.Drawing -ErrorAction Stop
    # Version 6.0.2: Der Worker haelt sich selbst versorgbar. Normalerweise
    # hat der Haupt-Runspace Arena.ScreenHelper bereits per Add-Type geladen
    # (prozessweit sichtbar). Falls DAS je scheiterte, starb hier bisher jede
    # Aufnahme still mit TypeNotFound - jetzt legt der Worker seinen eigenen
    # minimalen ScreenHelper nach.
    if (-not ('Arena.ScreenHelper' -as [type])) {
        Add-Type -TypeDefinition 'namespace Arena { [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)] public struct RECT { public int Left; public int Top; public int Right; public int Bottom; } public static class ScreenHelper { [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern bool IsIconic(System.IntPtr hWnd); [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern bool GetWindowRect(System.IntPtr hWnd, out RECT lpRect); [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern bool PrintWindow(System.IntPtr hWnd, System.IntPtr hdcBlt, uint nFlags); } }' -ErrorAction Stop
    }
    $hwnd = [IntPtr]$handleValue
    $rect = New-Object Arena.RECT
    if (-not [Arena.ScreenHelper]::GetWindowRect($hwnd, [ref]$rect)) {
        return @{ ok = $false; error = 'GetWindowRect fehlgeschlagen' }
    }
    $width = $rect.Right - $rect.Left
    $height = $rect.Bottom - $rect.Top
    if ($width -le 40 -or $height -le 40) { return @{ ok = $false; error = 'Fenstergroesse ungueltig' } }
    $full = [System.Drawing.Bitmap]::new($width, $height, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($full)
    $captureMethod = 'PrintWindow'
    $printed = $false
    try {
        # PW_RENDERFULLCONTENT (2): Windows rendert das Quellfenster selbst.
        # Anders als CopyFromScreen funktioniert das auch, wenn die Bridge vor
        # Studio liegt oder ein anderes Fenster Teile davon verdeckt.
        $hdc = $g.GetHdc()
        try { $printed = [Arena.ScreenHelper]::PrintWindow($hwnd, $hdc, 2) }
        finally { $g.ReleaseHdc($hdc) }
        # Einige GPU-beschleunigte Fenster melden bei PrintWindow Erfolg,
        # liefern aber nur eine komplett schwarze/transparente Bitmap. An
        # mehreren Punkten pruefen, statt so ein Schein-Ergebnis anzuzeigen.
        if ($printed) {
            $hasPixels = $false
            foreach ($px in @(2, [Math]::Max(2,[int]($width/2)), [Math]::Max(2,$width-3))) {
                foreach ($py in @(2, [Math]::Max(2,[int]($height/2)), [Math]::Max(2,$height-3))) {
                    $color = $full.GetPixel([Math]::Min($width-1,$px), [Math]::Min($height-1,$py))
                    if (($color.R + $color.G + $color.B) -gt 24) { $hasPixels = $true; break }
                }
                if ($hasPixels) { break }
            }
            if (-not $hasPixels) { $printed = $false }
        }
        if (-not $printed) {
            $captureMethod = 'CopyFromScreen-Fallback'
            $g.CopyFromScreen($rect.Left, $rect.Top, 0, 0, (New-Object System.Drawing.Size $width, $height))
        }
    } finally { $g.Dispose() }
    # Sofort auf Kachel-Groesse herunterskalieren (Performance!) - jedes
    # zusaetzliche Pixel darueber hinaus kostet nur Zeit/Speicher, ohne in der
    # kleinen Vorschau je sichtbar zu werden.
    $scale = $targetHeight / [double]$height
    $smallWidth = [Math]::Max(1, [int]($width * $scale))
    $small = New-Object System.Drawing.Bitmap $smallWidth, $targetHeight
    $g2 = [System.Drawing.Graphics]::FromImage($small)
    try {
        $g2.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBilinear
        $g2.DrawImage($full, 0, 0, $smallWidth, $targetHeight)
    } finally { $g2.Dispose() }
    $full.Dispose()
    $ms = New-Object System.IO.MemoryStream
    $small.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
    $small.Dispose()
    $bytes = $ms.ToArray()
    $ms.Dispose()
    return @{ ok = $true; bytes = $bytes; w = $smallWidth; h = $targetHeight; method = $captureMethod }
} catch {
    return @{ ok = $false; error = [string]$_.Exception.Message }
}
'@
    try {
        $worker = [PowerShell]::Create()
        [void]$worker.AddScript($code).AddArgument($handleValue).AddArgument($targetHeight)
        $job.Worker = $worker
        $job.Handle = $worker.BeginInvoke()
        $script:PlacePreviewJobs[$sessionId] = $job
        Write-PreviewTrace $flow 'WORKER_STARTED' $null 'kind=ps-runspace-fallback'
    } catch {
        try { $worker.Dispose() } catch {}
        Write-PreviewTrace $flow 'WORKER_START_FAILED' @{ error = [string]$_.Exception.Message } 'kind=ps-runspace-fallback'
        Write-UiErrorLog ('Place-Vorschau-Aufnahme ' + $sessionId + ' konnte nicht gestartet werden') $_
        Clear-PreviewFlow $flow
    }
}

function Update-PlacePreviewCaptures {
    if ($script:SettingsCache.editorIconsEnabled -eq $false) {
        foreach ($sessionId in @($script:PlacePreviewJobs.Keys)) {
            try {
                $job=$script:PlacePreviewJobs[$sessionId]
                if ($job.Worker) { try { $job.Worker.Stop() } catch {}; try { $job.Worker.Dispose() } catch {} }
                [void]$script:PlacePreviewJobs.Remove($sessionId)
            } catch {}
        }
        return
    }
    foreach ($sessionId in @($script:PlacePreviewJobs.Keys)) {
        $job = $script:PlacePreviewJobs[$sessionId]
        $flow = [string]$job.FlowId
        $isPsFallback = ([string]$job.Kind -eq 'ps-runspace-fallback')
        $completed = $false
        try {
            if ($isPsFallback) { $completed = [bool]$job.Handle.IsCompleted }
            else { $completed = ($null -ne $job.Task -and [bool]$job.Task.IsCompleted) }
        } catch { $completed = $false }
        if (-not $completed) {
            # Ein blockierter Aufnahmeaufruf darf diese Sitzung nicht fuer
            # immer sperren: Nach 10 s wird der Job fallengelassen (Task) bzw.
            # beendet (PS-Fallback); der normale Tick startet ihn neu. Der
            # UI-Thread wartet dabei NIE blockierend auf einen Worker.
            if ($job.StartedAt -and ((Get-Date) - [DateTime]$job.StartedAt).TotalSeconds -ge 10) {
                if ($isPsFallback) {
                    try { $job.Worker.Stop() } catch {}
                    try { $job.Worker.Dispose() } catch {}
                }
                $script:PlacePreviewJobs.Remove($sessionId)
                Write-PreviewTrace $flow 'WORKER_TIMEOUT' @{ error = 'Zeitueberschreitung nach 10 s' } ('kind=' + [string]$job.Kind)
                try { Write-RuntimeLog "Place-Vorschau ($sessionId): Aufnahme-Worker nach 10 Sekunden beendet (Zeitüberschreitung)." } catch {}
                Clear-PreviewFlow $flow
            }
            continue
        }
        $elapsedMs = '-'
        try { $elapsedMs = [string][int]((Get-Date) - [DateTime]$job.StartedAt).TotalMilliseconds } catch {}
        Write-PreviewTrace $flow 'WORKER_COMPLETED' $null ('kind=' + [string]$job.Kind + ' ms=' + $elapsedMs)

        $bytes = $null
        $resultOk = $false
        $resultError = ''
        $resultMethod = ''
        $resultAttempts = ''
        $resultType = '-'
        $resultW = '-'
        $resultH = '-'
        $minimized = $false
        $endError = ''
        try {
            if ($isPsFallback) {
                $workerResult = @($job.Worker.EndInvoke($job.Handle))[0]
                if ($workerResult) {
                    $resultOk = ($workerResult.ok -eq $true)
                    $minimized = ($workerResult.minimized -eq $true)
                    $resultError = [string]$workerResult.error
                    $resultMethod = [string]$workerResult.method
                    if ($resultOk -and $workerResult.bytes) {
                        $bytes = [byte[]]$workerResult.bytes
                        $resultType = [string]$workerResult.bytes.GetType().FullName
                    }
                    $resultW = [string]$workerResult.w
                    $resultH = [string]$workerResult.h
                }
            } else {
                # CLR-Ergebnis des C#-Helfers: byte[] ist hier GARANTIERT ein
                # echtes System.Byte[] - kein PSObject, kein Object[], keine
                # Serialisierung irgendwo dazwischen.
                $cap = $job.Task.Result
                if ($null -ne $cap) {
                    $resultOk = [bool]$cap.Ok
                    $minimized = [bool]$cap.Minimized
                    $resultError = [string]$cap.Error
                    $resultMethod = [string]$cap.Method
                    $resultAttempts = [string]$cap.AttemptLog
                    $resultW = [string]$cap.Width
                    $resultH = [string]$cap.Height
                    if ($resultOk -and $cap.Png) {
                        $bytes = [byte[]]$cap.Png
                        $resultType = [string]$cap.Png.GetType().FullName
                    }
                }
            }
        } catch {
            $endError = [string]$_.Exception.Message
            try { Write-RuntimeLog "Place-Vorschau ($sessionId): Aufnahme schlug fehl - $endError" } catch {}
        }
        if ($isPsFallback) { try { $job.Worker.Dispose() } catch {} }
        $script:PlacePreviewJobs.Remove($sessionId)

        $byteLen = 0
        if ($bytes) { $byteLen = $bytes.Length }
        $traceError = $resultError
        if ($endError) { $traceError = $endError }
        $resultExtra = 'ok=' + $resultOk + ' minimized=' + $minimized + ' method=' + $(if ($resultMethod) { $resultMethod } else { '-' })
        if ($resultAttempts) { $resultExtra += ' attempts=[' + $resultAttempts + ']' }
        Write-PreviewTrace $flow 'RESULT_RECEIVED' @{ type = $resultType; bytes = $byteLen; w = $resultW; h = $resultH; error = $traceError } $resultExtra

        if ($bytes -and $script:UiRows.ContainsKey($sessionId)) {
            # Eindeutig pruefbare Uebergabe: jede erfolgreiche Aufnahme liegt
            # zusaetzlich als atomar getauschte PNG-Datei pro Sitzung vor;
            # der Kurzhash stammt aus denselben Bytes, die die UI bekommt.
            try {
                $previewDir = Join-Path $script:AppDataRoot 'preview-cache'
                [void][System.IO.Directory]::CreateDirectory($previewDir)
                $safeSid = ($sessionId -replace '[^A-Za-z0-9_-]', '_')
                $pngPath = Join-Path $previewDir ($safeSid + '.png')
                $tmpPath = $pngPath + '.tmp'
                [System.IO.File]::WriteAllBytes($tmpPath, $bytes)
                if (Test-Path -LiteralPath $pngPath) { try { [System.IO.File]::Delete($pngPath) } catch {} }
                [System.IO.File]::Move($tmpPath, $pngPath)
                $shaShort = '-'
                try {
                    $shaShort = ([System.BitConverter]::ToString([System.Security.Cryptography.SHA256]::Create().ComputeHash($bytes))).Replace('-', '').Substring(0, 12)
                } catch {}
                Write-PreviewTrace $flow 'PNG_STORED' $null ('file="' + $pngPath + '" sha256=' + $shaShort)
            } catch {
                Write-PreviewTrace $flow 'PNG_STORE_FAILED' @{ error = [string]$_.Exception.Message }
            }
            $row = $script:UiRows[$sessionId]
            $row.PreviewFailCount = 0
            try {
                $script:PreviewLastOutcome = 'ok: ' + [string]$resultW + 'x' + [string]$resultH + ' px, ' + $(if ($resultMethod) { [string]$resultMethod } else { 'Methode unbekannt' })
                $script:PreviewLastOutcomeAt = Get-Date
            } catch {}
            if (-not $row.PreviewLoggedOnce) {
                # Einmalig festhalten, dass (und ab wann) die Vorschau dieser
                # Sitzung wirklich Bilder liefert - inkl. Aufnahme-Groesse.
                $row.PreviewLoggedOnce = $true
                $sizeInfo = ''
                try {
                    $sizeInfo = " ($resultW" + 'x' + "$resultH px"
                    if ($resultMethod) { $sizeInfo += ", $resultMethod" }
                    $sizeInfo += ')'
                } catch {}
                try { Write-RuntimeLog "Place-Vorschau ($sessionId): Live-Vorschau aktiv$sizeInfo." } catch {}
            }
            Set-PlacePreviewImage $row $bytes $flow
        } elseif (-not $bytes) {
            # Gescheiterte Aufnahme zaehlen, begruenden und nach 3
            # Fehlversuchen in Folge das Platzhalter-Symbol zeigen (statt des
            # endlos drehenden Kreises). Die Aufnahmen laufen gedrosselt
            # weiter: Sobald eine klappt, erscheint die Live-Vorschau.
            $reason = 'unbekannter Fehler'
            if ($minimized) { $reason = 'Studio-Fenster ist minimiert' }
            elseif ($traceError) { $reason = [string]$traceError }
            if ($script:UiRows.ContainsKey($sessionId)) {
                $row = $script:UiRows[$sessionId]
                $row.PreviewFailCount = [int]$row.PreviewFailCount + 1
                if ([int]$row.PreviewFailCount -ge 3 -and -not $row.PreviewHasFrame) {
                    try { Set-PlacePreviewSpinnerAnimation $row.IconVisual $false } catch {}
                    try { $row.IconSpinner.Visibility = 'Collapsed'; $row.IconFallback.Visibility = 'Visible' } catch {}
                }
            }
            $failCountNow = '-'
            try { if ($script:UiRows.ContainsKey($sessionId)) { $failCountNow = [string]$script:UiRows[$sessionId].PreviewFailCount } } catch {}
            Write-PreviewTrace $flow 'CAPTURE_FAILED' @{ error = $reason } ('failCount=' + $failCountNow)
            try {
                $script:PreviewLastOutcome = 'fehlgeschlagen: ' + [string]$reason
                $script:PreviewLastOutcomeAt = Get-Date
                Add-PreviewDiagLine ('Aufnahme fehlgeschlagen: ' + [string]$reason + ' (sid=' + $sessionId + ', Versuch ' + [string]$failCountNow + ')')
            } catch {}
            $now = Get-Date
            $lastLog = [DateTime]::MinValue
            if ($script:PlacePreviewFailLogAt.ContainsKey($sessionId)) { $lastLog = [DateTime]$script:PlacePreviewFailLogAt[$sessionId] }
            if (($now - $lastLog).TotalSeconds -ge 15) {
                $script:PlacePreviewFailLogAt[$sessionId] = $now
                try { Write-RuntimeLog "Place-Vorschau ($sessionId): Aufnahme fehlgeschlagen - $reason." } catch {}
            }
            Clear-PreviewFlow $flow
        } else {
            # Bilddaten ok, aber die Zeile ist inzwischen weg (Sitzung beendet,
            # waehrend die Aufnahme lief) - auch das war frueher ein stiller Weg.
            Write-PreviewTrace $flow 'IMAGE_ASSIGN_SKIPPED' @{ bytes = $byteLen } 'grund=Zeile nicht mehr in UiRows'
            Clear-PreviewFlow $flow
        }
    }
    # Version 6.0.5: kleiner Kurzbericht zum Weitergeben (gedrosselt, 10 s).
    Write-PreviewDiagnoseFile
}

function Set-EditorIconsEnabled {
    param([bool]$Enabled)
    $script:SettingsCache.editorIconsEnabled = $Enabled
    foreach ($row in @($script:UiRows.Values)) {
        try {
            $rowIsPreview = ([string]$row.sessionId -ne '__arena_all_places__')
            if ($row.IconFrame) { $row.IconFrame.Visibility = $(if ($Enabled -and $rowIsPreview) { 'Visible' } else { 'Collapsed' }) }
            if ($Enabled -and $rowIsPreview -and -not $row.PreviewHasFrame -and [int]$row.PreviewFailCount -lt 3) {
                try { Set-PlacePreviewSpinnerAnimation $row.IconVisual $true } catch {}
                if ($row.IconSpinner) { $row.IconSpinner.Visibility = 'Visible' }
                if ($row.IconFallback) { $row.IconFallback.Visibility = 'Collapsed' }
            } else {
                try { Set-PlacePreviewSpinnerAnimation $row.IconVisual $false } catch {}
                if ($row.PreviewHasFrame -and $row.IconImage) { $row.IconImage.Visibility = 'Visible' }
                if ($row.IconSpinner) { $row.IconSpinner.Visibility = 'Collapsed' }
                if ($row.IconFallback) { $row.IconFallback.Visibility = $(if ($Enabled -and $rowIsPreview -and -not $row.PreviewHasFrame) { 'Visible' } else { 'Collapsed' }) }
            }
        } catch {}
    }
    if (-not $Enabled) {
        # Stop expensive window captures immediately. C# tasks cannot safely
        # be aborted, so they are detached; PowerShell fallback workers are
        # stopped and disposed. No new capture starts while the switch is off.
        foreach ($sessionId in @($script:PlacePreviewJobs.Keys)) {
            try {
                $job=$script:PlacePreviewJobs[$sessionId]
                if ($job.Worker) { try { $job.Worker.Stop() } catch {}; try { $job.Worker.Dispose() } catch {} }
                [void]$script:PlacePreviewJobs.Remove($sessionId)
            } catch {}
        }
    }
    Write-RuntimeLog ('Editor-Vorschau-Icons ' + $(if ($Enabled) { 'aktiviert.' } else { 'deaktiviert - Fensteraufnahmen gestoppt.' }))
}

function Get-ArenaHistoryEntries {
    param([string]$SessionId)
    $entries = New-Object System.Collections.Generic.List[object]
    $wanted = @()
    if ([string]::IsNullOrWhiteSpace($SessionId)) { $wanted = @($script:Shared.ActivityLogs.Keys) } else { $wanted = @($SessionId) }
    foreach ($sid in $wanted) {
        $bag = $null
        if (-not $script:Shared.ActivityLogs.TryGetValue([string]$sid, [ref]$bag)) { continue }
        $place = 'Unbekannter Place'
        try { $raw=$null; if ($script:Shared.Sessions.TryGetValue([string]$sid,[ref]$raw)) { $place=[string](($raw|ConvertFrom-Json).placeName) } } catch {}
        foreach ($pair in $bag.GetEnumerator()) {
            try {
                $entry = $pair.Value | ConvertFrom-Json
                $entry | Add-Member -NotePropertyName 'placeName' -NotePropertyValue $place -Force
                $entries.Add($entry)
            } catch {}
        }
    }
    # Kein unitaeres Komma: sonst erhaelt das UI genau EIN verschachteltes Array
    # statt der Eintraege und der Arena-Verlauf wirkt dauerhaft leer.
    return @($entries | Sort-Object @{Expression={ [int64]$_.startedAt }}, @{Expression={ [int64]$_.updatedAt }})
}

function Clear-ArenaHistory {
    param([string]$SessionId)
    $wanted = if ([string]::IsNullOrWhiteSpace($SessionId)) { @($script:Shared.ActivityLogs.Keys) } else { @($SessionId) }
    foreach ($sid in $wanted) {
        $bag=$null
        if ($script:Shared.ActivityLogs.TryGetValue([string]$sid,[ref]$bag)) { try { $bag.Clear() } catch {} }
    }
}

# Version 6.0: Aurora-Lichter fuer programmatisch gebaute Fenster (der
# Verlaufs-Bildschirm kommt ohne XAML-Ressourcen aus). Jedes Licht ist eine
# Ellipse mit radialem Farbverlauf, die langsam hin- und herdriftet. Die
# Funktion ist bewusst defensiv gebaut: Schlaegt irgendetwas, liefert sie
# ein leeres Grid zurueck - das Fenster bleibt voll bedienbar.
function New-AuroraLayer {
    param([double]$Width, [double]$Height)
    $layer = [System.Windows.Controls.Grid]::new()
    $layer.IsHitTestVisible = $false
    try {
        $specs = @(
            @{ Size = [Math]::Min(520, $Width * 0.8); X = -170.0; Y = -190.0; Color = '#547B5CFF'; DX = 44.0; DY = 28.0; TX = 34; TY = 26 },
            @{ Size = [Math]::Min(420, $Width * 0.65); X = ($Width * 0.62); Y = ($Height * 0.5); Color = '#4D2E4FFF'; DX = -38.0; DY = -24.0; TX = 40; TY = 31 },
            @{ Size = [Math]::Min(330, $Width * 0.5); X = ($Width * 0.55); Y = -120.0; Color = '#4000CFC0'; DX = -30.0; DY = 22.0; TX = 28; TY = 36 }
        )
        foreach ($spec in $specs) {
            $blob = [System.Windows.Shapes.Ellipse]::new()
            $blob.Width = [double]$spec.Size
            $blob.Height = [double]$spec.Size
            $blob.HorizontalAlignment = 'Left'
            $blob.VerticalAlignment = 'Top'
            $blob.Margin = [System.Windows.Thickness]::new([double]$spec.X, [double]$spec.Y, 0, 0)
            $radial = [System.Windows.Media.RadialGradientBrush]::new()
            $radial.GradientOrigin = [System.Windows.Point]::new(0.5, 0.5)
            $null = $radial.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString([string]$spec.Color), 0.0))
            $transparent = [string]$spec.Color
            # '#AARRGGBB' -> Alpha auf 00 setzen (randlos auslaufen)
            $transparent = '#00' + $transparent.Substring(3)
            $null = $radial.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString($transparent), 1.0))
            try { $radial.Freeze() } catch {}
            $blob.Fill = $radial
            $drift = [System.Windows.Media.TranslateTransform]::new(0, 0)
            $blob.RenderTransform = $drift
            $animX = [System.Windows.Media.Animation.DoubleAnimation]::new(0, [double]$spec.DX, [System.TimeSpan]::FromSeconds([int]$spec.TX))
            $animX.AutoReverse = $true
            $animX.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $drift.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $animX)
            $animY = [System.Windows.Media.Animation.DoubleAnimation]::new(0, [double]$spec.DY, [System.TimeSpan]::FromSeconds([int]$spec.TY))
            $animY.AutoReverse = $true
            $animY.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $drift.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $animY)
            $null = $layer.Children.Add($blob)
        }
    } catch {}
    return $layer
}

function Add-ArenaHistoryCard {
    param($HostPanel, $Entry, [bool]$AllPlaces)
    $kind = [string]$Entry.kind
    # Version 6.0: Kräftigere Akzentfarben für die Glas-Karten.
    $colour = '#9AA9CE'
    switch ($kind) {
        'running' { $colour='#38BDF8'; break }
        'write'   { $colour='#34D167'; break }
        'console' { $colour='#FFB020'; break }
        'failed'  { $colour='#FF5C77'; break }
    }
    # Version 5.2: deutlich flachere Karten, damit eine Aktion weniger Hoehe braucht.
    # Version 6.0: halbtransparente Glas-Karten, die neu hinzukommenden Karten
    # blenden weich ein.
    $card = [System.Windows.Controls.Border]::new()
    $card.Background = Get-Brush '#4D101A3C'; $card.BorderBrush = Get-Brush '#2EFFFFFF'; $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.CornerRadius=[System.Windows.CornerRadius]::new(10); $card.Padding=[System.Windows.Thickness]::new(9,5,9,5); $card.Margin=[System.Windows.Thickness]::new(0,0,0,6)
    $grid=[System.Windows.Controls.Grid]::new()
    $c0=[System.Windows.Controls.ColumnDefinition]::new();$c0.Width=[System.Windows.GridLength]::new(4)
    $c1=[System.Windows.Controls.ColumnDefinition]::new();$grid.ColumnDefinitions.Add($c0);$grid.ColumnDefinitions.Add($c1)
    $line=[System.Windows.Controls.Border]::new();$line.Background=Get-Brush $colour;$line.CornerRadius=[System.Windows.CornerRadius]::new(2)
    [System.Windows.Controls.Grid]::SetColumn($line,0);$grid.Children.Add($line)|Out-Null
    $stack=[System.Windows.Controls.StackPanel]::new();$stack.Margin=[System.Windows.Thickness]::new(9,0,0,0)
    $main=[System.Windows.Controls.TextBlock]::new();$main.Foreground=Get-Brush '#EAF0FF';$main.FontSize=11.5;$main.TextWrapping='Wrap'
    $prefix=if($AllPlaces){ ([string]$Entry.placeName + ' · ') }else{''};$main.Text=$prefix + [string]$Entry.text
    $meta=[System.Windows.Controls.TextBlock]::new();$meta.Foreground=Get-Brush '#8FA3CC';$meta.FontSize=10;$meta.Margin=[System.Windows.Thickness]::new(0,2,0,0)
    $when='';try{$when=[DateTimeOffset]::FromUnixTimeSeconds([int64]$Entry.updatedAt).LocalDateTime.ToString('HH:mm:ss')}catch{}
    $state='Abgeschlossen'
    if ([int64]$Entry.updatedAt -eq 0) {
        # Version 5.2: die "Wartet ..."-Karte (Platzhalter, solange noch nichts
        # passiert ist) traegt den eigenen Status "Wartet".
        $state='Wartet'
    } else {
        switch ($kind) {
            'running' { $state='Macht gerade'; break }
            'read'    { $state='Abgerufen'; break }
            'write'   { $state='Geändert'; break }
            'console' { $state='Konsole'; break }
            'failed'  { $state='Warnung'; break }
        }
    }
    $timeSuffix = if ($when) { ' · ' + $when } else { '' }
    $meta.Text=$state + $timeSuffix
    $stack.Children.Add($main)|Out-Null;$stack.Children.Add($meta)|Out-Null
    [System.Windows.Controls.Grid]::SetColumn($stack,1);$grid.Children.Add($stack)|Out-Null;$card.Child=$grid;$HostPanel.Children.Add($card)|Out-Null
    try {
        $card.Opacity = 0
        $cardFade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(200))
        $card.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $cardFade)
    } catch {
        try { $card.Opacity = 1 } catch {}
    }
}

function Update-ArenaHistoryWindow {
    param($State)
    if ($null -eq $State -or $null -eq $State.Host) { return }
    # Version 5.2: Waehrend das Fenster mit der Maus verschoben wird (linke
    # Taste gedrueckt), wird der Verlauf nicht neu aufgebaut - sonst wuerden
    # die Karten genau waehrend des Ziehens aus dem Baum verschwinden.
    try {
        if ([System.Windows.Input.Mouse]::LeftButton -eq [System.Windows.Input.MouseButtonState]::Pressed -and $State.Window.IsActive) { return }
    } catch {}
    # Version 5.2: bei unveraendertem Inhalt gar nichts umbauen (kein Flackern).
    $entries = @(Get-ArenaHistoryEntries ([string]$State.SessionId))
    $contentSig = [string]$entries.Count
    foreach ($sigEntry in $entries) { try { $contentSig += '.' + [string]$sigEntry.updatedAt + [string]$sigEntry.kind } catch {} }
    if (-not $State.FirstRender -and $null -ne $State.Signature -and $State.Signature -eq $contentSig) { return }
    $State.Signature = $contentSig
    $scroll=$State.Scroll
    $atBottom=([double]$scroll.VerticalOffset -ge ([double]$scroll.ScrollableHeight - 18)) -or $State.FirstRender
    $oldOffset=[double]$scroll.VerticalOffset
    $State.Host.Children.Clear()
    $waitingText = if ([string]::IsNullOrWhiteSpace([string]$State.SessionId)) {
        'Wartet darauf, dass Arena die Bridge mit einem der verbundenen Places benutzt.'
    } else {
        'Wartet darauf, dass Arena die Bridge mit diesem Place benutzt.'
    }
    $waiting=[pscustomobject]@{kind='read';text=$waitingText;updatedAt=0;placeName=''}
    Add-ArenaHistoryCard $State.Host $waiting ([bool]$State.AllPlaces)
    foreach ($entry in $entries) { Add-ArenaHistoryCard $State.Host $entry ([bool]$State.AllPlaces) }
    if ($atBottom) { $scroll.ScrollToEnd() } else { $scroll.ScrollToVerticalOffset($oldOffset) }
    $State.FirstRender=$false
}

# Version 5.2: Button im normalen Titelleisten-Design (programmatisch gebaut,
# weil das Verlaufsfenster ohne XAML-Ressourcen auskommt).
# Version 6.0: Glas-Knopf - halbtransparenter heller Grund, weisser Rand,
# Hover-Farben kommen als Parameter (Crimson fuer Schliessen/Loeschen).
function New-HistoryButton {
    param(
        [string]$Glyph,
        [double]$GlyphSize,
        [string]$ToolTip,
        [string]$HoverBg,
        [string]$HoverBorder,
        [string]$PressBg
    )
    $button = [System.Windows.Controls.Button]::new()
    $button.Content = $Glyph
    $button.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe MDL2 Assets')
    $button.FontSize = $GlyphSize
    $button.Width = 38; $button.Height = 34
    $button.Cursor = [System.Windows.Input.Cursors]::Hand
    $button.ToolTip = $ToolTip
    $button.Foreground = Get-Brush '#E8EFFC'
    $button.Background = Get-Brush '#33FFFFFF'
    $button.BorderBrush = Get-Brush '#40FFFFFF'
    $button.BorderThickness = [System.Windows.Thickness]::new(1)
    $template = [System.Windows.Controls.ControlTemplate]::new([System.Windows.Controls.Button])
    $bd = [System.Windows.FrameworkElementFactory]::new([System.Windows.Controls.Border])
    $bd.Name = 'bd'
    [void]$bd.SetValue([System.Windows.Controls.Border]::CornerRadiusProperty, [System.Windows.CornerRadius]::new(12))
    $bgBind = [System.Windows.Data.Binding]::new('Background')
    $bgBind.RelativeSource = [System.Windows.Data.RelativeSource]::TemplatedParent
    $bd.SetBinding([System.Windows.Controls.Border]::BackgroundProperty, $bgBind)
    $bbBind = [System.Windows.Data.Binding]::new('BorderBrush')
    $bbBind.RelativeSource = [System.Windows.Data.RelativeSource]::TemplatedParent
    $bd.SetBinding([System.Windows.Controls.Border]::BorderBrushProperty, $bbBind)
    $btBind = [System.Windows.Data.Binding]::new('BorderThickness')
    $btBind.RelativeSource = [System.Windows.Data.RelativeSource]::TemplatedParent
    $bd.SetBinding([System.Windows.Controls.Border]::BorderThicknessProperty, $btBind)
    $cp = [System.Windows.FrameworkElementFactory]::new([System.Windows.Controls.ContentPresenter])
    [void]$cp.SetValue([System.Windows.FrameworkElement]::HorizontalAlignmentProperty, [System.Windows.HorizontalAlignment]::Center)
    [void]$cp.SetValue([System.Windows.FrameworkElement]::VerticalAlignmentProperty, [System.Windows.VerticalAlignment]::Center)
    [void]$bd.AppendChild($cp)
    $template.VisualTree = $bd
    $hover = [System.Windows.Trigger]::new()
    $hover.Property = [System.Windows.UIElement]::IsMouseOverProperty
    $hover.Value = $true
    [void]$hover.Setters.Add([System.Windows.Setter]::new([System.Windows.Controls.Border]::BackgroundProperty, (Get-Brush $HoverBg), 'bd'))
    [void]$hover.Setters.Add([System.Windows.Setter]::new([System.Windows.Controls.Border]::BorderBrushProperty, (Get-Brush $HoverBorder), 'bd'))
    [void]$hover.Setters.Add([System.Windows.Setter]::new([System.Windows.Controls.Control]::ForegroundProperty, [System.Windows.Media.Brushes]::White))
    [void]$template.Triggers.Add($hover)
    $pressed = [System.Windows.Trigger]::new()
    $pressed.Property = [System.Windows.Controls.Primitives.ButtonBase]::IsPressedProperty
    $pressed.Value = $true
    [void]$pressed.Setters.Add([System.Windows.Setter]::new([System.Windows.Controls.Border]::BackgroundProperty, (Get-Brush $PressBg), 'bd'))
    [void]$template.Triggers.Add($pressed)
    $button.Template = $template
    return $button
}
function Open-ArenaHistoryWindow {
    param([string]$SessionId, [string]$Title = 'Arena-Verlauf')
    $history=[System.Windows.Window]::new();$history.Title=$Title;$history.Width=660;$history.Height=620;$history.MinWidth=660;$history.MinHeight=620;$history.MaxWidth=660;$history.MaxHeight=620
    $history.WindowStartupLocation='CenterOwner';$history.WindowStyle='None';$history.AllowsTransparency=$true;$history.Background=[System.Windows.Media.Brushes]::Transparent;$history.FontFamily=[System.Windows.Media.FontFamily]::new('Segoe UI')
    try{$history.Owner=$window}catch{}
    # Version 6.0 (Liquid Glass): dunkle Glas-Schale auf navy-violettem
    # Verlauf, Aurora-Lichter dahinter, echter Rundungs-Beschchnitt.
    $shell=[System.Windows.Controls.Border]::new();$shell.CornerRadius=[System.Windows.CornerRadius]::new(18)
    $shellBg=[System.Windows.Media.LinearGradientBrush]::new()
    $shellBg.StartPoint=[System.Windows.Point]::new(0,0);$shellBg.EndPoint=[System.Windows.Point]::new(0.35,1)
    $null=$shellBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#F50B1030'),0.0))
    $null=$shellBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#F3080922'),1.0))
    try { $shellBg.Freeze() } catch {}
    $shell.Background=$shellBg
    $shell.BorderBrush=Get-Brush '#33FFFFFF';$shell.BorderThickness=[System.Windows.Thickness]::new(1);$shell.Padding=[System.Windows.Thickness]::new(20)
    try { $shell.Clip = [System.Windows.Media.RectangleGeometry]::new([System.Windows.Rect]::new(0,0,660,620), 18, 18) } catch {}
    try { $shell.Effect = New-Shadow -Blur 28 -Opacity 0.45 } catch {}
    $grid=[System.Windows.Controls.Grid]::new();$r0=[System.Windows.Controls.RowDefinition]::new();$r0.Height=[System.Windows.GridLength]::Auto;$r1=[System.Windows.Controls.RowDefinition]::new();$grid.RowDefinitions.Add($r0);$grid.RowDefinitions.Add($r1)
    try {
        $aurora = New-AuroraLayer -Width 660 -Height 620
        [System.Windows.Controls.Grid]::SetRow($aurora,0)
        [System.Windows.Controls.Grid]::SetRowSpan($aurora,2)
        $grid.Children.Add($aurora)|Out-Null
    } catch {}
    $head=[System.Windows.Controls.Grid]::new();$hc0=[System.Windows.Controls.ColumnDefinition]::new();$hc1=[System.Windows.Controls.ColumnDefinition]::new();$hc1.Width=[System.Windows.GridLength]::Auto;$hc2=[System.Windows.Controls.ColumnDefinition]::new();$hc2.Width=[System.Windows.GridLength]::Auto;$head.ColumnDefinitions.Add($hc0);$head.ColumnDefinitions.Add($hc1);$head.ColumnDefinitions.Add($hc2)
    $texts=[System.Windows.Controls.StackPanel]::new();$titleText=[System.Windows.Controls.TextBlock]::new();$titleText.Text=$Title;$titleText.Foreground=Get-Brush '#F4F8FF';$titleText.FontSize=18;$titleText.FontWeight='Bold';$sub=[System.Windows.Controls.TextBlock]::new();$sub.Text='Alle Aktionen von Arena in zeitlicher Reihenfolge - Fenster ist frei verschiebbar';$sub.Foreground=Get-Brush '#9AA9CE';$sub.FontSize=11.5;$sub.Margin=[System.Windows.Thickness]::new(0,4,0,0);$texts.Children.Add($titleText)|Out-Null;$texts.Children.Add($sub)|Out-Null;$head.Children.Add($texts)|Out-Null
    # Version 5.2: Die Knoepfe tragen das normale Titelleisten-Design des
    # Programms (dunkel, abgerundet, Hover-Farbe; Schliessen-Knopf wird rot) -
    # bis 5.0.2 waren es ungestylte Windows-Standardknoepfe.
    # Version 6.0: Glas-Knoepfe, Hover in Crimson.
    $trash=New-HistoryButton -Glyph ([char]0xE74D) -GlyphSize 14 -ToolTip 'Verlauf zurücksetzen' -HoverBg '#59E11D48' -HoverBorder '#80FF5C77' -PressBg '#40B01226'
    $trash.Margin=[System.Windows.Thickness]::new(0,0,8,0);[System.Windows.Controls.Grid]::SetColumn($trash,1);$head.Children.Add($trash)|Out-Null
    $close=New-HistoryButton -Glyph ([char]0xE8BB) -GlyphSize 12 -ToolTip 'Schließen' -HoverBg '#66FF4D6D' -HoverBorder '#99FF4D6D' -PressBg '#40D91A47'
    [System.Windows.Controls.Grid]::SetColumn($close,2);$head.Children.Add($close)|Out-Null
    [System.Windows.Controls.Grid]::SetRow($head,0);$grid.Children.Add($head)|Out-Null
    $scroll=[System.Windows.Controls.ScrollViewer]::new();$scroll.Margin=[System.Windows.Thickness]::new(0,14,0,0);$scroll.VerticalScrollBarVisibility='Auto';$scroll.HorizontalScrollBarVisibility='Disabled';$historyHost=[System.Windows.Controls.StackPanel]::new();$scroll.Content=$historyHost;[System.Windows.Controls.Grid]::SetRow($scroll,1);$grid.Children.Add($scroll)|Out-Null
    $shell.Child=$grid;$history.Content=$shell
    $state=[pscustomobject]@{Window=$history;Scroll=$scroll;Host=$historyHost;SessionId=$SessionId;AllPlaces=[string]::IsNullOrWhiteSpace($SessionId);FirstRender=$true;Signature=$null;Timer=$null}
    $history.Tag=$state;$trash.Tag=$state;$close.Tag=$history
    $trash.Add_Click({param($sender,$e) Clear-ArenaHistory ([string]$sender.Tag.SessionId);$sender.Tag.FirstRender=$true;$sender.Tag.Signature=$null;Update-ArenaHistoryWindow $sender.Tag})
    $close.Add_Click({param($sender,$e) $sender.Tag.Close()})
    # Version 5.2: Das Fenster laesst sich FREI ueber den Bildschirm schieben -
    # an der Titelzeile UND am Hintergrund/Verlauf (Knoepfe und Scrollbalken
    # behandeln ihren Klick selbst und loesen dadurch keinen Ziehmodus aus).
    $dragHandler = {
        param($sender, $e)
        if ($e.ChangedButton -eq [System.Windows.Input.MouseButton]::Left) {
            try {
                $dragWindow = [System.Windows.Window]::GetWindow($sender)
                if ($dragWindow) { $dragWindow.DragMove() }
            } catch {}
        }
    }
    $head.Add_MouseLeftButtonDown($dragHandler)
    $shell.Add_MouseLeftButtonDown($dragHandler)
    # Version 6.0: Das Fenster blendet beim Oeffnen weich ein.
    try {
        $history.Opacity = 0
        $history.Add_ContentRendered({
            param($s, $e)
            try {
                $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(220))
                $s.BeginAnimation([System.Windows.Window]::OpacityProperty, $fade)
            } catch { try { $s.Opacity = 1 } catch {} }
        })
    } catch {}
    $timer=[System.Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds(650);$timer.Tag=$state;$timer.Add_Tick({param($sender,$e) Update-ArenaHistoryWindow $sender.Tag});$state.Timer=$timer
    $history.Add_Loaded({param($sender,$e) Update-ArenaHistoryWindow $sender.Tag;$sender.Tag.Timer.Start()})
    $history.Add_Closed({param($sender,$e) try{$sender.Tag.Timer.Stop()}catch{}})
    [void]$history.ShowDialog()
}

function Copy-Prompt {
    param([string]$SessionId)
    if ($SessionId -eq '__arena_all_places__') {
        if ([string]::IsNullOrWhiteSpace($script:TunnelUrl)) { Show-CopyConfirm -Message 'Der Cloudflare-Tunnel ist noch nicht bereit.' -Seconds 5; return }
        try {
            # Version 5.2: Nur URL + TOKEN. MODE/HINWEIS sind weg - der Server
            # beantwortet Arenas erste Anfrage mit diesem Sammel-Token sowieso
            # automatisch mit der aktuellen places-Liste und der Anleitung.
            [System.Windows.Clipboard]::SetText("URL=$script:TunnelUrl`r`nTOKEN=$script:AllPlacesToken")
            Show-CopyConfirm -Message 'Prompt für alle Places wurde in die Zwischenablage kopiert - Arena sieht die Place-Auswahl dann automatisch' -Seconds 4
        } catch { Show-CopyConfirm -Message "Zwischenablage blockiert: $($_.Exception.Message)" -Seconds 6 }
        return
    }
    $token = $null
    if (-not $script:Shared.SessionTokens.TryGetValue($SessionId, [ref]$token)) {
        Show-CopyConfirm -Message 'Token konnte nicht gelesen werden.' -Seconds 5
        return
    }
    if ([string]::IsNullOrWhiteSpace($script:TunnelUrl)) {
        Show-CopyConfirm -Message 'Der Cloudflare-Tunnel ist noch nicht bereit.' -Seconds 5
        return
    }
    try {
        [System.Windows.Clipboard]::SetText("URL=$script:TunnelUrl`r`nTOKEN=$token")
        # Version 3.9: sichtbare Rueckmeldung im Fenster (blendet von allein aus)
        Show-CopyConfirm -Message 'Prompt wurde in die Zwischenablage kopiert' -Seconds 3
    } catch {
        Show-CopyConfirm -Message "Zwischenablage blockiert: $($_.Exception.Message)" -Seconds 6
    }
}

function Set-RowMode {
    param($Row, [string]$Mode, [switch]$Silent)

    $Row.Mode = $Mode
    $readonly = ($Mode -eq 'readonly')
    Set-MenuChecked $Row.Toggle $readonly
    $subtitle = if ($readonly) { 'Aktiv - Änderungen sind gesperrt' } else { 'Inaktiv - Änderungen sind erlaubt' }
    Set-Text $Row.Toggle.Sub $subtitle

    if (-not $Silent) {
        $message = if ($readonly) { 'Nur Lesezugriff ist aktiv.' } else { 'Lese- und Schreibzugriff ist aktiv.' }
        Show-Toast -Message $message -Kind 'Success'
    }
}

function New-Row {
    param($Studio, $WindowNames)

    $sessionId = [string]$Studio.sessionId

    $row = [pscustomobject]@{
        SessionId  = $sessionId
        Root       = $null
        Title      = $null
        Copy       = $null
        Menu       = $null
        Popup      = $null
        Toggle     = $null
        IconFrame  = $null
        IconImage  = $null
        IconSpinner = $null
        IconFallback = $null
        IconVisual = $null
        PreviewHandle   = $null
        PreviewHasFrame = $false
        PreviewVerifyDone = $false
        IconIconAttempted = $false
        PreviewFailCount = 0
        PreviewLoggedOnce = $false
        Mode       = $null
        ModeUntil  = [DateTime]::MinValue
        StaleText  = $null
        ProgressPanel = $null
        ProgressBar   = $null
        ProgressText  = $null
        ProgressPercent = $null
        ProgressState   = 'idle'
        IsMinimalFallback = $false
        # Version 7.0.7 HOTFIX: Diese Eigenschaft MUSS im Initialisierer stehen.
        # Ein "$row.CommandCancelButton = ..." ohne Deklaration wirft in Windows
        # PowerShell ("... cannot be found on this object ...") und riss den
        # kompletten Zeilenaufbau mit - die Place-Liste blieb leer.
        CommandCancelButton = $null
    }

    # Version 6.0 (Liquid Glass): Die Place-Zeile ist eine Teal-Glaskarte.
    # WICHTIG fuer Animationen: Hintergrund-/Randfarben kommen aus dem
    # eingefrorenen Brush-Cache (Get-Brush) - deren Color kann in WPF nicht
    # animiert werden. Deshalb liegt der Hover-Glanz als eigenes Ueberlagerungs-
    # Element ueber der Karte, dessen Opacity weich ein-/ausblendet, und die
    # Karte hebt sich beim Hover um 2 Pixel an (TranslateTransform).
    $border = [System.Windows.Controls.Border]::new()
    $border.CornerRadius = [System.Windows.CornerRadius]::new(16)
    $rowBg = [System.Windows.Media.LinearGradientBrush]::new()
    $rowBg.StartPoint = [System.Windows.Point]::new(0, 0)
    $rowBg.EndPoint = [System.Windows.Point]::new(0.4, 1)
    $null = $rowBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#D900D5C4'), 0.0))
    $null = $rowBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#B800A08D'), 1.0))
    try { $rowBg.Freeze() } catch {}
    $border.Background = $rowBg
    $border.BorderBrush = Get-Brush '#47FFFFFF'
    $border.BorderThickness = [System.Windows.Thickness]::new(1)
    # Version 7.0.5: symmetrisch und kompakt - 7.0.4 hatte 8 px oben/unten
    # plus die (falsch platzierte) Arbeitszeile, wodurch die Zeile hoch wirkte.
    $border.Padding = [System.Windows.Thickness]::new(16, 6, 16, 6)
    $border.Margin = [System.Windows.Thickness]::new(0, 0, 0, 12)
    $border.MinHeight = 64
    $border.Tag = $sessionId
    $border.Effect = New-Shadow -Blur 18 -Opacity 0.20 -Color '#0080D6C4'
    $border.RenderTransform = [System.Windows.Media.TranslateTransform]::new(0, 0)

    # Ebenen-Grid: [0] = Hover-Glanz, [1] = Glas-Schein oben, [2] = Inhalt
    $layer = [System.Windows.Controls.Grid]::new()
    $hoverGlow = [System.Windows.Controls.Border]::new()
    $hoverGlow.CornerRadius = [System.Windows.CornerRadius]::new(15)
    $hoverGlow.Background = Get-Brush '#5900E5D0'
    $hoverGlow.Opacity = 0
    $hoverGlow.IsHitTestVisible = $false
    $null = $layer.Children.Add($hoverGlow)
    $sheen = [System.Windows.Controls.Border]::new()
    $sheen.Height = 18
    $sheen.CornerRadius = [System.Windows.CornerRadius]::new(15, 15, 0, 0)
    $sheen.Margin = [System.Windows.Thickness]::new(1, 1, 1, 0)
    $sheen.VerticalAlignment = 'Top'
    $sheen.IsHitTestVisible = $false
    $sheenBrush = [System.Windows.Media.LinearGradientBrush]::new()
    $sheenBrush.StartPoint = [System.Windows.Point]::new(0, 0)
    $sheenBrush.EndPoint = [System.Windows.Point]::new(0, 1)
    $null = $sheenBrush.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#38FFFFFF'), 0.0))
    $null = $sheenBrush.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#00FFFFFF'), 1.0))
    try { $sheenBrush.Freeze() } catch {}
    $sheen.Background = $sheenBrush
    $null = $layer.Children.Add($sheen)

    $border.Add_MouseEnter({
        param($s, $e)
        try {
            $glow = $s.Child.Children[0]
            $show = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 0.55, [System.TimeSpan]::FromMilliseconds(150))
            $glow.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $show)
        } catch {}
        try {
            $lift = [System.Windows.Media.Animation.DoubleAnimation]::new(-2, [System.TimeSpan]::FromMilliseconds(140))
            $s.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $lift)
        } catch {}
    })
    $border.Add_MouseLeave({
        param($s, $e)
        try {
            $glow = $s.Child.Children[0]
            $hide = [System.Windows.Media.Animation.DoubleAnimation]::new(0, [System.TimeSpan]::FromMilliseconds(200))
            $glow.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $hide)
        } catch {}
        try {
            $drop = [System.Windows.Media.Animation.DoubleAnimation]::new(0, [System.TimeSpan]::FromMilliseconds(140))
            $s.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $drop)
        } catch {}
    })

    $grid = [System.Windows.Controls.Grid]::new()
    $nameCol = [System.Windows.Controls.ColumnDefinition]::new()
    $copyCol = [System.Windows.Controls.ColumnDefinition]::new(); $copyCol.Width = [System.Windows.GridLength]::Auto
    $menuCol = [System.Windows.Controls.ColumnDefinition]::new(); $menuCol.Width = [System.Windows.GridLength]::Auto
    $grid.ColumnDefinitions.Add($nameCol)
    $grid.ColumnDefinitions.Add($copyCol)
    $grid.ColumnDefinitions.Add($menuCol)

    $namePanel = [System.Windows.Controls.Grid]::new()
    # Version 7.1.4: Name + optionale Statuszeile sitzen zwischen zwei gleich
    # grossen Sternzeilen. Sind Plugin-Warnung und Fortschritt eingeklappt,
    # bleibt der einzelne Place-Name mathematisch in der Kartenmitte.
    $namePanel.VerticalAlignment = 'Stretch'
    $iconCol2 = [System.Windows.Controls.ColumnDefinition]::new(); $iconCol2.Width = [System.Windows.GridLength]::Auto
    $titleCol = [System.Windows.Controls.ColumnDefinition]::new()
    $namePanel.ColumnDefinitions.Add($iconCol2)
    $namePanel.ColumnDefinitions.Add($titleCol)
    # Version 5.0.2 Sicherheitsnetz: Icon, Auswahlmenue und Verlauf sind
    # bewusst in eigene try/catch-Bloecke gekapselt. Schlaegt eines davon
    # fehl, landet trotzdem immer eine minimal funktionsfaehige Zeile (Name
    # + "Prompt kopieren"-Knopf) im Fenster, statt die komplette Zeile zu
    # verlieren - genau das hatte die Liste in 5.0.0/5.0.1 leer gemacht.
    # Version 6.0.1: an dieser Stelle steht jetzt die Live-Fenster-Vorschau
    # statt des heruntergeladenen Spiel-Icons (siehe Manifest/Changelog).
    $placeIcon = $null
    try {
        $placeIcon = New-PlacePreviewVisual
        [System.Windows.Controls.Grid]::SetColumn($placeIcon.Frame, 0)
        # Vorschau mittig über den gesamten vierzeiligen Namensbereich.
        [System.Windows.Controls.Grid]::SetRowSpan($placeIcon.Frame, 4)
        $placeIcon.Frame.VerticalAlignment = 'Center'
    } catch {
        $placeIcon = $null
        Write-UiErrorLog 'Place-Zeile: Vorschau-Visual konnte nicht erstellt werden' $_
    }
    $title = [System.Windows.Controls.TextBlock]::new()
    $title.Text = Get-PlaceDisplayName $Studio $WindowNames
    $title.Foreground = Get-Brush '#FFFFFF'
    $title.FontSize = 16
    $title.FontWeight = 'SemiBold'
    $title.VerticalAlignment = 'Center'
    $title.Margin = [System.Windows.Thickness]::new(0, 0, 0, 0)
    $title.TextTrimming = 'CharacterEllipsis'
    [System.Windows.Controls.Grid]::SetColumn($title, 1)
    # Version 7.0.0: unter dem Namen liegt eine zweite Zeile - dort steht der
    # Plugin-veraltet-Hinweis in ROT (statt angehaengt im Titel, wie bisher).
    $staleText = [System.Windows.Controls.TextBlock]::new()
    $staleText.Text = ''
    $staleText.Foreground = Get-Brush '#FFFF5C77'
    $staleText.FontSize = 11.5
    $staleText.FontWeight = 'SemiBold'
    $staleText.Visibility = 'Collapsed'
    $staleText.Margin = [System.Windows.Thickness]::new(0, 1, 0, 0)
    $staleText.TextTrimming = 'CharacterEllipsis'
    $titleStack = [System.Windows.Controls.StackPanel]::new()
    $titleStack.VerticalAlignment = 'Center'
    $titleStack.Margin = [System.Windows.Thickness]::new(0, 0, 12, 0)
    $titleStack.Children.Add($title) | Out-Null
    $titleStack.Children.Add($staleText) | Out-Null
    [System.Windows.Controls.Grid]::SetColumn($titleStack, 1)
    if ($placeIcon) { $namePanel.Children.Add($placeIcon.Frame) | Out-Null }
    $namePanel.Children.Add($titleStack) | Out-Null
    [System.Windows.Controls.Grid]::SetColumn($namePanel, 0)
    $grid.Children.Add($namePanel) | Out-Null
    $row.Title = $title
    $row.StaleText = $staleText
    # Version 7.0.0: Fortschritt des Fortschrittsvertrags - BLAU (ausdruecklich
    # gewuenscht, nicht ins Pink-Schema umbiegen) direkt in der Place-Zeile.
    # Die konkrete Nachricht steht als Tooltip an der Leiste, damit die
    # Zeilenhoehe bei jedem Aufruf nicht springt.
    $progressText = [System.Windows.Controls.TextBlock]::new()
    $progressText.Text = ''
    $progressText.Foreground = Get-Brush '#FF6FB6FF'
    $progressText.FontSize = 11.5
    $progressText.FontWeight = 'SemiBold'
    $progressText.VerticalAlignment = 'Center'
    $progressText.Visibility = 'Collapsed'
    $progressBar = [System.Windows.Controls.ProgressBar]::new()
    $progressBar.Minimum = 0
    $progressBar.Maximum = 100
    $progressBar.Value = 0
    $progressBar.Height = 6
    $progressBar.VerticalAlignment = 'Center'
    $progressBar.Width = 150
    $progressBar.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
    $progressBar.Visibility = 'Collapsed'
    $progressBar.Foreground = Get-Brush '#FF4C9BFF'
    $progressBar.Background = Get-Brush '#33000000'
    $progressBar.BorderThickness = [System.Windows.Thickness]::new(0)
    $progressPercent = [System.Windows.Controls.TextBlock]::new()
    $progressPercent.Text = ''
    $progressPercent.Foreground = Get-Brush '#FF9CCBFF'
    $progressPercent.FontSize = 11
    $progressPercent.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
    $progressPercent.VerticalAlignment = 'Center'
    $progressPercent.Visibility = 'Collapsed'
    $progressRow = [System.Windows.Controls.StackPanel]::new()
    $progressRow.Orientation = 'Horizontal'
    $progressRow.VerticalAlignment = 'Center'
    $progressRow.Margin = [System.Windows.Thickness]::new(0, 1, 0, 0)
    $progressRow.Visibility = 'Collapsed'
    $progressRow.Children.Add($progressText) | Out-Null
    $progressRow.Children.Add($progressBar) | Out-Null
    $progressRow.Children.Add($progressPercent) | Out-Null
    # Version 7.0.6/7.0.7: Abbrechen direkt neben dem Befehlszustand. Der Knopf
    # ist OPTIONAL - er wird deshalb in try/catch gebaut. Ein Extra darf NIE
    # den Aufbau der ganzen Zeile kosten (genau das war der Live-Fehler in 7.0.6).
    try {
        $cancelButton = [System.Windows.Controls.Button]::new()
        $cancelButton.Content = 'Abbrechen'
        $cancelButton.FontSize = 10.5
        $cancelButton.Padding = [System.Windows.Thickness]::new(6, 1, 6, 1)
        $cancelButton.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
        $cancelButton.VerticalAlignment = 'Center'
        $cancelButton.Visibility = 'Collapsed'
        $cancelButton.Add_Click({ param($sender, $eventArgs) try { Invoke-PlaceRowCancel ([string]$sender.Tag) } catch {} })
        $progressRow.Children.Add($cancelButton) | Out-Null
        $row.CommandCancelButton = $cancelButton
    } catch {
        Write-UiErrorLog 'Abbrechen-Knopf konnte nicht gebaut werden (Zeile bleibt nutzbar)' $_
    }
    $topCenterSpacer = [System.Windows.Controls.RowDefinition]::new()
    $topCenterSpacer.Height = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    $titleRowDefinition = [System.Windows.Controls.RowDefinition]::new()
    $titleRowDefinition.Height = [System.Windows.GridLength]::Auto
    $progressRowDefinition = [System.Windows.Controls.RowDefinition]::new()
    $progressRowDefinition.Height = [System.Windows.GridLength]::Auto
    $bottomCenterSpacer = [System.Windows.Controls.RowDefinition]::new()
    $bottomCenterSpacer.Height = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    $namePanel.RowDefinitions.Add($topCenterSpacer) | Out-Null
    $namePanel.RowDefinitions.Add($titleRowDefinition) | Out-Null
    $namePanel.RowDefinitions.Add($progressRowDefinition) | Out-Null
    $namePanel.RowDefinitions.Add($bottomCenterSpacer) | Out-Null
    [System.Windows.Controls.Grid]::SetRow($titleStack, 1)
    [System.Windows.Controls.Grid]::SetRow($progressRow, 2)
    # Version 7.0.5: Die Arbeitszeile gehoert UNTER den Place-Namen (Spalte 1),
    # nicht unter die Vorschau (Standardspalte 0). Genau das machte die Place-
    # Zeile hoch und zog die Mitte auseinander.
    [System.Windows.Controls.Grid]::SetColumn($progressRow, 1)
    $namePanel.Children.Add($progressRow) | Out-Null
    $row.ProgressPanel = $progressRow
    $row.ProgressBar = $progressBar
    $row.ProgressText = $progressText
    $row.ProgressPercent = $progressPercent
    if ($placeIcon) {
        $row.IconFrame = $placeIcon.Frame
        $row.IconImage = $placeIcon.Image
        $row.IconSpinner = $placeIcon.Spinner
        $row.IconFallback = $placeIcon.Fallback
        $row.IconVisual = $placeIcon
    }

    # Version 6.0: "Prompt kopieren" ist ein gruener Glas-Knopf wie im
    # Entwurf (Liquid Glass). Farbe/Outline liegen direkt am Knopf, der
    # globale Button-Style im Hauptfenster liefert Schein, Hover-Glanz und
    # Druck-Animation ueber die Template-Bindings.
    $copyContent = [System.Windows.Controls.StackPanel]::new()
    $copyContent.Orientation = 'Horizontal'
    $copyGlyph = [System.Windows.Controls.TextBlock]::new()
    $copyGlyph.Text = [char]0xE8C8
    $copyGlyph.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe MDL2 Assets')
    $copyGlyph.FontSize = 13
    $copyGlyph.Foreground = Get-Brush '#FFFFFF'
    $copyGlyph.VerticalAlignment = 'Center'
    $copyGlyph.Margin = [System.Windows.Thickness]::new(0, 0, 8, 0)
    $copyLabel = [System.Windows.Controls.TextBlock]::new()
    $copyLabel.Text = 'Prompt kopieren'
    $copyLabel.Foreground = Get-Brush '#FFFFFF'
    $copyLabel.VerticalAlignment = 'Center'
    $copyContent.Children.Add($copyGlyph) | Out-Null
    $copyContent.Children.Add($copyLabel) | Out-Null

    $copy = [System.Windows.Controls.Button]::new()
    $copy.Content = $copyContent
    $greenBg = [System.Windows.Media.LinearGradientBrush]::new()
    $greenBg.StartPoint = [System.Windows.Point]::new(0, 0)
    $greenBg.EndPoint = [System.Windows.Point]::new(0, 1)
    $null = $greenBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#F238D16C'), 0.0))
    $null = $greenBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#E61FA34A'), 1.0))
    try { $greenBg.Freeze() } catch {}
    $copy.Background = $greenBg
    $copy.BorderBrush = Get-Brush '#4DFFFFFF'
    $copy.Foreground = Get-Brush '#FFFFFF'
    $copy.MinWidth = 150
    $copy.Height = 40
    $copy.Margin = [System.Windows.Thickness]::new(16, 0, 8, 0)
    $copy.IsEnabled = -not [string]::IsNullOrWhiteSpace($script:TunnelUrl)
    $copy.Tag = $sessionId
    $copy.Add_Click({
        param($s, $e)
        Copy-Prompt ([string]$s.Tag)
    })
    [System.Windows.Controls.Grid]::SetColumn($copy, 1)
    $grid.Children.Add($copy) | Out-Null
    $row.Copy = $copy

    # Version 6.0: Der "..."-Knopf ist ein neutraler Glas-Knopf.
    $menuButton = [System.Windows.Controls.Button]::new()
    $menuGlyph = [System.Windows.Controls.TextBlock]::new()
    $menuGlyph.Text = [char]0xE712
    $menuGlyph.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe MDL2 Assets')
    $menuGlyph.FontSize = 15
    $menuGlyph.Foreground = Get-Brush '#FFFFFF'
    $menuGlyph.HorizontalAlignment = 'Center'
    $menuGlyph.VerticalAlignment = 'Center'
    $menuButton.Content = $menuGlyph
    $menuBg = [System.Windows.Media.LinearGradientBrush]::new()
    $menuBg.StartPoint = [System.Windows.Point]::new(0, 0)
    $menuBg.EndPoint = [System.Windows.Point]::new(0, 1)
    $null = $menuBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#5CFFFFFF'), 0.0))
    $null = $menuBg.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#26FFFFFF'), 1.0))
    try { $menuBg.Freeze() } catch {}
    $menuButton.Background = $menuBg
    $menuButton.BorderBrush = Get-Brush '#3DFFFFFF'
    $menuButton.Foreground = Get-Brush '#FFFFFF'
    $menuButton.Width = 42
    $menuButton.Height = 40
    $menuButton.Padding = [System.Windows.Thickness]::new(0)
    $menuButton.ToolTip = 'Weitere Optionen'
    [System.Windows.Controls.Grid]::SetColumn($menuButton, 2)
    $grid.Children.Add($menuButton) | Out-Null
    $row.Menu = $menuButton

    # Version 5.0.2 Sicherheitsnetz: Das komplette Auswahlmenue (Popup,
    # Menueeintraege, Schatten-Effekt) ist gekapselt. Schlaegt es fehl,
    # bleibt eine funktionierende Zeile ohne Aufklappmenue uebrig - der
    # "..."-Knopf tut dann einfach nichts mehr ($popup bleibt $null,
    # der Klick-Handler prueft das bereits).
    $popup = $null
    try {
        # --- Auswahlmenue (Version 6.0: Violettes Glas-Panel) -------------
        $popup = [System.Windows.Controls.Primitives.Popup]::new()
        $popup.PlacementTarget = $menuButton
        $popup.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
        $popup.AllowsTransparency = $true
        # Version 6.0: Eigenes Einblend-Tempo (Faden + Hochgleiten, siehe
        # Add_Opened unten) statt PopupAnimation - beides zusammen wuerde
        # sich in der Opacity gegenseitig ueberlagern.
        $popup.PopupAnimation = [System.Windows.Controls.Primitives.PopupAnimation]::None
        # Version 3.7: StaysOpen=$true - das Menue schliesst nur noch gezielt:
        # Klick auf "..." schaltet es um, Klick ausserhalb schliesst es (siehe
        # PreviewMouseDown des Fensters). So ist ein echtes Umschalten moeglich.
        $popup.StaysOpen = $true
        $popup.HorizontalOffset = -256
        $popup.VerticalOffset = 8

        $menuShell = [System.Windows.Controls.Border]::new()
        $menuShell.Width = 284
        $menuShell.CornerRadius = [System.Windows.CornerRadius]::new(18)
        $menuBgBrush = [System.Windows.Media.LinearGradientBrush]::new()
        $menuBgBrush.StartPoint = [System.Windows.Point]::new(0, 0)
        $menuBgBrush.EndPoint = [System.Windows.Point]::new(0.3, 1)
        $null = $menuBgBrush.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#F06E50E8'), 0.0))
        $null = $menuBgBrush.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#E05038D8'), 1.0))
        try { $menuBgBrush.Freeze() } catch {}
        $menuShell.Background = $menuBgBrush
        $menuShell.BorderBrush = Get-Brush '#3DFFFFFF'
        $menuShell.BorderThickness = [System.Windows.Thickness]::new(1)
        $menuShell.Padding = [System.Windows.Thickness]::new(8)
        $menuShell.Margin = [System.Windows.Thickness]::new(0, 0, 14, 18)
        $menuShell.Effect = New-Shadow -Blur 30 -Opacity 0.55
        $menuShell.Opacity = 0
        $menuShell.RenderTransform = [System.Windows.Media.TranslateTransform]::new(0, -10)
        $menuShell.IsHitTestVisible = $true
        # Version 6.0: Das Menue blendet beim Oeffnen weich ein und gleitet
        # leicht nach oben (Liquid-Glass-Gefuehl). Reiner Opacity/Transform-
        # Tanz, kein Layout-Eingriff - bei einem Fehler bleibt das Menue
        # einfach ohne Animation voll funktionsfaehig.
        $popup.Add_Opened({
            param($s, $e)
            try {
                $shell = $s.Child
                $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(160))
                $shell.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fade)
                $rise = [System.Windows.Media.Animation.DoubleAnimation]::new(-10, 0, [System.TimeSpan]::FromMilliseconds(200))
                $riseEase = [System.Windows.Media.Animation.CubicEase]::new()
                $riseEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
                $rise.EasingFunction = $riseEase
                $shell.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $rise)
            } catch {
                try { $s.Child.Opacity = 1 } catch {}
            }
        })

        $menuStack = [System.Windows.Controls.StackPanel]::new()
        $menuHeader = [System.Windows.Controls.TextBlock]::new()
        $menuHeader.Text = 'OPTIONEN'
        $menuHeader.Foreground = Get-Brush '#E4DBFF'
        $menuHeader.FontSize = 10.5
        $menuHeader.FontWeight = 'Bold'
        $menuHeader.Margin = [System.Windows.Thickness]::new(9, 7, 9, 5)
        $menuStack.Children.Add($menuHeader) | Out-Null
        $menuStack.Children.Add((New-Separator)) | Out-Null

        # Version 7.2.2: Nutzernachrichten bleiben verfuegbar; der Befehl
        # "Laufenden Befehl abbrechen" wird im Place-Menue nicht angeboten.
        $messageItem = New-MenuRow -Glyph ([char]0xE724) -Title 'Nachricht an Arena senden' -Subtitle 'Korrektur während der Arbeit' -Accent '#FFD9A0'
        $copyItem = New-MenuRow -Glyph ([char]0xE8C8) -Title 'Prompt kopieren' -Subtitle 'URL und Token für Arena' -Accent '#5CFFEF'
        $resetItem = New-MenuRow -Glyph ([char]0xE72C) -Title 'Token zurücksetzen' -Subtitle 'Neuen Zugang für dieses Place' -Accent '#C9B7FF'
        $toggleItem = New-MenuRow -Glyph ([char]0xE72E) -Title 'Nur Lesezugriff' -Subtitle 'Inaktiv - Änderungen sind erlaubt' -Accent '#FFC1CE' -Checkable $true -Checked $false
        $historyItem = New-MenuRow -Glyph ([char]0xE81C) -Title 'Arena-Verlauf anzeigen' -Subtitle 'Aktionen und Änderungen dieses Place' -Accent '#9FDCFF'

        # Alle Daten haengen am Element selbst (Tag). Lokale Variablen einer
        # Funktion sind in Event-Handlern nicht verfuegbar.
        $itemTag = [pscustomobject]@{
            Popup     = $popup
            SessionId = $sessionId
            Row       = $row
            # Version 7.2.0 (D8): Der Place-Name gehoert ins Fenster
            # "Nachricht an Arena senden" - und Daten haengen am Element (Tag),
            # weil lokale Variablen in Event-Handlern nicht zuverlaessig sind.
            PlaceName = [string]$Studio.placeName
        }
        $messageItem.Root.Tag = $itemTag
        $copyItem.Root.Tag = $itemTag
        $resetItem.Root.Tag = $itemTag
        $toggleItem.Root.Tag = $itemTag
        $historyItem.Root.Tag = $itemTag

        $messageItem.Root.Add_MouseLeftButtonUp({
            param($s, $e)
            $info = $s.Tag
            try { $info.Popup.IsOpen = $false } catch {}
            try {
                $placeTitle = ''
                try { $placeTitle = [string]$info.PlaceName } catch {}
                if ([string]::IsNullOrWhiteSpace($placeTitle)) {
                    try { $placeTitle = [string]$script:PlaceNames[[string]$info.SessionId] } catch {}
                }
                Open-UserMessageWindow -SessionId ([string]$info.SessionId) -PlaceName $placeTitle
            } catch {
                Write-UiErrorLog 'Nachricht-Fenster konnte nicht geoeffnet werden' $_
            }
        })
        $copyItem.Root.Add_MouseLeftButtonUp({
            param($s, $e)
            $info = $s.Tag
            $info.Popup.IsOpen = $false
            Copy-Prompt $info.SessionId
        })
        $resetItem.Root.Add_MouseLeftButtonUp({
            param($s, $e)
            $info = $s.Tag
            $info.Popup.IsOpen = $false
            Reset-SessionToken $info.SessionId
        })
        $historyItem.Root.Add_MouseLeftButtonUp({
            param($s, $e)
            $info = $s.Tag
            try { $info.Popup.IsOpen = $false } catch {}
            try {
                if ([string]$info.SessionId -eq '__arena_all_places__') {
                    Open-ArenaHistoryWindow -SessionId '' -Title 'Arena-Verlauf · Alle Places'
                } else {
                    Open-ArenaHistoryWindow -SessionId ([string]$info.SessionId) -Title 'Arena-Verlauf'
                }
            } catch {
                Write-UiErrorLog 'Arena-Verlaufsfenster konnte nicht geoeffnet werden' $_
            }
        })
        $toggleItem.Root.Add_MouseLeftButtonUp({
            param($s, $e)
            $info = $s.Tag
            # Version 3.7: Das Menue bleibt bei "Nur Lesezugriff" OFFEN, damit
            # weitere Optionen direkt danach eingestellt werden koennen.
            $targetRow = $info.Row
            $newMode = if ($targetRow.Mode -eq 'readonly') { 'readwrite' } else { 'readonly' }
            Set-SessionMode $info.SessionId $newMode
            $targetRow.ModeUntil = [DateTime]::UtcNow.AddSeconds(3)
            Set-RowMode $targetRow $newMode
        })

        $menuStack.Children.Add($messageItem.Root) | Out-Null
        $menuStack.Children.Add((New-Separator)) | Out-Null
        $menuStack.Children.Add($copyItem.Root) | Out-Null
        $menuStack.Children.Add($resetItem.Root) | Out-Null
        $menuStack.Children.Add($historyItem.Root) | Out-Null
        $menuStack.Children.Add((New-Separator)) | Out-Null
        $menuStack.Children.Add($toggleItem.Root) | Out-Null

        $menuShell.Child = $menuStack
        $popup.Child = $menuShell
        $grid.Children.Add($popup) | Out-Null
    } catch {
        $popup = $null
        Write-UiErrorLog 'Place-Zeile: Auswahlmenue/Popup konnte nicht erstellt werden' $_
    }

    # Version 3.7: Klick auf "..." schaltet das Menue um (offen -> zu, zu -> offen).
    $menuButton.Tag = [pscustomobject]@{ Popup = $popup }
    $menuButton.Add_Click({
        param($s, $e)
        try {
            $target = $s.Tag.Popup
            if ($null -eq $target) { return }
            $target.IsOpen = -not $target.IsOpen
        } catch {}
    })

    $row.Toggle = $toggleItem
    $row.Popup = $popup
    $row.Root = $border
    $null = $layer.Children.Add($grid)
    $border.Child = $layer

    $startMode = if ([string]$Studio.accessMode -eq 'readonly') { 'readonly' } else { 'readwrite' }
    try { Set-RowMode $row $startMode -Silent } catch { Write-UiErrorLog 'Place-Zeile: Modus-Anzeige fehlgeschlagen' $_ }
    $row.ModeUntil = [DateTime]::MinValue
    # Version 6.0.1: Live-Fenster-Vorschau statt Spiel-Icon-Download (siehe
    # Start-PlacePreviewCapture - die virtuelle "Alle Places"-Zeile wird dort
    # bewusst uebersprungen und in New-AllPlacesRow zusaetzlich ausgeblendet).
    try { Start-PlacePreviewCapture $Studio $row } catch { Write-UiErrorLog 'Place-Zeile: Vorschau-Aufnahme fehlgeschlagen' $_ }

    return $row
}

function New-AllPlacesRow {
    param($Studios, $WindowNames)
    $virtualStudio = [pscustomobject]@{
        sessionId='__arena_all_places__'; placeName='Alle Places'; placeId='all'; gameId='0'; accessMode='readwrite'; versionMismatch=$false
    }
    # Version 5.2: Die Zeile sieht aus wie jede andere - nur "Prompt kopieren"
    # und "...". "Token zuruecksetzen" und "Nur Lesezugriff" (wirkt auf alle
    # verbundenen Places, siehe Set-AllSessionsMode) bleiben im "..."-Menue.
    # Bis 5.0.2 lagen beide zusaetzlich als eigene Knoepfe direkt in der Zeile.
    $row = New-Row $virtualStudio $WindowNames
    $row.Root.Tag = '__arena_all_places__'
    $row.Title.Text = 'Alle Places'
    try { $row.Copy.ToolTip = 'Prompt für alle verbundenen Places kopieren' } catch {}
    # Version 6.0.1: Die Sammelzeile bekommt (erstmal) bewusst KEINE Vorschau -
    # sie steht fuer mehrere Studio-Fenster gleichzeitig, ein einzelnes
    # Fenster-Bild waere hier irrefuehrend. Start-PlacePreviewCapture
    # ueberspringt diese Session-Id ohnehin (siehe New-Row); das Frame wird
    # zusaetzlich komplett ausgeblendet, damit kein Ladekreis ewig dreht.
    try { if ($row.IconFrame) { $row.IconFrame.Visibility = 'Collapsed' } } catch {}
    return $row
}

function Update-AllPlacesRow {
    param($Row, $Studios)
    Set-Text $Row.Title 'Alle Places'
    $Row.Copy.IsEnabled = -not [string]::IsNullOrWhiteSpace($script:TunnelUrl)
    # Checked only when every currently connected Place is temporarily readonly.
    $allReadOnly = ($Studios.Count -gt 0)
    foreach ($studio in $Studios) { if ([string]$studio.accessMode -ne 'readonly') { $allReadOnly = $false; break } }
    if ($Row.Mode -ne $(if($allReadOnly){'readonly'}else{'readwrite'})) { Set-RowMode $Row $(if($allReadOnly){'readonly'}else{'readwrite'}) -Silent }
}

function Update-Row {
    param($Row, $Studio, $WindowNames)

    $placeTitle = Get-PlaceDisplayName $Studio $WindowNames
    Set-Text $Row.Title $placeTitle
    # Version 7.0.0: "Plugin veraltet - Studio neustarten" steht NICHT mehr im
    # Namen, sondern als ROTER Hinweis UNTER dem Namen. Solange das Plugin
    # veraltet ist, sind "Prompt kopieren" und "..." abgedunkelt und nicht
    # anklickbar - ein veralteter Prompt darf nicht kopiert werden.
    $stale = ($Studio.versionMismatch -eq $true)
    if ($null -ne $Row.StaleText) {
        Set-Text $Row.StaleText $(if ($stale) { 'Plugin veraltet - Studio neustarten' } else { '' })
        $Row.StaleText.Visibility = $(if ($stale) { 'Visible' } else { 'Collapsed' })
    }
    $copyEnabled = (-not [string]::IsNullOrWhiteSpace($script:TunnelUrl)) -and (-not $stale)
    $Row.Copy.IsEnabled = $copyEnabled
    if ($null -ne $Row.Menu) {
        $Row.Menu.IsEnabled = -not $stale
        $Row.Menu.Opacity = $(if ($stale) { 0.45 } else { 1.0 })
    }
    try { Update-PlaceProgressVisual $Row $Studio } catch {}
    # Arena handoffs are checked once by Refresh-Ui, not once per Place row.
    # Version 6.0.1: Start-PlacePreviewCapture ist selbst gedrosselt (siehe
    # dort) - ein Aufruf pro Tick ist billig (nur Dictionary-Lookups, solange
    # kein neuer Screenshot faellig ist).
    try { Start-PlacePreviewCapture $Studio $Row } catch { Write-PreviewCaptureError ([string]$Studio.sessionId) $_ }

    $mode = if ([string]$Studio.accessMode -eq 'readonly') { 'readonly' } else { 'readwrite' }
    # Kurz nach einem Klick hat der lokale Wert Vorrang (verhindert Flackern)
    if ([DateTime]::UtcNow -lt $Row.ModeUntil) { return }
    if ($Row.Mode -ne $mode) {
        if ($null -ne $Row.Toggle) { Set-RowMode $Row $mode -Silent } else { $Row.Mode = $mode }
    }
}


# ----------------------------------------------------------------------------
# AKTUALISIERUNG DER OBERFLAECHE
# ----------------------------------------------------------------------------
function Set-LiveBadge {
    param([string]$Text, [string]$Hex, [string]$Bg, [string]$Border)
    Set-Text $LiveText $Text
    Set-Dot $LiveDot $Hex
    if ([string]$LiveBadge.Tag -ne $Bg) {
        $LiveBadge.Tag = $Bg
        $LiveBadge.Background = Get-Brush $Bg
        $LiveBadge.BorderBrush = Get-Brush $Border
    }
}

# ----------------------------------------------------------------------------
# KOPIER-BESTAETIGUNG (Version 3.9)
# Der Nutzer soll sehen, dass der Prompt wirklich in der Zwischenablage liegt.
# Bewusst KEINE Windows-Sprechblase und KEIN Popup unten rechts, sondern ein
# dezenter Hinweis IM Fenster, der nach wenigen Sekunden von allein ausblendet.
# ----------------------------------------------------------------------------
$script:CopyConfirmTimer = $null

function Show-CopyConfirm {
    param(
        [string]$Message = 'Prompt wurde in die Zwischenablage kopiert',
        [double]$Seconds = 3.0
    )
    if ($null -eq $CopyConfirm) { return }
    try {
        if ($null -ne $CopyConfirmText) { $CopyConfirmText.Text = $Message }

        # Ein evtl. noch laufender Ausblend-Zaehler wird zurueckgesetzt,
        # damit mehrmaliges Kopieren den Hinweis frisch anzeigt.
        if ($null -ne $script:CopyConfirmTimer) {
            try { $script:CopyConfirmTimer.Stop() } catch {}
            $script:CopyConfirmTimer = $null
        }

        $CopyConfirm.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        $CopyConfirm.Opacity = 0
        $CopyConfirm.Visibility = 'Visible'
        $fadeIn = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(220))
        $CopyConfirm.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeIn)
        # Version 6.0: Die Glas-Pille gleitet zusaetzlich sanft nach oben.
        try {
            $rise = [System.Windows.Media.Animation.DoubleAnimation]::new(10, 0, [System.TimeSpan]::FromMilliseconds(260))
            $riseEase = [System.Windows.Media.Animation.CubicEase]::new()
            $riseEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
            $rise.EasingFunction = $riseEase
            $CopyConfirm.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $rise)
        } catch {}

        $timer = [System.Windows.Threading.DispatcherTimer]::new()
        $timer.Interval = [System.TimeSpan]::FromSeconds($Seconds)
        $timer.Tag = $CopyConfirm
        $timer.Add_Tick({
            param($s, $e)
            $s.Stop()
            $panel = $s.Tag
            try {
                $fadeOut = [System.Windows.Media.Animation.DoubleAnimation]::new(1, 0, [System.TimeSpan]::FromMilliseconds(520))
                $panel.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeOut)
                $hideTimer = [System.Windows.Threading.DispatcherTimer]::new()
                $hideTimer.Interval = [System.TimeSpan]::FromMilliseconds(560)
                $hideTimer.Tag = $panel
                $hideTimer.Add_Tick({
                    param($s2, $e2)
                    $s2.Stop()
                    try { $s2.Tag.Visibility = 'Collapsed' } catch {}
                })
                $hideTimer.Start()
            } catch {
                try { $panel.Visibility = 'Collapsed' } catch {}
            }
        })
        $script:CopyConfirmTimer = $timer
        $timer.Start()
    } catch {
        # Der Hinweis ist reine Bequemlichkeit - er darf nie etwas kaputtmachen.
        try { $CopyConfirm.Visibility = 'Collapsed' } catch {}
    }
}

# ----------------------------------------------------------------------------
# STARTBILDSCHIRM (Version 3.4)
# Ladekreisel mit Fortschritt. Die Spieleliste erscheint erst, wenn alles
# bereit ist (oder ein Fehler/Timeout den Start beendet).
# ----------------------------------------------------------------------------
function Hide-Splash {
    if ($script:SplashDismissed) { return }
    $script:SplashDismissed = $true
    try {
        $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(1, 0, [System.TimeSpan]::FromMilliseconds(420))
        $SplashScreen.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fade)
        $collapseTimer = [System.Windows.Threading.DispatcherTimer]::new()
        $collapseTimer.Interval = [System.TimeSpan]::FromMilliseconds(460)
        $collapseTimer.Tag = $SplashScreen
        $collapseTimer.Add_Tick({
            param($s, $e)
            $s.Stop()
            try { $s.Tag.Visibility = 'Collapsed' } catch {}
        })
        $collapseTimer.Start()
    } catch {
        try { $SplashScreen.Visibility = 'Collapsed' } catch {}
    }
}

function Update-SplashScreen {
    if ($script:SplashDismissed) { return }
    if ($null -eq $SplashScreen) { return }

    # 3.5: StartupBlocked = der Start wurde abgebrochen (z.B. Port belegt).
    # In dem Fall ist "Plugin nicht installiert" KEIN Fehler, sondern Folge
    # des Abbruchs - der Startbildschirm muss sichtbar bleiben und den
    # Grund zeigen (genau das machte die 3.4 kaputt: sie blendete sofort aus).
    $studioFound = [bool]$script:RobloxStudioPath
    $blocked = [bool]$script:StartupBlocked
    $pluginFailed = ($studioFound -and -not $blocked -and -not $script:PluginInstalled)
    $tunnelFailed = ((-not $blocked) -and ($script:TunnelInstallFailed -or $script:TunnelFailed -or $script:TunnelMissing))
    $tunnelActive = ($script:TunnelInstalling -or $script:TunnelProcess)

    # Zeile: Roblox Studio
    if ($studioFound) {
        Set-Dot $SplashStudioDot $script:ColorGreen
        Set-Text $SplashStudioState 'Gefunden'
    } else {
        Set-Dot $SplashStudioDot $script:ColorRed
        Set-Text $SplashStudioState 'Nicht gefunden'
    }

    # Zeile: Studio-Plugin
    if ($blocked) {
        Set-Dot $SplashPluginDot $script:ColorGray
        Set-Text $SplashPluginState 'Übersprungen'
    } elseif (-not $studioFound) {
        Set-Dot $SplashPluginDot $script:ColorGray
        Set-Text $SplashPluginState 'Wartet'
    } elseif ($script:PluginInstalled) {
        Set-Dot $SplashPluginDot $script:ColorGreen
        Set-Text $SplashPluginState 'Installiert'
    } else {
        Set-Dot $SplashPluginDot $script:ColorRed
        Set-Text $SplashPluginState 'Fehler'
    }

    # Zeile: Cloudflare-Tunnel (der aktive Punkt pulsiert)
    if ($blocked) {
        Set-Dot $SplashTunnelDot $script:ColorGray
        Set-Text $SplashTunnelState 'Nicht gestartet'
    } elseif ($script:TunnelUrl) {
        Set-Dot $SplashTunnelDot $script:ColorGreen
        Set-Text $SplashTunnelState 'Verbunden'
    } elseif ($tunnelFailed) {
        Set-Dot $SplashTunnelDot $script:ColorRed
        Set-Text $SplashTunnelState 'Fehler'
    } elseif ($script:TunnelInstalling) {
        Set-Dot $SplashTunnelDot $script:ColorAmber
        Set-Text $SplashTunnelState 'Wird installiert'
    } elseif ($script:TunnelProcess) {
        Set-Dot $SplashTunnelDot $script:ColorAmber
        Set-Text $SplashTunnelState 'Verbindet'
    } else {
        Set-Dot $SplashTunnelDot $script:ColorGray
        Set-Text $SplashTunnelState 'Wartet'
    }
    if ($tunnelActive -and -not $script:TunnelUrl) {
        if (-not $script:SplashTunnelPulse) {
            $script:SplashTunnelPulse = $true
            $pulse = [System.Windows.Media.Animation.DoubleAnimation]::new(0.3, 1, [System.TimeSpan]::FromMilliseconds(650))
            $pulse.AutoReverse = $true
            $pulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $SplashTunnelDot.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $pulse)
        }
    } elseif ($script:SplashTunnelPulse) {
        $script:SplashTunnelPulse = $false
        $SplashTunnelDot.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        try { $SplashTunnelDot.Opacity = 1 } catch {}
    }

    # Ueberschrift + Untertext
    if ($blocked) {
        Set-Text $SplashHeadline 'Start fehlgeschlagen'
        Set-Text $SplashSub "Der lokale Port $($script:Port) konnte nicht freigegeben werden. Bitte schließe dieses Programm und starte es erneut - dabei wird die blockierende Instanz jetzt zuverlässig beendet. Hilft das nicht: PC einmal neu starten. Details: Protokoll (runtime.log) im Ordner %LOCALAPPDATA%\ArenaRobloxBridge."
    } elseif (-not $studioFound) {
        Set-Text $SplashHeadline 'Roblox Studio wurde nicht gefunden'
        Set-Text $SplashSub 'Bitte installiere Roblox Studio und starte dieses Programm danach neu.'
    } elseif ($pluginFailed) {
        Set-Text $SplashHeadline 'Studio-Plugin konnte nicht installiert werden'
        Set-Text $SplashSub 'Details stehen im Protokoll: %LOCALAPPDATA%\ArenaRobloxBridge\runtime.log'
    } elseif ($script:TunnelUrl) {
        Set-Text $SplashHeadline 'Alles bereit!'
        Set-Text $SplashSub 'Öffne ein Place in Roblox Studio - es erscheint automatisch in der Liste.'
    } elseif ($script:TunnelInstalling) {
        Set-Text $SplashHeadline 'Cloudflared wird installiert …'
        Set-Text $SplashSub 'Der Cloudflare-Tunnel wird automatisch heruntergeladen (dauert je nach Verbindung 1-3 Minuten).'
    } elseif ($tunnelFailed) {
        Set-Text $SplashHeadline 'Cloudflare-Tunnel fehlgeschlagen'
        $hint = if ($script:TunnelInstallMessage) { $script:TunnelInstallMessage } elseif ($script:LastTunnelMessage) { $script:LastTunnelMessage } else { 'Details stehen im Protokoll.' }
        if ($hint.Length -gt 220) { $hint = $hint.Substring(0, 220) + ' …' }
        Set-Text $SplashSub $hint
    } else {
        Set-Text $SplashHeadline 'Cloudflare-Tunnel wird verbunden …'
        Set-Text $SplashSub 'Das dauert normalerweise nur wenige Sekunden.'
    }

    # Ausblenden, wenn alles fertig ist (kurz "Alles bereit!" zeigen).
    # Bei einem endgueltigen Fehler bleibt der Startbildschirm ZUERST 10
    # Sekunden stehen (3.5: damit die Fehlermeldung auch gelesen werden
    # kann), danach blendet er aus und gibt die Oberflaeche frei.
    $allDone = ($studioFound -and $script:PluginInstalled -and $script:TunnelUrl)
    $terminal = ((-not $studioFound) -or $blocked -or $pluginFailed -or $tunnelFailed)
    $timedOut = (((Get-Date) - $script:StartTime).TotalSeconds -gt 150)
    if ($allDone) {
        if (-not $script:SplashReadyAt) { $script:SplashReadyAt = Get-Date }
        if (((Get-Date) - $script:SplashReadyAt).TotalMilliseconds -ge 700) { Hide-Splash }
    } elseif ($terminal -or $timedOut) {
        if (-not $script:SplashTerminalAt) { $script:SplashTerminalAt = Get-Date }
        if (((Get-Date) - $script:SplashTerminalAt).TotalMilliseconds -ge 10000) { Hide-Splash }
    }
}

# ----------------------------------------------------------------------------
# Version 7.0.3: LAUFZEITDIAGNOSTIK (Leistung) - Ausgabe auf der UI-Seite.
# Es wird NICHTS geschrieben, solange die Diagnose in den Einstellungen aus
# ist (Standard). Ist sie an, entsteht hoechstens alle 30 Sekunden EINE
# Zeile in runtime.log und ein kompakter Bericht in performance.txt - kein
# Logging pro Tick, keine zusaetzlichen HTTP-Anfragen, keine Messung im
# Vorschaupfad.
# ----------------------------------------------------------------------------
$script:PerfLastWrite = [DateTime]::MinValue
$script:PerfLastSnapshot = @{}

function Test-PerfDiagnosticsEnabled {
    try { return ($script:Shared.BridgeSettings.perfDiagnostics -eq $true) } catch { return $false }
}

function Get-PerfDelta {
    param([string]$Name, [double]$Value)
    $last = 0.0
    if ($script:PerfLastSnapshot.ContainsKey($Name)) { $last = [double]$script:PerfLastSnapshot[$Name] }
    $script:PerfLastSnapshot[$Name] = $Value
    return ($Value - $last)
}

function Update-PerfUiTick {
    param([double]$Milliseconds)
    try {
        $perf = $script:Shared.Perf
        if ($null -ne $perf) {
            $perf.UiTicks = [long]$perf.UiTicks + 1
            $perf.UiMsTotal = [double]$perf.UiMsTotal + $Milliseconds
            if ($Milliseconds -gt [double]$perf.UiMsMax) { $perf.UiMsMax = $Milliseconds }
        }
        Write-PerfReport
    } catch {}
}

function Write-PerfReport {
    param([switch]$Force)
    try {
        if (-not (Test-PerfDiagnosticsEnabled)) {
            $script:PerfLastWrite = [DateTime]::MinValue
            $script:PerfLastSnapshot = @{}
            return
        }
        $now = Get-Date
        if (-not $Force -and ($now - $script:PerfLastWrite).TotalSeconds -lt 30) { return }
        $wasWritten = ($script:PerfLastWrite -ne [DateTime]::MinValue)
        $windowSeconds = 0.0
        if ($wasWritten) { $windowSeconds = ($now - $script:PerfLastWrite).TotalSeconds }
        $script:PerfLastWrite = $now

        $perf = $script:Shared.Perf
        if ($null -eq $perf) { return }
        $lines = New-Object System.Collections.Generic.List[string]
        $lines.Add('Arena Roblox Bridge - Leistungsbericht (Version 7.4.1)')
        $lines.Add('Diese Datei ist klein und kann komplett weitergegeben werden.')
        $lines.Add(('Erstellt: {0:yyyy-MM-dd HH:mm:ss}' -f $now))
        $lines.Add('Diagnose: in den Einstellungen eingeschaltet (standardmaessig aus).')
        $lines.Add('')

        $httpRequests = [double]$perf.HttpRequests
        $httpMsTotal = [double]$perf.HttpMsTotal
        $httpMsMax = [double]$perf.HttpMsMax
        $uiTicks = [double]$perf.UiTicks
        $uiMsTotal = [double]$perf.UiMsTotal
        $uiMsMax = [double]$perf.UiMsMax
        $avgHttp = 0.0
        if ($httpRequests -gt 0) { $avgHttp = $httpMsTotal / $httpRequests }
        $avgUi = 0.0
        if ($uiTicks -gt 0) { $avgUi = $uiMsTotal / $uiTicks }

        $lines.Add('BRIDGE-SEITE (Prozess Arena Roblox Bridge)')
        $lines.Add(('  HTTP-Anfragen gesamt: {0}   davon Poll {1} / Heartbeat {2} / Hello {3}' -f [int]$httpRequests, [int]$perf.PollRequests, [int]$perf.Heartbeats, [int]$perf.HelloRequests))
        $lines.Add(('  Handler-Dauer je Anfrage: Durchschnitt {0:N1} ms, Maximum {1:N0} ms (enthaelt Parsen/Ausfuehren des Handlers)' -f $avgHttp, $httpMsMax))
        $lines.Add(('  UI-Abgleich (Place-Liste): {0} Ticks, Durchschnitt {1:N1} ms, Maximum {2:N0} ms' -f [int]$uiTicks, $avgUi, $uiMsMax))
        if ($wasWritten -and $windowSeconds -gt 1) {
            $uiRate = (Get-PerfDelta 'ui' $uiTicks) / $windowSeconds
            $httpRate = (Get-PerfDelta 'http' $httpRequests) / $windowSeconds
            $lines.Add(('  Letzte Messspanne ({0:N0} s): {1:N2} UI-Ticks/s, {2:N2} HTTP-Anfragen/s' -f $windowSeconds, $uiRate, $httpRate))
        }
        $lines.Add('')

        $lines.Add('STUDIO-PLUGIN (Kanal je verbundenem Place)')
        $sessionCount = 0
        foreach ($sid in @($script:Shared.Sessions.Keys)) {
            try {
                $sessionCount = $sessionCount + 1
                $raw = $null
                if (-not $perf.ContainsKey('Plugin:' + $sid)) { continue }
                $raw = $perf['Plugin:' + $sid]
                $stats = $raw | ConvertFrom-Json
                $periodMs = [double]$stats.periodMs
                if ($periodMs -lt 1) { $periodMs = 1 }
                $requests = [double]$stats.requests
                $pollMs = [double]$stats.pollMs
                $gapMs = [double]$stats.gapMs
                $reqPerMin = $requests * 60000.0 / $periodMs
                $duty = 0.0
                if (($pollMs + $gapMs) -gt 0) { $duty = 100.0 * $pollMs / ($pollMs + $gapMs) }
                $avgPoll = 0.0
                if ([double]$stats.polls -gt 0) { $avgPoll = $pollMs / [double]$stats.polls }
                $avgGap = 0.0
                if ([double]$stats.polls -gt 0) { $avgGap = $gapMs / [double]$stats.polls }
                $mode = 'aktiv'
                if ([int]$stats.quiet -eq 1) { $mode = 'Ruhemodus' }
                $placeName = ''
                if ($script:PlaceNames.ContainsKey([string]$sid)) { $placeName = [string]$script:PlaceNames[[string]$sid] }
                if ([string]::IsNullOrWhiteSpace($placeName)) { $placeName = [string]$sid }
                $lines.Add(('  Place "{0}" ({1})' -f $placeName, $mode))
                $lines.Add(('    Anfragen/Minute: {0:N1}   Poll-Dauer: {1:N0} ms im Mittel, {2:N0} ms maximal erwaehlt' -f $reqPerMin, $avgPoll, [double]$stats.waitMs / [double]([Math]::Max(1, [double]$stats.polls))))
                $lines.Add(('    HTTP-Platz belegt: {0:N0} % der Zeit, Pause: {1:N0} ms im Mittel (Pflichtpause je Anfrage)' -f $duty, $avgGap))
                $lines.Add(('    Befehle empfangen: {0}   Ersatz-Heartbeats: {1}   Messspanne: {2:N0} s' -f [int]$stats.cmds, [int]$stats.hbFallback, $periodMs / 1000.0))
            } catch {}
        }
        if ($sessionCount -eq 0) { $lines.Add('  (kein Place verbunden)') }
        $lines.Add('')
        $lines.Add('BEWERTUNG')
        $lines.Add('  Ziel: Poll-Dauer im Ruhemodus deutlich unter 100 % (Pflichtpause) und wenige Anfragen pro Minute.')
        $lines.Add('  Ist der Platz dauerhaft ~100 % belegt, arbeitet noch ein altes Plugin im Studio-Ordner - Studio neu starten.')

        $path = Join-Path $script:AppDataRoot 'performance.txt'
        [System.IO.File]::WriteAllText($path, ($lines -join [Environment]::NewLine), (New-Object System.Text.UTF8Encoding($false)))
        if ($wasWritten) {
            Write-RuntimeLog ('LEISTUNG Diagnose: HTTP {0} Anfragen, Handler im Mittel {1:N1} ms / max {2:N0} ms; UI-Ticks {3}, im Mittel {4:N1} ms / max {5:N0} ms; Orte {6}. Details: {7}' -f `
                [int]$httpRequests, $avgHttp, $httpMsMax, [int]$uiTicks, $avgUi, $uiMsMax, $sessionCount, $path)
        }
    } catch {
        try { Write-RuntimeLog ('Leistungsbericht konnte nicht geschrieben werden: ' + $_.Exception.Message) } catch {}
    }
}

function Refresh-Ui {
    # Version 7.4.0: Blender-Schritt 4 und Mesh-Takt laufen ganz vorne im
    # UI-Takt - auch dann, wenn (noch) kein Studio gefunden wurde, denn der
    # Blender-Schritt gehoert vor den Tunnel.
    try { Complete-BlenderStartupGate } catch { }
    try { Update-BlenderSplashRow $null } catch { }
    try { Update-MeshTick } catch { }
    try { if ($null -ne $script:MeshWindow) { Update-MeshWindow } } catch { }
    # Version 7.4.1: Das Mesh-Fenster kommt von selbst, sobald eine OBJ auf
    # den Upload wartet (modellos, ohne Menueeintrag).
    try { Update-MeshAutoWindow } catch { }
    $line = $null
    while ($script:TunnelLines.TryDequeue([ref]$line)) {
        $lineText = [string]$line
        $lineProcessId = 0
        if ($lineText -match '^\[pid=(\d+)\]\s*(.*)$') {
            try { $lineProcessId = [int]$matches[1] } catch {}
            $lineText = [string]$matches[2]
        }
        $activeProcessId = 0
        try { if ($null -ne $script:TunnelProcess) { $activeProcessId = [int]$script:TunnelProcess.Id } } catch {}
        # Nach Restart nur die Ausgabe des aktuellen cloudflared-Prozesses
        # akzeptieren. Unmarkierte Altzeilen bleiben fuer Kompatibilitaet lesbar.
        if ($lineProcessId -gt 0 -and $activeProcessId -gt 0 -and $lineProcessId -ne $activeProcessId) { continue }
        $script:LastTunnelMessage = $lineText
        if ($lineText -match 'https?://[A-Za-z0-9._-]+\.trycloudflare\.com') {
            $isNewTunnelUrl = ([string]$script:TunnelUrl -ne [string]$matches[0])
            $script:TunnelUrl = $matches[0]
            if ($isNewTunnelUrl) { $script:TunnelLiveSince = Get-Date }
            $script:TunnelNextRestartAt = [DateTime]::MinValue
            $script:TunnelLastExitCode = ''
            Write-RuntimeLog "Tunnel URL erkannt: $script:TunnelUrl"
            if (-not $script:TunnelReadyNotified) {
                $script:TunnelReadyNotified = $true
                Show-Toast -Message 'Tunnel ist bereit. Places können sich jetzt verbinden.' -Kind 'Success'
            }
        }
    }

    # Eine ausgegebene trycloudflare-URL ist nur gueltig, solange der zugehoerige
    # cloudflared-Prozess lebt. Vorher gewann `$TunnelUrl` die UI-Abfrage auch
    # nach einem Prozessende und verteilte dadurch eine tote TLS-Adresse.
    # Ein nur kurz ausgegebener Link darf den Backoff nicht wieder auf drei
    # Sekunden setzen; erst eine stabile Minute gilt als erfolgreiche Heilung.
    try {
        if ($script:TunnelUrl -and -not $script:TunnelFailed -and [int]$script:TunnelRecoveryAttempts -gt 0 -and
            $script:TunnelLiveSince -ne [DateTime]::MinValue -and ((Get-Date) - $script:TunnelLiveSince).TotalSeconds -ge 60) {
            $script:TunnelRecoveryAttempts = 0
            $script:TunnelNextRestartAt = [DateTime]::MinValue
            Write-RuntimeLog 'Cloudflare-Tunnel lief 60 Sekunden stabil; Wiederherstellungs-Backoff ist zurueckgesetzt.'
        }
    } catch {}
    $tunnelEnded = $false
    $exitCode = ''
    try {
        if ($null -ne $script:TunnelProcess -and [bool]$script:TunnelProcess.HasExited) {
            $tunnelEnded = $true
            try { $exitCode = [string]$script:TunnelProcess.ExitCode } catch {}
        }
    } catch {}
    if ($tunnelEnded) {
        $oldTunnelUrl = [string]$script:TunnelUrl
        $script:TunnelProcess = $null
        $script:TunnelUrl = $null
        $script:TunnelLiveSince = [DateTime]::MinValue
        $script:TunnelFailed = $true
        $script:TunnelLastExitCode = $exitCode
        $script:LastTunnelMessage = 'Cloudflared wurde beendet' + $(if ($exitCode) { ' (Exit ' + $exitCode + ')' } else { '' }) + '. Die alte Tunnel-Adresse wurde verworfen.'
        Write-RuntimeLog ($script:LastTunnelMessage + $(if ($oldTunnelUrl) { ' Alte URL war ' + $oldTunnelUrl + '.' } else { '' }))
    }

    # Begrenzte Selbstheilung: Ein frischer Quick Tunnel ist die einzige
    # moegliche Reparatur fuer eine nach Prozessende tote Cloudflare-TLS-Adresse.
    # Nach einem Auto/QUIC-Abbruch wechselt der erste Retry zu HTTP/2; weitere
    # Versuche bleiben gedrosselt (3, 6, 12, 24, maximal 45 Sekunden).
    if (($script:TunnelFailed -eq $true) -and -not $script:TunnelInstalling) {
        $recoveryNow = Get-Date
        if ($script:TunnelNextRestartAt -eq [DateTime]::MinValue) {
            $script:TunnelRecoveryAttempts = [Math]::Min(5, ([int]$script:TunnelRecoveryAttempts + 1))
            $backoffPower = [Math]::Max(0, ([int]$script:TunnelRecoveryAttempts - 1))
            $delaySeconds = [int][Math]::Min(45, (3 * [Math]::Pow(2, $backoffPower)))
            $script:TunnelNextRestartAt = $recoveryNow.AddSeconds($delaySeconds)
            Write-RuntimeLog ('Cloudflare-Tunnel-Wiederherstellung geplant in ' + [string]$delaySeconds + ' s (Versuch ' + [string]$script:TunnelRecoveryAttempts + ').')
        } elseif ($recoveryNow -ge $script:TunnelNextRestartAt) {
            $recoveryProtocol = if ([string]$script:TunnelProtocol -eq 'auto') { 'http2' } else { [string]$script:TunnelProtocol }
            $script:TunnelNextRestartAt = [DateTime]::MinValue
            Write-RuntimeLog ('Cloudflare-Tunnel wird selbst geheilt (Protokoll ' + $recoveryProtocol + ', Versuch ' + [string]$script:TunnelRecoveryAttempts + ').')
            Restart-CloudflareTunnel -Protocol $recoveryProtocol
        }
    }

    # Die Tunnel-Ausgabe oben wird auch minimiert abgearbeitet. Die Place-Liste
    # und WPF-Zeilen sind unsichtbar; Server/Plugin laufen separat weiter.
    try { if ($window -and $window.WindowState -eq 'Minimized') { return } } catch {}

    # Startbildschirm aktualisieren (Ladekreisel, Fortschritt, Ausblenden)
    Update-SplashScreen

    if (-not $script:RobloxStudioPath) {
        Set-LiveBadge 'OFFLINE' $script:ColorRed '#33E11D48' '#66FF5C77'
        Set-Text $EmptyTitle 'Roblox Studio wurde nicht gefunden'
        Set-Text $EmptyBody 'Installiere Roblox Studio, schließe dieses Fenster und öffne Arena Roblox Bridge danach erneut.'
        $EmptyState.Visibility = 'Visible'
        Sync-PlaceList @()
        return
    }

    if ($script:TunnelUrl -and -not $script:TunnelFailed) {
        Set-LiveBadge 'LIVE' $script:ColorGreen '#331FA34A' '#662FCB6C'
    } elseif ($script:TunnelInstalling) {
        # Cloudflared wird gerade automatisch heruntergeladen bzw. installiert.
        # Die Oberflaeche prueft den Fortschritt und startet den Tunnel
        # automatisch, sobald cloudflared verfuegbar ist.
        $installReady = $false
        $installError = $null
        if (Get-CloudflaredPath) {
            $installReady = $true
        } else {
            $installStatusPath = Join-Path $script:BinFolder 'install.status'
            if (Test-Path -LiteralPath $installStatusPath) {
                $installStatus = ''
                try { $installStatus = ([string](Get-Content -LiteralPath $installStatusPath -Raw)).Trim() } catch {}
                if ($installStatus -eq 'ok') {
                    # Installation fertig gemeldet, aber noch nicht gefunden:
                    # PATH neu einlesen (winget aendert den PATH eines laufenden
                    # Programms nicht von selbst) und erneut suchen.
                    Update-ProcessPath
                    if (Get-CloudflaredPath) { $installReady = $true }
                } elseif ($installStatus.StartsWith('error:')) {
                    $installError = $installStatus.Substring(6).Trim()
                }
            }
        }
        if ($installError) {
            $script:TunnelInstalling = $false
            $script:TunnelInstallFailed = $true
            $script:TunnelInstallMessage = $installError
            Write-RuntimeLog "Automatische Cloudflared-Installation fehlgeschlagen: $installError"
            Show-Toast -Message 'Cloudflared konnte nicht automatisch installiert werden. Details stehen im Protokoll.' -Kind 'Error' -Seconds 10
        } elseif ($installReady) {
            $script:TunnelInstalling = $false
            Write-RuntimeLog 'Cloudflared wurde automatisch installiert - Tunnel wird jetzt gestartet.'
            Show-Toast -Message 'Cloudflared wurde automatisch installiert. Der Tunnel wird jetzt gestartet ...' -Kind 'Success' -Seconds 6
            Start-CloudflareTunnel
        } else {
            $installSeconds = 0
            if ($script:TunnelInstallStartedAt) { $installSeconds = [int](((Get-Date) - $script:TunnelInstallStartedAt).TotalSeconds) }
            Set-LiveBadge 'INSTALL' $script:ColorAmber '#33C77F14' '#66FFC95E'
        }
    } elseif ($script:TunnelInstallFailed) {
        Set-LiveBadge 'FEHLER' $script:ColorRed '#33E11D48' '#66FF5C77'
        if (-not $script:TunnelInstallErrorNotified) {
            $script:TunnelInstallErrorNotified = $true
            $message = if ($script:TunnelInstallMessage) { $script:TunnelInstallMessage } else { 'Unbekannter Fehler.' }
            if ($message.Length -gt 300) { $message = $message.Substring(0, 300) + ' ...' }
            Write-RuntimeLog "Cloudflared-Installation endgueltig fehlgeschlagen: $($script:TunnelInstallMessage)"
            Show-Toast -Message "Cloudflared konnte nicht automatisch installiert werden: $message" -Kind 'Error' -Seconds 12
        }
    } elseif ($script:TunnelMissing) {
        Set-LiveBadge 'FEHLT' $script:ColorRed '#33E11D48' '#66FF5C77'
        if ($script:LastTunnelMessage -and -not $script:TunnelMissingNotified) {
            $script:TunnelMissingNotified = $true
            Show-Toast -Message $script:LastTunnelMessage -Kind 'Warn' -Seconds 7
        }
    } elseif ($script:TunnelFailed -or ($script:TunnelProcess -and $script:TunnelProcess.HasExited)) {
        $recoverySeconds = 0
        try {
            if ($script:TunnelNextRestartAt -gt (Get-Date)) { $recoverySeconds = [int][Math]::Ceiling(($script:TunnelNextRestartAt - (Get-Date)).TotalSeconds) }
        } catch {}
        if ($recoverySeconds -gt 0) {
            Set-LiveBadge 'HEILT' $script:ColorAmber '#33C77F14' '#66FFC95E'
        } else {
            Set-LiveBadge 'FEHLER' $script:ColorRed '#33E11D48' '#66FF5C77'
        }
        if (-not $script:TunnelErrorNotified) {
            $script:TunnelErrorNotified = $true
            $message = if ($script:LastTunnelMessage) { $script:LastTunnelMessage } else { 'Cloudflared hat sich sofort wieder beendet.' }
            if ($recoverySeconds -gt 0) { $message = $message + ' Wiederherstellung in ' + [string]$recoverySeconds + ' s.' }
            Write-RuntimeLog "Tunnel ohne Adresse beendet: $message"
            # Bestehende Fehleranzeige; kein neuer Benachrichtigungskanal.
            Show-Toast -Message $message -Kind 'Error' -Seconds 8
        }
    } else {
        $seconds = 0
        if ($script:TunnelStartedAt) { $seconds = [int](((Get-Date) - $script:TunnelStartedAt).TotalSeconds) }
        Set-LiveBadge 'VERBINDEN' $script:ColorAmber '#33C77F14' '#66FFC95E'

        if ($script:TunnelProcess -and -not $script:TunnelHttp2Tried -and $seconds -gt 20) {
            $script:TunnelHttp2Tried = $true
            Write-RuntimeLog "Tunnel nach $seconds Sekunden ohne Adresse - Neustart mit HTTP/2."
            Show-Toast -Message 'Tunnel braucht ungewoehnlich lange. Cloudflared wird mit HTTP/2 neu gestartet ...' -Kind 'Warn' -Seconds 6
            Restart-CloudflareTunnel -Protocol 'http2'
        } elseif ($script:TunnelProcess -and -not $script:TunnelSlowNotified -and $seconds -gt 55) {
            $script:TunnelSlowNotified = $true
            $hint = if ($script:LastTunnelMessage) { $script:LastTunnelMessage } else { 'Cloudflared liefert keine Adresse.' }
            Write-RuntimeLog "Tunnel weiter ohne Adresse: $hint"
            Show-Toast -Message "Tunnel weiter ohne Adresse: $hint" -Kind 'Warn' -Seconds 10
        }
    }

    if (-not $script:ServerCheckDone -and ((Get-Date) - $script:StartTime).TotalMilliseconds -gt 1500) {
        $script:ServerCheckDone = $true
        if (Test-PortListening $script:Port) {
            $script:ServerStarted = $true
            Write-RuntimeLog "Server OK: Port $($script:Port) antwortet."
        } else {
            Write-RuntimeLog "ACHTUNG: Der lokale Server antwortet nicht auf Port $($script:Port)."
            Show-Toast -Message "Lokaler Server konnte nicht gestartet werden (Port $($script:Port)). Details: $script:RuntimeLog" -Kind 'Error' -Seconds 8
        }
    }

    Write-ChannelDiagnoseFile
    # Version 7.2.0 (D3): Fragenfenster oeffnen, sobald eine Frage anliegt.
    Sync-AskWindows
    Update-PlacePreviewCaptures
    $activeStudios = @(Get-ActiveStudios)
    Update-HandoffCard
    Sync-PlaceList $activeStudios
}

# ----------------------------------------------------------------------------
# Version 5.0.2: Zeile sichtbar in die Place-Liste haengen (mit Sicherheitsnetz)
# - Der Einblend-Fade ist gekapselt: Schlaegt BeginAnimation fehl, wird die
#   Zeile hart auf sichtbar gestellt. Vorher stand sie mit Opacity=0
#   dauerhaft unsichtbar im Baum, weil UiRows bereits gesetzt war und der
#   naechste Refresh in den Update-Zweig lief (kein neuer Fade-Versuch).
# - Ein Watchdog prueft nach 1,5 s, ob die Animation ueberhaupt angelaufen
#   ist - bleibt sie beim Startwert 0 haengen, wird hart eingeblendet.
# - Danach wird der echte Zustand einmal in runtime.log gemessen: Kinderzahl,
#   Groesse von PlaceList, Visibility/IsVisible/Hoehe/Opacity der Zeile. Der
#   Log trennt damit sauber "Zeile nie gebaut", "Zeile gebaut aber
#   unsichtbar" und "Layout ohne Platz" - keine Diagnose mehr ins Blaue.
# ----------------------------------------------------------------------------
function Add-PlaceRowToPlaceList {
    param($Row, [string]$SessionId, [string]$Label)

    if ($null -eq $Row -or $null -eq $Row.Root) { throw 'Place-Zeile oder Root-Control ist null.' }
    $Row.Root.Tag = $SessionId
    $PlaceList.Children.Add($Row.Root) | Out-Null

    try {
        $Row.Root.Opacity = 0
        $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(260))
        $Row.Root.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fade)
    } catch {
        try { $Row.Root.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null) } catch {}
        try { $Row.Root.Opacity = 1 } catch {}
        Write-UiErrorLog ($Label + ': Einblend-Animation fehlgeschlagen - Zeile wurde hart auf sichtbar gestellt') $_
    }

    # Watchdog: Startet die Animation nie (Clock ohne einen einzigen Tick),
    # bleibt der animierte Wert beim From-Wert 0 haengen -> hart auf sichtbar.
    try {
        $fadeWatch = [System.Windows.Threading.DispatcherTimer]::new()
        $fadeWatch.Interval = [System.TimeSpan]::FromMilliseconds(1500)
        $fadeWatch.Tag = $Row.Root
        $fadeWatch.Add_Tick({
            param($s, $e)
            $s.Stop()
            $element = $s.Tag
            try {
                if ($element.Opacity -lt 0.05) {
                    $element.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
                    $element.Opacity = 1
                    Write-RuntimeLog 'Place-Zeile: Einblend-Animation kam nie an - Zeile wurde nachtraeglich hart auf sichtbar gestellt.'
                }
            } catch {}
        })
        $fadeWatch.Start()
    } catch {}

    # Diagnose: einmal pro neuer Zeile den echten Zustand messen und loggen.
    # UpdateLayout() erzwingt den Layout-Durchlauf, sonst waeren die
    # Actual-Werte zum Messzeitpunkt noch 0.
    try {
        $PlaceList.UpdateLayout()
        Write-RuntimeLog ('{0} hinzugefuegt (sid={1}): PlaceList.Children={2}, PlaceList {3}x{4}px, Zeile: Visibility={5}, IsVisible={6}, ActualHeight={7}px, ActualWidth={8}px, Opacity={9}' -f $Label, $SessionId, $PlaceList.Children.Count, [int]$PlaceList.ActualWidth, [int]$PlaceList.ActualHeight, $Row.Root.Visibility, $Row.Root.IsVisible, [int]$Row.Root.ActualHeight, [int]$Row.Root.ActualWidth, [string]$Row.Root.Opacity)
    } catch {
        Write-UiErrorLog ($Label + ': Diagnose-Vermessung fehlgeschlagen') $_
    }

    # Version 6.0.4: Sichtbarer Selbsttest des kompletten Vorschau-UI-Pfads
    # (einmal je Programmstart, erste echte Place-Zeile): Ein im Speicher
    # gezeichnetes Testbild durchlaeuft exakt denselben Set-PlacePreviewImage-
    # Weg wie echte Aufnahmen. Ergebnis im Log: PREVIEW_UI_SELFTEST_OK oder
    # PREVIEW_UI_SELFTEST_FAILED - damit ist sofort entschieden, ob der
    # Fehler in WPF/UI oder in der Fensteraufnahme liegt.
    try {
        if ($script:SettingsCache.editorIconsEnabled -ne $false -and -not $Row.IsMinimalFallback -and -not $script:PreviewSelfTestDone -and $Label -eq 'Place-Zeile') {
            $script:PreviewSelfTestDone = $true
            Invoke-PlacePreviewUiSelfTest $Row $SessionId
        }
    } catch {
        Write-UiErrorLog 'Vorschau-Selbsttest konnte nicht ausgefuehrt werden' $_
        try { Write-RuntimeLog ('PREVIEW_UI_SELFTEST_FAILED sid=' + [string]$SessionId + ' error=' + [string]$_.Exception.Message) } catch {}
    }
}

function New-MinimalPlaceRow {
    param($Studio, [string]$SessionId)

    # A connected session must still get a visible, useful row when a nonessential
    # rich control (menu, preview, animation) fails to construct.
    $row = [pscustomobject]@{
        SessionId = $SessionId
        Root = $null; Title = $null; Copy = $null; Menu = $null; Popup = $null
        Toggle = $null; IconFrame = $null; IconImage = $null; IconSpinner = $null
        IconFallback = $null; IconVisual = $null; PreviewHandle = [IntPtr]::Zero; PreviewHasFrame = $false
        PreviewVerifyDone = $false; IconIconAttempted = $false; PreviewFailCount = 0
        PreviewLoggedOnce = $false; Mode = $(if ([string]$Studio.accessMode -eq 'readonly') {'readonly'} else {'readwrite'})
        ModeUntil = [DateTime]::MinValue; StaleText = $null
        ProgressPanel = $null; ProgressBar = $null; ProgressText = $null
        ProgressPercent = $null; ProgressState = 'idle'; IsMinimalFallback = $true
        CommandCancelButton = $null
    }

    $root = [System.Windows.Controls.Border]::new()
    $root.CornerRadius = [System.Windows.CornerRadius]::new(14)
    $root.Background = Get-Brush '#C9121C44'
    $root.BorderBrush = Get-Brush '#3DFFFFFF'
    $root.BorderThickness = [System.Windows.Thickness]::new(1)
    $root.Padding = [System.Windows.Thickness]::new(16, 7, 12, 7)
    $root.Margin = [System.Windows.Thickness]::new(0, 0, 0, 10)
    $root.MinHeight = 64
    $root.Tag = $SessionId

    $content = [System.Windows.Controls.Grid]::new()
    $copyColumn = [System.Windows.Controls.ColumnDefinition]::new()
    $copyColumn.Width = [System.Windows.GridLength]::Auto
    $content.ColumnDefinitions.Add([System.Windows.Controls.ColumnDefinition]::new()) | Out-Null
    $content.ColumnDefinitions.Add($copyColumn) | Out-Null

    $namePanel = [System.Windows.Controls.StackPanel]::new()
    # Version 7.0.5: auch die Ersatzzeile zentriert ihren Inhalt wieder.
    $namePanel.VerticalAlignment = 'Center'
    $title = [System.Windows.Controls.TextBlock]::new()
    $title.Text = Get-PlaceDisplayName $Studio $null
    $title.Foreground = Get-Brush '#F2F6FF'
    $title.FontSize = 14
    $title.FontWeight = 'SemiBold'
    $title.TextTrimming = 'CharacterEllipsis'
    $title.ToolTip = $title.Text
    $staleText = [System.Windows.Controls.TextBlock]::new()
    $staleText.Text = if ($Studio.versionMismatch -eq $true) { 'Plugin veraltet - Studio neustarten' } else { '' }
    $staleText.Foreground = Get-Brush '#FFFF8C9F'
    $staleText.FontSize = 10.5
    $staleText.Margin = [System.Windows.Thickness]::new(0, 2, 0, 0)
    $staleText.Visibility = if ($Studio.versionMismatch -eq $true) { 'Visible' } else { 'Collapsed' }
    $namePanel.Children.Add($title) | Out-Null
    $namePanel.Children.Add($staleText) | Out-Null
    $progressText = [System.Windows.Controls.TextBlock]::new()
    $progressText.Foreground = Get-Brush '#FF6FB6FF'
    $progressText.FontSize = 11
    $progressText.FontWeight = 'SemiBold'
    $progressText.VerticalAlignment = 'Center'
    $progressBar = [System.Windows.Controls.ProgressBar]::new()
    $progressBar.Minimum = 0
    $progressBar.Maximum = 100
    $progressBar.Height = 6
    $progressBar.Width = 120
    $progressBar.VerticalAlignment = 'Center'
    $progressBar.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
    $progressBar.Foreground = Get-Brush '#FF4C9BFF'
    $progressBar.Background = Get-Brush '#33000000'
    $progressBar.BorderThickness = [System.Windows.Thickness]::new(0)
    $progressPercent = [System.Windows.Controls.TextBlock]::new()
    $progressPercent.Foreground = Get-Brush '#FF9CCBFF'
    $progressPercent.FontSize = 10.5
    $progressPercent.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
    $progressPercent.VerticalAlignment = 'Center'
    $progressPanel = [System.Windows.Controls.StackPanel]::new()
    $progressPanel.Orientation = 'Horizontal'
    $progressPanel.Margin = [System.Windows.Thickness]::new(0, 2, 0, 0)
    $progressPanel.Visibility = 'Collapsed'
    $progressPanel.Children.Add($progressText) | Out-Null
    $progressPanel.Children.Add($progressBar) | Out-Null
    $progressPanel.Children.Add($progressPercent) | Out-Null
    try {
        $cancelButton = [System.Windows.Controls.Button]::new()
        $cancelButton.Content = 'Abbrechen'
        $cancelButton.FontSize = 10
        $cancelButton.Padding = [System.Windows.Thickness]::new(6, 1, 6, 1)
        $cancelButton.Margin = [System.Windows.Thickness]::new(10, 0, 0, 0)
        $cancelButton.VerticalAlignment = 'Center'
        $cancelButton.Visibility = 'Collapsed'
        $cancelButton.Add_Click({ param($sender, $eventArgs) try { Invoke-PlaceRowCancel ([string]$sender.Tag) } catch {} })
        $progressPanel.Children.Add($cancelButton) | Out-Null
        $row.CommandCancelButton = $cancelButton
    } catch {
        Write-UiErrorLog 'Abbrechen-Knopf konnte in der Minimalzeile nicht gebaut werden' $_
    }
    $namePanel.Children.Add($progressPanel) | Out-Null
    $row.ProgressPanel = $progressPanel
    $row.ProgressBar = $progressBar
    $row.ProgressText = $progressText
    $row.ProgressPercent = $progressPercent
    [System.Windows.Controls.Grid]::SetColumn($namePanel, 0)
    $content.Children.Add($namePanel) | Out-Null

    $copyButton = [System.Windows.Controls.Button]::new()
    $copyButton.MinWidth = 154
    $copyButton.Height = 40
    $copyButton.Margin = [System.Windows.Thickness]::new(16, 0, 0, 0)
    $copyButton.VerticalAlignment = 'Center'
    $copyButton.HorizontalAlignment = 'Right'
    $copyButton.Cursor = [System.Windows.Input.Cursors]::Hand
    $copyButton.Background = $window.FindResource('GreenBtnBg')
    $copyButton.BorderBrush = Get-Brush '#4DFFFFFF'
    $copyButton.BorderThickness = [System.Windows.Thickness]::new(1)
    $copyButton.Foreground = Get-Brush '#FFFFFF'
    $copyButton.IsEnabled = (-not [string]::IsNullOrWhiteSpace($script:TunnelUrl)) -and ($Studio.versionMismatch -ne $true)
    $copyButton.ToolTip = 'Prompt-URL und Place-Token kopieren'
    $copyContent = [System.Windows.Controls.StackPanel]::new()
    $copyContent.Orientation = 'Horizontal'
    $copyContent.HorizontalAlignment = 'Center'
    $copyGlyph = [System.Windows.Controls.TextBlock]::new()
    $copyGlyph.Text = [char]0xE8C8
    $copyGlyph.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe MDL2 Assets')
    $copyGlyph.FontSize = 13
    $copyGlyph.Foreground = Get-Brush '#FFFFFF'
    $copyGlyph.VerticalAlignment = 'Center'
    $copyGlyph.Margin = [System.Windows.Thickness]::new(0, 0, 8, 0)
    $copyLabel = [System.Windows.Controls.TextBlock]::new()
    $copyLabel.Text = 'Prompt kopieren'
    $copyLabel.Foreground = Get-Brush '#FFFFFF'
    $copyLabel.VerticalAlignment = 'Center'
    $copyContent.Children.Add($copyGlyph) | Out-Null
    $copyContent.Children.Add($copyLabel) | Out-Null
    $copyButton.Content = $copyContent
    $copyButton.Tag = $SessionId
    $copyButton.Add_Click({ param($sender, $e) Copy-Prompt ([string]$sender.Tag) })
    [System.Windows.Controls.Grid]::SetColumn($copyButton, 1)
    $content.Children.Add($copyButton) | Out-Null

    $root.Child = $content
    $row.Root = $root
    $row.Title = $title
    $row.Copy = $copyButton
    $row.StaleText = $staleText
    return $row
}

# Baut die Liste nur um, wenn sich etwas geaendert hat -> kein Flackern.
function Sync-PlaceList {
    param($Studios)

    $windowNames = $null
    foreach ($studio in $Studios) {
        if (Test-StandardPlaceName ([string]$studio.placeName)) {
            $windowNames = @(Get-StudioWindowName)
            break
        }
    }

    $desired = New-Object System.Collections.Generic.List[string]
    if ($Studios.Count -ge 2) {
        $allSid = '__arena_all_places__'
        $desired.Add($allSid)
        if ($null -eq $script:AllPlacesRow) {
            try {
                $script:AllPlacesRow = New-AllPlacesRow $Studios $windowNames
                $script:UiRows[$allSid] = $script:AllPlacesRow
                Add-PlaceRowToPlaceList $script:AllPlacesRow $allSid 'Alle-Places-Zeile'
            } catch {
                Write-UiErrorLog 'Alle-Places-Zeile konnte nicht erstellt werden' $_
            }
        } else { try { Update-AllPlacesRow $script:AllPlacesRow $Studios } catch { Write-UiErrorLog 'Alle-Places-Zeile konnte nicht aktualisiert werden' $_ } }
    } elseif ($script:AllPlacesRow) {
        try { $script:AllPlacesRow.Popup.IsOpen = $false } catch {}
        $script:UiRows.Remove('__arena_all_places__')
        $script:AllPlacesRow = $null
    }
    foreach ($studio in $Studios) {
        $sid = [string]$studio.sessionId
        if ([string]::IsNullOrWhiteSpace($sid)) { continue }
        $desired.Add($sid)

        if ($script:UiRows.ContainsKey($sid)) {
            $existingRow = $script:UiRows[$sid]
            if ($null -eq $existingRow -or $null -eq $existingRow.Root -or $null -eq $existingRow.Title -or $null -eq $existingRow.Copy) {
                Write-RuntimeLog "Place-Zeile sid=$sid war unvollstaendig; sie wird neu aufgebaut."
                try { if ($existingRow -and $existingRow.Root) { $PlaceList.Children.Remove($existingRow.Root) | Out-Null } } catch {}
                [void]$script:UiRows.Remove($sid)
            }
        }

        if ($script:UiRows.ContainsKey($sid)) {
            try { Update-Row $script:UiRows[$sid] $studio $windowNames } catch {
                $updateErrorRecord = $_
                $updateErrorMessage = [string]$updateErrorRecord.Exception.Message
                Write-PlaceRowFailure -Context 'Place-Zeile konnte nicht aktualisiert werden; ersetze sie durch eine Minimalansicht' -SessionId $sid -ErrorRecord $updateErrorRecord
                $brokenRow = $script:UiRows[$sid]
                try { if ($brokenRow -and $brokenRow.Root) { $PlaceList.Children.Remove($brokenRow.Root) | Out-Null } } catch {}
                [void]$script:UiRows.Remove($sid)
                try {
                    $fallbackRow = New-MinimalPlaceRow $studio $sid
                    $script:UiRows[$sid] = $fallbackRow
                    Add-PlaceRowToPlaceList $fallbackRow $sid 'Place-Zeilen-Fallback'
                    Write-RuntimeLog "PLACE_ROW_FALLBACK sid=$sid stage=update reason=$updateErrorMessage"
                } catch {
                    Write-PlaceRowFailure -Context 'Place-Zeilen-Fallback konnte nicht erstellt werden' -SessionId $sid -ErrorRecord $_
                }
            }
        } else {
            $row = $null
            try {
                $row = New-Row $studio $windowNames
                if ($null -eq $row -or $null -eq $row.Root -or $null -eq $row.Title -or $null -eq $row.Copy) {
                    throw 'New-Row lieferte kein vollstaendiges Zeilenobjekt.'
                }
            } catch {
                $richRowError = [string]$_.Exception.Message
                Write-PlaceRowFailure -Context 'Place-Zeile konnte nicht erstellt werden; versuche Minimalansicht' -SessionId $sid -ErrorRecord $_
                try {
                    $row = New-MinimalPlaceRow $studio $sid
                    Write-RuntimeLog "PLACE_ROW_FALLBACK sid=$sid stage=construct reason=$richRowError"
                } catch {
                    $row = $null
                    Write-PlaceRowFailure -Context 'Place-Zeilen-Fallback konnte nicht erstellt werden' -SessionId $sid -ErrorRecord $_
                }
            }
            if ($null -ne $row -and $null -ne $row.Root) {
                $script:UiRows[$sid] = $row
                try {
                    $label = if ($row.IsMinimalFallback) { 'Place-Zeilen-Fallback' } else { 'Place-Zeile' }
                    Add-PlaceRowToPlaceList $row $sid $label
                } catch {
                    Write-PlaceRowFailure -Context 'Place-Zeile konnte nicht an die Liste angehaengt werden' -SessionId $sid -ErrorRecord $_
                    try { $PlaceList.Children.Remove($row.Root) | Out-Null } catch {}
                    if (-not $row.IsMinimalFallback) {
                        try {
                            $fallbackRow = New-MinimalPlaceRow $studio $sid
                            $script:UiRows[$sid] = $fallbackRow
                            Add-PlaceRowToPlaceList $fallbackRow $sid 'Place-Zeilen-Fallback'
                            Write-RuntimeLog "PLACE_ROW_FALLBACK sid=$sid stage=attach"
                        } catch {
                            Write-PlaceRowFailure -Context 'Place-Zeilen-Fallback konnte nicht an die Liste angehaengt werden' -SessionId $sid -ErrorRecord $_
                            [void]$script:UiRows.Remove($sid)
                        }
                    } else { [void]$script:UiRows.Remove($sid) }
                }
            }
        }
    }

    foreach ($sid in @($script:UiRows.Keys)) {
        if (-not $desired.Contains($sid)) {
            $row = $script:UiRows[$sid]
            try { $row.Popup.IsOpen = $false } catch {}
            $PlaceList.Children.Remove($row.Root) | Out-Null
            $script:UiRows.Remove($sid)
            $script:PlaceNames.Remove($sid)
        }
    }

    $current = New-Object System.Collections.Generic.List[string]
    foreach ($child in $PlaceList.Children) { $current.Add([string]$child.Tag) }
    $reorder = $false
    if ($current.Count -ne $desired.Count) {
        $reorder = $true
    } else {
        for ($i = 0; $i -lt $desired.Count; $i++) {
            if ($desired[$i] -ne $current[$i]) { $reorder = $true; break }
        }
    }
    if ($reorder) {
        # Version 5.0.2: gekapselt - ein Fehler zwischen Clear() und dem
        # Neu-Anordnen liess die Liste leer, ohne eine Spur im Log.
        try {
            $PlaceList.Children.Clear()
            foreach ($sid in $desired) {
                if ($script:UiRows.ContainsKey($sid)) {
                    $PlaceList.Children.Add($script:UiRows[$sid].Root) | Out-Null
                }
            }
        } catch {
            Write-UiErrorLog 'Place-Liste konnte nicht neu angeordnet werden' $_
        }
    }

    $count = $Studios.Count
    Set-Text $PlacesCountText ([string]$count)
    if ($count -eq 0) {
        # Restore the normal empty copy only if this function set the repair
        # message on a previous tick; preserve other diagnostics (e.g. Studio
        # not installed) written by the startup checks.
        if ([string]$EmptyTitle.Text -eq 'Place-Liste wird repariert') {
            Set-Text $EmptyTitle 'Öffne ein Place in Roblox Studio'
            Set-Text $EmptyBody 'Sobald sich ein Studio-Fenster mit einem geladenen Place verbindet, erscheint es hier automatisch.'
        }
        Set-Text $PlaceListStatusText 'Automatisch verbunden'
        $PlaceListStatusText.Foreground = Get-Brush '#AFC0E0'
        $EmptyState.Visibility = 'Visible'
    } elseif ($PlaceList.Children.Count -lt $desired.Count) {
        Set-Text $PlaceListStatusText 'Liste wird repariert'
        $PlaceListStatusText.Foreground = Get-Brush '#FFFFC95E'
        if ($PlaceList.Children.Count -eq 0) {
            Set-Text $EmptyTitle 'Place-Liste wird repariert'
            $emptyBodyText = 'Die Liste ist noch unvollständig. Die Bridge versucht, fehlende Zeilen automatisch erneut anzuzeigen; Details stehen in runtime.log.'
            # Version 7.0.7: den ECHTEN Grund direkt anzeigen - ein Screenshot
            # davon genuegt, um die Ursache zweifelsfrei zu belegen.
            try {
                if (-not [string]::IsNullOrWhiteSpace([string]$script:LastPlaceRowError)) {
                    $emptyBodyText = 'Ursache: ' + [string]$script:LastPlaceRowError + ' - die Bridge versucht es automatisch erneut.'
                }
            } catch {}
            Set-Text $EmptyBody $emptyBodyText
            $EmptyState.Visibility = 'Visible'
        } else {
            # Do not cover rows that did render; report a partial failure in the
            # header while the visible Place rows remain fully usable.
            $EmptyState.Visibility = 'Collapsed'
        }
        if (((Get-Date) - $script:PlaceListRepairLastLog).TotalSeconds -ge 10) {
            $script:PlaceListRepairLastLog = Get-Date
            $visibleIds = New-Object System.Collections.Generic.List[string]
            foreach ($child in $PlaceList.Children) { $visibleIds.Add([string]$child.Tag) }
            $missingIds = New-Object System.Collections.Generic.List[string]
            foreach ($wantedId in $desired) { if (-not $visibleIds.Contains($wantedId)) { $missingIds.Add($wantedId) } }
            $missingText = if ($missingIds.Count -gt 0) { $missingIds -join ',' } else { '(child-count mismatch)' }
            Write-RuntimeLog "PLACE_LIST_INCOMPLETE connectedCount=$count attachedRows=$($PlaceList.Children.Count) expectedRows=$($desired.Count) missing=$missingText uiRows=$($script:UiRows.Count); row fallback will retry."
        }
    } else {
        Set-Text $PlaceListStatusText 'Automatisch verbunden'
        $PlaceListStatusText.Foreground = Get-Brush '#AFC0E0'
        $EmptyState.Visibility = 'Collapsed'
    }
}

# ----------------------------------------------------------------------------
# FENSTERSTEUERUNG
# ----------------------------------------------------------------------------
$TitleBar.Add_MouseLeftButtonDown({
    if ($_.ButtonState -eq [System.Windows.Input.MouseButtonState]::Pressed) {
        $window.DragMove()
    }
})
$CloseButton.Add_Click({ $window.Close() })
$MinimizeButton.Add_Click({ $window.WindowState = 'Minimized' })
# Version 3.8: Die Einstellungen sind ein eigenes, grosses Fenster geworden.
$SettingsButton.Add_Click({
    try { Open-SettingsWindow } catch { Write-RuntimeLog "Einstellungsfenster konnte nicht geoeffnet werden: $($_.Exception.Message)" }
})
$ArenaAiButton.Add_Click({ Open-ArenaAiPage })

$window.Add_PreviewMouseDown({
    param($s, $e)
    try {
        # Version 3.7: Klick ausserhalb schliesst offene Auswahlmenues der
        # Places. Klicks INS Menue oder auf den "..."-Button zaehlen nicht
        # als "ausserhalb" (das Umschalten uebernimmt der Klick-Handler).
        $insideMenu = $false
        foreach ($uiRow in @($script:UiRows.Values)) {
            try {
                if ($uiRow.Popup.IsOpen -and ($uiRow.Popup.IsMouseOver -or $uiRow.Menu.IsMouseOver)) {
                    $insideMenu = $true
                    break
                }
            } catch {}
        }
        if (-not $insideMenu) {
            foreach ($uiRow in @($script:UiRows.Values)) {
                try { if ($uiRow.Popup.IsOpen) { $uiRow.Popup.IsOpen = $false } } catch {}
            }
        }
    } catch {}
})

$window.Add_Loaded({
    # Version 7.2.6 (NEVER SILENT): Ab jetzt gilt das Fenster als sichtbar -
    # Write-StartupFailureDiagnose zeigt danach keine Startfehler-Meldung mehr.
    $script:WindowShown = $true
    try { Write-RuntimeLog 'Hauptfenster geladen (Loaded).' } catch {}
    # Version 7.2.5 (MAIN_OPACITY_RESCUE) / 7.2.6 (Reihenfolge): Kommt die
    # Einblend-Animation nicht an (Dispatcher-/Animation-Stoerung), blieb das
    # Fenster dauerhaft unsichtbar - es wirkte, als wuerde die Bridge gar nicht
    # starten. Der Einmal-Timer wird deshalb VOR der Animation gestartet und
    # erzwingt nach 700 ms die volle Deckkraft (Muster aus 6.0.5:
    # PREVIEW_OPACITY_RESCUE).
    try {
        $opacityRescue = [System.Windows.Threading.DispatcherTimer]::new()
        $opacityRescue.Interval = [TimeSpan]::FromMilliseconds(700)
        $opacityRescue.Add_Tick({
            param($s, $e)
            try { $s.Stop() } catch {}
            try {
                if ($window.Opacity -lt 1) {
                    $window.Opacity = 1
                    try { Write-RuntimeLog 'MAIN_OPACITY_RESCUE: Einblend-Animation kam nicht an - Hauptfenster hart eingeblendet.' } catch {}
                }
            } catch {}
        })
        $opacityRescue.Start()
    } catch {}
    # Version 7.3.0 (STARTGARANTIE): Der GRUNDWERT ist sichtbar (Opacity = 1).
    # Die Einblendung ist nur noch Verzierung mit FillBehavior=Stop - laeuft
    # sie nicht an oder bleibt sie haengen, wird der sichtbare Grundwert wieder
    # wirksam und das Fenster bleibt sichtbar (Lehre aus 6.0.5). Bis 7.2.9
    # stand hier "Opacity = 0"; die Sichtbarkeit hing damit allein an der
    # Animation und an einem Rettungstimer.
    $window.Opacity = 1
    try {
        $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [System.TimeSpan]::FromMilliseconds(380))
        $fade.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
        $window.BeginAnimation([System.Windows.Window]::OpacityProperty, $fade)
    } catch {
        # Version 7.2.6: Scheitert schon die Animation, sofort hart einblenden.
        try { $window.Opacity = 1 } catch {}
        try { Write-RuntimeLog 'MAIN_OPACITY_RESCUE: Einblend-Animation konnte nicht erzeugt werden - Hauptfenster sofort eingeblendet.' } catch {}
    }

    # Version 6.0: Die Glas-Schale wächst beim Öffnen sanft auf 100 %
    # (Liquid-Glass-Eröffnung). Reiner Transform-Tanz ohne Layout-Eingriff.
    try {
        $openEase = [System.Windows.Media.Animation.CubicEase]::new()
        $openEase.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
        $scaleX = [System.Windows.Media.Animation.DoubleAnimation]::new(0.965, 1, [System.TimeSpan]::FromMilliseconds(300))
        $scaleY = [System.Windows.Media.Animation.DoubleAnimation]::new(0.965, 1, [System.TimeSpan]::FromMilliseconds(300))
        $scaleX.EasingFunction = $openEase
        $scaleY.EasingFunction = $openEase
        $RootShell.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $scaleX)
        $RootShell.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $scaleY)
    } catch {}

    # Version 7.0.2: Static status dots avoid perpetual per-frame WPF redraws.
    $PulseDot.Opacity = 1
    $LiveDot.Opacity = 1

    foreach ($toast in $script:PendingToasts) {
        Show-Toast -Message $toast.Message -Kind $toast.Kind -Seconds $toast.Seconds
    }
    $script:PendingToasts.Clear()
})
Set-StartupStage 'Ereignisse verdrahtet (Fenstersteuerung + Loaded)'

# ----------------------------------------------------------------------------
# UPDATE-HINWEIS (Version 3.7)
# Bei 'update-erfolgreich' und 'erster-start' zeigt das Programm ZUERST
# dieses Fenster (was ist neu + OK-Button). Erst danach erscheinen das
# Hauptfenster und der Startbildschirm.
# ----------------------------------------------------------------------------
function Show-UpdateNotice {
    $isNewInstall = ($UpdateStatus -eq 'erster-start')
    $versionText = '7.4.1'
    $notesText = 'Keine Details verfuegbar.'
    try {
        if ($script:UpdateDetails) {
            if ($script:UpdateDetails.version) { $versionText = [string]$script:UpdateDetails.version }
            if ($script:UpdateDetails.notes) {
                # Version 7.2.8 (Punkt 4): notes ist eine LISTE. [string] darauf
                # machte aus 13 Eintraegen mit zusammen 8,5 KB EINE einzige
                # Zeile ohne jeden Umbruch - unlesbar im Hinweisfenster.
                # Jetzt steht jeder Eintrag als eigener Absatz da.
                $noticeNoteItems = New-Object System.Collections.Generic.List[string]
                foreach ($noticeNoteItem in $script:UpdateDetails.notes) {
                    $noticeNoteText = ([string]$noticeNoteItem).Trim()
                    if (-not [string]::IsNullOrWhiteSpace($noticeNoteText)) {
                        $noticeNoteItems.Add($noticeNoteText)
                    }
                }
                if ($noticeNoteItems.Count -gt 0) {
                    $noticeSeparator = [Environment]::NewLine + [Environment]::NewLine
                    $notesText = [string]::Join($noticeSeparator, $noticeNoteItems.ToArray())
                    if ($notesText.Length -gt 6000) { $notesText = $notesText.Substring(0, 6000) + ' …' }
                }
            }
        }
    } catch {}

    if ($isNewInstall) {
        $titleText = 'Willkommen bei Arena Roblox Bridge!'
        $subText = 'Das Programm wurde zum ersten Mal geladen (Version ' + $versionText + '). Alles Weitere passiert automatisch.'
    } else {
        $titleText = 'Update installiert!'
        $subText = 'Version ' + $versionText + ' ist jetzt aktiv. Das ist neu:'
    }

    $noticeXaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Arena Roblox Bridge - Update"
        Width="520" Height="440" MinWidth="520" MinHeight="440" MaxWidth="520" MaxHeight="440"
        ResizeMode="NoResize" WindowStyle="None" AllowsTransparency="True"
        Background="Transparent" WindowStartupLocation="CenterScreen" FontFamily="Segoe UI">
    <Border CornerRadius="22" BorderBrush="#33FFFFFF" BorderThickness="1" ClipToBounds="True">
        <Border.Background>
            <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                <GradientStop Color="#060A1A" Offset="0"/>
                <GradientStop Color="#0A1128" Offset="0.55"/>
                <GradientStop Color="#0C1533" Offset="1"/>
            </LinearGradientBrush>
        </Border.Background>
        <Border.Clip>
            <RectangleGeometry Rect="0,0,520,440" RadiusX="22" RadiusY="22"/>
        </Border.Clip>
        <Grid>
            <!-- Aurora-Lichter hinter dem Glas (Version 6.0 Liquid Glass) -->
            <Grid IsHitTestVisible="False">
                <Ellipse Width="420" Height="420" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="-150,-170,0,0">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#547B5CFF" Offset="0"/>
                            <GradientStop Color="#007B5CFF" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                    <Ellipse.Triggers>
                        <EventTrigger RoutedEvent="Loaded">
                            <BeginStoryboard>
                                <Storyboard>
                                    <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" From="0" To="38" Duration="0:0:33" AutoReverse="True" RepeatBehavior="Forever"/>
                                    <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="0" To="24" Duration="0:0:26" AutoReverse="True" RepeatBehavior="Forever"/>
                                </Storyboard>
                            </BeginStoryboard>
                        </EventTrigger>
                    </Ellipse.Triggers>
                </Ellipse>
                <Ellipse Width="360" Height="360" HorizontalAlignment="Right" VerticalAlignment="Bottom" Margin="0,0,-120,-140">
                    <Ellipse.Fill>
                        <RadialGradientBrush>
                            <GradientStop Color="#4000CFC0" Offset="0"/>
                            <GradientStop Color="#0000CFC0" Offset="1"/>
                        </RadialGradientBrush>
                    </Ellipse.Fill>
                    <Ellipse.RenderTransform>
                        <TranslateTransform X="0" Y="0"/>
                    </Ellipse.RenderTransform>
                    <Ellipse.Triggers>
                        <EventTrigger RoutedEvent="Loaded">
                            <BeginStoryboard>
                                <Storyboard>
                                    <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)" From="0" To="-30" Duration="0:0:29" AutoReverse="True" RepeatBehavior="Forever"/>
                                    <DoubleAnimation Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)" From="0" To="-20" Duration="0:0:35" AutoReverse="True" RepeatBehavior="Forever"/>
                                </Storyboard>
                            </BeginStoryboard>
                        </EventTrigger>
                    </Ellipse.Triggers>
                </Ellipse>
            </Grid>

            <Grid Margin="30,26">
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>
                <StackPanel Grid.Row="0" Orientation="Horizontal" Margin="0,0,0,16">
                    <Grid Width="44" Height="44" Margin="0,0,14,0">
                        <Border Width="44" Height="44" CornerRadius="13" BorderBrush="#4DFFFFFF" BorderThickness="1">
                            <Border.Background>
                                <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                                    <GradientStop Color="#8B6BFF" Offset="0"/>
                                    <GradientStop Color="#00D0BE" Offset="1"/>
                                </LinearGradientBrush>
                            </Border.Background>
                        </Border>
                        <Ellipse Width="8" Height="8" Fill="#FFFFFF" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="7,0,0,0"/>
                        <Ellipse Width="8" Height="8" Fill="#FFFFFF" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,7,0"/>
                        <Rectangle Height="3" Fill="#0A1128" Margin="15,0,15,0" RadiusX="1.5" RadiusY="1.5"/>
                    </Grid>
                    <StackPanel VerticalAlignment="Center">
                        <TextBlock Text="ARENA ROBLOX BRIDGE" Foreground="#6E7FA8" FontSize="10.5" FontWeight="Bold"/>
                        <TextBlock x:Name="NoticeTitle" Foreground="#F4F8FF" FontSize="19" FontWeight="Bold" Margin="0,3,0,0"/>
                    </StackPanel>
                </StackPanel>
                <TextBlock Grid.Row="1" x:Name="NoticeSub" Foreground="#9AA9CE" FontSize="13" TextWrapping="Wrap" Margin="0,0,0,16"/>
                <Border Grid.Row="2" CornerRadius="14" Background="#33101838" BorderBrush="#26FFFFFF" BorderThickness="1" Padding="16">
                    <ScrollViewer VerticalScrollBarVisibility="Auto">
                        <TextBlock x:Name="NoticeNotes" Foreground="#DCE6FF" FontSize="12.5" TextWrapping="Wrap" LineHeight="21"/>
                    </ScrollViewer>
                </Border>
                <Button Grid.Row="3" x:Name="NoticeOk" Content="OK" Width="150" Height="42"
                        HorizontalAlignment="Center" Margin="0,20,0,2" Cursor="Hand">
                    <Button.Template>
                        <ControlTemplate TargetType="Button">
                            <Grid>
                                <Border x:Name="bd" CornerRadius="14">
                                    <Border.Background>
                                        <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                                            <GradientStop Color="#F238D16C" Offset="0"/>
                                            <GradientStop Color="#E61FA34A" Offset="1"/>
                                        </LinearGradientBrush>
                                    </Border.Background>
                                    <Border.BorderBrush>#4DFFFFFF</Border.BorderBrush>
                                    <Border.BorderThickness>1</Border.BorderThickness>
                                    <Border.RenderTransformOrigin>0.5,0.5</Border.RenderTransformOrigin>
                                    <Border.RenderTransform>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                    </Border.RenderTransform>
                                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="14,0"/>
                                </Border>
                                <Border x:Name="sheen" CornerRadius="13,13,10,10" Margin="1,1,1,0" Height="14" VerticalAlignment="Top" IsHitTestVisible="False" Opacity="0.14">
                                    <Border.Background>
                                        <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                                            <GradientStop Color="#59FFFFFF" Offset="0"/>
                                            <GradientStop Color="#00FFFFFF" Offset="1"/>
                                        </LinearGradientBrush>
                                    </Border.Background>
                                </Border>
                            </Grid>
                            <ControlTemplate.Triggers>
                                <Trigger Property="IsMouseOver" Value="True">
                                    <Setter TargetName="bd" Property="Background" Value="#F24AE07E"/>
                                    <Setter TargetName="bd" Property="BorderBrush" Value="#7FFFFFFF"/>
                                    <Trigger.EnterActions>
                                        <BeginStoryboard>
                                            <Storyboard>
                                                <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.40" Duration="0:0:0.13">
                                                    <DoubleAnimation.EasingFunction>
                                                        <CubicEase EasingMode="EaseOut"/>
                                                    </DoubleAnimation.EasingFunction>
                                                </DoubleAnimation>
                                            </Storyboard>
                                        </BeginStoryboard>
                                    </Trigger.EnterActions>
                                    <Trigger.ExitActions>
                                        <BeginStoryboard>
                                            <Storyboard>
                                                <DoubleAnimation Storyboard.TargetName="sheen" Storyboard.TargetProperty="Opacity" To="0.14" Duration="0:0:0.20"/>
                                            </Storyboard>
                                        </BeginStoryboard>
                                    </Trigger.ExitActions>
                                </Trigger>
                                <Trigger Property="IsPressed" Value="True">
                                    <Trigger.EnterActions>
                                        <BeginStoryboard>
                                            <Storyboard>
                                                <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="0.96" Duration="0:0:0.08"/>
                                                <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="0.96" Duration="0:0:0.08"/>
                                            </Storyboard>
                                        </BeginStoryboard>
                                    </Trigger.EnterActions>
                                    <Trigger.ExitActions>
                                        <BeginStoryboard>
                                            <Storyboard>
                                                <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleX)" To="1" Duration="0:0:0.15"/>
                                                <DoubleAnimation Storyboard.TargetName="bd" Storyboard.TargetProperty="(UIElement.RenderTransform).(ScaleTransform.ScaleY)" To="1" Duration="0:0:0.15"/>
                                            </Storyboard>
                                        </BeginStoryboard>
                                    </Trigger.ExitActions>
                                </Trigger>
                            </ControlTemplate.Triggers>
                        </ControlTemplate>
                    </Button.Template>
                    <Button.Foreground>#FFFFFF</Button.Foreground>
                    <Button.FontWeight>SemiBold</Button.FontWeight>
                    <Button.FontSize>13.5</Button.FontSize>
                </Button>
            </Grid>
        </Grid>
    </Border>
</Window>
'@
    $noticeReader = [System.Xml.XmlNodeReader]::new([xml]$noticeXaml)
    $noticeWindow = [Windows.Markup.XamlReader]::Load($noticeReader)
    $script:UpdateNoticeWindow = $noticeWindow
    $script:UpdateNoticeAccepted = $false
    # Version 7.3.0 (STARTGARANTIE): Das Hinweisfenster gehoert ab jetzt dem
    # sichtbaren Hauptfenster. Damit kann es nicht mehr auf einem anderen
    # Bildschirm, hinter anderen Fenstern oder ausserhalb des Desktops landen -
    # es erscheint immer ueber der Bridge und bleibt bedienbar.
    try {
        if ($script:MainWindow) { $noticeWindow.Owner = $script:MainWindow }
        $noticeWindow.WindowStartupLocation = 'CenterOwner'
    } catch {}
    # ------------------------------------------------------------------------
    # Version 7.2.8 (Punkt 1 + 2): Dieses Fenster ist MODAL und laeuft VOR dem
    # Hauptfenster. Es startet mit Opacity = 0, wurde nur durch eine
    # Einblend-Animation in ContentRendered sichtbar, und Add_Closing brach
    # jedes Schliessen ab, solange OK nicht gedrueckt war. Kam die Animation
    # nicht an, stand ein UNSICHTBARES, unbedienbares, nicht schliessbares
    # Fenster im Weg - ShowDialog() blockierte fuer immer und das Hauptfenster
    # wurde nie erreicht ("startet gar nicht mehr", ohne jede Ausnahme).
    #   NOTICE_OPACITY_RESCUE: Rettungstimer startet VOR der Animation und
    #     erzwingt nach 700 ms Deckkraft 1 (Muster aus 6.0.5 / 7.2.5).
    #   NOTICE_WATCHDOG: Misst nach 2500 ms, ob das Fenster wirklich geladen
    #     und sichtbar ist; wenn nicht, wird es geschlossen und der Start
    #     laeuft weiter.
    # ------------------------------------------------------------------------
    try {
        # Version 7.3.0 (STARTGARANTIE): Grundwert ist sofort sichtbar (1);
        # die Einblendung ist nur noch Verzierung (FillBehavior=Stop). Ein
        # unsichtbares, aber modales Fenster kann damit nicht mehr entstehen.
        $noticeWindow.Opacity = 1
        $noticeRescue = [System.Windows.Threading.DispatcherTimer]::new()
        $noticeRescue.Interval = [TimeSpan]::FromMilliseconds(700)
        $noticeRescue.Add_Tick({
            param($s, $e)
            try { $s.Stop() } catch {}
            try {
                if ($script:UpdateNoticeWindow.Opacity -lt 1) {
                    $script:UpdateNoticeWindow.Opacity = 1
                    try { Write-RuntimeLog 'NOTICE_OPACITY_RESCUE: Einblend-Animation des Hinweisfensters kam nicht an - Fenster hart eingeblendet.' } catch {}
                }
            } catch {}
        })
        $noticeRescue.Start()
        $noticeWindow.Add_ContentRendered({
            param($s, $e)
            try {
                $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [TimeSpan]::FromMilliseconds(240))
                # Version 7.3.0: Nach dem Ablauf gilt wieder der sichtbare
                # Grundwert - eine haengende Animation kann nichts verdecken.
                $fade.FillBehavior = [System.Windows.Media.Animation.FillBehavior]::Stop
                $s.BeginAnimation([System.Windows.Window]::OpacityProperty, $fade)
            } catch { try { $s.Opacity = 1 } catch {} }
        })
    } catch {
        try { $noticeWindow.Opacity = 1 } catch {}
    }
    try {
        $noticeWatchdog = [System.Windows.Threading.DispatcherTimer]::new()
        $noticeWatchdog.Interval = [TimeSpan]::FromMilliseconds(2500)
        $noticeWatchdog.Add_Tick({
            param($s, $e)
            try { $s.Stop() } catch {}
            $noticeVisible = $false
            try {
                $noticeVisible = ([bool]$script:UpdateNoticeWindow.IsLoaded -and [bool]$script:UpdateNoticeWindow.IsVisible)
            } catch {}
            if (-not $noticeVisible) {
                try { Write-RuntimeLog 'NOTICE_WATCHDOG: Update-Hinweisfenster wurde nicht sichtbar - es wird geschlossen, damit das Programm starten kann.' } catch {}
                try { $script:UpdateNoticeAccepted = $true } catch {}
                try { $script:UpdateNoticeWindow.DialogResult = $true } catch {
                    try { $script:UpdateNoticeWindow.Close() } catch {}
                }
            }
        })
        $noticeWatchdog.Start()
    } catch {}
    $noticeTitleEl = $noticeWindow.FindName('NoticeTitle')
    $noticeSubEl = $noticeWindow.FindName('NoticeSub')
    $noticeNotesEl = $noticeWindow.FindName('NoticeNotes')
    $noticeOkEl = $noticeWindow.FindName('NoticeOk')
    # Version 7.2.8 (Punkt 4): FindName darf den Start nicht kosten - fehlt ein
    # Element, wird nur dieser Text uebersprungen, das Fenster bleibt bedienbar.
    if ($noticeTitleEl) { $noticeTitleEl.Text = $titleText }
    if ($noticeSubEl) { $noticeSubEl.Text = $subText + ' Das Programm startet erst, wenn du OK drückst.' }
    if ($noticeNotesEl) { $noticeNotesEl.Text = $notesText }
    $noticeWindow.Add_Closing({
        param($sender, $eventArgs)
        if (-not $script:UpdateNoticeAccepted) { $eventArgs.Cancel = $true }
    })
    if ($noticeOkEl) {
        $noticeOkEl.Add_Click({
            param($s, $e)
            $script:UpdateNoticeAccepted = $true
            try { $script:UpdateNoticeWindow.DialogResult = $true } catch {
                try { $script:UpdateNoticeWindow.Close() } catch {}
            }
        })
    }
    # Version 7.2.8 (Punkt 2): Notausgang. Ein Fenster, das den Start blockiert
    # und sich nicht schliessen laesst, darf es nicht geben.
    $noticeWindow.Add_PreviewKeyDown({
        param($s, $e)
        try {
            if ($e.Key -eq [System.Windows.Input.Key]::Escape) {
                $script:UpdateNoticeAccepted = $true
                try { Write-RuntimeLog 'Update-Hinweisfenster mit Esc geschlossen.' } catch {}
                try { $script:UpdateNoticeWindow.DialogResult = $true } catch {
                    try { $script:UpdateNoticeWindow.Close() } catch {}
                }
            }
        } catch {}
    })
    if ($noticeOkEl) { try { $noticeOkEl.Focus() | Out-Null } catch {} }
    try {
        [void]$noticeWindow.ShowDialog()
    } catch {
        try { Write-RuntimeLog ('Update-Hinweisfenster konnte nicht angezeigt werden: ' + $_.Exception.Message) } catch {}
    }
    $script:UpdateNoticeAccepted = $false
    $script:UpdateNoticeWindow = $null
}


# ----------------------------------------------------------------------------
# EINSTELLUNGSFENSTER (Version 3.8)
# Die Einstellungen sind ein eigenes, deutlich groesseres Fenster geworden
# (vorher: kleines 300-px-Panel). Alle an/aus-Einstellungen sind jetzt echte
# Schalter mit ROT (aus) und GRUEN (an) statt Haekchen-Kaestchen, und jeder
# Schalter wird sofort dauerhaft in settings.json gespeichert.
# ----------------------------------------------------------------------------
function ConvertTo-XmlSafeText {
    param([string]$Text)
    if ($null -eq $Text) { return '' }
    return ([string]$Text).Replace('&', '&amp;').Replace('<', '&lt;').Replace('>', '&gt;')
}

function Get-NotifyRegistryValue {
    # Liefert $null, wenn der Schluessel oder der Wert nicht existiert -
    # "nicht gesetzt" ist etwas anderes als "aus".
    param([string]$Path, [string]$Name)
    try {
        if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Name)) { return $null }
        if (-not (Test-Path -LiteralPath $Path)) { return $null }
        $item = Get-ItemProperty -LiteralPath $Path -ErrorAction Stop
        if ($null -eq $item) { return $null }
        if (-not ($item.PSObject.Properties.Name -contains $Name)) { return $null }
        return $item.$Name
    } catch { return $null }
}

function Register-NotifyAumid {
    # Version 7.2.0 (D4): Windows zeigt einen Toast nur fuer eine REGISTRIERTE
    # App-Id. Registriert werden (a) HKCU\Software\Classes\AppUserModelId\<AUMID>
    # mit Anzeigename und (b) eine Startmenue-Verknuepfung, die genau diese
    # App-Id traegt. Beides liegt im Benutzerprofil, nichts im System, und
    # beides ist idempotent. Ohne diesen Schritt verwirft Windows die Meldung
    # still - Show() kehrt trotzdem ohne Ausnahme zurueck.
    param([switch]$Force)
    $aumid = 'Arena.ArenaRobloxBridge'
    $result = [pscustomobject]@{
        aumid = $aumid
        registered = $false
        registryKey = $false
        shortcutPath = ''
        shortcutExists = $false
        verdict = 'NOT_REGISTERED'
        reason = ''
        checkedAt = (Get-Date).ToString('u')
    }
    try {
        if ($null -ne $script:NotifyAumidState -and -not $Force) {
            if ([bool]$script:NotifyAumidState.registered) { return $script:NotifyAumidState }
        }
        $startMenu = Join-Path $env:APPDATA 'Microsoft\Windows\Start Menu\Programs'
        $shortcut = Join-Path $startMenu 'Arena Roblox Bridge.lnk'
        $result.shortcutPath = $shortcut
        $result.shortcutExists = (Test-Path -LiteralPath $shortcut)

        # (a) Registrierungsdatenbank: Anzeigename der App fuer die Meldung.
        $keyPath = 'HKCU:\Software\Classes\AppUserModelId\' + $aumid
        try {
            if (-not (Test-Path -LiteralPath $keyPath)) { New-Item -Path $keyPath -Force | Out-Null }
            Set-ItemProperty -LiteralPath $keyPath -Name 'DisplayName' -Value 'Arena Roblox Bridge' -Type String -ErrorAction Stop
            Set-ItemProperty -LiteralPath $keyPath -Name 'ShowInSettings' -Value 1 -Type DWord -ErrorAction Stop
            $result.registryKey = $true
        } catch {
            $result.reason = 'Registry: ' + $_.Exception.Message
        }

        # (b) Startmenue-Verknuepfung mit System.AppUserModel.ID.
        if ($Force -or -not $result.shortcutExists) {
            if (-not ('Arena.NotifyLink' -as [type])) {
                $result.verdict = 'HELPER_UNAVAILABLE'
                $result.reason = 'Arena.NotifyLink konnte nicht kompiliert werden (siehe runtime.log) - die Verknuepfung fehlt, Windows kann die Meldung verwerfen.'
                $script:NotifyAumidState = $result
                return $result
            }
            $target = ''
            try { $target = [string][System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch {}
            if ([string]::IsNullOrWhiteSpace($target)) { $target = (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') }
            $scriptPath = ''
            try { $scriptPath = [string]$script:ScriptPath } catch {}
            $arguments = '-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden'
            if (-not [string]::IsNullOrWhiteSpace($scriptPath)) { $arguments = $arguments + ' -File "' + $scriptPath + '"' }
            $workingDir = ''
            try { if (-not [string]::IsNullOrWhiteSpace($scriptPath)) { $workingDir = [string](Split-Path -Parent $scriptPath) } } catch {}
            $registerVerdict = ''
            try {
                $registerVerdict = [string][Arena.NotifyLink]::Register($shortcut, $target, $arguments, $workingDir, $aumid, 'Arena Roblox Bridge', '', 0)
            } catch {
                $registerVerdict = 'failed: ' + $_.Exception.Message
            }
            $result.shortcutExists = (Test-Path -LiteralPath $shortcut)
            if ($registerVerdict -eq 'ok' -and $result.shortcutExists) {
                $result.registered = $true
                $result.verdict = 'REGISTERED'
                $result.reason = 'Startmenue-Verknuepfung mit App-Id angelegt.'
            } else {
                $result.verdict = 'SHORTCUT_FAILED'
                $result.reason = ('Verknuepfung: ' + $registerVerdict)
            }
        } elseif ($result.shortcutExists -and $result.registryKey) {
            $result.registered = $true
            $result.verdict = 'ALREADY_REGISTERED'
            $result.reason = 'Verknuepfung und App-Id waren bereits vorhanden.'
        }
    } catch {
        $result.verdict = 'FAILED'
        $result.reason = $_.Exception.Message
    }
    $script:NotifyAumidState = $result
    try { Write-FlowTrace 'NOTIFY' 'aumid' 'REGISTER' @{ verdict = $result.verdict; registryKey = $result.registryKey; shortcut = $result.shortcutExists; reason = $result.reason } } catch {}
    return $result
}

function Test-NotifyPlatform {
    # Version 7.2.0 (D4): MESSEN statt behaupten. Bis hierher galt
    # "Toast.Show() ohne Ausnahme = angezeigt". Windows unterdrueckt Toasts
    # aber still. Diese Funktion liefert das Urteil UND den Grund.
    param()
    $platform = [pscustomobject]@{
        checkedAt = (Get-Date).ToString('u')
        settingEnabled = $false
        globalToastsEnabled = $null
        appNotificationsEnabled = $null
        appUserModelId = 'Arena.ArenaRobloxBridge'
        appUserModelIdRegistered = $false
        startMenuShortcut = $false
        focusAssist = 'unknown'
        foreground = 'unknown'
        windowsBuild = 0
        helperAvailable = $false
        verdict = 'UNKNOWN'
        reason = ''
    }
    try { $platform.settingEnabled = [bool]$script:Shared.BridgeSettings.notifyOnDone } catch {}
    try { $platform.windowsBuild = [int][Environment]::OSVersion.Version.Build } catch {}
    try { $platform.helperAvailable = [bool]('Arena.NotifyLink' -as [type]) } catch {}
    $settingsRoot = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings'
    $globalToasts = Get-NotifyRegistryValue $settingsRoot 'NOC_GLOBAL_SETTING_TOASTS_ENABLED'
    if ($null -ne $globalToasts) { try { $platform.globalToastsEnabled = ([int]$globalToasts -ne 0) } catch {} }
    $appEnabled = Get-NotifyRegistryValue ($settingsRoot + '\' + $platform.appUserModelId) 'ENABLED'
    if ($null -ne $appEnabled) { try { $platform.appNotificationsEnabled = ([int]$appEnabled -ne 0) } catch {} }
    # App-Id des PowerShell-Hosts (Fallback-Pfad der Meldung) ebenfalls pruefen.
    $legacyId = '{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\WindowsPowerShell\v1.0\powershell.exe'
    if ($null -eq $appEnabled) {
        $legacyEnabled = Get-NotifyRegistryValue ($settingsRoot + '\' + $legacyId) 'ENABLED'
        if ($null -ne $legacyEnabled) { try { $platform.appNotificationsEnabled = ([int]$legacyEnabled -ne 0) } catch {} }
    }
    try {
        if ($null -ne $script:NotifyAumidState) {
            $platform.appUserModelIdRegistered = [bool]$script:NotifyAumidState.registered
            $platform.startMenuShortcut = [bool]$script:NotifyAumidState.shortcutExists
        }
    } catch {}
    # Fokus-Assistent / "Benachrichtigungen nicht stoeren".
    $profileValue = Get-NotifyRegistryValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\QuietHours' 'Profile'
    if ($null -ne $profileValue -and -not [string]::IsNullOrWhiteSpace([string]$profileValue)) {
        $platform.focusAssist = ([string]$profileValue).ToLowerInvariant()
    }
    # Vollbild-App im Vordergrund: Windows zeigt dann von sich aus keine Toasts.
    if ($platform.helperAvailable) {
        try { $platform.foreground = [string][Arena.NotifyLink]::ForegroundFullscreen() } catch { $platform.foreground = 'unknown' }
    }
    # Urteil - in der Reihenfolge, in der Windows selbst unterdrueckt.
    if (-not $platform.settingEnabled) {
        $platform.verdict = 'SUPPRESSED_APP_DISABLED'
        $platform.reason = 'Der Schalter "Benachrichtigung, wenn Arena fertig ist" ist AUS.'
    } elseif ($platform.globalToastsEnabled -eq $false) {
        $platform.verdict = 'SUPPRESSED_WINDOWS_DISABLED'
        $platform.reason = 'Benachrichtigungen sind in Windows global ausgeschaltet (NOC_GLOBAL_SETTING_TOASTS_ENABLED = 0).'
    } elseif ($platform.appNotificationsEnabled -eq $false) {
        $platform.verdict = 'SUPPRESSED_APP_NOTIFICATIONS_OFF'
        $platform.reason = 'Benachrichtigungen sind fuer diese App in Windows ausgeschaltet (Einstellungen > System > Benachrichtigungen).'
    } elseif ($platform.focusAssist -eq 'priorityonly' -or $platform.focusAssist -eq 'alarmsonly') {
        $platform.verdict = 'SUPPRESSED_QUIET_HOURS'
        $platform.reason = ('Der Fokus-Assistent steht auf "' + $platform.focusAssist + '" - Windows legt die Meldung ins Info-Center statt sie zu zeigen.')
    } elseif ($platform.foreground -eq 'fullscreen') {
        $platform.verdict = 'SUPPRESSED_FULLSCREEN_RULE'
        $platform.reason = 'Eine Vollbild-Anwendung hat den Vordergrund - Windows unterdrueckt Toasts dann von sich aus.'
    } elseif (-not $platform.appUserModelIdRegistered -and -not $platform.startMenuShortcut) {
        $platform.verdict = 'AUMID_UNREGISTERED'
        $platform.reason = 'Die App-Id ist nicht registriert (keine Startmenue-Verknuepfung) - Windows kann die Meldung verwerfen, ohne dass Show() eine Ausnahme wirft.'
    } else {
        $platform.verdict = 'READY'
        $platform.reason = 'Keine Unterdrueckung messbar: Windows darf die Meldung zeigen.'
    }
    return $platform
}

function Get-NotifyPlatformLine {
    param($Platform)
    if ($null -eq $Platform) { return 'Plattform-Check nicht verfuegbar' }
    return ([string]$Platform.verdict + ' - ' + [string]$Platform.reason)
}

function Update-NotifyPlatformCache {
    # Haelt das Urteil fuer den HTTP-Handler bereit: Der Server-Runspace kann
    # keine UI-Funktionen aufrufen, liest aber genau dieses JSON, damit
    # report_done ehrlich antworten kann (NOTIFICATION_UNVERIFIED).
    param([switch]$Force)
    try {
        $now = Get-Date
        if (-not $Force -and $null -ne $script:NotifyPlatformCacheAt -and ($now - $script:NotifyPlatformCacheAt).TotalSeconds -lt 30) { return $script:NotifyPlatformCache }
        $script:NotifyPlatformCacheAt = $now
        $platform = Test-NotifyPlatform
        $script:NotifyPlatformCache = $platform
        $json = ''
        try { $json = ($platform | ConvertTo-Json -Depth 6 -Compress) } catch {}
        try { $script:Shared.NotifyPlatformJson = [string]$json } catch {}
        try { Set-UiChannelText 'NotifyLastVerdict' ([string]$platform.verdict) } catch {}
        try { Set-UiChannelText 'NotifyLastReason' ([string]$platform.reason) } catch {}
        return $platform
    } catch { return $null }
}

function Add-NotifyRecord {
    # Letzten Meldungen der Oberflaeche (maximal 20) - fuer notify.sweep und
    # notify-diagnose.txt.
    param($Record)
    try {
        if ($null -eq $Record) { return }
        if ($null -eq $script:NotifyRecords) { $script:NotifyRecords = New-Object System.Collections.Generic.List[object] }
        $script:NotifyRecords.Add($Record)
        while ($script:NotifyRecords.Count -gt 20) { $script:NotifyRecords.RemoveAt(0) }
        $json = ''
        try { $json = ($Record | ConvertTo-Json -Depth 6 -Compress) } catch {}
        try { $script:Shared.NotifyLastJson = [string]$json } catch {}
    } catch {}
}

function Invoke-NotifySweep {
    # Version 7.2.0: Nachsicht statt Blindheit. Windows bietet keine API, die
    # das Anzeigen eines Toasts bestaetigt - also wird NACH dem Aufruf erneut
    # gemessen und ehrlich verbucht: SHOWN (keine Unterdrueckung messbar) oder
    # SHOWN_UNVERIFIED (Grund steht dabei). Genau dieser Unterschied fehlte
    # 7.1.x, wo "delivered = true" blind zurueckgegeben wurde.
    param()
    try {
        if ($null -eq $script:NotifyRecords -or $script:NotifyRecords.Count -eq 0) { return }
        $nowSeconds = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
        foreach ($record in $script:NotifyRecords.ToArray()) {
            try {
                if ([bool]$record.swept) { continue }
                $shownAt = [int64]$record.shownAt
                if ($shownAt -le 0) { continue }
                if (($nowSeconds - $shownAt) -lt 4) { continue }
                $platform = Update-NotifyPlatformCache -Force
                $verdict = 'SHOWN_UNVERIFIED'
                $reason = 'Windows bestaetigt das Anzeigen eines Toasts nicht; nach dem Aufruf war keine Unterdrueckung messbar.'
                if ($null -ne $platform) {
                    if ([string]$platform.verdict -eq 'READY') {
                        $verdict = 'SHOWN'
                        $reason = [string]$platform.reason
                    } else {
                        $verdict = 'SHOWN_UNVERIFIED'
                        $reason = ('Nach dem Aufruf gemessen: ' + (Get-NotifyPlatformLine $platform))
                    }
                }
                Set-UiMessageField $record 'swept' $true
                Set-UiMessageField $record 'sweptAt' $nowSeconds
                Set-UiMessageField $record 'verdict' $verdict
                Set-UiMessageField $record 'sweepReason' $reason
                if ($verdict -eq 'SHOWN') { Add-UiChannelCount 'NotifyShown' 1 } else { Add-UiChannelCount 'NotifyUnverified' 1 }
                Set-UiChannelText 'NotifyLastVerdict' $verdict
                Set-UiChannelText 'NotifyLastReason' $reason
                Write-FlowTrace 'NOTIFY' ([string]$record.flowId) 'SWEEP' @{ verdict = $verdict; ageSeconds = ($nowSeconds - $shownAt); method = ([string]$record.method); reason = $reason }
                # Nicht erneut einreihen (das wuerde duplizieren) - nur die
                # gemeinsame Ablage fuer Diagnose/HTTP aktualisieren.
                try { $script:Shared.NotifyLastJson = [string]($record | ConvertTo-Json -Depth 6 -Compress) } catch {}
            } catch {}
        }
    } catch {}
}

function Clear-NotifyQueue {
    # Version 7.1.3: wartende Fertig-Meldungen verwerfen. Das Ausschalten des
    # Schalters "Benachrichtigung, wenn Arena fertig ist" muss SOFORT wirken,
    # nicht erst nach dem naechsten Anzeige-Takt.
    param()
    $drained = 0
    try {
        while ($true) {
            $item = $null
            if (-not $script:Shared.NotifyQueue.TryDequeue([ref]$item)) { break }
            $drained = $drained + 1
        }
    } catch {}
    if ($drained -gt 0) { Write-RuntimeLog "Fertig-Benachrichtigung aus: $drained wartende Meldung(en) verworfen." }
    return $drained
}

function Show-ArenaDoneNotification {
    # Version 3.8: Windows-Benachrichtigung "Arena ist fertig" - ausschliesslich
    # fuer die report_done-Meldung der KI (der Nutzer hat diese Benachrichtigung
    # dafuer explizit in den Einstellungen aktiviert; sie ist standardmaessig
    # AUS). Die alten stummen Toast-Stummel bleiben unangetastet.
    # Version 7.1.3: Der Schalter "Benachrichtigung, wenn Arena fertig ist"
    # steht direkt unter "Fortschritt in der Place-Liste anzeigen" und wird
    # hier ZUSAETZLICH unmittelbar vor dem Anzeigen geprueft - ein Ausschalten
    # wirkt damit auch fuer Meldungen, die schon in der Warteschlange lagen.
    # Version 7.2.0 (D4): Es wird GEMESSEN, nicht behauptet. Vor dem Aufruf
    # laeuft Test-NotifyPlatform, der Aufruf selbst bekommt eine Station, und
    # notify.sweep misst danach erneut. Ein Toast, den Windows still verworfen
    # hat, steht jetzt als SHOWN_UNVERIFIED mit Grund im Protokoll und in
    # notify-diagnose.txt - statt "Arena-Fertig-Meldung angezeigt".
    param([string]$Place, [string]$Title, [string]$Message, [string]$FlowId = '', [int64]$QueuedAt = 0)
    $flowId = [string]$FlowId
    if ([string]::IsNullOrWhiteSpace($flowId)) { $flowId = 'n-' + [string]([DateTimeOffset]::UtcNow.ToUnixTimeSeconds()) }
    $record = [pscustomobject]@{
        flowId     = $flowId
        place      = [string]$Place
        title      = [string]$Title
        message    = [string]$Message
        queuedAt   = $QueuedAt
        shownAt    = [int64]0
        method     = ''
        verdict    = 'PENDING'
        reason     = ''
        swept      = $false
        seenByUser = ''
    }
    $allowed = $false
    try { $allowed = [bool]$script:Shared.BridgeSettings.notifyOnDone } catch {}
    if (-not $allowed) {
        Set-UiMessageField $record 'verdict' 'SUPPRESSED_APP_DISABLED'
        Set-UiMessageField $record 'reason' 'Der Schalter "Benachrichtigung, wenn Arena fertig ist" ist aus.'
        Add-UiChannelCount 'NotifySuppressed' 1
        Set-UiChannelText 'NotifyLastVerdict' 'SUPPRESSED_APP_DISABLED'
        Set-UiChannelText 'NotifyLastReason' ([string]$record.reason)
        Write-FlowTrace 'NOTIFY' $flowId 'SUPPRESSED' @{ reason = 'setting_off'; place = ([string]$Place) }
        Add-NotifyRecord $record
        Write-RuntimeLog 'Fertig-Meldung verworfen: der Schalter "Benachrichtigung, wenn Arena fertig ist" ist aus.'
        return $record
    }
    # Plattform VOR dem Aufruf messen: das Urteil gehoert zur Meldung.
    $platform = Update-NotifyPlatformCache -Force
    if ($null -ne $platform) {
        Write-FlowTrace 'NOTIFY' $flowId 'PLATFORM' @{ verdict = ([string]$platform.verdict); globalToasts = $(if ($null -eq $platform.globalToastsEnabled) { 'unknown' } else { [string]$platform.globalToastsEnabled }); appEnabled = $(if ($null -eq $platform.appNotificationsEnabled) { 'unknown' } else { [string]$platform.appNotificationsEnabled }); focusAssist = ([string]$platform.focusAssist); foreground = ([string]$platform.foreground); aumidRegistered = ([string]$platform.appUserModelIdRegistered); build = ([string]$platform.windowsBuild) }
    }
    # Windows 11 ToastGeneric hat laut Microsoft kein festes Zeichenlimit je
    # Textfeld (Darstellung wird nach Breite/Skalierung abgeschnitten; Gesamt-XML
    # max. 5 KB). Fuer verlaesslich voll sichtbare Meldungen erzwingt die Bridge
    # den konservativen Windows-11-Anzeigebudget-Vertrag: 70 Zeichen Titel,
    # 140 Zeichen Inhalt. Dieselben Grenzen stehen in der Arena-Dokumentation.
    $title = $Title
    if ([string]::IsNullOrWhiteSpace($title)) { $title = '✅ Arena ist fertig!' }
    if ($title.Length -gt 70) { $title = $title.Substring(0, 69).TrimEnd() + '…' }
    $text = $Message
    if ($text.Length -gt 140) { $text = $text.Substring(0, 139).TrimEnd() + '…' }
    if ([string]::IsNullOrWhiteSpace($text)) { $text = 'Ich bin fertig.' }
    $shown = $false
    $method = ''
    # 1) Moderner Windows-Toast (WinRT) - mit der REGISTRIERTEN App-Id, damit
    #    Windows die Meldung nicht still verwirft und sie "Arena Roblox Bridge"
    #    heisst statt "Windows PowerShell".
    try {
        [void][Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime]
        [void][Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom, ContentType = WindowsRuntime]
        $appId = '{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\WindowsPowerShell\v1.0\powershell.exe'
        try {
            if ($null -ne $script:NotifyAumidState -and ([bool]$script:NotifyAumidState.registered -or [bool]$script:NotifyAumidState.shortcutExists)) {
                $appId = [string]$script:NotifyAumidState.aumid
            }
        } catch {}
        $toastXml = '<toast duration="long"><visual><binding template="ToastGeneric"><text>' + (ConvertTo-XmlSafeText $title) + '</text><text>' + (ConvertTo-XmlSafeText $text) + '</text></binding></visual><audio src="ms-winsoundevent:Notification.Default"/></toast>'
        $xmlDoc = New-Object Windows.Data.Xml.Dom.XmlDocument
        $xmlDoc.LoadXml($toastXml)
        $toast = New-Object Windows.UI.Notifications.ToastNotification $xmlDoc
        [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier($appId).Show($toast)
        $shown = $true
        $method = 'winrt:' + $appId
    } catch {
        Write-RuntimeLog "Windows-Toast fehlgeschlagen: $($_.Exception.Message)"
        Write-FlowTrace 'NOTIFY' $flowId 'CALL_FAILED' @{ channel = 'winrt'; error = $_.Exception.Message }
    }
    # 2) Fallback: klassischer Balloon-Hinweis ueber ein Tray-Symbol.
    if (-not $shown) {
        try {
            Add-Type -AssemblyName System.Windows.Forms
            $ni = New-Object System.Windows.Forms.NotifyIcon
            $ni.Icon = [System.Drawing.SystemIcons]::Information
            $ni.Visible = $true
            $ni.BalloonTipTitle = $title
            $ni.BalloonTipText = $text
            $ni.ShowBalloonTip(12000)
            if (-not $script:NotifyIcons) { $script:NotifyIcons = New-Object System.Collections.Generic.List[object] }
            $script:NotifyIcons.Add($ni)
            $niTimer = [System.Windows.Threading.DispatcherTimer]::new()
            $niTimer.Interval = [TimeSpan]::FromSeconds(25)
            $niTimer.Tag = $ni
            $niTimer.Add_Tick({
                param($s, $e)
                $s.Stop()
                try { $s.Tag.Visible = $false; $s.Tag.Dispose() } catch {}
            })
            $niTimer.Start()
            $shown = $true
            $method = 'balloon'
        } catch {
            Write-RuntimeLog "Balloon-Hinweis fehlgeschlagen: $($_.Exception.Message)"
            Write-FlowTrace 'NOTIFY' $flowId 'CALL_FAILED' @{ channel = 'balloon'; error = $_.Exception.Message }
        }
    }
    # 3) Letzter Fallback: Hauptfenster holen und aktivieren.
    if (-not $shown) {
        try {
            $window.Activate()
            [void]$window.Focus()
            $method = 'window'
        } catch {}
    }
    Set-UiMessageField $record 'shownAt' ([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())
    Set-UiMessageField $record 'method' $method
    if ($shown) {
        Set-UiMessageField $record 'verdict' 'CALL_RETURNED'
        Set-UiMessageField $record 'reason' 'Show() kam ohne Ausnahme zurueck - ob Windows die Meldung wirklich gezeichnet hat, misst notify.sweep.'
        Write-FlowTrace 'NOTIFY' $flowId 'CALL' @{ channel = $method; verdict = 'CALL_RETURNED'; platform = $(if ($null -ne $platform) { [string]$platform.verdict } else { '-' }) }
    } else {
        Set-UiMessageField $record 'verdict' 'CALL_FAILED'
        Set-UiMessageField $record 'reason' 'Kein Kanal (WinRT, Balloon, Fenster) konnte aufgerufen werden.'
        Add-UiChannelCount 'NotifyFailed' 1
        Set-UiChannelText 'NotifyLastVerdict' 'CALL_FAILED'
        Write-FlowTrace 'NOTIFY' $flowId 'CALL_FAILED' @{ channel = 'none' }
    }
    Add-NotifyRecord $record
    Write-RuntimeLog ("Arena-Fertig-Meldung angezeigt: " + $text + " (Kanal: " + $(if ($method) { $method } else { 'keiner' }) + ", Urteil: " + [string]$record.verdict + ", wird von notify.sweep nachgemessen)")
    return $record
}

function Get-NotifyDiagnoseLines {
    # Letzte Meldungen mit Kanal und Urteil - fuer notify-diagnose.txt.
    param()
    $lines = New-Object System.Collections.Generic.List[string]
    try {
        if ($null -eq $script:NotifyRecords -or $script:NotifyRecords.Count -eq 0) {
            $lines.Add('  (noch keine Fertig-Meldung in dieser Laufzeit)')
            return ,$lines
        }
        $records = $script:NotifyRecords.ToArray()
        for ($i = $records.Length - 1; $i -ge 0; $i--) {
            $record = $records[$i]
            $seen = ''
            try { $seen = [string]$record.seenByUser } catch {}
            $lines.Add(('  {0}  Place="{1}"  Kanal={2}  Urteil={3}{4}' -f [string]$record.flowId, [string]$record.place, $(if ([string]$record.method) { [string]$record.method } else { '-' }), [string]$record.verdict, $(if ($seen) { '  vom Nutzer gesehen: ' + $seen } else { '' })))
            $reason = ''
            try { $reason = [string]$record.sweepReason } catch {}
            if ([string]::IsNullOrWhiteSpace($reason)) { try { $reason = [string]$record.reason } catch {} }
            if (-not [string]::IsNullOrWhiteSpace($reason)) { $lines.Add(('      ' + $reason)) }
        }
    } catch {}
    return ,$lines
}

function Set-ArenaSwitchVisualState {
    param($Switch)
    if ($null -eq $Switch) { return }
    try {
        $Switch.ApplyTemplate() | Out-Null
        $thumb = $Switch.Template.FindName('thumb', $Switch)
        if ($null -ne $thumb -and $thumb.RenderTransform -is [System.Windows.Media.TranslateTransform]) {
            $thumb.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $null)
            $thumb.RenderTransform.X = if ([bool]$Switch.IsChecked) { 22.0 } else { 0.0 }
        }
    } catch {}
}

