                        <Button.Template>
                            <ControlTemplate TargetType="Button">
                                <Border x:Name="bd" CornerRadius="18" Background="{TemplateBinding Background}"
                                        BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}"
                                        RenderTransformOrigin="0.5,0.5">
                                    <Border.RenderTransform>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                    </Border.RenderTransform>
                                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                </Border>
                                <ControlTemplate.Triggers>
                                    <Trigger Property="IsMouseOver" Value="True">
                                        <Setter TargetName="bd" Property="Background" Value="#F2FF7A8C"/>
                                        <Setter TargetName="bd" Property="BorderBrush" Value="#7FFFFFFF"/>
                                    </Trigger>
                                    <Trigger Property="IsPressed" Value="True">
                                        <Setter TargetName="bd" Property="Background" Value="#D9C0103A"/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Button.Template>
                    </Button>
                </Grid>

                <!-- Inhalt -->
                <ScrollViewer Grid.Row="1" Margin="0,16,0,0" VerticalScrollBarVisibility="Auto">
                    <StackPanel Margin="0,0,8,0">

                        <TextBlock Text="PROGRAMM" Foreground="{StaticResource SwTextMuted}" FontSize="10.5" FontWeight="Bold" Margin="2,2,0,8"/>
                        <Border Background="{StaticResource SwCardBg}" BorderBrush="#2EFFFFFF" BorderThickness="1" CornerRadius="14" Padding="16,12">
                            <StackPanel>
                                <CheckBox x:Name="StartupSwitch" Style="{StaticResource ArenaSwitch}" Content="Beim PC-Start automatisch öffnen"/>
                            </StackPanel>
                        </Border>

                        <TextBlock Text="EDITOR" Foreground="{StaticResource SwTextMuted}" FontSize="10.5" FontWeight="Bold" Margin="2,20,0,8"/>
                        <Border Background="{StaticResource SwCardBg}" BorderBrush="#2EFFFFFF" BorderThickness="1" CornerRadius="14" Padding="16,12">
                            <StackPanel>
                                <CheckBox x:Name="EditorIconsSwitch" Style="{StaticResource ArenaSwitch}" Content="Live-Vorschau-Icons im Editor anzeigen"/>
                                <TextBlock Text="Aus spart Leistung: Fensteraufnahmen werden vollständig gestoppt." Foreground="{StaticResource SwTextFaint}" FontSize="10.5" Margin="0,7,0,0"/>
                            </StackPanel>
                        </Border>

                        <TextBlock Text="PLACE-LISTE" Foreground="{StaticResource SwTextMuted}" FontSize="10.5" FontWeight="Bold" Margin="2,20,0,8"/>
                        <Border Background="{StaticResource SwCardBg}" BorderBrush="#2EFFFFFF" BorderThickness="1" CornerRadius="14" Padding="16,12">
                            <StackPanel>
                                <CheckBox x:Name="ProgressSwitch" Style="{StaticResource ArenaSwitch}" Content="Fortschritt in der Place-Liste anzeigen"/>
                                <!-- Version 7.1.3: Fertig-Benachrichtigung als eigener
                                     Schalter direkt unter der Fortschrittsanzeige. -->
                                <CheckBox x:Name="DoneNotifySwitch" Style="{StaticResource ArenaSwitch}" Content="Benachrichtigung, wenn Arena fertig ist" Margin="0,14,0,0"/>
                                <TextBlock Text="Zeigt am Ende der Arbeit die Windows-Meldung von Arena (Titel und kurzer Text). Standard: aus." Foreground="{StaticResource SwTextFaint}" FontSize="10.5" TextWrapping="Wrap" Margin="0,7,0,0"/>
                            </StackPanel>
                        </Border>

                        <TextBlock Text="UPDATES" Foreground="{StaticResource SwTextMuted}" FontSize="10.5" FontWeight="Bold" Margin="2,20,0,8"/>
                        <TextBlock x:Name="UpdateInfoText" Foreground="{StaticResource SwTextFaint}" FontSize="11" TextWrapping="Wrap"/>

                        <Border Height="1" Background="{StaticResource SwLine}" Margin="0,18,0,12"/>
                        <TextBlock Text="Arena Roblox Bridge - Version 7.4.1" Foreground="{StaticResource SwTextFaint}" FontSize="11"/>

                    </StackPanel>
                </ScrollViewer>
            </Grid>
        </Grid>
    </Border>
</Window>
'@
    $settingsReader = [System.Xml.XmlNodeReader]::new([xml]$settingsXaml)
    $settingsWindow = [Windows.Markup.XamlReader]::Load($settingsReader)

    try { $settingsWindow.Owner = $window } catch {}
    # Version 6.0: Das Einstellungsfenster blendet weich ein (Liquid Glass).
    try {
        $settingsWindow.Opacity = 0
        $settingsWindow.Add_ContentRendered({
            param($s, $e)
            try {
                $fade = [System.Windows.Media.Animation.DoubleAnimation]::new(0, 1, [TimeSpan]::FromMilliseconds(220))
                $s.BeginAnimation([System.Windows.Window]::OpacityProperty, $fade)
            } catch { try { $s.Opacity = 1 } catch {} }
        })
    } catch {}

    $swTitleBar      = $settingsWindow.FindName('TitleBar')
    $swClose         = $settingsWindow.FindName('CloseButton')
    $startupSwitch   = $settingsWindow.FindName('StartupSwitch')
    $progressSwitch  = $settingsWindow.FindName('ProgressSwitch')
    $doneNotifySwitch = $settingsWindow.FindName('DoneNotifySwitch')
    $editorIconsSwitch = $settingsWindow.FindName('EditorIconsSwitch')
    $updateText      = $settingsWindow.FindName('UpdateInfoText')
    # 7.2.3: Die Test-Benachrichtigung ist vollstaendig aus den Einstellungen
    # entfernt. Der report_done-Kanal, seine Registrierung und seine Messung
    # bleiben unveraendert; nur ein zusaetzlicher kuenstlicher Popup-Test entfiel.

    $startupSwitch.IsChecked = $autoStartNow
    $progressSwitch.IsChecked = $progressNow
    $doneNotifySwitch.IsChecked = $doneNotifyNow
    $editorIconsSwitch.IsChecked = $editorIconsNow
    foreach ($toggleSwitch in @($startupSwitch, $progressSwitch, $doneNotifySwitch, $editorIconsSwitch)) {
        Set-ArenaSwitchVisualState $toggleSwitch
        $toggleSwitch.Add_Loaded({ param($s, $e) Set-ArenaSwitchVisualState $s })
    }
    if ($script:UpdateInfoState) {
        $updateText.Text = [string]$script:UpdateInfoState.Body
        $updateText.Foreground = Get-Brush ([string]$script:UpdateInfoState.BodyHex)
    } else {
        $updateText.Text = 'Version 7.4.1 - aktuell. Beim naechsten Start wird automatisch nach Updates gesucht.'
    }

    $swTitleBar.Add_MouseLeftButtonDown({
        if ($_.ButtonState -eq [System.Windows.Input.MouseButtonState]::Pressed) {
            try { $settingsWindow.DragMove() } catch {}
        }
    })
    $swClose.Add_Click({ try { $settingsWindow.Close() } catch {} })

    $startupSwitch.Add_Click({
        param($s, $e)
        try {
            Set-StartupEnabled ([bool]$s.IsChecked)
            $script:SettingsCache.autoStart = [bool]$s.IsChecked
            Save-BridgeSettingsFile
        } catch {
            Write-RuntimeLog "Der Autostart konnte nicht geaendert werden: $($_.Exception.Message)"
            $s.IsChecked = Get-StartupEnabled
        }
    })
    $progressSwitch.Add_Click({
        param($s, $e)
        $script:Shared.BridgeSettings.progressInPlaceList = [bool]$s.IsChecked
        $script:SettingsCache.progressInPlaceList = [bool]$s.IsChecked
        Save-BridgeSettingsFile
        # Version 7.0.0: AUS blendet die Anzeige aus - gespeichert wird weiter
        # alles vollstaendig, beim Wiedereinschalten fehlt nichts.
        $stateText = 'ausgeblendet'
        if ($s.IsChecked) { $stateText = 'sichtbar' }
        Write-RuntimeLog "Fortschrittsanzeige in der Place-Liste $stateText (Verlauf und Diagnose bleiben vollstaendig)."
    })
    $doneNotifySwitch.Add_Click({
        param($s, $e)
        # Version 7.1.3: An/Aus der Windows-Meldung "Arena ist fertig"
        # (report_done). Aus wirkt SOFORT: eine schon gemeldete Meldung wird
        # aus der Warteschlange verworfen und der Anzeige-Takt ueberspringt
        # sie; die KI erfaehrt denselben Stand in jeder Antwort.
        $enabled = [bool]$s.IsChecked
        $script:Shared.BridgeSettings.notifyOnDone = $enabled
        $script:SettingsCache.notifyOnDone = $enabled
        Save-BridgeSettingsFile
        if (-not $enabled) { Clear-NotifyQueue }
        # Version 7.2.0 (D4): Beim Einschalten die App-Id registrieren, sonst
        # verwirft Windows die Meldung still - und beim Ausschalten das Urteil
        # sofort neu messen (SUPPRESSED_APP_DISABLED).
        if ($enabled) { [void](Register-NotifyAumid -Force) }
        [void](Update-NotifyPlatformCache -Force)
        $stateText = 'aus'
        if ($enabled) { $stateText = 'an' }
        Write-RuntimeLog "Fertig-Benachrichtigung (report_done) ist jetzt $stateText."
    })
    $editorIconsSwitch.Add_Click({
        param($s, $e)
        Set-EditorIconsEnabled ([bool]$s.IsChecked)
        Save-BridgeSettingsFile
    })
    [void]$settingsWindow.ShowDialog()
}

# Version 3.8: Die Update-Infos stehen jetzt im grossen Einstellungsfenster.
# Der Zustand wird hier vorbereitet (rote "1" bleibt am Zahnrad) und beim
# Oeffnen der Einstellungen angezeigt.
$script:UpdateInfoState = @{
    IsError  = $false
    Body     = 'Version 7.4.1 - aktuell. Beim naechsten Start wird automatisch nach Updates gesucht.'
    BodyHex  = '#94A3B8'
}
if (Test-UpdateError) {
    try { $UpdateBadge.Visibility = 'Visible' } catch {}
    $updateErrorText = Get-UpdateStatusText
    if ($script:UpdateDetails -and $script:UpdateDetails.error) {
        $updateErrorText = $updateErrorText + ': ' + [string]$script:UpdateDetails.error
    }
    $script:UpdateInfoState.IsError = $true
    $script:UpdateInfoState.Body = $updateErrorText
    $script:UpdateInfoState.BodyHex = '#CBD5E1'
} elseif ($UpdateStatus -in @('update-erfolgreich', 'erster-start', 'kein-update')) {
    $verText = '7.4.1'
    if ($script:UpdateDetails -and $script:UpdateDetails.version) { $verText = [string]$script:UpdateDetails.version }
    $script:UpdateInfoState.Body = "Version $verText - aktuell. Beim naechsten Start wird automatisch nach Updates gesucht."
}

# Version 7.2.6 (START-NETZ KOMPLETT): Fehler im Fensterbau oder in der
# Ereignis-Verdrahtung werden gesichert und sichtbar gemeldet. Existiert gar
# kein Hauptfenster, ist ein Weiterlaufen sinnlos - dann sauber beenden.
} catch {
    # Version 7.2.6 (START-NETZ KOMPLETT): Fehler im Fensterbau oder in der
    # Ereignis-Verdrahtung werden gesichert und sichtbar gemeldet. Existiert
    # gar kein Hauptfenster, ist ein Weiterlaufen sinnlos - dann sauber beenden.
    Write-StartupFailureDiagnose $_
    if ($null -eq $window) { [System.Environment]::Exit(1) }
}

# ----------------------------------------------------------------------------
# Version 7.2.7 (MINI-START-FIX): Das Hauptfenster wird gezeigt, BEVOR
# Selbst-Update, Roblox-Suche, Plugin-, Server- und Tunnel-Start laufen. Ein
# Haenger in einem Startschritt kann die Bridge damit nicht mehr unsichtbar
# halten. ContentRendered stellt zugleich sicher, dass WPF den ersten Frame
# wirklich gezeichnet hat, bevor die Startarbeiten beginnen.
$script:UiRefreshTimer = $null
$script:NotifyTimer = $null
$script:StartupLaunchTimer = $null
$script:StartupRuntimeStarted = $false

function Set-UiRefreshCadence {
    param([bool]$Minimized)
    if ($null -eq $script:UiRefreshTimer) { return }
    $milliseconds = if ($Minimized) { $script:UiRefreshMinimizedMs } else { $script:UiRefreshVisibleMs }
    $interval = [System.TimeSpan]::FromMilliseconds($milliseconds)
    if ($script:UiRefreshTimer.Interval -ne $interval) { $script:UiRefreshTimer.Interval = $interval }
}

function Start-BridgeRuntime {
    Set-StartupStage 'Hauptfenster gerendert; Startinitialisierung beginnt'
    if (-not $script:EncodingOk) {
        Add-PendingToast 'Achtung: Die Skriptdatei ist nicht als "UTF-8 mit BOM" gespeichert. Umlaute koennen falsch aussehen.' 'Warn' 9
        Write-RuntimeLog 'ACHTUNG: Skriptdatei ist falsch codiert - Umlaute werden ggf. falsch angezeigt.'
    }
    Set-StartupStage 'Selbst-Update-Pruefung'
    $starterProvesFreshInstall = ((@('update-erfolgreich', 'erster-start') -contains $UpdateStatus) -eq $true)
    if (-not $starterProvesFreshInstall) {
        $selfUpdated = $false
        try {
            $selfUpdated = Invoke-AutostartSelfUpdate -VerifyMode:([bool]$UpdateStatus)
        } catch {
            $selfUpdated = $false
            try { Write-RuntimeLog "Update-Suche uebersprungen: $($_.Exception.Message)" } catch {}
        }
        if ($selfUpdated) {
            # Die neue Fassung laeuft bereits - dieser Prozess wird beendet.
            exit 0
        }
    }

    Set-StartupStage 'Roblox-Studio-Suche und Plugin-/Server-Start'
    $script:RobloxStudioPath = Find-RobloxStudio
    if ($script:RobloxStudioPath) {
        Write-RuntimeLog "Roblox Studio gefunden: $($script:RobloxStudioPath.FullName)"
        $portFree = Test-PortAvailable $script:Port
        if (-not $portFree) {
            # Port ist belegt: den belegenden Prozess automatisch beenden,
            # damit diese Instanz starten kann (vorher musste der Nutzer das
            # selbst im Task-Manager tun - das war irritierend).
            Write-RuntimeLog "Port $($script:Port) ist belegt - der belegende Prozess wird gesucht und automatisch beendet."
            Add-PendingToast "Der lokale Port $($script:Port) war belegt. Das blockierende Programm wird automatisch geschlossen ..." 'Info' 6
            $portFree = Free-Port -Port $script:Port
            if ($portFree) {
                Add-PendingToast "Port $($script:Port) wurde freigegeben - die Bridge startet jetzt." 'Success' 5
                Write-RuntimeLog "Port $($script:Port) wurde automatisch freigegeben."
            }
        }
        if (-not $portFree) {
            $script:StartupBlocked = $true
            Add-PendingToast "Der lokale Port $($script:Port) konnte nicht freigegeben werden. Bitte dieses Programm schließen und erneut starten. Details: $script:RuntimeLog" 'Error' 10
            Write-RuntimeLog "Port $($script:Port) konnte nicht freigegeben werden. Es wird kein Server und kein Tunnel gestartet."
        } else {
            try {
                $pluginPath = Install-RobloxPlugin
                Write-RuntimeLog "Studio Plugin installiert: $pluginPath"
                Start-BridgeServer -Port $script:Port
                # Version 7.4.0: Schritt 4 - Blender pruefen/installieren, BEVOR
                # der Tunnel startet. Ist Blender vorhanden, geht es sofort
                # weiter; sonst wartet der Tunnel und der UI-Takt loest ihn aus,
                # sobald der Schritt fertig, gescheitert oder uebersprungen ist.
                $blenderReady = $false
                try { $blenderReady = [bool](Start-BlenderStartupGate) } catch { Write-RuntimeLog ('Blender-Schritt 4 konnte nicht gestartet werden: ' + $_.Exception.Message) }
                if ($blenderReady) { Start-CloudflareTunnel }
                else { Write-RuntimeLog 'Der Start wartet auf den Blender-Schritt 4; der Tunnel startet danach automatisch.' }
                Add-PendingToast 'Plugin installiert. Öffne nun ein Place in Roblox Studio - es erscheint automatisch hier.' 'Info' 6
            } catch {
                Add-PendingToast "Startfehler: $($_.Exception.Message)" 'Error' 8
                Write-RuntimeLog "Startfehler: $($_.Exception.Message)"
            }
        }
    } else {
        Add-PendingToast 'Roblox Studio ist nicht installiert oder wurde nicht gefunden.' 'Warn' 7
        Write-RuntimeLog 'Roblox Studio wurde nicht gefunden.'
    }

    Set-StartupStage 'UI-Timer und Benachrichtigungen werden gestartet'
    $script:UiRefreshVisibleMs = 1800
    $script:UiRefreshMinimizedMs = 5000
    $script:UiRefreshTimer = [System.Windows.Threading.DispatcherTimer]::new()
    Set-UiRefreshCadence $false
    $script:UiRefreshTimer.Add_Tick({
        try {
            $minimized = $false
            try { $minimized = ($window.WindowState -eq 'Minimized') } catch {}
            Set-UiRefreshCadence $minimized
            # Version 7.0.3: Laufzeitdiagnostik. Der Waechter laeuft immer, misst
            # aber nur, wenn die Diagnose in den Einstellungen an ist - dann
            # entsteht hoechstens alle 30 s eine Zeile (kein Logging pro Tick).
            $perfWatch = $null
            try { if (Test-PerfDiagnosticsEnabled) { $perfWatch = [System.Diagnostics.Stopwatch]::StartNew() } } catch {}
            Refresh-Ui
            if ($null -ne $perfWatch) {
                try { Update-PerfUiTick $perfWatch.Elapsed.TotalMilliseconds } catch {}
            }
        } catch {
            Write-RuntimeLog "Refresh Fehler: $($_.Exception.Message)"
            try { Show-Toast -Message "Fehler abgefangen: $($_.Exception.Message)" -Kind 'Error' -Seconds 6 } catch {}
        }
    })
    $window.Add_StateChanged({
        param($sender, $e)
        $minimized = ($sender.WindowState -eq 'Minimized')
        Set-UiRefreshCadence $minimized
        if (-not $minimized) {
            try { Refresh-Ui } catch { Write-RuntimeLog "Refresh nach Wiederherstellung fehlgeschlagen: $($_.Exception.Message)" }
        }
    })
    $script:UiRefreshTimer.Start()

    # Version 3.8: report_done-Meldungen der KI abholen und als Windows-
    # Benachrichtigung anzeigen. Der Server legt sie nur in die Warteschlange,
    # wenn der Nutzer die Fertig-Meldung aktiviert hat.
    $script:NotifyTimer = [System.Windows.Threading.DispatcherTimer]::new()
    $script:NotifyTimer.Interval = [TimeSpan]::FromMilliseconds(800)
    $script:NotifyTimer.Add_Tick({
        try {
            # Version 7.1.3: Ist der Schalter aus, wird nicht nur nicht angezeigt -
            # die Warteschlange wird geleert, damit spaeter nichts nachploppt.
            $notifyAllowed = $false
            try { $notifyAllowed = [bool]$script:Shared.BridgeSettings.notifyOnDone } catch {}
            if (-not $notifyAllowed) { [void](Clear-NotifyQueue) }
            while ($notifyAllowed) {
                $item = $null
                if (-not $script:Shared.NotifyQueue.TryDequeue([ref]$item)) { break }
                try {
                    $payload = $item | ConvertFrom-Json
                    $payloadFlow = ''
                    try { if ($payload.PSObject.Properties['flowId']) { $payloadFlow = [string]$payload.flowId } } catch {}
                    $payloadQueued = [int64]0
                    try { if ($payload.PSObject.Properties['queuedAt']) { $payloadQueued = [int64]$payload.queuedAt } } catch {}
                    [void](Show-ArenaDoneNotification -Place ([string]$payload.place) -Title ([string]$payload.title) -Message ([string]$payload.message) -FlowId $payloadFlow -QueuedAt $payloadQueued)
                } catch {
                    Write-RuntimeLog "Fertig-Meldung konnte nicht angezeigt werden: $($_.Exception.Message)"
                    Write-FlowTrace 'NOTIFY' 'n-?' 'CALL_FAILED' @{ channel = 'tick'; error = $_.Exception.Message }
                }
                try { $notifyAllowed = [bool]$script:Shared.BridgeSettings.notifyOnDone } catch { $notifyAllowed = $false }
            }
            # Version 7.2.0 (D4): notify.sweep misst NACH dem Anzeigen erneut und
            # verbucht ehrlich SHOWN oder SHOWN_UNVERIFIED mit Grund. Windows bietet
            # keine Bestaetigungs-API fuer einen Toast - deshalb Messung plus
            # Nutzerfrage ("Gesehen? Ja/Nein") statt blindem delivered = true.
            Invoke-NotifySweep
            [void](Update-NotifyPlatformCache)
        } catch {}
    })
    # Version 7.2.0 (D4): Ohne registrierte App-Id verwirft Windows den Toast still,
    # obwohl Show() ohne Ausnahme zurueckkehrt. Registriert wird nur, wenn der
    # Nutzer Fertig-Meldungen ueberhaupt eingeschaltet hat - und nur im
    # Benutzerprofil (HKCU + Startmenue), idempotent.
    try {
        $notifyWantedAtStart = $false
        try { $notifyWantedAtStart = [bool]$script:Shared.BridgeSettings.notifyOnDone } catch {}
        if ($notifyWantedAtStart) { [void](Register-NotifyAumid) }
        [void](Update-NotifyPlatformCache -Force)
    } catch {}
    $script:NotifyTimer.Start()

    Refresh-Ui
    Set-StartupStage 'Startinitialisierung abgeschlossen; Hauptfenster bleibt sichtbar'

}

# ----------------------------------------------------------------------------
# START: Ereignisse stehen VOR ShowDialog, damit Schliessen auch waehrend der
# Startarbeiten sauber beendet. Die eigentliche Initialisierung startet erst
# nach dem ersten sichtbaren Rendern und genau einmal.
# ----------------------------------------------------------------------------
try {
    # Version 7.3.0 (STARTGARANTIE): Der Update-/Willkommenshinweis laeuft
    # NICHT mehr VOR dem Hauptfenster, sondern unmittelbar danach (siehe
    # ContentRendered/StartupLaunchTimer unten) - als modales Fenster ueber der
    # bereits sichtbaren Bridge. Grund: Ein modales Fenster VOR dem
    # Hauptfenster konnte den ganzen Start unsichtbar festhalten - genau das
    # gemeldete "das Programm startet gar nicht". Die Reihenfolge bleibt
    # inhaltlich erhalten: erst der Hinweis, danach starten Studio-/Plugin-/
    # Server-/Tunnel-Dienste; die Oberflaeche ist dabei schon sichtbar.
    $window.Add_Closed({
        try { if ($script:UiRefreshTimer) { $script:UiRefreshTimer.Stop() } } catch {}
        try { if ($script:NotifyTimer) { $script:NotifyTimer.Stop() } } catch {}
        try { if ($script:StartupLaunchTimer) { $script:StartupLaunchTimer.Stop() } } catch {}
        try {
            foreach ($row in @($script:UiRows.Values)) {
                try { $row.Popup.IsOpen = $false } catch {}
            }
        } catch {}
        try {
            if ($script:TunnelProcess -and -not $script:TunnelProcess.HasExited) {
                $script:TunnelProcess.Kill()
            }
        } catch {}
        try { Write-RuntimeLog 'Fenster geschlossen - Programm wird vollstaendig beendet.' } catch {}
        [System.Environment]::Exit(0)
    })
    $window.Add_ContentRendered({
        if ($script:StartupRuntimeStarted) { return }
        $script:StartupRuntimeStarted = $true
        Set-StartupStage 'Hauptfenster gerendert; Sichtbarkeit wird gesichert'
        # ContentRendered muss erst zurueckkehren, damit WPF den Opacity-Fade
        # und den sichtbaren Startbildschirm zeichnen kann. Danach haertet ein
        # kurzer Einmal-Timer die Deckkraft auf 1, BEVOR ein Startschritt den
        # Dispatcher eventuell laenger belegt.
        $script:StartupLaunchTimer = [System.Windows.Threading.DispatcherTimer]::new()
        $script:StartupLaunchTimer.Interval = [TimeSpan]::FromMilliseconds(500)
        $script:StartupLaunchTimer.Add_Tick({
            param($sender, $eventArgs)
            try { $sender.Stop() } catch {}
            try {
                try { $window.BeginAnimation([System.Windows.Window]::OpacityProperty, $null) } catch {}
                $window.Opacity = 1
                Set-StartupStage 'Hauptfenster sichtbar; Startinitialisierung beginnt'
                # Version 7.3.0 (STARTGARANTIE): Der Update-/Willkommenshinweis
                # erscheint jetzt HIER - ueber der sichtbaren Bridge und VOR
                # den Diensten. Scheitert er, laeuft der Start trotzdem weiter.
                if ($UpdateStatus -eq 'update-erfolgreich' -or $UpdateStatus -eq 'erster-start') {
                    Set-StartupStage 'Update-/Willkommenshinweis wird angezeigt'
                    try { Show-UpdateNotice } catch { Write-RuntimeLog "Update-Hinweis konnte nicht angezeigt werden: $($_.Exception.Message)" }
                    Set-StartupStage 'Update-/Willkommenshinweis geschlossen: Dienste starten'
                }
                Start-BridgeRuntime
            } catch {
                Write-StartupFailureDiagnose $_
            }
        })
        $script:StartupLaunchTimer.Start()
    })
    Set-StartupStage 'Hauptfenster wird jetzt geoeffnet (ShowDialog)'
    Write-RuntimeLog 'Fenster wird geöffnet; Startinitialisierung folgt nach dem ersten Rendern.'
    [void]$window.ShowDialog()
} catch {
    Write-StartupFailureDiagnose $_
}
# Sicherheitsnetz (Version 3.4): Falls das Closed-Ereignis doch nicht zum
# Exit gefuehrt haben sollte, wird der Prozess hier garantiert beendet.
try { Write-RuntimeLog '=== Programmende ===' } catch {}
[System.Environment]::Exit(0)
